-- ═══════════════════════════════════════════════════════════════════════════════════
-- bundled runtime
-- note: this keeps the one-file loader stable before any bundled modules run.
-- ═══════════════════════════════════════════════════════════════════════════════════

local __DG_ORIGINAL_REQUIRE = require
local __DG_BUNDLE_LOADERS = {}
local __DG_BUNDLE_CACHE = {}

local function __DG_BUNDLE_REQUIRE(name)
    if __DG_BUNDLE_CACHE[name] ~= nil then return __DG_BUNDLE_CACHE[name] end
    local loader = __DG_BUNDLE_LOADERS[name]
    if loader then
        local ok, result = driftgod.Try(loader)
        if not ok then error(result, 2) end
        if result == nil then result = true end
        __DG_BUNDLE_CACHE[name] = result
        return result
    end
    return __DG_ORIGINAL_REQUIRE(name)
end

require = __DG_BUNDLE_REQUIRE
driftgod = driftgod or DG or {}
DG = driftgod
_G.driftgod = driftgod
_G.DG = driftgod


local __DG_NATIVE_PCALL = pcall

function driftgod.Try(fn, ...)
    return __DG_NATIVE_PCALL(fn, ...)
end

driftgod.__GoldenBaseline = "v1.0.22 Flashless Prime Garage"
driftgod.__ProductionBundleBase = "v1.0.3-product-build"
driftgod.__ProductionPatch = "v1_0_3_Product_Build"

