-- ═══════════════════════════════════════════════════════════════════════════════════
-- feature registration safety
-- note: removes stale feature hashes before adding new cherax features.
-- ═══════════════════════════════════════════════════════════════════════════════════

function driftgod.SafeAddFeature(hash, name, featureType, desc, callback, ...)
    if FeatureMgr and FeatureMgr.RemoveFeature and hash ~= nil then
        driftgod.Try(function() FeatureMgr.RemoveFeature(hash) end)
    end
    if FeatureMgr and FeatureMgr.AddFeature then
        return FeatureMgr.AddFeature(hash, name, featureType, desc or "", callback, ...)
    end
    return nil
end

