-- ═══════════════════════════════════════════════════════════════════════════════════
-- ghost replay logging
-- note: normal ghost logs stay muted unless debug mode or an important warning is active.
-- ═══════════════════════════════════════════════════════════════════════════════════

local function ghostLog(msg, force)
    msg = tostring(msg or "")
    local lower = msg:lower()
    local important = force == true
        or lower:find("error", 1, true) ~= nil
        or lower:find("failed", 1, true) ~= nil
        or lower:find("warning", 1, true) ~= nil

    if not important and driftgod.S and driftgod.S.ghostReplayDebugEnabled ~= true then return end

    if driftgod.Log then
        driftgod.Log("[GhostReplay] " .. msg)
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] [GhostReplay] " .. msg)
    end
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- ghost replay defaults
-- note: initializes replay settings without overwriting saved user choices.
-- ═══════════════════════════════════════════════════════════════════════════════════

function driftgod.GhostReplayEnsureDefaults()
    -- ═══════════════════════════════════════════════════════════════════════════════════
-- runtime state
-- note: stores saved settings and runtime flags in one shared table.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.S = driftgod.S or {}
    driftgod.S.ghostReplayEnabled = driftgod.S.ghostReplayEnabled ~= false
    driftgod.S.ghostReplayDebugEnabled = driftgod.S.ghostReplayDebugEnabled == true
    driftgod.S.ghostReplaySelectedIndex = tonumber(driftgod.S.ghostReplaySelectedIndex or 1) or 1
    driftgod.S.ghostReplayPreviewVehicle = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0
    driftgod.S.ghostReplayPreviewVehicleModel = tonumber(driftgod.S.ghostReplayPreviewVehicleModel or 0) or 0
    driftgod.S.ghostReplayPreviewConfirmedWorking = driftgod.S.ghostReplayPreviewConfirmedWorking == true
    driftgod.S.ghostReplayPlaybackSpeed = tonumber(driftgod.S.ghostReplayPlaybackSpeed or 1.0) or 1.0
    driftgod.S.ghostReplayStopRequested = driftgod.S.ghostReplayStopRequested == true
    driftgod.S.ghostReplayPlaybackStatus = tostring(driftgod.S.ghostReplayPlaybackStatus or "Idle")
    driftgod.S.ghostReplayPlaybackProgressPct = tonumber(driftgod.S.ghostReplayPlaybackProgressPct or 0) or 0
    driftgod.S.ghostReplayPlaybackVerbose = driftgod.S.ghostReplayPlaybackVerbose == true

end

driftgod.GhostReplay.Replays = driftgod.GhostReplay.Replays or {}

driftgod.GhostReplay.Tracks = driftgod.GhostReplay.Tracks or {}

function driftgod.GetGhostReplayCount()
    return #(driftgod.GhostReplay and driftgod.GhostReplay.Replays or {})
end

function driftgod.GetGhostTrackCount()
    return #(driftgod.GhostReplay and driftgod.GhostReplay.Tracks or {})
end

function driftgod.GetSelectedGhostReplay()
    driftgod.GhostReplayEnsureDefaults()

    local replays = driftgod.GhostReplay and driftgod.GhostReplay.Replays or {}
    if #replays <= 0 then return nil end

    local idx = tonumber(driftgod.S.ghostReplaySelectedIndex or 1) or 1
    if idx < 1 then idx = 1 end
    if idx > #replays then idx = #replays end
    driftgod.S.ghostReplaySelectedIndex = idx

    return replays[idx], idx
end

function driftgod.SelectNextGhostReplay()
    driftgod.GhostReplayEnsureDefaults()

    local count = driftgod.GetGhostReplayCount()
    if count <= 0 then return nil end

    driftgod.S.ghostReplaySelectedIndex = (tonumber(driftgod.S.ghostReplaySelectedIndex or 1) or 1) + 1
    if driftgod.S.ghostReplaySelectedIndex > count then driftgod.S.ghostReplaySelectedIndex = 1 end

    return driftgod.GetSelectedGhostReplay()
end

function driftgod.SelectPreviousGhostReplay()
    driftgod.GhostReplayEnsureDefaults()

    local count = driftgod.GetGhostReplayCount()
    if count <= 0 then return nil end

    driftgod.S.ghostReplaySelectedIndex = (tonumber(driftgod.S.ghostReplaySelectedIndex or 1) or 1) - 1
    if driftgod.S.ghostReplaySelectedIndex < 1 then driftgod.S.ghostReplaySelectedIndex = count end

    return driftgod.GetSelectedGhostReplay()
end

function driftgod.GhostReplaySnapshot(reason)
    driftgod.GhostReplayEnsureDefaults()

    local replay, idx = driftgod.GetSelectedGhostReplay()

    if replay then
        ghostLog("Snapshot | reason=" .. tostring(reason or "manual")
            .. " | selected=" .. tostring(idx)
            .. "/" .. tostring(driftgod.GetGhostReplayCount())
            .. " | name=" .. tostring(replay.name or "")
            .. " | track=" .. tostring(replay.track or "")
            .. " | vehicleModel=" .. tostring(replay.vehicleModel or "")
            .. " | nodes=" .. tostring(replay.nodeCount or 0)
            .. " | confirmed=" .. tostring(driftgod.S.ghostReplayPreviewConfirmedWorking == true)
            .. " | firstNode=" .. tostring(type(replay.firstNode) == "table")
            .. " | atStart=" .. tostring(driftgod.S.ghostReplayAtReplayStart == true)
            .. " | microNodes=" .. tostring(type(replay.microNodes) == "table" and #replay.microNodes or 0), true)
    else
        ghostLog("Snapshot | reason=" .. tostring(reason or "manual")
            .. " | no replays registered", true)
    end
end

local function existsPath(path)
    local cur = _G
    for part in tostring(path or ""):gmatch("[^%.]+") do
        if type(cur) ~= "table" and type(cur) ~= "userdata" then return false end
        cur = cur[part]
        if cur == nil then return false end
    end
    return true
end

function driftgod.GhostReplayStyleEnvironmentSnapshot(reason)
    local checks = {
        "ENTITY.SET_ENTITY_ALPHA",
        "ENTITY.RESET_ENTITY_ALPHA",
        "ENTITY.SET_ENTITY_COLLISION",
        "ENTITY.FREEZE_ENTITY_POSITION",
        "ENTITY.SET_ENTITY_INVINCIBLE",
        "ENTITY.SET_ENTITY_VISIBLE",
        "ENTITY.SET_ENTITY_AS_MISSION_ENTITY",
        "VEHICLE.SET_VEHICLE_ENGINE_ON",
        "VEHICLE.SET_VEHICLE_COLOURS",
        "VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR",
        "VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR",
        "VEHICLE.SET_VEHICLE_NEON_ENABLED",
        "VEHICLE.SET_VEHICLE_NEON_COLOUR",
        "VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT",
        "VEHICLE.SET_VEHICLE_TYRES_CAN_BURST",
        "VEHICLE.SET_VEHICLE_DIRT_LEVEL",
        "GRAPHICS.SET_ENTITY_RENDER_SCORCHED",
        "driftgod.StyleGhostPreviewVehicle",
        "driftgod.ApplyGhostStyleToVehicle",
        "driftgod.MakeVehicleGhost",
    }

    local parts = {}
    for _, path in ipairs(checks) do
        table.insert(parts, path .. "=" .. tostring(existsPath and existsPath(path) or false))
    end

    ghostLog("Style Environment | reason=" .. tostring(reason or "manual") .. " | " .. table.concat(parts, " | "), true)
end

function driftgod.GhostReplaySpawnEnvironmentSnapshot(reason)
    local checks = {
        "STREAMING",
        "STREAMING.REQUEST_MODEL",
        "STREAMING.HAS_MODEL_LOADED",
        "PLAYER",
        "PLAYER.PLAYER_PED_ID",
        "PED",
        "PED.GET_VEHICLE_PED_IS_IN",
        "ENTITY",
        "ENTITY.GET_ENTITY_COORDS",
        "ENTITY.GET_ENTITY_HEADING",
        "ENTITY.DELETE_ENTITY",
        "ENTITY.FREEZE_ENTITY_POSITION",
        "VEHICLE",
        "VEHICLE.CREATE_VEHICLE",
        "VEHICLE.SET_VEHICLE_ENGINE_ON",
        "entities",
        "entities.create_vehicle",
        "entities.delete_by_handle",
        "Natives",
        "Natives.Invoke",
        "native",
        "native.call",
        "Script",
        "Script.Yield",
        "v3",
        "driftgod.SpawnVehicleAtCoords",
        "driftgod.SpawnZentorno",
        "driftgod.SpawnConfiguredZentorno",
        "driftgod.SpawnVehicle",
