        end
    end

    ghostLog("Spawn Environment | reason=" .. tostring(reason or "manual") .. " | " .. table.concat(parts, " | "), true)
end

local function callAnySpawnHelper(model, x, y, z, heading)
    local helperNames = {
        "SpawnVehicleAtCoords",
        "CreateVehicle",
        "SpawnVehicle",
        "SpawnConfiguredVehicle",
    }

    for _, name in ipairs(helperNames) do
        local fn = DG and DG[name]
        if type(fn) == "function" then
            local ok, result = driftgod.Try(fn, model, x, y, z, heading or 0.0)
            if ok and result and tonumber(result) and tonumber(result) ~= 0 then
                return tonumber(result), "driftgod." .. name
            end

            ok, result = driftgod.Try(fn, model)
            if ok and result and tonumber(result) and tonumber(result) ~= 0 then
                return tonumber(result), "driftgod." .. name .. "(model)"
            end
        end
    end

    return 0, "no DG spawn helper succeeded"
end

local function requestModelSafe(model)
    model = tonumber(model or 0) or 0
    if model == 0 then return false end

    local requested = false
    local loaded = false

    driftgod.Try(function()
        if STREAMING and STREAMING.REQUEST_MODEL then
            STREAMING.REQUEST_MODEL(model)
            requested = true
        elseif util and util.request_model then
            util.request_model(model)
            requested = true
            loaded = true
        end
    end)

    for _ = 1, 30 do
        driftgod.Try(function()
            if STREAMING and STREAMING.HAS_MODEL_LOADED then
                loaded = STREAMING.HAS_MODEL_LOADED(model) == true
            end
        end)

        if loaded then break end

        driftgod.Try(function()
            if Script and Script.Yield then Script.Yield(15) end
        end)
    end

    return requested or loaded
end

local function getPlayerPedSafe()
    local ped = 0
    driftgod.Try(function()
        if PLAYER and PLAYER.PLAYER_PED_ID then
            ped = PLAYER.PLAYER_PED_ID() or 0
        elseif players and players.user_ped then
            ped = players.user_ped() or 0
        end
    end)
    return ped or 0
end

local function getEntityCoordsSafe(ent)
    local x, y, z = 0.0, 0.0, 72.0

    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_COORDS then
            local c = ENTITY.GET_ENTITY_COORDS(ent, true)
            if type(c) == "table" then
                x = tonumber(c.x or c[1] or 0.0) or 0.0
                y = tonumber(c.y or c[2] or 0.0) or 0.0
                z = tonumber(c.z or c[3] or 72.0) or 72.0
            elseif c then

                x = tonumber(c.x or 0.0) or 0.0
                y = tonumber(c.y or 0.0) or 0.0
                z = tonumber(c.z or 72.0) or 72.0
            end
        end
    end)

    return x, y, z
end

local function getEntityHeadingSafe(ent)
    local h = 0.0
    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_HEADING then
            h = tonumber(ENTITY.GET_ENTITY_HEADING(ent) or 0.0) or 0.0
        end
    end)
    return h
end

local function offsetFromHeading(x, y, z, heading, forward, right)
    local rad = math.rad(tonumber(heading or 0.0) or 0.0)
    local sx = math.sin(rad)
    local cy = math.cos(rad)

    local fx = -sx
    local fy = cy
    local rx = cy
    local ry = sx

    return x + fx * forward + rx * right, y + fy * forward + ry * right, z
end

local function createVehicleSafe(model, x, y, z, heading)
    model = tonumber(model or 0) or 0
    if model == 0 then return 0, "invalid model" end

    local veh = 0
    local tried = {}

    local function mark(name, available)
        table.insert(tried, name .. "=" .. tostring(available))
    end

    local helperVeh, helperMethod = callAnySpawnHelper(model, x, y, z, heading)
    mark(helperMethod, helperVeh ~= 0)
    if helperVeh and helperVeh ~= 0 then return helperVeh, helperMethod end

    if entities and entities.create_vehicle then
        driftgod.Try(function()
            if v3 then
                veh = entities.create_vehicle(model, v3(x, y, z), heading or 0.0) or 0
            else
                veh = entities.create_vehicle(model, x, y, z, heading or 0.0) or 0
            end
        end)
        mark("entities.create_vehicle", veh ~= 0)
        if veh and veh ~= 0 then return veh, "entities.create_vehicle" end
    else
        mark("entities.create_vehicle", false)
    end

    if VEHICLE and VEHICLE.CREATE_VEHICLE then
        driftgod.Try(function()
            veh = VEHICLE.CREATE_VEHICLE(model, x, y, z, heading or 0.0, true, true, false) or 0
        end)
        mark("VEHICLE.CREATE_VEHICLE sigA", veh ~= 0)
        if veh and veh ~= 0 then return veh, "VEHICLE.CREATE_VEHICLE sigA" end

        driftgod.Try(function()
            veh = VEHICLE.CREATE_VEHICLE(model, x, y, z, heading or 0.0, true, false) or 0
        end)
        mark("VEHICLE.CREATE_VEHICLE sigB", veh ~= 0)
        if veh and veh ~= 0 then return veh, "VEHICLE.CREATE_VEHICLE sigB" end

        driftgod.Try(function()
            veh = VEHICLE.CREATE_VEHICLE(model, x, y, z, heading or 0.0) or 0
        end)
        mark("VEHICLE.CREATE_VEHICLE sigC", veh ~= 0)
        if veh and veh ~= 0 then return veh, "VEHICLE.CREATE_VEHICLE sigC" end
    else
        mark("VEHICLE.CREATE_VEHICLE", false)
    end

    if Natives and Natives.Invoke then
        driftgod.Try(function()
            veh = Natives.Invoke(0xAF35D0D2583051B0, model, x, y, z, heading or 0.0, true, true, false) or 0
        end)
        mark("Natives.Invoke", veh ~= 0)
        if veh and veh ~= 0 then return veh, "Natives.Invoke CREATE_VEHICLE" end
    else
        mark("Natives.Invoke", false)
    end

    if native and native.call then
        driftgod.Try(function()
            local r = native.call(0xAF35D0D2583051B0, model, x, y, z, heading or 0.0, true, true, false)
            if type(r) == "number" then veh = r end
        end)
        mark("native.call", veh ~= 0)
        if veh and veh ~= 0 then return veh, "native.call CREATE_VEHICLE" end
    else
        mark("native.call", false)
    end

    return 0, table.concat(tried, ", ")
end

function driftgod.DeleteGhostPreviewVehicle()
    driftgod.GhostReplayEnsureDefaults()

    if type(driftgod.DeleteGhostPreviewBridge) == "function" then
        return driftgod.DeleteGhostPreviewBridge()
    end

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0
    if veh == 0 then
        ghostLog("Delete preview skipped; no tracked preview vehicle handle")
        return false
    end

    local deleted = false
    driftgod.Try(function()
        if ENTITY and ENTITY.DELETE_ENTITY then
            ENTITY.DELETE_ENTITY(veh)
            deleted = true
        elseif entities and entities.delete_by_handle then
            entities.delete_by_handle(veh)
            deleted = true
        end
    end)

    driftgod.S.ghostReplayPreviewVehicle = 0
    driftgod.S.ghostReplayPreviewVehicleModel = 0
    driftgod.S.ghostReplayPreviewConfirmedWorking = false

    if deleted then
        ghostLog("Deleted ghost preview vehicle", true)
    else
        ghostLog("Warning: attempted to delete ghost preview vehicle, but no delete native/helper was available", true)
    end

    return deleted
end

function driftgod.StyleGhostPreviewVehicle(veh)
    veh = tonumber(veh or 0) or 0
    if veh == 0 then
        ghostLog("Ghost style skipped; invalid vehicle handle", true)
        return false
    end

    local applied = {}

    local function try(label, fn)
        local ok, err = driftgod.Try(fn)
        table.insert(applied, label .. "=" .. tostring(ok))
        return ok, err
    end

    if type(driftgod.ApplyGhostStyleToVehicle) == "function" then
        local ok, result = driftgod.Try(function() return driftgod.ApplyGhostStyleToVehicle(veh) end)
        table.insert(applied, "driftgod.ApplyGhostStyleToVehicle=" .. tostring(ok))
        if ok and result ~= false then
            ghostLog("Ghost style applied via driftgod.ApplyGhostStyleToVehicle | veh=" .. tostring(veh), true)
            return true
        end
    end

    if type(driftgod.MakeVehicleGhost) == "function" then
        local ok, result = driftgod.Try(function() return driftgod.MakeVehicleGhost(veh) end)
        table.insert(applied, "driftgod.MakeVehicleGhost=" .. tostring(ok))
        if ok and result ~= false then
            ghostLog("Ghost style applied via driftgod.MakeVehicleGhost | veh=" .. tostring(veh), true)
            return true
        end
    end

    try("ENTITY.SET_ENTITY_ALPHA", function()
        if ENTITY and ENTITY.SET_ENTITY_ALPHA then ENTITY.SET_ENTITY_ALPHA(veh, 145, false) else error("missing") end
    end)

    try("ENTITY.SET_ENTITY_COLLISION", function()
        if ENTITY and ENTITY.SET_ENTITY_COLLISION then ENTITY.SET_ENTITY_COLLISION(veh, false, false) else error("missing") end
    end)

    try("ENTITY.FREEZE_ENTITY_POSITION", function()
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) else error("missing") end
    end)

    try("ENTITY.SET_ENTITY_INVINCIBLE", function()
        if ENTITY and ENTITY.SET_ENTITY_INVINCIBLE then ENTITY.SET_ENTITY_INVINCIBLE(veh, true) else error("missing") end
    end)

    try("VEHICLE.SET_VEHICLE_ENGINE_ON", function()
        if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then VEHICLE.SET_VEHICLE_ENGINE_ON(veh, false, true, true) else error("missing") end
    end)

    try("VEHICLE.SET_VEHICLE_COLOURS", function()
        if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then VEHICLE.SET_VEHICLE_COLOURS(veh, 145, 145) else error("missing") end
    end)

    try("VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR", function()
        if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(veh, 120, 80, 255) else error("missing") end
    end)

    try("VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR", function()
        if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(veh, 40, 0, 80) else error("missing") end
    end)

    try("VEHICLE.SET_VEHICLE_NEON_ENABLED", function()
        if VEHICLE and VEHICLE.SET_VEHICLE_NEON_ENABLED then
            for i = 0, 3 do VEHICLE.SET_VEHICLE_NEON_ENABLED(veh, i, true) end
        else
            error("missing")
        end
    end)

    try("VEHICLE.SET_VEHICLE_NEON_COLOUR", function()
        if VEHICLE and VEHICLE.SET_VEHICLE_NEON_COLOUR then VEHICLE.SET_VEHICLE_NEON_COLOUR(veh, 120, 80, 255) else error("missing") end
    end)

    ghostLog("Ghost style attempt | veh=" .. tostring(veh) .. " | " .. table.concat(applied, " | "), driftgod.S and driftgod.S.ghostReplayPlaybackVerbose == true)
    return true
end

function driftgod.SpawnGhostPreviewVehicleWithModel(model, label)
    driftgod.GhostReplayEnsureDefaults()

    model = tonumber(model or 0) or 0
    label = tostring(label or "manual")

    if model == 0 then
        ghostLog("Warning: invalid ghost preview model for " .. label, true)
        return false
    end

    if type(driftgod.SpawnGhostPreviewBridge) == "function" then
        local veh = driftgod.SpawnGhostPreviewBridge(model, label, {
            alpha = 145,
            noCollision = true,
            frozen = true,
            invisible = false,
        })

        veh = tonumber(veh or 0) or 0
        if veh ~= 0 then
            driftgod.S.ghostReplayPreviewVehicle = veh
            driftgod.S.ghostReplayPreviewVehicleModel = model
            driftgod.S.ghostReplayPreviewConfirmedWorking = true
            ghostLog("Ghost spawn bridge success | model=" .. tostring(model)
                .. " | label=" .. label
                .. " | veh=" .. tostring(veh), true)
            return true
        end

        ghostLog("Warning: Ghost spawn bridge returned 0 | model=" .. tostring(model)
            .. " | label=" .. label, true)
    end

    if tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) ~= 0 then
        driftgod.DeleteGhostPreviewVehicle()
    end

    local requested = requestModelSafe(model)
    local ped = getPlayerPedSafe()
    if ped == 0 then
        ghostLog("Warning: could not resolve player ped for ghost preview spawn", true)
        return false
    end

    local px, py, pz = getEntityCoordsSafe(ped)
    local heading = getEntityHeadingSafe(ped)
    local sx, sy, sz = offsetFromHeading(px, py, pz, heading, 6.0, 3.0)

    local veh, method = createVehicleSafe(model, sx, sy, sz + 0.25, heading)
    if not veh or veh == 0 then
        ghostLog("Warning: failed to create ghost preview vehicle | model=" .. tostring(model)
            .. " | requested=" .. tostring(requested)
            .. " | lastMethod=" .. tostring(method), true)
        if driftgod.GhostReplaySpawnEnvironmentSnapshot then driftgod.GhostReplaySpawnEnvironmentSnapshot("spawn failure") end
        return false
    end

    driftgod.S.ghostReplayPreviewVehicle = veh
    driftgod.S.ghostReplayPreviewVehicleModel = model
    driftgod.S.ghostReplayPreviewConfirmedWorking = true
    driftgod.StyleGhostPreviewVehicle(veh)

    ghostLog("Spawned ghost preview vehicle | model=" .. tostring(model)
        .. " | label=" .. tostring(label)
        .. " | method=" .. tostring(method)
        .. " | handle=" .. tostring(veh), true)

    return true
end

function driftgod.SpawnGhostPreviewVehicle()
    driftgod.GhostReplayEnsureDefaults()

    local replay = driftgod.GetSelectedGhostReplay and driftgod.GetSelectedGhostReplay() or nil
    if not replay then
        ghostLog("Warning: no selected replay to spawn preview from", true)
        return false
    end

    return driftgod.SpawnGhostPreviewVehicleWithModel(replay.vehicleModel, replay.name or "selected replay")
end

function driftgod.SpawnGhostPreviewViaZentornoBridge()
    driftgod.GhostReplayEnsureDefaults()

    if type(driftgod.SpawnZentorno) ~= "function" then
        ghostLog("Warning: driftgod.SpawnZentorno bridge is not available", true)
        if driftgod.GhostReplaySpawnEnvironmentSnapshot then driftgod.GhostReplaySpawnEnvironmentSnapshot("zentorno bridge unavailable") end
        return false
    end

    local ok, result = driftgod.Try(function()
        return driftgod.SpawnZentorno()
    end)

    if ok then

        local veh = tonumber(result or 0) or 0
        driftgod.S.ghostReplayPreviewVehicle = veh
        driftgod.S.ghostReplayPreviewVehicleModel = 2891838741

        ghostLog("Zentorno bridge called successfully | returned=" .. tostring(result), true)

        if veh ~= 0 and driftgod.StyleGhostPreviewVehicle then
            driftgod.StyleGhostPreviewVehicle(veh)
        else
            ghostLog("Zentorno bridge did not return a usable handle for styling", true)
        end

        return true
    end

    ghostLog("Warning: driftgod.SpawnZentorno bridge errored | error=" .. tostring(result), true)
    return false
end

function driftgod.SpawnZentornoGhostPreview()

    driftgod.GhostReplayEnsureDefaults()

    local function tryModel(model, label)
        local ok, result = driftgod.Try(function()
            return driftgod.SpawnGhostPreviewVehicleWithModel(model, label)
        end)

        if ok and result == true then
            ghostLog("Zentorno ghost test succeeded | model=" .. tostring(model) .. " | label=" .. tostring(label), true)
            return true
        end

        ghostLog("Warning: Zentorno ghost test attempt failed | model=" .. tostring(model)
            .. " | ok=" .. tostring(ok)
            .. " | result=" .. tostring(result), true)
        return false
    end

    if tryModel(2891838741, "Zentorno ghost test unsigned") then return true end

    if tryModel(-1403128555, "Zentorno ghost test signed") then return true end

    ghostLog("Warning: Zentorno ghost test failed for both unsigned and signed hashes", true)
    return false
end

function driftgod.InstallGhostReplay(source)
    driftgod.GhostReplayEnsureDefaults()

    if driftgod.GhostReplay.installed == true then
        return true
    end

    driftgod.GhostReplay.installed = true
    driftgod.GhostReplay.source = tostring(source or "unknown")

    ghostLog("Installed GhostReplay foundation | source=" .. tostring(source or "unknown")
        .. " | replays=" .. tostring(driftgod.GetGhostReplayCount())
        .. " | tracks=" .. tostring(driftgod.GetGhostTrackCount()))

    return true
end

function driftgod.SafeDeleteGhostPreviewButton()
    driftgod.GhostReplayEnsureDefaults()

    local ok, result = driftgod.Try(function()
        if type(driftgod.DeleteGhostPreviewBridge) == "function" then
            return driftgod.DeleteGhostPreviewBridge()
        end

        local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0

        if veh ~= 0 then
            driftgod.Try(function()
                if ENTITY and ENTITY.DELETE_ENTITY then
                    ENTITY.DELETE_ENTITY(veh)
                elseif Natives and Natives.InvokeVoid then
                    Natives.InvokeVoid(0xAE3CBE5BF394C9C9, veh)
                end
            end)
        end

        driftgod.S.ghostReplayPreviewVehicle = 0
        driftgod.S.ghostReplayPreviewVehicleModel = 0
        driftgod.S.ghostReplayPreviewConfirmedWorking = false

        ghostLog("Safe delete ghost preview completed | veh=" .. tostring(veh), true)
        return true
    end)

    if not ok then
        ghostLog("Warning: SafeDeleteGhostPreviewButton caught error | error=" .. tostring(result), true)
        driftgod.S.ghostReplayPreviewVehicle = 0
        driftgod.S.ghostReplayPreviewVehicleModel = 0
        driftgod.S.ghostReplayPreviewConfirmedWorking = false
        return false
    end

    return result == true
end

function driftgod.SafeSpawnZentornoGhostButton()
    driftgod.GhostReplayEnsureDefaults()

    local attempts = {
        { model = 2891838741, label = "Zentorno ghost test unsigned" },
        { model = -1403128555, label = "Zentorno ghost test signed" },
    }

    for _, attempt in ipairs(attempts) do
        local ok, result = driftgod.Try(function()
            if type(driftgod.SpawnGhostPreviewVehicleWithModel) == "function" then
                return driftgod.SpawnGhostPreviewVehicleWithModel(attempt.model, attempt.label)
            end
            return false
        end)

        ghostLog("Zentorno safe attempt | model=" .. tostring(attempt.model)
            .. " | ok=" .. tostring(ok)
            .. " | result=" .. tostring(result), true)

        if ok and result == true then
            return true
        end
    end

    ghostLog("Warning: Safe Zentorno ghost test failed; replay ghost preview may still be working.", true)
    return false
end

