function driftgod.GetSelectedGhostReplayFirstNode()
    local replay = driftgod.GetSelectedGhostReplay and driftgod.GetSelectedGhostReplay() or nil
    if not replay then return nil end
    if type(replay.firstNode) ~= "table" then return nil end
    return replay.firstNode, replay
