function driftgod.MoveGhostPreviewToReplayStart()
    driftgod.GhostReplayEnsureDefaults()

    local node, replay = driftgod.GetSelectedGhostReplayFirstNode()
    if not node then
        ghostLog("Warning: selected replay has no firstNode data yet", true)
        return false
    end

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0

    if veh == 0 then
        ghostLog("Move to replay start: no ghost preview handle; spawning selected replay first", true)
        if driftgod.SpawnGhostPreviewVehicle then
            local spawned = driftgod.SpawnGhostPreviewVehicle()
            if spawned ~= true then
                ghostLog("Warning: could not spawn ghost preview before moving to replay start", true)
                return false
            end
            veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0
        end
    end

    if veh == 0 then
        ghostLog("Warning: still no ghost preview handle after spawn attempt", true)
        return false
    end

    local x = tonumber(node.x or 0.0) or 0.0
    local y = tonumber(node.y or 0.0) or 0.0
    local z = tonumber(node.z or 72.0) or 72.0
    local heading = tonumber(node.heading or node.yaw or 0.0) or 0.0

    local ok = false

    if type(driftgod.MoveGhostPreviewBridge) == "function" then
        ok = driftgod.MoveGhostPreviewBridge(veh, x, y, z + 0.10, heading) == true
    else
        driftgod.Try(function()
            if ENTITY and ENTITY.SET_ENTITY_COORDS_NO_OFFSET then
                ENTITY.SET_ENTITY_COORDS_NO_OFFSET(veh, x, y, z + 0.10, false, false, false)
                ok = true
            elseif ENTITY and ENTITY.SET_ENTITY_COORDS then
                ENTITY.SET_ENTITY_COORDS(veh, x, y, z + 0.10, false, false, false, false)
                ok = true
            end

            if ENTITY and ENTITY.SET_ENTITY_HEADING then
                ENTITY.SET_ENTITY_HEADING(veh, heading)
            end
        end)
    end

    driftgod.Try(function()
        if driftgod.StyleGhostPreviewVehicle then driftgod.StyleGhostPreviewVehicle(veh) end
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    driftgod.S.ghostReplayPreviewConfirmedWorking = ok == true
    driftgod.S.ghostReplayAtReplayStart = ok == true

    ghostLog("Move ghost to replay start | ok=" .. tostring(ok)
        .. " | veh=" .. tostring(veh)
        .. " | replay=" .. tostring(replay and replay.name or "")
        .. " | x=" .. tostring(x)
        .. " | y=" .. tostring(y)
        .. " | z=" .. tostring(z)
        .. " | heading=" .. tostring(heading), driftgod.S and driftgod.S.ghostReplayPlaybackVerbose == true)

    return ok == true
end

function driftgod.SafeMoveGhostToReplayStartButton()
    local ok, result = driftgod.Try(function()
        return driftgod.MoveGhostPreviewToReplayStart()
    end)

    if not ok then
        ghostLog("Warning: SafeMoveGhostToReplayStartButton caught error | error=" .. tostring(result), true)
        return false
    end

    return result == true
end

driftgod.GhostReplayMicroNodesByFile = driftgod.GhostReplayMicroNodesByFile or {}

function driftgod.GetSelectedGhostReplayMicroNodes()
    local replay = driftgod.GetSelectedGhostReplay and driftgod.GetSelectedGhostReplay() or nil
    if not replay then return nil, nil end

    if type(replay.microNodes) == "table" and #replay.microNodes > 1 then
        return replay.microNodes, replay
    end

    local byFile = driftgod.GhostReplayMicroNodesByFile or {}
    local keys = {
        replay.file,
        replay.name,
        tostring(replay.file or ""):gsub(":", "."),
        tostring(replay.file or ""):gsub("%.", ":", 1),
    }

    for _, key in ipairs(keys) do
        if key and type(byFile[key]) == "table" and #byFile[key] > 1 then
            replay.microNodes = byFile[key]
            ghostLog("MicroNodes fallback attached | key=" .. tostring(key) .. " | count=" .. tostring(#replay.microNodes), true)
            return replay.microNodes, replay
        end
    end

    ghostLog("Warning: no microNodes found | replay.file=" .. tostring(replay.file)
        .. " | replay.name=" .. tostring(replay.name)
        .. " | fallbackKeys=" .. tostring(byFile ~= nil), true)

    return nil, replay
end

function driftgod.MoveGhostPreviewNodeSafe(veh, x, y, z, heading)
    veh = tonumber(veh or 0) or 0
    if veh == 0 then return false, "no vehicle" end

    x = tonumber(x or 0.0) or 0.0
    y = tonumber(y or 0.0) or 0.0
    z = tonumber(z or 72.0) or 72.0
    heading = tonumber(heading or 0.0) or 0.0

    local bridgeOk = false
    local directOk = false
    local coordMethod = "none"
    local headingOk = false

    if type(driftgod.MoveGhostPreviewBridge) == "function" then
        local ok, result = driftgod.Try(function()
            return driftgod.MoveGhostPreviewBridge(veh, x, y, z, heading)
        end)
        bridgeOk = ok == true and result == true
    end

    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_COORDS_NO_OFFSET then
            ENTITY.SET_ENTITY_COORDS_NO_OFFSET(veh, x, y, z, false, false, false)
            directOk = true
            coordMethod = "SET_ENTITY_COORDS_NO_OFFSET"
        elseif ENTITY and ENTITY.SET_ENTITY_COORDS then
            ENTITY.SET_ENTITY_COORDS(veh, x, y, z, false, false, false, false)
            directOk = true
            coordMethod = "SET_ENTITY_COORDS"
        end
    end)

    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_HEADING then
            ENTITY.SET_ENTITY_HEADING(veh, heading)
            headingOk = true
        end
    end)

    return (bridgeOk or directOk), "bridge=" .. tostring(bridgeOk) .. ", direct=" .. tostring(directOk) .. ", coordMethod=" .. tostring(coordMethod) .. ", heading=" .. tostring(headingOk)
end

function driftgod.JumpGhostPreviewMovementTest()
    driftgod.GhostReplayEnsureDefaults()

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0
    if veh == 0 then
        if driftgod.SpawnGhostPreviewVehicle then driftgod.SpawnGhostPreviewVehicle() end
        veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0
    end

    if veh == 0 then
        ghostLog("Warning: jump movement test failed; no ghost preview handle", true)
        return false
    end

    local node, replay = driftgod.GetSelectedGhostReplayFirstNode and driftgod.GetSelectedGhostReplayFirstNode() or nil, nil
    if type(node) ~= "table" then
        ghostLog("Warning: jump movement test failed; no replay first node", true)
        return false
    end

    local x = tonumber(node.x or 0.0) or 0.0
    local y = tonumber(node.y or 0.0) or 0.0
    local z = tonumber(node.z or 72.0) or 72.0
    local heading = tonumber(node.heading or node.yaw or 0.0) or 0.0

    local rad = math.rad(heading)
    local x2 = x + math.sin(-rad) * 12.0
    local y2 = y + math.cos(rad) * 12.0

    driftgod.Try(function()
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, false) end
    end)

    local ok1, reason1 = driftgod.MoveGhostPreviewNodeSafe(veh, x2, y2, z + 0.25, heading)
    driftgod.Try(function() if Script and Script.Yield then Script.Yield(600) end end)
    local ok2, reason2 = driftgod.MoveGhostPreviewNodeSafe(veh, x, y, z + 0.45, heading)

    driftgod.Try(function()
        if driftgod.StyleGhostPreviewVehicle then driftgod.StyleGhostPreviewVehicle(veh) end
    end)

    ghostLog("Jump movement test | veh=" .. tostring(veh)
        .. " | out=" .. tostring(ok1) .. " {" .. tostring(reason1) .. "}"
        .. " | back=" .. tostring(ok2) .. " {" .. tostring(reason2) .. "}"
        .. " | from=" .. tostring(x) .. "," .. tostring(y) .. "," .. tostring(z)
        .. " | to=" .. tostring(x2) .. "," .. tostring(y2) .. "," .. tostring(z + 0.65), true)

    return ok1 == true or ok2 == true
end

function driftgod.SafeJumpGhostMovementButton()
    local ok, result = driftgod.Try(function()
        return driftgod.JumpGhostPreviewMovementTest()
    end)

    if not ok then
        ghostLog("Warning: SafeJumpGhostMovementButton caught error | error=" .. tostring(result), true)
        return false
    end

    return result == true
end

driftgod.GhostReplayThreeSecondNodesByFile = driftgod.GhostReplayThreeSecondNodesByFile or {}

function driftgod.PlayGhostReplayMicroTest()
    driftgod.GhostReplayEnsureDefaults()

    local nodes, replay = driftgod.GetSelectedGhostReplayMicroNodes()
    if not nodes or #nodes <= 1 then
        ghostLog("Warning: selected replay has no microNodes for playback", true)
        return false
    end

    if type(driftgod.MoveGhostPreviewToReplayStart) == "function" then
        driftgod.MoveGhostPreviewToReplayStart()
    end

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0
    if veh == 0 then
        ghostLog("Warning: no ghost preview handle for micro playback", true)
        return false
    end

    driftgod.S.ghostReplayMicroPlaying = true
    driftgod.S.ghostReplayPlaybackStablePolish = true
    driftgod.S.ghostReplayMicroLastIndex = 0
    driftgod.S.ghostReplayAtReplayStart = true

    ghostLog("Micro playback start | replay=" .. tostring(replay and replay.name or "")
        .. " | nodes=" .. tostring(#nodes)
        .. " | veh=" .. tostring(veh), true)

    driftgod.Try(function()
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    local maxNodes = math.min(#nodes, 45)
    local moved = 0

    for i = 1, maxNodes do
        local node = nodes[i]
        if not node then break end

        local x = tonumber(node.x or 0.0) or 0.0
        local y = tonumber(node.y or 0.0) or 0.0
        local z = tonumber(node.z or 72.0) or 72.0
        local heading = tonumber(node.heading or 0.0) or 0.0

        local ok = false
        local reason = "none"
        if type(driftgod.MoveGhostPreviewNodeSafe) == "function" then
            ok, reason = driftgod.MoveGhostPreviewNodeSafe(veh, x, y, z + 0.45, heading)
        elseif type(driftgod.MoveGhostPreviewBridge) == "function" then
            ok = driftgod.MoveGhostPreviewBridge(veh, x, y, z + 0.10, heading) == true
            reason = "bridgeOnly"
        end

        if i == 1 or i == maxNodes then
            ghostLog("Micro node move | i=" .. tostring(i)
                .. " | ok=" .. tostring(ok)
                .. " | reason=" .. tostring(reason)
                .. " | x=" .. tostring(x)
                .. " | y=" .. tostring(y)
                .. " | z=" .. tostring(z)
                .. " | heading=" .. tostring(heading), true)
        end

        moved = moved + (ok and 1 or 0)
        driftgod.S.ghostReplayMicroLastIndex = i

        driftgod.Try(function()
            if Script and Script.Yield then Script.Yield(0) end
        end)
    end

    driftgod.Try(function()
        if driftgod.StyleGhostPreviewVehicle then driftgod.StyleGhostPreviewVehicle(veh) end
    end)

    driftgod.S.ghostReplayMicroPlaying = false

    ghostLog("Micro playback complete | replay=" .. tostring(replay and replay.name or "")
        .. " | moved=" .. tostring(moved)
        .. "/" .. tostring(maxNodes)
        .. " | veh=" .. tostring(veh), true)

    return moved > 0
end

function driftgod.SafePlayGhostMicroButton()
    local ok, result = driftgod.Try(function()
        return driftgod.PlayGhostReplayMicroTest()
    end)

    if not ok then
        driftgod.S.ghostReplayMicroPlaying = false
        ghostLog("Warning: SafePlayGhostMicroButton caught error | error=" .. tostring(result), true)
        return false
    end

    return result == true
end

