driftgod.GhostReplayTenSecondNodesByFile = driftgod.GhostReplayTenSecondNodesByFile or {}

function driftgod.PlayGhostReplayThreeSecondTest()
    driftgod.GhostReplayEnsureDefaults()

    local nodes, replay = driftgod.GetSelectedGhostReplayThreeSecondNodes()
    if not nodes or #nodes <= 1 then
        ghostLog("Warning: selected replay has no 3-second nodes for playback", true)
        return false
    end

    if type(driftgod.MoveGhostPreviewToReplayStart) == "function" then
        driftgod.MoveGhostPreviewToReplayStart()
    end

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0
    if veh == 0 then
        ghostLog("Warning: no ghost preview handle for 3-second playback", true)
        return false
    end

    driftgod.S.ghostReplayThreeSecondPlaying = true
    driftgod.S.ghostReplayThreeSecondLastIndex = 0

    driftgod.Try(function()
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    local maxNodes = math.min(#nodes, 180)
    local moved = 0

    ghostLog("3 Second playback start | replay=" .. tostring(replay and replay.name or "")
        .. " | nodes=" .. tostring(maxNodes)
        .. " | veh=" .. tostring(veh), true)

    for i = 1, maxNodes do
        local node = nodes[i]
        if not node then break end

        local x = tonumber(node.x or 0.0) or 0.0
        local y = tonumber(node.y or 0.0) or 0.0
        local z = tonumber(node.z or 72.0) or 72.0
        local heading = tonumber(node.heading or 0.0) or 0.0

        local ok = false
        local reason = "none"

        if type(driftgod.MoveGhostPreviewNodeSafe) == "function" then
            ok, reason = driftgod.MoveGhostPreviewNodeSafe(veh, x, y, z + 0.45, heading)
        elseif type(driftgod.MoveGhostPreviewBridge) == "function" then
            ok = driftgod.MoveGhostPreviewBridge(veh, x, y, z + 0.45, heading) == true
            reason = "bridgeOnly"
        end

        if i == 1 or i == 60 or i == 120 or i == maxNodes then
            ghostLog("3 Second node move | i=" .. tostring(i)
                .. " | ok=" .. tostring(ok)
                .. " | reason=" .. tostring(reason)
                .. " | x=" .. tostring(x)
                .. " | y=" .. tostring(y)
                .. " | z=" .. tostring(z)
                .. " | heading=" .. tostring(heading), true)
        end

        moved = moved + (ok and 1 or 0)
        driftgod.S.ghostReplayThreeSecondLastIndex = i

        driftgod.Try(function()
            if Script and Script.Yield then Script.Yield(15) end
        end)
    end

    driftgod.Try(function()
        if driftgod.StyleGhostPreviewVehicle then driftgod.StyleGhostPreviewVehicle(veh) end
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    driftgod.S.ghostReplayThreeSecondPlaying = false

    ghostLog("3 Second playback complete | replay=" .. tostring(replay and replay.name or "")
        .. " | moved=" .. tostring(moved)
        .. "/" .. tostring(maxNodes)
        .. " | veh=" .. tostring(veh), true)

    return moved > 0
end

