function driftgod.GhostReplaySetPlaybackSpeed(mult)
    driftgod.GhostReplayEnsureDefaults()

    mult = tonumber(mult or 1.0) or 1.0
    if mult < 0.25 then mult = 0.25 end
    if mult > 3.0 then mult = 3.0 end

    driftgod.S.ghostReplayPlaybackSpeed = mult
    ghostLog("Playback speed set to " .. tostring(mult) .. "x", true)
    return true
end

