function driftgod.GetGhostReplayPlaybackSpeed()
    driftgod.GhostReplayEnsureDefaults()
    return tonumber(driftgod.S.ghostReplayPlaybackSpeed or 1.0) or 1.0
end

function driftgod.GetGhostReplayYieldMs(baseMs)
    local speed = driftgod.GetGhostReplayPlaybackSpeed and driftgod.GetGhostReplayPlaybackSpeed() or 1.0
    baseMs = tonumber(baseMs or 9) or 9
    local v = math.floor(baseMs / speed)
    if v < 1 then v = 1 end
    return v
end

function driftgod.GhostReplayShouldLogPlaybackCheckpoint(i, maxNodes, checkpointsOnly)
    if driftgod.S and driftgod.S.ghostReplayPlaybackVerbose == true then
        return true
    end

    if checkpointsOnly ~= false then
        local q1 = math.max(1, math.floor(maxNodes * 0.25))
        local q2 = math.max(1, math.floor(maxNodes * 0.50))
        local q3 = math.max(1, math.floor(maxNodes * 0.75))
        return i == 1 or i == q1 or i == q2 or i == q3 or i == maxNodes
    end

    return false
end

function driftgod.ToggleGhostReplayVerboseLogs()
    driftgod.GhostReplayEnsureDefaults()
    driftgod.S.ghostReplayPlaybackVerbose = not (driftgod.S.ghostReplayPlaybackVerbose == true)
    ghostLog("GhostReplay verbose playback logs: " .. tostring(driftgod.S.ghostReplayPlaybackVerbose == true), true)
    return true
end

function driftgod.PlayGhostReplayFullLapTest()
    driftgod.GhostReplayEnsureDefaults()

    local nodes, replay = driftgod.GetSelectedGhostReplayFullLapNodes()
    if not nodes or #nodes <= 1 then
        ghostLog("Warning: selected replay has no full lap nodes for playback", true)
        return false
    end

    if type(driftgod.MoveGhostPreviewToReplayStart) == "function" then
        driftgod.MoveGhostPreviewToReplayStart()
    end

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0
    if veh == 0 then
        ghostLog("Warning: no ghost preview handle for full lap playback", true)
        return false
    end

    driftgod.S.ghostReplayStopRequested = false
    driftgod.S.ghostReplayFullLapPlaying = true
    driftgod.S.ghostReplayFullLapLastIndex = 0
    driftgod.S.ghostReplayPlaybackStatus = "Playing Full Lap"
    driftgod.S.ghostReplayPlaybackProgressPct = 0

    driftgod.Try(function()
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    local maxNodes = #nodes
    local moved = 0
    local q1 = math.max(1, math.floor(maxNodes * 0.25))
    local q2 = math.max(1, math.floor(maxNodes * 0.50))
    local q3 = math.max(1, math.floor(maxNodes * 0.75))

    ghostLog("Full lap playback start | replay=" .. tostring(replay and replay.name or "")
        .. " | nodes=" .. tostring(maxNodes)
        .. " | veh=" .. tostring(veh), driftgod.S and driftgod.S.ghostReplayPlaybackVerbose == true)

    for i = 1, maxNodes do
        local node = nodes[i]
        if not node then break end

        local x = tonumber(node.x or 0.0) or 0.0
        local y = tonumber(node.y or 0.0) or 0.0
        local z = tonumber(node.z or 72.0) or 72.0
        local heading = tonumber(node.heading or 0.0) or 0.0

        local ok = false
        local reason = "none"

        if type(driftgod.MoveGhostPreviewNodeSafe) == "function" then
            ok, reason = driftgod.MoveGhostPreviewNodeSafe(veh, x, y, z + 0.45, heading)
        elseif type(driftgod.MoveGhostPreviewBridge) == "function" then
            ok = driftgod.MoveGhostPreviewBridge(veh, x, y, z + 0.45, heading) == true
            reason = "bridgeOnly"
        end

        if driftgod.GhostReplayShouldLogPlaybackCheckpoint and driftgod.GhostReplayShouldLogPlaybackCheckpoint(i, maxNodes, true) then
            ghostLog("Full lap node move | i=" .. tostring(i)
                .. "/" .. tostring(maxNodes)
                .. " | ok=" .. tostring(ok)
                .. " | reason=" .. tostring(reason)
                .. " | x=" .. tostring(x)
                .. " | y=" .. tostring(y)
                .. " | z=" .. tostring(z)
                .. " | heading=" .. tostring(heading), true)
        end

        moved = moved + (ok and 1 or 0)
        driftgod.S.ghostReplayFullLapLastIndex = i
        driftgod.S.ghostReplayPlaybackProgressPct = math.floor((i / maxNodes) * 100)

        if driftgod.S.ghostReplayStopRequested == true then
            ghostLog("Full lap playback stopped | i=" .. tostring(i) .. "/" .. tostring(maxNodes)
                .. " | moved=" .. tostring(moved), true)
            break
        end

        driftgod.Try(function()
            if Script and Script.Yield then
                local y = driftgod.GetGhostReplayYieldMs and driftgod.GetGhostReplayYieldMs(9) or 9
                Script.Yield(y)
            end
        end)
    end

    driftgod.Try(function()
        if driftgod.StyleGhostPreviewVehicle then driftgod.StyleGhostPreviewVehicle(veh) end
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    driftgod.S.ghostReplayFullLapPlaying = false
    if driftgod.S.ghostReplayStopRequested == true then
        driftgod.S.ghostReplayPlaybackStatus = "Stopped"
    else
        driftgod.S.ghostReplayPlaybackStatus = "Complete"
        driftgod.S.ghostReplayPlaybackProgressPct = 100
    end

    ghostLog("Full lap playback complete | replay=" .. tostring(replay and replay.name or "")
        .. " | moved=" .. tostring(moved)
        .. "/" .. tostring(maxNodes)
        .. " | veh=" .. tostring(veh), true)

    return moved > 0
end

function driftgod.SafePlayGhostFullLapButton()
    local ok, result = driftgod.Try(function()
        return driftgod.PlayGhostReplayFullLapTest()
    end)

    if not ok then
        driftgod.S.ghostReplayFullLapPlaying = false
        driftgod.S.ghostReplayPlaybackStatus = "Error"
        ghostLog("Warning: SafePlayGhostFullLapButton caught error | error=" .. tostring(result), true)
        return false
    end

    return result == true
end

driftgod.GhostReplayLogHistory = driftgod.GhostReplayLogHistory or {}

function driftgod.GhostReplayShouldShowLog(msg, force)
    msg = tostring(msg or "")
    if force == true then return true end

    local lower = string.lower(msg)
    if lower:find("warning", 1, true) then return true end
    if lower:find("error", 1, true) then return true end
    if lower:find("failed", 1, true) then return true end
    if lower:find("caught", 1, true) then return true end
    if lower:find("crash", 1, true) then return true end

    return driftgod.S and driftgod.S.ghostReplayPlaybackVerbose == true
end

function driftgod.GhostReplayCleanLog(msg, force)
    driftgod.GhostReplayEnsureDefaults()
    msg = tostring(msg or "")
    if msg:gsub("%s+", "") == "" then return false end

    table.insert(driftgod.GhostReplayLogHistory, msg)
    if #driftgod.GhostReplayLogHistory > 40 then
        table.remove(driftgod.GhostReplayLogHistory, 1)
    end

    if driftgod.GhostReplayShouldShowLog(msg, force) then
        if log then
            log("[GhostReplay] " .. msg)
        elseif Logger and Logger.Log then
            Logger.Log("[GhostReplay] " .. msg)
        end
    end
end

function driftgod.GhostReplayInfo(msg)
    return driftgod.GhostReplayCleanLog(msg, false)
end

function driftgod.GhostReplayImportant(msg)
    return driftgod.GhostReplayCleanLog(msg, true)
end

function driftgod.ToggleGhostReplayVerboseLogs()
    driftgod.GhostReplayEnsureDefaults()
    driftgod.S.ghostReplayPlaybackVerbose = not (driftgod.S.ghostReplayPlaybackVerbose == true)

    local msg = "GhostReplay verbose playback logs: " .. tostring(driftgod.S.ghostReplayPlaybackVerbose == true)
    if log then
        log("[GhostReplay] " .. msg)
    end
    return true
end

function driftgod.MarkGhostReplayGoldenCheckpoint()
    driftgod.GhostReplayEnsureDefaults()
    driftgod.S.ghostReplayGoldenCheckpoint = "v6.13.62A1 Full Lap Polish confirmed working"
    driftgod.GhostReplayImportant("Golden checkpoint marked: " .. tostring(driftgod.S.ghostReplayGoldenCheckpoint))
    return true
end

function driftgod.GetPlayerVehicleForGhostRecording()
    local ped = 0
    driftgod.Try(function()
        if PLAYER and PLAYER.PLAYER_PED_ID then
            ped = PLAYER.PLAYER_PED_ID() or 0
        end
    end)

    if ped == 0 then return 0 end

    local veh = 0
    driftgod.Try(function()
        if PED and PED.GET_VEHICLE_PED_IS_IN then
            veh = PED.GET_VEHICLE_PED_IS_IN(ped, false) or 0
        end
    end)

    return tonumber(veh or 0) or 0
end

function driftgod.GetEntityCoordsForRecording(ent)
    ent = tonumber(ent or 0) or 0
    local x, y, z = 0.0, 0.0, 72.0

    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_COORDS then
            local c = ENTITY.GET_ENTITY_COORDS(ent, true)
            if type(c) == "table" then
                x = tonumber(c.x or c.X or c[1] or 0.0) or 0.0
                y = tonumber(c.y or c.Y or c[2] or 0.0) or 0.0
                z = tonumber(c.z or c.Z or c[3] or 72.0) or 72.0
            elseif c then
                x = tonumber(c.x or c.X or 0.0) or 0.0
                y = tonumber(c.y or c.Y or 0.0) or 0.0
                z = tonumber(c.z or c.Z or 72.0) or 72.0
            end
        end
    end)

    return x, y, z
end

function driftgod.GetEntityHeadingForRecording(ent)
    ent = tonumber(ent or 0) or 0
    local heading = 0.0

    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_HEADING then
            heading = tonumber(ENTITY.GET_ENTITY_HEADING(ent) or 0.0) or 0.0
        end
    end)

    return heading
end

function driftgod.GhostRecordingEnsureDefaults()
    driftgod.GhostReplayEnsureDefaults()
    driftgod.S.ghostRecordingActive = driftgod.S.ghostRecordingActive == true
    driftgod.S.ghostRecordingNodes = driftgod.S.ghostRecordingNodes or {}
    driftgod.S.ghostRecordingNodeCount = tonumber(driftgod.S.ghostRecordingNodeCount or #driftgod.S.ghostRecordingNodes or 0) or 0
    driftgod.S.ghostRecordingStatus = tostring(driftgod.S.ghostRecordingStatus or "Idle")
    driftgod.S.ghostRecordingStartedAt = tonumber(driftgod.S.ghostRecordingStartedAt or 0) or 0
    driftgod.S.ghostRecordingVehicle = tonumber(driftgod.S.ghostRecordingVehicle or 0) or 0
    driftgod.S.ghostRecordingSampleMs = tonumber(driftgod.S.ghostRecordingSampleMs or 50) or 50
    driftgod.S.ghostRecordingMaxNodes = tonumber(driftgod.S.ghostRecordingMaxNodes or 5000) or 5000
    driftgod.S.ghostRecordedSmoothSteps = tonumber(driftgod.S.ghostRecordedSmoothSteps or 3) or 3

    driftgod.S.ghostRecordedZOffset = tonumber(driftgod.S.ghostRecordedZOffset or 0.08) or 0.08

    driftgod.S.ghostRecordApplyVehicleMods = driftgod.S.ghostRecordApplyVehicleMods ~= false
    driftgod.S.ghostRecordedFxEnabled = driftgod.S.ghostRecordedFxEnabled ~= false

end

function driftgod.SampleGhostRecordingNode(reason)
    driftgod.GhostRecordingEnsureDefaults()

    if driftgod.S.ghostRecordingActive ~= true then
        return false
    end

    local veh = tonumber(driftgod.S.ghostRecordingVehicle or 0) or 0
    if veh == 0 then
        veh = driftgod.GetPlayerVehicleForGhostRecording()
        driftgod.S.ghostRecordingVehicle = veh
    end

    if veh == 0 then
        driftgod.S.ghostRecordingStatus = "No Vehicle"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recording sample skipped: no player vehicle") end
        return false
    end

    local count = tonumber(driftgod.S.ghostRecordingNodeCount or 0) or 0
    local maxNodes = tonumber(driftgod.S.ghostRecordingMaxNodes or 5000) or 5000

    if count >= maxNodes then
        driftgod.S.ghostRecordingActive = false
        driftgod.S.ghostRecordingStatus = "Max Nodes Reached"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recording stopped: max nodes reached " .. tostring(maxNodes)) end
        return false
    end

    local x, y, z = driftgod.GetEntityCoordsForRecording(veh)
    local heading = driftgod.GetEntityHeadingForRecording(veh)

    count = count + 1
    driftgod.S.ghostRecordingNodeCount = count

    local t = count * (tonumber(driftgod.S.ghostRecordingSampleMs or 50) or 50) / 1000.0
    driftgod.S.ghostRecordingNodes[count] = {
        t = t,
        x = x,
        y = y,
        z = z,
        heading = heading,
    }

    if count == 1 or count % 100 == 0 then
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Recording sample | count=" .. tostring(count)
                .. " | x=" .. tostring(x)
                .. " | y=" .. tostring(y)
                .. " | z=" .. tostring(z)
                .. " | heading=" .. tostring(heading)
                .. " | reason=" .. tostring(reason or "manual"))
        end
    end

    driftgod.S.ghostRecordingStatus = "Recording"
    return true
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- ghost recording
-- note: records local ghost nodes for saved replay and race features.
-- ═══════════════════════════════════════════════════════════════════════════════════

function driftgod.StartGhostRecording()
    driftgod.GhostRecordingEnsureDefaults()

    local veh = driftgod.GetPlayerVehicleForGhostRecording()
    if veh == 0 then
        driftgod.S.ghostRecordingStatus = "Start Failed: No Vehicle"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Start recording failed: player is not in a vehicle") end
        return false
    end

    driftgod.S.ghostRecordingNodes = {}
    driftgod.S.ghostRecordingNodeCount = 0
    driftgod.S.ghostRecordingVehicle = veh
    driftgod.S.ghostRecordingActive = true
    driftgod.S.ghostRecordingStartedAt = os.clock and os.clock() or 0
    driftgod.S.ghostRecordingStatus = "Recording"

    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Ghost recording started | veh=" .. tostring(veh)) end

    driftgod.SampleGhostRecordingNode("start")
    return true
end

function driftgod.StopGhostRecording()
    driftgod.GhostRecordingEnsureDefaults()

    if driftgod.S.ghostRecordingActive ~= true then
        driftgod.S.ghostRecordingStatus = "Stopped"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Ghost recording stop requested; recording was not active") end
        return true
    end

    driftgod.SampleGhostRecordingNode("stop")
    driftgod.S.ghostRecordingActive = false
    driftgod.S.ghostRecordingStatus = "Stopped"

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Ghost recording stopped | nodes=" .. tostring(driftgod.S.ghostRecordingNodeCount or 0))
    end

    return true
end

function driftgod.ManualGhostRecordingSample()
    local ok, result = driftgod.Try(function()
        return driftgod.SampleGhostRecordingNode("manual")
    end)

    if not ok then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Manual recording sample error: " .. tostring(result)) end
        return false
    end

    return result == true
end

function driftgod.SafeStartGhostRecordingButton()
    local ok, result = driftgod.Try(function()
        return driftgod.StartGhostRecording()
    end)

    if not ok then
        driftgod.S.ghostRecordingActive = false
        driftgod.S.ghostRecordingStatus = "Start Error"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("SafeStartGhostRecordingButton caught error | error=" .. tostring(result)) end
        return false
    end

    return result == true
end

function driftgod.SafeStopGhostRecordingButton()
    local ok, result = driftgod.Try(function()
        return driftgod.StopGhostRecording()
    end)

    if not ok then
        driftgod.S.ghostRecordingActive = false
        driftgod.S.ghostRecordingStatus = "Stop Error"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("SafeStopGhostRecordingButton caught error | error=" .. tostring(result)) end
        return false
    end

    return result == true
end

function driftgod.SafeManualGhostRecordingSampleButton()
    return driftgod.ManualGhostRecordingSample()
end

function driftgod.GetGhostRecordingSummaryText()
    driftgod.GhostRecordingEnsureDefaults()
    return "Recording: " .. tostring(driftgod.S.ghostRecordingActive == true)
        .. " | Status: " .. tostring(driftgod.S.ghostRecordingStatus or "Idle")
        .. " | Nodes: " .. tostring(driftgod.S.ghostRecordingNodeCount or 0)
        .. " | Vehicle: " .. tostring(driftgod.S.ghostRecordingVehicle or 0)
end

function driftgod.GetRecordedGhostModel()
    driftgod.GhostRecordingEnsureDefaults()

    local veh = tonumber(driftgod.S.ghostRecordingVehicle or 0) or 0
    local model = 0

    if veh ~= 0 then
        driftgod.Try(function()
            if ENTITY and ENTITY.GET_ENTITY_MODEL then
                model = tonumber(ENTITY.GET_ENTITY_MODEL(veh) or 0) or 0
            end
        end)
    end

    if model == 0 then
        model = 2997294755
    end

    return model
end

function driftgod.SpawnRecordedGhostPreview()
    driftgod.GhostRecordingEnsureDefaults()

    local model = driftgod.GetRecordedGhostModel and driftgod.GetRecordedGhostModel() or 2997294755

    if type(driftgod.SpawnGhostPreviewVehicleWithModel) == "function" then
        local ok, result = driftgod.Try(function()
            return driftgod.SpawnGhostPreviewVehicleWithModel(model, "Recorded Ghost In-Memory")
        end)

        if ok and result == true then
            driftgod.S.ghostRecordedPlaybackVehicle = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0
            if driftgod.GhostReplayImportant then
                driftgod.GhostReplayImportant("Recorded ghost preview spawned | model=" .. tostring(model)
                    .. " | veh=" .. tostring(driftgod.S.ghostRecordedPlaybackVehicle or 0))
            end
            return driftgod.S.ghostRecordedPlaybackVehicle ~= 0
        end

        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Warning: recorded ghost preview spawn failed | ok=" .. tostring(ok)
                .. " | result=" .. tostring(result))
        end
    end

    return false
end

function driftgod.MoveRecordedGhostToStart()
    driftgod.GhostRecordingEnsureDefaults()

    local nodes = driftgod.S.ghostRecordingNodes or {}
    if #nodes <= 0 then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Warning: no recorded nodes to move ghost to start") end
        return false
    end

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    if veh == 0 then
        driftgod.SpawnRecordedGhostPreview()
        veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    end

    if veh == 0 then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Warning: no recorded ghost handle after spawn attempt") end
        return false
    end

    local node = nodes[1]
    local ok = false
    local reason = "none"

    if type(driftgod.MoveGhostPreviewNodeSafe) == "function" then
        ok, reason = driftgod.MoveGhostPreviewNodeSafe(veh, node.x, node.y, (node.z or 72.0) + 0.45, node.heading or 0.0)
    elseif type(driftgod.MoveGhostPreviewBridge) == "function" then
        ok = driftgod.MoveGhostPreviewBridge(veh, node.x, node.y, (node.z or 72.0) + 0.45, node.heading or 0.0) == true
        reason = "bridgeOnly"
    end

    driftgod.Try(function()
        if driftgod.StyleGhostPreviewVehicle then driftgod.StyleGhostPreviewVehicle(veh) end
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded ghost moved to start | ok=" .. tostring(ok)
            .. " | reason=" .. tostring(reason)
            .. " | nodes=" .. tostring(#nodes)
            .. " | veh=" .. tostring(veh))
    end

    return ok == true
end

function driftgod.PlayRecordedGhostInMemory()
    driftgod.GhostRecordingEnsureDefaults()

    local nodes = driftgod.S.ghostRecordingNodes or {}
    local count = tonumber(driftgod.S.ghostRecordingNodeCount or #nodes or 0) or 0

    if count <= 1 or #nodes <= 1 then
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Warning: not enough recorded nodes to play | count=" .. tostring(count))
        end
        return false
    end

    if driftgod.S.ghostRecordingActive == true then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recording is active; stopping before playback") end
        driftgod.StopGhostRecording()
    end

    driftgod.SpawnRecordedGhostPreview()
    driftgod.MoveRecordedGhostToStart()

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    if veh == 0 then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Warning: no recorded ghost vehicle handle for playback") end
        return false
    end

    driftgod.S.ghostRecordedPlaybackActive = true
    driftgod.S.ghostRecordedPlaybackStatus = "Playing"
    driftgod.S.ghostRecordedPlaybackLastIndex = 0
    driftgod.S.ghostReplayStopRequested = false

    local maxNodes = math.min(#nodes, count)
    local moved = 0

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded ghost playback start | nodes=" .. tostring(maxNodes)
            .. " | veh=" .. tostring(veh))
    end

    driftgod.Try(function()
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    local q1 = math.max(1, math.floor(maxNodes * 0.25))
    local q2 = math.max(1, math.floor(maxNodes * 0.50))
    local q3 = math.max(1, math.floor(maxNodes * 0.75))

    for i = 1, maxNodes do
        local node = nodes[i]
        if not node then break end

        local ok = false
        local reason = "none"

        if type(driftgod.MoveGhostPreviewNodeSafe) == "function" then
            ok, reason = driftgod.MoveGhostPreviewNodeSafe(veh, node.x, node.y, (node.z or 72.0) + 0.45, node.heading or 0.0)
        elseif type(driftgod.MoveGhostPreviewBridge) == "function" then
            ok = driftgod.MoveGhostPreviewBridge(veh, node.x, node.y, (node.z or 72.0) + 0.45, node.heading or 0.0) == true
            reason = "bridgeOnly"
        end

        if i == 1 or i == q1 or i == q2 or i == q3 or i == maxNodes then
            if driftgod.GhostReplayImportant then
                driftgod.GhostReplayImportant("Recorded node move | i=" .. tostring(i)
                    .. "/" .. tostring(maxNodes)
                    .. " | ok=" .. tostring(ok)
                    .. " | reason=" .. tostring(reason)
                    .. " | x=" .. tostring(node.x)
                    .. " | y=" .. tostring(node.y)
                    .. " | z=" .. tostring(node.z)
                    .. " | heading=" .. tostring(node.heading))
            end
        end

        moved = moved + (ok and 1 or 0)
        driftgod.S.ghostRecordedPlaybackLastIndex = i

        if driftgod.S.ghostReplayStopRequested == true then
            if driftgod.GhostReplayImportant then
                driftgod.GhostReplayImportant("Recorded ghost playback stopped | i=" .. tostring(i)
                    .. "/" .. tostring(maxNodes)
                    .. " | moved=" .. tostring(moved))
            end
            break
        end

        driftgod.Try(function()
            if Script and Script.Yield then
                local y = driftgod.GetGhostReplayYieldMs and driftgod.GetGhostReplayYieldMs(driftgod.S.ghostRecordingSampleMs or 50) or (driftgod.S.ghostRecordingSampleMs or 50)
                Script.Yield(y)
            end
        end)
    end

    driftgod.Try(function()
        if driftgod.StyleGhostPreviewVehicle then driftgod.StyleGhostPreviewVehicle(veh) end
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    driftgod.S.ghostRecordedPlaybackActive = false
    driftgod.S.ghostRecordedPlaybackStatus = driftgod.S.ghostReplayStopRequested == true and "Stopped" or "Complete"

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded ghost playback complete | moved=" .. tostring(moved)
            .. "/" .. tostring(maxNodes)
            .. " | veh=" .. tostring(veh))
    end

    return moved > 0
end

function driftgod.RestartRecordedGhostPlayback()
    driftgod.GhostRecordingEnsureDefaults()
    driftgod.S.ghostReplayStopRequested = true
    driftgod.Try(function() if Script and Script.Yield then Script.Yield(50) end end)
    driftgod.S.ghostReplayStopRequested = false
    return driftgod.PlayRecordedGhostInMemory()
end

