end

function driftgod.SafeMoveRecordedGhostToStartButton()
    local ok, result = driftgod.Try(function()
        return driftgod.MoveRecordedGhostToStart()
    end)

    if not ok then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("SafeMoveRecordedGhostToStartButton caught error | error=" .. tostring(result)) end
        return false
    end

    return result == true
end

function driftgod.RecordGhostFiveSecondTest()
    driftgod.GhostRecordingEnsureDefaults()

    local veh = driftgod.GetPlayerVehicleForGhostRecording and driftgod.GetPlayerVehicleForGhostRecording() or 0
    if veh == 0 then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Record 5 Second Test failed: player is not in a vehicle") end
        return false
    end

    driftgod.S.ghostRecordingNodes = {}
    driftgod.S.ghostRecordingNodeCount = 0
    driftgod.S.ghostRecordingVehicle = veh
    driftgod.S.ghostRecordingActive = true
    driftgod.S.ghostRecordingStatus = "Auto Recording 5s"
    driftgod.S.ghostRecordingSampleMs = 50

    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Record 5 Second Test started | veh=" .. tostring(veh)) end

    local captured = 0
    for i = 1, 100 do
        local ok = driftgod.SampleGhostRecordingNode and driftgod.SampleGhostRecordingNode("auto5s") or false
        if ok then captured = captured + 1 end

        driftgod.Try(function()
            if Script and Script.Yield then Script.Yield(50) end
        end)
    end

    driftgod.S.ghostRecordingActive = false
    driftgod.S.ghostRecordingStatus = "Auto 5s Complete"

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Record 5 Second Test complete | captured=" .. tostring(captured)
            .. " | nodes=" .. tostring(driftgod.S.ghostRecordingNodeCount or 0))
    end

    return captured > 1
end

function driftgod.SafeRecordGhostFiveSecondButton()
    local ok, result = driftgod.Try(function()
        return driftgod.RecordGhostFiveSecondTest()
    end)

    if not ok then
        driftgod.S.ghostRecordingActive = false
        driftgod.S.ghostRecordingStatus = "Auto 5s Error"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("SafeRecordGhostFiveSecondButton caught error | error=" .. tostring(result)) end
        return false
    end

    return result == true
end

function driftgod.HasEnoughRecordedGhostNodes(minNodes)
    driftgod.GhostRecordingEnsureDefaults()
    minNodes = tonumber(minNodes or 3) or 3

    local nodes = driftgod.S.ghostRecordingNodes or {}
    local count = tonumber(driftgod.S.ghostRecordingNodeCount or #nodes or 0) or 0

    if count < minNodes or #nodes < minNodes then
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Not enough recorded nodes | count=" .. tostring(count)
                .. " | tableCount=" .. tostring(#nodes)
                .. " | need=" .. tostring(minNodes))
        end
        return false
    end

    return true
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- ghost preview
-- note: spawns the saved ghost preview without touching the player vehicle.
-- ═══════════════════════════════════════════════════════════════════════════════════

function driftgod.SpawnRecordedGhostPreviewStable()
    driftgod.GhostRecordingEnsureDefaults()

    local existing = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    if existing ~= 0 then
        driftgod.S.ghostRecordedPlaybackVehicle = existing
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Recorded ghost preview already tracked | veh=" .. tostring(existing))
        end
        return true
    end

    return driftgod.SpawnRecordedGhostPreview and driftgod.SpawnRecordedGhostPreview() or false
end

function driftgod.PlayRecordedGhostPreviewPath()
    driftgod.GhostRecordingEnsureDefaults()

    if not driftgod.HasEnoughRecordedGhostNodes(3) then
        return false
    end

    local spawned = driftgod.SpawnRecordedGhostPreviewStable()
    if spawned ~= true then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Play recorded preview path failed: spawn failed") end
        return false
    end

    return driftgod.PlayRecordedGhostInMemory and driftgod.PlayRecordedGhostInMemory() or false
end

function driftgod.SafePlayRecordedGhostPreviewPathButton()
    local ok, result = driftgod.Try(function()
        return driftgod.PlayRecordedGhostPreviewPath()
    end)

    if not ok then
        driftgod.S.ghostRecordedPlaybackActive = false
        driftgod.S.ghostRecordedPlaybackStatus = "Preview Path Error"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("SafePlayRecordedGhostPreviewPathButton caught error | error=" .. tostring(result)) end
        return false
    end

    return result == true
end

function driftgod.PlayRecordedGhostInMemory()
    driftgod.GhostRecordingEnsureDefaults()

    local nodes = driftgod.S.ghostRecordingNodes or {}
    local count = tonumber(driftgod.S.ghostRecordingNodeCount or #nodes or 0) or 0

    if not driftgod.HasEnoughRecordedGhostNodes(3) then
        driftgod.S.ghostRecordedPlaybackStatus = "Not Enough Nodes"
        return false
    end

    if driftgod.S.ghostRecordingActive == true then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recording is active; stopping before recorded playback") end
        driftgod.StopGhostRecording()
    end

    driftgod.SpawnRecordedGhostPreviewStable()
    driftgod.MoveRecordedGhostToStart()

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    if veh == 0 then
        driftgod.S.ghostRecordedPlaybackStatus = "No Ghost Handle"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recorded playback failed: no ghost handle") end
        return false
    end

    driftgod.S.ghostRecordedPlaybackActive = true
    driftgod.S.ghostRecordedPlaybackStatus = "Playing"
    driftgod.S.ghostRecordedPlaybackLastIndex = 0
    driftgod.S.ghostReplayStopRequested = false

    local maxNodes = math.min(#nodes, count)
    local moved = 0

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded ghost playback start | nodes=" .. tostring(maxNodes)
            .. " | veh=" .. tostring(veh))
    end

    driftgod.Try(function()
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    local q1 = math.max(1, math.floor(maxNodes * 0.25))
    local q2 = math.max(1, math.floor(maxNodes * 0.50))
    local q3 = math.max(1, math.floor(maxNodes * 0.75))

    for i = 1, maxNodes do
        local node = nodes[i]
        if not node then break end

        local okMove = false
        local reason = "none"

        if type(driftgod.MoveGhostPreviewNodeSafe) == "function" then
            okMove, reason = driftgod.MoveGhostPreviewNodeSafe(veh, node.x, node.y, (node.z or 72.0) + 0.45, node.heading or 0.0)
        elseif type(driftgod.MoveGhostPreviewBridge) == "function" then
            okMove = driftgod.MoveGhostPreviewBridge(veh, node.x, node.y, (node.z or 72.0) + 0.45, node.heading or 0.0) == true
            reason = "bridgeOnly"
        end

        if i == 1 or i == q1 or i == q2 or i == q3 or i == maxNodes then
            if driftgod.GhostReplayImportant then
                driftgod.GhostReplayImportant("Recorded node move | i=" .. tostring(i)
                    .. "/" .. tostring(maxNodes)
                    .. " | ok=" .. tostring(okMove)
                    .. " | reason=" .. tostring(reason)
                    .. " | x=" .. tostring(node.x)
                    .. " | y=" .. tostring(node.y)
                    .. " | z=" .. tostring(node.z)
                    .. " | heading=" .. tostring(node.heading))
            end
        end

        moved = moved + (okMove and 1 or 0)
        driftgod.S.ghostRecordedPlaybackLastIndex = i

        if driftgod.S.ghostReplayStopRequested == true then
            if driftgod.GhostReplayImportant then
                driftgod.GhostReplayImportant("Recorded ghost playback stopped | i=" .. tostring(i)
                    .. "/" .. tostring(maxNodes)
                    .. " | moved=" .. tostring(moved))
            end
            break
        end

        driftgod.Try(function()
            if Script and Script.Yield then
                local base = tonumber(driftgod.S.ghostRecordingSampleMs or 50) or 50
                local y = driftgod.GetGhostReplayYieldMs and driftgod.GetGhostReplayYieldMs(base) or base
                Script.Yield(y)
            end
        end)
    end

    driftgod.Try(function()
        if driftgod.StyleGhostPreviewVehicle then driftgod.StyleGhostPreviewVehicle(veh) end
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    driftgod.S.ghostRecordedPlaybackActive = false
    driftgod.S.ghostRecordedPlaybackStatus = driftgod.S.ghostReplayStopRequested == true and "Stopped" or "Complete"

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded ghost playback complete | moved=" .. tostring(moved)
            .. "/" .. tostring(maxNodes)
            .. " | veh=" .. tostring(veh))
    end

    return moved > 0
end

function driftgod.LerpNumber(a, b, t)
    a = tonumber(a or 0.0) or 0.0
    b = tonumber(b or 0.0) or 0.0
    t = tonumber(t or 0.0) or 0.0
    return a + ((b - a) * t)
end

function driftgod.LerpHeading(a, b, t)
    a = tonumber(a or 0.0) or 0.0
    b = tonumber(b or 0.0) or 0.0
    t = tonumber(t or 0.0) or 0.0

    local diff = (b - a + 180.0) % 360.0 - 180.0
    return a + diff * t
end

function driftgod.SetRecordedSmoothSteps(steps)
    driftgod.GhostRecordingEnsureDefaults()
    steps = tonumber(steps or 3) or 3
    if steps < 1 then steps = 1 end
    if steps > 8 then steps = 8 end

    driftgod.S.ghostRecordedSmoothSteps = steps

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded smooth steps set to " .. tostring(steps))
    end

    return true
end

function driftgod.RecordGhostFiveSecondFastTest()
    driftgod.GhostRecordingEnsureDefaults()

    local veh = driftgod.GetPlayerVehicleForGhostRecording and driftgod.GetPlayerVehicleForGhostRecording() or 0
    if veh == 0 then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Record 5 Second Fast Test failed: player is not in a vehicle") end
        return false
    end

    driftgod.S.ghostRecordingNodes = {}
    driftgod.S.ghostRecordingNodeCount = 0
    driftgod.S.ghostRecordingVehicle = veh
    driftgod.S.ghostRecordingActive = true
    driftgod.S.ghostRecordingStatus = "Fast Auto Recording 5s"
    driftgod.S.ghostRecordingSampleMs = 25

    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Record 5 Second Fast Test started | veh=" .. tostring(veh) .. " | sampleMs=25") end

    local captured = 0
    for i = 1, 200 do
        local ok = driftgod.SampleGhostRecordingNode and driftgod.SampleGhostRecordingNode("fast5s") or false
        if ok then captured = captured + 1 end

        driftgod.Try(function()
            if Script and Script.Yield then Script.Yield(25) end
        end)
    end

    driftgod.S.ghostRecordingActive = false
    driftgod.S.ghostRecordingStatus = "Fast Auto 5s Complete"

    if driftgod.LogRecordedRotationRange then driftgod.LogRecordedRotationRange("Fast 5s recording rotation range") end

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Record 5 Second Fast Test complete | captured=" .. tostring(captured)
            .. " | nodes=" .. tostring(driftgod.S.ghostRecordingNodeCount or 0))
    end

    return captured > 1
end

function driftgod.SafeRecordGhostFiveSecondFastButton()
    local ok, result = driftgod.Try(function()
        return driftgod.RecordGhostFiveSecondFastTest()
    end)

    if not ok then
        driftgod.S.ghostRecordingActive = false
        driftgod.S.ghostRecordingStatus = "Fast Auto 5s Error"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("SafeRecordGhostFiveSecondFastButton caught error | error=" .. tostring(result)) end
        return false
    end

    return result == true
end

function driftgod.PlayRecordedGhostSmooth()
    driftgod.GhostRecordingEnsureDefaults()

    local nodes = driftgod.S.ghostRecordingNodes or {}
    local count = tonumber(driftgod.S.ghostRecordingNodeCount or #nodes or 0) or 0

    if not driftgod.HasEnoughRecordedGhostNodes or not driftgod.HasEnoughRecordedGhostNodes(3) then
        driftgod.S.ghostRecordedPlaybackStatus = "Not Enough Nodes"
        return false
    end

    if driftgod.S.ghostRecordingActive == true then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recording is active; stopping before smooth playback") end
        driftgod.StopGhostRecording()
    end

    driftgod.SpawnRecordedGhostPreviewStable()
    driftgod.MoveRecordedGhostToStart()

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    if veh == 0 then
        driftgod.S.ghostRecordedPlaybackStatus = "No Ghost Handle"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Smooth recorded playback failed: no ghost handle") end
        return false
    end

    local maxNodes = math.min(#nodes, count)
    local smoothSteps = tonumber(driftgod.S.ghostRecordedSmoothSteps or 3) or 3
    if smoothSteps < 1 then smoothSteps = 1 end
    if smoothSteps > 8 then smoothSteps = 8 end

    driftgod.S.ghostRecordedPlaybackActive = true
    driftgod.S.ghostRecordedPlaybackStatus = "Smooth Playing"
    driftgod.S.ghostRecordedPlaybackLastIndex = 0
    driftgod.S.ghostReplayStopRequested = false

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Smooth recorded playback start | nodes=" .. tostring(maxNodes)
            .. " | steps=" .. tostring(smoothSteps)
            .. " | veh=" .. tostring(veh))
    end

    driftgod.Try(function()
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    local moved = 0
    local q1 = math.max(1, math.floor(maxNodes * 0.25))
    local q2 = math.max(1, math.floor(maxNodes * 0.50))
    local q3 = math.max(1, math.floor(maxNodes * 0.75))

    for i = 1, maxNodes - 1 do
        local a = nodes[i]
        local b = nodes[i + 1]
        if not a or not b then break end

        for s = 1, smoothSteps do
            local t = s / smoothSteps
            local x = driftgod.LerpNumber(a.x, b.x, t)
            local y = driftgod.LerpNumber(a.y, b.y, t)
            local z = driftgod.LerpNumber(a.z, b.z, t)
            local heading = driftgod.LerpHeading(a.heading, b.heading, t)

            local okMove = false
            local reason = "none"

            if type(driftgod.MoveGhostPreviewNodeSafe) == "function" then
                okMove, reason = driftgod.MoveGhostPreviewNodeSafe(veh, x, y, (z or 72.0) + 0.45, heading or 0.0)
            elseif type(driftgod.MoveGhostPreviewBridge) == "function" then
                okMove = driftgod.MoveGhostPreviewBridge(veh, x, y, (z or 72.0) + 0.45, heading or 0.0) == true
                reason = "bridgeOnly"
            end

            moved = moved + (okMove and 1 or 0)
            driftgod.S.ghostRecordedPlaybackLastIndex = i

            if driftgod.S.ghostReplayStopRequested == true then
                if driftgod.GhostReplayImportant then
                    driftgod.GhostReplayImportant("Smooth recorded playback stopped | i=" .. tostring(i)
                        .. "/" .. tostring(maxNodes)
                        .. " | moved=" .. tostring(moved))
                end
                driftgod.S.ghostRecordedPlaybackActive = false
                driftgod.S.ghostRecordedPlaybackStatus = "Stopped"
                return moved > 0
            end

            driftgod.Try(function()
                if Script and Script.Yield then

                    local base = tonumber(driftgod.S.ghostRecordingSampleMs or 50) or 50
                    local yld = math.floor(base / smoothSteps)
                    if yld < 1 then yld = 1 end
                    local speedFn = driftgod.GetGhostReplayPlaybackSpeed and driftgod.GetGhostReplayPlaybackSpeed() or 1.0
                    yld = math.floor(yld / speedFn)
                    if yld < 1 then yld = 1 end
                    Script.Yield(yld)
                end
            end)
        end

        if i == 1 or i == q1 or i == q2 or i == q3 or i == maxNodes - 1 then
            if driftgod.GhostReplayImportant then
                driftgod.GhostReplayImportant("Smooth recorded node | i=" .. tostring(i)
                    .. "/" .. tostring(maxNodes)
                    .. " | movedFrames=" .. tostring(moved)
                    .. " | x=" .. tostring(a.x)
                    .. " | y=" .. tostring(a.y)
                    .. " | z=" .. tostring(a.z)
                    .. " | heading=" .. tostring(a.heading))
            end
        end
    end

    driftgod.Try(function()
        if driftgod.StyleGhostPreviewVehicle then driftgod.StyleGhostPreviewVehicle(veh) end
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    driftgod.S.ghostRecordedPlaybackActive = false
    driftgod.S.ghostRecordedPlaybackStatus = "Smooth Complete"

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Smooth recorded playback complete | movedFrames=" .. tostring(moved)
            .. " | nodes=" .. tostring(maxNodes)
            .. " | steps=" .. tostring(smoothSteps)
            .. " | veh=" .. tostring(veh))
    end

    return moved > 0
end

function driftgod.SafePlayRecordedGhostSmoothButton()
    local ok, result = driftgod.Try(function()
