    end)

    if not ok then
        driftgod.S.ghostRecordedPlaybackActive = false
        driftgod.S.ghostRecordedPlaybackStatus = "Smooth Error"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("SafePlayRecordedGhostSmoothButton caught error | error=" .. tostring(result)) end
        return false
    end

    return result == true
end

