    return driftgod.SetRecordedSmoothSteps(2)
end

function driftgod.RecordedSmoothSteps3()
    return driftgod.SetRecordedSmoothSteps(3)
end

function driftgod.RecordedSmoothSteps5()
    return driftgod.SetRecordedSmoothSteps(5)
end

function driftgod.GetEntityRotationForRecording(ent)
    ent = tonumber(ent or 0) or 0
    local pitch, roll, yaw = 0.0, 0.0, 0.0

    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_ROTATION then
            local r = ENTITY.GET_ENTITY_ROTATION(ent, 2)
            if type(r) == "table" then
                pitch = tonumber(r.x or r.X or r[1] or 0.0) or 0.0
                roll  = tonumber(r.y or r.Y or r[2] or 0.0) or 0.0
                yaw   = tonumber(r.z or r.Z or r[3] or 0.0) or 0.0
            elseif r then
                pitch = tonumber(r.x or r.X or 0.0) or 0.0
                roll  = tonumber(r.y or r.Y or 0.0) or 0.0
                yaw   = tonumber(r.z or r.Z or 0.0) or 0.0
            end
        end
    end)

    return pitch, roll, yaw
end

function driftgod.ApplyRecordedGhostRotation(veh, pitch, roll, yaw, headingFallback)
    veh = tonumber(veh or 0) or 0
    if veh == 0 then return false, "no vehicle" end

    pitch = tonumber(pitch or 0.0) or 0.0
    roll = tonumber(roll or 0.0) or 0.0
    yaw = tonumber(yaw or headingFallback or 0.0) or 0.0
    headingFallback = tonumber(headingFallback or yaw or 0.0) or 0.0

    local rotationOk = false
    local headingOk = false

    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_ROTATION then
            ENTITY.SET_ENTITY_ROTATION(veh, pitch, roll, yaw, 2, true)
            rotationOk = true
        end
    end)

    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_HEADING then
            ENTITY.SET_ENTITY_HEADING(veh, headingFallback)
            headingOk = true
        end
    end)

    return (rotationOk or headingOk), "rotation=" .. tostring(rotationOk) .. ", heading=" .. tostring(headingOk)
end

function driftgod.MoveRecordedGhostNode3D(veh, x, y, z, heading, pitch, roll, yaw)
    local okMove = false
    local moveReason = "none"

    if type(driftgod.MoveGhostPreviewNodeSafe) == "function" then
        okMove, moveReason = driftgod.MoveGhostPreviewNodeSafe(veh, x, y, (z or 72.0) + 0.45, heading or yaw or 0.0)
    elseif type(driftgod.MoveGhostPreviewBridge) == "function" then
        okMove = driftgod.MoveGhostPreviewBridge(veh, x, y, (z or 72.0) + 0.45, heading or yaw or 0.0) == true
        moveReason = "bridgeOnly"
    end

    local okRot, rotReason = driftgod.ApplyRecordedGhostRotation(veh, pitch or 0.0, roll or 0.0, yaw or heading or 0.0, heading or yaw or 0.0)

    return (okMove == true), tostring(moveReason) .. ", " .. tostring(rotReason)
end

function driftgod.SampleGhostRecordingNode(reason)
    driftgod.GhostRecordingEnsureDefaults()

    if driftgod.S.ghostRecordingActive ~= true then
        return false
    end

    local veh = tonumber(driftgod.S.ghostRecordingVehicle or 0) or 0
    if veh == 0 then
        veh = driftgod.GetPlayerVehicleForGhostRecording()
        driftgod.S.ghostRecordingVehicle = veh
    end

    if veh == 0 then
        driftgod.S.ghostRecordingStatus = "No Vehicle"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recording sample skipped: no player vehicle") end
        return false
    end

    local count = tonumber(driftgod.S.ghostRecordingNodeCount or 0) or 0
    local maxNodes = tonumber(driftgod.S.ghostRecordingMaxNodes or 5000) or 5000

    if count >= maxNodes then
        driftgod.S.ghostRecordingActive = false
        driftgod.S.ghostRecordingStatus = "Max Nodes Reached"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recording stopped: max nodes reached " .. tostring(maxNodes)) end
        return false
    end

    local x, y, z = driftgod.GetEntityCoordsForRecording(veh)
    local heading = driftgod.GetEntityHeadingForRecording(veh)
    local pitch, roll, yaw = driftgod.GetEntityRotationForRecording(veh)

    count = count + 1
    driftgod.S.ghostRecordingNodeCount = count

    local t = count * (tonumber(driftgod.S.ghostRecordingSampleMs or 50) or 50) / 1000.0
    driftgod.S.ghostRecordingNodes[count] = {
        t = t,
        x = x,
        y = y,
        z = z,
        heading = heading,
        pitch = pitch,
        roll = roll,
        yaw = yaw,
    }

    if count == 1 or count % 100 == 0 then
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Recording sample 3D | count=" .. tostring(count)
                .. " | x=" .. tostring(x)
                .. " | y=" .. tostring(y)
                .. " | z=" .. tostring(z)
                .. " | heading=" .. tostring(heading)
                .. " | pitch=" .. tostring(pitch)
                .. " | roll=" .. tostring(roll)
                .. " | yaw=" .. tostring(yaw)
                .. " | reason=" .. tostring(reason or "manual"))
        end
    end

    driftgod.S.ghostRecordingStatus = "Recording 3D"
    return true
end

function driftgod.PlayRecordedGhostInMemory()
    driftgod.GhostRecordingEnsureDefaults()

    local nodes = driftgod.S.ghostRecordingNodes or {}
    local count = tonumber(driftgod.S.ghostRecordingNodeCount or #nodes or 0) or 0

    if not driftgod.HasEnoughRecordedGhostNodes or not driftgod.HasEnoughRecordedGhostNodes(3) then
        driftgod.S.ghostRecordedPlaybackStatus = "Not Enough Nodes"
        return false
    end

    if driftgod.S.ghostRecordingActive == true then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recording is active; stopping before recorded playback") end
        driftgod.StopGhostRecording()
    end

    driftgod.SpawnRecordedGhostPreviewStable()
    driftgod.MoveRecordedGhostToStart()

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    if veh == 0 then
        driftgod.S.ghostRecordedPlaybackStatus = "No Ghost Handle"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recorded playback failed: no ghost handle") end
        return false
    end

    driftgod.S.ghostRecordedPlaybackActive = true
    driftgod.S.ghostRecordedPlaybackStatus = "Playing 3D"
    driftgod.S.ghostRecordedPlaybackLastIndex = 0
    driftgod.S.ghostReplayStopRequested = false

    local maxNodes = math.min(#nodes, count)
    local moved = 0

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded ghost 3D playback start | nodes=" .. tostring(maxNodes)
            .. " | veh=" .. tostring(veh))
    end

    driftgod.Try(function()
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    local q1 = math.max(1, math.floor(maxNodes * 0.25))
    local q2 = math.max(1, math.floor(maxNodes * 0.50))
    local q3 = math.max(1, math.floor(maxNodes * 0.75))

    for i = 1, maxNodes do
        local node = nodes[i]
        if not node then break end

        local okMove, reason = driftgod.MoveRecordedGhostNode3D(
            veh,
            node.x,
            node.y,
            node.z,
            node.heading or node.yaw or 0.0,
            node.pitch or 0.0,
            node.roll or 0.0,
            node.yaw or node.heading or 0.0,
            node.speed or 0.0
        )

        if i == 1 or i == q1 or i == q2 or i == q3 or i == maxNodes then
            if driftgod.GhostReplayImportant then
                driftgod.GhostReplayImportant("Recorded 3D node move | i=" .. tostring(i)
                    .. "/" .. tostring(maxNodes)
                    .. " | ok=" .. tostring(okMove)
                    .. " | reason=" .. tostring(reason)
                    .. " | pitch=" .. tostring(node.pitch)
                    .. " | roll=" .. tostring(node.roll)
                    .. " | yaw=" .. tostring(node.yaw))
            end
        end

        moved = moved + (okMove and 1 or 0)
        driftgod.S.ghostRecordedPlaybackLastIndex = i

        if driftgod.S.ghostReplayStopRequested == true then
            break
        end

        driftgod.Try(function()
            if Script and Script.Yield then
                local base = tonumber(driftgod.S.ghostRecordingSampleMs or 50) or 50
                local y = driftgod.GetGhostReplayYieldMs and driftgod.GetGhostReplayYieldMs(base) or base
                Script.Yield(y)
            end
        end)
    end

    driftgod.Try(function()
        if driftgod.StyleGhostPreviewVehicle then driftgod.StyleGhostPreviewVehicle(veh) end
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    driftgod.S.ghostRecordedPlaybackActive = false
    driftgod.S.ghostRecordedPlaybackStatus = driftgod.S.ghostReplayStopRequested == true and "Stopped" or "Complete 3D"

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded ghost 3D playback complete | moved=" .. tostring(moved)
            .. "/" .. tostring(maxNodes)
            .. " | veh=" .. tostring(veh))
    end

    return moved > 0
end

function driftgod.PlayRecordedGhostSmooth()
    driftgod.GhostRecordingEnsureDefaults()

    local nodes = driftgod.S.ghostRecordingNodes or {}
    local count = tonumber(driftgod.S.ghostRecordingNodeCount or #nodes or 0) or 0

    if not driftgod.HasEnoughRecordedGhostNodes or not driftgod.HasEnoughRecordedGhostNodes(3) then
        driftgod.S.ghostRecordedPlaybackStatus = "Not Enough Nodes"
        return false
    end

    if driftgod.S.ghostRecordingActive == true then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recording is active; stopping before smooth 3D playback") end
        driftgod.StopGhostRecording()
    end

    driftgod.SpawnRecordedGhostPreviewStable()
    driftgod.MoveRecordedGhostToStart()

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    if veh == 0 then
        driftgod.S.ghostRecordedPlaybackStatus = "No Ghost Handle"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Smooth 3D recorded playback failed: no ghost handle") end
        return false
    end

    local maxNodes = math.min(#nodes, count)
    local smoothSteps = tonumber(driftgod.S.ghostRecordedSmoothSteps or 3) or 3
    if smoothSteps < 1 then smoothSteps = 1 end
    if smoothSteps > 8 then smoothSteps = 8 end

    driftgod.S.ghostRecordedPlaybackActive = true
    driftgod.S.ghostRecordedPlaybackStatus = "Smooth 3D Playing"
    driftgod.S.ghostRecordedPlaybackLastIndex = 0
    driftgod.S.ghostReplayStopRequested = false

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Smooth recorded 3D playback start | nodes=" .. tostring(maxNodes)
            .. " | steps=" .. tostring(smoothSteps)
            .. " | veh=" .. tostring(veh))
    end

    driftgod.Try(function()
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    local moved = 0
    local q1 = math.max(1, math.floor(maxNodes * 0.25))
    local q2 = math.max(1, math.floor(maxNodes * 0.50))
    local q3 = math.max(1, math.floor(maxNodes * 0.75))

    for i = 1, maxNodes - 1 do
        local a = nodes[i]
        local b = nodes[i + 1]
        if not a or not b then break end

        for s = 1, smoothSteps do
            local t = s / smoothSteps
            local x = driftgod.LerpNumber(a.x, b.x, t)
            local y = driftgod.LerpNumber(a.y, b.y, t)
            local z = driftgod.LerpNumber(a.z, b.z, t)
            local heading = driftgod.LerpHeading(a.heading or a.yaw or 0.0, b.heading or b.yaw or 0.0, t)
            local pitch = driftgod.LerpHeading(a.pitch or 0.0, b.pitch or 0.0, t)
            local roll = driftgod.LerpHeading(a.roll or 0.0, b.roll or 0.0, t)
            local yaw = driftgod.LerpHeading(a.yaw or a.heading or 0.0, b.yaw or b.heading or 0.0, t)

            local okMove, reason = driftgod.MoveRecordedGhostNode3D(veh, x, y, z, heading, pitch, roll, yaw)

            moved = moved + (okMove and 1 or 0)
            driftgod.S.ghostRecordedPlaybackLastIndex = i

            if driftgod.S.ghostReplayStopRequested == true then
                driftgod.S.ghostRecordedPlaybackActive = false
                driftgod.S.ghostRecordedPlaybackStatus = "Stopped"
                return moved > 0
            end

            driftgod.Try(function()
                if Script and Script.Yield then
                    local base = tonumber(driftgod.S.ghostRecordingSampleMs or 50) or 50
                    local yld = math.floor(base / smoothSteps)
                    if yld < 1 then yld = 1 end
                    local speedFn = driftgod.GetGhostReplayPlaybackSpeed and driftgod.GetGhostReplayPlaybackSpeed() or 1.0
                    yld = math.floor(yld / speedFn)
                    if yld < 1 then yld = 1 end
                    Script.Yield(yld)
                end
            end)
        end

        if i == 1 or i == q1 or i == q2 or i == q3 or i == maxNodes - 1 then
            if driftgod.GhostReplayImportant then
                driftgod.GhostReplayImportant("Smooth recorded 3D node | i=" .. tostring(i)
                    .. "/" .. tostring(maxNodes)
                    .. " | movedFrames=" .. tostring(moved)
                    .. " | pitch=" .. tostring(a.pitch)
                    .. " | roll=" .. tostring(a.roll)
                    .. " | yaw=" .. tostring(a.yaw))
            end
        end
    end

    driftgod.Try(function()
        if driftgod.StyleGhostPreviewVehicle then driftgod.StyleGhostPreviewVehicle(veh) end
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    driftgod.S.ghostRecordedPlaybackActive = false
    driftgod.S.ghostRecordedPlaybackStatus = "Smooth 3D Complete"

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Smooth recorded 3D playback complete | movedFrames=" .. tostring(moved)
            .. " | nodes=" .. tostring(maxNodes)
            .. " | steps=" .. tostring(smoothSteps)
            .. " | veh=" .. tostring(veh))
    end

    return moved > 0
end

function driftgod.MoveRecordedGhostToStart()
    driftgod.GhostRecordingEnsureDefaults()

    local nodes = driftgod.S.ghostRecordingNodes or {}
    if #nodes <= 0 then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Warning: no recorded nodes to move ghost to start") end
        return false
    end

    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    if veh == 0 then
        driftgod.SpawnRecordedGhostPreview()
        veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    end

    if veh == 0 then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Warning: no recorded ghost handle after spawn attempt") end
        return false
    end

    local node = nodes[1]
    local ok, reason = driftgod.MoveRecordedGhostNode3D(
        veh,
        node.x,
        node.y,
        node.z,
        node.heading or node.yaw or 0.0,
        node.pitch or 0.0,
        node.roll or 0.0,
        node.yaw or node.heading or 0.0
    )

    driftgod.Try(function()
        if driftgod.StyleGhostPreviewVehicle then driftgod.StyleGhostPreviewVehicle(veh) end
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
    end)

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded ghost moved to 3D start | ok=" .. tostring(ok)
            .. " | reason=" .. tostring(reason)
            .. " | nodes=" .. tostring(#nodes)
            .. " | veh=" .. tostring(veh))
    end

    return ok == true
end

function driftgod.AngleAbsDiff(a, b)
    a = tonumber(a or 0.0) or 0.0
    b = tonumber(b or 0.0) or 0.0
    local d = (b - a + 180.0) % 360.0 - 180.0
    if d < 0 then d = -d end
    return d
end

function driftgod.GetRecordedRotationRange()
    driftgod.GhostRecordingEnsureDefaults()

    local nodes = driftgod.S.ghostRecordingNodes or {}
    local count = tonumber(driftgod.S.ghostRecordingNodeCount or #nodes or 0) or 0
    if count <= 1 then
        return 0.0, 0.0, 0.0
    end

    local minP, maxP = 9999.0, -9999.0
    local minR, maxR = 9999.0, -9999.0
    local minY, maxY = 9999.0, -9999.0

    for i = 1, math.min(count, #nodes) do
        local n = nodes[i]
        if n then
            local p = tonumber(n.pitch or 0.0) or 0.0
            local r = tonumber(n.roll or 0.0) or 0.0
            local y = tonumber(n.yaw or n.heading or 0.0) or 0.0

            if p < minP then minP = p end
            if p > maxP then maxP = p end
            if r < minR then minR = r end
            if r > maxR then maxR = r end
            if y < minY then minY = y end
            if y > maxY then maxY = y end
        end
    end

    return (maxP - minP), (maxR - minR), (maxY - minY)
end

