function driftgod.LogRecordedRotationRange(label)
    local pRange, rRange, yRange = driftgod.GetRecordedRotationRange()

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant(tostring(label or "Recorded rotation range")
            .. " | pitchRange=" .. tostring(pRange)
            .. " | rollRange=" .. tostring(rRange)
            .. " | yawRange=" .. tostring(yRange))
    end

    return true
end

function driftgod.ApplyRecordedGhostRotation(veh, pitch, roll, yaw, headingFallback)
    veh = tonumber(veh or 0) or 0
    if veh == 0 then return false, "no vehicle" end

    pitch = tonumber(pitch or 0.0) or 0.0
    roll = tonumber(roll or 0.0) or 0.0
    yaw = tonumber(yaw or headingFallback or 0.0) or 0.0
    headingFallback = tonumber(headingFallback or yaw or 0.0) or 0.0

    local rotationOk = false
    local headingOk = false

    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_ROTATION then

            ENTITY.SET_ENTITY_ROTATION(veh, pitch, roll, yaw, 2, true)
            rotationOk = true
        end
    end)

    if rotationOk ~= true then
        driftgod.Try(function()
            if ENTITY and ENTITY.SET_ENTITY_HEADING then
                ENTITY.SET_ENTITY_HEADING(veh, headingFallback)
                headingOk = true
            end
        end)
    end

    return (rotationOk or headingOk), "rotation=" .. tostring(rotationOk) .. ", headingFallbackOnly=" .. tostring(headingOk)
end

function driftgod.MoveRecordedGhostNode3D(veh, x, y, z, heading, pitch, roll, yaw)
    veh = tonumber(veh or 0) or 0
    if veh == 0 then return false, "no vehicle" end

    x = tonumber(x or 0.0) or 0.0
    y = tonumber(y or 0.0) or 0.0
    z = tonumber(z or 72.0) or 72.0
    heading = tonumber(heading or yaw or 0.0) or 0.0
    pitch = tonumber(pitch or 0.0) or 0.0
    roll = tonumber(roll or 0.0) or 0.0
    yaw = tonumber(yaw or heading or 0.0) or 0.0

    local coordOk = false
    local coordMethod = "none"

    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_COORDS_NO_OFFSET then
            ENTITY.SET_ENTITY_COORDS_NO_OFFSET(veh, x, y, z + 0.45, false, false, false)
            coordOk = true
            coordMethod = "SET_ENTITY_COORDS_NO_OFFSET"
        elseif ENTITY and ENTITY.SET_ENTITY_COORDS then
            ENTITY.SET_ENTITY_COORDS(veh, x, y, z + 0.45, false, false, false, false)
            coordOk = true
            coordMethod = "SET_ENTITY_COORDS"
        end
    end)

    if coordOk ~= true and type(driftgod.MoveGhostPreviewBridge) == "function" then
        local ok, result = driftgod.Try(function()
            return driftgod.MoveGhostPreviewBridge(veh, x, y, z + 0.45, heading)
        end)
        coordOk = ok == true and result == true
        coordMethod = "MoveGhostPreviewBridge"
    end

    local okRot, rotReason = driftgod.ApplyRecordedGhostRotation(veh, pitch, roll, yaw, heading)

    return (coordOk == true), "coord=" .. tostring(coordOk) .. ", method=" .. tostring(coordMethod) .. ", " .. tostring(rotReason)
end

function driftgod.DebugRecordedRotationSnapshot()
    driftgod.GhostRecordingEnsureDefaults()

    local nodes = driftgod.S.ghostRecordingNodes or {}
    local count = tonumber(driftgod.S.ghostRecordingNodeCount or #nodes or 0) or 0

    if count <= 0 then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recorded rotation snapshot: no nodes") end
        return false
    end

    local first = nodes[1] or {}
    local mid = nodes[math.max(1, math.floor(count * 0.5))] or {}
    local last = nodes[math.min(count, #nodes)] or {}
    local pRange, rRange, yRange = driftgod.GetRecordedRotationRange()

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded rotation snapshot | count=" .. tostring(count)
            .. " | first p/r/y=" .. tostring(first.pitch) .. "/" .. tostring(first.roll) .. "/" .. tostring(first.yaw)
            .. " | mid p/r/y=" .. tostring(mid.pitch) .. "/" .. tostring(mid.roll) .. "/" .. tostring(mid.yaw)
            .. " | last p/r/y=" .. tostring(last.pitch) .. "/" .. tostring(last.roll) .. "/" .. tostring(last.yaw)
            .. " | ranges p/r/y=" .. tostring(pRange) .. "/" .. tostring(rRange) .. "/" .. tostring(yRange))
    end

    return true
end

function driftgod.SafeDebugRecordedRotationSnapshotButton()
    local ok, result = driftgod.Try(function()
        return driftgod.DebugRecordedRotationSnapshot()
    end)

    if not ok then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("SafeDebugRecordedRotationSnapshotButton caught error | error=" .. tostring(result)) end
        return false
    end

    return result == true
end

function driftgod.GetRecordedGhostZOffset()
    driftgod.GhostRecordingEnsureDefaults()
    local offset = tonumber(driftgod.S.ghostRecordedZOffset or 0.08) or 0.08
    if offset < -0.20 then offset = -0.20 end
    if offset > 0.45 then offset = 0.45 end
    return offset
end

function driftgod.SetRecordedGhostZOffset(value)
    driftgod.GhostRecordingEnsureDefaults()
    value = tonumber(value or 0.08) or 0.08
    if value < -0.20 then value = -0.20 end
    if value > 0.45 then value = 0.45 end

    driftgod.S.ghostRecordedZOffset = value

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded ghost Z offset set to " .. tostring(value))
    end

    return true
end

