function driftgod.GhostRecordingAlphaEnsureDefaults()
    driftgod.GhostRecordingEnsureDefaults()

    driftgod.S.ghostRecordingDurationSec = tonumber(driftgod.S.ghostRecordingDurationSec or 30) or 30
    if driftgod.S.ghostRecordingDurationSec < 5 then driftgod.S.ghostRecordingDurationSec = 5 end
    if driftgod.S.ghostRecordingDurationSec > 300 then driftgod.S.ghostRecordingDurationSec = 300 end

    driftgod.S.ghostRecordingFileName = tostring(driftgod.S.ghostRecordingFileName or "")
    if driftgod.S.ghostRecordingFileName == "" then
        driftgod.S.ghostRecordingFileName = "DG_Run_" .. tostring(os.date and os.date("%Y%m%d_%H%M%S") or "New")
    end

    driftgod.S.ghostRecordingLastSavePath = tostring(driftgod.S.ghostRecordingLastSavePath or "")
    driftgod.S.ghostRecordingLastSaveStatus = tostring(driftgod.S.ghostRecordingLastSaveStatus or "Not saved")
    driftgod.S.ghostRecordingSaveFormat = tostring(driftgod.S.ghostRecordingSaveFormat or "json")
end

function driftgod.SanitizeGhostRecordingFileName(name)
    name = tostring(name or "")
    name = name:gsub("[\\/:*?\"<>|]", "_")
    name = name:gsub("%s+", "_")
    name = name:gsub("[^%w_%-%._]", "_")
    name = name:gsub("_+", "_")
    if name == "" then name = "DG_Run" end
    if #name > 64 then name = name:sub(1, 64) end
    return name
end

function driftgod.SetGhostRecordingFileName(name)
    driftgod.GhostRecordingAlphaEnsureDefaults()
    driftgod.S.ghostRecordingFileName = driftgod.SanitizeGhostRecordingFileName(name)
    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recording file name set: " .. tostring(driftgod.S.ghostRecordingFileName))
    end
    return true
end

function driftgod.GhostRecordingNameTimestamp()
    return driftgod.SetGhostRecordingFileName("DG_Run_" .. tostring(os.date and os.date("%Y%m%d_%H%M%S") or "Timestamp"))
end

