function driftgod.GetGhostRecordingSaveDir()

    local dir = nil
    driftgod.Try(function()
        if DG and -- ═══════════════════════════════════════════════════════════════════════════════════
-- paths and storage
-- note: keeps assets, saves, recordings, presets, and protected files under cherax lua storage.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Paths and driftgod.Paths.recordings then dir = tostring(driftgod.Paths.recordings) end
    end)
    if not dir or dir == "" then
        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then
                dir = tostring(FileMgr.GetMenuRootPath() or "") .. "\\Lua\\DriftGod\\storage\\recordings"
            end
        end)
    end
    if not dir or dir == "" then dir = "DriftGod\\storage\\recordings" end
    dir = tostring(dir):gsub("/", "\\")
    if dir:sub(-1) ~= "\\" then dir = dir .. "\\" end
    driftgod.Try(function() os.execute('mkdir "' .. dir .. '" 2>nul') end)
    return dir
end

function driftgod.JsonEscape(s)
    s = tostring(s or "")
    s = s:gsub("\\", "\\\\")
    s = s:gsub('"', '\\"')
    s = s:gsub("\n", "\\n")
    s = s:gsub("\r", "\\r")
    s = s:gsub("\t", "\\t")
    return s
end

function driftgod.BuildRecordedGhostJson()
    driftgod.GhostRecordingAlphaEnsureDefaults()

    local nodes = driftgod.S.ghostRecordingNodes or {}
    local count = tonumber(driftgod.S.ghostRecordingNodeCount or #nodes or 0) or 0

    if count <= 1 or #nodes <= 1 then
        return nil, "not enough recorded nodes"
    end

    local name = driftgod.SanitizeGhostRecordingFileName(driftgod.S.ghostRecordingFileName or "DG_Run")
    local model = tonumber(driftgod.GetRecordedGhostModel and driftgod.GetRecordedGhostModel() or 0) or 0

    local lines = {}
    table.insert(lines, "{\n")
    table.insert(lines, '  "Name": "' .. driftgod.JsonEscape(name) .. '",\n')
    table.insert(lines, '  "Track": "DriftGod Recorded",\n')
    table.insert(lines, '  "VehicleModel": ' .. tostring(model) .. ',\n')
    table.insert(lines, '  "NodeCount": ' .. tostring(count) .. ',\n')
    table.insert(lines, '  "Timestamp": "' .. driftgod.JsonEscape(os.date and os.date("%Y-%m-%d %H:%M:%S") or "") .. '",\n')
    table.insert(lines, '  "Source": "DriftGod ' .. driftgod.JsonEscape(tostring(driftgod.Version or "")) .. '",\n')
    table.insert(lines, '  "Nodes": [\n')

    for i = 1, math.min(count, #nodes) do
        local n = nodes[i] or {}
        local comma = (i < math.min(count, #nodes)) and "," or ""
        table.insert(lines,
            '    { "Time": ' .. tostring(tonumber(n.t or 0) or 0)
            .. ', "Position": { "X": ' .. tostring(tonumber(n.x or 0) or 0)
            .. ', "Y": ' .. tostring(tonumber(n.y or 0) or 0)
            .. ', "Z": ' .. tostring(tonumber(n.z or 0) or 0)
            .. ' }, "Rotation": { "X": ' .. tostring(tonumber(n.pitch or 0) or 0)
            .. ', "Y": ' .. tostring(tonumber(n.roll or 0) or 0)
            .. ', "Z": ' .. tostring(tonumber(n.yaw or n.heading or 0) or 0)
            .. ' }, "Heading": ' .. tostring(tonumber(n.heading or n.yaw or 0) or 0)
            .. " }" .. comma .. "\n"
        )
    end

    table.insert(lines, "  ]\n")
    table.insert(lines, "}\n")

    return table.concat(lines), nil
end

function driftgod.SaveRecordedGhostJson()
    driftgod.GhostRecordingAlphaEnsureDefaults()

    local jsonText, err = driftgod.BuildRecordedGhostJson()
    if not jsonText then
        driftgod.S.ghostRecordingLastSaveStatus = "Save failed: " .. tostring(err)
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant(driftgod.S.ghostRecordingLastSaveStatus) end
        return false
    end

    local dir = driftgod.GetGhostRecordingSaveDir()
    driftgod.Try(function() os.execute('mkdir "' .. tostring(dir) .. '" 2>nul') end)
    local name = driftgod.SanitizeGhostRecordingFileName(driftgod.S.ghostRecordingFileName or "DG_Run")
    local path = dir .. name .. ".json"

    local ok, writeErr = driftgod.Try(function()
        local f = io.open(path, "w")
        if not f then error("io.open failed: " .. tostring(path)) end
        f:write(jsonText)
        f:close()
    end)

    if ok then
        driftgod.S.ghostRecordingLastSavePath = path
        driftgod.S.ghostRecordingLastSaveStatus = "Saved"
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Recorded ghost saved | path=" .. tostring(path)
                .. " | nodes=" .. tostring(driftgod.S.ghostRecordingNodeCount or 0))
        end
        return true
    end

    driftgod.S.ghostRecordingLastSaveStatus = "Save failed: " .. tostring(writeErr)
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant(driftgod.S.ghostRecordingLastSaveStatus) end
    return false
end

