function driftgod.CaptureRecordedVehicleSnapshot(vehicle)
    driftgod.GhostVehicleFxEnsureDefaults()

    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 then return nil end

    local snap = {
        model = 0,
        primary = 0,
        secondary = 0,
        pearlescent = 0,
        wheelColor = 0,
        customPrimary = { r = 0, g = 0, b = 0 },
        customSecondary = { r = 0, g = 0, b = 0 },
        wheelType = 0,
        wheelMod = -1,
        wheelVariation = false,
        windowTint = 0,
        plateIndex = 0,
        tireSmoke = { r = 255, g = 255, b = 255 },
        mods = {},
    }

    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_MODEL then snap.model = tonumber(ENTITY.GET_ENTITY_MODEL(vehicle) or 0) or 0 end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_COLOURS then
            snap.primary, snap.secondary = VEHICLE.GET_VEHICLE_COLOURS(vehicle)
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_EXTRA_COLOURS then
            snap.pearlescent, snap.wheelColor = VEHICLE.GET_VEHICLE_EXTRA_COLOURS(vehicle)
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_CUSTOM_PRIMARY_COLOUR then
            local r,g,b = VEHICLE.GET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle)
            snap.customPrimary = { r = tonumber(r or 0) or 0, g = tonumber(g or 0) or 0, b = tonumber(b or 0) or 0 }
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_CUSTOM_SECONDARY_COLOUR then
            local r,g,b = VEHICLE.GET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle)
            snap.customSecondary = { r = tonumber(r or 0) or 0, g = tonumber(g or 0) or 0, b = tonumber(b or 0) or 0 }
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_WHEEL_TYPE then snap.wheelType = tonumber(VEHICLE.GET_VEHICLE_WHEEL_TYPE(vehicle) or 0) or 0 end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_MOD then
            snap.wheelMod = tonumber(VEHICLE.GET_VEHICLE_MOD(vehicle, 23) or -1) or -1
            if VEHICLE.GET_VEHICLE_MOD_VARIATION then snap.wheelVariation = VEHICLE.GET_VEHICLE_MOD_VARIATION(vehicle, 23) == true end
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_WINDOW_TINT then snap.windowTint = tonumber(VEHICLE.GET_VEHICLE_WINDOW_TINT(vehicle) or 0) or 0 end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT_INDEX then snap.plateIndex = tonumber(VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT_INDEX(vehicle) or 0) or 0 end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_TYRE_SMOKE_COLOR then
            local r,g,b = VEHICLE.GET_VEHICLE_TYRE_SMOKE_COLOR(vehicle)
            snap.tireSmoke = { r = tonumber(r or 255) or 255, g = tonumber(g or 255) or 255, b = tonumber(b or 255) or 255 }
        end
    end)

    for modType = 0, 49 do
        local idx = -1
        local var = false
        driftgod.Try(function()
            if VEHICLE and VEHICLE.GET_VEHICLE_MOD then idx = tonumber(VEHICLE.GET_VEHICLE_MOD(vehicle, modType) or -1) or -1 end
            if VEHICLE and VEHICLE.GET_VEHICLE_MOD_VARIATION then var = VEHICLE.GET_VEHICLE_MOD_VARIATION(vehicle, modType) == true end
        end)
        snap.mods[tostring(modType)] = { index = idx, variation = var }
    end

    driftgod.S.ghostRecordedVehicleSnapshot = snap

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Captured vehicle snapshot | model=" .. tostring(snap.model)
            .. " | primary=" .. tostring(snap.primary)
            .. " | secondary=" .. tostring(snap.secondary)
            .. " | wheelType=" .. tostring(snap.wheelType)
            .. " | wheelMod=" .. tostring(snap.wheelMod))
    end

    return snap
end

function driftgod.ApplyRecordedVehicleSnapshot(vehicle)
    driftgod.GhostVehicleFxEnsureDefaults()

    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 then return false end

    local snap = driftgod.S.ghostRecordedVehicleSnapshot
    if type(snap) ~= "table" then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("No recorded vehicle snapshot to apply") end
        return false
    end

    if driftgod.S.ghostRecordApplyVehicleMods ~= true then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recorded vehicle mod apply skipped; toggle is off") end
        return false
    end

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then VEHICLE.SET_VEHICLE_MOD_KIT(vehicle, 0) end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then VEHICLE.SET_VEHICLE_COLOURS(vehicle, snap.primary or 0, snap.secondary or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicle, snap.pearlescent or 0, snap.wheelColor or 0) end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR and type(snap.customPrimary) == "table" then
            VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle, snap.customPrimary.r or 0, snap.customPrimary.g or 0, snap.customPrimary.b or 0)
        end
        if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR and type(snap.customSecondary) == "table" then
            VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle, snap.customSecondary.r or 0, snap.customSecondary.g or 0, snap.customSecondary.b or 0)
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then VEHICLE.SET_VEHICLE_WHEEL_TYPE(vehicle, snap.wheelType or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD then VEHICLE.SET_VEHICLE_MOD(vehicle, 23, snap.wheelMod or -1, snap.wheelVariation == true) end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WINDOW_TINT then VEHICLE.SET_VEHICLE_WINDOW_TINT(vehicle, snap.windowTint or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX(vehicle, snap.plateIndex or 0) end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR and type(snap.tireSmoke) == "table" then
            VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR(vehicle, snap.tireSmoke.r or 255, snap.tireSmoke.g or 255, snap.tireSmoke.b or 255)
        end
        if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then VEHICLE.TOGGLE_VEHICLE_MOD(vehicle, 20, true) end
    end)

    if type(snap.mods) == "table" then
        for k, v in pairs(snap.mods) do
            local modType = tonumber(k)
            if modType and type(v) == "table" and tonumber(v.index or -1) and tonumber(v.index or -1) >= 0 then
                driftgod.Try(function()
                    if VEHICLE and VEHICLE.SET_VEHICLE_MOD then
                        VEHICLE.SET_VEHICLE_MOD(vehicle, modType, tonumber(v.index or -1) or -1, v.variation == true)
                    end
                end)
            end
        end
    end

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Applied recorded vehicle snapshot | veh=" .. tostring(vehicle)
            .. " | wheelType=" .. tostring(snap.wheelType)
            .. " | wheelMod=" .. tostring(snap.wheelMod))
    end

    return true
end

function driftgod.RecordedGhostApplyFxFrame(veh, speed)
    driftgod.GhostVehicleFxEnsureDefaults()

    if driftgod.S.ghostRecordedFxEnabled ~= true then return false end

    veh = tonumber(veh or 0) or 0
    speed = tonumber(speed or 0.0) or 0.0
    if veh == 0 then return false end

    local applied = false

    if driftgod.S.ghostRecordedWheelFxEnabled == true and speed > 1.0 then
        driftgod.Try(function()
            if ENTITY and ENTITY.SET_ENTITY_VELOCITY then

                ENTITY.SET_ENTITY_VELOCITY(veh, 0.0, 0.0, 0.0)
                applied = true
            end
        end)
    end

    if driftgod.S.ghostRecordedSmokeFxEnabled == true and speed > 8.0 then
        driftgod.Try(function()
            if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then VEHICLE.TOGGLE_VEHICLE_MOD(veh, 20, true) end
            applied = true
        end)
    end

    return applied
end

function driftgod.StartGhostRecording()
    driftgod.GhostRecordingAlphaEnsureDefaults()

    local veh = driftgod.GetPlayerVehicleForGhostRecording()
    if veh == 0 then
        driftgod.S.ghostRecordingStatus = "Start Failed: No Vehicle"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Start recording failed: player is not in a vehicle") end
        return false
    end

    driftgod.S.ghostRecordingNodes = {}
    driftgod.S.ghostRecordingNodeCount = 0
    driftgod.S.ghostRecordingVehicle = veh
    driftgod.S.ghostRecordingActive = true
    driftgod.S.ghostRecordingStartedAt = os.clock and os.clock() or 0
    driftgod.S.ghostRecordingStatus = "Recording"

    driftgod.CaptureRecordedVehicleSnapshot(veh)

    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Ghost recording started | veh=" .. tostring(veh)) end

    driftgod.SampleGhostRecordingNode("start")
    return true
end

function driftgod.RecordGhostTimed(seconds, sampleMs)
    driftgod.GhostRecordingAlphaEnsureDefaults()

    seconds = tonumber(seconds or driftgod.S.ghostRecordingDurationSec or 30) or 30
    sampleMs = tonumber(sampleMs or 25) or 25

    if seconds < 1 then seconds = 1 end
    if seconds > 300 then seconds = 300 end
    if sampleMs < 10 then sampleMs = 10 end
    if sampleMs > 250 then sampleMs = 250 end

    local veh = driftgod.GetPlayerVehicleForGhostRecording and driftgod.GetPlayerVehicleForGhostRecording() or 0
    if veh == 0 then
        driftgod.S.ghostRecordingStatus = "Timed Record Failed: No Vehicle"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Timed recording failed: player is not in a vehicle") end
        return false
    end

    driftgod.CaptureRecordedVehicleSnapshot(veh)

    local targetSamples = math.floor((seconds * 1000) / sampleMs)
    if targetSamples < 2 then targetSamples = 2 end

    driftgod.S.ghostRecordingNodes = {}
    driftgod.S.ghostRecordingNodeCount = 0
    driftgod.S.ghostRecordingVehicle = veh
    driftgod.S.ghostRecordingActive = true
    driftgod.S.ghostRecordingStatus = "Recording " .. tostring(seconds) .. "s"
    driftgod.S.ghostRecordingSampleMs = sampleMs
    driftgod.S.ghostRecordingMaxNodes = math.max(5000, targetSamples + 100)

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Timed recording started | seconds=" .. tostring(seconds)
            .. " | sampleMs=" .. tostring(sampleMs)
            .. " | targetSamples=" .. tostring(targetSamples)
            .. " | veh=" .. tostring(veh))
    end

    local captured = 0
    for i = 1, targetSamples do
        if driftgod.S.ghostRecordingActive ~= true then break end
        local ok = driftgod.SampleGhostRecordingNode and driftgod.SampleGhostRecordingNode("timed") or false
        if ok then captured = captured + 1 end
        driftgod.Try(function() if Script and Script.Yield then Script.Yield(sampleMs) end end)
    end

    driftgod.S.ghostRecordingActive = false
    driftgod.S.ghostRecordingStatus = "Recorded " .. tostring(captured) .. " nodes"

    if driftgod.LogRecordedRotationRange then driftgod.LogRecordedRotationRange("Timed recording rotation range") end

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Timed recording complete | captured=" .. tostring(captured)
            .. " | nodes=" .. tostring(driftgod.S.ghostRecordingNodeCount or 0))
    end

    return captured > 1
end

function driftgod.SampleGhostRecordingNode(reason)
    driftgod.GhostRecordingEnsureDefaults()

    if driftgod.S.ghostRecordingActive ~= true then return false end

    local veh = tonumber(driftgod.S.ghostRecordingVehicle or 0) or 0
    if veh == 0 then
        veh = driftgod.GetPlayerVehicleForGhostRecording()
        driftgod.S.ghostRecordingVehicle = veh
    end
    if veh == 0 then
        driftgod.S.ghostRecordingStatus = "No Vehicle"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recording sample skipped: no player vehicle") end
        return false
    end

    local count = tonumber(driftgod.S.ghostRecordingNodeCount or 0) or 0
    local maxNodes = tonumber(driftgod.S.ghostRecordingMaxNodes or 5000) or 5000
    if count >= maxNodes then
        driftgod.S.ghostRecordingActive = false
        driftgod.S.ghostRecordingStatus = "Max Nodes Reached"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recording stopped: max nodes reached " .. tostring(maxNodes)) end
        return false
    end

    local x, y, z = driftgod.GetEntityCoordsForRecording(veh)
    local heading = driftgod.GetEntityHeadingForRecording(veh)
    local pitch, roll, yaw = driftgod.GetEntityRotationForRecording(veh)
    local speed = 0.0

    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_SPEED then
            speed = tonumber(ENTITY.GET_ENTITY_SPEED(veh) or 0.0) or 0.0
        end
    end)

    count = count + 1
    driftgod.S.ghostRecordingNodeCount = count

    local t = count * (tonumber(driftgod.S.ghostRecordingSampleMs or 50) or 50) / 1000.0
    driftgod.S.ghostRecordingNodes[count] = {
        t = t,
        x = x,
        y = y,
        z = z,
        heading = heading,
        pitch = pitch,
        roll = roll,
        yaw = yaw,
        speed = speed,
    }

    if count == 1 or count % 100 == 0 then
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Recording sample FX | count=" .. tostring(count)
                .. " | speed=" .. tostring(speed)
                .. " | pitch=" .. tostring(pitch)
                .. " | roll=" .. tostring(roll)
                .. " | yaw=" .. tostring(yaw)
                .. " | reason=" .. tostring(reason or "manual"))
        end
    end

    driftgod.S.ghostRecordingStatus = "Recording FX"
    return true
end

function driftgod.SpawnRecordedGhostPreviewStable()
    driftgod.GhostVehicleFxEnsureDefaults()

    local existing = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    if existing ~= 0 then
        driftgod.S.ghostRecordedPlaybackVehicle = existing
        driftgod.ApplyRecordedVehicleSnapshot(existing)
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Recorded ghost preview already tracked | veh=" .. tostring(existing))
        end
        return true
    end

    local ok = driftgod.SpawnRecordedGhostPreview and driftgod.SpawnRecordedGhostPreview() or false
    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    if ok == true and veh ~= 0 then
        driftgod.ApplyRecordedVehicleSnapshot(veh)
    end
    return ok
end

function driftgod.BuildRecordedGhostJson()
    driftgod.GhostRecordingAlphaEnsureDefaults()

    local nodes = driftgod.S.ghostRecordingNodes or {}
    local count = tonumber(driftgod.S.ghostRecordingNodeCount or #nodes or 0) or 0

    if count <= 1 or #nodes <= 1 then
        return nil, "not enough recorded nodes"
    end

    local name = driftgod.SanitizeGhostRecordingFileName(driftgod.S.ghostRecordingFileName or "DG_Run")
    local model = tonumber(driftgod.GetRecordedGhostModel and driftgod.GetRecordedGhostModel() or 0) or 0
    local snap = driftgod.S.ghostRecordedVehicleSnapshot or {}

    local function q(s) return '"' .. driftgod.JsonEscape(tostring(s or "")) .. '"' end

    local lines = {}
    table.insert(lines, "{\n")
    table.insert(lines, '  "Name": ' .. q(name) .. ',\n')
    table.insert(lines, '  "Track": "DriftGod Recorded",\n')
    table.insert(lines, '  "VehicleModel": ' .. tostring(model) .. ',\n')
    table.insert(lines, '  "NodeCount": ' .. tostring(count) .. ',\n')
    table.insert(lines, '  "Timestamp": ' .. q(os.date and os.date("%Y-%m-%d %H:%M:%S") or "") .. ',\n')
    table.insert(lines, '  "Source": "DriftGod ' .. driftgod.JsonEscape(tostring(driftgod.Version or "")) .. '",\n')

    table.insert(lines, '  "VehicleSnapshot": {\n')
    table.insert(lines, '    "model": ' .. tostring(tonumber(snap.model or model) or model) .. ',\n')
    table.insert(lines, '    "primary": ' .. tostring(tonumber(snap.primary or 0) or 0) .. ',\n')
    table.insert(lines, '    "secondary": ' .. tostring(tonumber(snap.secondary or 0) or 0) .. ',\n')
    table.insert(lines, '    "pearlescent": ' .. tostring(tonumber(snap.pearlescent or 0) or 0) .. ',\n')
    table.insert(lines, '    "wheelColor": ' .. tostring(tonumber(snap.wheelColor or 0) or 0) .. ',\n')
    table.insert(lines, '    "wheelType": ' .. tostring(tonumber(snap.wheelType or 0) or 0) .. ',\n')
    table.insert(lines, '    "wheelMod": ' .. tostring(tonumber(snap.wheelMod or -1) or -1) .. ',\n')
    table.insert(lines, '    "windowTint": ' .. tostring(tonumber(snap.windowTint or 0) or 0) .. ',\n')
    table.insert(lines, '    "plateIndex": ' .. tostring(tonumber(snap.plateIndex or 0) or 0) .. '\n')
    table.insert(lines, '  },\n')

    table.insert(lines, '  "Nodes": [\n')
    for i = 1, math.min(count, #nodes) do
        local n = nodes[i] or {}
        local comma = (i < math.min(count, #nodes)) and "," or ""
        table.insert(lines,
            '    { "Time": ' .. tostring(tonumber(n.t or 0) or 0)
            .. ', "Position": { "X": ' .. tostring(tonumber(n.x or 0) or 0)
            .. ', "Y": ' .. tostring(tonumber(n.y or 0) or 0)
            .. ', "Z": ' .. tostring(tonumber(n.z or 0) or 0)
            .. ' }, "Rotation": { "X": ' .. tostring(tonumber(n.pitch or 0) or 0)
            .. ', "Y": ' .. tostring(tonumber(n.roll or 0) or 0)
            .. ', "Z": ' .. tostring(tonumber(n.yaw or n.heading or 0) or 0)
            .. ' }, "Heading": ' .. tostring(tonumber(n.heading or n.yaw or 0) or 0)
            .. ', "Speed": ' .. tostring(tonumber(n.speed or 0) or 0)
            .. " }" .. comma .. "\n"
        )
    end

    table.insert(lines, "  ]\n")
    table.insert(lines, "}\n")

    return table.concat(lines), nil
end

function driftgod.MoveRecordedGhostNode3D(veh, x, y, z, heading, pitch, roll, yaw, speed)
    veh = tonumber(veh or 0) or 0
    if veh == 0 then return false, "no vehicle" end

    x = tonumber(x or 0.0) or 0.0
    y = tonumber(y or 0.0) or 0.0
    z = tonumber(z or 72.0) or 72.0
    heading = tonumber(heading or yaw or 0.0) or 0.0
    pitch = tonumber(pitch or 0.0) or 0.0
    roll = tonumber(roll or 0.0) or 0.0
    yaw = tonumber(yaw or heading or 0.0) or 0.0
    speed = tonumber(speed or 0.0) or 0.0

    local zOffset = driftgod.GetRecordedGhostZOffset and driftgod.GetRecordedGhostZOffset() or 0.08
    local finalZ = z + zOffset
    local coordOk = false
    local coordMethod = "none"

    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_COORDS_NO_OFFSET then
            ENTITY.SET_ENTITY_COORDS_NO_OFFSET(veh, x, y, finalZ, false, false, false)
            coordOk = true
            coordMethod = "SET_ENTITY_COORDS_NO_OFFSET"
        elseif ENTITY and ENTITY.SET_ENTITY_COORDS then
            ENTITY.SET_ENTITY_COORDS(veh, x, y, finalZ, false, false, false, false)
            coordOk = true
            coordMethod = "SET_ENTITY_COORDS"
        end
    end)

    if coordOk ~= true and type(driftgod.MoveGhostPreviewBridge) == "function" then
        local ok, result = driftgod.Try(function()
            return driftgod.MoveGhostPreviewBridge(veh, x, y, finalZ, heading)
        end)
        coordOk = ok == true and result == true
        coordMethod = "MoveGhostPreviewBridge"
    end

    local okRot, rotReason = driftgod.ApplyRecordedGhostRotation(veh, pitch, roll, yaw, heading)
    driftgod.RecordedGhostApplyFxFrame(veh, speed)

    return (coordOk == true), "coord=" .. tostring(coordOk)
        .. ", method=" .. tostring(coordMethod)
        .. ", zOffset=" .. tostring(zOffset)
        .. ", speed=" .. tostring(speed)
        .. ", " .. tostring(rotReason)
end

function driftgod.IsRecordedGhostVehicle(veh)
    veh = tonumber(veh or 0) or 0
    if veh == 0 then return false end

    local a = tonumber(driftgod.S and driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    local b = tonumber(driftgod.S and driftgod.S.ghostReplayPreviewVehicle or 0) or 0

    return veh == a or veh == b
end

function driftgod.StyleRecordedGhostPreserveVisuals(veh)
    driftgod.GhostVehicleFxEnsureDefaults()

    veh = tonumber(veh or 0) or 0
    if veh == 0 then return false end

    local applied = {}

    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_ALPHA then ENTITY.SET_ENTITY_ALPHA(veh, 145, false); table.insert(applied, "alpha") end
        if ENTITY and ENTITY.SET_ENTITY_COLLISION then ENTITY.SET_ENTITY_COLLISION(veh, false, false); table.insert(applied, "collisionOff") end
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true); table.insert(applied, "frozen") end
        if ENTITY and ENTITY.SET_ENTITY_INVINCIBLE then ENTITY.SET_ENTITY_INVINCIBLE(veh, true); table.insert(applied, "invincible") end
        if ENTITY and ENTITY.SET_ENTITY_VISIBLE then ENTITY.SET_ENTITY_VISIBLE(veh, true, false); table.insert(applied, "visible") end
        if ENTITY and ENTITY.SET_ENTITY_AS_MISSION_ENTITY then ENTITY.SET_ENTITY_AS_MISSION_ENTITY(veh, true, true); table.insert(applied, "mission") end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then VEHICLE.SET_VEHICLE_ENGINE_ON(veh, true, true, false); table.insert(applied, "engineOn") end
        if VEHICLE and VEHICLE.SET_VEHICLE_DIRT_LEVEL then VEHICLE.SET_VEHICLE_DIRT_LEVEL(veh, 0.0); table.insert(applied, "clean") end
        if VEHICLE and VEHICLE.SET_VEHICLE_TYRES_CAN_BURST then VEHICLE.SET_VEHICLE_TYRES_CAN_BURST(veh, false); table.insert(applied, "bulletproofTires") end
    end)

    local snapOk = driftgod.ApplyRecordedVehicleSnapshot and driftgod.ApplyRecordedVehicleSnapshot(veh) or false

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded ghost preserve style | veh=" .. tostring(veh)
            .. " | style=" .. table.concat(applied, ",")
            .. " | snapshotApplied=" .. tostring(snapOk))
    end

    return true
end

local DG_PreA3R1_StyleGhostPreviewVehicle = driftgod.StyleGhostPreviewVehicle
function driftgod.StyleGhostPreviewVehicle(veh)
    if driftgod.IsRecordedGhostVehicle and driftgod.IsRecordedGhostVehicle(veh) then
        return driftgod.StyleRecordedGhostPreserveVisuals(veh)
    end

    if DG_PreA3R1_StyleGhostPreviewVehicle then
        return DG_PreA3R1_StyleGhostPreviewVehicle(veh)
    end

    return false
end

local DG_PreA3R1_ApplyRecordedVehicleSnapshot = driftgod.ApplyRecordedVehicleSnapshot
function driftgod.ApplyRecordedVehicleSnapshot(vehicle)
    driftgod.GhostVehicleFxEnsureDefaults()

    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 then return false end

    local snap = driftgod.S.ghostRecordedVehicleSnapshot
    if type(snap) ~= "table" then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("No recorded vehicle snapshot to apply | veh=" .. tostring(vehicle)) end
        return false
    end

    if driftgod.S.ghostRecordApplyVehicleMods ~= true then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recorded vehicle snapshot apply skipped; toggle off") end
        return false
    end

    driftgod.Try(function()
        if DG_PreA3R1_ApplyRecordedVehicleSnapshot then DG_PreA3R1_ApplyRecordedVehicleSnapshot(vehicle) end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then VEHICLE.SET_VEHICLE_MOD_KIT(vehicle, 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then VEHICLE.SET_VEHICLE_COLOURS(vehicle, snap.primary or 0, snap.secondary or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicle, snap.pearlescent or 0, snap.wheelColor or 0) end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR and type(snap.customPrimary) == "table" then
            VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle, snap.customPrimary.r or 0, snap.customPrimary.g or 0, snap.customPrimary.b or 0)
        end
        if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR and type(snap.customSecondary) == "table" then
            VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle, snap.customSecondary.r or 0, snap.customSecondary.g or 0, snap.customSecondary.b or 0)
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then VEHICLE.SET_VEHICLE_WHEEL_TYPE(vehicle, snap.wheelType or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD then
            VEHICLE.SET_VEHICLE_MOD(vehicle, 23, snap.wheelMod or -1, snap.wheelVariation == true)

            VEHICLE.SET_VEHICLE_MOD(vehicle, 24, (snap.mods and snap.mods["24"] and snap.mods["24"].index) or -1, (snap.mods and snap.mods["24"] and snap.mods["24"].variation) == true)
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WINDOW_TINT then VEHICLE.SET_VEHICLE_WINDOW_TINT(vehicle, snap.windowTint or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX(vehicle, snap.plateIndex or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR and type(snap.tireSmoke) == "table" then
            VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR(vehicle, snap.tireSmoke.r or 255, snap.tireSmoke.g or 255, snap.tireSmoke.b or 255)
        end
        if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then VEHICLE.TOGGLE_VEHICLE_MOD(vehicle, 20, true) end
    end)

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded vehicle snapshot FORCE applied | veh=" .. tostring(vehicle)
            .. " | model=" .. tostring(snap.model)
            .. " | primary=" .. tostring(snap.primary)
            .. " | secondary=" .. tostring(snap.secondary)
            .. " | pearl=" .. tostring(snap.pearlescent)
            .. " | wheelType=" .. tostring(snap.wheelType)
            .. " | wheelMod=" .. tostring(snap.wheelMod)
            .. " | customPrimary=" .. tostring(type(snap.customPrimary) == "table"))
    end

    return true
end

function driftgod.RecordedGhostApplyFxFrame(veh, speed)
    driftgod.GhostVehicleFxEnsureDefaults()

    if driftgod.S.ghostRecordedFxEnabled ~= true then return false end

    veh = tonumber(veh or 0) or 0
    speed = tonumber(speed or 0.0) or 0.0
    if veh == 0 then return false end

    local applied = {}

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then VEHICLE.SET_VEHICLE_ENGINE_ON(veh, true, true, false); table.insert(applied, "engine") end
    end)

    if driftgod.S.ghostRecordedWheelFxEnabled == true and speed > 0.5 then
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_FORWARD_SPEED then
                VEHICLE.SET_VEHICLE_FORWARD_SPEED(veh, math.min(speed, 35.0))
                table.insert(applied, "forwardSpeed")
            end
        end)
    end

    if driftgod.S.ghostRecordedSmokeFxEnabled == true and speed > 3.0 then
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_BURNOUT then VEHICLE.SET_VEHICLE_BURNOUT(veh, true); table.insert(applied, "burnout") end
            if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then VEHICLE.TOGGLE_VEHICLE_MOD(veh, 20, true); table.insert(applied, "smokeMod") end
        end)
    end

    driftgod.S.ghostRecordedFxFrameCounter = (tonumber(driftgod.S.ghostRecordedFxFrameCounter or 0) or 0) + 1
    if #applied > 0 and driftgod.S.ghostRecordedFxFrameCounter % 120 == 0 and driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded FX frame | veh=" .. tostring(veh)
            .. " | speed=" .. tostring(speed)
            .. " | applied=" .. table.concat(applied, ","))
    end

    return #applied > 0
end

function driftgod.SpawnRecordedGhostPreviewStable()
    driftgod.GhostVehicleFxEnsureDefaults()

    local existing = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    if existing ~= 0 then
        driftgod.S.ghostRecordedPlaybackVehicle = existing
        driftgod.StyleRecordedGhostPreserveVisuals(existing)
        return true
    end

    local ok = driftgod.SpawnRecordedGhostPreview and driftgod.SpawnRecordedGhostPreview() or false
    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or driftgod.S.ghostRecordedPlaybackVehicle or 0) or 0
    if ok == true and veh ~= 0 then
        driftgod.S.ghostRecordedPlaybackVehicle = veh
        driftgod.StyleRecordedGhostPreserveVisuals(veh)
    end
    return ok
end

