function driftgod.BoolText(v)
    return tostring(v == true)
end

function driftgod.CaptureVehicleColorAccuracy(vehicle, snap)
    vehicle = tonumber(vehicle or 0) or 0
    snap = snap or {}
    if vehicle == 0 then return snap end

    snap.hasCustomPrimary = false
    snap.hasCustomSecondary = false
    snap.plateText = ""

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_IS_VEHICLE_PRIMARY_COLOUR_CUSTOM then
            snap.hasCustomPrimary = VEHICLE.GET_IS_VEHICLE_PRIMARY_COLOUR_CUSTOM(vehicle) == true
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_IS_VEHICLE_SECONDARY_COLOUR_CUSTOM then
            snap.hasCustomSecondary = VEHICLE.GET_IS_VEHICLE_SECONDARY_COLOUR_CUSTOM(vehicle) == true
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT then
            snap.plateText = tostring(VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT(vehicle) or "")
        end
    end)

    return snap
end

local DG_PreA3R2_CaptureRecordedVehicleSnapshot = driftgod.CaptureRecordedVehicleSnapshot
function driftgod.CaptureRecordedVehicleSnapshot(vehicle)
    local snap = nil

    driftgod.Try(function()
        if DG_PreA3R2_CaptureRecordedVehicleSnapshot then
            snap = DG_PreA3R2_CaptureRecordedVehicleSnapshot(vehicle)
        end
    end)

    if type(snap) ~= "table" then
        snap = { mods = {} }
    end

    driftgod.CaptureVehicleColorAccuracy(vehicle, snap)
    driftgod.S.ghostRecordedVehicleSnapshot = snap

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Captured vehicle snapshot ACCURATE | model=" .. tostring(snap.model)
            .. " | indexed=" .. tostring(snap.primary) .. "/" .. tostring(snap.secondary)
            .. " | pearl/wheel=" .. tostring(snap.pearlescent) .. "/" .. tostring(snap.wheelColor)
            .. " | customFlags=" .. driftgod.BoolText(snap.hasCustomPrimary) .. "/" .. driftgod.BoolText(snap.hasCustomSecondary)
            .. " | customPrimary=" .. tostring(snap.customPrimary and (snap.customPrimary.r .. "," .. snap.customPrimary.g .. "," .. snap.customPrimary.b) or "nil")
            .. " | customSecondary=" .. tostring(snap.customSecondary and (snap.customSecondary.r .. "," .. snap.customSecondary.g .. "," .. snap.customSecondary.b) or "nil")
            .. " | wheelType=" .. tostring(snap.wheelType)
            .. " | wheelMod=" .. tostring(snap.wheelMod)
            .. " | plateText=" .. tostring(snap.plateText))
    end

    return snap
end

function driftgod.ApplyRecordedVehicleColorsAccurate(vehicle, snap)
    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 or type(snap) ~= "table" then return false end

    local applied = {}

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then VEHICLE.SET_VEHICLE_MOD_KIT(vehicle, 0) end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then
            VEHICLE.SET_VEHICLE_COLOURS(vehicle, tonumber(snap.primary or 0) or 0, tonumber(snap.secondary or 0) or 0)
            table.insert(applied, "indexed")
        end
        if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then
            VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicle, tonumber(snap.pearlescent or 0) or 0, tonumber(snap.wheelColor or 0) or 0)
            table.insert(applied, "extra")
        end
    end)

    if snap.hasCustomPrimary == true and type(snap.customPrimary) == "table" then
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then
                VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle, snap.customPrimary.r or 0, snap.customPrimary.g or 0, snap.customPrimary.b or 0)
                table.insert(applied, "customPrimary")
            end
        end)
    else
        driftgod.Try(function()
            if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR then
                VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle)
                table.insert(applied, "clearPrimary")
            end
        end)
    end

    if snap.hasCustomSecondary == true and type(snap.customSecondary) == "table" then
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then
                VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle, snap.customSecondary.r or 0, snap.customSecondary.g or 0, snap.customSecondary.b or 0)
                table.insert(applied, "customSecondary")
            end
        end)
    else
        driftgod.Try(function()
            if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR then
                VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle)
                table.insert(applied, "clearSecondary")
            end
        end)
    end

    return true, table.concat(applied, ",")
end

function driftgod.ApplyRecordedVehicleSnapshot(vehicle)
    driftgod.GhostVehicleFxEnsureDefaults()

    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 then return false end

    local snap = driftgod.S.ghostRecordedVehicleSnapshot
    if type(snap) ~= "table" then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("No recorded vehicle snapshot to apply | veh=" .. tostring(vehicle)) end
        return false
    end

    if driftgod.S.ghostRecordApplyVehicleMods ~= true then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recorded vehicle snapshot apply skipped; toggle off") end
        return false
    end

    local colorOk, colorApplied = driftgod.ApplyRecordedVehicleColorsAccurate(vehicle, snap)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then VEHICLE.SET_VEHICLE_WHEEL_TYPE(vehicle, snap.wheelType or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD then
            VEHICLE.SET_VEHICLE_MOD(vehicle, 23, snap.wheelMod or -1, snap.wheelVariation == true)
            if type(snap.mods) == "table" and snap.mods["24"] then
                VEHICLE.SET_VEHICLE_MOD(vehicle, 24, snap.mods["24"].index or -1, snap.mods["24"].variation == true)
            end
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WINDOW_TINT then VEHICLE.SET_VEHICLE_WINDOW_TINT(vehicle, snap.windowTint or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX(vehicle, snap.plateIndex or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT and snap.plateText and snap.plateText ~= "" then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT(vehicle, snap.plateText) end
        if VEHICLE and VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR and type(snap.tireSmoke) == "table" then
            VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR(vehicle, snap.tireSmoke.r or 255, snap.tireSmoke.g or 255, snap.tireSmoke.b or 255)
        end
        if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then VEHICLE.TOGGLE_VEHICLE_MOD(vehicle, 20, true) end
    end)

    if type(snap.mods) == "table" then
        for k, v in pairs(snap.mods) do
            local modType = tonumber(k)
            if modType and modType ~= 20 and modType ~= 23 and modType ~= 24 and type(v) == "table" and tonumber(v.index or -1) and tonumber(v.index or -1) >= 0 then
                driftgod.Try(function()
                    if VEHICLE and VEHICLE.SET_VEHICLE_MOD then
                        VEHICLE.SET_VEHICLE_MOD(vehicle, modType, tonumber(v.index or -1) or -1, v.variation == true)
                    end
                end)
            end
        end
    end

    driftgod.ApplyRecordedVehicleColorsAccurate(vehicle, snap)
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then VEHICLE.SET_VEHICLE_WHEEL_TYPE(vehicle, snap.wheelType or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD then VEHICLE.SET_VEHICLE_MOD(vehicle, 23, snap.wheelMod or -1, snap.wheelVariation == true) end
    end)

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Recorded vehicle snapshot ACCURATE applied | veh=" .. tostring(vehicle)
            .. " | colorOk=" .. tostring(colorOk)
            .. " | colorApplied=" .. tostring(colorApplied)
            .. " | indexed=" .. tostring(snap.primary) .. "/" .. tostring(snap.secondary)
            .. " | customFlags=" .. driftgod.BoolText(snap.hasCustomPrimary) .. "/" .. driftgod.BoolText(snap.hasCustomSecondary)
            .. " | wheelType=" .. tostring(snap.wheelType)
            .. " | wheelMod=" .. tostring(snap.wheelMod)
            .. " | plateText=" .. tostring(snap.plateText))
    end

    return true
end

function driftgod.RecordedSmokeFallbackProbe(veh, speed)
    driftgod.GhostVehicleFxEnsureDefaults()

    veh = tonumber(veh or 0) or 0
    speed = tonumber(speed or 0.0) or 0.0

    if veh == 0 or driftgod.S.ghostRecordedSmokeFxEnabled ~= true then return false end

    local tried = {}

    if speed > 3.0 then
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_BURNOUT then VEHICLE.SET_VEHICLE_BURNOUT(veh, true); table.insert(tried, "burnout") end
            if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then VEHICLE.TOGGLE_VEHICLE_MOD(veh, 20, true); table.insert(tried, "smokeMod") end
            if VEHICLE and VEHICLE.SET_VEHICLE_FORWARD_SPEED then VEHICLE.SET_VEHICLE_FORWARD_SPEED(veh, math.min(speed, 25.0)); table.insert(tried, "forwardSpeed") end
            if VEHICLE and VEHICLE.SET_VEHICLE_HAS_STRONG_AXLES then VEHICLE.SET_VEHICLE_HAS_STRONG_AXLES(veh, false); table.insert(tried, "axleProbe") end
        end)
    end

    driftgod.S.ghostRecordedSmokeProbeCounter = (tonumber(driftgod.S.ghostRecordedSmokeProbeCounter or 0) or 0) + 1
    if #tried > 0 and driftgod.S.ghostRecordedSmokeProbeCounter % 150 == 0 and driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Smoke fallback probe | speed=" .. tostring(speed)
            .. " | tried=" .. table.concat(tried, ","))
    end

    return #tried > 0
end

function driftgod.RecordedGhostApplyFxFrame(veh, speed)
    driftgod.GhostVehicleFxEnsureDefaults()

    if driftgod.S.ghostRecordedFxEnabled ~= true then return false end

    veh = tonumber(veh or 0) or 0
    speed = tonumber(speed or 0.0) or 0.0
    if veh == 0 then return false end

    local applied = {}

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then VEHICLE.SET_VEHICLE_ENGINE_ON(veh, true, true, false); table.insert(applied, "engine") end
    end)

    if driftgod.S.ghostRecordedWheelFxEnabled == true and speed > 0.5 then
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_FORWARD_SPEED then
                VEHICLE.SET_VEHICLE_FORWARD_SPEED(veh, math.min(speed, 35.0))
                table.insert(applied, "forwardSpeed")
            end
        end)
    end

    if driftgod.RecordedSmokeFallbackProbe then
        local smoke = driftgod.RecordedSmokeFallbackProbe(veh, speed)
        if smoke then table.insert(applied, "smokeProbe") end
    end

    return #applied > 0
end

