function driftgod.CheraxColorTable(r, g, b)
    return { r = tonumber(r or 0) or 0, g = tonumber(g or 0) or 0, b = tonumber(b or 0) or 0 }
end

function driftgod.BuildCheraxVehicleSnapshotFromRuntime(vehicle)
    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 then return nil end

    local snap = {
        format = "Cherax Entity Runtime Snapshot",
        type = 1,
        model = 0,
        baseFlags = 0,
        mods = {},
        wheelType = 0,
        tyreSmokeColor = { r = 255, g = 255, b = 255 },
        neonKits = {
            left = false,
            right = false,
            front = false,
            back = false,
            color = { r = 255, g = 0, b = 255 },
        },
        primaryColor = 0,
        secondaryColor = 0,
        pearlescentColor = 0,
        wheelColor = 0,
        isPrimaryColorCustom = false,
        customPrimaryColor = { r = 0, g = 0, b = 0 },
        isSecondaryColorCustom = false,
        customSecondaryColor = { r = 0, g = 0, b = 0 },
        windowTint = 0,
        interiorColor = 0,
        dashBoardColor = 0,
        plateText = "",
        plateTextIndex = 0,
    }

    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_MODEL then snap.model = tonumber(ENTITY.GET_ENTITY_MODEL(vehicle) or 0) or 0 end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_COLOURS then
            local p, s = VEHICLE.GET_VEHICLE_COLOURS(vehicle)
            snap.primaryColor = tonumber(p or 0) or 0
            snap.secondaryColor = tonumber(s or 0) or 0
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_EXTRA_COLOURS then
            local pearl, wheel = VEHICLE.GET_VEHICLE_EXTRA_COLOURS(vehicle)
            snap.pearlescentColor = tonumber(pearl or 0) or 0
            snap.wheelColor = tonumber(wheel or 0) or 0
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_IS_VEHICLE_PRIMARY_COLOUR_CUSTOM then
            snap.isPrimaryColorCustom = VEHICLE.GET_IS_VEHICLE_PRIMARY_COLOUR_CUSTOM(vehicle) == true
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_IS_VEHICLE_SECONDARY_COLOUR_CUSTOM then
            snap.isSecondaryColorCustom = VEHICLE.GET_IS_VEHICLE_SECONDARY_COLOUR_CUSTOM(vehicle) == true
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_CUSTOM_PRIMARY_COLOUR then
            local r, g, b = VEHICLE.GET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle)
            snap.customPrimaryColor = driftgod.CheraxColorTable(r, g, b)
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_CUSTOM_SECONDARY_COLOUR then
            local r, g, b = VEHICLE.GET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle)
            snap.customSecondaryColor = driftgod.CheraxColorTable(r, g, b)
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_WHEEL_TYPE then snap.wheelType = tonumber(VEHICLE.GET_VEHICLE_WHEEL_TYPE(vehicle) or 0) or 0 end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_TYRE_SMOKE_COLOR then
            local r, g, b = VEHICLE.GET_VEHICLE_TYRE_SMOKE_COLOR(vehicle)
            snap.tyreSmokeColor = driftgod.CheraxColorTable(r or 255, g or 255, b or 255)
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_WINDOW_TINT then snap.windowTint = tonumber(VEHICLE.GET_VEHICLE_WINDOW_TINT(vehicle) or 0) or 0 end
        if VEHICLE and VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT_INDEX then snap.plateTextIndex = tonumber(VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT_INDEX(vehicle) or 0) or 0 end
        if VEHICLE and VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT then snap.plateText = tostring(VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT(vehicle) or "") end
    end)

    for modType = 0, 49 do
        local idx = -1
        local var = false
        driftgod.Try(function()
            if VEHICLE and VEHICLE.GET_VEHICLE_MOD then idx = tonumber(VEHICLE.GET_VEHICLE_MOD(vehicle, modType) or -1) or -1 end
            if VEHICLE and VEHICLE.GET_VEHICLE_MOD_VARIATION then var = VEHICLE.GET_VEHICLE_MOD_VARIATION(vehicle, modType) == true end
        end)
        snap.mods["mod" .. tostring(modType)] = { index = idx, variation = var }
    end

    return snap
end

function driftgod.CaptureRecordedVehicleSnapshot(vehicle)
    driftgod.GhostVehicleFxEnsureDefaults()

    local snap = driftgod.BuildCheraxVehicleSnapshotFromRuntime(vehicle)
    if type(snap) ~= "table" then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Cherax snapshot capture failed | vehicle=" .. tostring(vehicle)) end
        return nil
    end

    snap.primary = snap.primaryColor
    snap.secondary = snap.secondaryColor
    snap.pearlescent = snap.pearlescentColor
    snap.customPrimary = snap.customPrimaryColor
    snap.customSecondary = snap.customSecondaryColor
    snap.hasCustomPrimary = snap.isPrimaryColorCustom
    snap.hasCustomSecondary = snap.isSecondaryColorCustom
    snap.tireSmoke = snap.tyreSmokeColor
    snap.plateIndex = snap.plateTextIndex
    if snap.mods and snap.mods.mod23 then
        snap.wheelMod = tonumber(snap.mods.mod23.index or -1) or -1
        snap.wheelVariation = snap.mods.mod23.variation == true
    end

    driftgod.S.ghostRecordedVehicleSnapshot = snap

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Captured CHERAX vehicle snapshot | model=" .. tostring(snap.model)
            .. " | primaryColor=" .. tostring(snap.primaryColor)
            .. " | secondaryColor=" .. tostring(snap.secondaryColor)
            .. " | pearl=" .. tostring(snap.pearlescentColor)
            .. " | wheelColor=" .. tostring(snap.wheelColor)
            .. " | customFlags=" .. tostring(snap.isPrimaryColorCustom) .. "/" .. tostring(snap.isSecondaryColorCustom)
            .. " | customPrimary=" .. tostring(snap.customPrimaryColor.r) .. "," .. tostring(snap.customPrimaryColor.g) .. "," .. tostring(snap.customPrimaryColor.b)
            .. " | customSecondary=" .. tostring(snap.customSecondaryColor.r) .. "," .. tostring(snap.customSecondaryColor.g) .. "," .. tostring(snap.customSecondaryColor.b)
            .. " | wheelType=" .. tostring(snap.wheelType)
            .. " | mod23=" .. tostring(snap.mods.mod23 and snap.mods.mod23.index or "nil")
            .. " | wheelColor=" .. tostring(snap.wheelColor)
            .. " | tyreSmoke=" .. tostring(snap.tyreSmokeColor.r) .. "," .. tostring(snap.tyreSmokeColor.g) .. "," .. tostring(snap.tyreSmokeColor.b)
            .. " | plate=" .. tostring(snap.plateTextIndex) .. "/" .. tostring(snap.plateText))
    end

    return snap
end

function driftgod.ApplyCheraxVehicleSnapshotToVehicle(vehicle, snap)
    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 or type(snap) ~= "table" then return false end

    local applied = {}

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then
            VEHICLE.SET_VEHICLE_MOD_KIT(vehicle, 0)
            table.insert(applied, "modKit")
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then
            VEHICLE.SET_VEHICLE_COLOURS(vehicle, tonumber(snap.primaryColor or snap.primary or 0) or 0, tonumber(snap.secondaryColor or snap.secondary or 0) or 0)
            table.insert(applied, "indexedPaint")
        end
        if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then
            VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicle, tonumber(snap.pearlescentColor or snap.pearlescent or 0) or 0, tonumber(snap.wheelColor or 0) or 0)
            table.insert(applied, "extraPearlWheel")
        end
    end)

    local isPrimaryCustom = snap.isPrimaryColorCustom == true or snap.hasCustomPrimary == true
    local isSecondaryCustom = snap.isSecondaryColorCustom == true or snap.hasCustomSecondary == true
    local cp = snap.customPrimaryColor or snap.customPrimary
    local cs = snap.customSecondaryColor or snap.customSecondary

    if isPrimaryCustom == true and type(cp) == "table" then
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then
                VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle, tonumber(cp.r or 0) or 0, tonumber(cp.g or 0) or 0, tonumber(cp.b or 0) or 0)
                table.insert(applied, "customPrimary")
            end
        end)
    else
        driftgod.Try(function()
            if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle); table.insert(applied, "clearPrimary") end
        end)
    end

    if isSecondaryCustom == true and type(cs) == "table" then
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then
                VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle, tonumber(cs.r or 0) or 0, tonumber(cs.g or 0) or 0, tonumber(cs.b or 0) or 0)
                table.insert(applied, "customSecondary")
            end
        end)
    else
        driftgod.Try(function()
            if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle); table.insert(applied, "clearSecondary") end
        end)
    end

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then
            VEHICLE.SET_VEHICLE_WHEEL_TYPE(vehicle, tonumber(snap.wheelType or 0) or 0)
            table.insert(applied, "wheelType")
        end
    end)

    if type(snap.mods) == "table" then
        for i = 0, 49 do
            local key = "mod" .. tostring(i)
            local m = snap.mods[key]
            if type(m) == "table" then
                local idx = tonumber(m.index or -1) or -1
                local var = m.variation == true
                if idx >= 0 then
                    driftgod.Try(function()
                        if VEHICLE and VEHICLE.SET_VEHICLE_MOD then
                            VEHICLE.SET_VEHICLE_MOD(vehicle, i, idx, var)
                        end
                    end)
                end
            end
        end
        table.insert(applied, "mods0-49")
    end

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then VEHICLE.SET_VEHICLE_WHEEL_TYPE(vehicle, tonumber(snap.wheelType or 0) or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD and snap.mods and snap.mods.mod23 then
            VEHICLE.SET_VEHICLE_MOD(vehicle, 23, tonumber(snap.mods.mod23.index or -1) or -1, snap.mods.mod23.variation == true)
        end
        if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then
            VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicle, tonumber(snap.pearlescentColor or snap.pearlescent or 0) or 0, tonumber(snap.wheelColor or 0) or 0)
        end
        table.insert(applied, "wheelFinal")
    end)

    if isPrimaryCustom == true and type(cp) == "table" then
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then
                VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle, tonumber(cp.r or 0) or 0, tonumber(cp.g or 0) or 0, tonumber(cp.b or 0) or 0)
            end
        end)
    end
    if isSecondaryCustom == true and type(cs) == "table" then
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then
                VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle, tonumber(cs.r or 0) or 0, tonumber(cs.g or 0) or 0, tonumber(cs.b or 0) or 0)
            end
        end)
    end

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WINDOW_TINT then VEHICLE.SET_VEHICLE_WINDOW_TINT(vehicle, tonumber(snap.windowTint or 0) or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX(vehicle, tonumber(snap.plateTextIndex or snap.plateIndex or 0) or 0) end
        if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT and snap.plateText and snap.plateText ~= "" then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT(vehicle, tostring(snap.plateText)) end
        local smoke = snap.tyreSmokeColor or snap.tireSmoke
        if VEHICLE and VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR and type(smoke) == "table" then
            VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR(vehicle, tonumber(smoke.r or 255) or 255, tonumber(smoke.g or 255) or 255, tonumber(smoke.b or 255) or 255)
        end
        if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then VEHICLE.TOGGLE_VEHICLE_MOD(vehicle, 20, true) end
        table.insert(applied, "extras")
    end)

    return true, table.concat(applied, ",")
end

function driftgod.ApplyRecordedVehicleSnapshot(vehicle)
    driftgod.GhostVehicleFxEnsureDefaults()

    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 then return false end

    local snap = driftgod.S.ghostRecordedVehicleSnapshot
    if type(snap) ~= "table" then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("No CHERAX snapshot to apply | veh=" .. tostring(vehicle)) end
        return false
    end

    if driftgod.S.ghostRecordApplyVehicleMods ~= true then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("CHERAX snapshot apply skipped; toggle off") end
        return false
    end

    local ok, applied = driftgod.ApplyCheraxVehicleSnapshotToVehicle(vehicle, snap)

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Applied CHERAX vehicle snapshot | veh=" .. tostring(vehicle)
            .. " | ok=" .. tostring(ok)
            .. " | applied=" .. tostring(applied)
            .. " | primaryColor=" .. tostring(snap.primaryColor)
            .. " | secondaryColor=" .. tostring(snap.secondaryColor)
            .. " | pearl=" .. tostring(snap.pearlescentColor)
            .. " | wheelColor=" .. tostring(snap.wheelColor)
            .. " | customFlags=" .. tostring(snap.isPrimaryColorCustom) .. "/" .. tostring(snap.isSecondaryColorCustom)
            .. " | customPrimary=" .. tostring(snap.customPrimaryColor and (snap.customPrimaryColor.r .. "," .. snap.customPrimaryColor.g .. "," .. snap.customPrimaryColor.b) or "nil")
            .. " | customSecondary=" .. tostring(snap.customSecondaryColor and (snap.customSecondaryColor.r .. "," .. snap.customSecondaryColor.g .. "," .. snap.customSecondaryColor.b) or "nil")
            .. " | wheelType=" .. tostring(snap.wheelType)
            .. " | mod23=" .. tostring(snap.mods and snap.mods.mod23 and snap.mods.mod23.index or "nil"))
    end

    return ok == true
end

function driftgod.DebugRecordedVehicleSnapshot()
    driftgod.GhostVehicleFxEnsureDefaults()

    local snap = driftgod.S.ghostRecordedVehicleSnapshot
    if type(snap) ~= "table" then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("CHERAX vehicle snapshot debug: no snapshot captured") end
        return false
    end

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("CHERAX vehicle snapshot debug | model=" .. tostring(snap.model)
            .. " | primaryColor=" .. tostring(snap.primaryColor)
            .. " | secondaryColor=" .. tostring(snap.secondaryColor)
            .. " | pearl=" .. tostring(snap.pearlescentColor)
            .. " | wheelColor=" .. tostring(snap.wheelColor)
            .. " | isCustom=" .. tostring(snap.isPrimaryColorCustom) .. "/" .. tostring(snap.isSecondaryColorCustom)
            .. " | customPrimary=" .. tostring(snap.customPrimaryColor and (snap.customPrimaryColor.r .. "," .. snap.customPrimaryColor.g .. "," .. snap.customPrimaryColor.b) or "nil")
            .. " | customSecondary=" .. tostring(snap.customSecondaryColor and (snap.customSecondaryColor.r .. "," .. snap.customSecondaryColor.g .. "," .. snap.customSecondaryColor.b) or "nil")
            .. " | wheelType=" .. tostring(snap.wheelType)
            .. " | mod23=" .. tostring(snap.mods and snap.mods.mod23 and snap.mods.mod23.index or "nil")
            .. " | tyreSmoke=" .. tostring(snap.tyreSmokeColor and (snap.tyreSmokeColor.r .. "," .. snap.tyreSmokeColor.g .. "," .. snap.tyreSmokeColor.b) or "nil")
            .. " | plate=" .. tostring(snap.plateTextIndex) .. "/" .. tostring(snap.plateText))
    end

    return true
end

local DG_PreA3R3_BuildRecordedGhostJson = driftgod.BuildRecordedGhostJson
function driftgod.BuildRecordedGhostJson()

    return DG_PreA3R3_BuildRecordedGhostJson()
end

function driftgod.ValueFromSnapshot(snap, ...)
    if type(snap) ~= "table" then return nil end
    for _, key in ipairs({...}) do
        local v = snap[key]
        if v ~= nil then return v end
    end
    return nil
end

function driftgod.ModValueFromSnapshot(snap, modType)
    if type(snap) ~= "table" then return -1, false end
    local mods = snap.mods or snap.vehicleMods or snap.Mods
    if type(mods) ~= "table" then return -1, false end

    local item = mods[tostring(modType)] or mods["mod" .. tostring(modType)] or mods[modType]
    if type(item) == "table" then
        local idx = tonumber(item.index or item.modIndex or item.value or item[1] or -1) or -1
        local var = item.variation == true or item.customTires == true or item[2] == true
        return idx, var
    elseif item ~= nil then
        return tonumber(item) or -1, false
    end
    return -1, false
end

function driftgod.GetStrictWheelSnapshotValues(snap)
    snap = snap or {}
    local wheelType = tonumber(driftgod.ValueFromSnapshot(snap, "wheelType", "WheelType", "wheelsType") or 0) or 0

    local frontWheelMod = tonumber(driftgod.ValueFromSnapshot(snap, "wheelMod", "frontWheelMod", "frontWheels", "mod23") or -9999)
    local frontVar = snap.wheelVariation == true or snap.frontWheelVariation == true or snap.customTires == true
    if frontWheelMod == -9999 then
        frontWheelMod, frontVar = driftgod.ModValueFromSnapshot(snap, 23)
    end

    local rearWheelMod = tonumber(driftgod.ValueFromSnapshot(snap, "rearWheelMod", "rearWheels", "mod24") or -9999)
    local rearVar = snap.rearWheelVariation == true or snap.customRearTires == true
    if rearWheelMod == -9999 then
        rearWheelMod, rearVar = driftgod.ModValueFromSnapshot(snap, 24)
    end

    if rearWheelMod == -1 or rearWheelMod == -9999 then
        rearWheelMod = frontWheelMod
        rearVar = frontVar
    end

    local wheelColor = tonumber(driftgod.ValueFromSnapshot(snap, "wheelColor", "WheelColor", "rimColor") or 0) or 0
    local pearl = tonumber(driftgod.ValueFromSnapshot(snap, "pearlescent", "pearlescentColor", "pearlColor") or 0) or 0

    return {
        wheelType = wheelType,
        frontWheelMod = tonumber(frontWheelMod or -1) or -1,
        frontVar = frontVar == true,
        rearWheelMod = tonumber(rearWheelMod or -1) or -1,
        rearVar = rearVar == true,
        wheelColor = wheelColor,
        pearlescent = pearl,
    }
end

function driftgod.ApplyRecordedVehicleBaseColorsStrict(vehicle, snap)
    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 or type(snap) ~= "table" then return false end

    local primary = tonumber(driftgod.ValueFromSnapshot(snap, "primary", "primaryColor", "PrimaryColor") or 0) or 0
    local secondary = tonumber(driftgod.ValueFromSnapshot(snap, "secondary", "secondaryColor", "SecondaryColor") or 0) or 0
    local w = driftgod.GetStrictWheelSnapshotValues(snap)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then VEHICLE.SET_VEHICLE_COLOURS(vehicle, primary, secondary) end
        if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicle, w.pearlescent, w.wheelColor) end
    end)

    local hasCustomPrimary = snap.hasCustomPrimary == true or snap.isPrimaryColorCustom == true
    local hasCustomSecondary = snap.hasCustomSecondary == true or snap.isSecondaryColorCustom == true

    if hasCustomPrimary == true and type(snap.customPrimary or snap.customPrimaryColor) == "table" then
        local c = snap.customPrimary or snap.customPrimaryColor
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then
                VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle, c.r or c.R or c[1] or 0, c.g or c.G or c[2] or 0, c.b or c.B or c[3] or 0)
            end
        end)
    else
        driftgod.Try(function()
            if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle) end
        end)
    end

    if hasCustomSecondary == true and type(snap.customSecondary or snap.customSecondaryColor) == "table" then
        local c = snap.customSecondary or snap.customSecondaryColor
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then
                VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle, c.r or c.R or c[1] or 0, c.g or c.G or c[2] or 0, c.b or c.B or c[3] or 0)
            end
        end)
    else
        driftgod.Try(function()
            if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle) end
        end)
    end

    return true
end

function driftgod.ApplyStrictCheraxWheelOrder(vehicle, snap, stage)
    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 or type(snap) ~= "table" then return false end

    local w = driftgod.GetStrictWheelSnapshotValues(snap)
    local before23, before24, after23, after24 = -999, -999, -999, -999

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_MOD then
            before23 = tonumber(VEHICLE.GET_VEHICLE_MOD(vehicle, 23) or -999) or -999
            before24 = tonumber(VEHICLE.GET_VEHICLE_MOD(vehicle, 24) or -999) or -999
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then VEHICLE.SET_VEHICLE_MOD_KIT(vehicle, 0) end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then VEHICLE.SET_VEHICLE_WHEEL_TYPE(vehicle, w.wheelType) end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD then
            VEHICLE.SET_VEHICLE_MOD(vehicle, 23, w.frontWheelMod, w.frontVar)
            if w.rearWheelMod and w.rearWheelMod >= 0 then
                VEHICLE.SET_VEHICLE_MOD(vehicle, 24, w.rearWheelMod, w.rearVar)
            end
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then
            VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicle, w.pearlescent, w.wheelColor)
        end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_MOD then
            after23 = tonumber(VEHICLE.GET_VEHICLE_MOD(vehicle, 23) or -999) or -999
            after24 = tonumber(VEHICLE.GET_VEHICLE_MOD(vehicle, 24) or -999) or -999
        end
    end)

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("STRICT WHEEL APPLY | stage=" .. tostring(stage or "unknown")
            .. " | wheelType=" .. tostring(w.wheelType)
            .. " | front23=" .. tostring(w.frontWheelMod) .. " var=" .. tostring(w.frontVar)
            .. " | rear24=" .. tostring(w.rearWheelMod) .. " var=" .. tostring(w.rearVar)
            .. " | wheelColor=" .. tostring(w.wheelColor)
            .. " | pearl=" .. tostring(w.pearlescent)
            .. " | before23=" .. tostring(before23)
            .. " | after23=" .. tostring(after23)
            .. " | before24=" .. tostring(before24)
            .. " | after24=" .. tostring(after24))
    end

    return true
end

function driftgod.ApplyAllNonWheelModsStrict(vehicle, snap)
    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 or type(snap) ~= "table" then return false end

    local mods = snap.mods or snap.vehicleMods or snap.Mods
    if type(mods) ~= "table" then return false end

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then VEHICLE.SET_VEHICLE_MOD_KIT(vehicle, 0) end
    end)

    for k, v in pairs(mods) do
        local modType = tonumber(k) or tonumber(tostring(k):match("mod(%d+)"))
        if modType and modType ~= 20 and modType ~= 23 and modType ~= 24 then
            local idx, var = -1, false
            if type(v) == "table" then
                idx = tonumber(v.index or v.modIndex or v.value or v[1] or -1) or -1
                var = v.variation == true or v.customTires == true or v[2] == true
            else
                idx = tonumber(v) or -1
            end
            if idx >= 0 then
                driftgod.Try(function()
                    if VEHICLE and VEHICLE.SET_VEHICLE_MOD then VEHICLE.SET_VEHICLE_MOD(vehicle, modType, idx, var) end
                end)
            end
        end
    end

    return true
end

function driftgod.ApplyRecordedVehicleSnapshot(vehicle)
    driftgod.GhostVehicleFxEnsureDefaults()

    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 then return false end

    local snap = driftgod.S.ghostRecordedVehicleSnapshot
    if type(snap) ~= "table" then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("No recorded vehicle snapshot to apply | veh=" .. tostring(vehicle)) end
        return false
    end

    if driftgod.S.ghostRecordApplyVehicleMods ~= true then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Recorded vehicle snapshot apply skipped; toggle off") end
        return false
    end

    driftgod.ApplyRecordedVehicleBaseColorsStrict(vehicle, snap)
    driftgod.ApplyStrictCheraxWheelOrder(vehicle, snap, "pre-other-mods")
    driftgod.ApplyAllNonWheelModsStrict(vehicle, snap)
    driftgod.ApplyStrictCheraxWheelOrder(vehicle, snap, "post-other-mods-final")
    driftgod.ApplyRecordedVehicleBaseColorsStrict(vehicle, snap)

    driftgod.Try(function()
        if Script and Script.Yield then Script.Yield(20) end
    end)
    driftgod.ApplyStrictCheraxWheelOrder(vehicle, snap, "delayed-final")

    if driftgod.GhostReplayImportant then
        local w = driftgod.GetStrictWheelSnapshotValues(snap)
        driftgod.GhostReplayImportant("STRICT CHERAX SNAPSHOT COMPLETE | veh=" .. tostring(vehicle)
            .. " | wheelType=" .. tostring(w.wheelType)
            .. " | wheel23=" .. tostring(w.frontWheelMod)
            .. " | wheel24=" .. tostring(w.rearWheelMod)
            .. " | wheelColor=" .. tostring(w.wheelColor)
            .. " | primary=" .. tostring(driftgod.ValueFromSnapshot(snap, "primary", "primaryColor"))
            .. " | secondary=" .. tostring(driftgod.ValueFromSnapshot(snap, "secondary", "secondaryColor")))
    end

    return true
end

