function driftgod.GhostSavedRecordingEnsureDefaults()
    driftgod.GhostRecordingAlphaEnsureDefaults()

    driftgod.S.savedGhostRecordings = driftgod.S.savedGhostRecordings or {}
    driftgod.S.savedGhostRecordingIndex = tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1
    driftgod.S.savedGhostRecordingSelectedFile = tostring(driftgod.S.savedGhostRecordingSelectedFile or "")
    driftgod.S.savedGhostRecordingSelectedName = tostring(driftgod.S.savedGhostRecordingSelectedName or "")
    driftgod.S.savedGhostRecordingLoadStatus = tostring(driftgod.S.savedGhostRecordingLoadStatus or "Not loaded")
    driftgod.S.savedGhostRecordingScanStatus = tostring(driftgod.S.savedGhostRecordingScanStatus or "Not scanned")
end

function driftgod.ReadTextFile(path)
    local ok, result = driftgod.Try(function()
        local f = io.open(path, "r")
        if not f then return nil, "io.open read failed: " .. tostring(path) end
        local txt = f:read("*a")
        f:close()
        return txt, nil
    end)

    if not ok then return nil, tostring(result) end
    return result
end

function driftgod.ListJsonFilesInDirWindows(dir)
    dir = tostring(dir or "")
    if dir == "" then return {}, "empty dir" end

    local files = {}
    local cmd = 'dir /b "' .. dir .. '*.json"'
    local ok, pipe = driftgod.Try(function()
        return io.popen(cmd)
    end)

    if not ok or not pipe then
        return files, "io.popen failed"
    end

    for line in pipe:lines() do
        if line and line:lower():match("%.json$") then
            table.insert(files, line)
        end
    end

    driftgod.Try(function() pipe:close() end)
    table.sort(files)
    return files, nil
end

function driftgod.ScanSavedGhostRecordings()
    driftgod.GhostSavedRecordingEnsureDefaults()

    local dir = driftgod.GetGhostRecordingSaveDir and driftgod.GetGhostRecordingSaveDir() or "DriftGod\\arcade\\GhostReplay\\Recordings\\"
    local files, err = driftgod.ListJsonFilesInDirWindows(dir)

    driftgod.S.savedGhostRecordings = {}
    for _, fileName in ipairs(files or {}) do
        table.insert(driftgod.S.savedGhostRecordings, {
            file = fileName,
            path = dir .. fileName,
            name = fileName:gsub("%.json$", ""),
        })
    end

    if #driftgod.S.savedGhostRecordings <= 0 then
        driftgod.S.savedGhostRecordingIndex = 1
        driftgod.S.savedGhostRecordingSelectedFile = ""
        driftgod.S.savedGhostRecordingSelectedName = ""
        driftgod.S.savedGhostRecordingScanStatus = "No saved recordings found"
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Saved recording scan complete | count=0 | dir=" .. tostring(dir) .. " | err=" .. tostring(err))
        end
        return false
    end

    if driftgod.S.savedGhostRecordingIndex < 1 then driftgod.S.savedGhostRecordingIndex = 1 end
    if driftgod.S.savedGhostRecordingIndex > #driftgod.S.savedGhostRecordings then driftgod.S.savedGhostRecordingIndex = #driftgod.S.savedGhostRecordings end

    local selected = driftgod.S.savedGhostRecordings[driftgod.S.savedGhostRecordingIndex]
    driftgod.S.savedGhostRecordingSelectedFile = selected.file
    driftgod.S.savedGhostRecordingSelectedName = selected.name
    driftgod.S.savedGhostRecordingScanStatus = "Found " .. tostring(#driftgod.S.savedGhostRecordings) .. " recordings"

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Saved recording scan complete | count=" .. tostring(#driftgod.S.savedGhostRecordings)
            .. " | selected=" .. tostring(selected.file)
            .. " | dir=" .. tostring(dir))
    end

    return true
end

function driftgod.GetSelectedSavedGhostRecording()
    driftgod.GhostSavedRecordingEnsureDefaults()

    local list = driftgod.S.savedGhostRecordings or {}
    if #list <= 0 then
        driftgod.ScanSavedGhostRecordings()
        list = driftgod.S.savedGhostRecordings or {}
    end

    if #list <= 0 then return nil, 0 end

    local idx = tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1
    if idx < 1 then idx = 1 end
    if idx > #list then idx = #list end
    driftgod.S.savedGhostRecordingIndex = idx

    local item = list[idx]
    if item then
        driftgod.S.savedGhostRecordingSelectedFile = item.file or ""
        driftgod.S.savedGhostRecordingSelectedName = item.name or ""
    end

    return item, idx
end

function driftgod.NextSavedGhostRecording()
    driftgod.GhostSavedRecordingEnsureDefaults()
    if #(driftgod.S.savedGhostRecordings or {}) <= 0 then driftgod.ScanSavedGhostRecordings() end

    local count = #(driftgod.S.savedGhostRecordings or {})
    if count <= 0 then return false end

    driftgod.S.savedGhostRecordingIndex = (tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1) + 1
    if driftgod.S.savedGhostRecordingIndex > count then driftgod.S.savedGhostRecordingIndex = 1 end

    local item = driftgod.S.savedGhostRecordings[driftgod.S.savedGhostRecordingIndex]
    if item and driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Selected saved recording next | " .. tostring(driftgod.S.savedGhostRecordingIndex) .. "/" .. tostring(count)
            .. " | file=" .. tostring(item.file))
    end

    return true
end

function driftgod.PreviousSavedGhostRecording()
    driftgod.GhostSavedRecordingEnsureDefaults()
    if #(driftgod.S.savedGhostRecordings or {}) <= 0 then driftgod.ScanSavedGhostRecordings() end

    local count = #(driftgod.S.savedGhostRecordings or {})
    if count <= 0 then return false end

    driftgod.S.savedGhostRecordingIndex = (tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1) - 1
    if driftgod.S.savedGhostRecordingIndex < 1 then driftgod.S.savedGhostRecordingIndex = count end

    local item = driftgod.S.savedGhostRecordings[driftgod.S.savedGhostRecordingIndex]
    if item and driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Selected saved recording previous | " .. tostring(driftgod.S.savedGhostRecordingIndex) .. "/" .. tostring(count)
            .. " | file=" .. tostring(item.file))
    end

    return true
end

function driftgod.ParseRecordedGhostJsonNodes(jsonText)
    jsonText = tostring(jsonText or "")
    local nodes = {}

    for time, x, y, z, pitch, roll, yaw, heading, speed in jsonText:gmatch(
        '"Time"%s*:%s*([%-%.%d]+)%s*,%s*"Position"%s*:%s*{%s*"X"%s*:%s*([%-%.%d]+)%s*,%s*"Y"%s*:%s*([%-%.%d]+)%s*,%s*"Z"%s*:%s*([%-%.%d]+)%s*}%s*,%s*"Rotation"%s*:%s*{%s*"X"%s*:%s*([%-%.%d]+)%s*,%s*"Y"%s*:%s*([%-%.%d]+)%s*,%s*"Z"%s*:%s*([%-%.%d]+)%s*}%s*,%s*"Heading"%s*:%s*([%-%.%d]+)%s*,%s*"Speed"%s*:%s*([%-%.%d]+)'
    ) do
        table.insert(nodes, {
            t = tonumber(time) or 0,
            x = tonumber(x) or 0,
            y = tonumber(y) or 0,
            z = tonumber(z) or 72,
            pitch = tonumber(pitch) or 0,
            roll = tonumber(roll) or 0,
            yaw = tonumber(yaw) or tonumber(heading) or 0,
            heading = tonumber(heading) or tonumber(yaw) or 0,
            speed = tonumber(speed) or 0,
        })
    end

    if #nodes <= 0 then
        for time, x, y, z, pitch, roll, yaw, heading in jsonText:gmatch(
            '"Time"%s*:%s*([%-%.%d]+)%s*,%s*"Position"%s*:%s*{%s*"X"%s*:%s*([%-%.%d]+)%s*,%s*"Y"%s*:%s*([%-%.%d]+)%s*,%s*"Z"%s*:%s*([%-%.%d]+)%s*}%s*,%s*"Rotation"%s*:%s*{%s*"X"%s*:%s*([%-%.%d]+)%s*,%s*"Y"%s*:%s*([%-%.%d]+)%s*,%s*"Z"%s*:%s*([%-%.%d]+)%s*}%s*,%s*"Heading"%s*:%s*([%-%.%d]+)'
        ) do
            table.insert(nodes, {
                t = tonumber(time) or 0,
                x = tonumber(x) or 0,
                y = tonumber(y) or 0,
                z = tonumber(z) or 72,
                pitch = tonumber(pitch) or 0,
                roll = tonumber(roll) or 0,
                yaw = tonumber(yaw) or tonumber(heading) or 0,
                heading = tonumber(heading) or tonumber(yaw) or 0,
                speed = 0,
            })
        end
    end

    return nodes
end

function driftgod.ParseRecordedGhostJsonMeta(jsonText)
    jsonText = tostring(jsonText or "")

    local meta = {
        name = jsonText:match('"Name"%s*:%s*"([^"]+)"') or "Saved Recording",
        track = jsonText:match('"Track"%s*:%s*"([^"]+)"') or "DriftGod Recorded",
        vehicleModel = tonumber(jsonText:match('"VehicleModel"%s*:%s*([%-%.%d]+)') or 0) or 0,
        nodeCount = tonumber(jsonText:match('"NodeCount"%s*:%s*(%d+)') or 0) or 0,
        timestamp = jsonText:match('"Timestamp"%s*:%s*"([^"]+)"') or "",
    }

    return meta
end

function driftgod.LoadSelectedSavedGhostRecording()
    driftgod.GhostSavedRecordingEnsureDefaults()

    local item, idx = driftgod.GetSelectedSavedGhostRecording()
    if not item then
        driftgod.S.savedGhostRecordingLoadStatus = "No selected saved recording"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Load saved recording failed: no selection") end
        return false
    end

    local txt, err = driftgod.ReadTextFile(item.path)
    if not txt then
        driftgod.S.savedGhostRecordingLoadStatus = "Read failed"
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Load saved recording failed | file=" .. tostring(item.path) .. " | err=" .. tostring(err))
        end
        return false
    end

    local nodes = driftgod.ParseRecordedGhostJsonNodes(txt)
    local meta = driftgod.ParseRecordedGhostJsonMeta(txt)

    if #nodes <= 1 then
        driftgod.S.savedGhostRecordingLoadStatus = "Parse failed: no nodes"
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Load saved recording parse failed | file=" .. tostring(item.path) .. " | nodes=" .. tostring(#nodes))
        end
        return false
    end

    driftgod.S.ghostRecordingNodes = nodes
    driftgod.S.ghostRecordingNodeCount = #nodes
    driftgod.S.ghostRecordingActive = false
    driftgod.S.ghostRecordingStatus = "Loaded Saved Recording"
    driftgod.S.ghostRecordingFileName = tostring(meta.name or item.name or "Saved Recording")
    driftgod.S.ghostRecordingVehicleModel = tonumber(meta.vehicleModel or 0) or 0
    driftgod.S.ghostRecordingVehicle = 0

    driftgod.S.savedGhostRecordingLoadStatus = "Loaded " .. tostring(#nodes) .. " nodes"
    driftgod.S.savedGhostRecordingSelectedFile = item.file
    driftgod.S.savedGhostRecordingSelectedName = meta.name or item.name

    if driftgod.ClearGhostPreviewTrackingOnly then
        driftgod.ClearGhostPreviewTrackingOnly()
    end

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Saved recording loaded | idx=" .. tostring(idx)
            .. " | file=" .. tostring(item.file)
            .. " | name=" .. tostring(meta.name)
            .. " | nodes=" .. tostring(#nodes)
            .. " | model=" .. tostring(meta.vehicleModel))
    end

    return true
end

