function driftgod.WriteTextFile(path, text)
    local ok, err = driftgod.Try(function()
        local f = io.open(path, "w")
        if not f then error("io.open write failed: " .. tostring(path)) end
        f:write(tostring(text or ""))
        f:close()
    end)
    if not ok then return false, tostring(err) end
    return true, nil
end

function driftgod.AppendTextFile(path, text)
    local ok, err = driftgod.Try(function()
        local f = io.open(path, "a")
        if not f then error("io.open append failed: " .. tostring(path)) end
        f:write(tostring(text or ""))
        f:close()
    end)
    if not ok then return false, tostring(err) end
    return true, nil
end

function driftgod.ReadTextFileSafe(path)
    local ok, txt, err = driftgod.Try(function()
        local f = io.open(path, "r")
        if not f then return nil, "io.open read failed: " .. tostring(path) end
        local t = f:read("*a")
        f:close()
        return t, nil
    end)
    if not ok then return nil, tostring(txt) end
    return txt, err
end

function driftgod.GetSavedGhostIndexPath()
    local dir = driftgod.GetGhostRecordingSaveDir and driftgod.GetGhostRecordingSaveDir() or "DriftGod\\arcade\\GhostReplay\\Recordings\\"
    return dir .. "_recordings_index.lua"
end

function driftgod.GetLastSavedGhostPathFile()
    local dir = driftgod.GetGhostRecordingSaveDir and driftgod.GetGhostRecordingSaveDir() or "DriftGod\\arcade\\GhostReplay\\Recordings\\"
    return dir .. "_last_saved.txt"
end

function driftgod.RegisterSavedGhostRecording(path, fileName)
    path = tostring(path or "")
    fileName = tostring(fileName or "")
    if path == "" then return false end
    if fileName == "" then fileName = path:match("([^\\]+)$") or path end

    local lastPathFile = driftgod.GetLastSavedGhostPathFile()
    local indexPath = driftgod.GetSavedGhostIndexPath()

    driftgod.WriteTextFile(lastPathFile, path)

    local escapedPath = path:gsub("\\", "\\\\"):gsub('"', '\\"')
    local escapedFile = fileName:gsub("\\", "\\\\"):gsub('"', '\\"')
    local line = '{ file="' .. escapedFile .. '", path="' .. escapedPath .. '", name="' .. escapedFile:gsub("%.json$", "") .. '" },\n'

    driftgod.AppendTextFile(indexPath, line)

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Registered saved ghost recording | file=" .. tostring(fileName)
            .. " | path=" .. tostring(path)
            .. " | index=" .. tostring(indexPath))
    end

    return true
end

local DG_Pre62R1_SaveRecordedGhostJson = driftgod.SaveRecordedGhostJson
function driftgod.SaveRecordedGhostJson()
    local ok = false
    local result = false

    driftgod.Try(function()
        if DG_Pre62R1_SaveRecordedGhostJson then
            result = DG_Pre62R1_SaveRecordedGhostJson()
            ok = result == true
        end
    end)

    if ok == true then
        local path = tostring(driftgod.S.ghostRecordingLastSavePath or "")
        local file = path:match("([^\\]+)$") or path
        driftgod.RegisterSavedGhostRecording(path, file)
        return true
    end

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("SaveRecordedGhostJson previous save did not return true; status=" .. tostring(driftgod.S.ghostRecordingLastSaveStatus))
    end

    return false
end

function driftgod.ScanSavedGhostRecordingsFromIndex()
    driftgod.GhostSavedRecordingEnsureDefaults()

    local indexPath = driftgod.GetSavedGhostIndexPath()
    local txt, err = driftgod.ReadTextFileSafe(indexPath)
    local found = {}

    if txt and txt ~= "" then
        for file, path, name in txt:gmatch('{%s*file="([^"]-)"%s*,%s*path="([^"]-)"%s*,%s*name="([^"]-)"%s*}') do
            path = path:gsub("\\\\", "\\")
            table.insert(found, { file = file, path = path, name = name })
        end
    end

    local lastPathTxt = driftgod.ReadTextFileSafe(driftgod.GetLastSavedGhostPathFile())
    if lastPathTxt and lastPathTxt ~= "" then
        local path = tostring(lastPathTxt):gsub("[\r\n]", "")
        local file = path:match("([^\\]+)$") or path
        local duplicate = false
        for _, item in ipairs(found) do
            if item.path == path then duplicate = true end
        end
        if not duplicate then
            table.insert(found, { file = file, path = path, name = file:gsub("%.json$", "") })
        end
    end

    if #found > 0 then
        driftgod.S.savedGhostRecordings = found
        driftgod.S.savedGhostRecordingIndex = math.max(1, math.min(tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1, #found))

        local item = found[driftgod.S.savedGhostRecordingIndex]
        driftgod.S.savedGhostRecordingSelectedFile = item.file
        driftgod.S.savedGhostRecordingSelectedName = item.name
        driftgod.S.savedGhostRecordingScanStatus = "Index fallback found " .. tostring(#found)

        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Saved recording index fallback scan complete | count=" .. tostring(#found)
                .. " | indexPath=" .. tostring(indexPath))
        end

        return true
    end

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Saved recording index fallback scan found none | indexPath=" .. tostring(indexPath)
            .. " | err=" .. tostring(err))
    end

    return false
end

local DG_Pre62R1_ScanSavedGhostRecordings = driftgod.ScanSavedGhostRecordings
function driftgod.ScanSavedGhostRecordings()
    driftgod.GhostSavedRecordingEnsureDefaults()

    local ok = false
    driftgod.Try(function()
        if DG_Pre62R1_ScanSavedGhostRecordings then
            ok = DG_Pre62R1_ScanSavedGhostRecordings() == true
        end
    end)

    if ok == true and #(driftgod.S.savedGhostRecordings or {}) > 0 then
        return true
    end

    driftgod.S.savedGhostRecordingScanStatus = "Dir scan failed/empty; trying index fallback"
    return driftgod.ScanSavedGhostRecordingsFromIndex()
end

function driftgod.LoadSavedGhostRecordingFromPath(path)
    driftgod.GhostSavedRecordingEnsureDefaults()

    path = tostring(path or "")
    path = path:gsub("[\r\n]", "")

    if path == "" then
        driftgod.S.savedGhostRecordingLoadStatus = "No path"
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Load saved recording from path failed: empty path") end
        return false
    end

    local txt, err = driftgod.ReadTextFileSafe(path)
    if not txt then
        driftgod.S.savedGhostRecordingLoadStatus = "Read failed"
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Load saved recording from path failed | path=" .. tostring(path) .. " | err=" .. tostring(err))
        end
        return false
    end

    local nodes = driftgod.ParseRecordedGhostJsonNodes and driftgod.ParseRecordedGhostJsonNodes(txt) or {}
    local meta = driftgod.ParseRecordedGhostJsonMeta and driftgod.ParseRecordedGhostJsonMeta(txt) or { name = path:match("([^\\]+)$") or "Saved Recording", vehicleModel = 0 }

    if #nodes <= 1 then
        driftgod.S.savedGhostRecordingLoadStatus = "Parse failed: no nodes"
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Load saved recording parse failed | path=" .. tostring(path) .. " | nodes=" .. tostring(#nodes))
        end
        return false
    end

    driftgod.S.ghostRecordingNodes = nodes
    driftgod.S.ghostRecordingNodeCount = #nodes
    driftgod.S.ghostRecordingActive = false
    driftgod.S.ghostRecordingStatus = "Loaded Saved Recording"
    driftgod.S.ghostRecordingFileName = tostring(meta.name or "Saved Recording")
    driftgod.S.ghostRecordingVehicleModel = tonumber(meta.vehicleModel or 0) or 0
    driftgod.S.ghostRecordingVehicle = 0

    driftgod.S.savedGhostRecordingLoadStatus = "Loaded " .. tostring(#nodes) .. " nodes"
    driftgod.S.savedGhostRecordingSelectedFile = path:match("([^\\]+)$") or path
    driftgod.S.savedGhostRecordingSelectedName = tostring(meta.name or driftgod.S.savedGhostRecordingSelectedFile)

    if driftgod.ClearGhostPreviewTrackingOnly then driftgod.ClearGhostPreviewTrackingOnly() end

    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Saved recording loaded from path | file=" .. tostring(driftgod.S.savedGhostRecordingSelectedFile)
            .. " | name=" .. tostring(driftgod.S.savedGhostRecordingSelectedName)
            .. " | nodes=" .. tostring(#nodes)
            .. " | model=" .. tostring(driftgod.S.ghostRecordingVehicleModel)
            .. " | path=" .. tostring(path))
    end

    return true
end

function driftgod.LoadLastSavedGhostRecording()
    local lastPathFile = driftgod.GetLastSavedGhostPathFile()
    local path, err = driftgod.ReadTextFileSafe(lastPathFile)

    if not path or path == "" then
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Load last saved recording failed | lastPathFile=" .. tostring(lastPathFile)
                .. " | err=" .. tostring(err))
        end
        return false
    end

    return driftgod.LoadSavedGhostRecordingFromPath(path)
end

function driftgod.PlayLastSavedGhostRecording()
    local ok = driftgod.LoadLastSavedGhostRecording()
    if ok ~= true then return false end

    if driftgod.PlayRecordedGhostSmooth then return driftgod.PlayRecordedGhostSmooth() end
    if driftgod.PlayRecordedGhostInMemory then return driftgod.PlayRecordedGhostInMemory() end
    return false
end

