function driftgod.GhostSimpleFlowEnsureDefaults()
    if driftgod.GhostSavedRecordingEnsureDefaults then driftgod.GhostSavedRecordingEnsureDefaults()
    elseif driftgod.GhostRecordingAlphaEnsureDefaults then driftgod.GhostRecordingAlphaEnsureDefaults()
    elseif driftgod.GhostRecordingEnsureDefaults then driftgod.GhostRecordingEnsureDefaults() end

    driftgod.S.ghostRecordedSmoothSteps = tonumber(driftgod.S.ghostRecordedSmoothSteps or 2) or 2
    if driftgod.S.ghostRecordedSmoothSteps < 1 then driftgod.S.ghostRecordedSmoothSteps = 2 end

    driftgod.S.ghostSimpleRecordDurationSec = tonumber(driftgod.S.ghostSimpleRecordDurationSec or 60) or 60
    if driftgod.S.ghostSimpleRecordDurationSec < 10 then driftgod.S.ghostSimpleRecordDurationSec = 10 end
    if driftgod.S.ghostSimpleRecordDurationSec > 300 then driftgod.S.ghostSimpleRecordDurationSec = 300 end

    driftgod.S.ghostSimpleRecordingOwner = tostring(driftgod.S.ghostSimpleRecordingOwner or "Self")
    driftgod.S.ghostSimpleFlowStatus = tostring(driftgod.S.ghostSimpleFlowStatus or "Ready")
end

function driftgod.SetGhostSimpleRecordingOwnerSelf()
    driftgod.GhostSimpleFlowEnsureDefaults()
    driftgod.S.ghostSimpleRecordingOwner = "Self"
    driftgod.S.ghostSimpleFlowStatus = "Recording as Self"
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Ghost recording owner set: Self") end
    return true
end

function driftgod.SetGhostSimpleRecordingOwnerRivalPlaceholder()
    driftgod.GhostSimpleFlowEnsureDefaults()
    driftgod.S.ghostSimpleRecordingOwner = "Rival Placeholder"
    driftgod.S.ghostSimpleFlowStatus = "Rival naming placeholder"
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Ghost recording owner set: Rival Placeholder") end
    return true
end

function driftgod.GhostSimpleDurationMinus()
    driftgod.GhostSimpleFlowEnsureDefaults()
    driftgod.S.ghostSimpleRecordDurationSec = math.max(10, (tonumber(driftgod.S.ghostSimpleRecordDurationSec or 60) or 60) - 10)
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Ghost simple duration set: " .. tostring(driftgod.S.ghostSimpleRecordDurationSec) .. "s") end
    return true
end

function driftgod.GhostSimpleDurationPlus()
    driftgod.GhostSimpleFlowEnsureDefaults()
    driftgod.S.ghostSimpleRecordDurationSec = math.min(300, (tonumber(driftgod.S.ghostSimpleRecordDurationSec or 60) or 60) + 10)
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Ghost simple duration set: " .. tostring(driftgod.S.ghostSimpleRecordDurationSec) .. "s") end
    return true
end

function driftgod.RecordGhostSimple()
    driftgod.GhostSimpleFlowEnsureDefaults()

    local owner = driftgod.S.ghostSimpleRecordingOwner or "Self"
    local stamp = tostring(os.date and os.date("%Y%m%d_%H%M%S") or "Run")
    if driftgod.SetGhostRecordingFileName then
        driftgod.SetGhostRecordingFileName("DG_" .. owner .. "_" .. stamp)
    end

    driftgod.S.ghostRecordedSmoothSteps = 2
    driftgod.S.ghostSimpleFlowStatus = "Recording Ghost"

    if driftgod.RecordGhostTimed then
        return driftgod.RecordGhostTimed(driftgod.S.ghostSimpleRecordDurationSec or 60, 25)
    end

    if driftgod.StartGhostRecording then
        return driftgod.StartGhostRecording()
    end

    return false
end

function driftgod.StopGhostSimpleRecording()
    driftgod.GhostSimpleFlowEnsureDefaults()
    driftgod.S.ghostSimpleFlowStatus = "Recording Stopped"

    if driftgod.StopGhostRecording then
        return driftgod.StopGhostRecording()
    end

    driftgod.S.ghostRecordingActive = false
    return true
end

function driftgod.PlayCurrentGhostRecordingSimple()
    driftgod.GhostSimpleFlowEnsureDefaults()
    driftgod.S.ghostRecordedSmoothSteps = 2
    driftgod.S.ghostSimpleFlowStatus = "Playing Current Recording"

    if driftgod.PlayRecordedGhostSmooth then return driftgod.PlayRecordedGhostSmooth() end
    if driftgod.PlayRecordedGhostInMemory then return driftgod.PlayRecordedGhostInMemory() end
    return false
end

