function driftgod.SaveCurrentGhostRecordingSimple()
    driftgod.GhostSimpleFlowEnsureDefaults()
    driftgod.S.ghostSimpleFlowStatus = "Saving Current Recording"

    if driftgod.SaveRecordedGhostJson then
        local ok = driftgod.SaveRecordedGhostJson()
        if ok == true then
            driftgod.S.ghostSimpleFlowStatus = "Saved Recording"
            if driftgod.ScanSavedGhostRecordings then driftgod.ScanSavedGhostRecordings() end
        else
            driftgod.S.ghostSimpleFlowStatus = "Save Failed"
        end
        return ok
    end

    return false
end

function driftgod.GetSavedRecordingComboPreview()
    driftgod.GhostSavedRecordingEnsureDefaults()
    local list = driftgod.S.savedGhostRecordings or {}
    local idx = tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1
    if #list <= 0 then return "No saved recordings" end
    if idx < 1 then idx = 1 end
    if idx > #list then idx = #list end
    local item = list[idx]
    if not item then return "No saved recordings" end
    return tostring(item.name or item.file or "Saved Recording")
end

function driftgod.SetSavedRecordingIndex(index)
    driftgod.GhostSavedRecordingEnsureDefaults()
    local list = driftgod.S.savedGhostRecordings or {}
    if #list <= 0 then return false end

    index = tonumber(index or 1) or 1
    if index < 1 then index = 1 end
    if index > #list then index = #list end

    driftgod.S.savedGhostRecordingIndex = index
    local item = list[index]
    if item then
        driftgod.S.savedGhostRecordingSelectedFile = item.file or ""
        driftgod.S.savedGhostRecordingSelectedName = item.name or item.file or ""
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("Saved recording selected | " .. tostring(index) .. "/" .. tostring(#list)
                .. " | file=" .. tostring(item.file))
        end
    end
    return true
end

