    driftgod.S.driftChallengeCheckpointDiameter = tonumber(driftgod.S.driftChallengeCheckpointDiameter or 20.0) or 20.0
    if driftgod.S.driftChallengeCheckpointDiameter < 20.0 then driftgod.S.driftChallengeCheckpointDiameter = 20.0 end
    driftgod.S.driftChallengeHudLastDrawMs = tonumber(driftgod.S.driftChallengeHudLastDrawMs or -1) or -1
