function driftgod.GetVectorPartsSafe(v)
    if not v then return nil end
    local x, y, z = nil, nil, nil
    driftgod.Try(function() x = tonumber(v.x or v.X) end)
    driftgod.Try(function() y = tonumber(v.y or v.Y) end)
    driftgod.Try(function() z = tonumber(v.z or v.Z) end)
    if not x then driftgod.Try(function() x = tonumber(v[1]) end) end
    if not y then driftgod.Try(function() y = tonumber(v[2]) end) end
    if not z then driftgod.Try(function() z = tonumber(v[3]) end) end
    if x and y then return x, y, z or 0.0 end
    return nil
end

function driftgod.GetDriftChallengePlayerPosition()
    local source = "none"

    local okObj, xObj, yObj, zObj = driftgod.Try(function()
        local obj = nil
        if GTA and GTA.GetLocalVehicle then obj = GTA.GetLocalVehicle() end
        if not obj and GTA and GTA.GetLocalPed then obj = GTA.GetLocalPed() end
        if obj and obj.Position then
            local x, y, z = driftgod.GetVectorPartsSafe(obj.Position)
            if x and y then return x, y, z or 0.0 end
        end
        return nil
    end)
    if okObj and xObj and yObj then
        driftgod.S.driftChallengePositionDebug = "CEntity.Position x=" .. tostring(math.floor(xObj)) .. " y=" .. tostring(math.floor(yObj))
        return xObj, yObj, zObj or 0.0
    end

    local veh = 0
    if driftgod.GetPlayerVehicleForGhostRecording then veh = tonumber(driftgod.GetPlayerVehicleForGhostRecording() or 0) or 0 end
    if veh ~= 0 and driftgod.GetEntityCoordsForRecording then
        local okWrap, x, y, z = driftgod.Try(function() return driftgod.GetEntityCoordsForRecording(veh) end)
        if okWrap and tonumber(x) and tonumber(y) then
            driftgod.S.driftChallengePositionDebug = "DG wrapper veh=" .. tostring(veh) .. " x=" .. tostring(math.floor(tonumber(x))) .. " y=" .. tostring(math.floor(tonumber(y)))
            return tonumber(x) or 0.0, tonumber(y) or 0.0, tonumber(z) or 0.0
        end
    end

    if Natives and Natives.InvokeInt and Natives.InvokeV3 then
        local ped = 0
        driftgod.Try(function() ped = tonumber(Natives.InvokeInt(0xD80958FC74E988A6) or 0) or 0 end)
        if ped ~= 0 then
            driftgod.Try(function() veh = tonumber(Natives.InvokeInt(0x9A9112A0FE9A4713, ped, false) or 0) or 0 end)
            local ent = veh ~= 0 and veh or ped
            local okNative, c = driftgod.Try(function()
                local raw = Natives.InvokeV3(0x3FEF770D40960D5A, ent, true)
                if V3 and V3.New then
                    local okV3, vv = driftgod.Try(function() return V3.New(raw) end)
                    if okV3 and vv then return vv end
                end
                return raw
            end)
            if okNative and c then
                local x, y, z = driftgod.GetVectorPartsSafe(c)
                if x and y then
                    driftgod.S.driftChallengePositionDebug = "Native ent=" .. tostring(ent) .. " x=" .. tostring(math.floor(x)) .. " y=" .. tostring(math.floor(y))
                    return x, y, z or 0.0
                end
            end
        end
    end

    driftgod.S.driftChallengePositionDebug = "Position failed"
    return nil
end

function driftgod.CreateDriftChallengeNativeCheckpointForIndex(index)
    driftgod.DriftChallengeA6EnsureDefaults()
    if driftgod.S.driftChallengeCheckpointMarkerEnabled == false then return false end

    index = tonumber(index or driftgod.S.driftChallengeCheckpointIndex or 1) or 1
    local cps = driftgod.S.ghostRecordingCheckpoints or {}
    local cp = cps[index]
    if type(cp) ~= "table" then
        if driftgod.DeleteDriftChallengeNativeCheckpoint then driftgod.DeleteDriftChallengeNativeCheckpoint("missing checkpoint") end
        return false
    end

    if driftgod.DeleteDriftChallengeNativeCheckpoint then driftgod.DeleteDriftChallengeNativeCheckpoint("replace A6") end
    if not Natives or not Natives.InvokeInt then return false end

    local nextCp = cps[index + 1] or cp
    local isFinal = index >= #cps
    local checkpointType = tonumber(driftgod.S.driftChallengeCheckpointTestType or 0) or 0
    local diameter = tonumber(driftgod.S.driftChallengeCheckpointDiameter or 20.0) or 20.0
    local r,g,b,a = 255, 220, 45, 230
    if isFinal then r,g,b,a = 120,255,180,235 end

    local handle = 0
    driftgod.Try(function()
        handle = tonumber(Natives.InvokeInt(0x0134F0835AB6BFCB,
            checkpointType,
            (tonumber(cp.x or 0) or 0) + 0.0,
            (tonumber(cp.y or 0) or 0) + 0.0,
            (tonumber(cp.z or 0) or 0) - 0.05,
            (tonumber(nextCp.x or cp.x or 0) or 0) + 0.0,
            (tonumber(nextCp.y or cp.y or 0) or 0) + 0.0,
            (tonumber(nextCp.z or cp.z or 0) or 0) - 0.05,
            diameter + 0.0,
            r, g, b, a,
            0
        ) or 0) or 0
    end)

    if handle ~= 0 and Natives.InvokeVoid then
        driftgod.Try(function() Natives.InvokeVoid(0x2707AAE9D9297D89, handle, 8.0, 8.0, 85.0) end)
        driftgod.Try(function() Natives.InvokeVoid(0x7167371E8AD747F7, handle, r, g, b, a) end)
        driftgod.Try(function() Natives.InvokeVoid(0xB9EA40907C680580, handle, r, g, b, 255) end)
        driftgod.Try(function() Natives.InvokeVoid(0x4B5B4DA5D79F1943, handle, 1.0) end)
        driftgod.Try(function() Natives.InvokeVoid(0x3C788E7F6438754D, handle,
            (tonumber(nextCp.x or cp.x or 0) or 0) + 0.0,
            (tonumber(nextCp.y or cp.y or 0) or 0) + 0.0,
            (tonumber(nextCp.z or cp.z or 0) or 0) - 0.05
        ) end)
    end

    driftgod.S.driftChallengeNativeCheckpointHandle = handle
    driftgod.S.driftChallengeNativeCheckpointIndex = handle ~= 0 and index or 0
    if handle ~= 0 and driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Native race checkpoint created A6 | idx=" .. tostring(index)
            .. "/" .. tostring(#cps)
            .. " | type=" .. tostring(checkpointType)
            .. " | label=" .. tostring(driftgod.S.driftChallengeCheckpointTestLabel)
            .. " | handle=" .. tostring(handle))
    end
    return handle ~= 0
end

function driftgod.DriftChallengeDistanceToCheckpoint(cp)
    if type(cp) ~= "table" then return 999999.0 end
    local x,y,z = driftgod.GetDriftChallengePlayerPosition and driftgod.GetDriftChallengePlayerPosition() or nil
    if not x then return 999999.0 end
    local dx = x - (tonumber(cp.x or 0) or 0)
    local dy = y - (tonumber(cp.y or 0) or 0)
    local dist = math.sqrt(dx*dx + dy*dy)
    driftgod.S.driftChallengeLastDistanceFloat = dist
    return dist
end

function driftgod.TickDriftChallengeRace()
    driftgod.DriftChallengeA6EnsureDefaults()
    local now = driftgod.DriftChallengeNowMs()

    if driftgod.S.driftChallengeCountdownActive == true then
        if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(false) end
        local elapsed = now - (tonumber(driftgod.S.driftChallengeCountdownStartMs or now) or now)
        if elapsed >= (tonumber(driftgod.S.driftChallengeCountdownDurationMs or 4200) or 4200) then
            driftgod.ActivateDriftChallengeRace()
        end
    end

    if driftgod.S.driftChallengeActive == true then
        driftgod.S.driftChallengeLivePoints = driftgod.GetDriftChallengeLiveScore and driftgod.GetDriftChallengeLiveScore() or 0
        driftgod.S.driftChallengeLiveStunts = driftgod.GetDriftChallengeLiveStunts and driftgod.GetDriftChallengeLiveStunts() or 0

        local checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
        if #checkpoints <= 0 and driftgod.BuildAutoDriftChallengeCheckpointsFromNodes then
            driftgod.BuildAutoDriftChallengeCheckpointsFromNodes()
            checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
            if driftgod.CreateDriftChallengeCheckpointBlips then driftgod.CreateDriftChallengeCheckpointBlips() end
        end

        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        local radius = tonumber(driftgod.S.driftChallengeCheckpointRadius or 55.0) or 55.0
        local nextCp = checkpoints[idx]
        if nextCp then
            if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(false) end
            local dist = driftgod.DriftChallengeDistanceToCheckpoint(nextCp)
            driftgod.S.driftChallengeNextCheckpointDistance = math.floor(dist)
            if dist <= radius then
                driftgod.S.driftChallengeCheckpointIndex = idx + 1
                driftgod.S.driftChallengeStatus = "Checkpoint " .. tostring(idx) .. " cleared"
                if driftgod.DeleteDriftChallengeNativeCheckpoint then driftgod.DeleteDriftChallengeNativeCheckpoint("checkpoint cleared A6") end
                if driftgod.AddBonusPopup then driftgod.AddBonusPopup("CHECKPOINT " .. tostring(idx), 255, 230, 80) end
                if driftgod.UpdateDriftChallengeRouteBlip then driftgod.UpdateDriftChallengeRouteBlip() end
                if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(true) end
                if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Drift Challenge checkpoint cleared A6 | idx=" .. tostring(idx) .. " | dist=" .. tostring(math.floor(dist)) .. " | radius=" .. tostring(radius)) end
            end
        elseif #checkpoints > 0 then
            driftgod.FinishDriftChallengeRace("all checkpoints cleared")
        end
    end

    return true
end

function driftgod.DrawDriftChallengeHud()
    if not driftgod.DrawText then return false end
    driftgod.DriftChallengeA6EnsureDefaults()
    local now = driftgod.DriftChallengeNowMs()
    if tonumber(driftgod.S.driftChallengeHudLastDrawMs or -1) == tonumber(now or -2) then return true end
    driftgod.S.driftChallengeHudLastDrawMs = now

    if driftgod.S.driftChallengeCountdownActive == true then
        local txt = driftgod.GetDriftChallengeCountdownText and driftgod.GetDriftChallengeCountdownText() or ""
        if txt ~= "" then
            local size = txt == "GO!" and 1.18 or 1.42
            local r,g,b = 255,255,255
            if txt == "GO!" then r,g,b = 120,255,180 end
            driftgod.DrawText(txt, 0.50, 0.36, size, r,g,b,255,7)
        end
    end

    if driftgod.S.driftChallengeActive == true then
        local checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        driftgod.S.driftChallengeLivePoints = driftgod.GetDriftChallengeLiveScore and driftgod.GetDriftChallengeLiveScore() or (driftgod.S.driftChallengeLivePoints or 0)
        driftgod.S.driftChallengeLiveStunts = driftgod.GetDriftChallengeLiveStunts and driftgod.GetDriftChallengeLiveStunts() or (driftgod.S.driftChallengeLiveStunts or 0)

        driftgod.DrawText("SCORE", 0.425, 0.078, 0.270, 166,94,252,235,7)
        driftgod.DrawText(tostring(driftgod.S.driftChallengeLivePoints or 0) .. " / " .. tostring(driftgod.S.driftChallengeTargetPoints or 0), 0.540, 0.078, 0.305, 255,255,255,235,7)
        driftgod.DrawText("STUNTS " .. tostring(driftgod.S.driftChallengeLiveStunts or 0) .. " / " .. tostring(driftgod.S.driftChallengeTargetStunts or 0), 0.50, 0.113, 0.235, 255,255,255,210,4)
        driftgod.DrawText("TYPE " .. tostring(driftgod.S.driftChallengeCheckpointTestType or 0) .. "  " .. tostring(driftgod.S.driftChallengeCheckpointTestLabel or ""), 0.50, 0.142, 0.200, 255,230,80,225,4)

        if #checkpoints > 0 then
            driftgod.DrawText("CHECKPOINT " .. tostring(math.min(idx, #checkpoints)) .. " / " .. tostring(#checkpoints)
                .. "   DIST " .. tostring(driftgod.S.driftChallengeNextCheckpointDistance or "--")
                .. "   R " .. tostring(math.floor(tonumber(driftgod.S.driftChallengeCheckpointRadius or 0) or 0)), 0.50, 0.168, 0.215, 255,230,80,230,4)
        else
            driftgod.DrawText("NO CHECKPOINTS FOUND", 0.50, 0.168, 0.235, 255,90,90,230,4)
        end
    end

    if (tonumber(driftgod.S.driftChallengeResultVisibleUntil or 0) or 0) > now then
        local result = driftgod.S.driftChallengeLastResult or {}
        local start = tonumber(driftgod.S.driftChallengeResultStartMs or now) or now
        local elapsed = now - start
        local slideX = 0.5
        if elapsed < 500 then slideX = -0.35 + (elapsed / 500.0) * 0.85 end
        if elapsed > 8200 then slideX = 0.5 + ((elapsed - 8200) / 800.0) * 0.85 end

        if elapsed < 2600 then
            if result.won == true then
                driftgod.DrawText("You Won!", slideX, 0.345, 0.86, 120,255,180,255,7)
            else
                driftgod.DrawText("You Failed!", slideX, 0.345, 0.86, 255,70,70,255,7)
            end
        else
            driftgod.DrawText("RIVAL", slideX - 0.070, 0.310, 0.390, 166,94,252,255,7)
            driftgod.DrawText(tostring(result.rival or driftgod.S.driftChallengeRivalName or "Rival"), slideX + 0.070, 0.310, 0.390, 255,255,255,255,7)
            driftgod.DrawText("Drifting Points:", slideX - 0.055, 0.365, 0.34, 255,255,255,245,4)
            driftgod.DrawText(tostring(result.points or 0), slideX + 0.120, 0.365, 0.34, 166,94,252,245,4)
            driftgod.DrawText("Number of Stunts:", slideX - 0.055, 0.405, 0.34, 255,255,255,245,4)
            driftgod.DrawText(tostring(result.stunts or 0), slideX + 0.120, 0.405, 0.34, 166,94,252,245,4)
            driftgod.DrawText(tostring(result.phrase or ""), slideX, 0.475, 0.285, 255,255,255,220,4)
        end
    end
    return true
end

function driftgod.DriftChallengeA7EnsureDefaults()
    if driftgod.DriftChallengeA6EnsureDefaults then driftgod.DriftChallengeA6EnsureDefaults()
    elseif driftgod.DriftChallengeA5EnsureDefaults then driftgod.DriftChallengeA5EnsureDefaults()
    elseif driftgod.DriftChallengeEnsureDefaults then driftgod.DriftChallengeEnsureDefaults() end
    driftgod.S.driftChallengeCheckpointRadius = tonumber(driftgod.S.driftChallengeCheckpointRadius or 70.0) or 70.0
    if driftgod.S.driftChallengeCheckpointRadius < 70.0 then driftgod.S.driftChallengeCheckpointRadius = 70.0 end
    driftgod.S.driftChallengeNativeHitRadius = tonumber(driftgod.S.driftChallengeNativeHitRadius or 85.0) or 85.0
    if driftgod.S.driftChallengeNativeHitRadius < 70.0 then driftgod.S.driftChallengeNativeHitRadius = 85.0 end
    driftgod.S.driftChallengeDrawNativeHud = false
    driftgod.S.driftChallengeHudPresentRegistered = driftgod.S.driftChallengeHudPresentRegistered == true
    driftgod.S.driftChallengeLastHitSource = tostring(driftgod.S.driftChallengeLastHitSource or "none")
end

function driftgod.GetLocalPedHandleA7()
    local ped = 0
    driftgod.Try(function()
        if PLAYER and PLAYER.PLAYER_PED_ID then ped = tonumber(PLAYER.PLAYER_PED_ID() or 0) or 0 end
    end)
    if ped ~= 0 then return ped end
    driftgod.Try(function() if Natives and Natives.InvokeInt then ped = tonumber(Natives.InvokeInt(0xD80958FC74E988A6) or 0) or 0 end end)
    if ped ~= 0 then return ped end
    driftgod.Try(function()
        if GTA and GTA.GetLocalPed and GTA.PointerToHandle and CPed and CPed.FromAddress then
            local p = GTA.GetLocalPed()
            if p and p.GetAddress then ped = tonumber(GTA.PointerToHandle(CPed.FromAddress(p:GetAddress())) or 0) or 0 end
        end
    end)
    return tonumber(ped or 0) or 0
end

function driftgod.GetLocalVehicleHandleA7()
    local veh = 0
    driftgod.Try(function()
        if GTA and GTA.GetLocalVehicle and GTA.PointerToHandle and CVehicle and CVehicle.FromAddress then
            local v = GTA.GetLocalVehicle()
            if v and v.GetAddress then veh = tonumber(GTA.PointerToHandle(CVehicle.FromAddress(v:GetAddress())) or 0) or 0 end
        end
    end)
    if veh ~= 0 then return veh end
    driftgod.Try(function() if driftgod.GetPlayerVehicleForGhostRecording then veh = tonumber(driftgod.GetPlayerVehicleForGhostRecording() or 0) or 0 end end)
    if veh ~= 0 then return veh end
    local ped = driftgod.GetLocalPedHandleA7 and driftgod.GetLocalPedHandleA7() or 0
    if ped ~= 0 then
        driftgod.Try(function()
            if PED and PED.GET_VEHICLE_PED_IS_IN then veh = tonumber(PED.GET_VEHICLE_PED_IS_IN(ped, false) or 0) or 0 end
        end)
        if veh ~= 0 then return veh end
        driftgod.Try(function() if Natives and Natives.InvokeInt then veh = tonumber(Natives.InvokeInt(0x9A9112A0FE9A4713, ped, false) or 0) or 0 end end)
    end
    return tonumber(veh or 0) or 0
end

function driftgod.GetDriftChallengeEntityForHitTestA7()
    local veh = driftgod.GetLocalVehicleHandleA7 and driftgod.GetLocalVehicleHandleA7() or 0
    if veh ~= 0 then return veh, "vehicle" end
    local ped = driftgod.GetLocalPedHandleA7 and driftgod.GetLocalPedHandleA7() or 0
    if ped ~= 0 then return ped, "ped" end
    return 0, "none"
end

function driftgod.IsDriftChallengeEntityAtCheckpointA7(cp)
    if type(cp) ~= "table" or not Natives or not Natives.InvokeBool then return false end
    local ent, source = driftgod.GetDriftChallengeEntityForHitTestA7()
    if not ent or ent == 0 then
        driftgod.S.driftChallengeLastHitSource = "no entity"
        return false
    end
    local r = tonumber(driftgod.S.driftChallengeNativeHitRadius or driftgod.S.driftChallengeCheckpointRadius or 85.0) or 85.0
    local x = tonumber(cp.x or 0) or 0
    local y = tonumber(cp.y or 0) or 0
    local z = tonumber(cp.z or 0) or 0
    local hit = false
    driftgod.Try(function()
        hit = Natives.InvokeBool(0x20B711662962B472, ent, x + 0.0, y + 0.0, z + 0.0, r + 0.0, r + 0.0, 18.0, false, true, 0) == true
    end)
    driftgod.S.driftChallengeLastHitSource = tostring(source) .. " nativeHit=" .. tostring(hit) .. " r=" .. tostring(math.floor(r))
    return hit == true
end

function driftgod.GetDriftChallengePlayerPosition()
    local obj = nil
    driftgod.Try(function() if GTA and GTA.GetLocalVehicle then obj = GTA.GetLocalVehicle() end end)
    if not obj then driftgod.Try(function() if GTA and GTA.GetLocalPed then obj = GTA.GetLocalPed() end end) end
    if obj and obj.Position and driftgod.GetVectorPartsSafe then
        local x,y,z = driftgod.GetVectorPartsSafe(obj.Position)
        if x and y then
            driftgod.S.driftChallengePositionDebug = "A7 CEntity.Position x=" .. tostring(math.floor(x)) .. " y=" .. tostring(math.floor(y))
            return x,y,z or 0.0
        end
    end

    local ent, source = driftgod.GetDriftChallengeEntityForHitTestA7()
    if ent ~= 0 then

        if driftgod.GetEntityCoordsForRecording then
            local ok, x, y, z = driftgod.Try(function() return driftgod.GetEntityCoordsForRecording(ent) end)
            if ok and tonumber(x) and tonumber(y) and not (tonumber(x) == 0 and tonumber(y) == 0) then
                driftgod.S.driftChallengePositionDebug = "A7 wrapper " .. tostring(source) .. " x=" .. tostring(math.floor(tonumber(x))) .. " y=" .. tostring(math.floor(tonumber(y)))
                return tonumber(x), tonumber(y), tonumber(z) or 0.0
            end
        end

        if Natives and Natives.InvokeV3 and driftgod.GetVectorPartsSafe then
            local ok, raw = driftgod.Try(function() return Natives.InvokeV3(0x3FEF770D40960D5A, ent, true) end)
            if ok and raw then
                local x,y,z = driftgod.GetVectorPartsSafe(raw)
                if x and y then
                    driftgod.S.driftChallengePositionDebug = "A7 native " .. tostring(source) .. " x=" .. tostring(math.floor(x)) .. " y=" .. tostring(math.floor(y))
                    return x,y,z or 0.0
                end
            end
        end
    end

    driftgod.S.driftChallengePositionDebug = "A7 Position failed | " .. tostring(driftgod.S.driftChallengeLastHitSource or "no hit source")
    return nil
end

function driftgod.ClearCurrentDriftChallengeCheckpointA7(reason)
    driftgod.DriftChallengeA7EnsureDefaults()
    local cps = driftgod.S.ghostRecordingCheckpoints or {}
    local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
    if idx > #cps then return false end
    driftgod.S.driftChallengeCheckpointIndex = idx + 1
    driftgod.S.driftChallengeStatus = "Checkpoint " .. tostring(idx) .. " cleared" .. (reason and (" | " .. tostring(reason)) or "")
    if driftgod.DeleteDriftChallengeNativeCheckpoint then driftgod.DeleteDriftChallengeNativeCheckpoint("checkpoint cleared A7") end
    if driftgod.AddBonusPopup then driftgod.AddBonusPopup("CHECKPOINT " .. tostring(idx), 255, 230, 80) end
    if driftgod.UpdateDriftChallengeRouteBlip then driftgod.UpdateDriftChallengeRouteBlip() end
    if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(true) end
    if idx >= #cps and #cps > 0 then

        driftgod.S.driftChallengeStatus = "Final checkpoint cleared"
    end
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Drift Challenge checkpoint cleared A7 | idx=" .. tostring(idx) .. " | reason=" .. tostring(reason or "unknown")) end
    return true
end

function driftgod.SafeForceClearCurrentCheckpointButton()
    local ok, result = driftgod.Try(function() return driftgod.ClearCurrentDriftChallengeCheckpointA7("manual force") end)
    if not ok and driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Force clear checkpoint error: " .. tostring(result)) end
    return ok and result == true
end

function driftgod.SafeDriftCheckpointType3Button() return driftgod.SetDriftChallengeCheckpointType(3, "Type 3 Ring / Alternate") end

function driftgod.TickDriftChallengeRace()
    driftgod.DriftChallengeA7EnsureDefaults()
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0

    if driftgod.S.driftChallengeCountdownActive == true then
        if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(false) end
        local elapsed = now - (tonumber(driftgod.S.driftChallengeCountdownStartMs or now) or now)
        if elapsed >= (tonumber(driftgod.S.driftChallengeCountdownDurationMs or 4200) or 4200) then
            driftgod.ActivateDriftChallengeRace()
        end
    end

    if driftgod.S.driftChallengeActive == true then
        driftgod.S.driftChallengeLivePoints = driftgod.GetDriftChallengeLiveScore and driftgod.GetDriftChallengeLiveScore() or 0
        driftgod.S.driftChallengeLiveStunts = driftgod.GetDriftChallengeLiveStunts and driftgod.GetDriftChallengeLiveStunts() or 0

        local checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
        if #checkpoints <= 0 and driftgod.BuildAutoDriftChallengeCheckpointsFromNodes then
            driftgod.BuildAutoDriftChallengeCheckpointsFromNodes()
            checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
            if driftgod.CreateDriftChallengeCheckpointBlips then driftgod.CreateDriftChallengeCheckpointBlips() end
        end

        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        local nextCp = checkpoints[idx]
        if nextCp then
            if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(false) end
            local nativeHit = driftgod.IsDriftChallengeEntityAtCheckpointA7 and driftgod.IsDriftChallengeEntityAtCheckpointA7(nextCp) or false
            local dist = driftgod.DriftChallengeDistanceToCheckpoint and driftgod.DriftChallengeDistanceToCheckpoint(nextCp) or 999999.0
            driftgod.S.driftChallengeNextCheckpointDistance = math.floor(tonumber(dist or 999999) or 999999)
            local radius = tonumber(driftgod.S.driftChallengeCheckpointRadius or 70.0) or 70.0
            if nativeHit == true or (tonumber(dist or 999999) or 999999) <= radius then
                driftgod.ClearCurrentDriftChallengeCheckpointA7(nativeHit and "native hit" or ("distance " .. tostring(math.floor(dist))))
            end
        elseif #checkpoints > 0 then
            driftgod.FinishDriftChallengeRace("all checkpoints cleared")
        end
    end

    return true
end

function driftgod.DrawDriftChallengeHud()
    driftgod.DriftChallengeA7EnsureDefaults()
    if driftgod.S.driftChallengeDrawNativeHud == true then

        return true
    end
    return true
end

function driftgod.PresentAddTextA7(x, y, r, g, b, a, text)
    if not ImGui then return false end
    text = tostring(text or "")
    local ok = false
    driftgod.Try(function()
        if ImGui.FgAddText then ImGui.FgAddText(x, y, r, g, b, a, text); ok = true
        elseif ImGui.BgAddText then ImGui.BgAddText(x, y, r, g, b, a, text); ok = true end
    end)
    return ok
end

function driftgod.DrawDriftChallengeHudOnPresent()
    if not DG or not driftgod.S then return end
    if driftgod.S.driftChallengeCountdownActive ~= true and driftgod.S.driftChallengeActive ~= true and not ((tonumber(driftgod.S.driftChallengeResultVisibleUntil or 0) or 0) > (driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0)) then return end
    local sw, sh = 1920, 1080
    driftgod.Try(function()
        if ImGui and ImGui.GetDisplaySize then
            local w,h = ImGui.GetDisplaySize()
            if w and h and w > 0 and h > 0 then sw, sh = w, h end
        end
    end)
    local cx = sw * 0.5
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0

    if driftgod.S.driftChallengeCountdownActive == true then
        local txt = driftgod.GetDriftChallengeCountdownText and driftgod.GetDriftChallengeCountdownText() or ""
        if txt ~= "" then
            local scale = txt == "GO!" and 94 or 112
            local width = string.len(txt) * (txt == "GO!" and 38 or 44)
            local r,g,b = 255,255,255
            if txt == "GO!" then r,g,b = 120,255,180 end
            driftgod.PresentAddTextA7(cx - (width / 2), sh * 0.34, r,g,b,255,txt)
        end
    end

    if driftgod.S.driftChallengeActive == true then
        local cps = driftgod.S.ghostRecordingCheckpoints or {}
        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        local score = tostring(driftgod.S.driftChallengeLivePoints or 0) .. " / " .. tostring(driftgod.S.driftChallengeTargetPoints or 0)
        local stunts = "STUNTS " .. tostring(driftgod.S.driftChallengeLiveStunts or 0) .. " / " .. tostring(driftgod.S.driftChallengeTargetStunts or 0)
        local cp = "CHECKPOINT " .. tostring(math.min(idx, math.max(#cps, 1))) .. " / " .. tostring(#cps) .. "   DIST " .. tostring(driftgod.S.driftChallengeNextCheckpointDistance or "--")
        driftgod.PresentAddTextA7(cx - 190, sh * 0.075, 166,94,252,240, "SCORE")
        driftgod.PresentAddTextA7(cx - 55, sh * 0.075, 255,255,255,240, score)
        driftgod.PresentAddTextA7(cx - 115, sh * 0.108, 255,255,255,220, stunts)
        driftgod.PresentAddTextA7(cx - 180, sh * 0.138, 255,230,80,230, cp)
        driftgod.PresentAddTextA7(cx - 180, sh * 0.164, 180,180,180,190, tostring(driftgod.S.driftChallengeLastHitSource or "hit: none"))
    end

    if (tonumber(driftgod.S.driftChallengeResultVisibleUntil or 0) or 0) > now then
        local result = driftgod.S.driftChallengeLastResult or {}
        local start = tonumber(driftgod.S.driftChallengeResultStartMs or now) or now
        local elapsed = now - start
        local slideX = cx
        if elapsed < 500 then slideX = -sw * 0.35 + (elapsed / 500.0) * (sw * 0.85) end
        if elapsed > 8200 then slideX = cx + ((elapsed - 8200) / 800.0) * (sw * 0.85) end
        if elapsed < 2600 then
            local msg = result.won == true and "You Won!" or "You Failed!"
            local r,g,b = result.won == true and 120 or 255, result.won == true and 255 or 70, result.won == true and 180 or 70
            driftgod.PresentAddTextA7(slideX - 170, sh * 0.33, r,g,b,255,msg)
        else
            driftgod.PresentAddTextA7(slideX - 150, sh * 0.30, 166,94,252,255,"RIVAL")
            driftgod.PresentAddTextA7(slideX - 35, sh * 0.30, 255,255,255,255,tostring(result.rival or driftgod.S.driftChallengeRivalName or "Rival"))
            driftgod.PresentAddTextA7(slideX - 165, sh * 0.36, 255,255,255,245,"Drifting Points:")
            driftgod.PresentAddTextA7(slideX + 90, sh * 0.36, 166,94,252,245,tostring(result.points or 0))
            driftgod.PresentAddTextA7(slideX - 165, sh * 0.405, 255,255,255,245,"Number of Stunts:")
            driftgod.PresentAddTextA7(slideX + 90, sh * 0.405, 166,94,252,245,tostring(result.stunts or 0))
            driftgod.PresentAddTextA7(slideX - 220, sh * 0.475, 255,255,255,220,tostring(result.phrase or ""))
        end
    end
end

function driftgod.RegisterDriftChallengeHudOnPresentA7()
    if driftgod.S and driftgod.S.driftChallengeHudPresentRegistered == true then return true end
    driftgod.S = driftgod.S or {}
    driftgod.S.driftChallengeHudPresentRegistered = true
    if EventMgr and eLuaEvent and eLuaEvent.ON_PRESENT then
        EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
            driftgod.Try(function() if DG and driftgod.DrawDriftChallengeHudOnPresent then driftgod.DrawDriftChallengeHudOnPresent() end end)
        end)
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Drift Challenge ON_PRESENT HUD registered A7") end
        return true
    end
    driftgod.S.driftChallengeDrawNativeHud = true
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("ON_PRESENT missing; race HUD native fallback enabled A7") end
    return false
end

driftgod.Try(function() driftgod.RegisterDriftChallengeHudOnPresentA7() end)

function driftgod.DriftChallengeA8EnsureDefaults()
    if driftgod.DriftChallengeA7EnsureDefaults then driftgod.DriftChallengeA7EnsureDefaults()
    elseif driftgod.DriftChallengeA6EnsureDefaults then driftgod.DriftChallengeA6EnsureDefaults()
    elseif driftgod.DriftChallengeEnsureDefaults then driftgod.DriftChallengeEnsureDefaults() end
    driftgod.S.driftChallengeCheckpointRadius = tonumber(driftgod.S.driftChallengeCheckpointRadius or 90.0) or 90.0
    if driftgod.S.driftChallengeCheckpointRadius < 90.0 then driftgod.S.driftChallengeCheckpointRadius = 90.0 end
    driftgod.S.driftChallengeNativeHitRadius = tonumber(driftgod.S.driftChallengeNativeHitRadius or 90.0) or 90.0
    if driftgod.S.driftChallengeNativeHitRadius < 90.0 then driftgod.S.driftChallengeNativeHitRadius = 90.0 end
    driftgod.S.driftChallengeA8LastCoordSource = tostring(driftgod.S.driftChallengeA8LastCoordSource or "none")
    driftgod.S.driftChallengeResultForceNativeDraw = true
end

function driftgod.GetVectorPartsA8(v, yArg, zArg)

    if tonumber(v) and tonumber(yArg) then
        return tonumber(v) or 0.0, tonumber(yArg) or 0.0, tonumber(zArg) or 0.0
    end

    if not v then return nil end
    local x, y, z = nil, nil, nil
    driftgod.Try(function() x = tonumber(v.x or v.X) end)
    driftgod.Try(function() y = tonumber(v.y or v.Y) end)
    driftgod.Try(function() z = tonumber(v.z or v.Z) end)
    if not x then driftgod.Try(function() x = tonumber(v[1]) end) end
    if not y then driftgod.Try(function() y = tonumber(v[2]) end) end
    if not z then driftgod.Try(function() z = tonumber(v[3]) end) end
    if x and y then return x, y, z or 0.0 end
    return nil
end

function driftgod.GetLocalPedHandleA8()
    local ped = 0
    driftgod.Try(function() if PLAYER and PLAYER.PLAYER_PED_ID then ped = tonumber(PLAYER.PLAYER_PED_ID() or 0) or 0 end end)
    if ped ~= 0 then return ped, "PLAYER.PLAYER_PED_ID" end
    driftgod.Try(function() if Natives and Natives.InvokeInt then ped = tonumber(Natives.InvokeInt(0xD80958FC74E988A6) or 0) or 0 end end)
    if ped ~= 0 then return ped, "native PLAYER_PED_ID D809" end
    driftgod.Try(function() if Natives and Natives.InvokeInt then ped = tonumber(Natives.InvokeInt(0x43A66C31C68491C0) or 0) or 0 end end)
    if ped ~= 0 then return ped, "native PLAYER_PED_ID 43A" end
    driftgod.Try(function()
        if GTA and GTA.GetLocalPed and GTA.PointerToHandle then
            local p = GTA.GetLocalPed()
            if p and p.GetAddress and CPed and CPed.FromAddress then
                ped = tonumber(GTA.PointerToHandle(CPed.FromAddress(p:GetAddress())) or 0) or 0
            elseif p then
                ped = tonumber(GTA.PointerToHandle(p) or 0) or 0
            end
        end
    end)
    if ped ~= 0 then return ped, "GTA.GetLocalPed handle" end
    return 0, "no ped"
end

function driftgod.GetLocalVehicleHandleA8()
    local veh = 0

    driftgod.Try(function() if driftgod.GetPlayerVehicleForGhostRecording then veh = tonumber(driftgod.GetPlayerVehicleForGhostRecording() or 0) or 0 end end)
    if veh ~= 0 then return veh, "driftgod.GetPlayerVehicleForGhostRecording" end

    local ped, pedSource = driftgod.GetLocalPedHandleA8()
    if ped ~= 0 then
        driftgod.Try(function() if PED and PED.GET_VEHICLE_PED_IS_IN then veh = tonumber(PED.GET_VEHICLE_PED_IS_IN(ped, false) or 0) or 0 end end)
        if veh ~= 0 then return veh, "PED.GET_VEHICLE_PED_IS_IN " .. tostring(pedSource) end
        driftgod.Try(function() if Natives and Natives.InvokeInt then veh = tonumber(Natives.InvokeInt(0x9A9112A0FE9A4713, ped, false) or 0) or 0 end end)
        if veh ~= 0 then return veh, "native GET_VEHICLE_PED_IS_IN " .. tostring(pedSource) end
    end

    driftgod.Try(function()
        if GTA and GTA.GetLocalVehicle and GTA.PointerToHandle then
            local v = GTA.GetLocalVehicle()
            if v and v.GetAddress and CVehicle and CVehicle.FromAddress then
                veh = tonumber(GTA.PointerToHandle(CVehicle.FromAddress(v:GetAddress())) or 0) or 0
            elseif v then
                veh = tonumber(GTA.PointerToHandle(v) or 0) or 0
            end
        end
    end)
    if veh ~= 0 then return veh, "GTA.GetLocalVehicle handle" end
    return 0, "no vehicle"
end

function driftgod.GetEntityCoordsA8(ent)
    ent = tonumber(ent or 0) or 0
    if ent == 0 then return nil end

    if driftgod.GetEntityCoordsForRecording then
        local ok, x, y, z = driftgod.Try(function() return driftgod.GetEntityCoordsForRecording(ent) end)
        if ok and tonumber(x) and tonumber(y) and not (math.abs(tonumber(x) or 0) < 0.001 and math.abs(tonumber(y) or 0) < 0.001) then
            return tonumber(x), tonumber(y), tonumber(z) or 0.0, "driftgod.GetEntityCoordsForRecording"
        end
    end

    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_COORDS then
            local c = ENTITY.GET_ENTITY_COORDS(ent, true)
            local x,y,z = driftgod.GetVectorPartsA8(c)
            if x and y then error({x=x,y=y,z=z,src="ENTITY.GET_ENTITY_COORDS wrapper"}) end
        end
    end)

    local okWrap, cWrap = driftgod.Try(function() if ENTITY and ENTITY.GET_ENTITY_COORDS then return ENTITY.GET_ENTITY_COORDS(ent, true) end end)
    if okWrap and cWrap then
        local x,y,z = driftgod.GetVectorPartsA8(cWrap)
        if x and y then return x,y,z or 0.0,"ENTITY.GET_ENTITY_COORDS wrapper" end
    end

    if Natives and Natives.InvokeV3 then
        local ok, xOrV, y, z = driftgod.Try(Natives.InvokeV3, 0x3FEF770D40960D5A, ent, true)
        if ok then
            local x1,y1,z1 = driftgod.GetVectorPartsA8(xOrV, y, z)
            if x1 and y1 then return x1,y1,z1 or 0.0,"Natives.InvokeV3 x/y/z" end
            if V3 and V3.New then
                local okV, vv = driftgod.Try(function() return V3.New(xOrV) end)
                if okV and vv then
                    local x2,y2,z2 = driftgod.GetVectorPartsA8(vv)
                    if x2 and y2 then return x2,y2,z2 or 0.0,"V3.New(native)" end
                end
            end
        end
    end
    return nil
end

function driftgod.GetDriftChallengePlayerPosition()
    driftgod.DriftChallengeA8EnsureDefaults()

    local veh, vehSource = driftgod.GetLocalVehicleHandleA8()
    if veh ~= 0 then
        local x,y,z,src = driftgod.GetEntityCoordsA8(veh)
        if x and y then
            driftgod.S.driftChallengeA8LastCoordSource = tostring(src) .. " | veh " .. tostring(vehSource)
            driftgod.S.driftChallengePositionDebug = "A8 VEH x=" .. tostring(math.floor(x)) .. " y=" .. tostring(math.floor(y)) .. " | " .. tostring(vehSource)
            return x,y,z or 0.0
        end
    end

    local ped, pedSource = driftgod.GetLocalPedHandleA8()
    if ped ~= 0 then
        local x,y,z,src = driftgod.GetEntityCoordsA8(ped)
        if x and y then
            driftgod.S.driftChallengeA8LastCoordSource = tostring(src) .. " | ped " .. tostring(pedSource)
            driftgod.S.driftChallengePositionDebug = "A8 PED x=" .. tostring(math.floor(x)) .. " y=" .. tostring(math.floor(y)) .. " | " .. tostring(pedSource)
            return x,y,z or 0.0
        end
    end

    driftgod.S.driftChallengeA8LastCoordSource = "failed veh=" .. tostring(vehSource) .. " ped=" .. tostring(pedSource)
    driftgod.S.driftChallengePositionDebug = "A8 Position failed | " .. tostring(driftgod.S.driftChallengeA8LastCoordSource)
    return nil
end

function driftgod.DriftChallengeDistanceToCheckpoint(cp)
    if type(cp) ~= "table" then return 999999.0 end
    local x,y,z = driftgod.GetDriftChallengePlayerPosition()
    if not x then
        driftgod.S.driftChallengeNextCheckpointDistance = 999999
        return 999999.0
    end
    local dx = x - (tonumber(cp.x or 0) or 0)
    local dy = y - (tonumber(cp.y or 0) or 0)
    local dz = (z or 0) - (tonumber(cp.z or 0) or 0)
    local dist2d = math.sqrt(dx*dx + dy*dy)
    local dist3d = math.sqrt(dx*dx + dy*dy + dz*dz)
    driftgod.S.driftChallengeLastDistanceFloat = dist2d
    driftgod.S.driftChallengeLastDistance3DFloat = dist3d
    driftgod.S.driftChallengeLastDeltaDebug = "dx=" .. tostring(math.floor(dx)) .. " dy=" .. tostring(math.floor(dy)) .. " dz=" .. tostring(math.floor(dz))
    return dist2d
end

function driftgod.GetDriftChallengeLiveScore()
    local cur = tonumber(driftgod.S.currentScore or driftgod.S.score or driftgod.S.driftScore or driftgod.S.runScore or 0) or 0
    local start = tonumber(driftgod.S.driftChallengeStartScore or 0) or 0
    return math.max(0, math.floor(cur - start))
end

function driftgod.GetDriftChallengeLiveStunts()
    local cur = tonumber(driftgod.S.landedStuntsThisRun or driftgod.S.stuntsLandedThisRun or driftgod.S.stuntCount or 0) or 0
    local start = tonumber(driftgod.S.driftChallengeStartStunts or 0) or 0
    return math.max(0, math.floor(cur - start))
end

function driftgod.MakeDriftChallengeResultA8(reason)
    driftgod.DriftChallengeA8EnsureDefaults()
    local points = driftgod.GetDriftChallengeLiveScore and driftgod.GetDriftChallengeLiveScore() or tonumber(driftgod.S.driftChallengeLivePoints or 0) or 0
    local stunts = driftgod.GetDriftChallengeLiveStunts and driftgod.GetDriftChallengeLiveStunts() or tonumber(driftgod.S.driftChallengeLiveStunts or 0) or 0
    local targetPoints = tonumber(driftgod.S.driftChallengeTargetPoints or 0) or 0
    local targetStunts = tonumber(driftgod.S.driftChallengeTargetStunts or 0) or 0
    local cps = driftgod.S.ghostRecordingCheckpoints or {}
    local cleared = math.max(0, math.min(#cps, (tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1) - 1))
    local won = false
    if targetPoints > 0 then won = points > targetPoints else won = points > 0 end
    if #cps > 0 and cleared < #cps and tostring(reason or "") ~= "manual" then won = false end
    return {
        rival = tostring(driftgod.S.driftChallengeRivalName or "Rival"),
        won = won,
        points = math.floor(points),
        targetPoints = math.floor(targetPoints),
        stunts = math.floor(stunts),
        targetStunts = math.floor(targetStunts),
        checkpoints = cleared,
        phrase = driftgod.GetDriftChallengePhrase and driftgod.GetDriftChallengePhrase(won) or "",
        reason = tostring(reason or "complete"),
        date = tostring(os.date and os.date("%Y-%m-%d %H:%M:%S") or "")
    }
end

function driftgod.ShowDriftChallengeResultA8(reason)
    driftgod.DriftChallengeA8EnsureDefaults()
    local result = driftgod.MakeDriftChallengeResultA8(reason)
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    driftgod.S.driftChallengeLastResult = result
    driftgod.S.driftChallengeActive = false
    driftgod.S.driftChallengeCountdownActive = false
    driftgod.S.driftChallengeStatus = result.won and "You Won" or "You Failed"
    driftgod.S.driftChallengeResultPhase = 1
    driftgod.S.driftChallengeResultStartMs = now
    driftgod.S.driftChallengeResultVisibleUntil = now + 12000
    driftgod.S.driftChallengeResultForceNativeDraw = true
    if driftgod.DeleteDriftChallengeNativeCheckpoint then driftgod.DeleteDriftChallengeNativeCheckpoint("result A8") end
    if driftgod.WriteDriftChallengeResultLog then driftgod.Try(function() driftgod.WriteDriftChallengeResultLog(result) end) end
    if driftgod.ClearDriftChallengeCheckpointBlips then driftgod.Try(function() driftgod.ClearDriftChallengeCheckpointBlips("result A8") end) end
    driftgod.Try(function()
        if GUI and GUI.AddToast then
            GUI.AddToast("Drift Challenge", result.won and "You Won!" or "You Failed!", 5000, eToastPos and eToastPos.TOP_RIGHT or nil)
        end
    end)
    if driftgod.AddBonusPopup then driftgod.Try(function() driftgod.AddBonusPopup(result.won and "YOU WON!" or "YOU FAILED!", result.won and 120 or 255, result.won and 255 or 70, result.won and 180 or 70) end) end
    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Drift Challenge result A8 | won=" .. tostring(result.won)
            .. " | points=" .. tostring(result.points) .. "/" .. tostring(result.targetPoints)
            .. " | stunts=" .. tostring(result.stunts) .. "/" .. tostring(result.targetStunts)
            .. " | checkpoints=" .. tostring(result.checkpoints)
            .. " | reason=" .. tostring(reason))
    end
    return true
end

function driftgod.FinishDriftChallengeRace(reason)
    return driftgod.ShowDriftChallengeResultA8(reason or "manual") == true
end

function driftgod.ClearCurrentDriftChallengeCheckpointA7(reason)
    driftgod.DriftChallengeA8EnsureDefaults()
    local cps = driftgod.S.ghostRecordingCheckpoints or {}
    local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
    if #cps <= 0 then return false end
    if idx > #cps then
        return driftgod.ShowDriftChallengeResultA8(reason or "already complete") == true
    end
    driftgod.S.driftChallengeCheckpointIndex = idx + 1
    driftgod.S.driftChallengeStatus = "Checkpoint " .. tostring(idx) .. " cleared" .. (reason and (" | " .. tostring(reason)) or "")
    if driftgod.DeleteDriftChallengeNativeCheckpoint then driftgod.DeleteDriftChallengeNativeCheckpoint("checkpoint cleared A8") end
    if driftgod.AddBonusPopup then driftgod.AddBonusPopup("CHECKPOINT " .. tostring(idx), 255, 230, 80) end
    if driftgod.UpdateDriftChallengeRouteBlip then driftgod.UpdateDriftChallengeRouteBlip() end
    if idx >= #cps then
        return driftgod.ShowDriftChallengeResultA8(reason or "all checkpoints cleared") == true
    end
    if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(true) end
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Drift Challenge checkpoint cleared A8 | idx=" .. tostring(idx) .. " | reason=" .. tostring(reason or "unknown")) end
    return true
end

function driftgod.SafeForceClearCurrentCheckpointButton()
    local ok, result = driftgod.Try(function() return driftgod.ClearCurrentDriftChallengeCheckpointA7("manual force") end)
    if not ok and driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Force clear checkpoint error A8: " .. tostring(result)) end
    return ok and result == true
end

function driftgod.SafeFinishDriftChallengeRaceButton()
    local ok, result = driftgod.Try(function() return driftgod.ShowDriftChallengeResultA8("manual") end)
    if not ok and driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Finish Drift Challenge error A8: " .. tostring(result)) end
    return ok and result == true
end

function driftgod.TickDriftChallengeRace()
    driftgod.DriftChallengeA8EnsureDefaults()
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0

    if driftgod.S.driftChallengeCountdownActive == true then
        if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(false) end
        local elapsed = now - (tonumber(driftgod.S.driftChallengeCountdownStartMs or now) or now)
        if elapsed >= (tonumber(driftgod.S.driftChallengeCountdownDurationMs or 4200) or 4200) then
            driftgod.ActivateDriftChallengeRace()
        end
    end

    if driftgod.S.driftChallengeActive == true then
        driftgod.S.driftChallengeLivePoints = driftgod.GetDriftChallengeLiveScore and driftgod.GetDriftChallengeLiveScore() or 0
        driftgod.S.driftChallengeLiveStunts = driftgod.GetDriftChallengeLiveStunts and driftgod.GetDriftChallengeLiveStunts() or 0

        local checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
        if #checkpoints <= 0 and driftgod.BuildAutoDriftChallengeCheckpointsFromNodes then
            driftgod.BuildAutoDriftChallengeCheckpointsFromNodes()
            checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
            if driftgod.CreateDriftChallengeCheckpointBlips then driftgod.CreateDriftChallengeCheckpointBlips() end
        end

        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        local nextCp = checkpoints[idx]
        if nextCp then
            if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(false) end
            local dist = driftgod.DriftChallengeDistanceToCheckpoint and driftgod.DriftChallengeDistanceToCheckpoint(nextCp) or 999999.0
            driftgod.S.driftChallengeNextCheckpointDistance = math.floor(tonumber(dist or 999999) or 999999)
            local radius = tonumber(driftgod.S.driftChallengeCheckpointRadius or 90.0) or 90.0
            if (tonumber(dist or 999999) or 999999) <= radius then
                driftgod.ClearCurrentDriftChallengeCheckpointA7("distance " .. tostring(math.floor(dist)))
            end
        elseif #checkpoints > 0 then
            driftgod.ShowDriftChallengeResultA8("all checkpoints cleared")
        end
    end

    return true
end

function driftgod.DrawDriftChallengeResultNativeA8()
    if not driftgod.DrawText then return false end
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    if not ((tonumber(driftgod.S.driftChallengeResultVisibleUntil or 0) or 0) > now) then return false end
    local result = driftgod.S.driftChallengeLastResult or {}
    local start = tonumber(driftgod.S.driftChallengeResultStartMs or now) or now
    local elapsed = now - start
    if elapsed < 2600 then
        if result.won == true then
            driftgod.DrawText("You Won!", 0.50, 0.345, 0.86, 120,255,180,255,7)
        else
            driftgod.DrawText("You Failed!", 0.50, 0.345, 0.86, 255,70,70,255,7)
        end
    else
        driftgod.DrawText("RIVAL", 0.43, 0.310, 0.390, 166,94,252,255,7)
        driftgod.DrawText(tostring(result.rival or driftgod.S.driftChallengeRivalName or "Rival"), 0.57, 0.310, 0.390, 255,255,255,255,7)
        driftgod.DrawText("Drifting Points:", 0.445, 0.365, 0.34, 255,255,255,245,4)
        driftgod.DrawText(tostring(result.points or 0), 0.620, 0.365, 0.34, 166,94,252,245,4)
        driftgod.DrawText("Number of Stunts:", 0.445, 0.405, 0.34, 255,255,255,245,4)
        driftgod.DrawText(tostring(result.stunts or 0), 0.620, 0.405, 0.34, 166,94,252,245,4)
        driftgod.DrawText(tostring(result.phrase or ""), 0.50, 0.475, 0.285, 255,255,255,220,4)
    end
    return true
end

local DG_Pre62A8_DrawDriftChallengeHud = driftgod.DrawDriftChallengeHud
function driftgod.DrawDriftChallengeHud()
    if DG_Pre62A8_DrawDriftChallengeHud then driftgod.Try(DG_Pre62A8_DrawDriftChallengeHud) end
    if driftgod.S and driftgod.S.driftChallengeResultForceNativeDraw == true then
        return driftgod.DrawDriftChallengeResultNativeA8()
    end
    return true
end

local DG_Pre62A8_DrawDriftChallengeHudOnPresent = driftgod.DrawDriftChallengeHudOnPresent
function driftgod.DrawDriftChallengeHudOnPresent()
    if DG_Pre62A8_DrawDriftChallengeHudOnPresent then driftgod.Try(DG_Pre62A8_DrawDriftChallengeHudOnPresent) end
    if not DG or not driftgod.S then return end
    if driftgod.S.driftChallengeActive ~= true then return end
    local sw, sh = 1920, 1080
    driftgod.Try(function()
        if ImGui and ImGui.GetDisplaySize then
            local w,h = ImGui.GetDisplaySize()
            if w and h and w > 0 and h > 0 then sw, sh = w, h end
        end
    end)
    local cx = sw * 0.5
    if driftgod.PresentAddTextA7 then
        driftgod.PresentAddTextA7(cx - 230, sh * 0.190, 180,180,180,190, tostring(driftgod.S.driftChallengePositionDebug or "no position"))
        driftgod.PresentAddTextA7(cx - 230, sh * 0.215, 180,180,180,190, tostring(driftgod.S.driftChallengeLastDeltaDebug or "no delta") .. " | " .. tostring(driftgod.S.driftChallengeA8LastCoordSource or "no source"))
    end
end

function driftgod.DriftChallengeA9EnsureDefaults()
    if driftgod.DriftChallengeA8EnsureDefaults then driftgod.DriftChallengeA8EnsureDefaults()
    elseif driftgod.DriftChallengeA7EnsureDefaults then driftgod.DriftChallengeA7EnsureDefaults()
    elseif driftgod.DriftChallengeA6EnsureDefaults then driftgod.DriftChallengeA6EnsureDefaults() end
    driftgod.S.driftChallengeDetectorMode = "PLAYER_ONLY_A9"
    driftgod.S.driftChallengePlayerOnlyRadius = tonumber(driftgod.S.driftChallengePlayerOnlyRadius or 36.0) or 36.0
    if driftgod.S.driftChallengePlayerOnlyRadius < 24.0 then driftgod.S.driftChallengePlayerOnlyRadius = 36.0 end

    driftgod.S.driftChallengeNativeHitRadius = tonumber(driftgod.S.driftChallengeNativeHitRadius or 42.0) or 42.0
    if driftgod.S.driftChallengeNativeHitRadius < 30.0 then driftgod.S.driftChallengeNativeHitRadius = 42.0 end
end

function driftgod.GetA9LocalPlayerPedHandle()
    local ped = 0
    driftgod.Try(function()
        if PLAYER and PLAYER.PLAYER_PED_ID then ped = tonumber(PLAYER.PLAYER_PED_ID() or 0) or 0 end
    end)
    if ped ~= 0 then return ped end
    driftgod.Try(function()
        if Natives and Natives.InvokeInt then ped = tonumber(Natives.InvokeInt(0xD80958FC74E988A6) or 0) or 0 end
    end)
    if ped ~= 0 then return ped end
    driftgod.Try(function()
        if GTA and GTA.GetLocalPed and GTA.PointerToHandle and CPed and CPed.FromAddress then
            local p = GTA.GetLocalPed()
            if p and p.GetAddress then ped = tonumber(GTA.PointerToHandle(CPed.FromAddress(p:GetAddress())) or 0) or 0 end
        end
    end)
    return tonumber(ped or 0) or 0
end

function driftgod.IsA9GhostVehicleHandle(handle)
    handle = tonumber(handle or 0) or 0
    if handle == 0 then return false end
    local ghosts = {
        driftgod.S.ghostReplayPreviewVehicle,
        driftgod.S.ghostRecordedPlaybackVehicle,
        driftgod.S.ghostRecordingPlaybackVehicle,
        driftgod.S.ghostPlaybackVehicle,
        driftgod.S.driftChallengeGhostVehicle,
    }
    for _, h in ipairs(ghosts) do
        if handle ~= 0 and tonumber(h or 0) == handle then return true end
    end
    return false
end

function driftgod.GetA9LocalPlayerVehicleHandle()
    local ped = driftgod.GetA9LocalPlayerPedHandle and driftgod.GetA9LocalPlayerPedHandle() or 0
    local veh = 0
    if ped ~= 0 then
        driftgod.Try(function()
            if PED and PED.GET_VEHICLE_PED_IS_IN then veh = tonumber(PED.GET_VEHICLE_PED_IS_IN(ped, false) or 0) or 0 end
        end)
        if veh == 0 then
            driftgod.Try(function()
                if Natives and Natives.InvokeInt then veh = tonumber(Natives.InvokeInt(0x9A9112A0FE9A4713, ped, false) or 0) or 0 end
            end)
        end
    end
    if veh ~= 0 and driftgod.IsA9GhostVehicleHandle and driftgod.IsA9GhostVehicleHandle(veh) then
        driftgod.S.driftChallengePositionDebug = "A9 rejected ghost veh=" .. tostring(veh)
        return 0
    end
    return tonumber(veh or 0) or 0
end

function driftgod.GetA9CheckpointDetectorEntity()

    local veh = driftgod.GetA9LocalPlayerVehicleHandle and driftgod.GetA9LocalPlayerVehicleHandle() or 0
    if veh ~= 0 then return veh, "player_vehicle" end
    local ped = driftgod.GetA9LocalPlayerPedHandle and driftgod.GetA9LocalPlayerPedHandle() or 0
    if ped ~= 0 then return ped, "player_ped" end
    return 0, "none"
end

function driftgod.GetA9EntityCoords(entity)
    entity = tonumber(entity or 0) or 0
    if entity == 0 then return nil end

    if driftgod.GetEntityCoordsForRecording then
        local ok, x, y, z = driftgod.Try(function() return driftgod.GetEntityCoordsForRecording(entity) end)
        if ok and tonumber(x) and tonumber(y) and not (tonumber(x) == 0 and tonumber(y) == 0) then
            return tonumber(x), tonumber(y), tonumber(z) or 0.0, "recording_wrapper"
        end
    end

    if Natives and Natives.InvokeV3 then

        local ok, x, y, z = driftgod.Try(Natives.InvokeV3, 0x3FEF770D40960D5A, entity, true)
        if ok and tonumber(x) and tonumber(y) then
            return tonumber(x), tonumber(y), tonumber(z) or 0.0, "native_xyz"
        end

        local ok2, raw = driftgod.Try(function() return Natives.InvokeV3(0x3FEF770D40960D5A, entity, true) end)
        if ok2 and raw and driftgod.GetVectorPartsSafe then
            local vx, vy, vz = driftgod.GetVectorPartsSafe(raw)
            if vx and vy then return vx, vy, vz or 0.0, "native_v3" end
        end
    end

    return nil
end

function driftgod.GetDriftChallengePlayerPosition()
    driftgod.DriftChallengeA9EnsureDefaults()
    local ent, source = driftgod.GetA9CheckpointDetectorEntity()
    if ent == 0 then
        driftgod.S.driftChallengePositionDebug = "A9 no player entity"
        return nil
    end
    local x, y, z, coordSource = driftgod.GetA9EntityCoords(ent)
    if x and y then
        driftgod.S.driftChallengePositionDebug = "A9 " .. tostring(source) .. " ent=" .. tostring(ent)
            .. " x=" .. tostring(math.floor(x)) .. " y=" .. tostring(math.floor(y))
            .. " src=" .. tostring(coordSource or "?")
        return x, y, z or 0.0
    end
    driftgod.S.driftChallengePositionDebug = "A9 coord failed | " .. tostring(source) .. " ent=" .. tostring(ent)
    return nil
end

function driftgod.IsDriftChallengeEntityAtCheckpointA7(cp)
    driftgod.DriftChallengeA9EnsureDefaults()
    if type(cp) ~= "table" or not Natives or not Natives.InvokeBool then return false end
    local ent, source = driftgod.GetA9CheckpointDetectorEntity()
    if not ent or ent == 0 then
        driftgod.S.driftChallengeLastHitSource = "A9 no player entity"
        return false
    end
    if driftgod.IsA9GhostVehicleHandle and driftgod.IsA9GhostVehicleHandle(ent) then
        driftgod.S.driftChallengeLastHitSource = "A9 rejected ghost hit ent=" .. tostring(ent)
        return false
    end
    local r = tonumber(driftgod.S.driftChallengeNativeHitRadius or 42.0) or 42.0
    local x = tonumber(cp.x or 0) or 0
    local y = tonumber(cp.y or 0) or 0
    local z = tonumber(cp.z or 0) or 0
    local hit = false
    driftgod.Try(function()
        hit = Natives.InvokeBool(0x20B711662962B472, ent, x + 0.0, y + 0.0, z + 0.0, r + 0.0, r + 0.0, 14.0, false, true, 0) == true
    end)
    driftgod.S.driftChallengeLastHitSource = "A9 " .. tostring(source) .. " nativeHit=" .. tostring(hit) .. " r=" .. tostring(math.floor(r))
    return hit == true
end

function driftgod.DriftChallengeDistanceToCheckpoint(cp)
    driftgod.DriftChallengeA9EnsureDefaults()
    if type(cp) ~= "table" then return 999999.0 end
    local x,y,z = driftgod.GetDriftChallengePlayerPosition and driftgod.GetDriftChallengePlayerPosition() or nil
    if not x then return 999999.0 end
    local dx = x - (tonumber(cp.x or 0) or 0)
    local dy = y - (tonumber(cp.y or 0) or 0)
    local dz = (z or 0) - (tonumber(cp.z or 0) or 0)
    local dist2d = math.sqrt(dx*dx + dy*dy)
    driftgod.S.driftChallengeLastDistanceFloat = dist2d
    driftgod.S.driftChallengeLastDeltaDebug = "A9 dx=" .. tostring(math.floor(dx))
        .. " dy=" .. tostring(math.floor(dy))
        .. " dz=" .. tostring(math.floor(dz))
        .. " d2=" .. tostring(math.floor(dist2d))
    return dist2d
end

function driftgod.TickDriftChallengeRace()
    driftgod.DriftChallengeA9EnsureDefaults()
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0

    if driftgod.S.driftChallengeCountdownActive == true then
        if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(false) end
        local elapsed = now - (tonumber(driftgod.S.driftChallengeCountdownStartMs or now) or now)
        if elapsed >= (tonumber(driftgod.S.driftChallengeCountdownDurationMs or 4200) or 4200) then
            driftgod.ActivateDriftChallengeRace()
        end
    end

    if driftgod.S.driftChallengeActive == true then
        driftgod.S.driftChallengeLivePoints = driftgod.GetDriftChallengeLiveScore and driftgod.GetDriftChallengeLiveScore() or 0
        driftgod.S.driftChallengeLiveStunts = driftgod.GetDriftChallengeLiveStunts and driftgod.GetDriftChallengeLiveStunts() or 0

        local checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
        if #checkpoints <= 0 and driftgod.BuildAutoDriftChallengeCheckpointsFromNodes then
            driftgod.BuildAutoDriftChallengeCheckpointsFromNodes()
            checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
            if driftgod.CreateDriftChallengeCheckpointBlips then driftgod.CreateDriftChallengeCheckpointBlips() end
        end

        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        local nextCp = checkpoints[idx]
        if nextCp then
            if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(false) end
            local dist = driftgod.DriftChallengeDistanceToCheckpoint and driftgod.DriftChallengeDistanceToCheckpoint(nextCp) or 999999.0
            local nativeHit = driftgod.IsDriftChallengeEntityAtCheckpointA7 and driftgod.IsDriftChallengeEntityAtCheckpointA7(nextCp) or false
            driftgod.S.driftChallengeNextCheckpointDistance = math.floor(tonumber(dist or 999999) or 999999)
            local radius = tonumber(driftgod.S.driftChallengePlayerOnlyRadius or driftgod.S.driftChallengeCheckpointRadius or 36.0) or 36.0
            if nativeHit == true or ((tonumber(dist or 999999) or 999999) <= radius) then
                driftgod.ClearCurrentDriftChallengeCheckpointA7(nativeHit and "player native hit" or ("player distance " .. tostring(math.floor(dist))))
            end
        elseif #checkpoints > 0 then
            driftgod.ShowDriftChallengeResultA8("all checkpoints cleared")
        end
    end

    return true
end

local DG_Pre62A9_DrawDriftChallengeHud = driftgod.DrawDriftChallengeHud
