        driftgod.DrawText(tostring(driftgod.S.driftChallengePositionDebug or "") .. " | " .. tostring(driftgod.S.driftChallengeLastDeltaDebug or ""), 0.50, 0.230, 0.18, 180,180,180,190,4)
    end
    return true
