function driftgod.DriftChallengeA10EnsureDefaults()
    if driftgod.DriftChallengeA9EnsureDefaults then driftgod.DriftChallengeA9EnsureDefaults()
    elseif driftgod.DriftChallengeA8EnsureDefaults then driftgod.DriftChallengeA8EnsureDefaults()
    elseif driftgod.DriftChallengeEnsureDefaults then driftgod.DriftChallengeEnsureDefaults() end
    driftgod.S.driftChallengeDetectorMode = "PLAYER_PED_POSITION_A10"
    driftgod.S.driftChallengePlayerOnlyRadius = tonumber(driftgod.S.driftChallengePlayerOnlyRadius or 48.0) or 48.0
    if driftgod.S.driftChallengePlayerOnlyRadius < 42.0 then driftgod.S.driftChallengePlayerOnlyRadius = 48.0 end
    driftgod.S.driftChallengeNativeHitRadius = tonumber(driftgod.S.driftChallengeNativeHitRadius or 52.0) or 52.0
    if driftgod.S.driftChallengeNativeHitRadius < 44.0 then driftgod.S.driftChallengeNativeHitRadius = 52.0 end
    driftgod.S.driftChallengeCountdownDurationMs = tonumber(driftgod.S.driftChallengeCountdownDurationMs or 4200) or 4200
    if driftgod.S.driftChallengeCountdownDurationMs < 3900 then driftgod.S.driftChallengeCountdownDurationMs = 4200 end
    driftgod.S.driftChallengeLastPlayerX = tonumber(driftgod.S.driftChallengeLastPlayerX or 0) or 0
    driftgod.S.driftChallengeLastPlayerY = tonumber(driftgod.S.driftChallengeLastPlayerY or 0) or 0
    driftgod.S.driftChallengeLastPlayerZ = tonumber(driftgod.S.driftChallengeLastPlayerZ or 0) or 0
    driftgod.S.driftChallengeRecordingStartCollisions = tonumber(driftgod.S.driftChallengeRecordingStartCollisions or 0) or 0
    driftgod.S.driftChallengeRaceStartCollisions = tonumber(driftgod.S.driftChallengeRaceStartCollisions or 0) or 0
    driftgod.S.driftChallengeCollisionCounter = tonumber(driftgod.S.driftChallengeCollisionCounter or 0) or 0
    driftgod.S.ghostRecordingChallengeCollisions = tonumber(driftgod.S.ghostRecordingChallengeCollisions or 0) or 0
    driftgod.S.driftChallengeTargetCollisions = tonumber(driftgod.S.driftChallengeTargetCollisions or driftgod.S.ghostRecordingChallengeCollisions or 0) or 0
end

function driftgod.DriftChallengeGetCollisionTotalA10()
    local total = tonumber(driftgod.S.driftChallengeCollisionCounter or 0) or 0

    if total <= 0 and driftgod.S.sessionChallengeRunNoCollision == false then total = 1 end
    if total <= 0 and driftgod.S.postStuntCollisionDetected == true then total = 1 end
    return math.floor(total)
end

function driftgod.DriftChallengeGetRunCollisionSnapshot()
    local total = driftgod.DriftChallengeGetCollisionTotalA10 and driftgod.DriftChallengeGetCollisionTotalA10() or 0
    local start = tonumber(driftgod.S.driftChallengeRecordingStartCollisions or 0) or 0
    local out = math.max(0, total - start)
    return math.floor(out)
end

function driftgod.GetDriftChallengeLiveCollisions()
    local total = driftgod.DriftChallengeGetCollisionTotalA10 and driftgod.DriftChallengeGetCollisionTotalA10() or 0
    local start = tonumber(driftgod.S.driftChallengeRaceStartCollisions or 0) or 0
    return math.max(0, math.floor(total - start))
end

local DG_Pre62A10_MarkSessionChallengeCollision = driftgod.MarkSessionChallengeCollision
function driftgod.MarkSessionChallengeCollision(source)
    driftgod.S.driftChallengeCollisionCounter = (tonumber(driftgod.S.driftChallengeCollisionCounter or 0) or 0) + 1
    if DG_Pre62A10_MarkSessionChallengeCollision then
        return DG_Pre62A10_MarkSessionChallengeCollision(source)
    end
    return true
end

local DG_Pre62A10_StopRunFromCollision = driftgod.StopRunFromCollision
function driftgod.StopRunFromCollision()

    local before = tonumber(driftgod.S.driftChallengeCollisionCounter or 0) or 0
    local result = nil
    if DG_Pre62A10_StopRunFromCollision then result = DG_Pre62A10_StopRunFromCollision() end
    local after = tonumber(driftgod.S.driftChallengeCollisionCounter or 0) or 0
    if after == before then driftgod.S.driftChallengeCollisionCounter = before + 1 end
    return result
end

function driftgod.GetA10PedHandle()
    local ped = 0
