    if ped == 0 then return 0 end
    local veh = 0
    driftgod.Try(function() if PED and PED.GET_VEHICLE_PED_IS_IN then veh = tonumber(PED.GET_VEHICLE_PED_IS_IN(ped, false) or 0) or 0 end end)
    if veh == 0 then driftgod.Try(function() if Natives and Natives.InvokeInt then veh = tonumber(Natives.InvokeInt(0x9A9112A0FE9A4713, ped, false) or 0) or 0 end end) end
