end

function driftgod.GetA10CoordsFromHandle(ent)
    ent = tonumber(ent or 0) or 0
    if ent == 0 then return nil end
    if Natives and Natives.InvokeV3 then
        local ok, x, y, z = driftgod.Try(Natives.InvokeV3, 0x3FEF770D40960D5A, ent, true)
        if ok and tonumber(x) and tonumber(y) then return tonumber(x), tonumber(y), tonumber(z) or 0.0, "native_xyz" end
        local ok2, raw = driftgod.Try(function() return Natives.InvokeV3(0x3FEF770D40960D5A, ent, true) end)
        if ok2 and raw and driftgod.GetVectorPartsSafe then
            local vx, vy, vz = driftgod.GetVectorPartsSafe(raw)
            if vx and vy then return vx, vy, vz or 0.0, "native_v3" end
        end
    end
    if driftgod.GetEntityCoordsForRecording then
        local ok, x, y, z = driftgod.Try(function() return driftgod.GetEntityCoordsForRecording(ent) end)
        if ok and tonumber(x) and tonumber(y) then return tonumber(x), tonumber(y), tonumber(z) or 0.0, "recording_wrapper" end
    end
    return nil
end

