    driftgod.Try(function() if GTA and GTA.GetLocalPed then p = GTA.GetLocalPed() end end)
    if p and p.Position and driftgod.GetVectorPartsSafe then
        local x,y,z = driftgod.GetVectorPartsSafe(p.Position)
        if x and y then return x,y,z or 0.0,"ped_centity_position" end
    end
    return nil
end

function driftgod.CaptureDriftChallengePlayerVehicleA10(reason)
    driftgod.DriftChallengeA10EnsureDefaults()
    local ped = driftgod.GetA10PedHandle and driftgod.GetA10PedHandle() or 0
    local veh = driftgod.GetA10VehicleHandleFromPed and driftgod.GetA10VehicleHandleFromPed(ped) or 0
    if veh ~= 0 and driftgod.IsA9GhostVehicleHandle and driftgod.IsA9GhostVehicleHandle(veh) then veh = 0 end
    driftgod.S.driftChallengePlayerPedHandle = ped
    driftgod.S.driftChallengePlayerRaceVehicle = veh
    driftgod.S.driftChallengePlayerVehicleCaptureStatus = "ped=" .. tostring(ped) .. " veh=" .. tostring(veh) .. " " .. tostring(reason or "")
    return veh ~= 0
end

function driftgod.GetDriftChallengePlayerPosition()
    driftgod.DriftChallengeA10EnsureDefaults()

    local x,y,z,src = driftgod.GetA10LocalPedPositionObject()
    if x and y then
        driftgod.S.driftChallengePositionDebug = "A10 player ped pos x=" .. tostring(math.floor(x)) .. " y=" .. tostring(math.floor(y)) .. " src=" .. tostring(src)
        driftgod.S.driftChallengeLastPlayerX, driftgod.S.driftChallengeLastPlayerY, driftgod.S.driftChallengeLastPlayerZ = x,y,z or 0.0
        return x,y,z or 0.0
    end

    local veh = tonumber(driftgod.S.driftChallengePlayerRaceVehicle or 0) or 0
    if veh ~= 0 and not (driftgod.IsA9GhostVehicleHandle and driftgod.IsA9GhostVehicleHandle(veh)) then
        local vx,vy,vz,vs = driftgod.GetA10CoordsFromHandle(veh)
        if vx and vy then
            driftgod.S.driftChallengePositionDebug = "A10 locked veh=" .. tostring(veh) .. " x=" .. tostring(math.floor(vx)) .. " y=" .. tostring(math.floor(vy)) .. " src=" .. tostring(vs)
            driftgod.S.driftChallengeLastPlayerX, driftgod.S.driftChallengeLastPlayerY, driftgod.S.driftChallengeLastPlayerZ = vx,vy,vz or 0.0
            return vx,vy,vz or 0.0
        end
    end

    local ped = driftgod.GetA10PedHandle and driftgod.GetA10PedHandle() or 0
    local px,py,pz,ps = driftgod.GetA10CoordsFromHandle(ped)
    if px and py then
        driftgod.S.driftChallengePositionDebug = "A10 ped handle=" .. tostring(ped) .. " x=" .. tostring(math.floor(px)) .. " y=" .. tostring(math.floor(py)) .. " src=" .. tostring(ps)
        driftgod.S.driftChallengeLastPlayerX, driftgod.S.driftChallengeLastPlayerY, driftgod.S.driftChallengeLastPlayerZ = px,py,pz or 0.0
        return px,py,pz or 0.0
    end

    driftgod.S.driftChallengePositionDebug = "A10 position failed | " .. tostring(driftgod.S.driftChallengePlayerVehicleCaptureStatus or "no capture")
    return nil
end

function driftgod.DriftChallengeDistanceToCheckpoint(cp)
    driftgod.DriftChallengeA10EnsureDefaults()
    if type(cp) ~= "table" then return 999999.0 end
    local x,y,z = driftgod.GetDriftChallengePlayerPosition and driftgod.GetDriftChallengePlayerPosition() or nil
    if not x then return 999999.0 end
    local dx = x - (tonumber(cp.x or 0) or 0)
    local dy = y - (tonumber(cp.y or 0) or 0)
    local dz = (z or 0) - (tonumber(cp.z or 0) or 0)
    local dist2d = math.sqrt(dx*dx + dy*dy)
    driftgod.S.driftChallengeLastDistanceFloat = dist2d
    driftgod.S.driftChallengeLastDeltaDebug = "A10 dx=" .. tostring(math.floor(dx)) .. " dy=" .. tostring(math.floor(dy)) .. " dz=" .. tostring(math.floor(dz)) .. " d2=" .. tostring(math.floor(dist2d))
    return dist2d
end

function driftgod.DriftChallengeSegmentCrossedCheckpointA10(cp)
    if type(cp) ~= "table" then return false end
    local lastX = tonumber(driftgod.S.driftChallengeLastPlayerX or 0) or 0
    local lastY = tonumber(driftgod.S.driftChallengeLastPlayerY or 0) or 0
    local curX, curY = driftgod.GetDriftChallengePlayerPosition()
    if not curX or lastX == 0 or lastY == 0 then return false end
    local cx = tonumber(cp.x or 0) or 0
    local cy = tonumber(cp.y or 0) or 0
    local ax, ay = lastX, lastY
    local bx, by = curX, curY
    local abx, aby = bx - ax, by - ay
    local acx, acy = cx - ax, cy - ay
    local ab2 = abx*abx + aby*aby
    if ab2 <= 0.001 then return false end
    local t = (acx*abx + acy*aby) / ab2
    if t < 0 then t = 0 elseif t > 1 then t = 1 end
    local px, py = ax + abx*t, ay + aby*t
    local dx, dy = px - cx, py - cy
    local d = math.sqrt(dx*dx + dy*dy)
    local r = tonumber(driftgod.S.driftChallengePlayerOnlyRadius or 48.0) or 48.0
    driftgod.S.driftChallengeLastSegmentDebug = "seg d=" .. tostring(math.floor(d)) .. " r=" .. tostring(math.floor(r))
    return d <= r
end

function driftgod.DriftChallengeGetVehicleLabelA10()
    local name = "Vehicle"
    driftgod.Try(function()
        if driftgod.GetVehicleMasteryName then
            local n = driftgod.GetVehicleMasteryName()
            if n and tostring(n) ~= "" then name = tostring(n) end
        end
    end)
    if name == "Vehicle" or name == "Unknown" then
        local model = tonumber(driftgod.GetRecordedGhostModel and driftgod.GetRecordedGhostModel() or driftgod.S.ghostRecordingVehicleModel or 0) or 0
        if model ~= 0 then name = "Vehicle_" .. tostring(model) end
    end
    name = name:gsub("[^%w%-_]", "_"):gsub("_+", "_"):gsub("^_", ""):gsub("_$", "")
    if name == "" then name = "Vehicle" end
    return name
end

function driftgod.SetGhostRecordingAutoFileNameA10()
    local stamp = tostring(os.date and os.date("%Y%m%d_%H%M%S") or "Timestamp")
    local vehicle = driftgod.DriftChallengeGetVehicleLabelA10 and driftgod.DriftChallengeGetVehicleLabelA10() or "Vehicle"
    local name = "DG_" .. stamp .. "_" .. tostring(vehicle)
    if driftgod.SetGhostRecordingFileName then driftgod.SetGhostRecordingFileName(name)
    else driftgod.S.ghostRecordingFileName = name end
    return name
end

