function driftgod.DriftChallengeJsonMetaBlock()
    driftgod.DriftChallengeA10EnsureDefaults()
    local points = driftgod.DriftChallengeGetRunScoreSnapshot and driftgod.DriftChallengeGetRunScoreSnapshot() or 0
    local stunts = driftgod.DriftChallengeGetRunStuntSnapshot and driftgod.DriftChallengeGetRunStuntSnapshot() or 0
    local collisions = driftgod.DriftChallengeGetRunCollisionSnapshot and driftgod.DriftChallengeGetRunCollisionSnapshot() or 0
    local rivalName = tostring(driftgod.S.ghostSimpleRecordingOwner or driftgod.S.driftChallengeRivalName or driftgod.S.ghostRecordingFileName or "Self Rival")
    rivalName = rivalName:gsub('"', "'")
    driftgod.S.ghostRecordingChallengePoints = points
    driftgod.S.ghostRecordingChallengeStunts = stunts
    driftgod.S.ghostRecordingChallengeCollisions = collisions
    driftgod.S.ghostRecordingChallengeRivalName = rivalName
    return '  "DriftChallenge": true,\n'
        .. '  "RivalName": "' .. rivalName .. '",\n'
        .. '  "DriftingPoints": ' .. tostring(points) .. ',\n'
        .. '  "NumberOfStunts": ' .. tostring(stunts) .. ',\n'
        .. '  "NumberOfCollisions": ' .. tostring(collisions) .. ',\n'
end

function driftgod.ParseDriftChallengeMeta(jsonText)
    jsonText = tostring(jsonText or "")
    local name = jsonText:match('"RivalName"%s*:%s*"([^"]*)"') or jsonText:match('"Name"%s*:%s*"([^"]*)"') or "Self Rival"
    local points = tonumber(jsonText:match('"DriftingPoints"%s*:%s*([%-%.%d]+)') or jsonText:match('"TargetPoints"%s*:%s*([%-%.%d]+)') or 0) or 0
    local stunts = tonumber(jsonText:match('"NumberOfStunts"%s*:%s*([%-%.%d]+)') or jsonText:match('"TargetStunts"%s*:%s*([%-%.%d]+)') or 0) or 0
    local collisions = tonumber(jsonText:match('"NumberOfCollisions"%s*:%s*([%-%.%d]+)') or jsonText:match('"TargetCollisions"%s*:%s*([%-%.%d]+)') or 0) or 0
    local isChallenge = jsonText:find('"DriftChallenge"%s*:%s*true') ~= nil or points > 0 or stunts > 0
    return { name = name, points = math.floor(points), stunts = math.floor(stunts), collisions = math.floor(collisions), isChallenge = isChallenge }
end

function driftgod.LoadDriftChallengeMetaFromJsonText(jsonText)
    driftgod.DriftChallengeA10EnsureDefaults()
    local meta = driftgod.ParseDriftChallengeMeta and driftgod.ParseDriftChallengeMeta(jsonText) or { name = "Self Rival", points = 0, stunts = 0, collisions = 0 }
    driftgod.S.driftChallengeRivalName = tostring(meta.name or "Self Rival")
    driftgod.S.driftChallengeTargetPoints = tonumber(meta.points or 0) or 0
    driftgod.S.driftChallengeTargetStunts = tonumber(meta.stunts or 0) or 0
    driftgod.S.driftChallengeTargetCollisions = tonumber(meta.collisions or 0) or 0
    driftgod.S.driftChallengeStatus = "Challenge Loaded"
    return meta
end

local DG_Pre62A10_StopGhostSimpleRecording = driftgod.StopGhostSimpleRecording
function driftgod.StopGhostSimpleRecording()
    local ok = DG_Pre62A10_StopGhostSimpleRecording and DG_Pre62A10_StopGhostSimpleRecording() or false

    driftgod.S.ghostRecordingChallengePoints = driftgod.DriftChallengeGetRunScoreSnapshot and driftgod.DriftChallengeGetRunScoreSnapshot() or 0
    driftgod.S.ghostRecordingChallengeStunts = driftgod.DriftChallengeGetRunStuntSnapshot and driftgod.DriftChallengeGetRunStuntSnapshot() or 0
    driftgod.S.ghostRecordingChallengeCollisions = driftgod.DriftChallengeGetRunCollisionSnapshot and driftgod.DriftChallengeGetRunCollisionSnapshot() or 0
    driftgod.SetGhostRecordingAutoFileNameA10()

    if ok == true and driftgod.SaveRecordedGhostJson then
        local saveOk = driftgod.SaveRecordedGhostJson() == true
        driftgod.S.ghostSimpleFlowStatus = saveOk and "Stopped + Auto-Saved Challenge" or "Stopped, Auto-Save Failed"
        if driftgod.ScanSavedGhostRecordings then driftgod.Try(driftgod.ScanSavedGhostRecordings) end
    end
    return ok == true
end

function driftgod.MakeDriftChallengeResultA8(reason)
    driftgod.DriftChallengeA10EnsureDefaults()
    local yourPoints = driftgod.GetDriftChallengeLiveScore and driftgod.GetDriftChallengeLiveScore() or tonumber(driftgod.S.driftChallengeLivePoints or 0) or 0
    local yourStunts = driftgod.GetDriftChallengeLiveStunts and driftgod.GetDriftChallengeLiveStunts() or tonumber(driftgod.S.driftChallengeLiveStunts or 0) or 0
    local yourCollisions = driftgod.GetDriftChallengeLiveCollisions and driftgod.GetDriftChallengeLiveCollisions() or 0
    local rivalPoints = tonumber(driftgod.S.driftChallengeTargetPoints or 0) or 0
    local rivalStunts = tonumber(driftgod.S.driftChallengeTargetStunts or 0) or 0
    local rivalCollisions = tonumber(driftgod.S.driftChallengeTargetCollisions or 0) or 0
    local cps = driftgod.S.ghostRecordingCheckpoints or {}
    local cleared = math.max(0, math.min(#cps, (tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1) - 1))
    local won = true
    if rivalPoints > 0 then won = won and (yourPoints >= rivalPoints) else won = won and (yourPoints > 0) end
    if rivalStunts > 0 then won = won and (yourStunts >= rivalStunts) end
    won = won and (yourCollisions <= rivalCollisions)
    if #cps > 0 and cleared < #cps and tostring(reason or "") ~= "manual" and tostring(reason or "") ~= "force complete" then won = false end
    return {
        rival = tostring(driftgod.S.driftChallengeRivalName or "Rival"),
        won = won,
        points = math.floor(yourPoints),
        stunts = math.floor(yourStunts),
        collisions = math.floor(yourCollisions),
        targetPoints = math.floor(rivalPoints),
        targetStunts = math.floor(rivalStunts),
        targetCollisions = math.floor(rivalCollisions),
        checkpoints = cleared,
        phrase = driftgod.GetDriftChallengePhrase and driftgod.GetDriftChallengePhrase(won) or "",
        reason = tostring(reason or "complete"),
        date = tostring(os.date and os.date("%Y-%m-%d %H:%M:%S") or "")
    }
end

function driftgod.ShowDriftChallengeResultA10(reason)
    local result = driftgod.MakeDriftChallengeResultA8(reason)
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    driftgod.S.driftChallengeLastResult = result
    driftgod.S.driftChallengeActive = false
    driftgod.S.driftChallengeCountdownActive = false
    driftgod.S.driftChallengeStatus = result.won and "You Won" or "You Failed"
    driftgod.S.driftChallengeResultStartMs = now
    driftgod.S.driftChallengeResultVisibleUntil = now + 11000
    driftgod.S.driftChallengeResultForceNativeDraw = true
    if driftgod.WriteDriftChallengeResultLog then driftgod.Try(function() driftgod.WriteDriftChallengeResultLog(result) end) end
    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("Drift Challenge A10 result | won=" .. tostring(result.won)
            .. " | your=" .. tostring(result.points) .. "/" .. tostring(result.stunts) .. "/" .. tostring(result.collisions)
            .. " | rival=" .. tostring(result.targetPoints) .. "/" .. tostring(result.targetStunts) .. "/" .. tostring(result.targetCollisions))
    end
    return true
end

function driftgod.FinishDriftChallengeRace(reason)
    if driftgod.ClearDriftChallengeCheckpointBlips then driftgod.Try(function() driftgod.ClearDriftChallengeCheckpointBlips("finish A10") end) end
    if driftgod.DeleteDriftChallengeNativeCheckpoint then driftgod.Try(function() driftgod.DeleteDriftChallengeNativeCheckpoint("finish A10") end) end
    return driftgod.ShowDriftChallengeResultA10(reason or "manual")
end

function driftgod.ClearCurrentDriftChallengeCheckpointA7(reason)
    driftgod.DriftChallengeA10EnsureDefaults()
    local cps = driftgod.S.ghostRecordingCheckpoints or {}
    local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
    if idx > #cps then return false end
    driftgod.S.driftChallengeCheckpointIndex = idx + 1
    driftgod.S.driftChallengeStatus = "Checkpoint " .. tostring(idx) .. " cleared" .. (reason and (" | " .. tostring(reason)) or "")
    if driftgod.DeleteDriftChallengeNativeCheckpoint then driftgod.DeleteDriftChallengeNativeCheckpoint("checkpoint cleared A10") end
    if driftgod.AddBonusPopup then driftgod.AddBonusPopup("CHECKPOINT " .. tostring(idx), 255, 230, 80) end
    if driftgod.UpdateDriftChallengeRouteBlip then driftgod.UpdateDriftChallengeRouteBlip() end
    if idx >= #cps and #cps > 0 then
        return driftgod.FinishDriftChallengeRace("all checkpoints cleared")
    end
    if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(true) end
    return true
end

local DG_Pre62A10_StartDriftChallengeCountdown = driftgod.StartDriftChallengeCountdown
function driftgod.StartDriftChallengeCountdown()
    driftgod.DriftChallengeA10EnsureDefaults()
    driftgod.CaptureDriftChallengePlayerVehicleA10("start countdown")
    driftgod.S.driftChallengeRaceStartCollisions = driftgod.DriftChallengeGetCollisionTotalA10 and driftgod.DriftChallengeGetCollisionTotalA10() or 0
    local ok = DG_Pre62A10_StartDriftChallengeCountdown and DG_Pre62A10_StartDriftChallengeCountdown() or false

    if ok == true then
        driftgod.S.driftChallengeCountdownActive = true
        driftgod.S.driftChallengeActive = false
        driftgod.S.driftChallengeCountdownStartMs = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
        driftgod.S.driftChallengeStatus = "Countdown"
        if driftgod.CreateDriftChallengeCheckpointBlips then driftgod.Try(driftgod.CreateDriftChallengeCheckpointBlips) end
        if driftgod.UpdateDriftChallengeRouteBlip then driftgod.Try(driftgod.UpdateDriftChallengeRouteBlip) end
    end
    return ok == true
end

local DG_Pre62A10_ActivateDriftChallengeRace = driftgod.ActivateDriftChallengeRace
function driftgod.ActivateDriftChallengeRace()
    driftgod.DriftChallengeA10EnsureDefaults()
    driftgod.CaptureDriftChallengePlayerVehicleA10("activate race")
    local ok = DG_Pre62A10_ActivateDriftChallengeRace and DG_Pre62A10_ActivateDriftChallengeRace() or false
    driftgod.S.driftChallengeActive = true
    driftgod.S.driftChallengeCountdownActive = false
    driftgod.S.driftChallengeStatus = "Race Active"
    return ok == true or true
end

function driftgod.TickDriftChallengeRace()
    driftgod.DriftChallengeA10EnsureDefaults()
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    if driftgod.S.driftChallengeCountdownActive == true then
        if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(false) end
        local elapsed = now - (tonumber(driftgod.S.driftChallengeCountdownStartMs or now) or now)
        if elapsed >= (tonumber(driftgod.S.driftChallengeCountdownDurationMs or 4200) or 4200) then
            driftgod.ActivateDriftChallengeRace()
        end
    end
    if driftgod.S.driftChallengeActive == true then
        driftgod.S.driftChallengeLivePoints = driftgod.GetDriftChallengeLiveScore and driftgod.GetDriftChallengeLiveScore() or 0
        driftgod.S.driftChallengeLiveStunts = driftgod.GetDriftChallengeLiveStunts and driftgod.GetDriftChallengeLiveStunts() or 0
        driftgod.S.driftChallengeLiveCollisions = driftgod.GetDriftChallengeLiveCollisions and driftgod.GetDriftChallengeLiveCollisions() or 0
        local checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
        if #checkpoints <= 0 and driftgod.BuildAutoDriftChallengeCheckpointsFromNodes then
            driftgod.BuildAutoDriftChallengeCheckpointsFromNodes(); checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
            if driftgod.CreateDriftChallengeCheckpointBlips then driftgod.CreateDriftChallengeCheckpointBlips() end
        end
        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        local cp = checkpoints[idx]
        if cp then
            if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.RefreshDriftChallengeNativeCheckpoint(false) end
            local dist = driftgod.DriftChallengeDistanceToCheckpoint and driftgod.DriftChallengeDistanceToCheckpoint(cp) or 999999
            local crossed = driftgod.DriftChallengeSegmentCrossedCheckpointA10 and driftgod.DriftChallengeSegmentCrossedCheckpointA10(cp) or false
            driftgod.S.driftChallengeNextCheckpointDistance = math.floor(tonumber(dist or 999999) or 999999)
            local radius = tonumber(driftgod.S.driftChallengePlayerOnlyRadius or 48.0) or 48.0
            if crossed == true or dist <= radius then
                driftgod.ClearCurrentDriftChallengeCheckpointA7(crossed and "player segment" or ("player distance " .. tostring(math.floor(dist))))
            end
        elseif #checkpoints > 0 then
            driftgod.FinishDriftChallengeRace("all checkpoints cleared")
        end
    end
    return true
end

function driftgod.GetDriftChallengeCountdownText()
    if driftgod.S.driftChallengeCountdownActive ~= true then return "" end
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    local elapsed = now - (tonumber(driftgod.S.driftChallengeCountdownStartMs or now) or now)
    if elapsed < 1000 then return "3" end
    if elapsed < 2000 then return "2" end
    if elapsed < 3000 then return "1" end
    if elapsed < 4200 then return "GO!" end
    return ""
end

function driftgod.DrawDriftChallengeHud()
    if not driftgod.DrawText then return true end
    driftgod.DriftChallengeA10EnsureDefaults()
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    if driftgod.S.driftChallengeCountdownActive == true then
        local txt = driftgod.GetDriftChallengeCountdownText and driftgod.GetDriftChallengeCountdownText() or ""
        if txt ~= "" then
            local size = txt == "GO!" and 1.20 or 1.46
            local r,g,b = 255,255,255
            if txt == "GO!" then r,g,b = 120,255,180 end
            driftgod.DrawText(txt, 0.50, 0.35, size, r,g,b,255,7)
        end
    end
    if driftgod.S.driftChallengeActive == true then
        local cps = driftgod.S.ghostRecordingCheckpoints or {}
        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        local youP = tonumber(driftgod.S.driftChallengeLivePoints or 0) or 0
        local youS = tonumber(driftgod.S.driftChallengeLiveStunts or 0) or 0
        local youC = tonumber(driftgod.S.driftChallengeLiveCollisions or 0) or 0
        driftgod.DrawText("YOU  PTS " .. tostring(youP) .. "   STUNTS " .. tostring(youS) .. "   COLLISIONS " .. tostring(youC), 0.50, 0.095, 0.255, 255,255,255,230,4)
        driftgod.DrawText("RIVAL  PTS " .. tostring(driftgod.S.driftChallengeTargetPoints or 0) .. "   STUNTS " .. tostring(driftgod.S.driftChallengeTargetStunts or 0) .. "   COLLISIONS <= " .. tostring(driftgod.S.driftChallengeTargetCollisions or 0), 0.50, 0.125, 0.235, 166,94,252,235,4)
        if #cps > 0 then
            driftgod.DrawText("CHECKPOINT " .. tostring(math.min(idx, #cps)) .. " / " .. tostring(#cps) .. "   DIST " .. tostring(driftgod.S.driftChallengeNextCheckpointDistance or "--"), 0.50, 0.155, 0.235, 255,230,80,230,4)
        end
        driftgod.DrawText(tostring(driftgod.S.driftChallengePositionDebug or "") .. " | " .. tostring(driftgod.S.driftChallengeLastDeltaDebug or ""), 0.50, 0.190, 0.17, 180,180,180,170,4)
    end
    if (tonumber(driftgod.S.driftChallengeResultVisibleUntil or 0) or 0) > now then
        local result = driftgod.S.driftChallengeLastResult or {}
        local elapsed = now - (tonumber(driftgod.S.driftChallengeResultStartMs or now) or now)
        if elapsed < 2600 then
            if result.won == true then driftgod.DrawText("You Won!", 0.50, 0.345, 0.86, 120,255,180,255,7)
            else driftgod.DrawText("You Failed!", 0.50, 0.345, 0.86, 255,70,70,255,7) end
        else
            driftgod.DrawText("RIVAL", 0.38, 0.300, 0.36, 166,94,252,255,7)
            driftgod.DrawText(tostring(result.rival or driftgod.S.driftChallengeRivalName or "Rival"), 0.54, 0.300, 0.36, 255,255,255,255,7)
            driftgod.DrawText("Rival Points: " .. tostring(result.targetPoints or 0) .. "     You: " .. tostring(result.points or 0), 0.50, 0.355, 0.32, 255,255,255,245,4)
            driftgod.DrawText("Rival Stunts: " .. tostring(result.targetStunts or 0) .. "     You: " .. tostring(result.stunts or 0), 0.50, 0.395, 0.32, 255,255,255,245,4)
            driftgod.DrawText("Rival Collisions <= " .. tostring(result.targetCollisions or 0) .. "     You: " .. tostring(result.collisions or 0), 0.50, 0.435, 0.32, 255,255,255,245,4)
            driftgod.DrawText(tostring(result.phrase or ""), 0.50, 0.490, 0.285, 166,94,252,225,4)
        end
    end
    return true
end

function driftgod.DrawDriftChallengeHudOnPresent()

    return true
end

function driftgod.SafeFinishDriftChallengeRaceButton()
    local ok, result = driftgod.Try(function() return driftgod.FinishDriftChallengeRace("force complete") end)
    if not ok and driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("Finish Drift Challenge error: " .. tostring(result)) end
