driftgod.S.driftChallengePatchVersion = "v6.13.62A10"

function driftgod.DriftChallengeA12EnsureDefaults()
    if driftgod.DriftChallengeA10EnsureDefaults then driftgod.Try(driftgod.DriftChallengeA10EnsureDefaults) end
    driftgod.S = driftgod.S or {}
    driftgod.S.driftChallengePatchVersion = "v6.13.62A13R1"
    driftgod.S.driftChallengeDetectorMode = "PLAYER_PED_TO_VEHICLE_A12"
    driftgod.S.driftChallengePlayerOnlyRadius = tonumber(driftgod.S.driftChallengePlayerOnlyRadius or 56.0) or 56.0
    if driftgod.S.driftChallengePlayerOnlyRadius < 48.0 then driftgod.S.driftChallengePlayerOnlyRadius = 56.0 end
    driftgod.S.driftChallengeCountdownDurationMs = 4300
    driftgod.S.driftChallengeResultVisibleMs = 12000
    driftgod.S.driftChallengeA12PrevX = driftgod.S.driftChallengeA12PrevX or nil
    driftgod.S.driftChallengeA12PrevY = driftgod.S.driftChallengeA12PrevY or nil
    driftgod.S.driftChallengeA12PrevZ = driftgod.S.driftChallengeA12PrevZ or nil
    driftgod.S.driftChallengeUiLastDrawMs = tonumber(driftgod.S.driftChallengeUiLastDrawMs or 0) or 0
end

function driftgod.A12ToNumber(v)
    local n = tonumber(v)
    if n then return n end
    return nil
end

function driftgod.A12VecParts(v)
    if not v then return nil end
    local x,y,z
    if type(v) == "table" then
        x = tonumber(v.x or v.X or v[1]); y = tonumber(v.y or v.Y or v[2]); z = tonumber(v.z or v.Z or v[3]) or 0.0
    else
        driftgod.Try(function() x = tonumber(v.x or v.X) end)
        driftgod.Try(function() y = tonumber(v.y or v.Y) end)
        driftgod.Try(function() z = tonumber(v.z or v.Z) end)
        if (not x or not y) and driftgod.GetVectorPartsSafe then
            local ok, vx, vy, vz = driftgod.Try(driftgod.GetVectorPartsSafe, v)
            if ok and vx and vy then x,y,z = vx,vy,vz or 0.0 end
        end
    end
    if x and y then return x,y,z or 0.0 end
    return nil
end

function driftgod.GetA12LocalPlayerId()
    local pid = nil
    driftgod.Try(function() if GTA and GTA.GetLocalPlayerId then pid = tonumber(GTA.GetLocalPlayerId()) end end)
    if pid ~= nil then return pid end
    driftgod.Try(function() if PLAYER and PLAYER.PLAYER_ID then pid = tonumber(PLAYER.PLAYER_ID()) end end)
    if pid ~= nil then return pid end
    driftgod.Try(function() if Natives and Natives.InvokeInt then pid = tonumber(Natives.InvokeInt(0x4F8644AF03D0E0D6)) end end)
    return tonumber(pid or 0) or 0
end

function driftgod.GetA12LocalPlayerPedHandle()
    local ped = 0
    local pid = driftgod.GetA12LocalPlayerId and driftgod.GetA12LocalPlayerId() or 0

    driftgod.Try(function()
        if Natives and Natives.InvokeInt and pid ~= nil then
            ped = tonumber(Natives.InvokeInt(0x50FAC3A3E030A6E1, pid) or 0) or 0
        end
    end)
    if ped ~= 0 then return ped, "GET_PLAYER_PED_SCRIPT_INDEX" end

    driftgod.Try(function()
        if Natives and Natives.InvokeInt and pid ~= nil then
            ped = tonumber(Natives.InvokeInt(0x43A66C31C68491C0, pid) or 0) or 0
        end
    end)
    if ped ~= 0 then return ped, "GET_PLAYER_PED" end

    driftgod.Try(function() if PLAYER and PLAYER.PLAYER_PED_ID then ped = tonumber(PLAYER.PLAYER_PED_ID() or 0) or 0 end end)
    if ped ~= 0 then return ped, "PLAYER.PLAYER_PED_ID" end
    driftgod.Try(function() if Natives and Natives.InvokeInt then ped = tonumber(Natives.InvokeInt(0xD80958FC74E988A6) or 0) or 0 end end)
    if ped ~= 0 then return ped, "PLAYER_PED_ID_NATIVE" end

    driftgod.Try(function()
        if GTA and GTA.GetLocalPed and GTA.PointerToHandle then
            local p = GTA.GetLocalPed()
            if p then ped = tonumber(GTA.PointerToHandle(p) or 0) or 0 end
        end
    end)
    if ped ~= 0 then return ped, "GTA.GetLocalPed" end

    return 0, "no_ped"
end

function driftgod.GetA12VehicleFromPed(ped)
    ped = tonumber(ped or 0) or 0
    if ped == 0 then return 0, "no_ped" end
    local veh = 0
    driftgod.Try(function() if PED and PED.GET_VEHICLE_PED_IS_IN then veh = tonumber(PED.GET_VEHICLE_PED_IS_IN(ped, false) or 0) or 0 end end)
    if veh ~= 0 then return veh, "PED.GET_VEHICLE_PED_IS_IN" end
    driftgod.Try(function() if Natives and Natives.InvokeInt then veh = tonumber(Natives.InvokeInt(0x9A9112A0FE9A4713, ped, false) or 0) or 0 end end)
    if veh ~= 0 then return veh, "GET_VEHICLE_PED_IS_IN_NATIVE" end
    return 0, "no_vehicle"
end

function driftgod.IsA12GhostVehicleHandle(handle)
    handle = tonumber(handle or 0) or 0
    if handle == 0 then return false end
    if driftgod.IsA9GhostVehicleHandle and driftgod.IsA9GhostVehicleHandle(handle) then return true end
    local names = {
        "ghostReplayPreviewVehicle", "ghostPreviewVehicle", "ghostRecordedPlaybackVehicle",
        "ghostRecordingPlaybackVehicle", "ghostPlaybackVehicle", "driftChallengeGhostVehicle",
        "ghostReplayVehicle", "ghostVehicle"
    }
    for _, key in ipairs(names) do
        if tonumber(driftgod.S and driftgod.S[key] or 0) == handle then return true end
        if tonumber(DG[key] or 0) == handle then return true end
    end
    return false
end

function driftgod.GetA12CoordsFromHandle(ent)
    ent = tonumber(ent or 0) or 0
    if ent == 0 then return nil end

    if ENTITY and ENTITY.GET_ENTITY_COORDS then
        local ok, c = driftgod.Try(function() return ENTITY.GET_ENTITY_COORDS(ent, true) end)
        if ok and c then
            local x,y,z = driftgod.A12VecParts(c)
            if x and y then return x,y,z or 0.0,"ENTITY.GET_ENTITY_COORDS" end
        end
    end

    if Natives and Natives.InvokeV3 then
        local ok, x, y, z = driftgod.Try(Natives.InvokeV3, 0x3FEF770D40960D5A, ent, true)
        if ok then
            if tonumber(x) and tonumber(y) then return tonumber(x), tonumber(y), tonumber(z) or 0.0, "InvokeV3_xyz" end
            local vx,vy,vz = driftgod.A12VecParts(x)
            if vx and vy then return vx,vy,vz or 0.0, "InvokeV3_vec" end
        end
    end

    if driftgod.GetEntityCoordsForRecording then
        local ok, x, y, z = driftgod.Try(function() return driftgod.GetEntityCoordsForRecording(ent) end)
        if ok and tonumber(x) and tonumber(y) and not (math.abs(tonumber(x)) < 0.001 and math.abs(tonumber(y)) < 0.001) then
            return tonumber(x), tonumber(y), tonumber(z) or 0.0, "GetEntityCoordsForRecording"
        end
    end
    return nil
end

function driftgod.GetDriftChallengePlayerPosition()
    driftgod.DriftChallengeA12EnsureDefaults()
    local ped, pedSrc = driftgod.GetA12LocalPlayerPedHandle()
    local veh, vehSrc = driftgod.GetA12VehicleFromPed(ped)

    if veh ~= 0 and not driftgod.IsA12GhostVehicleHandle(veh) then
        local x,y,z,src = driftgod.GetA12CoordsFromHandle(veh)
        if x and y then
            driftgod.S.driftChallengeA12PrevX = driftgod.S.driftChallengeLastPlayerX
            driftgod.S.driftChallengeA12PrevY = driftgod.S.driftChallengeLastPlayerY
            driftgod.S.driftChallengeA12PrevZ = driftgod.S.driftChallengeLastPlayerZ
            driftgod.S.driftChallengeLastPlayerX, driftgod.S.driftChallengeLastPlayerY, driftgod.S.driftChallengeLastPlayerZ = x,y,z or 0.0
            driftgod.S.driftChallengePositionDebug = "A13R1 playerVeh=" .. tostring(veh) .. " src=" .. tostring(src) .. " x=" .. tostring(math.floor(x)) .. " y=" .. tostring(math.floor(y))
            return x,y,z or 0.0,"player_vehicle"
        end
    elseif veh ~= 0 then
        driftgod.S.driftChallengePositionDebug = "A13R1 rejected ghost veh=" .. tostring(veh) .. " ped=" .. tostring(ped)
    end

    if ped ~= 0 then
        local x,y,z,src = driftgod.GetA12CoordsFromHandle(ped)
        if x and y then
            driftgod.S.driftChallengeA12PrevX = driftgod.S.driftChallengeLastPlayerX
            driftgod.S.driftChallengeA12PrevY = driftgod.S.driftChallengeLastPlayerY
            driftgod.S.driftChallengeA12PrevZ = driftgod.S.driftChallengeLastPlayerZ
            driftgod.S.driftChallengeLastPlayerX, driftgod.S.driftChallengeLastPlayerY, driftgod.S.driftChallengeLastPlayerZ = x,y,z or 0.0
            driftgod.S.driftChallengePositionDebug = "A13R1 ped=" .. tostring(ped) .. " pedSrc=" .. tostring(pedSrc) .. " coord=" .. tostring(src) .. " x=" .. tostring(math.floor(x)) .. " y=" .. tostring(math.floor(y))
            return x,y,z or 0.0,"player_ped"
        end
    end

    driftgod.S.driftChallengePositionDebug = "A13R1 position failed | ped=" .. tostring(ped) .. " " .. tostring(pedSrc) .. " veh=" .. tostring(veh) .. " " .. tostring(vehSrc)
    return nil
end

function driftgod.DriftChallengeDistanceToCheckpoint(cp)
    driftgod.DriftChallengeA12EnsureDefaults()
    if type(cp) ~= "table" then return 999999.0 end
    local x,y,z,src = driftgod.GetDriftChallengePlayerPosition()
    if not x then return 999999.0 end
    local cx,cy,cz = tonumber(cp.x or cp.X or 0) or 0, tonumber(cp.y or cp.Y or 0) or 0, tonumber(cp.z or cp.Z or 0) or 0
    local dx,dy,dz = x-cx, y-cy, (z or 0)-cz
    local d2 = math.sqrt(dx*dx + dy*dy)
    driftgod.S.driftChallengeLastDistanceFloat = d2
    driftgod.S.driftChallengeLastDeltaDebug = "A13R1 d2=" .. tostring(math.floor(d2)) .. " dx=" .. tostring(math.floor(dx)) .. " dy=" .. tostring(math.floor(dy)) .. " src=" .. tostring(src)
    return d2
end

function driftgod.DriftChallengeSegmentCrossedCheckpointA12(cp)
    if type(cp) ~= "table" then return false end
    local curX, curY = tonumber(driftgod.S.driftChallengeLastPlayerX), tonumber(driftgod.S.driftChallengeLastPlayerY)
    local oldX, oldY = tonumber(driftgod.S.driftChallengeA12PrevX), tonumber(driftgod.S.driftChallengeA12PrevY)
    if not curX or not curY or not oldX or not oldY then return false end
    if math.abs(oldX) < 0.001 and math.abs(oldY) < 0.001 then return false end
    local cx, cy = tonumber(cp.x or cp.X or 0) or 0, tonumber(cp.y or cp.Y or 0) or 0
    local abx, aby = curX-oldX, curY-oldY
    local acx, acy = cx-oldX, cy-oldY
    local ab2 = abx*abx + aby*aby
    if ab2 <= 0.001 then return false end
    local t = (acx*abx + acy*aby)/ab2
    if t < 0 then t = 0 elseif t > 1 then t = 1 end
    local px, py = oldX + abx*t, oldY + aby*t
    local dx,dy = px-cx, py-cy
    local d = math.sqrt(dx*dx + dy*dy)
    local r = tonumber(driftgod.S.driftChallengePlayerOnlyRadius or 56.0) or 56.0
    driftgod.S.driftChallengeLastSegmentDebug = "A13R1 seg=" .. tostring(math.floor(d)) .. " r=" .. tostring(math.floor(r))
    return d <= r
end

function driftgod.CaptureDriftChallengePlayerVehicleA10(reason)
    driftgod.DriftChallengeA12EnsureDefaults()
    local ped, pedSrc = driftgod.GetA12LocalPlayerPedHandle()
    local veh, vehSrc = driftgod.GetA12VehicleFromPed(ped)
    if veh ~= 0 and driftgod.IsA12GhostVehicleHandle(veh) then veh = 0 end
    driftgod.S.driftChallengePlayerPedHandle = ped
    driftgod.S.driftChallengePlayerRaceVehicle = veh
    driftgod.S.driftChallengePlayerVehicleCaptureStatus = "A13R1 ped=" .. tostring(ped) .. "(" .. tostring(pedSrc) .. ") veh=" .. tostring(veh) .. "(" .. tostring(vehSrc) .. ") " .. tostring(reason or "")
    driftgod.S.driftChallengeA12PrevX, driftgod.S.driftChallengeA12PrevY, driftgod.S.driftChallengeA12PrevZ = nil,nil,nil
    driftgod.S.driftChallengeLastPlayerX, driftgod.S.driftChallengeLastPlayerY, driftgod.S.driftChallengeLastPlayerZ = nil,nil,nil
    return veh ~= 0
end

function driftgod.StartDriftChallengeCountdown()
    driftgod.DriftChallengeA12EnsureDefaults()
    if (not driftgod.S.ghostRecordingNodes or #(driftgod.S.ghostRecordingNodes or {}) <= 0) and driftgod.LoadSelectedSavedRecording then
        driftgod.Try(driftgod.LoadSelectedSavedRecording)
    end
    driftgod.CaptureDriftChallengePlayerVehicleA10("A13R1 countdown")
    driftgod.S.driftChallengeRaceStartScore = driftgod.GetDriftChallengeLiveScore and driftgod.GetDriftChallengeLiveScore() or 0
    driftgod.S.driftChallengeRaceStartStunts = driftgod.GetDriftChallengeLiveStunts and driftgod.GetDriftChallengeLiveStunts() or 0
    driftgod.S.driftChallengeRaceStartCollisions = driftgod.DriftChallengeGetCollisionTotalA10 and driftgod.DriftChallengeGetCollisionTotalA10() or 0
    driftgod.S.driftChallengeCountdownActive = true
    driftgod.S.driftChallengeActive = false
    driftgod.S.driftChallengeResultVisibleUntil = 0
    driftgod.S.driftChallengeCountdownStartMs = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    driftgod.S.driftChallengeCheckpointIndex = 1
    driftgod.S.driftChallengeStatus = "3...2...1...GO"
    if (tonumber(driftgod.S.ghostRecordingCheckpointCount or 0) or 0) <= 0 and driftgod.BuildAutoDriftChallengeCheckpointsFromNodes then driftgod.Try(driftgod.BuildAutoDriftChallengeCheckpointsFromNodes) end
    if driftgod.CreateDriftChallengeCheckpointBlips then driftgod.Try(driftgod.CreateDriftChallengeCheckpointBlips) end
    if driftgod.UpdateDriftChallengeRouteBlip then driftgod.Try(driftgod.UpdateDriftChallengeRouteBlip) end
    if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.Try(function() driftgod.RefreshDriftChallengeNativeCheckpoint(true) end) end
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("A13R1 Drift Challenge countdown started") end
    return true
end

function driftgod.ActivateDriftChallengeRace()
    driftgod.DriftChallengeA12EnsureDefaults()
    driftgod.CaptureDriftChallengePlayerVehicleA10("A13R1 activate")
    driftgod.S.driftChallengeCountdownActive = false
    driftgod.S.driftChallengeActive = true
    driftgod.S.driftChallengeStatus = "Race Active"
    driftgod.S.driftChallengeRaceStartMs = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    driftgod.S.driftChallengeLivePoints = 0
    driftgod.S.driftChallengeLiveStunts = 0
    driftgod.S.driftChallengeLiveCollisions = 0
    if driftgod.StartDriftChallengeGhostPlaybackJob then driftgod.Try(driftgod.StartDriftChallengeGhostPlaybackJob) end
    if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.Try(function() driftgod.RefreshDriftChallengeNativeCheckpoint(true) end) end
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("A13R1 Drift Challenge race active") end
    return true
end

function driftgod.GetDriftChallengeCountdownTextA12()
    if driftgod.S.driftChallengeCountdownActive ~= true then return "" end
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    local start = tonumber(driftgod.S.driftChallengeCountdownStartMs or now) or now
    local elapsed = now - start
    if elapsed < 1000 then return "3" end
    if elapsed < 2000 then return "2" end
    if elapsed < 3000 then return "1" end
    if elapsed < 4300 then return "GO!" end
    return ""
end

function driftgod.TickDriftChallengeRace()
    driftgod.DriftChallengeA12EnsureDefaults()
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0

    if driftgod.S.driftChallengeCountdownActive == true then
        if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.Try(function() driftgod.RefreshDriftChallengeNativeCheckpoint(false) end) end
        local elapsed = now - (tonumber(driftgod.S.driftChallengeCountdownStartMs or now) or now)
        if elapsed >= 4300 then driftgod.ActivateDriftChallengeRace() end
        return true
    end

    if driftgod.S.driftChallengeActive == true then
        driftgod.S.driftChallengeLivePoints = driftgod.GetDriftChallengeLiveScore and driftgod.GetDriftChallengeLiveScore() or tonumber(driftgod.S.driftChallengeLivePoints or 0) or 0
        driftgod.S.driftChallengeLiveStunts = driftgod.GetDriftChallengeLiveStunts and driftgod.GetDriftChallengeLiveStunts() or tonumber(driftgod.S.driftChallengeLiveStunts or 0) or 0
        driftgod.S.driftChallengeLiveCollisions = driftgod.GetDriftChallengeLiveCollisions and driftgod.GetDriftChallengeLiveCollisions() or tonumber(driftgod.S.driftChallengeLiveCollisions or 0) or 0

        local checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
        if #checkpoints <= 0 and driftgod.BuildAutoDriftChallengeCheckpointsFromNodes then
            driftgod.Try(driftgod.BuildAutoDriftChallengeCheckpointsFromNodes)
            checkpoints = driftgod.S.ghostRecordingCheckpoints or {}
            if driftgod.CreateDriftChallengeCheckpointBlips then driftgod.Try(driftgod.CreateDriftChallengeCheckpointBlips) end
        end

        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        local cp = checkpoints[idx]
        if cp then
            if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.Try(function() driftgod.RefreshDriftChallengeNativeCheckpoint(false) end) end
            local dist = driftgod.DriftChallengeDistanceToCheckpoint(cp) or 999999.0
            driftgod.S.driftChallengeNextCheckpointDistance = math.floor(tonumber(dist or 999999) or 999999)
            local crossed = driftgod.DriftChallengeSegmentCrossedCheckpointA13R1 and driftgod.DriftChallengeSegmentCrossedCheckpointA12(cp) or false
            local radius = tonumber(driftgod.S.driftChallengePlayerOnlyRadius or 56.0) or 56.0
            if crossed == true or dist <= radius then
                return driftgod.ClearCurrentDriftChallengeCheckpointA7(crossed and "A13R1 player segment" or ("A13R1 player distance " .. tostring(math.floor(dist))))
            end
        elseif #checkpoints > 0 then
            return driftgod.FinishDriftChallengeRace("all checkpoints cleared")
        end
    end
    return true
end

function driftgod.FinishDriftChallengeRace(reason)
    driftgod.DriftChallengeA12EnsureDefaults()
    if driftgod.ClearDriftChallengeCheckpointBlips then driftgod.Try(function() driftgod.ClearDriftChallengeCheckpointBlips("finish A12") end) end
    if driftgod.DeleteDriftChallengeNativeCheckpoint then driftgod.Try(function() driftgod.DeleteDriftChallengeNativeCheckpoint("finish A12") end) end
    local result = driftgod.MakeDriftChallengeResultA8 and driftgod.MakeDriftChallengeResultA8(reason or "manual") or { won=false, rival="Rival", points=0, stunts=0, collisions=0, targetPoints=0, targetStunts=0, targetCollisions=0 }
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    driftgod.S.driftChallengeLastResult = result
    driftgod.S.driftChallengeActive = false
    driftgod.S.driftChallengeCountdownActive = false
    driftgod.S.driftChallengeResultStartMs = now
    driftgod.S.driftChallengeResultVisibleUntil = now + (tonumber(driftgod.S.driftChallengeResultVisibleMs or 12000) or 12000)
    driftgod.S.driftChallengeStatus = result.won and "You Won" or "You Failed"
    if driftgod.WriteDriftChallengeResultLog then driftgod.Try(function() driftgod.WriteDriftChallengeResultLog(result) end) end
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("A13R1 Drift Challenge result | won=" .. tostring(result.won) .. " | reason=" .. tostring(reason)) end
    return true
end

function driftgod.SafeStartDriftChallengeRaceButton()
    local ok, err = driftgod.Try(function() return driftgod.StartDriftChallengeCountdown() end)
    if not ok and driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("A13R1 Start Drift Challenge error: " .. tostring(err)) end
    return ok == true
end

function driftgod.SafeFinishDriftChallengeRaceButton()
    local ok, err = driftgod.Try(function() return driftgod.FinishDriftChallengeRace("force complete") end)
    if not ok and driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("A13R1 Finish Drift Challenge error: " .. tostring(err)) end
    return ok == true
end

function driftgod.DrawDriftChallengeHud()
    if not driftgod.DrawText then return true end
    driftgod.DriftChallengeA12EnsureDefaults()
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0

    if driftgod.S.driftChallengeCountdownActive == true then
        local txt = driftgod.GetDriftChallengeCountdownTextA12()
        if txt ~= "" then
            local size = txt == "GO!" and 1.22 or 1.54
            local r,g,b = 255,255,255
            if txt == "GO!" then r,g,b = 120,255,180 end
            driftgod.DrawText(txt, 0.50, 0.34, size, r,g,b,255,7)
        end
    end

    if driftgod.S.driftChallengeActive == true then
        local cps = driftgod.S.ghostRecordingCheckpoints or {}
        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        local youP = math.floor(tonumber(driftgod.S.driftChallengeLivePoints or 0) or 0)
        local youS = math.floor(tonumber(driftgod.S.driftChallengeLiveStunts or 0) or 0)
        local youC = math.floor(tonumber(driftgod.S.driftChallengeLiveCollisions or 0) or 0)
        driftgod.DrawText("YOU   POINTS " .. tostring(youP) .. "   STUNTS " .. tostring(youS) .. "   COLLISIONS " .. tostring(youC), 0.50, 0.090, 0.245, 255,255,255,235,4)
        driftgod.DrawText("RIVAL POINTS " .. tostring(driftgod.S.driftChallengeTargetPoints or 0) .. "   STUNTS " .. tostring(driftgod.S.driftChallengeTargetStunts or 0) .. "   COLLISIONS <= " .. tostring(driftgod.S.driftChallengeTargetCollisions or 0), 0.50, 0.120, 0.225, 166,94,252,235,4)
        if #cps > 0 then
            driftgod.DrawText("CHECKPOINT " .. tostring(math.min(idx, #cps)) .. " / " .. tostring(#cps) .. "   DIST " .. tostring(driftgod.S.driftChallengeNextCheckpointDistance or "--"), 0.50, 0.150, 0.225, 255,230,80,235,4)
        end
        driftgod.DrawText(tostring(driftgod.S.driftChallengePositionDebug or "") .. " | " .. tostring(driftgod.S.driftChallengeLastDeltaDebug or ""), 0.50, 0.180, 0.155, 190,190,190,175,4)
    end

    if (tonumber(driftgod.S.driftChallengeResultVisibleUntil or 0) or 0) > now then
        local result = driftgod.S.driftChallengeLastResult or {}
        local won = result.won == true
        driftgod.DrawText(won and "YOU WON" or "YOU FAILED", 0.50, 0.285, 0.62, won and 120 or 255, won and 255 or 70, won and 180 or 70, 255, 7)
        driftgod.DrawText("RIVAL", 0.405, 0.350, 0.34, 166,94,252,255,7)
        driftgod.DrawText(tostring(result.rival or driftgod.S.driftChallengeRivalName or "Rival"), 0.555, 0.350, 0.34, 255,255,255,255,7)
        driftgod.DrawText("Drift Score        Rival " .. tostring(result.targetPoints or 0) .. "        You " .. tostring(result.points or 0), 0.50, 0.405, 0.285, 255,255,255,245,4)
        driftgod.DrawText("# of Stunts        Rival " .. tostring(result.targetStunts or 0) .. "        You " .. tostring(result.stunts or 0), 0.50, 0.445, 0.285, 255,255,255,245,4)
        driftgod.DrawText("# of Collisions    Rival <= " .. tostring(result.targetCollisions or 0) .. "        You " .. tostring(result.collisions or 0), 0.50, 0.485, 0.285, 255,255,255,245,4)
        driftgod.DrawText(tostring(result.phrase or ""), 0.50, 0.540, 0.255, 166,94,252,225,4)
    end
    return true
end

