if false and Script and Script.RegisterLooped and not driftgod._DriftChallengeA12LoopInstalled then
    driftgod._DriftChallengeA12LoopInstalled = true
    Script.RegisterLooped(function()
        local ok, err = driftgod.Try(function()
            if driftgod.TickDriftChallengeRace then driftgod.TickDriftChallengeRace() end
            if driftgod.DrawDriftChallengeHud then driftgod.DrawDriftChallengeHud() end
        end)
        if not ok and driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("A13R1 race loop error: " .. tostring(err)) end
        if Script and Script.Yield then Script.Yield(0) end
    end)
end

driftgod.S = driftgod.S or {}
driftgod.S.driftChallengePatchVersion = "v1.0.0"
driftgod.S.ghostRecordedZOffset = 0.0
driftgod.S.driftChallengeGhostFadeDelayMs = 60000
driftgod.S.driftChallengeGhostFadeDurationMs = 10000
driftgod.S.driftChallengeHudUseOnPresentOnly = true
driftgod.S.driftChallengeResultVisibleMs = 14000

function driftgod.GetDriftChallengeGhostHandleA14()
    driftgod.S = driftgod.S or {}
    local keys = {
        "driftChallengeGhostVehicle",
        "ghostRecordedPlaybackVehicle",
        "ghostRecordingPlaybackVehicle",
        "ghostReplayPreviewVehicle",
        "ghostPreviewVehicle",
        "ghostPlaybackVehicle",
        "ghostReplayVehicle",
        "ghostVehicle"
    }
    for _, key in ipairs(keys) do
        local h = tonumber(driftgod.S[key] or 0) or 0
        if h ~= 0 then return h, key end
    end
    return 0, "none"
end

function driftgod.SetDriftChallengeGhostAlphaA14(alpha, visible)
    local veh, key = driftgod.GetDriftChallengeGhostHandleA14()
    if veh == 0 then return false end
    alpha = math.max(0, math.min(255, math.floor(tonumber(alpha or 145) or 145)))
    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_ALPHA then ENTITY.SET_ENTITY_ALPHA(veh, alpha, false)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(0x44A0870B7E92D7C0, veh, alpha, false) end
    end)
    if visible ~= nil then
        driftgod.Try(function()
            if ENTITY and ENTITY.SET_ENTITY_VISIBLE then ENTITY.SET_ENTITY_VISIBLE(veh, visible == true, false)
            elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(0xEA1C610A04DB6BBB, veh, visible == true, false) end
        end)
    end
    driftgod.S.driftChallengeGhostFadeLast = "alpha=" .. tostring(alpha) .. " veh=" .. tostring(veh) .. " key=" .. tostring(key)
    return true
end

function driftgod.ResetDriftChallengeGhostForRaceA14(reason)
    driftgod.S = driftgod.S or {}
    driftgod.S.driftChallengeGhostPlaybackQueued = false
    driftgod.S.driftChallengeGhostPlaybackStarted = false
    driftgod.S.driftChallengeGhostPlaybackStatus = "Ready"
    driftgod.S.driftChallengeGhostFadeArmed = false
    driftgod.S.driftChallengeGhostFadeStartMs = 0
    driftgod.S.driftChallengeGhostFadeDone = false
    driftgod.S.ghostReplayStopRequested = false
    driftgod.SetDriftChallengeGhostAlphaA14(145, true)
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("A14 race ghost reset | " .. tostring(reason or "")) end
    return true
end

local DG_Pre62A14_StartCountdown = driftgod.StartDriftChallengeCountdown
function driftgod.StartDriftChallengeCountdown()
    if driftgod.ResetDriftChallengeGhostForRaceA14 then driftgod.ResetDriftChallengeGhostForRaceA14("countdown start") end
    local ok = false
    if DG_Pre62A14_StartCountdown then ok = DG_Pre62A14_StartCountdown() == true end

    if ok == true then
        driftgod.S.driftChallengeCountdownActive = true
        driftgod.S.driftChallengeActive = false
        driftgod.S.driftChallengeCountdownStartMs = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
        driftgod.S.driftChallengeStatus = "Countdown"
        driftgod.S.driftChallengeResultVisibleUntil = 0
        if driftgod.EnsureDriftChallengeGhostReady then driftgod.Try(driftgod.EnsureDriftChallengeGhostReady) end
        driftgod.SetDriftChallengeGhostAlphaA14(145, true)
    end
    return ok == true
end

local DG_Pre62A14_ActivateRace = driftgod.ActivateDriftChallengeRace
function driftgod.ActivateDriftChallengeRace()
    driftgod.S = driftgod.S or {}
    driftgod.S.driftChallengeGhostPlaybackQueued = false
    driftgod.S.driftChallengeGhostPlaybackStarted = false
    driftgod.S.ghostReplayStopRequested = false
    local ok = DG_Pre62A14_ActivateRace and DG_Pre62A14_ActivateRace() or true
    driftgod.S.driftChallengeActive = true
    driftgod.S.driftChallengeCountdownActive = false
    driftgod.S.driftChallengeStatus = "Race Active"
    driftgod.SetDriftChallengeGhostAlphaA14(145, true)

    if driftgod.StartDriftChallengeGhostPlaybackJob then driftgod.Try(driftgod.StartDriftChallengeGhostPlaybackJob) end
    return ok ~= false
end

local DG_Pre62A14_FinishRace = driftgod.FinishDriftChallengeRace
function driftgod.FinishDriftChallengeRace(reason)
    local ok = DG_Pre62A14_FinishRace and DG_Pre62A14_FinishRace(reason or "manual") or true
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    driftgod.S.driftChallengeGhostFadeArmed = true
    driftgod.S.driftChallengeGhostFadeStartMs = now + (tonumber(driftgod.S.driftChallengeGhostFadeDelayMs or 60000) or 60000)
    driftgod.S.driftChallengeGhostFadeDone = false
    driftgod.S.driftChallengeStatus = tostring(driftgod.S.driftChallengeStatus or "Race Complete") .. " | ghost fades in 60s"
    return ok ~= false
end

function driftgod.TickDriftChallengeGhostFadeA14()
    driftgod.S = driftgod.S or {}
    if driftgod.S.driftChallengeGhostFadeArmed ~= true or driftgod.S.driftChallengeGhostFadeDone == true then return false end
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    local startMs = tonumber(driftgod.S.driftChallengeGhostFadeStartMs or 0) or 0
    if startMs <= 0 or now < startMs then return false end
    local dur = tonumber(driftgod.S.driftChallengeGhostFadeDurationMs or 10000) or 10000
    local progress = dur > 0 and math.max(0, math.min(1, (now - startMs) / dur)) or 1
    local alpha = math.floor(145 * (1.0 - progress))
    driftgod.SetDriftChallengeGhostAlphaA14(alpha, alpha > 0)
    if progress >= 1 then
        driftgod.S.driftChallengeGhostFadeDone = true
        driftgod.S.driftChallengeGhostFadeArmed = false
    end
    return true
end

local DG_Pre62A14_TickRace = driftgod.TickDriftChallengeRace
function driftgod.TickDriftChallengeRace()
    if DG_Pre62A14_TickRace then driftgod.Try(DG_Pre62A14_TickRace) end
    if driftgod.TickDriftChallengeGhostFadeA14 then driftgod.Try(driftgod.TickDriftChallengeGhostFadeA14) end
    return true
end

