end

function driftgod.DrawDriftChallengeHudOnPresent()
    if not DG or not driftgod.S then return end
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or 0
    local showResult = (tonumber(driftgod.S.driftChallengeResultVisibleUntil or 0) or 0) > now
    if driftgod.S.driftChallengeCountdownActive ~= true and driftgod.S.driftChallengeActive ~= true and not showResult then return end

    local sw, sh = 1920, 1080
    driftgod.Try(function()
        if ImGui and ImGui.GetDisplaySize then
            local w,h = ImGui.GetDisplaySize()
            if w and h and w > 0 and h > 0 then sw, sh = w, h end
        end
    end)
    local cx = sw * 0.5

    if driftgod.S.driftChallengeCountdownActive == true then
        local txt = driftgod.GetDriftChallengeCountdownTextA12 and driftgod.GetDriftChallengeCountdownTextA12() or (driftgod.GetDriftChallengeCountdownText and driftgod.GetDriftChallengeCountdownText() or "")
        if txt ~= "" then
            local width = #txt * (txt == "GO!" and 34 or 28)
            local r,g,b = 255,255,255
            if txt == "GO!" then r,g,b = 120,255,180 end
            driftgod.PresentAddTextA14(cx - width, sh * 0.33, r,g,b,255, txt)
        end
    end

    if driftgod.S.driftChallengeActive == true then
        local cps = driftgod.S.ghostRecordingCheckpoints or {}
        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        local youP = math.floor(tonumber(driftgod.S.driftChallengeLivePoints or 0) or 0)
        local youS = math.floor(tonumber(driftgod.S.driftChallengeLiveStunts or 0) or 0)
        local youC = math.floor(tonumber(driftgod.S.driftChallengeLiveCollisions or 0) or 0)
        local rivalP = math.floor(tonumber(driftgod.S.driftChallengeTargetPoints or 0) or 0)
        local rivalS = math.floor(tonumber(driftgod.S.driftChallengeTargetStunts or 0) or 0)
        local rivalC = math.floor(tonumber(driftgod.S.driftChallengeTargetCollisions or 0) or 0)
        local x = 34
        local y = 78
        driftgod.PresentAddTextA14(x, y, 166,94,252,245, "DRIFT CHALLENGE")
        driftgod.PresentAddTextA14(x, y + 28, 255,255,255,235, "YOU     POINTS " .. tostring(youP) .. "   STUNTS " .. tostring(youS) .. "   COLLISIONS " .. tostring(youC))
        driftgod.PresentAddTextA14(x, y + 54, 210,185,255,235, "RIVAL   POINTS " .. tostring(rivalP) .. "   STUNTS " .. tostring(rivalS) .. "   COLLISIONS <= " .. tostring(rivalC))
        if #cps > 0 then
            driftgod.PresentAddTextA14(x, y + 80, 255,230,80,235, "CHECKPOINT " .. tostring(math.min(idx, #cps)) .. " / " .. tostring(#cps) .. "   DIST " .. tostring(driftgod.S.driftChallengeNextCheckpointDistance or "--"))
        end
        local ghostStatus = tostring(driftgod.S.driftChallengeGhostPlaybackStatus or "")
        if ghostStatus ~= "" then driftgod.PresentAddTextA14(x, y + 106, 180,180,180,185, "GHOST " .. ghostStatus) end
    end

    if showResult then
        local result = driftgod.S.driftChallengeLastResult or {}
        local won = result.won == true
        driftgod.PresentAddTextA14(cx - 95, sh * 0.285, won and 120 or 255, won and 255 or 70, won and 180 or 70, 255, won and "YOU WON" or "YOU FAILED")
        driftgod.PresentAddTextA14(cx - 135, sh * 0.350, 166,94,252,255, "RIVAL")
        driftgod.PresentAddTextA14(cx - 30, sh * 0.350, 255,255,255,255, tostring(result.rival or driftgod.S.driftChallengeRivalName or "Rival"))
        driftgod.PresentAddTextA14(cx - 245, sh * 0.405, 255,255,255,245, "Drift Score        Rival " .. tostring(result.targetPoints or 0) .. "        You " .. tostring(result.points or 0))
        driftgod.PresentAddTextA14(cx - 245, sh * 0.445, 255,255,255,245, "# of Stunts        Rival " .. tostring(result.targetStunts or 0) .. "        You " .. tostring(result.stunts or 0))
        driftgod.PresentAddTextA14(cx - 245, sh * 0.485, 255,255,255,245, "# of Collisions    Rival <= " .. tostring(result.targetCollisions or 0) .. "        You " .. tostring(result.collisions or 0))
        driftgod.PresentAddTextA14(cx - 245, sh * 0.540, 166,94,252,225, tostring(result.phrase or ""))
        if driftgod.S.driftChallengeGhostFadeArmed == true then
            driftgod.PresentAddTextA14(cx - 245, sh * 0.575, 180,180,180,190, "Ghost replay fades out after 60 seconds.")
        end
    end
end

driftgod.Try(function()
    if driftgod.S and driftgod.S.driftChallengeHudPresentRegistered ~= true and driftgod.RegisterDriftChallengeHudOnPresentA7 then
        driftgod.RegisterDriftChallengeHudOnPresentA7()
    end
end)

driftgod.S = driftgod.S or {}
driftgod.S.driftChallengeHudUseOnPresentOnly = false
driftgod.S.ghostRecordedZOffset = 0.0
driftgod.S.driftChallengePlaybackZOffset = 0.0

local function DG_A15_Log(msg)
    if DG and driftgod.GhostReplayImportant then driftgod.GhostReplayImportant('[A15] ' .. tostring(msg)) end
end

function driftgod.DriftA15NowMs()
    local ms = 0
    driftgod.Try(function() if Time and Time.GetEpocheMs then ms = tonumber(Time.GetEpocheMs() or 0) or 0 end end)
    if ms == 0 then driftgod.Try(function() if os and os.clock then ms = math.floor((os.clock() or 0) * 1000) end end) end
    return ms
end

function driftgod.DriftA15FileNameOnly(path)
    path = tostring(path or '')
    return path:match('([^\\/]+)$') or path
end

function driftgod.DriftA15SelectSavedPath(path)
    path = tostring(path or driftgod.S.ghostRecordingLastSavePath or '')
    if path == '' then return false end
    local file = driftgod.DriftA15FileNameOnly(path)
    if driftgod.RegisterSavedGhostRecording then driftgod.Try(driftgod.RegisterSavedGhostRecording, path, file) end
    if driftgod.ScanSavedGhostRecordings then driftgod.Try(driftgod.ScanSavedGhostRecordings) end
    local list = driftgod.S.savedGhostRecordings or {}
    for i, item in ipairs(list) do
        if tostring(item.path or '') == path or tostring(item.file or '') == file then
            driftgod.S.savedGhostRecordingIndex = i
            driftgod.S.savedGhostRecordingSelectedFile = item.file or file
            driftgod.S.savedGhostRecordingSelectedName = item.name or file
            driftgod.S.driftChallengeCurrentRecordingPath = item.path or path
            driftgod.S.driftChallengeCurrentRecordingFile = item.file or file
            return true
        end
    end
    driftgod.S.savedGhostRecordingIndex = 1
    driftgod.S.savedGhostRecordingSelectedFile = file
    driftgod.S.savedGhostRecordingSelectedName = file
    driftgod.S.driftChallengeCurrentRecordingPath = path
    driftgod.S.driftChallengeCurrentRecordingFile = file
    return true
end

function driftgod.DriftA15LoadCurrentSavedRecording()
    local path = tostring(driftgod.S.driftChallengeCurrentRecordingPath or driftgod.S.ghostRecordingLastSavePath or '')
    if path ~= '' and driftgod.LoadSavedGhostRecordingFromPath then
        local ok = false
        driftgod.Try(function() ok = driftgod.LoadSavedGhostRecordingFromPath(path) == true end)
        if ok then
            driftgod.DriftA15SelectSavedPath(path)
            return true
        end
    end
    if driftgod.LoadSelectedSavedGhostRecording then
        local ok = false
        driftgod.Try(function() ok = driftgod.LoadSelectedSavedGhostRecording() == true end)
        return ok
    end
    return false
end

local DG_A15_PreStopSimple = driftgod.StopGhostSimpleRecording
function driftgod.StopGhostSimpleRecording()
    local stopped = false
    if DG_A15_PreStopSimple then
        driftgod.Try(function() stopped = DG_A15_PreStopSimple() == true end)
    else
        driftgod.S.ghostRecordingActive = false
        stopped = true
    end

    local saved = false
    if driftgod.SaveCurrentGhostRecordingSimple then
        driftgod.Try(function() saved = driftgod.SaveCurrentGhostRecordingSimple() == true end)
    elseif driftgod.SaveRecordedGhostJson then
        driftgod.Try(function() saved = driftgod.SaveRecordedGhostJson() == true end)
    end

    if saved == true then
        driftgod.S.ghostSimpleFlowStatus = 'Stopped + Auto-Saved'
        driftgod.DriftA15SelectSavedPath(driftgod.S.ghostRecordingLastSavePath)
        driftgod.DriftA15LoadCurrentSavedRecording()
        DG_A15_Log('Auto-saved stopped recording and selected it | file=' .. tostring(driftgod.S.savedGhostRecordingSelectedFile or ''))
    else
        driftgod.S.ghostSimpleFlowStatus = 'Stopped; auto-save failed'
        DG_A15_Log('Auto-save after stop failed | status=' .. tostring(driftgod.S.ghostRecordingLastSaveStatus or ''))
    end

    return stopped == true or saved == true
end

local DG_A15_PreSaveSimple = driftgod.SaveCurrentGhostRecordingSimple
function driftgod.SaveCurrentGhostRecordingSimple()
    local ok = false
    if DG_A15_PreSaveSimple then
        driftgod.Try(function() ok = DG_A15_PreSaveSimple() == true end)
    elseif driftgod.SaveRecordedGhostJson then
        driftgod.Try(function() ok = driftgod.SaveRecordedGhostJson() == true end)
    end
    if ok == true then
        driftgod.DriftA15SelectSavedPath(driftgod.S.ghostRecordingLastSavePath)
        driftgod.DriftA15LoadCurrentSavedRecording()
        driftgod.S.ghostSimpleFlowStatus = 'Saved + Selected Current'
    end
    return ok == true
end

function driftgod.DeleteSelectedSavedGhostRecording()
    if driftgod.GhostSavedRecordingEnsureDefaults then driftgod.GhostSavedRecordingEnsureDefaults() end
    local item = nil
    if driftgod.GetSelectedSavedGhostRecording then driftgod.Try(function() item = driftgod.GetSelectedSavedGhostRecording() end) end
    if not item then
        local list = driftgod.S.savedGhostRecordings or {}
        item = list[tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1]
    end
    if not item then
        driftgod.S.savedGhostRecordingLoadStatus = 'Delete failed: no selected recording'
        return false
    end
    local path = tostring(item.path or '')
    if path == '' and driftgod.GetGhostRecordingSaveDir then
        path = tostring(driftgod.GetGhostRecordingSaveDir()) .. tostring(item.file or '')
    end
    local ok = false
    if path ~= '' then
        ok = os.remove(path) == true
    end
    if ok then
        driftgod.S.savedGhostRecordingLoadStatus = 'Deleted ' .. tostring(item.file or driftgod.DriftA15FileNameOnly(path))
        driftgod.S.driftChallengeCurrentRecordingPath = ''
        driftgod.S.driftChallengeCurrentRecordingFile = ''
        if driftgod.ScanSavedGhostRecordings then driftgod.Try(driftgod.ScanSavedGhostRecordings) end
        DG_A15_Log('Deleted saved recording | path=' .. tostring(path))
        return true
    end
    driftgod.S.savedGhostRecordingLoadStatus = 'Delete failed: ' .. tostring(item.file or path)
    DG_A15_Log('Delete saved recording failed | path=' .. tostring(path))
    return false
end
function driftgod.SafeDeleteSelectedSavedGhostRecordingButton()
    local ok, res = driftgod.Try(driftgod.DeleteSelectedSavedGhostRecording)
    if not ok then DG_A15_Log('Delete selected recording error: ' .. tostring(res)) end
    return ok and res == true
end

function driftgod.RemoveDriftChallengeGhostBlipA15(reason)
    local blip = tonumber(driftgod.S.driftChallengeGhostBlip or 0) or 0
    if blip ~= 0 then
        driftgod.Try(function() Natives.InvokeVoid(0x86A652570E5F25DD, blip) end)
    end
    driftgod.S.driftChallengeGhostBlip = 0
end

function driftgod.GetDriftChallengeGhostVehicleA15()
    local candidates = {
        driftgod.S.ghostReplayPreviewVehicle,
        driftgod.S.ghostRecordedPlaybackVehicle,
        driftgod.S.ghostRecordingPlaybackVehicle,
        driftgod.S.ghostPlaybackVehicle,
        driftgod.S.driftChallengeGhostVehicle,
        driftgod.S.ghostPreviewVehicle,
    }
    for _, v in ipairs(candidates) do
        local h = tonumber(v or 0) or 0
        if h ~= 0 then
            local exists = false
            driftgod.Try(function() exists = Natives.InvokeBool(0x7239B21A38F536BA, h) == true end)
            if exists then return h end
        end
    end
    return 0
end

function driftgod.AttachRedGhostCarBlipA15()
    local veh = driftgod.GetDriftChallengeGhostVehicleA15()
    if veh == 0 then return false end
    if (tonumber(driftgod.S.driftChallengeGhostBlip or 0) or 0) ~= 0 then return true end
    local blip = 0
    driftgod.Try(function() blip = Natives.InvokeInt(0x5CDE92C702A8FCE7, veh) end)
    if blip and blip ~= 0 then
        driftgod.S.driftChallengeGhostBlip = blip
        driftgod.Try(function() Natives.InvokeVoid(0xDF735600A4696DAF, blip, 225) end)
        driftgod.Try(function() Natives.InvokeVoid(0x03D7FB09E75D6B7E, blip, 1) end)
        driftgod.Try(function() Natives.InvokeVoid(0xD38744167B2FA257, blip, 0.85) end)
        DG_A15_Log('Red ghost car blip attached | veh=' .. tostring(veh) .. ' | blip=' .. tostring(blip))
        return true
    end
    return false
end

local DG_A15_PrePrepare = driftgod.PrepareSelectedDriftChallenge
function driftgod.PrepareSelectedDriftChallenge()
    if driftgod.DriftChallengeEnsureDefaults then driftgod.DriftChallengeEnsureDefaults() end

    driftgod.DriftA15LoadCurrentSavedRecording()

    local ok = false
    if DG_A15_PrePrepare then driftgod.Try(function() ok = DG_A15_PrePrepare() == true end) end
    if ok ~= true then ok = driftgod.DriftA15LoadCurrentSavedRecording() == true end

    if driftgod.SpawnRecordedGhostPreviewStable then driftgod.Try(driftgod.SpawnRecordedGhostPreviewStable)
    elseif driftgod.SpawnRecordedGhostPreview then driftgod.Try(driftgod.SpawnRecordedGhostPreview) end
    if driftgod.MoveRecordedGhostToStart then driftgod.Try(driftgod.MoveRecordedGhostToStart) end
    driftgod.S.driftChallengeGhostPlaybackQueued = false
    driftgod.S.driftChallengeGhostPlaybackStarted = false
    driftgod.S.driftChallengeGhostPlaybackStatus = 'Prepared'
    driftgod.RemoveDriftChallengeGhostBlipA15('prepare refresh')
    driftgod.AttachRedGhostCarBlipA15()
    driftgod.S.driftChallengeStatus = 'Prepared: ' .. tostring(driftgod.S.driftChallengeRivalName or driftgod.S.savedGhostRecordingSelectedName or 'Rival')
    return ok == true
end

local DG_A15_PreStartRace = driftgod.StartDriftChallengeRace
-- ═══════════════════════════════════════════════════════════════════════════════════
-- ghost race start
-- note: starts the race countdown after the saved ghost has been prepared.
-- ═══════════════════════════════════════════════════════════════════════════════════

function driftgod.StartDriftChallengeRace()

    if driftgod.GetDriftChallengeGhostVehicleA15() == 0 then
        driftgod.Try(function() if driftgod.SpawnRecordedGhostPreviewStable then driftgod.SpawnRecordedGhostPreviewStable() elseif driftgod.SpawnRecordedGhostPreview then driftgod.SpawnRecordedGhostPreview() end end)
        if driftgod.MoveRecordedGhostToStart then driftgod.Try(driftgod.MoveRecordedGhostToStart) end
    end
    driftgod.AttachRedGhostCarBlipA15()
    driftgod.S.driftChallengeGhostPlaybackQueued = false
    driftgod.S.driftChallengeGhostPlaybackStarted = false
    driftgod.S.driftChallengeGhostPlaybackStatus = 'Waiting for GO'
    driftgod.S.driftChallengeCountdownActive = false
    local ok = false
    if DG_A15_PreStartRace then driftgod.Try(function() ok = DG_A15_PreStartRace() == true end) end
    return ok == true
end

function driftgod.DrawDriftChallengeHud()
    if not DG or not driftgod.S or not driftgod.DrawText then return end
    local now = driftgod.DriftChallengeNowMs and driftgod.DriftChallengeNowMs() or driftgod.DriftA15NowMs()
    local showResult = (tonumber(driftgod.S.driftChallengeResultVisibleUntil or 0) or 0) > now
    if driftgod.S.driftChallengeCountdownActive ~= true and driftgod.S.driftChallengeActive ~= true and not showResult then return end

    if driftgod.S.driftChallengeCountdownActive == true then
        local txt = driftgod.GetDriftChallengeCountdownTextA12 and driftgod.GetDriftChallengeCountdownTextA12() or (driftgod.GetDriftChallengeCountdownText and driftgod.GetDriftChallengeCountdownText() or '')
        if txt ~= '' then
            local r,g,b = 255,255,255
            if txt == 'GO!' then r,g,b = 120,255,180 end
            driftgod.DrawText(txt, 0.50, 0.33, txt == 'GO!' and 1.15 or 1.35, r,g,b,255,4)
        end
    end

    if driftgod.S.driftChallengeActive == true then
        local youP = math.floor(tonumber(driftgod.S.driftChallengeLivePoints or 0) or 0)
        local youS = math.floor(tonumber(driftgod.S.driftChallengeLiveStunts or 0) or 0)
        local youC = math.floor(tonumber(driftgod.S.driftChallengeLiveCollisions or 0) or 0)
        local rivalP = math.floor(tonumber(driftgod.S.driftChallengeTargetPoints or 0) or 0)
        local rivalS = math.floor(tonumber(driftgod.S.driftChallengeTargetStunts or 0) or 0)
        local rivalC = math.floor(tonumber(driftgod.S.driftChallengeTargetCollisions or 0) or 0)
        local cps = driftgod.S.ghostRecordingCheckpoints or {}
        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        if driftgod.DrawRect then
            driftgod.DrawRect(0.175, 0.145, 0.310, 0.135, 5,4,12,120)
            driftgod.DrawRect(0.175, 0.080, 0.280, 0.006, 166,94,252,190)
        end
        driftgod.DrawText('DRIFT CHALLENGE', 0.035, 0.055, 0.34, 166,94,252,245,4)
        driftgod.DrawText('YOU     POINTS ' .. tostring(youP) .. '   STUNTS ' .. tostring(youS) .. '   COLLISIONS ' .. tostring(youC), 0.035, 0.090, 0.27, 255,255,255,230,4)
        driftgod.DrawText('RIVAL   POINTS ' .. tostring(rivalP) .. '   STUNTS ' .. tostring(rivalS) .. '   COLLISIONS <= ' .. tostring(rivalC), 0.035, 0.122, 0.27, 210,185,255,230,4)
        driftgod.DrawText('CHECKPOINT ' .. tostring(math.min(idx, #cps)) .. ' / ' .. tostring(#cps) .. '   DIST ' .. tostring(driftgod.S.driftChallengeNextCheckpointDistance or '--'), 0.035, 0.154, 0.25, 255,230,80,225,4)
        local gs = tostring(driftgod.S.driftChallengeGhostPlaybackStatus or '')
        if gs ~= '' then driftgod.DrawText('GHOST ' .. gs, 0.035, 0.184, 0.22, 180,180,180,190,4) end
    end

    if showResult then
        local result = driftgod.S.driftChallengeLastResult or {}
        local won = result.won == true
        if driftgod.DrawRect then
            driftgod.DrawRect(0.50, 0.405, 0.500, 0.260, 5,4,12,145)
            driftgod.DrawRect(0.50, 0.280, 0.430, 0.007, 166,94,252,210)
        end
        driftgod.DrawText(won and 'YOU WON' or 'YOU FAILED', 0.50, 0.275, 0.62, won and 120 or 255, won and 255 or 70, won and 180 or 70, 255,4)
        driftgod.DrawText('RIVAL', 0.435, 0.335, 0.38, 166,94,252,255,4)
        driftgod.DrawText(tostring(result.rival or driftgod.S.driftChallengeRivalName or 'Rival'), 0.525, 0.335, 0.38, 255,255,255,255,4)
        driftgod.DrawText('Drift Score        Rival ' .. tostring(result.targetPoints or 0) .. '        You ' .. tostring(result.points or 0), 0.50, 0.390, 0.31, 255,255,255,240,4)
        driftgod.DrawText('# of Stunts        Rival ' .. tostring(result.targetStunts or 0) .. '        You ' .. tostring(result.stunts or 0), 0.50, 0.430, 0.31, 255,255,255,240,4)
        driftgod.DrawText('# of Collisions    Rival <= ' .. tostring(result.targetCollisions or 0) .. '        You ' .. tostring(result.collisions or 0), 0.50, 0.470, 0.31, 255,255,255,240,4)
        driftgod.DrawText(tostring(result.phrase or ''), 0.50, 0.530, 0.30, 166,94,252,225,4)
    end
end

driftgod.Try(function()
    if Script and Script.RegisterLooped and not driftgod.S.driftChallengeGhostBlipLoopA15 then
