    local ms = 0
    driftgod.Try(function() if Time and Time.GetEpocheMs then ms = tonumber(Time.GetEpocheMs() or 0) or 0 end end)
    if ms == 0 then driftgod.Try(function() if os and os.clock then ms = math.floor((os.clock() or 0) * 1000) end end) end
