function driftgod.DriftA16Log(msg)
    if driftgod.S and driftgod.S.driftChallengeVerboseLogsA16 == true then
        if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant('[A16] ' .. tostring(msg))
        elseif Logger and Logger.LogInfo then Logger.LogInfo('[DriftGod][A16] ' .. tostring(msg)) end
    end
end

function driftgod.DriftA16Toast(title, msg, ms)
    title = tostring(title or 'Drift Challenge')
    msg = tostring(msg or '')
    driftgod.Try(function()
        if GUI and GUI.AddToast then GUI.AddToast(title, msg, tonumber(ms or 1200) or 1200, eToastPos.TOP_RIGHT)
        elseif driftgod.Toast then driftgod.Toast(title .. ': ' .. msg, tonumber(ms or 1200) or 1200) end
    end)
end

function driftgod.HideDriftChallengeGhostA16(reason)
    local hidden = 0
    local candidates = {
        'driftChallengeGhostVehicle',
        'ghostReplayPreviewVehicle',
        'ghostRecordedPlaybackVehicle',
        'ghostRecordingPlaybackVehicle',
        'ghostPlaybackVehicle',
        'ghostPreviewVehicle',
        'ghostReplayVehicle',
        'ghostVehicle'
    }
    for _, key in ipairs(candidates) do
        local veh = tonumber(driftgod.S[key] or 0) or 0
        if veh ~= 0 then
            local exists = false
            driftgod.Try(function() exists = Natives and Natives.InvokeBool and Natives.InvokeBool(0x7239B21A38F536BA, veh) == true end)
            if exists then

                driftgod.Try(function() if Natives and Natives.InvokeVoid then Natives.InvokeVoid(0x44A0870B7E92D7C0, veh, 0, false) end end)
                driftgod.Try(function() if Natives and Natives.InvokeVoid then Natives.InvokeVoid(0xEA1C610A04DB6BBB, veh, false, false) end end)
                hidden = hidden + 1
            end
        end
        driftgod.S[key] = 0
    end
    if driftgod.ClearGhostPreviewTrackingOnly then driftgod.Try(function() driftgod.ClearGhostPreviewTrackingOnly() end) end
    driftgod.DriftA16Log('Hidden/cleared old ghost handles | hidden=' .. tostring(hidden) .. ' | reason=' .. tostring(reason or ''))
    return true
end

function driftgod.CleanupDriftChallengeRaceArtifactsA16(reason)
    driftgod.S = driftgod.S or {}
    if driftgod.ClearDriftChallengeCheckpointBlips then driftgod.Try(function() driftgod.ClearDriftChallengeCheckpointBlips('A16 ' .. tostring(reason or 'cleanup')) end) end
    if driftgod.DeleteDriftChallengeNativeCheckpoint then driftgod.Try(function() driftgod.DeleteDriftChallengeNativeCheckpoint('A16 ' .. tostring(reason or 'cleanup')) end) end
    if driftgod.RemoveDriftChallengeGhostBlipA15 then driftgod.Try(function() driftgod.RemoveDriftChallengeGhostBlipA15('A16 ' .. tostring(reason or 'cleanup')) end) end
    driftgod.S.driftChallengeCheckpointRouteBlip = 0
    driftgod.S.driftChallengeCheckpointBlips = {}
    driftgod.S.driftChallengeNativeCheckpointHandle = 0
    driftgod.S.driftChallengeNativeCheckpointIndex = 0
    driftgod.S.driftChallengeGhostBlip = 0
    driftgod.S.driftChallengeCountdownLastToast = ''
    driftgod.S.driftChallengeLastMenuStatus = 'Cleaned race artifacts: ' .. tostring(reason or 'cleanup')
    driftgod.DriftA16Log('Cleaned race artifacts | reason=' .. tostring(reason or ''))
    return true
end

local DG_Pre62A16_PrepareSelectedDriftChallenge = driftgod.PrepareSelectedDriftChallenge
function driftgod.PrepareSelectedDriftChallenge()
    driftgod.CleanupDriftChallengeRaceArtifactsA16('prepare new race')
    driftgod.HideDriftChallengeGhostA16('prepare new race')
    local ok = false
    if DG_Pre62A16_PrepareSelectedDriftChallenge then
        local success, res = driftgod.Try(function() return DG_Pre62A16_PrepareSelectedDriftChallenge() end)
        ok = success and res == true
        if not success then driftgod.DriftA16Log('Prepare pre-wrapper error: ' .. tostring(res)) end
    end

    if ok == true then
        if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.Try(function() driftgod.RefreshDriftChallengeNativeCheckpoint(true) end) end
        if driftgod.CreateDriftChallengeCheckpointBlips then driftgod.Try(function() driftgod.CreateDriftChallengeCheckpointBlips() end) end
