    else
        driftgod.S.driftChallengeLastMenuStatus = 'Prepare failed after cleanup'
    end
    driftgod.DriftA16Log('Prepare complete | ok=' .. tostring(ok) .. ' | ghost=' .. tostring(driftgod.GetDriftChallengeGhostVehicleA15 and driftgod.GetDriftChallengeGhostVehicleA15() or 0) .. ' | checkpointBlips=' .. tostring(type(driftgod.S.driftChallengeCheckpointBlips)=='table' and #driftgod.S.driftChallengeCheckpointBlips or 0))
    return ok == true
end

