function driftgod.A17R1FileNameOnly(path)
    path = tostring(path or ""):gsub("/", "\\"):gsub("\r", ""):gsub("\n", "")
    return path:match("([^\\]+)$") or path
end

function driftgod.A17R1NormalizePath(path)
    path = tostring(path or ""):gsub("/", "\\"):gsub("\r", ""):gsub("\n", "")
    return path
end

function driftgod.A17R1EnsureSlash(dir)
    dir = driftgod.A17R1NormalizePath(dir)
    if dir ~= "" and dir:sub(-1) ~= "\\" then dir = dir .. "\\" end
    return dir
end

function driftgod.A17R1AddSavedRecording(out, seen, dir, fileOrPath, source)
    out = out or {}
    seen = seen or {}
    dir = driftgod.A17R1EnsureSlash(dir)
    fileOrPath = driftgod.A17R1NormalizePath(fileOrPath)
    if fileOrPath == "" then return false end
    if not fileOrPath:lower():match("%.json$") then return false end

    local file = driftgod.A17R1FileNameOnly(fileOrPath)
    if file == "" or file:sub(1, 1) == "_" then return false end

    local path = fileOrPath
    if not path:find(":") and not path:find("\\") then
        path = dir .. file
    end
    path = driftgod.A17R1NormalizePath(path)

    local key = tostring(path ~= "" and path or file):lower()
    if seen[key] then return false end
    seen[key] = true

    table.insert(out, {
        file = file,
        path = path,
        name = file,
        displayName = file,
        source = source or "unknown",
    })
    return true
end

function driftgod.A17R1ScanWithDirCommand(dir)
    local out, seen = {}, {}
    dir = driftgod.A17R1EnsureSlash(dir)
    if dir == "" then return out, "empty dir" end

    local patterns = {
        'dir /a-d /b "' .. dir .. '*.json"',
        'cmd /c dir /a-d /b "' .. dir .. '*.json"',
    }

    local lastErr = nil
    for _, cmd in ipairs(patterns) do
        local ok, pipe = driftgod.Try(function() return io.popen(cmd) end)
        if ok and pipe then
            for line in pipe:lines() do
                line = tostring(line or ""):gsub("\r", ""):gsub("\n", "")
                driftgod.A17R1AddSavedRecording(out, seen, dir, line, "dir")
            end
            driftgod.Try(function() pipe:close() end)
            if #out > 0 then
                table.sort(out, function(a, b) return tostring(a.file):lower() < tostring(b.file):lower() end)
                return out, nil
            end
        else
            lastErr = "io.popen failed for " .. tostring(cmd)
        end
    end

    return out, lastErr or "dir returned no json files"
end

function driftgod.A17R1ScanIndexAndLastSaved(dir, seen)
    local out = {}
    seen = seen or {}
    dir = driftgod.A17R1EnsureSlash(dir)

    local function readText(path)
        path = tostring(path or "")
        if path == "" then return nil end
        if driftgod.ReadTextFileSafe then
            local ok, txt = driftgod.Try(function() return driftgod.ReadTextFileSafe(path) end)
            if ok and txt and txt ~= "" then return txt end
        end
        if driftgod.ReadTextFile then
            local ok, txt = driftgod.Try(function() return driftgod.ReadTextFile(path) end)
            if ok and txt and txt ~= "" then return txt end
        end
        local ok, txt = driftgod.Try(function()
            local f = io.open(path, "r")
            if not f then return nil end
            local t = f:read("*a")
            f:close()
            return t
        end)
        if ok then return txt end
        return nil
    end

    local indexPath = driftgod.GetSavedGhostIndexPath and driftgod.GetSavedGhostIndexPath() or (dir .. "_recordings_index.lua")
    local indexTxt = readText(indexPath)
    if indexTxt and indexTxt ~= "" then

        for file, path, name in indexTxt:gmatch('{%s*file="([^"]-)"%s*,%s*path="([^"]-)"%s*,%s*name="([^"]-)"%s*}') do
            path = tostring(path or ""):gsub("\\\\", "\\")
            driftgod.A17R1AddSavedRecording(out, seen, dir, path ~= "" and path or file, "index")
        end

        for quoted in indexTxt:gmatch('"([^"]+%.json)"') do
            driftgod.A17R1AddSavedRecording(out, seen, dir, quoted, "index-token")
        end
    end

    local lastPathFile = driftgod.GetLastSavedGhostPathFile and driftgod.GetLastSavedGhostPathFile() or (dir .. "_last_saved.txt")
    local lastTxt = readText(lastPathFile)
    if lastTxt and lastTxt ~= "" then
        driftgod.A17R1AddSavedRecording(out, seen, dir, lastTxt, "last_saved")
    end

    return out
end

function driftgod.A17R1SelectSavedRecordingByIndex(index)
    driftgod.GhostSavedRecordingEnsureDefaults()
    local list = driftgod.S.savedGhostRecordings or {}
    if #list <= 0 then return false end
    index = tonumber(index or driftgod.S.savedGhostRecordingIndex or 1) or 1
    if index < 1 then index = 1 end
    if index > #list then index = #list end
    driftgod.S.savedGhostRecordingIndex = index
    local item = list[index]
    if item then
        driftgod.S.savedGhostRecordingSelectedFile = tostring(item.file or "")
        driftgod.S.savedGhostRecordingSelectedName = tostring(item.displayName or item.file or item.name or "")
        driftgod.S.driftChallengeCurrentRecordingPath = tostring(item.path or driftgod.S.driftChallengeCurrentRecordingPath or "")
        driftgod.S.driftChallengeCurrentRecordingFile = tostring(item.file or driftgod.S.driftChallengeCurrentRecordingFile or "")
        return true
    end
    return false
end

function driftgod.ScanSavedGhostRecordings()
    driftgod.GhostSavedRecordingEnsureDefaults()

    local dir = driftgod.GetGhostRecordingSaveDir and driftgod.GetGhostRecordingSaveDir() or "DriftGod\\arcade\\GhostReplay\\Recordings\\"
    dir = driftgod.A17R1EnsureSlash(dir)

    local combined, seen = {}, {}
    local dirItems, dirErr = driftgod.A17R1ScanWithDirCommand(dir)
    for _, item in ipairs(dirItems or {}) do
        driftgod.A17R1AddSavedRecording(combined, seen, dir, item.path or item.file, item.source or "dir")
    end

    for _, item in ipairs(driftgod.A17R1ScanIndexAndLastSaved(dir, seen) or {}) do
        driftgod.A17R1AddSavedRecording(combined, seen, dir, item.path or item.file, item.source or "index/last")
    end

    table.sort(combined, function(a, b)
        return tostring(a.file or ""):lower() < tostring(b.file or ""):lower()
    end)

    driftgod.S.savedGhostRecordings = combined

    if #combined <= 0 then
        driftgod.S.savedGhostRecordingIndex = 1
        driftgod.S.savedGhostRecordingSelectedFile = ""
        driftgod.S.savedGhostRecordingSelectedName = ""
        driftgod.S.savedGhostRecordingScanStatus = "A17R1 found 0 recordings | dir=" .. tostring(dir) .. " | err=" .. tostring(dirErr)
        if driftgod.GhostReplayImportant then
            driftgod.GhostReplayImportant("[A17R1] Saved scan found 0 | dir=" .. tostring(dir) .. " | err=" .. tostring(dirErr))
        end
        return false
    end

    local wantedFile = tostring(driftgod.S.savedGhostRecordingSelectedFile or driftgod.S.driftChallengeCurrentRecordingFile or "")
    local wantedPath = tostring(driftgod.S.driftChallengeCurrentRecordingPath or "")
    local selectedIndex = tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1
    if wantedFile ~= "" or wantedPath ~= "" then
        for i, item in ipairs(combined) do
            if tostring(item.file or "") == wantedFile or tostring(item.path or "") == wantedPath then
                selectedIndex = i
                break
            end
        end
    end

    if selectedIndex < 1 then selectedIndex = 1 end
    if selectedIndex > #combined then selectedIndex = #combined end
    driftgod.A17R1SelectSavedRecordingByIndex(selectedIndex)

    local selected = combined[driftgod.S.savedGhostRecordingIndex]
    driftgod.S.savedGhostRecordingScanStatus = "A17R1 found " .. tostring(#combined) .. " recordings | full filenames"
    if driftgod.GhostReplayImportant then
        driftgod.GhostReplayImportant("[A17R1] Saved scan complete | count=" .. tostring(#combined)
            .. " | selected=" .. tostring(selected and selected.file or "none")
            .. " | dir=" .. tostring(dir)
            .. " | dirErr=" .. tostring(dirErr))
    end
    return true
end

function driftgod.GetSavedRecordingComboPreview()
    driftgod.GhostSavedRecordingEnsureDefaults()
    local list = driftgod.S.savedGhostRecordings or {}
    if #list <= 0 then return "No saved recordings" end
    local idx = tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1
    if idx < 1 then idx = 1 end
    if idx > #list then idx = #list end
    local item = list[idx]
    if not item then return "No saved recordings" end
    return tostring(item.displayName or item.file or item.name or "Saved Recording")
end

function driftgod.SetSavedRecordingIndex(index)
    local ok = driftgod.A17R1SelectSavedRecordingByIndex(index)
    if ok and driftgod.GhostReplayImportant then
        local item = (driftgod.S.savedGhostRecordings or {})[driftgod.S.savedGhostRecordingIndex or 1]
        driftgod.GhostReplayImportant("[A17R1] Saved recording selected | " .. tostring(driftgod.S.savedGhostRecordingIndex)
            .. "/" .. tostring(#(driftgod.S.savedGhostRecordings or {}))
            .. " | file=" .. tostring(item and item.file or "none"))
    end
    return ok
end

