function driftgod.A17R2Trim(s)
    return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

function driftgod.A17R2Norm(path)
    path = tostring(path or ""):gsub("/", "\\"):gsub("\r", ""):gsub("\n", "")
    return path
end

function driftgod.A17R2Slash(path)
    path = driftgod.A17R2Norm(path)
    if path ~= "" and path:sub(-1) ~= "\\" then path = path .. "\\" end
    return path
end

function driftgod.A17R2FileName(path)
    path = driftgod.A17R2Norm(path)
    return path:match("([^\\]+)$") or path
end

function driftgod.A17R2DirOf(path)
    path = driftgod.A17R2Norm(path)
    return path:match("^(.*\\)") or ""
end

function driftgod.A17R2ReadText(path)
    path = driftgod.A17R2Norm(path)
    if path == "" then return nil end
    if FileMgr and FileMgr.DoesFileExist and FileMgr.ReadFileContent then
        local okExists, exists = driftgod.Try(FileMgr.DoesFileExist, path)
        if okExists and exists then
            local okRead, txt = driftgod.Try(FileMgr.ReadFileContent, path)
            if okRead and txt and tostring(txt) ~= "" then return tostring(txt) end
        end
    end
    if driftgod.ReadTextFileSafe then
        local ok, txt = driftgod.Try(function() return driftgod.ReadTextFileSafe(path) end)
        if ok and txt and tostring(txt) ~= "" then return tostring(txt) end
    end
    local ok, txt = driftgod.Try(function()
        local f = io.open(path, "r")
        if not f then return nil end
        local t = f:read("*a")
        f:close()
        return t
    end)
    if ok and txt and tostring(txt) ~= "" then return tostring(txt) end
    return nil
end

function driftgod.A17R2WriteDebug(text)
    text = tostring(text or "")
    if text:gsub("%s+", "") == "" then return false end
    driftgod.S = driftgod.S or {}
    driftgod.S.savedGhostRecordingScanDebug = text
    if driftgod.GhostReplayImportant then driftgod.GhostReplayImportant("[A17R2] " .. text) end
    return true
end

function driftgod.A17R2CandidateRecordingDirs()
    local dirs, seen = {}, {}
    local function add(dir, reason)
        dir = driftgod.A17R2Slash(dir)
        if dir == "" then return end
        local key = dir:lower()
        if seen[key] then return end
        seen[key] = true
        table.insert(dirs, { dir = dir, reason = reason or "candidate" })
    end

    if DG and driftgod.Paths and driftgod.Paths.recordings then
        add(driftgod.Paths.recordings, "canonical storage recordings")
    end

    local source = ""
    driftgod.Try(function()
        if debug and debug.getinfo then source = tostring(debug.getinfo(1, "S").source or "") end
    end)
    if source:sub(1,1) == "@" then source = source:sub(2) end
    source = driftgod.A17R2Norm(source)
    local sourceDir = source:match("^(.*\\)ghost_records%.lua$")
    if sourceDir and sourceDir ~= "" then add(sourceDir .. "Recordings\\", "debug source") end

    if driftgod.GetGhostRecordingSaveDir then
        local ok, dir = driftgod.Try(driftgod.GetGhostRecordingSaveDir)
        if ok and dir then add(dir, "GetGhostRecordingSaveDir") end
    end

    local root = ""
    driftgod.Try(function()
        if FileMgr and FileMgr.GetMenuRootPath then root = tostring(FileMgr.GetMenuRootPath() or "") end
    end)
    root = driftgod.A17R2Slash(root)
    if root ~= "" then
        add(root .. "Lua\\DriftGod\\arcade\\GhostReplay\\Recordings\\", "root Lua DriftGod")
        add(root .. "DriftGod\\arcade\\GhostReplay\\Recordings\\", "root DriftGod")
        add(root .. "Lua\\arcade\\GhostReplay\\Recordings\\", "root Lua arcade")
    end

    add("DriftGod\\arcade\\GhostReplay\\Recordings\\", "relative DriftGod")
    add("Lua\\DriftGod\\arcade\\GhostReplay\\Recordings\\", "relative Lua DriftGod")
    add("arcade\\GhostReplay\\Recordings\\", "relative arcade")

    for _, cand in ipairs({
        (driftgod.GetLastSavedGhostPathFile and select(2, driftgod.Try(driftgod.GetLastSavedGhostPathFile))) or "",
        (driftgod.GetSavedGhostIndexPath and select(2, driftgod.Try(driftgod.GetSavedGhostIndexPath))) or "",
    }) do
        local d = driftgod.A17R2DirOf(cand)
        if d ~= "" then add(d, "helper sidecar") end
    end

    return dirs
end

function driftgod.A17R2AddRecording(out, seen, baseDir, fileOrPath, source)
    baseDir = driftgod.A17R2Slash(baseDir)
    fileOrPath = driftgod.A17R2Norm(fileOrPath)
    if fileOrPath == "" then return false end

    local file = driftgod.A17R2FileName(fileOrPath)
    if file == "" or not file:lower():match("%.json$") then return false end
    if file:sub(1,1) == "_" then return false end

    local path = fileOrPath
    if not path:find(":") and not path:find("\\") then path = baseDir .. file end
    path = driftgod.A17R2Norm(path)

    local key = path:lower()
    if seen[key] then return false end
    seen[key] = true
    table.insert(out, {
        file = file,
        path = path,
        name = file,
        displayName = file,
        source = source or "unknown",
    })
    return true
end

function driftgod.A17R2ScanDirWithFileMgr(dir)
    local out = {}
    if not (FileMgr and FileMgr.FindFiles) then return out, "FileMgr.FindFiles unavailable" end
    for _, recursive in ipairs({ false, true }) do
        for _, ext in ipairs({ ".json", "json" }) do
            local ok, files = driftgod.Try(FileMgr.FindFiles, dir, ext, recursive)
            if ok and type(files) == "table" then
                for _, item in pairs(files) do
                    table.insert(out, tostring(item or ""))
                end
            end
        end
    end
    return out, nil
end

function driftgod.A17R2ScanDirWithPopen(dir)
    local out = {}
    local cmds = {
        'dir /a-d /b "' .. dir .. '*.json"',
        'cmd /c dir /a-d /b "' .. dir .. '*.json"',
    }
    local lastErr = nil
    for _, cmd in ipairs(cmds) do
        local ok, pipe = driftgod.Try(function() return io.popen(cmd) end)
        if ok and pipe then
            for line in pipe:lines() do table.insert(out, tostring(line or "")) end
            driftgod.Try(function() pipe:close() end)
        else
            lastErr = "io.popen failed"
        end
    end
    return out, lastErr
end

function driftgod.A17R2ScanSidecars(dir, out, seen)
    dir = driftgod.A17R2Slash(dir)
    out = out or {}
    seen = seen or {}

    local indexPaths = {
        dir .. "_recordings_index.lua",
    }
    if driftgod.GetSavedGhostIndexPath then
        local ok, p = driftgod.Try(driftgod.GetSavedGhostIndexPath)
        if ok and p then table.insert(indexPaths, tostring(p)) end
    end

    for _, indexPath in ipairs(indexPaths) do
        local txt = driftgod.A17R2ReadText(indexPath)
        if txt and txt ~= "" then
            for file, path, name in txt:gmatch('{%s*file="([^"]-)"%s*,%s*path="([^"]-)"%s*,%s*name="([^"]-)"%s*}') do
                path = tostring(path or ""):gsub("\\\\", "\\")
                driftgod.A17R2AddRecording(out, seen, dir, path ~= "" and path or file, "index")
            end
            for quoted in txt:gmatch('"([^"]+%.json)"') do
                driftgod.A17R2AddRecording(out, seen, dir, quoted, "index-token")
            end
        end
    end

    local lastPaths = { dir .. "_last_saved.txt" }
    if driftgod.GetLastSavedGhostPathFile then
        local ok, p = driftgod.Try(driftgod.GetLastSavedGhostPathFile)
        if ok and p then table.insert(lastPaths, tostring(p)) end
    end
    for _, lastPath in ipairs(lastPaths) do
        local txt = driftgod.A17R2ReadText(lastPath)
        if txt and txt ~= "" then
            driftgod.A17R2AddRecording(out, seen, dir, driftgod.A17R2Trim(txt), "last_saved")
        end
    end

    return out
end

function driftgod.A17R2SelectSaved(index)
    driftgod.GhostSavedRecordingEnsureDefaults()
    local list = driftgod.S.savedGhostRecordings or {}
    if #list <= 0 then return false end
    index = tonumber(index or driftgod.S.savedGhostRecordingIndex or 1) or 1
    if index < 1 then index = 1 end
    if index > #list then index = #list end
    driftgod.S.savedGhostRecordingIndex = index
    local item = list[index]
    driftgod.S.savedGhostRecordingSelectedFile = tostring(item.file or "")
    driftgod.S.savedGhostRecordingSelectedName = tostring(item.displayName or item.file or item.name or "")
    driftgod.S.driftChallengeCurrentRecordingPath = tostring(item.path or "")
    driftgod.S.driftChallengeCurrentRecordingFile = tostring(item.file or "")
    return true
end

function driftgod.ScanSavedGhostRecordings()
    driftgod.GhostSavedRecordingEnsureDefaults()
    local combined, seen = {}, {}
    local attempted = {}

    for _, cand in ipairs(driftgod.A17R2CandidateRecordingDirs()) do
        local dir = driftgod.A17R2Slash(cand.dir)
        table.insert(attempted, cand.reason .. "=" .. dir)

        local fmFiles = driftgod.A17R2ScanDirWithFileMgr(dir)
        for _, item in ipairs(fmFiles or {}) do
            driftgod.A17R2AddRecording(combined, seen, dir, item, "FileMgr:" .. cand.reason)
        end

        local popenFiles = driftgod.A17R2ScanDirWithPopen(dir)
        for _, item in ipairs(popenFiles or {}) do
            driftgod.A17R2AddRecording(combined, seen, dir, item, "dir:" .. cand.reason)
        end

        driftgod.A17R2ScanSidecars(dir, combined, seen)
    end

    table.sort(combined, function(a,b) return tostring(a.file or ""):lower() < tostring(b.file or ""):lower() end)
    driftgod.S.savedGhostRecordings = combined

    if #combined <= 0 then
        driftgod.S.savedGhostRecordingIndex = 1
        driftgod.S.savedGhostRecordingSelectedFile = ""
        driftgod.S.savedGhostRecordingSelectedName = ""
        driftgod.S.savedGhostRecordingScanStatus = "A17R2 found 0 | checked " .. tostring(#attempted) .. " paths"
        driftgod.S.savedGhostRecordingScanDebug = table.concat(attempted, " | ")
        driftgod.A17R2WriteDebug("Saved scan found 0. Checked paths: " .. driftgod.S.savedGhostRecordingScanDebug)
        return false
    end

    local wantedFile = tostring(driftgod.S.savedGhostRecordingSelectedFile or driftgod.S.driftChallengeCurrentRecordingFile or "")
    local wantedPath = tostring(driftgod.S.driftChallengeCurrentRecordingPath or "")
    local selectIndex = tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1
    for i,item in ipairs(combined) do
        if (wantedFile ~= "" and tostring(item.file or "") == wantedFile)
            or (wantedPath ~= "" and tostring(item.path or "") == wantedPath) then
            selectIndex = i
            break
        end
    end
    driftgod.A17R2SelectSaved(selectIndex)
    driftgod.S.savedGhostRecordingScanStatus = "A17R2 found " .. tostring(#combined) .. " recordings"
    driftgod.S.savedGhostRecordingScanDebug = table.concat(attempted, " | ")
    local sel = combined[driftgod.S.savedGhostRecordingIndex or 1]
    driftgod.A17R2WriteDebug("Saved scan complete | count=" .. tostring(#combined)
        .. " | selected=" .. tostring(sel and sel.file or "none")
        .. " | checked=" .. tostring(#attempted) .. " paths")
    return true
end

function driftgod.GetSavedRecordingComboPreview()
    driftgod.GhostSavedRecordingEnsureDefaults()
    local list = driftgod.S.savedGhostRecordings or {}
    if #list <= 0 then return "No saved recordings" end
    local idx = tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1
    if idx < 1 then idx = 1 end
    if idx > #list then idx = #list end
    local item = list[idx]
    return tostring(item and (item.displayName or item.file or item.name) or "No saved recordings")
end

