driftgod.S.driftChallengeHudUseOnPresentOnly = true
driftgod.S.driftChallengeCheckpointBlipsEnabled = true
driftgod.S.driftChallengeCheckpointMarkerEnabled = true
driftgod.S.driftChallengeCheckpointVisualZOffset = -0.05
driftgod.S.ghostRecordedZOffset = 0.0
driftgod.S.driftChallengePlaybackZOffset = 0.0
