local function DG_A18_Log(msg)
    if DG and driftgod.GhostReplayImportant and driftgod.S and driftgod.S.driftChallengeA18VerboseLogs == true then
        driftgod.GhostReplayImportant('[A18] ' .. tostring(msg))
