function driftgod.A18NowMs()
    local ms = 0
    driftgod.Try(function() if Time and Time.GetEpocheMs then ms = tonumber(Time.GetEpocheMs() or 0) or 0 end end)
    if ms == 0 then driftgod.Try(function() if os and os.clock then ms = math.floor((os.clock() or 0) * 1000) end end) end
    return ms
end

function driftgod.A18RemoveBlip(blip, reason)
    blip = tonumber(blip or 0) or 0
    if blip == 0 or not Natives or not Natives.InvokeVoid then return false end
    driftgod.Try(function()
        if Memory and Memory.AllocInt and Memory.WriteInt and Memory.Free then
            local ptr = Memory.AllocInt()
            Memory.WriteInt(ptr, blip)
            Natives.InvokeVoid(0x86A652570E5F25DD, ptr)
            Memory.Free(ptr)
        else
            Natives.InvokeVoid(0x86A652570E5F25DD, blip)
        end
    end)
    return true
end

function driftgod.RemoveDriftChallengeGhostBlipA15(reason)
    local blip = tonumber(driftgod.S and driftgod.S.driftChallengeGhostBlip or 0) or 0
    if blip ~= 0 then driftgod.A18RemoveBlip(blip, reason or 'ghost blip remove A18') end
    driftgod.S.driftChallengeGhostBlip = 0
    return true
end

function driftgod.ClearDriftChallengeCheckpointBlips(reason)
    driftgod.S = driftgod.S or {}
    local blips = driftgod.S.driftChallengeCheckpointBlips or {}
    for _, b in ipairs(blips) do driftgod.A18RemoveBlip(b, reason or 'checkpoint blip clear A18') end
    driftgod.S.driftChallengeCheckpointBlips = {}
    driftgod.S.driftChallengeCheckpointRouteBlip = 0
    return true
end

function driftgod.A18EnsureRaceRouteArtifacts(reason)
    driftgod.S = driftgod.S or {}
    driftgod.S.driftChallengeCheckpointBlipsEnabled = true
    driftgod.S.driftChallengeCheckpointMarkerEnabled = true
    if (not driftgod.S.ghostRecordingCheckpoints or #(driftgod.S.ghostRecordingCheckpoints or {}) <= 0) and driftgod.BuildAutoDriftChallengeCheckpointsFromNodes then
        driftgod.Try(function() driftgod.BuildAutoDriftChallengeCheckpointsFromNodes() end)
    end
    local count = #(driftgod.S.ghostRecordingCheckpoints or {})
    if count > 0 then
        if driftgod.CreateDriftChallengeCheckpointBlips then driftgod.Try(function() driftgod.CreateDriftChallengeCheckpointBlips() end) end
        if driftgod.UpdateDriftChallengeRouteBlip then driftgod.Try(function() driftgod.UpdateDriftChallengeRouteBlip() end) end
        if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.Try(function() driftgod.RefreshDriftChallengeNativeCheckpoint(true) end) end
    end
    DG_A18_Log('Ensured route artifacts | reason=' .. tostring(reason or '') .. ' | checkpoints=' .. tostring(count) .. ' | blips=' .. tostring(type(driftgod.S.driftChallengeCheckpointBlips)=='table' and #driftgod.S.driftChallengeCheckpointBlips or 0) .. ' | native=' .. tostring(driftgod.S.driftChallengeNativeCheckpointHandle or 0))
    return count > 0
end

function driftgod.A18CleanRaceArtifactsForPrep(reason)
    driftgod.S = driftgod.S or {}
    if driftgod.ClearDriftChallengeCheckpointBlips then driftgod.Try(function() driftgod.ClearDriftChallengeCheckpointBlips('A18 prep ' .. tostring(reason or '')) end) end
    if driftgod.DeleteDriftChallengeNativeCheckpoint then driftgod.Try(function() driftgod.DeleteDriftChallengeNativeCheckpoint('A18 prep ' .. tostring(reason or '')) end) end
    if driftgod.RemoveDriftChallengeGhostBlipA15 then driftgod.Try(function() driftgod.RemoveDriftChallengeGhostBlipA15('A18 prep ' .. tostring(reason or '')) end) end
    driftgod.S.driftChallengeActive = false
    driftgod.S.driftChallengeCountdownActive = false
    driftgod.S.driftChallengeResultVisibleUntil = 0
    driftgod.S.driftChallengeGhostPlaybackQueued = false
    driftgod.S.driftChallengeGhostPlaybackStarted = false
    driftgod.S.ghostReplayStopRequested = false
    driftgod.S.driftChallengeCheckpointIndex = 1
    driftgod.S.driftChallengeLastHudStatus = 'Cleaned race artifacts'
    DG_A18_Log('Cleaned race artifacts | ' .. tostring(reason or ''))
    return true
end

local DG_A18_PreCreateNativeCheckpoint = driftgod.CreateDriftChallengeNativeCheckpointForIndex
function driftgod.CreateDriftChallengeNativeCheckpointForIndex(index)
    local ok = false
    if DG_A18_PreCreateNativeCheckpoint then driftgod.Try(function() ok = DG_A18_PreCreateNativeCheckpoint(index) == true end) end

    if ok ~= true then
        driftgod.S = driftgod.S or {}
        index = tonumber(index or driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        local cps = driftgod.S.ghostRecordingCheckpoints or {}
        local cp = cps[index]
        if type(cp) == 'table' and Natives and Natives.InvokeInt then
            if driftgod.DeleteDriftChallengeNativeCheckpoint then driftgod.Try(function() driftgod.DeleteDriftChallengeNativeCheckpoint('A18 minimal replace') end) end
            local zoff = tonumber(driftgod.S.driftChallengeCheckpointVisualZOffset or -0.05) or -0.05
            local nextCp = cps[index + 1] or cp
            local isFinal = index >= #cps
            local handle = 0
            driftgod.Try(function()
                handle = tonumber(Natives.InvokeInt(0x0134F0835AB6BFCB,
                    isFinal and 4 or 0,
                    (tonumber(cp.x or 0) or 0)+0.0,
                    (tonumber(cp.y or 0) or 0)+0.0,
                    (tonumber(cp.z or 0) or 0)+zoff,
                    (tonumber(nextCp.x or cp.x or 0) or 0)+0.0,
                    (tonumber(nextCp.y or cp.y or 0) or 0)+0.0,
                    (tonumber(nextCp.z or cp.z or 0) or 0)+zoff,
                    12.0,
                    isFinal and 120 or 166, isFinal and 255 or 94, isFinal and 180 or 252, 230, 0) or 0) or 0
            end)
            driftgod.S.driftChallengeNativeCheckpointHandle = handle
            driftgod.S.driftChallengeNativeCheckpointIndex = handle ~= 0 and index or 0
            ok = handle ~= 0
        end
    end
    return ok == true
end

local DG_A18_PrePrepare = driftgod.PrepareSelectedDriftChallenge
function driftgod.PrepareSelectedDriftChallenge()
    driftgod.A18CleanRaceArtifactsForPrep('prepare')
    if driftgod.DriftA15LoadCurrentSavedRecording then driftgod.Try(function() driftgod.DriftA15LoadCurrentSavedRecording() end) end
    local ok = false
    if DG_A18_PrePrepare then driftgod.Try(function() ok = DG_A18_PrePrepare() == true end) end
    if ok ~= true and driftgod.LoadSelectedSavedGhostRecording then driftgod.Try(function() ok = driftgod.LoadSelectedSavedGhostRecording() == true end) end
    if driftgod.SpawnRecordedGhostPreviewStable then driftgod.Try(function() driftgod.SpawnRecordedGhostPreviewStable() end)
    elseif driftgod.SpawnRecordedGhostPreview then driftgod.Try(function() driftgod.SpawnRecordedGhostPreview() end) end
    if driftgod.MoveRecordedGhostToStart then driftgod.Try(function() driftgod.MoveRecordedGhostToStart() end) end
    if driftgod.AttachRedGhostCarBlipA15 then driftgod.Try(function() driftgod.AttachRedGhostCarBlipA15() end) end
    driftgod.A18EnsureRaceRouteArtifacts('prepare')
    driftgod.S.driftChallengeStatus = 'Prepared: ' .. tostring(driftgod.S.savedGhostRecordingSelectedFile or driftgod.S.driftChallengeCurrentRecordingFile or driftgod.S.driftChallengeRivalName or 'Rival')
    driftgod.S.driftChallengeLastHudStatus = driftgod.S.driftChallengeStatus
    return true
end

local DG_A18_PreStartRace = driftgod.StartDriftChallengeRace
function driftgod.StartDriftChallengeRace()
    if driftgod.GetDriftChallengeGhostVehicleA15 and driftgod.GetDriftChallengeGhostVehicleA15() == 0 then
        if driftgod.SpawnRecordedGhostPreviewStable then driftgod.Try(function() driftgod.SpawnRecordedGhostPreviewStable() end)
        elseif driftgod.SpawnRecordedGhostPreview then driftgod.Try(function() driftgod.SpawnRecordedGhostPreview() end) end
        if driftgod.MoveRecordedGhostToStart then driftgod.Try(function() driftgod.MoveRecordedGhostToStart() end) end
    end
    if driftgod.AttachRedGhostCarBlipA15 then driftgod.Try(function() driftgod.AttachRedGhostCarBlipA15() end) end
    driftgod.A18EnsureRaceRouteArtifacts('start')
    local ok = false
    if DG_A18_PreStartRace then driftgod.Try(function() ok = DG_A18_PreStartRace() == true end) end

    if ok ~= true and driftgod.StartDriftChallengeCountdown then driftgod.Try(function() ok = driftgod.StartDriftChallengeCountdown() == true end) end
    return ok == true
end

local DG_A18_PreTickRace = driftgod.TickDriftChallengeRace
function driftgod.TickDriftChallengeRace()
    local ok, err = driftgod.Try(function() if DG_A18_PreTickRace then DG_A18_PreTickRace() end end)
    if not ok then DG_A18_Log('Tick wrapper error: ' .. tostring(err)) end
    if driftgod.S and (driftgod.S.driftChallengeCountdownActive == true or driftgod.S.driftChallengeActive == true) then
        if driftgod.S.driftChallengeCheckpointBlipsEnabled ~= true or #(driftgod.S.driftChallengeCheckpointBlips or {}) <= 0 then
            driftgod.A18EnsureRaceRouteArtifacts('tick rebuild')
        elseif driftgod.UpdateDriftChallengeRouteBlip then
            driftgod.Try(function() driftgod.UpdateDriftChallengeRouteBlip() end)
        end
        if driftgod.RefreshDriftChallengeNativeCheckpoint then driftgod.Try(function() driftgod.RefreshDriftChallengeNativeCheckpoint(false) end) end
    end
    return true
end

