function driftgod.A18TextWidthApprox(text, px)
    text = tostring(text or '')
    px = tonumber(px or 18) or 18
    return math.floor(#text * (px * 0.48))
end

function driftgod.A18FgText(x, y, r, g, b, a, text)
    if not ImGui then return false end
    text = tostring(text or '')
    local ok = false
    driftgod.Try(function()
        if ImGui.FgAddText then ImGui.FgAddText(x, y, r, g, b, a, text); ok = true
        elseif ImGui.BgAddText then ImGui.BgAddText(x, y, r, g, b, a, text); ok = true end
    end)
    return ok
end

function driftgod.A18DrawRaceHudOnPresent()
    if not DG or not driftgod.S then return end
    local now = driftgod.A18NowMs()
    local showResult = (tonumber(driftgod.S.driftChallengeResultVisibleUntil or 0) or 0) > now
    local active = driftgod.S.driftChallengeActive == true
    local countdown = driftgod.S.driftChallengeCountdownActive == true
    if not active and not countdown and not showResult then return end

    local sw, sh = 1920, 1080
    driftgod.Try(function()
        if ImGui and ImGui.GetDisplaySize then
            local w, h = ImGui.GetDisplaySize()
            if tonumber(w) and tonumber(h) and tonumber(w) > 0 and tonumber(h) > 0 then sw, sh = tonumber(w), tonumber(h) end
        end
    end)
    local cx = sw * 0.5

    if countdown then
        local txt = driftgod.GetDriftChallengeCountdownTextA12 and driftgod.GetDriftChallengeCountdownTextA12() or (driftgod.GetDriftChallengeCountdownText and driftgod.GetDriftChallengeCountdownText() or '')
        if txt ~= '' then
            local r,g,b = 255,255,255
            if txt == 'GO!' then r,g,b = 120,255,180 end
            local px = txt == 'GO!' and 66 or 86
            driftgod.A18FgText(cx - driftgod.A18TextWidthApprox(txt, px) * 0.5, sh * 0.315, r,g,b,255, txt)
        end
    end

    if active then
        local cps = driftgod.S.ghostRecordingCheckpoints or {}
        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        local x, y = 34, 74
        local youP = math.floor(tonumber(driftgod.S.driftChallengeLivePoints or 0) or 0)
        local youS = math.floor(tonumber(driftgod.S.driftChallengeLiveStunts or 0) or 0)
        local youC = math.floor(tonumber(driftgod.S.driftChallengeLiveCollisions or 0) or 0)
        local rivalP = math.floor(tonumber(driftgod.S.driftChallengeTargetPoints or 0) or 0)
        local rivalS = math.floor(tonumber(driftgod.S.driftChallengeTargetStunts or 0) or 0)
        local rivalC = math.floor(tonumber(driftgod.S.driftChallengeTargetCollisions or 0) or 0)
        driftgod.A18FgText(x, y, 166,94,252,245, 'DRIFT CHALLENGE')
        driftgod.A18FgText(x, y + 26, 255,255,255,235, 'YOU    PTS ' .. tostring(youP) .. '   STUNTS ' .. tostring(youS) .. '   COLLISIONS ' .. tostring(youC))
        driftgod.A18FgText(x, y + 50, 210,185,255,235, 'RIVAL  PTS ' .. tostring(rivalP) .. '   STUNTS ' .. tostring(rivalS) .. '   COLLISIONS <= ' .. tostring(rivalC))
        if #cps > 0 then
            driftgod.A18FgText(x, y + 74, 255,230,80,235, 'CHECKPOINT ' .. tostring(math.min(idx, #cps)) .. ' / ' .. tostring(#cps) .. '   DIST ' .. tostring(driftgod.S.driftChallengeNextCheckpointDistance or '--'))
        else
            driftgod.A18FgText(x, y + 74, 255,120,120,235, 'NO CHECKPOINTS FOUND - PREP REBUILDS FROM NODES')
        end
    end

    if showResult then
        local result = driftgod.S.driftChallengeLastResult or {}
        local won = result.won == true
        local main = result.didNotFinish and 'DID NOT FINISH' or (won and 'YOU WON' or 'YOU FAILED')
        driftgod.A18FgText(cx - driftgod.A18TextWidthApprox(main, 40) * 0.5, sh * 0.285, won and 120 or 255, won and 255 or 70, won and 180 or 70, 255, main)
        driftgod.A18FgText(cx - 135, sh * 0.350, 166,94,252,255, 'RIVAL')
        driftgod.A18FgText(cx - 30, sh * 0.350, 255,255,255,255, tostring(result.rival or driftgod.S.driftChallengeRivalName or 'Rival'))
        driftgod.A18FgText(cx - 245, sh * 0.405, 255,255,255,245, 'Drift Score        Rival ' .. tostring(result.targetPoints or 0) .. '        You ' .. tostring(result.points or 0))
        driftgod.A18FgText(cx - 245, sh * 0.445, 255,255,255,245, '# of Stunts        Rival ' .. tostring(result.targetStunts or 0) .. '        You ' .. tostring(result.stunts or 0))
        driftgod.A18FgText(cx - 245, sh * 0.485, 255,255,255,245, '# of Collisions    Rival <= ' .. tostring(result.targetCollisions or 0) .. '        You ' .. tostring(result.collisions or 0))
        driftgod.A18FgText(cx - 245, sh * 0.540, 166,94,252,225, tostring(result.phrase or ''))
    end
end

