function driftgod.A51R19SanitizeVehicleFileName(name)
    name = tostring(name or 'Vehicle')
    if driftgod.SanitizeGhostRecordingFileName then name = driftgod.SanitizeGhostRecordingFileName(name) end
    name = name:gsub('_+', '_'):gsub('^_+', ''):gsub('_+$', '')
    if name == '' then name = 'Vehicle' end
    return name
end

function driftgod.A51R19GetRecordingVehicleName()
    local name = nil
    driftgod.Try(function()
        if driftgod.GetVehicleMasteryName then name = driftgod.GetVehicleMasteryName() end
    end)
    if not name or tostring(name) == '' or tostring(name) == 'Current Vehicle' then
        local model = tonumber(driftgod.GetRecordedGhostModel and driftgod.GetRecordedGhostModel() or driftgod.S and driftgod.S.ghostRecordingVehicleModel or 0) or 0
        if model == 2891838741 or model == -1403128555 then name = 'Zentorno'
        elseif driftgod.ResolveVehicleNameFromKnownHash then name = driftgod.ResolveVehicleNameFromKnownHash(model) end
        if not name or tostring(name) == '' then name = 'Vehicle_' .. tostring(model ~= 0 and model or 'Run') end
    end
    return driftgod.A51R19SanitizeVehicleFileName(name)
end

function driftgod.A51R19BuildRecordingFileBase()
    local vehicle = driftgod.A51R19GetRecordingVehicleName and driftgod.A51R19GetRecordingVehicleName() or 'Vehicle'
    local stamp = os.date and os.date('%Y_%m_%d_%H%M') or 'Date_Time'
    return driftgod.A51R19SanitizeVehicleFileName(tostring(vehicle) .. '_' .. tostring(stamp))
end

