function driftgod.A51R19BuildRaceNodes2x()
    local src = driftgod.S and driftgod.S.ghostRecordingNodes or {}
    local count = tonumber(driftgod.S and (driftgod.S.ghostRecordingNodeCount or #src) or #src) or #src
    local maxNodes = math.min(#src, count)
    if maxNodes <= 2 then return src, count end
    local out = {}
    for i = 1, maxNodes, 2 do out[#out + 1] = src[i] end
    if src[maxNodes] and out[#out] ~= src[maxNodes] then out[#out + 1] = src[maxNodes] end
    return out, #out
end

function driftgod.PlayRecordedGhostSmoothRace2x()
    if not driftgod.S then return false end
    local originalNodes = driftgod.S.ghostRecordingNodes
    local originalCount = driftgod.S.ghostRecordingNodeCount
    local originalSteps = driftgod.S.ghostRecordedSmoothSteps
    local raceNodes, raceCount = driftgod.A51R19BuildRaceNodes2x()
    if type(raceNodes) ~= 'table' or raceCount <= 2 then return false end
    driftgod.S.ghostRecordingNodes = raceNodes
    driftgod.S.ghostRecordingNodeCount = raceCount
    driftgod.S.ghostRecordedSmoothSteps = 1
    driftgod.S.driftChallengeGhostPlaybackStatus = 'Playing 2x nodes'
    local ok, result = driftgod.Try(function()
        if driftgod.PlayRecordedGhostSmooth then return driftgod.PlayRecordedGhostSmooth() end
        if driftgod.PlayRecordedGhostInMemory then return driftgod.PlayRecordedGhostInMemory() end
        return false
    end)
    driftgod.S.ghostRecordingNodes = originalNodes
    driftgod.S.ghostRecordingNodeCount = originalCount
    driftgod.S.ghostRecordedSmoothSteps = originalSteps
    driftgod.S.driftChallengeGhostPlaybackStatus = (ok and result == true) and 'Complete' or 'Playback Failed'
    return ok and result == true
end

function driftgod.StartDriftChallengeGhostPlaybackJob()
    if not driftgod.S then driftgod.S = {} end
