    driftgod.S.driftChallengeGhostPlaybackStatus = 'Queued 2x nodes'
    driftgod.S.ghostReplayStopRequested = false
    local function runPlayback()
        if driftgod.EnsureDriftChallengeGhostReady then driftgod.Try(driftgod.EnsureDriftChallengeGhostReady) end
        return driftgod.PlayRecordedGhostSmoothRace2x and driftgod.PlayRecordedGhostSmoothRace2x() or false
    end
    if Script and Script.QueueJob then Script.QueueJob(runPlayback); return true end
    return runPlayback()
end

