    local start = tonumber(driftgod.S and (driftgod.S.driftChallengeCountdownStartMs or driftgod.S.driftChallengeCountdownStartedMs) or now) or now
    local elapsed = now - start
    if elapsed < 1000 then return '3' end
    if elapsed < 2000 then return '2' end
    if elapsed < 3000 then return '1' end
    if elapsed < 4200 then return 'GO!' end
    return ''
end

local DG_A51R19_PreTickRace = driftgod.TickDriftChallengeRace
