    end
    if ImGui and (ImGui.FgAddText or ImGui.BgAddText) then
        local sw, sh = 1920, 1080
        driftgod.Try(function() if ImGui.GetDisplaySize then local w,h=ImGui.GetDisplaySize(); if tonumber(w) then sw=tonumber(w) end; if tonumber(h) then sh=tonumber(h) end end end)
        local px, py = (tonumber(x or 0.5) or 0.5) * sw, (tonumber(y or 0.5) or 0.5) * sh
        driftgod.Try(function()
            if ImGui.FgAddText then ImGui.FgAddText(px, py, r or 255, g or 255, b or 255, a or 255, tostring(text or ''))
            else ImGui.BgAddText(px, py, r or 255, g or 255, b or 255, a or 255, tostring(text or '')) end
        end)
        return true
    end
    return false
end

function driftgod.DrawDriftChallengeHud()
    if not driftgod.S then return true end
