            driftgod.A51R19DrawText(txt, 0.50, 0.34, scale, r,g,b,255,7)
        end
    end
    if driftgod.S.driftChallengeActive == true then
        local cps = driftgod.S.ghostRecordingCheckpoints or {}
        local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
        driftgod.A51R19DrawText('DRIFT RACE', 0.50, 0.105, 0.34, 166,94,252,235,4)
        driftgod.A51R19DrawText('YOU: ' .. tostring(math.floor(tonumber(driftgod.S.driftChallengeLivePoints or 0) or 0)) .. ' pts  |  ' .. tostring(math.floor(tonumber(driftgod.S.driftChallengeLiveStunts or 0) or 0)) .. ' stunts', 0.50, 0.145, 0.28, 255,255,255,220,4)
        driftgod.A51R19DrawText('RIVAL: ' .. tostring(math.floor(tonumber(driftgod.S.driftChallengeTargetPoints or 0) or 0)) .. ' pts  |  ' .. tostring(math.floor(tonumber(driftgod.S.driftChallengeTargetStunts or 0) or 0)) .. ' stunts', 0.50, 0.178, 0.26, 220,220,220,205,4)
        if #cps > 0 then driftgod.A51R19DrawText('Checkpoint: ' .. tostring(math.min(idx, #cps)) .. ' / ' .. tostring(#cps), 0.50, 0.210, 0.25, 166,94,252,215,4) end
    end
    if (tonumber(driftgod.S.driftChallengeResultVisibleUntil or 0) or 0) > now then
        local result = driftgod.S.driftChallengeLastResult or {}
        local label = result.didNotFinish == true and 'DID NOT FINISH' or (result.won == true and 'YOU WON!' or 'YOU FAILED')
        local r,g,b = result.won == true and 120 or 255, result.won == true and 255 or 75, result.won == true and 180 or 75
