        driftgod.A51R19DrawText('You: ' .. tostring(result.points or 0) .. ' pts / ' .. tostring(result.stunts or 0) .. ' stunts', 0.50, 0.405, 0.33, 255,255,255,230,4)
        driftgod.A51R19DrawText('Rival: ' .. tostring(result.targetPoints or 0) .. ' pts / ' .. tostring(result.targetStunts or 0) .. ' stunts', 0.50, 0.445, 0.30, 166,94,252,230,4)
        if result.phrase and tostring(result.phrase) ~= '' then driftgod.A51R19DrawText(tostring(result.phrase), 0.50, 0.495, 0.28, 255,255,255,210,4) end
    end
    return true
end
