__DG_BUNDLE_LOADERS["core.boot"] = function()
DG = DG or {}
driftgod.Boot = driftgod.Boot or {}

local function dg_boot_now()
    if driftgod.Now then return tonumber(driftgod.Now() or 0) or 0 end
    if Time and Time.GetEpocheMs then return tonumber(Time.GetEpocheMs() or 0) or 0 end
    return math.floor(os.clock() * 1000)
end

local function dg_boot_log(msg)
    msg = tostring(msg or "")
    if msg:gsub("%s+", "") == "" then return end

    local lower = msg:lower()
    local important = lower:find("error", 1, true) ~= nil
        or lower:find("failed", 1, true) ~= nil
        or lower:find("unavailable", 1, true) ~= nil
        or lower:find("fallback", 1, true) ~= nil
        or lower:find("warning", 1, true) ~= nil

    if not important and not (driftgod.S and driftgod.S.bootDebugLogsEnabled == true) then return end

    if driftgod.Log then driftgod.Log("[Boot] " .. msg)
    elseif Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] [Boot] " .. msg)
    elseif log then log("[DriftGod] [Boot] " .. msg) end
end

local function dg_boot_yield(ms)
    if Script and Script.Yield then Script.Yield(ms or 0) end
end

local function dg_loader_set(name, progress)
    if driftgod.DriftGodStart then
        if driftgod.DriftGodStart.SetModule then driftgod.DriftGodStart.SetModule(name) end
        if driftgod.DriftGodStart.SetProgress then driftgod.DriftGodStart.SetProgress(progress or 0) end
    else
        if DriftGodLoader_SetModule then DriftGodLoader_SetModule(name) end
        if DriftGodLoader_SetProgress then DriftGodLoader_SetProgress(progress or 0) end
    end
    if driftgod.S then
        driftgod.S.bootLoadMessage = tostring(name or "Loading...")
        driftgod.S.bootLoadProgress = tonumber(progress or 0) or 0
    end
end

local function dg_load_step(name, progress, holdMs, fn)
    dg_loader_set(name, progress)
    local ok, err = driftgod.Try(fn or function() end)
    if not ok then
        dg_boot_log("[DriftGodStart] ERROR loading " .. tostring(name) .. ": " .. tostring(err))
        error(err)
    end
    dg_boot_yield(holdMs or 350)
end

function driftgod.Boot.RunNow(source, suppressIntro)
    source = tostring(source or "delayed")

    if driftgod.S then
        driftgod.S.bootLoading = true
        driftgod.S.bootReady = false
        driftgod.S.bootLoadMessage = "Loading modules..."
        driftgod.S.bootLoadProgress = 0.05
    end

    if driftgod.DebugLog and driftgod.S and driftgod.S.bootDebugLogsEnabled == true then
        driftgod.DebugLog("Boot", "driftgod.Boot.RunNow entered")
    end

    dg_load_step("Core Boot", 0.05, 420, function()
        driftgod.EnsureStorageDir()
    end)

    dg_load_step("Config / Save Data", 0.12, 520, function()
        if driftgod.LoadSettings then driftgod.LoadSettings(false) end
        if driftgod.LoadProgress then driftgod.LoadProgress(false) end
    end)

    dg_load_step("Logger / Debug Settings", 0.17, 300, function()

    end)

    dg_load_step("Native Helpers", 0.22, 360, function()
        driftgod.Try(function() require("core.natives") end)
    end)

    dg_load_step("UI Framework / Tabs", 0.34, 500, function()

    end)

    dg_load_step("Drift Engine", 0.48, 520, function()
        driftgod.Try(function() require("systems.vehicle_sectors"); if driftgod.InstallVehicleSectors then driftgod.InstallVehicleSectors("boot:drift-engine") end end)
        driftgod.Try(function() require("systems.drift") end)
        driftgod.Try(function() require("systems.scoring") end)
        driftgod.Try(function() require("systems.stunts") end)
    end)

    dg_load_step("Score / Combo / HUD", 0.58, 440, function()
        driftgod.Try(function() require("ui.hud") end)
        driftgod.Try(function() require("systems.progression") end)
    end)

    dg_load_step("Progress / Unlocks / Tiers", 0.68, 620, function()
        require("systems.progress_persistence")
        if driftgod.InstallProgressPersistence then driftgod.InstallProgressPersistence("boot:" .. source) end
        require("systems.session_challenges")
        if driftgod.InstallSessionChallenges then driftgod.InstallSessionChallenges("boot:" .. source) end
        require("systems.vehicle_mastery")
        if driftgod.InstallVehicleMastery then driftgod.InstallVehicleMastery("boot:" .. source) end
        require("systems.vehicle_sectors")
        if driftgod.InstallVehicleSectors then driftgod.InstallVehicleSectors("boot:" .. source) end
        require("systems.progress_milestones")
        if driftgod.InstallProgressMilestones then driftgod.InstallProgressMilestones("boot:" .. source) end
    end)

    dg_load_step("Banned Areas", 0.74, 420, function()
        require("systems.no_score_zones")
        if driftgod.InstallNoScoreZones then driftgod.InstallNoScoreZones() end
    end)

    dg_load_step("Ghost Replay", 0.82, 560, function()
        require("arcade.GhostReplay.ghost_records")
        if driftgod.InstallGhostReplay then driftgod.InstallGhostReplay("boot:" .. source) end
    end)

    dg_load_step("Race / Challenge", 0.90, 420, function()
        if driftgod.UpdateActiveRival then driftgod.UpdateActiveRival() end
    end)

    dg_load_step("Tips / Credits / Polish", 0.96, 360, function()

    end)

    dg_load_step("Finalizing", 0.99, 350, function()
        if driftgod.ColdBootProgressSync then driftgod.ColdBootProgressSync("boot-ready") end
    end)

    if driftgod.DriftGodStart and driftgod.DriftGodStart.Finish then
        driftgod.DriftGodStart.Finish()
    elseif DriftGodLoader_Finish then
        DriftGodLoader_Finish()
    end
    dg_loader_set("DriftGod Ready", 1.0)

    if driftgod.S then
        driftgod.S.bootLoadProgress = 1.0
        driftgod.S.bootLoadMessage = "DriftGod Ready"
        driftgod.S.bootReady = true
        driftgod.S.bootLoading = false
    end

    if Script and Script.QueueJob then
        Script.QueueJob(function()
            Script.Yield(1500)
            if driftgod.ColdBootProgressSync then driftgod.ColdBootProgressSync("boot-delayed-1.5s") end
            Script.Yield(3500)
            if driftgod.ColdBootProgressSync then driftgod.ColdBootProgressSync("boot-delayed-5s") end
        end)
    end

    if not suppressIntro and driftgod.S then
        local now = dg_boot_now()
        driftgod.S.introStartMs = now
        driftgod.S.lastScoreTick = now
        driftgod.S.lastAutoSaveMs = now
    end

    if driftgod.Toast then
        driftgod.Toast("DRIFTGOD " .. tostring(driftgod.Version) .. " loaded.", 4500)
    end

    dg_boot_log("RunNow complete | source=" .. source)
end

function driftgod.Boot.Start()
    driftgod.S = driftgod.S or {}

    if driftgod.Boot._started == true then return end
    driftgod.Boot._started = true

    local now = dg_boot_now()
    driftgod.S.bootLoading = true
    driftgod.S.bootReady = false
    driftgod.S.bootLoadStartMs = now
    driftgod.S.bootLoadReadyAtMs = now
    driftgod.S.bootLoadProgress = 0.0
    driftgod.S.bootLoadMessage = "Preparing DriftGodStart..."
    driftgod.S.introStartMs = 0
    driftgod.S.introDelayUntilLoaderDone = true
    driftgod.S.introStartMs = 0

    local loaderOk = driftgod.Try(function()
        require("core.driftgod_start_loader")
    end)

    if not loaderOk or not (driftgod.DriftGodStart and driftgod.DriftGodStart.StartPreload) then
        dg_boot_log("DriftGodStart loader unavailable; falling back to delayed boot")
        local delayMs = tonumber(driftgod.S.bootDelayMs or 10000) or 10000
        if driftgod.S.bootDelayEnabled == false then delayMs = 0 end
        if delayMs <= 0 or not (Script and Script.QueueJob) then
            driftgod.Boot.RunNow("fallback-immediate", false)
            return
        end
        Script.QueueJob(function()
            Script.Yield(delayMs)
            driftgod.Boot.RunNow("fallback-delayed", false)
        end)
        return
    end

    driftgod.DriftGodStart.StartPreload()
    dg_boot_log("DriftGodStart preload queued")

    if not (Script and Script.QueueJob) then
        driftgod.DriftGodStart.StartDynamic("Core Boot")
        driftgod.Boot.RunNow("no-queue", true)
        if driftgod.DriftGodStart.Finish then driftgod.DriftGodStart.Finish() end
        driftgod.S.introStartMs = dg_boot_now()
        return
    end

    Script.QueueJob(function()
        local preloadStart = dg_boot_now()
        local minPreloadMs = 600
        while not driftgod.DriftGodStart.IsPreloadComplete() do
            local p = driftgod.DriftGodStart.GetPreloadProgress and driftgod.DriftGodStart.GetPreloadProgress() or 0
            driftgod.S.bootLoadProgress = math.max(0.0, math.min(0.08, p * 0.08))
            driftgod.S.bootLoadMessage = "Preloading frames..."
            Script.Yield(25)
        end

        local elapsed = dg_boot_now() - preloadStart
        if elapsed < minPreloadMs then Script.Yield(minPreloadMs - elapsed) end

        driftgod.DriftGodStart.StartDynamic("Core Boot")
        driftgod.Boot.RunNow("driftgodstart", true)

        local waitStart = dg_boot_now()
        while driftgod.DriftGodStart.IsFinished and not driftgod.DriftGodStart.IsFinished() and (dg_boot_now() - waitStart) < 6000 do
            Script.Yield(50)
        end

        driftgod.S.introDelayUntilLoaderDone = false

        driftgod.IntroLogoTextureId = nil
        driftgod.IntroLogoTexture = nil
        if driftgod.LoadIntroLogoTexturePresent then driftgod.Try(driftgod.LoadIntroLogoTexturePresent) end
        driftgod.S.introStartMs = dg_boot_now()
        driftgod.S.lastScoreTick = driftgod.S.introStartMs
        driftgod.S.lastAutoSaveMs = driftgod.S.introStartMs
        dg_boot_log("DriftGod intro released after DriftGodStart fade")
    end)
end

return driftgod.Boot
end

