local function dg_join_path(a, b)
    a = tostring(a or ""):gsub("/", "\\")
    b = tostring(b or ""):gsub("/", "\\")
    if a:sub(-1) == "\\" then return a .. b end
    return a .. "\\" .. b
end

local function dg_slash(path)
    path = tostring(path or ""):gsub("/", "\\")
    if path ~= "" and path:sub(-1) == "\\" then path = path:sub(1, -2) end
    return path
end

