function driftgod.DebugLog(context, msg)
    if not driftgod.S or driftgod.S.debugLogsEnabled ~= true then return end

    local message = "[Debug][" .. tostring(context or "General") .. "] " .. tostring(msg or "")
    if driftgod.Log then
        driftgod.Log(message)
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] " .. message)
    elseif log then
        log("[DriftGod] " .. message)
    elseif print then
        print("[DriftGod] " .. message)
    end
end

function driftgod.MajorLog(context, err)
    if driftgod.S and driftgod.S.majorErrorLogsEnabled == false then return end

    local message = "[MajorError][" .. tostring(context or "Unknown") .. "] " .. tostring(err or "")
    if debug and debug.traceback then
        message = message .. "\n" .. tostring(debug.traceback("", 2))
    end

    if driftgod.Log then
        driftgod.Log(message)
    elseif Logger and Logger.LogError then
        Logger.LogError("[DriftGod] " .. message)
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] " .. message)
    elseif log then
        log("[DriftGod] " .. message)
    elseif print then
        print("[DriftGod] " .. message)
    end
end

function driftgod.SafeRequireDebug(moduleName)
    if driftgod.DebugLog and driftgod.S and driftgod.S.moduleDebugLogsEnabled == true then
        driftgod.DebugLog("Module", "Loading " .. tostring(moduleName))
    end

    local ok, result = driftgod.Try(function()
        return require(moduleName)
    end)

    if not ok then
        if driftgod.MajorLog then
            driftgod.MajorLog("Require " .. tostring(moduleName), result)
        elseif driftgod.Log then
            driftgod.Log("[MajorError][Require " .. tostring(moduleName) .. "] " .. tostring(result))
        end
        return false, result
    end

    if driftgod.DebugLog and driftgod.S and driftgod.S.moduleDebugLogsEnabled == true then
        driftgod.DebugLog("Module", "Loaded " .. tostring(moduleName))
    end

    return true, result
end

