function driftgod.SetScoreHudVisible(enabled)
    enabled = enabled == true

    driftgod.S.showScoreHudMaster = enabled
    driftgod.S.showScoreHud = enabled
    driftgod.S.scoreHudEnabled = enabled
    driftgod.S.mphHudEnabled = enabled

    if enabled == false then
        driftgod.S.showPointsHud = false
    end

    if driftgod.DebugLog then
        driftgod.DebugLog("HUD", "Score HUD master visible=" .. tostring(enabled))
    end
end

function driftgod.IsScoreHudVisible()
    if driftgod.S and driftgod.S.showScoreHudMaster == false then return false end
    if driftgod.S and driftgod.S.showScoreHud == false then return false end
    if driftgod.S and driftgod.S.scoreHudEnabled == false then return false end

    if driftgod.S and driftgod.S.showScoreHudMaster ~= nil then return driftgod.S.showScoreHudMaster == true end
    if driftgod.S and driftgod.S.scoreHudEnabled ~= nil then return driftgod.S.scoreHudEnabled == true end
    return true
end

function driftgod.CanShowScoreHud()
    return driftgod.IsScoreHudVisible == nil or driftgod.IsScoreHudVisible() == true
end

