function driftgod.NormalizeStuntName(name)
    local s = tostring(name or "")
    local lower = s:lower()

    if lower:find("layback", 1, true) then return "Excluded: Layback Grind" end
    if lower:find("brutal", 1, true) or lower:find("crash", 1, true) then return "Excluded: Brutal Crash" end

    if lower:find("donut", 1, true) then return "Donut" end
    if lower:find("720", 1, true) then return "720 Spin" end
    if lower:find("360", 1, true) then return "360 Flip" end

    if lower:find("back", 1, true) and lower:find("flip", 1, true) and not lower:find("backside", 1, true) then return "Back Flip" end
    if lower:find("front", 1, true) and lower:find("flip", 1, true) and not lower:find("frontside", 1, true) and not lower:find("forward", 1, true) then return "Front Flip" end
    if lower:find("forward", 1, true) and lower:find("flip", 1, true) then return "Forward Flip" end

    if lower:find("sideways", 1, true) and lower:find("kick", 1, true) then return "Sideways Kickflip" end
    if lower:find("kick", 1, true) and not lower:find("sideways", 1, true) then return "Kickflip" end
    if lower:find("heelflip", 1, true) and lower:find("inward", 1, true) then return "Inward Heelflip" end
    if lower:find("heelflip", 1, true) and lower:find("backside", 1, true) then return "Backside Heelflip" end
    if lower:find("heelflip", 1, true) and lower:find("frontside", 1, true) then return "Frontside Heelflip" end
    if lower:find("big", 1, true) and lower:find("heel", 1, true) then return "Big Heelflip" end
    if lower:find("heel", 1, true) then return "Heelflip" end
    if lower:find("finger", 1, true) then return "Fingerflip" end

    if lower:find("backside", 1, true) and lower:find("flip", 1, true) then return "Backside Flip" end
    if lower:find("frontside", 1, true) and lower:find("flip", 1, true) then return "Frontside Flip" end

    if lower:find("impossible", 1, true) then return "Impossible" end
    if lower:find("bigspin", 1, true) or lower:find("big spin", 1, true) then return "Bigspin" end
    if lower:find("hardflip 180", 1, true) or (lower:find("hard", 1, true) and lower:find("180", 1, true)) then return "Hardflip 180" end
    if lower:find("hard", 1, true) and lower:find("flip", 1, true) then return "Hardflip" end
    if lower:find("bubble", 1, true) then return "Bubble Flip" end
    if lower:find("anti", 1, true) and lower:find("casper", 1, true) then return "Anti Casper Flip" end
    if lower:find("casper", 1, true) then return "Casper Flip" end
    if lower:find("laser", 1, true) then return "Laser Flip" end
    if lower:find("alpha", 1, true) then return "Alpha Flip" end
    if lower:find("daydream", 1, true) then return "Daydream Flip" end
    if lower:find("ghetto", 1, true) then return "Ghetto Bird" end
    if lower:find("gazelle", 1, true) then return "Gazelle Flip" end
    if lower:find("japan", 1, true) then return "Japan Air" end

    return s
end

function driftgod.IsStuntExcluded(name)
    local key = driftgod.NormalizeStuntName(name)
    return key == "Excluded: Layback Grind" or key == "Excluded: Brutal Crash"
end

function driftgod.GetStuntUnlockRequirement(name)
    local key = driftgod.NormalizeStuntName(name)
    return tonumber(driftgod.StuntUnlocks and driftgod.StuntUnlocks[key] or 0) or 0
end

function driftgod.LockedStuntNotice(name)
    local key = driftgod.NormalizeStuntName(name)

    if driftgod.IsStuntExcluded and driftgod.IsStuntExcluded(name) then
        local msg = key .. " is not used in normal progression."
        if driftgod.Toast then driftgod.Toast(msg, 2500) elseif driftgod.Log then driftgod.Log("[StuntUnlocks] " .. msg) end
        return
    end

    local required = driftgod.GetStuntUnlockRequirement(key)
    local current = driftgod.GetLifetimeScore()
    local msg = key .. " locked. Need " .. tostring(required) .. " score. Current: " .. tostring(current)

    if driftgod.Toast then
        driftgod.Toast(msg, 2500)
    elseif driftgod.Log then
        driftgod.Log("[StuntUnlocks] " .. msg)
    end
end

function driftgod.TryRunUnlockedStunt(name, fn)
    if not driftgod.IsStuntUnlocked(name) then
        driftgod.LockedStuntNotice(name)
        return false
    end

    if type(fn) == "function" then fn() end
    return true
end

function driftgod.AreProgressUnlocksEnabled()
    if driftgod.S == nil then return true end

    if driftgod.S.progressUnlocksEnabled ~= nil then return driftgod.S.progressUnlocksEnabled == true end

    if driftgod.S.progressUnlocks ~= nil then return driftgod.S.progressUnlocks == true end
    if driftgod.S.unlockProgression ~= nil then return driftgod.S.unlockProgression == true end

    return true
end

function driftgod.IsStuntUnlocked(name)

    if driftgod.AreProgressUnlocksEnabled and not driftgod.AreProgressUnlocksEnabled() then
        return not (driftgod.IsStuntExcluded and driftgod.IsStuntExcluded(name))
    end

    if driftgod.S and driftgod.S.stuntUnlockPreviewAll == true then
        return not (driftgod.IsStuntExcluded and driftgod.IsStuntExcluded(name))
    end

    if driftgod.IsStuntExcluded and driftgod.IsStuntExcluded(name) then return false end

    local key = driftgod.NormalizeStuntName and driftgod.NormalizeStuntName(name) or tostring(name or "")
    local required = driftgod.StuntUnlocks and driftgod.StuntUnlocks[key]
    if required == nil then return false end

    return (driftgod.GetStuntUnlockScore and driftgod.GetStuntUnlockScore() or 0) >= tonumber(required or 0)
end

