function driftgod.GetStuntSortIndex(name)
    local key = driftgod.NormalizeStuntName and driftgod.NormalizeStuntName(name) or tostring(name or "")
    for i, stuntName in ipairs(driftgod.StuntUnlockOrder or {}) do
        if stuntName == key then return i end
    end
    return 9999
end

function driftgod.GetStuntUnlockScore()
    local score = driftgod.GetLifetimeScore and driftgod.GetLifetimeScore() or 0
    return math.floor(tonumber(score) or 0)
end

function driftgod.GetUnlockedTricks()
    local unlocksEnabled = true
    if driftgod.AreProgressUnlocksEnabled then unlocksEnabled = driftgod.AreProgressUnlocksEnabled() end

    local byName = {}
    for _, trick in ipairs(driftgod.Tricks or {}) do
        local originalName = tostring(trick and trick.name or "")
        local key = driftgod.NormalizeStuntName and driftgod.NormalizeStuntName(originalName) or originalName
        local excluded = driftgod.IsStuntExcluded and driftgod.IsStuntExcluded(originalName)
        if not excluded and byName[key] == nil then
            byName[key] = trick
        end
    end

    local unlocked = {}

    if unlocksEnabled == false then

        for _, stuntName in ipairs(driftgod.StuntUnlockOrder or {}) do
            if byName[stuntName] then
                table.insert(unlocked, byName[stuntName])
                byName[stuntName] = nil
            end
        end
        for _, trick in ipairs(driftgod.Tricks or {}) do
            local originalName = tostring(trick and trick.name or "")
            local key = driftgod.NormalizeStuntName and driftgod.NormalizeStuntName(originalName) or originalName
            if byName[key] then
                table.insert(unlocked, byName[key])
                byName[key] = nil
            end
        end
        return unlocked
    end

    for _, stuntName in ipairs(driftgod.StuntUnlockOrder or {}) do
        local trick = byName[stuntName]
        if trick and driftgod.IsStuntUnlocked and driftgod.IsStuntUnlocked(stuntName) then
            table.insert(unlocked, trick)
        end
    end

    if #unlocked == 0 then
        if byName["Donut"] then
            table.insert(unlocked, byName["Donut"])
        else
            for _, stuntName in ipairs(driftgod.StuntUnlockOrder or {}) do
                if byName[stuntName] then
                    table.insert(unlocked, byName[stuntName])
                    break
                end
            end
        end
    end

    return unlocked
end

function driftgod.ShouldRenderStuntFeature(index, trick)
    if trick == nil and driftgod.Tricks then
        trick = driftgod.Tricks[index]
    end

    local name = tostring(trick and trick.name or "")

    if name == "" then return false end
    if driftgod.IsStuntExcluded and driftgod.IsStuntExcluded(name) then return false end

    if driftgod.AreProgressUnlocksEnabled and not driftgod.AreProgressUnlocksEnabled() then
        return true
    end

    if driftgod.IsStuntUnlocked then
        return driftgod.IsStuntUnlocked(name) == true
    end

    return true
end

