function driftgod.GetMs()
    if util and util.current_time_millis then return util.current_time_millis() end
    if os and os.clock then return math.floor(os.clock() * 1000) end
    return 0
end

function driftgod.GetHighestUnlockedStuntName()
    local score = driftgod.GetStuntUnlockScore and driftgod.GetStuntUnlockScore() or (driftgod.GetLifetimeScore and driftgod.GetLifetimeScore() or 0)
    local highestName, highestReq = "Donut", 0
    for _, name in ipairs(driftgod.StuntUnlockOrder or {}) do
        local req = driftgod.GetStuntUnlockRequirement and driftgod.GetStuntUnlockRequirement(name) or 0
        if req <= score and req >= highestReq then highestName, highestReq = name, req end
    end
    return highestName, highestReq, score
end

function driftgod.GetNextStuntUnlock()
    local score = driftgod.GetStuntUnlockScore and driftgod.GetStuntUnlockScore() or (driftgod.GetLifetimeScore and driftgod.GetLifetimeScore() or 0)
    for _, name in ipairs(driftgod.StuntUnlockOrder or {}) do
        local req = driftgod.GetStuntUnlockRequirement and driftgod.GetStuntUnlockRequirement(name) or 0
        if req > score then return name, req, req - score, score end
    end
    return nil, nil, 0, score
end

function driftgod.StartStuntUnlockBanner(name)
    if not (driftgod.S and driftgod.S.stuntUnlockPolishEnabled) then return end
    driftgod.S.stuntUnlockBannerStart = driftgod.GetMs()
    driftgod.S.stuntUnlockBannerTitle = "NEW STUNT UNLOCKED!"
    driftgod.S.stuntUnlockBannerName = tostring(name or "UNKNOWN")
    if driftgod.DebugLog then driftgod.DebugLog("StuntUnlocks", "New stunt unlocked: " .. tostring(name)) end
end

function driftgod.StartStuntNeedPopup()
    if not (driftgod.S and driftgod.S.stuntUnlockPolishEnabled) then return end
    local n, req, needed = driftgod.GetNextStuntUnlock()
    if not n then return end
    driftgod.S.stuntUnlockNeedPopupStart = driftgod.GetMs()
    driftgod.S.stuntUnlockNeedPopupText = tostring(math.max(0, needed or 0)) .. " score needed for " .. tostring(n)
end

function driftgod.CheckStuntUnlockPolish()
    if not (driftgod.S and driftgod.S.stuntUnlockPolishEnabled) then return end
    if driftgod.AreProgressUnlocksEnabled and not driftgod.AreProgressUnlocksEnabled() then return end

    local now = driftgod.GetMs and driftgod.GetMs() or 0
    if (driftgod.S.stuntUnlockBootQuietUntil or 0) == 0 then
        driftgod.S.stuntUnlockBootQuietUntil = now + 5500
    end

    local highest = driftgod.GetHighestUnlockedStuntName and driftgod.GetHighestUnlockedStuntName() or nil
    if not highest or highest == "" then return end

    if now < (driftgod.S.stuntUnlockBootQuietUntil or 0) then
        driftgod.S.stuntUnlockLastHighest = highest
        return
    end

    if driftgod.S.stuntUnlockLastHighest == "" then
        driftgod.S.stuntUnlockLastHighest = highest
        return
    end

    if highest ~= driftgod.S.stuntUnlockLastHighest then
        driftgod.S.stuntUnlockLastHighest = highest
        driftgod.StartStuntUnlockBanner(highest)
    end
end

function driftgod.DrawTextCenter(text, x, y, scale, r, g, b, a, font)
    if not HUD then return end
    if HUD.SET_TEXT_FONT then HUD.SET_TEXT_FONT(font or 7) end
    if HUD.SET_TEXT_SCALE then HUD.SET_TEXT_SCALE(scale, scale) end
    if HUD.SET_TEXT_COLOUR then HUD.SET_TEXT_COLOUR(r or 255, g or 255, b or 255, a or 255) end
    if HUD.SET_TEXT_CENTRE then HUD.SET_TEXT_CENTRE(true) end
    if HUD.SET_TEXT_OUTLINE then HUD.SET_TEXT_OUTLINE() end
    if HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT then
        HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT("STRING")
        HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME(tostring(text or ""))
        HUD.END_TEXT_COMMAND_DISPLAY_TEXT(x, y)
    end
end

function driftgod.RenderStuntUnlockBanner()
    if not (driftgod.S and driftgod.S.stuntUnlockPolishEnabled) then return end
    if not HUD then return end
    local now, start = driftgod.GetMs(), tonumber(driftgod.S.stuntUnlockBannerStart or 0) or 0
    local dur = tonumber(driftgod.S.stuntUnlockBannerDuration or 3600) or 3600
    if start <= 0 then return end
    local e = now - start
    if e < 0 or e > dur then return end
    local t = e / dur
    local x
    if t < 0.24 then
        local p = t / 0.24; p = p*p*(3-2*p); x = -0.34 + 0.84*p
    elseif t < 0.68 then
        x = 0.5
    else
        local p = (t - 0.68) / 0.32; p = p*p*(3-2*p); x = 0.5 + 0.92*p
    end
    local alpha = 255
    if t > 0.76 then alpha = math.max(0, math.floor(255 * (1 - ((t - 0.76) / 0.24)))) end
    local y = 0.405 + ((t > 0.62) and math.sin(t * 34.0) * 0.004 or 0.0)

    if driftgod.S and driftgod.S.stuntUnlockBannerBackgroundEnabled == true and GRAPHICS and GRAPHICS.DRAW_RECT then
        GRAPHICS.DRAW_RECT(x, y + 0.01, 0.58, 0.118, 15, 4, 28, math.floor(alpha * 0.58))
        GRAPHICS.DRAW_RECT(x, y + 0.01, 0.52, 0.080, 90, 20, 170, math.floor(alpha * 0.16))
    end
    driftgod.DrawTextCenter(driftgod.S.stuntUnlockBannerTitle or "NEW STUNT UNLOCKED!", x, y - 0.020, 0.72, 170, 90, 255, alpha, 7)
    driftgod.DrawTextCenter(driftgod.S.stuntUnlockBannerName or "", x, y + 0.030, 0.56, 255, 255, 255, alpha, 7)
end

function driftgod.RenderStuntNeedPopup()
    if not (driftgod.S and driftgod.S.stuntUnlockPolishEnabled) then return end
    local start = tonumber(driftgod.S.stuntUnlockNeedPopupStart or 0) or 0
    if start <= 0 then return end
    local e, dur = driftgod.GetMs() - start, 2600
    if e < 0 or e > dur then return end
    local t = e / dur
    local alpha = math.max(0, math.floor(210 * (1 - t)))
    driftgod.DrawTextCenter(driftgod.S.stuntUnlockNeedPopupText or "", 0.5, 0.535 - 0.018*t, 0.34, 215, 210, 255, alpha, 4)
end

function driftgod.RenderStuntUnlockPolish()
    if driftgod.CheckStuntUnlockPolish then driftgod.CheckStuntUnlockPolish() end
    if driftgod.RenderStuntUnlockBanner then driftgod.RenderStuntUnlockBanner() end
    if driftgod.RenderStuntNeedPopup then driftgod.RenderStuntNeedPopup() end
end

