function driftgod.RenderStuntTierPopup()
    if not (driftgod.S and driftgod.S.stuntUpgradeTiersEnabled) then return end
    if not driftgod.DrawTextCenter then return end

    local start = tonumber(driftgod.S.stuntUpgradeTierPopupStart or 0) or 0
    if start <= 0 then return end

    local now = driftgod.GetMs and driftgod.GetMs() or 0
    local elapsed = now - start
    local duration = 2600
    if elapsed < 0 or elapsed > duration then return end

    local t = elapsed / duration
    local alpha = math.max(0, math.floor(230 * (1.0 - t)))
    local y = 0.595 - (0.020 * t)

    driftgod.DrawTextCenter(driftgod.S.stuntUpgradeTierPopupText or "", 0.5, y, 0.36, 185, 120, 255, alpha, 7)
end

function driftgod.RenderStuntUpgradePolish()
    if driftgod.CheckStuntTierUnlockPolish then driftgod.CheckStuntTierUnlockPolish() end
    if driftgod.RenderStuntTierPopup then driftgod.RenderStuntTierPopup() end
end

function driftgod.GetStuntTierRequirement(stuntName, tier)
    local base = driftgod.GetStuntUnlockRequirement and driftgod.GetStuntUnlockRequirement(stuntName) or 0
    tier = tonumber(tier or 1) or 1

    if tier <= 1 then return base end

    if tier == 2 then return math.floor(base + 1000) end
    return math.floor(base + 1000)
end

function driftgod.GetHighestStuntTierKey()

    local score = driftgod.GetStuntUnlockScore and driftgod.GetStuntUnlockScore() or (driftgod.GetLifetimeScore and driftgod.GetLifetimeScore() or 0)
    local bestName, bestBase = nil, -1

    for _, name in ipairs(driftgod.StuntUnlockOrder or {}) do
        local base = driftgod.GetStuntUnlockRequirement and driftgod.GetStuntUnlockRequirement(name) or 0
        if base <= score and base > bestBase and (driftgod.IsStuntUnlocked == nil or driftgod.IsStuntUnlocked(name)) then
            bestName, bestBase = name, base
        end
    end

    if not bestName then return "" end
    local tier = driftgod.GetStuntUpgradeTier and driftgod.GetStuntUpgradeTier(bestName) or 1
    return tostring(bestName) .. "_T" .. tostring(tier), bestName, tier
end

function driftgod.CheckStuntTierUnlockPolish()
    if not (driftgod.S and driftgod.S.stuntUpgradeTiersEnabled) then return end
    if driftgod.AreProgressUnlocksEnabled and not driftgod.AreProgressUnlocksEnabled() then return end

    local now = driftgod.GetMs and driftgod.GetMs() or 0
    if (driftgod.S.stuntUpgradeBootQuietUntil or 0) == 0 then
        driftgod.S.stuntUpgradeBootQuietUntil = now + 5500
    end

    local key, name, tier = driftgod.GetHighestStuntTierKey()
    if not key or key == "" then return end

    if now < (driftgod.S.stuntUpgradeBootQuietUntil or 0) then
        driftgod.S.stuntUpgradeLastHighestTierKey = key
        return
    end

    if driftgod.S.stuntUpgradeLastHighestTierKey == "" then
        driftgod.S.stuntUpgradeLastHighestTierKey = key
        return
    end

    if key ~= driftgod.S.stuntUpgradeLastHighestTierKey then
        driftgod.S.stuntUpgradeLastHighestTierKey = key
        if tonumber(tier or 1) and tonumber(tier or 1) > 1 then
            driftgod.StartStuntTierPopup(name, tier)
        end
    end
end

driftgod.S.stuntTierUseReq2 = driftgod.S.stuntTierUseReq2 or 3
driftgod.S.stuntTierUseReq3 = driftgod.S.stuntTierUseReq3 or 5
driftgod.S.stuntUseRunId = driftgod.S.stuntUseRunId or 0
driftgod.S.stuntUseRunCounts = driftgod.S.stuntUseRunCounts or {}
driftgod.S.stuntUseLastScoreActive = driftgod.S.stuntUseLastScoreActive or false
driftgod.S.stuntUseDebug = driftgod.S.stuntUseDebug or false

function driftgod.GetStuntUseKey(stuntName)
    return driftgod.NormalizeStuntName and driftgod.NormalizeStuntName(stuntName) or tostring(stuntName or "")
end

function driftgod.GetStuntTierUseRequirement(tier)
    tier = tonumber(tier or 1) or 1
    if tier <= 1 then return 0 end
    if tier == 2 then return tonumber(driftgod.S.stuntTierUseReq2 or 3) or 3 end
    return tonumber(driftgod.S.stuntTierUseReq3 or 5) or 5
end

function driftgod.GetStuntTierUseProgress(stuntName, tier)
    local count = driftgod.GetStuntRunUseCount and driftgod.GetStuntRunUseCount(stuntName) or 0
    local req = driftgod.GetStuntTierUseRequirement and driftgod.GetStuntTierUseRequirement(tier) or 0
    return count, req
end

function driftgod.HasStuntTierUseRequirement(stuntName, tier)
    local count, req = driftgod.GetStuntTierUseProgress(stuntName, tier)
    return tonumber(count or 0) >= tonumber(req or 0)
end

function driftgod.MonitorStuntUseRun()
    if not driftgod.S then return end

    local current = tonumber(driftgod.S.currentScore or driftgod.S.score or driftgod.S.driftScore or 0) or 0
    local active = current > 0

    if driftgod.S.stuntUseLastScoreActive == true and active == false then
        driftgod.ResetStuntUseRun("score inactive")
    end

    driftgod.S.stuntUseLastScoreActive = active
end

function driftgod.GetEarnedStuntTier(stuntName)
    local key = driftgod.GetStuntUseKey and driftgod.GetStuntUseKey(stuntName) or tostring(stuntName or "")
    driftgod.S.stuntUpgradeEarnedTiers = driftgod.S.stuntUpgradeEarnedTiers or {}
    local tier = tonumber(driftgod.S.stuntUpgradeEarnedTiers[key] or 1) or 1

    if driftgod.IsStuntUnlocked and not driftgod.IsStuntUnlocked(key) then return 1 end
    if tier < 1 then tier = 1 end
    if tier > 3 then tier = 3 end

    return tier
end

function driftgod.SetEarnedStuntTier(stuntName, tier)
    local key = driftgod.GetStuntUseKey and driftgod.GetStuntUseKey(stuntName) or tostring(stuntName or "")
    driftgod.S.stuntUpgradeEarnedTiers = driftgod.S.stuntUpgradeEarnedTiers or {}
    local newTier = math.max(1, math.min(3, tonumber(tier or 1) or 1))
    local oldTier = tonumber(driftgod.S.stuntUpgradeEarnedTiers[key] or 1) or 1
    driftgod.S.stuntUpgradeEarnedTiers[key] = newTier
    if newTier ~= oldTier and not driftgod._savingProgressNow then
        if driftgod.SaveProgressHard then driftgod.SaveProgressHard("stunt tier changed: " .. tostring(key) .. " T" .. tostring(newTier))
        elseif driftgod.SaveProgress then driftgod.SaveProgress(false) end
    end
end

function driftgod.GetStuntUpgradeTier(stuntName)
    if not (driftgod.S and driftgod.S.stuntUpgradeTiersEnabled) then return 1 end
    return driftgod.GetEarnedStuntTier and driftgod.GetEarnedStuntTier(stuntName) or 1
end

function driftgod.GetFreshUseKey(stuntName, targetTier)
    local key = driftgod.GetStuntUseKey and driftgod.GetStuntUseKey(stuntName) or tostring(stuntName or "")
    return key .. "_toT" .. tostring(targetTier or 1)
end

function driftgod.GetStuntRunUseCount(stuntName)
    local key = driftgod.GetStuntUseKey and driftgod.GetStuntUseKey(stuntName) or tostring(stuntName or "")
    return tonumber(driftgod.S.stuntUseRunCounts and driftgod.S.stuntUseRunCounts[key] or 0) or 0
end

function driftgod.GetFreshTierUseCount(stuntName, targetTier)
    local key = driftgod.GetFreshUseKey and driftgod.GetFreshUseKey(stuntName, targetTier) or tostring(stuntName or "")
    return tonumber(driftgod.S.stuntTierFreshUseCounts and driftgod.S.stuntTierFreshUseCounts[key] or 0) or 0
end

function driftgod.ResetFreshTierUseCount(stuntName, targetTier)
    driftgod.S.stuntTierFreshUseCounts = driftgod.S.stuntTierFreshUseCounts or {}
    local key = driftgod.GetFreshUseKey and driftgod.GetFreshUseKey(stuntName, targetTier) or tostring(stuntName or "")
    driftgod.S.stuntTierFreshUseCounts[key] = 0
end

function driftgod.ResetStuntUseRun(reason)
    driftgod.S.stuntUseRunId = (tonumber(driftgod.S.stuntUseRunId or 0) or 0) + 1
    driftgod.S.stuntUseRunCounts = {}
    driftgod.S.stuntTierFreshUseCounts = {}
    driftgod.S.stuntTierLastAcceptedUseMs = {}
    driftgod.S.stuntTierLastBlockedUseMs = {}

    if driftgod.DebugLog and driftgod.S.stuntUseDebug == true then
        driftgod.DebugLog("StuntUpgrades", "Reset stunt use run | reason=" .. tostring(reason or "unknown") .. " | runId=" .. tostring(driftgod.S.stuntUseRunId))
    end
end

function driftgod.RecordStuntUse(stuntName)
    if not (driftgod.S and driftgod.S.stuntUpgradeTiersEnabled) then return end

    local key = driftgod.GetStuntUseKey and driftgod.GetStuntUseKey(stuntName) or tostring(stuntName or "")
    if key == "" or (driftgod.IsStuntExcluded and driftgod.IsStuntExcluded(key)) then return end

    driftgod.S.stuntUseRunCounts = driftgod.S.stuntUseRunCounts or {}
    driftgod.S.stuntTierFreshUseCounts = driftgod.S.stuntTierFreshUseCounts or {}

    driftgod.S.stuntUseRunCounts[key] = (tonumber(driftgod.S.stuntUseRunCounts[key] or 0) or 0) + 1

    local earnedTier = driftgod.GetEarnedStuntTier and driftgod.GetEarnedStuntTier(key) or 1
    local targetTier = math.min(3, earnedTier + 1)

    if earnedTier < 3 then
        local freshKey = driftgod.GetFreshUseKey and driftgod.GetFreshUseKey(key, targetTier) or (key .. "_toT" .. tostring(targetTier))
        driftgod.S.stuntTierFreshUseCounts[freshKey] = (tonumber(driftgod.S.stuntTierFreshUseCounts[freshKey] or 0) or 0) + 1
    end

    if driftgod.DebugLog and driftgod.S.stuntUseDebug == true then
        driftgod.DebugLog("StuntUpgrades", "Use: " .. tostring(key) .. " run=" .. tostring(driftgod.S.stuntUseRunCounts[key]) .. " earnedTier=" .. tostring(earnedTier))
    end

    if driftgod.CheckSpecificStuntTierUnlock then
        driftgod.CheckSpecificStuntTierUnlock(key)
    end
end

function driftgod.HasFreshStuntTierUseRequirement(stuntName, targetTier)
    local count = driftgod.GetFreshTierUseCount and driftgod.GetFreshTierUseCount(stuntName, targetTier) or 0
    local req = driftgod.GetStuntTierUseRequirement and driftgod.GetStuntTierUseRequirement(targetTier) or 0
    return tonumber(count or 0) >= tonumber(req or 0)
end

function driftgod.CheckSpecificStuntTierUnlock(stuntName)
    if not (driftgod.S and driftgod.S.stuntUpgradeTiersEnabled) then return end
    if driftgod.AreProgressUnlocksEnabled and not driftgod.AreProgressUnlocksEnabled() then return end
    if driftgod.IsStuntUnlocked and not driftgod.IsStuntUnlocked(stuntName) then return end

    local key = driftgod.GetStuntUseKey and driftgod.GetStuntUseKey(stuntName) or tostring(stuntName or "")
    local earnedTier = driftgod.GetEarnedStuntTier and driftgod.GetEarnedStuntTier(key) or 1
    if earnedTier >= 3 then return end

    local targetTier = earnedTier + 1
    local score = driftgod.GetStuntUnlockScore and driftgod.GetStuntUnlockScore() or (driftgod.GetLifetimeScore and driftgod.GetLifetimeScore() or 0)
    local scoreReq = driftgod.GetStuntTierRequirement and driftgod.GetStuntTierRequirement(key, targetTier) or 999999999
    local scoreOK = score >= scoreReq
    local useOK = driftgod.HasFreshStuntTierUseRequirement and driftgod.HasFreshStuntTierUseRequirement(key, targetTier)

    if scoreOK and useOK then
        driftgod.SetEarnedStuntTier(key, targetTier)
        driftgod.ResetFreshTierUseCount(key, targetTier)

        if driftgod.StartStuntTierPopup then driftgod.StartStuntTierPopup(key, targetTier) end
    end
end

function driftgod.GetNextStuntTierRequirementText(stuntName)
    local earnedTier = driftgod.GetEarnedStuntTier and driftgod.GetEarnedStuntTier(stuntName) or 1
    if earnedTier >= 3 then return "Max Tier" end

    local targetTier = earnedTier + 1
    local score = driftgod.GetStuntUnlockScore and driftgod.GetStuntUnlockScore() or (driftgod.GetLifetimeScore and driftgod.GetLifetimeScore() or 0)
    local scoreReq = driftgod.GetStuntTierRequirement and driftgod.GetStuntTierRequirement(stuntName, targetTier) or 0
    local useCount = driftgod.GetFreshTierUseCount and driftgod.GetFreshTierUseCount(stuntName, targetTier) or 0
    local useReq = driftgod.GetStuntTierUseRequirement and driftgod.GetStuntTierUseRequirement(targetTier) or 0

    local scoreLeft = math.max(0, scoreReq - score)
    local usesLeft = math.max(0, useReq - useCount)

    return "Next Tier " .. tostring(targetTier) .. ": " .. tostring(scoreLeft) .. " score + " .. tostring(usesLeft) .. " fresh uses"
end

function driftgod.GetStuntTierDurationScalar(stuntName)

    local scoreGuard = driftgod.GetStuntUnlockScore and driftgod.GetStuntUnlockScore() or 0
    if tonumber(scoreGuard or 0) <= 0 then return 1.0 end
    if not (driftgod.S and driftgod.S.stuntTierSpeedScalingEnabled) then return 1.0 end
    local tier = driftgod.GetStuntUpgradeTier and driftgod.GetStuntUpgradeTier(stuntName) or 1
    return driftgod.StuntTierSpeed and driftgod.StuntTierSpeed[tier] or 1.0
end

function driftgod.ApplyStuntTierDuration(name, duration)
    local dur = tonumber(duration or 0) or 0
    if dur <= 0 then return duration end

    local scalar = driftgod.GetStuntTierDurationScalar and driftgod.GetStuntTierDurationScalar(name) or 1.0
    return math.max(1, math.floor(dur * scalar))
end

function driftgod.GetStuntTierLabel(stuntName)
    local tier = driftgod.GetStuntUpgradeTier and driftgod.GetStuntUpgradeTier(stuntName) or 1
    local scalar = driftgod.GetStuntTierDurationScalar and driftgod.GetStuntTierDurationScalar(stuntName) or 1.0
    return "Tier " .. tostring(tier) .. " | " .. tostring(math.floor(scalar * 100)) .. "%"
end

function driftgod.GetStuntTierDurationPercent(stuntName)
    local scalar = driftgod.GetStuntTierDurationScalar and driftgod.GetStuntTierDurationScalar(stuntName) or 1.0
    return math.floor((tonumber(scalar or 1.0) or 1.0) * 100)
end

function driftgod.GetEffectiveStuntDurationPercent(stuntName)

    if not (driftgod.S and driftgod.S.stuntTierSpeedScalingEnabled) then
        return tonumber(driftgod.S and driftgod.S.stuntDurationPercent or 100) or 100
    end

    return driftgod.GetStuntTierDurationPercent and driftgod.GetStuntTierDurationPercent(stuntName) or 100
end

function driftgod.ResetStuntProgressionState(reason)
    if not driftgod.S then return end

    local resetBaseline = driftgod.GetRawEarnedScoreForUnlocks and driftgod.GetRawEarnedScoreForUnlocks() or (driftgod.GetLifetimeScore and driftgod.GetLifetimeScore() or 0)
    driftgod.S.stuntProgressionResetActive = true
    driftgod.S.stuntProgressionResetBaseline = tonumber(resetBaseline or 0) or 0

    driftgod.S.bestScore = 0
    driftgod.S.bestDriftScore = 0
    driftgod.S.highScore = 0
    driftgod.S.highestScore = 0
    driftgod.S.topScore = 0
    driftgod.S.topDriftScore = 0
    driftgod.S.previousScore = 0
    driftgod.S.lastScore = 0
    driftgod.S.lastRunScore = 0
    driftgod.S.lifetimeScore = 0
    driftgod.S.totalScore = 0
    driftgod.S.totalDriftScore = 0
    driftgod.S.progressScore = 0
    driftgod.S.score = 0
    driftgod.S.currentScore = 0
    driftgod.S.sessionScore = 0
    driftgod.S.driftScore = 0
    driftgod.S.points = 0
    driftgod.S.totalPoints = 0
    driftgod.S.highScores = {}
    driftgod.S.beatenRivals = {}
    driftgod.S.notifiedUnlocks = {}
    driftgod.S.unlockedRewards = {}

    driftgod.S.stuntUnlockLastHighest = ""
    driftgod.S.stuntUnlockBannerStart = 0
    driftgod.S.stuntUnlockBannerTitle = ""
    driftgod.S.stuntUnlockBannerName = ""
    driftgod.S.stuntUnlockNeedPopupStart = 0
    driftgod.S.stuntUnlockNeedPopupText = ""

    driftgod.S.stuntUpgradeEarnedTiers = {}
    driftgod.S.stuntUpgradeAnnouncedTiers = {}
    driftgod.S.stuntUpgradeLastHighestTierKey = ""
    driftgod.S.stuntUpgradeTierPopupStart = 0
    driftgod.S.stuntUpgradeTierPopupText = ""

    driftgod.S.stuntUseRunCounts = {}
    driftgod.S.stuntTierFreshUseCounts = {}
    driftgod.S.stuntUseRunId = (tonumber(driftgod.S.stuntUseRunId or 0) or 0) + 1
    driftgod.S.stuntUseLastScoreActive = false

    driftgod.S.stuntUnlockLastScoreSource = "reset"
    driftgod.S.stuntUnlockLastDetectedScore = 0

    if type(driftgod.StuntUnlockOrder) == "table" then
        for _, stuntName in ipairs(driftgod.StuntUnlockOrder or {}) do
            driftgod.S.stuntUpgradeEarnedTiers[stuntName] = 1
            driftgod.S.stuntUpgradeAnnouncedTiers[stuntName] = 1
        end
    end

    driftgod._StuntCleanupApplied = false
    driftgod._StuntConfiguredMetaCache = nil
    driftgod.StuntConfiguredMetaCache = nil
    driftgod.ConfiguredStuntCache = nil
    driftgod.S.stuntDurationCacheResetAt = driftgod.GetMs and driftgod.GetMs() or 0

    if driftgod.DebugLog then
        driftgod.DebugLog("StuntUpgrades", "FULL reset stunt progression state | reason=" .. tostring(reason or "unknown"))
    elseif driftgod.Log then
        driftgod.Log("[StuntUpgrades] FULL reset stunt progression state | reason=" .. tostring(reason or "unknown"))
    end
end

