        driftgod.S.highestScore = 0
        driftgod.S.topScore = 0
        driftgod.S.topDriftScore = 0
        driftgod.S.lifetimeScore = 0
        driftgod.S.totalScore = 0
        driftgod.S.totalDriftScore = 0
        driftgod.S.progressScore = 0
    end
end

function driftgod.ForceAllStuntsTierOne(reason)
    if not driftgod.S then return end

    driftgod.S.stuntUpgradeEarnedTiers = {}
    driftgod.S.stuntUpgradeAnnouncedTiers = {}
    driftgod.S.stuntTierFreshUseCounts = {}
    driftgod.S.stuntUseRunCounts = {}

    if type(driftgod.StuntUnlockOrder) == "table" then
        for _, stuntName in ipairs(driftgod.StuntUnlockOrder or {}) do
            driftgod.S.stuntUpgradeEarnedTiers[stuntName] = 1
            driftgod.S.stuntUpgradeAnnouncedTiers[stuntName] = 1
        end
    end

    driftgod._StuntCleanupApplied = false
    driftgod._StuntConfiguredMetaCache = nil
    driftgod.StuntConfiguredMetaCache = nil
    driftgod.ConfiguredStuntCache = nil

    if driftgod.DebugLog then
        driftgod.DebugLog("StuntUpgrades", "Forced all stunts to Tier 1 | reason=" .. tostring(reason or "unknown"))
    end
end

function driftgod.GetRawEarnedScoreForUnlocks()
    local best = 0
    local bestLabel = "none"
    local sources = {}

    local function consider(label, value)
        local n = tonumber(value)
        if n then
            table.insert(sources, tostring(label) .. "=" .. tostring(n))
            if n > best then
                best = n
                bestLabel = tostring(label)
            end
        end
    end

    if driftgod.S then
        consider("S.stuntUnlockScoreOverride", driftgod.S.stuntUnlockScoreOverride)

        consider("S.lifetimeScore", driftgod.S.lifetimeScore)
        consider("S.totalScore", driftgod.S.totalScore)
        consider("S.totalDriftScore", driftgod.S.totalDriftScore)
        consider("S.progressScore", driftgod.S.progressScore)
        consider("S.score", driftgod.S.score)
        consider("S.currentScore", driftgod.S.currentScore)
        consider("S.sessionScore", driftgod.S.sessionScore)
        consider("S.driftScore", driftgod.S.driftScore)
        consider("S.points", driftgod.S.points)
        consider("S.totalPoints", driftgod.S.totalPoints)
        consider("S.bestScore", driftgod.S.bestScore)
        consider("S.bestDriftScore", driftgod.S.bestDriftScore)
        consider("S.highScore", driftgod.S.highScore)
        consider("S.highestScore", driftgod.S.highestScore)
        consider("S.topScore", driftgod.S.topScore)
        consider("S.topDriftScore", driftgod.S.topDriftScore)
        consider("S.previousScore", driftgod.S.previousScore)
        consider("S.lastScore", driftgod.S.lastScore)
        consider("S.lastRunScore", driftgod.S.lastRunScore)

        if type(driftgod.S.highScores) == "table" then
            for i, e in ipairs(driftgod.S.highScores) do
                if type(e) == "table" then
                    consider("S.highScores[" .. tostring(i) .. "].score", e.score)
                else
                    consider("S.highScores[" .. tostring(i) .. "]", e)
                end
            end
        end
    end

    if driftgod.Progress then
        consider("Progress.lifetimeScore", driftgod.Progress.lifetimeScore)
        consider("Progress.totalScore", driftgod.Progress.totalScore)
        consider("Progress.score", driftgod.Progress.score)
        consider("Progress.bestScore", driftgod.Progress.bestScore)
        consider("Progress.highScore", driftgod.Progress.highScore)
    end

    if driftgod.Score then
        consider("Score.lifetimeScore", driftgod.Score.lifetimeScore)
        consider("Score.totalScore", driftgod.Score.totalScore)
        consider("Score.score", driftgod.Score.score)
        consider("Score.current", driftgod.Score.current)
        consider("Score.currentScore", driftgod.Score.currentScore)
        consider("Score.bestScore", driftgod.Score.bestScore)
        consider("Score.highScore", driftgod.Score.highScore)
    end

    driftgod.S.stuntUnlockLastScoreSource = bestLabel
    driftgod.S.stuntUnlockLastRawScore = best

    if driftgod.DebugLog and driftgod.S and driftgod.S.stuntUnlockScoreDebug == true then
        driftgod.DebugLog("StuntUnlocks", "Raw earned score=" .. tostring(best) .. " from " .. tostring(bestLabel) .. " | " .. table.concat(sources, ", "))
    end

    return best
end

function driftgod.GetLifetimeScore()
    local raw = driftgod.GetRawEarnedScoreForUnlocks and driftgod.GetRawEarnedScoreForUnlocks() or 0

    if driftgod.S and driftgod.S.stuntProgressionResetActive == true then
        local baseline = tonumber(driftgod.S.stuntProgressionResetBaseline or 0) or 0
        local guarded = math.max(0, raw - baseline)

        driftgod.S.stuntUnlockLastDetectedScore = guarded
        driftgod.S.stuntUnlockLastScoreSource = tostring(driftgod.S.stuntUnlockLastScoreSource or "none") .. " guarded"

        return guarded
    end

    driftgod.S.stuntUnlockLastDetectedScore = raw
    return raw
end

function driftgod.GetStuntHudTierLabel(stuntName)
    local tier = driftgod.GetStuntUpgradeTier and driftgod.GetStuntUpgradeTier(stuntName) or 1
    return "Tier " .. tostring(tier)
end

driftgod.S.stuntTierUseCooldownMs = driftgod.S.stuntTierUseCooldownMs or 900
driftgod.S.stuntTierLastAcceptedUseMs = driftgod.S.stuntTierLastAcceptedUseMs or {}
driftgod.S.stuntTierLastBlockedUseMs = driftgod.S.stuntTierLastBlockedUseMs or {}

function driftgod.CanRecordStuntUseNow(stuntName)
    if not driftgod.S then return false, "no state" end

    local now = driftgod.GetMs and driftgod.GetMs() or 0
    local key = driftgod.GetStuntUseKey and driftgod.GetStuntUseKey(stuntName) or tostring(stuntName or "")
    if key == "" then return false, "missing stunt" end

    if driftgod.S.stuntBusy == true or driftgod.S.stuntIsBusy == true or driftgod.S.isStuntRunning == true then
        return false, "stunt busy"
    end

    if tonumber(driftgod.S.stuntBusyUntil or 0) > now then
        return false, "busy until"
    end

    if tonumber(driftgod.S.stuntCooldownUntil or 0) > now then
        return false, "cooldown until"
    end

    if tonumber(driftgod.S.nextStuntAllowedAt or 0) > now then
        return false, "next allowed"
    end

    if tonumber(driftgod.S.stuntInputLockUntil or 0) > now then
        return false, "input lock"
    end

    driftgod.S.stuntTierLastAcceptedUseMs = driftgod.S.stuntTierLastAcceptedUseMs or {}
    local last = tonumber(driftgod.S.stuntTierLastAcceptedUseMs[key] or 0) or 0
    local cd = tonumber(driftgod.S.stuntTierUseCooldownMs or 900) or 900

    if last > 0 and (now - last) < cd then
        return false, "tier use cooldown"
    end

    return true, "ok"
end

function driftgod.MarkStuntUseAccepted(stuntName)
    if not driftgod.S then return end
    local key = driftgod.GetStuntUseKey and driftgod.GetStuntUseKey(stuntName) or tostring(stuntName or "")
    driftgod.S.stuntTierLastAcceptedUseMs = driftgod.S.stuntTierLastAcceptedUseMs or {}
    driftgod.S.stuntTierLastAcceptedUseMs[key] = driftgod.GetMs and driftgod.GetMs() or 0
end

function driftgod.RecordStuntUseIfAllowed(stuntName)
    local ok, reason = true, "ok"
    if driftgod.CanRecordStuntUseNow then
        ok, reason = driftgod.CanRecordStuntUseNow(stuntName)
    end

    if not ok then
        if driftgod.S then
            local key = driftgod.GetStuntUseKey and driftgod.GetStuntUseKey(stuntName) or tostring(stuntName or "")
            driftgod.S.stuntTierLastBlockedUseMs = driftgod.S.stuntTierLastBlockedUseMs or {}
            driftgod.S.stuntTierLastBlockedUseMs[key] = driftgod.GetMs and driftgod.GetMs() or 0
        end

        if driftgod.DebugLog and driftgod.S and driftgod.S.stuntUseDebug == true then
            driftgod.DebugLog("StuntUpgrades", "Blocked tier use count for " .. tostring(stuntName) .. " | reason=" .. tostring(reason))
        end
        return false
    end

    if driftgod.MarkStuntUseAccepted then driftgod.MarkStuntUseAccepted(stuntName) end
    if driftgod.RecordStuntUse then driftgod.RecordStuntUse(stuntName) end
    return true
end

driftgod.S.progressPatchDeferred = true

driftgod.S.progressDebugEnabled = false
driftgod.S.progressSaveDebugEnabled = false
driftgod.S.menuDebugEnabled = false
driftgod.S.bootDebugEnabled = false

driftgod.S = driftgod.S or {}
driftgod.S.stuntProgressionDebugEnabled = driftgod.S.stuntProgressionDebugEnabled == true

local function DG_A19Num(v)
    return tonumber(v or 0) or 0
end

local function DG_A19ConsiderMax(best, value)
    local n = tonumber(value)
    if n and n > best then return n end
    return best
end

function driftgod.GetLivePostResetUnlockScore()
    local best = 0
    if driftgod.S then

        best = DG_A19ConsiderMax(best, driftgod.S.currentScore)
        best = DG_A19ConsiderMax(best, driftgod.S.previousScore)
        best = DG_A19ConsiderMax(best, driftgod.S.lastRunScore)
        best = DG_A19ConsiderMax(best, driftgod.S.bestScore)
        best = DG_A19ConsiderMax(best, driftgod.S.bestDriftScore)
        best = DG_A19ConsiderMax(best, driftgod.S.progressScore)
        best = DG_A19ConsiderMax(best, driftgod.S.lifetimeScore)
        best = DG_A19ConsiderMax(best, driftgod.S.totalScore)
        best = DG_A19ConsiderMax(best, driftgod.S.totalDriftScore)
        if type(driftgod.S.highScores) == "table" then
            for _, e in ipairs(driftgod.S.highScores) do
                if type(e) == "table" then best = DG_A19ConsiderMax(best, e.score)
                else best = DG_A19ConsiderMax(best, e) end
            end
        end
    end
    return math.floor(best)
end

function driftgod.GetLifetimeScore()
    local raw = driftgod.GetRawEarnedScoreForUnlocks and driftgod.GetRawEarnedScoreForUnlocks() or 0
    raw = DG_A19Num(raw)

    local score = raw
    if driftgod.S and driftgod.S.stuntProgressionResetActive == true then
        local baseline = DG_A19Num(driftgod.S.stuntProgressionResetBaseline)
        local guarded = math.max(0, raw - baseline)
        local live = driftgod.GetLivePostResetUnlockScore and driftgod.GetLivePostResetUnlockScore() or 0
        score = math.max(guarded, live)
        driftgod.S.stuntUnlockLastScoreSource = "A19 guarded/live"
    else
        driftgod.S.stuntUnlockLastScoreSource = driftgod.S and (driftgod.S.stuntUnlockLastScoreSource or "raw") or "raw"
    end

    if driftgod.S then driftgod.S.stuntUnlockLastDetectedScore = math.floor(score) end
    return math.floor(score)
end

function driftgod.GetStuntUnlockScore()
    return math.floor(driftgod.GetLifetimeScore and driftgod.GetLifetimeScore() or 0)
end

function driftgod.SyncLegacyUnlockRewardsFromScore(reason)
    if not (driftgod.S and driftgod.Unlocks) then return end
    if driftgod.S.progressUnlocksEnabled == false then return end
    local score = driftgod.GetStuntUnlockScore and driftgod.GetStuntUnlockScore() or driftgod.GetLifetimeScore and driftgod.GetLifetimeScore() or 0
    driftgod.S.notifiedUnlocks = driftgod.S.notifiedUnlocks or {}
    driftgod.S.unlockedRewards = driftgod.S.unlockedRewards or {}
    local changed = false
    for _, unlock in ipairs(driftgod.Unlocks or {}) do
        if unlock and unlock.id and tonumber(unlock.score or 0) and score >= tonumber(unlock.score or 0) then
            if driftgod.S.unlockedRewards[unlock.id] ~= true then
                driftgod.S.unlockedRewards[unlock.id] = true
                driftgod.S.notifiedUnlocks[unlock.id] = true
                changed = true
            end
        end
    end
    if changed then
        if driftgod.SaveProgress then driftgod.SaveProgress(false) end
        if driftgod.DebugLog then driftgod.DebugLog("StuntUnlocks", "A19 synced legacy unlocks | score=" .. tostring(score) .. " | reason=" .. tostring(reason or "sync")) end
    end
end

function driftgod.SyncStuntUnlockPolishFromScore(reason)
    if not (driftgod.S and driftgod.StuntUnlockOrder) then return end
    if driftgod.AreProgressUnlocksEnabled and not driftgod.AreProgressUnlocksEnabled() then return end
    local highest = driftgod.GetHighestUnlockedStuntName and driftgod.GetHighestUnlockedStuntName() or "Donut"
    if highest and highest ~= "" and highest ~= driftgod.S.stuntUnlockLastHighest then
        local old = driftgod.S.stuntUnlockLastHighest
        driftgod.S.stuntUnlockLastHighest = highest
        if old and old ~= "" and driftgod.StartStuntUnlockBanner then
            driftgod.StartStuntUnlockBanner(highest)
        end
    end
end

function driftgod.ForceCheckStuntProgression(reason)
    if driftgod.SyncLegacyUnlockRewardsFromScore then driftgod.SyncLegacyUnlockRewardsFromScore(reason) end
    if driftgod.SyncStuntUnlockPolishFromScore then driftgod.SyncStuntUnlockPolishFromScore(reason) end
    if driftgod.CheckStuntTierUnlockPolish then driftgod.CheckStuntTierUnlockPolish() end
end

function driftgod.RecordLandedStuntForProgress(stuntName)
    if not (driftgod.S and driftgod.S.stuntUpgradeTiersEnabled) then return false end
    local key = driftgod.GetStuntUseKey and driftgod.GetStuntUseKey(stuntName) or tostring(stuntName or "")
    if key == "" or (driftgod.IsStuntExcluded and driftgod.IsStuntExcluded(key)) then return false end
    if driftgod.IsStuntUnlocked and not driftgod.IsStuntUnlocked(key) then
        if driftgod.ForceCheckStuntProgression then driftgod.ForceCheckStuntProgression("landed locked check") end
        return false
    end

    driftgod.S.stuntUseRunCounts = driftgod.S.stuntUseRunCounts or {}
    driftgod.S.stuntTierFreshUseCounts = driftgod.S.stuntTierFreshUseCounts or {}
    driftgod.S.stuntUseRunCounts[key] = DG_A19Num(driftgod.S.stuntUseRunCounts[key]) + 1

    local earnedTier = driftgod.GetEarnedStuntTier and driftgod.GetEarnedStuntTier(key) or 1
    local targetTier = math.min(3, earnedTier + 1)
    if earnedTier < 3 then
        local freshKey = driftgod.GetFreshUseKey and driftgod.GetFreshUseKey(key, targetTier) or (key .. "_toT" .. tostring(targetTier))
        driftgod.S.stuntTierFreshUseCounts[freshKey] = DG_A19Num(driftgod.S.stuntTierFreshUseCounts[freshKey]) + 1
    end

    if driftgod.CheckSpecificStuntTierUnlock then driftgod.CheckSpecificStuntTierUnlock(key) end
    if driftgod.ForceCheckStuntProgression then driftgod.ForceCheckStuntProgression("landed " .. tostring(key)) end
    if driftgod.SaveProgress then driftgod.SaveProgress(false) end

    if driftgod.DebugLog and driftgod.S.stuntProgressionDebugEnabled == true then
        driftgod.DebugLog("StuntUnlocks", "A19 landed use | " .. tostring(key) .. " | uses=" .. tostring(driftgod.S.stuntUseRunCounts[key]) .. " | score=" .. tostring(driftgod.GetStuntUnlockScore and driftgod.GetStuntUnlockScore() or 0) .. " | tier=" .. tostring(driftgod.GetStuntUpgradeTier and driftgod.GetStuntUpgradeTier(key) or 1))
    end
    return true
end

driftgod.S = driftgod.S or {}
driftgod.S.trickHotkeysEnabled = false
driftgod.S.selectedStuntHotkeyEnabled = false

local function DG_A29Num(v, fallback)
    local n = tonumber(v)
    if n == nil then return fallback or 0 end
    return n
end

local function DG_A29CanonicalStuntName(name)
    local raw = tostring(name or "")
    if raw == "" then return "" end
    if driftgod.NormalizeStuntName then
        local normalized = driftgod.NormalizeStuntName(raw)
        if normalized and normalized ~= "" then return normalized end
    end
    local rawLower = raw:lower()
    for _, stuntName in ipairs(driftgod.StuntUnlockOrder or {}) do
        if tostring(stuntName):lower() == rawLower then return tostring(stuntName) end
    end
    for _, trick in ipairs(driftgod.Tricks or {}) do
        if type(trick) == "table" and tostring(trick.name or ""):lower() == rawLower then
            return tostring(trick.name)
        end
    end
    return raw
end

local function DG_A29NormalizeTierMap(mapName, defaultTier)
    driftgod.S = driftgod.S or {}
    local src = driftgod.S[mapName]
    if type(src) ~= "table" then src = {} end
    local out = {}

    for k, v in pairs(src) do
        local canon = DG_A29CanonicalStuntName(k)
        if canon ~= "" then
            local tier = math.max(1, math.min(3, DG_A29Num(v, defaultTier or 1)))
            out[canon] = math.max(DG_A29Num(out[canon], defaultTier or 1), tier)
        end
    end

    if mapName == "stuntUpgradeEarnedTiers" or mapName == "stuntUpgradeAnnouncedTiers" then
        for _, stuntName in ipairs(driftgod.StuntUnlockOrder or {}) do
            local canon = DG_A29CanonicalStuntName(stuntName)
            if canon ~= "" and out[canon] == nil then out[canon] = defaultTier or 1 end
        end
    end

    driftgod.S[mapName] = out
    return out
end

function driftgod.NormalizeStuntTierPersistence(reason)
    if not driftgod.S then return end
    DG_A29NormalizeTierMap("stuntUpgradeEarnedTiers", 1)
    DG_A29NormalizeTierMap("stuntUpgradeAnnouncedTiers", 1)

    if type(driftgod.S.stuntTierFreshUseCounts) ~= "table" then driftgod.S.stuntTierFreshUseCounts = {} end
    if type(driftgod.S.stuntUseRunCounts) ~= "table" then driftgod.S.stuntUseRunCounts = {} end

    if driftgod.DebugLog and driftgod.S.stuntProgressionDebugEnabled == true then
        driftgod.DebugLog("StuntUpgrades", "A29 normalized stunt tier persistence | reason=" .. tostring(reason or "manual"))
    end
end

local DG_A29OldGetEarnedStuntTier = driftgod.GetEarnedStuntTier
function driftgod.GetEarnedStuntTier(stuntName)
    if driftgod.NormalizeStuntTierPersistence then driftgod.NormalizeStuntTierPersistence("get tier") end
    local key = DG_A29CanonicalStuntName(stuntName)
    driftgod.S.stuntUpgradeEarnedTiers = driftgod.S.stuntUpgradeEarnedTiers or {}
    local tier = DG_A29Num(driftgod.S.stuntUpgradeEarnedTiers[key], 1)
    if driftgod.IsStuntUnlocked and not driftgod.IsStuntUnlocked(key) then return 1 end
    return math.max(1, math.min(3, tier))
end

local DG_A29OldSetEarnedStuntTier = driftgod.SetEarnedStuntTier
function driftgod.SetEarnedStuntTier(stuntName, tier)
    driftgod.S = driftgod.S or {}
    driftgod.S.stuntUpgradeEarnedTiers = driftgod.S.stuntUpgradeEarnedTiers or {}
    driftgod.S.stuntUpgradeAnnouncedTiers = driftgod.S.stuntUpgradeAnnouncedTiers or {}

    local key = DG_A29CanonicalStuntName(stuntName)
    local newTier = math.max(1, math.min(3, DG_A29Num(tier, 1)))
    local oldTier = DG_A29Num(driftgod.S.stuntUpgradeEarnedTiers[key], 1)

    driftgod.S.stuntUpgradeEarnedTiers[key] = math.max(oldTier, newTier)
    driftgod.S.stuntUpgradeAnnouncedTiers[key] = math.max(DG_A29Num(driftgod.S.stuntUpgradeAnnouncedTiers[key], 1), driftgod.S.stuntUpgradeEarnedTiers[key])

    if driftgod.NormalizeStuntTierPersistence then driftgod.NormalizeStuntTierPersistence("set tier " .. tostring(key)) end

    if driftgod.S.stuntUpgradeEarnedTiers[key] ~= oldTier and not driftgod._savingProgressNow then
        if driftgod.SaveProgressHard then driftgod.SaveProgressHard("stunt tier changed: " .. tostring(key) .. " T" .. tostring(driftgod.S.stuntUpgradeEarnedTiers[key]))
        elseif driftgod.SaveProgress then driftgod.SaveProgress(false) end
    end
end

function driftgod.ApplyLoadedStuntTierProgress(data, reason)
    if type(data) ~= "table" then return end
    driftgod.S = driftgod.S or {}
    if type(data.stuntUpgradeEarnedTiers) == "table" then driftgod.S.stuntUpgradeEarnedTiers = data.stuntUpgradeEarnedTiers end
    if type(data.stuntUpgradeAnnouncedTiers) == "table" then driftgod.S.stuntUpgradeAnnouncedTiers = data.stuntUpgradeAnnouncedTiers end
    if type(data.stuntTierFreshUseCounts) == "table" then driftgod.S.stuntTierFreshUseCounts = data.stuntTierFreshUseCounts end
    if type(data.stuntUseRunCounts) == "table" then driftgod.S.stuntUseRunCounts = data.stuntUseRunCounts end
    if driftgod.NormalizeStuntTierPersistence then driftgod.NormalizeStuntTierPersistence(reason or "load") end
end

driftgod.S = driftgod.S or {}

driftgod.S.stuntTierMinRunScoreT2 = driftgod.S.stuntTierMinRunScoreT2 or 500
driftgod.S.stuntTierMinRunScoreT3 = driftgod.S.stuntTierMinRunScoreT3 or 1500
driftgod.S.stuntTierMinMphForUse = driftgod.S.stuntTierMinMphForUse or 8

local function DG_A30Num(v, fallback)
    local n = tonumber(v)
    if n == nil then return fallback or 0 end
    return n
end

function driftgod.GetCurrentRunScoreForStuntTier()
    if not driftgod.S then return 0 end
    return DG_A30Num(driftgod.S.currentScore or driftgod.S.score or driftgod.S.driftScore or 0, 0)
end

function driftgod.GetCurrentMphForStuntTier()
    if driftgod.GetCurrentVehicleMph then return DG_A30Num(driftgod.GetCurrentVehicleMph(), 0) end
    if driftgod.GetSpeedMph then return DG_A30Num(driftgod.GetSpeedMph(), 0) end
    if driftgod.S and driftgod.S.currentMph then return DG_A30Num(driftgod.S.currentMph, 0) end
    return 0
end

function driftgod.GetStuntTierMinRunScore(targetTier)
    targetTier = DG_A30Num(targetTier, 2)
    if targetTier >= 3 then return DG_A30Num(driftgod.S.stuntTierMinRunScoreT3, 1500) end
    return DG_A30Num(driftgod.S.stuntTierMinRunScoreT2, 500)
end

function driftgod.CanCountStuntTierUse(stuntName, targetTier)
    if not driftgod.S then return false, "state missing" end
    local runScore = driftgod.GetCurrentRunScoreForStuntTier and driftgod.GetCurrentRunScoreForStuntTier() or 0
    local minScore = driftgod.GetStuntTierMinRunScore and driftgod.GetStuntTierMinRunScore(targetTier) or 500
    if runScore < minScore then
        return false, "Need " .. tostring(minScore) .. "+ run score"
    end

    local mph = driftgod.GetCurrentMphForStuntTier and driftgod.GetCurrentMphForStuntTier() or 0
    local minMph = DG_A30Num(driftgod.S.stuntTierMinMphForUse, 8)
    if mph < minMph then
        return false, "Need movement"
    end

    return true, "ok"
end

local DG_A30OldRecordStuntUse = driftgod.RecordStuntUse
function driftgod.RecordStuntUse(stuntName)
    if not (driftgod.S and driftgod.S.stuntUpgradeTiersEnabled) then return end

    local key = driftgod.GetStuntUseKey and driftgod.GetStuntUseKey(stuntName) or tostring(stuntName or "")
    if key == "" or (driftgod.IsStuntExcluded and driftgod.IsStuntExcluded(key)) then return end

    driftgod.S.stuntUseRunCounts = driftgod.S.stuntUseRunCounts or {}
    driftgod.S.stuntTierFreshUseCounts = driftgod.S.stuntTierFreshUseCounts or {}

    driftgod.S.stuntUseRunCounts[key] = (DG_A30Num(driftgod.S.stuntUseRunCounts[key], 0)) + 1

    local earnedTier = driftgod.GetEarnedStuntTier and driftgod.GetEarnedStuntTier(key) or 1
    local targetTier = math.min(3, earnedTier + 1)

    if earnedTier < 3 then
        local ok, reason = true, "ok"
        if driftgod.CanCountStuntTierUse then ok, reason = driftgod.CanCountStuntTierUse(key, targetTier) end
        if ok then
            local freshKey = driftgod.GetFreshUseKey and driftgod.GetFreshUseKey(key, targetTier) or (key .. "_toT" .. tostring(targetTier))
            driftgod.S.stuntTierFreshUseCounts[freshKey] = (DG_A30Num(driftgod.S.stuntTierFreshUseCounts[freshKey], 0)) + 1
        else
            driftgod.S.lastStuntTierBlockReason = tostring(reason or "blocked")
            if driftgod.DebugLog and driftgod.S.stuntUseDebug == true then
                driftgod.DebugLog("StuntUpgrades", "Tier use blocked | " .. tostring(key) .. " | " .. tostring(reason))
            end
        end
    end

    if driftgod.DebugLog and driftgod.S.stuntUseDebug == true then
        driftgod.DebugLog("StuntUpgrades", "Use: " .. tostring(key) .. " run=" .. tostring(driftgod.S.stuntUseRunCounts[key]) .. " earnedTier=" .. tostring(earnedTier) .. " score=" .. tostring(driftgod.GetCurrentRunScoreForStuntTier and driftgod.GetCurrentRunScoreForStuntTier() or 0))
    end

    if driftgod.CheckSpecificStuntTierUnlock then driftgod.CheckSpecificStuntTierUnlock(key) end
end

local DG_A30OldGetNextStuntTierRequirementText = driftgod.GetNextStuntTierRequirementText
function driftgod.GetNextStuntTierRequirementText(stuntName)
    local earnedTier = driftgod.GetEarnedStuntTier and driftgod.GetEarnedStuntTier(stuntName) or 1
    if earnedTier >= 3 then return "Max Tier" end

    local targetTier = earnedTier + 1
    local scoreReq = driftgod.GetStuntTierRequirement and driftgod.GetStuntTierRequirement(stuntName, targetTier) or 0
    local minScore = driftgod.GetStuntTierMinRunScore and driftgod.GetStuntTierMinRunScore(targetTier) or 0
    local useCount = driftgod.GetFreshTierUseCount and driftgod.GetFreshTierUseCount(stuntName, targetTier) or 0
    local useReq = driftgod.GetStuntTierUseRequirement and driftgod.GetStuntTierUseRequirement(targetTier) or 0

    return "Tier " .. tostring(targetTier) .. ": " .. tostring(scoreReq) .. " score | " .. tostring(useCount) .. "/" .. tostring(useReq) .. " uses"
end

return DG
end

__DG_BUNDLE_LOADERS["core.driftgod_start_loader"] = function()

local CLEAN_LOGS = true
local MOD_NAME = "DriftGodStart"
local MOD_VERSION = "v0.7.6-stable-selective-pcall-handoff"
local LIVE_STATUS_TITLE = "DriftGodStart"

local APPDATA = os.getenv("APPDATA") or "."
local MENU_ROOT = APPDATA .. "\\Cherax"

driftgod.Try(function()
    if FileMgr and FileMgr.GetMenuRootPath then
        local ok, root = driftgod.Try(FileMgr.GetMenuRootPath)
        if ok and root and tostring(root) ~= "" then
            MENU_ROOT = tostring(root)
        end
    end
end)

local SAVE_DIR = MENU_ROOT .. [[\Lua\DriftGod\assets\driftgod_loading]]
local FRAME_DIR = SAVE_DIR
local FRAME_COUNT = 180
local DURATION_MS = 8200
local FRAME_PREFIX = "DGSFrame_"
local FRAME_EXT = ".png"

local FRAME_REMOTE_ENABLED = true
local FRAME_REMOTE_BASE_URL = "https://raw.githubusercontent.com/ARandomAddonDev/GTAV-Cherax/main/DriftGod/assets/driftgod_loading/"
local FRAME_REMOTE_FALLBACK_BASE_URL = "https://raw.githubusercontent.com/ARandomAddonDev/GTAV-Cherax/main/DriftGod/assets/DriftGodStart/Frames/"
local FRAME_DOWNLOAD_TIMEOUT_TICKS = 280

local State

local function CLog(msg)
    msg = tostring(msg or "")

    if CLEAN_LOGS then
        local lower = string.lower(msg)
        local isImportant =
            string.find(lower, "error", 1, true) or
            string.find(lower, "failed", 1, true) or
            string.find(lower, "missing", 1, true)

        if not isImportant then
            return
        end
    end

    if Logger and Logger.LogInfo then
        Logger.LogInfo("[" .. MOD_NAME .. "] " .. msg)
    elseif Logger and Logger.Log then
        Logger.Log(eLogColor.WHITE, MOD_NAME, msg)
    end
end

local function DGS_AssetProgressLine(done, total)
    done = tonumber(done or 0) or 0
    total = math.max(tonumber(total or 1) or 1, 1)
    if done < 0 then done = 0 end
    if done > total then done = total end
    local pct = math.floor((done / total) * 100 + 0.5)
    local width = 60
    local filled = math.floor((pct / 100) * width + 0.5)
    if filled < 0 then filled = 0 end
    if filled > width then filled = width end
    return string.rep("=", filled) .. " " .. tostring(pct) .. "%", pct
end

local function DGS_WriteRawLine(text)
    text = tostring(text or "")
    local wroteRaw = false
    driftgod.Try(function()
        if Logger and Logger.LogRaw then Logger.LogRaw(text); wroteRaw = true end
    end)
    if not wroteRaw then driftgod.Try(function()
        if Logger and Logger.Raw then Logger.Raw(text); wroteRaw = true end
    end) end
    if not wroteRaw then driftgod.Try(function()
        if Logger and Logger.LogInfoRaw then Logger.LogInfoRaw(text); wroteRaw = true end
    end) end
    if not wroteRaw then driftgod.Try(function()
        if io and io.write then io.write(text); wroteRaw = true end
    end) end
    return wroteRaw
end

local function DGS_QueueStartupBannerAfterCheraxLoaded(delayMs)
    State = State or {}
    if State.startupBannerQueued == true then return end
    State.startupBannerQueued = true
    delayMs = tonumber(delayMs or 125) or 125

    local function printBanner()
        driftgod.Try(function()
            require("core.startup_banner")
            if DG and driftgod.PrintStartupBanner then driftgod.PrintStartupBanner() end
        end)
    end

    if Script and Script.QueueJob then
        Script.QueueJob(function()
            if Script.Yield then Script.Yield(delayMs) end
            printBanner()
        end)
    else
        printBanner()
    end
end

local function DGS_PrintInstallDoneAndBanner()
    State = State or {}
    if State.assetInstallDoneBannerPrinted == true then return end
    State.assetInstallDoneBannerPrinted = true

    local whiteAnsi = "\27[97m"
    local resetAnsi = "\27[0m"
    local doneLine = "\n" .. whiteAnsi .. "[DriftGod] Downloading assets done!" .. resetAnsi .. "\n"
    local wroteRaw = DGS_WriteRawLine(doneLine)
    if not wroteRaw then
        if Logger and Logger.LogInfo then
            Logger.LogInfo("[DriftGod] Downloading assets done!")
        elseif Logger and Logger.Log then
            Logger.Log(eLogColor.WHITE, "DriftGod", "Installing assets... Done!")
        end
    end

    DGS_QueueStartupBannerAfterCheraxLoaded(1500)
end

local function DGS_RawAssetProgress(done, total, final)

    State = State or {}

    local totalNum = math.max(tonumber(total or 1) or 1, 1)
    local doneNum = tonumber(done or 0) or 0
    if doneNum < 0 then doneNum = 0 end
    if doneNum > totalNum then doneNum = totalNum end
    local pct = math.floor((doneNum / totalNum) * 100 + 0.5)

    State.assetDownloadPct = pct
    State.assetDownloadLine = ""
    State.assetDownloadStatus = final == true and "Downloading assets done!" or "Downloading assets..."

    if DG and driftgod.S then
        driftgod.S.bootLoadMessage = State.assetDownloadStatus
        driftgod.S.bootLoadProgress = math.max(0.0, math.min(1.0, pct / 100.0))
    end

    driftgod.Try(function()
        if DG and driftgod.DriftGodStart and driftgod.DriftGodStart.SetModule then
            driftgod.DriftGodStart.SetModule(State.assetDownloadStatus)
        end
        if DG and driftgod.DriftGodStart and driftgod.DriftGodStart.SetProgress then
            driftgod.DriftGodStart.SetProgress(math.max(0.0, math.min(1.0, pct / 100.0)))
        end
    end)

    if final == true then
        if State.assetDownloadDoneLogged ~= true then
            State.assetDownloadDoneLogged = true
            if Logger and Logger.LogInfo then
                Logger.LogInfo("[DriftGod] Downloading assets done!")
            elseif Logger and Logger.Log then
                Logger.Log(eLogColor.WHITE, "DriftGod", "Downloading assets done!")
            end
            DGS_PrintInstallDoneAndBanner()
        end
    else
        if State.assetDownloadStartLogged ~= true then
            State.assetDownloadStartLogged = true
            if Logger and Logger.LogInfo then
                Logger.LogInfo("[DriftGod] Downloading assets...")
            elseif Logger and Logger.Log then
                Logger.Log(eLogColor.WHITE, "DriftGod", "Downloading assets...")
            end
        end
    end
end

local function DGS_LogFrameAssetProgress(done, total)
    total = tonumber(total or 0) or 0
    if total <= 0 then return end
    local pct = math.floor(((tonumber(done or 0) or 0) / total) * 100 + 0.5)
    if pct < 0 then pct = 0 end
    if pct > 100 then pct = 100 end
    local last = tonumber(State and State.framesDownloadLastLoggedPct or -1) or -1
    if last == pct then return end
    if State then State.framesDownloadLastLoggedPct = pct end
    DGS_RawAssetProgress(done, total, pct >= 100)
end

local function DGS_DebugFrameLog(msg)

    if DG and driftgod.S and driftgod.S.driftGodStartDebugToasts == true then
        CLog(msg)
    end
end

local function CToast(msg, ms)
    ms = ms or 3000
    if DG and driftgod.S and driftgod.S.driftGodStartDebugToasts == true then GUI.AddToast(LIVE_STATUS_TITLE, tostring(msg), ms) end
    CLog(msg)
end

local function NowMs()
    if MISC and MISC.GET_GAME_TIMER then
        local ok, value = driftgod.Try(MISC.GET_GAME_TIMER)
        if ok and type(value) == "number" then return value end
    end

    if Time and Time.GetEpocheMs then
        local ok, value = driftgod.Try(Time.GetEpocheMs)
        if ok and type(value) == "number" then return value end
    end

    return math.floor((os.clock() or 0) * 1000)
end

local function FileExists(path)
    local ok, exists = driftgod.Try(function()
        if FileMgr and FileMgr.DoesFileExist then
            return FileMgr.DoesFileExist(path)
        end
        local f = io.open(path, "rb")
        if f then f:close(); return true end
        return false
    end)
    return ok and exists == true
end

local function FramePath(i)
    return FRAME_DIR .. [[\]] .. FRAME_PREFIX .. string.format("%03d", i) .. FRAME_EXT
end

local function FrameRemoteUrl(i, fallback)
    local base = fallback == true and FRAME_REMOTE_FALLBACK_BASE_URL or FRAME_REMOTE_BASE_URL
    return base .. FRAME_PREFIX .. string.format("%03d", i) .. FRAME_EXT
end

local function EnsureDir(path)
    if not path or path == "" then return end
    driftgod.Try(function()
        if FileMgr and FileMgr.CreateDir then
            FileMgr.CreateDir(path)
        else
            os.execute('mkdir "' .. tostring(path) .. '" 2>nul')
        end
    end)
end

local function CurlSetOpt(curl, enumName, numericValue, value)
    if not curl or not curl.Setopt then return end
    local opt = numericValue
    driftgod.Try(function()
        if eCurlOption and eCurlOption[enumName] then opt = eCurlOption[enumName] end
    end)
    driftgod.Try(function() curl:Setopt(opt, value) end)
end

local function LooksLikePng(body)
    if type(body) ~= "string" or #body < 100 then return false end
    if body:byte(1) == 137 and body:sub(2, 4) == "PNG" then return true end
    return false
end

local function CountMissingFrames()
    local missing = 0
    for i = 1, FRAME_COUNT do
        if not FileExists(FramePath(i)) then missing = missing + 1 end
    end
    return missing
end

local function DownloadOneFrame(i)
    if not FRAME_REMOTE_ENABLED then return false, "remote disabled" end
    if not Curl or not Curl.Easy then return false, "Curl unavailable" end
    local path = FramePath(i)
    local lastErr = "unknown"

    for _, fallback in ipairs({ false, true }) do
        local url = FrameRemoteUrl(i, fallback)
        local curl = Curl.Easy()
        CurlSetOpt(curl, "CURLOPT_URL", 10002, url)
        CurlSetOpt(curl, "CURLOPT_USERAGENT", 10018, "Mozilla/5.0 DriftGod-Cherax")
        curl:Perform()

        local ticks = 0
        while not curl:GetFinished() and ticks < FRAME_DOWNLOAD_TIMEOUT_TICKS do
            Script.Yield(50)
            ticks = ticks + 1
        end

        if not curl:GetFinished() then
            lastErr = "timeout"
        else
            local code, body = curl:GetResponse()
            local success = (code == true) or (code == 0)
            driftgod.Try(function()
                if eCurlCode and code == eCurlCode.CURLE_OK then success = true end
            end)

            if success and LooksLikePng(body) then
                EnsureDir(SAVE_DIR)
                EnsureDir(FRAME_DIR)
                local f = io.open(path, "wb")
                if not f then return false, "write failed" end
                f:write(body)
                f:close()
                return true
            end

            lastErr = "download failed code=" .. tostring(code) .. " bytes=" .. tostring(type(body) == "string" and #body or 0)
        end
    end

    return false, lastErr
end

local function QueueMissingFrameDownloads(force)
    if State.framesDownloading then return end
    if State.framesDownloadQueued and force ~= true then return end

    local missing = CountMissingFrames()
    State.framesDownloadMissing = missing
    if missing <= 0 then
        State.framesDownloadQueued = true
        State.framesDownloadComplete = true
        State.framesDownloadFailed = false
        return
    end

    if not FRAME_REMOTE_ENABLED or not Curl or not Curl.Easy then
        State.framesDownloadFailed = true
        State.framesDownloadLast = "Missing " .. tostring(missing) .. " frames and Curl/remote downloader unavailable"
        CLog("[FrameDownload] " .. State.framesDownloadLast)
        return
    end

    State.framesDownloadQueued = true
    State.framesDownloading = true
    State.framesDownloadComplete = false
    State.framesDownloadFailed = false
    State.framesDownloadDone = 0
    State.framesDownloadLastLoggedPct = -1
    DGS_LogFrameAssetProgress(0, missing)

    Script.QueueJob(function()
        local ok, err = driftgod.Try(function()
            EnsureDir(SAVE_DIR)
            EnsureDir(FRAME_DIR)

            for i = 1, FRAME_COUNT do
                if not FileExists(FramePath(i)) then
                    State.framesDownloadLast = FRAME_PREFIX .. string.format("%03d", i) .. FRAME_EXT
                    local dlOk, dlErr = DownloadOneFrame(i)
                    if dlOk then
                        State.framesDownloadDone = State.framesDownloadDone + 1
                        DGS_LogFrameAssetProgress(State.framesDownloadDone, State.framesDownloadMissing)
                    else
                        State.framesDownloadFailed = true
                        State.framesDownloadLast = "Frame " .. tostring(i) .. " " .. tostring(dlErr)
                        CLog("[FrameDownload] " .. State.framesDownloadLast)
                    end
                    Script.Yield(10)
                end
            end
        end)

        if not ok then
            State.framesDownloadFailed = true
            State.framesDownloadLast = tostring(err)
            CLog("[FrameDownload] error: " .. tostring(err))
        end

        State.framesDownloading = false
        State.framesDownloadComplete = CountMissingFrames() <= 0
        if State.framesDownloadComplete then
            State.framesDownloadFailed = false
            DGS_LogFrameAssetProgress(State.framesDownloadMissing, State.framesDownloadMissing)
        elseif not State.framesDownloadFailed then
            State.framesDownloadFailed = true
            State.framesDownloadLast = "download incomplete; missing=" .. tostring(CountMissingFrames())
            CLog("[FrameDownload] " .. State.framesDownloadLast)
        end
    end)
end

local function GetDisplaySize()
    local sw, sh = 1920, 1080
    driftgod.Try(function()
        if ImGui and ImGui.GetDisplaySize then
            local rx, ry = ImGui.GetDisplaySize()
            if type(rx) == "number" and type(ry) == "number" and rx > 0 and ry > 0 then
                sw, sh = rx, ry
            end
        end
    end)
    return sw, sh
end

