}

local function ResetFrames()
    Frames = {}
    State.preloading = false
    State.preloadIndex = 1
    State.loadedCount = 0
    State.textureFailures = 0
    State.lastError = ""
end

local function LoadFrameTexture(i)
    if Frames[i] and Frames[i].textureSrv then
        return true
    end

    if not Texture or not Texture.LoadTexture or not Texture.IsTextureValid or not Texture.GetTexture then
        State.lastError = "Texture API missing"
        return false
    end

    local path = FramePath(i)
    if not FileExists(path) then
        State.lastError = "Missing frame: " .. tostring(path)
        if i == 1 then DGS_DebugFrameLog("[FrameLoad] " .. State.lastError) end
        return false
    end

    local frame = Frames[i] or { textureId = 0, textureSrv = nil, failed = false }
    Frames[i] = frame

    if frame.textureId == 0 then
        local ok, id = driftgod.Try(Texture.LoadTexture, path)
        if ok and type(id) == "number" and id > 0 then
            frame.textureId = id
        else
            frame.failed = true
            State.textureFailures = State.textureFailures + 1
            State.lastError = "Texture.LoadTexture failed frame " .. tostring(i) .. ": " .. tostring(path)
            DGS_DebugFrameLog("[FrameLoad] " .. State.lastError)
            return false
        end
    end

    if frame.textureId > 0 and not frame.textureSrv then
        local validOk, valid = driftgod.Try(Texture.IsTextureValid, frame.textureId)
        if not validOk or not valid then
            frame.failed = true
            State.lastError = "Texture invalid frame " .. tostring(i) .. " id=" .. tostring(frame.textureId)
            DGS_DebugFrameLog("[FrameLoad] " .. State.lastError)
            return false
        end

        local ok, d3d = driftgod.Try(Texture.GetTexture, frame.textureId)
        if ok and d3d then
            local srvOk, srv = driftgod.Try(function()
                return d3d:GetCurrent()
            end)
            if srvOk and srv then
                frame.textureSrv = srv
                State.loadedCount = State.loadedCount + 1
                if i == 1 or i == FRAME_COUNT then
                    DGS_DebugFrameLog("[FrameLoad] Loaded frame " .. tostring(i) .. "/" .. tostring(FRAME_COUNT) .. " id=" .. tostring(frame.textureId))
                end
                return true
            end
        end

        State.lastError = "GetCurrent failed frame " .. tostring(i) .. " id=" .. tostring(frame.textureId)
        DGS_DebugFrameLog("[FrameLoad] " .. State.lastError)
        return false
    end

    return frame.textureSrv ~= nil
end

local function PreloadStep()
    if not State.preloading then return end

    QueueMissingFrameDownloads(false)

    if State.preloadIndex > FRAME_COUNT then
        State.preloading = false
        if (State.loadedCount or 0) <= 0 then
            CLog("Frame preload error: no DriftGod loading frames loaded from " .. tostring(FRAME_DIR))
        else
            DGS_DebugFrameLog("Frame preload complete: " .. tostring(State.loadedCount) .. "/" .. tostring(FRAME_COUNT))
        end
        return
    end

    if not FileExists(FramePath(State.preloadIndex)) then
        if State.framesDownloading or not State.framesDownloadComplete then
            return
        end

        State.preloadIndex = State.preloadIndex + 1
        return
    end

    LoadFrameTexture(State.preloadIndex)
    State.preloadIndex = State.preloadIndex + 1
end

local function StartAnimation()
    State.active = true
    State.started = true
    State.startMs = NowMs()
    State.lastError = ""
    State.preloading = true
    if State.loadedCount <= 0 then
        State.preloadIndex = 1
    end
    if State.holdFrameOne then
        CToast("DriftGod static frame preview started (Hold Frame 001 is ON).", 1500)
    else
        CToast("DriftGod VVS-style frame animation started.", 1500)
    end
end

local function StopAnimation()
    State.active = false
    CToast("DriftGod VVS-style frame animation stopped.", 1200)
end

local NativeOK = false
local function DGS_BuildTextNatives()
    if not Natives or not Natives.InvokeVoid then return false end
    local InvokeVoid = Natives.InvokeVoid
    HUD = HUD or {}
    HUD.SET_TEXT_FONT = HUD.SET_TEXT_FONT or function(font) return InvokeVoid(0x66E0276CC5F6B9DA, font) end
    HUD.SET_TEXT_SCALE = HUD.SET_TEXT_SCALE or function(scale, size) return InvokeVoid(0x07C837F9A01C34C9, scale + 0.0, size + 0.0) end
    HUD.SET_TEXT_COLOUR = HUD.SET_TEXT_COLOUR or function(r, g, b, a) return InvokeVoid(0xBE6B23FFA53FB442, r, g, b, a) end
    HUD.SET_TEXT_CENTRE = HUD.SET_TEXT_CENTRE or function(toggle) return InvokeVoid(0xC02F4DBFB51D988B, toggle) end
    HUD.SET_TEXT_DROP_SHADOW = HUD.SET_TEXT_DROP_SHADOW or function() return InvokeVoid(0x1CA3E9EAC9D93E5E) end
    HUD.SET_TEXT_OUTLINE = HUD.SET_TEXT_OUTLINE or function() return InvokeVoid(0x2513DFB0FB8400FE) end
    HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT = HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT or function(text) return InvokeVoid(0x25FBB336DF1804CB, text) end
    HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME = HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME or function(text) return InvokeVoid(0x6C188BE134E074AA, tostring(text)) end
    HUD.END_TEXT_COMMAND_DISPLAY_TEXT = HUD.END_TEXT_COMMAND_DISPLAY_TEXT or function(x, y) return InvokeVoid(0xCD015E5BB0D96A57, x + 0.0, y + 0.0) end
    return true
end
NativeOK = DGS_BuildTextNatives()

local function DGS_DrawNativeText(text, x, y, size, r, g, b, a, font)
    if not NativeOK or not HUD or not HUD.SET_TEXT_FONT then return false end
    return driftgod.Try(function()
        HUD.SET_TEXT_FONT(font or 7)
        HUD.SET_TEXT_SCALE(0.0, (size or 0.4) + 0.0)
        HUD.SET_TEXT_COLOUR(r or 255, g or 255, b or 255, a or 255)
        HUD.SET_TEXT_CENTRE(true)
        HUD.SET_TEXT_DROP_SHADOW()
        HUD.SET_TEXT_OUTLINE()
        HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT("STRING")
        HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME(tostring(text or ""))
        HUD.END_TEXT_COMMAND_DISPLAY_TEXT((x or 0.5) + 0.0, (y or 0.5) + 0.0)
    end)
end

local function PackedColor(alpha)
    alpha = math.floor(alpha or 255)
    if alpha < 0 then alpha = 0 end
    if alpha > 255 then alpha = 255 end

    return ((alpha & 0xFF) << 24) | 0xFFFFFF
end

local function DrawNativeTestPanel(sw, sh, x, y, size, alpha)
    if not State.showPanel or not ImGui then return end

    driftgod.Try(function()
        ImGui.BgAddRectFilled(x, y, x + size, y + size, 0, 0, 0, math.floor(alpha * 0.18), 12.0, 0)
        ImGui.BgAddRect(x, y, x + size, y + size, 139, 92, 246, math.floor(alpha * 0.62), 12.0, 0, 2.0)
        ImGui.BgAddRectFilled(x + size * 0.15, y + size * 0.15, x + size * 0.85, y + size * 0.85, 139, 92, 246, math.floor(alpha * 0.10), 20.0, 0)
    end)
end

local function DGS_AddLine(x1, y1, x2, y2, r, g, b, a, thickness)
    if not ImGui then return false end
    local ok = false

    ok = driftgod.Try(function()
        if ImGui.BgAddLine then
            ImGui.BgAddLine(x1, y1, x2, y2, r, g, b, a, thickness or 2.0)
        else
            error("BgAddLine missing")
        end
    end)
    if ok then return true end

    ok = driftgod.Try(function()
        if ImGui.GetBackgroundDrawList then
            local dl = ImGui.GetBackgroundDrawList()
            if dl and dl.AddLine then
                local col = 0xFFFFFFFF
                if ImGui.ColorConvertRGBAToU32 then
                    col = ImGui.ColorConvertRGBAToU32({r or 255, g or 255, b or 255, a or 255})
                else
                    col = (((a or 255) & 0xFF) << 24) | ((b or 255) << 16) | ((g or 255) << 8) | (r or 255)
                end
                dl:AddLine(x1, y1, x2, y2, col, thickness or 2.0)
            else
                error("DrawList AddLine missing")
            end
        else
            error("GetBackgroundDrawList missing")
        end
    end)

    return ok == true
end

local function DGS_DrawArc(cx, cy, radius, startDeg, endDeg, r, g, b, a, thickness, segments)
    segments = segments or 72
    local startRad = math.rad(startDeg)
    local endRad = math.rad(endDeg)
    local span = endRad - startRad
    local prevX, prevY = nil, nil

    for i = 0, segments do
        local t = i / segments
        local ang = startRad + span * t
        local x = cx + math.cos(ang) * radius
        local y = cy + math.sin(ang) * radius
        if prevX then
            DGS_AddLine(prevX, prevY, x, y, r, g, b, a, thickness)
        end
        prevX, prevY = x, y
    end
end

local function DGS_DrawLiveLoaderUI(progress, sw, sh, alpha)
    if not State.liveLoaderUI or not ImGui then return end

    if State.loaderActive then
        if DGL_GetExampleTarget then DGL_GetExampleTarget() end
        if DGL_UpdateDisplayProgress then DGL_UpdateDisplayProgress() end
        if State.loaderDone and not State.loaderFadeOut and (tonumber(State.loaderDisplayProgress or 0.0) or 0.0) >= 0.995 then
            State.loaderFadeOut = true
            State.loaderFadeStartMs = NowMs()
        end
        progress = State.loaderDisplayProgress or progress or 0.0
        if DGL_GetLoaderAlpha then
            alpha = DGL_GetLoaderAlpha()
        else
            alpha = 255
        end

        if State.loaderFullyComplete or (tonumber(alpha) or 0) <= 0 then
            return
        end
    end

    progress = progress or 0
    if State.loadingPercentOverride ~= nil and not State.loaderActive then
        progress = math.max(0.0, math.min(1.0, tonumber(State.loadingPercentOverride) or progress))
    end

    local baseScale = math.min(sw, sh) / 1080.0
    if baseScale < 0.70 then baseScale = 0.70 end

    local ringX = tonumber(State.uiRingX) or 0.490
    local ringZ = tonumber(State.uiRingZ) or 0.435
    local ringScale = tonumber(State.uiRingScale) or 0.700

    local pctX = tonumber(State.uiPercentX) or 0.490
    local pctZ = tonumber(State.uiPercentZ) or 0.387
    local pctScale = tonumber(State.uiPercentScale) or 0.600

    local txtX = tonumber(State.uiTextX) or 0.490
    local txtZ = tonumber(State.uiTextZ) or 0.460
    local txtScale = tonumber(State.uiTextScale) or 0.650

    local cx = sw * ringX
    local cy = sh * ringZ
    local scale = baseScale * ringScale

    local radius = 150 * scale
    local baseThick = 15 * scale
    local progThick = 22 * scale
    local a = math.max(0, math.min(255, math.floor(alpha or 255)))

    DGS_DrawArc(cx, cy, radius, -90, 270, 255, 255, 255, math.floor(a * 0.46), baseThick, 120)
    DGS_DrawArc(cx, cy, radius, -90, -90 + progress * 360.0, 139, 92, 246, math.floor(a * 0.98), progThick, 120)
    DGS_DrawArc(cx, cy, radius + (13 * scale), -90, -90 + progress * 360.0, 183, 110, 255, math.floor(a * 0.48), 4 * scale, 120)

    local pct = math.floor(progress * 100 + 0.5)
    local pctText = tostring(pct) .. "%"

    local loadingText = "LOADING"
    if State.loaderActive then
        loadingText = tostring(State.loaderCurrentModule or "Loading...")
    end

    local usedNativePct = DGS_DrawNativeText(pctText, pctX, pctZ, 0.78 * baseScale * pctScale, 245, 245, 255, a, 7)
    local usedNativeLabel = DGS_DrawNativeText(loadingText, txtX, txtZ, 0.25 * baseScale * txtScale, 175, 175, 190, math.floor(a * 0.78), 4)

    if not usedNativePct then
        driftgod.Try(function()
            ImGui.BgAddText((sw * pctX) - (28 * baseScale * pctScale), (sh * pctZ) - (24 * baseScale * pctScale), pctText, 245, 245, 255, a)
        end)
    end

    if not usedNativeLabel then
        driftgod.Try(function()
            ImGui.BgAddText((sw * txtX) - (34 * baseScale * txtScale), sh * txtZ, loadingText, 175, 175, 190, math.floor(a * 0.75))
        end)
    end
end

local function DGS_Clamp01(v)
    v = tonumber(v) or 0.0
    if v < 0.0 then return 0.0 end
    if v > 1.0 then return 1.0 end
    return v
end

local function DrawFrameDownloadUI(sw, sh)
    if not ImGui then return false end

    local missingTotal = tonumber(State.framesDownloadMissing or 0) or 0
    local done = tonumber(State.framesDownloadDone or 0) or 0
    local active = State.framesDownloading == true
    local pending = State.framesDownloadQueued == true and State.framesDownloadComplete ~= true and missingTotal > 0
    local failed = State.framesDownloadFailed == true and State.framesDownloadComplete ~= true and missingTotal > 0

    if not active and not pending and not failed then
        State.framesDownloadUiVisible = false

        State.installerUiPct = nil
        State.installerUiPercentText = nil
        State.installerUiFileText = nil
        State.installerUiCountText = nil
        State.installerUiLastUpdateMs = nil
        return false
    end

    State.framesDownloadUiVisible = true

    if missingTotal <= 0 then missingTotal = FRAME_COUNT end
    if done < 0 then done = 0 end
    if done > missingTotal then done = missingTotal end

    local rawPct = 0.0
    if missingTotal > 0 then rawPct = done / missingTotal end
    rawPct = DGS_Clamp01(rawPct)

    local now = NowMs()

    if State.installerUiPct == nil or rawPct < 0.001 then
        State.installerUiPct = rawPct
    else
        local current = tonumber(State.installerUiPct or 0.0) or 0.0
        if rawPct > current then
            local step = math.max(0.010, (rawPct - current) * 0.50)
            State.installerUiPct = math.min(rawPct, current + step)
        elseif rawPct >= 0.999 then
            State.installerUiPct = rawPct
        end
    end

    if State.installerUiLastUpdateMs == nil or now - (State.installerUiLastUpdateMs or 0) > 140 then
        State.installerUiLastUpdateMs = now
        local pctForText = math.floor(DGS_Clamp01(State.installerUiPct) * 100 + 0.5)
        State.installerUiPercentText = tostring(pctForText) .. "%"
        State.installerUiCountText = tostring(done) .. " / " .. tostring(missingTotal)

        local currentFile = tostring(State.framesDownloadLast or "")
        if currentFile == "" then currentFile = "Preparing..." end
        local displayFile = tostring(currentFile or "")
        displayFile = string.gsub(displayFile, "\\", "/")
        displayFile = string.match(displayFile, "([^/]+)$") or displayFile
        if displayFile == "" then displayFile = "Preparing..." end
        if failed then
            State.installerUiFileText = "Retrying safely: " .. tostring(displayFile)
        else
            State.installerUiFileText = tostring(displayFile)
        end
        State.installerUiCurrentAssetText = currentFile
    end

    local pct = DGS_Clamp01(State.installerUiPct)
    local percentText = tostring(State.installerUiPercentText or (tostring(math.floor(pct * 100 + 0.5)) .. "%"))
    local fileText = tostring(State.installerUiFileText or "Preparing...")
    local countText = tostring(State.installerUiCountText or (tostring(done) .. " / " .. tostring(missingTotal)))

    local barW = math.min(sw * 0.44, 620)
    local barH = 16
    local barX = (sw - barW) * 0.5
    local barY = sh * 0.505
    local fillW = barW * pct

    driftgod.Try(function()
        ImGui.BgAddRectFilled(barX, barY, barX + barW, barY + barH, 18, 18, 24, 210, 7.0, 0)
        ImGui.BgAddRectFilled(barX, barY, barX + fillW, barY + barH, 139, 92, 246, 245, 7.0, 0)
        ImGui.BgAddRect(barX, barY, barX + barW, barY + barH, 220, 205, 255, 155, 7.0, 0, 1.0)
    end)

    local usedPct = DGS_DrawNativeText(percentText, 0.5, (barY - 66) / sh, 0.46, 245, 245, 255, 255, 7)
    local usedFile = DGS_DrawNativeText(fileText, 0.5, (barY + 34) / sh, 0.22, 210, 205, 230, 230, 4)
    local usedCount = DGS_DrawNativeText(countText, 0.5, (barY + 58) / sh, 0.20, 165, 165, 185, 220, 4)

    driftgod.Try(function()
        if not usedPct then ImGui.BgAddText(barX + (barW * 0.5) - 18, barY - 76, percentText, 245,245,255,255) end
        if not usedFile then ImGui.BgAddText(barX, barY + 30, fileText, 210,205,230,230) end
        if not usedCount then ImGui.BgAddText(barX, barY + 54, countText, 165,165,185,220) end
    end)

    return true
end

local function DrawDebugText(sw, sh, text, line, r, g, b)
    if not ImGui then return end
    driftgod.Try(function()
        ImGui.BgAddText(sw * 0.36, sh * (0.80 + line * 0.026), tostring(text), r or 255, g or 255, b or 255, 230)
    end)
end

local function DrawFrameOnPresent()
    if DGS_AutoStartController then DGS_AutoStartController() end
    PreloadStep()

    local swForDownload, shForDownload = GetDisplaySize()
    if DrawFrameDownloadUI(swForDownload, shForDownload) then
        return
    end

    if State.dynamicOnlyWindow then
        if State.loaderFullyComplete then
            return
        end

        if not State.loaderActive and not State.dynamicExample then
            return
        end
    end

    if not State.active and not State.persistent and not State.holdFrameOne then
        return
    end
    if not ImGui then return end

    local now = NowMs()
    if not State.started then
        State.started = true
        State.startMs = now
    end

    local elapsed = now - (State.startMs or now)
    if elapsed < 0 then elapsed = 0 end

    if elapsed > DURATION_MS and not State.persistent and not State.holdFrameOne then
        State.active = false
        return
    elseif elapsed > DURATION_MS and (State.persistent or State.holdFrameOne) then
        State.startMs = now
        elapsed = 0
    end

    local progress = elapsed / DURATION_MS
    if progress < 0 then progress = 0 end
    if progress > 1 then progress = 1 end

    local frameIndex = math.floor(progress * (FRAME_COUNT - 1)) + 1
    if State.holdFrameOne then frameIndex = 1 end
    State.lastFrame = frameIndex

    if not Frames[frameIndex] or not Frames[frameIndex].textureSrv then
        LoadFrameTexture(frameIndex)
    end

    local frame = Frames[frameIndex]
    local sw, sh = GetDisplaySize()
    local loopX = tonumber(State.driftLoopX) or 0.500
    local loopZ = tonumber(State.driftLoopZ) or 0.420
    local loopScale = tonumber(State.driftLoopScale) or 1.000

    local size = math.min((State.drawSize or 560) * loopScale, math.min(sw, sh) * 0.74 * loopScale)
    local x = (sw * loopX) - (size * 0.5)
    local y = (sh * loopZ) - (size * 0.5)

    local alpha = 255
    if elapsed < 350 then
        alpha = math.floor(255 * (elapsed / 350))
    elseif elapsed > (DURATION_MS - 700) and not State.persistent and not State.holdFrameOne then
        local remain = DURATION_MS - elapsed
        alpha = math.floor(255 * (remain / 700))
    end
    if alpha < 0 then alpha = 0 end
    if alpha > 255 then alpha = 255 end

    if State.loaderFadeOut and DGL_GetLoaderAlpha then
        local loaderAlpha = tonumber(DGL_GetLoaderAlpha()) or 255
        alpha = math.floor(alpha * (loaderAlpha / 255.0))
    end

    DrawNativeTestPanel(sw, sh, x, y, size, alpha)

    State.lastDrawOk = false

    if frame and frame.textureSrv then
        local color = PackedColor(alpha)

        local ok, err = driftgod.Try(function()
            ImGui.BgAddImage(frame.textureSrv, x, y, x + size, y + size, 0.0, 0.0, 1.0, 1.0, color)
        end)

        if ok then
            State.lastError = ""
            State.lastDrawOk = true
        else
            State.lastError = "BgAddImage failed: " .. tostring(err)
        end
    else
        State.lastError = "No textureSrv for frame " .. tostring(frameIndex)
    end

    DGS_DrawLiveLoaderUI(progress, sw, sh, alpha)

    if State.debug then
        DrawDebugText(sw, sh, "v0.3.9 ON_PRESENT | frame=" .. tostring(frameIndex) .. "/" .. tostring(FRAME_COUNT) .. " loaded=" .. tostring(State.loadedCount) .. " drawOk=" .. tostring(State.lastDrawOk), 0, 255, 255, 255)
        DrawDebugText(sw, sh, "texId=" .. tostring(frame and frame.textureId or 0) .. " srv=" .. tostring(frame and frame.textureSrv ~= nil) .. " active=" .. tostring(State.active), 1, 210, 210, 255)
        DrawDebugText(sw, sh, "lastError=" .. tostring(State.lastError or ""), 2, 255, 150, 150)
    end
end

local function ClampUI(v)
    v = tonumber(v) or 0.5
    if v < 0.0 then return 0.0 end
    if v > 1.0 then return 1.0 end
    return v
end

local function ClampScale(v)
    v = tonumber(v) or 1.0
    if v < 0.25 then return 0.25 end
    if v > 3.00 then return 3.00 end
    return v
end

local function NudgeUI(field, delta)
    State[field] = ClampUI((tonumber(State[field]) or 0.5) + delta)
    CToast(field .. ": " .. string.format("%.3f", State[field]), 850)
end

local function NudgeScale(field, delta)
    State[field] = ClampScale((tonumber(State[field]) or 1.0) + delta)
    CToast(field .. ": " .. string.format("%.2f", State[field]), 850)
end

local function LogUIConfig()
    CLog("[UIConfig] "
        .. "Ring X=" .. string.format("%.3f", State.uiRingX or 0)
        .. " Z=" .. string.format("%.3f", State.uiRingZ or 0)
        .. " Scale=" .. string.format("%.2f", State.uiRingScale or 1)
        .. " | Percent X=" .. string.format("%.3f", State.uiPercentX or 0)
        .. " Z=" .. string.format("%.3f", State.uiPercentZ or 0)
        .. " Scale=" .. string.format("%.2f", State.uiPercentScale or 1)
        .. " | Text X=" .. string.format("%.3f", State.uiTextX or 0)
        .. " Z=" .. string.format("%.3f", State.uiTextZ or 0)
        .. " Scale=" .. string.format("%.2f", State.uiTextScale or 1)
        .. " | DriftLoop X=" .. string.format("%.3f", State.driftLoopX or 0)
        .. " Z=" .. string.format("%.3f", State.driftLoopZ or 0)
        .. " Scale=" .. string.format("%.2f", State.driftLoopScale or 1)
        .. " | Step=" .. string.format("%.3f", State.uiStep or 0.005)
        .. " ScaleStep=" .. string.format("%.3f", State.uiScaleStep or 0.050))
end

local DYNAMIC_EXAMPLE_STAGES = {
    { name = "Core Boot",          pct = 0.08, hold = 450 },
    { name = "Config / Saves",     pct = 0.16, hold = 650 },
    { name = "Frame Textures",     pct = 0.28, hold = 900 },
    { name = "UI Tabs",            pct = 0.40, hold = 850 },
    { name = "Drift Engine",       pct = 0.58, hold = 1250 },
    { name = "Ghost Replay",       pct = 0.72, hold = 1000 },
    { name = "Race System",        pct = 0.86, hold = 850 },
    { name = "Finalizing",         pct = 0.96, hold = 600 },
    { name = "DriftGod Ready",     pct = 1.00, hold = 650 }
}

local function DGL_Clamp01(v)
    v = tonumber(v) or 0.0
    if v < 0.0 then return 0.0 end
    if v > 1.0 then return 1.0 end
    return v
end

function DriftGodLoader_SetModule(name)
    State.loaderCurrentModule = tostring(name or "Loading...")
end

function DriftGodLoader_SetProgress(value)
    State.loaderRealProgress = DGL_Clamp01(value or 0.0)
end

function DriftGodLoader_Finish()
    State.loaderRealProgress = 1.0
    State.loaderCurrentModule = "DriftGod Ready"
    State.loaderDone = true
end

function DGL_ResetExample()
    State.dynamicExample = true
    State.loaderActive = true
    State.loaderDone = false
    State.loaderStartMs = NowMs()
    State.loaderRealProgress = 0.0
    State.loaderDisplayProgress = 0.0
    State.loaderCurrentModule = "Starting DriftGod..."
    State.loaderLastStage = 0
    State.loaderFadeOut = false
    State.loaderFadeStartMs = 0

    State.active = true
    State.started = true
    State.persistent = true
    State.holdFrameOne = false
    State.loaderFullyComplete = false
    State.startMs = NowMs()

    CToast("Dynamic loader started.", 1500)
    CLog("[DynamicLoader] Example started.")
end

function DGL_StopExample()
    State.dynamicExample = false
    State.loaderActive = false
    State.loaderDone = false
    State.loaderFadeOut = false
    State.loaderCurrentModule = "Waiting..."

    State.active = false
    State.started = false
    State.persistent = false
    State.holdFrameOne = false
    State.loaderFullyComplete = true

    CToast("Dynamic loader stopped.", 1200)
    CLog("[DynamicLoader] Example stopped.")
end

function DGL_GetExampleTarget()
    if not State.dynamicExample or not State.loaderActive then return end

    local elapsed = NowMs() - (State.loaderStartMs or NowMs())
    local total = 0
    local stageIndex = 1

    for i, st in ipairs(DYNAMIC_EXAMPLE_STAGES) do
        total = total + (st.hold or 500)
        if elapsed <= total then
            stageIndex = i
            break
        end
        stageIndex = i
    end

    local st = DYNAMIC_EXAMPLE_STAGES[stageIndex] or DYNAMIC_EXAMPLE_STAGES[#DYNAMIC_EXAMPLE_STAGES]
    if stageIndex ~= State.loaderLastStage then
        State.loaderLastStage = stageIndex
        DriftGodLoader_SetModule(st.name)
        DriftGodLoader_SetProgress(st.pct)
        CLog("[DynamicLoader] Loading: " .. tostring(st.name) .. " -> " .. tostring(math.floor((st.pct or 0) * 100)) .. "%")
    end

    if elapsed > total and stageIndex >= #DYNAMIC_EXAMPLE_STAGES then
        DriftGodLoader_Finish()
        if not State.loaderFadeOut then
            State.loaderFadeOut = true
            State.loaderFadeStartMs = NowMs()
        end
    end
end

function DGL_UpdateDisplayProgress()
    local real = DGL_Clamp01(State.loaderRealProgress or 0.0)
    local display = DGL_Clamp01(State.loaderDisplayProgress or 0.0)

    local speed
    if display < 0.20 then
        speed = 0.105
    elseif display < 0.72 then
        speed = 0.035
    else
        speed = 0.085
    end

    local diff = real - display
    if math.abs(diff) < 0.001 then
        display = real
    else
        display = display + diff * speed
    end

    State.loaderDisplayProgress = DGL_Clamp01(display)
end

function DGL_GetLoaderAlpha()
    if not State.loaderFadeOut then return 255 end
    local elapsed = NowMs() - (State.loaderFadeStartMs or NowMs())
    local fadeMs = tonumber(State.loaderFadeDurationMs or 2600) or 2600
    if fadeMs < 600 then fadeMs = 600 end

    local t = math.min(1.0, math.max(0.0, elapsed / fadeMs))
    local eased = t * t * (3.0 - 2.0 * t)
    local k = 1.0 - eased
    if k <= 0.0 then
        State.loaderActive = false
        State.dynamicExample = false

        State.active = false
        State.started = false
        State.persistent = false
        State.holdFrameOne = false

        State.loaderCurrentModule = "Waiting..."
        State.loaderFullyComplete = true

        return 0
    end
    return math.floor(255 * k)
end

local function DGS_AutoCallPreloadFrames()

    if State then
        State.preloading = true
        State.preloadIndex = 1
        State.lastError = ""
        CToast("Frame preload auto-queued.", 1200)
        return true
    end
    return false
end

local function DGS_AutoCallStartAnimation()

    if State then
        State.active = false
        State.started = false
        State.startMs = 0
        State.lastError = ""
        State.preloading = false
        State.holdFrameOne = false
        State.persistent = false
        CLog("[AutoStartDiag] Preload ready; base animation intentionally held until dynamic loader starts.")
        return true
    end
    return false
end

local function DGS_AutoApplyRecommendedSettings()
    State.holdFrameOne = false
    State.persistent = true
    State.showPanel = false
    State.liveLoaderUI = true
    State.debug = false
end

function DGS_AutoStartController()
    if not State or not State.autoStartEnabled then return end

    DGS_AutoApplyRecommendedSettings()

    if State.autoStartQueued and not State.autoPreloadQueued then
        State.autoPreloadQueued = true
        DGS_AutoCallPreloadFrames()
        CLog("[AutoStart] Frame preload auto-queued.")
    end

    local loaded = tonumber(State.loadedCount or State.loadedFrames or State.framesLoaded or 0) or 0
    local total = tonumber(State.totalFrames or State.frameCount or 180) or 180

    if loaded >= total and not State.autoAnimationStarted then
        State.autoAnimationStarted = true
        State.autoReadyMs = NowMs()
        DGS_AutoCallStartAnimation()
        CLog("[AutoStart] Frames ready; visual animation waiting for dynamic loader.")
    end

    if State.autoAnimationStarted and not State.autoLoaderStarted then
        local delay = tonumber(State.autoLoadDelayMs or 350) or 350
        if (NowMs() - (State.autoReadyMs or NowMs())) >= delay then
            State.autoLoaderStarted = true
            if DGL_ResetExample then
                DGL_ResetExample()
                CLog("[AutoStart] Dynamic loader auto-started.")
            else
                CLog("[AutoStart] Dynamic loader could not start: DGL_ResetExample missing.")
            end
        end
    end
end

DG = DG or {}
driftgod.DriftGodStart = driftgod.DriftGodStart or {}

function driftgod.DriftGodStart.StartPreload()
    State.autoStartEnabled = false
    State.autoStartQueued = false
    State.autoPreloadQueued = false
    State.autoAnimationStarted = false
    State.autoLoaderStarted = false
    State.dynamicOnlyWindow = true
    State.loaderFullyComplete = false
    State.loaderActive = false
    State.dynamicExample = false
    State.active = false
    State.started = false
    State.persistent = false
    State.holdFrameOne = false
    State.liveLoaderUI = true
    State.showPanel = false
    State.debug = false

    local dlOk, dlErr = driftgod.Try(function()
        State.framesDownloadComplete = CountMissingFrames() <= 0
        if not State.framesDownloadComplete then
            QueueMissingFrameDownloads(false)
        end
    end)
    if not dlOk then
        State.framesDownloadFailed = true
        State.framesDownloadComplete = true
        State.framesDownloadLast = tostring(dlErr)
        CLog('[FrameDownload] disabled after startup error: ' .. tostring(dlErr))
    end

    if State.loadedCount < FRAME_COUNT then
        State.preloading = true
        State.preloadIndex = 1
    end
    CLog("[Port] preload queued")
end

function driftgod.DriftGodStart.IsPreloadComplete()
    local loaded = tonumber(State.loadedCount or 0) or 0
    if loaded >= FRAME_COUNT then return true end

    if State.preloading == false and (tonumber(State.preloadIndex or 1) or 1) > FRAME_COUNT then
        return true
    end

    return false
end

function driftgod.DriftGodStart.GetPreloadProgress()
    local loaded = tonumber(State.loadedCount or 0) or 0
    local textureProgress = math.max(0.0, math.min(1.0, loaded / math.max(1, FRAME_COUNT)))
    if State.framesDownloading and tonumber(State.framesDownloadMissing or 0) and (tonumber(State.framesDownloadMissing or 0) > 0) then
        local dl = tonumber(State.framesDownloadDone or 0) or 0
        local miss = tonumber(State.framesDownloadMissing or 1) or 1
        local downloadProgress = math.max(0.0, math.min(1.0, dl / math.max(1, miss)))
        return math.max(textureProgress, downloadProgress * 0.50)
    end
    return textureProgress
end

function driftgod.DriftGodStart.StartDynamic(moduleName)
    State.autoStartEnabled = false
    State.dynamicExample = false
    State.loaderActive = true
    State.loaderDone = false
    State.loaderStartMs = NowMs()
    State.loaderRealProgress = 0.0
    State.loaderDisplayProgress = 0.0
    State.loaderCurrentModule = tostring(moduleName or "Starting DriftGod...")
    State.loaderLastStage = 0
    State.loaderFadeOut = false
    State.loaderFadeStartMs = 0
    State.loaderFullyComplete = false
    State.active = true
    State.started = true
    State.persistent = true
    State.holdFrameOne = false
    State.startMs = NowMs()
    CLog("[Port] dynamic loader started")
end

function driftgod.DriftGodStart.SetModule(name)
    DriftGodLoader_SetModule(name)
end

function driftgod.DriftGodStart.SetProgress(value)
    DriftGodLoader_SetProgress(value)
end

function driftgod.DriftGodStart.Finish()
    DriftGodLoader_Finish()
end

function driftgod.DriftGodStart.IsFinished()
    return State.loaderFullyComplete == true
end

function driftgod.DriftGodStart.Stop()
    State.active = false
    State.started = false
    State.persistent = false
    State.holdFrameOne = false
    State.loaderActive = false
    State.dynamicExample = false
    State.loaderFullyComplete = true
end

function driftgod.DriftGodStart.Status()
    return {
        loaded = State.loadedCount,
        total = FRAME_COUNT,
        preloadComplete = driftgod.DriftGodStart.IsPreloadComplete(),
        loaderActive = State.loaderActive,
        loaderDone = State.loaderDone,
        loaderFinished = State.loaderFullyComplete,
        module = State.loaderCurrentModule,
        realProgress = State.loaderRealProgress,
        displayProgress = State.loaderDisplayProgress,
    }
end

function DriftGodLoader_SetModule(name) State.loaderCurrentModule = tostring(name or "Loading...") end
function DriftGodLoader_SetProgress(value) State.loaderRealProgress = DGL_Clamp01(value or 0.0) end
function DriftGodLoader_Finish()
    State.loaderRealProgress = 1.0
    State.loaderCurrentModule = "DriftGod Ready"
    State.loaderDone = true
end

if EventMgr and eLuaEvent and eLuaEvent.ON_PRESENT then
    EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
        DrawFrameOnPresent()
    end)
    CLog("[Port] ON_PRESENT loader renderer registered")
else
    CLog("[Port] ON_PRESENT unavailable; DriftGodStart loader renderer could not register")
end

if EventMgr and eLuaEvent and eLuaEvent.ON_UNLOAD then
    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        if DG and driftgod.DriftGodStart and driftgod.DriftGodStart.Stop then driftgod.DriftGodStart.Stop() end
    end)
end

return driftgod.DriftGodStart
end

__DG_BUNDLE_LOADERS["core.natives"] = function()
DG = DG or {}

-- ═══════════════════════════════════════════════════════════════════════════════════
-- native bridge
-- note: builds safe native wrappers before gameplay systems call gta functions.
-- ═══════════════════════════════════════════════════════════════════════════════════

function driftgod.BuildNatives()
    if not Natives or not V3 then
        driftgod.Log("Natives or V3 missing.")
        return false
    end

    if not Natives.InvokeBool or not Natives.InvokeFloat or not Natives.InvokeInt or not Natives.InvokeVoid or not Natives.InvokeV3 then
        driftgod.Log("Required native invoke functions missing.")
        return false
    end

    driftgod.Inv = {
        Bool = Natives.InvokeBool,
        Float = Natives.InvokeFloat,
        Int = Natives.InvokeInt,
        String = Natives.InvokeString,
        Void = Natives.InvokeVoid,
        V3Raw = Natives.InvokeV3
    }

    function driftgod.Inv.V3(hash, ...)
        return V3.New(driftgod.Inv.V3Raw(hash, ...))
    end
    function driftgod.NativeWarnOnce(label, err)
        driftgod.S = driftgod.S or {}
        driftgod.S._nativeWarned = driftgod.S._nativeWarned or {}
        label = tostring(label or "native")
        if driftgod.S._nativeWarned[label] then return end
        driftgod.S._nativeWarned[label] = true
        local msg = "[NativeGuard] Disabled unsafe native path: " .. label
        if err ~= nil then msg = msg .. " | " .. tostring(err) end
        if driftgod.Log then driftgod.Log(msg)
        elseif Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] " .. msg) end
    end

    function driftgod.TryInvokeVoid(label, hash, ...)
        if not driftgod.Inv or not driftgod.Inv.Void then return false end
        local ok, err = driftgod.Try(driftgod.Inv.Void, hash, ...)
        if not ok then
            driftgod.NativeWarnOnce(label, err)
            return false
        end
        return true
    end

    function driftgod.SafeSetVehicleReduceGrip(vehicle, toggle)
        return driftgod.TryInvokeVoid("SET_VEHICLE_REDUCE_GRIP", 0x222FF6A823D122E2, vehicle, toggle == true)
    end

    function driftgod.SafeSetVehicleReduceGripLevel(vehicle, value)

        driftgod.NativeWarnOnce("SET_VEHICLE_REDUCE_GRIP_LEVEL skipped")
        return false
    end

    function driftgod.SafeSetVehicleFrictionOverride(vehicle, friction)

        driftgod.NativeWarnOnce("SET_VEHICLE_FRICTION_OVERRIDE skipped")
        return false
    end

    PLAYER = PLAYER or {}
    PED = PED or {}
    ENTITY = ENTITY or {}
    VEHICLE = VEHICLE or {}
    PAD = PAD or {}
    MISC = MISC or {}
    HUD = HUD or {}
    GRAPHICS = GRAPHICS or {}

    PLAYER.PLAYER_ID = PLAYER.PLAYER_ID or function() return driftgod.Inv.Int(0x4F8644AF03D0E0D6) end
    PLAYER.PLAYER_PED_ID = PLAYER.PLAYER_PED_ID or function() return driftgod.Inv.Int(0xD80958FC74E988A6) end
    PLAYER.GET_PLAYER_PED_SCRIPT_INDEX = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX or function(playerId) return driftgod.Inv.Int(0x50FAC3A3E030A6E1, playerId) end

    PED.IS_PED_IN_ANY_VEHICLE = PED.IS_PED_IN_ANY_VEHICLE or function(ped, atGetIn) return driftgod.Inv.Bool(0x997ABD671D25CA0B, ped, atGetIn) end
    PED.GET_VEHICLE_PED_IS_IN = PED.GET_VEHICLE_PED_IS_IN or function(ped, lastVehicle) return driftgod.Inv.Int(0x9A9112A0FE9A4713, ped, lastVehicle) end

    ENTITY.DOES_ENTITY_EXIST = ENTITY.DOES_ENTITY_EXIST or function(entity) return driftgod.Inv.Bool(0x7239B21A38F536BA, entity) end
    ENTITY.GET_ENTITY_MODEL = ENTITY.GET_ENTITY_MODEL or function(entity) return driftgod.Inv.Int(0x9F47B058362C84B5, entity) end
    ENTITY.GET_ENTITY_SPEED = ENTITY.GET_ENTITY_SPEED or function(entity) return driftgod.Inv.Float(0xD5037BA82E12416F, entity) end
    ENTITY.GET_ENTITY_VELOCITY = ENTITY.GET_ENTITY_VELOCITY or function(entity) return driftgod.Inv.V3(0x4805D2B1D8CF94A9, entity) end
    ENTITY.SET_ENTITY_VELOCITY = ENTITY.SET_ENTITY_VELOCITY or function(entity, x, y, z) return driftgod.Inv.Void(0x1C99BB7B6E96D16F, entity, x + 0.0, y + 0.0, z + 0.0) end
    ENTITY.GET_ENTITY_ROTATION = ENTITY.GET_ENTITY_ROTATION or function(entity, order) return driftgod.Inv.V3(0xAFBD61CC738D9EB9, entity, order) end
    ENTITY.SET_ENTITY_ROTATION = ENTITY.SET_ENTITY_ROTATION or function(entity, pitch, roll, yaw, order, p5) return driftgod.Inv.Void(0x8524A8B0171D5E07, entity, pitch + 0.0, roll + 0.0, yaw + 0.0, order, p5) end
    ENTITY.GET_ENTITY_HEADING = ENTITY.GET_ENTITY_HEADING or function(entity) return driftgod.Inv.Float(0xE83D4F9BA2A38914, entity) end
