driftgod.S.nativeOK = driftgod.BuildNatives()

function driftgod.HasNatives()
    return driftgod.S and driftgod.S.nativeOK and PLAYER and PED and ENTITY and VEHICLE and PAD and HUD and GRAPHICS
end

return DG
end

__DG_BUNDLE_LOADERS["core.save"] = function()
DG = DG or {}

driftgod.S = driftgod.S or {
    loaderDebugLogs = false,
    asciiPurpleAnsiTest = true,
    stuntHudMoveEnabled = false,
    stuntHudX = 0.50,
    stuntHudY = 0.50,
    driftGodPresetUnlockBestScore = 3000,}
if driftgod.S.introLogoDebugLogs == nil then driftgod.S.introLogoDebugLogs = false end

function driftgod.IntroLogoLog(msg)
    if driftgod.S and driftgod.S.introLogoDebugLogs == true and driftgod.Log then
        driftgod.IntroLogoLog(tostring(msg))
    end
end

function driftgod.IntroLogoLogOnce(key, msg)
    driftgod._IntroLogoLoggedOnce = driftgod._IntroLogoLoggedOnce or {}
    if driftgod.S and driftgod.S.introLogoDebugLogs == true and driftgod._IntroLogoLoggedOnce[key] ~= true then
        driftgod._IntroLogoLoggedOnce[key] = true
        if driftgod.Log then driftgod.IntroLogoLog(tostring(msg)) end
    end
end

function driftgod.Serialize(value, indent)
    indent = indent or ""
    if type(value) == "number" then return tostring(value) end
    if type(value) == "boolean" then return tostring(value) end
    if type(value) == "string" then return string.format("%q", value) end
    if type(value) == "table" then
        local nextIndent = indent .. "    "
        local parts = {"{\n"}
        for k, v in pairs(value) do
            local key
            if type(k) == "string" and string.match(k, "^[%a_][%w_]*$") then
                key = k
            else
                key = "[" .. driftgod.Serialize(k, nextIndent) .. "]"
            end
            table.insert(parts, nextIndent .. key .. " = " .. driftgod.Serialize(v, nextIndent) .. ",\n")
        end
        table.insert(parts, indent .. "}")
        return table.concat(parts)
    end
    return "nil"
end

function driftgod.SaveTable(path, value)
    driftgod.EnsureStorageDir()
    if driftgod.EnsureParentDir then driftgod.EnsureParentDir(path) end

    local body = "return " .. driftgod.Serialize(value, "") .. "\n"

    if FileMgr and FileMgr.WriteFileContent then
        local ok, res = driftgod.Try(function() return FileMgr.WriteFileContent(path, body, false) end)
        if ok and res == true then return true end
    end

    local file = io.open(path, "w")
    if not file then
        driftgod.Toast("Could not save: " .. tostring(path), 5000)
        return false
    end
    file:write(body)
    file:close()
    return true
end

function driftgod.LoadTable(path)
    local file = io.open(path, "r")
    if not file then return nil end
    file:close()
    local ok, result = driftgod.Try(function() return dofile(path) end)
    if ok and type(result) == "table" then return result end
    return nil
end

function driftgod.ExportSettings()
    local t = {}
    for k, _ in pairs(driftgod.DefaultSettings or {}) do
        t[k] = driftgod.S[k]
    end

    t.inputHudEnabled = false

    t.mphHudEnabled = driftgod.S.mphHudEnabled
    t.noScoreZonesEnabled = true
    t.bannedAreasEnabled = true
    t.blockDriveOnWaterScore = driftgod.S.blockDriveOnWaterScore ~= false
    t.noScoreZoneRadius = driftgod.S.noScoreZoneRadius or driftgod.S.bannedAreaRadius or 55.0
    t.bannedAreaRadius = driftgod.S.bannedAreaRadius or driftgod.S.noScoreZoneRadius or 55.0
    t.noScoreZones = driftgod.S.noScoreZones or {}

    return t
end

function driftgod.ApplyStartupPreset(showToast)
    if driftgod.StartupPresetEnabled ~= true then return end

    local p = driftgod.StartupPreset
    if type(p) ~= "table" then return end

    driftgod.S = driftgod.S or {}
    driftgod.S.activeStartupPreset = p.name or "Default Drifting"

    driftgod.S.driftAssistEnabled = p.driftAssistEnabled == true
    driftgod.S.driftTuningEnabled = p.driftTuningEnabled ~= false
    driftgod.S.driftTuningDriftEnabled = p.driftTuningDriftEnabled == true
    driftgod.S.driftGripLevel = p.driftGripLevel or 1

    driftgod.S.stabilityAssistEnabled = p.stabilityAssistEnabled == true
    driftgod.S.driftStabilityLevel = p.driftStabilityLevel or 1

    driftgod.S.autoCounterSteerEnabled = p.autoCounterSteerEnabled ~= false
    driftgod.S.autoCounterSteerLevel = p.autoCounterSteerLevel or 1

    driftgod.S.accelAssistEnabled = p.accelAssistEnabled == true
    driftgod.S.accelStrength = p.accelStrength or 1

    driftgod.S.momentumAssistEnabled = p.momentumAssistEnabled == true
    driftgod.S.momentumStrength = p.momentumStrength or 1

    driftgod.S.experimentalAccelEnabled = p.experimentalAccelEnabled == true
    driftgod.S.experimentalAccelStrength = p.experimentalAccelStrength or 1

    driftgod.S.experimentalTractionEnabled = p.experimentalTractionEnabled == true
    driftgod.S.experimentalTractionLevel = p.experimentalTractionLevel or 0

    driftgod.S.experimentalGripEnabled = p.experimentalGripEnabled == true
    driftgod.S.experimentalGripLevel = p.experimentalGripLevel or 0

    if showToast == true and driftgod.Toast then
        driftgod.Toast("Startup preset loaded: " .. tostring(driftgod.S.activeStartupPreset), 3000)
    end
end

function driftgod.ApplyPublisherDefaultsOnce()
    driftgod.S = driftgod.S or {}

    if driftgod.S.publisherDefaultsApplied_v61349 == true then return end

    driftgod.S.progressUnlocksEnabled = true
    if driftgod.S.autoPlateEnabled == nil then driftgod.S.autoPlateEnabled = false end
    if driftgod.S.driftGodPlateEnabled == nil then driftgod.S.driftGodPlateEnabled = false end
    if driftgod.S.plateEnabled == nil then driftgod.S.plateEnabled = false end
    if driftgod.S.customPlateEnabled == nil then driftgod.S.customPlateEnabled = false end
    driftgod.S.accelAssistEnabled = true
    driftgod.S.momentumAssistEnabled = true

    driftgod.S.publisherDefaultsApplied_v61349 = true
end

