local function dg_progress_log(msg, force)
    msg = tostring(msg or "")
    if msg:gsub("%s+", "") == "" then return end

    local lower = msg:lower()
    local important = force == true
        or lower:find("error", 1, true) ~= nil
        or lower:find("failed", 1, true) ~= nil
        or lower:find("warning", 1, true) ~= nil
    if not important and not (driftgod.S and driftgod.S.progressDebugEnabled == true) then return end
    if driftgod.Log then driftgod.Log("[ProgressDisk] " .. msg)
    elseif Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] [ProgressDisk] " .. msg)
    elseif log then log("[DriftGod] [ProgressDisk] " .. msg) end
end

local function dg_unique_paths(paths)
    local out, seen = {}, {}
    for _, p in ipairs(paths or {}) do
        p = tostring(p or "")
        if p ~= "" and not seen[p:lower()] then
            seen[p:lower()] = true
            table.insert(out, p)
        end
    end
    return out
end

function driftgod.GetProgressVaultWritePaths()
    local paths = {}

    if driftgod.ProgressFile then table.insert(paths, driftgod.ProgressFile) end
    if driftgod.Paths then
        table.insert(paths, driftgod.Paths.progressBackup)
        table.insert(paths, driftgod.Paths.progressAutosave)
        table.insert(paths, driftgod.Paths.progressColdboot)
        table.insert(paths, driftgod.Paths.userProgress)
        table.insert(paths, driftgod.Paths.userProgressBackup)
    elseif driftgod.StorageDir then
        table.insert(paths, driftgod.StorageDir .. "\\progress_backup.lua")
        table.insert(paths, driftgod.StorageDir .. "\\progress_autosave.lua")
        table.insert(paths, driftgod.StorageDir .. "\\progress_coldboot.lua")
        table.insert(paths, driftgod.StorageDir .. "\\user_progress.lua")
        table.insert(paths, driftgod.StorageDir .. "\\user_progress_backup.lua")
    end

    return dg_unique_paths(paths)
end

function driftgod.GetProgressVaultPaths()

    local paths = driftgod.GetProgressVaultWritePaths and driftgod.GetProgressVaultWritePaths() or {}

    if driftgod.Paths then
        table.insert(paths, driftgod.Paths.legacyUserProgress)
        table.insert(paths, driftgod.Paths.legacyUserProgressBackup)
    else
        local luaRoot = nil
        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then
                luaRoot = tostring(FileMgr.GetMenuRootPath() or "") .. "\\Lua"
            end
        end)
        if luaRoot and luaRoot ~= "\\Lua" and luaRoot ~= "" then
            table.insert(paths, luaRoot .. "\\DriftGod_UserProgress.lua")
            table.insert(paths, luaRoot .. "\\DriftGod_UserProgress.bak.lua")
        end
    end

    return dg_unique_paths(paths)
end

local function dg_table_count(t)
    local n = 0
    if type(t) == "table" then for _ in pairs(t) do n = n + 1 end end
    return n
end

local function dg_highest_score_in_table(t)
    local best = 0
    if type(t) ~= "table" then return 0 end
    local candidates = {
        t.bestScore, t.highScore, t.highestScore, t.bestDriftScore, t.topScore,
        t.progressScore, t.lifetimeScore, t.totalScore, t.totalDriftScore,
        t.lastRunScore, t.previousScore, t.challengeBestScore
    }
    for _, v in ipairs(candidates) do
        local n = tonumber(v)
        if n and n > best then best = n end
    end
    if type(t.highScores) == "table" then
        for _, e in pairs(t.highScores) do
            local n = tonumber(type(e) == "table" and e.score or e)
            if n and n > best then best = n end
        end
    end
    if type(t.vehicleHighScores) == "table" then
        for _, e in pairs(t.vehicleHighScores) do
            local n = tonumber(type(e) == "table" and e.score or e)
            if n and n > best then best = n end
        end
    end
    return math.floor(best)
end

function driftgod.GetProgressDataScore(t)
    return dg_highest_score_in_table(t)
end

local function dg_progress_quality(t)
    if type(t) ~= "table" then return -1, -1, -1 end
    local serial = tonumber(t.progressSaveSerial or 0) or 0
    local score = dg_highest_score_in_table(t)
    local tierCount = dg_table_count(t.stuntUpgradeEarnedTiers)
    local overall = tonumber(t.overallScore or 0) or 0

    local quality = (serial * 1000000000) + (score * 1000) + (tierCount * 10) + math.min(overall, 999999)
    return quality, score, tierCount
end

function driftgod.LoadBestProgressFromVault()
    local bestData, bestPath, bestQuality, bestScore, bestTiers = nil, nil, -1, 0, 0
    for _, path in ipairs(driftgod.GetProgressVaultPaths and driftgod.GetProgressVaultPaths() or { driftgod.ProgressFile }) do
        local data = driftgod.LoadTable(path)
        if type(data) == "table" then
            local q, score, tiers = dg_progress_quality(data)
            if q > bestQuality then
                bestData, bestPath, bestQuality, bestScore, bestTiers = data, path, q, score, tiers
            end
        end
    end

    if type(bestData) == "table" then
        driftgod.S = driftgod.S or {}
        driftgod.S.progressVaultLastLoadedPath = tostring(bestPath or "")
        driftgod.S.progressVaultLastLoadedScore = tonumber(bestScore or 0) or 0
        driftgod.S.progressVaultLastLoadedTiers = tonumber(bestTiers or 0) or 0
        dg_progress_log("Vault selected | file=" .. tostring(bestPath)
            .. " | score=" .. tostring(bestScore)
            .. " | tierKeys=" .. tostring(bestTiers)
            .. " | serial=" .. tostring(bestData.progressSaveSerial or 0), false)
        return bestData, bestPath
    end

    dg_progress_log("Vault found no valid progress files", false)
    return nil, nil
end

function driftgod.SaveProgressToVault(data)
    data = data or (driftgod.ExportProgress and driftgod.ExportProgress()) or {}
    if type(data) ~= "table" then return false end

    driftgod.EnsureStorageDir()
    local okAny = false
    local failed = {}
    for _, path in ipairs(driftgod.GetProgressVaultWritePaths and driftgod.GetProgressVaultWritePaths() or { driftgod.ProgressFile }) do
        local ok = driftgod.SaveTable(path, data)
        if ok then okAny = true else table.insert(failed, tostring(path)) end
    end

    local score = dg_highest_score_in_table(data)
    local tiers = dg_table_count(data.stuntUpgradeEarnedTiers)
    dg_progress_log("Vault saved | ok=" .. tostring(okAny)
        .. " | score=" .. tostring(score)
        .. " | tierKeys=" .. tostring(tiers)
        .. " | serial=" .. tostring(data.progressSaveSerial or 0)
        .. (#failed > 0 and (" | failed=" .. table.concat(failed, ", ")) or ""), #failed > 0)

    if okAny and driftgod.ProgressFile then
        local verify = driftgod.LoadTable(driftgod.ProgressFile)
        local verifyScore = dg_highest_score_in_table(verify)
        if verifyScore < score then
            dg_progress_log("Primary verify WARNING | wroteScore=" .. tostring(score)
                .. " | readScore=" .. tostring(verifyScore), true)
        end
    end

    return okAny
end

function driftgod.GetTodayBestDateKey()
    local ok, value = driftgod.Try(function() return os.date("%Y-%m-%d") end)
    if ok and value then return tostring(value) end
    return tostring(driftgod.DateString and driftgod.DateString() or "unknown")
end

function driftgod.EnsureTodayBest()
    driftgod.S = driftgod.S or {}
    local today = driftgod.GetTodayBestDateKey and driftgod.GetTodayBestDateKey() or "unknown"
    if tostring(driftgod.S.todayBestDateKey or "") ~= tostring(today) then
        driftgod.S.todayBestDateKey = today
        driftgod.S.todayBestScore = 0
    end
    driftgod.S.todayBestScore = math.floor(tonumber(driftgod.S.todayBestScore or 0) or 0)
    return driftgod.S.todayBestScore, driftgod.S.todayBestDateKey
end

function driftgod.UpdateTodayBest(score)
    driftgod.EnsureTodayBest()
    score = math.floor(tonumber(score or 0) or 0)
    if score > (tonumber(driftgod.S.todayBestScore or 0) or 0) then
        driftgod.S.todayBestScore = score
        driftgod.S.todayBestDateKey = driftgod.GetTodayBestDateKey and driftgod.GetTodayBestDateKey() or driftgod.S.todayBestDateKey
        return true
    end
    return false
end

function driftgod.ExportProgress()
    driftgod.S = driftgod.S or {}

    local serial = tonumber(driftgod.S.progressSaveSerial or 0) or 0
    serial = serial + 1
    driftgod.S.progressSaveSerial = serial

    local best = driftgod.GetProgressDataScore and driftgod.GetProgressDataScore(driftgod.S) or tonumber(driftgod.S.bestScore or 0) or 0
    driftgod.S.bestScore = math.max(tonumber(driftgod.S.bestScore or 0) or 0, best)
    driftgod.S.highScore = math.max(tonumber(driftgod.S.highScore or 0) or 0, best)
    driftgod.S.highestScore = math.max(tonumber(driftgod.S.highestScore or 0) or 0, best)
    driftgod.S.progressScore = math.max(tonumber(driftgod.S.progressScore or 0) or 0, best)
    driftgod.S.lifetimeScore = math.max(tonumber(driftgod.S.lifetimeScore or 0) or 0, best)
    driftgod.S.totalScore = math.max(tonumber(driftgod.S.totalScore or 0) or 0, best)
    if driftgod.EnsureTodayBest then driftgod.EnsureTodayBest() end

    if driftgod.NormalizeStuntTierPersistence then driftgod.NormalizeStuntTierPersistence("core ExportProgress A40") end

    return {
        progressSaveVersion = "A40",
        progressSaveSerial = serial,
        progressSavedAt = driftgod.DateString and driftgod.DateString() or tostring(os.date()),

        bestScore = driftgod.S.bestScore,
        highScore = driftgod.S.highScore,
        highestScore = driftgod.S.highestScore,
        previousScore = driftgod.S.previousScore,
        lastRunScore = driftgod.S.lastRunScore,
        bestCombo = driftgod.S.bestCombo,
        totalStuntsLanded = driftgod.S.totalStuntsLanded,
        highScores = driftgod.S.highScores,
        vehicleHighScores = driftgod.S.vehicleHighScores,
        unlockedRewards = driftgod.S.unlockedRewards,
        notifiedUnlocks = driftgod.S.notifiedUnlocks,
        beatenRivals = driftgod.S.beatenRivals,
        challengeBestScore = driftgod.S.challengeBestScore,
        todayBestScore = driftgod.S.todayBestScore,
        todayBestDateKey = driftgod.S.todayBestDateKey,

        progressScore = driftgod.S.progressScore,
        lifetimeScore = driftgod.S.lifetimeScore,
        totalScore = driftgod.S.totalScore,
        totalDriftScore = driftgod.S.totalDriftScore,
        overallScore = driftgod.S.overallScore,
        overallScoreBankedRuns = driftgod.S.overallScoreBankedRuns,
        overallScoreLastBankedRun = driftgod.S.overallScoreLastBankedRun,
        overallScoreLastBankedAt = driftgod.S.overallScoreLastBankedAt,

        stuntTierPersistenceVersion = "A40",
        stuntUpgradeEarnedTiers = driftgod.S.stuntUpgradeEarnedTiers or {},
        stuntUpgradeAnnouncedTiers = driftgod.S.stuntUpgradeAnnouncedTiers or {},
        stuntTierFreshUseCounts = driftgod.S.stuntTierFreshUseCounts or {},
        stuntUseRunCounts = driftgod.S.stuntUseRunCounts or {},
        stuntUnlockLastHighest = driftgod.S.stuntUnlockLastHighest or "",
        stuntProgressionResetActive = driftgod.S.stuntProgressionResetActive,
        stuntProgressionResetBaseline = driftgod.S.stuntProgressionResetBaseline,

        dailyChallengeDateKey = driftgod.S.dailyChallengeDateKey,
        dailyChallengeActiveIds = driftgod.S.dailyChallengeActiveIds,
        dailyChallengeCompleted = driftgod.S.dailyChallengeCompleted,
        dailyChallengeForceNonce = driftgod.S.dailyChallengeForceNonce,
        sessionChallengePoints = driftgod.S.sessionChallengePoints,
        sessionChallengeTotalPool = driftgod.S.sessionChallengeTotalPool,
        sessionChallengesCompleted = driftgod.S.sessionChallengesCompleted,
        sessionChallengeLastCompleted = driftgod.S.sessionChallengeLastCompleted,
        progressMilestonePoints = driftgod.S.progressMilestonePoints,
        progressMilestoneTitle = driftgod.S.progressMilestoneTitle,
        progressMilestoneLastCompleted = driftgod.S.progressMilestoneLastCompleted,
        progressMilestonesCompleted = driftgod.S.progressMilestonesCompleted,
        vehicleMastery = driftgod.S.vehicleMastery,
        vehicleMasteryRewards = driftgod.S.vehicleMasteryRewards,
        vehicleMasteryLastVehicleModel = driftgod.S.vehicleMasteryLastVehicleModel,
        vehicleMasteryLastVehicleName = driftgod.S.vehicleMasteryLastVehicleName,
    }
end

function driftgod.ApplyProgress(t)
    if type(t) ~= "table" then return end
    for k, v in pairs(t) do
        driftgod.S[k] = v
    end
    if driftgod.EnsureTodayBest then driftgod.EnsureTodayBest() end
    if driftgod.ApplyLoadedStuntTierProgress then
        driftgod.ApplyLoadedStuntTierProgress(t, "core save ApplyProgress")
    elseif driftgod.NormalizeStuntTierPersistence then
        driftgod.NormalizeStuntTierPersistence("core save ApplyProgress")
    end
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- settings save
-- note: writes current settings quietly without startup noise.
-- ═══════════════════════════════════════════════════════════════════════════════════

function driftgod.SaveSettings(showToast)
    if driftgod.SaveTable(driftgod.SettingsFile, driftgod.ExportSettings()) and showToast ~= false then
        driftgod.Toast("Settings saved.", 2500)
    end
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- settings load
-- note: loads saved settings carefully so missing fields fall back to defaults.
-- ═══════════════════════════════════════════════════════════════════════════════════

function driftgod.LoadSettings(showToast)
    local data = driftgod.LoadTable(driftgod.SettingsFile)
    if not data and driftgod.LegacySettingsFile then
        data = driftgod.LoadTable(driftgod.LegacySettingsFile)
        if data and driftgod.SaveTable then

            driftgod.Try(function() driftgod.SaveTable(driftgod.SettingsFile, data) end)
        end
    end
    if data then
        driftgod.ApplySettings(data)

        driftgod.S = driftgod.S or {}
        driftgod.S.speedScoreScalingEnabled = true
        if showToast ~= false then driftgod.Toast("Settings loaded. Default Drifting startup preset applied.", 3000) end
        return true
    end
    if showToast ~= false then driftgod.Toast("No settings file found yet.", 2500) end
    return false
end

function driftgod.SaveProgress(showToast)
    local data = driftgod.ExportProgress()
    local ok = false
    if driftgod.SaveProgressToVault then
        ok = driftgod.SaveProgressToVault(data) == true
    else
        ok = driftgod.SaveTable(driftgod.ProgressFile, data) == true
    end
    if ok and showToast ~= false then
        driftgod.Toast("Progress saved.", 2500)
    elseif not ok and showToast ~= false then
        driftgod.Toast("Progress save failed. Check logs.", 4000)
    end
    return ok
end

function driftgod.LoadProgress(showToast)
    local data, path = nil, nil
    if driftgod.LoadBestProgressFromVault then
        data, path = driftgod.LoadBestProgressFromVault()
    else
        data = driftgod.LoadTable(driftgod.ProgressFile)
        path = driftgod.ProgressFile
    end

    if data then
        driftgod.ApplyProgress(data)

        driftgod.Try(function()
            if driftgod.SaveProgressToVault then driftgod.SaveProgressToVault(data) end
        end)
        if showToast ~= false then driftgod.Toast("Progress loaded.", 2500) end
        return true
    end
    if showToast ~= false then driftgod.Toast("No progress file found yet.", 2500) end
    return false
end

function driftgod.RestoreDefaultSettings()
    for k, v in pairs(driftgod.DefaultSettings or {}) do
        driftgod.S[k] = v
    end

    driftgod.S.inputHudEnabled = false
    driftgod.S.inputHudX = 0.190
    driftgod.S.inputHudY = 0.805
    driftgod.S.inputHudScale = 0.50
    driftgod.S.inputHudBackground = false

    driftgod.S.mphHudEnabled = true
    driftgod.S.mphHudX = 0.175
    driftgod.S.mphHudY = 0.977
    driftgod.S.mphHudScale = 0.65
    driftgod.S.mphHudBackground = false

    driftgod.SaveSettings(false)
    driftgod.S.progressUnlocksEnabled = true
    driftgod.S.autoPlateEnabled = false
    driftgod.S.driftGodPlateEnabled = false
    driftgod.S.accelAssistEnabled = true
    driftgod.S.momentumAssistEnabled = true

    driftgod.Toast("Default settings restored. Input Visualizer OFF. Plate OFF. Default Drifting will apply again next Lua load. Progress was not reset.", 4000)
end

function driftgod.AutoSaveTick()
    local now = driftgod.Now()
    if driftgod.S.lastAutoSaveMs == 0 then
        driftgod.S.lastAutoSaveMs = now
        return
    end

    if now - driftgod.S.lastAutoSaveMs >= driftgod.S.autoSaveIntervalMs then
        driftgod.S.lastAutoSaveMs = now
        driftgod.SaveProgress(false)
        driftgod.Log("Auto-saved progress.")
    end
end

