__DG_BUNDLE_LOADERS["core.startup_banner"] = function()
DG = DG or {}
driftgod.S = driftgod.S or {}

driftgod.S.asciiPurpleAnsiTest = driftgod.S.asciiPurpleAnsiTest ~= false

local ASCII = [==[
██████╗ ██████╗ ██╗███████╗████████╗ ██████╗  ██████╗ ██████╗
██╔══██╗██╔══██╗██║██╔════╝╚══██╔══╝██╔════╝ ██╔═══██╗██╔══██╗
██║  ██║██████╔╝██║█████╗     ██║   ██║  ███╗██║   ██║██║  ██║
██║  ██║██╔══██╗██║██╔══╝     ██║   ██║   ██║██║   ██║██║  ██║
██████╔╝██║  ██║██║██║        ██║   ╚██████╔╝╚██████╔╝██████╔╝
╚═════╝ ╚═╝  ╚═╝╚═╝╚═╝        ╚═╝    ╚═════╝  ╚═════╝ ╚═════╝

]==]

local function rawLog(text)
    text = tostring(text or "")

    local ok = false

    driftgod.Try(function()
        if Logger and Logger.LogRaw then
            Logger.LogRaw(text)
            ok = true
        end
    end)

    if ok then return end

    driftgod.Try(function()
        if Logger and Logger.Raw then
            Logger.Raw(text)
            ok = true
        end
    end)

    if ok then return end

    driftgod.Try(function()
        if Logger and Logger.LogInfoRaw then
            Logger.LogInfoRaw(text)
            ok = true
        end
    end)

    if ok then return end

    driftgod.Try(function()
        print(text)
        ok = true
    end)

    if ok then return end

    if DG and driftgod.Log then
        driftgod.Log(text)
    end
end

function driftgod.PrintStartupBanner()
    if driftgod._startupBannerPrinted == true then
        return
    end
    driftgod._startupBannerPrinted = true

    local line = "============================================================"

    local purpleAnsi = "\27[38;5;93m"
    local whiteAnsi = "\27[97m"
    local resetAnsi = "\27[0m"

    local asciiPart =
        "\n\n" ..
        line .. "\n\n" ..
        ASCII .. "\n"

    local metaPart =
        "DriftGod - Drift Like a God\n" ..
        "Developed By: " .. tostring(driftgod.Developer or "Animus") .. "\n" ..
        "Discord: " .. tostring(driftgod.Discord or "animusx1337") .. "\n" ..
        "Version: " .. tostring(driftgod.Version or "v1.0.1") .. "\n" ..
        "Build: " .. tostring(driftgod.BuildNumber or "2026.06.26.309") .. "\n" ..
        "Last Updated: " .. tostring(driftgod.LastUpdateDate or driftgod.LastUpdated or "2026-06-26") .. "\n"

    local dividerPart = "\n" .. line .. "\n\n"
    local happyPart = "Happy Drifting "
    local tsuPart = "ツ\n"

    local block
    if driftgod.S and driftgod.S.asciiPurpleAnsiTest == true then
        block = purpleAnsi .. asciiPart .. whiteAnsi .. metaPart .. purpleAnsi .. dividerPart .. whiteAnsi .. happyPart .. purpleAnsi .. tsuPart .. resetAnsi
    else
        block = asciiPart .. metaPart .. dividerPart .. happyPart .. tsuPart
    end

    rawLog(block)
end

driftgod.StartupBanner = driftgod.PrintStartupBanner

return DG
end

driftgod.Try(function()
    if DGS_QueueStartupBannerAfterCheraxLoaded then
        DGS_QueueStartupBannerAfterCheraxLoaded(1500)
    else

        require("core.startup_banner")
        if DG and driftgod.PrintStartupBanner then driftgod.PrintStartupBanner() end
    end
end)

