__DG_BUNDLE_LOADERS["core.utils"] = function()
DG = DG or {}

function driftgod.CreateDirRecursive(path)

    path = tostring(path or ""):gsub("/", "\\")
    if path == "" then return false end
    if path:sub(-1) == "\\" then path = path:sub(1, -2) end

    local function tryCreate(dir)
        dir = tostring(dir or "")
        if dir == "" then return false end
        local okAny = false
        if FileMgr and FileMgr.CreateDir then
            local ok, res = driftgod.Try(function() return FileMgr.CreateDir(dir) end)
            okAny = okAny or (ok and res ~= false)
        end

        driftgod.Try(function() os.execute('mkdir "' .. dir .. '" 2>nul') end)
        return okAny
    end

    tryCreate(path)

    local drive = path:match("^%a:\\")
    local current = ""
    local rest = path
    if drive then
        current = drive:sub(1, -2)
        rest = path:sub(#drive + 1)
    end

    for part in rest:gmatch("[^\\]+") do
        if part ~= "" then
            if current == "" then
                current = part
            else
                current = current .. "\\" .. part
            end
            tryCreate(current)
        end
    end

    tryCreate(path)
    return true
end

function driftgod.EnsureStorageDir()

    local dirs = {
        driftgod.RootDir,
        driftgod.StorageDir,
        driftgod.ConfigDir,
        driftgod.RecordingsDir,
        driftgod.Paths and driftgod.Paths.assets,
        driftgod.Paths and driftgod.Paths.loading,
        driftgod.Paths and driftgod.Paths.framesRoot,
        driftgod.Paths and driftgod.Paths.ghosts,
        driftgod.Paths and driftgod.Paths.ghostReplays,
        driftgod.Paths and driftgod.Paths.ghostTracks,
        driftgod.Paths and driftgod.Paths.vehicles,
        driftgod.Paths and driftgod.Paths.logs,
    }
    for _, dir in ipairs(dirs) do
        if dir and tostring(dir) ~= "" then
            driftgod.CreateDirRecursive(dir)
        end
    end

    if driftgod.EnsureOfficialVehicleAssets then
        driftgod.Try(function() driftgod.EnsureOfficialVehicleAssets(false) end)
    end
    if driftgod.QueueOfficialAssetDownloads then
        driftgod.QueueOfficialAssetDownloads(false)
    end
end

function driftgod.EnsureParentDir(path)
    path = tostring(path or ""):gsub("/", "\\")
    local dir = path:match("^(.*)\\[^\\]+$")
    if dir and dir ~= "" then
        driftgod.CreateDirRecursive(dir)
    end
end

driftgod.OfficialAssetDownloadState = driftgod.OfficialAssetDownloadState or {
    queued = false,
    running = false,
    done = 0,
    failed = 0,
    last = "",
}

local function DG_FileExists_OfficialAsset(path)
    path = tostring(path or "")
    if path == "" then return false end
    if FileMgr and FileMgr.DoesFileExist then
        local ok, exists = driftgod.Try(function() return FileMgr.DoesFileExist(path) end)
        if ok and exists == true then return true end
    end
    local f = io.open(path, "rb")
    if f then f:close(); return true end
    return false
end

local function DG_WriteFile_OfficialAsset(path, body)
    if type(body) ~= "string" or body == "" then return false end
    if driftgod.EnsureParentDir then driftgod.EnsureParentDir(path) end
    if FileMgr and FileMgr.WriteFileContent then
        local ok, res = driftgod.Try(function() return FileMgr.WriteFileContent(path, body, false) end)
        if ok and res == true then return true end
    end
    local f = io.open(path, "wb")
    if not f then return false end
    f:write(body)
    f:close()
    return true
end

local function DG_CurlSetOpt_OfficialAsset(curl, enumName, numericValue, value)
    if not curl or not curl.Setopt then return end
    local opt = numericValue
    driftgod.Try(function()
        if eCurlOption and eCurlOption[enumName] then opt = eCurlOption[enumName] end
    end)
    driftgod.Try(function() curl:Setopt(opt, value) end)
end

local function DG_DownloadOfficialAsset(url, path, timeoutTicks)
    if not Curl or not Curl.Easy then return false, "Curl unavailable" end
    local curl = Curl.Easy()
    DG_CurlSetOpt_OfficialAsset(curl, "CURLOPT_URL", 10002, url)
    DG_CurlSetOpt_OfficialAsset(curl, "CURLOPT_USERAGENT", 10018, "Mozilla/5.0 DriftGod-Cherax")
    curl:Perform()

    local ticks = 0
    timeoutTicks = timeoutTicks or 300
    while not curl:GetFinished() and ticks < timeoutTicks do
        Script.Yield(50)
        ticks = ticks + 1
    end

    if not curl:GetFinished() then return false, "timeout" end
    local code, body = curl:GetResponse()
    local success = (code == true) or (code == 0)
    driftgod.Try(function()
        if eCurlCode and code == eCurlCode.CURLE_OK then success = true end
    end)
    if not success then return false, "curl code=" .. tostring(code) end
    if type(body) ~= "string" or #body < 2 then return false, "empty body" end
    if body:find("404: Not Found", 1, true) then return false, "404" end
    if not DG_WriteFile_OfficialAsset(path, body) then return false, "write failed" end
    return true
end

local function DG_OfficialAssetManifest()
    local base = "https://raw.githubusercontent.com/ARandomAddonDev/GTAV-Cherax/main/DriftGod/assets/"
    return {
        {
            label = "Zentorno",
            path = driftgod.OfficialVehicleAssetDir and (driftgod.OfficialVehicleAssetDir() .. "\\Zentorno.json") or (driftgod.Paths and driftgod.Paths.vehicles and (driftgod.Paths.vehicles .. "\\Zentorno.json") or ""),
            urls = {
                base .. "vehicles/Zentorno.json",
            },
        },
        {
            label = "Torero XO",
            path = driftgod.OfficialVehicleAssetDir and (driftgod.OfficialVehicleAssetDir() .. "\\ToreroXO.json") or (driftgod.Paths and driftgod.Paths.vehicles and (driftgod.Paths.vehicles .. "\\ToreroXO.json") or ""),
            urls = {
                base .. "vehicles/ToreroXO.json",
            },
        },
    }
end

function driftgod.LogOfficialAssetProgress(done, total)
    driftgod.OfficialAssetDownloadState = driftgod.OfficialAssetDownloadState or {}
    local st = driftgod.OfficialAssetDownloadState
    total = math.max(tonumber(total or 1) or 1, 1)
    done = tonumber(done or 0) or 0
    if done < 0 then done = 0 end
    if done > total then done = total end
    local pct = math.floor((done / total) * 100 + 0.5)
    local last = tonumber(st.lastLoggedPct or -1) or -1
    if pct == last then return end
    st.lastLoggedPct = pct

    DGS_RawAssetProgress(done, total, pct >= 100)
end

function driftgod.QueueOfficialAssetDownloads(force)
    driftgod.OfficialAssetDownloadState = driftgod.OfficialAssetDownloadState or {}
    local st = driftgod.OfficialAssetDownloadState
    if st.running then return end
    if st.queued and force ~= true then return end
    if not Script or not Script.QueueJob then return end

    local missing = {}
    for _, item in ipairs(DG_OfficialAssetManifest()) do
        if item.path and item.path ~= "" and not DG_FileExists_OfficialAsset(item.path) then
            table.insert(missing, item)
        end
    end
    if #missing <= 0 then
        st.queued = true
        st.running = false
        st.last = "official assets present"
        return
    end

    st.queued = true
    st.running = true
    st.done = 0
    st.failed = 0
    st.total = #missing
    st.lastLoggedPct = -1
    st.last = "missing=" .. tostring(#missing)
    if driftgod.LogOfficialAssetProgress then driftgod.LogOfficialAssetProgress(0, #missing) end

    Script.QueueJob(function()
        local ok, err = driftgod.Try(function()
            if driftgod.EnsureStorageDir then

                if driftgod.CreateDirRecursive then
                    driftgod.CreateDirRecursive(driftgod.Paths and driftgod.Paths.assets or "")
                    driftgod.CreateDirRecursive(driftgod.Paths and driftgod.Paths.ghosts or "")
                    driftgod.CreateDirRecursive(driftgod.Paths and driftgod.Paths.ghostReplays or "")
                    driftgod.CreateDirRecursive(driftgod.Paths and driftgod.Paths.ghostTracks or "")
                    driftgod.CreateDirRecursive(driftgod.Paths and driftgod.Paths.vehicles or "")
                end
            end

            for _, item in ipairs(missing) do
                if not DG_FileExists_OfficialAsset(item.path) then
                    local downloaded = false
                    local lastErr = "unknown"
                    for _, url in ipairs(item.urls or {}) do
                        local dlOk, dlErr = DG_DownloadOfficialAsset(url, item.path, 300)
                        if dlOk then
                            downloaded = true
                            st.done = (st.done or 0) + 1
                            st.last = tostring(item.label) .. " downloaded"
                            if driftgod.LogOfficialAssetProgress then driftgod.LogOfficialAssetProgress(st.done, st.total or #missing) end
                            break
                        end
                        lastErr = tostring(dlErr or "download failed")
                    end
                    if not downloaded then
                        st.failed = (st.failed or 0) + 1
                        st.last = tostring(item.label) .. " failed: " .. tostring(lastErr)
                        if driftgod.Log then driftgod.Log("[OfficialAssets] " .. st.last) end
                    end
                    Script.Yield(25)
                end
            end
        end)
        if not ok then
            st.failed = (st.failed or 0) + 1
            st.last = tostring(err)
            if driftgod.Log then driftgod.Log("[OfficialAssets] error: " .. tostring(err)) end
        end
        st.running = false
        if (tonumber(st.failed or 0) or 0) <= 0 and driftgod.LogOfficialAssetProgress then
            driftgod.LogOfficialAssetProgress(st.total or #missing, st.total or #missing)
        end
    end)
end

function driftgod.Log(msg)
    msg = tostring(msg or "")
    if msg:gsub("%s+", "") == "" then return end
    if Logger and Logger.Log then
        Logger.Log(eLogColor.WHITE, "DriftGod", msg)
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] " .. msg)
    end
end

function driftgod.LogColor(color, msg)
    msg = tostring(msg or "")
    if msg:gsub("%s+", "") == "" then return end
    if Logger and Logger.Log and color then
        Logger.Log(color, "DriftGod", msg)
    else
        driftgod.Log(msg)
    end
end

function driftgod.Toast(msg, ms)
    ms = ms or 4000
    if GUI and GUI.AddToast then
        GUI.AddToast("DriftGod", tostring(msg), ms)
    end
    if driftgod.S and driftgod.S.logToasts == true then
        driftgod.Log(msg)
    end
end

function driftgod.Yield(ms)
    if Script and Script.Yield then
        Script.Yield(ms or 0)
    elseif g_util and g_util.yield then
        g_util.yield(ms or 0)
    end
end

function driftgod.Now()
    if MISC and MISC.GET_GAME_TIMER then
        local ok, result = driftgod.Try(function() return MISC.GET_GAME_TIMER() end)
        if ok and result then return result end
    end
    return math.floor(os.clock() * 1000)
end

function driftgod.DateString()
    local ok, result = driftgod.Try(function() return os.date("%Y-%m-%d %I:%M:%S %p") end)
    if ok and result then return result end
    return "Unknown date"
end

function driftgod.ClampInt(value, minValue, maxValue)
    value = math.floor(value or minValue)
    if value < minValue then value = minValue end
    if value > maxValue then value = maxValue end
    return value
end

function driftgod.ClampFloat(value, minValue, maxValue)
    value = value or minValue
    if value < minValue then value = minValue end
    if value > maxValue then value = maxValue end
    return value
end

function driftgod.Wrap360(value)
    while value < 0.0 do value = value + 360.0 end
    while value > 360.0 do value = value - 360.0 end
    return value
end

function driftgod.SafeCall(label, fn)
    local ok, err = driftgod.Try(fn)
    if not ok then driftgod.Log(tostring(label) .. " failed: " .. tostring(err)) end
    return ok
end

return DG
end

