__DG_BUNDLE_LOADERS["systems.boost"] = function()
DG = DG or {}
function driftgod.ApplyBoost()
    if not driftgod.HasNatives() then driftgod.Toast("Native bridge not ready.", 2500) return end
    local now = driftgod.Now()
    if driftgod.S.cooldownsEnabled and now - driftgod.S.lastBoostTime < driftgod.S.boostCooldownMs then
        driftgod.Toast("Boost cooldown: " .. tostring(math.ceil((driftgod.S.boostCooldownMs - (now - driftgod.S.lastBoostTime)) / 1000)) .. "s", 1500)
        return
    end
    local veh = driftgod.RequireVehicle(); if veh == 0 then return end
    driftgod.S.lastBoostTime = now
    local vel = ENTITY.GET_ENTITY_VELOCITY(veh)
    ENTITY.SET_ENTITY_VELOCITY(veh, vel.x * 1.25, vel.y * 1.25, vel.z * 1.10)
    driftgod.AddBonusPopup("BOOST", 190, 90, 255)
    driftgod.Toast("Boost applied. No score bonus.", 1500)
end
return DG
end

