local function DG_R133_PathJoin(a, b)
    a = tostring(a or ""):gsub("/", "\\")
    b = tostring(b or ""):gsub("/", "\\")
    if a == "" then return b end
    if a:sub(-1) == "\\" then return a .. b end
    return a .. "\\" .. b
end

local function DG_R133_FileExists(path)
    path = tostring(path or "")
    if path == "" then return false end
    if FileMgr and FileMgr.DoesFileExist then
        local ok, exists = driftgod.Try(function() return FileMgr.DoesFileExist(path) end)
        if ok and exists == true then return true end
    end
    local f = io.open(path, "rb")
    if f then f:close(); return true end
    return false
end

local function DG_R133_ReadFile(path)
    path = tostring(path or "")
    if path == "" then return nil end
    if FileMgr and FileMgr.ReadFileContent then
        local ok, body = driftgod.Try(function() return FileMgr.ReadFileContent(path) end)
        if ok and type(body) == "string" and body ~= "" then return body end
    end
    local f = io.open(path, "rb")
    if not f then return nil end
    local body = f:read("*a")
    f:close()
    return body
end

local function DG_R133_WriteFile(path, body)
    path = tostring(path or "")
    if path == "" or type(body) ~= "string" or body == "" then return false end
    if DG and driftgod.EnsureParentDir then driftgod.Try(function() driftgod.EnsureParentDir(path) end) end
    if FileMgr and FileMgr.WriteFileContent then
        local ok, res = driftgod.Try(function() return FileMgr.WriteFileContent(path, body, false) end)
        if ok and res == true then return true end
    end
    local f = io.open(path, "wb")
    if not f then return false end
    f:write(body)
    f:close()
    return true
end

local function DG_R133_JsonEscape(s)
    s = tostring(s or "")
    s = s:gsub('\\', '\\\\'):gsub('"', '\\"'):gsub('\r', '\\r'):gsub('\n', '\\n'):gsub('\t', '\\t')
    return '"' .. s .. '"'
end

local function DG_R133_IsArray(t)
    if type(t) ~= "table" then return false end
    local n = 0
    for k, _ in pairs(t) do
        if type(k) ~= "number" or k < 1 or k % 1 ~= 0 then return false end
        if k > n then n = k end
    end
    for i = 1, n do if t[i] == nil then return false end end
    return true
end

local function DG_R133_EncodeJson(v, depth)
    depth = (depth or 0) + 1
    if depth > 12 then return "null" end
    local tv = type(v)
    if tv == "nil" then return "null" end
    if tv == "boolean" then return v and "true" or "false" end
    if tv == "number" then return tostring(v) end
    if tv == "string" then return DG_R133_JsonEscape(v) end
    if tv ~= "table" then return "null" end
    local parts = {}
    if DG_R133_IsArray(v) then
        for i = 1, #v do parts[#parts+1] = DG_R133_EncodeJson(v[i], depth) end
        return "[" .. table.concat(parts, ",") .. "]"
    end
    local keys = {}
    for k, _ in pairs(v) do keys[#keys+1] = k end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    for _, k in ipairs(keys) do
        local key = tostring(k)
        parts[#parts+1] = DG_R133_JsonEscape(key) .. ":" .. DG_R133_EncodeJson(v[k], depth)
    end
    return "{" .. table.concat(parts, ",") .. "}"
end

local function DG_R133_VehicleAssetBody(label, cfg)
    local body = DG_R133_EncodeJson(cfg or {})
    return body
end

driftgod.OfficialVehicleAssetDir = function()
    driftgod.Paths = driftgod.Paths or {}
    if not driftgod.Paths.vehicles or driftgod.Paths.vehicles == "" then
        local root = (driftgod.Paths and driftgod.Paths.assets) or ((driftgod.RootDir or "") .. "\\assets")
        driftgod.Paths.vehicles = DG_R133_PathJoin(root, "vehicles")
    end
    return driftgod.Paths.vehicles
end

function driftgod.EnsureOfficialVehicleAssets(forceRewrite)
    local dir = driftgod.OfficialVehicleAssetDir and driftgod.OfficialVehicleAssetDir() or ""
    if dir == "" then return false end
    if DG and driftgod.CreateDirRecursive then driftgod.Try(function() driftgod.CreateDirRecursive(dir) end) end

    local manifest = {
        { name = "Zentorno", file = "Zentorno.json", cfg = ZENTORNO },
        { name = "Torero XO", file = "ToreroXO.json", cfg = TOREROXO },
    }

    local legacyDirs = {}
    local function addLegacy(path)
        path = tostring(path or ""):gsub("/", "\\")
        if path ~= "" and path ~= dir then legacyDirs[#legacyDirs+1] = path end
    end
    addLegacy(DG_R133_PathJoin(driftgod.Paths and driftgod.Paths.root or driftgod.RootDir or "", "vehicles"))
    addLegacy(DG_R133_PathJoin(driftgod.Paths and driftgod.Paths.storage or driftgod.StorageDir or "", "vehicles"))
    addLegacy(DG_R133_PathJoin(driftgod.Paths and driftgod.Paths.luaRoot or "", "DriftGodVehicles"))
    addLegacy(DG_R133_PathJoin(driftgod.Paths and driftgod.Paths.luaRoot or "", "Vehicles\\DriftGod"))
    addLegacy(DG_R133_PathJoin(driftgod.Paths and driftgod.Paths.menuRoot or "", "Vehicles\\DriftGod"))

    local installed = 0
    for _, item in ipairs(manifest) do
        local canonical = DG_R133_PathJoin(dir, item.file)
        if forceRewrite ~= true and DG_R133_FileExists(canonical) then
            installed = installed + 1
        else
            local moved = false
            for _, oldDir in ipairs(legacyDirs) do
                local oldPath = DG_R133_PathJoin(oldDir, item.file)
                if DG_R133_FileExists(oldPath) then
                    local body = DG_R133_ReadFile(oldPath)
                    if body and body ~= "" and DG_R133_WriteFile(canonical, body) then
                        moved = true
                        installed = installed + 1
                        break
                    end
                end
            end
            if not moved then
                local body = DG_R133_VehicleAssetBody(item.name, item.cfg)
                if body and body ~= "" and DG_R133_WriteFile(canonical, body) then
                    installed = installed + 1
                end
            end
        end
    end

    return installed >= #manifest
end

if Script and Script.QueueJob then
    Script.QueueJob(function()
        driftgod.Try(function() if DG and driftgod.EnsureOfficialVehicleAssets then driftgod.EnsureOfficialVehicleAssets(false) end end)
    end)
else
    driftgod.Try(function() if DG and driftgod.EnsureOfficialVehicleAssets then driftgod.EnsureOfficialVehicleAssets(false) end end)
end

local function toast(msg, ms)
    if DG and driftgod.Toast then
        driftgod.Toast(tostring(msg), ms or 1800)
    elseif GUI and GUI.AddToast then
        GUI.AddToast("DriftGod", tostring(msg), ms or 1800)
    end
end

local function ptrToHandle(ptr)
    if not ptr then return 0 end
    if type(ptr) == "number" then return ptr end

    local h = 0
    driftgod.Try(function()
        if GTA and GTA.PointerToHandle then
            h = GTA.PointerToHandle(ptr)
        end
    end)

    return tonumber(h) or 0
end

local function getVehicle()
    local veh = 0

    driftgod.Try(function()
        if DG and driftgod.GetVehicle then
            local ptr = driftgod.GetVehicle()
            veh = ptrToHandle(ptr)
        end
    end)

    if not veh or veh == 0 then
        driftgod.Try(function()
            if GTA and GTA.GetLocalVehicle then
                veh = ptrToHandle(GTA.GetLocalVehicle())
            end
        end)
    end

    if not veh or veh == 0 then
        driftgod.Try(function()
            if PLAYER and PLAYER.PLAYER_PED_ID and PED and PED.GET_VEHICLE_PED_IS_IN then
                local ped = PLAYER.PLAYER_PED_ID()
                veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
            elseif Natives then
                local ped = Natives.InvokeInt(natives.playerPedId)
                if Natives.InvokeBool(natives.isPedInAnyVehicle, ped, false) then
                    veh = Natives.InvokeInt(natives.getVehiclePedIsIn, ped, false)
                end
            end
        end)
    end

    return tonumber(veh) or 0
end

local function entityExists(ent)
    if not ent or ent == 0 then return false end
    local ok, exists = driftgod.Try(function()
        if ENTITY and ENTITY.DOES_ENTITY_EXIST then
            return ENTITY.DOES_ENTITY_EXIST(ent)
        elseif Natives then
            return Natives.InvokeBool(natives.doesEntityExist, ent)
        end
        return false
    end)
    return ok and exists == true
end

local function getSpeed(veh)
    local speed = 0.0
    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_SPEED then
            speed = ENTITY.GET_ENTITY_SPEED(veh)
        elseif Natives then
            speed = Natives.InvokeFloat(natives.getEntitySpeed, veh)
        end
    end)
    return tonumber(speed) or 0.0
end

local function setBoostActive(veh, active)
    local ok, err = driftgod.Try(function()
        if AUDIO and AUDIO.SET_VEHICLE_BOOST_ACTIVE then
            AUDIO.SET_VEHICLE_BOOST_ACTIVE(veh, active == true)
        elseif Natives then
            Natives.InvokeVoid(natives.setVehicleBoostActive, veh, active == true)
        end
    end)
    if not ok then log("SET_VEHICLE_BOOST_ACTIVE failed: " .. tostring(err)) end
    return ok
end

local function setForwardSpeed(veh, speed)
    local ok, err = driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_FORWARD_SPEED then
            VEHICLE.SET_VEHICLE_FORWARD_SPEED(veh, speed)
        elseif Natives then
            Natives.InvokeVoid(natives.setVehicleForwardSpeed, veh, speed)
        end
    end)
    if not ok then log("SET_VEHICLE_FORWARD_SPEED failed: " .. tostring(err)) end
    return ok
end

local function raceTurbo(play)
    driftgod.Try(function()
        if play then
            if GRAPHICS and GRAPHICS.ANIMPOSTFX_PLAY then
                GRAPHICS.ANIMPOSTFX_PLAY("RaceTurbo", 0, false)
            elseif Natives then
                Natives.InvokeVoid(natives.animpostfxPlay, "RaceTurbo", 0, false)
            end
        else
            if GRAPHICS and GRAPHICS.ANIMPOSTFX_STOP then
                GRAPHICS.ANIMPOSTFX_STOP("RaceTurbo")
            elseif Natives then
                Natives.InvokeVoid(natives.animpostfxStop, "RaceTurbo")
            end
        end
    end)
end

function driftgod.BoostFXPulse()
    driftgod.S = driftgod.S or {}
    local veh = getVehicle()

    if not veh or veh == 0 or not entityExists(veh) then
        toast("Boost FX needs a vehicle.", 1800)
        log("pulse failed: no vehicle")
        return
    end

    local currentSpeed = getSpeed(veh)
    local add = tonumber(driftgod.S.boostFXStrength or 10.0) or 10.0
    local targetSpeed = currentSpeed + add

    setBoostActive(veh, true)
    raceTurbo(true)
    setForwardSpeed(veh, targetSpeed)

    driftgod.S.boostFXLastPulseClock = os.clock()
    driftgod.S.boostFXNeedsDeactivate = true

    log("pulse veh=" .. tostring(veh) ..
        " currentSpeed=" .. string.format("%.2f", currentSpeed) ..
        " add=" .. string.format("%.2f", add) ..
        " target=" .. string.format("%.2f", targetSpeed))

    toast("Boost FX Pulse", 1000)
end

function driftgod.ToggleBoostFX()
    driftgod.S = driftgod.S or {}
    driftgod.S.boostFXEnabled = not (driftgod.S.boostFXEnabled == true)
    toast("Boost FX / Red Trail: " .. (driftgod.S.boostFXEnabled and "ON" or "OFF"), 1800)
    log("toggle=" .. tostring(driftgod.S.boostFXEnabled))
end

function driftgod.BoostFXStrengthUp()
    driftgod.S = driftgod.S or {}
    driftgod.S.boostFXStrength = math.min(100.0, (tonumber(driftgod.S.boostFXStrength) or 10.0) + 5.0)
    toast("Boost FX Strength: " .. tostring(driftgod.S.boostFXStrength), 1200)
    log("strength=" .. tostring(driftgod.S.boostFXStrength))
end

function driftgod.BoostFXStrengthDown()
    driftgod.S = driftgod.S or {}
    driftgod.S.boostFXStrength = math.max(1.0, (tonumber(driftgod.S.boostFXStrength) or 10.0) - 5.0)
    toast("Boost FX Strength: " .. tostring(driftgod.S.boostFXStrength), 1200)
    log("strength=" .. tostring(driftgod.S.boostFXStrength))
end

function driftgod.BoostFXStatus()
    driftgod.S = driftgod.S or {}
    return "Boost FX: " .. tostring(driftgod.S.boostFXEnabled == true) ..
        " | Strength: " .. tostring(driftgod.S.boostFXStrength or 10) ..
        " | Interval: " .. tostring(driftgod.S.boostFXIntervalMs or 950) .. "ms"
end

function driftgod.BoostFXTick()
    driftgod.S = driftgod.S or {}

    local veh = getVehicle()

    if driftgod.S.boostFXNeedsDeactivate == true then
        local last = tonumber(driftgod.S.boostFXLastPulseClock or 0) or 0
        if ((os.clock() - last) * 1000.0) >= tonumber(driftgod.S.boostFXActiveMs or 220) then
            if veh and veh ~= 0 then setBoostActive(veh, false) end
            raceTurbo(false)
            driftgod.S.boostFXNeedsDeactivate = false
            log("boost active reset off")
        end
    end

    if driftgod.S.boostFXEnabled ~= true then
        return
    end

    if not veh or veh == 0 or not entityExists(veh) then
        return
    end

    local interval = tonumber(driftgod.S.boostFXIntervalMs or 950) or 950
    local lastPulse = tonumber(driftgod.S.boostFXLastPulseClock or 0) or 0
    if ((os.clock() - lastPulse) * 1000.0) >= interval then
        driftgod.BoostFXPulse()
    end
end

driftgod.Try(function()
    if Script and Script.RegisterLooped then
        Script.RegisterLooped(function()
            if ShouldUnload and ShouldUnload() then return false end
            local active = driftgod.S and (driftgod.S.boostFXEnabled == true or driftgod.S.boostFXNeedsDeactivate == true)
            if active and DG and driftgod.BoostFXTick then driftgod.BoostFXTick() end
            if Script and Script.Yield then Script.Yield(active and 0 or 100) end
        end)

    elseif FeatureMgr and FeatureMgr.AddFeature and Utils and Utils.Joaat and eFeatureType then
        driftgod.SafeAddFeature(Utils.Joaat("DG_BOOSTFX_TICK_V61268"), "DriftGod BoostFX Tick", eFeatureType.Script, "", function()
            if driftgod.BoostFXTick then driftgod.BoostFXTick() end
        end)

    end
end)

if driftgod.S.boostFXEnabled == nil then driftgod.S.boostFXEnabled = false end
if driftgod.S.boostFXStrength == nil then driftgod.S.boostFXStrength = 10.0 end
if driftgod.S.boostFXIntervalMs == nil then driftgod.S.boostFXIntervalMs = 950 end
if driftgod.S.boostFXActiveMs == nil then driftgod.S.boostFXActiveMs = 220 end

return DG
end

__DG_BUNDLE_LOADERS["systems.collision"] = function()
DG = DG or {}
function driftgod.StopRunFromCollision()

    if DG and driftgod.IsPostStuntLandingGraceActive and driftgod.IsPostStuntLandingGraceActive() then
        driftgod.S.postStuntCollisionDetected = true
        driftgod.S.postStuntCollisionReason = "collision system"
        if driftgod.Log then driftgod.Log("[Stunts] Collision marker set during stunt grace.") end
    end
    if not driftgod.S.collisionEndsRun then return end
    driftgod.StopRun("Collision", "COLLISION!", "Collision detected. Score stopped.")
end
function driftgod.ShouldCollideHandler(pEntityA, pEntityB, materialA, materialB, vPointA, vWorldA, vPointB, vWorldB)
    local veh = nil
    if GTA and GTA.GetLocalVehicle then veh = GTA.GetLocalVehicle() end
    if not veh then return true end
    if pEntityA == veh or pEntityB == veh then
        local other = (pEntityA == veh) and pEntityB or pEntityA
        local physical = false
        driftgod.Try(function() physical = other and other.IsPhysical and other:IsPhysical() end)
        if physical then driftgod.StopRunFromCollision() end
    end
    return true
end
if EventMgr and eLuaEvent and eLuaEvent.SHOULD_COLLIDE then
    EventMgr.RegisterHandler(eLuaEvent.SHOULD_COLLIDE, driftgod.ShouldCollideHandler)
end
return DG
end

__DG_BUNDLE_LOADERS["systems.drift"] = function()
DG = DG or {}

function driftgod.GetHeadingOfTravel(veh)
    local velocity = ENTITY.GET_ENTITY_VELOCITY(veh)
    local angle = math.atan(velocity.y or 0.0, velocity.x or 0.0)
    return math.fmod(270.0 + math.deg(angle), 360.0)
end

function driftgod.GetDriftAngle(veh)
    local drift = ENTITY.GET_ENTITY_HEADING(veh) - driftgod.GetHeadingOfTravel(veh)
    drift = driftgod.Wrap360(drift)
    if drift > 180.0 then drift = 360.0 - drift end
    return drift
end

function driftgod.GetSteerBias()
    if driftgod.S and driftgod.S.stabilityAssistEnabled == false then return 0.0 end
    local map = {0.22, 0.31, 0.38, 0.46, 0.54}
    return map[driftgod.S.driftStabilityLevel] or 0.22
end

function driftgod.GetAutoCounterSteerBias(readableAngle, signedAngle)
    driftgod.S = driftgod.S or {}
    if driftgod.S.autoCounterSteerEnabled == false then return 0.0 end
    readableAngle = tonumber(readableAngle or 0.0) or 0.0
    signedAngle = tonumber(signedAngle or readableAngle or 0.0) or 0.0
    if readableAngle < 10.0 then return 0.0 end
    local level = math.floor(tonumber(driftgod.S.autoCounterSteerLevel or 3) or 3)
    if level < 1 then level = 1 end
    if level > 5 then level = 5 end
    local gainMap = {0.075, 0.105, 0.135, 0.170, 0.210}
    local maxMap = {6.0, 8.0, 10.0, 12.0, 14.0}
    local over = math.max(0.0, readableAngle - 12.0)
    local deg = math.min(over * (gainMap[level] or 0.135), maxMap[level] or 10.0)
    if deg <= 0.0 then return 0.0 end
    local sign = signedAngle >= 0 and 1.0 or -1.0
    return math.rad(sign * deg)
end

function driftgod.ApplyAutoCounterSteer(veh, kmh, readableAngle, signedAngle, held)
    if not held or not veh or veh == 0 then return end
    if driftgod.S and driftgod.S.autoCounterSteerEnabled == false then return end
    if driftgod.S and driftgod.S.stuntBusy then return end
    kmh = tonumber(kmh or 0.0) or 0.0
    if kmh < 10.0 then return end
    local now = driftgod.Now and driftgod.Now() or math.floor((os.clock() or 0) * 1000)
    if now - (driftgod.S.lastAutoCounterSteerTick or 0) < 80 then return end
    driftgod.S.lastAutoCounterSteerTick = now
    local bias = driftgod.GetAutoCounterSteerBias(readableAngle, signedAngle)
    if bias == 0.0 then return end
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_STEER_BIAS then VEHICLE.SET_VEHICLE_STEER_BIAS(veh, bias) end
    end)
end

function driftgod.GetEffectiveDriftGripLevel(level)
    level = math.floor(tonumber(level or (driftgod.S and driftgod.S.driftGripLevel) or 1) or 1)
    if level < 1 then level = 1 end
    if level > 5 then level = 5 end
    return 6 - level
end
local function DG_DriftSetReduceGrip(veh, enabled)
    if DG and driftgod.SafeSetVehicleReduceGrip then
        return driftgod.SafeSetVehicleReduceGrip(veh, enabled == true)
    end
    local ok = driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_REDUCE_GRIP then
            VEHICLE.SET_VEHICLE_REDUCE_GRIP(veh, enabled == true)
        end
    end)
    return ok
end

local function DG_DriftSetReduceGripLevel(veh, level)
    if DG and driftgod.SafeSetVehicleReduceGripLevel then
        return driftgod.SafeSetVehicleReduceGripLevel(veh, level)
    end
    return false
end

function driftgod.ResetVehicleState(showToast)
    if not driftgod.HasNatives() then return end
    local veh = driftgod.GetVehicle()
    if veh == 0 then return end
    driftgod.Try(function()
        DG_DriftSetReduceGrip(veh, false)
        VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 0, false)
        VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 1, false)
        VEHICLE.SET_VEHICLE_STEER_BIAS(veh, 0.0)
    end)
    driftgod.S.isDrifting = false
    driftgod.S.prevGripState = false
    driftgod.S.oldGripState = false
    driftgod.S.lastDriftAngle = 0.0
    driftgod.S.driftWasActive = false
    if showToast then driftgod.Toast("Vehicle grip / indicators reset.", 2500) end
end

function driftgod.ApplyMomentum(veh, kmh, driftAngle, held)
    if not driftgod.S.momentumAssistEnabled or not held or driftgod.S.stuntBusy then return end
    local now = driftgod.Now()
    if now - driftgod.S.lastMomentumTick < 120 then return end
    driftgod.S.lastMomentumTick = now
    if kmh < 18.0 or kmh > 120.0 or driftAngle < 12.0 or driftAngle > 110.0 or ENTITY.IS_ENTITY_IN_AIR(veh) then return end
    local velocity = ENTITY.GET_ENTITY_VELOCITY(veh)
    local map = {1.0035, 1.0060, 1.0090, 1.0120, 1.0150}
    local mult = map[driftgod.S.momentumStrength] or 1.0060
    ENTITY.SET_ENTITY_VELOCITY(veh, velocity.x * mult, velocity.y * mult, velocity.z)
end

function driftgod.ApplyAccel(veh, kmh, driftAngle, held)
    if not driftgod.S.accelAssistEnabled or not held or driftgod.S.stuntBusy then return end
    local now = driftgod.Now()
    if now - driftgod.S.lastAccelTick < 135 then return end
    driftgod.S.lastAccelTick = now
    if ENTITY.IS_ENTITY_IN_AIR(veh) or kmh < 3.0 or kmh > 92.0 or driftAngle < 4.0 or driftAngle > 122.0 then return end
    local velocity = ENTITY.GET_ENTITY_VELOCITY(veh)
    local level = math.max(1, math.min(5, math.floor(tonumber(driftgod.S.accelStrength or 3) or 3)))
    local map = {1.0065, 1.0105, 1.0150, 1.0205, 1.0270}
    local lowMap = {0.0007, 0.0013, 0.0021, 0.0030, 0.0042}
    local lowSpeed = math.max(0.0, math.min(1.0, (62.0 - kmh) / 57.0))
    local mult = (map[level] or 1.0150) + ((lowMap[level] or 0.0021) * lowSpeed)
    ENTITY.SET_ENTITY_VELOCITY(veh, velocity.x * mult, velocity.y * mult, velocity.z)
end

function driftgod.ApplyExperimental(veh, kmh, driftAngle, held)
    if not held or driftgod.S.stuntBusy then return end
    local now = driftgod.Now()
    if driftgod.S.experimentalGravityEnabled and now - driftgod.S.lastGravityTick >= 90 then
        driftgod.S.lastGravityTick = now
        if kmh >= 8.0 and driftAngle >= 5.0 then
            local map = {-0.035, -0.060, -0.090, -0.125, -0.165}
            ENTITY.APPLY_FORCE_TO_ENTITY(veh, 1, 0.0, 0.0, map[driftgod.S.experimentalGravityStrength] or -0.060, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
        end
    end
    if driftgod.S.experimentalAccelEnabled and now - driftgod.S.lastExperimentalAccelTick >= 115 then
        driftgod.S.lastExperimentalAccelTick = now
        if not ENTITY.IS_ENTITY_IN_AIR(veh) and kmh >= 3.0 and kmh <= 112.0 and driftAngle >= 4.0 and driftAngle <= 125.0 then
            local velocity = ENTITY.GET_ENTITY_VELOCITY(veh)
            local level = math.max(1, math.min(5, math.floor(tonumber(driftgod.S.experimentalAccelStrength or 3) or 3)))
            local map = {1.0040, 1.0070, 1.0105, 1.0155, 1.0220}
            local lowMap = {0.0005, 0.0010, 0.0016, 0.0022, 0.0031}
            local lowSpeed = math.max(0.0, math.min(1.0, (68.0 - kmh) / 63.0))
            local mult = (map[level] or 1.0105) + ((lowMap[level] or 0.0016) * lowSpeed)
            ENTITY.SET_ENTITY_VELOCITY(veh, velocity.x * mult, velocity.y * mult, velocity.z)
        end
    end
    if driftgod.S.experimentalTractionEnabled and now - driftgod.S.lastExperimentalTractionTick >= 160 then
        driftgod.S.lastExperimentalTractionTick = now
        if kmh >= 5.0 then
            DG_DriftSetReduceGrip(veh, true)
            DG_DriftSetReduceGripLevel(veh, driftgod.S.experimentalTractionLevel)
        end
    end
end

function driftgod.DriftTick()
    if not driftgod.HasNatives() or not driftgod.S.driftAssistEnabled then return end
    local veh = driftgod.GetVehicle()
    if veh == 0 then
        if driftgod.S.driftWasActive then driftgod.ResetVehicleState(false) end
        return
    end
    if driftgod.VehicleSectorGateTick and not driftgod.VehicleSectorGateTick("drift", veh) then
        return
    end
    driftgod.S.driftWasActive = true
    local kmh = ENTITY.GET_ENTITY_SPEED(veh) * 3.6
    local held = driftgod.IsDriftHeld()
    if held and driftgod.IsLockedArcadePresetBlocking and driftgod.IsLockedArcadePresetBlocking() then
        if driftgod.ShowLockedArcadePresetShiftNotice then driftgod.ShowLockedArcadePresetShiftNotice() end
        if driftgod.S.oldGripState then DG_DriftSetReduceGrip(veh, false) driftgod.S.oldGripState = false end
        if driftgod.ResetVehicleState then driftgod.Try(function() driftgod.ResetVehicleState(false) end) end
        driftgod.S.prevGripState = false
        driftgod.S.isDrifting = false
        return
    end
    if held then
        driftgod.S.hudVisibleUntil = driftgod.Now() + driftgod.S.hudFadeAfterMs
        driftgod.S.hudAlpha = 255
        local drift = ENTITY.GET_ENTITY_HEADING(veh) - driftgod.GetHeadingOfTravel(veh)
        if drift and driftgod.S.lastDriftAngle then
            local diff = drift - driftgod.S.lastDriftAngle
            if diff > 180.0 then drift = drift - 360.0 end
            if diff < -180.0 then drift = drift + 360.0 end
        end
        drift = driftgod.Wrap360(drift)
        driftgod.S.lastDriftAngle = drift
        local readable = drift
        local signedDrift = drift
        if readable > 180.0 then readable = 360.0 - readable end
        if signedDrift > 180.0 then signedDrift = -(360.0 - signedDrift) end
        if driftgod.ApplyAutoCounterSteer then driftgod.ApplyAutoCounterSteer(veh, kmh, readable, signedDrift, held) end
        driftgod.ApplyMomentum(veh, kmh, readable, held)
        driftgod.ApplyAccel(veh, kmh, readable, held)
        driftgod.ApplyExperimental(veh, kmh, readable, held)
        local done = false
        if ((driftgod.S.isDrifting or kmh > 12.0) and (math.abs(drift - 360.0) < 50.0 or drift < 50.0)) then
            driftgod.S.isDrifting = true
            if not driftgod.S.oldGripState then
                DG_DriftSetReduceGrip(veh, true)
                driftgod.Try(function() DG_DriftSetReduceGripLevel(veh, driftgod.GetEffectiveDriftGripLevel(driftgod.S.driftGripLevel)) end)
                driftgod.S.oldGripState = true
            end
            done = true
        end
        if not done and kmh < 12.0 then
            if not driftgod.S.oldGripState then
                DG_DriftSetReduceGrip(veh, true)
                driftgod.S.oldGripState = true
            end
            done = true
        end
        if not done then
            local steer = driftgod.GetSteerBias()
            if driftgod.S.oldGripState then DG_DriftSetReduceGrip(veh, false) driftgod.S.oldGripState = false end
            if math.abs(drift - 360.0) < 60.0 then
                VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 0, true)
                VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 1, false)
                VEHICLE.SET_VEHICLE_STEER_BIAS(veh, steer)
            elseif drift < 55.0 then
                VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 1, true)
                VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 0, false)
                VEHICLE.SET_VEHICLE_STEER_BIAS(veh, -steer)
            end
        else
            VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 0, false)
            VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 1, false)
        end
        if driftgod.ApplyArcadeDriftPresetRuntime then
            driftgod.Try(function() driftgod.ApplyArcadeDriftPresetRuntime(veh, kmh, readable, held) end)
        end
    end
    if not held and driftgod.S.prevGripState then driftgod.ResetVehicleState(false) end
    driftgod.S.prevGripState = held
end

return DG
end

__DG_BUNDLE_LOADERS["systems.experimental_grip"] = function()
DG = DG or {}
driftgod.S = driftgod.S or {}

local function log(msg)
    if DG and driftgod.Log then
        driftgod.Log("[ExperimentalGrip] " .. tostring(msg))
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] [ExperimentalGrip] " .. tostring(msg))
    end
end

local function clamp(v, lo, hi)
    v = tonumber(v or 0) or 0
    if v < lo then return lo end
    if v > hi then return hi end
    return v
end

local function ptrToHandle(ptr)
    if not ptr then return 0 end
    if type(ptr) == "number" then return ptr end
    local h = 0
    driftgod.Try(function()
        if GTA and GTA.PointerToHandle then
            h = GTA.PointerToHandle(ptr)
        end
    end)
    return tonumber(h) or 0
end

local function getVehicle()
    local veh = 0

    driftgod.Try(function()
        if driftgod.GetVehicle then
            veh = ptrToHandle(driftgod.GetVehicle())
        end
    end)

    if veh == 0 then
        driftgod.Try(function()
            local ped = 0
            if PLAYER and PLAYER.PLAYER_PED_ID then
                ped = PLAYER.PLAYER_PED_ID()
            elseif Natives and Natives.InvokeInt then
                ped = Natives.InvokeInt(0xD80958FC74E988A6)
            end

            if ped and ped ~= 0 then
                if PED and PED.GET_VEHICLE_PED_IS_IN then
                    veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
                elseif Natives and Natives.InvokeInt then
                    veh = Natives.InvokeInt(0x9A9112A0FE9A4713, ped, false)
                end
            end
        end)
    end

    return tonumber(veh) or 0
end

local function setReduceGrip(veh, enabled)
    if DG and driftgod.SafeSetVehicleReduceGrip then
        return driftgod.SafeSetVehicleReduceGrip(veh, enabled == true)
    end
    local ok = driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_REDUCE_GRIP then
            VEHICLE.SET_VEHICLE_REDUCE_GRIP(veh, enabled == true)
        elseif Natives and Natives.InvokeVoid then
            Natives.InvokeVoid(0x222FF6A823D122E2, veh, enabled == true)
        end
    end)
    return ok
end

local function setFrictionOverride(veh, friction)
    friction = clamp(friction, 0.0, 2.0)

    if DG and driftgod.SafeSetVehicleFrictionOverride then
        return driftgod.SafeSetVehicleFrictionOverride(veh, friction)
    end
    return false
end

local function controlPressed(control)
    if not control then return false end
    local c = tonumber(control)
    if not c then return false end

    local pressed = false
    driftgod.Try(function()
        if PAD and PAD.IS_DISABLED_CONTROL_PRESSED and PAD.IS_DISABLED_CONTROL_PRESSED(0, c) then pressed = true end
        if PAD and PAD.IS_CONTROL_PRESSED and PAD.IS_CONTROL_PRESSED(0, c) then pressed = true end
        if Natives and Natives.InvokeBool then
            if Natives.InvokeBool(0xE2587F8CBBD87B1D, 0, c) then pressed = true end
            if Natives.InvokeBool(0xF3A21BCD95725CA0B, 0, c) then pressed = true end
        end
    end)
    return pressed
end

local function keyPressed(vk)
    local pressed = false
    driftgod.Try(function()
        if Utils and Utils.IsKeyPressed and Utils.IsKeyPressed(vk) then pressed = true end
    end)
    return pressed
end

local function isShiftBindPressed()

    if keyPressed(0x10) or keyPressed(0xA0) or keyPressed(0xA1) then
        return true
    end

    if controlPressed(21) or controlPressed(22) then
        return true
    end

    return false
end

local function gripToFriction(level)
    level = math.floor(clamp(level, 0, 5))

    local map = {
        [0] = 0.15,
        [1] = 0.28,
        [2] = 0.45,
        [3] = 0.70,
        [4] = 1.00,
        [5] = 1.35,
    }

    return map[level] or 0.70
end

function driftgod.ApplyExperimentalGrip()
    driftgod.S = driftgod.S or {}

    local veh = getVehicle()
    if not veh or veh == 0 then return end

    if driftgod.S.experimentalGripEnabled ~= true or not isShiftBindPressed() then
        if driftgod.S._experimentalGripWasOn == true then
            setReduceGrip(veh, false)
            setFrictionOverride(veh, 1.0)
            driftgod.S._experimentalGripWasOn = false
            log("cleared / shift released")
        end
        return
    end

    local level = clamp(tonumber(driftgod.S.experimentalGripLevel or 3) or 3, 0, 5)
    local friction = gripToFriction(level)

    setReduceGrip(veh, level <= 2)
    setFrictionOverride(veh, friction)

    driftgod.S._experimentalGripWasOn = true
end

function driftgod.SetExperimentalGripLevel(level)
    driftgod.S = driftgod.S or {}
    driftgod.S.experimentalGripLevel = math.floor(clamp(level, 0, 5))
    if driftgod.Toast then
        driftgod.Toast("Experimental Grip: " .. tostring(driftgod.S.experimentalGripLevel) .. " / 5", 1200)
    end
end

driftgod.Try(function()
    if Script and Script.RegisterLooped then
        Script.RegisterLooped(function()
            if ShouldUnload and ShouldUnload() then return false end
            local active = driftgod.S and (driftgod.S.experimentalGripEnabled == true or driftgod.S._experimentalGripWasOn == true)
            if active and DG and driftgod.ApplyExperimentalGrip then driftgod.ApplyExperimentalGrip() end
            if Script and Script.Yield then Script.Yield(active and 0 or 100) end
        end)

    elseif FeatureMgr and FeatureMgr.AddFeature and Utils and Utils.Joaat and eFeatureType then
        driftgod.SafeAddFeature(Utils.Joaat("DG_EXPERIMENTAL_GRIP_TICK_V61292"), "DriftGod Experimental Grip Tick", eFeatureType.Script, "", function()
            if DG and driftgod.ApplyExperimentalGrip then driftgod.ApplyExperimentalGrip() end
        end)

    end
end)

if driftgod.S.experimentalGripEnabled == nil then driftgod.S.experimentalGripEnabled = false end
if driftgod.S.experimentalGripLevel == nil then driftgod.S.experimentalGripLevel = 3 end

return DG
end

__DG_BUNDLE_LOADERS["systems.horn_boost_probe"] = function()
DG = DG or {}
driftgod.S = driftgod.S or {}

local HASH_HORN_BOOST = 1333242408
local HASH_FORWARD_STRENGTH = 3887896978
local HASH_BOOST_FX = 1034789123
local HASH_BOOST_FX_SOUND = 3775835664

local natives = {
    playerPedId = 0xD80958FC74E988A6,
    isPedInAnyVehicle = 0x997ABD671D25CA0B,
    getVehiclePedIsIn = 0x9A9112A0FE9A4713,
    doesEntityExist = 0x7239B21A38F536BA,
    getEntitySpeed = 0xD5037BA82E12416F,
    setVehicleForwardSpeed = 0xAB54A438726D25D5,
    setVehicleBoostActive = 0x4A04DE7CAB2739A1,
}

local function log(msg)
    if DG and driftgod.Log then
        driftgod.Log("[HornProbe] " .. tostring(msg))
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] [HornProbe] " .. tostring(msg))
    end
end

local function toast(msg, ms)
    if DG and driftgod.Toast then
        driftgod.Toast(tostring(msg), ms or 1800)
    elseif GUI and GUI.AddToast then
        GUI.AddToast("DriftGod", tostring(msg), ms or 1800)
    end
end

local function ptrToHandle(ptr)
    if not ptr then return 0 end
    if type(ptr) == "number" then return ptr end
    local h = 0
    driftgod.Try(function()
        if GTA and GTA.PointerToHandle then
            h = GTA.PointerToHandle(ptr)
        end
    end)
    return tonumber(h) or 0
end

local function getVehicle()
    local veh = 0

    driftgod.Try(function()
        if DG and driftgod.GetVehicle then
            veh = ptrToHandle(driftgod.GetVehicle())
        end
    end)

    if not veh or veh == 0 then
        driftgod.Try(function()
            if GTA and GTA.GetLocalVehicle then
                veh = ptrToHandle(GTA.GetLocalVehicle())
            end
        end)
    end

    if not veh or veh == 0 then
        driftgod.Try(function()
            if PLAYER and PLAYER.PLAYER_PED_ID and PED and PED.GET_VEHICLE_PED_IS_IN then
                local ped = PLAYER.PLAYER_PED_ID()
                veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
            elseif Natives then
                local ped = Natives.InvokeInt(natives.playerPedId)
                if Natives.InvokeBool(natives.isPedInAnyVehicle, ped, false) then
                    veh = Natives.InvokeInt(natives.getVehiclePedIsIn, ped, false)
                end
            end
        end)
    end

    return tonumber(veh) or 0
end

local function entityExists(ent)
    if not ent or ent == 0 then return false end
    local ok, exists = driftgod.Try(function()
        if ENTITY and ENTITY.DOES_ENTITY_EXIST then
            return ENTITY.DOES_ENTITY_EXIST(ent)
        elseif Natives then
            return Natives.InvokeBool(natives.doesEntityExist, ent)
        end
        return false
    end)
    return ok and exists == true
end

local function getSpeed(veh)
    local speed = 0.0
    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_SPEED then
            speed = ENTITY.GET_ENTITY_SPEED(veh)
        elseif Natives then
            speed = Natives.InvokeFloat(natives.getEntitySpeed, veh)
        end
    end)
    return tonumber(speed) or 0.0
end

local function setForwardSpeed(veh, speed)
    local ok, err = driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_FORWARD_SPEED then
            VEHICLE.SET_VEHICLE_FORWARD_SPEED(veh, speed)
        elseif Natives then
            Natives.InvokeVoid(natives.setVehicleForwardSpeed, veh, speed)
        end
    end)
    log("SET_VEHICLE_FORWARD_SPEED speed=" .. tostring(speed) .. " ok=" .. tostring(ok) .. " err=" .. tostring(err))
    return ok
end

local function setBoostActive(veh, active)
    local ok, err = driftgod.Try(function()
        if AUDIO and AUDIO.SET_VEHICLE_BOOST_ACTIVE then
            AUDIO.SET_VEHICLE_BOOST_ACTIVE(veh, active == true)
        elseif Natives then
            Natives.InvokeVoid(natives.setVehicleBoostActive, veh, active == true)
        end
    end)
    log("SET_VEHICLE_BOOST_ACTIVE active=" .. tostring(active == true) .. " veh=" .. tostring(veh) .. " ok=" .. tostring(ok) .. " err=" .. tostring(err))
    return ok
end

local function getFeature(hash)
    local feat = nil
    driftgod.Try(function()
        if FeatureMgr and FeatureMgr.GetFeature then
            feat = FeatureMgr.GetFeature(hash)
        end
    end)
    return feat
end

local function setFeatureBool(hash, state)
    local feat = getFeature(hash)
    local ok, err = driftgod.Try(function()
        if feat then
            if feat.SetBoolValue then
                feat:SetBoolValue(state == true)
            elseif feat.SetToggle then
                feat:SetToggle(state == true)
            elseif feat.SetToggled then
                feat:SetToggled(state == true)
            elseif feat.SetValue then
                feat:SetValue(state == true)
            end
        end
    end)
    log("set feature hash=" .. tostring(hash) .. " exists=" .. tostring(feat ~= nil) .. " state=" .. tostring(state == true) .. " ok=" .. tostring(ok) .. " err=" .. tostring(err))
    return ok and feat ~= nil
end

local function setFeatureInt(hash, value)
    local feat = getFeature(hash)
    local ok, err = driftgod.Try(function()
        if feat then
            if feat.SetIntValue then
                feat:SetIntValue(value)
            elseif feat.SetValue then
                feat:SetValue(value)
            end
        end
    end)
    log("set int feature hash=" .. tostring(hash) .. " exists=" .. tostring(feat ~= nil) .. " value=" .. tostring(value) .. " ok=" .. tostring(ok) .. " err=" .. tostring(err))
    return ok and feat ~= nil
end

local function triggerFeature(hash)
    local feat = getFeature(hash)
    local ok, err = driftgod.Try(function()
        if feat then
            if feat.TriggerCallback then
                feat:TriggerCallback()
            elseif feat.Trigger then
                feat:Trigger()
            elseif feat.OnClick then
                feat:OnClick()
            elseif feat.TriggerCallbackWithArg then
                feat:TriggerCallbackWithArg(0)
            end
        end
    end)
    log("trigger feature hash=" .. tostring(hash) .. " exists=" .. tostring(feat ~= nil) .. " ok=" .. tostring(ok) .. " err=" .. tostring(err))
    return ok and feat ~= nil
end

local function prepareBuiltInFx()
    setFeatureBool(HASH_BOOST_FX, true)
    setFeatureBool(HASH_BOOST_FX_SOUND, false)
end

function driftgod.HornProbe_CallbackOnly()
    driftgod.S = driftgod.S or {}
    prepareBuiltInFx()
    triggerFeature(HASH_HORN_BOOST)
    toast("Horn Probe: callback only", 1300)
end

function driftgod.HornProbe_CallbackWithStrength()
    driftgod.S = driftgod.S or {}
    local strength = tonumber(driftgod.S.hornProbeBuiltInStrength or 1) or 1

    prepareBuiltInFx()
    setFeatureInt(HASH_FORWARD_STRENGTH, strength)
    setFeatureBool(HASH_HORN_BOOST, true)
    triggerFeature(HASH_HORN_BOOST)

    toast("Horn Probe: callback + strength " .. tostring(strength), 1500)
end

function driftgod.HornProbe_MicroSpeedPulse()
    driftgod.S = driftgod.S or {}

    local veh = getVehicle()
    if not veh or veh == 0 or not entityExists(veh) then
        toast("Horn Probe needs a vehicle.", 1600)
        log("micro pulse failed: no vehicle")
        return
    end

    local currentSpeed = getSpeed(veh)
    local micro = tonumber(driftgod.S.hornProbeMicroSpeed or 0.10) or 0.10

    prepareBuiltInFx()
    setBoostActive(veh, true)

    setForwardSpeed(veh, currentSpeed + micro)

    driftgod.S.hornProbeBoostNeedsOff = true
    driftgod.S.hornProbeBoostLastClock = os.clock()

    log("micro pulse veh=" .. tostring(veh) ..
        " currentSpeed=" .. string.format("%.3f", currentSpeed) ..
        " micro=" .. string.format("%.3f", micro) ..
        " target=" .. string.format("%.3f", currentSpeed + micro))
    toast("Horn Probe: micro-speed pulse", 1300)
end

function driftgod.HornProbe_ToggleHold()
    driftgod.S = driftgod.S or {}
    driftgod.S.hornProbeHold = not (driftgod.S.hornProbeHold == true)
    if driftgod.S.hornProbeHold then
        prepareBuiltInFx()
    else
        setFeatureBool(HASH_HORN_BOOST, false)
        setFeatureBool(HASH_BOOST_FX, false)
        setFeatureBool(HASH_BOOST_FX_SOUND, false)
        local veh = getVehicle()
        if veh and veh ~= 0 then setBoostActive(veh, false) end
    end
    toast("Horn Probe Hold: " .. (driftgod.S.hornProbeHold and "ON" or "OFF"), 1500)
    log("hold=" .. tostring(driftgod.S.hornProbeHold))
end

function driftgod.HornProbe_StrengthUp()
    driftgod.S = driftgod.S or {}
    driftgod.S.hornProbeBuiltInStrength = math.min(100, (tonumber(driftgod.S.hornProbeBuiltInStrength) or 1) + 1)
    toast("Built-in Horn Strength: " .. tostring(driftgod.S.hornProbeBuiltInStrength), 1000)
end

function driftgod.HornProbe_StrengthDown()
    driftgod.S = driftgod.S or {}
    driftgod.S.hornProbeBuiltInStrength = math.max(1, (tonumber(driftgod.S.hornProbeBuiltInStrength) or 1) - 1)
    toast("Built-in Horn Strength: " .. tostring(driftgod.S.hornProbeBuiltInStrength), 1000)
end

function driftgod.HornProbe_MicroUp()
    driftgod.S = driftgod.S or {}
    driftgod.S.hornProbeMicroSpeed = math.min(5.0, (tonumber(driftgod.S.hornProbeMicroSpeed) or 0.10) + 0.10)
    toast("Micro Speed: " .. string.format("%.2f", driftgod.S.hornProbeMicroSpeed), 1000)
end

function driftgod.HornProbe_MicroDown()
    driftgod.S = driftgod.S or {}
    driftgod.S.hornProbeMicroSpeed = math.max(0.0, (tonumber(driftgod.S.hornProbeMicroSpeed) or 0.10) - 0.10)
    toast("Micro Speed: " .. string.format("%.2f", driftgod.S.hornProbeMicroSpeed), 1000)
end

function driftgod.HornProbe_Stop()
    driftgod.S = driftgod.S or {}
    driftgod.S.hornProbeHold = false
    driftgod.S.hornProbeBoostNeedsOff = false
    setFeatureBool(HASH_HORN_BOOST, false)
    setFeatureBool(HASH_BOOST_FX, false)
    setFeatureBool(HASH_BOOST_FX_SOUND, false)

    local veh = getVehicle()
    if veh and veh ~= 0 then
        setBoostActive(veh, false)
    end

    toast("Horn Probe stopped", 1200)
    log("stopped")
end

function driftgod.HornProbeStatus()
    driftgod.S = driftgod.S or {}
    return "Horn Probe: " .. tostring(driftgod.S.hornProbeHold == true) ..
        " | BuiltInStrength: " .. tostring(driftgod.S.hornProbeBuiltInStrength or 1) ..
        " | Micro: " .. string.format("%.2f", tonumber(driftgod.S.hornProbeMicroSpeed or 0.10) or 0.10)
end

function driftgod.HornProbeTick()
    driftgod.S = driftgod.S or {}

    local veh = getVehicle()

    if driftgod.S.hornProbeBoostNeedsOff == true then
        local last = tonumber(driftgod.S.hornProbeBoostLastClock or 0) or 0
        if ((os.clock() - last) * 1000.0) >= tonumber(driftgod.S.hornProbeActiveMs or 180) then
            if veh and veh ~= 0 then setBoostActive(veh, false) end
            driftgod.S.hornProbeBoostNeedsOff = false
            log("boost active reset off")
        end
    end

    if driftgod.S.hornProbeHold ~= true then return end

    local interval = tonumber(driftgod.S.hornProbeIntervalMs or 900) or 900
    local last = tonumber(driftgod.S.hornProbeLastClock or 0) or 0

    if ((os.clock() - last) * 1000.0) >= interval then
        driftgod.S.hornProbeLastClock = os.clock()

        if driftgod.S.hornProbeHoldMode == "micro" then
            driftgod.HornProbe_MicroSpeedPulse()
        else
            driftgod.HornProbe_CallbackWithStrength()
        end
    end
end

driftgod.Try(function()
    if Script and Script.RegisterLooped then
        Script.RegisterLooped(function()
            if ShouldUnload and ShouldUnload() then return false end
            local active = driftgod.S and (driftgod.S.hornProbeHold == true or driftgod.S.hornProbeBoostNeedsOff == true)
            if active and DG and driftgod.HornProbeTick then driftgod.HornProbeTick() end
            if Script and Script.Yield then Script.Yield(active and 0 or 100) end
        end)

    elseif FeatureMgr and FeatureMgr.AddFeature and Utils and Utils.Joaat and eFeatureType then
        driftgod.SafeAddFeature(Utils.Joaat("DG_HORN_PROBE_TICK_V61271"), "DriftGod Horn Probe Tick", eFeatureType.Script, "", function()
            if driftgod.HornProbeTick then driftgod.HornProbeTick() end
        end)

    end
end)

if driftgod.S.hornProbeHold == nil then driftgod.S.hornProbeHold = false end
if driftgod.S.hornProbeBuiltInStrength == nil then driftgod.S.hornProbeBuiltInStrength = 1 end
if driftgod.S.hornProbeMicroSpeed == nil then driftgod.S.hornProbeMicroSpeed = 0.10 end
if driftgod.S.hornProbeIntervalMs == nil then driftgod.S.hornProbeIntervalMs = 900 end
if driftgod.S.hornProbeActiveMs == nil then driftgod.S.hornProbeActiveMs = 180 end
if driftgod.S.hornProbeHoldMode == nil then driftgod.S.hornProbeHoldMode = "callback" end

return DG
end

__DG_BUNDLE_LOADERS["systems.input"] = function()
DG = DG or {}

function driftgod.GetPed()
    if not driftgod.HasNatives() then return 0 end
    local ped = 0
    driftgod.Try(function() ped = PLAYER.PLAYER_PED_ID() end)
    if ped and ped ~= 0 then return ped end
    driftgod.Try(function() ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(PLAYER.PLAYER_ID()) end)
    return ped or 0
end

function driftgod.GetVehicle()
    if not driftgod.HasNatives() then return 0 end
    local ped = driftgod.GetPed()
    if not ped or ped == 0 then return 0 end
    local inVeh = false
    driftgod.Try(function() inVeh = PED.IS_PED_IN_ANY_VEHICLE(ped, false) end)
    if not inVeh then return 0 end
    local veh = 0
    driftgod.Try(function() veh = PED.GET_VEHICLE_PED_IS_IN(ped, false) end)
    if not veh or veh == 0 then return 0 end
    local exists = true
    driftgod.Try(function() exists = ENTITY.DOES_ENTITY_EXIST(veh) end)
    if not exists then return 0 end
    return veh
end

function driftgod.IsInVehicle() return driftgod.GetVehicle() ~= 0 end

function driftgod.IsDrivingVehicle()
    if not driftgod.HasNatives() then return false end
    local ped = driftgod.GetPed()
    local veh = driftgod.GetVehicle()
    if ped == 0 or veh == 0 then return false end
    local driverPed = 0
    driftgod.Try(function() driverPed = VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, -1, false) end)
    return driverPed == ped
end

function driftgod.RequireVehicle()
    local veh = driftgod.GetVehicle()
    if veh == 0 then driftgod.Toast("Get inside a vehicle first.", 2500) end
    return veh
end

function driftgod.IsControlPressed(control)
    if not driftgod.HasNatives() or not control or control < 0 then return false end
    return PAD.IS_CONTROL_PRESSED(0, control) or PAD.IS_CONTROL_PRESSED(2, control) or PAD.IS_DISABLED_CONTROL_PRESSED(0, control) or PAD.IS_DISABLED_CONTROL_PRESSED(2, control)
end

function driftgod.IsControlJustPressed(control)
    if not driftgod.HasNatives() or not control or control < 0 then return false end
    return PAD.IS_CONTROL_JUST_PRESSED(0, control) or PAD.IS_CONTROL_JUST_PRESSED(2, control) or PAD.IS_DISABLED_CONTROL_JUST_PRESSED(0, control) or PAD.IS_DISABLED_CONTROL_JUST_PRESSED(2, control)
end

function driftgod.IsDriftHeld()
    if not driftgod.HasNatives() then return false end
    local c = driftgod.Controls
    return PAD.IS_CONTROL_PRESSED(2, c.VEHICLE_DUCK)
        or PAD.IS_DISABLED_CONTROL_PRESSED(2, c.VEHICLE_DUCK)
        or PAD.IS_CONTROL_PRESSED(0, c.VEHICLE_MOVE_UP_ONLY)
        or PAD.IS_DISABLED_CONTROL_PRESSED(0, c.VEHICLE_MOVE_UP_ONLY)
end

function driftgod.GetInput()
    return { x = PAD.GET_CONTROL_NORMAL(0, 1), y = PAD.GET_CONTROL_NORMAL(0, 2) }
end

function driftgod.BlockScrollWheelControls()
    if not driftgod.HasNatives() or not driftgod.S.disableScrollWheel then return end
    local c = driftgod.Controls
    PAD.DISABLE_CONTROL_ACTION(0, c.MOUSE_WHEEL_UP, true)
    PAD.DISABLE_CONTROL_ACTION(0, c.MOUSE_WHEEL_DOWN, true)
    PAD.DISABLE_CONTROL_ACTION(2, c.MOUSE_WHEEL_UP, true)
    PAD.DISABLE_CONTROL_ACTION(2, c.MOUSE_WHEEL_DOWN, true)
    PAD.DISABLE_CONTROL_ACTION(0, c.SELECT_NEXT_WEAPON, true)
    PAD.DISABLE_CONTROL_ACTION(0, c.SELECT_PREV_WEAPON, true)
    PAD.DISABLE_CONTROL_ACTION(2, c.SELECT_NEXT_WEAPON, true)
    PAD.DISABLE_CONTROL_ACTION(2, c.SELECT_PREV_WEAPON, true)
end

function driftgod.InputTick()
    if not driftgod.HasNatives() then return end
    driftgod.BlockScrollWheelControls()
    if driftgod.S.disableQRadioBind then
        PAD.DISABLE_CONTROL_ACTION(0, driftgod.Controls.RADIO_WHEEL, true)
        PAD.DISABLE_CONTROL_ACTION(2, driftgod.Controls.RADIO_WHEEL, true)
        PAD.DISABLE_CONTROL_ACTION(0, driftgod.Controls.Q, true)
        PAD.DISABLE_CONTROL_ACTION(2, driftgod.Controls.Q, true)
    end

end

return DG
end

__DG_BUNDLE_LOADERS["systems.manual_horn_fx_matrix"] = function()
DG = DG or {}
driftgod.S = driftgod.S or {}

local HASH_HORN_BOOST = 1333242408
local HASH_FORWARD_STRENGTH = 3887896978
local HASH_BOOST_FX = 1034789123
local HASH_BOOST_FX_SOUND = 3775835664

local function log(msg)
    if DG and driftgod.Log then
        driftgod.Log("[ManualHornFX] " .. tostring(msg))
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] [ManualHornFX] " .. tostring(msg))
    end
end

local function toast(msg, ms)
    if DG and driftgod.Toast then
        driftgod.Toast(tostring(msg), ms or 2200)
    elseif GUI and GUI.AddToast then
        GUI.AddToast("DriftGod", tostring(msg), ms or 2200)
    end
end

local function getFeature(hash)
    local feat = nil
    driftgod.Try(function()
        if FeatureMgr and FeatureMgr.GetFeature then
            feat = FeatureMgr.GetFeature(hash)
        end
    end)
    return feat
end

local function setFeatureBool(hash, state, label)
    local feat = getFeature(hash)
    local ok, err = driftgod.Try(function()
        if feat then
            if feat.SetBoolValue then
                feat:SetBoolValue(state == true)
            elseif feat.SetToggle then
                feat:SetToggle(state == true)
            elseif feat.SetToggled then
                feat:SetToggled(state == true)
            elseif feat.SetValue then
                feat:SetValue(state == true)
            elseif feat.Toggle and state == true then
                feat:Toggle()
            end
        end
    end)

    log("set bool " .. tostring(label or hash) ..
        " hash=" .. tostring(hash) ..
        " exists=" .. tostring(feat ~= nil) ..
        " state=" .. tostring(state == true) ..
        " ok=" .. tostring(ok) ..
        " err=" .. tostring(err))

    return ok and feat ~= nil
end

local function setFeatureInt(hash, value, label)
    local feat = getFeature(hash)
    local ok, err = driftgod.Try(function()
        if feat then
            if feat.SetIntValue then
                feat:SetIntValue(value)
            elseif feat.SetValue then
                feat:SetValue(value)
            end
        end
    end)

    log("set int " .. tostring(label or hash) ..
        " hash=" .. tostring(hash) ..
        " exists=" .. tostring(feat ~= nil) ..
        " value=" .. tostring(value) ..
        " ok=" .. tostring(ok) ..
        " err=" .. tostring(err))

    return ok and feat ~= nil
end

local function triggerFeature(hash, label)
    local feat = getFeature(hash)
    local ok, err = driftgod.Try(function()
        if feat then
            if feat.TriggerCallback then
                feat:TriggerCallback()
            elseif feat.Trigger then
                feat:Trigger()
            elseif feat.OnClick then
                feat:OnClick()
            end
        end
    end)

    log("trigger " .. tostring(label or hash) ..
        " hash=" .. tostring(hash) ..
        " exists=" .. tostring(feat ~= nil) ..
        " ok=" .. tostring(ok) ..
        " err=" .. tostring(err))

    return ok and feat ~= nil
end

local function applyMatrix(soundOn)
    driftgod.S = driftgod.S or {}

    local strength = tonumber(driftgod.S.manualHornFXStrength or 10) or 10
    local hornOn = driftgod.S.manualHornFXHornBoost ~= false
    local fxOn = driftgod.S.manualHornFXBoostFX ~= false

    setFeatureInt(HASH_FORWARD_STRENGTH, strength, "Forward Strength")
    setFeatureBool(HASH_BOOST_FX, fxOn, "Boost FX")
    setFeatureBool(HASH_BOOST_FX_SOUND, soundOn == true, "Boost FX Sound")
    setFeatureBool(HASH_HORN_BOOST, hornOn, "Horn Boost")

    driftgod.S.manualHornFXActive = true
    driftgod.S.manualHornFXSound = soundOn == true

    log("matrix applied horn=" .. tostring(hornOn) ..
        " boostFx=" .. tostring(fxOn) ..
        " sound=" .. tostring(soundOn == true) ..
        " strength=" .. tostring(strength))

    toast("Manual Horn FX Matrix ON | Now press horn in-game", 3200)
end

function driftgod.ManualHornFX_OnSoundOff()
    applyMatrix(false)
end

function driftgod.ManualHornFX_OnSoundOn()
    applyMatrix(true)
end

function driftgod.ManualHornFX_TriggerThenPressHorn()
    applyMatrix(driftgod.S.manualHornFXSound == true)
    triggerFeature(HASH_HORN_BOOST, "Horn Boost")
    toast("Triggered once. Now physically press horn.", 3000)
end

function driftgod.ManualHornFX_StrengthUp()
    driftgod.S = driftgod.S or {}
    driftgod.S.manualHornFXStrength = math.min(100, (tonumber(driftgod.S.manualHornFXStrength) or 10) + 5)
    setFeatureInt(HASH_FORWARD_STRENGTH, driftgod.S.manualHornFXStrength, "Forward Strength")
    toast("Manual Horn FX Strength: " .. tostring(driftgod.S.manualHornFXStrength), 1400)
end

function driftgod.ManualHornFX_StrengthDown()
    driftgod.S = driftgod.S or {}
    driftgod.S.manualHornFXStrength = math.max(1, (tonumber(driftgod.S.manualHornFXStrength) or 10) - 5)
    setFeatureInt(HASH_FORWARD_STRENGTH, driftgod.S.manualHornFXStrength, "Forward Strength")
    toast("Manual Horn FX Strength: " .. tostring(driftgod.S.manualHornFXStrength), 1400)
end

function driftgod.ManualHornFX_ToggleSound()
    driftgod.S = driftgod.S or {}
    driftgod.S.manualHornFXSound = not (driftgod.S.manualHornFXSound == true)
    setFeatureBool(HASH_BOOST_FX_SOUND, driftgod.S.manualHornFXSound == true, "Boost FX Sound")
    toast("Boost FX Sound: " .. (driftgod.S.manualHornFXSound and "ON" or "OFF"), 1400)
end

function driftgod.ManualHornFX_Stop()
    driftgod.S = driftgod.S or {}
    setFeatureBool(HASH_HORN_BOOST, false, "Horn Boost")
    setFeatureBool(HASH_BOOST_FX, false, "Boost FX")
    setFeatureBool(HASH_BOOST_FX_SOUND, false, "Boost FX Sound")
    driftgod.S.manualHornFXActive = false
    toast("Manual Horn FX Matrix OFF", 1600)
    log("stopped")
end

function driftgod.ManualHornFXStatus()
    driftgod.S = driftgod.S or {}
    return "Manual Horn FX: " .. tostring(driftgod.S.manualHornFXActive == true) ..
        " | Strength: " .. tostring(driftgod.S.manualHornFXStrength or 10) ..
        " | Sound: " .. tostring(driftgod.S.manualHornFXSound == true) ..
        " | Press horn manually"
end

if driftgod.S.manualHornFXActive == nil then driftgod.S.manualHornFXActive = false end
if driftgod.S.manualHornFXStrength == nil then driftgod.S.manualHornFXStrength = 10 end
if driftgod.S.manualHornFXSound == nil then driftgod.S.manualHornFXSound = false end
if driftgod.S.manualHornFXHornBoost == nil then driftgod.S.manualHornFXHornBoost = true end
if driftgod.S.manualHornFXBoostFX == nil then driftgod.S.manualHornFXBoostFX = true end

return DG
end

__DG_BUNDLE_LOADERS["systems.no_score_zones"] = function()
DG = DG or {}
driftgod.NoScoreZones = driftgod.NoScoreZones or {}

local function now_ms()
    if driftgod.Now then return driftgod.Now() end
    return math.floor((os.clock() or 0) * 1000)
end

local function clean_name(name)
    name = tostring(name or "Banned Area")
    name = name:gsub("[^%w%s%-%_#]", "")
    if name == "" then name = "Banned Area" end
    return name
end

local function log_info(msg)
    msg = tostring(msg or "")
    if msg == "" then return end
    if driftgod.LogInfo then driftgod.LogInfo(msg)
    elseif driftgod.Log then driftgod.Log("[Banned] " .. msg)
    elseif Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] [Banned] " .. msg)
    end
end

local function get_pos()
    if not driftgod.HasNatives or not driftgod.HasNatives() then return nil end
    local ent = 0
    if driftgod.GetVehicle then ent = driftgod.GetVehicle() end
    if not ent or ent == 0 then
        if driftgod.GetPed then ent = driftgod.GetPed() end
    end
    if not ent or ent == 0 then return nil end

    local ok, v = driftgod.Try(function() return ENTITY.GET_ENTITY_COORDS(ent, true) end)
    if ok and v then
        if type(v) == "table" and v.x and v.y and v.z then
            return { x = tonumber(v.x) or 0.0, y = tonumber(v.y) or 0.0, z = tonumber(v.z) or 0.0, ent = ent }
        end
        if type(v) == "userdata" then
            local x = tonumber(v.x or v.X or 0.0) or 0.0
            local y = tonumber(v.y or v.Y or 0.0) or 0.0
            local z = tonumber(v.z or v.Z or 0.0) or 0.0
            return { x = x, y = y, z = z, ent = ent }
        end
    end

    if Natives and driftgod.Natives and driftgod.Natives.GET_ENTITY_COORDS then
        local ok2, x, y, z = driftgod.Try(Natives.InvokeV3, driftgod.Natives.GET_ENTITY_COORDS, ent, true)
        if ok2 and x then
            if type(x) == "number" then
                return { x = x or 0.0, y = y or 0.0, z = z or 0.0, ent = ent }
            elseif type(x) == "table" then
                return { x = tonumber(x.x or x.X or 0.0) or 0.0, y = tonumber(x.y or x.Y or 0.0) or 0.0, z = tonumber(x.z or x.Z or 0.0) or 0.0, ent = ent }
            elseif type(x) == "userdata" then
                return { x = tonumber(x.x or x.X or 0.0) or 0.0, y = tonumber(x.y or x.Y or 0.0) or 0.0, z = tonumber(x.z or x.Z or 0.0) or 0.0, ent = ent }
            end
        end
    end

    return nil
end

function driftgod.GetBannedAreas()
    driftgod.S = driftgod.S or {}
    if type(driftgod.S.noScoreZones) ~= "table" then driftgod.S.noScoreZones = {} end
    return driftgod.S.noScoreZones
end

function driftgod.GetNoScoreZones()
    return driftgod.GetBannedAreas()
end

function driftgod.GetBannedAreaCount()
    local zones = driftgod.GetBannedAreas()
    local n = 0
    for _, z in ipairs(zones) do
        if z and z.enabled ~= false then n = n + 1 end
    end
    return n
end

function driftgod.GetNoScoreZoneCount()
    return driftgod.GetBannedAreaCount()
end

function driftgod.MarkBannedAreaPosition()
    local pos = get_pos()
    if not pos then
        if driftgod.Toast then driftgod.Toast("Banned marker failed: get in a vehicle or stand there first.", 3000) end
        log_info("Marker failed | no player/vehicle coords")
        return false
    end
    driftgod.S = driftgod.S or {}
    driftgod.S.lastBannedMarker = { x = pos.x, y = pos.y, z = pos.z, ent = pos.ent, time = now_ms() }
    local line = string.format("Marker | X %.3f | Y %.3f | Z %.3f | ent=%s", pos.x, pos.y, pos.z, tostring(pos.ent or 0))
    log_info(line)
    if driftgod.Toast then driftgod.Toast("Banned marker logged: X " .. string.format("%.1f", pos.x) .. " / Y " .. string.format("%.1f", pos.y), 3500) end
    return true
end

function driftgod.AddBannedAreaAtCurrentPosition(name, radius)
    local pos = get_pos()
    if not pos then
        if driftgod.Toast then driftgod.Toast("Banned Area: get in a vehicle or stand in the area first.", 3000) end
        log_info("Add area failed | no player/vehicle coords")
        return false
    end
    local zones = driftgod.GetBannedAreas()
    radius = tonumber(radius or driftgod.S.bannedAreaRadius or driftgod.S.noScoreZoneRadius or 55.0) or 55.0
    if radius < 5.0 then radius = 5.0 end
    if radius > 500.0 then radius = 500.0 end
    local zone = {
        name = clean_name(name or ("Area " .. tostring(#zones + 1))),
        x = pos.x,
        y = pos.y,
        z = pos.z,
        radius = radius,
        enabled = true,
    }
    table.insert(zones, zone)
    driftgod.S.noScoreZones = zones
    driftgod.S.bannedAreaRadius = radius
    driftgod.S.noScoreZoneRadius = radius
    if driftgod.SaveSettings then driftgod.SaveSettings(false) end
    log_info(string.format("Added banned area | %s | X %.3f | Y %.3f | Z %.3f | radius %.1fm", zone.name, zone.x, zone.y, zone.z, zone.radius))
    if driftgod.Toast then driftgod.Toast("Banned area added. Drift score will not count here.", 3500) end
    return true
end

function driftgod.AddNoScoreZoneAtCurrentPosition(name, radius)
    return driftgod.AddBannedAreaAtCurrentPosition(name, radius)
end

function driftgod.RemoveLastBannedArea()
    local zones = driftgod.GetBannedAreas()
    if #zones <= 0 then
        if driftgod.Toast then driftgod.Toast("No banned areas to remove.", 2200) end
        return false
    end
    local removed = table.remove(zones, #zones)
    driftgod.S.noScoreZones = zones
    if driftgod.SaveSettings then driftgod.SaveSettings(false) end
    log_info("Removed banned area | " .. tostring(removed and removed.name or "last"))
    if driftgod.Toast then driftgod.Toast("Removed last banned area.", 2200) end
    return true
end

function driftgod.RemoveLastNoScoreZone()
    return driftgod.RemoveLastBannedArea()
end

function driftgod.ClearBannedAreas()
    driftgod.S.noScoreZones = {}
    if driftgod.SaveSettings then driftgod.SaveSettings(false) end
    log_info("All banned areas cleared")
    if driftgod.Toast then driftgod.Toast("All banned areas cleared.", 2500) end
    return true
end

function driftgod.ClearNoScoreZones()
    return driftgod.ClearBannedAreas()
end

function driftgod.AdjustBannedAreaRadius(delta)
    driftgod.S = driftgod.S or {}
    local r = tonumber(driftgod.S.bannedAreaRadius or driftgod.S.noScoreZoneRadius or 55.0) or 55.0
    r = r + (tonumber(delta or 0) or 0)
    if r < 5.0 then r = 5.0 end
    if r > 500.0 then r = 500.0 end
    driftgod.S.bannedAreaRadius = r
    driftgod.S.noScoreZoneRadius = r
    if driftgod.SaveSettings then driftgod.SaveSettings(false) end
    if driftgod.Toast then driftgod.Toast("Banned radius: " .. tostring(math.floor(r)) .. "m", 1500) end
    return r
end

function driftgod.AdjustNoScoreZoneRadius(delta)
    return driftgod.AdjustBannedAreaRadius(delta)
end

function driftgod.GetActiveBannedArea()
    driftgod.S = driftgod.S or {}
    if driftgod.S.bannedAreasEnabled == false or driftgod.S.noScoreZonesEnabled == false then return nil end
    local zones = driftgod.GetBannedAreas()
    if #zones <= 0 then return nil end
    local pos = get_pos()
    if not pos then return nil end
    for i, z in ipairs(zones) do
        if z and z.enabled ~= false then
            local dx = (pos.x or 0.0) - (tonumber(z.x or 0.0) or 0.0)
            local dy = (pos.y or 0.0) - (tonumber(z.y or 0.0) or 0.0)
            local dz = math.abs((pos.z or 0.0) - (tonumber(z.z or 0.0) or 0.0))
            local r = tonumber(z.radius or driftgod.S.bannedAreaRadius or driftgod.S.noScoreZoneRadius or 55.0) or 55.0
            if (dx * dx + dy * dy) <= (r * r) and dz <= math.max(12.0, r * 0.50) then
                z.index = i
                z.distance = math.sqrt(dx * dx + dy * dy)
                return z
            end
        end
    end
    return nil
end

function driftgod.GetActiveNoScoreZone()
    return driftgod.GetActiveBannedArea()
end

function driftgod.IsInBannedArea()
    return driftgod.GetActiveBannedArea() ~= nil
end

function driftgod.IsInNoScoreZone()
    return driftgod.IsInBannedArea()
end

