local function point_in_polygon(px, py, poly)
    local inside = false
    local j = #poly
    for i = 1, #poly do
        local xi, yi = tonumber(poly[i].x or 0) or 0, tonumber(poly[i].y or 0) or 0
        local xj, yj = tonumber(poly[j].x or 0) or 0, tonumber(poly[j].y or 0) or 0
        local crosses = ((yi > py) ~= (yj > py))
        if crosses then
            local x_at_y = (xj - xi) * (py - yi) / ((yj - yi) + 0.000001) + xi
            if px < x_at_y then inside = not inside end
        end
        j = i
    end
    return inside
end

local function get_preset_flags()
    driftgod.S = driftgod.S or {}
    if type(driftgod.S.presetBannedAreas) ~= "table" then driftgod.S.presetBannedAreas = {} end
    if driftgod.S.lsiaBannedEnabled == true then driftgod.S.presetBannedAreas.lsia = true end
    return driftgod.S.presetBannedAreas
end

function driftgod.GetPresetBannedAreas()
    return PRESET_BANNED_AREAS
end

function driftgod.IsPresetBannedAreaEnabled(id)
    return get_preset_flags()[tostring(id or "")] == true
end

function driftgod.SetPresetBannedAreaEnabled(id, enabled)
    local flags = get_preset_flags()
    id = tostring(id or "")
    flags[id] = enabled == true
    if id == "lsia" then driftgod.S.lsiaBannedEnabled = enabled == true end
    driftgod.S.presetBannedAreas = flags
    if driftgod.SaveSettings then driftgod.SaveSettings(false) end
    return flags[id]
end

function driftgod.SetAllPresetBannedAreas(enabled)
    local flags = get_preset_flags()
    for _, area in ipairs(PRESET_BANNED_AREAS) do
        flags[area.id] = enabled == true
    end
    driftgod.S.lsiaBannedEnabled = enabled == true
    driftgod.S.presetBannedAreas = flags
    if driftgod.SaveSettings then driftgod.SaveSettings(false) end
    if driftgod.Toast then driftgod.Toast((enabled and "Enabled" or "Disabled") .. " all preset banned areas.", 2500) end
end

function driftgod.GetEnabledPresetBannedAreaCount()
    local n = 0
    for _, area in ipairs(PRESET_BANNED_AREAS) do
        if driftgod.IsPresetBannedAreaEnabled(area.id) then n = n + 1 end
    end
    return n
end

function driftgod.GetActivePresetBannedArea()
    driftgod.S = driftgod.S or {}
    if driftgod.S.bannedAreasEnabled == false or driftgod.S.noScoreZonesEnabled == false then return nil end
    local pos = get_pos()
    if not pos then return nil end
    local px, py = tonumber(pos.x or 0) or 0, tonumber(pos.y or 0) or 0
    for _, area in ipairs(PRESET_BANNED_AREAS) do
        if driftgod.IsPresetBannedAreaEnabled(area.id) and point_in_polygon(px, py, area.points or {}) then
            return area
        end
    end
    return nil
end

function driftgod.IsInPresetBannedArea(id)
    if id then
        local pos = get_pos()
        if not pos then return false end
        local px, py = tonumber(pos.x or 0) or 0, tonumber(pos.y or 0) or 0
        for _, area in ipairs(PRESET_BANNED_AREAS) do
            if area.id == id and driftgod.IsPresetBannedAreaEnabled(area.id) then
                return point_in_polygon(px, py, area.points or {})
            end
        end
        return false
    end
    return driftgod.GetActivePresetBannedArea() ~= nil
end

function driftgod.GetOpenBannedPolygon()
    return PRESET_BANNED_AREAS[1].points
end

function driftgod.IsInOpenBannedArea()
    return driftgod.IsInPresetBannedArea and driftgod.IsInPresetBannedArea("lsia") or false
end

function driftgod.GetOpenBannedAreaStatus()
    if driftgod.IsPresetBannedAreaEnabled and driftgod.IsPresetBannedAreaEnabled("lsia") then
        if driftgod.IsInOpenBannedArea and driftgod.IsInOpenBannedArea() then return "Inside Open" end
        return "Enabled"
    end
    return "Disabled"
end

local drive_water_candidates = {
    "Drive On Water",
    "Drive on Water",
    "Drive-On-Water",
    "Drive On Water##Vehicle",
    "Vehicle Drive On Water",
    "Water Drive",
}

function driftgod.GetDriveOnWaterFeature()
    if not FeatureMgr then return nil, nil end
    if FeatureMgr.GetFeatureByName then
        for _, name in ipairs(drive_water_candidates) do
            local ok, feat = driftgod.Try(FeatureMgr.GetFeatureByName, name)
            if ok and feat then return feat, name end
        end
    end
    if FeatureMgr.GetFeature and Utils and Utils.Joaat then
        for _, name in ipairs(drive_water_candidates) do
            local ok, feat = driftgod.Try(FeatureMgr.GetFeature, Utils.Joaat(name))
            if ok and feat then return feat, name end
        end
    end
    return nil, nil
end

function driftgod.IsDriveOnWaterActive()
    driftgod.S = driftgod.S or {}
    if driftgod.S.blockDriveOnWaterScore == false then return false end
    if not driftgod.GetDriveOnWaterFeature then return false end
    local feat, name = driftgod.GetDriveOnWaterFeature()
    if feat and feat.IsToggled then
        local ok, toggled = driftgod.Try(function() return feat:IsToggled() end)
        if ok and toggled == true then
            driftgod.S.driveOnWaterFeatureName = name or "Drive On Water"
            return true
        end
    end
    return false
end

function driftgod.GetBannedScoreBlockReason()
    local presetArea = driftgod.GetActivePresetBannedArea and driftgod.GetActivePresetBannedArea() or nil
    if presetArea then
        return "BANNED AREA", tostring(presetArea.name or "Preset Banned Area"), presetArea
    end
    local zone = driftgod.GetActiveBannedArea and driftgod.GetActiveBannedArea() or nil
    if zone then
        return "BANNED AREA", tostring(zone.name or "Banned Area"), zone
    end
    if driftgod.IsDriveOnWaterActive and driftgod.IsDriveOnWaterActive() then
        return "DRIVE ON WATER", "Drive On Water is enabled", nil
    end
    return nil, nil, nil
end

function driftgod.HandleBannedScoreBlockedPoints(amount)
    local code, label, zone = driftgod.GetBannedScoreBlockReason()
    if not code then return false end
    local now = now_ms()
    driftgod.S.bannedAreaLastName = label
    driftgod.S.noScoreZoneLastName = label
    driftgod.S.noScoreZoneActiveUntil = now + 1200
    driftgod.S.hudVisibleUntil = now + (driftgod.S.hudFadeAfterMs or 3500)
    driftgod.S.hudAlpha = 255
    if not driftgod.S.bannedLastWarnAt or (now - driftgod.S.bannedLastWarnAt) > 240000 then
        driftgod.S.bannedLastWarnAt = now
        if driftgod.AddBonusPopup then
            if code == "BANNED AREA" then
                driftgod.AddBonusPopup("This area is banned in DriftGod's Point System!", 255, 90, 90)
            else
                driftgod.AddBonusPopup(code, 255, 90, 90)
            end
        end
        if driftgod.Toast then
            if code == "BANNED AREA" then
                driftgod.Toast("This area is banned in DriftGod's Point System!", 3200)
            else
                driftgod.Toast("This will not count toward drifting.", 3200)
            end
        end
        log_info("Blocked score | " .. tostring(code) .. " | " .. tostring(label) .. " | amount=" .. tostring(math.floor(amount or 0)))
    end
    return true
end

function driftgod.HandleNoScoreZoneBlockedPoints(amount)
    return driftgod.HandleBannedScoreBlockedPoints(amount)
end

function driftgod.InstallNoScoreZones()
    driftgod.S = driftgod.S or {}

    driftgod.S.bannedAreasEnabled = true
    driftgod.S.noScoreZonesEnabled = true
    if driftgod.S.bannedAreaRadius == nil then driftgod.S.bannedAreaRadius = driftgod.S.noScoreZoneRadius or 55.0 end
    if driftgod.S.noScoreZoneRadius == nil then driftgod.S.noScoreZoneRadius = driftgod.S.bannedAreaRadius or 55.0 end
    if driftgod.S.blockDriveOnWaterScore == nil then driftgod.S.blockDriveOnWaterScore = true end
    if type(driftgod.S.noScoreZones) ~= "table" then driftgod.S.noScoreZones = {} end

    driftgod.S.presetBannedAreas = type(driftgod.S.presetBannedAreas) == "table" and driftgod.S.presetBannedAreas or {}
    if type(PRESET_BANNED_AREAS) == "table" then
        for _, area in ipairs(PRESET_BANNED_AREAS) do
            if area and area.id then driftgod.S.presetBannedAreas[area.id] = true end
        end
    end
    driftgod.S.lsiaBannedEnabled = true
end

return driftgod.NoScoreZones
end

