local function milestoneLog(msg, force)
    msg = tostring(msg or "")
    local lower = msg:lower()
    local important = force == true
        or lower:find("error", 1, true) ~= nil
        or lower:find("failed", 1, true) ~= nil
        or lower:find("warning", 1, true) ~= nil

    if not important and driftgod.S and driftgod.S.progressMilestoneDebugEnabled ~= true then return end

    if driftgod.Log then
        driftgod.Log("[Milestones] " .. msg)
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] [Milestones] " .. msg)
    elseif log then
        log("[DriftGod] [Milestones] " .. msg)
    end
end

