    driftgod.S.progressMilestonesCompleted = driftgod.S.progressMilestonesCompleted or {}
    driftgod.S.progressMilestonePoints = tonumber(driftgod.S.progressMilestonePoints or 0) or 0
    driftgod.S.progressMilestoneLastCompleted = driftgod.S.progressMilestoneLastCompleted or ""
