    if driftgod.S and type(driftgod.S.vehicleMastery) == "table" then
        for _, record in pairs(driftgod.S.vehicleMastery) do
            local lvl = tonumber(record.masteryLevel or 1) or 1
            if lvl > highest then highest = lvl end
