            if done == true then count = count + 1 end
        end
    elseif driftgod.S and type(driftgod.S.stuntUnlockNotified) == "table" then
        for _, done in pairs(driftgod.S.stuntUnlockNotified) do
            if done == true then count = count + 1 end
        end
    end

    return count
end

