function driftgod.GetProgressMilestoneById(id)
    for _, milestone in ipairs(driftgod.ProgressMilestoneList or {}) do
        if milestone.id == id then return milestone end
    end
    return nil
end

function driftgod.CompleteProgressMilestone(milestone, reason)
    driftgod.ProgressMilestonesEnsureDefaults()
    if not milestone or not milestone.id then return false end

    if driftgod.S.progressMilestonesCompleted[milestone.id] == true then return false end

    driftgod.S.progressMilestonesCompleted[milestone.id] = true
    driftgod.S.progressMilestonePoints = (tonumber(driftgod.S.progressMilestonePoints or 0) or 0) + (tonumber(milestone.points or 1) or 1)
    driftgod.S.progressMilestoneLastCompleted = milestone.id
    driftgod.S.progressMilestoneTitle = driftgod.GetProgressMilestoneTitleByPoints and driftgod.GetProgressMilestoneTitleByPoints(driftgod.S.progressMilestonePoints) or driftgod.S.progressMilestoneTitle

    toast("MILESTONE COMPLETE: " .. tostring(milestone.title or milestone.id), 3500)

    milestoneLog("MILESTONE COMPLETE: " .. tostring(milestone.title or milestone.id)
        .. " | +" .. tostring(milestone.points or 1)
        .. " MP | totalMP=" .. tostring(driftgod.S.progressMilestonePoints)
        .. " | title=" .. tostring(driftgod.S.progressMilestoneTitle)
        .. " | reason=" .. tostring(reason or "check"), true)

    if driftgod.SaveProgress then driftgod.SaveProgress(false) end
    return true
end

function driftgod.CheckProgressMilestones(reason)
    driftgod.ProgressMilestonesEnsureDefaults()
    if driftgod.S.progressMilestonesEnabled == false then return end

    for _, milestone in ipairs(driftgod.ProgressMilestoneList or {}) do
        if milestone and milestone.id and driftgod.S.progressMilestonesCompleted[milestone.id] ~= true then
            local ok = false
            if type(milestone.check) == "function" then
                local success, result = driftgod.Try(milestone.check)
                ok = success and result == true
            end

            if ok then
                driftgod.CompleteProgressMilestone(milestone, reason or "check")
            end
        end
    end
end

function driftgod.ProgressMilestoneSnapshot(reason)
    driftgod.ProgressMilestonesEnsureDefaults()

    local completed = 0
    for _, done in pairs(driftgod.S.progressMilestonesCompleted or {}) do
        if done == true then completed = completed + 1 end
    end

    milestoneLog("Snapshot | reason=" .. tostring(reason or "manual")
        .. " | completed=" .. tostring(completed) .. "/" .. tostring(#(driftgod.ProgressMilestoneList or {}))
        .. " | MP=" .. tostring(driftgod.S.progressMilestonePoints or 0)
        .. " | title=" .. tostring(driftgod.S.progressMilestoneTitle or "")
        .. " | overall=" .. tostring(driftgod.S.overallScore or 0)
        .. " | challenges=" .. tostring(driftgod.CountCompletedSessionChallenges and driftgod.CountCompletedSessionChallenges() or 0)
        .. " | vehicleHighest=" .. tostring(driftgod.GetHighestVehicleMasteryLevel and driftgod.GetHighestVehicleMasteryLevel() or 1), true)
end

function driftgod.InstallProgressMilestones(source)
    driftgod.ProgressMilestonesEnsureDefaults()

    if driftgod.ProgressMilestones.installed == true then
        return true
    end

    driftgod.ProgressMilestones.installed = true
    driftgod.ProgressMilestones.source = tostring(source or "unknown")

    if type(driftgod.ExportProgress) == "function" then
        local oldExportProgress = driftgod.ExportProgress
        driftgod.ExportProgress = function()
            local t = oldExportProgress() or {}
            t.progressMilestonesCompleted = driftgod.S.progressMilestonesCompleted or {}
            t.progressMilestonePoints = tonumber(driftgod.S.progressMilestonePoints or 0) or 0
            t.progressMilestoneLastCompleted = driftgod.S.progressMilestoneLastCompleted or ""
            t.progressMilestoneTitle = driftgod.S.progressMilestoneTitle or "Drift Initiate"
            return t
        end
    else
        milestoneLog("Warning: driftgod.ExportProgress missing during milestone install", true)
    end

    if type(driftgod.ApplyProgress) == "function" then
        local oldApplyProgress = driftgod.ApplyProgress
        driftgod.ApplyProgress = function(t)
            local result = oldApplyProgress(t)

            if type(t) == "table" then
                if type(t.progressMilestonesCompleted) == "table" then
                    driftgod.S.progressMilestonesCompleted = t.progressMilestonesCompleted
                end

                driftgod.S.progressMilestonePoints = tonumber(t.progressMilestonePoints or driftgod.S.progressMilestonePoints or 0) or 0
                driftgod.S.progressMilestoneLastCompleted = tostring(t.progressMilestoneLastCompleted or driftgod.S.progressMilestoneLastCompleted or "")
                driftgod.S.progressMilestoneTitle = tostring(t.progressMilestoneTitle or driftgod.S.progressMilestoneTitle or "Drift Initiate")
            end

            driftgod.ProgressMilestonesEnsureDefaults()
            return result
        end
    else
        milestoneLog("Warning: driftgod.ApplyProgress missing during milestone install", true)
    end

    if driftgod.LoadProgress and driftgod.ProgressMilestones.reloadedAfterInstall ~= true then
        driftgod.ProgressMilestones.reloadedAfterInstall = true
        driftgod.Try(function() driftgod.LoadProgress(false) end)
    end

    if driftgod.CheckProgressMilestones then driftgod.CheckProgressMilestones("install") end

    milestoneLog("Installed progress milestones | source=" .. tostring(source or "unknown"))
    return true
end

return DG
end

__DG_BUNDLE_LOADERS["systems.progress_persistence"] = function()
DG = DG or {}

driftgod.ProgressPersistence = driftgod.ProgressPersistence or {}

local function nowMs()
    if driftgod.Now then return tonumber(driftgod.Now() or 0) or 0 end
    if driftgod.GetMs then return tonumber(driftgod.GetMs() or 0) or 0 end
    return 0
end

local function safeLog(msg, force)
    msg = tostring(msg or "")

    local lower = msg:lower()

    local important = lower:find("error", 1, true) ~= nil
        or lower:find("failed", 1, true) ~= nil
        or lower:find("warning", 1, true) ~= nil
        or (force == true and driftgod.S and driftgod.S.progressForceVerbose == true)

    if not important and not (driftgod.S and driftgod.S.progressDebugEnabled == true) then return end

    if driftgod.Log then
        driftgod.Log("[ProgressDebug] " .. msg)
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] [ProgressDebug] " .. msg)
    elseif log then
        log("[DriftGod] [ProgressDebug] " .. msg)
    end
end

function driftgod.ProgressLog(msg)
    safeLog(msg)
end

local function tableCopyInto(dst, src)
    if type(dst) ~= "table" then dst = {} end
    if type(src) ~= "table" then return dst end

    for k, v in pairs(src) do
        dst[k] = v
    end

    return dst
end

function driftgod.ProgressPersistenceEnsureDefaults()
    driftgod.S = driftgod.S or {}

    driftgod.S.progressPersistenceEnabled = driftgod.S.progressPersistenceEnabled ~= false
    driftgod.S.progressDebugEnabled = driftgod.S.progressDebugEnabled == true
    driftgod.S.overallScoreEnabled = driftgod.S.overallScoreEnabled ~= false
    driftgod.S.overallScoreAutoBankEnabled = driftgod.S.overallScoreAutoBankEnabled ~= false

    driftgod.S.overallScore = tonumber(driftgod.S.overallScore or 0) or 0
    driftgod.S.overallScoreBankedRuns = tonumber(driftgod.S.overallScoreBankedRuns or 0) or 0
    driftgod.S.overallScoreLastBankedRun = tonumber(driftgod.S.overallScoreLastBankedRun or 0) or 0
    driftgod.S.overallScoreLastBankedAt = tonumber(driftgod.S.overallScoreLastBankedAt or 0) or 0

    driftgod.S.progressPersistenceLastBankScore = tonumber(driftgod.S.progressPersistenceLastBankScore or 0) or 0
    driftgod.S.progressPersistenceLastBankAt = tonumber(driftgod.S.progressPersistenceLastBankAt or 0) or 0

    driftgod.S.stuntUpgradeEarnedTiers = driftgod.S.stuntUpgradeEarnedTiers or {}
    driftgod.S.stuntUpgradeAnnouncedTiers = driftgod.S.stuntUpgradeAnnouncedTiers or {}

    driftgod.S.progressPersistenceInstalled = true
    driftgod.S.progressPersistenceLoadVerified = driftgod.S.progressPersistenceLoadVerified or false
end

function driftgod.GetLiveRunScoreForOverall()
    local best = 0

    if driftgod.S then
        local candidates = {
            driftgod.S.currentScore,
            driftgod.S.score,
            driftgod.S.sessionScore,
            driftgod.S.driftScore,
            driftgod.S.points,
            driftgod.S.previousScore,
            driftgod.S.lastRunScore,
            driftgod.S.lastScore,
        }

        for _, value in ipairs(candidates) do
            local n = tonumber(value)
            if n and n > best then best = n end
        end
    end

    return math.floor(math.max(0, best))
end

function driftgod.BankOverallScoreValue(runScore, reason)
    driftgod.ProgressPersistenceEnsureDefaults()

    if not (driftgod.S and driftgod.S.overallScoreEnabled) then return false end

    runScore = math.floor(tonumber(runScore or 0) or 0)
    if runScore <= 0 then
        safeLog("Bank skipped: runScore <= 0 | reason=" .. tostring(reason or "unknown"))
        return false
    end

    local now = nowMs()
    local lastScore = tonumber(driftgod.S.progressPersistenceLastBankScore or 0) or 0
    local lastAt = tonumber(driftgod.S.progressPersistenceLastBankAt or 0) or 0

    if lastScore == runScore and lastAt > 0 and (now - lastAt) < 2500 then
        safeLog("Bank skipped: duplicate guard | score=" .. tostring(runScore) .. " | deltaMs=" .. tostring(now - lastAt))
        return false
    end

    driftgod.S.overallScore = math.floor((tonumber(driftgod.S.overallScore or 0) or 0) + runScore)
    driftgod.S.overallScoreLastBankedRun = runScore
    driftgod.S.overallScoreBankedRuns = (tonumber(driftgod.S.overallScoreBankedRuns or 0) or 0) + 1
    driftgod.S.overallScoreLastBankedAt = now
    driftgod.S.progressPersistenceLastBankScore = runScore
    driftgod.S.progressPersistenceLastBankAt = now

    safeLog("BANKED +" .. tostring(runScore)
        .. " | Overall Score=" .. tostring(driftgod.S.overallScore)
        .. " | Banked Runs=" .. tostring(driftgod.S.overallScoreBankedRuns)
        .. " | reason=" .. tostring(reason or "run ended"))

    if driftgod.SaveProgress then driftgod.SaveProgress(false) end
    return true
end

function driftgod.BankOverallScoreFromRun(reason)
    local score = driftgod.GetLiveRunScoreForOverall and driftgod.GetLiveRunScoreForOverall() or 0
    return driftgod.BankOverallScoreValue(score, reason or "manual/current run")
end

function driftgod.ProgressPersistenceSnapshot(reason)
    driftgod.ProgressPersistenceEnsureDefaults()

    safeLog("Snapshot | reason=" .. tostring(reason or "manual")
        .. " | live=" .. tostring(driftgod.GetLiveRunScoreForOverall and driftgod.GetLiveRunScoreForOverall() or 0)
        .. " | previous=" .. tostring(driftgod.S.previousScore or 0)
        .. " | best=" .. tostring(driftgod.S.bestScore or 0)
        .. " | overall=" .. tostring(driftgod.S.overallScore or 0)
        .. " | bankedRuns=" .. tostring(driftgod.S.overallScoreBankedRuns or 0)
        .. " | earnedTierCount=" .. tostring(type(driftgod.S.stuntUpgradeEarnedTiers) == "table" and #driftgod.S.stuntUpgradeEarnedTiers or 0), true)
end

function driftgod.InstallProgressPersistence(source)
    driftgod.ProgressPersistenceEnsureDefaults()

    if driftgod.ProgressPersistence.installed == true then
        safeLog("Install skipped; already installed | source=" .. tostring(source or "unknown"))
        return true
    end

    driftgod.ProgressPersistence.installed = true
    driftgod.ProgressPersistence.source = tostring(source or "unknown")

    if type(driftgod.ExportProgress) == "function" then
        local oldExportProgress = driftgod.ExportProgress
        driftgod.ExportProgress = function()
            local t = oldExportProgress() or {}

            t.overallScore = tonumber(driftgod.S.overallScore or 0) or 0
            t.overallScoreBankedRuns = tonumber(driftgod.S.overallScoreBankedRuns or 0) or 0
            t.overallScoreLastBankedRun = tonumber(driftgod.S.overallScoreLastBankedRun or 0) or 0
            t.overallScoreLastBankedAt = tonumber(driftgod.S.overallScoreLastBankedAt or 0) or 0

            if driftgod.NormalizeStuntTierPersistence then driftgod.NormalizeStuntTierPersistence("progress export") end
            t.stuntUpgradeEarnedTiers = driftgod.S.stuntUpgradeEarnedTiers or {}
            t.stuntUpgradeAnnouncedTiers = driftgod.S.stuntUpgradeAnnouncedTiers or {}
            t.stuntTierFreshUseCounts = driftgod.S.stuntTierFreshUseCounts or {}
            t.stuntUseRunCounts = driftgod.S.stuntUseRunCounts or {}
            t.stuntUnlockLastHighest = driftgod.S.stuntUnlockLastHighest or ""
            t.stuntTierPersistenceVersion = "A29"

            return t
        end
    else
        safeLog("Warning: driftgod.ExportProgress missing during install", true)
    end

    if type(driftgod.ApplyProgress) == "function" then
        local oldApplyProgress = driftgod.ApplyProgress
        driftgod.ApplyProgress = function(t)
            local result = oldApplyProgress(t)

            if type(t) == "table" then

                driftgod.S.overallScore = tonumber(t.overallScore ~= nil and t.overallScore or driftgod.S.overallScore or 0) or 0
                driftgod.S.overallScoreBankedRuns = tonumber(t.overallScoreBankedRuns ~= nil and t.overallScoreBankedRuns or driftgod.S.overallScoreBankedRuns or 0) or 0
                driftgod.S.overallScoreLastBankedRun = tonumber(t.overallScoreLastBankedRun ~= nil and t.overallScoreLastBankedRun or driftgod.S.overallScoreLastBankedRun or 0) or 0
                driftgod.S.overallScoreLastBankedAt = tonumber(t.overallScoreLastBankedAt ~= nil and t.overallScoreLastBankedAt or driftgod.S.overallScoreLastBankedAt or 0) or 0

                if type(t.stuntUpgradeEarnedTiers) == "table" then driftgod.S.stuntUpgradeEarnedTiers = t.stuntUpgradeEarnedTiers end
                if type(t.stuntUpgradeAnnouncedTiers) == "table" then driftgod.S.stuntUpgradeAnnouncedTiers = t.stuntUpgradeAnnouncedTiers end
                if type(t.stuntTierFreshUseCounts) == "table" then driftgod.S.stuntTierFreshUseCounts = t.stuntTierFreshUseCounts end
                if type(t.stuntUseRunCounts) == "table" then driftgod.S.stuntUseRunCounts = t.stuntUseRunCounts end
                if driftgod.ApplyLoadedStuntTierProgress then driftgod.ApplyLoadedStuntTierProgress(t, "progress persistence ApplyProgress") end
            end

            driftgod.ProgressPersistenceEnsureDefaults()
            driftgod.S.progressPersistenceLoadVerified = true
            safeLog("Applied progress | Overall Score=" .. tostring(driftgod.S.overallScore or 0)
                .. " | Banked Runs=" .. tostring(driftgod.S.overallScoreBankedRuns or 0))

            return result
        end
    else
        safeLog("Warning: driftgod.ApplyProgress missing during install", true)
    end

    if type(driftgod.SaveProgress) == "function" then
        local oldSaveProgress = driftgod.SaveProgress
        driftgod.SaveProgress = function(showToast)
            if driftgod.NormalizeStuntTierPersistence then driftgod.NormalizeStuntTierPersistence("A38 SaveProgress wrapper") end
            local result = oldSaveProgress(showToast)
            safeLog("Saved progress | file=" .. tostring(driftgod.ProgressFile or "unknown")
                .. " | Overall Score=" .. tostring(driftgod.S and driftgod.S.overallScore or 0))
            return result
        end
    else
        safeLog("Warning: driftgod.SaveProgress missing during install", true)
    end

    if type(driftgod.LoadProgress) == "function" then
        local oldLoadProgress = driftgod.LoadProgress
        driftgod.LoadProgress = function(showToast)
            local result = oldLoadProgress(showToast)
            safeLog("LoadProgress result=" .. tostring(result)
                .. " | file=" .. tostring(driftgod.ProgressFile or "unknown")
                .. " | Overall Score=" .. tostring(driftgod.S and driftgod.S.overallScore or 0))
            return result
        end
    else
        safeLog("Warning: driftgod.LoadProgress missing during install", true)
    end

    if type(driftgod.FinishRun) == "function" then
        local oldFinishRun = driftgod.FinishRun
        driftgod.FinishRun = function(reason)
            local finalScore = math.floor(tonumber(driftgod.S and driftgod.S.currentScore or 0) or 0)
            safeLog("FinishRun hook | reason=" .. tostring(reason or "Run Ended") .. " | finalScore=" .. tostring(finalScore))

            local result = oldFinishRun(reason)

            if finalScore > 0 then
                driftgod.BankOverallScoreValue(finalScore, "FinishRun: " .. tostring(reason or "Run Ended"))
                if driftgod.SaveProgressHard then driftgod.SaveProgressHard("FinishRun wrapper") end
            else
                safeLog("FinishRun hook skipped bank: finalScore <= 0")
            end

            return result
        end
    else
        safeLog("Warning: driftgod.FinishRun missing during install; auto-bank will wait for scoring module", true)
    end

    if driftgod.LoadProgress and driftgod.ProgressPersistence.reloadedAfterInstall ~= true then
        driftgod.ProgressPersistence.reloadedAfterInstall = true
        driftgod.Try(function()
            driftgod.LoadProgress(false)
        end)
    end

    safeLog("Installed progress persistence module | source=" .. tostring(source or "unknown"))
    return true
end

local function dg_a38_count_keys(t)
    local n = 0
    if type(t) == "table" then for _ in pairs(t) do n = n + 1 end end
    return n
end

local function dg_a38_donut_tier()
    local tiers = driftgod.S and driftgod.S.stuntUpgradeEarnedTiers or nil
    if type(tiers) ~= "table" then return 1 end
    return tonumber(tiers.Donut or tiers.donut or tiers["Donut"] or 1) or 1
end

function driftgod.SaveProgressHard(reason)
    if driftgod._savingProgressNow == true then return false end
    driftgod._savingProgressNow = true
    reason = tostring(reason or "manual")
    if driftgod.NormalizeStuntTierPersistence then driftgod.NormalizeStuntTierPersistence("A38 hard save: " .. reason) end
    if driftgod.ForceCheckStuntProgression then driftgod.ForceCheckStuntProgression("A38 hard save: " .. reason) end

    local ok = false
    if driftgod.SaveProgress then
        ok = driftgod.SaveProgress(false) ~= false
    end

    if ok and driftgod.ProgressFile and driftgod.ExportProgress and driftgod.SaveTable then
        local backup = tostring(driftgod.ProgressFile) .. ".bak"
        driftgod.SaveTable(backup, driftgod.ExportProgress())
    end

    safeLog("A38 hard save | reason=" .. reason
        .. " | ok=" .. tostring(ok)
        .. " | best=" .. tostring(driftgod.S and driftgod.S.bestScore or 0)
        .. " | tierKeys=" .. tostring(dg_a38_count_keys(driftgod.S and driftgod.S.stuntUpgradeEarnedTiers or nil))
        .. " | donut=" .. tostring(dg_a38_donut_tier()), true)
    driftgod._savingProgressNow = false
    return ok
end

function driftgod.ColdBootProgressSync(reason)
    reason = tostring(reason or "cold-boot")
    if driftgod.LoadProgress then driftgod.LoadProgress(false) end
    if driftgod.ApplyLoadedStuntTierProgress then driftgod.ApplyLoadedStuntTierProgress(driftgod.S or {}, "A38 cold boot sync: " .. reason) end
    if driftgod.NormalizeStuntTierPersistence then driftgod.NormalizeStuntTierPersistence("A38 cold boot sync: " .. reason) end

    safeLog("A38 cold boot sync | reason=" .. reason
        .. " | best=" .. tostring(driftgod.S and driftgod.S.bestScore or 0)
        .. " | previous=" .. tostring(driftgod.S and driftgod.S.previousScore or 0)
        .. " | tierKeys=" .. tostring(dg_a38_count_keys(driftgod.S and driftgod.S.stuntUpgradeEarnedTiers or nil))
        .. " | donut=" .. tostring(dg_a38_donut_tier()), true)
    return true
end

return DG
end

__DG_BUNDLE_LOADERS["systems.progression"] = function()
DG = DG or {}
function driftgod.ScoreForUnlock() return math.max(driftgod.S.bestScore or 0, driftgod.S.currentScore or 0) end
function driftgod.GetUnlockedDriftLevel()
    if not driftgod.S.progressUnlocksEnabled then return 5 end
