end
function driftgod.GetUnlockedAutoCounterSteerLevel()
    if not driftgod.S.progressUnlocksEnabled then return 5 end
    local score = driftgod.ScoreForUnlock()
    if score >= 18000 then return 5 elseif score >= 12000 then return 4 elseif score >= 3000 then return 3 elseif score >= 1200 then return 2 end
    return 1
end
function driftgod.GetUnlockedMomentumLevel()
    if not driftgod.S.progressUnlocksEnabled then return 5 end
    local score = driftgod.ScoreForUnlock()
    if score >= 22500 then return 5 elseif score >= 15000 then return 4 elseif score >= 4500 then return 3 elseif score >= 1500 then return 2 end
    return 1
end
function driftgod.GetUnlockedAccelLevel()
    if not driftgod.S.progressUnlocksEnabled then return 5 end
    local score = driftgod.ScoreForUnlock()
    if score >= 45000 then return 5 elseif score >= 30000 then return 4 elseif score >= 10500 then return 3 elseif score >= 2250 then return 2 end
    return 1
