function driftgod.ApplyProgressStarterSettings()
    driftgod.S.driftGripLevel = 1; driftgod.S.driftStabilityLevel = 1; driftgod.S.autoCounterSteerEnabled = true; driftgod.S.autoCounterSteerLevel = 1; driftgod.S.momentumAssistEnabled = false; driftgod.S.momentumStrength = 1; driftgod.S.accelAssistEnabled = false; driftgod.S.accelStrength = 3
    driftgod.Toast("Progress Mode enabled: starter settings applied.", 3500)
end
function driftgod.CheckUnlocks()
    if not driftgod.S.progressUnlocksEnabled then return end
    local score = driftgod.ScoreForUnlock()
    for _, unlock in ipairs(driftgod.Unlocks or {}) do
        if score >= unlock.score and driftgod.S.notifiedUnlocks[unlock.id] ~= true then
            driftgod.S.notifiedUnlocks[unlock.id] = true
            driftgod.S.unlockedRewards[unlock.id] = true
            driftgod.S.lastRunEndMessage = "CONGRATULATIONS!"
            driftgod.S.lastRunEndUntil = driftgod.Now() + 3500
            driftgod.AddBonusPopup("UNLOCKED: " .. unlock.text, 255, 220, 120)
            driftgod.Toast("CONGRATULATIONS! You unlocked " .. unlock.text .. " in DriftGod!", 6000)
            driftgod.SaveProgress(false)
        end
    end
end
return DG
end

__DG_BUNDLE_LOADERS["systems.rival_system"] = function()
DG = DG or {}
function driftgod.GetActiveRival()
    local score = driftgod.ScoreForUnlock and driftgod.ScoreForUnlock() or math.max(driftgod.S.bestScore or 0, driftgod.S.currentScore or 0)
    for _, rival in ipairs(driftgod.Rivals or {}) do if score < rival.target then return rival end end
    return (driftgod.Rivals or {})[#(driftgod.Rivals or {})]
end
function driftgod.UpdateActiveRival()
    local rival = driftgod.GetActiveRival()
    if not rival then return end
    driftgod.S.rivalName = rival.name
    driftgod.S.rivalTargetScore = rival.target
    for i, entry in ipairs(driftgod.Rivals or {}) do if entry.id == rival.id then driftgod.S.rivalIndex = i break end end
end
function driftgod.CheckRivalBeaten()
    if not driftgod.S.rivalEnabled then return end
    local displayScore = math.floor(driftgod.S.currentScore or 0)
    local rival = driftgod.GetActiveRival()
    if rival and displayScore >= rival.target and driftgod.S.beatenRivals[rival.id] ~= true then
        driftgod.S.beatenRivals[rival.id] = true
        driftgod.AddBonusPopup("RIVAL BEATEN: " .. rival.name, 255, 220, 120)
        driftgod.Toast("You beat " .. rival.name .. "! Next rival unlocked.", 5000)
        driftgod.SaveProgress(false)
        driftgod.UpdateActiveRival()
    end
end
return DG
end

__DG_BUNDLE_LOADERS["systems.rivals"] = function()

DG = DG or {}
driftgod.S = driftgod.S or {}

driftgod.S.beatenRivals = driftgod.S.beatenRivals or {}
driftgod.S.rivalEnabled = driftgod.S.rivalEnabled ~= false

local function rivalScore()
    return math.max(math.floor(driftgod.S.bestScore or 0), math.floor(driftgod.S.currentScore or 0))
end

function driftgod.GetActiveRival()
    local score = rivalScore()

    for _, rival in ipairs(driftgod.Rivals or {}) do
        if score < (rival.target or 0) then
            return rival
        end
    end

    if driftgod.Rivals and #driftgod.Rivals > 0 then return driftgod.Rivals[#driftgod.Rivals] end
    return { id = "none", name = "None", target = 0 }
end

function driftgod.UpdateActiveRival(showToast)
    if not driftgod.S.rivalEnabled then
        driftgod.S.rivalName = "Disabled"
        driftgod.S.rivalTargetScore = 0
        return
    end

    local oldName = driftgod.S.rivalName
    local rival = driftgod.GetActiveRival()

    driftgod.S.rivalName = rival.name or "None"
    driftgod.S.rivalTargetScore = rival.target or 0

    for i, entry in ipairs(driftgod.Rivals or {}) do
        if entry.id == rival.id then
            driftgod.S.rivalIndex = i
            break
        end
    end

    if showToast and oldName and oldName ~= driftgod.S.rivalName and driftgod.Toast then
        driftgod.Toast("Next Rival: " .. tostring(driftgod.S.rivalName) .. " / " .. tostring(driftgod.S.rivalTargetScore), 3500)
    end
end

function driftgod.CheckRivalBeaten()
    if not driftgod.S.rivalEnabled then return end

    local score = rivalScore()

    for _, rival in ipairs(driftgod.Rivals or {}) do
        if score >= (rival.target or 0) and driftgod.S.beatenRivals[rival.id] ~= true then
            driftgod.S.beatenRivals[rival.id] = true

            if driftgod.AddBonusPopup then
                driftgod.AddBonusPopup("RIVAL BEATEN: " .. tostring(rival.name), 255, 220, 120)
            end

            if driftgod.Toast then
                driftgod.Toast("You beat " .. tostring(rival.name) .. "! Next rival unlocked.", 4500)
            end
        end
    end

    driftgod.UpdateActiveRival(false)
end

function driftgod.RivalTick()
    if not driftgod.S.rivalEnabled then return end
    driftgod.CheckRivalBeaten()
    driftgod.UpdateActiveRival(false)
end

driftgod.UpdateActiveRival(false)

return DG
end

__DG_BUNDLE_LOADERS["systems.scoring"] = function()

local function dgScoreGetMphSafe()
    local mph = 0
    driftgod.Try(function()
        if driftgod.GetSpeedMph then mph = driftgod.GetSpeedMph()
        elseif driftgod.S and driftgod.S.currentMph then mph = driftgod.S.currentMph end
    end)
    return tonumber(mph or 0) or 0
end

function driftgod.ShouldIgnoreMinorStuntScrape(reason)
    if driftgod.S.stuntLandingGraceEnabled == true and driftgod.IsStuntLandingGraceActive and driftgod.IsStuntLandingGraceActive() then
        return true, "landing grace active"
    end

    if driftgod.S.stuntMinorScrapeGraceEnabled == true then
        local mph = dgScoreGetMphSafe()
        local limit = tonumber(driftgod.S.stuntMinorScrapeSpeedMph or 18) or 18
        if mph <= limit then
            return true, "minor scrape under mph threshold"
        end
    end

    return false, reason or "not ignored"
end

DG = DG or {}

function driftgod.SortHighScores()
    table.sort(driftgod.S.highScores, function(a, b) return (a.score or 0) > (b.score or 0) end)
    while #driftgod.S.highScores > 5 do table.remove(driftgod.S.highScores, #driftgod.S.highScores) end
end

function driftgod.AddHighScore(score, label)
    score = math.floor(score or 0)
    if score <= 0 then return false end
    table.insert(driftgod.S.highScores, { score = score, combo = driftgod.S.currentRunBestCombo, label = label or "Run", rank = driftgod.GetRank(score), date = driftgod.DateString(), longest = driftgod.S.longestDriftMs })
    driftgod.SortHighScores()
    return true
end

function driftgod.ResetRunStats()
    driftgod.S.currentScore = 0.0
    driftgod.S.activeDriftMs = 0
    driftgod.S.validDriftWatchMs = 0
    driftgod.S.longestDriftMs = 0
    driftgod.S.runActive = false
    driftgod.S.crashWatchMs = 0
    driftgod.S.slideOutWatchMs = 0
    driftgod.S.stoppedWatchMs = 0
    driftgod.S.comboMultiplier = 1
    driftgod.S.cleanStuntChain = 0
    driftgod.S.landedStuntsThisRun = 0
    driftgod.S.currentRunBestCombo = 1
    driftgod.S.comboGraceUntil = 0
end

function driftgod.FinishRun(reason)

    if reason and tostring(reason):lower():find("collision", 1, true) and driftgod.MarkSessionChallengeCollision then driftgod.MarkSessionChallengeCollision(reason) end
local finalScore = math.floor(driftgod.S.currentScore or 0)
    if finalScore <= 0 then driftgod.ResetRunStats() return end
    driftgod.S.previousScore = finalScore
    if driftgod.UpdateTodayBest then driftgod.UpdateTodayBest(finalScore) end
    local wasNewBest = false
    if finalScore > driftgod.S.bestScore then driftgod.S.bestScore = finalScore wasNewBest = true end
    if driftgod.S.currentRunBestCombo > driftgod.S.bestCombo then driftgod.S.bestCombo = driftgod.S.currentRunBestCombo end
    driftgod.AddHighScore(finalScore, reason or "Run Ended")

    driftgod.S.lastRunScore = finalScore
    driftgod.S.progressScore = math.max(tonumber(driftgod.S.progressScore or 0) or 0, finalScore)
    driftgod.S.lifetimeScore = math.max(tonumber(driftgod.S.lifetimeScore or 0) or 0, finalScore)
    driftgod.S.totalScore = math.max(tonumber(driftgod.S.totalScore or 0) or 0, finalScore)
    if driftgod.CheckUnlocks then driftgod.CheckUnlocks() end
    if driftgod.ForceCheckStuntProgression then driftgod.ForceCheckStuntProgression("FinishRun") end
    if driftgod.CheckRivalBeaten then driftgod.CheckRivalBeaten() end
    if wasNewBest then
        driftgod.S.lastRunEndMessage = "NEW HIGH SCORE - " .. driftgod.GetRank(finalScore)
        driftgod.AddBonusPopup("NEW HIGH SCORE", 255, 220, 120)
    else
        driftgod.S.lastRunEndMessage = "RUN SAVED - " .. tostring(finalScore)
    end
    driftgod.S.lastRunEndUntil = driftgod.Now() + 3500
    driftgod.S.hudVisibleUntil = driftgod.Now() + driftgod.S.hudFadeAfterMs
    driftgod.S.hudAlpha = 255
    if driftgod.SaveProgressHard then driftgod.SaveProgressHard("FinishRun direct") else driftgod.SaveProgress(false) end
    driftgod.ResetRunStats()
    if driftgod.UpdateActiveRival then driftgod.UpdateActiveRival() end
end

function driftgod.StopRun(reason, popupText, toastText)
    if not driftgod.S.pointsEnabled or driftgod.S.stuntBusy then return end
    if not driftgod.S.runActive and (driftgod.S.currentScore or 0) <= 0 then return end
    driftgod.FinishRun(reason or "Run Ended")
    driftgod.S.lastRunEndMessage = popupText or "RUN ENDED"
    driftgod.S.lastRunEndUntil = driftgod.Now() + 3500
    driftgod.AddBonusPopup(popupText or "RUN ENDED", 255, 80, 80)
    driftgod.Toast(toastText or "Run ended.", 2500)
    driftgod.S.crashLockoutUntil = driftgod.Now() + 1200
end

function driftgod.GetSpeedScoreMultiplier(speedKmh)
    driftgod.S = driftgod.S or {}
    if driftgod.S.speedScoreScalingEnabled ~= true then return 1.0 end

    speedKmh = tonumber(speedKmh or 0) or 0
    local mph = speedKmh * 0.621371

    local mult
    if mph <= 20 then
        mult = 0.35
    elseif mph < 45 then
        mult = 0.35 + ((mph - 20) / 25) * 0.65
    elseif mph < 100 then
        mult = 1.00 + ((mph - 45) / 55) * 0.35
    else
        mult = 1.35
    end

    if mult < 0.25 then mult = 0.25 end
    if mult > 1.50 then mult = 1.50 end

    driftgod.S.lastSpeedScoreMph = mph
    driftgod.S.lastSpeedScoreMultiplier = mult

    if driftgod.S.speedScoreScalingDebugEnabled == true then
        local now = driftgod.Now and driftgod.Now() or 0
        if (tonumber(now or 0) - tonumber(driftgod.S.lastSpeedScoreDebugMs or 0)) >= 2500 then
            driftgod.S.lastSpeedScoreDebugMs = tonumber(now or 0)
            if driftgod.Log then driftgod.Log("[SpeedScore] mph=" .. tostring(math.floor(mph)) .. " mult=" .. tostring(string.format and string.format("%.2f", mult) or mult)) end
        end
    end

    return mult
end

function driftgod.AddPoints(amount, speedKmh)
    if not driftgod.S.pointsEnabled then return end
    amount = amount or 0
    if amount <= 0 then return end

    if driftgod.S.speedScoreScalingEnabled == true then
        amount = amount * (driftgod.GetSpeedScoreMultiplier and driftgod.GetSpeedScoreMultiplier(speedKmh) or 1.0)
    end

    if driftgod.HandleBannedScoreBlockedPoints and driftgod.HandleBannedScoreBlockedPoints(amount) then return end
    driftgod.S.currentScore = (driftgod.S.currentScore or 0) + amount
    if driftgod.S.currentScore > driftgod.S.bestScore then driftgod.S.bestScore = math.floor(driftgod.S.currentScore) end
    local todayBestImproved = false
    if driftgod.UpdateTodayBest then todayBestImproved = driftgod.UpdateTodayBest(driftgod.S.currentScore) == true end

    driftgod.S.progressScore = math.max(tonumber(driftgod.S.progressScore or 0) or 0, math.floor(driftgod.S.currentScore or 0))
    driftgod.S.lifetimeScore = math.max(tonumber(driftgod.S.lifetimeScore or 0) or 0, math.floor(driftgod.S.currentScore or 0))
    driftgod.S.totalScore = math.max(tonumber(driftgod.S.totalScore or 0) or 0, math.floor(driftgod.S.currentScore or 0))

    if driftgod.S.currentScore >= driftgod.S.bestScore then
        local now = driftgod.Now and driftgod.Now() or 0
        if (tonumber(now or 0) - tonumber(driftgod.S.lastLiveBestDiskSaveMs or 0)) >= 3000 then
            driftgod.S.lastLiveBestDiskSaveMs = tonumber(now or 0)
            if driftgod.SaveProgressHard then driftgod.SaveProgressHard("live high score throttle") else driftgod.SaveProgress(false) end
        end
    elseif todayBestImproved == true then
        local now = driftgod.Now and driftgod.Now() or 0
        if (tonumber(now or 0) - tonumber(driftgod.S.lastTodayBestDiskSaveMs or 0)) >= 5000 then
            driftgod.S.lastTodayBestDiskSaveMs = tonumber(now or 0)
            if driftgod.SaveProgressHard then driftgod.SaveProgressHard("today best throttle") else driftgod.SaveProgress(false) end
        end
    end
    driftgod.S.hudVisibleUntil = driftgod.Now() + driftgod.S.hudFadeAfterMs
    driftgod.S.hudAlpha = 255
    if driftgod.CheckUnlocks then driftgod.CheckUnlocks() end
    if driftgod.ForceCheckStuntProgression then driftgod.ForceCheckStuntProgression("AddPoints") end
    if driftgod.CheckRivalBeaten then driftgod.CheckRivalBeaten() end
end

function driftgod.IncreaseCombo(amount, reason)

    local current = tonumber(driftgod.S.comboMultiplier or 1) or 1
    local maxCombo = tonumber(driftgod.S.maxComboMultiplier or 10) or 10
    if maxCombo < 1 then maxCombo = 10 end
    if maxCombo > 10 then maxCombo = 10 end
    driftgod.S.maxComboMultiplier = maxCombo

    local nextCombo = current + 1
    driftgod.S.comboMultiplier = driftgod.ClampInt(nextCombo, 1, maxCombo)
    if driftgod.S.comboMultiplier > driftgod.S.currentRunBestCombo then driftgod.S.currentRunBestCombo = driftgod.S.comboMultiplier end
    if driftgod.S.comboMultiplier > driftgod.S.bestCombo then driftgod.S.bestCombo = driftgod.S.comboMultiplier end
    driftgod.AddBonusPopup(tostring(driftgod.S.comboMultiplier) .. "x Combo", 190, 90, 255)
end

