function driftgod.AwardStuntLanding(name)
    if not driftgod.S.pointsEnabled then return end
    driftgod.S.landedStuntsThisRun = driftgod.S.landedStuntsThisRun + 1
    driftgod.S.totalStuntsLanded = driftgod.S.totalStuntsLanded + 1
    driftgod.S.cleanStuntChain = driftgod.S.cleanStuntChain + 1
    driftgod.IncreaseCombo(driftgod.S.cleanStuntChain >= 2 and 2 or 1, "COMBO")
    if driftgod.AddStuntLandingPhrasePopup then driftgod.AddStuntLandingPhrasePopup() else driftgod.AddBonusPopup("CLEAN LANDING", 120, 255, 180) end
    driftgod.S.lastStuntName = name
    driftgod.S.lastStuntLanded = true

    if driftgod.RecordLandedStuntForProgress then driftgod.RecordLandedStuntForProgress(name) end
    if driftgod.ForceCheckStuntProgression then driftgod.ForceCheckStuntProgression("AwardStuntLanding") end
    driftgod.SaveProgress(false)
end

driftgod.ComboSavePhrases = driftgod.ComboSavePhrases or {
    "COMBO GRACE",
    "CHAIN SAVED",
    "STREAK SAVED",
}

function driftgod.GetRandomComboSavePhrase()
    if driftgod.S and driftgod.S.comboSaveArcadePhrasesEnabled == false then
        return "CHAIN SAVED"
    end

    local pool = driftgod.ComboSavePhrases or {}
    if #pool <= 0 then return "CHAIN SAVED" end

    local phrase = pool[math.random(1, #pool)] or "CHAIN SAVED"

    if #pool > 1 and driftgod.S and phrase == driftgod.S.lastComboSavePhrase then
        for _ = 1, 4 do
            local retry = pool[math.random(1, #pool)] or phrase
            if retry ~= driftgod.S.lastComboSavePhrase then
                phrase = retry
                break
            end
        end
    end

    if driftgod.S then driftgod.S.lastComboSavePhrase = phrase end
    return phrase
end

function driftgod.AddComboSavePopup()
    local now = driftgod.Now and driftgod.Now() or math.floor((os.clock() or 0) * 1000)

    if driftgod.S.lastComboSavePopupAt and (now - driftgod.S.lastComboSavePopupAt) < 300 then
        return false
    end

    driftgod.S.lastComboSavePopupAt = now
    driftgod.AddBonusPopup(driftgod.NormalizeComboPopupText and driftgod.NormalizeComboPopupText(driftgod.GetRandomComboSavePhrase and driftgod.GetRandomComboSavePhrase() or "CHAIN SAVED") or (driftgod.GetRandomComboSavePhrase and driftgod.GetRandomComboSavePhrase() or "CHAIN SAVED"), 130, 220, 255)
    return true
end

function driftgod.NormalizeComboPopupText(text)
    text = tostring(text or "")
    text = text:gsub("(%d+x)%s+[Cc][Oo][Mm][Bb][Oo].*", "%1 Combo")
    text = text:gsub("(%d+x)%s*%-%s*.*", "%1 Combo")
    return text
end

function driftgod.PointsTick()
    if not driftgod.S.pointsEnabled or not driftgod.HasNatives() then return end
    local now = driftgod.Now()
    if driftgod.S.lastScoreTick == 0 then driftgod.S.lastScoreTick = now return end
    local dt = now - driftgod.S.lastScoreTick
    driftgod.S.lastScoreTick = now
    if dt <= 0 or dt > 500 or now < driftgod.S.crashLockoutUntil then return end
    local veh = driftgod.GetVehicle()
    if veh == 0 then if driftgod.S.runActive then driftgod.FinishRun("Exited Vehicle") end driftgod.S.hudAlpha = 0 return end
    if driftgod.VehicleSectorGateTick and not driftgod.VehicleSectorGateTick("score", veh) then return end
    local held = driftgod.IsDriftHeld()
    if not held then
        driftgod.S.validDriftWatchMs = 0
        if driftgod.S.runActive or driftgod.S.currentScore > 0 then
            if driftgod.S.comboGraceUntil == 0 then
                driftgod.S.comboGraceUntil = now + driftgod.S.comboGraceMs
                driftgod.S.lastShiftReleaseMs = now
                driftgod.AddComboSavePopup()
            end
            if now <= driftgod.S.comboGraceUntil then driftgod.S.hudVisibleUntil = now + driftgod.S.hudFadeAfterMs driftgod.S.hudAlpha = 255 return end
            driftgod.FinishRun("Combo Grace Ended")
        end
        return
    end
    if driftgod.S.comboGraceUntil > 0 then driftgod.S.comboGraceUntil = 0 driftgod.AddComboSavePopup() end
    local speedKmh = ENTITY.GET_ENTITY_SPEED(veh) * 3.6
    local driftAngle = driftgod.GetDriftAngle(veh)
    local inAir = ENTITY.IS_ENTITY_IN_AIR(veh)
    local validDrift = speedKmh >= 18.0 and driftAngle >= 15.0 and driftAngle <= 125.0 and not inAir
    if validDrift then driftgod.S.validDriftWatchMs = driftgod.S.validDriftWatchMs + dt else driftgod.S.validDriftWatchMs = 0 end
    if validDrift and driftgod.S.validDriftWatchMs >= 300 then
        driftgod.S.runActive = true
        driftgod.S.activeDriftMs = driftgod.S.activeDriftMs + dt
        if driftgod.S.activeDriftMs > driftgod.S.longestDriftMs then driftgod.S.longestDriftMs = driftgod.S.activeDriftMs end
        if driftgod.S.lastCleanDriftComboTick == 0 then driftgod.S.lastCleanDriftComboTick = now end
        if now - driftgod.S.lastCleanDriftComboTick >= 7000 then driftgod.IncreaseCombo(1, "LONG SLIDE") driftgod.S.lastCleanDriftComboTick = now end
        local gained = (dt / 1000.0) * 22.0 * (1.0 + math.min(driftAngle, 80.0) / 70.0) * (1.0 + math.min(speedKmh, 180.0) / 220.0) * driftgod.S.comboMultiplier
        driftgod.AddPoints(gained, speedKmh)
    else
        driftgod.S.lastCleanDriftComboTick = 0
        if driftgod.S.runActive and speedKmh < 3.0 then driftgod.S.stoppedWatchMs = driftgod.S.stoppedWatchMs + dt else driftgod.S.stoppedWatchMs = 0 end
        if driftgod.S.stoppedWatchMs >= 700 then driftgod.StopRun("Stopped", "STOPPED!", "Stopped. Score saved.") end
    end
end

function driftgod.ResetCurrentScore()
    driftgod.FinishRun("Manual Reset")
    driftgod.ResetRunStats()
    driftgod.Toast("Current DriftGod score reset.", 2500)
end

driftgod.Try(function()
    require("systems.progress_persistence")
    if driftgod.InstallProgressPersistence then driftgod.InstallProgressPersistence("scoring") end
end)

driftgod.Try(function()
    require("systems.session_challenges")
    if driftgod.InstallSessionChallenges then driftgod.InstallSessionChallenges("scoring") end
    require("systems.vehicle_mastery")
    if driftgod.InstallVehicleMastery then driftgod.InstallVehicleMastery("scoring") end
    require("systems.vehicle_sectors")
    if driftgod.InstallVehicleSectors then driftgod.InstallVehicleSectors("scoring") end
    require("systems.progress_milestones")
    if driftgod.InstallProgressMilestones then driftgod.InstallProgressMilestones("scoring") end
end)

return DG
end

