local function logChallenge(msg, force)
    msg = tostring(msg or "")

    local lower = msg:lower()
    local important = force == true
        or lower:find("error", 1, true) ~= nil
        or lower:find("failed", 1, true) ~= nil
        or lower:find("warning", 1, true) ~= nil

    if not important and driftgod.S and driftgod.S.sessionChallengeDebugEnabled ~= true then return end

    if driftgod.Log then
        driftgod.Log("[Challenge] " .. msg)
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] [Challenge] " .. msg)
    elseif log then
        log("[DriftGod] [Challenge] " .. msg)
    end
end

local function toast(msg, ms)
    if driftgod.Toast then
        driftgod.Toast(tostring(msg or ""), tonumber(ms or 2500) or 2500)
    elseif UI and UI.Notify then
        UI.Notify(tostring(msg or ""))
    end
end

