function driftgod.GetDailyChallengeDateKey()
    if os and os.date then
        return tostring(os.date("%Y-%m-%d"))
    end

    local day = 0
    if driftgod.GetMs then day = math.floor((tonumber(driftgod.GetMs() or 0) or 0) / 86400000) end
    return "day-" .. tostring(day)
end

function driftgod.DailyChallengeSeedFromDate(dateKey)
    local seed = 0
    local s = tostring(dateKey or "")
    for i = 1, #s do
        seed = seed + (string.byte(s, i) or 0) * i
    end
    return seed
end

function driftgod.DailyChallengeSortScore(id, dateKey)
    local forceNonce = tonumber(driftgod.S and driftgod.S.dailyChallengeForceNonce or 0) or 0
    local seed = (driftgod.DailyChallengeSeedFromDate and driftgod.DailyChallengeSeedFromDate(dateKey) or 0) + (forceNonce * 7919)
    local score = seed
    local s = tostring(id or "")
    for i = 1, #s do
        score = (score * 33 + (string.byte(s, i) or 0) * (i + 17)) % 1000003
    end
    return score
end

function driftgod.IsChallengeEligibleForDaily(challenge)
    if not challenge or not challenge.id then return false end

    if driftgod.S and driftgod.S.sessionChallengesCompleted and driftgod.S.sessionChallengesCompleted[challenge.id] == true then
        return false
    end

    if tostring(challenge.id or ""):find("rival", 1, true) then
        return false
    end

    return true
end

function driftgod.RefreshDailyChallenges(force)
    driftgod.SessionChallengesEnsureDefaults()

    if driftgod.S.dailyChallengesEnabled == false then return end

    local dateKey = driftgod.GetDailyChallengeDateKey and driftgod.GetDailyChallengeDateKey() or "unknown"
    if force ~= true and driftgod.S.dailyChallengeDateKey == dateKey and type(driftgod.S.dailyChallengeActiveIds) == "table" and #driftgod.S.dailyChallengeActiveIds > 0 then
        return
    end

    local pool = {}
    for _, challenge in ipairs(driftgod.SessionChallengeList or {}) do
        if driftgod.IsChallengeEligibleForDaily and driftgod.IsChallengeEligibleForDaily(challenge) then
            table.insert(pool, challenge)
        end
    end

    table.sort(pool, function(a, b)
        local sa = driftgod.DailyChallengeSortScore and driftgod.DailyChallengeSortScore(a.id, dateKey) or 0
        local sb = driftgod.DailyChallengeSortScore and driftgod.DailyChallengeSortScore(b.id, dateKey) or 0
        return sa < sb
    end)

    driftgod.S.dailyChallengeDateKey = dateKey
    driftgod.S.dailyChallengeActiveIds = {}
    driftgod.S.dailyChallengeCompleted = driftgod.S.dailyChallengeCompleted or {}

    local limit = tonumber(driftgod.S.dailyChallengeLimit or 3) or 3
    for i = 1, math.min(limit, #pool) do
        table.insert(driftgod.S.dailyChallengeActiveIds, pool[i].id)
    end

    logChallenge("Daily challenges refreshed | date=" .. tostring(dateKey) .. " | active=" .. table.concat(driftgod.S.dailyChallengeActiveIds, ", "))
    if driftgod.SaveProgress then driftgod.SaveProgress(false) end
end

function driftgod.IsDailyChallengeActive(id)
    driftgod.SessionChallengesEnsureDefaults()
    if driftgod.S.dailyChallengesEnabled == false then return true end
    if driftgod.RefreshDailyChallenges then driftgod.RefreshDailyChallenges(false) end

    for _, activeId in ipairs(driftgod.S.dailyChallengeActiveIds or {}) do
        if activeId == id then return true end
    end

    return false
end

function driftgod.GetActiveDailyChallenges()
    driftgod.SessionChallengesEnsureDefaults()
    if driftgod.RefreshDailyChallenges then driftgod.RefreshDailyChallenges(false) end

    local list = {}

    if driftgod.S.dailyChallengesEnabled == false then
        return driftgod.SessionChallengeList or {}
    end

    for _, id in ipairs(driftgod.S.dailyChallengeActiveIds or {}) do
        local challenge = driftgod.GetSessionChallengeById and driftgod.GetSessionChallengeById(id) or nil
        if challenge then table.insert(list, challenge) end
    end

    return list
end

function driftgod.ForceNextDailyChallenges()
    driftgod.SessionChallengesEnsureDefaults()

    driftgod.S.dailyChallengeForceNonce = (tonumber(driftgod.S.dailyChallengeForceNonce or 0) or 0) + 1
    driftgod.S.dailyChallengeDateKey = ""
    driftgod.S.dailyChallengeActiveIds = {}

    if driftgod.RefreshDailyChallenges then driftgod.RefreshDailyChallenges(true) end

    if driftgod.SaveProgress then driftgod.SaveProgress(false) end
end

function driftgod.GetSessionChallengeById(id)
    for _, challenge in ipairs(driftgod.SessionChallengeList or {}) do
        if challenge.id == id then return challenge end
    end
    return nil
end

function driftgod.GetSessionChallengeRunState()
    driftgod.SessionChallengesEnsureDefaults()

    local unique = 0
    if type(driftgod.S.sessionChallengeRunStuntTypes) == "table" then
        for _, seen in pairs(driftgod.S.sessionChallengeRunStuntTypes) do
            if seen == true then unique = unique + 1 end
        end
    end

    local durationMs = tonumber(driftgod.S.sessionChallengeRunDurationMs or 0) or 0
    if driftgod.S.sessionChallengeRunActive == true and tonumber(driftgod.S.sessionChallengeRunStartAt or 0) > 0 then
        durationMs = math.max(durationMs, nowMs() - (tonumber(driftgod.S.sessionChallengeRunStartAt or 0) or 0))
    end

    return {
        score = tonumber(driftgod.S.sessionChallengeRunPeakScore or 0) or 0,
        stunts = tonumber(driftgod.S.sessionChallengeRunStunts or 0) or 0,
        donuts = tonumber(driftgod.S.sessionChallengeRunDonuts or 0) or 0,
        uniqueStunts = unique,
        combo = tonumber(driftgod.S.sessionChallengeRunComboPeak or 0) or 0,
        rivalBeat = driftgod.S.sessionChallengeRunRivalBeat == true,
        bankedOverall = driftgod.S.sessionChallengeRunBankedOverall == true,
        noCollision = driftgod.S.sessionChallengeRunNoCollision == true,
        durationMs = durationMs,
    }
end

function driftgod.StartSessionChallengeRun(reason)
    driftgod.SessionChallengesEnsureDefaults()

    if driftgod.S.sessionChallengeRunActive == true then return end

    driftgod.S.sessionChallengeRunId = (tonumber(driftgod.S.sessionChallengeRunId or 0) or 0) + 1
    driftgod.S.sessionChallengeRunActive = true
    driftgod.S.sessionChallengeRunPeakScore = 0
    driftgod.S.sessionChallengeRunStunts = 0
    driftgod.S.sessionChallengeRunDonuts = 0
    driftgod.S.sessionChallengeRunComboPeak = 0
    driftgod.S.sessionChallengeRunBankedOverall = false
    driftgod.S.sessionChallengeRunRivalBeat = false
    driftgod.S.sessionChallengeRunNoCollision = true
    driftgod.S.sessionChallengeRunDurationMs = 0
    driftgod.S.sessionChallengeRunStartAt = nowMs()
    driftgod.S.sessionChallengeRunStuntTypes = {}

    logChallenge("Run started | runId=" .. tostring(driftgod.S.sessionChallengeRunId) .. " | reason=" .. tostring(reason or "unknown"))
end

function driftgod.UpdateSessionChallengeRunScore(score)
    driftgod.SessionChallengesEnsureDefaults()
    if not (driftgod.S.sessionChallengesEnabled) then return end

    score = math.floor(tonumber(score or 0) or 0)
    if score <= 0 then return end

    if driftgod.S.sessionChallengeRunActive ~= true then
        driftgod.StartSessionChallengeRun("score")
    end

    if score > (tonumber(driftgod.S.sessionChallengeRunPeakScore or 0) or 0) then
        driftgod.S.sessionChallengeRunPeakScore = score
    end

    local combo = tonumber(driftgod.S.combo or driftgod.S.comboCount or driftgod.S.currentCombo or driftgod.S.comboMultiplier or 0) or 0
    if combo > (tonumber(driftgod.S.sessionChallengeRunComboPeak or 0) or 0) then
        driftgod.S.sessionChallengeRunComboPeak = combo
    end

    driftgod.CheckSessionChallenges("score update")
end

function driftgod.RecordSessionChallengeAcceptedLanding(stuntName, source)
    driftgod.SessionChallengesEnsureDefaults()
    if not (driftgod.S.sessionChallengesEnabled) then return end

    local name = tostring(stuntName or "")
    if name == "" then name = "Unknown" end

    local now = nowMs()
    local key = name:lower()

    driftgod.S.sessionChallengeLastAcceptedLandingName = driftgod.S.sessionChallengeLastAcceptedLandingName or ""
    driftgod.S.sessionChallengeLastAcceptedLandingAt = tonumber(driftgod.S.sessionChallengeLastAcceptedLandingAt or 0) or 0

    if driftgod.S.sessionChallengeLastAcceptedLandingName == key and (now - driftgod.S.sessionChallengeLastAcceptedLandingAt) < 1200 then
        logChallenge("Accepted landing duplicate skipped | name=" .. name .. " | source=" .. tostring(source or "unknown"))
        return
    end

    driftgod.S.sessionChallengeLastAcceptedLandingName = key
    driftgod.S.sessionChallengeLastAcceptedLandingAt = now

    driftgod.RecordSessionChallengeStuntUse(name)
end

function driftgod.RecordSessionChallengeStuntUse(stuntName)
    driftgod.SessionChallengesEnsureDefaults()
    if not (driftgod.S.sessionChallengesEnabled) then return end

    if driftgod.S.sessionChallengeRunActive ~= true then
        driftgod.StartSessionChallengeRun("stunt")
    end

    driftgod.S.sessionChallengeRunStunts = (tonumber(driftgod.S.sessionChallengeRunStunts or 0) or 0) + 1

    local name = tostring(stuntName or ""):lower()
    local key = name:gsub("%s+", "_")
    driftgod.S.sessionChallengeRunStuntTypes = driftgod.S.sessionChallengeRunStuntTypes or {}
    if key ~= "" then driftgod.S.sessionChallengeRunStuntTypes[key] = true end

    if name:find("donut", 1, true) then
        driftgod.S.sessionChallengeRunDonuts = (tonumber(driftgod.S.sessionChallengeRunDonuts or 0) or 0) + 1
    end

    logChallenge("Stunt accepted | name=" .. tostring(stuntName or "unknown")
        .. " | stunts=" .. tostring(driftgod.S.sessionChallengeRunStunts)
        .. " | donuts=" .. tostring(driftgod.S.sessionChallengeRunDonuts))

    driftgod.CheckSessionChallenges("stunt use")
end

function driftgod.MarkSessionChallengeRivalBeatFromState(source)
    driftgod.SessionChallengesEnsureDefaults()
    if not (driftgod.S.sessionChallengesEnabled) then return end

    local count = 0
    if type(driftgod.S.beatenRivals) == "table" then
        for _, done in pairs(driftgod.S.beatenRivals) do
            if done == true then count = count + 1 end
        end
    end

    local previous = tonumber(driftgod.S.sessionChallengeSeenRivalBeatCount or 0) or 0
    if count > previous then
        driftgod.S.sessionChallengeSeenRivalBeatCount = count
        driftgod.MarkSessionChallengeRivalBeat("Rival #" .. tostring(count) .. " via " .. tostring(source or "state"))
    end
end

function driftgod.MarkSessionChallengeRivalBeat(rivalName)
    driftgod.SessionChallengesEnsureDefaults()
    if not (driftgod.S.sessionChallengesEnabled) then return end

    if driftgod.S.sessionChallengeRunActive ~= true then
        driftgod.StartSessionChallengeRun("rival")
    end

    driftgod.S.sessionChallengeRunRivalBeat = true
    logChallenge("Rival beat marked | rival=" .. tostring(rivalName or "unknown"))
    driftgod.CheckSessionChallenges("rival beat")
end

function driftgod.MarkSessionChallengeOverallBank(runScore)
    driftgod.SessionChallengesEnsureDefaults()
    if not (driftgod.S.sessionChallengesEnabled) then return end

    if driftgod.S.sessionChallengeRunActive ~= true then
        driftgod.StartSessionChallengeRun("overall bank")
    end

    driftgod.S.sessionChallengeRunBankedOverall = true
    if tonumber(runScore or 0) and tonumber(runScore or 0) > (tonumber(driftgod.S.sessionChallengeRunPeakScore or 0) or 0) then
        driftgod.S.sessionChallengeRunPeakScore = tonumber(runScore or 0) or driftgod.S.sessionChallengeRunPeakScore
    end

    logChallenge("Overall bank marked | score=" .. tostring(runScore or 0))
    driftgod.CheckSessionChallenges("overall bank")
end

function driftgod.CompleteSessionChallenge(challenge, reason)
    driftgod.SessionChallengesEnsureDefaults()
    if not challenge or not challenge.id then return false end

    if driftgod.S.sessionChallengesCompleted[challenge.id] == true then return false end

    driftgod.S.sessionChallengesCompleted[challenge.id] = true
    driftgod.S.sessionChallengePoints = (tonumber(driftgod.S.sessionChallengePoints or 0) or 0) + (tonumber(challenge.points or 1) or 1)
    driftgod.S.sessionChallengeLastCompleted = challenge.id
    driftgod.S.dailyChallengeCompleted = driftgod.S.dailyChallengeCompleted or {}
    driftgod.S.dailyChallengeCompleted[challenge.id] = driftgod.GetDailyChallengeDateKey and driftgod.GetDailyChallengeDateKey() or "unknown"

    local msg = "CHALLENGE COMPLETE: " .. tostring(challenge.title or challenge.id)
    toast(msg, 3000)

    logChallenge(msg
        .. " | +" .. tostring(challenge.points or 1)
        .. " CP | totalCP=" .. tostring(driftgod.S.sessionChallengePoints)
        .. " | reason=" .. tostring(reason or "unknown"), true)

    if driftgod.CheckProgressMilestones then driftgod.CheckProgressMilestones("session challenge") end
    if driftgod.SaveProgress then driftgod.SaveProgress(false) end
    return true
end

function driftgod.CheckSessionChallenges(reason)
    driftgod.SessionChallengesEnsureDefaults()
    if not (driftgod.S.sessionChallengesEnabled) then return end

    local run = driftgod.GetSessionChallengeRunState and driftgod.GetSessionChallengeRunState() or {}

    for _, challenge in ipairs(driftgod.SessionChallengeList or {}) do

        if challenge and challenge.id and driftgod.S.sessionChallengesCompleted[challenge.id] ~= true and (driftgod.IsDailyChallengeActive == nil or driftgod.IsDailyChallengeActive(challenge.id)) then
            local ok = false
            if type(challenge.check) == "function" then
                local success, result = driftgod.Try(challenge.check, run)
                ok = success and result == true
            end

            if ok then
                driftgod.CompleteSessionChallenge(challenge, reason or "check")
            end
        end
    end
end

function driftgod.MarkSessionChallengeCollision(source)
    driftgod.SessionChallengesEnsureDefaults()
    if not (driftgod.S.sessionChallengesEnabled) then return end
    if driftgod.S.sessionChallengeRunActive == true then
        driftgod.S.sessionChallengeRunNoCollision = false
        logChallenge("Collision marked | source=" .. tostring(source or "unknown"))
    end
end

function driftgod.EndSessionChallengeRun(reason, finalScore)
    driftgod.SessionChallengesEnsureDefaults()
    if not (driftgod.S.sessionChallengesEnabled) then return end

    finalScore = math.floor(tonumber(finalScore or 0) or 0)
    if finalScore > (tonumber(driftgod.S.sessionChallengeRunPeakScore or 0) or 0) then
        driftgod.S.sessionChallengeRunPeakScore = finalScore
    end

    driftgod.CheckSessionChallenges("run ended")

    logChallenge("Run ended | runId=" .. tostring(driftgod.S.sessionChallengeRunId)
        .. " | final=" .. tostring(finalScore)
        .. " | peak=" .. tostring(driftgod.S.sessionChallengeRunPeakScore)
        .. " | stunts=" .. tostring(driftgod.S.sessionChallengeRunStunts)
        .. " | donuts=" .. tostring(driftgod.S.sessionChallengeRunDonuts)
        .. " | reason=" .. tostring(reason or "unknown"))

    driftgod.S.sessionChallengeLastRunScore = driftgod.S.sessionChallengeRunPeakScore
    driftgod.S.sessionChallengeRunDurationMs = 0
    driftgod.S.sessionChallengeRunStartAt = 0
    driftgod.S.sessionChallengeRunActive = false
    driftgod.S.sessionChallengeRunPeakScore = 0
    driftgod.S.sessionChallengeRunStunts = 0
    driftgod.S.sessionChallengeRunDonuts = 0
    driftgod.S.sessionChallengeRunComboPeak = 0
    driftgod.S.sessionChallengeRunBankedOverall = false
    driftgod.S.sessionChallengeRunRivalBeat = false
    driftgod.S.sessionChallengeRunNoCollision = true
    driftgod.S.sessionChallengeRunStuntTypes = {}

    if driftgod.SaveProgress then driftgod.SaveProgress(false) end
end

function driftgod.SessionChallengeSnapshot(reason)
    driftgod.SessionChallengesEnsureDefaults()

    local completed = 0
    for _, done in pairs(driftgod.S.sessionChallengesCompleted or {}) do
        if done == true then completed = completed + 1 end
    end

    local run = driftgod.GetSessionChallengeRunState and driftgod.GetSessionChallengeRunState() or {}

    logChallenge("Snapshot | reason=" .. tostring(reason or "manual")
        .. " | completed=" .. tostring(completed) .. "/" .. tostring(#(driftgod.SessionChallengeList or {}))
        .. " | CP=" .. tostring(driftgod.S.sessionChallengePoints or 0)
        .. " | runScore=" .. tostring(run.score or 0)
        .. " | stunts=" .. tostring(run.stunts or 0)
        .. " | donuts=" .. tostring(run.donuts or 0)
        .. " | unique=" .. tostring(run.uniqueStunts or 0)
        .. " | combo=" .. tostring(run.combo or 0)
        .. " | clean=" .. tostring(run.noCollision)
        .. " | durationMs=" .. tostring(run.durationMs or 0)
        .. " | rivalBeat=" .. tostring(run.rivalBeat)
        .. " | bankedOverall=" .. tostring(run.bankedOverall), true)
end

function driftgod.InstallSessionChallenges(source)
    driftgod.SessionChallengesEnsureDefaults()

    if driftgod.SessionChallenges.installed == true then
        logChallenge("Install skipped; already installed | source=" .. tostring(source or "unknown"))
        return true
    end

    driftgod.SessionChallenges.installed = true
    driftgod.SessionChallenges.source = tostring(source or "unknown")

    if type(driftgod.ExportProgress) == "function" then
        local oldExportProgress = driftgod.ExportProgress
        driftgod.ExportProgress = function()
            local t = oldExportProgress() or {}
            t.sessionChallengesCompleted = driftgod.S.sessionChallengesCompleted or {}
            t.sessionChallengePoints = tonumber(driftgod.S.sessionChallengePoints or 0) or 0
            t.sessionChallengeLastCompleted = driftgod.S.sessionChallengeLastCompleted or ""
            t.sessionChallengeTotalPool = #(driftgod.SessionChallengeList or {})
            t.dailyChallengeDateKey = driftgod.S.dailyChallengeDateKey or ""
            t.dailyChallengeActiveIds = driftgod.S.dailyChallengeActiveIds or {}
            t.dailyChallengeCompleted = driftgod.S.dailyChallengeCompleted or {}
            t.dailyChallengeForceNonce = tonumber(driftgod.S.dailyChallengeForceNonce or 0) or 0
            return t
        end
    else
        logChallenge("Warning: driftgod.ExportProgress missing during session challenge install", true)
    end

    if type(driftgod.ApplyProgress) == "function" then
        local oldApplyProgress = driftgod.ApplyProgress
        driftgod.ApplyProgress = function(t)
            local result = oldApplyProgress(t)

            if type(t) == "table" then
                if type(t.sessionChallengesCompleted) == "table" then
                    driftgod.S.sessionChallengesCompleted = t.sessionChallengesCompleted
                end
                driftgod.S.sessionChallengePoints = tonumber(t.sessionChallengePoints or driftgod.S.sessionChallengePoints or 0) or 0
                driftgod.S.sessionChallengeLastCompleted = tostring(t.sessionChallengeLastCompleted or driftgod.S.sessionChallengeLastCompleted or "")
                if type(t.dailyChallengeActiveIds) == "table" then driftgod.S.dailyChallengeActiveIds = t.dailyChallengeActiveIds end
                if type(t.dailyChallengeCompleted) == "table" then driftgod.S.dailyChallengeCompleted = t.dailyChallengeCompleted end
                driftgod.S.dailyChallengeDateKey = tostring(t.dailyChallengeDateKey or driftgod.S.dailyChallengeDateKey or "")
                driftgod.S.dailyChallengeForceNonce = tonumber(t.dailyChallengeForceNonce or driftgod.S.dailyChallengeForceNonce or 0) or 0
            end

            driftgod.SessionChallengesEnsureDefaults()
            return result
        end
    else
        logChallenge("Warning: driftgod.ApplyProgress missing during session challenge install", true)
    end

    if type(driftgod.AwardStuntLanding) == "function" then
        local oldAwardStuntLanding = driftgod.AwardStuntLanding
        driftgod.AwardStuntLanding = function(stuntName)
            local result = oldAwardStuntLanding(stuntName)

            if driftgod.RecordSessionChallengeAcceptedLanding then
                driftgod.RecordSessionChallengeAcceptedLanding(stuntName, "AwardStuntLanding")
            end

            return result
        end
    else
        logChallenge("Warning: driftgod.AwardStuntLanding missing during session challenge install", true)
    end

    if type(driftgod.BankOverallScoreValue) == "function" then
        local oldBankOverallScoreValue = driftgod.BankOverallScoreValue
        driftgod.BankOverallScoreValue = function(runScore, reason)
            local result = oldBankOverallScoreValue(runScore, reason)
            if result == true then
                driftgod.MarkSessionChallengeOverallBank(runScore)
            end
            return result
        end
    else
        logChallenge("Warning: driftgod.BankOverallScoreValue missing during session challenge install", true)
    end

    if type(driftgod.FinishRun) == "function" then
        local oldFinishRun = driftgod.FinishRun
        driftgod.FinishRun = function(reason)
            local finalScore = math.floor(tonumber(driftgod.S and driftgod.S.currentScore or 0) or 0)
            if finalScore > 0 then
                driftgod.UpdateSessionChallengeRunScore(finalScore)
            end

            local result = oldFinishRun(reason)

            driftgod.EndSessionChallengeRun(reason or "FinishRun", finalScore)
            return result
        end
    else
        logChallenge("Warning: driftgod.FinishRun missing during session challenge install", true)
    end

    if driftgod.LoadProgress and driftgod.SessionChallenges.reloadedAfterInstall ~= true then
        driftgod.SessionChallenges.reloadedAfterInstall = true
        driftgod.Try(function()
            driftgod.LoadProgress(false)
        end)
    end

    logChallenge("Installed session challenges module | source=" .. tostring(source or "unknown"))
    return true
end

return DG
end

__DG_BUNDLE_LOADERS["systems.smoke"] = function()
DG = DG or {}
function driftgod.GetSmokeRGB()
    local now = driftgod.Now()
    local t = driftgod.S.smokeSpeed * 0.0025 * now
    local pulse = math.sin(t) * 0.5 + 0.5
    local style = driftgod.SmokeStyles[driftgod.S.smokeStyleIndex] or "White Smoke"
    if style == "White Smoke" then return 255,255,255 end
    if style == "Red Pulse" then return math.floor(100 + 155 * pulse),0,0 end
    if style == "Purple Pulse" then return math.floor(90 + 120 * pulse),0,math.floor(140 + 115 * pulse) end
    if style == "Red / Black" then return math.floor(255 * pulse),0,0 end
    if style == "Purple / Black" then return math.floor(190 * pulse),0,math.floor(255 * pulse) end
    if style == "Gold / White" then return 255,math.floor(200 + 55 * pulse),math.floor(80 + 175 * pulse) end
    if style == "Rainbow" then return math.floor(math.sin(t) * 127 + 128), math.floor(math.sin(t + 2) * 127 + 128), math.floor(math.sin(t + 4) * 127 + 128) end
    if style == "DriftGod Purple" then return 190,90,255 end
    return 255,255,255
end
function driftgod.UpdateScoreReactiveSmoke()
    if not driftgod.S.scoreReactiveSmokeEnabled then return end
    local score = math.floor(driftgod.S.currentScore or 0)
    if score >= 50000 then driftgod.S.smokeStyleIndex = 8 elseif score >= 25000 then driftgod.S.smokeStyleIndex = 7 elseif score >= 10000 then driftgod.S.smokeStyleIndex = 6 elseif score >= 5000 then driftgod.S.smokeStyleIndex = 5 elseif score >= 2500 then driftgod.S.smokeStyleIndex = 4 elseif score >= 1000 then driftgod.S.smokeStyleIndex = 3 elseif score >= 500 then driftgod.S.smokeStyleIndex = 2 else driftgod.S.smokeStyleIndex = driftgod.S.baseSmokeStyleIndex end
end
function driftgod.SmokeTick()
    if not driftgod.HasNatives() then return end
    local veh = driftgod.GetVehicle(); if veh == 0 then return end
    driftgod.UpdateScoreReactiveSmoke()
    local r,g,b = driftgod.GetSmokeRGB()
    driftgod.Try(function()
        VEHICLE.SET_VEHICLE_MOD_KIT(veh, 0)
        VEHICLE.TOGGLE_VEHICLE_MOD(veh, 20, true)
        VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR(veh, r, g, b)
    end)
end
return DG
end

__DG_BUNDLE_LOADERS["systems.spawn"] = function()
DG = DG or {}
driftgod.S = driftgod.S or {}

local function DG_SPAWN_DEBUG_ENABLED()
    return DG and driftgod.S and driftgod.S.spawnDebugEnabled == true
end

local function DG_ZENTORNO_LOG(msg)
    msg = tostring(msg or "")

    if DG and driftgod.Log then
        driftgod.Log("[ZentornoWheel] " .. msg)
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] [ZentornoWheel] " .. msg)
    elseif log then
        log("[DriftGod] [ZentornoWheel] " .. msg)
    end
end

local function DG_ZENTORNO_SAFE_CALL(fn)
    local ok, err = driftgod.Try(fn)
    return ok, err
end

local function DG_ZENTORNO_SET_MOD_KIT(veh)
    return DG_ZENTORNO_SAFE_CALL(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then
            VEHICLE.SET_VEHICLE_MOD_KIT(veh, 0)
        elseif Natives and Natives.InvokeVoid then

            Natives.InvokeVoid(0x1F2AA07F00B3217A, veh, 0)
        end
    end)
end

local function DG_ZENTORNO_SET_WHEEL_TYPE(veh, wheelType)
    wheelType = tonumber(wheelType or 11) or 11

    return DG_ZENTORNO_SAFE_CALL(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then
            VEHICLE.SET_VEHICLE_WHEEL_TYPE(veh, wheelType)
        elseif Natives and Natives.InvokeVoid then

            Natives.InvokeVoid(0x487EB21CC7295BA1, veh, wheelType)
        end
    end)
end

local function DG_ZENTORNO_SET_MOD(veh, modType, modIndex, customTires)
    modType = tonumber(modType or 0) or 0
    modIndex = tonumber(modIndex or -1) or -1
    customTires = customTires == true

    return DG_ZENTORNO_SAFE_CALL(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD then
            VEHICLE.SET_VEHICLE_MOD(veh, modType, modIndex, customTires)
        elseif Natives and Natives.InvokeVoid then

            Natives.InvokeVoid(0x6AF0636DDEDCB6DD, veh, modType, modIndex, customTires)
        end
    end)
end

local function DG_ZENTORNO_SET_WHEEL_COLOR(veh, pearlescentColor, wheelColor)
    pearlescentColor = tonumber(pearlescentColor or 0) or 0
    wheelColor = tonumber(wheelColor or 0) or 0

    return DG_ZENTORNO_SAFE_CALL(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then
            VEHICLE.SET_VEHICLE_EXTRA_COLOURS(veh, pearlescentColor, wheelColor)
        elseif Natives and Natives.InvokeVoid then

            Natives.InvokeVoid(0x2036F561ADD12E33, veh, pearlescentColor, wheelColor)
        end
    end)
end

local function DG_APPLY_ZENTORNO_WHEEL_ORDER(veh, cfg)
    cfg = cfg or {}
    if not veh or veh == 0 then return false end

    local wheelType = tonumber(cfg.wheelType or cfg.zentornoWheelType or 11) or 11
    local rimMod23 = tonumber(cfg.rimMod23 or cfg.frontWheelMod or cfg.wheelMod or 18) or 18
    local wheelColor = tonumber(cfg.wheelColor or cfg.zentornoWheelColor or 0) or 0
    local pearlescentColor = tonumber(cfg.pearlescentColor or cfg.pearlColor or 0) or 0

    DG_ZENTORNO_LOG("v6.13.62A1 wheel debug step logs: applying mod kit -> wheel type -> mod23 -> wheel color")
    DG_ZENTORNO_SET_MOD_KIT(veh)

    DG_ZENTORNO_SET_WHEEL_TYPE(veh, wheelType)

    DG_ZENTORNO_SET_MOD(veh, 23, rimMod23, false)

    DG_ZENTORNO_SET_WHEEL_COLOR(veh, pearlescentColor, wheelColor)

    if DG and driftgod.Log then
        driftgod.Log("[Spawn] Zentorno final wheel apply executed")
    end

    if DG and driftgod.Log then
        driftgod.Log("[Spawn] Zentorno wheel order applied: kit=0 wheelType=" .. tostring(wheelType) .. " mod23=" .. tostring(rimMod23) .. " wheelColor=" .. tostring(wheelColor))
    end

    return true
end

