local function toast(msg, ms)
    if DG and driftgod.Toast then driftgod.Toast(tostring(msg), ms or 1500)
    elseif GUI and GUI.AddToast then GUI.AddToast("DriftGod", tostring(msg), ms or 1500) end
end

local function log(msg)
    if not DG_SPAWN_DEBUG_ENABLED() then return end
    if DG and driftgod.Log then driftgod.Log("[Spawn] " .. tostring(msg))
    elseif Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] [Spawn] " .. tostring(msg)) end
end

local function unpackVec3(a, b, c, dx, dy, dz)
    if type(a) == "table" then
        return tonumber(a.x or a.X or a[1]) or dx,
               tonumber(a.y or a.Y or a[2]) or dy,
               tonumber(a.z or a.Z or a[3]) or dz
    end
    if type(a) == "userdata" then
        local okx, x = driftgod.Try(function() return a.x or a.X end)
        local oky, y = driftgod.Try(function() return a.y or a.Y end)
        local okz, z = driftgod.Try(function() return a.z or a.Z end)
        if okx or oky or okz then return tonumber(x) or dx, tonumber(y) or dy, tonumber(z) or dz end
    end
    return tonumber(a) or dx, tonumber(b) or dy, tonumber(c) or dz
end

local function getPed()
    local ped = 0
    driftgod.Try(function()
        if PLAYER and PLAYER.PLAYER_PED_ID then ped = PLAYER.PLAYER_PED_ID()
        elseif Natives and Natives.InvokeInt then ped = Natives.InvokeInt(NATIVE_PLAYER_PED_ID) end
    end)
    return tonumber(ped) or 0
end

local function getCoords(entity)
    local x, y, z = 0.0, 0.0, 0.0
    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_COORDS then
            local a, b, c = ENTITY.GET_ENTITY_COORDS(entity, true)
            x, y, z = unpackVec3(a, b, c, x, y, z)
        elseif Natives and Natives.InvokeV3 then
            local a, b, c = Natives.InvokeV3(NATIVE_GET_ENTITY_COORDS, entity, true)
            x, y, z = unpackVec3(a, b, c, x, y, z)
        end
    end)
    return x, y, z
end

local function getHeading(entity)
    local heading = 0.0
    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_HEADING then heading = ENTITY.GET_ENTITY_HEADING(entity)
        elseif Natives and Natives.InvokeFloat then heading = Natives.InvokeFloat(NATIVE_GET_ENTITY_HEADING, entity) end
    end)
    return tonumber(heading) or 0.0
end

local function resolveZentornoHash()
    local h = nil
    driftgod.Try(function()
        if Utils and Utils.Joaat then h = Utils.Joaat(ZENTORNO.modelName or "zentorno") end
    end)
    h = tonumber(h or ZENTORNO.model or -1403128555) or -1403128555

    if h > 2147483647 then h = h - 4294967296 end
    return h
end

local function unsignedHash(h)
    h = tonumber(h or 0) or 0
    if h < 0 then return h + 4294967296 end
    return h
end

local function requestModel(hash)
    if not hash or hash == 0 then return false end
    driftgod.Try(function()
        if STREAMING and STREAMING.REQUEST_MODEL then STREAMING.REQUEST_MODEL(hash)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_REQUEST_MODEL, hash) end
    end)
    local loaded = false
    for _ = 1, 120 do
        driftgod.Try(function()
            if STREAMING and STREAMING.HAS_MODEL_LOADED then loaded = STREAMING.HAS_MODEL_LOADED(hash)
            elseif Natives and Natives.InvokeBool then loaded = Natives.InvokeBool(NATIVE_HAS_MODEL_LOADED, hash) end
        end)
        if loaded then return true end
        if Script and Script.Yield then Script.Yield(0) end
    end
    return loaded == true
end

local function setModelDone(hash)
    driftgod.Try(function()
        if STREAMING and STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED then STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(hash)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_MODEL_AS_NO_LONGER_NEEDED, hash) end
    end)
end

local function createVehicle(hash, x, y, z, heading)

    local gtaAttempts = {
        { label = "GTA.SpawnVehicle signed", fn = function()
            if GTA and GTA.SpawnVehicle then return GTA.SpawnVehicle(hash, x + 0.0, y + 0.0, z + 0.0, heading + 0.0, true, true) end
            return 0
        end },
        { label = "GTA.SpawnVehicle unsigned", fn = function()
            if GTA and GTA.SpawnVehicle then return GTA.SpawnVehicle(unsignedHash(hash), x + 0.0, y + 0.0, z + 0.3, heading + 0.0, true, true) end
            return 0
        end },
        { label = "GTA.SpawnVehicleForPlayer signed", fn = function()
            local pid = 0
            driftgod.Try(function() if PLAYER and PLAYER.PLAYER_ID then pid = PLAYER.PLAYER_ID() end end)
            if GTA and GTA.SpawnVehicleForPlayer then return GTA.SpawnVehicleForPlayer(hash, pid, 6.0) end
            return 0
        end },
        { label = "GTA.SpawnVehicleForPlayer model", fn = function()
            local pid = 0
            driftgod.Try(function() if PLAYER and PLAYER.PLAYER_ID then pid = PLAYER.PLAYER_ID() end end)
            if GTA and GTA.SpawnVehicleForPlayer then return GTA.SpawnVehicleForPlayer("zentorno", pid, 6.0) end
            return 0
        end },
    }

    for _, a in ipairs(gtaAttempts) do
        local veh = 0
        local ok, err = driftgod.Try(function() veh = a.fn() end)
        veh = tonumber(veh) or 0
        if veh ~= 0 then
            log("CREATE_VEHICLE success via " .. tostring(a.label) .. " veh=" .. tostring(veh))
            return veh
        end
        if ok ~= true then log("CREATE_VEHICLE helper failed via " .. tostring(a.label) .. ": " .. tostring(err)) end
    end

    local attempts = {
        { h = hash,                 network = true,  scriptHost = true,  p7 = false, dz = 0.0, label = "signed network+script" },
        { h = hash,                 network = true,  scriptHost = false, p7 = false, dz = 0.3, label = "signed network" },
        { h = hash,                 network = false, scriptHost = false, p7 = false, dz = 0.6, label = "signed local" },
        { h = hash,                 network = false, scriptHost = true,  p7 = false, dz = 0.9, label = "signed local+script" },
        { h = unsignedHash(hash),   network = true,  scriptHost = true,  p7 = false, dz = 1.2, label = "unsigned network+script" },
        { h = unsignedHash(hash),   network = false, scriptHost = false, p7 = true,  dz = 1.5, label = "unsigned local p7" },
    }

    for _, a in ipairs(attempts) do
        local veh = 0
        local ok, err = driftgod.Try(function()
            local sx, sy, sz = x + 0.0, y + 0.0, z + (tonumber(a.dz or 0) or 0)
            if VEHICLE and VEHICLE.CREATE_VEHICLE then
                veh = VEHICLE.CREATE_VEHICLE(a.h, sx, sy, sz, heading + 0.0, a.network == true, a.scriptHost == true, a.p7 == true)
            elseif Natives and Natives.InvokeInt then
                veh = Natives.InvokeInt(NATIVE_CREATE_VEHICLE, a.h, sx, sy, sz, heading + 0.0, a.network == true, a.scriptHost == true, a.p7 == true)
            end
        end)

        veh = tonumber(veh) or 0
        if veh ~= 0 then
            log("CREATE_VEHICLE success via " .. tostring(a.label) .. " veh=" .. tostring(veh))
            return veh
        end

        if not ok then
            log("CREATE_VEHICLE attempt error via " .. tostring(a.label) .. ": " .. tostring(err))
        else
            log("CREATE_VEHICLE returned 0 via " .. tostring(a.label))
        end

        if Script and Script.Yield then Script.Yield(50) end
    end

    return 0
end

local function setMissionEntity(ent)
    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_AS_MISSION_ENTITY then ENTITY.SET_ENTITY_AS_MISSION_ENTITY(ent, true, true)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_ENTITY_AS_MISSION_ENTITY, ent, true, true) end
    end)
end

local function putPedInVehicle(ped, veh)
    driftgod.Try(function()
        if PED and PED.SET_PED_INTO_VEHICLE then PED.SET_PED_INTO_VEHICLE(ped, veh, -1)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_PED_INTO_VEHICLE, ped, veh, -1) end
    end)
end

local function setMod(veh, modType, idx, variation)
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD then VEHICLE.SET_VEHICLE_MOD(veh, modType, idx, variation == true)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_MOD, veh, modType, idx, variation == true) end
    end)
end

local function toggleMod(veh, modType, enabled)
    driftgod.Try(function()
        if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then VEHICLE.TOGGLE_VEHICLE_MOD(veh, modType, enabled == true)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_TOGGLE_VEHICLE_MOD, veh, modType, enabled == true) end
    end)
end

local function getVehicleModCountSafe(veh, modType)
    veh = tonumber(veh or 0) or 0
    modType = tonumber(modType or -1) or -1
    if veh == 0 or modType < 0 then return -1 end
    local count = -1
    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_NUM_VEHICLE_MODS then
            count = tonumber(VEHICLE.GET_NUM_VEHICLE_MODS(veh, modType)) or -1
        elseif Natives and Natives.InvokeInt then
            count = tonumber(Natives.InvokeInt(0xE38E9162A2500646, veh, modType)) or -1
        end
    end)
    return count
end

local function setModToMaxOrFallback(veh, modType, fallbackIndex, variation)
    local count = getVehicleModCountSafe(veh, modType)
    local idx = tonumber(fallbackIndex or -1) or -1
    if count and count > 0 then idx = count - 1 end
    setMod(veh, modType, idx, variation == true)
    return idx
end

local function setModFromEndOrFallback(veh, modType, fromLastOneBased, fallbackIndex, variation)

    local count = getVehicleModCountSafe(veh, modType)
    local idx = tonumber(fallbackIndex or -1) or -1
    local n = tonumber(fromLastOneBased or 1) or 1
    if count and count > 0 and count >= n then idx = count - n end
    setMod(veh, modType, idx, variation == true)
    return idx
end

local function applyToreroXOPostSpawnPass(veh, label)
    veh = tonumber(veh or 0) or 0
    if veh == 0 then return false end
    label = tostring(label or "torero")

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then VEHICLE.SET_VEHICLE_MOD_KIT(veh, 0)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_MOD_KIT, veh, 0) end
    end)

    setMod(veh, 0, -1, false)
    setMod(veh, 1, -1, false)
    setMod(veh, 2, 0, false)
    setMod(veh, 3, -1, false)
    setModFromEndOrFallback(veh, 4, 3, 12, false)
    setMod(veh, 5, 0, false)

    setMod(veh, 6, 2, false)
    setMod(veh, 8, -1, false)
    setMod(veh, 9, -1, false)
    setMod(veh, 7, 2, false)
    setMod(veh, 10, -1, false)
    setMod(veh, 37, 3, false)
    setMod(veh, 23, -1, false)
    setMod(veh, 24, -1, false)
    setMod(veh, 48, -1, false)

    setMod(veh, 25, -1, false)
    setMod(veh, 26, -1, false)
    setMod(veh, 27, -1, false)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then VEHICLE.SET_VEHICLE_WHEEL_TYPE(veh, 0)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_WHEEL_TYPE, veh, 0) end
    end)

    setModToMaxOrFallback(veh, 11, 3, false)
    setModToMaxOrFallback(veh, 12, 2, false)
    setModToMaxOrFallback(veh, 13, 2, false)
    setModToMaxOrFallback(veh, 15, 3, false)
    setModToMaxOrFallback(veh, 16, 4, false)
    setModToMaxOrFallback(veh, 14, 5, false)

    toggleMod(veh, 18, true)
    toggleMod(veh, 20, true)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WINDOW_TINT then VEHICLE.SET_VEHICLE_WINDOW_TINT(veh, 1)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_WINDOW_TINT, veh, 1) end
    end)

    if DG_SPAWN_DEBUG_ENABLED() and DG and driftgod.Log then
        driftgod.Log("[Spawn] Torero XO post-spawn cleanup applied | pass=" .. label)
    end
    return true
end

local function applyVehicleMods(veh, cfg)
    if not veh or veh == 0 then return end

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then VEHICLE.SET_VEHICLE_MOD_KIT(veh, 0)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_MOD_KIT, veh, 0) end
    end)

    for modType, _ in pairs(cfg.stockVisualMods or {}) do
        setMod(veh, modType, -1, false)
    end

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then VEHICLE.SET_VEHICLE_WHEEL_TYPE(veh, cfg.wheelType or 11)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_WHEEL_TYPE, veh, cfg.wheelType or 11) end
    end)

    for modType, mod in pairs(cfg.mods or {}) do
        if not (cfg.stockVisualMods and cfg.stockVisualMods[tonumber(modType)]) then
            setMod(veh, modType, tonumber(mod.index or -1) or -1, mod.variation == true)
        end
    end

    toggleMod(veh, 22, true)
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_XENON_LIGHT_COLOR_INDEX then
            VEHICLE.SET_VEHICLE_XENON_LIGHT_COLOR_INDEX(veh, 0)
        elseif Natives and Natives.InvokeVoid then
            Natives.InvokeVoid(NATIVE_SET_VEHICLE_XENON_LIGHT_COLOR_INDEX, veh, 0)
        end
    end)

    for _, modType in ipairs({18, 20}) do
        local mod = cfg.mods and cfg.mods[modType]
        if mod and tonumber(mod.index or 0) == 1 then
            toggleMod(veh, modType, true)
        end
    end
end

local function applyVehicleColors(veh, cfg)
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then VEHICLE.SET_VEHICLE_COLOURS(veh, cfg.primaryColor or 89, cfg.secondaryColor or 89)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_COLOURS, veh, cfg.primaryColor or 89, cfg.secondaryColor or 89) end
    end)
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then VEHICLE.SET_VEHICLE_EXTRA_COLOURS(veh, cfg.pearlescentColor or 32, cfg.wheelColor or 0)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_EXTRA_COLOURS, veh, cfg.pearlescentColor or 32, cfg.wheelColor or 0) end
    end)

    local cp = cfg.customPrimaryColor or { r = 13, g = 6, b = 32 }
    local cs = cfg.customSecondaryColor or { r = 13, g = 6, b = 32 }
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(veh, cp.r, cp.g, cp.b)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_CUSTOM_PRIMARY_COLOUR, veh, cp.r, cp.g, cp.b) end
    end)
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(veh, cs.r, cs.g, cs.b)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_CUSTOM_SECONDARY_COLOUR, veh, cs.r, cs.g, cs.b) end
    end)

    local smoke = cfg.tyreSmokeColor or { r = 81, g = 0, b = 81 }
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR then VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR(veh, smoke.r, smoke.g, smoke.b)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_TYRE_SMOKE_COLOR, veh, smoke.r, smoke.g, smoke.b) end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_WINDOW_TINT then VEHICLE.SET_VEHICLE_WINDOW_TINT(veh, cfg.windowTint or 2)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_WINDOW_TINT, veh, cfg.windowTint or 2) end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_INTERIOR_COLOUR then VEHICLE.SET_VEHICLE_INTERIOR_COLOUR(veh, cfg.interiorColor or 0)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_INTERIOR_COLOUR, veh, cfg.interiorColor or 0) end
    end)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_DASHBOARD_COLOUR then VEHICLE.SET_VEHICLE_DASHBOARD_COLOUR(veh, cfg.dashBoardColor or 0)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_DASHBOARD_COLOUR, veh, cfg.dashBoardColor or 0) end
    end)
end

local function applyVehicleExtras(veh, cfg)
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX(veh, cfg.plateTextIndex or 1)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX, veh, cfg.plateTextIndex or 1) end
    end)
    driftgod.Try(function()
        local plateText = cfg.plateText
        if (plateText == nil or tostring(plateText) == "") and driftgod.S and driftgod.S.driftGodPlateEnabled == true and driftgod.S.autoPlateEnabled == true then
            plateText = driftgod.PlateText or "DRIFTGOD"
        end
        if plateText ~= nil and tostring(plateText) ~= "" then
            if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT(veh, tostring(plateText))
            elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_NUMBER_PLATE_TEXT, veh, tostring(plateText)) end
        end
    end)

    local neon = cfg.neon or {}
    local neonMap = { neon.left, neon.right, neon.front, neon.back }
    for i = 1, 4 do
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_NEON_LIGHT_ENABLED then VEHICLE.SET_VEHICLE_NEON_LIGHT_ENABLED(veh, i - 1, neonMap[i] == true)
            elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_NEON_LIGHT_ENABLED, veh, i - 1, neonMap[i] == true) end
        end)
    end

    local nc = cfg.neonColor or { r = 255, g = 0, b = 255 }
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_NEON_COLOUR then VEHICLE.SET_VEHICLE_NEON_COLOUR(veh, nc.r, nc.g, nc.b)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_VEHICLE_NEON_COLOUR, veh, nc.r, nc.g, nc.b) end
    end)
end

local function applyZentornoFullStylePass(veh, label)
    veh = tonumber(veh or 0) or 0
    if veh == 0 then return false end

    label = tostring(label or "style")

    applyVehicleColors(veh, ZENTORNO)
    applyVehicleMods(veh, ZENTORNO)
    applyVehicleExtras(veh, ZENTORNO)

    if driftgod.ApplyZentornoFinalWheels then
        driftgod.ApplyZentornoFinalWheels(veh, ZENTORNO.pearlescentColor, ZENTORNO.wheelColor)
    end

    applyVehicleColors(veh, ZENTORNO)
    applyVehicleExtras(veh, ZENTORNO)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_DIRT_LEVEL then
            VEHICLE.SET_VEHICLE_DIRT_LEVEL(veh, 0.0)
        elseif Natives and Natives.InvokeVoid then
            Natives.InvokeVoid(NATIVE_SET_VEHICLE_DIRT_LEVEL, veh, 0.0)
        end
    end)

    if DG_SPAWN_DEBUG_ENABLED() and DG and driftgod.Log then
        driftgod.Log("[Spawn] Zentorno style reapplied | pass=" .. label .. " | primary=" .. tostring(ZENTORNO.primaryColor) .. " secondary=" .. tostring(ZENTORNO.secondaryColor) .. " pearl=" .. tostring(ZENTORNO.pearlescentColor) .. " wheel=" .. tostring(ZENTORNO.wheelColor))
    end
    return true
end

function driftgod.ApplyZentornoFullStyle(veh, source)
    source = tostring(source or "manual")
    local okNow = applyZentornoFullStylePass(veh, source .. ":now")

    if Script and Script.QueueJob then
        Script.QueueJob(function()
            if Script and Script.Yield then Script.Yield(250) end
            applyZentornoFullStylePass(veh, source .. ":250ms")
            if Script and Script.Yield then Script.Yield(750) end
            applyZentornoFullStylePass(veh, source .. ":1000ms")
            if Script and Script.Yield then Script.Yield(1000) end
            applyZentornoFullStylePass(veh, source .. ":2000ms")
        end)
    end

    return okNow
end

local function ghostInvokeVoid(hash, ...)

    local args = { ... }
    local ok = driftgod.Try(function()
        if Natives and Natives.InvokeVoid then
            local unpackFn = (table and table.unpack) or unpack
            Natives.InvokeVoid(hash, unpackFn(args))
        end
    end)
    return ok == true
end

function driftgod.ApplyGhostStyleToVehicle(veh, opts)
    veh = tonumber(veh or 0) or 0
    opts = opts or {}
    if veh == 0 then
        log("Ghost style failed: invalid vehicle handle")
        return false
    end

    local alpha = tonumber(opts.alpha or 145) or 145
    local invisible = opts.invisible == true
    local noCollision = opts.noCollision ~= false
    local frozen = opts.frozen ~= false

    local results = {}

    local function try(label, fn)
        local ok = driftgod.Try(fn)
        table.insert(results, label .. "=" .. tostring(ok))
        return ok
    end

    try("mission", function() setMissionEntity(veh) end)

    try("alpha", function()
        if invisible then
            if ENTITY and ENTITY.SET_ENTITY_VISIBLE then ENTITY.SET_ENTITY_VISIBLE(veh, false, false)
            else ghostInvokeVoid(NATIVE_SET_ENTITY_VISIBLE, veh, false, false) end
        else
            if ENTITY and ENTITY.SET_ENTITY_ALPHA then ENTITY.SET_ENTITY_ALPHA(veh, alpha, false)
            else ghostInvokeVoid(NATIVE_SET_ENTITY_ALPHA, veh, alpha, false) end
            if ENTITY and ENTITY.SET_ENTITY_VISIBLE then ENTITY.SET_ENTITY_VISIBLE(veh, true, false)
            else ghostInvokeVoid(NATIVE_SET_ENTITY_VISIBLE, veh, true, false) end
        end
    end)

    if noCollision then
        try("collision", function()
            if ENTITY and ENTITY.SET_ENTITY_COLLISION then ENTITY.SET_ENTITY_COLLISION(veh, false, false)
            else ghostInvokeVoid(NATIVE_SET_ENTITY_COLLISION, veh, false, false) end
        end)

        try("collisionFull", function()
            if ENTITY and ENTITY.SET_ENTITY_COMPLETELY_DISABLE_COLLISION then ENTITY.SET_ENTITY_COMPLETELY_DISABLE_COLLISION(veh, false, false)
            else ghostInvokeVoid(NATIVE_SET_ENTITY_COMPLETELY_DISABLE_COLLISION, veh, false, false) end
        end)
    end

    if frozen then
        try("freeze", function()
            if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true)
            else ghostInvokeVoid(NATIVE_FREEZE_ENTITY_POSITION, veh, true) end
        end)
    end

    try("invincible", function()
        if ENTITY and ENTITY.SET_ENTITY_INVINCIBLE then ENTITY.SET_ENTITY_INVINCIBLE(veh, true)
        else ghostInvokeVoid(NATIVE_SET_ENTITY_INVINCIBLE, veh, true) end
    end)

    try("engineOff", function()
        if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then VEHICLE.SET_VEHICLE_ENGINE_ON(veh, false, true, true)
        else ghostInvokeVoid(NATIVE_SET_VEHICLE_ENGINE_ON, veh, false, true, true) end
    end)

    try("locked", function()
        if VEHICLE and VEHICLE.SET_VEHICLE_DOORS_LOCKED then VEHICLE.SET_VEHICLE_DOORS_LOCKED(veh, 10)
        else ghostInvokeVoid(NATIVE_SET_VEHICLE_DOORS_LOCKED, veh, 10) end
    end)

    try("bulletproof", function()
        if VEHICLE and VEHICLE.SET_VEHICLE_TYRES_CAN_BURST then VEHICLE.SET_VEHICLE_TYRES_CAN_BURST(veh, false)
        else ghostInvokeVoid(NATIVE_SET_VEHICLE_TYRES_CAN_BURST, veh, false) end
    end)

    try("clean", function()
        if VEHICLE and VEHICLE.SET_VEHICLE_DIRT_LEVEL then VEHICLE.SET_VEHICLE_DIRT_LEVEL(veh, 0.0)
        else ghostInvokeVoid(NATIVE_SET_VEHICLE_DIRT_LEVEL, veh, 0.0) end
    end)

    try("purplePaint", function()
        if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(veh, 120, 80, 255)
        else Natives.InvokeVoid(NATIVE_SET_VEHICLE_CUSTOM_PRIMARY_COLOUR, veh, 120, 80, 255) end
        if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(veh, 40, 0, 80)
        else Natives.InvokeVoid(NATIVE_SET_VEHICLE_CUSTOM_SECONDARY_COLOUR, veh, 40, 0, 80) end
    end)

    try("neon", function()
        for i = 0, 3 do
            if VEHICLE and VEHICLE.SET_VEHICLE_NEON_LIGHT_ENABLED then VEHICLE.SET_VEHICLE_NEON_LIGHT_ENABLED(veh, i, true)
            else Natives.InvokeVoid(NATIVE_SET_VEHICLE_NEON_LIGHT_ENABLED, veh, i, true) end
        end
        if VEHICLE and VEHICLE.SET_VEHICLE_NEON_COLOUR then VEHICLE.SET_VEHICLE_NEON_COLOUR(veh, 120, 80, 255)
        else Natives.InvokeVoid(NATIVE_SET_VEHICLE_NEON_COLOUR, veh, 120, 80, 255) end
    end)

    log("Ghost style bridge applied veh=" .. tostring(veh) .. " | " .. table.concat(results, " | "))
    return true
end

function driftgod.SpawnGhostPreviewBridge(model, label, opts)
    opts = opts or {}
    label = tostring(label or "ghost preview")
    local ped = getPed()
    if ped == 0 then
        log("Ghost preview failed: no player ped")
        return 0
    end

    local hash = tonumber(model or 0) or 0
    if hash == 0 then
        log("Ghost preview failed: invalid model for " .. label)
        return 0
    end

    if hash > 2147483647 then hash = hash - 4294967296 end

    if not requestModel(hash) then
        local uh = unsignedHash(hash)
        if uh ~= hash and requestModel(uh) then
            hash = uh
        else
            log("Ghost preview failed: model not loaded hash=" .. tostring(hash) .. " label=" .. label)
            return 0
        end
    end

    local x, y, z = getCoords(ped)
    local heading = getHeading(ped)
    local rad = math.rad(heading)
    local sx = x + math.sin(-rad) * tonumber(opts.forward or 7.5)
    local sy = y + math.cos(rad) * tonumber(opts.forward or 7.5)
    local sz = z + tonumber(opts.zOffset or 0.55)

    local veh = createVehicle(hash, sx, sy, sz, heading)
    if veh == 0 then
        log("Ghost preview failed: create returned 0 | hash=" .. tostring(hash) .. " label=" .. label)
        setModelDone(hash)
        return 0
    end

    setMissionEntity(veh)
    driftgod.ApplyGhostStyleToVehicle(veh, opts)

    driftgod.S = driftgod.S or {}
    driftgod.S.ghostReplayPreviewVehicle = veh
    driftgod.S.ghostReplayPreviewVehicleModel = hash
    driftgod.S.ghostReplayPreviewLabel = label

    setModelDone(hash)
    toast("Spawned ghost preview", 1500)
    log("Ghost preview bridge spawned veh=" .. tostring(veh) .. " hash=" .. tostring(hash) .. " label=" .. label)
    return veh
end

function driftgod.DeleteGhostPreviewBridge()
    driftgod.S = driftgod.S or {}
    local veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0
    if veh == 0 then
        log("Ghost preview delete skipped: no tracked handle")
        return false
    end

    local ok = driftgod.Try(function()
        if ENTITY and ENTITY.DELETE_ENTITY then ENTITY.DELETE_ENTITY(veh)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_DELETE_ENTITY, veh) end
    end)

    driftgod.S.ghostReplayPreviewVehicle = 0
    driftgod.S.ghostReplayPreviewVehicleModel = 0
    driftgod.S.ghostReplayPreviewLabel = ""

    log("Ghost preview bridge delete veh=" .. tostring(veh) .. " ok=" .. tostring(ok))
    return ok == true
end

function driftgod.MoveGhostPreviewBridge(veh, x, y, z, heading)
    veh = tonumber(veh or 0) or tonumber(driftgod.S and driftgod.S.ghostReplayPreviewVehicle or 0) or 0
    if veh == 0 then return false end

    local ok1 = driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_COORDS_NO_OFFSET then ENTITY.SET_ENTITY_COORDS_NO_OFFSET(veh, x + 0.0, y + 0.0, z + 0.0, false, false, false)
        elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_ENTITY_COORDS_NO_OFFSET, veh, x + 0.0, y + 0.0, z + 0.0, false, false, false) end
    end)

    local ok2 = driftgod.Try(function()
        if heading ~= nil then
            if ENTITY and ENTITY.SET_ENTITY_HEADING then ENTITY.SET_ENTITY_HEADING(veh, heading + 0.0)
            elseif Natives and Natives.InvokeVoid then Natives.InvokeVoid(NATIVE_SET_ENTITY_HEADING, veh, heading + 0.0) end
        end
    end)

    return ok1 == true and ok2 == true
end

function driftgod.SpawnZentorno()
    local ped = getPed()
    if ped == 0 then toast("Spawn failed: no player ped", 1800); return 0 end

    local hash = resolveZentornoHash()
    if not requestModel(hash) then
        toast("Spawn failed: Zentorno model not loaded", 2200)
        log("model request failed hash=" .. tostring(hash))
        local uh = unsignedHash(hash)
        if uh ~= hash and requestModel(uh) then hash = uh else return 0 end
    end

    local x, y, z = getCoords(ped)
    local heading = getHeading(ped)
    local rad = math.rad(heading)
    local sx = x + math.sin(-rad) * 6.0
    local sy = y + math.cos(rad) * 6.0
    local sz = z + 0.5

    local veh = createVehicle(hash, sx, sy, sz, heading)
    if veh == 0 then
        toast("Spawn failed: create vehicle returned 0", 2200)
        log("CREATE_VEHICLE failed all attempts. hash=" .. tostring(hash) .. " coords=" .. tostring(sx) .. "," .. tostring(sy) .. "," .. tostring(sz) .. " heading=" .. tostring(heading))
        setModelDone(hash)
        return 0
    end

    setMissionEntity(veh)

    if driftgod.ApplyZentornoFullStyle then
        driftgod.ApplyZentornoFullStyle(veh, "spawn")
    else
        applyVehicleMods(veh, ZENTORNO)
        applyVehicleColors(veh, ZENTORNO)
        applyVehicleExtras(veh, ZENTORNO)
        if driftgod.ApplyZentornoFinalWheels then driftgod.ApplyZentornoFinalWheels(veh, ZENTORNO.pearlescentColor, ZENTORNO.wheelColor) end
    end

    setModelDone(hash)

    toast("Spawned custom Zentorno", 1600)
    log("Spawned Zentorno details veh=" .. tostring(veh) .. " style=full-reapply primary=89 secondary=89 pearl=32 wheelColor=0 wheelType=Street(11) wheelMod=17")
    return veh
end

local function resolveVehicleConfigHash(cfg)
    cfg = cfg or {}
    local h = nil
    driftgod.Try(function()
        if cfg.modelName and Utils and Utils.Joaat then h = Utils.Joaat(cfg.modelName) end
    end)
    h = tonumber(h or cfg.model or 0) or 0
    if h > 2147483647 then h = h - 4294967296 end
    return h
end

local function applyConfiguredVehicleStylePass(veh, cfg, label)
    veh = tonumber(veh or 0) or 0
    if veh == 0 or type(cfg) ~= "table" then return false end
    label = tostring(label or "style")

    applyVehicleColors(veh, cfg)
    applyVehicleMods(veh, cfg)
    if cfg == TOREROXO then
        applyToreroXOPostSpawnPass(veh, label)
    end
    applyVehicleExtras(veh, cfg)
    applyVehicleColors(veh, cfg)
    if cfg == TOREROXO then
        applyToreroXOPostSpawnPass(veh, label .. ":final")
    end
    applyVehicleExtras(veh, cfg)

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_DIRT_LEVEL then
            VEHICLE.SET_VEHICLE_DIRT_LEVEL(veh, 0.0)
        elseif Natives and Natives.InvokeVoid then
            Natives.InvokeVoid(NATIVE_SET_VEHICLE_DIRT_LEVEL, veh, 0.0)
        end
    end)

    if DG_SPAWN_DEBUG_ENABLED() and DG and driftgod.Log then
        driftgod.Log("[Spawn] configured vehicle style applied | " .. label .. " | veh=" .. tostring(veh))
    end
    return true
end

function driftgod.ApplyConfiguredVehicleFullStyle(veh, cfg, source)
    source = tostring(source or "manual")
    local okNow = applyConfiguredVehicleStylePass(veh, cfg, source .. ":now")

    if Script and Script.QueueJob then
        Script.QueueJob(function()
            if Script and Script.Yield then Script.Yield(250) end
            applyConfiguredVehicleStylePass(veh, cfg, source .. ":250ms")
            if Script and Script.Yield then Script.Yield(750) end
            applyConfiguredVehicleStylePass(veh, cfg, source .. ":1000ms")
            if Script and Script.Yield then Script.Yield(1000) end
            applyConfiguredVehicleStylePass(veh, cfg, source .. ":2000ms")
        end)
    end

    return okNow
end

function driftgod.SpawnConfiguredVehicle(cfg, label)
    cfg = cfg or {}
    label = tostring(label or cfg.displayName or cfg.modelName or "Vehicle")

    local ped = getPed()
    if ped == 0 then toast("Spawn failed: no player ped", 1800); return 0 end

    local hash = resolveVehicleConfigHash(cfg)
    if hash == 0 then toast("Spawn failed: invalid " .. label .. " model", 2200); return 0 end

    if not requestModel(hash) then
        toast("Spawn failed: " .. label .. " model not loaded", 2200)
        log(label .. " model request failed hash=" .. tostring(hash))
        local uh = unsignedHash(hash)
        if uh ~= hash and requestModel(uh) then hash = uh else return 0 end
    end

    local x, y, z = getCoords(ped)
    local heading = getHeading(ped)
    local rad = math.rad(heading)
    local sx = x + math.sin(-rad) * 6.0
    local sy = y + math.cos(rad) * 6.0
    local sz = z + 0.5

    local veh = createVehicle(hash, sx, sy, sz, heading)
    if veh == 0 then
        toast("Spawn failed: " .. label .. " returned 0", 2200)
        log(label .. " CREATE_VEHICLE failed. hash=" .. tostring(hash))
        setModelDone(hash)
        return 0
    end

    setMissionEntity(veh)
    driftgod.ApplyConfiguredVehicleFullStyle(veh, cfg, label)
    setModelDone(hash)

    toast("Spawned " .. label, 1600)
    log("Spawned configured vehicle " .. label .. " veh=" .. tostring(veh) .. " hash=" .. tostring(hash))
    return veh
end

function driftgod.SpawnToreroXO()
    return driftgod.SpawnConfiguredVehicle(TOREROXO, "Torero XO")
end

function driftgod.TrySpawnToreroXO(source)
    source = tostring(source or "menu")
    if not driftgod.SpawnToreroXO then
        if driftgod.Toast then driftgod.Toast("Spawn failed: Torero XO unavailable", 2200) end
        return 0
    end
    local ok, veh = driftgod.Try(function() return driftgod.SpawnToreroXO() end)
    veh = tonumber(veh) or 0
    if ok ~= true then
        if driftgod.Log then driftgod.Log("[Spawn] Torero XO error from " .. source .. ": " .. tostring(veh)) end
        if driftgod.Toast then driftgod.Toast("Spawn failed: Torero XO error", 2200) end
        return 0
    end
    return veh
end

function driftgod.ReapplyZentornoWheelsToVehicle(veh)
    if not veh or veh == 0 then
        if driftgod.GetVehicle then veh = driftgod.GetVehicle() end
    end
    return DG_APPLY_ZENTORNO_WHEEL_ORDER(veh, { wheelType = 11, rimMod23 = 18, wheelColor = 0, pearlescentColor = 0 })
end

local function DG_ZENTORNO_GET_NUM_MODS(veh, modType)
    local ok, result = driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_NUM_VEHICLE_MODS then
            return VEHICLE.GET_NUM_VEHICLE_MODS(veh, modType)
        elseif Natives and Natives.InvokeInt then

            return Natives.InvokeInt(0xE38E9162A2500646, veh, modType)
        end
        return -1
    end)

    if ok then return tonumber(result) or -1 end
    return -1
end

local function DG_ZENTORNO_GET_MOD(veh, modType)
    local ok, result = driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_MOD then
            return VEHICLE.GET_VEHICLE_MOD(veh, modType)
        elseif Natives and Natives.InvokeInt then

            return Natives.InvokeInt(0x772960298DA26FDB, veh, modType)
        end
        return -999
    end)

    if ok then return tonumber(result) or -999 end
    return -999
end

local function DG_ZENTORNO_WAIT_TICK()
    driftgod.Try(function()
        if Script and Script.Yield then
            Script.Yield(0)
        elseif coroutine and coroutine.yield then
            coroutine.yield()
        end
    end)
end

local function DG_ZENTORNO_APPLY_WHEEL_COMBO(veh, wheelType, modIndex, wheelColor)
    wheelType = tonumber(wheelType or 11) or 11
    modIndex = tonumber(modIndex or 18) or 18
    wheelColor = tonumber(wheelColor or 0) or 0

    if not veh or veh == 0 then
        DG_ZENTORNO_LOG("No vehicle handle for wheel combo.")
        return false
    end

    DG_ZENTORNO_LOG("Trying combo: wheelType=" .. tostring(wheelType) .. " mod23=" .. tostring(modIndex) .. " wheelColor=" .. tostring(wheelColor))

    DG_ZENTORNO_SET_MOD_KIT(veh)
    DG_ZENTORNO_WAIT_TICK()

    DG_ZENTORNO_SET_WHEEL_TYPE(veh, wheelType)
    DG_ZENTORNO_WAIT_TICK()

    local count = DG_ZENTORNO_GET_NUM_MODS(veh, 23)
    DG_ZENTORNO_LOG("After wheelType=" .. tostring(wheelType) .. " numMods[23]=" .. tostring(count))

    DG_ZENTORNO_SET_MOD(veh, 23, modIndex, false)
    DG_ZENTORNO_WAIT_TICK()

    DG_ZENTORNO_SET_WHEEL_COLOR(veh, 0, wheelColor)
    DG_ZENTORNO_WAIT_TICK()

    local applied = DG_ZENTORNO_GET_MOD(veh, 23)
    DG_ZENTORNO_LOG("Applied check: GET_VEHICLE_MOD[23]=" .. tostring(applied))

    return true
end

function driftgod.ZentornoWheelProbeCurrent()
    local veh = nil

    if driftgod.GetVehicle then
        local ok, result = driftgod.Try(driftgod.GetVehicle)
        if ok then veh = result end
    end

    if (not veh or veh == 0) and PLAYER and PLAYER.PLAYER_PED_ID and PED and PED.GET_VEHICLE_PED_IS_IN then
        driftgod.Try(function()
            veh = PED.GET_VEHICLE_PED_IS_IN(PLAYER.PLAYER_PED_ID(), false)
        end)
    end

    if not veh or veh == 0 then
        DG_ZENTORNO_LOG("No current vehicle found.")
        return false
    end

    local tests = {
        { 11, 18, 0 },
        { 11, 17, 0 },
        { 11, 19, 0 },
        { 12, 18, 0 },
        { 7, 18, 0 },
    }

    for _, t in ipairs(tests) do
        DG_ZENTORNO_APPLY_WHEEL_COMBO(veh, t[1], t[2], t[3])
    end

    DG_ZENTORNO_LOG("Probe complete. Visually check which final combo remained.")
    return true
end

