local function DG_ZENTORNO_APPLY_METHOD(veh, label, wheelType, modIndex, customTires, passes, delayMs)
    if not veh or veh == 0 then
        DG_ZENTORNO_LOG(label .. " failed: no vehicle")
        return false
    end

    wheelType = tonumber(wheelType or 11) or 11
    modIndex = tonumber(modIndex or 18) or 18
    passes = tonumber(passes or 1) or 1
    delayMs = tonumber(delayMs or 0) or 0

    DG_ZENTORNO_LOG(label .. " start veh=" .. tostring(veh) .. " wheelType=" .. tostring(wheelType) .. " mod23=" .. tostring(modIndex) .. " customTires=" .. tostring(customTires == true))

    for pass = 1, passes do
        DG_ZENTORNO_MODKIT(veh)
        DG_ZENTORNO_YIELD(delayMs)

        DG_ZENTORNO_WHEELTYPE(veh, wheelType)
        DG_ZENTORNO_YIELD(delayMs)

        local count = DG_ZENTORNO_NUM_MODS(veh, 23)
        DG_ZENTORNO_LOG(label .. " pass " .. tostring(pass) .. " numMods23=" .. tostring(count))

        DG_ZENTORNO_SETMOD(veh, 23, modIndex, customTires == true)
        DG_ZENTORNO_YIELD(delayMs)

        DG_ZENTORNO_WHEELCOLOR(veh, 0, 0)
        DG_ZENTORNO_YIELD(delayMs)

        local applied = DG_ZENTORNO_GET_MOD(veh, 23)
        DG_ZENTORNO_LOG(label .. " pass " .. tostring(pass) .. " GET_MOD23=" .. tostring(applied))
    end

    return true
end

