local function vmLog(msg, force)
    msg = tostring(msg or "")
    local lower = msg:lower()
    local important = force == true
        or lower:find("error", 1, true) ~= nil
        or lower:find("failed", 1, true) ~= nil
        or lower:find("warning", 1, true) ~= nil

    if not important and driftgod.S and driftgod.S.vehicleMasteryDebugEnabled ~= true then return end

    if driftgod.Log then
        driftgod.Log("[VehicleMastery] " .. msg)
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] [VehicleMastery] " .. msg)
    end
end

function driftgod.VehicleMasteryEnsureDefaults()
    driftgod.S = driftgod.S or {}
    driftgod.S.vehicleMasteryEnabled = driftgod.S.vehicleMasteryEnabled ~= false
    driftgod.S.vehicleMasteryDebugEnabled = driftgod.S.vehicleMasteryDebugEnabled == true
    driftgod.S.vehicleMastery = driftgod.S.vehicleMastery or {}
    driftgod.S.vehicleMasteryRewards = driftgod.S.vehicleMasteryRewards or {}
    driftgod.S.vehicleMasteryLastVehicleKey = driftgod.S.vehicleMasteryLastVehicleKey or ""
end

function driftgod.SanitizeVehicleMasteryName(name)
    name = tostring(name or "")
    name = name:gsub("^%s+", ""):gsub("%s+$", "")

    local afterDash = name:match("%-%-%-%s*(.+)$")
    if afterDash and afterDash ~= "" then name = afterDash end

    name = name:gsub("%.json$", ""):gsub("%.ini$", "")
    name = name:gsub("_", " ")
    name = name:gsub("%s+", " ")

    if name == "" or name == "NULL" or name == "CARNOTFOUND" then name = "Current Vehicle" end
    return name
end

function driftgod.JoaatVehicleHash(modelName)
    local hash = 0
    local s = tostring(modelName or ""):lower()

    for i = 1, #s do
        hash = (hash + string.byte(s, i)) & 0xFFFFFFFF
        hash = (hash + ((hash << 10) & 0xFFFFFFFF)) & 0xFFFFFFFF
        hash = (hash ~ (hash >> 6)) & 0xFFFFFFFF
    end

    hash = (hash + ((hash << 3) & 0xFFFFFFFF)) & 0xFFFFFFFF
    hash = (hash ~ (hash >> 11)) & 0xFFFFFFFF
    hash = (hash + ((hash << 15) & 0xFFFFFFFF)) & 0xFFFFFFFF

    return hash & 0xFFFFFFFF
end

