function driftgod.BuildVehicleMasteryHashLookup()
    driftgod.VehicleMasteryHashToName = driftgod.VehicleMasteryHashToName or {}

    for modelName, prettyName in pairs(driftgod.VehicleMasteryKnownModels or {}) do
        local ok, hash = driftgod.Try(function()
            if GAMEPLAY and GAMEPLAY.GET_HASH_KEY then
                return GAMEPLAY.GET_HASH_KEY(modelName)
            elseif MISC and MISC.GET_HASH_KEY then
                return MISC.GET_HASH_KEY(modelName)
            elseif driftgod.JoaatVehicleHash then
                return driftgod.JoaatVehicleHash(modelName)
            end
            return nil
        end)

        if ok and hash then
            local unsigned = tonumber(hash)
            if unsigned then
                if unsigned < 0 then unsigned = unsigned + 4294967296 end
                driftgod.VehicleMasteryHashToName[tostring(unsigned)] = prettyName

                if unsigned > 2147483647 then
                    driftgod.VehicleMasteryHashToName[tostring(unsigned - 4294967296)] = prettyName
                end
            end
        end
    end
end

function driftgod.ResolveVehicleNameFromKnownHash(model)
    if not driftgod.VehicleMasteryHashToName then
        if driftgod.BuildVehicleMasteryHashLookup then driftgod.BuildVehicleMasteryHashLookup() end
    end

    local n = tonumber(model or 0) or 0
    if n == 0 then return nil end

    local direct = driftgod.VehicleMasteryHashToName and driftgod.VehicleMasteryHashToName[tostring(n)] or nil
    if direct then return direct end

    if n < 0 then
        local unsigned = n + 4294967296
        local alt = driftgod.VehicleMasteryHashToName and driftgod.VehicleMasteryHashToName[tostring(unsigned)] or nil
        if alt then return alt end
    elseif n > 2147483647 then
        local signed = n - 4294967296
        local alt = driftgod.VehicleMasteryHashToName and driftgod.VehicleMasteryHashToName[tostring(signed)] or nil
        if alt then return alt end
    end

    return nil
end

function driftgod.GetCurrentVehicleHandleForMastery()
    local veh = 0

    driftgod.Try(function()
        if PLAYER and PLAYER.PLAYER_PED_ID and PED and PED.GET_VEHICLE_PED_IS_IN then
            local ped = PLAYER.PLAYER_PED_ID()
            veh = PED.GET_VEHICLE_PED_IS_IN(ped, false) or 0
        end
    end)

    if (not veh or veh == 0) and driftgod.GetPlayerVehicle then
        driftgod.Try(function()
            veh = driftgod.GetPlayerVehicle() or 0
        end)
    end

    return veh or 0
end

function driftgod.GetVehicleModelForMastery(veh)
    veh = veh or (driftgod.GetCurrentVehicleHandleForMastery and driftgod.GetCurrentVehicleHandleForMastery() or 0)
    local model = 0

    if veh and veh ~= 0 then
        driftgod.Try(function()
            if ENTITY and ENTITY.GET_ENTITY_MODEL then
                model = ENTITY.GET_ENTITY_MODEL(veh) or 0
            end
        end)
    end

    return model or 0
end

function driftgod.ResolveVehicleDisplayNameFromModel(model)
    model = tonumber(model or 0) or 0
    if model == 0 then return nil end

    local displayLabel = nil
    local displayName = nil

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_DISPLAY_NAME_FROM_VEHICLE_MODEL then
            displayLabel = VEHICLE.GET_DISPLAY_NAME_FROM_VEHICLE_MODEL(model)
        end
    end)

    if displayLabel and tostring(displayLabel) ~= "" then
        driftgod.Try(function()
            if HUD and HUD.GET_LABEL_TEXT then
                displayName = HUD.GET_LABEL_TEXT(displayLabel)
            end
        end)

        if displayName and tostring(displayName) ~= "" and tostring(displayName) ~= "NULL" and tostring(displayName) ~= "CARNOTFOUND" then
            return driftgod.SanitizeVehicleMasteryName(displayName)
        end

        local labelText = tostring(displayLabel)
        if labelText ~= "" and labelText ~= "NULL" and labelText ~= "CARNOTFOUND" then
            return driftgod.SanitizeVehicleMasteryName(labelText)
        end
    end

    return nil
end

function driftgod.ProbeVehicleNameFromNatives()
    local veh = driftgod.GetCurrentVehicleHandleForMastery and driftgod.GetCurrentVehicleHandleForMastery() or 0
    local model = driftgod.GetVehicleModelForMastery and driftgod.GetVehicleModelForMastery(veh) or 0
    local name = driftgod.ResolveVehicleDisplayNameFromModel and driftgod.ResolveVehicleDisplayNameFromModel(model) or nil

    if name and name ~= "" and name ~= "Current Vehicle" then
        driftgod.SetVehicleMasteryCurrentVehicle(name, model)
        return name, model, veh
    end

    if model and model ~= 0 then

        local knownName = driftgod.ResolveVehicleNameFromKnownHash and driftgod.ResolveVehicleNameFromKnownHash(model) or nil
        if knownName and knownName ~= "" then
            driftgod.SetVehicleMasteryCurrentVehicle(knownName, model)
            return knownName, model, veh
        end

        driftgod.SetVehicleMasteryCurrentVehicle("Vehicle " .. tostring(model), model)
        return "Vehicle " .. tostring(model), model, veh
    end

    return nil, model, veh
end

function driftgod.SetVehicleMasteryCurrentVehicle(name, model)
    driftgod.VehicleMasteryEnsureDefaults()

    local cleanName = driftgod.SanitizeVehicleMasteryName and driftgod.SanitizeVehicleMasteryName(name) or tostring(name or "Current Vehicle")
    local modelText = tostring(model or "")

    driftgod.S.vehicleMasteryCurrentName = cleanName
    driftgod.S.vehicleMasteryCurrentModel = modelText

    if cleanName ~= "" and cleanName ~= "Current Vehicle" then
        driftgod.S.vehicleMasteryLastVehicleName = cleanName
    end

    if modelText ~= "" and modelText ~= "0" then
        driftgod.S.vehicleMasteryLastVehicleModel = modelText
    end
end

function driftgod.RefreshVehicleMasteryCurrentVehicle()
    local name, model, veh = driftgod.ProbeVehicleNameFromNatives and driftgod.ProbeVehicleNameFromNatives() or nil, 0, 0
    return name, model, veh
end

function driftgod.GetVehicleMasteryKey()
    driftgod.VehicleMasteryEnsureDefaults()

    if driftgod.ProbeVehicleNameFromNatives then
        driftgod.Try(function() driftgod.ProbeVehicleNameFromNatives() end)
    end

    local name = tostring(driftgod.S.vehicleMasteryCurrentName or driftgod.S.vehicleMasteryLastVehicleName or "")
    if name ~= "" and name ~= "Current Vehicle" then
        return "name:" .. name:lower():gsub("%s+", "_")
    end

    local model = tostring(driftgod.S.vehicleMasteryCurrentModel or driftgod.S.vehicleMasteryLastVehicleModel or "")
    if model ~= "" and model ~= "0" then
        return "model:" .. model
    end

    return "current_vehicle"
end

function driftgod.GetVehicleMasteryName()
    driftgod.VehicleMasteryEnsureDefaults()

    if driftgod.ProbeVehicleNameFromNatives then
        driftgod.Try(function() driftgod.ProbeVehicleNameFromNatives() end)
    end

    local name = tostring(driftgod.S.vehicleMasteryCurrentName or driftgod.S.vehicleMasteryLastVehicleName or "")
    if name ~= "" and name ~= "Current Vehicle" then return name end

    local model = tostring(driftgod.S.vehicleMasteryCurrentModel or driftgod.S.vehicleMasteryLastVehicleModel or "")
    if model ~= "" and model ~= "0" then return "Vehicle " .. model end

    return "Current Vehicle"
end

function driftgod.GetVehicleMasteryRecord(key)
    driftgod.VehicleMasteryEnsureDefaults()
    key = tostring(key or (driftgod.GetVehicleMasteryKey and driftgod.GetVehicleMasteryKey() or "current_vehicle"))

    driftgod.S.vehicleMastery[key] = driftgod.S.vehicleMastery[key] or {
        name = driftgod.GetVehicleMasteryName and driftgod.GetVehicleMasteryName() or key,
        totalScore = 0,
        bestScore = 0,
        runsBanked = 0,
        stuntsLanded = 0,
        masteryLevel = 1,
        title = "Discovered",
        unlockedRewards = {},
        lastUpdated = 0,
    }

    driftgod.S.vehicleMastery[key].name = driftgod.GetVehicleMasteryName and driftgod.GetVehicleMasteryName() or driftgod.S.vehicleMastery[key].name or key
    if driftgod.EnsureVehicleMasteryRewards then driftgod.EnsureVehicleMasteryRewards(driftgod.S.vehicleMastery[key], key) end
    return driftgod.S.vehicleMastery[key]
end

function driftgod.ComputeVehicleMasteryLevel(record)
    local total = tonumber(record.totalScore or 0) or 0
    local best = tonumber(record.bestScore or 0) or 0
    local runs = tonumber(record.runsBanked or 0) or 0
    local stunts = tonumber(record.stuntsLanded or 0) or 0

    local level = 1
    if total >= 5000 or best >= 2500 or runs >= 3 or stunts >= 5 then level = 2 end
    if total >= 25000 or best >= 10000 or runs >= 10 or stunts >= 20 then level = 3 end
    if total >= 75000 or best >= 25000 or runs >= 25 or stunts >= 50 then level = 4 end
    if total >= 150000 or best >= 50000 or runs >= 50 or stunts >= 100 then level = 5 end

    return level
end

driftgod.VehicleMasteryLevelTitles = driftgod.VehicleMasteryLevelTitles or {
    [1] = "Discovered",
    [2] = "Rookie Driver",
    [3] = "Skilled Driver",
    [4] = "Elite Driver",
    [5] = "Legendary Driver",
}

function driftgod.GetVehicleMasteryTitle(record)
    local level = tonumber(record and record.masteryLevel or 1) or 1
    if level < 1 then level = 1 end
    if level > 5 then level = 5 end
    return driftgod.VehicleMasteryLevelTitles[level] or "Discovered"
end

function driftgod.GetVehicleMasteryRewardKey(vehicleKey, level)
    return tostring(vehicleKey or "vehicle") .. "::level_" .. tostring(level or 1)
end

function driftgod.EnsureVehicleMasteryRewards(record, vehicleKey)
    driftgod.VehicleMasteryEnsureDefaults()
    if not record then return end

    driftgod.S.vehicleMasteryRewards = driftgod.S.vehicleMasteryRewards or {}

    local level = tonumber(record.masteryLevel or 1) or 1
    if level < 1 then level = 1 end
    if level > 5 then level = 5 end

    record.unlockedRewards = record.unlockedRewards or {}

    for i = 1, level do
        local rewardKey = driftgod.GetVehicleMasteryRewardKey(vehicleKey, i)
        if driftgod.S.vehicleMasteryRewards[rewardKey] ~= true then
            driftgod.S.vehicleMasteryRewards[rewardKey] = true
            record.unlockedRewards[i] = true
        end
    end

    record.title = driftgod.GetVehicleMasteryTitle(record)
end

function driftgod.AnnounceVehicleMasteryReward(record, vehicleKey, oldLevel, newLevel)
    if not record then return end

    local name = tostring(record.name or "Vehicle")
    local title = driftgod.GetVehicleMasteryTitle(record)

    if driftgod.Toast then
        driftgod.Toast(name .. " Mastery Level " .. tostring(newLevel) .. "/5: " .. title, 3500)
    end

    vmLog("Reward unlocked | " .. tostring(name)
        .. " | level=" .. tostring(newLevel)
        .. " | title=" .. tostring(title)
        .. " | key=" .. tostring(vehicleKey or ""), true)
end

function driftgod.UpdateVehicleMasteryLevel(record, key)
    if not record then return end

    local old = tonumber(record.masteryLevel or 1) or 1
    local new = driftgod.ComputeVehicleMasteryLevel and driftgod.ComputeVehicleMasteryLevel(record) or old
    record.masteryLevel = new

    if driftgod.EnsureVehicleMasteryRewards then
        driftgod.EnsureVehicleMasteryRewards(record, key)
    end

    if new > old then
        if driftgod.AnnounceVehicleMasteryReward then
            driftgod.AnnounceVehicleMasteryReward(record, key, old, new)
        else
            if driftgod.Toast then driftgod.Toast("Vehicle Mastery Level " .. tostring(new) .. " unlocked!", 3000) end
            vmLog("Level up | " .. tostring(key or "") .. " | " .. tostring(old) .. " -> " .. tostring(new), true)
        end
    end
end

function driftgod.RecordVehicleMasteryRun(score, reason)
    driftgod.VehicleMasteryEnsureDefaults()
    if driftgod.S.vehicleMasteryEnabled == false then return end

    score = math.floor(tonumber(score or 0) or 0)
    if score <= 0 then return end

    local key = driftgod.GetVehicleMasteryKey and driftgod.GetVehicleMasteryKey() or "current_vehicle"
    local record = driftgod.GetVehicleMasteryRecord(key)

    record.totalScore = math.floor((tonumber(record.totalScore or 0) or 0) + score)
    record.bestScore = math.max(tonumber(record.bestScore or 0) or 0, score)
    record.runsBanked = (tonumber(record.runsBanked or 0) or 0) + 1
    record.lastUpdated = os and os.time and os.time() or 0

    driftgod.UpdateVehicleMasteryLevel(record, key)
    vmLog("Run banked | key=" .. tostring(key) .. " | +" .. tostring(score) .. " | total=" .. tostring(record.totalScore) .. " | reason=" .. tostring(reason or "run"))

    if driftgod.CheckProgressMilestones then driftgod.CheckProgressMilestones("vehicle mastery") end
    if driftgod.SaveProgress then driftgod.SaveProgress(false) end
end

function driftgod.RecordVehicleMasteryStunt(stuntName)
    driftgod.VehicleMasteryEnsureDefaults()
    if driftgod.S.vehicleMasteryEnabled == false then return end

    local key = driftgod.GetVehicleMasteryKey and driftgod.GetVehicleMasteryKey() or "current_vehicle"
    local record = driftgod.GetVehicleMasteryRecord(key)

    record.stuntsLanded = (tonumber(record.stuntsLanded or 0) or 0) + 1
    record.lastUpdated = os and os.time and os.time() or 0

    driftgod.UpdateVehicleMasteryLevel(record, key)
end

function driftgod.VehicleMasterySnapshot(reason)
    driftgod.VehicleMasteryEnsureDefaults()

    local key = driftgod.GetVehicleMasteryKey and driftgod.GetVehicleMasteryKey() or "current_vehicle"
    local record = driftgod.GetVehicleMasteryRecord(key)

    vmLog("Snapshot | reason=" .. tostring(reason or "manual")
        .. " | key=" .. tostring(key)
        .. " | name=" .. tostring(record.name or "")
        .. " | level=" .. tostring(record.masteryLevel or 1)
        .. " | title=" .. tostring(record.title or (driftgod.GetVehicleMasteryTitle and driftgod.GetVehicleMasteryTitle(record) or "Discovered"))
        .. " | total=" .. tostring(record.totalScore or 0)
        .. " | best=" .. tostring(record.bestScore or 0)
        .. " | runs=" .. tostring(record.runsBanked or 0)
        .. " | stunts=" .. tostring(record.stuntsLanded or 0), true)
end

function driftgod.InstallVehicleMastery(source)
    driftgod.VehicleMasteryEnsureDefaults()
    if driftgod.BuildVehicleMasteryHashLookup then driftgod.BuildVehicleMasteryHashLookup() end

    if driftgod.VehicleMastery.installed == true then
        return true
    end

    driftgod.VehicleMastery.installed = true
    driftgod.VehicleMastery.source = tostring(source or "unknown")

    if type(driftgod.Log) == "function" and driftgod.VehicleMastery.logWrapped ~= true then
        driftgod.VehicleMastery.logWrapped = true
        local oldDGLog = driftgod.Log
        driftgod.Log = function(msg)
            local text = tostring(msg or "")
            local loadedName = text:match("%[Vehicle%]%s*Successfully loaded vehicle%s*'([^']+)'")
            if loadedName and driftgod.SetVehicleMasteryCurrentVehicle then
                driftgod.SetVehicleMasteryCurrentVehicle(loadedName, nil)
            end
            return oldDGLog(msg)
        end
    end

    if type(driftgod.ExportProgress) == "function" then
        local oldExportProgress = driftgod.ExportProgress
        driftgod.ExportProgress = function()
            local t = oldExportProgress() or {}
            t.vehicleMastery = driftgod.S.vehicleMastery or {}
            t.vehicleMasteryRewards = driftgod.S.vehicleMasteryRewards or {}
            t.vehicleMasteryLastVehicleName = driftgod.S.vehicleMasteryLastVehicleName or ""
            t.vehicleMasteryLastVehicleModel = driftgod.S.vehicleMasteryLastVehicleModel or ""
            return t
        end
    else
        vmLog("Warning: driftgod.ExportProgress missing during vehicle mastery install", true)
    end

    if type(driftgod.ApplyProgress) == "function" then
        local oldApplyProgress = driftgod.ApplyProgress
        driftgod.ApplyProgress = function(t)
            local result = oldApplyProgress(t)
            if type(t) == "table" and type(t.vehicleMastery) == "table" then
                driftgod.S.vehicleMastery = t.vehicleMastery
            end
            if type(t) == "table" and type(t.vehicleMasteryRewards) == "table" then
                driftgod.S.vehicleMasteryRewards = t.vehicleMasteryRewards
            end
            if type(t) == "table" then
                driftgod.S.vehicleMasteryLastVehicleName = tostring(t.vehicleMasteryLastVehicleName or driftgod.S.vehicleMasteryLastVehicleName or "")
                driftgod.S.vehicleMasteryLastVehicleModel = tostring(t.vehicleMasteryLastVehicleModel or driftgod.S.vehicleMasteryLastVehicleModel or "")
            end
            driftgod.VehicleMasteryEnsureDefaults()
            return result
        end
    else
        vmLog("Warning: driftgod.ApplyProgress missing during vehicle mastery install", true)
    end

    if type(driftgod.BankOverallScoreValue) == "function" then
        local oldBankOverallScoreValue = driftgod.BankOverallScoreValue
        driftgod.BankOverallScoreValue = function(runScore, reason)
            local result = oldBankOverallScoreValue(runScore, reason)
            if result == true then
                driftgod.RecordVehicleMasteryRun(runScore, "Overall bank")
            end
            return result
        end
    else
        vmLog("Warning: driftgod.BankOverallScoreValue missing during vehicle mastery install", true)
    end

    if type(driftgod.RecordSessionChallengeAcceptedLanding) == "function" then
        local oldAcceptedLanding = driftgod.RecordSessionChallengeAcceptedLanding
        driftgod.RecordSessionChallengeAcceptedLanding = function(stuntName, source)
            local result = oldAcceptedLanding(stuntName, source)
            driftgod.RecordVehicleMasteryStunt(stuntName)
            return result
        end
    end

    if driftgod.LoadProgress and driftgod.VehicleMastery.reloadedAfterInstall ~= true then
        driftgod.VehicleMastery.reloadedAfterInstall = true
        driftgod.Try(function() driftgod.LoadProgress(false) end)
    end

    vmLog("Installed vehicle mastery | source=" .. tostring(source or "unknown"))
    return true
end

return DG
end

__DG_BUNDLE_LOADERS["systems.vehicle_sectors"] = function()
DG = DG or {}

driftgod.VehicleSectors = driftgod.VehicleSectors or {}

local NATIVE_GET_VEHICLE_CLASS = 0x29439776AAA00A62

local function vsNow()
    if driftgod.Now then return tonumber(driftgod.Now() or 0) or 0 end
    return math.floor((os.clock() or 0) * 1000)
end

local function vsLog(msg, force)
    if force ~= true and not (driftgod.S and driftgod.S.vehicleSectorDebugEnabled == true) then return end
    msg = tostring(msg or "")
    if driftgod.Log then driftgod.Log("[VehicleSectors] " .. msg)
    elseif Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] [VehicleSectors] " .. msg) end
end

driftgod.VehicleSectorClassNames = driftgod.VehicleSectorClassNames or {
    [0] = "Compacts",
    [1] = "Sedans",
    [2] = "SUVs",
    [3] = "Coupes",
    [4] = "Muscle",
    [5] = "Sports Classics",
    [6] = "Sports",
    [7] = "Super",
    [8] = "Motorcycles",
    [9] = "Off-Road",
    [10] = "Industrial",
    [11] = "Utility",
    [12] = "Vans",
    [13] = "Cycles",
    [14] = "Boats",
    [15] = "Helicopters",
    [16] = "Planes",
    [17] = "Service",
    [18] = "Emergency",
    [19] = "Military",
    [20] = "Commercial",
    [21] = "Trains",
    [22] = "Open Wheel",
    [23] = "Drift",
}

driftgod.VehicleSectorBeginnerZentornoScoreCap = driftgod.VehicleSectorBeginnerZentornoScoreCap or 0

driftgod.VehicleSectorUnlocks = driftgod.VehicleSectorUnlocks or {
    { id = "starter",          label = "Beginner Car",      classId = nil, threshold = 0,     starterOnly = true, description = "Zentorno always allowed" },
    { id = "compacts",         label = "Compacts",          classId = 0,   threshold = 500   },
    { id = "coupes",           label = "Coupes",            classId = 3,   threshold = 1000  },
    { id = "vans",             label = "Vans",              classId = 12,  threshold = 1500  },
    { id = "utility",          label = "Utility",           classId = 11,  threshold = 3000  },
    { id = "service",          label = "Service",           classId = 17,  threshold = 4500  },
    { id = "industrial",       label = "Industrial",        classId = 10,  threshold = 6000  },
    { id = "emergency",        label = "Emergency",         classId = 18,  threshold = 7500  },
    { id = "suvs",             label = "SUVs",              classId = 2,   threshold = 10500 },
    { id = "sedans",           label = "Sedans",            classId = 1,   threshold = 9000  },
    { id = "open_wheel",       label = "Open Wheel",        classId = 22,  threshold = 15000 },
    { id = "off_road",         label = "Off-Road",          classId = 9,   threshold = 16500 },
    { id = "sports_classics",  label = "Sports Classics",   classId = 5,   threshold = 18000 },
    { id = "muscle",           label = "Muscle",            classId = 4,   threshold = 19500 },
    { id = "drift",            label = "Drift",             classId = 23,  threshold = 21000 },
    { id = "military",         label = "Military",          classId = 19,  threshold = 22500 },
    { id = "sports",           label = "Sports",            classId = 6,   threshold = 24000 },
    { id = "super",            label = "Super",             classId = 7,   threshold = 25000 },
}

driftgod.VehicleSectorUnsupportedClasses = driftgod.VehicleSectorUnsupportedClasses or {
    [8] = true,
    [13] = true,
    [14] = true,
    [15] = true,
    [16] = true,
    [20] = true,
    [21] = true,
}

local function buildClassLookup()
    driftgod.VehicleSectorByClass = {}
    for _, sector in ipairs(driftgod.VehicleSectorUnlocks or {}) do
        if sector.classId ~= nil then
            driftgod.VehicleSectorByClass[tonumber(sector.classId)] = sector
        end
    end
end

buildClassLookup()

function driftgod.VehicleSectorsEnsureDefaults()
    driftgod.S = driftgod.S or {}
    driftgod.S.vehicleSectorUnlocksEnabled = driftgod.S.vehicleSectorUnlocksEnabled ~= false
    driftgod.S.vehicleSectorDebugEnabled = driftgod.S.vehicleSectorDebugEnabled == true
    driftgod.S.vehicleSectorLastStatus = driftgod.S.vehicleSectorLastStatus or ""
    driftgod.S.vehicleSectorLastLabel = driftgod.S.vehicleSectorLastLabel or "Unknown"
    driftgod.S.vehicleSectorLastClass = tonumber(driftgod.S.vehicleSectorLastClass or -1) or -1
end

function driftgod.GetVehicleSectorProgressScore()
    driftgod.S = driftgod.S or {}
    local best = tonumber(driftgod.S.bestScore or 0) or 0
    local progress = tonumber(driftgod.S.progressScore or 0) or 0
    local lifetime = tonumber(driftgod.S.lifetimeScore or 0) or 0
    local total = tonumber(driftgod.S.totalScore or 0) or 0
    local previous = tonumber(driftgod.S.previousScore or 0) or 0
    return math.floor(math.max(best, progress, lifetime, total, previous, 0))
end

function driftgod.GetVehicleClassSafe(veh)
    veh = veh or (driftgod.GetVehicle and driftgod.GetVehicle() or 0)
    if not veh or veh == 0 then return -1 end
    local classId = -1

    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_CLASS then
            classId = VEHICLE.GET_VEHICLE_CLASS(veh) or classId
        end
    end)

    if (tonumber(classId or -1) or -1) < 0 then
        driftgod.Try(function()
            if Natives and Natives.InvokeInt then
                classId = Natives.InvokeInt(NATIVE_GET_VEHICLE_CLASS, veh) or classId
            end
        end)
    end

    return tonumber(classId or -1) or -1
end

function driftgod.GetVehicleModelSafe(veh)
    veh = veh or (driftgod.GetVehicle and driftgod.GetVehicle() or 0)
    if not veh or veh == 0 then return 0 end
    local model = 0
    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_MODEL then model = ENTITY.GET_ENTITY_MODEL(veh) or 0 end
    end)
    return tonumber(model or 0) or 0
end

local zentornoHashes = nil
local function getZentornoHashes()
    if zentornoHashes then return zentornoHashes end
    zentornoHashes = {}
    local h = nil
    driftgod.Try(function()
        if GAMEPLAY and GAMEPLAY.GET_HASH_KEY then h = GAMEPLAY.GET_HASH_KEY("zentorno")
        elseif MISC and MISC.GET_HASH_KEY then h = MISC.GET_HASH_KEY("zentorno") end
    end)
    if not h and driftgod.JoaatVehicleHash then h = driftgod.JoaatVehicleHash("zentorno") end
    if h then
        local n = tonumber(h)
        if n then
            zentornoHashes[tostring(n)] = true
            if n < 0 then zentornoHashes[tostring(n + 4294967296)] = true end
            if n > 2147483647 then zentornoHashes[tostring(n - 4294967296)] = true end
        end
    end
    return zentornoHashes
end

function driftgod.IsStarterZentornoVehicle(veh)
    local model = driftgod.GetVehicleModelSafe and driftgod.GetVehicleModelSafe(veh) or 0
    if not model or model == 0 then return false end
    local hashes = getZentornoHashes()
    if hashes[tostring(model)] == true then return true end

    local name = nil
    driftgod.Try(function()
        if driftgod.ResolveVehicleDisplayNameFromModel then name = driftgod.ResolveVehicleDisplayNameFromModel(model) end
    end)
    name = tostring(name or ""):lower()
    return name:find("zentorno", 1, true) ~= nil
end

function driftgod.GetVehicleSectorInfo(veh)
    driftgod.VehicleSectorsEnsureDefaults()
    veh = veh or (driftgod.GetVehicle and driftgod.GetVehicle() or 0)
    if not veh or veh == 0 then
        return { ok = false, reason = "no_vehicle", noHud = true, classId = -1, label = "No Vehicle", threshold = 0, score = driftgod.GetVehicleSectorProgressScore() }
    end

    local classId = driftgod.GetVehicleClassSafe and driftgod.GetVehicleClassSafe(veh) or -1
    local classLabel = driftgod.VehicleSectorClassNames[classId] or ("Class " .. tostring(classId))
    local score = driftgod.GetVehicleSectorProgressScore and driftgod.GetVehicleSectorProgressScore() or 0
    local starter = driftgod.IsStarterZentornoVehicle and driftgod.IsStarterZentornoVehicle(veh) or false

    driftgod.S.vehicleSectorLastClass = classId
    driftgod.S.vehicleSectorLastLabel = classLabel

    if driftgod.DebugTrialVehicleBypass == true then
        return { ok = true, reason = "debug_trial_vehicle_bypass", classId = classId, label = classLabel, threshold = 0, score = score, starter = starter }
    end

    if driftgod.S.vehicleSectorUnlocksEnabled == false then
        return { ok = true, reason = "system_disabled", classId = classId, label = classLabel, threshold = 0, score = score, starter = starter }
    end

    if starter then
        return { ok = true, reason = "starter_zentorno_always", classId = classId, label = "Beginner Car", threshold = 0, score = score, starter = true, starterCap = nil }
    end

    if driftgod.VehicleSectorUnsupportedClasses[classId] == true then
        return { ok = false, reason = "unsupported", noHud = true, classId = classId, label = classLabel, threshold = nil, score = score, starter = false }
    end

    if classId == nil or classId < 0 then
        return { ok = true, reason = "class_unknown_fail_open", classId = classId or -1, label = "Unknown Vehicle", threshold = 0, score = score, starter = starter }
    end

    local sector = driftgod.VehicleSectorByClass and driftgod.VehicleSectorByClass[classId] or nil
    if not sector then
        return { ok = false, reason = "unsupported", noHud = true, classId = classId, label = classLabel, threshold = nil, score = score, starter = false }
    end

    local threshold = tonumber(sector.threshold or 0) or 0
    if score >= threshold then
        return { ok = true, reason = "unlocked", classId = classId, label = sector.label or classLabel, threshold = threshold, score = score, sector = sector, starter = false }
    end

    return { ok = false, reason = "locked", noHud = true, classId = classId, label = sector.label or classLabel, threshold = threshold, score = score, sector = sector, starter = false }
end

function driftgod.CanUseVehicleSector(veh)
    local info = driftgod.GetVehicleSectorInfo and driftgod.GetVehicleSectorInfo(veh) or { ok = true }
    return info.ok == true, info
end

function driftgod.VehicleSectorBlockCurrentRun(reason)
    driftgod.S = driftgod.S or {}
    if driftgod.S.currentScore and driftgod.S.currentScore > 0 and driftgod.FinishRun then
        driftgod.FinishRun(reason or "Vehicle Sector Locked")
    else
        driftgod.S.runActive = false
        driftgod.S.validDriftWatchMs = 0
        driftgod.S.activeDriftMs = 0
        driftgod.S.comboGraceUntil = 0
    end
    driftgod.S.hudAlpha = 0
    driftgod.S.hudVisibleUntil = 0
end

function driftgod.VehicleSectorGateTick(context, veh)
    driftgod.VehicleSectorsEnsureDefaults()
    if driftgod.S.vehicleSectorUnlocksEnabled == false then return true end
    local ok, info = driftgod.CanUseVehicleSector(veh)
    if ok then
        driftgod.S.vehicleSectorLastStatus = "unlocked"
        return true, info
    end

    driftgod.S.vehicleSectorLastStatus = tostring(info and info.reason or "blocked")

    if context == "hud" then
        if info and info.reason == "locked" then return true, info end
        driftgod.S.hudAlpha = 0
        driftgod.S.hudVisibleUntil = 0
        return false, info
    end

    if context == "drift" and driftgod.ResetVehicleState then

        driftgod.Try(function() driftgod.ResetVehicleState(false) end)
    end

    if context == "score" then
        driftgod.VehicleSectorBlockCurrentRun(info and info.reason == "locked" and "Vehicle Sector Locked" or "Unsupported Vehicle")
    else
        driftgod.S.hudAlpha = 0
        driftgod.S.hudVisibleUntil = 0
    end

    local now = vsNow()
    if driftgod.S.vehicleSectorDebugEnabled == true and (now - tonumber(driftgod.S.lastVehicleSectorBlockLogMs or 0)) > 2500 then
        driftgod.S.lastVehicleSectorBlockLogMs = now
        vsLog("blocked context=" .. tostring(context) .. " label=" .. tostring(info and info.label) .. " reason=" .. tostring(info and info.reason) .. " score=" .. tostring(info and info.score), true)
    end

    return false, info
end

function driftgod.GetVehicleSectorRows()
    local score = driftgod.GetVehicleSectorProgressScore and driftgod.GetVehicleSectorProgressScore() or 0
    local rows = {}
    for _, sector in ipairs(driftgod.VehicleSectorUnlocks or {}) do
        local unlocked = false
        if sector.starterOnly then
            unlocked = true
        else
            unlocked = score >= (tonumber(sector.threshold or 0) or 0)
        end
        rows[#rows + 1] = {
            label = sector.label or sector.id or "Sector",
            threshold = tonumber(sector.threshold or 0) or 0,
            unlocked = unlocked,
            starterOnly = sector.starterOnly == true,
            classId = sector.classId,
            id = sector.id,
            description = sector.description or nil,
        }
    end
    return rows
end

function driftgod.InstallVehicleSectors(source)
    driftgod.VehicleSectorsEnsureDefaults()
    buildClassLookup()
    driftgod.S.vehicleSectorGateInstalled = true
    if driftgod.S.vehicleSectorInstallLogged ~= true then
        driftgod.S.vehicleSectorInstallLogged = true

        vsLog("Installed vehicle sector gate | source=" .. tostring(source or "unknown"), false)
    elseif driftgod.S.vehicleSectorDebugEnabled == true then
        vsLog("Install skipped; already active | source=" .. tostring(source or "unknown"), false)
    end
    return true
end

return DG
end

__DG_BUNDLE_LOADERS["systems.visual_boost_fx"] = function()
DG = DG or {}
driftgod.S = driftgod.S or {}

local HASH_BOOST_FX = 1034789123
local HASH_BOOST_FX_SOUND = 3775835664

local natives = {
    playerPedId = 0xD80958FC74E988A6,
    isPedInAnyVehicle = 0x997ABD671D25CA0B,
    getVehiclePedIsIn = 0x9A9112A0FE9A4713,
    doesEntityExist = 0x7239B21A38F536BA,
    setVehicleBoostActive = 0x4A04DE7CAB2739A1,
}

local function log(msg)
    if DG and driftgod.Log then
        driftgod.Log("[VisualBoostFX] " .. tostring(msg))
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] [VisualBoostFX] " .. tostring(msg))
    end
end

local function toast(msg, ms)
    if DG and driftgod.Toast then
        driftgod.Toast(tostring(msg), ms or 1800)
    elseif GUI and GUI.AddToast then
        GUI.AddToast("DriftGod", tostring(msg), ms or 1800)
    end
end

local function ptrToHandle(ptr)
    if not ptr then return 0 end
    if type(ptr) == "number" then return ptr end
    local h = 0
    driftgod.Try(function()
        if GTA and GTA.PointerToHandle then
            h = GTA.PointerToHandle(ptr)
        end
    end)
    return tonumber(h) or 0
end

local function getVehicle()
    local veh = 0

    driftgod.Try(function()
        if DG and driftgod.GetVehicle then
            veh = ptrToHandle(driftgod.GetVehicle())
        end
    end)

    if not veh or veh == 0 then
        driftgod.Try(function()
            if GTA and GTA.GetLocalVehicle then
                veh = ptrToHandle(GTA.GetLocalVehicle())
            end
        end)
    end

    if not veh or veh == 0 then
        driftgod.Try(function()
            if PLAYER and PLAYER.PLAYER_PED_ID and PED and PED.GET_VEHICLE_PED_IS_IN then
                local ped = PLAYER.PLAYER_PED_ID()
                veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
            elseif Natives then
                local ped = Natives.InvokeInt(natives.playerPedId)
                if Natives.InvokeBool(natives.isPedInAnyVehicle, ped, false) then
                    veh = Natives.InvokeInt(natives.getVehiclePedIsIn, ped, false)
                end
            end
        end)
    end

    return tonumber(veh) or 0
end

local function entityExists(ent)
    if not ent or ent == 0 then return false end
    local ok, exists = driftgod.Try(function()
        if ENTITY and ENTITY.DOES_ENTITY_EXIST then
            return ENTITY.DOES_ENTITY_EXIST(ent)
        elseif Natives then
            return Natives.InvokeBool(natives.doesEntityExist, ent)
        end
        return false
    end)
    return ok and exists == true
end

local function getFeature(hash)
    local feat = nil
    driftgod.Try(function()
        if FeatureMgr and FeatureMgr.GetFeature then
            feat = FeatureMgr.GetFeature(hash)
        end
    end)
    return feat
end

local function setFeatureToggle(hash, state)
    local feat = getFeature(hash)
    local ok, err = driftgod.Try(function()
        if feat then
            if feat.SetBoolValue then
                feat:SetBoolValue(state == true)
            elseif feat.SetToggle then
                feat:SetToggle(state == true)
            elseif feat.SetToggled then
                feat:SetToggled(state == true)
            elseif feat.SetValue then
                feat:SetValue(state == true)
            elseif feat.Toggle then

                feat:Toggle()
            end
        end
    end)

    log("set feature hash=" .. tostring(hash) ..
        " exists=" .. tostring(feat ~= nil) ..
        " state=" .. tostring(state == true) ..
        " ok=" .. tostring(ok) ..
        " err=" .. tostring(err))
    return ok and feat ~= nil
end

local function triggerFeature(hash)
    local feat = getFeature(hash)
    local ok, err = driftgod.Try(function()
        if feat then
            if feat.TriggerCallback then
                feat:TriggerCallback()
            elseif feat.Trigger then
                feat:Trigger()
            elseif feat.OnClick then
                feat:OnClick()
            end
        end
    end)

    log("trigger feature hash=" .. tostring(hash) ..
        " exists=" .. tostring(feat ~= nil) ..
        " ok=" .. tostring(ok) ..
        " err=" .. tostring(err))
    return ok and feat ~= nil
end

local function setBoostActive(veh, active)
    local ok, err = driftgod.Try(function()
        if AUDIO and AUDIO.SET_VEHICLE_BOOST_ACTIVE then
            AUDIO.SET_VEHICLE_BOOST_ACTIVE(veh, active == true)
        elseif Natives then
            Natives.InvokeVoid(natives.setVehicleBoostActive, veh, active == true)
        end
    end)

    log("SET_VEHICLE_BOOST_ACTIVE active=" .. tostring(active == true) ..
        " veh=" .. tostring(veh) ..
        " ok=" .. tostring(ok) ..
        " err=" .. tostring(err))
    return ok
end

function driftgod.VisualBoostFX_EnableBuiltIn()
    driftgod.S = driftgod.S or {}
    setFeatureToggle(HASH_BOOST_FX, true)
    setFeatureToggle(HASH_BOOST_FX_SOUND, false)
    driftgod.S.visualBoostFXBuiltIn = true
    toast("Built-in Boost FX: ON / Sound OFF", 1600)
end

function driftgod.VisualBoostFX_DisableBuiltIn()
    driftgod.S = driftgod.S or {}
    setFeatureToggle(HASH_BOOST_FX, false)
    setFeatureToggle(HASH_BOOST_FX_SOUND, false)
    driftgod.S.visualBoostFXBuiltIn = false
    toast("Built-in Boost FX: OFF", 1600)
end

function driftgod.VisualBoostFX_TriggerBuiltInOnce()
    triggerFeature(HASH_BOOST_FX)
    setFeatureToggle(HASH_BOOST_FX_SOUND, false)
    toast("Triggered built-in Boost FX once", 1400)
end

function driftgod.VisualBoostFX_PulseBoostState()
    driftgod.S = driftgod.S or {}

    local veh = getVehicle()
    if not veh or veh == 0 or not entityExists(veh) then
        toast("Visual Boost FX needs a vehicle.", 1800)
        log("pulse failed: no vehicle")
        return
    end

    setBoostActive(veh, true)
    driftgod.S.visualBoostStateNeedsOff = true
    driftgod.S.visualBoostStateLastClock = os.clock()

    toast("Boost-state visual pulse only", 1000)
end

function driftgod.VisualBoostFX_StartHold()
    driftgod.S = driftgod.S or {}
    driftgod.S.visualBoostFXEnabled = true
    driftgod.VisualBoostFX_EnableBuiltIn()
    driftgod.VisualBoostFX_PulseBoostState()
    toast("Visual Boost FX Hold: ON", 1600)
end

function driftgod.VisualBoostFX_StopHold()
    driftgod.S = driftgod.S or {}
    driftgod.S.visualBoostFXEnabled = false
    driftgod.VisualBoostFX_DisableBuiltIn()

    local veh = getVehicle()
    if veh and veh ~= 0 then
        setBoostActive(veh, false)
    end

    driftgod.S.visualBoostStateNeedsOff = false
    toast("Visual Boost FX Hold: OFF", 1600)
    log("hold stopped")
end

function driftgod.VisualBoostFX_ToggleHold()
    driftgod.S = driftgod.S or {}
    if driftgod.S.visualBoostFXEnabled == true then
        driftgod.VisualBoostFX_StopHold()
    else
        driftgod.VisualBoostFX_StartHold()
    end
end

function driftgod.VisualBoostFXStatus()
    driftgod.S = driftgod.S or {}
    return "Visual Boost FX: " .. tostring(driftgod.S.visualBoostFXEnabled == true) ..
        " | BuiltIn: " .. tostring(driftgod.S.visualBoostFXBuiltIn == true) ..
        " | Pulse: " .. tostring(driftgod.S.visualBoostPulseMs or 200) .. "ms" ..
        " | Interval: " .. tostring(driftgod.S.visualBoostIntervalMs or 650) .. "ms"
end

function driftgod.VisualBoostFXTick()
    driftgod.S = driftgod.S or {}

    local veh = getVehicle()

    if driftgod.S.visualBoostStateNeedsOff == true then
        local last = tonumber(driftgod.S.visualBoostStateLastClock or 0) or 0
        if ((os.clock() - last) * 1000.0) >= tonumber(driftgod.S.visualBoostPulseMs or 200) then
            if veh and veh ~= 0 then
                setBoostActive(veh, false)
            end
            driftgod.S.visualBoostStateNeedsOff = false
            log("boost state off after pulse")
        end
    end

    if driftgod.S.visualBoostFXEnabled ~= true then return end
    if not veh or veh == 0 or not entityExists(veh) then return end

    if driftgod.S.visualBoostFXBuiltIn ~= true then
        driftgod.VisualBoostFX_EnableBuiltIn()
    end

    local interval = tonumber(driftgod.S.visualBoostIntervalMs or 650) or 650
    local last = tonumber(driftgod.S.visualBoostStateLastClock or 0) or 0
    if ((os.clock() - last) * 1000.0) >= interval then
        driftgod.VisualBoostFX_PulseBoostState()
    end
end

driftgod.Try(function()
    if Script and Script.RegisterLooped then
        Script.RegisterLooped(function()
            if ShouldUnload and ShouldUnload() then return false end
            local active = driftgod.S and (driftgod.S.visualBoostFXEnabled == true or driftgod.S.visualBoostStateNeedsOff == true)
            if active and DG and driftgod.VisualBoostFXTick then driftgod.VisualBoostFXTick() end
            if Script and Script.Yield then Script.Yield(active and 0 or 100) end
        end)

    elseif FeatureMgr and FeatureMgr.AddFeature and Utils and Utils.Joaat and eFeatureType then
        driftgod.SafeAddFeature(Utils.Joaat("DG_VISUAL_BOOSTFX_TICK_V61270"), "DriftGod Visual BoostFX Tick", eFeatureType.Script, "", function()
            if driftgod.VisualBoostFXTick then driftgod.VisualBoostFXTick() end
        end)

    end
end)

if driftgod.S.visualBoostFXEnabled == nil then driftgod.S.visualBoostFXEnabled = false end
if driftgod.S.visualBoostFXBuiltIn == nil then driftgod.S.visualBoostFXBuiltIn = false end
if driftgod.S.visualBoostPulseMs == nil then driftgod.S.visualBoostPulseMs = 200 end
if driftgod.S.visualBoostIntervalMs == nil then driftgod.S.visualBoostIntervalMs = 650 end

return DG
end

__DG_BUNDLE_LOADERS["ui.credits"] = function()
DG = DG or {}

local PROFILE_IMAGE_REL = "assets\\Public_Urinal.png"

local PROFILE_IMAGE_URL = "https://raw.githubusercontent.com/ARandomAddonDev/GTAV-Cherax/refs/heads/main/DriftGod/assets/Public_Urinal.png"
driftgod.CreditsProfileImageDownloadState = driftgod.CreditsProfileImageDownloadState or "idle"
driftgod.CreditsProfileImageDownloadStarted = driftgod.CreditsProfileImageDownloadStarted or false

local function creditsSetCurlOpt(curl, enumName, numericValue, value)
    if not curl or not curl.Setopt then return end
    local opt = numericValue
    driftgod.Try(function()
        if eCurlOption and eCurlOption[enumName] then opt = eCurlOption[enumName] end
    end)
    driftgod.Try(function() curl:Setopt(opt, value) end)
end

local function creditsLooksLikePng(body)
    if type(body) ~= "string" or #body < 100 then return false end
    if body:byte(1) == 137 and body:sub(2, 4) == "PNG" then return true end
    if body:sub(1, 8):find("PNG", 1, true) then return true end
    return #body > 1000
end

local function creditsDirName(path)
    path = tostring(path or "")
    return path:match("^(.*)[/\\][^/\\]+$")
end

local function creditsEnsureDir(path)
    if not path or path == "" then return end
    driftgod.Try(function()
        if FileMgr and FileMgr.CreateDir then FileMgr.CreateDir(path) end
    end)
end

local function queueProfileImageDownload(path)
    if not path or path == "" then return end
    if driftgod.CreditsProfileImageDownloadState == "loading" then return end
    if driftgod.CreditsProfileImageDownloadStarted == true then return end
    if not Curl or not Curl.Easy or not Script or not Script.QueueJob then
        driftgod.CreditsProfileImageDownloadState = "curl_unavailable"
        return
    end

    driftgod.CreditsProfileImageDownloadStarted = true
    driftgod.CreditsProfileImageDownloadState = "loading"

    Script.QueueJob(function()
        local ok, err = driftgod.Try(function()
            local curl = Curl.Easy()
            creditsSetCurlOpt(curl, "CURLOPT_URL", 10002, PROFILE_IMAGE_URL)
            creditsSetCurlOpt(curl, "CURLOPT_USERAGENT", 10018, "Mozilla/5.0 DriftGod-Cherax")
            curl:Perform()

            local ticks = 0
            while not curl:GetFinished() and ticks < 300 do
                Script.Yield(50)
                ticks = ticks + 1
            end

            if not curl:GetFinished() then
                driftgod.CreditsProfileImageDownloadState = "timeout"
                return
            end

            local code, body = curl:GetResponse()
            local success = (code == true) or (code == 0)
            driftgod.Try(function()
                if eCurlCode and code == eCurlCode.CURLE_OK then success = true end
            end)

            if not success or not creditsLooksLikePng(body) then
                driftgod.CreditsProfileImageDownloadState = "failed"
                return
            end

            creditsEnsureDir(creditsDirName(path))
            local f = io.open(path, "wb")
            if not f then
                driftgod.CreditsProfileImageDownloadState = "write_failed"
                return
            end
            f:write(body)
            f:close()

            driftgod.CreditsProfileImageTextureId = nil
            driftgod.CreditsProfileImageSrv = nil
            driftgod.CreditsProfileImageFailed = nil
            driftgod.CreditsProfileImageDownloadState = "done"
        end)
        if not ok then
            driftgod.CreditsProfileImageDownloadState = "error"
            driftgod.CreditsProfileImageFailed = tostring(err)
        end
    end)
end

local function textLine(value)
    if ImGui and ImGui.Text then
        ImGui.Text(tostring(value))
    end
end

local function colorLine(value, r, g, b, a)
    if ImGui and ImGui.TextColored then
        ImGui.TextColored(r or 1.0, g or 1.0, b or 1.0, a or 1.0, tostring(value or ""))
    else
        textLine(value)
    end
end

local function dgCreditsPackedColor(alpha)
    alpha = math.floor(tonumber(alpha) or 255)
    if alpha < 0 then alpha = 0 end
    if alpha > 255 then alpha = 255 end
    return ((alpha & 0xFF) << 24) | 0xFFFFFF
end

local function vecXY(v)
    if type(v) == "table" then
        return tonumber(v.x or v.X or v[1] or 0) or 0, tonumber(v.y or v.Y or v[2] or 0) or 0
    end
    local x, y = 0, 0
    driftgod.Try(function() if v and v.x ~= nil then x = tonumber(v.x) or x end end)
    driftgod.Try(function() if v and v.X ~= nil then x = tonumber(v.X) or x end end)
    driftgod.Try(function() if v and v.y ~= nil then y = tonumber(v.y) or y end end)
    driftgod.Try(function() if v and v.Y ~= nil then y = tonumber(v.Y) or y end end)
    return x, y
end

local function dgCreditsFileExists(path)
    local ok, exists = driftgod.Try(function()
        if FileMgr and FileMgr.DoesFileExist then
            return FileMgr.DoesFileExist(path)
        end
        local f = io.open(path, "rb")
        if f then f:close(); return true end
        return false
    end)
    return ok and exists == true
end

local function getProfileImagePath()
    local root = nil
    driftgod.Try(function()
        if DG and driftgod.Paths and driftgod.Paths.root then root = tostring(driftgod.Paths.root)
        elseif DG and driftgod.RootDir then root = tostring(driftgod.RootDir) end
    end)
    if not root or root == "" then
        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then
                root = tostring(FileMgr.GetMenuRootPath() or "") .. "\\Lua\\DriftGod"
            end
        end)
    end
    if not root or root == "" then return nil end

    local path = root .. "\\" .. PROFILE_IMAGE_REL
    if dgCreditsFileExists(path) then return path end

    local alt = root .. "\\assets\\Public_Urinal.png"
    if dgCreditsFileExists(alt) then return alt end

    queueProfileImageDownload(path)
    return path
end

local function loadProfileImageTexture()
    if driftgod.CreditsProfileImageSrv then return driftgod.CreditsProfileImageSrv end
    if not Texture or not Texture.LoadTexture or not Texture.GetTexture then return nil end

    local path = getProfileImagePath()
    if not path or path == "" then
        driftgod.CreditsProfileImageFailed = "missing path"
        return nil
    end
    if not dgCreditsFileExists(path) then
        queueProfileImageDownload(path)
        driftgod.CreditsProfileImageFailed = "downloading profile image"
        return nil
    end

    local texId = 0
    local okLoad, errLoad = driftgod.Try(function()
        texId = Texture.LoadTexture(path)
    end)
    if not okLoad or not texId or tonumber(texId) == 0 then
        driftgod.CreditsProfileImageFailed = "LoadTexture failed: " .. tostring(errLoad)
        return nil
    end

    local valid = true
    if Texture.IsTextureValid then
        local okValid, isValid = driftgod.Try(Texture.IsTextureValid, texId)
        valid = okValid and isValid == true
    end
    if valid ~= true then
        driftgod.CreditsProfileImageFailed = "texture invalid: " .. tostring(texId)
        return nil
    end

    local d3d = nil
    local srv = nil
    local okTex, errTex = driftgod.Try(function()
        d3d = Texture.GetTexture(texId)
        if d3d then
            srv = d3d:GetCurrent()
        end
    end)
    if not okTex or not srv then
        driftgod.CreditsProfileImageFailed = "GetTexture failed: " .. tostring(errTex)
        return nil
    end

    driftgod.CreditsProfileImageTextureId = texId
    driftgod.CreditsProfileImageSrv = srv
    driftgod.CreditsProfileImageFailed = nil
    return srv
end

local function drawProfileImage(sizeOverride)
    local srv = loadProfileImageTexture()
    if not srv or not ImGui then return false end

    local size = tonumber(sizeOverride) or 128.0
    local cursorX, cursorY = 0.0, 0.0
    driftgod.Try(function()
        local x, y = ImGui.GetCursorScreenPos()
        cursorX = tonumber(x) or cursorX
        cursorY = tonumber(y) or cursorY
    end)
    if cursorX <= 0 or cursorY <= 0 then return false end

    local pushed = false
    if ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Button then
        driftgod.Try(function()
            ImGui.PushStyleColor(ImGuiCol.Button, 0.06, 0.06, 0.07, 0.00)
            ImGui.PushStyleColor(ImGuiCol.ButtonHovered, 0.06, 0.06, 0.07, 0.00)
            ImGui.PushStyleColor(ImGuiCol.ButtonActive, 0.06, 0.06, 0.07, 0.00)
            pushed = true
        end)
    end

    local reserved = false
    if ImGui.Button then
        reserved = driftgod.Try(ImGui.Button, "##DG_Credits_Public_Urinal_Image", size, size)
        reserved = true
    elseif ImGui.Dummy then
        reserved = driftgod.Try(ImGui.Dummy, size, size)
        reserved = true
    end

    if pushed and ImGui.PopStyleColor then
        driftgod.Try(ImGui.PopStyleColor, 3)
    end

    local ok = false

    if ImGui.AddImage then
        ok = driftgod.Try(ImGui.AddImage, srv, cursorX, cursorY, cursorX + size, cursorY + size)
    end
    if not ok and ImGui.AddImageRounded then
        ok = driftgod.Try(ImGui.AddImageRounded, srv, cursorX, cursorY, cursorX + size, cursorY + size, 0.0, 0.0, 1.0, 1.0, dgCreditsPackedColor(255), 8.0)
    end

    if not ok and ImGui.TextDisabled then
        driftgod.Try(ImGui.TextDisabled, "[Public Urinal image loading]")
    end
    return ok == true or reserved == true
end

local function safeGetCursorPosX()
    local ok, v = driftgod.Try(function()
        if ImGui and ImGui.GetCursorPosX then return ImGui.GetCursorPosX() end
        return 0
    end)
    return (ok and tonumber(v)) or 0
end

local function safeGetCursorPosY()
    local ok, v = driftgod.Try(function()
        if ImGui and ImGui.GetCursorPosY then return ImGui.GetCursorPosY() end
        return 0
    end)
    return (ok and tonumber(v)) or 0
end

local function safeSetCursorPosX(v)
    if ImGui and ImGui.SetCursorPosX then driftgod.Try(ImGui.SetCursorPosX, tonumber(v) or 0) end
end

local function safeSetCursorPosY(v)
    if ImGui and ImGui.SetCursorPosY then driftgod.Try(ImGui.SetCursorPosY, tonumber(v) or 0) end
end

local function getContentAvailWidth()
    local ok, a, b = driftgod.Try(function()
        if ImGui and ImGui.GetContentRegionAvail then return ImGui.GetContentRegionAvail() end
        return 0
    end)
    if not ok then return 0 end
    if type(a) == "number" then return tonumber(a) or 0 end
    if type(a) == "table" then return tonumber(a.x or a.X or a[1] or 0) or 0 end
    return 0
end

local function drawProfileImageRightColumn(anchorY)

    if not ImGui then return false end

    local savedX = safeGetCursorPosX()
    local savedY = safeGetCursorPosY()
    local availW = getContentAvailWidth()
    local size = 138.0

    local targetX = savedX + 300.0
    if availW and availW > 360.0 then
        targetX = savedX + math.max(250.0, availW - size - 38.0)
    end

    safeSetCursorPosX(targetX)
    safeSetCursorPosY((tonumber(anchorY) or savedY) + 8.0)
    local ok = drawProfileImage(size)

    safeSetCursorPosX(savedX)
    safeSetCursorPosY(savedY)
    return ok
end

