__DG_BUNDLE_LOADERS["ui.hud"] = function()
DG = DG or {}

driftgod.S = driftgod.S or {}
if driftgod.S.mphHudX == nil then driftgod.S.mphHudX = 0.175 end
if driftgod.S.mphHudY == nil then driftgod.S.mphHudY = 0.977 end
if driftgod.S.stuntHudMoveEnabled == nil then driftgod.S.stuntHudMoveEnabled = false end
if driftgod.S.stuntHudX == nil then driftgod.S.stuntHudX = 0.50 end
if driftgod.S.stuntHudY == nil then driftgod.S.stuntHudY = 0.50 end

function driftgod.GetStuntHudPosition(defaultX, defaultY)

    local stuntHudX, stuntHudY = driftgod.GetStuntHudPosition and driftgod.GetStuntHudPosition(0.50, 0.50) or 0.50, 0.50
    driftgod.S = driftgod.S or {}
    if driftgod.S.stuntHudMoveEnabled == true then
        return tonumber(driftgod.S.stuntHudX or defaultX or 0.50) or 0.50,
               tonumber(driftgod.S.stuntHudY or defaultY or 0.50) or 0.50
    end
    return tonumber(defaultX or 0.50) or 0.50,
           tonumber(defaultY or 0.50) or 0.50
end

driftgod.S = driftgod.S or {}
if driftgod.S.stuntHudMoveEnabled == nil then driftgod.S.stuntHudMoveEnabled = false end
if driftgod.S.stuntHudX == nil then driftgod.S.stuntHudX = 0.50 end
if driftgod.S.stuntHudY == nil then driftgod.S.stuntHudY = 0.50 end

function driftgod.GetStuntHudPosition(defaultX, defaultY)

    local stuntHudX, stuntHudY = driftgod.GetStuntHudPosition and driftgod.GetStuntHudPosition(0.50, 0.50) or 0.50, 0.50

    local stuntHudX, stuntHudY = driftgod.GetStuntHudPosition and driftgod.GetStuntHudPosition(0.50, 0.50) or 0.50, 0.50
    driftgod.S = driftgod.S or {}

