driftgod.IntroLogoUseTopLayerFallback = false
driftgod.IntroLogoSuppressTopLayerFailLog = true

function driftgod.QueueRecordingIntroHUD(delayMs)
    driftgod.S = driftgod.S or {}

    delayMs = tonumber(delayMs or driftgod.S.recordingIntroDelayMs or 3000) or 3000
    if driftgod.S.recordingIntroDelayEnabled == false then delayMs = 0 end
    if delayMs < 0 then delayMs = 0 end

    local now = driftgod.Now and driftgod.Now() or math.floor(os.clock() * 1000)

    driftgod.S.introEnabled = true
    driftgod.S.introStartMs = 0
    driftgod.S.recordingIntroQueued = true
    driftgod.S.recordingIntroReadyAtMs = now + delayMs

    if driftgod.Toast then
        driftgod.Toast("Intro HUD queued in " .. tostring(string.format("%.1f", delayMs / 1000.0)) .. "s", 1800)
    end
end

function driftgod.RecordingIntroDelayGate(now)
    driftgod.S = driftgod.S or {}

    if driftgod.S.recordingIntroQueued ~= true then
        return true
    end

    local readyAt = tonumber(driftgod.S.recordingIntroReadyAtMs or 0) or 0
    if now < readyAt then
        return false
    end

    driftgod.S.recordingIntroQueued = false
    driftgod.S.recordingIntroReadyAtMs = 0
    driftgod.S.introStartMs = now
    return true
end

local function DG_IntroLog(msg)
    driftgod.Try(function()
        if DG and driftgod.S and driftgod.S.introLogoDebug == false then return end
        if DG and driftgod.Log then
            driftgod.IntroLogoLog(tostring(msg))
        elseif Logger and Logger.LogInfo then
            driftgod.IntroLogoLog(tostring(msg))
        end
    end)
end

local function DG_FileExists(path)
    if not path or path == "" then return false end
    local ok, exists = driftgod.Try(function()
        if FileMgr and FileMgr.DoesFileExist then
            return FileMgr.DoesFileExist(path)
        end
        local f = io.open(path, "rb")
        if f then f:close(); return true end
        return false
    end)
    return ok and exists == true
end

local function DG_GetLogoIntroPath()
    local rel = "assets/DriftGod.png"
    driftgod.Try(function()
        if DG and driftgod.S and driftgod.S.introLogoFile then rel = driftgod.S.introLogoFile end
    end)

    local root = nil
    driftgod.Try(function()
        if DG and driftgod.Paths and driftgod.Paths.root then root = driftgod.Paths.root .. "\\"
        elseif DG and driftgod.RootPath then root = driftgod.RootPath end
    end)

    if not root or root == "" then
        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then
                root = FileMgr.GetMenuRootPath() .. "\\Lua\\DriftGod\\"
            end
        end)
    end

    root = root or ""
    rel = tostring(rel or "assets/DriftGod.png")
    rel = rel:gsub("/", "\\")
    local full = root .. rel
    return full, rel, root
end

local function DG_LoadLogoTextureIfNeeded()
    driftgod.IntroLogoTexture = driftgod.IntroLogoTexture or nil
    if driftgod.IntroLogoTexture then
        return driftgod.IntroLogoTexture
    end

    local full, rel, root = DG_GetLogoIntroPath()
    DG_IntroLog("root=" .. tostring(root))
    DG_IntroLog("relative=" .. tostring(rel))
    DG_IntroLog("full=" .. tostring(full))
    DG_IntroLog("exists=" .. tostring(DG_FileExists(full)))

    if not DG_FileExists(full) then
        DG_IntroLog("FAILED: logo file missing. Expected: " .. tostring(full))
        return nil
    end

    local tex = nil
    local ok, err = driftgod.Try(function()
        if Texture and Texture.LoadTexture then
            tex = Texture.LoadTexture(full)
        elseif ImGui and ImGui.LoadTexture then
            tex = ImGui.LoadTexture(full)
        end
    end)

    DG_IntroLog("Texture.LoadTexture available=" .. tostring(Texture and Texture.LoadTexture ~= nil))
    DG_IntroLog("load ok=" .. tostring(ok) .. " result=" .. tostring(tex) .. " err=" .. tostring(err))

    if ok and tex then
        driftgod.IntroLogoTexture = tex
        DG_IntroLog("SUCCESS: logo texture loaded.")
        return tex
    end

    DG_IntroLog("FAILED: texture returned nil/false; falling back to text intro.")
    return nil
end

