end
function driftgod.DrawText(text, x, y, size, r, g, b, a, font)
    if not driftgod.HasNatives() then return end
    driftgod.Try(function()
        HUD.SET_TEXT_FONT(font or 7)
        HUD.SET_TEXT_SCALE(0.0, size + 0.0)
        HUD.SET_TEXT_COLOUR(r or 255, g or 255, b or 255, a or 255)
        HUD.SET_TEXT_CENTRE(true)
        HUD.SET_TEXT_DROP_SHADOW()
        HUD.SET_TEXT_OUTLINE()
        HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT("STRING")
        HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME(tostring(text))
        HUD.END_TEXT_COMMAND_DISPLAY_TEXT(x + 0.0, y + 0.0)
    end)
end
function driftgod.ResolveIntroLogoPath()
    local file = (driftgod.S and driftgod.S.introLogoFile) or "assets/DriftGod.png"
    if file:find(":\\") or file:find("^/") then return file end
    local root = ""
    driftgod.Try(function() root = FileMgr.GetMenuRootPath() .. "\\Lua\\DriftGod\\" end)
    return root .. file
end

function driftgod.LoadIntroLogoTexture()
    if driftgod.S.introLogoTextureId and driftgod.S.introLogoTextureId ~= 0 then
        return driftgod.S.introLogoTextureId
    end

    if not Texture or not Texture.LoadTexture then return 0 end

    local path = driftgod.ResolveIntroLogoPath()
    local ok, texId = driftgod.Try(Texture.LoadTexture, path)
    if ok and texId and texId ~= 0 then
        driftgod.S.introLogoTextureId = texId
        if Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] Loaded intro logo: " .. tostring(path)) end
        return texId
    end

    if Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] Failed to load intro logo: " .. tostring(path)) end
    driftgod.S.introLogoTextureId = 0
    return 0
end

function driftgod.DrawIntroLogo(alpha)

    if driftgod.DrawLogoIntroOrText and driftgod.DrawLogoIntroOrText(alpha or 1.0) then return true end
    if not ImGui or not Texture then return false end

    local texId = driftgod.LoadIntroLogoTexture()
    if not texId or texId == 0 then return false end

    local okTex, texture = driftgod.Try(Texture.GetTexture, texId)
    if not okTex or not texture then return false end

    local sw, sh = 1920, 1080
    driftgod.Try(function()
        local w, h = ImGui.GetDisplaySize()
        if w and h and w > 0 and h > 0 then sw, sh = w, h end
    end)

    local scale = tonumber(driftgod.S.introLogoScale or 0.28) or 0.28
    scale = driftgod.ClampFloat and driftgod.ClampFloat(scale, 0.10, 0.55) or math.max(0.10, math.min(0.55, scale))

    local size = math.min(sw * scale, sh * 0.44)
    local cx = sw * 0.50
    local cy = sh * (tonumber(driftgod.S.introLogoY or 0.38) or 0.38)
    local x1, y1 = cx - size / 2, cy - size / 2
    local x2, y2 = cx + size / 2, cy + size / 2

    local okDraw = driftgod.Try(function()
        if ImGui.BgAddImageRounded then
            local color = 0xFFFFFFFF
            driftgod.Try(function()
                if ImGui.ColorConvertRGBAToU32 then color = ImGui.ColorConvertRGBAToU32({255, 255, 255, alpha}) end
            end)
            ImGui.BgAddImageRounded(texture, x1, y1, x2, y2, 0.0, 0.0, 1.0, 1.0, color, 18.0)
        elseif ImGui.BgAddImage then
            local color = 0xFFFFFFFF
            driftgod.Try(function()
                if ImGui.ColorConvertRGBAToU32 then color = ImGui.ColorConvertRGBAToU32({255, 255, 255, alpha}) end
            end)
            ImGui.BgAddImage(texture, x1, y1, x2, y2, 0.0, 0.0, 1.0, 1.0, color)
        elseif ImGui.AddImageRotated then
            ImGui.AddImageRotated(texture, cx, cy, size, size, 0.0, alpha)
        end
    end)

    return okDraw
end

function driftgod.DrawIntro()
    if not driftgod.S.introEnabled then return end

    if driftgod.S and driftgod.S.introDelayUntilLoaderDone == true then return end
    local now = driftgod.Now()
    if not driftgod.RecordingIntroDelayGate(now) then return end
    if driftgod.S.introStartMs == 0 then driftgod.S.introStartMs = now end
    local elapsed = now - driftgod.S.introStartMs
    if elapsed > driftgod.S.introDurationMs then return end

    local alpha = 255
    if elapsed > driftgod.S.introFadeStartMs then
        local fadeElapsed = elapsed - driftgod.S.introFadeStartMs
        local fadeDuration = driftgod.S.introDurationMs - driftgod.S.introFadeStartMs
        alpha = math.floor(math.max(0, math.min(255, 255 * (1.0 - fadeElapsed / fadeDuration))))
    end

    local logoDrawn = false
    if driftgod.S.introLogoEnabled ~= false then
        logoDrawn = driftgod.DrawIntroLogo(alpha)
    end

    if logoDrawn then
        driftgod.DrawText(driftgod.Subtitle or "Drift Like a God.", 0.5, driftgod.S.introCaptionY or 0.61, 0.52, 255, 255, 255, alpha, 7)
        local creditY = (driftgod.S.introCaptionY or 0.61) + 0.045
        driftgod.DrawText("Developed By: " .. tostring(driftgod.Developer or "Animus"), 0.5, creditY, 0.34, 166, 94, 252, alpha, 4)
        driftgod.DrawText("Discord: " .. tostring(driftgod.Discord or "animusx1337"), 0.5, creditY + 0.034, 0.28, 255, 255, 255, alpha, 4)
        driftgod.DrawText("Version: " .. tostring(driftgod.Version or "v1.0.1"), 0.5, creditY + 0.070, 0.25, 166, 94, 252, alpha, 4)
    else

        driftgod.DrawText("", 0.5, 0.36, 1.48, 190, 90, 255, alpha, 7)
        driftgod.DrawText(driftgod.Subtitle or "Drift Like a God.", 0.5, 0.455, 0.48, 255, 255, 255, alpha, 4)
        driftgod.DrawText("Developed By: " .. tostring(driftgod.Developer or "Animus"), 0.5, 0.500, 0.32, 166, 94, 252, alpha, 4)
        driftgod.DrawText("Discord: " .. tostring(driftgod.Discord or "animusx1337"), 0.5, 0.534, 0.26, 255, 255, 255, alpha, 4)
        driftgod.DrawText("Version: " .. tostring(driftgod.Version or "v1.0.1"), 0.5, 0.570, 0.235, 166, 94, 252, alpha, 4)
    end
end
function driftgod.UpdateHudFade()
    local now = driftgod.Now()
    if driftgod.IsDriftHeld and (driftgod.IsDriftHeld() or driftgod.S.runActive or driftgod.S.currentScore > 0 or now <= driftgod.S.comboGraceUntil) then
        driftgod.S.hudVisibleUntil = now + driftgod.S.hudFadeAfterMs
        driftgod.S.hudAlpha = 255
        return
    end
    if now <= driftgod.S.hudVisibleUntil then driftgod.S.hudAlpha = 255 return end
    driftgod.S.hudAlpha = math.max(0, driftgod.S.hudAlpha - 5)
end
function driftgod.DrawBonusPopups(alpha)
    local now = driftgod.Now(); local alive = {}
    for _, popup in ipairs(driftgod.S.bonusPopups) do
        local age = now - popup.start
        if age < popup.life then
            local progress = age / popup.life
            local a = math.floor((1.0 - progress) * alpha)

            local drift = tonumber(popup.drift or 0.09) or 0.09
            local dirX = tonumber(popup.dirX or 1.0) or 1.0
            local dirY = tonumber(popup.dirY or -0.45) or -0.45
            local startRadius = tonumber(popup.startRadius or driftgod.S.bonusPopupRadialStartRadius or 0.012) or 0.012

            local anchorX = driftgod.S.hudX + tonumber(driftgod.S.bonusPopupScoreAnchorOffsetX or 0.000)
            local anchorY = driftgod.S.hudY + tonumber(driftgod.S.bonusPopupScoreAnchorOffsetY or -0.065)

            local x = driftgod.ClampFloat(anchorX + (dirX * startRadius) + (dirX * drift * progress), 0.02, 0.98)
            local y = driftgod.ClampFloat(anchorY + (dirY * startRadius) + (dirY * drift * progress), 0.02, 0.90)

            driftgod.DrawText(popup.text, x, y, 0.34, popup.r, popup.g, popup.b, a, 4)
            table.insert(alive, popup)
        end
    end
    driftgod.S.bonusPopups = alive
end
function driftgod.DrawScoreHud()
    if driftgod.S and driftgod.S.showScoreHudMaster == false then return end
    if driftgod.CanShowScoreHud and not driftgod.CanShowScoreHud() then return end
    if driftgod.CanShowScoreHud and not driftgod.CanShowScoreHud() then return end
    if driftgod.IsScoreHudVisible and not driftgod.IsScoreHudVisible() then return end
    if not driftgod.S.scoreHudEnabled or not driftgod.IsInVehicle or not driftgod.IsInVehicle() then return end
    if driftgod.VehicleSectorGateTick and not driftgod.VehicleSectorGateTick("hud", driftgod.GetVehicle and driftgod.GetVehicle() or 0) then return end
    driftgod.UpdateHudFade()
    if driftgod.S.hudAlpha <= 0 then return end
    if driftgod.UpdateActiveRival then driftgod.UpdateActiveRival() end
    local alpha = driftgod.ClampInt(driftgod.S.hudAlpha, 0, 255)
    local displayScore = math.floor(driftgod.S.currentScore or 0)
    local rankName = driftgod.GetRank(math.max(driftgod.S.currentScore or 0, driftgod.S.bestScore or 0))
    driftgod.DrawText(tostring(displayScore), driftgod.S.hudX, driftgod.S.hudY, 1.15, 255, 255, 255, alpha, 7)
    driftgod.DrawText(tostring(driftgod.S.comboMultiplier) .. "x COMBO", driftgod.S.hudX, driftgod.S.hudY + 0.065, 0.44, 190, 90, 255, alpha, 7)
    driftgod.DrawText(rankName, driftgod.S.hudX, driftgod.S.hudY + 0.105, 0.33, 230, 230, 230, math.floor(alpha * 0.90), 4)
    driftgod.DrawText("Best: " .. tostring(math.floor(driftgod.S.bestScore or 0)) .. " Points", driftgod.S.hudX, driftgod.S.hudY + 0.140, 0.32, 200, 200, 200, math.floor(alpha * 0.85), 4)
    if driftgod.EnsureTodayBest then driftgod.EnsureTodayBest() end
    driftgod.DrawText("Today's Best: " .. tostring(math.floor(driftgod.S.todayBestScore or 0)) .. " Points", driftgod.S.hudX, driftgod.S.hudY + 0.175, 0.30, 200, 200, 200, math.floor(alpha * 0.82), 4)
    if driftgod.S.rivalEnabled then driftgod.DrawText("Rival: " .. driftgod.S.rivalName .. " | Target: " .. tostring(driftgod.S.rivalTargetScore), driftgod.S.hudX, driftgod.S.hudY + 0.210, 0.28, 255, 180, 180, math.floor(alpha * 0.80), 4) end
    local now = driftgod.Now()
    if driftgod.S.comboGraceUntil > now and driftgod.S.currentScore > 0 then driftgod.DrawText("Combo Grace: " .. tostring(math.ceil((driftgod.S.comboGraceUntil - now) / 1000)) .. "s", driftgod.S.hudX, driftgod.S.hudY + 0.240, 0.28, 255, 220, 120, math.floor(alpha * 0.80), 4) end
    if driftgod.S.lastRunEndMessage ~= "" and now < driftgod.S.lastRunEndUntil then driftgod.DrawText(driftgod.S.lastRunEndMessage, driftgod.S.hudX, driftgod.S.hudY + 0.280, 0.42, 190, 90, 255, alpha, 7) end
    driftgod.DrawBonusPopups(alpha)
end

