    if not tex then return false end

    alpha = alpha or 1.0
    local scale = tonumber(driftgod.S.introLogoScale or 0.28) or 0.28
    local yNorm = tonumber(driftgod.S.introLogoY or 0.38) or 0.38
    local sx, sy = DG_GetScreenSize()

    local size = math.floor(math.min(sx, sy) * scale)
    local x = math.floor((sx - size) / 2)
    local y = math.floor((sy * yNorm) - (size / 2))

    local okDraw = driftgod.Try(function()
        if ImGui and ImGui.GetBackgroundDrawList then
            local dl = ImGui.GetBackgroundDrawList()
            if dl and dl.AddImage then
                dl:AddImage(tex, {x, y}, {x + size, y + size}, {0, 0}, {1, 1}, {1, 1, 1, alpha})
            elseif dl and dl.AddImageRounded then
                dl:AddImageRounded(tex, {x, y}, {x + size, y + size}, {0, 0}, {1, 1}, {1, 1, 1, alpha}, 0)
            end
        end
    end)

    if okDraw then
        DG_LogoIntroLog("draw-list logo attempted size=" .. tostring(size) .. " x=" .. tostring(x) .. " y=" .. tostring(y))
        return true
    end

    local okWrapper = driftgod.Try(function()
        if driftgod.DrawTextureCentered then
            driftgod.DrawTextureCentered(tex, 0.5, yNorm, scale, scale, alpha)
        end
    end)

    if okWrapper then
        DG_LogoIntroLog("driftgod.DrawTextureCentered logo attempted.")
        return true
    end

    DG_LogoIntroLog("No usable image draw method detected.")
    return false
end

