function driftgod.DrawLogoIntroOrText(alpha)
    alpha = alpha or 1.0

    if driftgod.S and driftgod.S.introLogoEnabled == false then
        DG_LogoIntroLog39("introLogoEnabled=false; skipping logo")
        return false
    end

    local srv, texId, texW, texH = DG_GetLogoSrv39()
    if not srv then
        DG_LogoIntroLog39("no SRV; fallback text")
        return false
    end

    local sw, sh = DG_GetDisplaySize39()
    local scale = tonumber((driftgod.S and driftgod.S.introLogoScale) or 0.28) or 0.28
    local yNorm = tonumber((driftgod.S and driftgod.S.introLogoY) or 0.38) or 0.38

    local maxSize = tonumber((driftgod.S and driftgod.S.introLogoPixelSize) or 990) or 990
    local ratio = 1.0
    if texW and texH and texH ~= 0 then ratio = texW / texH end

    local logoW, logoH
    if ratio >= 1.0 then
        logoW = maxSize
        logoH = maxSize / ratio
    else
        logoH = maxSize
        logoW = maxSize * ratio
    end

    local centerX = tonumber((driftgod.S and driftgod.S.introLogoPixelX) or 960) or 960
    local centerY = tonumber((driftgod.S and driftgod.S.introLogoPixelY) or 330) or 330
    local alphaInt = math.max(0, math.min(255, math.floor((alpha or 1.0) * 255)))

    local okDraw, errDraw = driftgod.Try(function()
        ImGui.BgAddImageRotated(srv, centerX, centerY, logoW, logoH, 0.0, alphaInt)
    end)

    DG_LogoIntroLog39("BgAddImageRotated ok=" .. tostring(okDraw) .. " texId=" .. tostring(texId) .. " center=" .. tostring(math.floor(centerX)) .. "," .. tostring(math.floor(centerY)) .. " size=" .. tostring(math.floor(logoW)) .. "x" .. tostring(math.floor(logoH)) .. " alpha=" .. tostring(alphaInt) .. " err=" .. tostring(errDraw))

    driftgod.Try(function()
        local caption = tostring((driftgod.S and driftgod.S.introLogoCaption) or "Drift Like a God.")
        local captionY = tonumber((driftgod.S and driftgod.S.introCaptionY) or 0.61) or 0.61
        if driftgod.DrawTextCentered then
            driftgod.DrawTextCentered(caption, 0.5, captionY, 0.70, alpha)
        elseif driftgod.DrawText then
            driftgod.DrawText(caption, 0.5, captionY, 0.70, alpha, true)
        end
    end)

    return okDraw == true
end

