function driftgod.QueueRecordingIntroHUD(delayMs)
    driftgod.S = driftgod.S or {}

    delayMs = tonumber(delayMs or driftgod.S.recordingIntroDelayMs or 3000) or 3000
    if driftgod.S.recordingIntroDelayEnabled == false then delayMs = 0 end
    if delayMs < 0 then delayMs = 0 end

    local now = driftgod.Now and driftgod.Now() or math.floor(os.clock() * 1000)

    driftgod.S.introEnabled = true
    driftgod.S.introStartMs = 0
    driftgod.S.recordingIntroQueued = true
    driftgod.S.recordingIntroReadyAtMs = now + delayMs

    if driftgod.Toast then
        driftgod.Toast("Intro HUD queued in " .. tostring(math.floor(delayMs / 1000)) .. "s", 1800)
    end
end

local function DG_RecordingIntroDelayGate(now)
    driftgod.S = driftgod.S or {}

    if driftgod.S.recordingIntroQueued ~= true then
        return true
    end

    local readyAt = tonumber(driftgod.S.recordingIntroReadyAtMs or 0) or 0
    if now < readyAt then
        return false
    end

    driftgod.S.recordingIntroQueued = false
    driftgod.S.recordingIntroReadyAtMs = 0
    driftgod.S.introStartMs = now
    return true
end

if driftgod.S.introEnabled == false then return 0 end

    local now = DG_PresentLogoNow44()
    if not driftgod.RecordingIntroDelayGate(now) then return 0 end

    if driftgod.S.introDelayUntilLoaderDone == true then return 0 end
    if not driftgod.S.introStartMs or driftgod.S.introStartMs == 0 then
        driftgod.S.introStartMs = now
    end

    local elapsed = now - driftgod.S.introStartMs
    local duration = tonumber(driftgod.S.introDurationMs or 6000) or 6000
    local fadeStart = tonumber(driftgod.S.introFadeStartMs or 4200) or 4200

    if elapsed < 0 or elapsed > duration then return 0 end

    local alpha = 255
    if elapsed > fadeStart then
        local fadeElapsed = elapsed - fadeStart
        local fadeDuration = math.max(1, duration - fadeStart)
        alpha = math.floor(math.max(0, math.min(255, 255 * (1.0 - fadeElapsed / fadeDuration))))
    end

    return alpha
end

