local function DG_SetCurlOpt48R1(curl, enumName, numericValue, value)
    if not curl or not curl.Setopt then return end
    local opt = numericValue
    driftgod.Try(function()
        if eCurlOption and eCurlOption[enumName] then opt = eCurlOption[enumName] end
    end)
    driftgod.Try(function() curl:Setopt(opt, value) end)
end

local function DG_ResponseLooksLikePng48R1(body)
    if type(body) ~= "string" or #body < 100 then return false end
    if body:byte(1) == 137 and body:sub(2, 4) == "PNG" then return true end
    if body:sub(1, 8):find("PNG", 1, true) then return true end
    return #body > 1000
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- intro logo cache
-- note: downloads the remote logo into the local asset cache when needed.
-- ═══════════════════════════════════════════════════════════════════════════════════

function driftgod.QueueIntroLogoRemoteDownload48R1(force)
    driftgod.S = driftgod.S or {}
    if driftgod.S.introLogoRemoteEnabled == false then return end
    if not Curl or not Curl.Easy then
        if DG_PresentLogoLog44 then DG_PresentLogoLog44("GitHub logo skipped: Curl unavailable.", true) end
        return
    end

    local url = tostring((driftgod.R296_GetIntroLogoRemoteUrl and driftgod.R296_GetIntroLogoRemoteUrl()) or "")
    if url == "" then return end

    local cacheRel = tostring(driftgod.S.introLogoRemoteCacheFile or "assets/driftgod_loading/DriftGod_github.png")
    local cachePath = DG_PathFromRoot48R1(cacheRel)

    if force ~= true and DG_FileExists48R1(cachePath) then
        driftgod.IntroLogoRemoteDownloadState = "done"
        return
    end

    if driftgod.IntroLogoRemoteDownloadState == "loading" then return end
    if force ~= true and driftgod.IntroLogoRemoteDownloadStarted == true then return end

    driftgod.IntroLogoRemoteDownloadStarted = true
    driftgod.IntroLogoRemoteDownloadState = "loading"
    if DG_PresentLogoLog44 then DG_PresentLogoLog44("GitHub logo download queued: " .. tostring(cacheRel), true) end

    Script.QueueJob(function()
        local ok, err = driftgod.Try(function()
            local curl = Curl.Easy()
            DG_SetCurlOpt48R1(curl, "CURLOPT_URL", 10002, url)
            DG_SetCurlOpt48R1(curl, "CURLOPT_USERAGENT", 10018, "Mozilla/5.0 DriftGod-Cherax")
            curl:Perform()

            local timeoutTicks = tonumber(driftgod.S.introLogoRemoteTimeoutTicks or 300) or 300
            local ticks = 0
            while not curl:GetFinished() and ticks < timeoutTicks do
                Script.Yield(50)
                ticks = ticks + 1
            end

            if not curl:GetFinished() then
                driftgod.IntroLogoRemoteDownloadState = "timeout"
                if DG_PresentLogoLog44 then DG_PresentLogoLog44("GitHub logo download timed out.", true) end
                return
            end

            local code, body = curl:GetResponse()
            local success = (code == true) or (code == 0)
            driftgod.Try(function()
                if eCurlCode and code == eCurlCode.CURLE_OK then success = true end
            end)

            if not success or not DG_ResponseLooksLikePng48R1(body) then
                driftgod.IntroLogoRemoteDownloadState = "failed"
                if DG_PresentLogoLog44 then DG_PresentLogoLog44("GitHub logo download failed. code=" .. tostring(code) .. " bytes=" .. tostring(type(body) == "string" and #body or 0), true) end
                return
            end

            DG_CreateDir48R1(DG_DirName48R1(cachePath))
            local f = io.open(cachePath, "wb")
            if not f then
                driftgod.IntroLogoRemoteDownloadState = "write_failed"
                if DG_PresentLogoLog44 then DG_PresentLogoLog44("GitHub logo cache write failed: " .. tostring(cachePath), true) end
                return
            end
            f:write(body)
            f:close()

            driftgod.IntroLogoTextureId = 0
            driftgod.IntroLogoTexture = nil
            driftgod.IntroLogoRemoteDownloadState = "done"
            if DG_PresentLogoLog44 then DG_PresentLogoLog44("GitHub logo cached: " .. tostring(cachePath) .. " bytes=" .. tostring(#body), true) end
        end)

        if not ok then
            driftgod.IntroLogoRemoteDownloadState = "error"
            if DG_PresentLogoLog44 then DG_PresentLogoLog44("GitHub logo download error: " .. tostring(err), true) end
        end
    end)
end

local function DG_PresentLogoPath44()
    driftgod.S = driftgod.S or {}

    if driftgod.S.introLogoRemoteEnabled ~= false and driftgod.S.introLogoRemotePrimary ~= false then
        if driftgod.QueueIntroLogoRemoteDownload48R1 then
            driftgod.QueueIntroLogoRemoteDownload48R1(false)
        end

        local cacheRel = tostring(driftgod.S.introLogoRemoteCacheFile or "assets/driftgod_loading/DriftGod_github.png")
        local cachePath = DG_PathFromRoot48R1(cacheRel)
        if DG_FileExists48R1(cachePath) then
            return cachePath
        end
    end

    local rel = "assets/DriftGod.png"
    driftgod.Try(function()
        if DG and driftgod.S and driftgod.S.introLogoFile then rel = driftgod.S.introLogoFile end
    end)

    return DG_PathFromRoot48R1(rel)
end

local function DG_PresentFileExists44(path)
    local ok, exists = driftgod.Try(function()
        if FileMgr and FileMgr.DoesFileExist then
            return FileMgr.DoesFileExist(path)
        end
        local f = io.open(path, "rb")
        if f then f:close(); return true end
        return false
    end)

    return ok and exists == true
end

function driftgod.LoadIntroLogoTexturePresent()
    if driftgod.IntroLogoTextureId and driftgod.IntroLogoTextureId > 0 then
        return driftgod.IntroLogoTextureId
    end

    local path = DG_PresentLogoPath44()
    if not DG_PresentFileExists44(path) then
        DG_PresentLogoLog44("ON_PRESENT missing logo file: " .. tostring(path), true)
        driftgod.IntroLogoTextureId = 0
        return 0
    end

    local texId = 0
    local ok, err = driftgod.Try(function()
        if Texture and Texture.LoadTexture then
            texId = Texture.LoadTexture(path)
        end
    end)

    DG_PresentLogoLog44("ON_PRESENT Texture.LoadTexture ok=" .. tostring(ok) .. " texId=" .. tostring(texId) .. " err=" .. tostring(err), true)

    if ok and texId and texId > 0 then
        driftgod.IntroLogoTextureId = texId
        return texId
    end

    driftgod.IntroLogoTextureId = 0
    return 0
end

function driftgod.DrawIntroLogoOnPresent()
    if not DG or not driftgod.S then return end
    if driftgod.S.introLogoEnabled == false then return end

    if driftgod.S.introDelayUntilLoaderDone == true then return end

    local alpha = tonumber(DG_PresentIntroAlpha44() or 0) or 0
    if alpha <= 0 then return end

    local texId = driftgod.LoadIntroLogoTexturePresent()
    if not texId or texId <= 0 then return end

    local valid = true
    driftgod.Try(function()
        if Texture and Texture.IsTextureValid then
            valid = Texture.IsTextureValid(texId)
        end
    end)
    if valid == false then
        DG_PresentLogoLog44("ON_PRESENT texture invalid: " .. tostring(texId), true)
        return
    end

    local screenW, screenH = 1920, 1080
    driftgod.Try(function()
        if ImGui and ImGui.GetDisplaySize then
            local w, h = ImGui.GetDisplaySize()
            if tonumber(w) and tonumber(h) and tonumber(w) > 0 and tonumber(h) > 0 then
                screenW, screenH = tonumber(w), tonumber(h)
            end
        end
    end)

    local d3dTexture = nil
    local srv = nil
    local texW, texH = 1024, 1024

    local okTex, errTex = driftgod.Try(function()
        d3dTexture = Texture.GetTexture(texId)
        if d3dTexture then
            srv = d3dTexture:GetCurrent()
            if d3dTexture.GetWidth then texW = d3dTexture:GetWidth() end
            if d3dTexture.GetHeight then texH = d3dTexture:GetHeight() end
        end
    end)

    if not okTex or not srv then
        DG_PresentLogoLog44("ON_PRESENT GetTexture failed ok=" .. tostring(okTex) .. " srv=" .. tostring(srv) .. " err=" .. tostring(errTex), true)
        return
    end

    local maxSize = tonumber((driftgod.S and driftgod.S.introLogoPixelSize) or 990) or 990

    local ratio = 1.0
    if texW and texH and texH ~= 0 then
        ratio = texW / texH
    end

    local logoW, logoH
    if ratio >= 1.0 then
        logoW = maxSize
        logoH = maxSize / ratio
    else
        logoH = maxSize
        logoW = maxSize * ratio
    end

    local centerX = screenW * 0.50
    local centerY = screenH * 0.30

    local okDraw, errDraw = driftgod.Try(function()
        ImGui.BgAddImageRotated(srv, centerX, centerY, logoW, logoH, 0.0, alpha)
    end)

    driftgod.Try(function()
        local caption = "Drift Like a God."
        local credit = "Developed By: " .. tostring(driftgod.Developer or "Animus")
        local discordCredit = "Discord: " .. tostring(driftgod.Discord or "animusx1337")
        local versionCredit = "Version: " .. tostring(driftgod.Version or "v1.0.1")
        local captionGap = tonumber((driftgod.S and driftgod.S.introLogoCaptionGap) or -115) or -115
        local captionY = centerY + (logoH / 2) + captionGap
        local creditY = captionY + 38
        local discordY = creditY + 30
        local versionY = discordY + 34

        local purpleR, purpleG, purpleB = 166, 94, 252
        local whiteR, whiteG, whiteB = 255, 255, 255
        local textAlpha = math.max(0, math.min(255, tonumber(alpha) or 255))

        local captionWidth = string.len(caption) * 17
        local creditWidth = string.len(credit) * 11
        local discordWidth = string.len(discordCredit) * 9
        local versionWidth = string.len(versionCredit) * 9

        if ImGui and ImGui.FgAddText then
            ImGui.FgAddText(centerX - (captionWidth / 2), captionY, purpleR, purpleG, purpleB, textAlpha, caption)
            ImGui.FgAddText(centerX - (creditWidth / 2), creditY, whiteR, whiteG, whiteB, textAlpha, credit)
            ImGui.FgAddText(centerX - (discordWidth / 2), discordY, whiteR, whiteG, whiteB, textAlpha, discordCredit)
            ImGui.FgAddText(centerX - (versionWidth / 2), versionY, purpleR, purpleG, purpleB, textAlpha, versionCredit)
        elseif ImGui and ImGui.BgAddText then
            ImGui.BgAddText(centerX - (captionWidth / 2), captionY, purpleR, purpleG, purpleB, textAlpha, caption)
            ImGui.BgAddText(centerX - (creditWidth / 2), creditY, whiteR, whiteG, whiteB, textAlpha, credit)
            ImGui.BgAddText(centerX - (discordWidth / 2), discordY, whiteR, whiteG, whiteB, textAlpha, discordCredit)
            ImGui.BgAddText(centerX - (versionWidth / 2), versionY, purpleR, purpleG, purpleB, textAlpha, versionCredit)
        end
    end)

    driftgod.IntroLogoPresentDrawCount = (driftgod.IntroLogoPresentDrawCount or 0) + 1
    DG_PresentLogoLog44(
        "ON_PRESENT draw ok=" .. tostring(okDraw) ..
        " texId=" .. tostring(texId) ..
        " screen=" .. tostring(math.floor(screenW)) .. "x" .. tostring(math.floor(screenH)) ..
        " center=" .. tostring(math.floor(centerX)) .. "," .. tostring(math.floor(centerY)) ..
        " size=" .. tostring(math.floor(logoW)) .. "x" .. tostring(math.floor(logoH)) ..
        " alpha=" .. tostring(alpha) ..
        " err=" .. tostring(errDraw),
        false
    )
end

function driftgod.RegisterIntroLogoOnPresent()
    if driftgod.IntroLogoPresentRegistered == true then return end
    driftgod.IntroLogoPresentRegistered = true

    if EventMgr and eLuaEvent and eLuaEvent.ON_PRESENT then
        EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
            if DG and driftgod.DrawIntroLogoOnPresent then
                driftgod.DrawIntroLogoOnPresent()
            end
        end)

        DG_PresentLogoLog44("ON_PRESENT logo handler registered. CaptionHigher installed: purple caption moved 20% higher, scale=0.94.", true)
    else
        DG_PresentLogoLog44("ON_PRESENT unavailable. EventMgr/eLuaEvent.ON_PRESENT missing.", true)
    end
end

driftgod.RegisterIntroLogoOnPresent()

DG_PresentLogoLog44("CaptionHigher code patch installed.", true)

driftgod.Try(function()
    driftgod.S = driftgod.S or {}
    driftgod.S.logoIntroCaption = ""
    driftgod.S.introLogoCaption = ""
end)

driftgod.Try(function()
    driftgod.S = driftgod.S or {}
    driftgod.S.introTitle = ""
    driftgod.S.logoIntroTitle = ""
    driftgod.S.showIntroTitleText = false
end)

driftgod.Try(function()

end)

if Script and Script.RegisterLooped then
    Script.RegisterLooped(function()
        if driftgod.RenderStuntUnlockPolish then driftgod.RenderStuntUnlockPolish() end
        if driftgod.MonitorStuntUseRun then driftgod.MonitorStuntUseRun() end
        if driftgod.UpdateSessionChallengeRunScore then driftgod.UpdateSessionChallengeRunScore(driftgod.S and driftgod.S.currentScore or 0) end
        if driftgod.MarkSessionChallengeRivalBeatFromState then driftgod.MarkSessionChallengeRivalBeatFromState("hud poll") end
        if driftgod.RenderStuntUpgradePolish then driftgod.RenderStuntUpgradePolish() end
    end)
end

if false and Script and Script.RegisterLooped then
    Script.RegisterLooped(function()
        if driftgod.RenderLockedArcadePresetBanner then driftgod.RenderLockedArcadePresetBanner() end
    end)
end

return DG
end

__DG_BUNDLE_LOADERS["ui.input_hud"] = function()
DG = DG or {}

function driftgod.DrawInputKey(label, control, x, y, w, h, forcePressed)
    if driftgod.S.inputHudEnabled ~= true then return end

    local pressed = forcePressed ~= nil and forcePressed == true or driftgod.IsControlPressed(control)

    local bgR,bgG,bgB,bgA = 20,20,26,150
    local brR,brG,brB,brA = 190,90,255,150
    local txR,txG,txB,txA = 230,230,235,215

    if pressed then
        bgR,bgG,bgB,bgA = 190,90,255,230
        brR,brG,brB,brA = 255,255,255,230
        txR,txG,txB,txA = 255,255,255,255
    end

    driftgod.DrawRect(x, y, w + 0.004, h + 0.004, brR, brG, brB, brA)
    driftgod.DrawRect(x, y, w, h, bgR, bgG, bgB, bgA)
    driftgod.DrawText(label, x, y - (h * 0.30), 0.28 * (driftgod.S.inputHudScale or 0.40), txR, txG, txB, txA, 4)
end

function driftgod.DrawInputVisualizer()
    if driftgod.S.inputHudEnabled ~= true then return end
    if not driftgod.HasNatives() then return end
    if not driftgod.IsDrivingVehicle() then return end

    local s = driftgod.S.inputHudScale or 0.50
    local x = driftgod.S.inputHudX or 0.190
    local y = driftgod.S.inputHudY or 0.805

    local keyW = 0.036 * s
    local keyH = 0.042 * s
    local gap = 0.006 * s

    local c = driftgod.Controls

    driftgod.DrawInputKey("W", c.W, x + keyW + gap, y, keyW, keyH)
    driftgod.DrawInputKey("A", c.A, x, y + keyH + gap, keyW, keyH)
    driftgod.DrawInputKey("S", c.S, x + keyW + gap, y + keyH + gap, keyW, keyH)
    driftgod.DrawInputKey("D", c.D, x + (keyW + gap) * 2, y + keyH + gap, keyW, keyH)
    driftgod.DrawInputKey("B", c.B, x + (keyW + gap) * 3.35, y + keyH + gap, keyW * 1.35, keyH)

    driftgod.DrawInputKey("SHIFT", c.SHIFT, x, y + (keyH + gap) * 2, keyW * 2.15, 0.034 * s, driftgod.IsDriftHeld())
    driftgod.DrawInputKey("SPACE", c.SPACE, x + keyW + gap, y + (keyH + gap) * 3, (keyW * 3.0) + (gap * 2.0), 0.034 * s)
end

return DG
end

