local function log(msg)
    if DG and driftgod.Log then
        driftgod.Log("[PTFX] " .. tostring(msg))
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo("[DriftGod] [PTFX] " .. tostring(msg))
    end
end

local function toast(msg, ms)
    if driftgod.Toast then
        driftgod.Toast(tostring(msg), ms or 2200)
    elseif GUI and GUI.AddToast then
        GUI.AddToast("DriftGod", tostring(msg), ms or 2200)
    end
end

local function ptrToHandle(ptr)
    if not ptr then return 0 end
    if type(ptr) == "number" then return ptr end

    local h = 0
    driftgod.Try(function()
        if GTA and GTA.PointerToHandle then
            h = GTA.PointerToHandle(ptr)
        end
    end)

    return tonumber(h) or 0
end

local function getVehicleHandle()
    local ptr = nil

    driftgod.Try(function()
        if driftgod.GetVehicle then
            ptr = driftgod.GetVehicle()
        end
    end)

    if not ptr or ptr == 0 then
        driftgod.Try(function()
            if GTA and GTA.GetLocalVehicle then
                ptr = GTA.GetLocalVehicle()
            end
        end)
    end

    local h = ptrToHandle(ptr)
    log("vehicle ptr=" .. tostring(ptr) .. " handle=" .. tostring(h))
    return h
end

local function networkSessionStarted()
    local started = false
    driftgod.Try(function()
        if NETWORK and NETWORK.NETWORK_IS_SESSION_STARTED then
            started = NETWORK.NETWORK_IS_SESSION_STARTED()
        elseif Natives then
            started = Natives.InvokeBool(0x9DE624D2FC4B603F)
        end
    end)
    return started == true
end

local function runContext(fn)
    driftgod.S = driftgod.S or {}

    if driftgod.S.ptfxUseFreemodeScript == true then
        if not networkSessionStarted() then
            log("Freemode requested but NETWORK_IS_SESSION_STARTED=false; using local context.")
            return driftgod.Try(fn)
        end

        if Script and Script.ExecuteAsScript then
            local ok, err = driftgod.Try(function()
                Script.ExecuteAsScript("freemode", function()
                    fn()
                end)
            end)
            log("ExecuteAsScript(freemode) ok=" .. tostring(ok) .. " err=" .. tostring(err))
            return ok, err
        end

        log("Freemode requested but Script.ExecuteAsScript unavailable; using local context.")
    end

    return driftgod.Try(fn)
end

local function requestPtfx(dict)
    dict = tostring(dict or "core")

    local okReq, errReq = driftgod.Try(function()
        if STREAMING and STREAMING.REQUEST_NAMED_PTFX_ASSET then
            STREAMING.REQUEST_NAMED_PTFX_ASSET(dict)
        elseif Natives then
            Natives.InvokeVoid(0xB80D8756B4668AB6, dict)
        end
    end)

    local loaded = true
    driftgod.Try(function()
        if STREAMING and STREAMING.HAS_NAMED_PTFX_ASSET_LOADED then
            local startedAt = os.clock()
            loaded = STREAMING.HAS_NAMED_PTFX_ASSET_LOADED(dict)
            while not loaded and (os.clock() - startedAt) < 2.0 do
                if Script and Script.Yield then Script.Yield(0) end
                loaded = STREAMING.HAS_NAMED_PTFX_ASSET_LOADED(dict)
            end
        end
    end)

    local okUse, errUse = driftgod.Try(function()
        if GRAPHICS and GRAPHICS.USE_PARTICLE_FX_ASSET then
            GRAPHICS.USE_PARTICLE_FX_ASSET(dict)
        elseif Natives then
            Natives.InvokeVoid(0x6C38AF3693A69A91, dict)
        end
    end)

    log("request dict=" .. dict .. " okReq=" .. tostring(okReq) .. " loaded=" .. tostring(loaded) .. " okUse=" .. tostring(okUse) .. " errReq=" .. tostring(errReq) .. " errUse=" .. tostring(errUse))
    return okUse == true
end

local function startLoopedOnEntityOffset(entity, dict, effect, pos, scale)
    scale = tonumber(scale or 1.0) or 1.0
    requestPtfx(dict)

    local handle = -1
    local ok, err = driftgod.Try(function()
        if driftgod.S and driftgod.S.ptfxUseFreemodeScript == true and GRAPHICS and GRAPHICS.START_NETWORKED_PARTICLE_FX_LOOPED_ON_ENTITY then

            handle = GRAPHICS.START_NETWORKED_PARTICLE_FX_LOOPED_ON_ENTITY(effect, entity, pos.x, pos.y, pos.z, 0.0, 0.0, 0.0, scale, false, false, false)
        elseif GRAPHICS and GRAPHICS.START_PARTICLE_FX_LOOPED_ON_ENTITY then
            handle = GRAPHICS.START_PARTICLE_FX_LOOPED_ON_ENTITY(effect, entity, pos.x, pos.y, pos.z, 0.0, 0.0, 0.0, scale, false, false, false)
        elseif GRAPHICS and GRAPHICS.START_NETWORKED_PARTICLE_FX_LOOPED_ON_ENTITY then
            handle = GRAPHICS.START_NETWORKED_PARTICLE_FX_LOOPED_ON_ENTITY(effect, entity, pos.x, pos.y, pos.z, 0.0, 0.0, 0.0, scale, false, false, false)
        elseif Natives then

            handle = Natives.InvokeInt(0x1AE42C1660FD6517, effect, entity, pos.x, pos.y, pos.z, 0.0, 0.0, 0.0, scale, false, false, false)
        end
    end)

    log("start looped label=" .. tostring(pos.label) ..
        " dict=" .. tostring(dict) ..
        " effect=" .. tostring(effect) ..
        " entity=" .. tostring(entity) ..
        " offset=" .. tostring(pos.x) .. "," .. tostring(pos.y) .. "," .. tostring(pos.z) ..
        " scale=" .. tostring(scale) ..
        " ok=" .. tostring(ok) ..
        " handle=" .. tostring(handle) ..
        " err=" .. tostring(err))

    if ok and handle and handle ~= 0 and handle ~= -1 then
        driftgod.PTFX.handles[#driftgod.PTFX.handles + 1] = handle
        return true
    end

    return false
end

local function getOffsets(location)
    location = tostring(location or "wheels")

    if location == "wheels" then
        return {
            { label = "wheel_center_lf", x = -0.95, y =  1.20, z = -0.32 },
            { label = "wheel_center_rf", x =  0.95, y =  1.20, z = -0.32 },
            { label = "wheel_center_lr", x = -0.95, y = -1.20, z = -0.32 },
            { label = "wheel_center_rr", x =  0.95, y = -1.20, z = -0.32 }
        }
    elseif location == "taillights" then
        return {
            { label = "rear_taillight_l", x = -0.70, y = -2.25, z = 0.55 },
            { label = "rear_taillight_r", x =  0.70, y = -2.25, z = 0.55 }
        }
    end

    return {
        { label = "exhaust_l", x = -0.42, y = -2.25, z = 0.28 },
        { label = "exhaust_r", x =  0.42, y = -2.25, z = 0.28 }
    }
end

local function selectedEffect()
    driftgod.S = driftgod.S or {}
    local total = #driftgod.PTFX.effects
    if total <= 0 then return nil, 0 end

    driftgod.S.ptfxSelectedIndex = tonumber(driftgod.S.ptfxSelectedIndex or 1) or 1
    if driftgod.S.ptfxSelectedIndex < 1 then driftgod.S.ptfxSelectedIndex = total end
    if driftgod.S.ptfxSelectedIndex > total then driftgod.S.ptfxSelectedIndex = 1 end

    return driftgod.PTFX.effects[driftgod.S.ptfxSelectedIndex], driftgod.S.ptfxSelectedIndex
end

function driftgod.PTFXSelectedLabel()
    local fx, idx = selectedEffect()
    if not fx then return "None" end
    return tostring(idx) .. "/" .. tostring(#driftgod.PTFX.effects) .. " " .. tostring(fx.label) .. " | " .. tostring(fx.dict) .. " / " .. tostring(fx.effect)
end

function driftgod.SetPTFXLocationExhaust()
    driftgod.S = driftgod.S or {}
    driftgod.S.ptfxLocation = "exhaust"
    log("location=exhaust")
    toast("PTFX Location: Exhaust")
end

function driftgod.SetPTFXLocationWheels()
    driftgod.S = driftgod.S or {}
    driftgod.S.ptfxLocation = "wheels"
    log("location=wheels")
    toast("PTFX Location: Wheel Center")
end

function driftgod.SetPTFXLocationTaillights()
    driftgod.S = driftgod.S or {}
    driftgod.S.ptfxLocation = "taillights"
    log("location=taillights")
    toast("PTFX Location: Rear Taillights")
end

local function stopHandlesQuiet()
    local count = 0

    for _, handle in ipairs(driftgod.PTFX.handles or {}) do
        driftgod.Try(function()
            if GRAPHICS and GRAPHICS.REMOVE_PARTICLE_FX then
                GRAPHICS.REMOVE_PARTICLE_FX(handle, false)
            elseif Natives then
                Natives.InvokeVoid(0xC401503DFE8D53CF, handle, false)
            end
        end)
        count = count + 1
    end

    driftgod.PTFX.handles = {}
    return count
end

local function startSelectedQuiet()
    driftgod.S = driftgod.S or {}

    local fx, idx = selectedEffect()
    if not fx then
        log("quiet start failed: no effect")
        return 0
    end

    local veh = getVehicleHandle()
    if not veh or veh == 0 then
        log("quiet start failed: no vehicle")
        return 0
    end

    local location = tostring(driftgod.S.ptfxLocation or "wheels")
    local offsets = getOffsets(location)
    local started = 0

    runContext(function()
        for _, pos in ipairs(offsets) do
            if startLoopedOnEntityOffset(veh, fx.dict, fx.effect, pos, fx.scale or 1.0) then
                started = started + 1
            end
        end
    end)

    log("quiet restart selected=" .. tostring(idx) ..
        " label=" .. tostring(fx.label) ..
        " location=" .. tostring(location) ..
        " started=" .. tostring(started) ..
        " freemode=" .. tostring(driftgod.S.ptfxUseFreemodeScript == true))

    return started
end

function driftgod.StopPTFX()
    if ShouldUnload and ShouldUnload() then
        -- Cherax may fire toggle callbacks while removing features. Never invoke particle
        -- natives, logs, or toasts from those teardown callbacks.
        driftgod.PTFX = driftgod.PTFX or {}
        driftgod.PTFX.handles = {}
        driftgod.S = driftgod.S or {}
        driftgod.S.ptfxRunning = false
        return 0
    end
    local count = stopHandlesQuiet()
    driftgod.S.ptfxRunning = false
    log("stopped handles=" .. tostring(count))
    toast("Stopped PTFX", 1600)
end

function driftgod.StartPTFX()
    driftgod.S = driftgod.S or {}

    stopHandlesQuiet()

    local fx, idx = selectedEffect()
    if not fx then
        toast("No PTFX selected.", 2200)
        return
    end

    local veh = getVehicleHandle()
    if not veh or veh == 0 then
        toast("PTFX needs a vehicle.", 2200)
        log("start failed: no vehicle")
        return
    end

    local location = tostring(driftgod.S.ptfxLocation or "wheels")
    local offsets = getOffsets(location)
    local started = 0

    runContext(function()
        for _, pos in ipairs(offsets) do
            if startLoopedOnEntityOffset(veh, fx.dict, fx.effect, pos, fx.scale or 1.0) then
                started = started + 1
            end
        end
    end)

    driftgod.S.ptfxRunning = started > 0
    driftgod.S.ptfxLastRefreshClock = os.clock()
    log("START selected=" .. tostring(idx) ..
        " label=" .. tostring(fx.label) ..
        " dict=" .. tostring(fx.dict) ..
        " effect=" .. tostring(fx.effect) ..
        " location=" .. tostring(location) ..
        " started=" .. tostring(started) ..
        " freemode=" .. tostring(driftgod.S.ptfxUseFreemodeScript == true))

    toast("PTFX: " .. tostring(fx.label) .. " | " .. tostring(location), 2600)
end

function driftgod.NextPTFX()
    driftgod.S = driftgod.S or {}
    local total = #driftgod.PTFX.effects
    if total <= 0 then return end

    driftgod.StopPTFX()
    driftgod.S.ptfxSelectedIndex = (tonumber(driftgod.S.ptfxSelectedIndex or 1) or 1) + 1
    if driftgod.S.ptfxSelectedIndex > total then driftgod.S.ptfxSelectedIndex = 1 end

    log("next selected=" .. driftgod.PTFXSelectedLabel())
    driftgod.StartPTFX()
end

function driftgod.PreviousPTFX()
    driftgod.S = driftgod.S or {}
    local total = #driftgod.PTFX.effects
    if total <= 0 then return end

    driftgod.StopPTFX()
    driftgod.S.ptfxSelectedIndex = (tonumber(driftgod.S.ptfxSelectedIndex or 1) or 1) - 1
    if driftgod.S.ptfxSelectedIndex < 1 then driftgod.S.ptfxSelectedIndex = total end

    log("previous selected=" .. driftgod.PTFXSelectedLabel())
    driftgod.StartPTFX()
end

function driftgod.ToggleFreemodePTFXMode()
    driftgod.S = driftgod.S or {}
    driftgod.S.ptfxUseFreemodeScript = not (driftgod.S.ptfxUseFreemodeScript == true)
    log("freemode mode=" .. tostring(driftgod.S.ptfxUseFreemodeScript == true))
    toast("PTFX Freemode Mode: " .. (driftgod.S.ptfxUseFreemodeScript and "ON" or "OFF"), 2200)
end

function driftgod.RefreshPTFXLoop()
    driftgod.S = driftgod.S or {}
    if driftgod.S.ptfxRunning ~= true then return end

    stopHandlesQuiet()
    local started = startSelectedQuiet()
    driftgod.S.ptfxRunning = started > 0
    driftgod.S.ptfxLastRefreshClock = os.clock()

    log("loop keeper refresh started=" .. tostring(started))
end

function driftgod.LightTrailsTick()
    driftgod.S = driftgod.S or {}

    if driftgod.S.ptfxRunning == true and driftgod.S.ptfxLoopKeeperEnabled ~= false then
        local intervalMs = tonumber(driftgod.S.ptfxLoopRefreshMs or 850) or 850
        local last = tonumber(driftgod.S.ptfxLastRefreshClock or 0) or 0
        local now = os.clock()

        if ((now - last) * 1000.0) >= intervalMs then
            driftgod.RefreshPTFXLoop()
        end
    end
end

function driftgod.TogglePTFXLoopKeeper()
    driftgod.S = driftgod.S or {}
    driftgod.S.ptfxLoopKeeperEnabled = not (driftgod.S.ptfxLoopKeeperEnabled ~= false)
    log("loop keeper=" .. tostring(driftgod.S.ptfxLoopKeeperEnabled ~= false))
    toast("PTFX Loop Keeper: " .. ((driftgod.S.ptfxLoopKeeperEnabled ~= false) and "ON" or "OFF"), 1800)
end

function driftgod.PTFXLoopKeeperStatus()
    driftgod.S = driftgod.S or {}
    return "Loop Keeper: " .. tostring(driftgod.S.ptfxLoopKeeperEnabled ~= false) .. " | Refresh: " .. tostring(driftgod.S.ptfxLoopRefreshMs or 850) .. "ms"
end

driftgod.StopFreemodeLocationPTFX = driftgod.StopPTFX
driftgod.TestWheelCompareClownTrail = function() driftgod.S.ptfxSelectedIndex = 1; driftgod.SetPTFXLocationWheels(); driftgod.StartPTFX() end
driftgod.TestWheelCompareRedTrail = function()
    driftgod.S.ptfxSelectedIndex = 1
    for i, fx in ipairs(driftgod.PTFX.effects) do
        if fx.effect == "veh_light_red_trail" then driftgod.S.ptfxSelectedIndex = i break end
    end
    driftgod.SetPTFXLocationWheels()
    driftgod.StartPTFX()
end

if driftgod.S.ptfxSelectedIndex == nil then driftgod.S.ptfxSelectedIndex = 1 end
if driftgod.S.ptfxLocation == nil then driftgod.S.ptfxLocation = "wheels" end
if driftgod.S.ptfxUseFreemodeScript == nil then driftgod.S.ptfxUseFreemodeScript = false end
if driftgod.S.ptfxLoopKeeperEnabled == nil then driftgod.S.ptfxLoopKeeperEnabled = true end
if driftgod.S.ptfxLoopRefreshMs == nil then driftgod.S.ptfxLoopRefreshMs = 850 end

return DG
end

