function driftgod.EnsureSpawnSystem(source)
    if driftgod.SpawnZentorno or driftgod.TrySpawnZentorno then return true end
    local ok, err = driftgod.Try(function() require("systems.spawn") end)
    if ok ~= true then
        if driftgod.Log then driftgod.Log("[Spawn] Failed to load systems.spawn from " .. tostring(source or "menu") .. ": " .. tostring(err)) end
        if driftgod.Toast then driftgod.Toast("Spawn failed: spawn system load error", 2500) end
        return false
    end
    return driftgod.SpawnZentorno ~= nil or driftgod.TrySpawnZentorno ~= nil
end

function driftgod.Hash(name) return Utils.Joaat("DG_V61319_" .. name) end

function driftgod.AddButton(key, name, desc, cb)
    driftgod.H[key] = driftgod.Hash(key)
    return driftgod.SafeAddFeature(driftgod.H[key], name, eFeatureType.Button, desc or "", cb)
end

function driftgod.AddToggle(key, name, desc, cb, defaultValue)
    driftgod.H[key] = driftgod.Hash(key)
    local f = driftgod.SafeAddFeature(driftgod.H[key], name, eFeatureType.Toggle, desc or "", cb)
    if f and f.SetDefaultValue then f:SetDefaultValue(defaultValue == true):Reset() end
    return f
end

function driftgod.AddToggleOnTick(key, name, desc, cb, defaultValue)
    driftgod.H[key] = driftgod.Hash(key)
    local f = driftgod.SafeAddFeature(driftgod.H[key], name, eFeatureType.Toggle, desc or "", cb)
    if f and f.RegisterCallbackTrigger then f:RegisterCallbackTrigger(eCallbackTrigger.OnTick) end
    if f and f.SetDefaultValue then f:SetDefaultValue(defaultValue == true):Reset() end
    return f
end

function driftgod.AddSliderInt(key, name, desc, minValue, maxValue, stepValue, defaultValue, cb)
    driftgod.H[key] = driftgod.Hash(key)
    local f = driftgod.SafeAddFeature(driftgod.H[key], name, eFeatureType.SliderInt, desc or "", function(feat)
        if cb then cb(feat) end
    end)

    if f and f.SetLimitValues then f:SetLimitValues(minValue, maxValue) end
    if f and f.SetStepSize then f:SetStepSize(stepValue or 1) end
    if f and f.SetIntValue then f:SetIntValue(defaultValue or minValue) end

    return f
end

local function capDrift() if driftgod.IsArcadePresetTestingMode and driftgod.IsArcadePresetTestingMode() then return 5 end if driftgod.GetUnlockedDriftLevel then return driftgod.GetUnlockedDriftLevel() end return 5 end
local function capStability() if driftgod.IsArcadePresetTestingMode and driftgod.IsArcadePresetTestingMode() then return 5 end if driftgod.GetUnlockedStabilityLevel then return driftgod.GetUnlockedStabilityLevel() end return 5 end
local function capAutoCounterSteer() if driftgod.IsArcadePresetTestingMode and driftgod.IsArcadePresetTestingMode() then return 5 end if driftgod.GetUnlockedAutoCounterSteerLevel then return driftgod.GetUnlockedAutoCounterSteerLevel() end return 5 end
local function capMomentum() if driftgod.IsArcadePresetTestingMode and driftgod.IsArcadePresetTestingMode() then return 5 end if driftgod.GetUnlockedMomentumLevel then return driftgod.GetUnlockedMomentumLevel() end return 5 end
local function capAccel() if driftgod.IsArcadePresetTestingMode and driftgod.IsArcadePresetTestingMode() then return 5 end if driftgod.GetUnlockedAccelLevel then return driftgod.GetUnlockedAccelLevel() end return 5 end

local function cint(v, mn, mx)
    if driftgod.ClampInt then return driftgod.ClampInt(v, mn, mx) end
    v = math.floor(v or mn)
    if v < mn then v = mn end
    if v > mx then v = mx end
    return v
end

local function cfloat(v, mn, mx)
    if driftgod.ClampFloat then return driftgod.ClampFloat(v, mn, mx) end
    v = v or mn
    if v < mn then v = mn end
    if v > mx then v = mx end
    return v
end

local function setDrift(v)
    local cap = capDrift()
    driftgod.S.driftGripLevel = cint(v, 1, cap)
    toast("Drift Level: " .. driftgod.S.driftGripLevel .. " / " .. cap .. " (flipped feel)", 1500)
end

local function setStability(v)
    local cap = capStability()
    driftgod.S.driftStabilityLevel = cint(v, 1, cap)
    toast("Stability: " .. driftgod.S.driftStabilityLevel .. " / " .. cap, 1500)
end

local function setAutoCounterSteer(v)
