    driftgod.S.autoCounterSteerLevel = cint(v, 1, cap)
    toast("Automatic Counter-Steering: " .. driftgod.S.autoCounterSteerLevel .. " / " .. cap, 1500)
end

local function setMomentum(v)
    local cap = capMomentum()
    driftgod.S.momentumStrength = cint(v, 1, cap)
    toast("Momentum: " .. driftgod.S.momentumStrength .. " / " .. cap, 1500)
end

local function setAccel(v)
    local cap = capAccel()
    driftgod.S.accelStrength = cint(v, 1, cap)
    toast("Acceleration Assist: " .. driftgod.S.accelStrength .. " / " .. cap, 1500)
end

function driftgod.ClampAssistToUnlocks(showToast)
    driftgod.S = driftgod.S or {}

    local oldDrift = tonumber(driftgod.S.driftGripLevel or 1) or 1
    local oldStability = tonumber(driftgod.S.driftStabilityLevel or driftgod.S.stabilityLevel or 1) or 1
    local oldCounter = tonumber(driftgod.S.autoCounterSteerLevel or driftgod.S.counterSteerLevel or 1) or 1
    local oldMomentum = tonumber(driftgod.S.momentumStrength or driftgod.S.momentumLevel or 1) or 1
    local oldAccel = tonumber(driftgod.S.accelStrength or driftgod.S.accelerationLevel or 1) or 1

    local dCap = capDrift()
    local sCap = capStability()
    local cCap = capAutoCounterSteer()
    local mCap = capMomentum()
    local aCap = capAccel()

    driftgod.S.driftGripLevel = cint(oldDrift, 1, dCap)
    driftgod.S.driftStabilityLevel = cint(oldStability, 1, sCap)
    driftgod.S.autoCounterSteerLevel = cint(oldCounter, 1, cCap)
    driftgod.S.momentumStrength = cint(oldMomentum, 1, mCap)
    driftgod.S.accelStrength = cint(oldAccel, 1, aCap)

    driftgod.S.stabilityLevel = driftgod.S.driftStabilityLevel
    driftgod.S.stability = driftgod.S.driftStabilityLevel
    driftgod.S.driftStability = driftgod.S.driftStabilityLevel

    driftgod.S.counterSteerLevel = driftgod.S.autoCounterSteerLevel
    driftgod.S.autoCounterSteer = driftgod.S.autoCounterSteerLevel
    driftgod.S.driftCounterSteer = driftgod.S.autoCounterSteerLevel

    driftgod.S.momentumLevel = driftgod.S.momentumStrength
    driftgod.S.momentum = driftgod.S.momentumStrength
    driftgod.S.driftMomentum = driftgod.S.momentumStrength

    driftgod.S.accelerationLevel = driftgod.S.accelStrength
    driftgod.S.acceleration = driftgod.S.accelStrength
    driftgod.S.driftAcceleration = driftgod.S.accelStrength

    driftgod.S.momentumAssistEnabled = driftgod.S.momentumAssistEnabled == true and mCap >= 2 and driftgod.S.momentumStrength >= 2
    driftgod.S.accelAssistEnabled = driftgod.S.accelAssistEnabled == true and aCap >= 2 and driftgod.S.accelStrength >= 2

    local changed = oldDrift ~= driftgod.S.driftGripLevel or oldStability ~= driftgod.S.driftStabilityLevel or oldCounter ~= driftgod.S.autoCounterSteerLevel or oldMomentum ~= driftgod.S.momentumStrength or oldAccel ~= driftgod.S.accelStrength
    if changed and showToast ~= false then
        toast("Preset capped to unlocked progression levels.", 2200)
    end
    return changed
end

