function driftgod.RestoreDefaultSettings()
    for k, v in pairs(driftgod.DefaultSettings or {}) do driftgod.S[k] = v end
    if driftgod.S.inputHudEnabled == nil then driftgod.S.inputHudEnabled = false end
driftgod.S.disableScrollWheel = false
    driftgod.S.inputHudX = 0.190
    driftgod.S.inputHudY = 0.915
    driftgod.S.inputHudScale = 0.40
    driftgod.S.inputHudBackground = false

    driftgod.S.mphHudEnabled = true
    driftgod.S.mphHudX = 0.175
    driftgod.S.mphHudY = 0.977
    driftgod.S.mphHudScale = 0.65
    driftgod.S.mphHudBackground = false
    driftgod.S.autoPlateEnabled = false

    driftgod.Try(function()
        if FeatureMgr and FeatureMgr.GetFeature and driftgod.H then
            local ids = {
                StabilityPlus = 5,
                AccelPlus = 5,
                MomentumPlus = 5,
            }
            for key, value in pairs(ids) do
                local f = driftgod.H[key] and FeatureMgr.GetFeature(driftgod.H[key])
                if f and f.SetIntValue then f:SetIntValue(value) end
            end
        end
    end)

    if driftgod.SaveSettings then driftgod.SaveSettings(false) end
    toast("Defaults restored. Input Visualizer OFF. Plate OFF. Default Drifting remains startup tune.", 3000)
end

function driftgod.ApplyKriegerPreset(showToast)
    if driftgod.ClearLockedArcadePresetBlocker then driftgod.ClearLockedArcadePresetBlocker("Krieger preset applied") end
    driftgod.S.activeStartupPreset = "Krieger"
    driftgod.S.driftAssistEnabled = true
    driftgod.S.driftGripLevel = 1
    driftgod.S.driftStabilityLevel = 5
    driftgod.S.accelAssistEnabled = false
    driftgod.S.accelStrength = 2
    driftgod.S.momentumAssistEnabled = false
    driftgod.S.momentumStrength = 3

    driftgod.S.experimentalTractionEnabled = true
    driftgod.S.experimentalTractionLevel = 1

    if driftgod.ClampAssistToUnlocks then driftgod.ClampAssistToUnlocks(false) end

    if showToast ~= false then
        toast("Preset applied: Krieger (capped to unlocks)", 2500)
    end
end

local function applyPreset(name, drift, stability, momentum, accel, useMomentum, useAccel)
    if driftgod.ClearLockedArcadePresetBlocker then driftgod.ClearLockedArcadePresetBlocker("preset applied") end
    driftgod.S.driftGripLevel = math.min(drift, capDrift())
    driftgod.S.driftStabilityLevel = math.min(stability, capStability())
    driftgod.S.momentumStrength = math.min(momentum, capMomentum())
    driftgod.S.accelStrength = math.min(accel, capAccel())
    driftgod.S.momentumAssistEnabled = useMomentum and capMomentum() >= 2 and driftgod.S.momentumStrength >= 2
    driftgod.S.accelAssistEnabled = useAccel and capAccel() >= 2 and driftgod.S.accelStrength >= 2
    if driftgod.ClampAssistToUnlocks then driftgod.ClampAssistToUnlocks(false) end
    toast("Preset applied: " .. name .. " (capped)", 2000)
end

