        drift=1, stability=5, momentum=3, accel=3, useMomentum=true, useAccel=true,
        intensity=34, angle=43, assist=94, min_speed=12.0, base_force=0.014, grip_pad=3.0, style="speedthread"
    },
    {
        id="corner_magnet", name="DriftGod", source_name="Corner Magnet", family="Technical / Windy Roads", unlock=100000, trial_until=3000,
        desc="DriftGod preset powered by the golden Corner Magnet tune. Starter trial until 3,000 Best Run, then permanent unlock at 100,000 Best Run.",
        drift=1, stability=5, momentum=3, accel=2, useMomentum=true, useAccel=true,
        intensity=32, angle=46, assist=90, min_speed=13.0, base_force=0.017, grip_pad=4.0, style="corner"
    },
}

driftgod.S = driftgod.S or {}

driftgod.S.testAllArcadeDriftPresets = true

function driftgod.IsArcadePresetTestingMode()
    return true
end

local function dgArcadePresetScore()

    driftgod.S = driftgod.S or {}
    local best = tonumber(driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore or 0) or 0
    local current = tonumber(driftgod.S.currentScore or 0) or 0
    if current > best then best = current end
    if best < 0 then best = 0 end
    return math.floor(best)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- reward score source
-- note: uses the best available score source for preset, tuning, and transition unlocks.
-- ═══════════════════════════════════════════════════════════════════════════════════

function driftgod.GetArcadeDriftPresetScore()
    return dgArcadePresetScore()
end

function driftgod.GetNextLockedArcadeDriftPreset()
    local score = driftgod.GetArcadeDriftPresetScore and driftgod.GetArcadeDriftPresetScore() or dgArcadePresetScore()
    local best = nil
    local bestNeed = nil
    for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
        local need = tonumber(p.unlock or 0) or 0
        if need > 0 and score < need then
            if not bestNeed or need < bestNeed then
                best = p
                bestNeed = need
            end
        end
    end
    if not best then return nil, 0, 0, score end
    return best, bestNeed or 0, math.max(0, (bestNeed or 0) - score), score
end

function driftgod.GetNextArcadeDriftPresetHint()
    local p, need, left, score = driftgod.GetNextLockedArcadeDriftPreset()
    if not p then
        return "All Drift Presets unlocked. Nice work."
    end
    local leftText = tostring(left or 0)
    if dgFmtNum then leftText = dgFmtNum(left) end
    local needText = tostring(need or 0)
    if dgFmtNum then needText = dgFmtNum(need) end
    return "Unlock more in Arcade > Drift Presets. Only " .. leftText .. " Best Run score needed for " .. tostring(p.name or "next preset") .. " (" .. needText .. ")."
end

function driftgod.GetArcadeDriftPresetById(id)
    for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
        if p.id == id then return p end
    end
    return nil
end

function driftgod.IsArcadeDriftPresetTrialAvailable(id)
    local p = driftgod.GetArcadeDriftPresetById(id)
    if not p then return false end
    local trialUntil = tonumber(p.trial_until or 0) or 0
    if trialUntil <= 0 then return false end
    local score = dgArcadePresetScore()
    local need = tonumber(p.unlock or 0) or 0
    return score < trialUntil and score < need
end

function driftgod.IsArcadeDriftPresetUnlocked(id)
    local p = driftgod.GetArcadeDriftPresetById(id)
    if not p then return false end
    if driftgod.IsArcadePresetTestingMode and driftgod.IsArcadePresetTestingMode() then return true end
    if driftgod.IsArcadeDriftPresetTrialAvailable and driftgod.IsArcadeDriftPresetTrialAvailable(id) then return true end
    return dgArcadePresetScore() >= (tonumber(p.unlock or 0) or 0)
end

function driftgod.IsArcadeDriftPresetPermanentlyUnlocked(id)
    local p = driftgod.GetArcadeDriftPresetById(id)
    if not p then return false end
    if driftgod.IsArcadePresetTestingMode and driftgod.IsArcadePresetTestingMode() then return true end
    return dgArcadePresetScore() >= (tonumber(p.unlock or 0) or 0)
end

function driftgod.GetArcadeDriftPresetLabel(p)
    if not p then return "Unknown Preset" end
    local score = dgArcadePresetScore()
    local need = tonumber(p.unlock or 0) or 0
    local trialUntil = tonumber(p.trial_until or 0) or 0
    local active = (driftgod.S and driftgod.S.activeArcadeDriftPreset == p.id) and "  [ACTIVE]" or ""
    if driftgod.IsArcadePresetTestingMode and driftgod.IsArcadePresetTestingMode() then
        return tostring(p.name) .. " — TEST UNLOCKED" .. active
    end
    if driftgod.IsArcadeDriftPresetPermanentlyUnlocked and driftgod.IsArcadeDriftPresetPermanentlyUnlocked(p.id) then
        return tostring(p.name) .. " — UNLOCKED" .. active
    end
    if trialUntil > 0 and score < trialUntil then
        return "TRIAL: " .. tostring(p.name) .. " — Starter Preview until " .. tostring(trialUntil) .. " Best Run" .. active
    end
    return "LOCKED: " .. tostring(p.name) .. " | Unlock at " .. tostring(need) .. " | Current " .. tostring(score)
end

function driftgod.ClearLockedArcadePresetBlocker(reason)
    driftgod.S = driftgod.S or {}
    driftgod.S.lockedArcadeDriftPresetArmed = false
    driftgod.S.lockedArcadeDriftPresetId = nil
    driftgod.S.lockedArcadeDriftPresetName = nil
    driftgod.S.lockedArcadeDriftPresetNeed = 0
    driftgod.S.lockedArcadeDriftPresetCurrent = 0
    driftgod.S.lockedArcadeDriftPresetLastNoticeMs = 0
    driftgod.S.lockedArcadeDriftPresetBannerStart = 0
    driftgod.S.lockedArcadeDriftPresetBannerTitle = ""
    driftgod.S.lockedArcadeDriftPresetBannerText = ""
end

function driftgod.ArmLockedArcadePresetBlocker(p, currentScore, requiredScore)
    driftgod.S = driftgod.S or {}
    p = p or {}
    local need = tonumber(requiredScore or p.unlock or 0) or 0
    local cur = tonumber(currentScore or 0) or 0
    driftgod.S.lockedArcadeDriftPresetArmed = true
    driftgod.S.lockedArcadeDriftPresetId = tostring(p.id or "")
    driftgod.S.lockedArcadeDriftPresetName = tostring(p.name or "Drift Preset")
    driftgod.S.lockedArcadeDriftPresetNeed = need
    driftgod.S.lockedArcadeDriftPresetCurrent = cur
    driftgod.S.lockedArcadeDriftPresetLastNoticeMs = 0
    if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
end

function driftgod.IsLockedArcadePresetBlocking()
    driftgod.S = driftgod.S or {}
    if driftgod.S.lockedArcadeDriftPresetArmed ~= true then return false end
    local id = tostring(driftgod.S.lockedArcadeDriftPresetId or "")
    if id ~= "" and driftgod.IsArcadeDriftPresetUnlocked and driftgod.IsArcadeDriftPresetUnlocked(id) == true then
        driftgod.ClearLockedArcadePresetBlocker("now unlocked")
        return false
    end
    return true
end

function driftgod.ShowLockedArcadePresetShiftNotice()
    driftgod.S = driftgod.S or {}
    if not driftgod.IsLockedArcadePresetBlocking or not driftgod.IsLockedArcadePresetBlocking() then return end

    local now = driftgod.Now and driftgod.Now() or math.floor(os.clock() * 1000)
    if now - (tonumber(driftgod.S.lockedArcadeDriftPresetLastNoticeMs or 0) or 0) < 850 then return end
    driftgod.S.lockedArcadeDriftPresetLastNoticeMs = now

    local name = tostring(driftgod.S.lockedArcadeDriftPresetName or "Drift Preset")
    local need = tonumber(driftgod.S.lockedArcadeDriftPresetNeed or 0) or 0
    local cur = driftgod.GetArcadeDriftPresetScore and driftgod.GetArcadeDriftPresetScore() or (tonumber(driftgod.S.lockedArcadeDriftPresetCurrent or 0) or 0)
    local left = math.max(0, need - cur)

    driftgod.S.lockedArcadeDriftPresetBannerStart = now
    driftgod.S.lockedArcadeDriftPresetBannerTitle = "DRIFT PRESET LOCKED!"
    driftgod.S.lockedArcadeDriftPresetBannerText = "You need " .. tostring(need) .. " High Score to unlock " .. name .. "."

    if driftgod.Toast then
        driftgod.Toast("Drift Preset Locked! You need " .. tostring(need) .. " High Score to unlock this preset. Need " .. tostring(left) .. " more.", 2200)
    end
end

function driftgod.RenderLockedArcadePresetBanner()
    driftgod.S = driftgod.S or {}
    if not driftgod.DrawTextCenter then return end
    local start = tonumber(driftgod.S.lockedArcadeDriftPresetBannerStart or 0) or 0
    if start <= 0 then return end
    local now = driftgod.Now and driftgod.Now() or math.floor(os.clock() * 1000)
    local dur = 3300
    local e = now - start
    if e < 0 or e > dur then return end

    local t = e / dur
    local x
    if t < 0.22 then
        local p = t / 0.22; p = p*p*(3-2*p); x = -0.36 + 0.86*p
    elseif t < 0.72 then
        x = 0.5
    else
        local p = (t - 0.72) / 0.28; p = p*p*(3-2*p); x = 0.5 + 0.92*p
    end
    local alpha = 240
    if t > 0.78 then alpha = math.max(0, math.floor(240 * (1 - ((t - 0.78) / 0.22)))) end
    local y = 0.405
    driftgod.DrawTextCenter(driftgod.S.lockedArcadeDriftPresetBannerTitle or "DRIFT PRESET LOCKED!", x, y - 0.020, 0.58, 255, 90, 120, alpha, 7)
    driftgod.DrawTextCenter(driftgod.S.lockedArcadeDriftPresetBannerText or "Unlock this preset to drift.", x, y + 0.030, 0.34, 235, 225, 255, alpha, 4)
end

function driftgod.ApplyArcadeDriftPreset(id, showToast)
    driftgod.S = driftgod.S or {}
    local p = driftgod.GetArcadeDriftPresetById(id)
    if not p then
        if showToast ~= false then toast("Preset unavailable: " .. tostring(id), 2200) end
        return false
    end

    local score = dgArcadePresetScore()
    local need = tonumber(p.unlock or 0) or 0
    local trialAvailable = driftgod.IsArcadeDriftPresetTrialAvailable and driftgod.IsArcadeDriftPresetTrialAvailable(p.id)
    local permanentUnlocked = (driftgod.IsArcadePresetTestingMode and driftgod.IsArcadePresetTestingMode()) or score >= need
    if not trialAvailable and not permanentUnlocked then
        local left = math.max(0, need - score)
        if driftgod.ArmLockedArcadePresetBlocker then driftgod.ArmLockedArcadePresetBlocker(p, score, need) end
        if showToast ~= false then
            toast("Drift Preset Locked! You need " .. tostring(need) .. " High Score to unlock this preset. Need " .. tostring(left) .. " more.", 4200)
        end
        if driftgod.Log then driftgod.Log("[ArcadePreset] Locked armed " .. tostring(p.name) .. " | score=" .. tostring(score) .. "/" .. tostring(need)) end
        return false
    end

    if driftgod.ClearLockedArcadePresetBlocker then driftgod.ClearLockedArcadePresetBlocker("unlocked preset applied") end
    driftgod.S.activeArcadeDriftPreset = p.id
    driftgod.S.activeStartupPreset = p.name
    driftgod.S.r198BaseTuningPreset = p.id
    driftgod.S.r198ActiveCustomPreset = nil
    driftgod.S.driftAssistEnabled = true
    driftgod.S.driftGripLevel = math.min(tonumber(p.drift or 1) or 1, capDrift())
    driftgod.S.driftStabilityLevel = math.min(tonumber(p.stability or 1) or 1, capStability())
    driftgod.S.momentumStrength = math.min(tonumber(p.momentum or 1) or 1, capMomentum())
    driftgod.S.accelStrength = math.min(tonumber(p.accel or 1) or 1, capAccel())
    driftgod.S.momentumAssistEnabled = p.useMomentum == true and capMomentum() >= 2 and driftgod.S.momentumStrength >= 2
    driftgod.S.accelAssistEnabled = p.useAccel == true and capAccel() >= 2 and driftgod.S.accelStrength >= 2
    driftgod.S.arcadePresetRuntimeEnabled = true

    if driftgod.ClampAssistToUnlocks then driftgod.ClampAssistToUnlocks(false) end
    if driftgod.SaveSettings then driftgod.SaveSettings(false) end

    if showToast ~= false then
        if trialAvailable and not permanentUnlocked then
            toast("DriftGod Trial active — Corner Magnet behavior. Permanent unlock at " .. tostring(need) .. " Best Run.", 3600)
        else
            toast("Preset applied: " .. tostring(p.name), 2200)
        end
    end
    return true
end

local function dgPresetVelocityMultiplier(veh, mult)
    if not veh or veh == 0 or not ENTITY or not ENTITY.GET_ENTITY_VELOCITY or not ENTITY.SET_ENTITY_VELOCITY then return end
    mult = tonumber(mult or 1.0) or 1.0
    if mult <= 0.0 or math.abs(mult - 1.0) < 0.0001 then return end
    driftgod.Try(function()
        local v = ENTITY.GET_ENTITY_VELOCITY(veh)
        if v then ENTITY.SET_ENTITY_VELOCITY(veh, (v.x or 0.0) * mult, (v.y or 0.0) * mult, v.z or 0.0) end
    end)
end

local function dgPresetApplyForce(veh, amount, signedAngle)
    if not veh or veh == 0 or not ENTITY or not ENTITY.APPLY_FORCE_TO_ENTITY then return end
    amount = tonumber(amount or 0.0) or 0.0
    if amount <= 0.0 then return end
    driftgod.Try(function()
        local h = ENTITY.GET_ENTITY_HEADING and ENTITY.GET_ENTITY_HEADING(veh) or 0.0
        local rad = math.rad(h or 0.0)
        local fx = -math.sin(rad)
        local fy = math.cos(rad)
        local side = (signedAngle or 0.0) >= 0 and 1.0 or -1.0
        local rx = math.cos(rad) * side
        local ry = math.sin(rad) * side
        ENTITY.APPLY_FORCE_TO_ENTITY(veh, 1, fx * amount + rx * amount * 0.22, fy * amount + ry * amount * 0.22, 0.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
    end)
end

function driftgod.R198_GetTunedRuntimePreset(p)
    driftgod.S = driftgod.S or {}
    if type(p) ~= "table" then return p end

    if driftgod.S.driftAssistEnabled == false then return p end
    if driftgod.S.driftTuningEnabled ~= nil and driftgod.S.driftTuningEnabled ~= true then return p end

    local function clone(tbl)
        local out = {}
        for k, v in pairs(tbl or {}) do out[k] = v end
        return out
    end

    local function clamp(v, mn, mx)
        v = tonumber(v or mn) or mn
        if v < mn then return mn end
        if v > mx then return mx end
        return v
    end

    local function level(value, fallback)
        local n = tonumber(value or fallback or 3) or 3
        if n < 0 then n = 0 end
        if n > 5 then n = 5 end
        return n
    end

    local function enabled(name, default)
        local v = driftgod.S[name]
        if v == nil then return default == true end
        return v == true
    end

    local q = clone(p)

    local driftDelta     = level(driftgod.S.driftGripLevel,       p.drift or 3)     - level(p.drift, 3)
    local stabilityDelta = level(driftgod.S.driftStabilityLevel,  p.stability or 3) - level(p.stability, 3)
    local momentumDelta  = level(driftgod.S.momentumStrength,     p.momentum or 3)  - level(p.momentum, 3)
    local accelDelta     = level(driftgod.S.accelStrength,        p.accel or 3)     - level(p.accel, 3)

    local counterDelta = level(driftgod.S.autoCounterSteerLevel or driftgod.S.counterSteerLevel, 3) - 3
    local gravityDelta = enabled("experimentalGravityEnabled", false) and (level(driftgod.S.experimentalGravityStrength or driftgod.S.gravityLevel, 3) - 3) or 0
    local expAccelDelta = enabled("experimentalAccelEnabled", false) and (level(driftgod.S.experimentalAccelStrength or driftgod.S.experimentalAccelLevel, 3) - 3) or 0
    local tractionDelta = enabled("experimentalTractionEnabled", false) and (level(driftgod.S.experimentalTractionLevel or driftgod.S.tractionLevel, 3) - 3) or 0
    local gripDelta = enabled("experimentalGripEnabled", false) and (level(driftgod.S.experimentalGripLevel, 3) - 3) or 0

    if not enabled("stabilityAssistEnabled", true) then stabilityDelta = 0 end
    if not enabled("autoCounterSteerEnabled", true) then counterDelta = 0 end
    if not enabled("momentumAssistEnabled", p.useMomentum == true) then momentumDelta = 0 end
    if not enabled("accelAssistEnabled", p.useAccel == true) then accelDelta = 0 end

    q.angle = clamp((tonumber(p.angle or 50.0) or 50.0)
        + driftDelta * 4.0
        + gripDelta * 1.5
        - tractionDelta * 1.5,
        25.0, 92.0)

    q.grip_pad = clamp((tonumber(p.grip_pad or 8.0) or 8.0)
        + driftDelta * 1.4
        + gripDelta * 2.0
        + tractionDelta * 1.1
        + gravityDelta * 0.7
        - stabilityDelta * 0.35,
        0.0, 30.0)

    q.assist = clamp((tonumber(p.assist or 80.0) or 80.0)
        + stabilityDelta * 5.0
        + counterDelta * 7.0,
        35.0, 100.0)

    q.intensity = clamp((tonumber(p.intensity or 30.0) or 30.0)
        + momentumDelta * 4.0
        + expAccelDelta * 2.0
        - stabilityDelta * 1.0,
        10.0, 72.0)

    q.base_force = clamp((tonumber(p.base_force or 0.015) or 0.015)
        * (1.0 + accelDelta * 0.080 + momentumDelta * 0.045 + expAccelDelta * 0.060),
        0.004, 0.050)

    q.min_speed = clamp((tonumber(p.min_speed or 12.0) or 12.0)
        - gripDelta * 0.70
        - gravityDelta * 0.50
        + tractionDelta * 0.35,
        5.0, 38.0)

    q._r198ExtraVelocity = clamp((momentumDelta * 0.0018) + (expAccelDelta * 0.0018) + (accelDelta * 0.0012), -0.0040, 0.0080)
    q._r198Downforce = clamp(gravityDelta * 0.010, -0.010, 0.030)

    local now = driftgod.Now and driftgod.Now() or math.floor((os.clock() or 0) * 1000)
    if driftgod.S.driftTuningDebugEnabled == true and (now - (driftgod.S.r198LastTuneLogMs or 0)) > 1500 then
        driftgod.S.r198LastTuneLogMs = now
        if driftgod.Log then
            driftgod.Log("[DriftTuning][R198] base=" .. tostring(p.name or p.id)
                .. " angle=" .. string.format("%.1f", q.angle)
                .. " pad=" .. string.format("%.1f", q.grip_pad)
                .. " assist=" .. string.format("%.1f", q.assist)
                .. " intensity=" .. string.format("%.1f", q.intensity)
                .. " force=" .. string.format("%.4f", q.base_force)
                .. " minSpeed=" .. string.format("%.1f", q.min_speed))
        end
    end

    return q
end

function driftgod.ApplyArcadeDriftPresetRuntime(veh, kmh, driftAngle, held)
    driftgod.S = driftgod.S or {}
    if not held or veh == 0 or driftgod.S.arcadePresetRuntimeEnabled == false then return end
    local p = driftgod.GetArcadeDriftPresetById(driftgod.S.activeArcadeDriftPreset)
    if driftgod.R197_GetTunedRuntimePreset then p = driftgod.R197_GetTunedRuntimePreset(p) end
    if not p then return end
    if driftgod.S.stuntBusy then return end

    local now = driftgod.Now and driftgod.Now() or math.floor(os.clock() * 1000)
    if now - (driftgod.S.lastArcadePresetRuntimeTick or 0) < 90 then return end
    driftgod.S.lastArcadePresetRuntimeTick = now

    kmh = tonumber(kmh or 0.0) or 0.0
    local raw = tonumber(driftgod.S.lastDriftAngle or driftAngle or 0.0) or 0.0
    local signed = raw
    if signed > 180.0 then signed = -(360.0 - signed) end
    local absAngle = math.abs(tonumber(driftAngle or signed or 0.0) or 0.0)
    local maxAngle = tonumber(p.angle or 50.0) or 50.0
    local minSpeed = tonumber(p.min_speed or 12.0) or 12.0
    local pad = tonumber(p.grip_pad or 8.0) or 8.0
    local intensity = (tonumber(p.intensity or 30) or 30) / 100.0
    local assist = (tonumber(p.assist or 80) or 80) / 100.0
    local force = (tonumber(p.base_force or 0.015) or 0.015) * intensity
    local style = tostring(p.style or "sweep")
    local wantGrip = kmh >= minSpeed and absAngle <= (maxAngle + pad)
    local steerGain = 0.10 + (0.18 * assist)

    if style == "speedcontrol" then
        local angleScale = 1.0 - math.min(absAngle / 115.0, 0.62)
        local speedScale = math.max(0.35, math.min(kmh / 85.0, 1.05))
        force = force * angleScale * speedScale
        steerGain = 0.18 + (0.22 * assist) + math.min(kmh / 260.0, 0.06)
    elseif style == "apexrunner" then
        local cornerScale = absAngle >= 8.0 and math.max(0.35, math.min(absAngle / maxAngle, 1.0)) or 0.22
        force = force * cornerScale * math.max(0.35, math.min(kmh / 95.0, 0.95))
        if absAngle > maxAngle * 0.82 then force = force * 0.45 end
        steerGain = 0.20 + (0.24 * assist) + math.min(kmh / 300.0, 0.05)
    elseif style == "velocityarc" then
        force = force * math.max(0.25, math.min(kmh / 120.0, 0.85)) * (1.0 - math.min(absAngle / 170.0, 0.45))
        steerGain = 0.12 + (0.18 * assist) + math.min(kmh / 340.0, 0.07)
    elseif style == "speedthread" then
        force = force * 0.30 * (absAngle >= 10.0 and 1.0 or 0.45)
        steerGain = 0.24 + (0.28 * assist) + math.min(kmh / 310.0, 0.04)
    elseif style == "corner" then
        if absAngle < 18.0 then force = force * 0.40 end
        steerGain = 0.18 + (0.18 * assist)
    elseif style == "dgplus" then
        if driftgod.S.oldGripState and absAngle <= (maxAngle + pad + 4.0) then wantGrip = kmh >= (minSpeed - 3.0) end
        force = force * (absAngle >= 10.0 and 1.0 or 0.45)
        steerGain = 0.14 + (0.18 * assist)
    elseif style == "sweep" then
        force = force * math.min(kmh / 85.0, 1.0)
        steerGain = 0.09 + (0.13 * assist) + math.min(kmh / 250.0, 0.08)
    end

    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_REDUCE_GRIP then VEHICLE.SET_VEHICLE_REDUCE_GRIP(veh, wantGrip == true) end
    end)

    if kmh >= minSpeed and wantGrip and force > 0.0 then
        dgPresetApplyForce(veh, force, signed)
        local extraVelocity = tonumber(p._r198ExtraVelocity or 0.0) or 0.0
        dgPresetVelocityMultiplier(veh, 1.0 + math.min(force * 0.085, 0.0045) + extraVelocity)

        local downforce = tonumber(p._r198Downforce or 0.0) or 0.0
        if math.abs(downforce) > 0.0001 and ENTITY and ENTITY.APPLY_FORCE_TO_ENTITY then
            driftgod.Try(function()
                ENTITY.APPLY_FORCE_TO_ENTITY(veh, 1, 0.0, 0.0, -downforce, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
            end)
        end
    end

    if kmh >= minSpeed and absAngle >= (maxAngle * 0.72) then
        local over = math.min(absAngle - (maxAngle * 0.72), maxAngle)
        local biasDeg = (signed >= 0 and 1.0 or -1.0) * math.min(over * steerGain, 16.0)
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_STEER_BIAS then VEHICLE.SET_VEHICLE_STEER_BIAS(veh, math.rad(biasDeg)) end
        end)
    end
end

for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
    local desc = tostring(p.family or "") .. " | Unlock: " .. tostring(p.unlock or 0) .. " Best Run. " .. tostring(p.desc or "")
    if tonumber(p.trial_until or 0) and tonumber(p.trial_until or 0) > 0 then
        desc = desc .. " Trial preview until " .. tostring(p.trial_until) .. " Best Run."
    end
    driftgod.AddButton("ArcadePreset_" .. p.id, "Preset: " .. p.name, desc, function()
