    driftgod.AddToggle("BannedPreset_" .. id, label, "Blocks DriftGod score inside this preset polygon area.", function(f)
        if driftgod.SetPresetBannedAreaEnabled then
            driftgod.SetPresetBannedAreaEnabled(id, f:IsToggled())
