function driftgod.SafeSyncPointsHudDefaults()
    driftgod.S = driftgod.S or {}

    if driftgod.S.pointsHudEnabled == nil then driftgod.S.pointsHudEnabled = true end
    if driftgod.S.scoreHudEnabled == nil then driftgod.S.scoreHudEnabled = true end
    if driftgod.S.showPointsHud == nil then driftgod.S.showPointsHud = true end

    if driftgod.S.pointsHudEnabled == true or driftgod.S.scoreHudEnabled == true or driftgod.S.showPointsHud == true then
        driftgod.S.pointsHudEnabled = true
        driftgod.S.scoreHudEnabled = true
        driftgod.S.showPointsHud = true
    end
end

driftgod.SafeSyncPointsHudDefaults()

driftgod.Unlocks = driftgod.Unlocks or {}
driftgod.Unlocks.DriftGodPresetBestScore = 100000

function driftgod.GetBestDriftScore()
    driftgod.S = driftgod.S or {}

    local candidates = {
        driftgod.S.bestScore,
        driftgod.S.bestDriftScore,
        driftgod.S.highScore,
        driftgod.S.highestScore,
        driftgod.S.topScore,
        driftgod.S.topDriftScore,
        driftgod.S.personalBest,
        driftgod.S.pb,
        driftgod.S.bestRun,
        driftgod.S.bestPoints,
        driftgod.BestScore,
        driftgod.HighScore,
        driftgod.TopScore,
    }

    local best = 0

    for _, value in ipairs(candidates) do
        local n = tonumber(value)
        if n and n > best then
            best = n
        end
    end

    return math.floor(best)
end

function driftgod.IsDriftGodPresetUnlocked()
    if driftgod.IsArcadeDriftPresetPermanentlyUnlocked then
        return driftgod.IsArcadeDriftPresetPermanentlyUnlocked("corner_magnet") == true
    end
    return driftgod.GetBestDriftScore() >= (driftgod.Unlocks.DriftGodPresetBestScore or 100000)
end

function driftgod.IsDriftGodPresetTrialAvailable()
    if driftgod.IsArcadeDriftPresetTrialAvailable then
        return driftgod.IsArcadeDriftPresetTrialAvailable("corner_magnet") == true
    end
    return false
end

function driftgod.ApplyDriftGodPreset()
    if driftgod.ApplyArcadeDriftPreset then
        return driftgod.ApplyArcadeDriftPreset("corner_magnet", true)
    end
    if driftgod.Toast then driftgod.Toast("DriftGod preset unavailable: Arcade preset system not loaded.", 2600) end
    return false
end

function driftgod.GetDriftGodPresetLabel()
    local p = driftgod.GetArcadeDriftPresetById and driftgod.GetArcadeDriftPresetById("corner_magnet") or nil
    if p and driftgod.GetArcadeDriftPresetLabel then
        return driftgod.GetArcadeDriftPresetLabel(p) .. "  (Corner Magnet tune)"
    end

    local need = driftgod.Unlocks.DriftGodPresetBestScore or 100000
    local best = driftgod.GetBestDriftScore()
    if driftgod.IsDriftGodPresetUnlocked() then return "DriftGod — Unlocked" end
    return "Locked: DriftGod | Unlock at " .. tostring(need) .. " | Current " .. tostring(best)
end

function driftgod.ShowDriftGodPresetRequirement()
    local need = driftgod.Unlocks.DriftGodPresetBestScore or 100000
    local score = driftgod.GetArcadeDriftPresetScore and driftgod.GetArcadeDriftPresetScore() or driftgod.GetBestDriftScore()
    local trial = driftgod.IsDriftGodPresetTrialAvailable and driftgod.IsDriftGodPresetTrialAvailable()
    local left = math.max(0, need - score)

    if driftgod.Toast then
        if trial then
            driftgod.Toast("DriftGod Trial available now. Permanent unlock at " .. tostring(need) .. " Best Run.", 3200)
        else
            driftgod.Toast("DriftGod preset locked — unlock at " .. tostring(need) .. " Best Run. Current: " .. tostring(score) .. ". Need " .. tostring(left) .. " more.", 4200)
        end
    end

    if driftgod.Log then
        driftgod.Log("[Preset] DriftGod unlock info | arcadeScore=" .. tostring(score) .. "/" .. tostring(need) .. " trial=" .. tostring(trial))
    end
end

local function dgStuntMenuClamp(v, lo, hi)
    v = tonumber(v or lo) or lo
    if v < lo then return lo end
    if v > hi then return hi end
    return v
end

local function dgGetStuntMenuXY()
    if driftgod.GetStuntQuickMenuPosition then
        return driftgod.GetStuntQuickMenuPosition(0.085, 0.560)
    end
    driftgod.S = driftgod.S or {}
    local x = dgStuntMenuClamp(driftgod.S.stuntQuickMenuX or driftgod.S.stuntHudX or 0.085, 0.000, 1.000)
    local y = dgStuntMenuClamp(driftgod.S.stuntQuickMenuY or driftgod.S.stuntHudY or 0.560, 0.000, 1.000)
    driftgod.S.stuntQuickMenuX, driftgod.S.stuntHudX = x, x
    driftgod.S.stuntQuickMenuY, driftgod.S.stuntHudY = y, y
    return x, y
end

local function dgSetStuntMenuXY(x, y, toastText)
    driftgod.S = driftgod.S or {}
    x = dgStuntMenuClamp(x, 0.000, 1.000)
    y = dgStuntMenuClamp(y, 0.000, 1.000)

    if driftgod.SetStuntQuickMenuPosition then
        driftgod.SetStuntQuickMenuPosition(x, y, false)
    else
        driftgod.S.stuntQuickMenuX, driftgod.S.stuntHudX = x, x
        driftgod.S.stuntQuickMenuY, driftgod.S.stuntHudY = y, y
        driftgod.S.stuntHudMoveEnabled = true
    end

    if driftgod.SaveSettings then driftgod.SaveSettings(false) end
    if driftgod.Toast then driftgod.Toast((toastText or "Stunt Menu") .. ": " .. string.format("%.3f / %.3f", x, y), 1000) end
    return x, y
end

local function dgMoveStuntMenu(dx, dy, label)
    local x, y = dgGetStuntMenuXY()
    return dgSetStuntMenuXY(x + (dx or 0), y + (dy or 0), label or "Stunt Menu")
end

