local function renderFeatureSafe(handle, label)
    if handle ~= nil then
        local ok, err = driftgod.Try(function()
            ClickGUI.RenderFeature(handle)
        end)
        if not ok and DG and driftgod.Log then
            driftgod.Log("[Menu] RenderFeature failed for " .. tostring(label or "unknown") .. " | " .. tostring(err))
        end
    elseif DG and driftgod.Log then
        driftgod.Log("[Menu] Missing feature handle: " .. tostring(label or "unknown"))
    end
end

