local dgColorText, dgFmtNum, dgSafeTableFlags, dgTableCell

local function dgArcadePresetStatus(p, score)
    driftgod.S = driftgod.S or {}
    if not p then return "LOCKED", "locked", 0 end
    score = tonumber(score or 0) or 0
    local need = tonumber(p.unlock or 0) or 0
    local trialUntil = tonumber(p.trial_until or 0) or 0
    local active = driftgod.S.activeArcadeDriftPreset == p.id

    if driftgod.IsArcadePresetTestingMode and driftgod.IsArcadePresetTestingMode() then
        if active then return "TEST ACTIVE", "active", 0 end
        return "TEST", "unlocked", 0
    end

    if active then
        if driftgod.IsArcadeDriftPresetPermanentlyUnlocked and driftgod.IsArcadeDriftPresetPermanentlyUnlocked(p.id) then
            return "ACTIVE", "active", 0
        end
        if driftgod.IsArcadeDriftPresetTrialAvailable and driftgod.IsArcadeDriftPresetTrialAvailable(p.id) then
            return "TRIAL ACTIVE", "active", math.max(0, need - score)
        end
        return "ACTIVE", "active", 0
    end

    if driftgod.IsArcadeDriftPresetPermanentlyUnlocked and driftgod.IsArcadeDriftPresetPermanentlyUnlocked(p.id) then
        return "UNLOCKED", "unlocked", 0
    end

    if trialUntil > 0 and driftgod.IsArcadeDriftPresetTrialAvailable and driftgod.IsArcadeDriftPresetTrialAvailable(p.id) then
        return "TRIAL", "next", math.max(0, need - score)
    end

    return "LOCKED", "locked", math.max(0, need - score)
end

local function dgPresetRoadLabel(familyName)
    familyName = tostring(familyName or "")
    if familyName == "Wide / Open Roads" then return "Wide Road" end
    if familyName == "Technical / Windy Roads" then return "Technical" end
    if familyName == "Open" then return "Open" end
    if familyName == "Default / Starter" then return "Starter" end
    return familyName
end

local function dgPresetTipText(p, maxChars)
    if not p or not p.desc then return "" end
    maxChars = tonumber(maxChars or 86) or 86
    local txt = tostring(p.name or "Preset") .. ": " .. tostring(p.desc or "")
    txt = txt:gsub("%s+", " ")
    if #txt > maxChars then
        txt = txt:sub(1, math.max(1, maxChars - 3)) .. "..."
    end
    return txt
end

local function dgRenderPresetSummary(score)
    driftgod.S = driftgod.S or {}
    dgColorText("Drift Presets", "header")
    if ImGui.BeginTable("DriftPresetSummaryGrid", 2, dgSafeTableFlags()) then
        local function row(k, v, color)
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0); ImGui.Text(tostring(k))
            ImGui.TableSetColumnIndex(1); dgTableCell(tostring(v), color)
        end
        row("Best Run", dgFmtNum(score or 0), "gold")
        row("Active Preset", tostring(driftgod.S.activeStartupPreset or driftgod.S.activeArcadeDriftPreset or "None"), "active")
        row("Progression Loop", "Drive -> Score -> Unlock Presets -> Master Road Types", "cyan")
        row("DriftGod Trial", "Available before 3,000 | Permanent at 100,000", "next")
        if driftgod.IsArcadePresetTestingMode and driftgod.IsArcadePresetTestingMode() then row("Testing Mode", "All presets available at full strength", "cyan") end
        ImGui.EndTable()
    else
        ImGui.Text("Best Run: " .. tostring(score or 0))
        ImGui.Text("Active Preset: " .. tostring(driftgod.S.activeStartupPreset or driftgod.S.activeArcadeDriftPreset or "None"))
    end
    ImGui.Separator()
    dgColorText("Green = Test/Unlocked  |  Yellow = Trial / Next  |  Purple = Active  |  Gray = Locked", "dim")
    ImGui.Separator()
end

local function renderArcadeDriftPresetButtons(familyName)
    driftgod.S = driftgod.S or {}
    local score = driftgod.GetArcadeDriftPresetScore and driftgod.GetArcadeDriftPresetScore() or 0

    dgColorText(dgPresetRoadLabel(familyName or "Presets"), "header")

    local rows = {}
    for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
        if p.family == familyName then table.insert(rows, p) end
    end

    if #rows <= 0 then
        dgColorText("No presets in this family yet.", "dim")
        return
    end

    if ImGui.BeginTable("DriftPresetGrid_" .. tostring(familyName):gsub("[^%w]", "_"), 6, dgSafeTableFlags()) then

        if ImGui.TableSetupColumn then
            driftgod.Try(ImGui.TableSetupColumn, "Status", 0, 78)
            driftgod.Try(ImGui.TableSetupColumn, "Preset", 0, 185)
            driftgod.Try(ImGui.TableSetupColumn, "Score", 0, 54)
            driftgod.Try(ImGui.TableSetupColumn, "Left", 0, 54)
            driftgod.Try(ImGui.TableSetupColumn, "Road", 0, 58)
            driftgod.Try(ImGui.TableSetupColumn, "Action", 0, 92)
        end
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0); dgColorText("Status", "header")
        ImGui.TableSetColumnIndex(1); dgColorText("Preset", "header")
        ImGui.TableSetColumnIndex(2); dgColorText("Score", "header")
        ImGui.TableSetColumnIndex(3); dgColorText("Left", "header")
        ImGui.TableSetColumnIndex(4); dgColorText("Road", "header")
        ImGui.TableSetColumnIndex(5); dgColorText("Action", "header")

        for _, p in ipairs(rows) do
            local status, color, remaining = dgArcadePresetStatus(p, score)
            local need = tonumber(p.unlock or 0) or 0
            local scoreText = need <= 0 and "Starter" or dgFmtNum(need)
            local leftText = (remaining and remaining > 0) and dgFmtNum(remaining) or "--"
            local presetName = tostring(p.name or "Preset")
            if p.source_name and tostring(p.source_name) ~= "" then presetName = presetName .. "  (" .. tostring(p.source_name) .. ")" end

            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0); dgTableCell(status, color)
            ImGui.TableSetColumnIndex(1); dgTableCell(presetName, color == "locked" and "locked" or nil)
            ImGui.TableSetColumnIndex(2); dgTableCell(scoreText)
            ImGui.TableSetColumnIndex(3); dgTableCell(leftText, status == "TRIAL" and "next" or nil)
            ImGui.TableSetColumnIndex(4); dgTableCell(dgPresetRoadLabel(p.family or familyName), color == "active" and "active" or nil)
            ImGui.TableSetColumnIndex(5); renderFeatureSafe(driftgod.H["ArcadePreset_" .. p.id], p.name)
        end
        ImGui.EndTable()
    else
        for _, p in ipairs(rows) do
            local status, color, remaining = dgArcadePresetStatus(p, score)
            local need = tonumber(p.unlock or 0) or 0
            dgColorText(status .. " | " .. tostring(p.name) .. " | " .. (need <= 0 and "Starter" or dgFmtNum(need)) .. " | Left " .. dgFmtNum(remaining or 0) .. " | " .. dgPresetRoadLabel(p.family or familyName), color)
            renderFeatureSafe(driftgod.H["ArcadePreset_" .. p.id], p.name)
        end
    end

    ImGui.Separator()
    for _, p in ipairs(rows) do
        if p.desc and tostring(p.desc) ~= "" then

            dgColorText(dgPresetTipText(p, 69), "dim")
        end
    end
end

