local function DG_GetFeatureNumberSafe(f, fallback)
    fallback = tonumber(fallback or 0) or 0

    local methods = {
        "GetInt",
        "GetValue",
        "GetFloat",
        "Get",
        "Value",
        "GetNumber",
    }

    for _, method in ipairs(methods) do
        local candidate = f and f[method]
        if type(candidate) == "function" then
            local ok, value = driftgod.Try(function() return candidate(f) end)
            local n = tonumber(value)
            if ok and n ~= nil then return n end
        elseif candidate ~= nil then
            local n = tonumber(candidate)
            if n ~= nil then return n end
        end
    end

    if f and f.value ~= nil then
        local n = tonumber(f.value)
        if n ~= nil then return n end
    end

    if f and f.Value ~= nil then
        local n = tonumber(f.Value)
        if n ~= nil then return n end
    end

    return fallback
end

