function driftgod.RenderStuntUnlockProgress()
    if not ImGui or not driftgod.StuntUnlocks then return end
    local score = driftgod.GetLifetimeScore and driftgod.GetLifetimeScore() or 0
    ImGui.Text("Stunt Unlocks")
    ImGui.Text("Strict Unlock Score: " .. tostring(score))
    ImGui.Text("Unlock Score Source: " .. tostring(driftgod.S and driftgod.S.stuntUnlockLastScoreSource or "none"))
    local nextName, nextReq = nil, nil
    for _, n in ipairs(driftgod.StuntUnlockOrder or {}) do
        local req = driftgod.GetStuntUnlockRequirement and driftgod.GetStuntUnlockRequirement(n) or 0
        if req > score then nextName, nextReq = n, req; break end
    end
    if nextName then ImGui.Text("Next Locked Stunt: " .. tostring(nextName) .. " @ " .. tostring(nextReq)); ImGui.Text("Score Needed: " .. tostring(math.max(0, nextReq - score))) end
    ImGui.Text("Stunt Score Override: " .. tostring(driftgod.S and driftgod.S.stuntUnlockScoreOverride or 0))
    ImGui.Text("Progress Unlocks: " .. tostring((driftgod.AreProgressUnlocksEnabled and driftgod.AreProgressUnlocksEnabled()) and "ON" or "OFF"))
    local order = driftgod.StuntUnlockOrder or {"Donut", "720 Spin", "Back Flip", "Front Flip", "Forward Flip", "Kickflip", "Heelflip", "Fingerflip", "Backside Flip", "Frontside Flip", "Backside Heelflip", "Frontside Heelflip", "Impossible"}
    for _, name in ipairs(order) do
        local req = driftgod.GetStuntUnlockRequirement and driftgod.GetStuntUnlockRequirement(name) or 0
        local unlocked = driftgod.IsStuntUnlocked and driftgod.IsStuntUnlocked(name)
        local tier = driftgod.GetStuntUpgradeTier and driftgod.GetStuntUpgradeTier(name) or 1
        local speed = driftgod.GetStuntUpgradeSpeed and driftgod.GetStuntUpgradeSpeed(name) or 1.0
        local uses = driftgod.GetStuntRunUseCount and driftgod.GetStuntRunUseCount(name) or 0
        local nextTierText = driftgod.GetNextStuntTierRequirementText and driftgod.GetNextStuntTierRequirementText(name) or ""
        ImGui.Text(tostring(name) .. " : " .. (unlocked and ("UNLOCKED | Tier: " .. tostring(tier) .. " | Duration: " .. tostring(math.floor(speed * 100)) .. "% | Uses This Run: " .. tostring(uses) .. " | " .. tostring(nextTierText)) or ("LOCKED - " .. tostring(req))))
    end
end

local function dgCountDoneTable(t)
    local count = 0
    if type(t) == "table" then
        for _, done in pairs(t) do
            if done == true then count = count + 1 end
        end
    end
    return count
end

