end

local function dgGetCurrentVehicleMasteryRecord()
    if driftgod.InstallVehicleMastery then driftgod.InstallVehicleMastery("arcade vehicle") end
    local key = driftgod.GetVehicleMasteryKey and driftgod.GetVehicleMasteryKey() or "current_vehicle"
    local record = driftgod.GetVehicleMasteryRecord and driftgod.GetVehicleMasteryRecord(key) or {}
    return key, record
end

local function dgGetActiveDailyChallengeCount()
    local active = (driftgod.GetActiveDailyChallenges and driftgod.GetActiveDailyChallenges()) or {}
    local remaining = 0
    for _, challenge in ipairs(active) do
        local done = driftgod.S.sessionChallengesCompleted and driftgod.S.sessionChallengesCompleted[challenge.id] == true
        if done ~= true then remaining = remaining + 1 end
    end
    return #active, remaining
end

local function dgGetBeatenRivalCount()
    local beaten = 0
    if type(driftgod.S.beatenRivals) == "table" then
        for _, done in pairs(driftgod.S.beatenRivals) do
            if done == true then beaten = beaten + 1 end
        end
    end
    return beaten
end

