local function renderArcadeOverviewTab()
    if driftgod.InstallSessionChallenges then driftgod.InstallSessionChallenges("arcade overview") end
    if driftgod.RefreshDailyChallenges then driftgod.RefreshDailyChallenges(false) end
    if driftgod.InstallProgressMilestones then driftgod.InstallProgressMilestones("arcade overview") end
    if driftgod.InstallVehicleMastery then driftgod.InstallVehicleMastery("arcade overview") end

    local key, record = dgGetCurrentVehicleMasteryRecord()
    local active, remaining = dgGetActiveDailyChallengeCount()
    local completedMilestones = dgCountDoneTable(driftgod.S.progressMilestonesCompleted)
    local beatenRivals = dgGetBeatenRivalCount()

    ImGui.Text("Arcade")
    ImGui.Separator()
    ImGui.Text("Daily Challenges Left: " .. tostring(remaining) .. " / " .. tostring(active))
    ImGui.Text("Overall Score: " .. tostring(driftgod.S.overallScore or 0))
    ImGui.Text("Banked Runs: " .. tostring(driftgod.S.overallScoreBankedRuns or 0))
    ImGui.Text("Rivals Beaten: " .. tostring(beatenRivals))
    ImGui.Text("Current Vehicle: " .. tostring(record.name or key))
    ImGui.Text("Vehicle Mastery: Level " .. tostring(record.masteryLevel or 1) .. "/5 - " .. tostring(record.title or (driftgod.GetVehicleMasteryTitle and driftgod.GetVehicleMasteryTitle(record) or "Discovered")))
    ImGui.Text("Milestones Completed: " .. tostring(completedMilestones) .. " / " .. tostring(#(driftgod.ProgressMilestoneList or {})))
    ImGui.Separator()
    ImGui.Text("Use the Arcade sub-tabs for details.")
end

local function renderArcadeChallengesTab()
    if driftgod.InstallSessionChallenges then driftgod.InstallSessionChallenges("arcade challenges") end
    if driftgod.RefreshDailyChallenges then driftgod.RefreshDailyChallenges(false) end

    ImGui.Text("Today's 3 Challenges")
    ImGui.Separator()
    ImGui.Text("Challenge Points: " .. tostring(driftgod.S.sessionChallengePoints or 0))
    ImGui.Text("Completed Challenges: " .. tostring(dgCountDoneTable(driftgod.S.sessionChallengesCompleted)) .. " / " .. tostring(#(driftgod.SessionChallengeList or {})))

    local active = (driftgod.GetActiveDailyChallenges and driftgod.GetActiveDailyChallenges()) or {}
    if #active <= 0 then
        ImGui.Text("No active daily challenges found.")
    end

    for _, challenge in ipairs(active) do
        local done = driftgod.S.sessionChallengesCompleted and driftgod.S.sessionChallengesCompleted[challenge.id] == true
        local mark = done and "[DONE] " or "[ ] "
        ImGui.Text(mark .. tostring(challenge.title or challenge.id) .. " +" .. tostring(challenge.points or 1) .. " CP")
        if challenge.description then
            ImGui.Text("  " .. tostring(challenge.description))
        end
    end
end

