local DG_PROGRESSION_COLORS = {
    unlocked = {0.30, 0.95, 0.40, 1.00},
    locked   = {0.62, 0.62, 0.62, 1.00},
    next     = {1.00, 0.82, 0.18, 1.00},
    active   = {0.72, 0.42, 1.00, 1.00},
    purple   = {0.72, 0.42, 1.00, 1.00},
    gold     = {1.00, 0.78, 0.18, 1.00},
    red      = {1.00, 0.24, 0.24, 1.00},
    warning  = {1.00, 0.42, 0.28, 1.00},
    header   = {0.42, 0.82, 1.00, 1.00},
    white    = {0.92, 0.92, 0.92, 1.00},
    dim      = {0.55, 0.55, 0.55, 1.00},
}

function dgColorText(text, colorKey)
    local c = DG_PROGRESSION_COLORS[colorKey or "white"] or DG_PROGRESSION_COLORS.white
    if ImGui and ImGui.TextColored then
        ImGui.TextColored(c[1], c[2], c[3], c[4], tostring(text or ""))
        return
    end
    ImGui.Text(tostring(text or ""))
end

function dgFmtNum(n)
    n = tonumber(n or 0) or 0
    local s = tostring(math.floor(n))
    while true do
        local ns, k = s:gsub("^(-?%d+)(%d%d%d)", "%1,%2")
        s = ns
        if k == 0 then break end
    end
    return s
end

local function dgProgressScore()
    if driftgod.ScoreForUnlock then return tonumber(driftgod.ScoreForUnlock()) or 0 end
    return math.max(tonumber(driftgod.S.bestScore or 0) or 0, tonumber(driftgod.S.highScore or 0) or 0, tonumber(driftgod.S.currentScore or 0) or 0)
end

local function dgProgressStatus(score, req, isNext)
    req = tonumber(req or 0) or 0
    if req <= 0 or score >= req then return "UNLOCKED", "unlocked", 0 end
    if isNext == true then return "NEXT", "next", math.max(0, req - score) end
    return "LOCKED", "locked", math.max(0, req - score)
end

local function dgFindNextRequirement(score, rows)
    local nextIndex = nil
    local nextReq = nil
    for i, row in ipairs(rows or {}) do
        local req = tonumber(row.req or 0) or 0
        if req > score and (nextReq == nil or req < nextReq) then
            nextIndex = i
            nextReq = req
        end
    end
    return nextIndex, nextReq
end

function dgSafeTableFlags()
    if ImGuiTableFlags and ImGuiTableFlags.SizingStretchSame then
        return ImGuiTableFlags.SizingStretchSame
    end
    return 0
end

function dgTableCell(text, colorKey)
    if colorKey then dgColorText(text, colorKey) else ImGui.Text(tostring(text or "")) end
end

local function dgRenderUnlockTable(tableId, rows, activeLevel, compact)
    local score = dgProgressScore()
    local nextIndex = dgFindNextRequirement(score, rows)
    if ImGui.BeginTable(tableId, compact and 4 or 5, dgSafeTableFlags()) then
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0); dgColorText("Status", "header")
        ImGui.TableSetColumnIndex(1); dgColorText("Unlock", "header")
        ImGui.TableSetColumnIndex(2); dgColorText("Score", "header")
        ImGui.TableSetColumnIndex(3); dgColorText(compact and "Left" or "Remaining", "header")
        if not compact then ImGui.TableSetColumnIndex(4); dgColorText("Note", "header") end

        for i, row in ipairs(rows or {}) do
            local status, color, remaining = dgProgressStatus(score, row.req, i == nextIndex)
            local isActive = tonumber(activeLevel or 0) == tonumber(row.level or -999)
            if isActive and status == "UNLOCKED" then status, color = "ACTIVE", "active" end
            local reqText = (tonumber(row.req or 0) or 0) <= 0 and "starter" or dgFmtNum(row.req)
            local remText = remaining > 0 and dgFmtNum(remaining) or "--"

            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0); dgTableCell(status, color)
            ImGui.TableSetColumnIndex(1); dgTableCell(row.short or row.label or "unlock", color == "locked" and "locked" or nil)
            ImGui.TableSetColumnIndex(2); dgTableCell(reqText)
            ImGui.TableSetColumnIndex(3); dgTableCell(remText)
            if not compact then ImGui.TableSetColumnIndex(4); dgTableCell(row.note or "") end
        end
        ImGui.EndTable()
    else
        for i, row in ipairs(rows or {}) do
            local status, color, remaining = dgProgressStatus(score, row.req, i == nextIndex)
            dgColorText(status .. " | " .. tostring(row.short or row.label) .. " | " .. dgFmtNum(row.req) .. " | " .. dgFmtNum(remaining), color)
        end
    end
end

