local function dgAllProgressionRows()
    local allRows = {}
    local order = {"drift", "stability", "counter", "momentum", "accel", "gravity", "expaccel", "traction", "grip"}
    for _, key in ipairs(order) do
        for _, row in ipairs(DG_ABILITY_ROWS[key] or {}) do table.insert(allRows, row) end
    end
    for _, row in ipairs(DG_PTFX_ROWS) do table.insert(allRows, row) end
    for _, row in ipairs(DG_UTILITY_ROWS) do table.insert(allRows, row) end
    return allRows
end

local function dgCurrentUnlocks()
    local drift = driftgod.GetUnlockedDriftLevel and driftgod.GetUnlockedDriftLevel() or 1
    local stability = driftgod.GetUnlockedStabilityLevel and driftgod.GetUnlockedStabilityLevel() or 1
    local counter = driftgod.GetUnlockedAutoCounterSteerLevel and driftgod.GetUnlockedAutoCounterSteerLevel() or 1
    local momentum = driftgod.GetUnlockedMomentumLevel and driftgod.GetUnlockedMomentumLevel() or 1
    local accel = driftgod.GetUnlockedAccelLevel and driftgod.GetUnlockedAccelLevel() or 1
    local gravity = driftgod.GetUnlockedExperimentalGravityLevel and driftgod.GetUnlockedExperimentalGravityLevel() or 1
    local expaccel = driftgod.GetUnlockedExperimentalAccelLevel and driftgod.GetUnlockedExperimentalAccelLevel() or 1
    local traction = driftgod.GetUnlockedExperimentalTractionLevel and driftgod.GetUnlockedExperimentalTractionLevel() or 0
    local grip = driftgod.GetUnlockedExperimentalGripLevel and driftgod.GetUnlockedExperimentalGripLevel() or 0
    return drift, stability, counter, momentum, accel, gravity, expaccel, traction, grip
end

local function dgRenderProgressionSummary()
    local score = dgProgressScore()
    local drift, stability, counter, momentum, accel, gravity, expaccel, traction, grip = dgCurrentUnlocks()
    local allRows = dgAllProgressionRows()
    local nextIdx = dgFindNextRequirement(score, allRows)
    local nextRow = nextIdx and allRows[nextIdx]

    dgColorText("Progression Summary", "header")
    if ImGui.BeginTable("ProgressionSummaryGrid", 2, dgSafeTableFlags()) then
        local function row(k, v, color)
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0); ImGui.Text(k)
            ImGui.TableSetColumnIndex(1); dgTableCell(v, color)
        end
        row("Unlock Score", dgFmtNum(score), "white")
        row("Title", tostring(driftgod.S.progressMilestoneTitle or "Drift Initiate"), "active")
        row("Drift", tostring(drift) .. " / 5", "unlocked")
        row("Stability", tostring(stability) .. " / 5", "unlocked")
        row("Counter-Steer", tostring(counter) .. " / 5", "unlocked")
        row("Momentum", tostring(momentum) .. " / 5", "unlocked")
        row("Acceleration", tostring(accel) .. " / 5", "unlocked")
        row("Gravity", tostring(gravity) .. " / 5", "unlocked")
        row("Exp Accel", tostring(expaccel) .. " / 5", "unlocked")
        row("Traction", tostring(traction) .. " / 5", traction > 0 and "unlocked" or "locked")
        row("Grip", tostring(grip) .. " / 5", grip > 0 and "unlocked" or "locked")
        if nextRow then
            row("Next Goal", tostring(nextRow.short or nextRow.label), "next")
            row("Remaining", dgFmtNum((tonumber(nextRow.req) or 0) - score), "next")
        else
            row("Next Goal", "All Listed Goals Unlocked", "unlocked")
        end
        ImGui.EndTable()
    end
    ImGui.Separator()
    dgColorText("Green = Unlocked  |  Yellow = Next  |  Purple = Active  |  Gray = Locked", "dim")
end

