local function dgRenderProgressionStunts()
    dgColorText("Stunts", "header")

    local score = driftgod.GetStuntUnlockScore and driftgod.GetStuntUnlockScore() or (driftgod.GetLifetimeScore and driftgod.GetLifetimeScore() or dgProgressScore())
    local order = driftgod.StuntUnlockOrder or {"Donut", "720 Spin", "Back Flip", "Front Flip", "Forward Flip", "Kickflip", "Heelflip", "Fingerflip", "Backside Flip", "Frontside Flip", "Backside Heelflip", "Frontside Heelflip", "Impossible"}

    local rows = {}
    local nextIndex, nextReq = nil, nil
    for i, name in ipairs(order) do
        local req = driftgod.GetStuntUnlockRequirement and driftgod.GetStuntUnlockRequirement(name) or 0
        if req > score and (nextReq == nil or req < nextReq) then
            nextIndex, nextReq = i, req
        end
    end

    if ImGui.BeginTable("ProgressionStuntsGrid", 6, dgSafeTableFlags()) then
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0); dgColorText("Status", "header")
        ImGui.TableSetColumnIndex(1); dgColorText("Stunt", "header")
        ImGui.TableSetColumnIndex(2); dgColorText("Score", "header")
        ImGui.TableSetColumnIndex(3); dgColorText("Tier", "header")
        ImGui.TableSetColumnIndex(4); dgColorText("Uses", "header")
        ImGui.TableSetColumnIndex(5); dgColorText("Next", "header")

        for i, name in ipairs(order) do
            local req = driftgod.GetStuntUnlockRequirement and driftgod.GetStuntUnlockRequirement(name) or 0
            local unlocked = driftgod.IsStuntUnlocked and driftgod.IsStuntUnlocked(name)
            local status, color, remaining = dgProgressStatus(score, req, i == nextIndex)
            if unlocked == true then status, color, remaining = "UNLOCKED", "unlocked", 0 end

            local tier = driftgod.GetStuntUpgradeTier and driftgod.GetStuntUpgradeTier(name) or 1
            local uses = driftgod.GetStuntRunUseCount and driftgod.GetStuntRunUseCount(name) or 0
            local nextTierText = driftgod.GetNextStuntTierRequirementText and driftgod.GetNextStuntTierRequirementText(name) or ""
            if nextTierText == nil or tostring(nextTierText) == "" then nextTierText = remaining > 0 and ("Left " .. dgFmtNum(remaining)) or "--" end

            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0); dgTableCell(status, color)
            ImGui.TableSetColumnIndex(1); dgTableCell(tostring(name), color == "locked" and "locked" or nil)
            ImGui.TableSetColumnIndex(2); dgTableCell((tonumber(req or 0) or 0) <= 0 and "Starter" or dgFmtNum(req))
            ImGui.TableSetColumnIndex(3); dgTableCell(tostring(tier) .. " / 3", unlocked and "active" or nil)
            ImGui.TableSetColumnIndex(4); dgTableCell(tostring(uses))
            ImGui.TableSetColumnIndex(5); dgTableCell(tostring(nextTierText), status == "NEXT" and "next" or nil)
        end
        ImGui.EndTable()
        ImGui.Separator()
        dgColorText("Locked stunts are hidden from the Stunts tab until earned.", "dim")
        dgColorText("Hit the listed score to unlock each stunt. Tier speed improves through landed uses.", "warning")
    else
        for i, name in ipairs(order) do
            local req = driftgod.GetStuntUnlockRequirement and driftgod.GetStuntUnlockRequirement(name) or 0
            local status, color, remaining = dgProgressStatus(score, req, i == nextIndex)
            dgColorText(status .. " | " .. tostring(name) .. " | " .. ((req <= 0) and "Starter" or dgFmtNum(req)) .. " | Left " .. dgFmtNum(remaining), color)
        end
    end
end

