local dgRenderFeatureSafe

local function dgRenderProgressionVehicleUnlocks()
    if driftgod.InstallVehicleSectors then driftgod.InstallVehicleSectors("progression vehicle unlocks") end
    local score = driftgod.GetVehicleSectorProgressScore and driftgod.GetVehicleSectorProgressScore() or dgProgressScore()
    dgColorText("Vehicle Unlocks", "header")
    if driftgod.H and driftgod.H.VehicleSectorUnlocksToggle then dgRenderFeatureSafe(driftgod.H.VehicleSectorUnlocksToggle) end
    if driftgod.H and driftgod.H.SpeedScoreScalingToggle then dgRenderFeatureSafe(driftgod.H.SpeedScoreScalingToggle) end
    if driftgod.H and driftgod.H.MakeWayAutoToggle then dgRenderFeatureSafe(driftgod.H.MakeWayAutoToggle) end
    ImGui.Text("Unlock Score: " .. dgFmtNum(score))
    ImGui.Text("Beginner Rule: Zentorno is always allowed. Sectors unlock extra vehicle categories.")
    ImGui.Text("Utility Unlock: Make Way auto-enables at 20,000 score.")
    ImGui.Separator()

    local rows = driftgod.GetVehicleSectorRows and driftgod.GetVehicleSectorRows() or {}
    local nextIndex, nextReq = nil, nil
    for i, row in ipairs(rows) do
        local req = tonumber(row.threshold or 0) or 0
        if row.starterOnly ~= true and req > score and (nextReq == nil or req < nextReq) then
            nextIndex, nextReq = i, req
        end
    end

    if ImGui.BeginTable("ProgressionVehicleUnlocksGrid", 4, dgSafeTableFlags()) then
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0); dgColorText("Status", "header")
        ImGui.TableSetColumnIndex(1); dgColorText("Vehicle Sector", "header")
        ImGui.TableSetColumnIndex(2); dgColorText("Score", "header")
        ImGui.TableSetColumnIndex(3); dgColorText("Left", "header")

        for i, row in ipairs(rows) do
            local req = tonumber(row.threshold or 0) or 0
            local status, color, remaining
            if row.starterOnly == true then
                status, color, remaining = "BEGINNER", "active", 0
            else
                status, color, remaining = dgProgressStatus(score, req, i == nextIndex)
            end
            local reqText = row.starterOnly and "0 / beginner" or dgFmtNum(req)
            local remText = (remaining and remaining > 0) and dgFmtNum(remaining) or "--"
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0); dgTableCell(status, color)
            ImGui.TableSetColumnIndex(1); dgTableCell(tostring(row.label or "Sector"), color == "locked" and "locked" or nil)
            ImGui.TableSetColumnIndex(2); dgTableCell(reqText)
            ImGui.TableSetColumnIndex(3); dgTableCell(remText, status == "NEXT" and "next" or nil)
        end
        ImGui.EndTable()
    else
        for i, row in ipairs(rows) do
            local req = tonumber(row.threshold or 0) or 0
            local status, color, remaining
            if row.starterOnly == true then
                status, color, remaining = "BEGINNER", "active", 0
            else
                status, color, remaining = dgProgressStatus(score, req, i == nextIndex)
            end
            dgColorText(status .. " | " .. tostring(row.label or "Sector") .. " | " .. (row.starterOnly and "0 / beginner" or dgFmtNum(req)) .. " | Left " .. dgFmtNum(remaining or 0), color)
        end
    end

    ImGui.Separator()
    dgColorText("Unsupported categories stay silent: planes, helicopters, boats, motorcycles, cycles, commercial, and trains.", "dim")
end

