local function renderArcadeProgressionTab()
    dgColorText("Tuning", "purple")
    ImGui.Separator()
    if ImGui.BeginTabBar("DriftGodProgressionTabs") then
        if ImGui.BeginTabItem("Summary") then dgRenderProgressionSummary(); ImGui.EndTabItem() end
