local function renderArcadeRivalLeadersTab()
    ImGui.Text("Rival Leaders")
    ImGui.Separator()

    local beaten = dgGetBeatenRivalCount()
    local currentName = tostring(driftgod.S.currentRivalName or driftgod.S.rivalName or driftgod.S.nextRivalName or "Unknown Rival")
    local currentTarget = tostring(driftgod.S.rivalTargetScore or driftgod.S.nextRivalScore or driftgod.S.currentRivalTarget or "N/A")

    ImGui.Text("Beaten Rivals: " .. tostring(beaten))
    ImGui.Text("Current / Next Rival: " .. currentName)
    ImGui.Text("Target Score: " .. currentTarget)
    ImGui.Separator()
    ImGui.Text("Ghost Records: Coming soon")
    ImGui.Text("Future home for AI Ghosts, saved routes, rival replays, and ghost leaderboard runs.")
end

local function renderArcadeVehicleMasteryTab()
    if driftgod.InstallVehicleMastery then driftgod.InstallVehicleMastery("arcade vehicle mastery") end

    local key, record = dgGetCurrentVehicleMasteryRecord()

    ImGui.Text("Vehicle Mastery")
    ImGui.Separator()
    ImGui.Text("Current: " .. tostring(record.name or key))
    ImGui.Text("Level: " .. tostring(record.masteryLevel or 1) .. " / 5")
    ImGui.Text("Title: " .. tostring(record.title or (driftgod.GetVehicleMasteryTitle and driftgod.GetVehicleMasteryTitle(record) or "Discovered")))
    ImGui.Text("Total Score: " .. tostring(record.totalScore or 0))
    ImGui.Text("Best Run: " .. tostring(record.bestScore or 0))
    ImGui.Text("Banked Runs: " .. tostring(record.runsBanked or 0))
    ImGui.Text("Stunts Landed: " .. tostring(record.stuntsLanded or 0))

    ImGui.Separator()
    ImGui.Text("All Vehicle Mastery Records")

    local anyVehicle = false
    for _, vehicleRecord in pairs(driftgod.S.vehicleMastery or {}) do
        local name = tostring(vehicleRecord.name or "Vehicle")
        local level = tonumber(vehicleRecord.masteryLevel or 1) or 1
        local title = tostring(vehicleRecord.title or (driftgod.GetVehicleMasteryTitle and driftgod.GetVehicleMasteryTitle(vehicleRecord) or "Discovered"))

        if name ~= "" then
            anyVehicle = true
            ImGui.Text(name .. ": Mastery Level " .. tostring(level) .. "/5 - " .. title)
        end
    end

    if anyVehicle ~= true then
        ImGui.Text("No vehicle mastery records yet.")
    end
end

local function renderArcadeMilestonesTab()
    if driftgod.InstallProgressMilestones then driftgod.InstallProgressMilestones("arcade milestones") end
    if driftgod.CheckProgressMilestones then driftgod.CheckProgressMilestones("arcade milestones") end

    ImGui.Text("Milestones")
    ImGui.Separator()
    ImGui.Text("Milestone Title: " .. tostring(driftgod.S.progressMilestoneTitle or "Drift Initiate"))
    ImGui.Text("Milestone Points: " .. tostring(driftgod.S.progressMilestonePoints or 0))
    ImGui.Text("Completed Milestones: " .. tostring(dgCountDoneTable(driftgod.S.progressMilestonesCompleted)) .. " / " .. tostring(#(driftgod.ProgressMilestoneList or {})))

    ImGui.Separator()
    ImGui.Text("Active Milestones")
    local anyActive = false
    for _, milestone in ipairs(driftgod.ProgressMilestoneList or {}) do
        local done = driftgod.S.progressMilestonesCompleted and driftgod.S.progressMilestonesCompleted[milestone.id] == true
        if done ~= true then
            anyActive = true
            ImGui.Text("[ ] " .. tostring(milestone.title or milestone.id) .. " +" .. tostring(milestone.points or 1) .. " MP")
            if milestone.description then
                ImGui.Text("  " .. tostring(milestone.description))
            end
        end
    end

    if anyActive ~= true then
        ImGui.Text("All milestones completed.")
    end
end

dgRenderFeatureSafe = function(handle)
    if handle and ClickGUI and ClickGUI.RenderFeature then
        ClickGUI.RenderFeature(handle)
    end
end

local function dgBeginThreeColTable(id)
    if ImGui.BeginTable and ImGuiTableFlags then
        return ImGui.BeginTable(id, 3, ImGuiTableFlags.SizingStretchSame)
    end
    return false
end

local function dgEndThreeColTable()
    if ImGui.EndTable then ImGui.EndTable() end
end

local function dgTableColumn(index)
    if ImGui.TableNextRow and ImGui.TableSetColumnIndex then
        if index == 0 then ImGui.TableNextRow() end
        ImGui.TableSetColumnIndex(index)
    end
end

