local function renderGhostSavedCleanTab()
    if driftgod.GhostSavedRecordingEnsureDefaults then driftgod.GhostSavedRecordingEnsureDefaults() end

    local list = driftgod.S.savedGhostRecordings or {}
    local selectedLabel = driftgod.GetSavedRecordingComboPreview and driftgod.GetSavedRecordingComboPreview() or "No saved recordings"

    if dgBeginThreeColTable("DG_GhostSavedClean_Table") then
        dgTableColumn(0)
            ImGui.Text("Saved Recordings")
