            ImGui.Text("File:")
            ImGui.Text(tostring(driftgod.S.savedGhostRecordingSelectedFile or ""))

            if ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
                local comboOpen = false
                driftgod.Try(function()
                    comboOpen = ImGui.BeginCombo("Saved Recording", selectedLabel)
                end)
                if comboOpen then
                    for i, item in ipairs(list) do
                        local label = tostring(item.name or item.file or ("Recording " .. tostring(i)))
                        local selected = (i == (tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1))
                        local clicked = false
                        driftgod.Try(function()
                            clicked = ImGui.Selectable(label, selected)
                        end)
                        if clicked and driftgod.SetSavedRecordingIndex then
                            driftgod.SetSavedRecordingIndex(i)
                        end
                    end
                    ImGui.EndCombo()
                end
            else
                ImGui.Text("Dropdown unavailable; use Previous / Next.")
            end

        dgTableColumn(1)
            ImGui.Text("Select / Load")
            ImGui.Separator()
            dgRenderFeatureSafe(driftgod.H.GhostSavedScan)
            dgRenderFeatureSafe(driftgod.H.GhostSavedPrevious)
            dgRenderFeatureSafe(driftgod.H.GhostSavedNext)
            dgRenderFeatureSafe(driftgod.H.GhostSavedLoad)
            dgRenderFeatureSafe(driftgod.H.GhostSavedLoadLast)

