function driftgod.SyncScoreHudVisibilityFromFlags()
    if not driftgod.S then return end

    if driftgod.S.showScoreHudMaster == false or driftgod.S.showScoreHud == false or driftgod.S.scoreHudEnabled == false then
        driftgod.S.showScoreHudMaster = false
        driftgod.S.showScoreHud = false
        driftgod.S.scoreHudEnabled = false

        driftgod.S.showPointsHud = false
    end
end

local function renderChallenges()
    if driftgod.InstallSessionChallenges then driftgod.InstallSessionChallenges("challenges tab") end
    if driftgod.RefreshDailyChallenges then driftgod.RefreshDailyChallenges(false) end

    if ClickGUI.BeginCustomChildWindow("Session Challenges") then
        ImGui.Text("Session Challenges")
        ImGui.Text("30 Challenge Pool / 3 Active Daily")
        ImGui.Text("Daily Date: " .. tostring(driftgod.S.dailyChallengeDateKey or ""))
        ImGui.Separator()

        ImGui.Text("Challenge Points: " .. tostring(driftgod.S.sessionChallengePoints or 0))

        local completed = 0
        for _, done in pairs(driftgod.S.sessionChallengesCompleted or {}) do
            if done == true then completed = completed + 1 end
        end

        ImGui.Text("Total Completed: " .. tostring(completed) .. " / " .. tostring(#(driftgod.SessionChallengeList or {})))
        ImGui.Separator()

        if driftgod.H and ClickGUI.RenderFeature then
            if driftgod.H.SessionChallengesToggle then ClickGUI.RenderFeature(driftgod.H.SessionChallengesToggle) end
            if driftgod.H.SessionChallengeDebugToggle then ClickGUI.RenderFeature(driftgod.H.SessionChallengeDebugToggle) end
            if driftgod.H.SessionChallengeSnapshot then ClickGUI.RenderFeature(driftgod.H.SessionChallengeSnapshot) end
            if driftgod.H.ResetSessionChallenges then ClickGUI.RenderFeature(driftgod.H.ResetSessionChallenges) end
            if driftgod.H.ForceNextDailyChallenges then ClickGUI.RenderFeature(driftgod.H.ForceNextDailyChallenges) end
        end

        ImGui.Separator()
        ImGui.Text("Today's 3 Challenges:")

        for _, challenge in ipairs((driftgod.GetActiveDailyChallenges and driftgod.GetActiveDailyChallenges()) or {}) do
            local done = driftgod.S.sessionChallengesCompleted and driftgod.S.sessionChallengesCompleted[challenge.id] == true
            local mark = done and "[DONE] " or "[ ] "
            ImGui.Text(mark .. tostring(challenge.title or challenge.id) .. " +" .. tostring(challenge.points or 1) .. " CP")
        end

        ClickGUI.EndCustomChildWindow()
    end
end

local function renderDailyChallengesSection()
    if driftgod.InstallSessionChallenges then driftgod.InstallSessionChallenges("progress tab challenges") end
    if driftgod.RefreshDailyChallenges then driftgod.RefreshDailyChallenges(false) end

    ImGui.Separator()
    ImGui.Text("Daily Challenges")
    ImGui.Text("30 Challenge Pool / 3 Active Daily")
    ImGui.Text("Daily Date: " .. tostring(driftgod.S.dailyChallengeDateKey or ""))
    ImGui.Text("Challenge Points: " .. tostring(driftgod.S.sessionChallengePoints or 0))

    local completed = 0
    for _, done in pairs(driftgod.S.sessionChallengesCompleted or {}) do
        if done == true then completed = completed + 1 end
    end

    ImGui.Text("Total Completed: " .. tostring(completed) .. " / " .. tostring(#(driftgod.SessionChallengeList or {})))

    if driftgod.H and ClickGUI.RenderFeature then
        if driftgod.H.SessionChallengesToggle then ClickGUI.RenderFeature(driftgod.H.SessionChallengesToggle) end
        if driftgod.H.SessionChallengeSnapshot then ClickGUI.RenderFeature(driftgod.H.SessionChallengeSnapshot) end
        if driftgod.H.ForceNextDailyChallenges then ClickGUI.RenderFeature(driftgod.H.ForceNextDailyChallenges) end
    end

    ImGui.Separator()
    ImGui.Text("Today's 3 Challenges:")

    local active = (driftgod.GetActiveDailyChallenges and driftgod.GetActiveDailyChallenges()) or {}
    if #active <= 0 then
        ImGui.Text("No active daily challenges found.")
    end

    for _, challenge in ipairs(active) do
        local done = driftgod.S.sessionChallengesCompleted and driftgod.S.sessionChallengesCompleted[challenge.id] == true
        local mark = done and "[DONE] " or "[ ] "
        ImGui.Text(mark .. tostring(challenge.title or challenge.id) .. " +" .. tostring(challenge.points or 1) .. " CP")
        if challenge.description then
            ImGui.Text("  " .. tostring(challenge.description))
        end
    end
end

