local function renderVehicleMastery()
    if driftgod.InstallVehicleMastery then driftgod.InstallVehicleMastery("vehicle mastery tab") end

    if ClickGUI.BeginCustomChildWindow("Vehicle Mastery") then
        local key = driftgod.GetVehicleMasteryKey and driftgod.GetVehicleMasteryKey() or "current_vehicle"
        local record = driftgod.GetVehicleMasteryRecord and driftgod.GetVehicleMasteryRecord(key) or {}

        ImGui.Text("Vehicle Mastery")
        ImGui.Separator()
        ImGui.Text("Current: " .. tostring(record.name or key))
        ImGui.Text("Native Key: " .. tostring(key))
        ImGui.Text("Level: " .. tostring(record.masteryLevel or 1) .. " / 5")
        ImGui.Text("Title: " .. tostring(record.title or (driftgod.GetVehicleMasteryTitle and driftgod.GetVehicleMasteryTitle(record) or "Discovered")))
        ImGui.Text("Total Score: " .. tostring(record.totalScore or 0))
        ImGui.Text("Best Run: " .. tostring(record.bestScore or 0))
        ImGui.Text("Banked Runs: " .. tostring(record.runsBanked or 0))
        ImGui.Text("Stunts Landed: " .. tostring(record.stuntsLanded or 0))
        ImGui.Separator()

        if driftgod.H and ClickGUI.RenderFeature then
            if driftgod.H.VehicleMasteryToggle then ClickGUI.RenderFeature(driftgod.H.VehicleMasteryToggle) end
            if driftgod.H.VehicleMasteryDebugToggle then ClickGUI.RenderFeature(driftgod.H.VehicleMasteryDebugToggle) end
            if driftgod.H.VehicleMasterySnapshot then ClickGUI.RenderFeature(driftgod.H.VehicleMasterySnapshot) end
            if driftgod.H.VehicleMasteryRefreshVehicle then ClickGUI.RenderFeature(driftgod.H.VehicleMasteryRefreshVehicle) end
        end

        ImGui.Separator()
        ImGui.Text("All Vehicle Mastery Records")

        local anyVehicle = false
        for _, vehicleRecord in pairs(driftgod.S.vehicleMastery or {}) do
            local name = tostring(vehicleRecord.name or "Vehicle")
            local level = tonumber(vehicleRecord.masteryLevel or 1) or 1

            if name ~= "" then
                anyVehicle = true
                ImGui.Text(name .. ": Mastery Level " .. tostring(level) .. "/5" .. " - " .. tostring(vehicleRecord.title or (driftgod.GetVehicleMasteryTitle and driftgod.GetVehicleMasteryTitle(vehicleRecord) or "Discovered")))
            end
        end

        if anyVehicle ~= true then
            ImGui.Text("No vehicle mastery records yet.")
        end

        ClickGUI.EndCustomChildWindow()
    end
end

