driftgod.S = driftgod.S or {}
driftgod.S.zentornoSpawnSelectedMethod = driftgod.S.zentornoSpawnSelectedMethod or 1
driftgod.S.zentornoSpawnToggleMethod = driftgod.S.zentornoSpawnToggleMethod or 1

local ZENTORNO_SPAWN_METHODS = {
    { id = 1, key = "A", name = "A - Current", fn = function() if driftgod.SpawnZentorno_MethodA_Current then driftgod.SpawnZentorno_MethodA_Current() elseif driftgod.SpawnZentorno then driftgod.SpawnZentorno() end end },
    { id = 2, key = "B", name = "B - Street 18 After", fn = function() if driftgod.SpawnZentorno_MethodB_Street18_After then driftgod.SpawnZentorno_MethodB_Street18_After() end end },
    { id = 3, key = "C", name = "C - Street 17 After", fn = function() if driftgod.SpawnZentorno_MethodC_Street17_After then driftgod.SpawnZentorno_MethodC_Street17_After() end end },
    { id = 4, key = "D", name = "D - Street 19 After", fn = function() if driftgod.SpawnZentorno_MethodD_Street19_After then driftgod.SpawnZentorno_MethodD_Street19_After() end end },
    { id = 5, key = "E", name = "E - Delayed Triple", fn = function() if driftgod.SpawnZentorno_MethodE_DelayedTriple then driftgod.SpawnZentorno_MethodE_DelayedTriple() end end },
    { id = 6, key = "F", name = "F - Track 18", fn = function() if driftgod.SpawnZentorno_MethodF_Track18 then driftgod.SpawnZentorno_MethodF_Track18() end end },
    { id = 7, key = "G", name = "G - High End 18", fn = function() if driftgod.SpawnZentorno_MethodG_HighEnd18 then driftgod.SpawnZentorno_MethodG_HighEnd18() end end },
    { id = 8, key = "H", name = "H - Street 18 Custom Tires", fn = function() if driftgod.SpawnZentorno_MethodH_CustomTires then driftgod.SpawnZentorno_MethodH_CustomTires() end end },
    { id = 9, key = "P", name = "Probe Current Zentorno Wheels", fn = function() if driftgod.ZentornoWheelProbeCurrent then driftgod.ZentornoWheelProbeCurrent() end end },
}

local function runZentornoSpawnMethod(methodId)
    methodId = tonumber(methodId or 1) or 1

    for _, method in ipairs(ZENTORNO_SPAWN_METHODS) do
        if method.id == methodId then
            if driftgod.Log then driftgod.Log("[SpawnTab] Running Zentorno method " .. tostring(method.name)) end
            driftgod.Try(method.fn)
            return true
        end
    end

    if driftgod.Log then driftgod.Log("[SpawnTab] Invalid Zentorno method: " .. tostring(methodId)) end
    return false
end

local function spawnTabButton(label, cb)
    local clicked = false

    driftgod.Try(function()
        if ImGui and ImGui.Button then
            clicked = ImGui.Button(label)
        elseif ClickGUI and ClickGUI.Button then
            clicked = ClickGUI.Button(label)
        elseif GUI and GUI.Button then
            clicked = GUI.Button(label)
        end
    end)

    if clicked and cb then
        driftgod.Try(cb)
    end
end

local function spawnTabText(text)
    driftgod.Try(function()
        if ImGui and ImGui.Text then
            ImGui.Text(tostring(text or ""))
        elseif ClickGUI and ClickGUI.Text then
            ClickGUI.Text(tostring(text or ""))
        elseif GUI and GUI.Text then
            GUI.Text(tostring(text or ""))
        end
    end)
end

