end

local function renderSpawnButtons()
    spawnTabText("Buttons")
    for _, method in ipairs(ZENTORNO_SPAWN_METHODS) do
        spawnTabButton("Spawn Zentorno " .. method.name, function()
            runZentornoSpawnMethod(method.id)
        end)
    end
end

local function renderSpawnDropdown()
    spawnTabText("Dropdown-style selector")
    spawnTabText("Selected Method: " .. tostring(driftgod.S.zentornoSpawnSelectedMethod) .. " / " .. tostring(#ZENTORNO_SPAWN_METHODS))

    spawnTabButton("Previous Zentorno Method", function()
        driftgod.S.zentornoSpawnSelectedMethod = (tonumber(driftgod.S.zentornoSpawnSelectedMethod or 1) or 1) - 1
        if driftgod.S.zentornoSpawnSelectedMethod < 1 then driftgod.S.zentornoSpawnSelectedMethod = #ZENTORNO_SPAWN_METHODS end
    end)

    spawnTabButton("Next Zentorno Method", function()
        driftgod.S.zentornoSpawnSelectedMethod = (tonumber(driftgod.S.zentornoSpawnSelectedMethod or 1) or 1) + 1
        if driftgod.S.zentornoSpawnSelectedMethod > #ZENTORNO_SPAWN_METHODS then driftgod.S.zentornoSpawnSelectedMethod = 1 end
    end)

    for _, method in ipairs(ZENTORNO_SPAWN_METHODS) do
        if method.id == tonumber(driftgod.S.zentornoSpawnSelectedMethod or 1) then
            spawnTabText("Current: " .. method.name)
            break
        end
    end

    spawnTabButton("Spawn Selected Zentorno Method", function()
        runZentornoSpawnMethod(driftgod.S.zentornoSpawnSelectedMethod)
    end)
end

local function renderSpawnToggles()
    spawnTabText("Toggle-style selector")
    spawnTabText("Active Toggle Method: " .. tostring(driftgod.S.zentornoSpawnToggleMethod) .. " / " .. tostring(#ZENTORNO_SPAWN_METHODS))

    for _, method in ipairs(ZENTORNO_SPAWN_METHODS) do
        local label = (driftgod.S.zentornoSpawnToggleMethod == method.id and "[ON] " or "[OFF] ") .. method.name
        spawnTabButton(label, function()
            driftgod.S.zentornoSpawnToggleMethod = method.id
            if driftgod.Log then driftgod.Log("[SpawnTab] Toggle selected: " .. method.name) end
        end)
    end

    spawnTabButton("Spawn From Toggle Selection", function()
        runZentornoSpawnMethod(driftgod.S.zentornoSpawnToggleMethod)
    end)
end

