local DG_A24_COLORS = {
    purple = {0.72, 0.42, 1.00, 1.00},
    green  = {0.30, 0.95, 0.40, 1.00},
    yellow = {1.00, 0.86, 0.22, 1.00},
    red    = {1.00, 0.25, 0.25, 1.00},
    gold   = {1.00, 0.74, 0.18, 1.00},
    cyan   = {0.35, 0.82, 1.00, 1.00},
    gray   = {0.62, 0.62, 0.68, 1.00},
    white  = {1.00, 1.00, 1.00, 1.00},
}

local function dgA24ColorText(text, colorName)
    local c = DG_A24_COLORS[colorName or "white"] or DG_A24_COLORS.white
    if ImGui and ImGui.TextColored then
        ImGui.TextColored(c[1], c[2], c[3], c[4], tostring(text or ""))
    elseif ImGui and ImGui.Text then
        ImGui.Text(tostring(text or ""))
    end
end

local function dgA24SameLine()
    if ImGui and ImGui.SameLine then ImGui.SameLine() end
end

local function dgA24Button(label, cb)
    if ImGui and ImGui.Button then
        local ok, pressed = driftgod.Try(function() return ImGui.Button(tostring(label or "Button")) end)
        if ok and pressed then
            if cb then driftgod.Try(cb) end
            return true
        end
    end
    return false
end

local function dgA24SaveQuiet()
    if DG and driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
end

local function dgA24Header(title, subtitle)
    dgA24ColorText(tostring(title or "DriftGod"), "purple")
    if subtitle and tostring(subtitle) ~= "" then dgA24ColorText(tostring(subtitle), "gray") end
    if ImGui and ImGui.Separator then ImGui.Separator() end
end

local function dgA24StatusColor(ok, warn)
    if ok == true then return "green" end
    if warn == true then return "yellow" end
    return "gray"
end

local function dgA24BoolLabel(v)
    return v == true and "Enabled" or "Disabled"
end

local function dgA24RenderMetricTable(id, rows)
    if ImGui and ImGui.BeginTable and ImGuiTableFlags and ImGui.BeginTable(id, 2, ImGuiTableFlags.SizingStretchSame) then
        for _, row in ipairs(rows or {}) do
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0)
            dgA24ColorText(row[1] or "", row[3] or "cyan")
            ImGui.TableSetColumnIndex(1)
            dgA24ColorText(row[2] or "", row[4] or "white")
        end
        ImGui.EndTable()
    else
        for _, row in ipairs(rows or {}) do ImGui.Text(tostring(row[1]) .. ": " .. tostring(row[2])) end
    end
end

local function dgA24BeginTable(id, columns)
    return ImGui and ImGui.BeginTable and ImGuiTableFlags and ImGui.BeginTable(id, columns, ImGuiTableFlags.SizingStretchSame)
end

local function dgA24RenderFeature(handle, label)
    if handle and ClickGUI and ClickGUI.RenderFeature then
        ClickGUI.RenderFeature(handle)
    else
        dgA24ColorText("Missing: " .. tostring(label or "feature"), "red")
    end
end

