        dgA24Header("Presets", "Only unlocked / currently usable presets are shown here.")
        dgA24RenderFeature(driftgod.H.PresetDefault, "PresetDefault")
        dgA24RenderFeature(driftgod.H.PresetKrieger, "PresetKrieger")

        local shownArcadePreset = false
        local function renderPresetCategory(label, familyList)
            local categoryShown = false
            for _, familyName in ipairs(familyList or {}) do
                for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
                    local usable = false
                    if p and p.id and p.family == familyName then
                        if driftgod.IsArcadeDriftPresetUnlocked then
                            usable = driftgod.IsArcadeDriftPresetUnlocked(p.id) == true
                        else
                            usable = (tonumber(p.unlock or 0) or 0) <= 0
                        end
                    end
                    if usable then
                        if not shownArcadePreset then

                            dgA24ColorText("Arcade Presets", "purple")
                            shownArcadePreset = true
                        end
                        if not categoryShown then

                            dgA24ColorText("  " .. tostring(label or "Preset Category"), "header")
                            categoryShown = true
                        end
                        dgA24RenderFeature(driftgod.H["ArcadePreset_" .. tostring(p.id)], "ArcadePreset_" .. tostring(p.id))
                    end
                end
            end
        end

        renderPresetCategory("Starter", {"Default / Starter"})
        renderPresetCategory("Open", {"Open"})
        renderPresetCategory("Wide Road", {"Wide / Open Roads"})
        renderPresetCategory("Technical / Windy Roads", {"Technical / Windy Roads"})

        if not shownArcadePreset then
            ImGui.Separator()
            dgA24ColorText("Beat higher Best Run scores to unlock more Drift presets.", "cyan")
        end
        dgA24ColorText("Preset values are capped by your unlocked Tuning levels.", "cyan")
        if dgColorText then
            dgColorText(driftgod.GetNextArcadeDriftPresetHint and driftgod.GetNextArcadeDriftPresetHint() or "Unlock more in Arcade > Drift Presets.", "next")
        else
            ImGui.Text("Unlock more in Arcade > Drift Presets.")
        end
        ClickGUI.EndCustomChildWindow()
    end

    if ClickGUI.BeginCustomChildWindow("Drift Tuning") then
        if driftgod.ClampAssistToUnlocks then driftgod.ClampAssistToUnlocks(false) end
        dgA24Header("Unlocked Tuning", "Presets and buttons are capped by your unlocked progression levels.")
        dgA24RenderMetricTable("A24_DriftTuneGrid", {
            {"Drift Level", dgAssistDisplay(driftgod.S.driftGripLevel or 1, capDrift()), "purple", "green"},
            {"Stability", dgAssistDisplay(driftgod.S.driftStabilityLevel or 1, capStability()), "purple", "green"},
            {"Auto Counter", dgAssistDisplay(driftgod.S.autoCounterSteerLevel or 1, capAutoCounterSteer()), "purple", "green"},
