            {"Traction Override", tostring(driftgod.S.experimentalTractionLevel or 0) .. " / 5", "yellow", "white"},
            {"Grip Override", tostring(driftgod.S.experimentalGripLevel or 3) .. " / 5", "yellow", "white"},
            {"Gravity", tostring(driftgod.S.experimentalGravityStrength or 1) .. " / 5", "yellow", "white"},
            {"Experimental Accel", tostring(driftgod.S.experimentalAccelStrength or 3) .. " / 5", "yellow", "white"},
        })
        ImGui.Separator()
