renderArcadeVehicleMasteryTab = function()
    if driftgod.InstallVehicleMastery then driftgod.InstallVehicleMastery("a24 vehicle") end
    if ClickGUI.BeginCustomChildWindow("Vehicle Mastery") then
        local key, record = dgGetCurrentVehicleMasteryRecord()
        dgA24Header("Vehicle Mastery", "Current vehicle progress and discovered mastery records.")
        dgA24RenderMetricTable("A24_VehicleMasteryCurrent", {
            {"Current", tostring(record.name or key), "cyan", "white"},
            {"Level", tostring(record.masteryLevel or 1) .. " / 5", "green", "white"},
            {"Title", tostring(record.title or (driftgod.GetVehicleMasteryTitle and driftgod.GetVehicleMasteryTitle(record) or "Discovered")), "purple", "white"},
            {"Total Score", tostring(record.totalScore or 0), "gold", "white"},
            {"Best Run", tostring(record.bestScore or 0), "gold", "white"},
        })
        ImGui.Separator()
        driftgod.Try(function()
            if driftgod.InstallVehicleSectors then driftgod.InstallVehicleSectors("vehicle mastery render") end
            local veh = driftgod.GetVehicle and driftgod.GetVehicle() or 0
            local ok, info = driftgod.CanUseVehicleSector and driftgod.CanUseVehicleSector(veh) or true, nil
            if driftgod.GetVehicleSectorInfo then info = driftgod.GetVehicleSectorInfo(veh) end
            ImGui.Text("Vehicle Sectors")
            ImGui.Text("Unlock Score: " .. tostring(math.floor((driftgod.GetVehicleSectorProgressScore and driftgod.GetVehicleSectorProgressScore()) or (driftgod.S.bestScore or 0))))
            if info then
                ImGui.Text("Current Sector: " .. tostring(info.label or "Unknown") .. " - " .. (info.ok and "UNLOCKED" or string.upper(tostring(info.reason or "LOCKED"))))
            end
            local rows = driftgod.GetVehicleSectorRows and driftgod.GetVehicleSectorRows() or {}
            for _, row in ipairs(rows) do
                local label = tostring(row.label or "Sector")
                local status = row.unlocked and "UNLOCKED" or (tostring(row.threshold or 0) .. " score")
                if row.description then status = tostring(row.description) end
                ImGui.Text(label .. ": " .. status)
            end
        end)
        ImGui.Separator()
        dgA24RenderFeature(driftgod.H.VehicleMasteryToggle, "VehicleMasteryToggle")
        dgA24RenderFeature(driftgod.H.VehicleSectorUnlocksToggle, "VehicleSectorUnlocksToggle")
        dgA24RenderFeature(driftgod.H.VehicleMasterySnapshot, "VehicleMasterySnapshot")
        dgA24RenderFeature(driftgod.H.VehicleMasteryRefreshVehicle, "VehicleMasteryRefreshVehicle")
        ClickGUI.EndCustomChildWindow()
    end
end

