local function dgA25Text(text)
    if ImGui and ImGui.Text then ImGui.Text(tostring(text or "")) end
end

local function dgA25Color(text, color)
    if dgA24ColorText then
        dgA24ColorText(tostring(text or ""), tostring(color or "white"))
    elseif ImGui and ImGui.Text then
        ImGui.Text(tostring(text or ""))
    end
end

local function dgA25Header(title, subtitle)
    if dgA24Header then
        dgA24Header(tostring(title or ""), tostring(subtitle or ""))
    else
        dgA25Color(title, "purple")
        if subtitle and subtitle ~= "" then dgA25Color(subtitle, "cyan") end
        if ImGui and ImGui.Separator then ImGui.Separator() end
    end
end

local function dgA25StatusColor(status)
    status = tostring(status or ""):lower()
    if status:find("ready") or status:find("loaded") or status:find("saved") or status:find("complete") or status:find("enabled") or status:find("prepared") then return "green" end
    if status:find("record") or status:find("race") or status:find("play") or status:find("active") then return "purple" end
    if status:find("fail") or status:find("error") or status:find("none") or status:find("missing") then return "red" end
    if status:find("wait") or status:find("idle") or status:find("not") then return "yellow" end
    return "white"
end

local function dgA25BeginTable(id, cols)
    if dgA24BeginTable then return dgA24BeginTable(id, cols) end
    if ImGui and ImGui.BeginTable and ImGuiTableFlags then return ImGui.BeginTable(id, cols, ImGuiTableFlags.SizingStretchSame) end
    return false
end

local function dgA25EndTable()
    if ImGui and ImGui.EndTable then ImGui.EndTable() end
end

local function dgA25Row(label, value, labelColor, valueColor)
    if not (ImGui and ImGui.TableNextRow and ImGui.TableSetColumnIndex) then
        dgA25Text(tostring(label or "") .. ": " .. tostring(value or ""))
        return
    end
    ImGui.TableNextRow()
    ImGui.TableSetColumnIndex(0); dgA25Color(label, labelColor or "cyan")
    ImGui.TableSetColumnIndex(1); dgA25Color(value, valueColor or "white")
end

local function dgA25MetricGrid(id, rows)
    if dgA25BeginTable(id, 2) then
        for _, row in ipairs(rows or {}) do
            dgA25Row(row[1], row[2], row[3], row[4])
        end
        dgA25EndTable()
    else
        for _, row in ipairs(rows or {}) do dgA25Text(tostring(row[1]) .. ": " .. tostring(row[2])) end
    end
end

local function dgA25Feature(handle, key)
    if dgA24RenderFeature then return dgA24RenderFeature(handle, key) end
    if handle and ClickGUI and ClickGUI.RenderFeature then ClickGUI.RenderFeature(handle) end
end

local function dgA25SameLine()
    if dgA24SameLine then dgA24SameLine() elseif ImGui and ImGui.SameLine then ImGui.SameLine() end
end

renderArcadeProgressTab = function()
    if ClickGUI.BeginCustomChildWindow("Progress Snapshot") then
        local unlockScore = driftgod.GetLifetimeScore and driftgod.GetLifetimeScore() or (driftgod.S.bestScore or 0)
        local bestScore = tonumber(driftgod.S.bestScore or 0) or 0
        local rank = tostring(driftgod.GetRank and driftgod.GetRank(bestScore) or "Unknown")
        local milestoneTitle = tostring(driftgod.S.progressMilestoneTitle or "Drift Initiate")
        local milestonePoints = tonumber(driftgod.S.progressMilestonePoints or 0) or 0
        local completed = 0
        for _, done in pairs(driftgod.S.progressMilestonesCompleted or {}) do if done == true then completed = completed + 1 end end
        local totalMilestones = #(driftgod.ProgressMilestoneList or {})

        dgA25Header("Progress", "Fast snapshot. Use Progression for exact unlock requirements.")
        dgA25MetricGrid("A25_ProgressSnapshotGrid", {
