local function renderBanned()
    if driftgod.InstallNoScoreZones then driftgod.InstallNoScoreZones() end
    if ClickGUI.BeginCustomChildWindow("Banned Area Control") then
        dgA24Header("Banned", "Developer-only zones where drift score and unlock progress do not count.")
        local customArea = driftgod.GetActiveBannedArea and driftgod.GetActiveBannedArea() or nil
        local presetArea = driftgod.GetActivePresetBannedArea and driftgod.GetActivePresetBannedArea() or nil
        local activeArea = presetArea or customArea
        local driveWater = driftgod.IsDriveOnWaterActive and driftgod.IsDriveOnWaterActive() or false
        dgA24RenderMetricTable("A35_BannedStatusGrid", {
            {"Banned Areas", (driftgod.S.bannedAreasEnabled ~= false and driftgod.S.noScoreZonesEnabled ~= false) and "Enabled" or "Disabled", (driftgod.S.bannedAreasEnabled ~= false and driftgod.S.noScoreZonesEnabled ~= false) and "green" or "red", "white"},
            {"Preset Areas", tostring(driftgod.GetEnabledPresetBannedAreaCount and driftgod.GetEnabledPresetBannedAreaCount() or 0) .. " Enabled", "gold", "white"},
            {"Custom Areas", tostring(driftgod.GetBannedAreaCount and driftgod.GetBannedAreaCount() or 0), "purple", "white"},
            {"Radius", tostring(math.floor(tonumber(driftgod.S.bannedAreaRadius or driftgod.S.noScoreZoneRadius or 55.0) or 55)) .. "m", "cyan", "white"},
            {"Current Area", activeArea and tostring(activeArea.name or "Banned Area") or "Scoring Allowed", activeArea and "red" or "green", "white"},
            {"Drive On Water", driveWater and "Blocked" or "Not Detected", driveWater and "red" or "gray", "white"},
        })
        dgA24ColorText("Use this for farm spots, exploit areas, or map scouting. Drift still works, but score is blocked.", "yellow")
        dgA24ColorText("Preset areas are polygon bans built from your marker logs. Toggle them on/off for testing.", "cyan")
        dgA24RenderFeature(driftgod.H.NoScoreZonesToggle, "NoScoreZonesToggle")
        dgA24RenderFeature(driftgod.H.BlockDriveOnWaterScore, "BlockDriveOnWaterScore")
        if ImGui and ImGui.Separator then ImGui.Separator() end
        dgA24Header("Preset Areas", "Named flat-area polygons for anti-farm scoring protection.")
        dgA24ColorText("Each preset area has its own toggle. Green = enabled, gray = disabled.", "cyan")

        local function dgA36RenderPresetArea(area)
            if not area or not area.id then return end
            local id = tostring(area.id)
            local label = tostring(area.name or id)
            local enabled = driftgod.IsPresetBannedAreaEnabled and driftgod.IsPresetBannedAreaEnabled(id) or false
            local statusColor = enabled and "green" or "gray"
            local statusText = enabled and "ENABLED" or "DISABLED"
            dgA24ColorText(statusText, statusColor)
            if ImGui and ImGui.SameLine then ImGui.SameLine() end
            dgA24ColorText(label, enabled and "gold" or "white")
            if ImGui and ImGui.SameLine then ImGui.SameLine() end
            local buttonText = (enabled and "Disable##A36_" or "Enable##A36_") .. id
            if ImGui and ImGui.Button and ImGui.Button(buttonText) then
                if driftgod.SetPresetBannedAreaEnabled then driftgod.SetPresetBannedAreaEnabled(id, not enabled) end
            end
        end

        local presetAreas = driftgod.GetPresetBannedAreas and driftgod.GetPresetBannedAreas() or {}
        if #presetAreas > 0 then

            local col = 0
            for _, area in ipairs(presetAreas) do
                dgA36RenderPresetArea(area)
                col = col + 1
                if col % 2 == 1 then
                    if ImGui and ImGui.SameLine then ImGui.SameLine() end
                    dgA24ColorText("   ", "gray")
                    if ImGui and ImGui.SameLine then ImGui.SameLine() end
                end
            end
        else
            dgA24ColorText("No preset areas loaded.", "red")
        end

        dgA24RenderFeature(driftgod.H.BannedPresetEnableAll, "BannedPresetEnableAll"); dgA24SameLine(); dgA24RenderFeature(driftgod.H.BannedPresetDisableAll, "BannedPresetDisableAll")
        if ImGui and ImGui.Separator then ImGui.Separator() end
        dgA24Header("Custom Tools", "Mark or add temporary radius-based banned areas while scouting.")
        dgA24RenderFeature(driftgod.H.BannedMarkHere, "BannedMarkHere")
        dgA24RenderFeature(driftgod.H.NoScoreZoneAddHere, "NoScoreZoneAddHere")
        dgA24RenderFeature(driftgod.H.NoScoreZoneRadiusMinus, "NoScoreZoneRadiusMinus"); dgA24SameLine(); dgA24RenderFeature(driftgod.H.NoScoreZoneRadiusPlus, "NoScoreZoneRadiusPlus")
        dgA24RenderFeature(driftgod.H.NoScoreZoneRemoveLast, "NoScoreZoneRemoveLast"); dgA24SameLine(); dgA24RenderFeature(driftgod.H.NoScoreZoneClearAll, "NoScoreZoneClearAll")
        ClickGUI.EndCustomChildWindow()
    end

    if ClickGUI.BeginCustomChildWindow("Area List") then
        dgA24Header("Saved Banned Areas", "Coordinates are saved in settings and checked during scoring.")
        local zones = driftgod.GetBannedAreas and driftgod.GetBannedAreas() or {}
        if #zones <= 0 then
            dgA24ColorText("No banned areas saved yet. Press Mark Coordinates or Add Banned Area Here while scouting.", "gray")
        else
            if ImGui and ImGui.BeginTable and ImGui.BeginTable("A33_BannedAreasTable", 5) then
                ImGui.TableSetupColumn("#")
                ImGui.TableSetupColumn("Name")
                ImGui.TableSetupColumn("X")
                ImGui.TableSetupColumn("Y")
                ImGui.TableSetupColumn("Radius")
                ImGui.TableHeadersRow()
                for i, z in ipairs(zones) do
                    ImGui.TableNextRow()
                    ImGui.TableSetColumnIndex(0); dgA24ColorText(tostring(i), "purple")
                    ImGui.TableSetColumnIndex(1); dgA24ColorText(tostring(z.name or "Area"), z.enabled == false and "gray" or "white")
                    ImGui.TableSetColumnIndex(2); dgA24ColorText(string.format("%.1f", tonumber(z.x or 0) or 0), "cyan")
                    ImGui.TableSetColumnIndex(3); dgA24ColorText(string.format("%.1f", tonumber(z.y or 0) or 0), "cyan")
                    ImGui.TableSetColumnIndex(4); dgA24ColorText(tostring(math.floor(tonumber(z.radius or 0) or 0)) .. "m", "gold")
                end
                ImGui.EndTable()
            else
                for i, z in ipairs(zones) do
                    dgA24ColorText(string.format("%02d  %s  X %.1f / Y %.1f / R %sm", i, tostring(z.name or "Area"), tonumber(z.x or 0) or 0, tonumber(z.y or 0) or 0, tostring(math.floor(tonumber(z.radius or 0) or 0))), "white")
                end
            end
        end
        ClickGUI.EndCustomChildWindow()
    end
end

local function dgA38Text(msg, color)
    local s = tostring(msg or "")
    local c = tostring(color or "white")
    local map = {
        header={0.72,0.42,1.00,1.00}, purple={0.72,0.42,1.00,1.00}, active={0.72,0.42,1.00,1.00},
        green={0.30,1.00,0.45,1.00}, red={1.00,0.30,0.34,1.00}, yellow={1.00,0.86,0.25,1.00},
        gold={1.00,0.72,0.18,1.00}, cyan={0.35,0.86,1.00,1.00}, blue={0.45,0.65,1.00,1.00},
        dim={0.62,0.62,0.68,1.00}, locked={1.00,0.28,0.32,1.00}, white={1.00,1.00,1.00,1.00}
    }
    local rgba = map[c] or map.white
    if ImGui and ImGui.TextColored then
        driftgod.Try(function() ImGui.TextColored(rgba[1], rgba[2], rgba[3], rgba[4], s) end)
    elseif dgColorText then
        dgColorText(s, c)
    elseif dgA24ColorText then
        dgA24ColorText(s, c)
    elseif ImGui and ImGui.Text then
        ImGui.Text(s)
    end
end

local function dgA38Num(v)
    if dgFmtNum then return dgFmtNum(v or 0) end
    local n = tonumber(v or 0) or 0
    local s = tostring(math.floor(n))
    local left, num, right = string.match(s, '^([^%d]*%d)(%d*)(.-)$')
    if not left then return s end
    return left .. (num:reverse():gsub('(%d%d%d)', '%1,'):reverse()) .. right
end

local function dgA38CurrentPresetLabel()
    driftgod.S = driftgod.S or {}
    local id = driftgod.S.activeArcadeDriftPreset
    if id and driftgod.ArcadeDriftPresets then
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            if p.id == id then return tostring(p.name or id) end
        end
    end
    return tostring(driftgod.S.activeStartupPreset or driftgod.StartupPresetName or 'Default')
end

local function renderHome()
    driftgod.S = driftgod.S or {}
    local best = driftgod.GetArcadeDriftPresetScore and driftgod.GetArcadeDriftPresetScore() or (driftgod.S.bestScore or driftgod.S.highestScore or 0)
    local nextHint = driftgod.GetNextArcadeDriftPresetHint and driftgod.GetNextArcadeDriftPresetHint() or 'Unlock more in Arcade > Drift Presets.'

    if ClickGUI.BeginCustomChildWindow('Home - Quick Start') then
        dgA38Text('Welcome to DriftGod', 'header')
        dgA38Text('New here? Spawn the Zentorno, choose an unlocked preset, then hold Shift to drift.', 'yellow')
        if ImGui and ImGui.Separator then ImGui.Separator() end
        dgA38Text('Current Preset: ' .. dgA38CurrentPresetLabel(), 'active')
        dgA38Text('Best Run: ' .. dgA38Num(best), 'gold')
        dgA38Text(tostring(nextHint), 'next')
        if ImGui and ImGui.Separator then ImGui.Separator() end
        renderFeatureSafe(driftgod.H.SpawnZentornoFinal, 'Spawn Zentorno')
        renderFeatureSafe(driftgod.H.SpawnToreroXOTest, 'Spawn Torero XO')
        if ImGui and ImGui.Separator then ImGui.Separator() end
        renderFeatureSafe(driftgod.H.PresetDefault, 'Preset: Default')
        renderFeatureSafe(driftgod.H.PresetKrieger, 'Preset: Krieger')
        if driftgod.ArcadeDriftPresets then
            for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
                if p and p.name == 'Runway King' and driftgod.H['ArcadePreset_' .. tostring(p.id)] then
                    renderFeatureSafe(driftgod.H['ArcadePreset_' .. tostring(p.id)], 'Preset: Runway King')
                    break
                end
            end
        end
        ClickGUI.EndCustomChildWindow()
    end

    if ClickGUI.BeginCustomChildWindow('How To Play') then
        dgA38Text('Welcome to DriftGod!', 'header')
        dgA38Text('Your goal is simple: score points, unlock rewards, and become a better drifter.', 'white')
        dgA38Text('To start drifting, use your Shift drift bind.', 'white')
        dgA38Text('Begin with:', 'white')
        dgA38Text('- Trial Zentorno', 'white')
        dgA38Text('- Trial Torero XO', 'white')
        dgA38Text('- Trial DriftGod Preset', 'white')
        dgA38Text('The Zentorno can help you reach roughly 5,000 points, while the Torero XO can push you toward 10,000 points.', 'white')
        dgA38Text('The Trial DriftGod Preset can also be used up to 10,000 points.', 'white')
        dgA38Text('Once a trial ends, the reward must be permanently unlocked through progression.', 'white')
        dgA38Text('View rewards under Arcade > Rewards.', 'yellow')
        dgA38Text('Landing stunts grants multipliers which significantly boost your score.', 'white')
        dgA38Text('There is no one-preset-fits-all. Experiment, modify, and make presets your own.', 'white')
        dgA38Text('Combine drifting, stunts, presets, abilities, and multipliers to earn higher scores and unlock rewards faster.', 'active')
        dgA38Text('Get creative. Drift like a god.', 'gold')
        ClickGUI.EndCustomChildWindow()
    end

    if ClickGUI.BeginCustomChildWindow('Quick Toggles') then
        renderFeatureSafe(driftgod.H.PointsToggle, 'Scoring ON/OFF')
        renderFeatureSafe(driftgod.H.DriftAssist, 'Drift Assist ON/OFF')
        renderFeatureSafe(driftgod.H.SmokeToggle, 'Tire Smoke')
        ClickGUI.EndCustomChildWindow()
    end
end

local function renderAdvanced()
    dgA38Text('Advanced / Setup', 'header')
    dgA38Text('Developer, config, HUD, asset, and recovery tools live here so new players are not overloaded.', 'yellow')
    if ImGui and ImGui.Separator then ImGui.Separator() end
    if ImGui.BeginTabBar('DriftGodAdvancedTabs') then
        if ImGui.BeginTabItem('Status') then renderStatus(); renderHighScores(); ImGui.EndTabItem() end
        if ImGui.BeginTabItem('Config / HUD') then renderConfig(); ImGui.EndTabItem() end
        if ImGui.BeginTabItem('Beta / Dev') then renderBeta(); ImGui.EndTabItem() end
        if ImGui.BeginTabItem('Tips') then renderTips(); ImGui.EndTabItem() end
        if ImGui.BeginTabItem('Credits') then if driftgod.RenderCredits then driftgod.RenderCredits() end; ImGui.EndTabItem() end
        ImGui.EndTabBar()
    else
        renderStatus(); renderHighScores(); renderConfig()
    end
end

local function dgMiniSep()
    if ImGui and ImGui.Separator then ImGui.Separator() end
end

local function dgMiniSameLine()
    if dgA24SameLine then dgA24SameLine()
    elseif ImGui and ImGui.SameLine then ImGui.SameLine() end
end

local function dgMiniText(msg, color)
    if dgA38Text then dgA38Text(msg, color)
    elseif dgA24ColorText then dgA24ColorText(tostring(msg or ""), color or "white")
    elseif ImGui and ImGui.Text then ImGui.Text(tostring(msg or "")) end
end

local function dgMiniFeature(handle, fallback)
    if handle and ClickGUI and ClickGUI.RenderFeature then
        ClickGUI.RenderFeature(handle)
    elseif renderFeatureSafe then
        renderFeatureSafe(handle, fallback)
    elseif dgA24RenderFeature then
        dgA24RenderFeature(handle, fallback)
    else
        dgMiniText("Missing: " .. tostring(fallback or "feature"), "red")
    end
end

local function dgMiniBeginColumns(id, columns)
    columns = tonumber(columns or 2) or 2
    if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex then
        local ok = false
        if dgSafeTableFlags then ok = ImGui.BeginTable(tostring(id), columns, dgSafeTableFlags())
        elseif ImGuiTableFlags and ImGuiTableFlags.SizingStretchSame then ok = ImGui.BeginTable(tostring(id), columns, ImGuiTableFlags.SizingStretchSame)
        else ok = ImGui.BeginTable(tostring(id), columns) end
        if ok then
            ImGui.TableNextRow()
            return true
        end
    end
    return false
end

local function dgMiniColumn(index)
    if ImGui and ImGui.TableSetColumnIndex then ImGui.TableSetColumnIndex(tonumber(index or 0) or 0) end
end

local function dgMiniEndColumns(active)
    if active and ImGui and ImGui.EndTable then ImGui.EndTable() end
end

local function dgMiniTable(id, rows)
    rows = rows or {}
    if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex then
        local ok = false
        if dgSafeTableFlags then ok = ImGui.BeginTable(tostring(id), 2, dgSafeTableFlags())
        elseif ImGuiTableFlags and ImGuiTableFlags.SizingStretchSame then ok = ImGui.BeginTable(tostring(id), 2, ImGuiTableFlags.SizingStretchSame)
        else ok = ImGui.BeginTable(tostring(id), 2) end
        if ok then
            for _, row in ipairs(rows) do
                ImGui.TableNextRow()
                ImGui.TableSetColumnIndex(0); dgMiniText(tostring(row[1] or ""), row[3] or "white")
                ImGui.TableSetColumnIndex(1); dgMiniText(tostring(row[2] or ""), row[4] or row[3] or "white")
            end
            ImGui.EndTable()
            return true
        end
    end
    for _, row in ipairs(rows) do
        dgMiniText(tostring(row[1] or "") .. ": " .. tostring(row[2] or ""), row[4] or row[3] or "white")
    end
    return false
end

local function dgMiniPresetUnlocked(p)
    if not p or not p.id then return false end
    if driftgod.IsArcadeDriftPresetUnlocked then return driftgod.IsArcadeDriftPresetUnlocked(p.id) == true end
    return (tonumber(p.unlock or 0) or 0) <= 0
end

local function dgMiniPresetCategory(label, familyList)
    local printed = false
    for _, familyName in ipairs(familyList or {}) do
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            if p and p.family == familyName and dgMiniPresetUnlocked(p) then
                if not printed then
                    dgMiniText(tostring(label or "Presets"), "header")
                    printed = true
                end
                dgMiniFeature(driftgod.H["ArcadePreset_" .. tostring(p.id)], tostring(p.name or p.id))
            end
        end
    end
    return printed
end

local function dgMiniNextUnlockCompact()
    local hint = driftgod.GetNextArcadeDriftPresetHint and driftgod.GetNextArcadeDriftPresetHint() or "Unlock more in Arcade > Drift Presets."
    hint = tostring(hint or "")
    hint = hint:gsub("Unlock more in Arcade > Drift Presets%.%s*", "")
    hint = hint:gsub("Only ", "")
    return hint ~= "" and hint or "Keep scoring to unlock more."
end

local function dgMiniRenderAbilitySnapshot(id)
    if driftgod.ClampAssistToUnlocks then driftgod.ClampAssistToUnlocks(false) end
    local rows = {
        {"Drift", dgAssistDisplay and dgAssistDisplay(driftgod.S.driftGripLevel or 1, capDrift()) or tostring(driftgod.S.driftGripLevel or 1), "white", "green"},
        {"Stability", dgAssistDisplay and dgAssistDisplay(driftgod.S.driftStabilityLevel or 1, capStability()) or tostring(driftgod.S.driftStabilityLevel or 1), "white", "green"},
        {"Counter-Steer", dgAssistDisplay and dgAssistDisplay(driftgod.S.autoCounterSteerLevel or 1, capAutoCounterSteer()) or tostring(driftgod.S.autoCounterSteerLevel or 1), "white", "green"},
        {"Momentum", dgAssistDisplay and dgAssistDisplay(driftgod.S.momentumStrength or 1, capMomentum()) or tostring(driftgod.S.momentumStrength or 1), "white", "green"},
        {"Acceleration", dgAssistDisplay and dgAssistDisplay(driftgod.S.accelStrength or 1, capAccel()) or tostring(driftgod.S.accelStrength or 1), "white", "green"},
    }
    if dgA24RenderMetricTable then dgA24RenderMetricTable(tostring(id or "DG_MiniAbilityTable"), rows)
    else dgMiniTable(tostring(id or "DG_MiniAbilityTable"), rows) end
end

