local function dgR85BestRun()
    return tonumber(driftgod.GetArcadeDriftPresetScore and driftgod.GetArcadeDriftPresetScore() or driftgod.S.bestScore or driftgod.S.highestScore or 0) or 0
end

local function dgR85ProgressTitle()
    return tostring(driftgod.S.progressMilestoneTitle or "Drift Initiate")
end

local function dgR85NextPresetName()
    if driftgod.GetNextLockedArcadeDriftPreset then
        local p, need, left = driftgod.GetNextLockedArcadeDriftPreset()
        if p then
            return tostring(p.name or "Next Preset"), tonumber(need or 0) or 0, tonumber(left or 0) or 0
        end
    end
    return "More Presets", 0, 0
end

local function dgR85RenderArcadeSnapshot(id)
    driftgod.S = driftgod.S or {}
    local best = dgR85BestRun()
    local nextName, need, left = dgR85NextPresetName()
    local cp = tonumber(driftgod.S.sessionChallengePoints or 0) or 0
    local beaten = (dgGetBeatenRivalCount and dgGetBeatenRivalCount()) or 0
    dgMiniTable(id or "DG_R85ArcadeSnapshot", {
        {"Best Run", dgA38Num(best), "white", "gold"},
        {"Active Preset", dgA38CurrentPresetLabel(), "white", "active"},
        {"Next Preset", nextName, "white", "next"},
        {"Score Left", left > 0 and dgA38Num(left) or "--", "white", left > 0 and "cyan" or "green"},
        {"Challenge Points", tostring(cp), "white", "cyan"},
        {"Rivals Beaten", tostring(beaten), "white", beaten > 0 and "green" or "white"},
    })
end

local function dgR85RenderVehicleSnapshot(id)
    driftgod.S = driftgod.S or {}
    local best = dgR85BestRun()
    local superUnlocked = best >= 25000
    local key, record = nil, nil
    if dgGetCurrentVehicleMasteryRecord then key, record = dgGetCurrentVehicleMasteryRecord() end
    record = record or {}
    dgMiniTable(id or "DG_R85VehicleSnapshot", {
        {"Current Vehicle", tostring(record.name or key or (driftgod.GetVehicleName and driftgod.GetVehicleName() or "Current")), "white", "cyan"},
        {"Mastery", "Level " .. tostring(record.masteryLevel or 1) .. " / 5", "white", "green"},
        {"Torero XO", superUnlocked and "Permanent" or (best < 5000 and "Trial" or "Locked"), "white", superUnlocked and "green" or (best < 5000 and "next" or "locked")},
        {"Zentorno", superUnlocked and "Permanent" or (best < 10000 and "Trial" or "Locked"), "white", superUnlocked and "green" or (best < 10000 and "next" or "locked")},
        {"Super", superUnlocked and "Unlocked" or (dgA38Num(math.max(0, 25000 - best)) .. " left"), "white", superUnlocked and "green" or "cyan"},
    })
end

local function dgR85RenderChallengeSnapshot(id)
    if driftgod.InstallSessionChallenges then driftgod.InstallSessionChallenges("arcade R85") end
    if driftgod.RefreshDailyChallenges then driftgod.RefreshDailyChallenges(false) end
    local active, remaining = 0, 0
    if dgGetActiveDailyChallengeCount then active, remaining = dgGetActiveDailyChallengeCount() end
    local completed = dgCountDoneTable and dgCountDoneTable(driftgod.S.sessionChallengesCompleted) or 0
    dgMiniTable(id or "DG_R85ChallengeSnapshot", {
        {"Active", tostring(active), "white", "cyan"},
        {"Remaining", tostring(remaining), "white", remaining > 0 and "next" or "green"},
        {"Completed", tostring(completed) .. " / " .. tostring(#(driftgod.SessionChallengeList or {})), "white", completed > 0 and "green" or "white"},
        {"Points", tostring(driftgod.S.sessionChallengePoints or 0), "white", "gold"},
    })
end

local function dgR85RenderMilestoneSnapshot(id)
    if driftgod.InstallProgressMilestones then driftgod.InstallProgressMilestones("arcade R85") end
    local completed = dgCountDoneTable and dgCountDoneTable(driftgod.S.progressMilestonesCompleted) or 0
    local total = #(driftgod.ProgressMilestoneList or {})
    dgMiniTable(id or "DG_R85MilestoneSnapshot", {
        {"Title", dgR85ProgressTitle(), "white", "active"},
        {"Points", dgA38Num(driftgod.S.progressMilestonePoints or 0), "white", "gold"},
        {"Completed", tostring(completed) .. " / " .. tostring(total), "white", completed > 0 and "green" or "white"},
        {"Overall Score", dgA38Num(driftgod.S.overallScore or 0), "white", "cyan"},
    })
end

local function dgR85RenderChallengeList()
    if driftgod.InstallSessionChallenges then driftgod.InstallSessionChallenges("arcade R85 list") end
    if driftgod.RefreshDailyChallenges then driftgod.RefreshDailyChallenges(false) end
    local active = (driftgod.GetActiveDailyChallenges and driftgod.GetActiveDailyChallenges()) or {}
    if #active <= 0 then
        dgMiniText("No active daily challenges found.", "dim")
        return
    end
    if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex then
        local ok = ImGui.BeginTable("DG_R85ChallengeList", 3, dgSafeTableFlags and dgSafeTableFlags() or 0)
        if ok then
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0); dgMiniText("Status", "header")
            ImGui.TableSetColumnIndex(1); dgMiniText("Challenge", "header")
            ImGui.TableSetColumnIndex(2); dgMiniText("CP", "header")
            for _, challenge in ipairs(active) do
                local done = driftgod.S.sessionChallengesCompleted and driftgod.S.sessionChallengesCompleted[challenge.id] == true
                ImGui.TableNextRow()
                ImGui.TableSetColumnIndex(0); dgMiniText(done and "DONE" or "OPEN", done and "green" or "next")
                ImGui.TableSetColumnIndex(1); dgMiniText(tostring(challenge.title or challenge.id), "white")
                ImGui.TableSetColumnIndex(2); dgMiniText("+" .. tostring(challenge.points or 1), "gold")
            end
            ImGui.EndTable()
            return
        end
    end
    for _, challenge in ipairs(active) do
        local done = driftgod.S.sessionChallengesCompleted and driftgod.S.sessionChallengesCompleted[challenge.id] == true
        dgMiniText((done and "DONE  " or "OPEN  ") .. tostring(challenge.title or challenge.id) .. "  +" .. tostring(challenge.points or 1) .. " CP", done and "green" or "white")
    end
end

