local function renderArcadeRivalsFlatR88()
    if driftgod.InstallRivals then driftgod.InstallRivals("r88 rivals flat") end
    dgR88MiniHeader("Rivals", "Simple rival progress without boxed child panels.")
    local beaten = dgGetBeatenRivalCount and dgGetBeatenRivalCount() or 0
    local total = #(driftgod.Rivals or {})
    local remaining = math.max(0, total - beaten)
    local currentName = tostring(driftgod.S.currentRivalName or driftgod.S.rivalName or driftgod.S.nextRivalName or "Unknown Rival")
    local currentTarget = tostring(driftgod.S.rivalTargetScore or driftgod.S.nextRivalScore or driftgod.S.currentRivalTarget or "N/A")
    local last = driftgod.S.driftChallengeLastResult or {}
    local lastResult = last.won == true and "Won" or (last.won == false and (last.didNotFinish and "DNF" or "Failed") or "None")
    dgMiniTable("DG_R88RivalRewardsTable", {
        {"Rivals Beaten", tostring(beaten) .. " / " .. tostring(total), "white", beaten > 0 and "green" or "white"},
        {"Remaining", tostring(remaining), "white", remaining > 0 and "next" or "green"},
        {"Current Rival", currentName, "white", "active"},
        {"Target Score", currentTarget, "white", "gold"},
        {"Last Result", lastResult, "white", lastResult == "Won" and "green" or (lastResult == "Failed" and "red" or "dim")},
    })
    dgMiniSep()
    dgMiniText("Race saved ghosts from Arcade > Ghosts & Race (Beta).", "dim")
end

