            if ok ~= true then dgMiniText("UI section failed: " .. tostring(err), "red") end
            ClickGUI.EndCustomChildWindow()
        end
    else
        dgMiniText(tostring(title or "Section"), "header")
        local ok, err = driftgod.Try(bodyFn)
        if ok ~= true then dgMiniText("UI section failed: " .. tostring(err), "red") end
        dgMiniSep()
    end
end

