function driftgod.VS_Clamp(v, mn, mx)
    v = math.floor(tonumber(v or mn) or mn)
    if v < mn then v = mn end
    if v > mx then v = mx end
    return v
end

function driftgod.VS_Now()
    if Time and Time.GetEpocheMs then
        local ok, ms = driftgod.Try(Time.GetEpocheMs)
        if ok and ms then return tonumber(ms) or 0 end
    end
    return math.floor(os.clock() * 1000)
end

function driftgod.VS_Log(msg)
    msg = tostring(msg or "")
    driftgod.VS.runtime.lastStatus = msg
    if driftgod.Log then driftgod.Log("[VehicleSpawner] " .. msg)
    elseif Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] [VehicleSpawner] " .. msg) end
end

function driftgod.VS_Warn(msg)
    msg = tostring(msg or "")
    driftgod.VS.runtime.lastStatus = msg
    if Logger and Logger.LogError then Logger.LogError("[DriftGod] [VehicleSpawner] " .. msg)
    elseif driftgod.Log then driftgod.Log("[VehicleSpawner] " .. msg) end
end

function driftgod.VS_Toast(msg, ms)
    if driftgod.Toast then driftgod.Toast(tostring(msg or ""), ms or 2500)
    elseif GUI and GUI.AddToast then GUI.AddToast("DriftGod", tostring(msg or ""), ms or 2500) end
end

function driftgod.VS_EnsureDefaults()
    driftgod.S = driftgod.S or {}
    if driftgod.S.vehicleSpawnerHotkeyInsert == nil then driftgod.S.vehicleSpawnerHotkeyInsert = false end
    if driftgod.S.vehicleSpawnerHudPresetIndex == nil then driftgod.S.vehicleSpawnerHudPresetIndex = 1 end
    if driftgod.S.vehicleSpawnerHudX == nil then driftgod.S.vehicleSpawnerHudX = 0.085 end
    if driftgod.S.vehicleSpawnerHudY == nil then driftgod.S.vehicleSpawnerHudY = 0.080 end
    if driftgod.S.vehicleSpawnerHudWidth == nil then driftgod.S.vehicleSpawnerHudWidth = 0.128 end
    if driftgod.S.vehicleSpawnerHudOpacity == nil then driftgod.S.vehicleSpawnerHudOpacity = 0.50 end
    if driftgod.S.vehicleSpawnerIndex == nil then driftgod.S.vehicleSpawnerIndex = 0 end
    if driftgod.S.vehicleSpawnerCategoryIndex == nil then driftgod.S.vehicleSpawnerCategoryIndex = 0 end
end

function driftgod.VS_TrimSlash(path)
    path = tostring(path or ""):gsub("/", "\\")
    while #path > 3 and path:sub(-1) == "\\" do path = path:sub(1, -2) end
    return path
end

function driftgod.VS_Normalize(path)
    return tostring(path or ""):gsub("/", "\\")
end

function driftgod.VS_Filename(path)
    return tostring(path or ""):match("([^\\/]+)$") or tostring(path or "")
end

function driftgod.VS_StripExt(name)
    return tostring(name or ""):gsub("%.[%w_]+$", "")
end

function driftgod.VS_Roots()
    driftgod.VS._roots = {}
    driftgod.VS._seenRoots = {}
    function driftgod.VS_AddRoot(path)
        path = driftgod.VS_TrimSlash(path or "")
        if path == "" then return end
        if not driftgod.VS._seenRoots[path:lower()] then
            driftgod.VS._seenRoots[path:lower()] = true
            driftgod.VS._roots[#driftgod.VS._roots + 1] = path
        end
    end
    driftgod.Try(function() driftgod.VS_AddRoot(FileMgr.GetMenuRootPath() .. "\\Vehicles") end)
    driftgod.Try(function()
        driftgod.VS_AddRoot(tostring(FileMgr.GetMenuRootPath() or ""):gsub("/", "\\"):gsub("\\Lua$", "") .. "\\Vehicles")
    end)
    driftgod.Try(function()
        local docs = os.getenv("USERPROFILE") or ""
        if docs ~= "" then driftgod.VS_AddRoot(docs .. "\\Documents\\Cherax\\Vehicles") end
    end)
    return driftgod.VS._roots
end

function driftgod.VS_CategoryFromPath(root, path)
    root = driftgod.VS_Normalize(root or "")
    path = driftgod.VS_Normalize(path or "")
    driftgod.VS._rel = path
    if root ~= "" and path:lower():sub(1, #root) == root:lower() then driftgod.VS._rel = path:sub(#root + 1) end
    driftgod.VS._rel = driftgod.VS_Normalize(driftgod.VS._rel):gsub("^\\+", "")
    driftgod.VS._cat = driftgod.VS._rel:match("^([^\\]+)\\") or "Root"
    if driftgod.VS._cat == "" then driftgod.VS._cat = "Root" end
    return driftgod.VS._cat, driftgod.VS._rel
end

function driftgod.VS_IndexKey(value)
    driftgod.VS._idxText = tostring(value or ""):gsub("/", "\\"):gsub(">", "\\")
    driftgod.VS._idxText = driftgod.VS._idxText:gsub("%s*\\%s*", "\\")
    driftgod.VS._idxText = driftgod.VS._idxText:gsub("%.[%w_]+$", "")
    driftgod.VS._idxText = driftgod.VS._idxText:gsub("^%s+", ""):gsub("%s+$", "")
    return driftgod.VS._idxText:lower()
end

function driftgod.VS_CategoryFromListLabel(label)
    driftgod.VS._rawLabel = tostring(label or ""):gsub("^%s+", ""):gsub("%s+$", "")
    driftgod.VS._catLabel, driftgod.VS._leafLabel = driftgod.VS._rawLabel:match("^([^/\\>]+)%s*[/\\>]%s*(.+)$")
    if driftgod.VS._catLabel and driftgod.VS._leafLabel and driftgod.VS._leafLabel ~= "" then
        return driftgod.VS._catLabel:gsub("^%s+", ""):gsub("%s+$", ""), driftgod.VS._leafLabel:gsub("^%s+", ""):gsub("%s+$", "")
    end
    return "Cherax", driftgod.VS._rawLabel
end

function driftgod.VS_FindFiles(root, extensions)
    driftgod.VS._found = {}
    driftgod.VS._seen = {}
    function driftgod.VS_AddFound(path)
        if not path or tostring(path) == "" then return end
        driftgod.VS._fkey = driftgod.VS_Normalize(path):lower()
        if not driftgod.VS._seen[driftgod.VS._fkey] then
            driftgod.VS._seen[driftgod.VS._fkey] = true
            driftgod.VS._found[#driftgod.VS._found + 1] = tostring(path)
        end
    end
    for _, ext in ipairs(extensions or { "json" }) do
        driftgod.Try(function()
            driftgod.VS._list = FileMgr.FindFiles(root, ext, true)
            if driftgod.VS._list then for _, f in ipairs(driftgod.VS._list) do driftgod.VS_AddFound(f) end end
        end)
        driftgod.Try(function()
            driftgod.VS._list = FileMgr.FindFiles(root, "." .. tostring(ext):gsub("^%.", ""), true)
            if driftgod.VS._list then for _, f in ipairs(driftgod.VS._list) do driftgod.VS_AddFound(f) end end
        end)
    end
    return driftgod.VS._found
end

function driftgod.VS_PushIndex(map, key, entry)
    driftgod.VS._ikey = driftgod.VS_IndexKey(key)
    if driftgod.VS._ikey == "" then return end
    if not map[driftgod.VS._ikey] then map[driftgod.VS._ikey] = {} end
    map[driftgod.VS._ikey][#map[driftgod.VS._ikey] + 1] = entry
end

function driftgod.VS_BuildCheraxIndex()
    driftgod.VS._indexMap = {}
    for _, hash in ipairs(driftgod.VS.CheraxSavedVehicleHashes or {}) do
        driftgod.VS._okList, driftgod.VS._list = driftgod.Try(function() return FeatureMgr.GetFeatureList(hash) end)
        if driftgod.VS._okList and driftgod.VS._list then
            driftgod.Try(function()
                for i, label in ipairs(driftgod.VS._list) do
                    driftgod.VS._display = tostring(label or ""):gsub("^%s+", ""):gsub("%s+$", "")
                    if driftgod.VS._display ~= "" then
                        driftgod.VS._cat, driftgod.VS._leaf = driftgod.VS_CategoryFromListLabel(driftgod.VS._display)
                        driftgod.VS._cleanLeaf = driftgod.VS_StripExt(driftgod.VS_Filename(driftgod.VS._leaf))
                        driftgod.VS._entry = { hash = hash, index = i - 1, label = driftgod.VS._display, used = false }
                        driftgod.VS_PushIndex(driftgod.VS._indexMap, driftgod.VS._display, driftgod.VS._entry)
                        driftgod.VS_PushIndex(driftgod.VS._indexMap, driftgod.VS._cleanLeaf, driftgod.VS._entry)
                        if driftgod.VS._cat and driftgod.VS._cat ~= "" and driftgod.VS._cat ~= "Cherax" then
                            driftgod.VS_PushIndex(driftgod.VS._indexMap, tostring(driftgod.VS._cat) .. "\\" .. tostring(driftgod.VS._cleanLeaf), driftgod.VS._entry)
                            driftgod.VS_PushIndex(driftgod.VS._indexMap, tostring(driftgod.VS._cat) .. "/" .. tostring(driftgod.VS._cleanLeaf), driftgod.VS._entry)
                        end
                    end
                end
            end)
        end
    end
    return driftgod.VS._indexMap
end

function driftgod.VS_ConsumeIndex(map, category, name)
    if not map then return nil end
    driftgod.VS._keys = { tostring(category or "") .. "\\" .. tostring(name or ""), tostring(category or "") .. "/" .. tostring(name or ""), tostring(name or "") }
    for _, key in ipairs(driftgod.VS._keys) do
        driftgod.VS._queue = map[driftgod.VS_IndexKey(key)]
        if driftgod.VS._queue then
            for _, entry in ipairs(driftgod.VS._queue) do
                if entry and entry.used ~= true then entry.used = true; return entry end
            end
        end
    end
    return nil
end

function driftgod.VS_BuiltInItems()
    driftgod.VS._builtItems = {}
    for _, hash in ipairs(driftgod.VS.CheraxSavedVehicleHashes or {}) do
        driftgod.VS._okList2, driftgod.VS._list2 = driftgod.Try(function() return FeatureMgr.GetFeatureList(hash) end)
        if driftgod.VS._okList2 and driftgod.VS._list2 then
            driftgod.Try(function()
                for i, label in ipairs(driftgod.VS._list2) do
                    driftgod.VS._display2 = tostring(label or ""):gsub("^%s+", ""):gsub("%s+$", "")
                    if driftgod.VS._display2 ~= "" then
                        driftgod.VS._cat2, driftgod.VS._leaf2 = driftgod.VS_CategoryFromListLabel(driftgod.VS._display2)
                        driftgod.VS._name2 = driftgod.VS_StripExt(driftgod.VS_Filename(driftgod.VS._leaf2))
                        driftgod.VS._builtItems[#driftgod.VS._builtItems + 1] = {
                            name = driftgod.VS._name2,
                            path = "cherax://saved_vehicle/" .. tostring(i - 1),
                            category = driftgod.VS._cat2 or "Cherax",
                            displayLabel = ((driftgod.VS._cat2 and driftgod.VS._cat2 ~= "Root" and driftgod.VS._cat2 ~= "All") and (tostring(driftgod.VS._cat2) .. " / " .. driftgod.VS._name2) or driftgod.VS._name2),
                            ext = "cherax",
                            root = "Cherax Built-In Saved Vehicles",
                            cheraxListHash = hash,
                            cheraxListIndex = i - 1,
                            cheraxListLabel = driftgod.VS._display2,
                        }
                    end
                end
            end)
            if #driftgod.VS._builtItems > 0 then return driftgod.VS._builtItems end
        end
    end
    return driftgod.VS._builtItems
end

function driftgod.VS_Refresh()
    driftgod.VS_EnsureDefaults()
    driftgod.VS.runtime.items = {}
    driftgod.VS.runtime.categories = { "All" }
    driftgod.VS._catSeen = { All = true }
    driftgod.VS._roots = driftgod.VS_Roots()
    driftgod.VS._index = driftgod.VS_BuildCheraxIndex()
    driftgod.VS._seenFiles = {}
    driftgod.VS._extensions = { "json", "ini", "xml", "txt", "cfg", "vehicle", "veh" }

    for _, root in ipairs(driftgod.VS._roots or {}) do
        driftgod.Try(function() FileMgr.CreateDir(root) end)
        for _, f in ipairs(driftgod.VS_FindFiles(root, driftgod.VS._extensions)) do
            driftgod.VS._fileKey = driftgod.VS_Normalize(f):lower()
            if not driftgod.VS._seenFiles[driftgod.VS._fileKey] then
                driftgod.VS._seenFiles[driftgod.VS._fileKey] = true
                driftgod.VS._cat3, driftgod.VS._rel3 = driftgod.VS_CategoryFromPath(root, f)
                if not driftgod.VS._catSeen[driftgod.VS._cat3] then driftgod.VS._catSeen[driftgod.VS._cat3] = true; driftgod.VS.runtime.categories[#driftgod.VS.runtime.categories + 1] = driftgod.VS._cat3 end
                driftgod.VS._nm = driftgod.VS_StripExt(driftgod.VS_Filename(f))
                driftgod.VS._match = driftgod.VS_ConsumeIndex(driftgod.VS._index, driftgod.VS._cat3, driftgod.VS._nm)
                driftgod.VS._item = {
                    name = driftgod.VS._nm,
                    path = f,
                    rel = driftgod.VS._rel3,
                    category = driftgod.VS._cat3,
                    displayLabel = ((driftgod.VS._cat3 and driftgod.VS._cat3 ~= "Root" and driftgod.VS._cat3 ~= "All") and (tostring(driftgod.VS._cat3) .. " / " .. driftgod.VS._nm) or driftgod.VS._nm),
                    ext = tostring(f):match("%.([%w_]+)$") or "",
                    root = root,
                }
                if driftgod.VS._match then
                    driftgod.VS._item.cheraxListHash = driftgod.VS._match.hash
                    driftgod.VS._item.cheraxListIndex = driftgod.VS._match.index
                    driftgod.VS._item.cheraxListLabel = driftgod.VS._match.label
                end
                driftgod.VS.runtime.items[#driftgod.VS.runtime.items + 1] = driftgod.VS._item
            end
        end
    end

    if #driftgod.VS.runtime.items == 0 then
        for _, item in ipairs(driftgod.VS_BuiltInItems()) do
            if not driftgod.VS._catSeen[item.category or "Cherax"] then driftgod.VS._catSeen[item.category or "Cherax"] = true; driftgod.VS.runtime.categories[#driftgod.VS.runtime.categories + 1] = item.category or "Cherax" end
            driftgod.VS.runtime.items[#driftgod.VS.runtime.items + 1] = item
        end
    end

    table.sort(driftgod.VS.runtime.categories, function(a, b) if a == "All" then return true end if b == "All" then return false end return tostring(a):lower() < tostring(b):lower() end)
    table.sort(driftgod.VS.runtime.items, function(a, b)
        if tostring(a.category or ""):lower() == tostring(b.category or ""):lower() then return tostring(a.name or ""):lower() < tostring(b.name or ""):lower() end
        return tostring(a.category or ""):lower() < tostring(b.category or ""):lower()
    end)
    driftgod.VS.runtime.root = (driftgod.VS._roots and driftgod.VS._roots[1]) or ""
    driftgod.VS.runtime.lastScanMs = driftgod.VS_Now()
    driftgod.S.vehicleSpawnerIndex = 0
    driftgod.S.vehicleSpawnerCategoryIndex = driftgod.VS_Clamp(driftgod.S.vehicleSpawnerCategoryIndex or 0, 0, math.max(0, #driftgod.VS.runtime.categories - 1))
    driftgod.VS_Rebuild()
    driftgod.VS_SyncFeatures()
    driftgod.VS_Log("Scanned " .. tostring(#driftgod.VS.runtime.items) .. " saved vehicles.")
    return #driftgod.VS.runtime.items
end

function driftgod.VS_RandomRow(category)
    return { isRandom = true, name = "Random", displayLabel = "Random", category = category or "All", randomTargetCategory = category or "All" }
end

function driftgod.VS_Rebuild()
    driftgod.VS_EnsureDefaults()
    driftgod.VS.runtime.filtered = {}
    driftgod.VS.runtime.names = {}
    if driftgod.VS.runtime.open and driftgod.VS.runtime.currentFolder and driftgod.VS.runtime.currentFolder ~= "" then
        driftgod.VS.runtime.filtered[#driftgod.VS.runtime.filtered + 1] = driftgod.VS_RandomRow(driftgod.VS.runtime.currentFolder)
        for _, item in ipairs(driftgod.VS.runtime.items or {}) do
            if tostring(item.category or "Root"):lower() == tostring(driftgod.VS.runtime.currentFolder):lower() then driftgod.VS.runtime.filtered[#driftgod.VS.runtime.filtered + 1] = item end
        end
    elseif driftgod.VS.runtime.open then
        if #(driftgod.VS.runtime.items or {}) > 0 then driftgod.VS.runtime.filtered[#driftgod.VS.runtime.filtered + 1] = driftgod.VS_RandomRow("All") end
        driftgod.VS._folderSeen = {}
        driftgod.VS._folderRows = {}
        for _, item in ipairs(driftgod.VS.runtime.items or {}) do
            driftgod.VS._cat4 = tostring(item.category or "Root")
            if driftgod.VS._cat4 ~= "" and driftgod.VS._cat4 ~= "Root" and driftgod.VS._cat4 ~= "All" and not driftgod.VS._folderSeen[driftgod.VS._cat4] then
                driftgod.VS._folderSeen[driftgod.VS._cat4] = true
                driftgod.VS._folderRows[#driftgod.VS._folderRows + 1] = { isFolder = true, name = "/" .. driftgod.VS._cat4, displayLabel = "/" .. driftgod.VS._cat4, category = driftgod.VS._cat4, folderTarget = driftgod.VS._cat4 }
            end
        end
        table.sort(driftgod.VS._folderRows, function(a,b) return tostring(a.name):lower() < tostring(b.name):lower() end)
        for _, folder in ipairs(driftgod.VS._folderRows) do driftgod.VS.runtime.filtered[#driftgod.VS.runtime.filtered + 1] = folder end
        for _, item in ipairs(driftgod.VS.runtime.items or {}) do
            driftgod.VS._cat5 = tostring(item.category or "Root")
            if driftgod.VS._cat5 == "Root" or driftgod.VS._cat5 == "" then driftgod.VS.runtime.filtered[#driftgod.VS.runtime.filtered + 1] = item end
        end
    else
        driftgod.VS._selCat = tostring((driftgod.VS.runtime.categories or {})[(driftgod.S.vehicleSpawnerCategoryIndex or 0) + 1] or "All")
        for _, item in ipairs(driftgod.VS.runtime.items or {}) do
            if driftgod.VS._selCat == "All" or tostring(item.category or "Root") == driftgod.VS._selCat then driftgod.VS.runtime.filtered[#driftgod.VS.runtime.filtered + 1] = item end
        end
    end
    for _, item in ipairs(driftgod.VS.runtime.filtered or {}) do driftgod.VS.runtime.names[#driftgod.VS.runtime.names + 1] = tostring(item.displayLabel or item.name or "Vehicle") end
    if #driftgod.VS.runtime.names == 0 then driftgod.VS.runtime.names[1] = "No saved vehicles scanned yet" end
    driftgod.S.vehicleSpawnerIndex = driftgod.VS_Clamp(driftgod.S.vehicleSpawnerIndex or 0, 0, math.max(0, #(driftgod.VS.runtime.filtered or {}) - 1))
    driftgod.VS_NormalizeSelection()
    driftgod.VS_SyncFeatures()
end

function driftgod.VS_NormalizeSelection()
    driftgod.VS._count = #(driftgod.VS.runtime.filtered or {})
    if driftgod.VS._count <= 0 then driftgod.S.vehicleSpawnerIndex = 0; driftgod.VS.hud.scroll = 0; return end
    driftgod.S.vehicleSpawnerIndex = driftgod.VS_Clamp(driftgod.S.vehicleSpawnerIndex or 0, 0, driftgod.VS._count - 1)
    driftgod.VS._rows = 6
    if driftgod.S.vehicleSpawnerIndex < (driftgod.VS.hud.scroll or 0) then driftgod.VS.hud.scroll = driftgod.S.vehicleSpawnerIndex
    elseif driftgod.S.vehicleSpawnerIndex >= (driftgod.VS.hud.scroll or 0) + driftgod.VS._rows then driftgod.VS.hud.scroll = driftgod.S.vehicleSpawnerIndex - driftgod.VS._rows + 1 end
    driftgod.VS.hud.scroll = driftgod.VS_Clamp(driftgod.VS.hud.scroll or 0, 0, math.max(0, driftgod.VS._count - driftgod.VS._rows))
end

function driftgod.VS_SyncFeatures()
    if not driftgod.VS.features then return end
    driftgod.Try(function() if driftgod.VS.features.category then driftgod.VS.features.category:SetList(driftgod.VS.runtime.categories or { "All" }); driftgod.VS.features.category:SetListIndex(driftgod.S.vehicleSpawnerCategoryIndex or 0) end end)
    driftgod.Try(function() if driftgod.VS.features.vehicle then driftgod.VS.features.vehicle:SetList(driftgod.VS.runtime.names or { "No saved vehicles scanned yet" }); driftgod.VS.features.vehicle:SetListIndex(driftgod.S.vehicleSpawnerIndex or 0) end end)
    driftgod.Try(function() if driftgod.VS.features.openToggle then driftgod.VS.features.openToggle:SetBoolValue(driftgod.VS.runtime.open == true) end end)
end

function driftgod.VS_Selected()
    driftgod.VS_Rebuild()
    return (driftgod.VS.runtime.filtered or {})[(driftgod.S.vehicleSpawnerIndex or 0) + 1]
end

function driftgod.VS_LoadItem(item)
    if not item then driftgod.VS_Warn("No saved vehicle selected."); return false end
    if item.isRandom then
        driftgod.VS._pool = {}
        for _, candidate in ipairs(driftgod.VS.runtime.items or {}) do
            if item.randomTargetCategory == "All" or tostring(candidate.category or "Root"):lower() == tostring(item.randomTargetCategory or ""):lower() then driftgod.VS._pool[#driftgod.VS._pool + 1] = candidate end
        end
        if #driftgod.VS._pool <= 0 then driftgod.VS_Warn("No vehicles available for Random."); return false end
        item = driftgod.VS._pool[math.random(1, #driftgod.VS._pool)]
    end
    if item.isFolder then
        driftgod.VS.runtime.currentFolder = item.folderTarget or item.category
        driftgod.S.vehicleSpawnerIndex = 0
        driftgod.VS.hud.scroll = 0
        driftgod.VS_Rebuild()
        return true
    end
    driftgod.VS._indexToLoad = item.cheraxListIndex
    if driftgod.VS._indexToLoad == nil and tostring(item.path or ""):lower():match("%.json$") then
        driftgod.VS._jsons = {}
        for _, root in ipairs(driftgod.VS_Roots()) do for _, f in ipairs(driftgod.VS_FindFiles(root, { "json" })) do driftgod.VS._jsons[#driftgod.VS._jsons + 1] = f end end
        table.sort(driftgod.VS._jsons, function(a,b) return tostring(a):lower() < tostring(b):lower() end)
        driftgod.VS._want = driftgod.VS_Normalize(item.path):lower()
        for i, f in ipairs(driftgod.VS._jsons) do if driftgod.VS_Normalize(f):lower() == driftgod.VS._want then driftgod.VS._indexToLoad = i - 1; break end end
    end
    if driftgod.VS._indexToLoad == nil then driftgod.VS_Warn("Could not map saved vehicle to Cherax Saved Vehicles list."); return false end
    driftgod.VS._listHash = item.cheraxListHash or 514776905
    driftgod.Try(function() FeatureMgr.SetFeatureListIndex(driftgod.VS._listHash, driftgod.VS._indexToLoad) end)
    driftgod.VS._loadFeature = nil
    driftgod.Try(function() driftgod.VS._loadFeature = FeatureMgr.GetFeatureByName(driftgod.VS.LoadVehicleFeatureName) end)
    if driftgod.VS._loadFeature and driftgod.VS._loadFeature.TriggerCallback then
        driftgod.VS._okLoad = driftgod.Try(function() driftgod.VS._loadFeature:TriggerCallback() end)
        if driftgod.VS._okLoad then
            driftgod.VS.runtime.lastSpawnedName = tostring(item.displayLabel or item.name or "Saved Vehicle")
            driftgod.VS.runtime.lastSpawnedModel = "Cherax Saved Vehicle"
            driftgod.VS.runtime.lastSpawnedHandle = 0
            driftgod.VS.runtime.spawnCount = (driftgod.VS.runtime.spawnCount or 0) + 1
            driftgod.VS_Log("Loaded " .. driftgod.VS.runtime.lastSpawnedName)
            driftgod.VS_Toast("Loaded " .. driftgod.VS.runtime.lastSpawnedName, 2500)
            return true
        end
    end
    driftgod.VS_Warn("Cherax Load Vehicle feature was not found or failed.")
    return false
end

function driftgod.VS_LoadSelected()
    return driftgod.VS_LoadItem(driftgod.VS_Selected())
end

function driftgod.VS_QueueSelected()
    driftgod.VS.runtime.pending = { item = driftgod.VS_Selected(), at = driftgod.VS_Now() }
    if driftgod.VS.runtime.pending.item then driftgod.VS.runtime.lastStatus = "Queued " .. tostring(driftgod.VS.runtime.pending.item.displayLabel or driftgod.VS.runtime.pending.item.name or "vehicle") end
end

function driftgod.VS_ProcessPending()
    if not driftgod.VS.runtime.pending then return end
    if (driftgod.VS_Now() - (driftgod.VS.runtime.pending.at or 0)) < 50 then return end
    driftgod.VS._pending = driftgod.VS.runtime.pending
    driftgod.VS.runtime.pending = nil
    driftgod.VS_LoadItem(driftgod.VS._pending.item)
end

function driftgod.VS_SetOpen(state)
    driftgod.VS_EnsureDefaults()
    driftgod.VS.runtime.open = state == true
    if driftgod.VS.runtime.open and #(driftgod.VS.runtime.items or {}) == 0 then driftgod.VS_Refresh() end
    if driftgod.VS.runtime.open then
        driftgod.VS.runtime.currentFolder = nil
        driftgod.VS.hud.scroll = 0
        driftgod.VS.hud.inputLockUntil = driftgod.VS_Now() + 220
        driftgod.VS.hud.lastKeys = {}
        driftgod.VS_Rebuild()
        driftgod.VS_PlaySound("SELECT")
    else
        driftgod.VS_PlaySound("BACK")
        driftgod.VS.hud.lastKeys = {}
        driftgod.VS.runtime.currentFolder = nil
        driftgod.VS_Rebuild()
    end
    driftgod.VS_SyncFeatures()
end

function driftgod.VS_ToggleOpen()
    driftgod.VS_SetOpen(not (driftgod.VS.runtime.open == true))
end

function driftgod.VS_KeyPressed(vk)
    if not Utils or not Utils.IsKeyPressed then return false end
    driftgod.VS._okKey, driftgod.VS._pressed = driftgod.Try(Utils.IsKeyPressed, vk)
    driftgod.VS._pressed = driftgod.VS._okKey and driftgod.VS._pressed == true
    driftgod.VS._was = driftgod.VS.hud.lastKeys[vk] == true
    driftgod.VS.hud.lastKeys[vk] = driftgod.VS._pressed
    return driftgod.VS._pressed and not driftgod.VS._was
end

function driftgod.VS_PlaySound(name)
    driftgod.Try(function() Natives.InvokeVoid(0xCADA5A0D0702381E, name or "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET") end)
end

function driftgod.VS_BlockControls()
    driftgod.VS._controls = { 27, 176, 177, 178, 179, 199, 200, 201, 202, 172, 173, 174, 175, 24, 25, 69, 70, 92, 106, 114, 140, 141, 142, 257, 263, 264 }
    for _, control in ipairs(driftgod.VS._controls) do driftgod.Try(function() Natives.InvokeVoid(0xFE99B66D079CF6BC, 0, control, true) end) end
    driftgod.Try(function() Natives.InvokeVoid(0xEDE476E5EE29EDB1, 0, 172) end)
    driftgod.Try(function() Natives.InvokeVoid(0xEDE476E5EE29EDB1, 0, 173) end)
    driftgod.Try(function() Natives.InvokeVoid(0xEDE476E5EE29EDB1, 0, 174) end)
    driftgod.Try(function() Natives.InvokeVoid(0xEDE476E5EE29EDB1, 0, 175) end)
end

function driftgod.VS_HandleInput()
    if driftgod.VS_Now() < (driftgod.VS.hud.inputLockUntil or 0) then return end
    driftgod.VS._count2 = #(driftgod.VS.runtime.filtered or {})
    if driftgod.VS_KeyPressed(driftgod.VS.Keys.F5) then driftgod.VS_Refresh(); driftgod.VS_PlaySound("SELECT") end
    if driftgod.VS._count2 <= 0 then
        if driftgod.VS_KeyPressed(driftgod.VS.Keys.DELETE) or driftgod.VS_KeyPressed(driftgod.VS.Keys.LEFT) then driftgod.VS_SetOpen(false) end
        return
    end
    if driftgod.VS_KeyPressed(driftgod.VS.Keys.UP) then
        driftgod.S.vehicleSpawnerIndex = (driftgod.S.vehicleSpawnerIndex or 0) - 1
        if driftgod.S.vehicleSpawnerIndex < 0 then driftgod.S.vehicleSpawnerIndex = driftgod.VS._count2 - 1 end
        driftgod.VS_NormalizeSelection(); driftgod.VS_PlaySound("NAV_UP_DOWN")
    elseif driftgod.VS_KeyPressed(driftgod.VS.Keys.DOWN) then
        driftgod.S.vehicleSpawnerIndex = (driftgod.S.vehicleSpawnerIndex or 0) + 1
        if driftgod.S.vehicleSpawnerIndex >= driftgod.VS._count2 then driftgod.S.vehicleSpawnerIndex = 0 end
        driftgod.VS_NormalizeSelection(); driftgod.VS_PlaySound("NAV_UP_DOWN")
    elseif driftgod.VS_KeyPressed(driftgod.VS.Keys.ENTER) or driftgod.VS_KeyPressed(driftgod.VS.Keys.RIGHT) then
        driftgod.VS_QueueSelected(); driftgod.VS_PlaySound("SELECT")
    elseif driftgod.VS_KeyPressed(driftgod.VS.Keys.DELETE) or driftgod.VS_KeyPressed(driftgod.VS.Keys.LEFT) then
        if driftgod.VS.runtime.currentFolder then driftgod.VS.runtime.currentFolder = nil; driftgod.S.vehicleSpawnerIndex = 0; driftgod.VS.hud.scroll = 0; driftgod.VS_Rebuild(); driftgod.VS_PlaySound("BACK") else driftgod.VS_SetOpen(false) end
    end
end

function driftgod.VS_DrawRect(x, y, w, h, r, g, b, a)
    driftgod.Try(function() Natives.InvokeVoid(0x61BB1D9B3A95D802, 7) end)
    driftgod.Try(function() Natives.InvokeVoid(0xC6372ECD45D73BCD, true) end)
    driftgod.Try(function() Natives.InvokeVoid(0x3A618A217E5154F0, x, y, w, h, r, g, b, a, 0) end)
end

function driftgod.VS_Text(text, x, y, scale, r, g, b, a, justify, wrapLeft, wrapRight, maxChars)
    text = tostring(text or "")
    maxChars = tonumber(maxChars or 44) or 44
    if maxChars > 0 and #text > maxChars then text = text:sub(1, math.max(1, maxChars - 3)) .. "..." end
    driftgod.Try(function() Natives.InvokeVoid(0x66E0276CC5F6B9DA, 4) end)
    driftgod.Try(function() Natives.InvokeVoid(0x07C837F9A01C34C9, 0.0, scale or 0.225) end)
    driftgod.Try(function() Natives.InvokeVoid(0xBE6B23FFA53FB442, r or 255, g or 255, b or 255, a or 255) end)
    driftgod.Try(function() Natives.InvokeVoid(0x63145D9C883A1A70, wrapLeft or 0.0, wrapRight or 1.0) end)
    driftgod.Try(function() Natives.InvokeVoid(0xC02F4DBFB51D988B, justify == 0) end)
    if justify == 2 then driftgod.Try(function() Natives.InvokeVoid(0x6B3C4650BC8BEE47, true) end) end
    driftgod.Try(function() Natives.InvokeVoid(0x4E096588B13FFECA, justify or 1) end)
    driftgod.Try(function() Natives.InvokeVoid(0x2513DFB0FB8400FE) end)
    driftgod.Try(function() Natives.InvokeVoid(0x25FBB336DF1804CB, "STRING") end)
    driftgod.Try(function() Natives.InvokeVoid(0x6C188BE134E074AA, text) end)
    driftgod.Try(function() Natives.InvokeVoid(0xCD015E5BB0D96A57, x, y, 0) end)
end

function driftgod.VS_RenderHud()
    if driftgod.VS.runtime.open ~= true then return end
    driftgod.VS_BlockControls()
    driftgod.VS_HandleInput()
    driftgod.VS_Rebuild()
    driftgod.VS._x = tonumber(driftgod.S.vehicleSpawnerHudX or 0.085) or 0.085
    driftgod.VS._y = tonumber(driftgod.S.vehicleSpawnerHudY or 0.560) or 0.560
    driftgod.VS._width = tonumber(driftgod.S.vehicleSpawnerHudWidth or 0.128) or 0.128
    driftgod.VS._opacity = tonumber(driftgod.S.vehicleSpawnerHudOpacity or 0.50) or 0.50
    if driftgod.VS._opacity < 0.10 then driftgod.VS._opacity = 0.10 elseif driftgod.VS._opacity > 1.0 then driftgod.VS._opacity = 1.0 end
    driftgod.VS._rows = 6
    driftgod.VS._rowH = 0.026
    driftgod.VS._headerH = 0.040
    driftgod.VS._subH = 0.024
    driftgod.VS._footerH = 0.024
    driftgod.VS._height = driftgod.VS._headerH + driftgod.VS._subH + (driftgod.VS._rows * driftgod.VS._rowH) + driftgod.VS._footerH
    driftgod.VS._panelAlpha = math.floor(220 * driftgod.VS._opacity)
    driftgod.VS._headerAlpha = math.floor(240 * driftgod.VS._opacity)
    driftgod.VS._rowAlpha = math.floor(205 * driftgod.VS._opacity)
    driftgod.VS._selectedAlpha = math.floor(220 * driftgod.VS._opacity)
    driftgod.VS._footerAlpha = math.floor(235 * driftgod.VS._opacity)
    driftgod.VS._glowAlpha = math.floor(85 * driftgod.VS._opacity)
    driftgod.VS._left = driftgod.VS._x - driftgod.VS._width / 2
    driftgod.VS._right = driftgod.VS._x + driftgod.VS._width / 2
    driftgod.VS_DrawRect(driftgod.VS._x, driftgod.VS._y + driftgod.VS._height / 2, driftgod.VS._width + 0.006, driftgod.VS._height + 0.006, 150, 45, 255, driftgod.VS._glowAlpha)
    driftgod.VS_DrawRect(driftgod.VS._x, driftgod.VS._y + driftgod.VS._height / 2, driftgod.VS._width, driftgod.VS._height, 5, 5, 11, driftgod.VS._panelAlpha)
    driftgod.VS_DrawRect(driftgod.VS._x, driftgod.VS._y + driftgod.VS._headerH / 2, driftgod.VS._width, driftgod.VS._headerH, 80, 0, 125, driftgod.VS._headerAlpha)
    driftgod.VS_DrawRect(driftgod.VS._x, driftgod.VS._y + driftgod.VS._headerH + driftgod.VS._subH / 2, driftgod.VS._width, driftgod.VS._subH, 0, 0, 0, driftgod.VS._panelAlpha)
    driftgod.VS_Text("DRIFTGOD GARAGE", driftgod.VS._x, driftgod.VS._y + 0.006, 0.245, 255, 255, 255, 255, 0)
    driftgod.VS._folderLabel = driftgod.VS.runtime.currentFolder and ("/" .. tostring(driftgod.VS.runtime.currentFolder)) or "Root"
    if driftgod.VS.runtime.currentFolder then
        driftgod.VS_Text("[ " .. driftgod.VS._folderLabel .. " ]", driftgod.VS._left + 0.009, driftgod.VS._y + driftgod.VS._headerH + 0.003, 0.210, 90, 255, 120, 255, 1)
    else
        driftgod.VS_Text("[ Root ]", driftgod.VS._left + 0.009, driftgod.VS._y + driftgod.VS._headerH + 0.003, 0.210, 255, 255, 255, 255, 1)
    end
    driftgod.VS._filtered = driftgod.VS.runtime.filtered or {}
    if #driftgod.VS._filtered <= 0 then
        driftgod.VS_Text("No vehicles loaded", driftgod.VS._left + 0.010, driftgod.VS._y + driftgod.VS._headerH + driftgod.VS._subH + 0.010, 0.255, 255, 120, 120, 240, 1)
    else
        for i = 1, driftgod.VS._rows do
            driftgod.VS._itemIndex = (driftgod.VS.hud.scroll or 0) + i
            driftgod.VS._item = driftgod.VS._filtered[driftgod.VS._itemIndex]
            driftgod.VS._rowY = driftgod.VS._y + driftgod.VS._headerH + driftgod.VS._subH + ((i - 0.5) * driftgod.VS._rowH)
            if driftgod.VS._item then
                driftgod.VS._selected = (driftgod.VS._itemIndex - 1) == (driftgod.S.vehicleSpawnerIndex or 0)
                if driftgod.VS._selected then driftgod.VS_DrawRect(driftgod.VS._x, driftgod.VS._rowY, driftgod.VS._width - 0.010, driftgod.VS._rowH - 0.002, 115, 45, 255, driftgod.VS._selectedAlpha)
                else driftgod.VS_DrawRect(driftgod.VS._x, driftgod.VS._rowY, driftgod.VS._width - 0.010, driftgod.VS._rowH - 0.002, 9, 7, 16, driftgod.VS._rowAlpha) end
                driftgod.VS._label = tostring(driftgod.VS._item.displayLabel or driftgod.VS._item.name or "Vehicle")
                if driftgod.VS._item.isRandom then driftgod.VS_Text(driftgod.VS._label, driftgod.VS._left + 0.009, driftgod.VS._rowY - 0.010, 0.218, 255, 70, 130, 255, 1, driftgod.VS._left + 0.006, driftgod.VS._right - 0.022, 44)
                elseif driftgod.VS._item.isFolder then driftgod.VS_Text(driftgod.VS._label, driftgod.VS._left + 0.009, driftgod.VS._rowY - 0.010, 0.218, 90, 255, 120, 255, 1, driftgod.VS._left + 0.006, driftgod.VS._right - 0.022, 44)
                else driftgod.VS_Text(driftgod.VS._label, driftgod.VS._left + 0.009, driftgod.VS._rowY - 0.010, 0.218, 245, 245, 255, 245, 1, driftgod.VS._left + 0.006, driftgod.VS._right - 0.022, 44) end
                if driftgod.VS._selected then driftgod.VS_Text("›", driftgod.VS._right - 0.010, driftgod.VS._rowY - 0.010, 0.230, 255, 255, 255, 245, 2) end
            end
        end
    end
    driftgod.VS._footerY = driftgod.VS._y + driftgod.VS._height - driftgod.VS._footerH / 2
    driftgod.VS_DrawRect(driftgod.VS._x, driftgod.VS._footerY, driftgod.VS._width, driftgod.VS._footerH, 35, 0, 55, driftgod.VS._footerAlpha)
    driftgod.VS_Text(driftgod.VS.runtime.currentFolder and "ENTER | DEL BACK" or "ENTER | DEL CLOSE", driftgod.VS._x, driftgod.VS._footerY - 0.009, 0.176, 220, 220, 235, 235, 0)
end

function driftgod.VS_Tick()
    driftgod.VS_EnsureDefaults()
    if driftgod.S.vehicleSpawnerHotkeyInsert ~= false and driftgod.VS_KeyPressed(driftgod.VS.Keys.INSERT) then driftgod.VS_ToggleOpen() end

    driftgod.VS_RenderHud()
end

function driftgod.VS_ApplyHudPreset(index, silent)
    driftgod.VS_EnsureDefaults()
    index = driftgod.VS_Clamp(index or 0, 0, #driftgod.VS.HudPresets - 1)
    driftgod.S.vehicleSpawnerHudPresetIndex = index
    driftgod.VS._preset = driftgod.VS.HudPresets[index + 1] or driftgod.VS.HudPresets[1]
    driftgod.S.vehicleSpawnerHudX = driftgod.VS._preset.x
    driftgod.S.vehicleSpawnerHudY = driftgod.VS._preset.y
    if silent ~= true then driftgod.VS_Log("HUD preset: " .. tostring(driftgod.VS._preset.name)) end
    if driftgod.SaveSettings then driftgod.SaveSettings(false) end
end

function driftgod.VS_PrintStatus()
    driftgod.VS_Log("Status | scanned=" .. tostring(#(driftgod.VS.runtime.items or {})) .. " | selected=" .. tostring(((driftgod.VS_Selected() or {}).displayLabel) or "None") .. " | last=" .. tostring(driftgod.VS.runtime.lastSpawnedName or "None"))
end

function driftgod.VS_InstallWorker()
    if driftgod.VS.runtime.workerInstalled == true then return end
    driftgod.VS.runtime.workerInstalled = true
    if not Script or not Script.RegisterLooped then
        driftgod.VS_Warn("Script.RegisterLooped unavailable; saved vehicle queue worker not installed.")
        return
    end
    Script.RegisterLooped(function()
        if ShouldUnload and ShouldUnload() then return false end
        if driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.pending then
            driftgod.VS_ProcessPending()
            if Script and Script.Yield then Script.Yield(0) end
        else
            if Script and Script.Yield then Script.Yield(100) end
        end
    end)
end

function driftgod.VS_RegisterFeatures()
    if driftgod.VS.features then return end
    driftgod.VS_EnsureDefaults()
    driftgod.VS_InstallWorker()
    driftgod.VS.features = {}
    driftgod.H.VehicleSpawnerRuntime = driftgod.Hash("VehicleSpawnerRuntime")
    driftgod.VS.features.runtime = driftgod.SafeAddFeature(driftgod.H.VehicleSpawnerRuntime, "DriftGod Garage Runtime", eFeatureType.Toggle, "Runtime tick for DriftGod Garage HUD.", function(f) if f and f.IsToggled and not f:IsToggled() then return end; if driftgod.VS_Tick then driftgod.VS_Tick() end end, true)
    driftgod.Try(function() driftgod.VS.features.runtime:RegisterCallbackTrigger(eCallbackTrigger.OnTick) end)
    driftgod.Try(function() driftgod.VS.features.runtime:SetDefaultValue(true):Reset() end)

    driftgod.H.VehicleSpawnerHotkeyInsert = driftgod.Hash("VehicleSpawnerHotkeyInsert")
    driftgod.VS.features.hotkey = driftgod.SafeAddFeature(driftgod.H.VehicleSpawnerHotkeyInsert, "Garage HUD Hotkey", eFeatureType.Toggle, "No default key is assigned. Recommended hotkey: Insert. Use this only if you manually want Insert to open/close the DriftGod Garage HUD.", function(f) driftgod.S.vehicleSpawnerHotkeyInsert = f:IsToggled(); if driftgod.SaveSettings then driftgod.SaveSettings(false) end end)
    driftgod.Try(function() driftgod.VS.features.hotkey:SetDefaultValue(driftgod.S.vehicleSpawnerHotkeyInsert == true):Reset() end)

    driftgod.H.VehicleSpawnerOpen = driftgod.Hash("VehicleSpawnerOpen")
    driftgod.VS.features.openToggle = driftgod.SafeAddFeature(driftgod.H.VehicleSpawnerOpen, "Open DriftGod Garage HUD", eFeatureType.Toggle, "Keyboard HUD: arrows, Enter, Delete, F5. Recommended manual hotkey: Insert.", function(f) driftgod.VS_SetOpen(f:IsToggled()) end)

    driftgod.H.VehicleSpawnerScan = driftgod.Hash("VehicleSpawnerScan")
    driftgod.VS.features.scan = driftgod.SafeAddFeature(driftgod.H.VehicleSpawnerScan, "Scan Cherax Vehicles", eFeatureType.Button, "Scans Documents\\Cherax\\Vehicles and Cherax saved vehicle list.", function() driftgod.VS_Refresh() end)

    driftgod.H.VehicleSpawnerSpawnSaved = driftgod.Hash("VehicleSpawnerSpawnSaved")
    driftgod.VS.features.spawn = driftgod.SafeAddFeature(driftgod.H.VehicleSpawnerSpawnSaved, "Spawn Selected Saved Vehicle", eFeatureType.Button, "Queues selected saved vehicle through Cherax Load Vehicle. Safe worker prevents UI-yield errors.", function() driftgod.VS_QueueSelected() end)

    driftgod.H.VehicleSpawnerCategory = driftgod.Hash("VehicleSpawnerCategory")
    driftgod.VS.features.category = driftgod.SafeAddFeature(driftgod.H.VehicleSpawnerCategory, "Saved Vehicle Category", eFeatureType.Combo, "Category/folder under Cherax Vehicles.", function(f) driftgod.S.vehicleSpawnerCategoryIndex = driftgod.VS_Clamp(f:GetListIndex(), 0, math.max(0, #(driftgod.VS.runtime.categories or {}) - 1)); driftgod.S.vehicleSpawnerIndex = 0; driftgod.VS_Rebuild(); if driftgod.SaveSettings then driftgod.SaveSettings(false) end end)

    driftgod.H.VehicleSpawnerVehicle = driftgod.Hash("VehicleSpawnerVehicle")
    driftgod.VS.features.vehicle = driftgod.SafeAddFeature(driftgod.H.VehicleSpawnerVehicle, "Saved Vehicle", eFeatureType.Combo, "Selected saved vehicle.", function(f) driftgod.S.vehicleSpawnerIndex = driftgod.VS_Clamp(f:GetListIndex(), 0, math.max(0, #(driftgod.VS.runtime.filtered or {}) - 1)); if driftgod.SaveSettings then driftgod.SaveSettings(false) end end)

    driftgod.H.VehicleSpawnerHudPreset = driftgod.Hash("VehicleSpawnerHudPreset")
    driftgod.VS.features.hudPreset = driftgod.SafeAddFeature(driftgod.H.VehicleSpawnerHudPreset, "HUD Position", eFeatureType.Combo, "Quick position for the DriftGod Garage HUD.", function(f) driftgod.VS_ApplyHudPreset(f:GetListIndex(), false) end)
    driftgod.Try(function() driftgod.VS.features.hudPreset:SetList(driftgod.VS.HudPresetNames); driftgod.VS.features.hudPreset:SetListIndex(driftgod.S.vehicleSpawnerHudPresetIndex or 0) end)

    driftgod.H.VehicleSpawnerClose = driftgod.Hash("VehicleSpawnerClose")
    driftgod.VS.features.close = driftgod.SafeAddFeature(driftgod.H.VehicleSpawnerClose, "Close Garage HUD", eFeatureType.Button, "Closes the DriftGod Garage HUD.", function() driftgod.VS_SetOpen(false) end)

    driftgod.H.VehicleSpawnerStatus = driftgod.Hash("VehicleSpawnerStatus")
    driftgod.VS.features.status = driftgod.SafeAddFeature(driftgod.H.VehicleSpawnerStatus, "Print Garage Status", eFeatureType.Button, "Logs DriftGod Garage saved vehicle browser status.", function() driftgod.VS_PrintStatus() end)

    driftgod.VS_SyncFeatures()
    driftgod.Try(function() driftgod.VS_Refresh() end)
end

