    local superUnlocked = (tonumber(best or 0) or 0) >= 25000
    local col = dgMiniBeginColumns("DG_GarageColumns_A99", 2)
    dgMiniColumn(0)
    if ClickGUI.BeginCustomChildWindow("Vehicles") then
        dgMiniText("Spawn", "header")
