        dgMiniText("Official DriftGod vehicles stay here.", "dim")
        ClickGUI.EndCustomChildWindow()
    end
    dgMiniColumn(1)
    if ClickGUI.BeginCustomChildWindow("Vehicle Gates") then
        dgMiniTable("DG_GarageVehicleGateTable_A99", {
            {"Torero XO", superUnlocked and "Permanent" or ((tonumber(best or 0) or 0) < 5000 and "Trial" or "Locked"), "white", superUnlocked and "green" or ((tonumber(best or 0) or 0) < 5000 and "next" or "locked")},
            {"Zentorno", superUnlocked and "Permanent" or ((tonumber(best or 0) or 0) < 10000 and "Trial" or "Locked"), "white", superUnlocked and "green" or ((tonumber(best or 0) or 0) < 10000 and "next" or "locked")},
            {"Super", superUnlocked and "Unlocked" or (dgA38Num(math.max(0, 25000 - (tonumber(best or 0) or 0))) .. " left"), "white", superUnlocked and "green" or "cyan"},
        })
