function driftgod.R101_SetFeatureToggle(hash, state)
    if not hash or not FeatureMgr or not FeatureMgr.GetFeature then return false end
    local ok, feat = driftgod.Try(function() return FeatureMgr.GetFeature(hash) end)
    if not ok or not feat then return false end
    driftgod.Try(function() if feat.SetDefaultValue then feat:SetDefaultValue(state == true) end end)
    local current = nil
    driftgod.Try(function() if feat.IsToggled then current = feat:IsToggled() end end)
    if current ~= nil and current ~= (state == true) then driftgod.Try(function() if feat.Toggle then feat:Toggle() end end) end
    driftgod.Try(function() if feat.SetToggle then feat:SetToggle(state == true) end end)
    driftgod.Try(function() if feat.SetToggled then feat:SetToggled(state == true) end end)
    return true
end

function driftgod.R101_ForceAlwaysOn()
    driftgod.S = driftgod.S or {}
    driftgod.S.vehicleSectorUnlocksEnabled = true
    driftgod.S.progressMilestonesEnabled = true
    if driftgod.H then
        driftgod.R101_SetFeatureToggle(driftgod.H.VehicleSectorUnlocksToggle, true)
        driftgod.R101_SetFeatureToggle(driftgod.H.ProgressMilestonesToggle, true)
    end
end
driftgod.R101_ForceAlwaysOn()

function driftgod.R101_TriggerFeature(hash)
    if not hash or not FeatureMgr or not FeatureMgr.GetFeature then return false end
    local ok, feat = driftgod.Try(function() return FeatureMgr.GetFeature(hash) end)
    if not ok or not feat then return false end
    local done = false
    driftgod.Try(function() if feat.TriggerCallback then feat:TriggerCallback(); done = true end end)
    if done then return true end
    driftgod.Try(function() if feat.Trigger then feat:Trigger(); done = true end end)
    if done then return true end
    driftgod.Try(function() if feat.OnClick then feat:OnClick(); done = true end end)
    return done
end

function driftgod.R101_PushButtonColor(kind)
    if not (ImGui and ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Button) then return 0 end
    local r, g, b = 0.18, 0.18, 0.22
    local hr, hg, hb = 0.26, 0.26, 0.32
    local ar, ag, ab = 0.32, 0.32, 0.38
    if kind == "red" then r,g,b = 0.45,0.06,0.08; hr,hg,hb = 0.62,0.10,0.12; ar,ag,ab = 0.78,0.14,0.16 end
    if kind == "green" then r,g,b = 0.06,0.35,0.14; hr,hg,hb = 0.08,0.48,0.20; ar,ag,ab = 0.10,0.62,0.26 end
    if kind == "blue" then r,g,b = 0.06,0.20,0.50; hr,hg,hb = 0.09,0.30,0.68; ar,ag,ab = 0.12,0.38,0.85 end
    driftgod.Try(function()
        ImGui.PushStyleColor(ImGuiCol.Button, r,g,b, 0.92)
        ImGui.PushStyleColor(ImGuiCol.ButtonHovered, hr,hg,hb, 0.98)
        ImGui.PushStyleColor(ImGuiCol.ButtonActive, ar,ag,ab, 1.00)
    end)
    return 3
end

function driftgod.R101_ColorButton(label, kind, cb)
    local pushed = driftgod.R101_PushButtonColor(kind)
    local clicked = false
    if ImGui and ImGui.Button then clicked = ImGui.Button(tostring(label or "Button")) == true end
    if pushed > 0 and ImGui and ImGui.PopStyleColor then driftgod.Try(ImGui.PopStyleColor, pushed) end
    if clicked and cb then driftgod.Try(cb) end
    return clicked
end

function driftgod.R101_RegisterHudTargetFeature()
    if driftgod.R101HudTargetRegistered == true then return end
    driftgod.R101HudTargetRegistered = true
    driftgod.H = driftgod.H or {}
    driftgod.H.SettingsHudTarget = driftgod.Hash("SettingsHudTarget")
    if FeatureMgr and FeatureMgr.AddFeature then
        local ok, f = driftgod.Try(function()
            return driftgod.SafeAddFeature(driftgod.H.SettingsHudTarget, "HUD Position", eFeatureType.Combo, "Choose which HUD controls to show in Settings.", function(feat)
                driftgod.S.settingsHudTargetIndex = feat:GetListIndex()
                if driftgod.SaveSettings then driftgod.SaveSettings(false) end
            end)
        end)
        if ok and f then
            driftgod.R101HudTargetFeature = f
            driftgod.Try(function() f:SetList({"Score HUD", "MPH HUD", "Visualizer", "Stunt Menu", "Garage HUD"}) end)
            driftgod.Try(function() f:SetListIndex(driftgod.S.settingsHudTargetIndex or 0) end)
        end
    end
end

function driftgod.R101_RenderInputVisualizerSettings()
    if ClickGUI.BeginCustomChildWindow("Visualizer HUD") then
