        ImGui.Text("Current X/Y: " .. string.format("%.3f", driftgod.S.inputHudX or 0.190) .. " / " .. string.format("%.3f", driftgod.S.inputHudY or 0.805))
        ImGui.Text("Scale: " .. string.format("%.2f", driftgod.S.inputHudScale or 0.50))
        if ImGui.Button("Visualizer: Default") then
            driftgod.S.inputHudX, driftgod.S.inputHudY, driftgod.S.inputHudScale = 0.190, 0.805, 0.50
            if driftgod.SaveSettings then driftgod.SaveSettings(false) end
            if driftgod.Toast then driftgod.Toast("Visualizer HUD reset.", 1500) end
        end
        ImGui.Text("Move")
        if ImGui.Button("X-##VisualizerXMinus") then moveInput(-0.01, 0) end
        ImGui.SameLine()
        if ImGui.Button("X+##VisualizerXPlus") then moveInput(0.01, 0) end
        if ImGui.Button("Y-##VisualizerYMinus") then moveInput(0, -0.01) end
        ImGui.SameLine()
        if ImGui.Button("Y+##VisualizerYPlus") then moveInput(0, 0.01) end
        ImGui.Text("Fine Move")
        if ImGui.Button("X-##VisualizerFineXMinus") then moveInput(-0.005, 0) end
        ImGui.SameLine()
        if ImGui.Button("X+##VisualizerFineXPlus") then moveInput(0.005, 0) end
        if ImGui.Button("Y-##VisualizerFineYMinus") then moveInput(0, -0.005) end
        ImGui.SameLine()
        if ImGui.Button("Y+##VisualizerFineYPlus") then moveInput(0, 0.005) end
        ImGui.Text("Scale")
        if ImGui.Button("Visualizer Scale -") then driftgod.S.inputHudScale = cfloat((driftgod.S.inputHudScale or 0.50) - 0.10, 0.30, 2.00); if driftgod.SaveSettings then driftgod.SaveSettings(false) end end
        ImGui.SameLine()
        if ImGui.Button("Visualizer Scale +") then driftgod.S.inputHudScale = cfloat((driftgod.S.inputHudScale or 0.50) + 0.10, 0.30, 2.00); if driftgod.SaveSettings then driftgod.SaveSettings(false) end end
        ClickGUI.EndCustomChildWindow()
    end
end

