        ClickGUI.EndCustomChildWindow()
    end
    local idx = tonumber(driftgod.S.settingsHudTargetIndex or 0) or 0
    if idx == 0 then renderScoreHudSettingsFinal()
    elseif idx == 1 then renderMphSettings()
