function driftgod.GetNextStuntTierRequirementText(stuntName)
    local earnedTier = driftgod.GetEarnedStuntTier and driftgod.GetEarnedStuntTier(stuntName) or 1
    if earnedTier >= 3 then return "Max" end
    local targetTier = earnedTier + 1
    local scoreReq = driftgod.GetStuntTierRequirement and driftgod.GetStuntTierRequirement(stuntName, targetTier) or 0
    local useCount = driftgod.GetFreshTierUseCount and driftgod.GetFreshTierUseCount(stuntName, targetTier) or 0
    local useReq = driftgod.GetStuntTierUseRequirement and driftgod.GetStuntTierUseRequirement(targetTier) or 0
    return "T" .. tostring(targetTier) .. ": " .. tostring(scoreReq) .. " pts | " .. tostring(useCount) .. "/" .. tostring(useReq)
end

dgPresetTipText = function(p, maxChars)
