driftgod.R102_StuntHudPresets = driftgod.R102_StuntHudPresets or {
    { name = "Bottom Left",  x = 0.085, y = 0.560 },
    { name = "Top Left",     x = 0.085, y = 0.080 },
    { name = "Top Right",    x = 0.915, y = 0.080 },
    { name = "Bottom Right", x = 0.915, y = 0.560 },
    { name = "Center Left",  x = 0.085, y = 0.330 },
}
driftgod.R102_StuntHudPresetNames = driftgod.R102_StuntHudPresetNames or { "Bottom Left", "Top Left", "Top Right", "Bottom Right", "Center Left" }

function driftgod.R102_SaveSettingsQuiet()
    if driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
end

function driftgod.R102_GetUnlockScore()
    if driftgod.GetVehicleSectorProgressScore then return tonumber(driftgod.GetVehicleSectorProgressScore() or 0) or 0 end
    return math.max(tonumber(driftgod.S.bestScore or 0) or 0, tonumber(driftgod.S.highestScore or 0) or 0, tonumber(driftgod.S.previousScore or 0) or 0, tonumber(driftgod.S.totalScore or 0) or 0, tonumber(driftgod.S.lifetimeScore or 0) or 0)
end

function driftgod.R102_HeadlightsUnlockScore()
    driftgod.S = driftgod.S or {}
    return tonumber(driftgod.S.headlightsAlwaysUnlockScore or 7500) or 7500
end

function driftgod.R102_IsHeadlightsUnlocked()
    return (driftgod.R102_GetUnlockScore() or 0) >= (driftgod.R102_HeadlightsUnlockScore() or 7500)
end

function driftgod.R158_PlateUnlockScore()
    return 100
end

function driftgod.R158_IsPlateUnlocked()
    return (driftgod.R102_GetUnlockScore and (driftgod.R102_GetUnlockScore() or 0) or 0) >= (driftgod.R158_PlateUnlockScore() or 100)
end

function driftgod.GetDriftGodPlateText()
    return tostring(driftgod.PlateText or "DRIFTGOD"):sub(1, 8)
end

function driftgod.GetVehiclePlateText(vehicle)
    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 then return "" end

    local text = ""
    driftgod.Try(function()
        if VEHICLE and VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT then
            text = tostring(VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT(vehicle) or "")
        end
    end)

    return tostring(text or "")
end

function driftgod.SetVehiclePlateText(vehicle, text)
    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 then return false end

    text = tostring(text or driftgod.GetDriftGodPlateText() or "DRIFTGOD"):sub(1, 8)

    local ok = false
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT then
            VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT(vehicle, text)
            ok = true
        elseif Natives and Natives.InvokeVoid then
            Natives.InvokeVoid(0x95A88F0B409CDA47, vehicle, text)
            ok = true
        end
    end)

    return ok == true
end

function driftgod.CleanPlateText(text)
    return tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

function driftgod.ApplyDriftGodPlate(vehicle)
    driftgod.S = driftgod.S or {}
    if driftgod.S.driftGodPlateEnabled ~= true then return false end
    if driftgod.S.autoPlateEnabled == false or driftgod.S.plateEnabled == false or driftgod.S.customPlateEnabled == false then return false end
    if driftgod.R158_IsPlateUnlocked and driftgod.R158_IsPlateUnlocked() ~= true then return false end

    vehicle = tonumber(vehicle or 0) or 0
    if vehicle == 0 and driftgod.GetVehicle then vehicle = tonumber(driftgod.GetVehicle() or 0) or 0 end
    if vehicle == 0 then return false end

    if tonumber(driftgod.S.driftGodPlateLastVehicle or 0) ~= vehicle then
        driftgod.S.driftGodPlateLastVehicle = vehicle
        local current = driftgod.GetVehiclePlateText(vehicle)
        if driftgod.CleanPlateText(current) ~= driftgod.CleanPlateText(driftgod.GetDriftGodPlateText()) then
            driftgod.S.driftGodPlatePreviousText = current
        end
    end

    return driftgod.SetVehiclePlateText(vehicle, driftgod.GetDriftGodPlateText())
end

function driftgod.RestoreDriftGodPlate(vehicle)
    driftgod.S = driftgod.S or {}

    vehicle = tonumber(vehicle or driftgod.S.driftGodPlateLastVehicle or 0) or 0
    if vehicle == 0 and driftgod.GetVehicle then vehicle = tonumber(driftgod.GetVehicle() or 0) or 0 end

    local previous = tostring(driftgod.S.driftGodPlatePreviousText or "")
    local target = driftgod.CleanPlateText(driftgod.GetDriftGodPlateText())

    if vehicle ~= 0 then
        local current = driftgod.CleanPlateText(driftgod.GetVehiclePlateText(vehicle))
        if driftgod.CleanPlateText(previous) ~= "" and driftgod.CleanPlateText(previous) ~= target then
            driftgod.SetVehiclePlateText(vehicle, previous)
        elseif current == target then
            driftgod.SetVehiclePlateText(vehicle, "        ")
        end
    end

    driftgod.S.driftGodPlateLastVehicle = 0
    driftgod.S.driftGodPlatePreviousText = ""
end

function driftgod.DriftGodPlateTick()
    driftgod.S = driftgod.S or {}
    if driftgod.S.driftGodPlateEnabled ~= true or driftgod.S.autoPlateEnabled == false or driftgod.S.plateEnabled == false or driftgod.S.customPlateEnabled == false then
        if tonumber(driftgod.S.driftGodPlateLastVehicle or 0) ~= 0 then driftgod.RestoreDriftGodPlate() end
        return
    end
    if driftgod.R158_IsPlateUnlocked and driftgod.R158_IsPlateUnlocked() ~= true then return end
    driftgod.ApplyDriftGodPlate()
end

function driftgod.RegisterDriftGodPlateFeature()
    if driftgod.DriftGodPlateRegistered == true then return end
    driftgod.DriftGodPlateRegistered = true

    driftgod.S = driftgod.S or {}
    driftgod.H = driftgod.H or {}
    if driftgod.S.driftGodPlateEnabled == nil then driftgod.S.driftGodPlateEnabled = false end

    driftgod.H.DriftGodPlateToggle = driftgod.Hash("DriftGodPlateToggle")

    if FeatureMgr and FeatureMgr.AddFeature then
        driftgod.Try(function()
            driftgod.DriftGodPlateFeature = driftgod.SafeAddFeature(driftgod.H.DriftGodPlateToggle, "DriftGod Plate", eFeatureType.Toggle, "", function(f)
                local enabled = f:IsToggled() == true
                driftgod.S.driftGodPlateEnabled = enabled
                driftgod.S.autoPlateEnabled = enabled
                driftgod.S.plateEnabled = enabled
                driftgod.S.customPlateEnabled = enabled

                if enabled == true then
                    driftgod.ApplyDriftGodPlate()
                else
                    driftgod.RestoreDriftGodPlate()
                end

                driftgod.R102_SaveSettingsQuiet()
            end, driftgod.S.driftGodPlateEnabled == true)

            if driftgod.DriftGodPlateFeature and driftgod.DriftGodPlateFeature.SetDefaultValue then
                driftgod.DriftGodPlateFeature:SetDefaultValue(driftgod.S.driftGodPlateEnabled == true):Reset()
            end
        end)
    end
end
driftgod.RegisterDriftGodPlateFeature()


function driftgod.R102_SetHeadlightsOn(vehicle)
    if not vehicle or vehicle == 0 then return false end
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_LIGHTS then VEHICLE.SET_VEHICLE_LIGHTS(vehicle, 2) else Natives.InvokeVoid(0x34E710FF01247C5A, vehicle, 2) end
    end)
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_FULLBEAM then VEHICLE.SET_VEHICLE_FULLBEAM(vehicle, true) else Natives.InvokeVoid(0x8B7FD87F0DDB421E, vehicle, true) end
    end)
    return true
end

function driftgod.R102_HeadlightsTick()
    driftgod.S = driftgod.S or {}
    if driftgod.S.headlightsAlwaysEnabled ~= true then return end
    if not driftgod.R102_IsHeadlightsUnlocked() then return end
    if not driftgod.GetVehicle then return end
    driftgod.R102_SetHeadlightsOn(driftgod.GetVehicle())
end

function driftgod.R102_RegisterHeadlightsFeature()
    if driftgod.R102HeadlightsRegistered == true then return end
    driftgod.R102HeadlightsRegistered = true
    driftgod.H = driftgod.H or {}
    driftgod.H.HeadlightsAlwaysToggle = driftgod.Hash("HeadlightsAlwaysToggle")
    if FeatureMgr and FeatureMgr.AddFeature then
        driftgod.Try(function()
            driftgod.R102HeadlightsFeature = driftgod.SafeAddFeature(driftgod.H.HeadlightsAlwaysToggle, "Headlights Always", eFeatureType.Toggle, "Unlocks at 7,500 Best Run. Keeps vehicle headlights on once unlocked.", function(f)
                driftgod.S.headlightsAlwaysEnabled = f:IsToggled()
                driftgod.R102_SaveSettingsQuiet()
            end, driftgod.S.headlightsAlwaysEnabled == true)
            if driftgod.R102HeadlightsFeature and driftgod.R102HeadlightsFeature.SetDefaultValue then driftgod.R102HeadlightsFeature:SetDefaultValue(driftgod.S.headlightsAlwaysEnabled == true):Reset() end
        end)
    end
end
driftgod.R102_RegisterHeadlightsFeature()

if Script and Script.RegisterLooped and not driftgod.R102HeadlightsLoopInstalled then
    driftgod.R102HeadlightsLoopInstalled = true
    Script.RegisterLooped(function()
        if ShouldUnload and ShouldUnload() then return false end
        if driftgod.R102_HeadlightsTick then driftgod.R102_HeadlightsTick() end
        if driftgod.DriftGodPlateTick then driftgod.DriftGodPlateTick() end
        if Script and Script.Yield then Script.Yield(350) end
    end)
end

function driftgod.R102_RegisterStuntHudPositionFeature()
    if driftgod.R102StuntHudPosRegistered == true then return end
    driftgod.R102StuntHudPosRegistered = true
    driftgod.H = driftgod.H or {}
    driftgod.H.StuntHudPreset = driftgod.Hash("StuntHudPreset")
    if FeatureMgr and FeatureMgr.AddFeature then
        driftgod.Try(function()
            driftgod.R102StuntHudPresetFeature = driftgod.SafeAddFeature(driftgod.H.StuntHudPreset, "Stunt HUD Position", eFeatureType.Combo, "Quick position for the DriftGod Stunts / quick menu.", function(f)
                driftgod.R102_ApplyStuntHudPreset(f:GetListIndex())
            end)
            if driftgod.R102StuntHudPresetFeature then
                driftgod.Try(function() driftgod.R102StuntHudPresetFeature:SetList(driftgod.R102_StuntHudPresetNames) end)
                driftgod.Try(function() driftgod.R102StuntHudPresetFeature:SetListIndex(driftgod.S.stuntHudPresetIndex or 0) end)
            end
        end)
    end
end

function driftgod.R102_ApplyStuntHudPreset(index)
    driftgod.S = driftgod.S or {}
    index = math.floor(tonumber(index or 0) or 0)
    if index < 0 then index = 0 end
    if index > (#driftgod.R102_StuntHudPresets - 1) then index = #driftgod.R102_StuntHudPresets - 1 end
    driftgod.S.stuntHudPresetIndex = index
    driftgod.R102_StuntPreset = driftgod.R102_StuntHudPresets[index + 1] or driftgod.R102_StuntHudPresets[1]
    if driftgod.SetStuntQuickMenuPosition then
        driftgod.SetStuntQuickMenuPosition(driftgod.R102_StuntPreset.x, driftgod.R102_StuntPreset.y, true)
    else
        driftgod.S.stuntQuickMenuX = driftgod.R102_StuntPreset.x
        driftgod.S.stuntQuickMenuY = driftgod.R102_StuntPreset.y
        driftgod.S.stuntHudX = driftgod.R102_StuntPreset.x
        driftgod.S.stuntHudY = driftgod.R102_StuntPreset.y
    end
    driftgod.S.stuntHudMoveEnabled = true
    driftgod.R102_SaveSettingsQuiet()
end
driftgod.R102_RegisterStuntHudPositionFeature()

function driftgod.R102_ApplySpawnerTopLeftDefault()
