function driftgod.GetNextStuntTierRequirementText(stuntName)
    driftgod.R102_tier = driftgod.GetEarnedStuntTier and driftgod.GetEarnedStuntTier(stuntName) or 1
    if driftgod.R102_tier >= 3 then return "Max" end
    driftgod.R102_targetTier = driftgod.R102_tier + 1
    driftgod.R102_scoreReq = driftgod.GetStuntTierRequirement and driftgod.GetStuntTierRequirement(stuntName, driftgod.R102_targetTier) or 0
    return "T" .. tostring(driftgod.R102_targetTier) .. ": " .. tostring(driftgod.R102_scoreReq) .. " pts"
end

