function driftgod.R102_RenderPresetButtons(familyName)
    driftgod.R102_score = driftgod.GetArcadeDriftPresetScore and driftgod.GetArcadeDriftPresetScore() or 0
    dgColorText(dgPresetRoadLabel(familyName or "Presets"), "header")
    driftgod.R102_rows = {}
    for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do if p.family == familyName then driftgod.R102_rows[#driftgod.R102_rows+1] = p end end
    if #driftgod.R102_rows <= 0 then dgColorText("No presets in this family yet.", "dim"); return end
    if ImGui.BeginTable("DriftPresetGrid_R102_" .. tostring(familyName):gsub("[^%w]", "_"), 6, dgSafeTableFlags()) then
        if ImGui.TableSetupColumn then
            driftgod.Try(ImGui.TableSetupColumn, "Status", 0, 72)
            driftgod.Try(ImGui.TableSetupColumn, "Preset", 0, 165)
            driftgod.Try(ImGui.TableSetupColumn, "Score", 0, 52)
            driftgod.Try(ImGui.TableSetupColumn, "Left", 0, 52)
            driftgod.Try(ImGui.TableSetupColumn, "Road", 0, 52)
            driftgod.Try(ImGui.TableSetupColumn, "Action", 0, 54)
        end
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0); dgColorText("Status", "header")
        ImGui.TableSetColumnIndex(1); dgColorText("Preset", "header")
        ImGui.TableSetColumnIndex(2); dgColorText("Score", "header")
        ImGui.TableSetColumnIndex(3); dgColorText("Left", "header")
        ImGui.TableSetColumnIndex(4); dgColorText("Road", "header")
        ImGui.TableSetColumnIndex(5); dgColorText("Action", "header")
        for _, p in ipairs(driftgod.R102_rows) do
            driftgod.R102_status, driftgod.R102_color, driftgod.R102_remaining = dgArcadePresetStatus(p, driftgod.R102_score)
            driftgod.R102_need = tonumber(p.unlock or 0) or 0
            driftgod.R102_name = tostring(p.name or "Preset")
            if p.source_name and tostring(p.source_name) ~= "" then driftgod.R102_name = driftgod.R102_name .. " (" .. tostring(p.source_name) .. ")" end
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0); dgTableCell(driftgod.R102_status, driftgod.R102_color)
            ImGui.TableSetColumnIndex(1); dgTableCell(driftgod.R102_name, driftgod.R102_color == "locked" and "locked" or nil)
            ImGui.TableSetColumnIndex(2); dgTableCell(driftgod.R102_need <= 0 and "Starter" or dgFmtNum(driftgod.R102_need))
            ImGui.TableSetColumnIndex(3); dgTableCell((driftgod.R102_remaining and driftgod.R102_remaining > 0) and dgFmtNum(driftgod.R102_remaining) or "--", driftgod.R102_status == "TRIAL" and "next" or nil)
            ImGui.TableSetColumnIndex(4); dgTableCell(dgPresetRoadLabel(p.family or familyName), driftgod.R102_color == "active" and "active" or nil)
            ImGui.TableSetColumnIndex(5); driftgod.R102_RenderPresetApplyButton(p)
        end
        ImGui.EndTable()
    end
    ImGui.Separator()
    for _, p in ipairs(driftgod.R102_rows) do if p.desc and tostring(p.desc) ~= "" then dgColorText(dgPresetTipText(p, 200), "dim") end end
end

