function driftgod.IsDriftHeld()
    if not driftgod.HasNatives or not driftgod.HasNatives() then return false end
    driftgod.R102_c = driftgod.Controls or {}
    return PAD.IS_CONTROL_PRESSED(2, driftgod.R102_c.VEHICLE_DUCK)
        or PAD.IS_DISABLED_CONTROL_PRESSED(2, driftgod.R102_c.VEHICLE_DUCK)
        or PAD.IS_CONTROL_PRESSED(0, driftgod.R102_c.SHIFT)
        or PAD.IS_DISABLED_CONTROL_PRESSED(0, driftgod.R102_c.SHIFT)
end

