driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.__ProductionPatch = "R309_ProductBuild_1_0_0"

    driftgod.S.testAllArcadeDriftPresets = true

    local function R109Text(txt, color)
        if dgMiniText then dgMiniText(tostring(txt or ""), color)
        elseif dgA38Text then dgA38Text(tostring(txt or ""), color)
        elseif ImGui and ImGui.Text then ImGui.Text(tostring(txt or "")) end
    end
    local function R109Sep() if dgMiniSep then dgMiniSep() elseif ImGui and ImGui.Separator then ImGui.Separator() end end
    local function R109SameLine() if ImGui and ImGui.SameLine then ImGui.SameLine() end end
    local function R109Button(label, cb)
        if ImGui and ImGui.Button and ImGui.Button(tostring(label or "Button")) then if cb then cb() end; return true end
        return false
    end
    local function R109Feature(hash, label)
        if dgMiniFeature then return dgMiniFeature(hash, label) end
        if renderFeatureSafe then return renderFeatureSafe(hash, label) end
        if hash and ClickGUI and ClickGUI.RenderFeature then local ok = driftgod.Try(function() ClickGUI.RenderFeature(hash) end); if ok then return true end end
        if label then R109Text(label, "dim") end
        return false
    end
    local function R109Child(name)
        if ClickGUI and ClickGUI.BeginCustomChildWindow then return ClickGUI.BeginCustomChildWindow(name) end
        R109Text(name, "header"); return true
    end
    local function R109EndChild()
        if ClickGUI and ClickGUI.EndCustomChildWindow then ClickGUI.EndCustomChildWindow() end
    end
    local function R109SafeName(name)
        name = tostring(name or "CustomPreset")
        name = name:gsub("[^%w%-%_ ]", ""):gsub("%s+", "_")
        if name == "" then name = "CustomPreset" end
        return name
    end

    driftgod.R109_CustomPresetDir = (FileMgr and FileMgr.GetMenuRootPath and (FileMgr.GetMenuRootPath() .. "\\Lua\\DriftGod\\storage\\presets\\")) or "presets\\"
    local function R109EnsurePresetDir()
        driftgod.Try(function()
            if FileMgr and FileMgr.CreateDir then
                FileMgr.CreateDir((FileMgr.GetMenuRootPath and (FileMgr.GetMenuRootPath() .. "\\Lua\\DriftGod")) or driftgod.R109_CustomPresetDir)
                FileMgr.CreateDir(driftgod.R109_CustomPresetDir)
            end
        end)
    end
    local function R109PresetPath(name) return driftgod.R109_CustomPresetDir .. R109SafeName(name) .. ".lua" end
    local R109PresetKeys = {
        "driftGripLevel", "driftStabilityLevel", "autoCounterSteerLevel",
        "momentumAssistEnabled", "momentumStrength", "accelAssistEnabled", "accelStrength",
        "experimentalGravityEnabled", "experimentalGravityStrength",
        "experimentalAccelEnabled", "experimentalAccelStrength",
        "experimentalTractionEnabled", "experimentalTractionLevel",
        "experimentalGripEnabled", "experimentalGripLevel",
        "activeArcadeDriftPreset", "arcadePresetRuntimeAssist"
    }
    local function R109SerializePreset(tbl)
        local out = { "return {" }
        for _, k in ipairs(R109PresetKeys) do
            local v = tbl[k]
            if type(v) == "number" or type(v) == "boolean" then
                out[#out+1] = "  " .. k .. " = " .. tostring(v) .. ","
            elseif type(v) == "string" then
                out[#out+1] = "  " .. k .. " = " .. string.format("%q", v) .. ","
            end
        end
        out[#out+1] = "}"
        return table.concat(out, "\n")
    end
    function driftgod.R109_ScanCustomPresets()
        R109EnsurePresetDir()
        local list = {}
        local ok, files = driftgod.Try(function()
            if FileMgr and FileMgr.FindFiles then return FileMgr.FindFiles(driftgod.R109_CustomPresetDir, "lua") end
            return nil
        end)
        if ok and type(files) == "table" then
            for _, f in ipairs(files) do
                local n = tostring(f or ""):match("([^\\/]+)%.lua$")
                if n then list[#list+1] = n end
            end
        else

            if driftgod.S.customPresetList and type(driftgod.S.customPresetList) == "table" then list = driftgod.S.customPresetList end
        end
        table.sort(list)
        driftgod.S.customPresetList = list
        driftgod.S.customPresetIndex = math.max(1, math.min(tonumber(driftgod.S.customPresetIndex or 1) or 1, math.max(1, #list)))
        return list
    end
    function driftgod.R109_SaveCustomPreset()
        R109EnsurePresetDir()
        local name = R109SafeName(driftgod.S.customPresetName or "CustomPreset")
        driftgod.S.customPresetName = name
        local data = {}
        for _, k in ipairs(R109PresetKeys) do data[k] = driftgod.S[k] end
        local ok = false
        driftgod.Try(function() if FileMgr and FileMgr.WriteFileContent then ok = FileMgr.WriteFileContent(R109PresetPath(name), R109SerializePreset(data), false) end end)
        driftgod.R109_ScanCustomPresets()
        if driftgod.Toast then driftgod.Toast(ok and ("Saved preset: " .. name) or "Preset save failed", 2200) end
        return ok
    end
    function driftgod.R109_LoadSelectedCustomPreset()
        local list = driftgod.R109_ScanCustomPresets()
        local name = list[tonumber(driftgod.S.customPresetIndex or 1) or 1]
        if not name then if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end; return false end
        local ok, data = driftgod.Try(function() return dofile(R109PresetPath(name)) end)
        if not ok or type(data) ~= "table" then if driftgod.Toast then driftgod.Toast("Preset load failed", 2200) end; return false end
        for _, k in ipairs(R109PresetKeys) do if data[k] ~= nil then driftgod.S[k] = data[k] end end
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Applied preset: " .. tostring(name), 2200) end
        return true
    end
    function driftgod.R109_DeleteSelectedCustomPreset()
        local list = driftgod.R109_ScanCustomPresets()
        local name = list[tonumber(driftgod.S.customPresetIndex or 1) or 1]
        if not name then if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end; return false end
        driftgod.Try(function() os.remove(R109PresetPath(name)) end)
        driftgod.R109_ScanCustomPresets()
        if driftgod.Toast then driftgod.Toast("Deleted preset: " .. tostring(name), 2200) end
        return true
    end

    driftgod.R110_ScanCustomPresets = driftgod.R110_ScanCustomPresets or driftgod.R109_ScanCustomPresets
    driftgod.R110_SaveCustomPreset = driftgod.R110_SaveCustomPreset or driftgod.R109_SaveCustomPreset
    driftgod.R110_ApplyCustomPreset = driftgod.R110_ApplyCustomPreset or driftgod.R109_LoadSelectedCustomPreset
    driftgod.R110_DeleteCustomPreset = driftgod.R110_DeleteCustomPreset or driftgod.R109_DeleteSelectedCustomPreset

    function driftgod.R109_RenderPresetCreation()
        if R109Child("Preset Creation") then
            R109Text("Preset Creation", "header")
            R109Text("Save your current Drift Tuning setup, then reload it from the dropdown.", "dim")
            R109Sep()
            if dgMiniRenderAbilitySnapshot then dgMiniRenderAbilitySnapshot("DG_R109_PresetCreationSnapshot") end
            R109Sep()
            driftgod.S.customPresetName = tostring(driftgod.S.customPresetName or "CustomPreset")
            if ImGui and ImGui.InputText then
                local ok, value = driftgod.Try(function() return ImGui.InputText("Preset Name", driftgod.S.customPresetName, 64) end)
                if ok then
                    if type(value) == "string" then driftgod.S.customPresetName = value
                    elseif type(value) == "table" and value[1] then driftgod.S.customPresetName = tostring(value[1]) end
                end
            else
                R109Text("Name: " .. tostring(driftgod.S.customPresetName), "white")
            end
            R109Button("Save Current Tuning", driftgod.R109_SaveCustomPreset)
            R109SameLine(); R109Button("Refresh Presets", driftgod.R109_ScanCustomPresets)
            local list = driftgod.R109_ScanCustomPresets()
            local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
            local preview = list[idx] or "No custom presets"
            if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
                local open = false; driftgod.Try(function() open = ImGui.BeginCombo("Custom Preset", tostring(preview)) end)
                if open then
                    for i, name in ipairs(list) do
                        local clicked = false; driftgod.Try(function() clicked = ImGui.Selectable(tostring(name), i == idx) end)
                        if clicked then driftgod.S.customPresetIndex = i end
                    end
                    ImGui.EndCombo()
                end
            else
                R109Text("Selected: " .. tostring(preview), "white")
            end
            R109Button("Apply Selected", driftgod.R109_LoadSelectedCustomPreset)
            R109SameLine(); R109Button("Delete Selected", driftgod.R109_DeleteSelectedCustomPreset)
            R109Sep()
            R109Text("Current values saved: Drift, Stability, Counter-Steer, Momentum, Accel, Gravity, Traction, Grip, and active Arcade preset.", "dim")
            R109EndChild()
        end

        if R109Child("Built-In Presets") then
            R109Text("Built-In Presets", "header")
            R109Text("Testing mode is ON here, so all preset families are visible.", "dim")
            R109Sep()
            if renderArcadeDriftPresetsPanelFlatR88 then renderArcadeDriftPresetsPanelFlatR88()
            elseif renderArcadeDriftPresetsPanel then renderArcadeDriftPresetsPanel() end
            R109EndChild()
        end
    end

    function driftgod.R109_SpawnRandomSavedVehicle()
        if driftgod.VS_RegisterFeatures then driftgod.Try(driftgod.VS_RegisterFeatures) end
        if driftgod.VS_Refresh and (not driftgod.VS or not driftgod.VS.runtime or #(driftgod.VS.runtime.items or {}) <= 0) then driftgod.Try(driftgod.VS_Refresh) end
        if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.items) or #(driftgod.VS.runtime.items or {}) <= 0 then
            if driftgod.Toast then driftgod.Toast("No saved vehicles scanned yet. Press Scan first.", 2200) end
            return false
        end
        local item = driftgod.VS.runtime.items[math.random(1, #driftgod.VS.runtime.items)]
        if driftgod.VS_LoadItem then return driftgod.VS_LoadItem(item) end
        return false
    end
    driftgod.H.VehicleSpawnerRandom = driftgod.Hash and driftgod.Hash("VehicleSpawnerRandom") or Utils.Joaat("VehicleSpawnerRandom")
    if driftgod.SafeAddFeature then
        driftgod.VS = driftgod.VS or {}; driftgod.VS.features = driftgod.VS.features or {}
        driftgod.VS.features.random = driftgod.SafeAddFeature(driftgod.H.VehicleSpawnerRandom, "Random", "Button", "Spawns a random saved/scanned vehicle.", function() driftgod.R109_SpawnRandomSavedVehicle() end)
    end

    local R109_OldVSRender = driftgod.VS_RenderGaragePanel
    function driftgod.VS_RenderGaragePanel()
        if driftgod.VS_RegisterFeatures then driftgod.Try(driftgod.VS_RegisterFeatures) end
        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("DriftGod Garage") then
            R109Text("Saved Vehicles", "header")
            R109Feature(driftgod.H.VehicleSpawnerScan, "Scan")
            R109Feature(driftgod.H.VehicleSpawnerOpen, "Open HUD")
            R109Feature(driftgod.H.VehicleSpawnerHotkeyInsert, "Insert Hotkey")
            R109Sep()
            R109Feature(driftgod.H.VehicleSpawnerHudPreset, "HUD Position")
            R109Feature(driftgod.H.VehicleSpawnerCategory, "Category")
            R109Feature(driftgod.H.VehicleSpawnerVehicle, "Saved Vehicle")
            R109Feature(driftgod.H.VehicleSpawnerSpawnSaved, "Spawn Selected")
            R109Feature(driftgod.H.VehicleSpawnerRandom, "Random")
            R109Sep()
            R109Text("HUD controls: Insert open/close, arrows select, Enter spawn/open, Delete back/close, F5 scan.", "dim")
            ClickGUI.EndCustomChildWindow()
        elseif R109_OldVSRender then
            R109_OldVSRender()
        end
    end

    driftgod.Try(function() if ClickGUI and ClickGUI.RemoveTab then ClickGUI.RemoveTab("DriftGod") end end)
    ClickGUI.AddTab("DriftGod", function()
        if ImGui and ImGui.BeginTabBar and ImGui.BeginTabBar("DriftGodTabs_R109_Recovery") then
            if ImGui.BeginTabItem("Home") then renderHomeMinimal(); ImGui.EndTabItem() end
            if ImGui.BeginTabItem("Drift") then renderDriftMinimal(); ImGui.EndTabItem() end
            if ImGui.BeginTabItem("Preset Creation") then driftgod.R109_RenderPresetCreation(); ImGui.EndTabItem() end
