        if ImGui and ImGui.Button and ImGui.Button(tostring(label or "Button")) then if cb then cb() end; return true end
        return false
    end
    local function R110ColorButton(label, color, cb)
        local pushed = 0
        if ImGui and ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Button then
            local r,g,b = 0.22,0.22,0.26
            local hr,hg,hb = 0.30,0.30,0.36
            local ar,ag,ab = 0.38,0.38,0.44
            if color == "purple" then r,g,b=0.45,0.18,0.85; hr,hg,hb=0.58,0.30,1.00; ar,ag,ab=0.35,0.12,0.70 end
            if color == "green" then r,g,b=0.06,0.35,0.14; hr,hg,hb=0.08,0.48,0.20; ar,ag,ab=0.10,0.62,0.26 end
            if color == "blue" then r,g,b=0.06,0.20,0.50; hr,hg,hb=0.09,0.30,0.68; ar,ag,ab=0.12,0.38,0.85 end
            if color == "red" then r,g,b=0.45,0.06,0.08; hr,hg,hb=0.62,0.10,0.12; ar,ag,ab=0.78,0.14,0.16 end
            driftgod.Try(function()
                ImGui.PushStyleColor(ImGuiCol.Button, r,g,b,0.94)
                ImGui.PushStyleColor(ImGuiCol.ButtonHovered, hr,hg,hb,0.98)
                ImGui.PushStyleColor(ImGuiCol.ButtonActive, ar,ag,ab,1.00)
            end)
            pushed = 3
        end
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) == true end)
        elseif driftgod.R101_ColorButton then clicked = driftgod.R101_ColorButton(label, color, cb) == true
        else clicked = R110Button(label, cb) == true end
        if pushed > 0 and ImGui and ImGui.PopStyleColor then driftgod.Try(ImGui.PopStyleColor, pushed) end
        if clicked and cb then driftgod.Try(cb) end
        return clicked
    end
    local function R110Fmt(n)
        if dgA38Num then return dgA38Num(n or 0) end
        n = tonumber(n or 0) or 0
        if n >= 1000000 then return string.format("%.1fm", n/1000000) end
        if n >= 1000 then return string.format("%.1fk", n/1000) end
        return tostring(math.floor(n))
    end
    local function R110Table(id, rows)
        if dgMiniTable then return dgMiniTable(id, rows) end
        for _, r in ipairs(rows or {}) do R110Text(tostring(r[1] or "") .. ": " .. tostring(r[2] or ""), r[4] or r[3]) end
    end

    driftgod.S.testAllArcadeDriftPresets = true

    driftgod.S.productionAutosaveIntervalMs = tonumber(driftgod.S.productionAutosaveIntervalMs or 300000) or 300000
    driftgod.S.productionLastAutosaveMs = tonumber(driftgod.S.productionLastAutosaveMs or 0) or 0
    driftgod.S.productionDirtyProgress = driftgod.S.productionDirtyProgress or false
    local R110_PreSetEarnedStuntTier = driftgod.SetEarnedStuntTier
    function driftgod.SetEarnedStuntTier(stuntName, tier)
        driftgod.S = driftgod.S or {}
        local key = driftgod.GetStuntUseKey and driftgod.GetStuntUseKey(stuntName) or tostring(stuntName or "")
        driftgod.S.stuntUpgradeEarnedTiers = driftgod.S.stuntUpgradeEarnedTiers or {}
        local oldTier = tonumber(driftgod.S.stuntUpgradeEarnedTiers[key] or 1) or 1
        local newTier = math.max(1, math.min(3, tonumber(tier or 1) or 1))
        driftgod.S.stuntUpgradeEarnedTiers[key] = newTier
        if newTier ~= oldTier then
            driftgod.S.productionDirtyProgress = true
            driftgod.S.stuntTierDirty = true
            driftgod.S.lastStuntTierDirtyReason = "tier " .. tostring(key) .. " -> T" .. tostring(newTier)
            if driftgod.DebugLog then driftgod.DebugLog("StuntUpgrades", "Marked dirty instead of hard-saving immediately | " .. tostring(driftgod.S.lastStuntTierDirtyReason)) end
        end
    end
    if not driftgod.__R110AutosaveLoopInstalled and Script and Script.RegisterLooped then
        driftgod.__R110AutosaveLoopInstalled = true
        Script.RegisterLooped(function()
            Script.Yield(10000)
            driftgod.S = driftgod.S or {}
            if driftgod.S.productionDirtyProgress == true or driftgod.S.stuntTierDirty == true then
                local now = driftgod.GetMs and driftgod.GetMs() or (os.clock and math.floor(os.clock()*1000) or 0)
                local last = tonumber(driftgod.S.productionLastAutosaveMs or 0) or 0
                local interval = tonumber(driftgod.S.productionAutosaveIntervalMs or 300000) or 300000
                if last <= 0 then driftgod.S.productionLastAutosaveMs = now; return end
                if now - last >= interval then
                    driftgod.S.productionLastAutosaveMs = now
                    driftgod.S.productionDirtyProgress = false
                    driftgod.S.stuntTierDirty = false
                    if driftgod.SaveProgress then driftgod.Try(function() driftgod.SaveProgress(false) end) end
                    if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
                    if driftgod.DebugLog then driftgod.DebugLog("Save", "R110 throttled autosave flushed progress/settings") end
                end
            end
        end)
    end
    driftgod.Try(function()
        if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_UNLOAD then
            EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
                if driftgod.S and (driftgod.S.productionDirtyProgress == true or driftgod.S.stuntTierDirty == true) then
                    if driftgod.SaveProgress then driftgod.Try(function() driftgod.SaveProgress(false) end) end
                    if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
                end
            end)
        end
    end)

    local R110_PreResetStunt = driftgod.ResetStuntProgressionState
    function driftgod.ResetStuntProgressionState(reason)
        local overall = driftgod.S and driftgod.S.overallScore or nil
