    local R110_OldHome = renderHomeMinimal
    renderHomeMinimal = function()
        driftgod.S = driftgod.S or {}
        local best = driftgod.GetArcadeDriftPresetScore and driftgod.GetArcadeDriftPresetScore() or (driftgod.S.bestScore or driftgod.S.highestScore or 0)
        local col = dgMiniBeginColumns and dgMiniBeginColumns("DG_R110_HomeColumns", 2) or nil

        if dgMiniColumn then dgMiniColumn(0) end
        if R110Child("Current Setup") then
            local function R158ShortText(value, maxLen)
                local s = tostring(value or "")
                maxLen = tonumber(maxLen or 24) or 24
                s = s:gsub("DriftGod Wide Angle", "Wide Angle")
                     :gsub("Speed %+ Control", "Speed+Control")
                     :gsub("High Speed Sweep", "Speed Sweep")
                     :gsub("Touge Rebuild", "Touge")
                     :gsub("Runway King", "Runway")
                     :gsub("Velocity Arc", "Velocity")
                     :gsub("Apex Runner", "Apex")
                     :gsub("Corner Magnet", "DriftGod")
                s = s:gsub("Unlock more in Arcade > Drift Presets%.%s*", "")
                     :gsub(" Best Run score", " BR")
                     :gsub(" Best Run", " BR")
                     :gsub("Only ", "")
                     :gsub(" needed for ", " → ")
                     :gsub("Current Preset:%s*", "")
                     :gsub("Preset:%s*", "")
                if #s > maxLen then return string.sub(s, 1, math.max(1, maxLen - 1)) .. "…" end
                return s
            end
            local function R159PresetLabel()
                local raw = dgA38CurrentPresetLabel and dgA38CurrentPresetLabel() or tostring(driftgod.S.activeArcadeDriftPreset or "Default")
                return R158ShortText(raw, 18)
            end
            local function R161BestRunScore()
                if driftgod.GetArcadeDriftPresetScore then
                    local ok, v = driftgod.Try(driftgod.GetArcadeDriftPresetScore)
                    if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
                end
                driftgod.S = driftgod.S or {}
                return math.floor(math.max(
                    tonumber(driftgod.S.bestScore or 0) or 0,
                    tonumber(driftgod.S.highScore or 0) or 0,
                    tonumber(driftgod.S.highestScore or 0) or 0,
                    tonumber(driftgod.S.currentScore or 0) or 0,
                    0
                ))
            end
            local function R161AddCandidate(list, category, name, req)
                req = tonumber(req or 0) or 0
                if req <= R161BestRunScore() then return end
                table.insert(list, { category=tostring(category or "Unlock"), name=tostring(name or "Reward"), req=req })
            end
            local function R161NextUnlockCompact()
                local score = R161BestRunScore()
                local candidates = {}

                if driftgod.GetNextLockedArcadeDriftPreset then
                    local ok, p, need = driftgod.Try(driftgod.GetNextLockedArcadeDriftPreset)
                    if ok and p then R161AddCandidate(candidates, "Preset", p.name or p.id or "Preset", need or p.unlock or p.score) end
                end

                for _, sector in ipairs(driftgod.VehicleSectorUnlocks or {}) do
                    if sector and not sector.starterOnly then
                        R161AddCandidate(candidates, "Vehicle", sector.label or sector.id, sector.threshold)
                    end
                end

                local abilityRows = {
                    {"Tuning", "Drift 2", 300}, {"Tuning", "Drift 3", 750}, {"Tuning", "Drift 4", 3000}, {"Tuning", "Drift 5", 7500},
                    {"Assist", "Stability 2", 900}, {"Assist", "Stability 3", 2250}, {"Assist", "Stability 4", 9000}, {"Assist", "Stability 5", 15000},
                    {"Assist", "Counter 2", 1200}, {"Assist", "Counter 3", 3000}, {"Assist", "Counter 4", 12000}, {"Assist", "Counter 5", 18000},
                    {"Assist", "Momentum 2", 1500}, {"Assist", "Momentum 3", 4500}, {"Assist", "Momentum 4", 15000}, {"Assist", "Momentum 5", 22500},
                    {"Assist", "Accel 2", 2250}, {"Assist", "Accel 3", 10500}, {"Assist", "Accel 4", 30000}, {"Assist", "Accel 5", 45000},
                }
                for _, r in ipairs(abilityRows) do R161AddCandidate(candidates, r[1], r[2], r[3]) end

                for _, stuntName in ipairs(driftgod.StuntUnlockOrder or {}) do
                    local req = driftgod.GetStuntUnlockRequirement and driftgod.GetStuntUnlockRequirement(stuntName) or (driftgod.StuntUnlocks and driftgod.StuntUnlocks[stuntName])
                    if tonumber(req or 0) and tonumber(req or 0) > score then
                        R161AddCandidate(candidates, "Stunt", stuntName, req)
                        break
                    end
                end

                R161AddCandidate(candidates, "Utility", "DriftGod Plate", 100)
                R161AddCandidate(candidates, "PTFX", "PTFX Starter", 3000)
                R161AddCandidate(candidates, "PTFX", "Effect Tier 2", 8000)
                R161AddCandidate(candidates, "PTFX", "Rear Wheel", 15000)
                R161AddCandidate(candidates, "PTFX", "Side Trail", 25000)
                R161AddCandidate(candidates, "PTFX", "Premium Effect", 40000)
                R161AddCandidate(candidates, "PTFX", "Dual-Side", 60000)
                R161AddCandidate(candidates, "PTFX", "Rare Effect", 80000)
                R161AddCandidate(candidates, "PTFX", "Clown Trails", 100000)
                R161AddCandidate(candidates, "Utility", "Traffic Reduce", 15000)
                R161AddCandidate(candidates, "Utility", "Clear Traffic", 50000)

                table.sort(candidates, function(a,b) return (a.req or 0) < (b.req or 0) end)
                local n = candidates[1]
                if not n then return "All Unlocked" end
                local label = tostring(n.category or "Unlock") .. ": " .. tostring(n.name or "Reward")
                return R158ShortText(label, 24)
            end
            R110Text("Current Setup", "header")
            R110Table("DG_R110_CurrentSetup", {
