                {"Banked Runs", tostring(driftgod.S.overallBankCount or driftgod.S.bankCount or 0), "white", "white"},
                {"Status", "Ready", "white", "green"},
            })
            R110EndChild()
        end
        if R110Child("Challenges") then
            R110Text("Challenges", "header")
            if dgR85RenderChallengeSnapshot then dgR85RenderChallengeSnapshot("DG_R110_ChallengeSnapshot")
            else
                R110Table("DG_R110_ChallengeFallback", {
                    {"Daily", driftgod.S.dailyChallengeName or "Open Arcade > Challenges", "white", "cyan"},
                    {"Session", driftgod.S.sessionChallengeName or "Session Challenges", "white", "white"},
