                    {"Vehicle Mastery", "Drive current vehicle to progress", "white", "purple"},
                })
            end
            R110Sep()
            if dgR85RenderVehicleSnapshot then dgR85RenderVehicleSnapshot("DG_R110_VehicleSnapshot") end
            R110EndChild()
        end
        if dgMiniEndColumns then dgMiniEndColumns(col) end
    end

    local function R110PresetRows(family)
        local rows = {}
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do if tostring(p.family or "") == tostring(family or "") then rows[#rows+1] = p end end
        return rows
