    local function R123RenderSlider(hash, label)
        if hash then R110Feature(hash, label) else R110Text("—", "dim") end
    end
    local function R123RenderTuningGrid()
            R123RegisterSliders()

            local function r177IsDriftAssistOn()
                if DG and driftgod.S and driftgod.S.driftAssistEnabled == true then return true end
                local h = DG and driftgod.H and driftgod.H.DriftAssist
                local feat = nil
                if h and FeatureMgr and FeatureMgr.GetFeature then driftgod.Try(function() feat = FeatureMgr.GetFeature(h) end) end
                if feat and feat.IsToggled then
                    local ok, on = driftgod.Try(function() return feat:IsToggled() end)
                    if ok then return on == true end
                end
                return false
            end
            local function r195PresetNameById(id)
                id = tostring(id or "")
                if id == "default_drifting" or id == "reset" or id == "Default Drifting" then return "Reset" end
                for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
                    if tostring(p.id or "") == id then
                        local name = (driftgod.R247PresetDisplayName and driftgod.R247PresetDisplayName(id, p)) or tostring(p.name or p.id or id)
                        return tostring(name):gsub("Default Drifting", "Reset"):gsub("DriftGod Wide Angle", "Wide Angle")
                    end
                end
                return id ~= "" and id or "Select preset"
            end
            local function r195SelectedBasePreset()
                driftgod.S = driftgod.S or {}
                local id = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or "")
                if id == "nil" then id = "" end
                if id ~= "" and id ~= "default_drifting" and id ~= "reset" and id ~= "Default Drifting" then
                    local p = nil
                    for _, row in ipairs(driftgod.ArcadeDriftPresets or {}) do if tostring(row.id or "") == id then p = row break end end
                    if driftgod.R248BasePresetAllowed and driftgod.R248BasePresetAllowed(id, p) ~= true then
                        id = "default_drifting"
                        driftgod.S.r195BaseTuningPreset = id
                    end
                end
                return id
            end
            local function r195RenderBasePresetDropdown()
                driftgod.S = driftgod.S or {}
                local current = r195SelectedBasePreset()
                local preview = current ~= "" and r195PresetNameById(current) or "Select preset"

                if driftgod.PrimeRenderDriftTuningBasePresetSelector then
                    local ok = driftgod.Try(driftgod.PrimeRenderDriftTuningBasePresetSelector, current, preview, "R196B_1")
                    if ok then return end
                end

                R110Text("Base Preset: " .. tostring(preview), current ~= "" and "purple" or "dim")
            end

            local driftAssistOn = r177IsDriftAssistOn()
            local basePresetId = r195SelectedBasePreset()
            local basePresetSelected = basePresetId ~= ""
            local tuningOn = driftAssistOn and basePresetSelected and DG and driftgod.S and driftgod.S.driftTuningEnabled == true
            local rows = {
                {name="Drift", toggle=driftgod.H.R179_DriftToggle, slider=driftgod.H.R123_DriftSlider, sliderLabel="Drift", desc="Drift Higher = wider angle / looser drift window"},
                {name="Stability", toggle=driftgod.H.StabilityAssist, slider=driftgod.H.R123_StabilitySlider, sliderLabel="Stability", desc="Stability Higher = smoother and more corrected, less wild"},
                {name="Counter-Steer", toggle=driftgod.H.AutoCounterSteer, slider=driftgod.H.R123_CounterSlider, sliderLabel="Counter-Steer", desc="Counter-Steer Higher = stronger steering bias when angle gets high"},
                {name="Momentum", toggle=driftgod.H.MomentumAssist, slider=driftgod.H.R123_MomentumSlider, sliderLabel="Momentum", desc="Momentum Higher = more speed carry / push through drift"},
                {name="Acceleration", toggle=driftgod.H.AccelAssist, slider=driftgod.H.R123_AccelSlider, sliderLabel="Acceleration", desc="Acceleration Higher = stronger forward assist"},
                {name="Gravity", toggle=driftgod.H.ExperimentalGravity, slider=driftgod.H.R123_GravitySlider, sliderLabel="Gravity", desc="Gravity Higher = more downforce/grip stability"},
                {name="Exp Accel", toggle=driftgod.H.ExperimentalAcceleration or driftgod.H.ExperimentalAccel, slider=driftgod.H.R123_ExpAccelSlider, sliderLabel="Exp Accel", desc="Exp Accel Higher = extra velocity/force boost"},
                {name="Traction", toggle=driftgod.H.ExperimentalTraction, slider=driftgod.H.R123_TractionSlider, sliderLabel="Traction", desc="Traction Higher = tighter, more controlled grip window"},
                {name="Grip", toggle=driftgod.H.ExperimentalGrip, slider=driftgod.H.R123_GripSlider, sliderLabel="Grip", desc="Grip Higher = easier to hold drift / wider grip pad"},
            }
            local flags = dgSafeTableFlags and dgSafeTableFlags() or 0
            if ImGui and ImGui.BeginTable and ImGui.BeginTable("DG_R196B_TuningMasterGrid", 2, flags) then
                if ImGui.TableSetupColumn then
