                end
                if ImGui.TableHeadersRow then driftgod.Try(ImGui.TableHeadersRow) end

                ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
                R110Feature(driftgod.H.DriftAssist, "Drift Tuning")
                ImGui.TableSetColumnIndex(1); R110Text("Required for DriftGod presets and tuning. Sliders cap at unlocked levels.", "dim")

