                    R110Text("Base Preset", "white")
                    ImGui.TableSetColumnIndex(1)
                    r195RenderBasePresetDropdown()
                    R110Text("Required preset for tuning", "dim")

                    ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
                    R110Text("Base Tuning", "white")
                    ImGui.TableSetColumnIndex(1)
                    if driftgod.P25_RenderBaseTuningCombo then
                        driftgod.P25_RenderBaseTuningCombo()
                    else
                        R110Text("Standard", "purple")
                    end
                    R110Text("Saved per Base Preset.", "dim")
                end

                if driftAssistOn and basePresetSelected then
                    ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
                    R110Feature(driftgod.H.DriftTuningMaster, "Tuning")
                    ImGui.TableSetColumnIndex(1); R110Text("Required for Drift Tuning toggles. Values cap at unlocked levels.", "dim")
                end

                if tuningOn then
                    for _, row in ipairs(rows) do
                        ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
                        if row.toggle then R110Feature(row.toggle, row.name) else R110Text("—", "dim") end
                        ImGui.TableSetColumnIndex(1)
                        if row.slider then R110Feature(row.slider, row.sliderLabel or row.name) else R110Text("—", "dim") end
                        if row.desc then R110Text(row.desc, "dim") end
