                ImGui.EndTable()
            else
                R110Feature(driftgod.H.DriftAssist, "Drift Tuning")
                R110Text("Required for DriftGod presets and tuning. Sliders cap at unlocked levels.", "dim")
                if driftAssistOn then
                    R110Text("Base Preset", "header")
                    r195RenderBasePresetDropdown()
                    R110Text("Required preset for tuning", "dim")
                    R110Text("Base Tuning", "header")
                    if driftgod.P25_RenderBaseTuningCombo then
                        driftgod.P25_RenderBaseTuningCombo()
                    else
                        R110Text("Standard", "purple")
                    end
                    R110Text("Saved per Base Preset.", "dim")
                end
                if driftAssistOn and basePresetSelected then
                    R110Feature(driftgod.H.DriftTuningMaster, "Tuning")
                    R110Text("Required for Drift Tuning toggles. Values cap at unlocked levels.", "dim")
                end
                if tuningOn then
                    for _, row in ipairs(rows) do
                        if row.toggle then R110Feature(row.toggle, row.name) end
                        if row.slider then R110Feature(row.slider, row.sliderLabel or row.name) end
                        if row.desc then R110Text(row.desc, "dim") end
                    end
                end
            end
        end

