    local function R243Feature(hash, label)
        if hash then
            if R110Feature and R110Feature(hash, label) then return true end
            if dgRenderFeatureSafe then local ok = driftgod.Try(dgRenderFeatureSafe, hash); if ok then return true end end
            if ClickGUI and ClickGUI.RenderFeature then local ok = driftgod.Try(ClickGUI.RenderFeature, hash); if ok then return true end end
        end
        if label and R110Text then R110Text("Missing: " .. tostring(label), "dim") end
        return false
    end

    local function R243Same() if R110SameLine then R110SameLine() elseif ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end end
    local function R243Sep() if R110Sep then R110Sep() elseif ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end end
    local function R243Text(txt, color) if R110Text then R110Text(tostring(txt or ""), color) elseif ImGui and ImGui.Text then driftgod.Try(ImGui.Text, tostring(txt or "")) end end
    local function R243Row(a, la, b, lb)
        R243Feature(a, la)
        if b then R243Same(); R243Feature(b, lb) end
    end

    local function R243Section(title, sub, fn)
        local opened = true
        if R110Child then opened = R110Child(tostring(title or "Ghost Section")) end
        if opened then
            R243Text(title, "header")
            if sub and tostring(sub) ~= "" then R243Text(sub, "dim") end
            R243Sep()
            local ok, err = driftgod.Try(fn)
            if not ok then R243Text("Section error: " .. tostring(err), "red") end
            if R110EndChild then R110EndChild() end
        end
    end

