        R243Text("Nodes: " .. tostring(driftgod.S.ghostRecordingNodeCount or 0) .. "   Checkpoints: " .. tostring(driftgod.S.ghostRecordingCheckpointCount or 0), "white")
        R243Text("Saved Count: " .. tostring(type(driftgod.S.savedGhostRecordings) == "table" and #driftgod.S.savedGhostRecordings or 0), "white")
        R243Text("Race: " .. tostring(driftgod.S.driftChallengeStatus or "Ready"), "white")
        R243Text("Last Result: " .. tostring(driftgod.S.driftChallengeLastMenuStatus or "None"), "white")
    end

    local R256GhostPages = { "Overview", "Record", "Saved", "Playback", "Race", "Settings" }

    local function R256ClampPage()
        driftgod.S = driftgod.S or {}
        local idx = tonumber(driftgod.S.ghostRaceUiPage or 1) or 1
        if idx < 1 then idx = 1 end
        if idx > #R256GhostPages then idx = #R256GhostPages end
        driftgod.S.ghostRaceUiPage = idx
        return idx
    end

    local function R256SetPage(idx)
        driftgod.S = driftgod.S or {}
        idx = tonumber(idx or 1) or 1
        if idx < 1 then idx = 1 end
        if idx > #R256GhostPages then idx = #R256GhostPages end
        driftgod.S.ghostRaceUiPage = idx
    end

    local function R256Button(label, cb)
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) == true end) end
        if clicked and type(cb) == "function" then driftgod.Try(cb) end
        return clicked
    end

    local function R256Same() if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end end

    local function R256Columns(id, cols, fn)

        local lastCol = 0
        local function verticalBreak(col)
            col = tonumber(col or 1) or 1
            if col > 1 or lastCol > 0 then
                R243Sep()
            end
            lastCol = col
        end
        if type(fn) == "function" then
            local ok, err = driftgod.Try(fn, verticalBreak)
            if not ok then R243Text("Ghost page error: " .. tostring(err), "red") end
        end
        return true
    end

    local function R256PageSelector()
        local idx = R256ClampPage()
        R243Text("Ghosts & Race (Beta)", "header")
        R243Text("Record ghosts, save routes, replay runs, and race with countdown/results.", "dim")
        R243Sep()
        if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
            local open = false
            driftgod.Try(function() open = ImGui.BeginCombo("Ghost Page##R256GhostPage", R256GhostPages[idx] or "Overview") end)
            if open then
                for i, name in ipairs(R256GhostPages) do
                    local clicked = false
                    driftgod.Try(function() clicked = ImGui.Selectable(tostring(name), i == idx) end)
                    if clicked then R256SetPage(i) end
                end
                ImGui.EndCombo()
            end
        else
            R243Text("Page: " .. tostring(R256GhostPages[idx] or "Overview"), "white")
        end
        R243Sep()
        for i, name in ipairs(R256GhostPages) do
            if i > 1 then R256Same() end
            local prefix = (idx == i) and "[" or ""
            local suffix = (idx == i) and "]" or ""
            R256Button(prefix .. tostring(name) .. suffix .. "##R256GhostNav" .. tostring(i), function() R256SetPage(i) end)
        end
        R243Sep()
    end

    local function R256CountdownText()
        if driftgod.S and driftgod.S.driftChallengeCountdownActive == true then
            local txt = ""
            if driftgod.A51R19CountdownText then local ok, v = driftgod.Try(driftgod.A51R19CountdownText); if ok then txt = tostring(v or "") end end
            if txt == "" and driftgod.GetDriftChallengeCountdownTextA12 then local ok, v = driftgod.Try(driftgod.GetDriftChallengeCountdownTextA12); if ok then txt = tostring(v or "") end end
            if txt == "" and driftgod.GetDriftChallengeCountdownText then local ok, v = driftgod.Try(driftgod.GetDriftChallengeCountdownText); if ok then txt = tostring(v or "") end end
            if txt == "" then txt = tostring(driftgod.S.driftChallengeCountdownLastToast or "3") end
            return txt ~= "" and txt or "3"
        end
        return "Ready"
    end

    local function R256LivePoints()
        if driftgod.GetDriftChallengeLiveScore then local ok, v = driftgod.Try(driftgod.GetDriftChallengeLiveScore); if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end end
        return math.floor(tonumber(driftgod.S and driftgod.S.driftChallengeLivePoints or 0) or 0)
    end
    local function R256LiveStunts()
        if driftgod.GetDriftChallengeLiveStunts then local ok, v = driftgod.Try(driftgod.GetDriftChallengeLiveStunts); if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end end
        return math.floor(tonumber(driftgod.S and driftgod.S.driftChallengeLiveStunts or 0) or 0)
    end
    local function R256LiveCollisions()
        if driftgod.GetDriftChallengeLiveCollisions then local ok, v = driftgod.Try(driftgod.GetDriftChallengeLiveCollisions); if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end end
        return math.floor(tonumber(driftgod.S and driftgod.S.driftChallengeLiveCollisions or 0) or 0)
    end

    local function R256RaceStatusCard()
        local result = driftgod.S and driftgod.S.driftChallengeLastResult or {}
        local resultText = "None"
        if type(result) == "table" then
            if result.didNotFinish == true then resultText = "Did Not Finish"
            elseif result.won == true then resultText = "Won"
            elseif result.won == false then resultText = "Failed" end
        end
        R243Text("Race UI", "header")
        R243Text("Countdown: " .. tostring(R256CountdownText()), driftgod.S and driftgod.S.driftChallengeCountdownActive == true and "gold" or "white")
        R243Text("Countdown Flow: 3... 2... 1... GO!", "dim")
        R243Text("Race Active: " .. tostring(driftgod.S and driftgod.S.driftChallengeActive == true), "white")
        R243Text("Status: " .. tostring(driftgod.S and driftgod.S.driftChallengeStatus or "Ready"), "white")
        R243Text("Last Menu Status: " .. tostring(driftgod.S and driftgod.S.driftChallengeLastMenuStatus or ""), "dim")
        R243Sep()
        R243Text("You: " .. tostring(R256LivePoints()) .. " pts / " .. tostring(R256LiveStunts()) .. " stunts / " .. tostring(R256LiveCollisions()) .. " collisions", "white")
        R243Text("Rival: " .. tostring(driftgod.S and driftgod.S.driftChallengeTargetPoints or 0) .. " pts / " .. tostring(driftgod.S and driftgod.S.driftChallengeTargetStunts or 0) .. " stunts / <= " .. tostring(driftgod.S and driftgod.S.driftChallengeTargetCollisions or 0) .. " collisions", "white")
        R243Text("Checkpoint: " .. tostring(driftgod.S and driftgod.S.driftChallengeCheckpointIndex or 1) .. " / " .. tostring(driftgod.S and driftgod.S.ghostRecordingCheckpointCount or 0), "white")
        R243Text("Distance: " .. tostring(driftgod.S and driftgod.S.driftChallengeNextCheckpointDistance or "--"), "white")
        R243Text("Last Result: " .. tostring(resultText), resultText == "Won" and "green" or (resultText == "Failed" or resultText == "Did Not Finish") and "red" or "white")
    end

    local function R256SavedDropdown()
        local list = driftgod.S and driftgod.S.savedGhostRecordings or {}
        if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo and type(list) == "table" and #list > 0 then
            local preview = driftgod.GetSavedRecordingComboPreview and driftgod.GetSavedRecordingComboPreview() or tostring(driftgod.S.savedGhostRecordingSelectedName or "Saved Recording")
            local open = false
            driftgod.Try(function() open = ImGui.BeginCombo("Saved Recording##R256GhostSaved", preview) end)
            if open then
                for i, item in ipairs(list) do
                    local label = tostring(item.name or item.file or ("Recording " .. tostring(i)))
                    local selected = i == (tonumber(driftgod.S.savedGhostRecordingIndex or 1) or 1)
                    local clicked = false
                    driftgod.Try(function() clicked = ImGui.Selectable(label, selected) end)
                    if clicked and driftgod.SetSavedRecordingIndex then driftgod.Try(driftgod.SetSavedRecordingIndex, i) end
                end
                ImGui.EndCombo()
            end
        else
            R243Text("Saved recording dropdown appears after Scan finds recordings.", "dim")
        end
    end

