    local function R123Cap(fnName)
        if driftgod.IsArcadePresetTestingMode and driftgod.IsArcadePresetTestingMode() then return 5 end
        local fn = DG[fnName]
        if type(fn) == "function" then
            local ok, v = driftgod.Try(fn)
            if ok and tonumber(v) then return math.max(1, tonumber(v)) end
        end
        return 5
    end
    local function R123CInt(v, mn, mx)
        v = math.floor(tonumber(v or mn) or mn)
        if v < mn then v = mn end
        if v > mx then v = mx end
        return v
    end
    local function R123MarkDirty()
        driftgod.S = driftgod.S or {}
        driftgod.S.productionDirtyProgress = true
        driftgod.S.productionDirtySettings = true
    end
    local function R123SetAliases(kind, v)
        driftgod.S = driftgod.S or {}
        if kind == "drift" then driftgod.S.driftGripLevel = v
        elseif kind == "stability" then driftgod.S.driftStabilityLevel=v; driftgod.S.stabilityLevel=v; driftgod.S.stability=v; driftgod.S.driftStability=v
        elseif kind == "counter" then driftgod.S.autoCounterSteerLevel=v; driftgod.S.counterSteerLevel=v; driftgod.S.autoCounterSteer=v; driftgod.S.driftCounterSteer=v
        elseif kind == "momentum" then driftgod.S.momentumStrength=v; driftgod.S.momentumLevel=v; driftgod.S.momentum=v; driftgod.S.driftMomentum=v
        elseif kind == "accel" then driftgod.S.accelStrength=v; driftgod.S.accelerationLevel=v; driftgod.S.acceleration=v; driftgod.S.driftAcceleration=v
        elseif kind == "gravity" then driftgod.S.experimentalGravityStrength=v
        elseif kind == "expaccel" then driftgod.S.experimentalAccelStrength=v
        elseif kind == "traction" then driftgod.S.experimentalTractionLevel=v
        elseif kind == "grip" then driftgod.S.experimentalGripLevel=v
        end
        if driftgod.R196B_TuningDebug then driftgod.R196B_TuningDebug("Tuning value changed | " .. tostring(kind) .. "=" .. tostring(v) .. " | base=" .. tostring(driftgod.S and (driftgod.S.r195BaseTuningPreset or driftgod.S.activeArcadeDriftPreset) or "none")) end
        R123MarkDirty()
    end

    local function R245ScoreForTuningCaps()
        if DG and driftgod.ScoreForUnlock then
            local ok, v = driftgod.Try(driftgod.ScoreForUnlock)
            if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
        end
        local best = tonumber(DG and driftgod.S and (driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore) or 0) or 0
        local cur = tonumber(DG and driftgod.S and driftgod.S.currentScore or 0) or 0
        return math.floor(math.max(best, cur, 0))
    end
    local function R245ExperimentalOneToFiveCap()
        if DG and driftgod.S and driftgod.S.progressUnlocksEnabled == false then return 5 end
        local score = R245ScoreForTuningCaps()
        if score >= 80000 then return 5 elseif score >= 60000 then return 4 elseif score >= 40000 then return 3 elseif score >= 25000 then return 2 end
        return 1
    end
    local function R245ExperimentalZeroToFiveCap()
        if DG and driftgod.S and driftgod.S.progressUnlocksEnabled == false then return 5 end
        local score = R245ScoreForTuningCaps()
        if score >= 100000 then return 5 elseif score >= 80000 then return 4 elseif score >= 60000 then return 3 elseif score >= 40000 then return 2 elseif score >= 25000 then return 1 end
        return 0
    end
    function driftgod.GetUnlockedExperimentalGravityLevel() return R245ExperimentalOneToFiveCap() end
    function driftgod.GetUnlockedExperimentalAccelLevel() return R245ExperimentalOneToFiveCap() end
    function driftgod.GetUnlockedExperimentalTractionLevel() return R245ExperimentalZeroToFiveCap() end
    function driftgod.GetUnlockedExperimentalGripLevel() return R245ExperimentalZeroToFiveCap() end
    function driftgod.R245GetTuningCap(kind, fallback)
        kind = tostring(kind or "")
        if kind == "drift" and driftgod.GetUnlockedDriftLevel then return driftgod.GetUnlockedDriftLevel() end
        if kind == "stability" and driftgod.GetUnlockedStabilityLevel then return driftgod.GetUnlockedStabilityLevel() end
        if kind == "counter" and driftgod.GetUnlockedAutoCounterSteerLevel then return driftgod.GetUnlockedAutoCounterSteerLevel() end
        if kind == "momentum" and driftgod.GetUnlockedMomentumLevel then return driftgod.GetUnlockedMomentumLevel() end
        if kind == "accel" and driftgod.GetUnlockedAccelLevel then return driftgod.GetUnlockedAccelLevel() end
        if kind == "gravity" and driftgod.GetUnlockedExperimentalGravityLevel then return driftgod.GetUnlockedExperimentalGravityLevel() end
        if kind == "expaccel" and driftgod.GetUnlockedExperimentalAccelLevel then return driftgod.GetUnlockedExperimentalAccelLevel() end
        if kind == "traction" and driftgod.GetUnlockedExperimentalTractionLevel then return driftgod.GetUnlockedExperimentalTractionLevel() end
        if kind == "grip" and driftgod.GetUnlockedExperimentalGripLevel then return driftgod.GetUnlockedExperimentalGripLevel() end
        return tonumber(fallback or 5) or 5
    end
    local function R123Slider(key, name, mn, mx, default, kind, desc)
        driftgod.H[key] = driftgod.H[key] or (driftgod.Hash and driftgod.Hash(key) or Utils.Joaat("DG_" .. key))
        if driftgod.SafeAddFeature and eFeatureType and eFeatureType.SliderInt then
            local ok, f = driftgod.Try(function()
                return driftgod.SafeAddFeature(driftgod.H[key], name, eFeatureType.SliderInt, tostring(desc or ""), function(feat)
                    local v = default or mn
                    driftgod.Try(function() if feat and feat.GetIntValue then v = feat:GetIntValue() end end)
                    local activeMax = (DG and driftgod.R245GetTuningCap and driftgod.R245GetTuningCap(kind, mx)) or mx
                    R123SetAliases(kind, R123CInt(v, mn, activeMax))
                end)
            end)
            if ok and f then
                driftgod.Try(function() if f.SetLimitValues then f:SetLimitValues(mn, (DG and driftgod.R245GetTuningCap and driftgod.R245GetTuningCap(kind, mx)) or mx) end end)
                driftgod.Try(function() if f.SetStepSize then f:SetStepSize(1) end end)
                driftgod.Try(function() if f.SetIntValue then local activeMax = (DG and driftgod.R245GetTuningCap and driftgod.R245GetTuningCap(kind, mx)) or mx; f:SetIntValue(R123CInt(default or mn, mn, activeMax)) end end)
            end
        end
    end
    local function R123RegisterSliders()
        if driftgod.__R123SlidersRegistered then return end
        driftgod.__R123SlidersRegistered = true
        driftgod.S = driftgod.S or {}
        R123Slider("R123_DriftSlider", "Drift", 1, R123Cap("GetUnlockedDriftLevel"), driftgod.S.driftGripLevel or 1, "drift", "Drift Higher = wider angle / looser drift window")
        R123Slider("R123_StabilitySlider", "Stability", 1, R123Cap("GetUnlockedStabilityLevel"), driftgod.S.driftStabilityLevel or driftgod.S.stabilityLevel or 1, "stability", "Stability Higher = smoother and more corrected, less wild")
        R123Slider("R123_CounterSlider", "Counter-Steer", 1, R123Cap("GetUnlockedAutoCounterSteerLevel"), driftgod.S.autoCounterSteerLevel or driftgod.S.counterSteerLevel or 1, "counter", "Counter-Steer Higher = stronger steering bias when angle gets high")
        R123Slider("R123_MomentumSlider", "Momentum", 1, R123Cap("GetUnlockedMomentumLevel"), driftgod.S.momentumStrength or driftgod.S.momentumLevel or 1, "momentum", "Momentum Higher = more speed carry / push through drift")
        R123Slider("R123_AccelSlider", "Acceleration", 1, R123Cap("GetUnlockedAccelLevel"), driftgod.S.accelStrength or driftgod.S.accelerationLevel or 1, "accel", "Acceleration Higher = stronger forward assist")
        R123Slider("R123_GravitySlider", "Gravity", 1, 5, driftgod.S.experimentalGravityStrength or 1, "gravity", "Gravity Higher = more downforce/grip stability")
        R123Slider("R123_ExpAccelSlider", "Exp Accel", 1, 5, driftgod.S.experimentalAccelStrength or 1, "expaccel", "Exp Accel Higher = extra velocity/force boost")
        R123Slider("R123_TractionSlider", "Traction", 0, 5, driftgod.S.experimentalTractionLevel or 0, "traction", "Traction Higher = tighter, more controlled grip window")
        R123Slider("R123_GripSlider", "Grip", 0, 5, driftgod.S.experimentalGripLevel or 0, "grip", "Grip Higher = easier to hold drift / wider grip pad")
    end
    R123RegisterSliders()

    local function R123PurpleButton(label, cb)
        return R110ColorButton(tostring(label or "Apply"), "purple", cb)
    end
    local function R123PresetRows(family)
        local rows = {}
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            if tostring(p.family or "") == tostring(family or "") then rows[#rows+1] = p end
        end
        return rows
    end
    function driftgod.R110_RenderPresetColumns(id)

        local groups = {
            {label="Default / Starter", sections={{label=nil, family="Default / Starter"}, {label="Very Open", family="Open"}}},
            {label="Wide Road", sections={{label=nil, family="Wide / Open Roads"}}},
            {label="Technical", sections={{label=nil, family="Technical / Windy Roads"}}},
            {label="Custom / Favorites", custom=true},
        }
        local function renderSection(section)
            if section.label and section.label ~= "Default / Starter" then R110Text(section.label, "header") end
            local rows = R123PresetRows(section.family)
            if #rows <= 0 then R110Text("No presets", "dim") end
            for _, p in ipairs(rows) do
                R110Text(tostring(p.name or p.id or "Preset"), "white")
                R123PurpleButton("Apply##R128_" .. tostring(p.id or p.name), function()
                    if driftgod.ApplyArcadeDriftPreset then driftgod.ApplyArcadeDriftPreset(p.id, true) end
                end)
            end
        end
        local function renderCustomFavorites()
            local list = {}
            if driftgod.R110_ScanCustomPresets then list = driftgod.R110_ScanCustomPresets() or {} end
            if #list <= 0 then
                R110Text("No custom presets yet", "dim")
                R110Text("Save one below in Preset Creation.", "dim")
                return
            end
            for i, name in ipairs(list) do
                R110Text(tostring(name), "white")
                R123PurpleButton("Apply##R128_Custom_" .. tostring(i), function()
                    driftgod.S = driftgod.S or {}
                    driftgod.S.customPresetIndex = i
                    if driftgod.R110_ApplyCustomPreset then driftgod.R110_ApplyCustomPreset() end
                end)
            end
        end
        if ImGui and ImGui.BeginTable and ImGui.BeginTable(id or "DG_R128_PresetColumns", 4, dgSafeTableFlags and dgSafeTableFlags() or 0) then
            for _, g in ipairs(groups) do if ImGui.TableSetupColumn then driftgod.Try(ImGui.TableSetupColumn, g.label) end end
            ImGui.TableNextRow()
            for c, g in ipairs(groups) do ImGui.TableSetColumnIndex(c-1); R110Text(g.label, "header") end
            ImGui.TableNextRow()
            for c, g in ipairs(groups) do
                ImGui.TableSetColumnIndex(c-1)
                if g.custom then
                    renderCustomFavorites()
                else
                    for si, section in ipairs(g.sections) do
                        if si > 1 and ImGui.Spacing then ImGui.Spacing() end
                        renderSection(section)
                    end
                end
            end
            ImGui.EndTable()
        else
            for _, g in ipairs(groups) do
                R110Text(g.label, "header")
                if g.custom then renderCustomFavorites() else for _, section in ipairs(g.sections) do renderSection(section) end end
            end
        end
    end

    local function R123RenderSlider(hash, label)
        if hash then R110Feature(hash, label) else R110Text("—", "dim") end
    end
    local function R123RenderTuningGrid()
            R123RegisterSliders()

            local function r177IsDriftAssistOn()
                if DG and driftgod.S and driftgod.S.driftAssistEnabled == true then return true end
                local h = DG and driftgod.H and driftgod.H.DriftAssist
                local feat = nil
                if h and FeatureMgr and FeatureMgr.GetFeature then driftgod.Try(function() feat = FeatureMgr.GetFeature(h) end) end
                if feat and feat.IsToggled then
                    local ok, on = driftgod.Try(function() return feat:IsToggled() end)
                    if ok then return on == true end
                end
                return false
            end
            local function r195PresetNameById(id)
                id = tostring(id or "")
                if id == "default_drifting" or id == "reset" or id == "Default Drifting" then return "Reset" end
                for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
                    if tostring(p.id or "") == id then
                        local name = (driftgod.R247PresetDisplayName and driftgod.R247PresetDisplayName(id, p)) or tostring(p.name or p.id or id)
                        return tostring(name):gsub("Default Drifting", "Reset"):gsub("DriftGod Wide Angle", "Wide Angle")
                    end
                end
                return id ~= "" and id or "Select preset"
            end
            local function r195SelectedBasePreset()
                driftgod.S = driftgod.S or {}
                local id = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or "")
                if id == "nil" then id = "" end
                if id ~= "" and id ~= "default_drifting" and id ~= "reset" and id ~= "Default Drifting" then
                    local p = nil
                    for _, row in ipairs(driftgod.ArcadeDriftPresets or {}) do if tostring(row.id or "") == id then p = row break end end
                    if driftgod.R248BasePresetAllowed and driftgod.R248BasePresetAllowed(id, p) ~= true then
                        id = "default_drifting"
                        driftgod.S.r195BaseTuningPreset = id
                    end
                end
                return id
            end
            local function r195RenderBasePresetDropdown()
                driftgod.S = driftgod.S or {}
                local current = r195SelectedBasePreset()
                local preview = current ~= "" and r195PresetNameById(current) or "Select preset"

                if driftgod.PrimeRenderDriftTuningBasePresetSelector then
                    local ok = driftgod.Try(driftgod.PrimeRenderDriftTuningBasePresetSelector, current, preview, "R196B_2")
                    if ok then return end
                end

                R110Text("Base Preset: " .. tostring(preview), current ~= "" and "purple" or "dim")
            end

            local driftAssistOn = r177IsDriftAssistOn()
            local basePresetId = r195SelectedBasePreset()
            local basePresetSelected = basePresetId ~= ""
            local tuningOn = driftAssistOn and basePresetSelected and DG and driftgod.S and driftgod.S.driftTuningEnabled == true
            local rows = {
                {name="Drift", toggle=driftgod.H.R179_DriftToggle, slider=driftgod.H.R123_DriftSlider, sliderLabel="Drift", desc="Drift Higher = wider angle / looser drift window"},
                {name="Stability", toggle=driftgod.H.StabilityAssist, slider=driftgod.H.R123_StabilitySlider, sliderLabel="Stability", desc="Stability Higher = smoother and more corrected, less wild"},
                {name="Counter-Steer", toggle=driftgod.H.AutoCounterSteer, slider=driftgod.H.R123_CounterSlider, sliderLabel="Counter-Steer", desc="Counter-Steer Higher = stronger steering bias when angle gets high"},
                {name="Momentum", toggle=driftgod.H.MomentumAssist, slider=driftgod.H.R123_MomentumSlider, sliderLabel="Momentum", desc="Momentum Higher = more speed carry / push through drift"},
                {name="Acceleration", toggle=driftgod.H.AccelAssist, slider=driftgod.H.R123_AccelSlider, sliderLabel="Acceleration", desc="Acceleration Higher = stronger forward assist"},
                {name="Gravity", toggle=driftgod.H.ExperimentalGravity, slider=driftgod.H.R123_GravitySlider, sliderLabel="Gravity", desc="Gravity Higher = more downforce/grip stability"},
                {name="Exp Accel", toggle=driftgod.H.ExperimentalAcceleration or driftgod.H.ExperimentalAccel, slider=driftgod.H.R123_ExpAccelSlider, sliderLabel="Exp Accel", desc="Exp Accel Higher = extra velocity/force boost"},
                {name="Traction", toggle=driftgod.H.ExperimentalTraction, slider=driftgod.H.R123_TractionSlider, sliderLabel="Traction", desc="Traction Higher = tighter, more controlled grip window"},
                {name="Grip", toggle=driftgod.H.ExperimentalGrip, slider=driftgod.H.R123_GripSlider, sliderLabel="Grip", desc="Grip Higher = easier to hold drift / wider grip pad"},
            }
            local flags = dgSafeTableFlags and dgSafeTableFlags() or 0
            if ImGui and ImGui.BeginTable and ImGui.BeginTable("DG_R196B_TuningMasterGrid", 2, flags) then
                if ImGui.TableSetupColumn then
                    driftgod.Try(ImGui.TableSetupColumn, "Toggle")
                    driftgod.Try(ImGui.TableSetupColumn, "Slider / Info")
                end
                if ImGui.TableHeadersRow then driftgod.Try(ImGui.TableHeadersRow) end

                ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
                R110Feature(driftgod.H.DriftAssist, "Drift Tuning")
                ImGui.TableSetColumnIndex(1); R110Text("Required for DriftGod presets and tuning. Sliders cap at unlocked levels.", "dim")

                if driftAssistOn then
                    ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
                    R110Text("Base Preset", "white")
                    ImGui.TableSetColumnIndex(1)
                    r195RenderBasePresetDropdown()
                    R110Text("Required preset for tuning", "dim")

                    ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
                    R110Text("Base Tuning", "white")
                    ImGui.TableSetColumnIndex(1)
                    if driftgod.P25_RenderBaseTuningCombo then
                        driftgod.P25_RenderBaseTuningCombo()
                    else
                        R110Text("Standard", "purple")
                    end
                    R110Text("Saved per Base Preset.", "dim")
                end

                if driftAssistOn and basePresetSelected then
                    ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
                    R110Feature(driftgod.H.DriftTuningMaster, "Tuning")
                    ImGui.TableSetColumnIndex(1); R110Text("Required for Drift Tuning toggles. Values cap at unlocked levels.", "dim")
                end

                if tuningOn then
                    for _, row in ipairs(rows) do
                        ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
                        if row.toggle then R110Feature(row.toggle, row.name) else R110Text("—", "dim") end
                        ImGui.TableSetColumnIndex(1)
                        if row.slider then R110Feature(row.slider, row.sliderLabel or row.name) else R110Text("—", "dim") end
                    end
                end
                ImGui.EndTable()
            else
                R110Feature(driftgod.H.DriftAssist, "Drift Tuning")
                R110Text("Required for DriftGod presets and tuning. Sliders cap at unlocked levels.", "dim")
                if driftAssistOn then
                    R110Text("Base Preset", "header")
                    r195RenderBasePresetDropdown()
                    R110Text("Required preset for tuning", "dim")
                    R110Text("Base Tuning", "header")
                    if driftgod.P25_RenderBaseTuningCombo then
                        driftgod.P25_RenderBaseTuningCombo()
                    else
                        R110Text("Standard", "purple")
                    end
                    R110Text("Saved per Base Preset.", "dim")
                end
                if driftAssistOn and basePresetSelected then
                    R110Feature(driftgod.H.DriftTuningMaster, "Tuning")
                    R110Text("Required for Drift Tuning toggles. Values cap at unlocked levels.", "dim")
                end
                if tuningOn then
                    for _, row in ipairs(rows) do
                        if row.toggle then R110Feature(row.toggle, row.name) end
                        if row.slider then R110Feature(row.slider, row.sliderLabel or row.name) end
                    end
                end
            end
        end

    function driftgod.R110_RenderPresetCreation()
        if R110Child("Preset Creation") then
            driftgod.S.customPresetName = tostring(driftgod.S.customPresetName or "CustomPreset")
            if ImGui and ImGui.InputText then
                local ok, value = driftgod.Try(function() return ImGui.InputText("Preset Name", driftgod.S.customPresetName, 64) end)
                if ok then
                    if type(value) == "string" then driftgod.S.customPresetName = value
                    elseif type(value) == "table" and value[1] then driftgod.S.customPresetName = tostring(value[1]) end
                end
            else
                R110Text("Preset Name: " .. tostring(driftgod.S.customPresetName), "white")
            end
            R123PurpleButton("Save Current Tuning", driftgod.R110_SaveCustomPreset)
            R110SameLine(); R110ColorButton("Refresh", "blue", driftgod.R110_ScanCustomPresets)
            local list = driftgod.R110_ScanCustomPresets and driftgod.R110_ScanCustomPresets() or {}
            local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
            local preview = list[idx] or "No custom presets"
            if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
                local open = false; driftgod.Try(function() open = ImGui.BeginCombo("Custom Preset", tostring(preview)) end)
                if open then
                    for i, name in ipairs(list) do
                        local clicked=false; driftgod.Try(function() clicked = ImGui.Selectable(tostring(name), i == idx) end)
                        if clicked then driftgod.S.customPresetIndex = i end
                    end
                    ImGui.EndCombo()
                end
            else
                R110Text("Selected: " .. tostring(preview), "white")
            end
            R123PurpleButton("Apply", driftgod.R110_ApplyCustomPreset)
            R110SameLine(); R110ColorButton("Delete", "red", driftgod.R110_DeleteCustomPreset)
            R110EndChild()
        end
    end

    renderDriftMinimal = function()
        if R110Child("Presets") then
            driftgod.R110_RenderPresetColumns("DG_R123_DriftPresetColumns")
