__DG_BUNDLE_LOADERS["ui.mph_hud"] = function()
DG = DG or {}

function driftgod.GetCurrentVehicleMph()
    if not driftgod.HasNatives or not driftgod.HasNatives() then return 0 end
    if not driftgod.GetVehicle then return 0 end

    local veh = driftgod.GetVehicle()
    if not veh or veh == 0 then return 0 end

    local mps = 0
    local ok = driftgod.Try(function()
        mps = ENTITY.GET_ENTITY_SPEED(veh)
    end)

    if not ok or not mps then return 0 end
    return mps * 2.236936
end

function driftgod.DrawMphHud()
    driftgod.S = driftgod.S or {}
    if driftgod.S.mphHudEnabled ~= true then return end
    if not driftgod.HasNatives or not driftgod.HasNatives() then return end

    local inVehicle = false
    if driftgod.IsInVehicle then
        inVehicle = driftgod.IsInVehicle() == true
    elseif driftgod.GetVehicle then
        local veh = driftgod.GetVehicle()
        inVehicle = veh ~= nil and veh ~= 0
    end
    if not inVehicle then return end

    local mph = math.floor((driftgod.GetCurrentVehicleMph() or 0) + 0.5)
    local x = driftgod.S.mphHudX or 0.167
    local y = driftgod.S.mphHudY or 0.977
    local scale = driftgod.S.mphHudScale or 0.65

    local text = "MPH: " .. tostring(mph)

    if driftgod.S.mphHudBackground == true then
        driftgod.DrawRect(x, y + (0.004 * scale), 0.170 * scale, 0.042 * scale, 5, 5, 10, 110)
    end

    driftgod.DrawText(text, x, y - (0.016 * scale), 0.42 * scale, 255, 255, 255, 235, 4)
end

return DG
end

__DG_BUNDLE_LOADERS["ui.popups"] = function()
DG = DG or {}
function driftgod.AddBonusPopup(text, r, g, b)

    local angle = math.random() * math.pi * 2.0
    local dirX = math.cos(angle)
    local dirY = math.sin(angle)

    if math.abs(dirX) < 0.22 then dirX = dirX < 0 and -0.22 or 0.22 end
    if math.abs(dirY) < 0.22 then dirY = dirY < 0 and -0.22 or 0.22 end

    local minDrift = tonumber((driftgod.S and (driftgod.S.bonusPopupRadialMinDrift or driftgod.S.bonusPopupRandomMinDrift)) or 0.060) or 0.060
    local maxDrift = tonumber((driftgod.S and (driftgod.S.bonusPopupRadialMaxDrift or driftgod.S.bonusPopupRandomMaxDrift)) or 0.135) or 0.135
    local drift = minDrift + (math.random() * math.max(0.001, maxDrift - minDrift))

    local startRadius = tonumber((driftgod.S and driftgod.S.bonusPopupRadialStartRadius) or 0.012) or 0.012

    table.insert(driftgod.S.bonusPopups, {
        text = text,
        start = driftgod.Now(),
        life = 2000,
        r = r or 190,
        g = g or 90,
        b = b or 255,

        dirX = dirX,
        dirY = dirY,
        drift = drift,
        startRadius = startRadius,

        anchorMode = "score_radial"
    })
end

function driftgod.NormalizeComboPopupText(text)
    text = tostring(text or "")
    text = text:gsub("(%d+x)%s+[Cc][Oo][Mm][Bb][Oo]%s*%-%s*[Cc][Oo][Mm][Bb][Oo]", "%1 Combo")
    text = text:gsub("(%d+x)%s*%-%s*[Cc][Oo][Mm][Bb][Oo]", "%1 Combo")
    text = text:gsub("(%d+x)%s+[Cc][Oo][Mm][Bb][Oo]%s+[Cc][Oo][Mm][Bb][Oo]", "%1 Combo")
    return text
end

return DG
end

__DG_BUNDLE_LOADERS["ui.stunt_menu"] = function()
DG = DG or {}

driftgod.S = driftgod.S or {}
if driftgod.S.stuntQuickMenuX == nil then driftgod.S.stuntQuickMenuX = tonumber(driftgod.S.stuntHudX or 0.085) or 0.085 end
if driftgod.S.stuntQuickMenuY == nil then driftgod.S.stuntQuickMenuY = tonumber(driftgod.S.stuntHudY or 0.560) or 0.560 end
if driftgod.S.stuntHudX == nil then driftgod.S.stuntHudX = driftgod.S.stuntQuickMenuX end
if driftgod.S.stuntHudY == nil then driftgod.S.stuntHudY = driftgod.S.stuntQuickMenuY end

local function DG_A50R4Clamp(v, lo, hi)
    v = tonumber(v or lo) or lo
    if v < lo then return lo end
    if v > hi then return hi end
    return v
end

function driftgod.GetStuntQuickMenuPosition(defaultX, defaultY)
    driftgod.S = driftgod.S or {}
    local x = tonumber(driftgod.S.stuntQuickMenuX)
    local y = tonumber(driftgod.S.stuntQuickMenuY)

    if x == nil then x = tonumber(driftgod.S.stuntHudX) end
    if y == nil then y = tonumber(driftgod.S.stuntHudY) end

    x = DG_A50R4Clamp(x or defaultX or 0.085, 0.000, 1.000)
    y = DG_A50R4Clamp(y or defaultY or 0.560, 0.000, 1.000)

    driftgod.S.stuntQuickMenuX = x
    driftgod.S.stuntQuickMenuY = y
    driftgod.S.stuntHudX = x
    driftgod.S.stuntHudY = y
    return x, y
end

function driftgod.SetStuntQuickMenuPosition(x, y, save)
    driftgod.S = driftgod.S or {}
    x = DG_A50R4Clamp(x or driftgod.S.stuntQuickMenuX or driftgod.S.stuntHudX or 0.085, 0.000, 1.000)
    y = DG_A50R4Clamp(y or driftgod.S.stuntQuickMenuY or driftgod.S.stuntHudY or 0.560, 0.000, 1.000)

    driftgod.S.stuntQuickMenuX = x
    driftgod.S.stuntQuickMenuY = y
    driftgod.S.stuntHudX = x
    driftgod.S.stuntHudY = y
    driftgod.S.stuntHudMoveEnabled = true

    if save ~= false and driftgod.SaveSettings then driftgod.SaveSettings(false) end
    return x, y
end

driftgod.StuntSafety = driftgod.StuntSafety or {
    enabled = true,
    maxLinear = 2.35,
    maxUp = 0.62,
    maxDown = -0.45,
    maxAngular = 3.25,
    aggressiveMultiplier = 0.42,
    defaultMultiplier = 0.72,
}

local function DG_StuntClamp(value, minValue, maxValue)
    value = tonumber(value or 0.0) or 0.0
    if value < minValue then return minValue end
    if value > maxValue then return maxValue end
    return value
end

local function DG_StuntNameKey(name)
    return tostring(name or ""):lower():gsub("%s+", " ")
end

local DG_STUNT_AGGRESSIVE_NAMES = {
    ["backside flip"] = true,
    ["hardflip"] = true,
    ["inward heelflip"] = true,
    ["laser flip"] = true,
    ["tre flip"] = true,
    ["360 flip"] = true,
    ["varial flip"] = true,
    ["backside 180"] = true,
    ["frontside 180"] = true,
    ["pop shove"] = true,
    ["pop shove-it"] = true,
    ["shove"] = true,
    ["shove-it"] = true,
}

function driftgod.GetStuntSafetyMultiplier(stuntName)
    local key = DG_StuntNameKey(stuntName)
    if DG_STUNT_AGGRESSIVE_NAMES[key] then
        return driftgod.StuntSafety.aggressiveMultiplier or 0.42
    end

    if key:find("flip", 1, true) or key:find("shove", 1, true) or key:find("180", 1, true) or key:find("360", 1, true) then
        return driftgod.StuntSafety.defaultMultiplier or 0.72
    end

    return 1.0
end

function driftgod.SafeStuntVector(x, y, z, stuntName)
    if not driftgod.StuntSafety or driftgod.StuntSafety.enabled ~= true then
        return x, y, z
    end

    local mult = driftgod.GetStuntSafetyMultiplier(stuntName)
    local maxLinear = tonumber(driftgod.StuntSafety.maxLinear or 2.35) or 2.35
    local maxUp = tonumber(driftgod.StuntSafety.maxUp or 0.62) or 0.62
    local maxDown = tonumber(driftgod.StuntSafety.maxDown or -0.45) or -0.45

    x = DG_StuntClamp((tonumber(x or 0.0) or 0.0) * mult, -maxLinear, maxLinear)
    y = DG_StuntClamp((tonumber(y or 0.0) or 0.0) * mult, -maxLinear, maxLinear)
    z = DG_StuntClamp((tonumber(z or 0.0) or 0.0) * mult, maxDown, maxUp)

    return x, y, z
end

function driftgod.SafeStuntScalar(value, stuntName, kind)
    if not driftgod.StuntSafety or driftgod.StuntSafety.enabled ~= true then
        return value
    end

    local mult = driftgod.GetStuntSafetyMultiplier(stuntName)
    local maxAngular = tonumber(driftgod.StuntSafety.maxAngular or 3.25) or 3.25
    local maxLinear = tonumber(driftgod.StuntSafety.maxLinear or 2.35) or 2.35

    local maxValue = maxLinear
    if tostring(kind or ""):lower():find("angular", 1, true) or tostring(kind or ""):lower():find("rot", 1, true) then
        maxValue = maxAngular
    end

    return DG_StuntClamp((tonumber(value or 0.0) or 0.0) * mult, -maxValue, maxValue)
end

function driftgod.ToggleStuntSafety()
    driftgod.StuntSafety = driftgod.StuntSafety or {}
    driftgod.StuntSafety.enabled = not (driftgod.StuntSafety.enabled == true)

    if driftgod.Toast then
        driftgod.Toast("Stunt Safety: " .. (driftgod.StuntSafety.enabled and "ON" or "OFF"), 1400)
    end

    if driftgod.Log then
        driftgod.Log("[Stunts] Safety=" .. tostring(driftgod.StuntSafety.enabled))
    end
end

function driftgod.StuntSafetySofter()
    driftgod.StuntSafety = driftgod.StuntSafety or {}
    driftgod.StuntSafety.aggressiveMultiplier = DG_StuntClamp((tonumber(driftgod.StuntSafety.aggressiveMultiplier or 0.42) or 0.42) - 0.05, 0.20, 1.00)

    if driftgod.Toast then
        driftgod.Toast("Aggressive Stunt Power: " .. string.format("%.2f", driftgod.StuntSafety.aggressiveMultiplier), 1200)
    end
end

function driftgod.StuntSafetyStronger()
    driftgod.StuntSafety = driftgod.StuntSafety or {}
    driftgod.StuntSafety.aggressiveMultiplier = DG_StuntClamp((tonumber(driftgod.StuntSafety.aggressiveMultiplier or 0.42) or 0.42) + 0.05, 0.20, 1.00)

    if driftgod.Toast then
        driftgod.Toast("Aggressive Stunt Power: " .. string.format("%.2f", driftgod.StuntSafety.aggressiveMultiplier), 1200)
    end
end

driftgod.S = driftgod.S or {}
if driftgod.S.stuntDurationPercent == nil then driftgod.S.stuntDurationPercent = 65 end
if driftgod.S.stuntMaxHeight == nil then driftgod.S.stuntMaxHeight = 1 end
