    ["ghetto bird"] = true,
    ["hardflip 180"] = true,
    ["backside heelflip"] = true,
    ["backside flip"] = true,
    ["fingerflip"] = true,
    ["sideways kickflip"] = true,
}

driftgod.StuntPendingLandingFixes = driftgod.StuntPendingLandingFixes or {}

local function DG_StuntCfgClamp(v, mn, mx)
    v = tonumber(v or mn) or mn
    if v < mn then return mn end
    if v > mx then return mx end
    return v
end

local function DG_StuntCfgNameKey(name)
    return tostring(name or ""):lower():gsub("^%s+", ""):gsub("%s+$", ""):gsub("%s+", " ")
end

local function DG_StuntCfgNowMs()
    local ok, t = driftgod.Try(function()
        if Time and Time.GetEpocheMs then return Time.GetEpocheMs() end
    end)
    if ok and t then return tonumber(t) or math.floor(os.clock() * 1000) end

    local ok2, gt = driftgod.Try(function()
        if Natives and Natives.InvokeInt then return Natives.InvokeInt(0x9CD27B0045628463) end
    end)
    if ok2 and gt then return tonumber(gt) or math.floor(os.clock() * 1000) end

    return math.floor(os.clock() * 1000)
end

local function DG_StuntCfgCopyTable(src)
    local dst = {}
    for k, v in pairs(src or {}) do dst[k] = v end
    return dst
end

local function DG_StuntCfgPtrToHandle(ptr)
    if not ptr then return 0 end
    if type(ptr) == "number" then return ptr end

    local h = 0
    driftgod.Try(function()
        if GTA and GTA.PointerToHandle then h = GTA.PointerToHandle(ptr) end
    end)

    return tonumber(h) or 0
end

local function DG_StuntCfgGetVehicle()
    local veh = 0

    driftgod.Try(function()
        if driftgod.GetVehicle then
            veh = DG_StuntCfgPtrToHandle(driftgod.GetVehicle())
        end
    end)

    if veh == 0 then
        driftgod.Try(function()
            local ped = 0
            if PLAYER and PLAYER.PLAYER_PED_ID then
                ped = PLAYER.PLAYER_PED_ID()
            elseif Natives and Natives.InvokeInt then
                ped = Natives.InvokeInt(0xD80958FC74E988A6)
            end

            if ped and ped ~= 0 then
                if PED and PED.GET_VEHICLE_PED_IS_IN then
                    veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
                elseif Natives and Natives.InvokeInt then
                    veh = Natives.InvokeInt(0x9A9112A0FE9A4713, ped, false)
                end
            end
        end)
    end

    return tonumber(veh) or 0
end

local function DG_StuntCfgGetHeading(veh)
    local heading = 0.0

    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_HEADING then
            heading = ENTITY.GET_ENTITY_HEADING(veh)
        elseif Natives and Natives.InvokeFloat then
            heading = Natives.InvokeFloat(0xE83D4F9BA2A38914, veh)
        end
    end)

    return tonumber(heading) or 0.0
end

local function DG_StuntCfgSetHeading(veh, heading)
    heading = tonumber(heading or 0.0) or 0.0

    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_HEADING then
            ENTITY.SET_ENTITY_HEADING(veh, heading)
        elseif Natives and Natives.InvokeVoid then
            Natives.InvokeVoid(0x8E2530AA8ADA980E, veh, heading)
        end
    end)
end

local function DG_StuntCfgSetRotationUpright(veh, heading)
    heading = tonumber(heading or 0.0) or 0.0

    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_ROTATION then
            ENTITY.SET_ENTITY_ROTATION(veh, 0.0, 0.0, heading, 2, true)
        elseif Natives and Natives.InvokeVoid then
            Natives.InvokeVoid(0x8524A8B0171D5E07, veh, 0.0, 0.0, heading, 2, true)
        end
    end)
end

local function DG_StuntCfgSetVelocitySoft(veh)

    driftgod.Try(function()
        if ENTITY and ENTITY.SET_ENTITY_VELOCITY then
            ENTITY.SET_ENTITY_VELOCITY(veh, 0.0, 0.0, 0.0)
        elseif Natives and Natives.InvokeVoid then
            Natives.InvokeVoid(0x1C99BB7B6E96D16F, veh, 0.0, 0.0, 0.0)
        end
