driftgod.StuntHardStopNames = driftgod.StuntHardStopNames or {
    ["backside flip"] = true,
    ["backside heelflip"] = true,
}

driftgod.StuntReverseFinishNames = driftgod.StuntReverseFinishNames or {
    ["fingerflip"] = true,
}

driftgod.StuntLowLandingNames = driftgod.StuntLowLandingNames or {
    ["sideways kickflip"] = true,
}

local function DG_StuntCfgForceGroundSnap(veh)
    if not veh or veh == 0 then return end
    driftgod.Try(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY then
            VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY(veh)
        elseif Natives and Natives.InvokeBool then
            Natives.InvokeBool(0x49733E92263139D1, veh)
        end
    end)
end

local function DG_StuntCfgFreezeBriefly(veh, frozen)
    if not veh or veh == 0 then return end
    driftgod.Try(function()
        if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then
            ENTITY.FREEZE_ENTITY_POSITION(veh, frozen == true)
        elseif Natives and Natives.InvokeVoid then
            Natives.InvokeVoid(0x428CA6DBD1094446, veh, frozen == true)
        end
    end)
end

function driftgod.GetStuntFinishHeading(trick, startHeading)
    local key = DG_StuntCfgNameKey(trick and trick.name)
    local heading = tonumber(startHeading or 0.0) or 0.0

    if driftgod.StuntReverseFinishNames[key] == true then
        heading = (heading + 180.0) % 360.0
    end

    return heading
end

function driftgod.GetStuntFinishMode(trick)
    local key = DG_StuntCfgNameKey(trick and trick.name)

    if driftgod.StuntHardStopNames[key] == true then return "hard_stop" end
    if driftgod.StuntLowLandingNames[key] == true then return "low_landing" end

    return "normal"
end

function driftgod.ApplyStuntCleanup()
    if driftgod._StuntCleanupApplied == true then return end
    if type(driftgod.Tricks) ~= "table" then return end

    local cleaned = {}
    local removed = {}

    for _, trick in ipairs(driftgod.Tricks or {}) do
        local key = DG_StuntCfgNameKey(trick and trick.name)
        if driftgod.StuntDeletedNames[key] == true then
            table.insert(removed, tostring(trick.name or key))
        else
            table.insert(cleaned, trick)
        end
    end

    driftgod.Tricks = cleaned
    driftgod._StuntCleanupApplied = true

    if driftgod.Log and #removed > 0 then

    end
end

local function DG_StuntCfgScaleNumber(v, scalar)
    if type(v) ~= "number" then return v end
    return math.floor((v * scalar) + 0.5)
end

function driftgod.BuildConfiguredStuntMeta(trick)
    if type(trick) ~= "table" then return trick end

    local patched = DG_StuntCfgCopyTable(trick)
    local durationScalar = DG_StuntCfgClamp(((tonumber(driftgod.GetEffectiveStuntDurationPercent and driftgod.GetEffectiveStuntDurationPercent(trick and trick.name or patched.name) or driftgod.S.stuntDurationPercent or 65) or 100) / 100.0), 0.50, 1.25)
    local maxHeight = DG_StuntCfgClamp(tonumber(driftgod.S.stuntMaxHeight or 1) or 8, 1, 25)

    local durationFields = {
        "duration", "durationMs", "time", "timeMs", "flipDuration", "flip_duration", "trickDuration", "trick_duration", "ms"
    }

    for _, field in ipairs(durationFields) do
        if type(patched[field]) == "number" then
            patched[field] = DG_StuntCfgScaleNumber(patched[field], durationScalar)
        end
    end

    local trickKeyForHeight = DG_StuntCfgNameKey(patched.name)
    if driftgod.StuntLowLandingNames and driftgod.StuntLowLandingNames[trickKeyForHeight] == true then
        maxHeight = math.min(maxHeight, 1)
        for _, field in ipairs({"jump", "jumpForce", "jump_force", "jumpHeight", "jump_height", "lift", "liftForce", "upForce", "upwardForce", "launch", "launchForce", "height"}) do
            if type(patched[field]) == "number" then patched[field] = math.min(patched[field], 1) end
        end
    end

    local heightFields = {
        "jump", "jumpForce", "jump_force", "jumpHeight", "jump_height", "lift", "liftForce", "upForce", "upwardForce", "launch", "launchForce", "height"
    }

    for _, field in ipairs(heightFields) do
        if type(patched[field]) == "number" then
            patched[field] = math.min(patched[field], maxHeight)
        end
    end

    if type(patched.force) == "table" then
        patched.force = DG_StuntCfgCopyTable(patched.force)
        if type(patched.force.z) == "number" then patched.force.z = math.min(patched.force.z, maxHeight) end
        if type(patched.force[3]) == "number" then patched.force[3] = math.min(patched.force[3], maxHeight) end
    end

    if type(patched.velocity) == "table" then
        patched.velocity = DG_StuntCfgCopyTable(patched.velocity)
        if type(patched.velocity.z) == "number" then patched.velocity.z = math.min(patched.velocity.z, maxHeight) end
        if type(patched.velocity[3]) == "number" then patched.velocity[3] = math.min(patched.velocity[3], maxHeight) end
    end

    return patched
end

function driftgod.ScheduleStuntLandingFix(trick, startVeh, startHeading)
    if driftgod.S.stuntLandingFixEnabled ~= true then return end
    if type(trick) ~= "table" then return end

    local key = DG_StuntCfgNameKey(trick.name)
    if driftgod.StuntOrientationFixNames[key] ~= true then return end

    local duration = tonumber(trick.durationMs or trick.duration or trick.flipDuration or trick.flip_duration or trick.timeMs or trick.time or 1500) or 1500
    local when = DG_StuntCfgNowMs() + DG_StuntCfgClamp(duration + 250, 500, 5000)

    table.insert(driftgod.StuntPendingLandingFixes, {
        name = tostring(trick.name or key),
        veh = tonumber(startVeh or 0) or 0,
        heading = driftgod.GetStuntFinishHeading and driftgod.GetStuntFinishHeading(trick, startHeading) or (tonumber(startHeading or 0.0) or 0.0),
        mode = driftgod.GetStuntFinishMode and driftgod.GetStuntFinishMode(trick) or "normal",
        at = when,
        tries = 0,
    })
end

function driftgod.ProcessStuntLandingFixes()
    if driftgod.S.stuntLandingFixEnabled ~= true then return end

    local now = DG_StuntCfgNowMs()
    local keep = {}

    for _, fix in ipairs(driftgod.StuntPendingLandingFixes or {}) do
        if now >= (fix.at or 0) then
            local veh = tonumber(fix.veh or 0) or 0
            if veh == 0 then veh = DG_StuntCfgGetVehicle() end

            if veh ~= 0 then
                local finishHeading = tonumber(fix.heading or 0.0) or 0.0
                local finishMode = tostring(fix.mode or "normal")

                DG_StuntCfgSetRotationUpright(veh, finishHeading)
                DG_StuntCfgSetHeading(veh, finishHeading)

                if finishMode == "hard_stop" then
                    DG_StuntCfgSetVelocitySoft(veh)
                    DG_StuntCfgFreezeBriefly(veh, true)
                    DG_StuntCfgForceGroundSnap(veh)
                    DG_StuntCfgFreezeBriefly(veh, false)
                elseif finishMode == "low_landing" then
                    DG_StuntCfgSetVelocitySoft(veh)
                    DG_StuntCfgForceGroundSnap(veh)
                else
                    DG_StuntCfgSetVelocitySoft(veh)
                end
            end

            fix.tries = (fix.tries or 0) + 1

            if fix.tries < 3 then
                fix.at = now + 180
                table.insert(keep, fix)
            end
        else
            table.insert(keep, fix)
        end
    end

    driftgod.StuntPendingLandingFixes = keep
end

function driftgod.InstallStuntConfigWrapper()
    if driftgod._StuntConfigWrapperInstalled == true then return end
    if type(driftgod.RunTrickMeta) ~= "function" then return end

    driftgod._OriginalRunTrickMeta_StuntConfig = driftgod.RunTrickMeta

    driftgod.RunTrickMeta = function(trick)
        driftgod.ApplyStuntCleanup()

        local veh = DG_StuntCfgGetVehicle()
        local heading = DG_StuntCfgGetHeading(veh)

        local patched = driftgod.BuildConfiguredStuntMeta(trick)
        local result = driftgod._OriginalRunTrickMeta_StuntConfig(patched)

        driftgod.ScheduleStuntLandingFix(patched, veh, heading)

        return result
    end

    driftgod._StuntConfigWrapperInstalled = true

    if driftgod.Log then

    end
end

function driftgod.SetStuntDurationPercent(value)
    driftgod.S = driftgod.S or {}
    driftgod.S.stuntDurationPercent = math.floor(DG_StuntCfgClamp(value, 50, 200))
    if driftgod.Toast then driftgod.Toast("Stunt Duration: " .. tostring(driftgod.S.stuntDurationPercent) .. "%", 1200) end
    if driftgod.SaveSettings then driftgod.SaveSettings(false) end
end

function driftgod.SetStuntMaxHeight(value)
    driftgod.S = driftgod.S or {}
    driftgod.S.stuntMaxHeight = math.floor(DG_StuntCfgClamp(value, 1, 25))
    if driftgod.Toast then driftgod.Toast("Stunt Max Height: " .. tostring(driftgod.S.stuntMaxHeight), 1200) end
    if driftgod.SaveSettings then driftgod.SaveSettings(false) end
end

function driftgod.ToggleStuntLandingFix()
    driftgod.S = driftgod.S or {}
    driftgod.S.stuntLandingFixEnabled = not (driftgod.S.stuntLandingFixEnabled == true)
    if driftgod.Toast then driftgod.Toast("Stunt Landing Fix: " .. (driftgod.S.stuntLandingFixEnabled and "ON" or "OFF"), 1400) end
    if driftgod.SaveSettings then driftgod.SaveSettings(false) end
end

driftgod.Try(function()
    driftgod.ApplyStuntCleanup()
    driftgod.InstallStuntConfigWrapper()
end)

driftgod.Try(function()
    if Script and Script.RegisterLooped then
        Script.RegisterLooped(function()
            if ShouldUnload and ShouldUnload() then return false end
            if DG and driftgod._StuntCleanupApplied ~= true and driftgod.ApplyStuntCleanup then driftgod.ApplyStuntCleanup() end
            if DG and driftgod._StuntConfigWrapperInstalled ~= true and driftgod.InstallStuntConfigWrapper then driftgod.InstallStuntConfigWrapper() end
            local active = driftgod.S and driftgod.S.stuntLandingFixEnabled == true and type(driftgod.StuntPendingLandingFixes) == "table" and #driftgod.StuntPendingLandingFixes > 0
            if active and DG and driftgod.ProcessStuntLandingFixes then driftgod.ProcessStuntLandingFixes() end
            if Script and Script.Yield then Script.Yield(active and 0 or 100) end
        end)
    elseif FeatureMgr and FeatureMgr.AddFeature and Utils and Utils.Joaat and eFeatureType then
        driftgod.SafeAddFeature(Utils.Joaat("DG_STUNT_CONFIG_TICK_V61298"), "DriftGod Stunt Config Tick", eFeatureType.Script, "", function()
            if DG and driftgod.ApplyStuntCleanup then driftgod.ApplyStuntCleanup() end
            if DG and driftgod.InstallStuntConfigWrapper then driftgod.InstallStuntConfigWrapper() end
            if DG and driftgod.ProcessStuntLandingFixes then driftgod.ProcessStuntLandingFixes() end
        end)
    end
end)

driftgod.StuntQuickMenu = driftgod.StuntQuickMenu or {}

local SQM = driftgod.StuntQuickMenu

SQM.open = SQM.open or false
SQM.selected = SQM.selected or 1
SQM.scroll = SQM.scroll or 0
SQM.lastKeys = SQM.lastKeys or {}
SQM.inputLockUntil = SQM.inputLockUntil or 0

local VK = {
    UP = 0x26,
    DOWN = 0x28,
    LEFT = 0x25,
    RIGHT = 0x27,
    ENTER = 0x0D,
    DELETE = 0x2E,
    HOME = 0x24
}

local function clamp(v, lo, hi)
    v = tonumber(v) or lo
    if v < lo then return lo end
    if v > hi then return hi end
    return v
end

local function nowMs()
    local ok, t = driftgod.Try(function() return Time.GetEpocheMs() end)
    if ok and t then return t end
    local ok2, gt = driftgod.Try(Natives.InvokeInt, 0x9CD27B0045628463)
    return ok2 and gt or math.floor(os.clock() * 1000)
end

local function keyJustPressed(vk)
    local ok, pressed = driftgod.Try(Utils.IsKeyPressed, vk)
    pressed = ok and pressed == true
    local was = SQM.lastKeys[vk] or false
    SQM.lastKeys[vk] = pressed
    return pressed and not was
end

local HUD = HUD or {}
HUD.SET_TEXT_FONT = HUD.SET_TEXT_FONT or function(...) return Natives.InvokeVoid(0x66E0276CC5F6B9DA, ...) end
