local GRAPHICS = GRAPHICS or {}
GRAPHICS.SET_SCRIPT_GFX_DRAW_ORDER = GRAPHICS.SET_SCRIPT_GFX_DRAW_ORDER or function(...) return Natives.InvokeVoid(0x61BB1D9B3A95D802, ...) end
GRAPHICS.SET_SCRIPT_GFX_DRAW_BEHIND_PAUSEMENU = GRAPHICS.SET_SCRIPT_GFX_DRAW_BEHIND_PAUSEMENU or function(...) return Natives.InvokeVoid(0xC6372ECD45D73BCD, ...) end
GRAPHICS.DRAW_RECT = GRAPHICS.DRAW_RECT or function(...) return Natives.InvokeVoid(0x3A618A217E5154F0, ...) end

