local function drawRect(x, y, w, h, r, g, b, a)
    driftgod.Try(GRAPHICS.SET_SCRIPT_GFX_DRAW_ORDER, 7)
    driftgod.Try(GRAPHICS.SET_SCRIPT_GFX_DRAW_BEHIND_PAUSEMENU, true)
    driftgod.Try(GRAPHICS.DRAW_RECT, x, y, w, h, r, g, b, a, 0)
end

local function drawText(text, x, y, scale, r, g, b, a, justify)
    text = tostring(text or "")
    if #text > 34 then text = text:sub(1, 31) .. "..." end

    driftgod.Try(HUD.SET_TEXT_FONT, 4)
    driftgod.Try(HUD.SET_TEXT_SCALE, 0.0, scale or 0.285)
    driftgod.Try(HUD.SET_TEXT_COLOUR, r or 255, g or 255, b or 255, a or 255)
    driftgod.Try(HUD.SET_TEXT_WRAP, 0.0, 1.0)
    driftgod.Try(HUD.SET_TEXT_CENTRE, justify == 0)
    if justify == 2 then driftgod.Try(HUD.SET_TEXT_RIGHT_JUSTIFY, true) end
    driftgod.Try(HUD.SET_TEXT_JUSTIFICATION, justify or 1)
    driftgod.Try(HUD.SET_TEXT_OUTLINE)
    driftgod.Try(HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT, "STRING")
    driftgod.Try(HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME, text)
    driftgod.Try(HUD.END_TEXT_COMMAND_DISPLAY_TEXT, x, y, 0)
end

local function playSound(name)
    driftgod.Try(AUDIO.PLAY_DEFERRED_SOUND_FRONTEND, name or "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET")
end

local function isInAnyVehicle()
    if driftgod.IsInVehicle then
        local ok, result = driftgod.Try(driftgod.IsInVehicle)
        if ok then return result == true end
    end

    if driftgod.IsDrivingVehicle then
        local ok, result = driftgod.Try(driftgod.IsDrivingVehicle)
        if ok then return result == true end
    end

    if driftgod.GetVehicle then
        local ok, veh = driftgod.Try(driftgod.GetVehicle)
        if ok and veh and veh ~= 0 then return true end
    end

    return false
end

local function blockPhoneControls()

    local controls = {
        27, 176, 177, 178, 179, 199, 200, 201, 202,
        172, 173, 174, 175,
        24, 25, 69, 70, 92, 106, 114, 140, 141, 142, 257, 263, 264
    }

    for _, control in ipairs(controls) do
        driftgod.Try(PAD.DISABLE_CONTROL_ACTION, 0, control, true)
    end

    driftgod.Try(PAD.SET_INPUT_EXCLUSIVE, 0, 172)
    driftgod.Try(PAD.SET_INPUT_EXCLUSIVE, 0, 173)
    driftgod.Try(PAD.SET_INPUT_EXCLUSIVE, 0, 174)
    driftgod.Try(PAD.SET_INPUT_EXCLUSIVE, 0, 175)
    driftgod.Try(PAD.SET_INPUT_EXCLUSIVE, 0, 176)
    driftgod.Try(PAD.SET_INPUT_EXCLUSIVE, 0, 177)
end

local function visibleCount()
    return math.min(tonumber(driftgod.S.stuntQuickMenuMaxOptions or 6) or 6, 8)
end

local function unlockedTricks()
    if driftgod.GetUnlockedTricks then
        return driftgod.GetUnlockedTricks()
    end
    return driftgod.Tricks or {}
end

local function stuntCount()
    return #unlockedTricks()
end

local function normalizeSelection()
    local count = stuntCount()
    if count <= 0 then
        SQM.selected = 1
        SQM.scroll = 0
        return
    end

    SQM.selected = clamp(SQM.selected or 1, 1, count)

    local maxRows = visibleCount()
    if SQM.selected <= SQM.scroll then
        SQM.scroll = SQM.selected - 1
    elseif SQM.selected > SQM.scroll + maxRows then
        SQM.scroll = SQM.selected - maxRows
    end

    SQM.scroll = clamp(SQM.scroll or 0, 0, math.max(0, count - maxRows))
end

function driftgod.OpenStuntQuickMenu()
    if not isInAnyVehicle() then
        SQM.open = false
        playSound("ERROR")
        if driftgod.Toast then driftgod.Toast("Stunt Quick Menu only opens inside a vehicle.", 2000) end
        return
    end

    SQM.open = true
    SQM.selected = clamp(SQM.selected or 1, 1, math.max(1, stuntCount()))
    SQM.inputLockUntil = nowMs() + 220
    normalizeSelection()
    playSound("SELECT")
    if driftgod.Toast then driftgod.Toast("Stunt Quick Menu opened.", 1500) end
end

function driftgod.CloseStuntQuickMenu()
    SQM.open = false
    playSound("BACK")
end

function driftgod.ToggleStuntQuickMenu()
    if SQM.open then
        driftgod.CloseStuntQuickMenu()
    else
        driftgod.OpenStuntQuickMenu()
    end
end

local function runSelectedStunt()
    local trick = unlockedTricks()[SQM.selected]

    if not trick then
        playSound("ERROR")
        return
    end

    playSound("SELECT")

    if driftgod.RunTrickMeta then
        driftgod.RunTrickMeta(trick)
    elseif trick.fn then
        trick.fn()
    end

end

local function handleInput()
    if nowMs() < (SQM.inputLockUntil or 0) then return end

    local count = stuntCount()
    if count <= 0 then
        if keyJustPressed(VK.DELETE) or keyJustPressed(VK.LEFT) then driftgod.CloseStuntQuickMenu() end
        return
    end

    if keyJustPressed(VK.UP) then
        SQM.selected = SQM.selected - 1
        if SQM.selected < 1 then SQM.selected = count end
        normalizeSelection()
        playSound("NAV_UP_DOWN")
    elseif keyJustPressed(VK.DOWN) then
        SQM.selected = SQM.selected + 1
        if SQM.selected > count then SQM.selected = 1 end
        normalizeSelection()
        playSound("NAV_UP_DOWN")
    elseif keyJustPressed(VK.ENTER) or keyJustPressed(VK.RIGHT) then
        runSelectedStunt()
    elseif keyJustPressed(VK.DELETE) or keyJustPressed(VK.LEFT) then
        driftgod.CloseStuntQuickMenu()
    end
end

local function render()
    local x, y
    if driftgod.GetStuntQuickMenuPosition then
        x, y = driftgod.GetStuntQuickMenuPosition(0.085, 0.560)
    else
        x = tonumber(driftgod.S.stuntQuickMenuX or driftgod.S.stuntHudX) or 0.085
        y = tonumber(driftgod.S.stuntQuickMenuY or driftgod.S.stuntHudY) or 0.560
    end
    local width = tonumber(driftgod.S.stuntQuickMenuWidth) or 0.128
    local rows = visibleCount()
    local rowH = 0.026
    local headerH = 0.040
    local subH = 0.024
    local footerH = 0.024
    local height = headerH + subH + (rows * rowH) + footerH
    local opacity = tonumber(driftgod.S.stuntQuickMenuOpacity) or 0.50
    opacity = clamp(opacity, 0.10, 1.00)
    local alpha = math.floor(255 * opacity)
    local panelAlpha = math.floor(220 * opacity)
    local headerAlpha = math.floor(240 * opacity)
    local rowAlpha = math.floor(205 * opacity)
    local selectedAlpha = math.floor(220 * opacity)
    local footerAlpha = math.floor(235 * opacity)
    local glowAlpha = math.floor(85 * opacity)

    local top = y
    local cx = x
    local left = cx - width / 2
    local right = cx + width / 2

    drawRect(cx, top + height / 2, width + 0.006, height + 0.006, 120, 35, 255, glowAlpha)
    drawRect(cx, top + height / 2, width, height, 5, 5, 11, panelAlpha)

    drawRect(cx, top + headerH / 2, width, headerH, 78, 0, 205, headerAlpha)
    drawRect(cx, top + headerH + subH / 2, width, subH, 0, 0, 0, panelAlpha)

    drawText("DRIFTGOD STUNTS", cx, top + 0.006, 0.245, 255, 255, 255, 255, 0)
    drawText("STUNT SELECTOR", left + 0.009, top + headerH + 0.004, 0.195, 220, 220, 235, 240, 1)
    local count = stuntCount()
    if count <= 0 then
        drawText("No stunts loaded", left + 0.010, top + headerH + subH + 0.010, 0.270, 255, 120, 120, 240, 1)
    else
        normalizeSelection()
    for i = 1, rows do
            local stuntIndex = SQM.scroll + i
            local trick = unlockedTricks()[stuntIndex]
            local rowY = top + headerH + subH + ((i - 0.5) * rowH)

            if trick then
                local selected = stuntIndex == SQM.selected

                if selected then
                    drawRect(cx, rowY, width - 0.010, rowH - 0.002, 170, 0, 255, selectedAlpha)
                else
                    drawRect(cx, rowY, width - 0.010, rowH - 0.002, 9, 7, 16, rowAlpha)
                end

                local label = tostring(trick.name or ("Stunt " .. tostring(stuntIndex)))
                if #label > 18 then label = label:sub(1, 15) .. "..." end
                drawText(label, left + 0.009, rowY - 0.010, 0.225, 245, 245, 255, 245, 1)
                if selected then
                    drawText("›", right - 0.010, rowY - 0.010, 0.230, 255, 255, 255, 245, 2)
                end
            end
        end
    end

    local footerY = top + height - footerH / 2
    drawRect(cx, footerY, width, footerH, 0, 0, 3, footerAlpha)
    drawText("ENTER", cx, footerY - 0.009, 0.180, 220, 220, 235, 235, 0)
end

local function handleHomeHotkey()
    if driftgod.S.stuntQuickMenuHomeHotkey == false then return end

    if keyJustPressed(VK.HOME) then
        if SQM.open then
            driftgod.CloseStuntQuickMenu()
            return
        end

        driftgod.OpenStuntQuickMenu()
    end
end

function driftgod.StuntQuickMenuTick()
    if driftgod.S.stuntQuickMenuEnabled == false then return end

    handleHomeHotkey()

    if not SQM.open then return end

    if not isInAnyVehicle() then
        SQM.open = false
        return
    end

    blockPhoneControls()
    handleInput()
    render()
end

return DG
end

local function __DG_BOOT_REQUIRE(name, required)
    local ok, res = driftgod.Try(require, name)
    if not ok then
        local msg = "[ProductionBundle] Failed to load " .. tostring(name) .. ": " .. tostring(res)
        if Logger and Logger.LogError then Logger.LogError(msg) elseif Logger and Logger.LogInfo then Logger.LogInfo(msg) elseif log then log(msg) else print(msg) end
        if required then error(res, 2) end
        return nil, res
    end
    return res
end

