function driftgod.A51R27NowMs()
    if driftgod.A51R19NowMs then return tonumber(driftgod.A51R19NowMs() or 0) or 0 end
    if driftgod.A18NowMs then return tonumber(driftgod.A18NowMs() or 0) or 0 end
