function driftgod.A51R27DrawText(text, x, y, scale, r, g, b, a, font)
    text = tostring(text or '')
    if text == '' then return true end
    x = tonumber(x or 0.5) or 0.5
    y = tonumber(y or 0.5) or 0.5
    scale = tonumber(scale or 0.30) or 0.30
    r = tonumber(r or 255) or 255
    g = tonumber(g or 255) or 255
    b = tonumber(b or 255) or 255
    a = tonumber(a or 255) or 255
    font = tonumber(font or 4) or 4

    if ImGui and (ImGui.FgAddText or ImGui.BgAddText) then
        local sw, sh = 1920, 1080
        driftgod.Try(function()
            if ImGui.GetDisplaySize then
                local w, h = ImGui.GetDisplaySize()
                if tonumber(w) then sw = tonumber(w) end
                if tonumber(h) then sh = tonumber(h) end
            end
        end)
        local px, py = x * sw, y * sh
        local ok = driftgod.Try(function()
            if ImGui.FgAddText then ImGui.FgAddText(px, py, r, g, b, a, text)
            else ImGui.BgAddText(px, py, r, g, b, a, text) end
        end)
        if ok then return true end
    end

    if driftgod.DrawText then
        driftgod.Try(function() driftgod.DrawText(text, x, y, scale, r, g, b, a, font) end)
        return true
    end
    if driftgod.A51R19DrawText then return driftgod.A51R19DrawText(text, x, y, scale, r, g, b, a, font) end
    return false
end

function driftgod.A51R27CountdownText(now)
    now = tonumber(now or driftgod.A51R27NowMs()) or 0
    local start = tonumber(driftgod.S and (driftgod.S.driftChallengeCountdownStartMs or driftgod.S.driftChallengeCountdownStartedMs) or now) or now
    local elapsed = now - start
    if elapsed < 1000 then return '3' end
    if elapsed < 2000 then return '2' end
    if elapsed < 3000 then return '1' end
    if elapsed < 4200 then return 'GO!' end
    return ''
end

function driftgod.A51R27GetRaceUiCache(now)
    driftgod.S = driftgod.S or {}
    now = tonumber(now or driftgod.A51R27NowMs()) or 0
    local cache = driftgod.S.driftChallengeRaceUiCache
    if type(cache) ~= 'table' then cache = {}; driftgod.S.driftChallengeRaceUiCache = cache end
    local cacheMs = tonumber(driftgod.S.driftChallengeRaceUiCacheMs or 120) or 120
    if (tonumber(cache.lastUpdateMs or 0) or 0) + cacheMs > now then return cache end
    cache.lastUpdateMs = now

    if driftgod.S.driftChallengeActive == true then
        if driftgod.GetDriftChallengeLiveScore then driftgod.Try(function() driftgod.S.driftChallengeLivePoints = driftgod.GetDriftChallengeLiveScore() end) end
        if driftgod.GetDriftChallengeLiveStunts then driftgod.Try(function() driftgod.S.driftChallengeLiveStunts = driftgod.GetDriftChallengeLiveStunts() end) end
    end

    local cps = driftgod.S.ghostRecordingCheckpoints or {}
    local idx = tonumber(driftgod.S.driftChallengeCheckpointIndex or 1) or 1
    if idx < 1 then idx = 1 end
    cache.youPoints = math.floor(tonumber(driftgod.S.driftChallengeLivePoints or 0) or 0)
    cache.youStunts = math.floor(tonumber(driftgod.S.driftChallengeLiveStunts or 0) or 0)
    cache.rivalPoints = math.floor(tonumber(driftgod.S.driftChallengeTargetPoints or 0) or 0)
    cache.rivalStunts = math.floor(tonumber(driftgod.S.driftChallengeTargetStunts or 0) or 0)
    cache.cpIndex = math.min(idx, #cps)
    cache.cpCount = #cps
    cache.ghostStatus = tostring(driftgod.S.driftChallengeGhostPlaybackStatus or '')
    return cache
end

function driftgod.A51R27DrawRaceHudStable(source)
    driftgod.S = driftgod.S or {}
    local now = driftgod.A51R27NowMs()
    local hasCountdown = driftgod.S.driftChallengeCountdownActive == true
    local hasRace = driftgod.S.driftChallengeActive == true
    local hasResult = (tonumber(driftgod.S.driftChallengeResultVisibleUntil or 0) or 0) > now
    if not hasCountdown and not hasRace and not hasResult then return true end

    local minMs = tonumber(driftgod.S.driftChallengeRaceRenderMinMs or 12) or 12
    local last = tonumber(driftgod.S.driftChallengeRaceLastRenderMs or 0) or 0
    if last > 0 and (now - last) < minMs then return true end
    driftgod.S.driftChallengeRaceLastRenderMs = now

    if hasCountdown then
        local txt = driftgod.A51R27CountdownText(now)
        if txt ~= '' then
            local scale = txt == 'GO!' and 1.05 or 1.25
            local r,g,b = 255,255,255
            if txt == 'GO!' then r,g,b = 120,255,180 end
            driftgod.A51R27DrawText(txt, 0.50, 0.34, scale, r,g,b,255,7)
        end
    end

    if hasRace then
        local c = driftgod.A51R27GetRaceUiCache(now)
        driftgod.A51R27DrawText('DRIFT RACE', 0.50, 0.105, 0.34, 166,94,252,235,4)
        driftgod.A51R27DrawText('YOU: ' .. tostring(c.youPoints or 0) .. ' pts  |  ' .. tostring(c.youStunts or 0) .. ' stunts', 0.50, 0.145, 0.28, 255,255,255,220,4)
        driftgod.A51R27DrawText('RIVAL: ' .. tostring(c.rivalPoints or 0) .. ' pts  |  ' .. tostring(c.rivalStunts or 0) .. ' stunts', 0.50, 0.178, 0.26, 220,220,220,205,4)
        if (tonumber(c.cpCount or 0) or 0) > 0 then
            driftgod.A51R27DrawText('Checkpoint: ' .. tostring(c.cpIndex or 1) .. ' / ' .. tostring(c.cpCount or 0), 0.50, 0.210, 0.25, 166,94,252,215,4)
        end
        if tostring(c.ghostStatus or '') ~= '' then
            driftgod.A51R27DrawText('Ghost: ' .. tostring(c.ghostStatus), 0.50, 0.238, 0.22, 180,180,180,170,4)
        end
    end

    if hasResult then
        local result = driftgod.S.driftChallengeLastResult or {}
        local dnf = result.didNotFinish == true or tostring(driftgod.S.driftChallengeStatus or ''):lower():find('did not finish', 1, true) ~= nil
        local won = result.won == true and not dnf
        local label = dnf and 'DID NOT FINISH' or (won and 'YOU WON!' or 'YOU FAILED')
        local r,g,b = won and 120 or 255, won and 255 or 75, won and 180 or 75
        driftgod.A51R27DrawText(label, 0.50, 0.34, 0.88, r,g,b,255,7)
        driftgod.A51R27DrawText('You: ' .. tostring(result.points or 0) .. ' pts / ' .. tostring(result.stunts or 0) .. ' stunts', 0.50, 0.405, 0.33, 255,255,255,230,4)
        driftgod.A51R27DrawText('Rival: ' .. tostring(result.targetPoints or 0) .. ' pts / ' .. tostring(result.targetStunts or 0) .. ' stunts', 0.50, 0.445, 0.30, 166,94,252,230,4)
        if result.phrase and tostring(result.phrase) ~= '' then driftgod.A51R27DrawText(tostring(result.phrase), 0.50, 0.495, 0.28, 255,255,255,210,4) end
    end
    return true
end

