function driftgod.PlayRecordedGhostSmoothRaceInterpolated()
    if not driftgod.S then return false end
    local originalSteps = driftgod.S.ghostRecordedSmoothSteps
    local steps = tonumber(driftgod.S.driftChallengeGhostSmoothSteps or originalSteps or 2) or 2
    if steps < 1 then steps = 1 end
    if steps > 8 then steps = 8 end
    driftgod.S.ghostRecordedSmoothSteps = steps
    driftgod.S.driftChallengeGhostPlaybackStatus = 'Playing smooth ' .. tostring(steps) .. 'x'
    local ok, result = driftgod.Try(function()
        if driftgod.PlayRecordedGhostSmooth then return driftgod.PlayRecordedGhostSmooth() end
        if driftgod.PlayRecordedGhostInMemory then return driftgod.PlayRecordedGhostInMemory() end
        return false
    end)
    driftgod.S.ghostRecordedSmoothSteps = originalSteps
    driftgod.S.driftChallengeGhostPlaybackStatus = (ok and result == true) and 'Complete' or 'Playback Failed'
    return ok and result == true
end

function driftgod.StartDriftChallengeGhostPlaybackJob()
    if not driftgod.S then driftgod.S = {} end
    if driftgod.S.driftChallengeGhostPlaybackQueued == true then return true end
    driftgod.S.driftChallengeGhostPlaybackQueued = true
    driftgod.S.driftChallengeGhostPlaybackStarted = true
    driftgod.S.driftChallengeGhostPlaybackStatus = 'Queued smooth ' .. tostring(tonumber(driftgod.S.driftChallengeGhostSmoothSteps or 2) or 2) .. 'x'
    driftgod.S.ghostReplayStopRequested = false
    local function runPlayback()
        if driftgod.EnsureDriftChallengeGhostReady then driftgod.Try(driftgod.EnsureDriftChallengeGhostReady) end
        return driftgod.PlayRecordedGhostSmoothRaceInterpolated and driftgod.PlayRecordedGhostSmoothRaceInterpolated() or false
    end
    if Script and Script.QueueJob then Script.QueueJob(runPlayback); return true end
    return runPlayback()
end

