    if score >= 3000 then return false end
    if driftgod.S.activeArcadeDriftPreset == "corner_magnet" then return true end
    if driftgod.ApplyArcadeDriftPreset then
        local ok = driftgod.Try(function() driftgod.ApplyArcadeDriftPreset("corner_magnet", false) end)
        if ok then
            driftgod.S.activeStartupPreset = "DriftGod"
            driftgod.S.accelAssistEnabled = false
            driftgod.S.momentumAssistEnabled = false
            driftgod.S.driftGodStarterTrialDefaultApplied = true
            if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end

            return true
        end
    end
    return false
end

