local dgR68OriginalGetVehicleSectorInfo = driftgod.GetVehicleSectorInfo

local function dgR68FindSuperThreshold()
    for _, sector in ipairs(driftgod.VehicleSectorUnlocks or {}) do
        if sector and tostring(sector.id or "") == "super" then
            return tonumber(sector.threshold or driftgod.VehicleSectorSuperUnlockScore or 25000) or 25000
        end
    end
    return tonumber(driftgod.VehicleSectorSuperUnlockScore or 25000) or 25000
end

local toreroXOHashesR68 = nil
local function dgR68GetToreroXOHashes()
    if toreroXOHashesR68 then return toreroXOHashesR68 end
    toreroXOHashesR68 = {}
    local candidates = { "torero2", "toreroxo", "torero xo", 4129572538, -165394758 }
    for _, c in ipairs(candidates) do
        local h = nil
        if type(c) == "number" then
            h = c
        else
            driftgod.Try(function()
                if GAMEPLAY and GAMEPLAY.GET_HASH_KEY then h = GAMEPLAY.GET_HASH_KEY(c)
                elseif MISC and MISC.GET_HASH_KEY then h = MISC.GET_HASH_KEY(c) end
            end)
            if (not h or h == 0) and driftgod.JoaatVehicleHash then
                driftgod.Try(function() h = driftgod.JoaatVehicleHash(c) end)
            end
        end
        local n = tonumber(h)
        if n and n ~= 0 then
            toreroXOHashesR68[tostring(n)] = true
            if n < 0 then toreroXOHashesR68[tostring(n + 4294967296)] = true end
            if n > 2147483647 then toreroXOHashesR68[tostring(n - 4294967296)] = true end
        end
    end
    return toreroXOHashesR68
end

function driftgod.IsStarterToreroXOVehicle(veh)
    local model = driftgod.GetVehicleModelSafe and driftgod.GetVehicleModelSafe(veh) or 0
    if not model or model == 0 then return false end
    local hashes = dgR68GetToreroXOHashes()
    if hashes[tostring(model)] == true then return true end
    local name = nil
    driftgod.Try(function()
        if driftgod.ResolveVehicleDisplayNameFromModel then name = driftgod.ResolveVehicleDisplayNameFromModel(model) end
    end)
    name = tostring(name or ""):lower()
    return name:find("torero", 1, true) ~= nil and (name:find("xo", 1, true) ~= nil or name:find("torero2", 1, true) ~= nil)
end

function driftgod.GetVehicleSectorInfo(veh)

    if not dgR68OriginalGetVehicleSectorInfo then
        return { ok = true, reason = "no_original_vehicle_sector_gate" }
    end

    driftgod.VehicleSectorsEnsureDefaults()
    veh = veh or (driftgod.GetVehicle and driftgod.GetVehicle() or 0)
    if not veh or veh == 0 then
        return dgR68OriginalGetVehicleSectorInfo(veh)
    end

    local score = driftgod.GetVehicleSectorProgressScore and driftgod.GetVehicleSectorProgressScore() or dgR68BestRunScore()
    score = math.floor(tonumber(score or 0) or 0)
    local superNeed = dgR68FindSuperThreshold()
    local superUnlocked = score >= superNeed
    local classId = driftgod.GetVehicleClassSafe and driftgod.GetVehicleClassSafe(veh) or -1

    if driftgod.IsStarterToreroXOVehicle and driftgod.IsStarterToreroXOVehicle(veh) then
        local cap = tonumber(driftgod.VehicleSectorToreroXOTrialCap or 5000) or 5000
        if score < cap or superUnlocked then
            return { ok = true, reason = superUnlocked and "torero_xo_super_unlocked" or "torero_xo_trial", classId = classId, label = "Torero XO Trial", threshold = cap, score = score, starter = true, starterCap = cap, superThreshold = superNeed }
        end
        return { ok = false, reason = "torero_xo_trial_expired", noHud = true, classId = classId, label = "Torero XO Trial Expired", threshold = superNeed, score = score, starter = true, starterCap = cap, superThreshold = superNeed }
    end

    if driftgod.IsStarterZentornoVehicle and driftgod.IsStarterZentornoVehicle(veh) then
        local cap = tonumber(driftgod.VehicleSectorZentornoTrialCap or 10000) or 10000
        if score < cap or superUnlocked then
            return { ok = true, reason = superUnlocked and "zentorno_super_unlocked" or "zentorno_trial", classId = classId, label = "Zentorno Trial", threshold = cap, score = score, starter = true, starterCap = cap, superThreshold = superNeed }
        end
        return { ok = false, reason = "zentorno_trial_expired", noHud = true, classId = classId, label = "Zentorno Trial Expired", threshold = superNeed, score = score, starter = true, starterCap = cap, superThreshold = superNeed }
    end

    return dgR68OriginalGetVehicleSectorInfo(veh)
end

