function driftgod.ShowVehicleTrialEndedNoticeR69(info)
    driftgod.S = driftgod.S or {}
    info = info or {}
    local reason = tostring(info.reason or "")
    local vehicleName, cap
    if reason == "zentorno_trial_expired" then
        vehicleName = "Zentorno"
        cap = tonumber(driftgod.VehicleSectorZentornoTrialCap or 10000) or 10000
    elseif reason == "torero_xo_trial_expired" then
        vehicleName = "Torero XO"
        cap = tonumber(driftgod.VehicleSectorToreroXOTrialCap or 5000) or 5000
    else
        return false
    end

    local now = dgR69Now()
    local key = "vehicleTrialEndedNotice_" .. reason
    local last = tonumber(driftgod.S[key] or 0) or 0

    if now - last < 4500 then return true end
    driftgod.S[key] = now

    local msg = vehicleName .. " Trial Ended. Please drift with another vehicle."
    local sub = "Unlock Super at " .. dgR69Fmt(driftgod.VehicleSectorSuperUnlockScore or 25000) .. " Best Run to use it permanently."

    driftgod.S.vehicleTrialEndedBannerStart = now
    driftgod.S.vehicleTrialEndedBannerTitle = string.upper(vehicleName) .. " TRIAL ENDED!"
    driftgod.S.vehicleTrialEndedBannerText = "Trial expired. Choose another ride."
    driftgod.S.vehicleTrialEndedBannerSub = sub

    return true
end

function driftgod.RenderVehicleTrialEndedBannerR69()
    driftgod.S = driftgod.S or {}
    if not driftgod.DrawTextCenter then return end
    local start = tonumber(driftgod.S.vehicleTrialEndedBannerStart or 0) or 0
    if start <= 0 then return end
    local now = dgR69Now()
    local dur = 4200
    local e = now - start
    if e < 0 or e > dur then return end

    local t = e / dur
    local x
    if t < 0.18 then
        local p = t / 0.18; p = p*p*(3-2*p); x = -0.38 + 0.88*p
    elseif t < 0.76 then
        x = 0.5
    else
        local p = (t - 0.76) / 0.24; p = p*p*(3-2*p); x = 0.5 + 0.92*p
    end
    local alpha = 245
    if t > 0.82 then alpha = math.max(0, math.floor(245 * (1 - ((t - 0.82) / 0.18)))) end
    local y = 0.405
    driftgod.DrawTextCenter(driftgod.S.vehicleTrialEndedBannerTitle or "VEHICLE TRIAL ENDED!", x, y - 0.030, 0.58, driftgod.ThemeNoticeRed[1], driftgod.ThemeNoticeRed[2], driftgod.ThemeNoticeRed[3], alpha, 7)
    driftgod.DrawTextCenter(driftgod.S.vehicleTrialEndedBannerText or "Trial expired. Choose another ride.", x, y + 0.020, 0.36, driftgod.ThemeNoticeWhite[1], driftgod.ThemeNoticeWhite[2], driftgod.ThemeNoticeWhite[3], alpha, 4)
    driftgod.DrawTextCenter(driftgod.S.vehicleTrialEndedBannerSub or "", x, y + 0.060, 0.30, driftgod.ThemeNoticePurple[1], driftgod.ThemeNoticePurple[2], driftgod.ThemeNoticePurple[3], alpha, 4)
end

