function driftgod.ShowVehicleLockedDriftNoticeR70(info)
    driftgod.S = driftgod.S or {}
    info = info or {}
    local reason = tostring(info.reason or "")

    if reason == "zentorno_trial_expired" or reason == "torero_xo_trial_expired" then
        if driftgod.ShowVehicleTrialEndedNoticeR69 then return driftgod.ShowVehicleTrialEndedNoticeR69(info) end
        return false
    end

    local now = dgR70Now()
    if now - (tonumber(driftgod.S.vehicleLockedDriftNoticeLastMs or 0) or 0) < 2400 then return true end
    driftgod.S.vehicleLockedDriftNoticeLastMs = now

    local label = tostring(info.label or "Vehicle")
    local threshold = tonumber(info.threshold or 0) or 0
    local score = tonumber(info.score or 0) or 0
    local left = math.max(0, threshold - score)

    local title, text, sub
    if reason == "locked" then
        title = "VEHICLE LOCKED!"
        text = "This ride is not worthy yet."
        sub = "Unlock " .. label .. " at " .. dgR70Fmt(threshold) .. " High Score. Need " .. dgR70Fmt(left) .. " more."
    elseif reason == "unsupported" then

        driftgod.S.vehicleLockedDriftBannerStart = 0
        return false
    else
        title = "VEHICLE UNAVAILABLE!"
        text = "This vehicle cannot drift yet."
        sub = "Unlock more vehicles in Arcade progression."
    end

    driftgod.S.vehicleLockedDriftBannerStart = now
    driftgod.S.vehicleLockedDriftBannerTitle = title
    driftgod.S.vehicleLockedDriftBannerText = text
    driftgod.S.vehicleLockedDriftBannerSub = sub

    return true
end

