    if start <= 0 then return end
    local now = dgR70Now()
    local dur = 3600
    local e = now - start
    if e < 0 or e > dur then return end

    local t = e / dur
    local x
    if t < 0.20 then
        local p = t / 0.20; p = p*p*(3-2*p); x = -0.38 + 0.88*p
    elseif t < 0.74 then
        x = 0.5
    else
        local p = (t - 0.74) / 0.26; p = p*p*(3-2*p); x = 0.5 + 0.92*p
    end
    local alpha = 245
