    local y = 0.405
    driftgod.DrawTextCenter(driftgod.S.vehicleLockedDriftBannerTitle or "VEHICLE LOCKED!", x, y - 0.030, 0.60, driftgod.ThemeNoticeRed[1], driftgod.ThemeNoticeRed[2], driftgod.ThemeNoticeRed[3], alpha, 7)
