local DG_R70_PreVehicleSectorGateTick = driftgod.VehicleSectorGateTick
function driftgod.VehicleSectorGateTick(context, veh)
    local ok, info
    if DG_R70_PreVehicleSectorGateTick then
        ok, info = DG_R70_PreVehicleSectorGateTick(context, veh)
    else
        ok, info = true, nil
    end

    local reason = tostring(info and info.reason or "")
    local blocked = (ok ~= true) or reason == "locked" or reason == "unsupported" or reason == "zentorno_trial_expired" or reason == "torero_xo_trial_expired"

    if context == "hud" and blocked then
        dgR70HideScoreHud()
        return false, info
    end

    if blocked and (context == "drift" or context == "score") then
        dgR70HideScoreHud()

        local held = dgR71DriftHeldOnly()
        if held then
            if reason == "unsupported" then

            elseif reason == "zentorno_trial_expired" or reason == "torero_xo_trial_expired" then
                if driftgod.ShowVehicleTrialEndedNoticeR69 then driftgod.ShowVehicleTrialEndedNoticeR69(info) end
            elseif driftgod.ShowVehicleLockedDriftNoticeR70 then
                driftgod.ShowVehicleLockedDriftNoticeR70(info)
            end
        end
        return false, info
    end

    return ok, info
end

