    if enabled == true and driftgod.S and tonumber(driftgod.S.scoreHudForceHideUntil or 0) > dgR70Now() then
        enabled = false
    end
    if DG_R70_PreSetScoreHudVisible then return DG_R70_PreSetScoreHudVisible(enabled) end
    driftgod.S = driftgod.S or {}; driftgod.S.showScoreHudMaster = enabled == true; driftgod.S.scoreHudEnabled = enabled == true
end

