local function dgR73SlideX(t)
    local x
    if t < 0.12 then
        local p = t / 0.12; p = p*p*(3-2*p); x = -0.38 + 0.88*p
    elseif t < 0.82 then
        x = 0.5
    else
        local p = (t - 0.82) / 0.18; p = p*p*(3-2*p); x = 0.5 + 0.92*p
    end
    return x
end

local function dgR73Alpha(t, maxAlpha)
    maxAlpha = maxAlpha or 245
    if t > 0.86 then
        return math.max(0, math.floor(maxAlpha * (1 - ((t - 0.86) / 0.14))))
    end
    return maxAlpha
end

