    local function R114Text(text, color)
        if dgMiniText then driftgod.Try(dgMiniText, tostring(text or ""), color or "white")
        elseif ImGui and ImGui.Text then ImGui.Text(tostring(text or "")) end
    end
    local function R114SameLine() if ImGui and ImGui.SameLine then ImGui.SameLine() end end
    local function R114Button(label, cb)
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) == true end) end
        if clicked and cb then driftgod.Try(cb) end
        return clicked
    end
