        if not hash then return false end
        if dgMiniFeature then local ok = driftgod.Try(dgMiniFeature, hash, label); if ok then return true end end
        if ClickGUI and ClickGUI.RenderFeature then local ok = driftgod.Try(ClickGUI.RenderFeature, hash); if ok then return true end end
        return false
    end

    local function R114EnsureRuntimeOn()
        if driftgod.VS_RegisterFeatures then driftgod.Try(driftgod.VS_RegisterFeatures) end
        driftgod.Try(function()
            local f = driftgod.VS and driftgod.VS.features and driftgod.VS.features.runtime
            if f then
                if f.SetBoolValue then f:SetBoolValue(true) end
                if f.SetToggled then f:SetToggled(true) end
                if f.SetToggle then f:SetToggle(true) end
                local on = nil
                if f.IsToggled then on = f:IsToggled() end
                if on == false and f.Toggle then f:Toggle() end
            end
        end)
        driftgod.Try(function()
            if FeatureMgr and FeatureMgr.GetFeature and driftgod.H.VehicleSpawnerRuntime then
                local f = FeatureMgr.GetFeature(driftgod.H.VehicleSpawnerRuntime)
                if f then
                    if f.SetBoolValue then f:SetBoolValue(true) end
                    if f.SetToggled then f:SetToggled(true) end
                    if f.SetToggle then f:SetToggle(true) end
                    local on = nil
                    if f.IsToggled then on = f:IsToggled() end
                    if on == false and f.Toggle then f:Toggle() end
                end
            end
        end)
    end

