        else driftgod.VS = driftgod.VS or {}; driftgod.VS.runtime = driftgod.VS.runtime or {}; driftgod.VS.runtime.open = true end
        driftgod.Try(function() if driftgod.VS_SyncFeatures then driftgod.VS_SyncFeatures() end end)
