    if Script and Script.RegisterLooped and not driftgod.R115SpawnerHudLoopInstalled then
        driftgod.R115SpawnerHudLoopInstalled = true
        Script.RegisterLooped(function()
            if DG and driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.open == true then
                if driftgod.VS_Tick then driftgod.Try(driftgod.VS_Tick)
                elseif driftgod.VS_RenderHud then driftgod.Try(driftgod.VS_RenderHud) end
            end
            Script.Yield(0)
        end)
