            EnsureVS()
            if Child("DriftGod Garage") then
                Text("Saved Vehicles", "header")
                Button("Open HUD##GarageR115", driftgod.R115_OpenSpawnerHud)
                SameLine(); Button("Close HUD##GarageR115", driftgod.R115_CloseSpawnerHud)
                SameLine(); Button("Scan##GarageR115", driftgod.R115_ScanSpawnerVehicles)
                SameLine(); Button("Random##GarageR115", driftgod.R115_RandomSpawnerVehicle)
                Feature(driftgod.H.VehicleSpawnerCategory, "Category")
                Feature(driftgod.H.VehicleSpawnerVehicle, "Saved Vehicle")
                Button("Spawn Selected##GarageR115", function() if driftgod.VS_QueueSelected then driftgod.VS_QueueSelected() end end)
                if driftgod.VS and driftgod.VS.runtime then
                    local count = 0; driftgod.Try(function() count = #(driftgod.VS.runtime.items or {}) end)
                    Text("Scanned: " .. tostring(count) .. " | HUD: " .. (driftgod.VS.runtime.open and "Open" or "Closed"), "dim")
                end
                EndChild()
            end
        end
    end
end)

DG = DG or {}
driftgod.S = driftgod.S or {}

local function R116_clamp(v, lo, hi)
    v = tonumber(v or lo) or lo
    if v < lo then return lo end
    if v > hi then return hi end
    return v
end

local function R116_now()
    if DG and driftgod.Now then return driftgod.Now() end
    return math.floor(os.clock() * 1000)
end

local function R116_void(fn, ...)
    if fn then driftgod.Try(fn, ...) end
end

local function R116_set_reduce_grip(veh, enabled)
    driftgod.S = driftgod.S or {}
    if not veh or veh == 0 then return end

    if driftgod.S.r116GripOn == enabled and driftgod.S.r116LastVehicle == veh then return end
    if driftgod.SafeSetVehicleReduceGrip then
        driftgod.Try(function() driftgod.SafeSetVehicleReduceGrip(veh, enabled == true) end)
    elseif VEHICLE and VEHICLE.SET_VEHICLE_REDUCE_GRIP then
        driftgod.Try(function() VEHICLE.SET_VEHICLE_REDUCE_GRIP(veh, enabled == true) end)
    elseif Natives and Natives.InvokeVoid then
        driftgod.Try(function() Natives.InvokeVoid(0x222FF6A823D122E2, veh, enabled == true) end)
    end
    driftgod.S.r116GripOn = enabled == true
    driftgod.S.r116LastVehicle = veh
    driftgod.S.oldGripState = enabled == true
end

local function R116_apply_force(veh, x, y, z)
    if not veh or veh == 0 then return end
    if ENTITY and ENTITY.APPLY_FORCE_TO_ENTITY then
        driftgod.Try(function() ENTITY.APPLY_FORCE_TO_ENTITY(veh, 1, x or 0.0, y or 0.0, z or 0.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true) end)
    elseif Natives and Natives.InvokeVoid then
        driftgod.Try(function() Natives.InvokeVoid(0xC5F68BE9613E2D18, veh, 1, x or 0.0, y or 0.0, z or 0.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true) end)
    end
end

local function R116_forward_vector(veh)
    local vec = nil
    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_FORWARD_VECTOR then vec = ENTITY.GET_ENTITY_FORWARD_VECTOR(veh) end
    end)
    if not vec and Natives and Natives.InvokeV3 and V3 then
        driftgod.Try(function() vec = V3.New(Natives.InvokeV3(0x0A794A5A57F8DF91, veh)) end)
    end
    if vec then return tonumber(vec.x or vec[1] or 0.0) or 0.0, tonumber(vec.y or vec[2] or 0.0) or 0.0, tonumber(vec.z or vec[3] or 0.0) or 0.0 end
    return 0.0, 1.0, 0.0
end

local function R116_apply_forward_momentum(veh, strength)
    strength = tonumber(strength or 0.0) or 0.0
    if strength <= 0.0 then return end
    local now = R116_now()
    if now - (driftgod.S.r116LastForwardForceMs or 0) < 90 then return end
    driftgod.S.r116LastForwardForceMs = now
    local x,y,z = R116_forward_vector(veh)
    R116_apply_force(veh, x * strength, y * strength, z * strength)
end

local function R116_apply_lateral_nudge(veh, strength, direction)
    strength = tonumber(strength or 0.0) or 0.0
    if strength <= 0.0 then return end
    local h = 0.0
    driftgod.Try(function()
        if ENTITY and ENTITY.GET_ENTITY_HEADING then h = ENTITY.GET_ENTITY_HEADING(veh) end
    end)
    local rad = math.rad(tonumber(h or 0.0) or 0.0)
    local sign = direction or 1.0
    R116_apply_force(veh, math.cos(rad) * strength * sign, math.sin(rad) * strength * sign, 0.0)
end

local function R116_clear_steer()

end

function driftgod.R116RefreshUniversalPresetValues()
    driftgod.ArcadeDriftPresets = driftgod.ArcadeDriftPresets or {}
    local exact = {
        runway_king={intensity=42, angle=68, assist=82, min_speed=28.0, base_force=0.026, grip_pad=14.0, style='sweep', ud_source='Open - Runway King'},
        driftgod_wide_angle={intensity=44, angle=72, assist=84, min_speed=16.0, base_force=0.028, grip_pad=18.0, style='dgplus', ud_source='Open - DriftGod Wide Angle'},
        speed_control={intensity=36, angle=52, assist=86, min_speed=20.0, base_force=0.021, grip_pad=6.0, style='speedcontrol', ud_source='Wide - Speed + Control'},
        velocity_arc={intensity=32, angle=54, assist=80, min_speed=24.0, base_force=0.019, grip_pad=8.0, style='velocityarc', ud_source='Wide - Velocity Arc Pro'},
        high_speed_sweep={intensity=34, angle=55, assist=82, min_speed=24.0, base_force=0.020, grip_pad=7.0, style='sweep', ud_source='Wide - High Speed Sweep Pro'},
        apex_runner={intensity=30, angle=45, assist=90, min_speed=15.0, base_force=0.016, grip_pad=4.0, style='apexrunner', ud_source='Technical - Apex Runner'},
        touge_rebuild={intensity=34, angle=43, assist=94, min_speed=12.0, base_force=0.014, grip_pad=3.0, style='speedthread', ud_source='Technical - Touge Rebuild'},
        corner_magnet={intensity=32, angle=46, assist=90, min_speed=13.0, base_force=0.017, grip_pad=4.0, style='corner', ud_source='Technical - Corner Magnet Pro'},
    }
    for _, p in ipairs(driftgod.ArcadeDriftPresets) do
        local e = exact[p.id]
        if e then
            for k,v in pairs(e) do p[k]=v end
            p.runtime='UniversalDrifting'
        end
    end
end

function driftgod.R116ResetUniversalRuntimeState(veh)
    driftgod.S = driftgod.S or {}
    if veh and veh ~= 0 then
        R116_set_reduce_grip(veh, false)
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_STEER_BIAS then VEHICLE.SET_VEHICLE_STEER_BIAS(veh, 0.0) end
            if VEHICLE and VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS then
                VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 0, false)
                VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 1, false)
            end
        end)
    else
        driftgod.S.r116GripOn = false
    end
    driftgod.S.r116LastAngle = 0.0
    driftgod.S.r116EntryMsByPreset = {}
end

local R116_oldResetVehicleState = driftgod.ResetVehicleState
function driftgod.ResetVehicleState(showToast)
    local veh = 0
    driftgod.Try(function() if driftgod.GetVehicle then veh = driftgod.GetVehicle() end end)
    driftgod.Try(function() driftgod.R116ResetUniversalRuntimeState(veh or 0) end)
    if R116_oldResetVehicleState then return R116_oldResetVehicleState(showToast) end
end

function driftgod.ApplyArcadeDriftPresetRuntime(veh, kmh, driftAngle, held)
    driftgod.S = driftgod.S or {}
    if not held or not veh or veh == 0 or driftgod.S.arcadePresetRuntimeEnabled == false then return end
    if driftgod.S.stuntBusy then return end
    local p = driftgod.GetArcadeDriftPresetById and driftgod.GetArcadeDriftPresetById(driftgod.S.activeArcadeDriftPreset) or nil
    if not p then return end

    local now = R116_now()

    if now - (driftgod.S.r116LastRuntimeTick or 0) < 35 then return end
    driftgod.S.r116LastRuntimeTick = now

    kmh = tonumber(kmh or 0.0) or 0.0
    local angle = tonumber(driftAngle or 0.0) or 0.0
    local raw = tonumber(driftgod.S.lastDriftAngle or angle or 0.0) or 0.0
    local signed = raw
    if signed > 180.0 then signed = -(360.0 - signed) end
    local absAngle = math.abs(angle)

    local maxAngle = R116_clamp(p.angle or 50.0, 10.0, 100.0)
    local minSpeed = tonumber(p.min_speed or 12.0) or 12.0
    local pad = tonumber(p.grip_pad or 8.0) or 8.0
    local intensity = R116_clamp(p.intensity or 30, 1, 100) / 100.0
    local assist = R116_clamp(p.assist or 80, 1, 100) / 100.0
    local style = tostring(p.style or 'sweep')
    driftgod.S.r116EntryMsByPreset = driftgod.S.r116EntryMsByPreset or {}
    if not driftgod.S.r116EntryMsByPreset[p.id] or driftgod.S.r116EntryMsByPreset[p.id] == 0 then driftgod.S.r116EntryMsByPreset[p.id] = now end
    local entryAge = now - (driftgod.S.r116EntryMsByPreset[p.id] or now)

    local wantGrip = false
    local force = (tonumber(p.base_force or 0.015) or 0.015) * intensity
    local steerGain = 0.10 + (0.18 * assist)

    if style == 'speedcontrol' then
        wantGrip = kmh >= minSpeed and kmh <= 155.0 and absAngle <= (maxAngle + pad)
        local angleScale = 1.0 - math.min(absAngle / 115.0, 0.62)
        local speedScale = R116_clamp(kmh / 85.0, 0.35, 1.05)
        force = force * angleScale * speedScale
        steerGain = 0.18 + (0.22 * assist) + math.min(kmh / 260.0, 0.06)
    elseif style == 'apexrunner' then
        wantGrip = kmh >= minSpeed and kmh <= 170.0 and absAngle <= (maxAngle + pad)
        local cornerScale = absAngle >= 8.0 and R116_clamp(absAngle / maxAngle, 0.35, 1.0) or 0.22
        force = force * cornerScale * R116_clamp(kmh / 95.0, 0.35, 0.95)
        if absAngle > maxAngle * 0.82 then force = force * 0.45 end
        steerGain = 0.20 + (0.24 * assist) + math.min(kmh / 300.0, 0.05)
    elseif style == 'velocityarc' then
        wantGrip = kmh >= minSpeed and kmh <= 190.0 and absAngle <= (maxAngle + pad)
        force = force * R116_clamp(kmh / 120.0, 0.25, 0.85) * (1.0 - math.min(absAngle / 170.0, 0.45))
        steerGain = 0.12 + (0.18 * assist) + math.min(kmh / 340.0, 0.07)
    elseif style == 'speedthread' then
        wantGrip = kmh >= minSpeed and kmh <= 145.0 and absAngle <= (maxAngle + pad)
        force = force * 0.30 * (absAngle >= 10.0 and 1.0 or 0.45)
        steerGain = 0.24 + (0.28 * assist) + math.min(kmh / 310.0, 0.04)
    elseif style == 'corner' then
        local entry = entryAge < 420
        wantGrip = kmh >= minSpeed and (entry or absAngle <= (maxAngle + pad))
        if not entry and absAngle < 18.0 then force = force * 0.40 end
        steerGain = 0.18 + (0.18 * assist)
    elseif style == 'dgplus' then
        wantGrip = kmh >= minSpeed and absAngle <= (maxAngle + pad)
        if driftgod.S.r116GripOn and absAngle <= (maxAngle + pad + 4.0) then wantGrip = kmh >= (minSpeed - 3.0) end
        force = force * (absAngle >= 10.0 and 1.0 or 0.45)
        steerGain = 0.14 + (0.18 * assist)
    elseif style == 'sweep' then
        wantGrip = kmh >= minSpeed and absAngle <= (maxAngle + pad)
        force = force * math.min(kmh / 85.0, 1.0)
        steerGain = 0.09 + (0.13 * assist) + math.min(kmh / 250.0, 0.08)
    elseif style == 'chaos' then
        wantGrip = kmh >= minSpeed and absAngle <= (maxAngle + pad)
        force = force * (absAngle > maxAngle and 0.20 or 1.05)
        steerGain = 0.18 + (0.26 * assist)
    else
        wantGrip = kmh >= minSpeed and absAngle <= (maxAngle + pad)
    end

    R116_set_reduce_grip(veh, wantGrip)

    if kmh >= minSpeed and wantGrip and force > 0.0 then
        R116_apply_forward_momentum(veh, force)
    end

    if style == 'chaos' or style == 'apexrunner' then
        if kmh >= minSpeed and absAngle > 12.0 and absAngle < (maxAngle + 18.0) then
            R116_apply_lateral_nudge(veh, force * 0.35, signed >= 0 and 1.0 or -1.0)
        end
    end

    if driftgod.S.autoCounterSteerEnabled ~= false and kmh >= minSpeed then
        local engage = maxAngle * 0.72
        if absAngle > engage then
            local over = math.min(absAngle - engage, maxAngle)
            local biasDeg = (signed >= 0 and 1.0 or -1.0) * math.min(over * steerGain, 16.0)
            driftgod.Try(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_STEER_BIAS then VEHICLE.SET_VEHICLE_STEER_BIAS(veh, math.rad(biasDeg)) end
                if VEHICLE and VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS then
                    VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 0, signed > 0)
                    VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 1, signed < 0)
                end
            end)
        else
            driftgod.Try(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_STEER_BIAS then VEHICLE.SET_VEHICLE_STEER_BIAS(veh, 0.0) end
                if VEHICLE and VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS then
                    VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 0, false)
                    VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 1, false)
                end
            end)
        end
    else
        driftgod.Try(function() if VEHICLE and VEHICLE.SET_VEHICLE_STEER_BIAS then VEHICLE.SET_VEHICLE_STEER_BIAS(veh, 0.0) end end)
    end
end

local R116_oldApplyArcadeDriftPreset = driftgod.ApplyArcadeDriftPreset
function driftgod.ApplyArcadeDriftPreset(id, showToast)
    driftgod.R116RefreshUniversalPresetValues()
    local ok = false
    if R116_oldApplyArcadeDriftPreset then ok = R116_oldApplyArcadeDriftPreset(id, showToast) end
    if ok ~= false then
        driftgod.S = driftgod.S or {}
        driftgod.S.arcadePresetRuntimeEnabled = true
        driftgod.S.universalPresetRuntimeEnabled = true
        driftgod.S.r116EntryMsByPreset = {}
        local p = driftgod.GetArcadeDriftPresetById and driftgod.GetArcadeDriftPresetById(id) or nil
        if p and showToast ~= false and driftgod.Toast then
            driftgod.Toast('UniversalDrifting base loaded: ' .. tostring(p.ud_source or p.name or id), 1800)
        end
    end
    return ok
end

driftgod.Try(function() driftgod.R116RefreshUniversalPresetValues() end)

driftgod.Try(function()
    DG = DG or {}
    driftgod.S = driftgod.S or {}
    driftgod.H = driftgod.H or {}

    if driftgod.S.pureUniversalRuntimeEnabled == nil then
        driftgod.S.pureUniversalRuntimeEnabled = false
    end

    local function r118_toast(msg, ms)
        if driftgod.Toast then driftgod.Toast(tostring(msg), tonumber(ms or 1800) or 1800) end
    end

    local function r118_vehicle()
        local veh = 0
        driftgod.Try(function()
            if driftgod.GetVehicle then veh = driftgod.GetVehicle() end
        end)
        return tonumber(veh or 0) or 0
    end

    local function r118_heading_of_travel(veh)
        if driftgod.GetHeadingOfTravel then
            local ok, v = driftgod.Try(function() return driftgod.GetHeadingOfTravel(veh) end)
            if ok and v ~= nil then return tonumber(v or 0.0) or 0.0 end
        end
        return 0.0
    end

    local function r118_readable_angle(veh)
        local drift = 0.0
        driftgod.Try(function()
            local heading = 0.0
            if ENTITY and ENTITY.GET_ENTITY_HEADING then heading = ENTITY.GET_ENTITY_HEADING(veh) end
            drift = (tonumber(heading or 0.0) or 0.0) - r118_heading_of_travel(veh)
        end)
        if driftgod.Wrap360 then drift = driftgod.Wrap360(drift) else drift = drift % 360.0 end
        driftgod.S.lastDriftAngle = drift
        local readable = drift
        local signed = drift
        if readable > 180.0 then readable = 360.0 - readable end
        if signed > 180.0 then signed = -(360.0 - signed) end
        return readable, signed
    end

    local function r118_pure_tick()
        if not driftgod.HasNatives or not driftgod.HasNatives() then return end
        if driftgod.S.driftAssistEnabled ~= true then return end

        local veh = r118_vehicle()
        if veh == 0 then
            if driftgod.S.driftWasActive and driftgod.ResetVehicleState then driftgod.ResetVehicleState(false) end
            return
        end

        if driftgod.VehicleSectorGateTick and not driftgod.VehicleSectorGateTick("drift", veh) then return end

        local held = false
        driftgod.Try(function() if driftgod.IsDriftHeld then held = driftgod.IsDriftHeld() == true end end)
        if not held then
            if driftgod.S.prevGripState then
                if driftgod.ResetVehicleState then driftgod.ResetVehicleState(false) end
            end
            driftgod.S.prevGripState = false
            driftgod.S.isDrifting = false
            return
        end

        if held and driftgod.IsLockedArcadePresetBlocking and driftgod.IsLockedArcadePresetBlocking() then
            if driftgod.ShowLockedArcadePresetShiftNotice then driftgod.ShowLockedArcadePresetShiftNotice() end
            if driftgod.ResetVehicleState then driftgod.ResetVehicleState(false) end
            driftgod.S.prevGripState = false
            driftgod.S.isDrifting = false
            return
        end

        driftgod.S.driftWasActive = true
        driftgod.S.prevGripState = true
        driftgod.S.isDrifting = true
        driftgod.S.hudVisibleUntil = (driftgod.Now and driftgod.Now() or math.floor(os.clock() * 1000)) + (tonumber(driftgod.S.hudFadeAfterMs or 2500) or 2500)
        driftgod.S.hudAlpha = 255

        local kmh = 0.0
        driftgod.Try(function() if ENTITY and ENTITY.GET_ENTITY_SPEED then kmh = (ENTITY.GET_ENTITY_SPEED(veh) or 0.0) * 3.6 end end)
        local readable = r118_readable_angle(veh)

        if driftgod.ApplyArcadeDriftPresetRuntime then
            driftgod.Try(function() driftgod.ApplyArcadeDriftPresetRuntime(veh, kmh, readable, true) end)
        end

        if driftgod.ApplyMomentum then driftgod.Try(function() driftgod.ApplyMomentum(veh, kmh, readable, true) end) end
        if driftgod.ApplyAccel then driftgod.Try(function() driftgod.ApplyAccel(veh, kmh, readable, true) end) end
        if driftgod.ApplyExperimental then driftgod.Try(function() driftgod.ApplyExperimental(veh, kmh, readable, true) end) end
    end

    local r118_oldDriftTick = driftgod.DriftTick
    driftgod.DriftTick = function()
        driftgod.S = driftgod.S or {}
        if driftgod.S.pureUniversalRuntimeEnabled == true then
            return r118_pure_tick()
        end
        if r118_oldDriftTick then return r118_oldDriftTick() end
    end

    if driftgod.AddToggle and not driftgod.H.PureUniversalRuntime then
        driftgod.AddToggle("PureUniversalRuntime", "Pure Universal Runtime", "Testing only: bypasses legacy DriftGod grip/steer controller so presets use the UniversalDrifting base cleanly. Default OFF.", function(f)
            driftgod.S = driftgod.S or {}
            driftgod.S.pureUniversalRuntimeEnabled = f and f.IsToggled and f:IsToggled() == true or false
            local veh = r118_vehicle()
            if driftgod.ResetVehicleState then driftgod.Try(function() driftgod.ResetVehicleState(false) end) end
            if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
            r118_toast(driftgod.S.pureUniversalRuntimeEnabled and "Pure Universal Runtime ON" or "Pure Universal Runtime OFF", 1800)
        end, false)
    end

    local function r118_render_toggle_panel()
        if not renderFeatureSafe or not driftgod.H or not driftgod.H.PureUniversalRuntime then return end
        if dgColorText then dgColorText("Testing Runtime", "header") else ImGui.Text("Testing Runtime") end
        renderFeatureSafe(driftgod.H.PureUniversalRuntime, "Pure Universal Runtime")
        if dgMiniText then
            dgMiniText("ON = Universal preset base only + visible layers you toggle. OFF = normal DriftGod stack.", "dim")
        elseif ImGui and ImGui.Text then
            ImGui.Text("ON = Universal preset base only + visible layers you toggle.")
        end
        if ImGui and ImGui.Separator then ImGui.Separator() end
    end

    local r118_oldFlat = renderArcadeDriftPresetsPanelFlatR88
    renderArcadeDriftPresetsPanelFlatR88 = function(...)
        r118_render_toggle_panel()
        if r118_oldFlat then return r118_oldFlat(...) end
    end

    local r118_oldPanel = renderArcadeDriftPresetsPanel
    renderArcadeDriftPresetsPanel = function(...)
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            if ClickGUI.BeginCustomChildWindow("Drift Presets") then
                if renderArcadeDriftPresetsPanelFlatR88 then renderArcadeDriftPresetsPanelFlatR88(...) end
                ClickGUI.EndCustomChildWindow()
            end
            return
        end
        r118_render_toggle_panel()
        if r118_oldPanel then return r118_oldPanel(...) end
    end

    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.LastUpdated = "2026-06-26"
end)

driftgod.Try(function()
    DG = DG or {}
    driftgod.S = driftgod.S or {}
    driftgod.H = driftgod.H or {}

    local function R119_IsPure()
        return DG and driftgod.S and driftgod.S.pureUniversalRuntimeEnabled == true
    end

    local function R119_Veh()
        local veh = 0
        driftgod.Try(function() if driftgod.GetVehicle then veh = driftgod.GetVehicle() end end)
        return tonumber(veh or 0) or 0
    end

    local function R119_ResetForPure(veh)
        driftgod.S = driftgod.S or {}

        driftgod.S.superDriveEnabled = false
        driftgod.S.boostFXEnabled = false
        driftgod.S.boostFXNeedsDeactivate = false
        driftgod.S.hornProbeHold = false
        driftgod.S.hornProbeBoostNeedsOff = false
        driftgod.S.experimentalGripEnabled = false
        driftgod.S._experimentalGripWasOn = false
        driftgod.S.experimentalGravityEnabled = false
        driftgod.S.experimentalAccelEnabled = false
        driftgod.S.experimentalTractionEnabled = false
        driftgod.S.accelAssistEnabled = false
        driftgod.S.momentumAssistEnabled = false
        driftgod.S.stabilityAssistEnabled = false

        if veh and veh ~= 0 then
            driftgod.Try(function()
                if driftgod.SafeSetVehicleFrictionOverride then driftgod.SafeSetVehicleFrictionOverride(veh, 1.0) end
                if VEHICLE and VEHICLE.SET_VEHICLE_STEER_BIAS then VEHICLE.SET_VEHICLE_STEER_BIAS(veh, 0.0) end
                if VEHICLE and VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS then
                    VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 0, false)
                    VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 1, false)
                end
                if AUDIO and AUDIO.SET_VEHICLE_BOOST_ACTIVE then AUDIO.SET_VEHICLE_BOOST_ACTIVE(veh, false) end
            end)
        end
    end

    local R119_oldSuperDriveTick = driftgod.SuperDriveTick
    driftgod.SuperDriveTick = function(...)
        if R119_IsPure() then return end
        if R119_oldSuperDriveTick then return R119_oldSuperDriveTick(...) end
    end

    local R119_oldExperimentalGrip = driftgod.ApplyExperimentalGrip
    driftgod.ApplyExperimentalGrip = function(...)
        if R119_IsPure() then
            driftgod.S = driftgod.S or {}; driftgod.S.experimentalGripEnabled = false; driftgod.S._experimentalGripWasOn = false
            return
        end
        if R119_oldExperimentalGrip then return R119_oldExperimentalGrip(...) end
    end

    local R119_oldBoostFXTick = driftgod.BoostFXTick
    driftgod.BoostFXTick = function(...)
        if R119_IsPure() then
            driftgod.S = driftgod.S or {}; driftgod.S.boostFXEnabled = false; driftgod.S.boostFXNeedsDeactivate = false
            return
        end
        if R119_oldBoostFXTick then return R119_oldBoostFXTick(...) end
    end

    local R119_oldHornProbeTick = driftgod.HornProbeTick
    driftgod.HornProbeTick = function(...)
        if R119_IsPure() then
            driftgod.S = driftgod.S or {}; driftgod.S.hornProbeHold = false; driftgod.S.hornProbeBoostNeedsOff = false
            return
        end
        if R119_oldHornProbeTick then return R119_oldHornProbeTick(...) end
    end

    local R119_oldMomentum = driftgod.ApplyMomentum
    driftgod.ApplyMomentum = function(...)
        if R119_IsPure() then return end
        if R119_oldMomentum then return R119_oldMomentum(...) end
    end

    local R119_oldAccel = driftgod.ApplyAccel
    driftgod.ApplyAccel = function(...)
        if R119_IsPure() then return end
        if R119_oldAccel then return R119_oldAccel(...) end
    end

    local R119_oldExperimental = driftgod.ApplyExperimental
    driftgod.ApplyExperimental = function(...)
        if R119_IsPure() then return end
        if R119_oldExperimental then return R119_oldExperimental(...) end
    end

    local function R119_HeadingOfTravel(veh)
        if driftgod.GetHeadingOfTravel then
            local ok, v = driftgod.Try(function() return driftgod.GetHeadingOfTravel(veh) end)
            if ok and v ~= nil then return tonumber(v or 0.0) or 0.0 end
        end
        return 0.0
    end

    local function R119_ReadableAngle(veh)
        local drift = 0.0
        driftgod.Try(function()
            local heading = 0.0
            if ENTITY and ENTITY.GET_ENTITY_HEADING then heading = ENTITY.GET_ENTITY_HEADING(veh) end
            drift = (tonumber(heading or 0.0) or 0.0) - R119_HeadingOfTravel(veh)
        end)
        if driftgod.Wrap360 then drift = driftgod.Wrap360(drift) else drift = drift % 360.0 end
        driftgod.S.lastDriftAngle = drift
        local readable = drift
        if readable > 180.0 then readable = 360.0 - readable end
        return readable
    end

    local function R119_PureTick()
        driftgod.S = driftgod.S or {}
        if not driftgod.HasNatives or not driftgod.HasNatives() then return end
        if driftgod.S.driftAssistEnabled ~= true then return end

        local veh = R119_Veh()
        if veh == 0 then
            if driftgod.S.driftWasActive and driftgod.ResetVehicleState then driftgod.ResetVehicleState(false) end
            return
        end

        R119_ResetForPure(veh)

        if driftgod.VehicleSectorGateTick and not driftgod.VehicleSectorGateTick("drift", veh) then return end

        local held = false
        driftgod.Try(function() if driftgod.IsDriftHeld then held = driftgod.IsDriftHeld() == true end end)
        if not held then
            if driftgod.S.prevGripState or driftgod.S.r116GripOn then
                if driftgod.R116ResetUniversalRuntimeState then driftgod.R116ResetUniversalRuntimeState(veh) end
                driftgod.Try(function() if driftgod.SafeSetVehicleReduceGrip then driftgod.SafeSetVehicleReduceGrip(veh, false) end end)
            end
            driftgod.S.prevGripState = false
            driftgod.S.isDrifting = false
            return
        end

        if driftgod.IsLockedArcadePresetBlocking and driftgod.IsLockedArcadePresetBlocking() then
            if driftgod.ShowLockedArcadePresetShiftNotice then driftgod.ShowLockedArcadePresetShiftNotice() end
            if driftgod.R116ResetUniversalRuntimeState then driftgod.R116ResetUniversalRuntimeState(veh) end
            driftgod.S.prevGripState = false
            driftgod.S.isDrifting = false
            return
        end

        driftgod.S.driftWasActive = true
        driftgod.S.prevGripState = true
        driftgod.S.isDrifting = true
        driftgod.S.hudVisibleUntil = (driftgod.Now and driftgod.Now() or math.floor(os.clock() * 1000)) + (tonumber(driftgod.S.hudFadeAfterMs or 2500) or 2500)
        driftgod.S.hudAlpha = 255

        local kmh = 0.0
        driftgod.Try(function() if ENTITY and ENTITY.GET_ENTITY_SPEED then kmh = (ENTITY.GET_ENTITY_SPEED(veh) or 0.0) * 3.6 end end)
        local readable = R119_ReadableAngle(veh)

        if driftgod.ApplyArcadeDriftPresetRuntime then
            driftgod.Try(function() driftgod.ApplyArcadeDriftPresetRuntime(veh, kmh, readable, true) end)
        end
    end

    local R119_oldDriftTick = driftgod.DriftTick
    driftgod.DriftTick = function(...)
        if R119_IsPure() then return R119_PureTick() end
        if R119_oldDriftTick then return R119_oldDriftTick(...) end
    end

    if driftgod.H and driftgod.H.PureUniversalRuntime and FeatureMgr and FeatureMgr.GetFeature then
        driftgod.Try(function()
            local f = FeatureMgr.GetFeature(driftgod.H.PureUniversalRuntime)
            if f and f.RegisterCallback then
                f:RegisterCallback(function(feat)
                    driftgod.S = driftgod.S or {}
                    driftgod.S.pureUniversalRuntimeEnabled = feat and feat.IsToggled and feat:IsToggled() == true or false
                    local veh = R119_Veh()
                    R119_ResetForPure(veh)
                    if driftgod.R116ResetUniversalRuntimeState then driftgod.Try(function() driftgod.R116ResetUniversalRuntimeState(veh) end) end
                    if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
                    if driftgod.Toast then driftgod.Toast(driftgod.S.pureUniversalRuntimeEnabled and "Strict Pure Universal ON" or "Pure Universal OFF", 1800) end
                end)
            end
        end)
    end

    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.LastUpdated = "2026-06-26"
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}
    if driftgod.Toast and not driftgod._R121OriginalToast then
        driftgod._R121OriginalToast = driftgod.Toast
        driftgod._R121ToastLast = driftgod._R121ToastLast or {}
        driftgod.Toast = function(msg, ms)
            local text = tostring(msg or '')
            if text:find('Drift Assist%+') or text:find('Universal') or text:find('presets only') then
                local now = (driftgod.Now and driftgod.Now()) or math.floor((os.clock() or 0) * 1000)
                local last = driftgod._R121ToastLast[text] or 0
                if now - last < 10000 then return end
                driftgod._R121ToastLast[text] = now
            end
            return driftgod._R121OriginalToast(msg, ms)
        end
    end
end)

driftgod.Try(function()
    DG = DG or {}
    driftgod.S = driftgod.S or {}
    driftgod.H = driftgod.H or {}

    driftgod.S.legacyDriftLogicDisabled = true

    driftgod.S.driftAssistPlusEnabled = false
    driftgod.S.pureUniversalRuntimeEnabled = true
    if driftgod.S.driftTuningEnabled == nil then driftgod.S.driftTuningEnabled = false end

    local function R120_now()
        if driftgod.Now then return driftgod.Now() end
        return math.floor((os.clock() or 0) * 1000)
    end

    local function R120_vehicle()
        local veh = 0
        driftgod.Try(function() if driftgod.GetVehicle then veh = driftgod.GetVehicle() end end)
        return tonumber(veh or 0) or 0
    end

    local function R120_reset_vehicle(veh)
        driftgod.S = driftgod.S or {}
        driftgod.S.isDrifting = false
        driftgod.S.prevGripState = false
        driftgod.S.oldGripState = false
        driftgod.S.driftWasActive = false
        driftgod.S.r116GripOn = false
        if veh and veh ~= 0 then
            driftgod.Try(function()
                if driftgod.R116ResetUniversalRuntimeState then driftgod.R116ResetUniversalRuntimeState(veh) end
            end)
            driftgod.Try(function()
                if driftgod.SafeSetVehicleReduceGrip then driftgod.SafeSetVehicleReduceGrip(veh, false)
                elseif VEHICLE and VEHICLE.SET_VEHICLE_REDUCE_GRIP then VEHICLE.SET_VEHICLE_REDUCE_GRIP(veh, false) end
            end)
            driftgod.Try(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_STEER_BIAS then VEHICLE.SET_VEHICLE_STEER_BIAS(veh, 0.0) end
                if VEHICLE and VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS then
                    VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 0, false)
                    VEHICLE.SET_VEHICLE_INDICATOR_LIGHTS(veh, 1, false)
                end
            end)
        end
    end

    local function R120_heading_of_travel(veh)
        if driftgod.GetHeadingOfTravel then
            local ok, v = driftgod.Try(function() return driftgod.GetHeadingOfTravel(veh) end)
            if ok and v ~= nil then return tonumber(v or 0.0) or 0.0 end
        end
        return 0.0
    end

    local function R120_readable_angle(veh)
        local drift = 0.0
        driftgod.Try(function()
            local heading = 0.0
            if ENTITY and ENTITY.GET_ENTITY_HEADING then heading = ENTITY.GET_ENTITY_HEADING(veh) end
            drift = (tonumber(heading or 0.0) or 0.0) - R120_heading_of_travel(veh)
        end)
        if driftgod.Wrap360 then drift = driftgod.Wrap360(drift) else drift = drift % 360.0 end
        driftgod.S.lastDriftAngle = drift
        local readable = drift
        if readable > 180.0 then readable = 360.0 - readable end
        return readable
    end

    driftgod._R139OriginalApplyMomentum = driftgod._R139OriginalApplyMomentum or driftgod.ApplyMomentum
    driftgod._R139OriginalApplyAccel = driftgod._R139OriginalApplyAccel or driftgod.ApplyAccel
    driftgod._R139OriginalApplyExperimental = driftgod._R139OriginalApplyExperimental or driftgod.ApplyExperimental
    driftgod._R139OriginalApplyAutoCounterSteer = driftgod._R139OriginalApplyAutoCounterSteer or driftgod.ApplyAutoCounterSteer
    driftgod._R139OriginalApplyExperimentalGrip = driftgod._R139OriginalApplyExperimentalGrip or driftgod.ApplyExperimentalGrip
    driftgod._R139OriginalSuperDriveTick = driftgod._R139OriginalSuperDriveTick or driftgod.SuperDriveTick
    driftgod._R139OriginalBoostFXTick = driftgod._R139OriginalBoostFXTick or driftgod.BoostFXTick
    driftgod._R139OriginalHornProbeTick = driftgod._R139OriginalHornProbeTick or driftgod.HornProbeTick

    local function R139TuningOn() return DG and driftgod.S and driftgod.S.driftTuningEnabled == true end
    driftgod.ApplyMomentum = function(...) if R139TuningOn() and driftgod._R139OriginalApplyMomentum then return driftgod._R139OriginalApplyMomentum(...) end end
    driftgod.ApplyAccel = function(...) if R139TuningOn() and driftgod._R139OriginalApplyAccel then return driftgod._R139OriginalApplyAccel(...) end end
    driftgod.ApplyExperimental = function(...) if R139TuningOn() and driftgod._R139OriginalApplyExperimental then return driftgod._R139OriginalApplyExperimental(...) end end
    driftgod.ApplyAutoCounterSteer = function(...) if R139TuningOn() and driftgod._R139OriginalApplyAutoCounterSteer then return driftgod._R139OriginalApplyAutoCounterSteer(...) end end
    driftgod.ApplyExperimentalGrip = function(...) if R139TuningOn() and driftgod._R139OriginalApplyExperimentalGrip then return driftgod._R139OriginalApplyExperimentalGrip(...) end end
    driftgod.SuperDriveTick = function(...) if R139TuningOn() and driftgod._R139OriginalSuperDriveTick then return driftgod._R139OriginalSuperDriveTick(...) end end
    driftgod.BoostFXTick = function(...) if R139TuningOn() and driftgod._R139OriginalBoostFXTick then return driftgod._R139OriginalBoostFXTick(...) end end
    driftgod.HornProbeTick = function(...) if R139TuningOn() and driftgod._R139OriginalHornProbeTick then return driftgod._R139OriginalHornProbeTick(...) end end

    function driftgod.R120PresetOnlyTick()
        driftgod.S = driftgod.S or {}
        if driftgod.S.driftAssistPlusEnabled ~= true and driftgod.S.driftAssistEnabled ~= true then return end
        if not driftgod.HasNatives or not driftgod.HasNatives() then return end

        local veh = R120_vehicle()
        if veh == 0 then
            if driftgod.S.driftWasActive then R120_reset_vehicle(0) end
            return
        end

        if driftgod.VehicleSectorGateTick and not driftgod.VehicleSectorGateTick('drift', veh) then return end

        local held = false
        driftgod.Try(function() if driftgod.IsDriftHeld then held = driftgod.IsDriftHeld() == true end end)
        if not held then
            if driftgod.S.prevGripState or driftgod.S.r116GripOn or driftgod.S.oldGripState then R120_reset_vehicle(veh) end
            return
        end

        if driftgod.IsLockedArcadePresetBlocking and driftgod.IsLockedArcadePresetBlocking() then
            if driftgod.ShowLockedArcadePresetShiftNotice then driftgod.ShowLockedArcadePresetShiftNotice() end
            R120_reset_vehicle(veh)
            return
        end

        driftgod.S.driftWasActive = true
        driftgod.S.prevGripState = true
        driftgod.S.isDrifting = true
        driftgod.S.hudVisibleUntil = R120_now() + (tonumber(driftgod.S.hudFadeAfterMs or 2500) or 2500)
        driftgod.S.hudAlpha = 255

        local kmh = 0.0
        driftgod.Try(function() if ENTITY and ENTITY.GET_ENTITY_SPEED then kmh = (ENTITY.GET_ENTITY_SPEED(veh) or 0.0) * 3.6 end end)
        local readable = R120_readable_angle(veh)

        if driftgod.ApplyArcadeDriftPresetRuntime then
            driftgod.Try(function() driftgod.ApplyArcadeDriftPresetRuntime(veh, kmh, readable, true) end)
        end
    end

    driftgod.DriftTick = function(...)
        return driftgod.R120PresetOnlyTick()
    end

    if Script and Script.RegisterLooped and not driftgod._R120PresetOnlyLoopInstalled then
        driftgod._R120PresetOnlyLoopInstalled = true
        Script.RegisterLooped(function()

            if false and DG and driftgod.S and driftgod.S.driftAssistPlusEnabled == true and driftgod.R120PresetOnlyTick then
                driftgod.R120PresetOnlyTick()
            end
            if Script and Script.Yield then Script.Yield(0) end
        end)
    end

    if driftgod.AddToggleOnTick and not driftgod.H.DriftAssistPlus then
        driftgod.AddToggleOnTick('DriftAssistPlus', 'Drift Assist+ (Legacy Test)', 'Retired test toggle. Use Drift Assist for presets and Tuning for edits.', function(f)
            driftgod.S = driftgod.S or {}
            local newState = f and f.IsToggled and f:IsToggled() == true or false
            local oldState = driftgod.S.driftAssistPlusEnabled == true
            driftgod.S.driftAssistPlusEnabled = newState
            driftgod.S.legacyDriftLogicDisabled = true
            driftgod.S.pureUniversalRuntimeEnabled = true

            if newState ~= oldState then
                local veh = R120_vehicle()
                if not newState then R120_reset_vehicle(veh) end
                if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
