        }
        for _, t in ipairs(tries) do
            local ok, files = driftgod.Try(FileMgr.FindFiles, dir, t[1], t[2])
            if ok and type(files) == "table" then
                for _, f in ipairs(files) do found[#found+1] = tostring(f) end
            end
            if #found > 0 then break end
        end
        return found
    end

    function driftgod.R129_ScanCustomPresets()
        r129_ensure_dirs()
        local paths = {}
        local root = r129_root()
        local dirs = {
            driftgod.R129_CustomPresetDir
        }
        for _, dir in ipairs(dirs) do
            for _, f in ipairs(r129_try_find(dir)) do paths[#paths+1] = f end
        end

        local list, seen, map = {}, {}, {}
        for _, p in ipairs(paths) do
            local name = r129_file_name_from_path(p)
            if name and not seen[name] then
                seen[name] = true
                list[#list+1] = name
                if tostring(p):find("[\\/]", 1, false) then map[name] = p else map[name] = r129_path(name) end
            end
        end

        if driftgod.S.customPresetLastSavedName and not seen[driftgod.S.customPresetLastSavedName] then
            local name = tostring(driftgod.S.customPresetLastSavedName)
            seen[name] = true
            list[#list+1] = name
            map[name] = r129_path(name)
        end

        table.sort(list)
        driftgod.R129_CustomPresetPaths = map
        driftgod.S.customPresetList = list
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        if #list <= 0 then idx = 1 else idx = math.max(1, math.min(idx, #list)) end
        driftgod.S.customPresetIndex = idx
        return list
    end

    function driftgod.R129_SaveCustomPreset()
        r129_ensure_dirs()
        local name = r129_safe_name(driftgod.S.customPresetName or "CustomPreset")
        driftgod.S.customPresetName = name
        driftgod.S.customPresetLastSavedName = name
