        local ok = false
        driftgod.Try(function()
            if FileMgr and FileMgr.WriteFileContent then ok = FileMgr.WriteFileContent(r129_path(name), r129_serialize(data), false) end
        end)
        driftgod.R129_ScanCustomPresets()

        for i, n in ipairs(driftgod.S.customPresetList or {}) do if n == name then driftgod.S.customPresetIndex = i break end end
        if driftgod.Toast then driftgod.Toast(ok and ("Saved custom preset: " .. name) or "Custom preset save failed", 2200) end
        return ok
    end

    function driftgod.R129_ApplyCustomPreset(index)
        local list = driftgod.R129_ScanCustomPresets()
        local i = tonumber(index or driftgod.S.customPresetIndex or 1) or 1
        local name = list[i]
        if not name then if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end; return false end
        local path = (driftgod.R129_CustomPresetPaths and driftgod.R129_CustomPresetPaths[name]) or r129_path(name)
        local ok, data = driftgod.Try(function() return dofile(path) end)
        if not ok or type(data) ~= "table" then if driftgod.Toast then driftgod.Toast("Custom preset load failed", 2200) end; return false end
        for _, k in ipairs(R129PresetKeys) do if data[k] ~= nil then driftgod.S[k] = data[k] end end
        driftgod.S.customPresetIndex = i
