        end)
        if driftgod.S.customPresetLastSavedName == name then driftgod.S.customPresetLastSavedName = nil end
        driftgod.R129_ScanCustomPresets()
        if driftgod.Toast then driftgod.Toast(ok and ("Deleted custom preset: " .. name) or "Custom preset delete failed", 1800) end
