    end

    local function ensure_new_dir()
        mkdir(ROOT .. "\\Lua\\DriftGod")
        mkdir(ROOT .. "\\Lua\\DriftGod\\storage")
        mkdir(NEW_DIR)
    end

    local function safe_name(name)
        name = tostring(name or "CustomPreset")
        name = name:gsub("[^%w%-%_ ]", ""):gsub("%s+", "_")
        if name == "" then name = "CustomPreset" end
        return name
    end

    local function file_name_from_path(path)
        local n = tostring(path or ""):match("([^\\/]+)%.lua$")
        if n and n ~= "" then return n end
        n = tostring(path or ""):match("([^\\/]+)$")
        if n then n = n:gsub("%.lua$", "") end
        if not n or n == "" then return nil end
        return n
    end

    local function new_path(name)
        return NEW_DIR .. safe_name(name) .. ".lua"
    end

    local function find_lua(dir)
        local found = {}
        if FileMgr and FileMgr.FindFiles then
            local tries = {{".lua", false}, {"lua", false}, {".lua", true}, {"lua", true}}
            for _, t in ipairs(tries) do
                local ok, files = driftgod.Try(FileMgr.FindFiles, dir, t[1], t[2])
                if ok and type(files) == "table" then
                    for _, f in ipairs(files) do found[#found+1] = tostring(f) end
                end
                if #found > 0 then break end
            end
        end
        return found
    end

    local function read_file(path)
        local body = nil
        driftgod.Try(function()
            if FileMgr and FileMgr.ReadFileContent then body = FileMgr.ReadFileContent(path) end
        end)
        if body == nil and io and io.open then
            driftgod.Try(function()
                local f = io.open(path, "rb")
                if f then body = f:read("*a"); f:close() end
            end)
        end
        return body
    end

    local function write_file(path, body)
        local ok = false
        driftgod.Try(function()
            if FileMgr and FileMgr.WriteFileContent then ok = FileMgr.WriteFileContent(path, tostring(body or ""), false) end
        end)
        if not ok and io and io.open then
            driftgod.Try(function()
                local f = io.open(path, "wb")
                if f then f:write(tostring(body or "")); f:close(); ok = true end
            end)
        end
        return ok
    end

    function driftgod.R132_MigrateCustomPresetsFolder()

        ensure_new_dir()
        driftgod.S.presetsFolderMigrated = true
        return 0
    end

    driftgod.Try(driftgod.R132_MigrateCustomPresetsFolder)

    driftgod.R132_CustomPresetDir = NEW_DIR
    driftgod.R130_CustomPresetDir = NEW_DIR
    driftgod.R129_CustomPresetDir = NEW_DIR
    driftgod.R110_CustomPresetDir = NEW_DIR
    driftgod.R109_CustomPresetDir = NEW_DIR

    local PresetKeys = {
        "driftAssistPlusEnabled", "pureUniversalRuntimeEnabled", "legacyDriftLogicDisabled",
        "driftGripLevel", "driftStabilityLevel", "autoCounterSteerLevel",
        "momentumAssistEnabled", "momentumStrength",
        "accelAssistEnabled", "accelStrength",
        "experimentalGravityEnabled", "experimentalGravityStrength",
        "experimentalAccelEnabled", "experimentalAccelStrength",
        "experimentalTractionEnabled", "experimentalTractionLevel",
        "experimentalGripEnabled", "experimentalGripLevel",
        "activeArcadeDriftPreset", "arcadePresetRuntimeAssist",
        "customPresetSavedAt", "customPresetBasePreset", "presetName"
    }

    local function serialize(tbl)
        local out = { "return {" }
        local wrote = {}
        for _, k in ipairs(PresetKeys) do
            local v = tbl[k]
            if v ~= nil and not wrote[k] then
                wrote[k] = true
                if type(v) == "number" or type(v) == "boolean" then
                    out[#out+1] = "  " .. k .. " = " .. tostring(v) .. ","
                elseif type(v) == "string" then
                    out[#out+1] = "  " .. k .. " = " .. string.format("%q", v) .. ","
                end
            end
        end
        out[#out+1] = "}"
        return table.concat(out, "\n")
    end

    local function read_saved_at(path, name)
        local ok, data = driftgod.Try(function() return dofile(path) end)
        if ok and type(data) == "table" then
            return tonumber(data.customPresetSavedAt or data.savedAt or 0) or 0
        end
        return 0
    end

    function driftgod.R132_ScanCustomPresets()
        ensure_new_dir()
        local records, map, seen = {}, {}, {}
        for _, f in ipairs(find_lua(NEW_DIR)) do
            local name = file_name_from_path(f)
            if name and not seen[name] then
                local path = tostring(f):find("[\\/]", 1, false) and tostring(f) or (NEW_DIR .. tostring(f))
                seen[name] = true
                map[name] = path
                records[#records+1] = { name=name, path=path, savedAt=read_saved_at(path, name) }
            end
        end
        if driftgod.S.customPresetLastSavedName and not seen[driftgod.S.customPresetLastSavedName] then
            local name = tostring(driftgod.S.customPresetLastSavedName)
            seen[name] = true
            map[name] = new_path(name)
            records[#records+1] = { name=name, path=new_path(name), savedAt=9999999999 }
        end
        table.sort(records, function(a,b)
            local at, bt = tonumber(a.savedAt or 0) or 0, tonumber(b.savedAt or 0) or 0
            if at ~= bt then return at > bt end
            return tostring(a.name):lower() < tostring(b.name):lower()
        end)
        local list = {}
        for _, r in ipairs(records) do list[#list+1] = r.name end
        driftgod.R129_CustomPresetPaths = map
        driftgod.R130_CustomPresetRecords = records
        driftgod.S.customPresetList = list
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        if #list <= 0 then idx = 1 else idx = math.max(1, math.min(idx, #list)) end
        driftgod.S.customPresetIndex = idx
        return list
    end

    function driftgod.R132_SaveCustomPreset()
        ensure_new_dir()
        local name = safe_name(driftgod.S.customPresetName or "CustomPreset")
        driftgod.S.customPresetName = name
        driftgod.S.customPresetLastSavedName = name
        local data = {
            presetName = name,
            customPresetSavedAt = (os and os.time and os.time()) or math.floor((driftgod.Now and driftgod.Now()) or 0),
            customPresetBasePreset = tostring(driftgod.S.activeArcadeDriftPreset or "")
        }
        for _, k in ipairs(PresetKeys) do if data[k] == nil then data[k] = driftgod.S[k] end end
        local ok = write_file(new_path(name), serialize(data))
        driftgod.R132_ScanCustomPresets()
        for i, n in ipairs(driftgod.S.customPresetList or {}) do if n == name then driftgod.S.customPresetIndex = i break end end
        if driftgod.Toast then driftgod.Toast(ok and ("Saved preset: " .. name) or "Preset save failed", 2200) end
        return ok
    end

    function driftgod.R132_ApplyCustomPreset(index)
        local list = driftgod.R132_ScanCustomPresets()
        local i = tonumber(index or driftgod.S.customPresetIndex or 1) or 1
        local name = list[i]
        if not name then if driftgod.Toast then driftgod.Toast("No preset selected", 1800) end; return false end
        local path = (driftgod.R129_CustomPresetPaths and driftgod.R129_CustomPresetPaths[name]) or new_path(name)
        local ok, data = driftgod.Try(function() return dofile(path) end)
        if not ok or type(data) ~= "table" then if driftgod.Toast then driftgod.Toast("Preset load failed", 2200) end; return false end
        for _, k in ipairs(PresetKeys) do if data[k] ~= nil then driftgod.S[k] = data[k] end end
        driftgod.S.customPresetIndex = i
        local preset = data.activeArcadeDriftPreset or data.customPresetBasePreset
        if preset and preset ~= "" and driftgod.ApplyArcadeDriftPreset then driftgod.Try(function() driftgod.ApplyArcadeDriftPreset(preset, true) end) end
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Applied preset: " .. tostring(name), 1600) end
        return true
    end

    function driftgod.R132_DeleteCustomPreset(index)
        local list = driftgod.R132_ScanCustomPresets()
        local i = tonumber(index or driftgod.S.customPresetIndex or 1) or 1
        local name = list[i]
        if not name then if driftgod.Toast then driftgod.Toast("No preset selected", 1600) end; return false end
        local path = (driftgod.R129_CustomPresetPaths and driftgod.R129_CustomPresetPaths[name]) or new_path(name)
        local ok = false
        driftgod.Try(function()
            if FileMgr and FileMgr.DeleteFile then ok = FileMgr.DeleteFile(path)
            elseif os and os.remove then ok = os.remove(path) == true end
        end)
        if driftgod.S.customPresetLastSavedName == name then driftgod.S.customPresetLastSavedName = nil end
        driftgod.R132_ScanCustomPresets()
        if driftgod.Toast then driftgod.Toast(ok and ("Deleted preset: " .. name) or "Preset delete failed", 1800) end
        return ok
    end

    driftgod.R109_ScanCustomPresets = driftgod.R132_ScanCustomPresets
    driftgod.R110_ScanCustomPresets = driftgod.R132_ScanCustomPresets
    driftgod.R129_ScanCustomPresets = driftgod.R132_ScanCustomPresets
