        mkdir(ROOT .. "\\Lua\\DriftGod\\storage")
        mkdir(PRESET_DIR)
    end

    local function safe_name(name)
        name = tostring(name or "CustomPreset")
        name = name:gsub("[^%w%-%_ ]", ""):gsub("%s+", "_")
        if name == "" then name = "CustomPreset" end
        return name
    end

    local function path_for(name)
        return PRESET_DIR .. safe_name(name) .. ".lua"
    end

    local function file_name(path)
        local n = tostring(path or ""):match("([^\\/]+)%.lua$")
        if n and n ~= "" then return n end
        n = tostring(path or ""):match("([^\\/]+)$")
        if n then n = n:gsub("%.lua$", "") end
        if not n or n == "" then return nil end
        return n
    end

    local function find_lua(dir)
        local found = {}
        if FileMgr and FileMgr.FindFiles then
            local tries = {{".lua", false}, {"lua", false}, {".lua", true}, {"lua", true}}
            for _, t in ipairs(tries) do
