                local f = io.open(path, "wb")
                if f then f:write(tostring(body or "")); f:close(); ok = true end
            end)
        end
        return ok
    end

    local Keys = {
        "presetName", "customPresetSavedAt", "customPresetSavedAtMs", "customPresetSavedSort", "customPresetBasePreset",
        "driftAssistPlusEnabled", "pureUniversalRuntimeEnabled", "legacyDriftLogicDisabled",
        "driftGripLevel", "driftStabilityLevel", "autoCounterSteerLevel",
        "momentumAssistEnabled", "momentumStrength",
        "accelAssistEnabled", "accelStrength",
        "experimentalGravityEnabled", "experimentalGravityStrength",
        "experimentalAccelEnabled", "experimentalAccelStrength",
        "experimentalTractionEnabled", "experimentalTractionLevel",
        "experimentalGripEnabled", "experimentalGripLevel",
        "activeArcadeDriftPreset", "arcadePresetRuntimeAssist"
    }

    local function serialize(tbl)
        local out = { "return {" }
        local wrote = {}
        for _, k in ipairs(Keys) do
            local v = tbl[k]
            if v ~= nil and not wrote[k] then
                wrote[k] = true
                if type(v) == "number" or type(v) == "boolean" then
                    out[#out + 1] = "  " .. k .. " = " .. tostring(v) .. ","
                elseif type(v) == "string" then
                    out[#out + 1] = "  " .. k .. " = " .. string.format("%q", v) .. ","
                end
            end
        end
        out[#out + 1] = "}"
        return table.concat(out, "\n")
    end

    local function load_table(path)
        local ok, data = driftgod.Try(function() return dofile(path) end)
        if ok and type(data) == "table" then return data end
        return nil
    end

    local function sort_key(path)
        local data = load_table(path)
        if type(data) == "table" then
            return tonumber(data.customPresetSavedSort)
                or tonumber(data.customPresetSavedAtMs)
                or ((tonumber(data.customPresetSavedAt or data.savedAt or 0) or 0) * 1000000)
                or 0
        end
        return 0
    end

    function driftgod.R136_ScanCustomPresets()
        ensure_dir()
        local records, paths, seen = {}, {}, {}
        for _, f in ipairs(find_lua(PRESET_DIR)) do
            local name = file_name(f)
            if name and not seen[name] then
                local fullPath = tostring(f):find("[\\/]", 1, false) and tostring(f) or (PRESET_DIR .. tostring(f))
                seen[name] = true
                paths[name] = fullPath
                records[#records + 1] = { name = name, path = fullPath, sortKey = sort_key(fullPath) }
            end
        end
        table.sort(records, function(a, b)
            local ak, bk = tonumber(a.sortKey or 0) or 0, tonumber(b.sortKey or 0) or 0
            if ak ~= bk then return ak > bk end
            return tostring(a.name):lower() < tostring(b.name):lower()
        end)
        local list = {}
        for _, r in ipairs(records) do list[#list + 1] = r.name end
        driftgod.R129_CustomPresetPaths = paths
        driftgod.R130_CustomPresetRecords = records
        driftgod.R136_CustomPresetRecords = records
        driftgod.S.customPresetList = list
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        if #list <= 0 then idx = 1 else idx = math.max(1, math.min(idx, #list)) end
        driftgod.S.customPresetIndex = idx
        return list
    end

    local function next_sort_stamp()
        local sec = (os and os.time and os.time()) or 0
        local clk = (os and os.clock and os.clock()) or 0
        local now = (sec * 1000000) + math.floor(clk * 1000000)
        local last = tonumber(driftgod.S.customPresetLastSortStamp or 0) or 0
        if now <= last then now = last + 1 end
        driftgod.S.customPresetLastSortStamp = now
        return now
    end

    function driftgod.R136_SaveCustomPreset()
        ensure_dir()
        local name = safe_name(driftgod.S.customPresetName or "CustomPreset")
        driftgod.S.customPresetName = name
        driftgod.S.customPresetLastSavedName = name
        local stamp = next_sort_stamp()
        local data = {
            presetName = name,
            customPresetSavedAt = (os and os.time and os.time()) or 0,
            customPresetSavedAtMs = stamp,
            customPresetSavedSort = stamp,
            customPresetBasePreset = tostring(driftgod.S.activeArcadeDriftPreset or "")
        }
        for _, k in ipairs(Keys) do if data[k] == nil then data[k] = driftgod.S[k] end end
        local ok = write_file(path_for(name), serialize(data))
        driftgod.R136_ScanCustomPresets()
        for i, n in ipairs(driftgod.S.customPresetList or {}) do if n == name then driftgod.S.customPresetIndex = i break end end
        if driftgod.Toast then driftgod.Toast(ok and ("Saved preset: " .. name) or "Preset save failed", 1800) end
        return ok
    end

    function driftgod.R136_ApplyCustomPreset(index)
        local list = driftgod.R136_ScanCustomPresets()
        local i = tonumber(index or driftgod.S.customPresetIndex or 1) or 1
        local name = list[i]
        if not name then if driftgod.Toast then driftgod.Toast("No preset selected", 1400) end; return false end
        local path = (driftgod.R129_CustomPresetPaths and driftgod.R129_CustomPresetPaths[name]) or path_for(name)
        local data = load_table(path)
        if type(data) ~= "table" then if driftgod.Toast then driftgod.Toast("Preset load failed", 1800) end; return false end
        for _, k in ipairs(Keys) do if data[k] ~= nil then driftgod.S[k] = data[k] end end
        driftgod.S.customPresetIndex = i
        local preset = data.activeArcadeDriftPreset or data.customPresetBasePreset
        if preset and preset ~= "" and driftgod.ApplyArcadeDriftPreset then driftgod.Try(function() driftgod.ApplyArcadeDriftPreset(preset, true) end) end
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Applied preset: " .. tostring(name), 1400) end
        return true
    end

    function driftgod.R136_DeleteCustomPreset(index)
        local list = driftgod.R136_ScanCustomPresets()
        local i = tonumber(index or driftgod.S.customPresetIndex or 1) or 1
        local name = list[i]
        if not name then if driftgod.Toast then driftgod.Toast("No preset selected", 1400) end; return false end
        local path = (driftgod.R129_CustomPresetPaths and driftgod.R129_CustomPresetPaths[name]) or path_for(name)
        local ok = false
        driftgod.Try(function()
            if FileMgr and FileMgr.DeleteFile then ok = FileMgr.DeleteFile(path)
            elseif os and os.remove then ok = os.remove(path) == true end
        end)
        driftgod.R136_ScanCustomPresets()
        if driftgod.Toast then driftgod.Toast(ok and ("Deleted preset: " .. name) or "Preset delete failed", 1500) end
        return ok
    end

