        elseif dgA38Text then driftgod.Try(dgA38Text, tostring(t or ""), color)
        elseif ImGui and ImGui.TextColored and color == "purple" then driftgod.Try(ImGui.TextColored, 0.74, 0.45, 1.0, 1.0, tostring(t or ""))
        elseif ImGui and ImGui.TextColored and color == "gold" then driftgod.Try(ImGui.TextColored, 1.0, 0.78, 0.18, 1.0, tostring(t or ""))
        elseif ImGui and ImGui.TextColored and color == "cyan" then driftgod.Try(ImGui.TextColored, 0.25, 0.85, 1.0, 1.0, tostring(t or ""))
        elseif ImGui and ImGui.TextColored and color == "green" then driftgod.Try(ImGui.TextColored, 0.35, 1.0, 0.55, 1.0, tostring(t or ""))
        elseif ImGui and ImGui.Text then driftgod.Try(ImGui.Text, tostring(t or "")) end
    end

    local function button(label, cb, purple)
        local pushed = false
        if purple and ImGui and ImGui.PushStyleColor and ImGui.Col and ImGui.Col.Button then
            driftgod.Try(function()
                ImGui.PushStyleColor(ImGui.Col.Button, 0.45, 0.20, 0.85, 1.0)
                ImGui.PushStyleColor(ImGui.Col.ButtonHovered, 0.58, 0.30, 1.0, 1.0)
                ImGui.PushStyleColor(ImGui.Col.ButtonActive, 0.35, 0.13, 0.70, 1.0)
                pushed = true
            end)
        end
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label)) end) end
        if pushed and ImGui.PopStyleColor then driftgod.Try(ImGui.PopStyleColor, 3) end
        if clicked and cb then driftgod.Try(cb) end
        return clicked
    end

    local function builtin_rows(family)
        local out = {}
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            if tostring(p.family or "") == tostring(family or "") then out[#out + 1] = p end
        end
        return out
    end

    function driftgod.R110_RenderPresetColumns(id)
        local groups = {
            { label = "Starter", color = "gold", sections = { { family = "Default / Starter" }, { label = "Very Open", color = "green", family = "Open" } } },
            { label = "Wide Road", color = "cyan", sections = { { family = "Wide / Open Roads" } } },
            { label = "Technical", color = "purple", sections = { { family = "Technical / Windy Roads" } } },
            { label = "Custom", color = "purple", custom = true },
        }

        local function render_builtin(section)
            if section.label then txt(section.label, section.color or "white") end
            local rows = builtin_rows(section.family)
            if #rows <= 0 then txt("No presets", "dim") end
            for _, p in ipairs(rows) do
                txt(tostring(p.name or p.id or "Preset"), "white")
                button("Apply##R136_" .. tostring(p.id or p.name), function()
                    if driftgod.ApplyArcadeDriftPreset then driftgod.ApplyArcadeDriftPreset(p.id, true) end
                end, true)
            end
        end

        local function render_custom_recent()
            local list = driftgod.R136_ScanCustomPresets()
            if #list <= 0 then txt("No custom presets yet", "dim"); return end
            local max = math.min(3, #list)
            for i = 1, max do
                local name = list[i]
                txt(tostring(name), "white")
                button("Apply##R136_Custom_" .. tostring(i), function() driftgod.R136_ApplyCustomPreset(i) end, true)
            end
            if #list > 3 then txt("More in Custom Preset dropdown", "dim") end
        end

        local flags = dgSafeTableFlags and dgSafeTableFlags() or 0
        if ImGui and ImGui.BeginTable and ImGui.BeginTable(id or "DG_R136_PresetColumns", 4, flags) then
            for _, g in ipairs(groups) do if ImGui.TableSetupColumn then driftgod.Try(ImGui.TableSetupColumn, g.label) end end
            if ImGui.TableNextRow then ImGui.TableNextRow() end
            for c, g in ipairs(groups) do
                if ImGui.TableSetColumnIndex then ImGui.TableSetColumnIndex(c - 1) end
                txt(g.label, g.color)
            end
            if ImGui.TableNextRow then ImGui.TableNextRow() end
            for c, g in ipairs(groups) do
                if ImGui.TableSetColumnIndex then ImGui.TableSetColumnIndex(c - 1) end
                if g.custom then
                    render_custom_recent()
                else
                    for si, section in ipairs(g.sections or {}) do
                        if si > 1 and ImGui.Spacing then driftgod.Try(ImGui.Spacing) end
                        render_builtin(section)
                    end
                end
            end
            if ImGui.EndTable then ImGui.EndTable() end
        else
            for _, g in ipairs(groups) do
                txt(g.label, g.color)
                if g.custom then render_custom_recent() else for _, section in ipairs(g.sections or {}) do render_builtin(section) end end
            end
        end
    end

    driftgod.Try(driftgod.R136_ScanCustomPresets)
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.LastUpdated = "2026-06-26"
end)

driftgod.Try(function()
    DG = DG or {}
    driftgod.S = driftgod.S or {}

    local function nowMs()
        if driftgod.Now then
            local ok, v = driftgod.Try(driftgod.Now)
            if ok and tonumber(v) then return tonumber(v) end
        end
        return math.floor((os.clock() or 0) * 1000)
    end

    local SAVE_INTERVAL_MS = 300000
    driftgod.S.progressSaveThrottleMs = tonumber(driftgod.S.progressSaveThrottleMs or SAVE_INTERVAL_MS) or SAVE_INTERVAL_MS
    if driftgod.S.progressSaveThrottleMs < SAVE_INTERVAL_MS then driftgod.S.progressSaveThrottleMs = SAVE_INTERVAL_MS end
    driftgod.S.progressDirty = driftgod.S.progressDirty or false
    driftgod.S.lastProgressDiskWriteMs = tonumber(driftgod.S.lastProgressDiskWriteMs or 0) or 0

    local rawSaveProgress = driftgod.SaveProgress
    local rawSaveProgressHard = driftgod.SaveProgressHard

    local function canWriteProgress(showToast, reason)

        if showToast == true then return true end

        local now = nowMs()
        local last = tonumber(driftgod.S.lastProgressDiskWriteMs or 0) or 0
        if last <= 0 then
            driftgod.S.lastProgressDiskWriteMs = now
            driftgod.S.progressDirty = true
            return false
        end

        if (now - last) >= (tonumber(driftgod.S.progressSaveThrottleMs or SAVE_INTERVAL_MS) or SAVE_INTERVAL_MS) then
            driftgod.S.lastProgressDiskWriteMs = now
            driftgod.S.progressDirty = false
            return true
        end

        driftgod.S.progressDirty = true
        driftgod.S.lastProgressDirtyReason = tostring(reason or "throttled")
        return false
    end

    function driftgod.SaveProgress(showToast)
        if not rawSaveProgress then return false end
        if not canWriteProgress(showToast, "SaveProgress") then
            return true
        end
        return rawSaveProgress(showToast)
    end

    function driftgod.SaveProgressHard(reason)
        if not rawSaveProgressHard and not rawSaveProgress then return false end
        if not canWriteProgress(false, reason or "SaveProgressHard") then
            return true
        end
        if rawSaveProgressHard then return rawSaveProgressHard(reason) end
        return rawSaveProgress(false)
    end

    local rawAutoSaveTick = driftgod.AutoSaveTick
    function driftgod.AutoSaveTick()
        local now = nowMs()
        local interval = tonumber(driftgod.S.progressSaveThrottleMs or SAVE_INTERVAL_MS) or SAVE_INTERVAL_MS
        if driftgod.S.progressDirty == true and ((tonumber(driftgod.S.lastProgressDiskWriteMs or 0) or 0) <= 0 or (now - (tonumber(driftgod.S.lastProgressDiskWriteMs or 0) or 0)) >= interval) then
            driftgod.S.lastProgressDiskWriteMs = now
            driftgod.S.progressDirty = false
            if rawSaveProgress then rawSaveProgress(false) end
            return
        end
        if rawAutoSaveTick then

            return rawAutoSaveTick()
        end
    end

    driftgod.R137_FlushProgressIfDirty = function()
        if driftgod.S and driftgod.S.progressDirty == true and rawSaveProgress then
            driftgod.S.progressDirty = false
            driftgod.S.lastProgressDiskWriteMs = nowMs()
            return rawSaveProgress(false)
        end
        return true
    end

    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.LastUpdated = "2026-06-26"
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.S.driftAssistPlusEnabled = false
    if driftgod.S.driftTuningEnabled == nil then driftgod.S.driftTuningEnabled = false end
    if driftgod.AddToggle and not driftgod.H.DriftTuningMaster then
        driftgod.AddToggle('DriftTuningMaster', 'Tuning', 'Required for Drift Tuning toggles. Values cap at unlocked levels..', function(f)
            driftgod.S.driftTuningEnabled = (driftgod.S.driftAssistEnabled == true) and f and f.IsToggled and f:IsToggled() == true or false
            if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        end, false)
    end
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    if driftgod.S.superDriveDirection == nil then driftgod.S.superDriveDirection = "camera" end
    if driftgod.S.superDriveSurfaceGrip == nil then driftgod.S.superDriveSurfaceGrip = 100 end

    local function r140Hash(key)
        if driftgod.Hash then return driftgod.Hash("R140_" .. tostring(key)) end
        return Utils.Joaat("DG_R140_" .. tostring(key))
    end

    local function r140Toast(msg, ms)
        if driftgod.Toast then driftgod.Toast(tostring(msg), ms or 1400)
        elseif GUI and GUI.AddToast then GUI.AddToast("DriftGod", tostring(msg), ms or 1400) end
    end

    local function r140Clamp(v, mn, mx)
        v = tonumber(v) or mn
        if v < mn then return mn end
        if v > mx then return mx end
        return v
    end

    function driftgod.R187_SetRoadSurfaceEnabled(enabled)
        driftgod.S.roadSurfaceEnabled = enabled == true
        if driftgod.S.roadSurfaceEnabled ~= true then
            driftgod.S.superDriveSurfaceGrip = 100
            driftgod.S.superDriveIceMode = false
            driftgod.S.superDriveLowGrip = false
            driftgod.S.superDriveIceFriction = 0.60
        end
        driftgod.Try(function()
            local veh = (getVehicle and getVehicle()) or 0
            if veh and veh ~= 0 and applyGripMode then applyGripMode(veh) end
        end)
    end

    function driftgod.R140_SetPTFXEnabled(enabled)

        driftgod.S.ptfxRunning = enabled == true
        if enabled == true then
            driftgod.S.ptfxFreemode = true
            driftgod.S.ptfxUseFreemode = true
            driftgod.S.ptfxFreemodeMode = true
            driftgod.Try(function()
                if driftgod.H.PTFXToggleFreemodeClean and FeatureMgr and FeatureMgr.GetFeature then
                    local f = FeatureMgr.GetFeature(driftgod.H.PTFXToggleFreemodeClean)
                    if f and f.SetBoolValue then f:SetBoolValue(true) end
                end
            end)
        end
        driftgod.S._r143PtfxBusy = true
        local ok, err
        if enabled == true then
            ok, err = driftgod.Try(function() if driftgod.StartPTFX then driftgod.StartPTFX() end end)
        else
            ok, err = driftgod.Try(function() if driftgod.StopPTFX then driftgod.StopPTFX() end end)
        end
        driftgod.S._r143PtfxBusy = false
        if ok then driftgod.S._r143PtfxSelectionDirty = false end
        if not ok and driftgod.Log then driftgod.Log("[PTFX] toggle failed safely: " .. tostring(err)) end
    end

    function driftgod.R140_SetSurfaceGrip(percent)

        driftgod.S.superDriveSurfaceGrip = math.floor(r140Clamp(percent, 0, 100) + 0.5)
        if driftgod.S.roadSurfaceEnabled ~= true then
            driftgod.S.superDriveSurfaceGrip = 100
        end
        local p = driftgod.S.superDriveSurfaceGrip
        if p >= 100 then
            driftgod.S.superDriveIceMode = false
            driftgod.S.superDriveLowGrip = false
            driftgod.S.superDriveIceFriction = 0.60
        else
            driftgod.S.superDriveIceMode = true
            driftgod.S.superDriveLowGrip = false

            driftgod.S.superDriveIceFriction = r140Clamp((p / 100.0) * 0.60, 0.0, 0.60)
        end
        driftgod.Try(function()
            local veh = (getVehicle and getVehicle()) or 0
            if veh and veh ~= 0 and applyGripMode then applyGripMode(veh) end
        end)
    end

    function driftgod.R140_SurfaceGripLabel()
        local p = tonumber(driftgod.S.superDriveSurfaceGrip or 100) or 100
        if p >= 100 then return "Normal" end
        if p >= 75 then return "Sport / Mild Slip" end
        if p >= 50 then return "Low Grip" end
        if p >= 20 then return "Ice" end
        return "Zero Traction"
    end

    function driftgod.R140_RegisterBetaFeatures()
        if driftgod.__R140BetaFeaturesRegistered then return end
        driftgod.__R140BetaFeaturesRegistered = true

        driftgod.H.R140_PTFXEnabled = r140Hash("PTFXEnabled")
        driftgod.H.R140_SuperDriveSpeed = r140Hash("SuperDriveSpeed")
        driftgod.H.R140_SuperDriveAccel = r140Hash("SuperDriveAccel")
        driftgod.H.R187_RoadSurfaceToggle = r140Hash("RoadSurfaceToggle")
        driftgod.H.R140_SurfaceGrip = r140Hash("SurfaceGrip")

        if driftgod.SafeAddFeature and eFeatureType then
            driftgod.SafeAddFeature(driftgod.H.R140_PTFXEnabled, "Enable PTFX", eFeatureType.Toggle, "", function(f)
                local on = false
                driftgod.Try(function() on = f:IsToggled() == true end)
                driftgod.R140_SetPTFXEnabled(on)
            end)

            local spd = driftgod.SafeAddFeature(driftgod.H.R140_SuperDriveSpeed, "Speed", eFeatureType.SliderInt, "", function(f)
                local v = tonumber(driftgod.S.superDriveSpeed or 16) or 16
                driftgod.Try(function() if f.GetIntValue then v = f:GetIntValue() end end)
                driftgod.S.superDriveSpeed = r140Clamp(v, 3, 90)
                driftgod.S.superDriveMaxSpeed = math.max(tonumber(driftgod.S.superDriveMaxSpeed or 48) or 48, driftgod.S.superDriveSpeed)
            end)
            if spd then
                driftgod.Try(function() if spd.SetLimitValues then spd:SetLimitValues(3, 90) end end)
                driftgod.Try(function() if spd.SetStepSize then spd:SetStepSize(1) end end)
                driftgod.Try(function() if spd.SetIntValue then spd:SetIntValue(math.floor(tonumber(driftgod.S.superDriveSpeed or 16) or 16)) end end)
            end

            local acc = driftgod.SafeAddFeature(driftgod.H.R140_SuperDriveAccel, "Acceleration", eFeatureType.SliderInt, "", function(f)

                local pct = math.floor(((tonumber(driftgod.S.superDriveAccel or 0.18) or 0.18) / 1.25) * 100 + 0.5)
                driftgod.Try(function() if f.GetIntValue then pct = f:GetIntValue() end end)
                pct = r140Clamp(pct, 1, 100)
                driftgod.S.superDriveAccel = r140Clamp((pct / 100.0) * 1.25, 0.05, 1.25)
            end)
            if acc then
                driftgod.Try(function() if acc.SetLimitValues then acc:SetLimitValues(1, 100) end end)
                driftgod.Try(function() if acc.SetStepSize then acc:SetStepSize(1) end end)
                driftgod.Try(function() if acc.SetIntValue then acc:SetIntValue(math.floor(((tonumber(driftgod.S.superDriveAccel or 0.18) or 0.18) / 1.25) * 100 + 0.5)) end end)
            end

            driftgod.SafeAddFeature(driftgod.H.R187_RoadSurfaceToggle, "Road Surface", eFeatureType.Toggle, "Enables Road Surface / Grip changes.", function(f)
                local on = false
                driftgod.Try(function() on = f:IsToggled() == true end)
                driftgod.R187_SetRoadSurfaceEnabled(on)
            end, false)

            local grip = driftgod.SafeAddFeature(driftgod.H.R140_SurfaceGrip, "Grip", eFeatureType.SliderInt, "", function(f)
                local v = driftgod.S.superDriveSurfaceGrip or 100
                driftgod.Try(function() if f.GetIntValue then v = f:GetIntValue() end end)
                driftgod.R140_SetSurfaceGrip(v)
            end)
            if grip then
                driftgod.Try(function() if grip.SetLimitValues then grip:SetLimitValues(0, 100) end end)
                driftgod.Try(function() if grip.SetStepSize then grip:SetStepSize(5) end end)
                driftgod.Try(function() if grip.SetIntValue then grip:SetIntValue(math.floor(tonumber(driftgod.S.superDriveSurfaceGrip or 100) or 100)) end end)
            end
        end
    end

    local function r140RenderFeature(hash, fallbackLabel)
        if ClickGUI and ClickGUI.RenderFeature then
            local ok = driftgod.Try(function() ClickGUI.RenderFeature(hash) end)
            if ok then return end
        end
        if ImGui and ImGui.Text then ImGui.Text(tostring(fallbackLabel or "Unavailable")) end
    end

    local function r140Combo(label, preview, items, currentIndex, onSelect)
        if not (ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo) then
            ImGui.Text(tostring(label) .. ": " .. tostring(preview))
            return currentIndex
        end
        local changedIndex = currentIndex
        local opened = false
        driftgod.Try(function() opened = ImGui.BeginCombo(label, tostring(preview or "Select")) end)
        if opened then
            for i, item in ipairs(items or {}) do
                local itemLabel = tostring(item.label or item.name or item[1] or item)
                local selected = (i == currentIndex)
                local clicked = false
                driftgod.Try(function() clicked = ImGui.Selectable(itemLabel, selected) end)
                if clicked then
                    changedIndex = i
                    if onSelect then onSelect(i, item) end
                end
            end
            driftgod.Try(function() ImGui.EndCombo() end)
        end
        return changedIndex
    end

    local function r140PtfxLocationLabel(loc)
        loc = tostring(loc or "wheels")
        if loc == "exhaust" then return "Exhaust" end
        if loc == "taillights" then return "Rear Taillights" end
        return "Wheels"
    end

    function driftgod.R140_RenderPTFXBeta()
        driftgod.R140_RegisterBetaFeatures()
        driftgod.S.ptfxSelectedIndex = tonumber(driftgod.S.ptfxSelectedIndex or 1) or 1
        driftgod.S.ptfxLocation = tostring(driftgod.S.ptfxLocation or "wheels")

        if ClickGUI.BeginCustomChildWindow("PTFX") then
            r140RenderFeature(driftgod.H.R140_PTFXEnabled, "Enable PTFX")
            local effects = driftgod.PTFX and driftgod.PTFX.effects or {}
            local fx = effects[driftgod.S.ptfxSelectedIndex] or effects[1]
            r140Combo("PTFX Effect", fx and fx.label or "None", effects, driftgod.S.ptfxSelectedIndex, function(i)
                driftgod.S.ptfxSelectedIndex = i
                driftgod.S._r143PtfxSelectionDirty = true
            end)
            local locItems = {
                { label = "Exhaust", value = "exhaust" },
                { label = "Wheels", value = "wheels" },
                { label = "Rear Taillights", value = "taillights" },
            }
            local locIndex = (driftgod.S.ptfxLocation == "exhaust" and 1) or (driftgod.S.ptfxLocation == "taillights" and 3) or 2
            r140Combo("PTFX Location", r140PtfxLocationLabel(driftgod.S.ptfxLocation), locItems, locIndex, function(_, item)
                driftgod.S.ptfxLocation = item.value
                driftgod.S._r143PtfxSelectionDirty = true
            end)
            if driftgod.S._r143PtfxSelectionDirty == true and driftgod.S.ptfxRunning == true and ImGui and ImGui.Text then
                ImGui.Text("Selection changed. Toggle Enable PTFX OFF/ON to apply.")
            end

            ClickGUI.EndCustomChildWindow()
        end
    end

    function driftgod.R140_RenderSuperDriveBeta()
        driftgod.R140_RegisterBetaFeatures()
        if ClickGUI.BeginCustomChildWindow("Super Drive") then
            ImGui.Text(tostring(driftgod.SuperDriveStatus and driftgod.SuperDriveStatus() or "Super Drive"))
            if driftgod.H.SuperDriveOptionToggle then r140RenderFeature(driftgod.H.SuperDriveOptionToggle, "Super Drive") end
            local modeItems = {
                { label = "Cam", value = "camera" },
                { label = "Vehicle", value = "vehicle" },
                { label = "WASD", value = "wasd" },
            }
            local curMode = tostring(driftgod.S.superDriveDirection or "camera")
            local modeIndex = (curMode == "vehicle" and 2) or (curMode == "wasd" and 3) or 1
            local modePreview = modeItems[modeIndex] and modeItems[modeIndex].label or "Cam"
            r140Combo("Super Drive Mode", modePreview, modeItems, modeIndex, function(_, item)
                driftgod.S.superDriveDirection = tostring(item.value or "camera")
                if driftgod.S.superDriveDirection == "vehicle" and driftgod.SetSuperDriveDirectionVehicle then driftgod.SetSuperDriveDirectionVehicle()
                elseif driftgod.S.superDriveDirection == "wasd" and driftgod.SetSuperDriveDirectionWASD then driftgod.SetSuperDriveDirectionWASD()
                elseif driftgod.SetSuperDriveDirectionCamera then driftgod.SetSuperDriveDirectionCamera() end
            end)
            ImGui.Text("Speed / Acceleration")
            r140RenderFeature(driftgod.H.R140_SuperDriveSpeed, "Speed")
            r140RenderFeature(driftgod.H.R140_SuperDriveAccel, "Acceleration")
            ClickGUI.EndCustomChildWindow()
        end
    end

    function driftgod.R140_RenderRoadSurfaceBeta()
        driftgod.R140_RegisterBetaFeatures()
        if ClickGUI.BeginCustomChildWindow("Road Surface") then
            r140RenderFeature(driftgod.H.R187_RoadSurfaceToggle, "Road Surface")
            if driftgod.S.roadSurfaceEnabled == true then
                ImGui.Text("Surface: " .. tostring(driftgod.R140_SurfaceGripLabel()))
                r140RenderFeature(driftgod.H.R140_SurfaceGrip, "Grip")
                ImGui.Text("100 = Normal | 50 = Low Grip | 25 = Ice | 0 = Zero Traction")
            else
                ImGui.Text("Grip changes are off.")
            end
