function driftgod.R153_InstallVehicleSpawnerHudTick()
    if driftgod.R153VehicleSpawnerHudTickInstalled then return end
    if not (FeatureMgr and FeatureMgr.AddFeature and Utils and Utils.Joaat) then return end
    local hash = Utils.Joaat('DG_R153_VehicleSpawnerHudTick')

    -- v1.0.3 UI safety: this hidden runtime feature can survive Lua reloads in Cherax.
    -- Remove the stale hash first so reloads do not throw:
    -- "A feature named 'DG DriftGod Garage HUD Runtime' does already exist..."
    local ok, feat = driftgod.Try(function()
        if FeatureMgr and FeatureMgr.RemoveFeature then
            driftgod.Try(function() FeatureMgr.RemoveFeature(hash) end)
        end

        local callback = function(f)
            if f and f.IsToggled and not f:IsToggled() then return end
            if DG and driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.open == true and driftgod.VS_RenderHud then
                driftgod.VS_RenderHud()
            end
        end

        if driftgod.SafeAddFeature then
            return driftgod.SafeAddFeature(hash, 'DG DriftGod Garage HUD Runtime', eFeatureType.Toggle, 'Hidden runtime renderer for DriftGod Garage HUD.', callback, true)
        end

        return FeatureMgr.AddFeature(hash, 'DG DriftGod Garage HUD Runtime', eFeatureType.Toggle, 'Hidden runtime renderer for DriftGod Garage HUD.', callback, true)
    end)

    driftgod.R153VehicleSpawnerHudTickInstalled = true

    if ok and feat then
        driftgod.R153VehicleSpawnerHudTickFeature = feat
        driftgod.Try(function()
            if eCallbackTrigger and eCallbackTrigger.OnTick then feat:RegisterCallbackTrigger(eCallbackTrigger.OnTick)
            elseif eCallbackTrigger and eCallbackTrigger.ON_TICK then feat:RegisterCallbackTrigger(eCallbackTrigger.ON_TICK)
            else feat:RegisterCallbackTrigger(eCallbackTrigger.OnTick) end
        end)
        driftgod.Try(function() feat:SetDefaultValue(true):Reset() end)
    end
end
