if DG and driftgod.VS_HandleInput and not driftgod.R153OldVSHandleInput then
    driftgod.R153OldVSHandleInput = driftgod.VS_HandleInput
    function driftgod.VS_HandleInput()
        if not (DG and driftgod.VS and driftgod.VS.runtime and driftgod.VS.hud) then return end
        if driftgod.VS_Now and driftgod.VS_Now() < (driftgod.VS.hud.inputLockUntil or 0) then return end
        local count = #(driftgod.VS.runtime.filtered or {})
        if driftgod.VS_KeyPressed and driftgod.VS.Keys and driftgod.VS_KeyPressed(driftgod.VS.Keys.F5) then
            if driftgod.VS_Refresh then driftgod.VS_Refresh() end
            if driftgod.VS_PlaySound then driftgod.VS_PlaySound('SELECT') end
        end
        if count <= 0 then
            if driftgod.VS_KeyPressed and driftgod.VS.Keys and (driftgod.VS_KeyPressed(driftgod.VS.Keys.DELETE) or driftgod.VS_KeyPressed(driftgod.VS.Keys.LEFT)) then
                if driftgod.VS_SetOpen then driftgod.VS_SetOpen(false) end
            end
            return
        end
        if driftgod.VS_KeyPressed and driftgod.VS.Keys and driftgod.VS_KeyPressed(driftgod.VS.Keys.UP) then
            driftgod.S.vehicleSpawnerIndex = (driftgod.S.vehicleSpawnerIndex or 0) - 1
            if driftgod.S.vehicleSpawnerIndex < 0 then driftgod.S.vehicleSpawnerIndex = count - 1 end
            if driftgod.VS_NormalizeSelection then driftgod.VS_NormalizeSelection() end
            if driftgod.VS_PlaySound then driftgod.VS_PlaySound('NAV_UP_DOWN') end
        elseif driftgod.VS_KeyPressed and driftgod.VS.Keys and driftgod.VS_KeyPressed(driftgod.VS.Keys.DOWN) then
            driftgod.S.vehicleSpawnerIndex = (driftgod.S.vehicleSpawnerIndex or 0) + 1
            if driftgod.S.vehicleSpawnerIndex >= count then driftgod.S.vehicleSpawnerIndex = 0 end
            if driftgod.VS_NormalizeSelection then driftgod.VS_NormalizeSelection() end
            if driftgod.VS_PlaySound then driftgod.VS_PlaySound('NAV_UP_DOWN') end
        elseif driftgod.VS_KeyPressed and driftgod.VS.Keys and (driftgod.VS_KeyPressed(driftgod.VS.Keys.ENTER) or driftgod.VS_KeyPressed(driftgod.VS.Keys.RIGHT)) then
            local item = (driftgod.VS.runtime.filtered or {})[(driftgod.S.vehicleSpawnerIndex or 0) + 1]
            if item and item.isFolder then
                if driftgod.VS_LoadItem then driftgod.VS_LoadItem(item) end
            else
                if driftgod.VS_QueueSelected then driftgod.VS_QueueSelected() end
            end
            if driftgod.VS_PlaySound then driftgod.VS_PlaySound('SELECT') end
        elseif driftgod.VS_KeyPressed and driftgod.VS.Keys and (driftgod.VS_KeyPressed(driftgod.VS.Keys.DELETE) or driftgod.VS_KeyPressed(driftgod.VS.Keys.LEFT)) then
            if driftgod.VS.runtime.currentFolder then
                driftgod.VS.runtime.currentFolder = nil
                driftgod.S.vehicleSpawnerIndex = 0
                driftgod.VS.hud.scroll = 0
                if driftgod.VS_Rebuild then driftgod.VS_Rebuild() end
                if driftgod.VS_PlaySound then driftgod.VS_PlaySound('BACK') end
            else
                if driftgod.VS_SetOpen then driftgod.VS_SetOpen(false) end
            end
        end
    end
end

