function driftgod.VS_Roots()
    driftgod.VS = driftgod.VS or {}
    local roots, seen = {}, {}
    local function add(path)
        path = R154_trim(path or '')
        if path == '' then return end
        local key = path:lower()
        if not seen[key] then
            seen[key] = true
            roots[#roots + 1] = path
            driftgod.Try(function() if FileMgr and FileMgr.CreateDir then FileMgr.CreateDir(path) end end)
        end
    end
    add(driftgod.VS_OFFICIAL_CHERAX_VEHICLES_ROOT)
    driftgod.Try(function() add(FileMgr.GetMenuRootPath() .. '\\Vehicles') end)
    driftgod.Try(function()
        local root = tostring(FileMgr.GetMenuRootPath() or ''):gsub('/', '\\')
        add(root:gsub('\\Lua$', '') .. '\\Vehicles')
    end)
    return roots
end

