local function R162_clamp01(v, fallback)
    v = tonumber(v or fallback or 0) or (fallback or 0)
    if v < 0.000 then v = 0.000 end
    if v > 1.000 then v = 1.000 end
    return v
end

function driftgod.R162_SaveSettingsQuiet()
    if driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
end

function driftgod.R162_EnsureSpawnerHudDefaults()
    driftgod.S = driftgod.S or {}
    if driftgod.S.vehicleSpawnerHudPresetIndex == nil then driftgod.S.vehicleSpawnerHudPresetIndex = 1 end
    if driftgod.S.vehicleSpawnerHudX == nil then driftgod.S.vehicleSpawnerHudX = 0.085 end
    if driftgod.S.vehicleSpawnerHudY == nil then driftgod.S.vehicleSpawnerHudY = 0.080 end
    if driftgod.S.vehicleSpawnerHudMoveEnabled == nil then driftgod.S.vehicleSpawnerHudMoveEnabled = false end
end

function driftgod.R162_SetSpawnerHudXY(x, y, toastText)
    driftgod.R162_EnsureSpawnerHudDefaults()
    x = R162_clamp01(x, 0.085)
    y = R162_clamp01(y, 0.080)
    driftgod.S.vehicleSpawnerHudX = x
    driftgod.S.vehicleSpawnerHudY = y
    driftgod.S.vehicleSpawnerHudMoveEnabled = true
    driftgod.R162_SaveSettingsQuiet()
    if toastText and driftgod.Toast then driftgod.Try(driftgod.Toast, tostring(toastText) .. ': ' .. string.format('%.3f / %.3f', x, y), 1000) end
    return x, y
end

function driftgod.R162_MoveSpawnerHud(dx, dy, label)
    driftgod.R162_EnsureSpawnerHudDefaults()
    return driftgod.R162_SetSpawnerHudXY((tonumber(driftgod.S.vehicleSpawnerHudX) or 0.085) + (dx or 0), (tonumber(driftgod.S.vehicleSpawnerHudY) or 0.080) + (dy or 0), label or 'Garage HUD')
end

