    driftgod.VS.HudPresetNames = driftgod.R162_SpawnerHudPresetNames
end

function driftgod.VS_ApplyHudPreset(index, silent)
    driftgod.R162_EnsureSpawnerHudDefaults()
    index = math.floor(tonumber(index or 0) or 0)
    if index < 0 then index = 0 end
    if index > (#driftgod.R162_SpawnerHudPresets - 1) then index = #driftgod.R162_SpawnerHudPresets - 1 end
    driftgod.S.vehicleSpawnerHudPresetIndex = index
    local preset = driftgod.R162_SpawnerHudPresets[index + 1] or driftgod.R162_SpawnerHudPresets[1]
    driftgod.S.vehicleSpawnerHudX = preset.x
    driftgod.S.vehicleSpawnerHudY = preset.y
    if driftgod.VS and driftgod.VS_Log and silent ~= true then driftgod.VS_Log('HUD preset: ' .. tostring(preset.name)) end
    driftgod.R162_SaveSettingsQuiet()
end

function driftgod.R162_RegisterSpawnerHudMovementFeature()
    if driftgod.R162SpawnerHudMovementRegistered == true then return end
    driftgod.R162SpawnerHudMovementRegistered = true
    driftgod.R162_EnsureSpawnerHudDefaults()
    driftgod.H.VehicleSpawnerHudMoveToggle = driftgod.Hash and driftgod.Hash('VehicleSpawnerHudMoveToggle') or driftgod.H.VehicleSpawnerHudMoveToggle
    if FeatureMgr and FeatureMgr.AddFeature and driftgod.SafeAddFeature and driftgod.H.VehicleSpawnerHudMoveToggle then
        driftgod.Try(function()
            driftgod.R162SpawnerHudMoveFeature = driftgod.SafeAddFeature(driftgod.H.VehicleSpawnerHudMoveToggle, 'Garage HUD Movement', eFeatureType.Toggle, 'Enable custom X/Y positioning for the DriftGod Garage HUD.', function(f)
                driftgod.S.vehicleSpawnerHudMoveEnabled = f and f.IsToggled and f:IsToggled() == true
                driftgod.R162_SaveSettingsQuiet()
            end)
            if driftgod.R162SpawnerHudMoveFeature then
                driftgod.Try(function() driftgod.R162SpawnerHudMoveFeature:SetDefaultValue(driftgod.S.vehicleSpawnerHudMoveEnabled == true):Reset() end)
            end
        end)
    end
end
