local function R168_getSpawnerHudPresetDisplayIndex()
    DG = DG or {}; driftgod.S = driftgod.S or {}
    local raw = tonumber(driftgod.S.vehicleSpawnerHudPresetIndex)
    local count = #(driftgod.R168_SpawnerHudPresets or {})
    if not raw then return 1 end

    if raw >= 0 and raw <= count - 1 then return raw + 1 end
    if raw >= 1 and raw <= count then return raw end
    return 1
end

local function R168_applySpawnerHudPresetDisplayIndex(displayIndex)
    displayIndex = math.floor(tonumber(displayIndex or 1) or 1)
    local presets = driftgod.R168_SpawnerHudPresets or {}
    if displayIndex < 1 then displayIndex = 1 end
    if displayIndex > #presets then displayIndex = #presets end
    local zeroIndex = displayIndex - 1
    driftgod.S = driftgod.S or {}
    driftgod.S.vehicleSpawnerHudPresetIndex = zeroIndex
    if driftgod.VS_ApplyHudPreset then
        driftgod.Try(driftgod.VS_ApplyHudPreset, zeroIndex, true)
    else
        local p = presets[displayIndex]
        if p then
            driftgod.S.vehicleSpawnerHudX = p.x
            driftgod.S.vehicleSpawnerHudY = p.y
            if driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
        end
    end
    if driftgod.Toast then driftgod.Try(driftgod.Toast, 'Garage HUD: ' .. tostring((presets[displayIndex] or {}).name or 'Position'), 1000) end
end

local function R168_renderSpawnerHudPositionDropdown()
    local presets = driftgod.R168_SpawnerHudPresets or {}
    if #presets <= 0 then return end
    local displayIndex = R168_getSpawnerHudPresetDisplayIndex()
    local preview = tostring((presets[displayIndex] or presets[1] or {}).name or 'Top Left')

    if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
        local opened = false
        driftgod.Try(function() opened = ImGui.BeginCombo('Garage HUD Position', preview) end)
        if opened then
            for i, p in ipairs(presets) do
                local clicked = false
                driftgod.Try(function() clicked = ImGui.Selectable(tostring(p.name), i == displayIndex) end)
                if clicked then
                    R168_applySpawnerHudPresetDisplayIndex(i)
                end
            end
            driftgod.Try(function() ImGui.EndCombo() end)
        end
    else
        R164_text('Garage HUD Position: ' .. preview, 'white')
    end
end

