local function R171_getSpawnerHudPresetDisplayIndex()
    DG = DG or {}; driftgod.S = driftgod.S or {}
    local presets = driftgod.R168_SpawnerHudPresets or driftgod.R162_SpawnerHudPresets or {}
    local count = #presets
    if count <= 0 then return 1 end
    local raw = tonumber(driftgod.S.vehicleSpawnerHudPresetIndex)
    if raw == nil then return 1 end

    if raw >= 0 and raw <= count - 1 then return math.floor(raw) + 1 end
    if raw >= 1 and raw <= count then return math.floor(raw) end
    return 1
end

local function R171_applySpawnerHudPresetDisplayIndex(displayIndex)
    DG = DG or {}; driftgod.S = driftgod.S or {}
    local presets = driftgod.R168_SpawnerHudPresets or driftgod.R162_SpawnerHudPresets or {}
    if #presets <= 0 then return end
    displayIndex = math.floor(tonumber(displayIndex or 1) or 1)
    if displayIndex < 1 then displayIndex = 1 end
    if displayIndex > #presets then displayIndex = #presets end

    local preset = presets[displayIndex]
    if not preset then return end

    driftgod.S.vehicleSpawnerHudPresetIndex = displayIndex - 1
    driftgod.S.vehicleSpawnerHudX = tonumber(preset.x) or 0.085
    driftgod.S.vehicleSpawnerHudY = tonumber(preset.y) or 0.080
    driftgod.S.vehicleSpawnerHudMoveEnabled = true

    if driftgod.VS then
        driftgod.VS.HudPresets = presets
        driftgod.VS.HudPresetNames = driftgod.R168_SpawnerHudPresetNames or driftgod.R162_SpawnerHudPresetNames or {}
    end

    if driftgod.R162_SaveSettingsQuiet then
        driftgod.Try(driftgod.R162_SaveSettingsQuiet)
    elseif driftgod.SaveSettings then
        driftgod.Try(driftgod.SaveSettings, false)
    end
end

local function R171_renderSpawnerHudPositionDropdown()
