    local displayIndex = R171_getSpawnerHudPresetDisplayIndex()
    local preview = tostring((presets[displayIndex] or presets[1] or {}).name or 'Top Left')

    if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
        local opened = false
        local okOpen = driftgod.Try(function() opened = ImGui.BeginCombo('Garage HUD Position', preview) end)
        if okOpen and opened then
            for i, p in ipairs(presets) do
                local clicked = false
                driftgod.Try(function() clicked = ImGui.Selectable(tostring(p.name or ('Position ' .. tostring(i))), i == displayIndex) end)
                if clicked then
                    R171_applySpawnerHudPresetDisplayIndex(i)
                    displayIndex = i
                end
            end
            driftgod.Try(function() ImGui.EndCombo() end)
        end
    else
        R164_text('Garage HUD Position: ' .. preview, 'white')
    end
end

