local function R172_toast(msg)
    if DG and driftgod.Toast then driftgod.Try(driftgod.Toast, tostring(msg), 1200)
    elseif toast then driftgod.Try(toast, tostring(msg), 1200) end
end

local function R172_applyScoreHudPreset(index, doToast)
    DG = DG or {}; driftgod.S = driftgod.S or {}
    local presets = driftgod.R172_ScoreHudPresets or {}
    index = math.floor(tonumber(index or 1) or 1)
    if index < 1 then index = 1 end
    if index > #presets then index = #presets end
    local preset = presets[index]
    if not preset then return end
    driftgod.S.scoreHudPresetIndex = index
    driftgod.S.hudX = tonumber(preset.x) or 0.50
    driftgod.S.hudY = tonumber(preset.y) or 0.10
    R172_saveQuiet()
    if doToast then R172_toast('Score HUD preset: ' .. tostring(preset.name or 'Position')) end
end

local function R172_findScoreHudPresetIndex()
    DG = DG or {}; driftgod.S = driftgod.S or {}
    local presets = driftgod.R172_ScoreHudPresets or {}
    local stored = tonumber(driftgod.S.scoreHudPresetIndex or 0) or 0
    if stored >= 1 and stored <= #presets then return math.floor(stored) end
    local x = tonumber(driftgod.S.hudX or 0.50) or 0.50
    local y = tonumber(driftgod.S.hudY or 0.10) or 0.10
    local best, bestDist = 1, 999
    for i, p in ipairs(presets) do
        local dx = math.abs((tonumber(p.x) or 0) - x)
        local dy = math.abs((tonumber(p.y) or 0) - y)
        local d = dx + dy
        if d < bestDist then best, bestDist = i, d end
    end
    return best
end

local function R172_renderScoreHudPositionDropdown()
    local presets = driftgod.R172_ScoreHudPresets or {}
    if #presets <= 0 then return end
    local index = R172_findScoreHudPresetIndex()
    local preview = tostring((presets[index] or presets[1] or {}).name or 'Top Center')
    if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
        local opened = false
        driftgod.Try(function() opened = ImGui.BeginCombo('Score HUD Position', preview) end)
        if opened then
            for i, p in ipairs(presets) do
                local clicked = false
                driftgod.Try(function() clicked = ImGui.Selectable(tostring(p.name or ('Position ' .. tostring(i))), i == index) end)
                if clicked then
                    R172_applyScoreHudPreset(i, true)
                    index = i
                end
            end
            driftgod.Try(function() ImGui.EndCombo() end)
        end
    elseif R164_text then
        R164_text('Score HUD Position: ' .. preview, 'white')
    elseif ImGui and ImGui.Text then
        ImGui.Text('Score HUD Position: ' .. preview)
    end
end

local function R172_moveScoreHud(dx, dy)
    DG = DG or {}; driftgod.S = driftgod.S or {}
    local x = tonumber(driftgod.S.hudX or 0.50) or 0.50
    local y = tonumber(driftgod.S.hudY or 0.10) or 0.10
    x = math.max(0.000, math.min(1.000, x + (tonumber(dx) or 0)))
    y = math.max(0.000, math.min(1.000, y + (tonumber(dy) or 0)))
    driftgod.S.hudX, driftgod.S.hudY = x, y
    driftgod.S.scoreHudPresetIndex = 0
    R172_saveQuiet()
end

function driftgod.R172_RenderScoreHudSettings()
    if not (ClickGUI and ClickGUI.BeginCustomChildWindow) then return end
    if ClickGUI.BeginCustomChildWindow('Score HUD Settings') then
        if dgA24Header then dgA24Header('Score HUD Settings', 'Move the live score / best score HUD.')
        elseif R164_text then R164_text('Score HUD Settings', 'header')
        elseif ImGui and ImGui.Text then ImGui.Text('Score HUD Settings') end

        if driftgod.H and driftgod.H.ScoreHudToggle and ClickGUI.RenderFeature then
            driftgod.Try(function() ClickGUI.RenderFeature(driftgod.H.ScoreHudToggle) end)
        end
        if ImGui and ImGui.Text then
            ImGui.Text('Current X/Y: ' .. string.format('%.3f', tonumber(driftgod.S.hudX or 0.50) or 0.50) .. ' / ' .. string.format('%.3f', tonumber(driftgod.S.hudY or 0.10) or 0.10))
        end
        if ImGui and ImGui.Separator then ImGui.Separator() end
        if ImGui and ImGui.Text then ImGui.Text('Presets') end
        R172_renderScoreHudPositionDropdown()
        if ImGui and ImGui.Separator then ImGui.Separator() end

        if ImGui and ImGui.Text then ImGui.Text('Move') end
        if ImGui and ImGui.Button then
            if ImGui.Button('X-##R172ScoreHudMoveXMinus') then R172_moveScoreHud(-0.020, 0.000) end
            if ImGui.SameLine then ImGui.SameLine() end
            if ImGui.Button('X+##R172ScoreHudMoveXPlus') then R172_moveScoreHud(0.020, 0.000) end
            if ImGui.Button('Y-##R172ScoreHudMoveYMinus') then R172_moveScoreHud(0.000, -0.020) end
            if ImGui.SameLine then ImGui.SameLine() end
            if ImGui.Button('Y+##R172ScoreHudMoveYPlus') then R172_moveScoreHud(0.000, 0.020) end

            if ImGui.Text then ImGui.Text('Fine Move') end
            if ImGui.Button('X-##R172ScoreHudFineXMinus') then R172_moveScoreHud(-0.005, 0.000) end
            if ImGui.SameLine then ImGui.SameLine() end
            if ImGui.Button('X+##R172ScoreHudFineXPlus') then R172_moveScoreHud(0.005, 0.000) end
            if ImGui.Button('Y-##R172ScoreHudFineYMinus') then R172_moveScoreHud(0.000, -0.005) end
            if ImGui.SameLine then ImGui.SameLine() end
            if ImGui.Button('Y+##R172ScoreHudFineYPlus') then R172_moveScoreHud(0.000, 0.005) end
        end
        ClickGUI.EndCustomChildWindow()
    end
end

