    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"

    local desiredOrder = {
        starter = 1,
        compacts = 2,
        coupes = 3,
        vans = 4,
        utility = 5,
        service = 6,
        industrial = 7,
        emergency = 8,
        suvs = 9,
        sedans = 10,
        open_wheel = 11,
        off_road = 12,
        sports_classics = 13,
        muscle = 14,
        drift = 15,
        military = 16,
        sports = 17,
        super = 18,
    }

    if driftgod.VehicleSectorUnlocks then
        for _, sector in ipairs(driftgod.VehicleSectorUnlocks) do
            if sector then
                if sector.id == 'compacts' then
                    sector.threshold = 500
                    sector.label = 'Compacts'
                elseif sector.id == 'coupes' then
                    sector.threshold = 1000
                    sector.label = 'Coupes'
                elseif sector.id == 'sedans' then
                    sector.threshold = 9000
                    sector.label = 'Sedans'
                    sector.classId = 1
                elseif sector.id == 'suvs' then
                    sector.label = 'SUVs'
                    sector.classId = 2
                end
            end
        end

        table.sort(driftgod.VehicleSectorUnlocks, function(a, b)
            local ai = desiredOrder[tostring(a and a.id or '')] or 999
            local bi = desiredOrder[tostring(b and b.id or '')] or 999
            if ai == bi then
                return tostring(a and a.label or '') < tostring(b and b.label or '')
            end
            return ai < bi
        end)

        driftgod.VehicleSectorByClass = {}
        for _, sector in ipairs(driftgod.VehicleSectorUnlocks) do
            if sector and sector.classId ~= nil then
                driftgod.VehicleSectorByClass[tonumber(sector.classId)] = sector
            end
        end
    end
end)

