                    driftgod.Try(function() ClickGUI.RenderFeature(driftgod.H.SettingsHudTarget) end)
                else
                    text('Selected: ' .. preview, 'purple')
                end
            end
            text('Choose which HUD controls to edit below.', 'dim')
            endChild()
        else

            text('Choose HUD', 'header')
            if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
                local opened = false
                driftgod.Try(function() opened = ImGui.BeginCombo('Choose HUD', preview) end)
                if opened then
                    for i, item in ipairs(hudItems) do
                        local selected = ((i - 1) == idx)
                        local clicked = false
