        elseif idx == 1 then
            if driftgod.R102_RenderMphSettings then driftgod.Try(driftgod.R102_RenderMphSettings) elseif renderMphSettings then driftgod.Try(renderMphSettings) end
        elseif idx == 2 then
            if driftgod.R101_RenderInputVisualizerSettings then driftgod.Try(driftgod.R101_RenderInputVisualizerSettings) end
        elseif idx == 3 then
            if driftgod.R189_RenderStuntHudSettings then driftgod.Try(driftgod.R189_RenderStuntHudSettings) elseif renderStuntHudSettings then driftgod.Try(renderStuntHudSettings) end
        else
