            return
        end
        if idx == 2 then
            if driftgod.R101_RenderInputVisualizerSettings then driftgod.Try(driftgod.R101_RenderInputVisualizerSettings) end
            return
        end
        if idx == 3 then
            if driftgod.R189_RenderStuntHudSettings then driftgod.Try(driftgod.R189_RenderStuntHudSettings)
            elseif renderStuntHudSettings then driftgod.Try(renderStuntHudSettings) end
            return
        end
        if idx == 4 then
            if driftgod.R189_RenderSpawnerHudSettings then driftgod.Try(driftgod.R189_RenderSpawnerHudSettings)
            elseif driftgod.R171_RenderSpawnerHudControls then driftgod.Try(driftgod.R171_RenderSpawnerHudControls)
            elseif driftgod.R101_RenderSpawnerHudSettings then driftgod.Try(driftgod.R101_RenderSpawnerHudSettings) end
            return
        end
    end

