        driftgod.S.stuntQuickMenuX, driftgod.S.stuntHudX = p.x, p.x
        driftgod.S.stuntQuickMenuY, driftgod.S.stuntHudY = p.y, p.y
        driftgod.S.stuntHudMoveEnabled = true
        if driftgod.SetStuntQuickMenuPosition then
            driftgod.Try(driftgod.SetStuntQuickMenuPosition, p.x, p.y, true)
        end
        if driftgod.R102StuntHudPresetFeature and driftgod.R102StuntHudPresetFeature.SetListIndex then
            driftgod.Try(function() driftgod.R102StuntHudPresetFeature:SetListIndex(index) end)
