driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"

    local function r197_log(msg)
        if driftgod.R196B_TuningDebug then driftgod.R196B_TuningDebug('[R197] ' .. tostring(msg or ''))
        elseif driftgod.Log then driftgod.Log('[DriftTuning][R197] ' .. tostring(msg or '')) end
    end

    local function r197_safe_name(name)
        name = tostring(name or 'CustomPreset')
        name = name:gsub('[\\/:%*%?"<>|]', '_'):gsub('^%s+', ''):gsub('%s+$', '')
        if name == '' then name = 'CustomPreset' end
        return name
    end

    local function r197_dir()
        if driftgod.R109_CustomPresetDir then return driftgod.R109_CustomPresetDir end
        if FileMgr and FileMgr.GetMenuRootPath then return FileMgr.GetMenuRootPath() .. '\\Lua\\DriftGod\\storage\\presets\\' end
        return 'DriftGod\\storage\\presets\\'
    end

    local function r197_ensure_dir()
        driftgod.Try(function()
            if FileMgr and FileMgr.CreateDir then
                if FileMgr.GetMenuRootPath then
                    FileMgr.CreateDir(FileMgr.GetMenuRootPath() .. '\\Lua\\DriftGod')
                    FileMgr.CreateDir(FileMgr.GetMenuRootPath() .. '\\Lua\\DriftGod\\storage')
                end
                FileMgr.CreateDir(r197_dir())
            end
        end)
    end

    local function r197_path(name) return r197_dir() .. r197_safe_name(name) .. '.lua' end

    local function r197_builtin_name_set()
        local set = {}
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            set[r197_safe_name(p.name or p.id)] = true
            set[r197_safe_name(p.id or p.name)] = true
        end
        return set
    end

    local R197PresetKeys = {
        'r195BaseTuningPreset',
        'activeArcadeDriftPreset',
        'arcadePresetRuntimeAssist',
        'arcadePresetRuntimeEnabled',
        'driftAssistEnabled',
        'driftTuningEnabled',
        'driftGripLevel',
        'driftStabilityLevel',
        'autoCounterSteerLevel',
        'momentumAssistEnabled',
        'momentumStrength',
        'accelAssistEnabled',
        'accelStrength',
        'experimentalGravityEnabled',
        'experimentalGravityStrength',
        'experimentalAccelEnabled',
        'experimentalAccelStrength',
        'experimentalTractionEnabled',
        'experimentalTractionLevel',
        'experimentalGripEnabled',
        'experimentalGripLevel'
    }

    local function r197_serialize(tbl)
        local out = {'return {'}
        for k, v in pairs(tbl or {}) do
            if type(v) == 'number' or type(v) == 'boolean' then
                out[#out+1] = '  ' .. tostring(k) .. ' = ' .. tostring(v) .. ','
            elseif type(v) == 'string' then
                out[#out+1] = '  ' .. tostring(k) .. ' = ' .. string.format('%q', v) .. ','
            end
        end
        out[#out+1] = '}'
        return table.concat(out, '\n')
    end

    local function r197_read_file_names()
        r197_ensure_dir()
        local list = {}
        local ok, files = driftgod.Try(function()
            if FileMgr and FileMgr.FindFiles then return FileMgr.FindFiles(r197_dir(), 'lua') end
        end)
        if ok and type(files) == 'table' then
            for _, f in ipairs(files) do
                local n = tostring(f or ''):match('([^\\/]+)%.lua$')
                if n and n ~= '_preset_index' then list[#list+1] = n end
            end
        end
        return list
    end

    local function r197_load_preset_data(name)
        local ok, tbl = driftgod.Try(function() return dofile(r197_path(name)) end)
        if ok and type(tbl) == 'table' then return tbl end
        return nil
    end

    local function r197_recent_score(name)
        driftgod.S.r197CustomPresetRecent = driftgod.S.r197CustomPresetRecent or {}
        for i, n in ipairs(driftgod.S.r197CustomPresetRecent) do
            if tostring(n) == tostring(name) then return 1000000 - i end
        end
        local tbl = r197_load_preset_data(name)
        return tonumber(tbl and tbl.saved_at or 0) or 0
    end

    local function r197_mark_recent(name)
        driftgod.S.r197CustomPresetRecent = driftgod.S.r197CustomPresetRecent or {}
        local out = {tostring(name)}
        for _, n in ipairs(driftgod.S.r197CustomPresetRecent) do
            if tostring(n) ~= tostring(name) then out[#out+1] = tostring(n) end
        end
        driftgod.S.r197CustomPresetRecent = out
    end

    function driftgod.R197_ScanCustomPresets()
        local names = r197_read_file_names()
        if (#names <= 0) and type(driftgod.S.customPresetList) == 'table' then
            for _, n in ipairs(driftgod.S.customPresetList) do names[#names+1] = tostring(n) end
        end
        table.sort(names, function(a,b)
            local sa, sb = r197_recent_score(a), r197_recent_score(b)
            if sa == sb then return tostring(a) < tostring(b) end
            return sa > sb
        end)
        driftgod.S.customPresetList = names
        driftgod.S.customPresetIndex = math.max(1, math.min(tonumber(driftgod.S.customPresetIndex or 1) or 1, math.max(1, #names)))
        return names
    end

    local function r197_unique_name(base)
        local safe = r197_safe_name(base)
        local builtins = r197_builtin_name_set()
        local existing = {}
        for _, n in ipairs(r197_read_file_names()) do existing[r197_safe_name(n)] = true end
        if not builtins[safe] and not existing[safe] then return safe end
        local i = 2
        while true do
            local candidate = safe .. '_' .. tostring(i)
            if not builtins[candidate] and not existing[candidate] then return candidate end
            i = i + 1
        end
    end

    function driftgod.R197_SaveCustomPreset()
        r197_ensure_dir()
        driftgod.S = driftgod.S or {}
        local requested = driftgod.S.customPresetName or 'CustomPreset'
        local name = r197_unique_name(requested)
        driftgod.S.customPresetName = name

        local base = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or '')
        local save = {
            preset_schema = 'DriftGodCustomPreset_R197',
            name = name,
            saved_at = os.time and os.time() or math.floor(os.clock() * 1000),
            base_preset = base,
            source_preset = base,
            is_custom_preset = true
        }
        for _, k in ipairs(R197PresetKeys) do save[k] = driftgod.S[k] end
        save.r195BaseTuningPreset = base
        save.activeArcadeDriftPreset = base

        local ok = false
        driftgod.Try(function()
            if FileMgr and FileMgr.WriteFileContent then ok = FileMgr.WriteFileContent(r197_path(name), r197_serialize(save), false) end
        end)
        if not ok then
            driftgod.Try(function()
                local f = io.open(r197_path(name), 'w')
                if f then f:write(r197_serialize(save)); f:close(); ok = true end
            end)
        end

        r197_mark_recent(name)
        driftgod.R197_ScanCustomPresets()
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        r197_log('Saved custom preset "' .. tostring(name) .. '" from base=' .. tostring(base))
        if driftgod.Toast then driftgod.Toast(ok and ('Saved preset: ' .. name) or 'Preset save failed', 2200) end
        return ok
    end

    function driftgod.R197_LoadSelectedCustomPreset()
        local list = driftgod.R197_ScanCustomPresets()
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        local name = list[idx]
        if not name then if driftgod.Toast then driftgod.Toast('No custom preset selected', 1800) end; return false end
        local tbl = r197_load_preset_data(name)
        if type(tbl) ~= 'table' then if driftgod.Toast then driftgod.Toast('Preset load failed', 2200) end; return false end

        local base = tostring(tbl.base_preset or tbl.r195BaseTuningPreset or tbl.activeArcadeDriftPreset or '')
        if base ~= '' and driftgod.ApplyArcadeDriftPreset then
            driftgod.Try(function() driftgod.ApplyArcadeDriftPreset(base, false) end)
        end
        for _, k in ipairs(R197PresetKeys) do
            if tbl[k] ~= nil then driftgod.S[k] = tbl[k] end
        end
        driftgod.S.r195BaseTuningPreset = base ~= '' and base or driftgod.S.r195BaseTuningPreset
        driftgod.S.activeArcadeDriftPreset = base ~= '' and base or driftgod.S.activeArcadeDriftPreset
        driftgod.S.r197ActiveCustomPreset = name
        r197_mark_recent(name)
        driftgod.R197_ScanCustomPresets()
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        r197_log('Loaded custom preset "' .. tostring(name) .. '" base=' .. tostring(base))
        if driftgod.Toast then driftgod.Toast('Applied custom preset: ' .. tostring(name), 2200) end
        return true
    end

    function driftgod.R197_DeleteSelectedCustomPreset()
        local list = driftgod.R197_ScanCustomPresets()
        local name = list[tonumber(driftgod.S.customPresetIndex or 1) or 1]
        if not name then if driftgod.Toast then driftgod.Toast('No custom preset selected', 1800) end; return false end
        driftgod.Try(function() os.remove(r197_path(name)) end)
        if type(driftgod.S.r197CustomPresetRecent) == 'table' then
            local out = {}
            for _, n in ipairs(driftgod.S.r197CustomPresetRecent) do if tostring(n) ~= tostring(name) then out[#out+1] = n end end
            driftgod.S.r197CustomPresetRecent = out
        end
        driftgod.R197_ScanCustomPresets()
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        r197_log('Deleted custom preset "' .. tostring(name) .. '"')
        if driftgod.Toast then driftgod.Toast('Deleted preset: ' .. tostring(name), 2200) end
        return true
    end

