    driftgod.R110_DeleteCustomPreset = driftgod.R197_DeleteSelectedCustomPreset

    local function r197_clone(t)
        local c = {}
        for k, v in pairs(t or {}) do c[k] = v end
        return c
    end

    local function r197_level(name, default)
        local v = tonumber(driftgod.S and driftgod.S[name] or default) or default
        if v < 1 then v = 1 end
        if v > 5 then v = 5 end
        return v
    end

    function driftgod.R197_GetTunedRuntimePreset(p)
        if type(p) ~= 'table' then return p end
        driftgod.S = driftgod.S or {}
        if not (driftgod.S.driftAssistEnabled == true and driftgod.S.driftTuningEnabled == true) then return p end
        local base = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or '')
        if base == '' then return p end

        local q = r197_clone(p)

        local drift = r197_level('driftGripLevel', q.drift or 3) - 3
        local stability = r197_level('driftStabilityLevel', q.stability or 3) - 3
        local counter = r197_level('autoCounterSteerLevel', 3) - 3
        local momentum = r197_level('momentumStrength', q.momentum or 3) - 3
        local accel = r197_level('accelStrength', q.accel or 3) - 3
        local gravity = (driftgod.S.experimentalGravityEnabled == true) and (r197_level('experimentalGravityStrength', 3) - 3) or 0
        local expAccel = (driftgod.S.experimentalAccelEnabled == true) and (r197_level('experimentalAccelStrength', 3) - 3) or 0
        local traction = (driftgod.S.experimentalTractionEnabled == true) and (r197_level('experimentalTractionLevel', 3) - 3) or 0
        local grip = (driftgod.S.experimentalGripEnabled == true) and (r197_level('experimentalGripLevel', 3) - 3) or 0

        q.angle = math.max(28.0, math.min(92.0, (tonumber(q.angle or 50.0) or 50.0) + drift * 4.0 - traction * 2.0))
        q.grip_pad = math.max(0.0, math.min(28.0, (tonumber(q.grip_pad or 8.0) or 8.0) + drift * 1.25 + grip * 2.0 + traction * 1.25 + gravity * 0.75))
        q.assist = math.max(35.0, math.min(100.0, (tonumber(q.assist or 80.0) or 80.0) + stability * 4.0 + counter * 5.0))
        q.intensity = math.max(12.0, math.min(70.0, (tonumber(q.intensity or 30.0) or 30.0) + momentum * 3.0 + expAccel * 2.0 - stability * 1.0))
        q.base_force = math.max(0.006, math.min(0.045, (tonumber(q.base_force or 0.015) or 0.015) * (1.0 + accel * 0.08 + expAccel * 0.06 + momentum * 0.035)))
        q.min_speed = math.max(6.0, math.min(36.0, (tonumber(q.min_speed or 12.0) or 12.0) - grip * 0.75 - gravity * 0.50 + traction * 0.40))
        q._r197_tuned = true
        return q
    end

    if not driftgod._R197_ApplyPresetWrapped and driftgod.ApplyArcadeDriftPreset then
        local oldApply = driftgod.ApplyArcadeDriftPreset
        driftgod.ApplyArcadeDriftPreset = function(id, showToast)
            local ok = oldApply(id, showToast)
            if ok then
                driftgod.S = driftgod.S or {}
                driftgod.S.r195BaseTuningPreset = tostring(id or driftgod.S.activeArcadeDriftPreset or '')
