            end
            return ok
        end
        driftgod._R197_ApplyPresetWrapped = true
    end

    if driftgod.R110_RenderPresetColumns then
        local oldCols = driftgod.R110_RenderPresetColumns
        driftgod.R110_RenderPresetColumns = function(id)
            local oldScan = driftgod.R110_ScanCustomPresets
            driftgod.R110_ScanCustomPresets = function()
                local all = driftgod.R197_ScanCustomPresets()
                local top = {}
                for i = 1, math.min(3, #all) do top[#top+1] = all[i] end
