            end
            local ok, err = driftgod.Try(function() oldCols(id) end)
            driftgod.R110_ScanCustomPresets = oldScan
            if not ok then
                if driftgod.Log then driftgod.Log('[DriftTuning][R197] Preset column render fallback: ' .. tostring(err)) end
                local list = driftgod.R197_ScanCustomPresets()
                for i = 1, math.min(3, #list) do
                    if R110Text then R110Text(tostring(list[i]), 'white') end
                end
            end
        end
    end

    r197_log('Preset-based tuning + custom recent stack loaded')
end)

