            if FileMgr and FileMgr.CreateDir then
                if FileMgr.GetMenuRootPath then
                    FileMgr.CreateDir(FileMgr.GetMenuRootPath() .. '\\Lua\\DriftGod')
                    FileMgr.CreateDir(FileMgr.GetMenuRootPath() .. '\\Lua\\DriftGod\\storage')
                end
                FileMgr.CreateDir(r199_dir())
            end
        end)
    end

    local function r199_path(name)
        return r199_dir() .. r199_safe_name(name) .. '.lua'
    end

    local function r199_builtin_names()
        local set = {}
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            set[r199_safe_name(p.id or '')] = true
            set[r199_safe_name(p.name or '')] = true
        end
        return set
    end

    local function r199_read_preset(name)
        local ok, tbl = driftgod.Try(function() return dofile(r199_path(name)) end)
        if ok and type(tbl) == 'table' then return tbl end
        return nil
    end

    local function r199_add_unique(list, seen, raw)
        local n = tostring(raw or '')
        n = n:match('([^\\/]+)%.lua$') or n
        n = n:gsub('%.lua$', '')
        n = r199_safe_name(n)
        if n ~= '' and n ~= '_preset_index' and not seen[n] then
            seen[n] = true
            list[#list + 1] = n
        end
    end

    local function r199_recent_rank(name)
        name = tostring(name or '')
        local recent = driftgod.S.r199CustomPresetRecent or driftgod.S.r197CustomPresetRecent or {}
        for i, n in ipairs(recent) do
            if tostring(n) == name then return 100000000 - i end
        end
        local tbl = r199_read_preset(name)
        return tonumber(tbl and tbl.saved_at or 0) or 0
    end

    local function r199_mark_recent(name)
        name = r199_safe_name(name)
        local out = { name }
        local function merge(src)
            if type(src) ~= 'table' then return end
            for _, n in ipairs(src) do
                n = r199_safe_name(n)
                if n ~= '' and n ~= name then out[#out + 1] = n end
            end
        end
        merge(driftgod.S.r199CustomPresetRecent)
        merge(driftgod.S.r197CustomPresetRecent)
        merge(driftgod.S.customPresetList)
        driftgod.S.r199CustomPresetRecent = out
        driftgod.S.r197CustomPresetRecent = out
        return out
    end

    function driftgod.R199_ScanCustomPresets()
        r199_ensure_dir()
        local list, seen = {}, {}

        local ok, files = driftgod.Try(function()
            if FileMgr and FileMgr.FindFiles then return FileMgr.FindFiles(r199_dir(), 'lua') end
            return nil
        end)
        if ok and type(files) == 'table' then
            for _, f in ipairs(files) do r199_add_unique(list, seen, f) end
        end

        for _, n in ipairs(driftgod.S.r199CustomPresetRecent or {}) do r199_add_unique(list, seen, n) end
        for _, n in ipairs(driftgod.S.r197CustomPresetRecent or {}) do r199_add_unique(list, seen, n) end
        for _, n in ipairs(driftgod.S.customPresetList or {}) do r199_add_unique(list, seen, n) end

        table.sort(list, function(a, b)
            local ra, rb = r199_recent_rank(a), r199_recent_rank(b)
            if ra == rb then return tostring(a) < tostring(b) end
            return ra > rb
        end)

        driftgod.S.customPresetList = list
        driftgod.S.customPresetIndex = math.max(1, math.min(tonumber(driftgod.S.customPresetIndex or 1) or 1, math.max(1, #list)))
        return list
    end

    local function r199_unique_name(requested)
        local base = r199_safe_name(requested)
        local builtins = r199_builtin_names()
        local existing = {}
        for _, n in ipairs(driftgod.R199_ScanCustomPresets()) do existing[r199_safe_name(n)] = true end
        if not builtins[base] and not existing[base] then return base end
        local i = 2
        while true do
            local candidate = base .. '_' .. tostring(i)
            if not builtins[candidate] and not existing[candidate] then return candidate end
            i = i + 1
        end
    end

    local function r199_serialize(tbl)
        local out = { 'return {' }
        for k, v in pairs(tbl or {}) do
            if type(v) == 'number' or type(v) == 'boolean' then
                out[#out + 1] = '  ' .. tostring(k) .. ' = ' .. tostring(v) .. ','
            elseif type(v) == 'string' then
                out[#out + 1] = '  ' .. tostring(k) .. ' = ' .. string.format('%q', v) .. ','
            end
        end
        out[#out + 1] = '}'
        return table.concat(out, '\n')
    end

    function driftgod.R199_SaveCustomPreset()
        r199_ensure_dir()
        driftgod.S = driftgod.S or {}

        local name = r199_unique_name(driftgod.S.customPresetName or 'CustomPreset')
        local base = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.r198BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or '')

        local save = {
            preset_schema = 'DriftGodCustomPreset_R199',
            name = name,
            saved_at = os.time and os.time() or math.floor((os.clock() or 0) * 1000),
            base_preset = base,
            source_preset = base,
            is_custom_preset = true
        }

        for _, k in ipairs(R199PresetKeys) do save[k] = driftgod.S[k] end
        save.r195BaseTuningPreset = base
        save.r198BaseTuningPreset = base
        save.activeArcadeDriftPreset = base

        local ok = false
        driftgod.Try(function()
            if FileMgr and FileMgr.WriteFileContent then
                ok = FileMgr.WriteFileContent(r199_path(name), r199_serialize(save), false)
            end
        end)
        if not ok then
            driftgod.Try(function()
                local f = io.open(r199_path(name), 'w')
                if f then f:write(r199_serialize(save)); f:close(); ok = true end
            end)
        end

        r199_mark_recent(name)
        driftgod.S.customPresetList = driftgod.S.customPresetList or {}
        local newList = { name }
        for _, n in ipairs(driftgod.S.customPresetList) do
            if tostring(n) ~= tostring(name) then newList[#newList + 1] = tostring(n) end
        end
        driftgod.S.customPresetList = newList
        driftgod.S.customPresetIndex = 1
        driftgod.S.customPresetName = name
        driftgod.S.r199LastSavedCustomPreset = name
        driftgod.S.r199CustomPresetRefreshNonce = (tonumber(driftgod.S.r199CustomPresetRefreshNonce or 0) or 0) + 1

        driftgod.R199_ScanCustomPresets()
        driftgod.S.customPresetIndex = 1

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        r199_log('Saved custom preset and refreshed Custom column: ' .. tostring(name) .. ' | base=' .. tostring(base))
        if driftgod.Toast then driftgod.Toast(ok and ('Saved preset: ' .. name) or 'Preset save failed', 2200) end
        return ok
    end

    function driftgod.R199_LoadSelectedCustomPreset()
        local list = driftgod.R199_ScanCustomPresets()
        local name = list[tonumber(driftgod.S.customPresetIndex or 1) or 1]
        if not name then if driftgod.Toast then driftgod.Toast('No custom preset selected', 1800) end; return false end

        local tbl = r199_read_preset(name)
        if type(tbl) ~= 'table' then if driftgod.Toast then driftgod.Toast('Preset load failed', 2200) end; return false end

        local base = tostring(tbl.base_preset or tbl.r195BaseTuningPreset or tbl.r198BaseTuningPreset or tbl.activeArcadeDriftPreset or '')
        if base ~= '' and driftgod.ApplyArcadeDriftPreset then
            driftgod.Try(function() driftgod.ApplyArcadeDriftPreset(base, false) end)
        end

        for _, k in ipairs(R199PresetKeys) do
            if tbl[k] ~= nil then driftgod.S[k] = tbl[k] end
        end

        driftgod.S.r195BaseTuningPreset = base ~= '' and base or driftgod.S.r195BaseTuningPreset
        driftgod.S.r198BaseTuningPreset = base ~= '' and base or driftgod.S.r198BaseTuningPreset
        driftgod.S.activeArcadeDriftPreset = base ~= '' and base or driftgod.S.activeArcadeDriftPreset
        driftgod.S.r199ActiveCustomPreset = name
        r199_mark_recent(name)
        driftgod.R199_ScanCustomPresets()
        driftgod.S.customPresetIndex = 1

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        r199_log('Loaded custom preset: ' .. tostring(name) .. ' | base=' .. tostring(base))
        if driftgod.Toast then driftgod.Toast('Applied custom preset: ' .. tostring(name), 2200) end
        return true
    end

    function driftgod.R199_DeleteSelectedCustomPreset()
        local list = driftgod.R199_ScanCustomPresets()
        local name = list[tonumber(driftgod.S.customPresetIndex or 1) or 1]
        if not name then if driftgod.Toast then driftgod.Toast('No custom preset selected', 1800) end; return false end

        driftgod.Try(function() os.remove(r199_path(name)) end)

        local function removeFrom(src)
            local out = {}
            if type(src) == 'table' then
                for _, n in ipairs(src) do if tostring(n) ~= tostring(name) then out[#out + 1] = n end end
            end
            return out
        end
        driftgod.S.r199CustomPresetRecent = removeFrom(driftgod.S.r199CustomPresetRecent)
        driftgod.S.r197CustomPresetRecent = removeFrom(driftgod.S.r197CustomPresetRecent)
        driftgod.S.customPresetList = removeFrom(driftgod.S.customPresetList)
        driftgod.S.customPresetIndex = 1

        driftgod.R199_ScanCustomPresets()
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        r199_log('Deleted custom preset and refreshed Custom column: ' .. tostring(name))
        if driftgod.Toast then driftgod.Toast('Deleted preset: ' .. tostring(name), 2200) end
        return true
    end

    driftgod.R197_ScanCustomPresets = driftgod.R199_ScanCustomPresets
    driftgod.R109_ScanCustomPresets = driftgod.R199_ScanCustomPresets
    driftgod.R110_ScanCustomPresets = driftgod.R199_ScanCustomPresets

    driftgod.R197_SaveCustomPreset = driftgod.R199_SaveCustomPreset
    driftgod.R109_SaveCustomPreset = driftgod.R199_SaveCustomPreset
    driftgod.R110_SaveCustomPreset = driftgod.R199_SaveCustomPreset

    driftgod.R197_LoadSelectedCustomPreset = driftgod.R199_LoadSelectedCustomPreset
    driftgod.R109_LoadSelectedCustomPreset = driftgod.R199_LoadSelectedCustomPreset
    driftgod.R110_ApplyCustomPreset = driftgod.R199_LoadSelectedCustomPreset

    driftgod.R197_DeleteSelectedCustomPreset = driftgod.R199_DeleteSelectedCustomPreset
    driftgod.R109_DeleteSelectedCustomPreset = driftgod.R199_DeleteSelectedCustomPreset
    driftgod.R110_DeleteCustomPreset = driftgod.R199_DeleteSelectedCustomPreset

    r199_log('Custom preset auto-refresh patch loaded')
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"

    local function log(msg)
        if driftgod.R196B_TuningDebug then driftgod.R196B_TuningDebug('[R202] ' .. tostring(msg or ''))
        elseif driftgod.Log then driftgod.Log('[DriftTuning][R202] ' .. tostring(msg or '')) end
    end

    local function safeName(name)
        name = tostring(name or 'CustomPreset')
        name = name:gsub('[\\/:%*%?"<>|]', '_')
        name = name:gsub('%s+', '_')
        name = name:gsub('_+', '_')
        name = name:gsub('^_+', ''):gsub('_+$', '')
        if name == '' then name = 'CustomPreset' end
        return name
    end

    local function displayPresetName(id)
        id = tostring(id or '')
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            if tostring(p.id or '') == id then return tostring(p.name or p.id or id) end
        end
        return id
    end

    local function prefixForBase(id)
        local n = displayPresetName(id)
        n = safeName(n)
        if n == '' or n == 'CustomPreset' then return 'CustomPreset-' end
        return n .. '-'
    end

    function driftgod.R202_SetCustomPresetNamePrefix(baseId, force)
        driftgod.S = driftgod.S or {}
        local prefix = prefixForBase(baseId or driftgod.S.r195BaseTuningPreset or driftgod.S.r198BaseTuningPreset or driftgod.S.activeArcadeDriftPreset)
        local current = tostring(driftgod.S.customPresetName or '')
        local last = tostring(driftgod.S.r202LastAutoPresetPrefix or '')
        if force == true or current == '' or current == 'CustomPreset' or current == last or current:match('^[%w_]+%-$') then
            driftgod.S.customPresetName = prefix
            driftgod.S.r202LastAutoPresetPrefix = prefix
            log('Preset name prefilled: ' .. tostring(prefix))
        else
            driftgod.S.r202LastAutoPresetPrefix = prefix
        end
        return driftgod.S.customPresetName
    end

    local function dir()
        if driftgod.R109_CustomPresetDir then return driftgod.R109_CustomPresetDir end
        if FileMgr and FileMgr.GetMenuRootPath then return FileMgr.GetMenuRootPath() .. '\\Lua\\DriftGod\\storage\\presets\\' end
        return 'DriftGod\\storage\\presets\\'
    end

    local function ensureDir()
        driftgod.Try(function()
            if FileMgr and FileMgr.CreateDir then
                if FileMgr.GetMenuRootPath then
                    FileMgr.CreateDir(FileMgr.GetMenuRootPath() .. '\\Lua\\DriftGod')
                    FileMgr.CreateDir(FileMgr.GetMenuRootPath() .. '\\Lua\\DriftGod\\storage')
                end
                FileMgr.CreateDir(dir())
            end
        end)
    end

    local function path(name) return dir() .. safeName(name) .. '.lua' end

    local function getFeature(hash)
        if not hash then return nil end
        local feat = nil
        driftgod.Try(function()
            if FeatureMgr and FeatureMgr.GetFeature then feat = FeatureMgr.GetFeature(hash)
            elseif FeatureMgr and FeatureMgr.GetFeatureByHash then feat = FeatureMgr.GetFeatureByHash(hash) end
        end)
        return feat
    end

    local function featBool(hash, fallback)
        local feat = getFeature(hash)
        if not feat then return fallback == true end
        local out = fallback == true
        driftgod.Try(function()
            if feat.IsToggled then out = feat:IsToggled() == true
            elseif feat.GetBoolValue then out = feat:GetBoolValue() == true
            elseif feat.GetValue then out = feat:GetValue() == true
            elseif feat.IsOn then out = feat:IsOn() == true end
        end)
        return out == true
    end

    local function featInt(hash, fallback, mn, mx)
        local feat = getFeature(hash)
        local out = tonumber(fallback or mn or 0) or (mn or 0)
        if feat then
            driftgod.Try(function()
                if feat.GetIntValue then out = feat:GetIntValue()
                elseif feat.GetValue then out = feat:GetValue()
                elseif feat.GetFloatValue then out = feat:GetFloatValue() end
            end)
        end
        out = tonumber(out or fallback or mn or 0) or (mn or 0)
        if mn ~= nil and out < mn then out = mn end
        if mx ~= nil and out > mx then out = mx end
        return math.floor(out)
    end

    local function setFeatBool(hash, value)
        local feat = getFeature(hash)
        if not feat then return false end
        local on = value == true
        local ok = driftgod.Try(function()
            if feat.SetBoolValue then feat:SetBoolValue(on)
            elseif feat.SetToggle then feat:SetToggle(on)
            elseif feat.SetToggled then feat:SetToggled(on)
            elseif feat.SetValue then feat:SetValue(on) end
        end)
        driftgod.Try(function()
            if feat.TriggerCallback then feat:TriggerCallback()
            elseif feat.Trigger then feat:Trigger()
            elseif feat.OnClick then feat:OnClick() end
        end)
        return ok
    end

    local function setFeatInt(hash, value, mn, mx)
        local feat = getFeature(hash)
        value = tonumber(value or mn or 0) or (mn or 0)
        if mn ~= nil and value < mn then value = mn end
        if mx ~= nil and value > mx then value = mx end
        value = math.floor(value)
        if not feat then return false end
        local ok = driftgod.Try(function()
            if feat.SetIntValue then feat:SetIntValue(value)
            elseif feat.SetValue then feat:SetValue(value)
            elseif feat.SetFloatValue then feat:SetFloatValue(value) end
        end)
        driftgod.Try(function()
            if feat.TriggerCallback then feat:TriggerCallback()
            elseif feat.Trigger then feat:Trigger() end
        end)
        return ok
    end

    local function setAliases(kind, v)
        driftgod.S = driftgod.S or {}
        v = tonumber(v or 0) or 0
        if kind == 'drift' then driftgod.S.driftGripLevel = v; driftgod.S.driftLevel = v; driftgod.S.drift = v
        elseif kind == 'stability' then driftgod.S.driftStabilityLevel = v; driftgod.S.stabilityLevel = v; driftgod.S.stability = v; driftgod.S.driftStability = v
        elseif kind == 'counter' then driftgod.S.autoCounterSteerLevel = v; driftgod.S.counterSteerLevel = v; driftgod.S.autoCounterSteer = v; driftgod.S.driftCounterSteer = v
        elseif kind == 'momentum' then driftgod.S.momentumStrength = v; driftgod.S.momentumLevel = v; driftgod.S.momentum = v; driftgod.S.driftMomentum = v
        elseif kind == 'accel' then driftgod.S.accelStrength = v; driftgod.S.accelerationLevel = v; driftgod.S.acceleration = v; driftgod.S.driftAcceleration = v
        elseif kind == 'gravity' then driftgod.S.experimentalGravityStrength = v
        elseif kind == 'expaccel' then driftgod.S.experimentalAccelStrength = v
        elseif kind == 'traction' then driftgod.S.experimentalTractionLevel = v
        elseif kind == 'grip' then driftgod.S.experimentalGripLevel = v end
    end

    local boolMap = {
        {key='driftAssistEnabled', hash=function() return driftgod.H.DriftAssist end},
        {key='driftTuningEnabled', hash=function() return driftgod.H.DriftTuningMaster end},
        {key='driftTuningDriftEnabled', hash=function() return driftgod.H.R179_DriftToggle end},
        {key='stabilityAssistEnabled', hash=function() return driftgod.H.StabilityAssist end},
        {key='autoCounterSteerEnabled', hash=function() return driftgod.H.AutoCounterSteer end},
        {key='momentumAssistEnabled', hash=function() return driftgod.H.MomentumAssist end},
        {key='accelAssistEnabled', hash=function() return driftgod.H.AccelAssist end},
        {key='experimentalGravityEnabled', hash=function() return driftgod.H.ExperimentalGravity end},
        {key='experimentalAccelEnabled', hash=function() return driftgod.H.ExperimentalAcceleration or driftgod.H.ExperimentalAccel end},
        {key='experimentalTractionEnabled', hash=function() return driftgod.H.ExperimentalTraction end},
        {key='experimentalGripEnabled', hash=function() return driftgod.H.ExperimentalGrip end},
    }

    local intMap = {
        {key='driftGripLevel', alias='drift', hash=function() return driftgod.H.R123_DriftSlider end, mn=1, mx=5},
        {key='driftStabilityLevel', alias='stability', hash=function() return driftgod.H.R123_StabilitySlider end, mn=1, mx=5},
        {key='autoCounterSteerLevel', alias='counter', hash=function() return driftgod.H.R123_CounterSlider end, mn=1, mx=5},
        {key='momentumStrength', alias='momentum', hash=function() return driftgod.H.R123_MomentumSlider end, mn=1, mx=5},
        {key='accelStrength', alias='accel', hash=function() return driftgod.H.R123_AccelSlider end, mn=1, mx=5},
        {key='experimentalGravityStrength', alias='gravity', hash=function() return driftgod.H.R123_GravitySlider end, mn=1, mx=5},
        {key='experimentalAccelStrength', alias='expaccel', hash=function() return driftgod.H.R123_ExpAccelSlider end, mn=1, mx=5},
        {key='experimentalTractionLevel', alias='traction', hash=function() return driftgod.H.R123_TractionSlider end, mn=0, mx=5},
        {key='experimentalGripLevel', alias='grip', hash=function() return driftgod.H.R123_GripSlider end, mn=0, mx=5},
    }

    function driftgod.R202_CaptureTuningFeatureState()
        driftgod.S = driftgod.S or {}
        for _, row in ipairs(boolMap) do
            local h = row.hash and row.hash() or nil
            if h then driftgod.S[row.key] = featBool(h, driftgod.S[row.key]) end
        end
        for _, row in ipairs(intMap) do
            local h = row.hash and row.hash() or nil
            local v = featInt(h, driftgod.S[row.key], row.mn, row.mx)
            driftgod.S[row.key] = v
            setAliases(row.alias, v)
        end
        return true
    end

    function driftgod.R202_ApplyTuningFeatureState(tbl)
        driftgod.S = driftgod.S or {}
        tbl = tbl or driftgod.S

        for _, row in ipairs(boolMap) do
            if tbl[row.key] ~= nil then driftgod.S[row.key] = tbl[row.key] == true end
        end
        for _, row in ipairs(intMap) do
            if tbl[row.key] ~= nil then
                local v = tonumber(tbl[row.key]) or row.mn
                driftgod.S[row.key] = v
                setAliases(row.alias, v)
            end
        end

        for _, row in ipairs(boolMap) do
            if tbl[row.key] ~= nil then setFeatBool(row.hash and row.hash() or nil, tbl[row.key] == true) end
        end
        for _, row in ipairs(intMap) do
            if tbl[row.key] ~= nil then setFeatInt(row.hash and row.hash() or nil, tbl[row.key], row.mn, row.mx) end
        end
        return true
    end

    local SaveKeys = {
        'customPresetName',
        'base_preset',
        'source_preset',
        'r195BaseTuningPreset',
        'r198BaseTuningPreset',
        'activeArcadeDriftPreset',
        'arcadePresetRuntimeAssist',
        'arcadePresetRuntimeEnabled',
        'driftAssistEnabled',
        'driftTuningEnabled',
        'driftTuningDriftEnabled',
        'stabilityAssistEnabled',
        'autoCounterSteerEnabled',
        'momentumAssistEnabled',
        'accelAssistEnabled',
        'experimentalGravityEnabled',
        'experimentalAccelEnabled',
        'experimentalTractionEnabled',
        'experimentalGripEnabled',
        'driftGripLevel',
        'driftStabilityLevel',
        'stabilityLevel',
        'autoCounterSteerLevel',
        'counterSteerLevel',
        'momentumStrength',
        'momentumLevel',
        'accelStrength',
        'accelerationLevel',
        'experimentalGravityStrength',
        'experimentalAccelStrength',
        'experimentalTractionLevel',
        'experimentalGripLevel'
    }

    local function serialize(tbl)
        local out = { 'return {' }
        for _, k in ipairs(SaveKeys) do
            local v = tbl[k]
            if type(v) == 'number' or type(v) == 'boolean' then
                out[#out+1] = '  ' .. k .. ' = ' .. tostring(v) .. ','
            elseif type(v) == 'string' then
                out[#out+1] = '  ' .. k .. ' = ' .. string.format('%q', v) .. ','
            end
        end
        out[#out+1] = '  preset_schema = "DriftGodCustomPreset_R202",'
        out[#out+1] = '  saved_at = ' .. tostring(tbl.saved_at or (os.time and os.time() or math.floor((os.clock() or 0) * 1000))) .. ','
        out[#out+1] = '  is_custom_preset = true,'
        out[#out+1] = '}'
        return table.concat(out, '\n')
    end

    function driftgod.R202_ScanCustomPresets()
        if driftgod.R199_ScanCustomPresets then return driftgod.R199_ScanCustomPresets() end
        return driftgod.S.customPresetList or {}
    end

    local function readPreset(name)
        local ok, tbl = driftgod.Try(function() return dofile(path(name)) end)
        if ok and type(tbl) == 'table' then return tbl end
        return nil
    end

    local function existingSet()
        local set = {}
        for _, n in ipairs(driftgod.R202_ScanCustomPresets() or {}) do set[safeName(n)] = true end
        return set
    end

    local function builtinSet()
        local set = {}
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            set[safeName(p.id or '')] = true
            set[safeName(p.name or '')] = true
        end
        return set
    end

    local function uniqueName(requested)
        local base = safeName(requested or driftgod.S.customPresetName or 'CustomPreset')
        local builtins = builtinSet()
        local existing = existingSet()
        if not builtins[base] and not existing[base] then return base end
        local i = 2
        while true do
            local candidate = base .. '_' .. tostring(i)
            if not builtins[candidate] and not existing[candidate] then return candidate end
            i = i + 1
        end
    end

    local function markRecent(name)
        if driftgod.R199_ScanCustomPresets then
            driftgod.S.r199CustomPresetRecent = driftgod.S.r199CustomPresetRecent or {}
        end
        local out = { name }
        local function merge(src)
            if type(src) ~= 'table' then return end
            for _, n in ipairs(src) do if tostring(n) ~= tostring(name) then out[#out+1] = tostring(n) end end
        end
        merge(driftgod.S.r199CustomPresetRecent)
        merge(driftgod.S.r197CustomPresetRecent)
        merge(driftgod.S.customPresetList)
        driftgod.S.r199CustomPresetRecent = out
        driftgod.S.r197CustomPresetRecent = out
        driftgod.S.customPresetList = out
        driftgod.S.customPresetIndex = 1
    end

    function driftgod.R202_SaveCustomPreset()
        ensureDir()
        driftgod.S = driftgod.S or {}
        if driftgod.R123RegisterSliders then driftgod.Try(driftgod.R123RegisterSliders) end
        driftgod.R202_CaptureTuningFeatureState()

        local base = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.r198BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or '')
        if base == '' then base = tostring(driftgod.S.activeArcadeDriftPreset or '') end
        local name = uniqueName(driftgod.S.customPresetName or prefixForBase(base))

        local tbl = {
            customPresetName = name,
            base_preset = base,
            source_preset = base,
            r195BaseTuningPreset = base,
            r198BaseTuningPreset = base,
            activeArcadeDriftPreset = base,
            saved_at = os.time and os.time() or math.floor((os.clock() or 0) * 1000)
        }
        for _, k in ipairs(SaveKeys) do if driftgod.S[k] ~= nil then tbl[k] = driftgod.S[k] end end
        tbl.customPresetName = name
        tbl.base_preset = base
        tbl.source_preset = base
        tbl.r195BaseTuningPreset = base
        tbl.r198BaseTuningPreset = base
        tbl.activeArcadeDriftPreset = base

        local ok = false
        driftgod.Try(function()
            if FileMgr and FileMgr.WriteFileContent then ok = FileMgr.WriteFileContent(path(name), serialize(tbl), false) end
        end)
        if not ok then
            driftgod.Try(function()
                local f = io.open(path(name), 'w')
                if f then f:write(serialize(tbl)); f:close(); ok = true end
            end)
        end

        driftgod.S.customPresetName = name
        driftgod.S.r202ActiveCustomPreset = name
        driftgod.S.r199ActiveCustomPreset = name
        markRecent(name)
        if driftgod.R199_ScanCustomPresets then driftgod.Try(driftgod.R199_ScanCustomPresets) end
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        log('Saved custom tuning preset: ' .. tostring(name) .. ' | base=' .. tostring(base))
        if driftgod.Toast then driftgod.Toast(ok and ('Saved preset: ' .. tostring(name)) or 'Preset save failed', 2200) end
        return ok
    end

    function driftgod.R202_LoadSelectedCustomPreset()
        local list = driftgod.R202_ScanCustomPresets() or {}
        local name = list[tonumber(driftgod.S.customPresetIndex or 1) or 1]
        if not name then if driftgod.Toast then driftgod.Toast('No custom preset selected', 1800) end; return false end

        local tbl = readPreset(name)
        if type(tbl) ~= 'table' then if driftgod.Toast then driftgod.Toast('Preset load failed', 2200) end; return false end

        local base = tostring(tbl.base_preset or tbl.r195BaseTuningPreset or tbl.r198BaseTuningPreset or tbl.activeArcadeDriftPreset or '')
        driftgod.S.r202SuppressBasePrefill = true
        if base ~= '' and driftgod.ApplyArcadeDriftPreset then driftgod.Try(function() driftgod.ApplyArcadeDriftPreset(base, false) end) end
        driftgod.S.r202SuppressBasePrefill = false

        for _, k in ipairs(SaveKeys) do
            if tbl[k] ~= nil then driftgod.S[k] = tbl[k] end
        end
        driftgod.S.r195BaseTuningPreset = base ~= '' and base or driftgod.S.r195BaseTuningPreset
        driftgod.S.r198BaseTuningPreset = base ~= '' and base or driftgod.S.r198BaseTuningPreset
        driftgod.S.activeArcadeDriftPreset = base ~= '' and base or driftgod.S.activeArcadeDriftPreset
        driftgod.S.customPresetName = tostring(tbl.customPresetName or name)
        driftgod.S.r202ActiveCustomPreset = name
        driftgod.S.r199ActiveCustomPreset = name

        driftgod.R202_ApplyTuningFeatureState(tbl)

        markRecent(name)
        if driftgod.R199_ScanCustomPresets then driftgod.Try(driftgod.R199_ScanCustomPresets) end
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        log('Loaded custom tuning preset: ' .. tostring(name) .. ' | base=' .. tostring(base))
        if driftgod.Toast then driftgod.Toast('Applied custom preset: ' .. tostring(name), 2200) end
        return true
    end

    function driftgod.R202_DeleteSelectedCustomPreset()
        if driftgod.R199_DeleteSelectedCustomPreset then return driftgod.R199_DeleteSelectedCustomPreset() end
        return false
    end

    driftgod.R109_SaveCustomPreset = driftgod.R202_SaveCustomPreset
    driftgod.R110_SaveCustomPreset = driftgod.R202_SaveCustomPreset
    driftgod.R197_SaveCustomPreset = driftgod.R202_SaveCustomPreset
    driftgod.R199_SaveCustomPreset = driftgod.R202_SaveCustomPreset

    driftgod.R109_LoadSelectedCustomPreset = driftgod.R202_LoadSelectedCustomPreset
    driftgod.R110_ApplyCustomPreset = driftgod.R202_LoadSelectedCustomPreset
    driftgod.R197_LoadSelectedCustomPreset = driftgod.R202_LoadSelectedCustomPreset
    driftgod.R199_LoadSelectedCustomPreset = driftgod.R202_LoadSelectedCustomPreset

    if not driftgod._R202_ApplyPresetWrapped and driftgod.ApplyArcadeDriftPreset then
        local oldApply = driftgod.ApplyArcadeDriftPreset
        driftgod.ApplyArcadeDriftPreset = function(id, showToast)
            local ok = oldApply(id, showToast)
            if ok ~= false then
                driftgod.S = driftgod.S or {}
                driftgod.S.r195BaseTuningPreset = tostring(id or driftgod.S.activeArcadeDriftPreset or '')
                driftgod.S.r198BaseTuningPreset = tostring(id or driftgod.S.activeArcadeDriftPreset or '')
                if driftgod.S.r202SuppressBasePrefill ~= true then
                    driftgod.R202_SetCustomPresetNamePrefix(id, true)
                end
            end
            return ok
        end
        driftgod._R202_ApplyPresetWrapped = true
    end

    if tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.r198BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or '') ~= '' then
        driftgod.R202_SetCustomPresetNamePrefix(driftgod.S.r195BaseTuningPreset or driftgod.S.r198BaseTuningPreset or driftgod.S.activeArcadeDriftPreset, false)
    end

    log('Custom tuning state restore + base-name prefill loaded')
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"

    local function log(msg)
        if driftgod.R196B_TuningDebug then driftgod.R196B_TuningDebug("[R203] " .. tostring(msg or ""))
        elseif driftgod.Log then driftgod.Log("[DriftGod][R203] " .. tostring(msg or "")) end
    end

    local function root()
        local r = "."
        driftgod.Try(function() if FileMgr and FileMgr.GetMenuRootPath then r = FileMgr.GetMenuRootPath() or "." end end)
        if r == nil or r == "" then r = "." end
        return r
    end

    local PRESET_DIR = root() .. "\\Lua\\DriftGod\\storage\\presets\\"

    local function ensureDir()
        driftgod.Try(function()
            if FileMgr and FileMgr.CreateDir then
                FileMgr.CreateDir(root() .. "\\Lua\\DriftGod")
                FileMgr.CreateDir(root() .. "\\Lua\\DriftGod\\storage")
                FileMgr.CreateDir(PRESET_DIR)
            end
        end)
    end

    driftgod.R203_CustomPresetDir = PRESET_DIR
    driftgod.R136_CustomPresetDir = PRESET_DIR
    driftgod.R132_CustomPresetDir = PRESET_DIR
    driftgod.R130_CustomPresetDir = PRESET_DIR
    driftgod.R129_CustomPresetDir = PRESET_DIR
    driftgod.R110_CustomPresetDir = PRESET_DIR
    driftgod.R109_CustomPresetDir = PRESET_DIR

    local function safeName(name)
        name = tostring(name or "CustomPreset")
        name = name:gsub("[\\/:%*%?\"<>|]", "_")
        name = name:gsub("%s+", "_")
        name = name:gsub("_+", "_")
        name = name:gsub("^_+", ""):gsub("_+$", "")
        if name == "" then name = "CustomPreset" end
        return name
    end

    local function pathFor(name) return PRESET_DIR .. safeName(name) .. ".lua" end

    local function fileNameFromPath(p)
        local n = tostring(p or ""):match("([^\\/]+)%.lua$")
        if n then return safeName(n) end
        n = tostring(p or ""):gsub("%.lua$", "")
        if n ~= "" and not n:find("[\\/]") then return safeName(n) end
        return nil
    end

    local function findLuaFiles()
        ensureDir()
        local files, seen = {}, {}
        local function add(f)
            local n = fileNameFromPath(f)
            if n and n ~= "_preset_index" and not seen[n] then
                seen[n] = tostring(f or n)
                files[#files + 1] = tostring(f or n)
            end
        end

        driftgod.Try(function()
            if FileMgr and FileMgr.FindFiles then
                local tries = {
                    function() return FileMgr.FindFiles(PRESET_DIR, "lua", false) end,
                    function() return FileMgr.FindFiles(PRESET_DIR, ".lua", false) end,
                    function() return FileMgr.FindFiles(PRESET_DIR, "lua") end,
                    function() return FileMgr.FindFiles(PRESET_DIR, ".lua") end,
                }
                for _, fn in ipairs(tries) do
                    local ok, result = driftgod.Try(fn)
                    if ok and type(result) == "table" then
                        for _, f in ipairs(result) do add(f) end
                    end
                    if #files > 0 then break end
                end
            end
        end)

        for _, n in ipairs(driftgod.S.r203SavedPresetNames or {}) do add(n) end

        return files
    end

    local function readPreset(nameOrPath)
        local n = fileNameFromPath(nameOrPath) or safeName(nameOrPath)
        local full = tostring(nameOrPath or "")
        if not full:find("[\\/]", 1, false) then full = pathFor(n) end

        local ok, tbl = driftgod.Try(function() return dofile(full) end)
        if ok and type(tbl) == "table" then return tbl, n end

        ok, tbl = driftgod.Try(function()
            if FileMgr and FileMgr.ReadFileContent then
                local txt = FileMgr.ReadFileContent(full)
                if type(txt) == "string" and txt ~= "" then
                    local loader = load or loadstring
                    if loader then
                        local chunk = loader(txt)
                        if chunk then return chunk() end
                    end
                end
            end
            return nil
        end)
        if ok and type(tbl) == "table" then return tbl, n end
        return nil, n
    end

    local function savedAtFor(nameOrPath)
        local tbl = readPreset(nameOrPath)
        if type(tbl) == "table" then
            return tonumber(tbl.saved_at or tbl.customPresetSavedAt or tbl.savedAt or tbl.customPresetSavedAtMs or 0) or 0
        end
        return 0
    end

    function driftgod.R203_ScanCustomPresets()
        ensureDir()
        local names, seen = {}, {}
        for _, f in ipairs(findLuaFiles()) do
            local n = fileNameFromPath(f)
            if n and not seen[n] then
                seen[n] = true
                names[#names + 1] = n
            end
        end

        table.sort(names, function(a, b)
            local aa, bb = savedAtFor(a), savedAtFor(b)
            if aa == bb then return tostring(a) < tostring(b) end
            return aa > bb
        end)

        driftgod.S.customPresetList = names

        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        if #names <= 0 then idx = 1
        elseif idx < 1 then idx = 1
        elseif idx > #names then idx = #names end
        driftgod.S.customPresetIndex = idx

        return names
    end

    function driftgod.R203_ScanRecentCustomPresets(limit)
        local all = driftgod.R203_ScanCustomPresets()
        local out = {}
        limit = tonumber(limit or 3) or 3
        for i = 1, math.min(limit, #all) do out[#out + 1] = all[i] end
        return out
    end

    local SaveKeys = {
        "customPresetName",
        "base_preset", "source_preset",
        "r195BaseTuningPreset", "r198BaseTuningPreset", "activeArcadeDriftPreset",
        "arcadePresetRuntimeAssist", "arcadePresetRuntimeEnabled",
        "driftAssistEnabled", "driftTuningEnabled", "driftTuningDriftEnabled",
        "stabilityAssistEnabled", "autoCounterSteerEnabled",
        "momentumAssistEnabled", "accelAssistEnabled",
        "experimentalGravityEnabled", "experimentalAccelEnabled", "experimentalTractionEnabled", "experimentalGripEnabled",
        "driftGripLevel", "driftStabilityLevel", "stabilityLevel",
        "autoCounterSteerLevel", "counterSteerLevel",
        "momentumStrength", "momentumLevel",
        "accelStrength", "accelerationLevel",
        "experimentalGravityStrength", "experimentalAccelStrength",
        "experimentalTractionLevel", "experimentalGripLevel"
    }

    local function serialize(tbl)
        local out = { "return {" }
        for _, k in ipairs(SaveKeys) do
            local v = tbl[k]
            if type(v) == "number" or type(v) == "boolean" then
                out[#out + 1] = "  " .. k .. " = " .. tostring(v) .. ","
            elseif type(v) == "string" then
                out[#out + 1] = "  " .. k .. " = " .. string.format("%q", v) .. ","
            end
        end
        out[#out + 1] = "  preset_schema = \"DriftGodCustomPreset_R203\","
        out[#out + 1] = "  saved_at = " .. tostring(tbl.saved_at or (os.time and os.time() or math.floor((os.clock() or 0) * 1000))) .. ","
        out[#out + 1] = "  is_custom_preset = true,"
        out[#out + 1] = "}"
        return table.concat(out, "\n")
    end

    local function builtinSet()
        local set = {}
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            set[safeName(p.id or "")] = true
            set[safeName(p.name or "")] = true
        end
        return set
    end

    local function uniqueName(requested)
        local base = safeName(requested or driftgod.S.customPresetName or "CustomPreset")
        local builtins = builtinSet()
        local existing = {}
        for _, n in ipairs(driftgod.R203_ScanCustomPresets()) do existing[safeName(n)] = true end
        if not builtins[base] and not existing[base] then return base end
        local i = 2
        while true do
            local c = base .. "_" .. tostring(i)
            if not builtins[c] and not existing[c] then return c end
            i = i + 1
        end
    end

    local function markJustSaved(name)
        name = safeName(name)
        local out = { name }
        for _, n in ipairs(driftgod.S.r203SavedPresetNames or {}) do
            if tostring(n) ~= name then out[#out + 1] = tostring(n) end
        end
        driftgod.S.r203SavedPresetNames = out
        driftgod.S.customPresetList = out
        driftgod.S.customPresetIndex = 1
    end

    function driftgod.R203_SaveCustomPreset()
        ensureDir()
        driftgod.S = driftgod.S or {}

        if driftgod.R202_CaptureTuningFeatureState then driftgod.Try(driftgod.R202_CaptureTuningFeatureState) end

        local base = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.r198BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or "")
        local name = uniqueName(driftgod.S.customPresetName or "CustomPreset")

        local tbl = {
            customPresetName = name,
            base_preset = base,
            source_preset = base,
            r195BaseTuningPreset = base,
            r198BaseTuningPreset = base,
            activeArcadeDriftPreset = base,
            saved_at = os.time and os.time() or math.floor((os.clock() or 0) * 1000)
        }
        for _, k in ipairs(SaveKeys) do
            if driftgod.S[k] ~= nil then tbl[k] = driftgod.S[k] end
        end
        tbl.customPresetName = name
        tbl.base_preset = base
        tbl.source_preset = base
        tbl.r195BaseTuningPreset = base
        tbl.r198BaseTuningPreset = base
        tbl.activeArcadeDriftPreset = base

        local ok = false
        driftgod.Try(function()
            if FileMgr and FileMgr.WriteFileContent then
                ok = FileMgr.WriteFileContent(pathFor(name), serialize(tbl), false)
            end
        end)
        if not ok then
            driftgod.Try(function()
                local f = io.open(pathFor(name), "w")
                if f then f:write(serialize(tbl)); f:close(); ok = true end
            end)
        end

        markJustSaved(name)
        driftgod.R203_ScanCustomPresets()
        driftgod.S.customPresetIndex = 1
        driftgod.S.customPresetName = name
        driftgod.S.r203ActiveCustomPreset = name

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast(ok and ("Saved preset: " .. tostring(name)) or "Preset save failed", 2200) end
        log("Saved preset to storage\\presets only: " .. tostring(name))
        return ok
    end

    function driftgod.R203_LoadCustomPresetByName(name)
        ensureDir()
        local tbl, clean = readPreset(name)
        if type(tbl) ~= "table" then
            if driftgod.Toast then driftgod.Toast("Preset load failed", 2200) end
            return false
        end
        clean = safeName(clean or name)

        local base = tostring(tbl.base_preset or tbl.r195BaseTuningPreset or tbl.r198BaseTuningPreset or tbl.activeArcadeDriftPreset or "")
        driftgod.S.r202SuppressBasePrefill = true
        if base ~= "" and driftgod.ApplyArcadeDriftPreset then driftgod.Try(function() driftgod.ApplyArcadeDriftPreset(base, false) end) end
        driftgod.S.r202SuppressBasePrefill = false

        for _, k in ipairs(SaveKeys) do
            if tbl[k] ~= nil then driftgod.S[k] = tbl[k] end
        end

        driftgod.S.r195BaseTuningPreset = base ~= "" and base or driftgod.S.r195BaseTuningPreset
        driftgod.S.r198BaseTuningPreset = base ~= "" and base or driftgod.S.r198BaseTuningPreset
        driftgod.S.activeArcadeDriftPreset = base ~= "" and base or driftgod.S.activeArcadeDriftPreset
        driftgod.S.customPresetName = tostring(tbl.customPresetName or clean)
        driftgod.S.r203ActiveCustomPreset = clean

        if driftgod.R202_ApplyTuningFeatureState then driftgod.Try(function() driftgod.R202_ApplyTuningFeatureState(tbl) end) end

        local list = driftgod.R203_ScanCustomPresets()
        for i, n in ipairs(list) do
            if tostring(n) == tostring(clean) then driftgod.S.customPresetIndex = i; break end
        end

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Applied custom preset: " .. tostring(clean), 2200) end
        log("Loaded custom preset from storage\\presets: " .. tostring(clean) .. " | base=" .. tostring(base))
        return true
    end

    function driftgod.R203_LoadSelectedCustomPreset()
        local list = driftgod.R203_ScanCustomPresets()
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        local name = list[idx]
        if not name then
            if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end
            return false
        end
        return driftgod.R203_LoadCustomPresetByName(name)
    end

    function driftgod.R203_DeleteSelectedCustomPreset()
        local list = driftgod.R203_ScanCustomPresets()
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        local name = list[idx]
        if not name then
            if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end
            return false
        end
        driftgod.Try(function()
            if FileMgr and FileMgr.DeleteFile then FileMgr.DeleteFile(pathFor(name))
            elseif os and os.remove then os.remove(pathFor(name)) end
        end)
        driftgod.S.r203SavedPresetNames = {}
        driftgod.R203_ScanCustomPresets()
        driftgod.S.customPresetIndex = 1
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Deleted preset: " .. tostring(name), 2200) end
        return true
    end

