        driftgod.AddToggle("DriftGodPointsHudToggle", "DriftGod Points HUD", "Shows or hides the DriftGod Points HUD.", function(f)
            driftgod.S = driftgod.S or {}
            local on = f and f.IsToggled and f:IsToggled() == true or false
            driftgod.S.pointsHudEnabled = on
