    local function btn(label, color, cb)
        if driftgod.R101_ColorButton then return driftgod.R101_ColorButton(tostring(label or "Apply"), color or "purple", cb) end
        if ImGui and ImGui.Button and ImGui.Button(tostring(label or "Apply")) then if cb then cb() end; return true end
        return false
    end

    local function renderBuiltinFamily(family)
        local any = false
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            if tostring(p.family or "") == tostring(family or "") then
                any = true
                txt(tostring(p.name or p.id or "Preset"), "white")
                btn("Apply##R203_" .. tostring(p.id or p.name), "purple", function()
                    if driftgod.ApplyArcadeDriftPreset then driftgod.ApplyArcadeDriftPreset(p.id, true) end
                end)
            end
        end
        if not any then txt("No presets", "dim") end
    end

    local function renderCustomRecent()
        local list = driftgod.R203_ScanRecentCustomPresets(3)
        if #list <= 0 then
            txt("No custom presets yet.", "dim")
            txt("Save one in Preset Creation.", "dim")
            return
        end
        for _, name in ipairs(list) do
            txt(tostring(name), "white")
            btn("Apply##R203_Custom_" .. tostring(name), "purple", function()
                driftgod.R203_LoadCustomPresetByName(name)
            end)
        end
    end

    function driftgod.R203_RenderPresetColumns(id)
        local groups = {
            { label = "Default / Starter", mode = "families", families = {"Default / Starter", "Open"} },
            { label = "Wide Road", mode = "families", families = {"Wide / Open Roads"} },
            { label = "Technical", mode = "families", families = {"Technical / Windy Roads"} },
            { label = "Custom", mode = "custom" },
        }

        if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex and ImGui.BeginTable(id or "DG_R203_PresetColumns", 4, dgSafeTableFlags and dgSafeTableFlags() or 0) then
            ImGui.TableNextRow()
            for i, g in ipairs(groups) do
                ImGui.TableSetColumnIndex(i - 1)
                txt(g.label, "header")
            end
            ImGui.TableNextRow()
            for i, g in ipairs(groups) do
                ImGui.TableSetColumnIndex(i - 1)
                if g.mode == "custom" then
                    renderCustomRecent()
                else
                    for _, fam in ipairs(g.families or {}) do renderBuiltinFamily(fam) end
                end
            end
            ImGui.EndTable()
        else
            for _, g in ipairs(groups) do
                txt(g.label, "header")
                if g.mode == "custom" then renderCustomRecent()
                else for _, fam in ipairs(g.families or {}) do renderBuiltinFamily(fam) end end
            end
        end
    end

    driftgod.R110_RenderPresetColumns = driftgod.R203_RenderPresetColumns
    driftgod.R129_RenderPresetColumns = driftgod.R203_RenderPresetColumns
    driftgod.R130_RenderPresetColumns = driftgod.R203_RenderPresetColumns
    driftgod.R136_RenderPresetColumns = driftgod.R203_RenderPresetColumns

    driftgod.Try(driftgod.R203_ScanCustomPresets)
    log("Presets folder-only backend and Custom column renderer loaded: " .. tostring(PRESET_DIR))
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"

    local function log(msg)
        if driftgod.R196B_TuningDebug then driftgod.R196B_TuningDebug("[R204] " .. tostring(msg or ""))
        elseif driftgod.Log then driftgod.Log("[DriftTuning][R204] " .. tostring(msg or "")) end
    end

    local function getPreset()
        local id = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.r198BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or "")
        if id ~= "" and driftgod.GetArcadeDriftPresetById then
            local ok, p = driftgod.Try(function() return driftgod.GetArcadeDriftPresetById(id) end)
            if ok and type(p) == "table" then return p end
        end
        return nil
    end

    local function getFeature(hash)
        if not hash then return nil end
        local feat = nil
        driftgod.Try(function()
            if FeatureMgr and FeatureMgr.GetFeature then feat = FeatureMgr.GetFeature(hash)
            elseif FeatureMgr and FeatureMgr.GetFeatureByHash then feat = FeatureMgr.GetFeatureByHash(hash) end
        end)
        return feat
    end

    local function setToggle(hash, on)
        local feat = getFeature(hash)
        if not feat then return false end
        on = on == true
        driftgod.Try(function()
            if feat.SetBoolValue then feat:SetBoolValue(on)
            elseif feat.SetToggle then feat:SetToggle(on)
            elseif feat.SetToggled then feat:SetToggled(on)
            elseif feat.SetValue then feat:SetValue(on) end
        end)
        driftgod.Try(function()
            if feat.TriggerCallback then feat:TriggerCallback()
            elseif feat.Trigger then feat:Trigger() end
        end)
        return true
    end

    local function setSlider(hash, value)
        local feat = getFeature(hash)
        value = math.floor(tonumber(value or 0) or 0)
        if not feat then return false end
        driftgod.Try(function()
            if feat.SetIntValue then feat:SetIntValue(value)
            elseif feat.SetValue then feat:SetValue(value)
            elseif feat.SetFloatValue then feat:SetFloatValue(value) end
        end)
        driftgod.Try(function()
            if feat.TriggerCallback then feat:TriggerCallback()
            elseif feat.Trigger then feat:Trigger() end
        end)
        return true
    end

    function driftgod.R204_ResetTuningDefaults()
        driftgod.S = driftgod.S or {}
        local p = getPreset()

        local drift = tonumber(p and p.drift or 3) or 3
        local stability = tonumber(p and p.stability or 3) or 3
        local momentum = tonumber(p and p.momentum or 3) or 3
        local accel = tonumber(p and p.accel or 3) or 3

        driftgod.S.driftTuningDriftEnabled = false
        driftgod.S.stabilityAssistEnabled = false
        driftgod.S.autoCounterSteerEnabled = false
        driftgod.S.momentumAssistEnabled = false
        driftgod.S.accelAssistEnabled = false
        driftgod.S.experimentalGravityEnabled = false
        driftgod.S.experimentalAccelEnabled = false
        driftgod.S.experimentalTractionEnabled = false
        driftgod.S.experimentalGripEnabled = false

        driftgod.S.driftGripLevel = drift
        driftgod.S.driftLevel = drift
        driftgod.S.drift = drift

        driftgod.S.driftStabilityLevel = stability
        driftgod.S.stabilityLevel = stability
        driftgod.S.stability = stability

        driftgod.S.autoCounterSteerLevel = 3
        driftgod.S.counterSteerLevel = 3
        driftgod.S.autoCounterSteer = 3

        driftgod.S.momentumStrength = momentum
        driftgod.S.momentumLevel = momentum
        driftgod.S.momentum = momentum

        driftgod.S.accelStrength = accel
        driftgod.S.accelerationLevel = accel
        driftgod.S.acceleration = accel

        driftgod.S.experimentalGravityStrength = 3
        driftgod.S.experimentalAccelStrength = 3
        driftgod.S.experimentalTractionLevel = 3
        driftgod.S.experimentalGripLevel = 3

        setToggle(driftgod.H.R179_DriftToggle, false)
        setToggle(driftgod.H.StabilityAssist, false)
        setToggle(driftgod.H.AutoCounterSteer, false)
        setToggle(driftgod.H.MomentumAssist, false)
        setToggle(driftgod.H.AccelAssist, false)
        setToggle(driftgod.H.ExperimentalGravity, false)
        setToggle(driftgod.H.ExperimentalAcceleration or driftgod.H.ExperimentalAccel, false)
        setToggle(driftgod.H.ExperimentalTraction, false)
        setToggle(driftgod.H.ExperimentalGrip, false)

        setSlider(driftgod.H.R123_DriftSlider, drift)
        setSlider(driftgod.H.R123_StabilitySlider, stability)
        setSlider(driftgod.H.R123_CounterSlider, 3)
        setSlider(driftgod.H.R123_MomentumSlider, momentum)
        setSlider(driftgod.H.R123_AccelSlider, accel)
        setSlider(driftgod.H.R123_GravitySlider, 3)
        setSlider(driftgod.H.R123_ExpAccelSlider, 3)
        setSlider(driftgod.H.R123_TractionSlider, 3)
        setSlider(driftgod.H.R123_GripSlider, 3)

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        log("Tuning defaults reset: modifiers OFF, values baseline/neutral")
        return true
    end

    if not driftgod._R204_SafeAddFeatureWrapped and driftgod.SafeAddFeature then
        driftgod._R204_SafeAddFeatureWrapped = true
        local oldSafeAddFeature = driftgod.SafeAddFeature
        driftgod.SafeAddFeature = function(hash, name, ftype, desc, cb, ...)
            local wrapped = cb
            local label = tostring(name or "")
            if label == "Tuning" or label == "Drift Tuning" then
                wrapped = function(feat)
                    local before = driftgod.S and driftgod.S.driftTuningEnabled == true
                    local r
                    if cb then r = cb(feat) end
                    local on = driftgod.S and driftgod.S.driftTuningEnabled == true
                    if on and not before then driftgod.Try(driftgod.R204_ResetTuningDefaults) end
                    return r
                end
            end
            return oldSafeAddFeature(hash, name, ftype, desc, wrapped, ...)
        end
    end

    if driftgod.AddButton and not driftgod.H.R204_ResetTuningDefaults then
        driftgod.H.R204_ResetTuningDefaults = driftgod.Hash and driftgod.Hash("R204_ResetTuningDefaults") or nil
        driftgod.Try(function()
            driftgod.AddButton("R204_ResetTuningDefaults", "Reset Tuning Defaults", "Turns tuning modifiers OFF and resets values to preset defaults.", function()
                return driftgod.R204_ResetTuningDefaults()
            end)
        end)
    end

    log("Tuning master default-reset patch loaded")
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"

    local function log(msg)
        if driftgod.R196B_TuningDebug then driftgod.R196B_TuningDebug("[R205] " .. tostring(msg or ""))
        elseif driftgod.Log then driftgod.Log("[DriftGod][R205] " .. tostring(msg or "")) end
    end

    local function menuRoot()
        local r = "."
        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then r = FileMgr.GetMenuRootPath() or "." end
        end)
        if r == nil or r == "" then r = "." end
        return tostring(r)
    end

    local ROOT = menuRoot()
    local PRESET_DIR = ROOT .. "\\Lua\\DriftGod\\storage\\presets\\"

    local retiredPresetDirs = {}

    driftgod.R203_CustomPresetDir = PRESET_DIR
    driftgod.R202_CustomPresetDir = PRESET_DIR
    driftgod.R199_CustomPresetDir = PRESET_DIR
    driftgod.R197_CustomPresetDir = PRESET_DIR
    driftgod.R136_CustomPresetDir = PRESET_DIR
    driftgod.R132_CustomPresetDir = PRESET_DIR
    driftgod.R130_CustomPresetDir = PRESET_DIR
    driftgod.R129_CustomPresetDir = PRESET_DIR
    driftgod.R110_CustomPresetDir = PRESET_DIR
    driftgod.R109_CustomPresetDir = PRESET_DIR
    driftgod.R205_CustomPresetDir = PRESET_DIR

    local function ensureDir()
        driftgod.Try(function()
            if FileMgr and FileMgr.CreateDir then
                FileMgr.CreateDir(ROOT .. "\\Lua\\DriftGod")
                FileMgr.CreateDir(ROOT .. "\\Lua\\DriftGod\\storage")
                FileMgr.CreateDir(PRESET_DIR)
            end
        end)
    end

    local function safeName(name)
        name = tostring(name or "CustomPreset")
        name = name:gsub("[\\/:%*%?\"<>|]", "_")
        name = name:gsub("%s+", "_")
        name = name:gsub("_+", "_")
        name = name:gsub("^_+", ""):gsub("_+$", "")
        if name == "" then name = "CustomPreset" end
        return name
    end

    local function fileNameFromPath(p)
        local n = tostring(p or ""):match("([^\\/]+)%.lua$")
        if n then return safeName(n) end
        n = tostring(p or ""):gsub("%.lua$", "")
        if n ~= "" and not n:find("[\\/]", 1, false) then return safeName(n) end
        return nil
    end

    local function pathFor(name)
        return PRESET_DIR .. safeName(name) .. ".lua"
    end

    local function join(dir, name)
        return tostring(dir or "") .. safeName(name) .. ".lua"
    end

    local function readText(path)
        local ok, txt = driftgod.Try(function()
            if FileMgr and FileMgr.ReadFileContent then return FileMgr.ReadFileContent(path) end
            return nil
        end)
        if ok and type(txt) == "string" and txt ~= "" then return txt end

        ok, txt = driftgod.Try(function()
            local f = io and io.open and io.open(path, "r")
            if not f then return nil end
            local s = f:read("*a")
            f:close()
            return s
        end)
        if ok and type(txt) == "string" and txt ~= "" then return txt end
        return nil
    end

    local function writeText(path, txt)
        local ok = false
        driftgod.Try(function()
            if FileMgr and FileMgr.WriteFileContent then ok = FileMgr.WriteFileContent(path, tostring(txt or ""), false) end
        end)
        if ok then return true end

        driftgod.Try(function()
            local f = io and io.open and io.open(path, "w")
            if f then f:write(tostring(txt or "")); f:close(); ok = true end
        end)
        return ok == true
    end

    local function listFilesInDir(dir)
        local out, seen = {}, {}

        local function add(raw)
            local n = fileNameFromPath(raw)
            if n and n ~= "_preset_index" and not seen[n] then
                seen[n] = true
                out[#out + 1] = { name = n, path = tostring(raw or ""):find("[\\/]", 1, false) and tostring(raw) or join(dir, n) }
            end
        end

        driftgod.Try(function()
            if FileMgr and FileMgr.FindFiles then
                local tries = {
                    function() return FileMgr.FindFiles(dir, "lua", false) end,
                    function() return FileMgr.FindFiles(dir, ".lua", false) end,
                    function() return FileMgr.FindFiles(dir, "*.lua", false) end,
                    function() return FileMgr.FindFiles(dir, "lua") end,
                    function() return FileMgr.FindFiles(dir, ".lua") end,
                    function() return FileMgr.FindFiles(dir, "*.lua") end,
                }
                for _, fn in ipairs(tries) do
                    local ok, files = driftgod.Try(fn)
                    if ok and type(files) == "table" then
                        for _, f in ipairs(files) do add(f) end
                    end
                    if #out > 0 then break end
                end
            end
        end)

        if #out <= 0 then
            driftgod.Try(function()
                if io and io.popen then
                    local cmd = 'dir /b /a-d "' .. tostring(dir) .. '*.lua" 2>nul'
                    local p = io.popen(cmd)
                    if p then
                        for line in p:lines() do add(line) end
                        p:close()
                    end
                end
            end)
        end

        return out
    end

    local function loadPresetTable(name)
        local full = pathFor(name)
        local ok, tbl = driftgod.Try(function() return dofile(full) end)
        if ok and type(tbl) == "table" then return tbl end

        local txt = readText(full)
        if type(txt) == "string" then
            ok, tbl = driftgod.Try(function()
                local loader = load or loadstring
                if not loader then return nil end
                local chunk = loader(txt)
                if chunk then return chunk() end
                return nil
            end)
            if ok and type(tbl) == "table" then return tbl end
        end
        return nil
    end

    local function savedAt(name)
        local tbl = loadPresetTable(name)
        if type(tbl) == "table" then return tonumber(tbl.saved_at or tbl.savedAt or tbl.customPresetSavedAt or 0) or 0 end
        return 0
    end

    local function migrateLegacy()
        ensureDir()
        if driftgod.S.r205LegacyMigrationDone == true then return end

        local migrated = 0
        local existing = {}
        for _, f in ipairs(listFilesInDir(PRESET_DIR)) do existing[safeName(f.name)] = true end

        for _, dir in ipairs(retiredPresetDirs) do
            if tostring(dir) ~= tostring(PRESET_DIR) then
                for _, f in ipairs(listFilesInDir(dir)) do
                    local n = safeName(f.name)
                    if n ~= "" and not existing[n] then
                        local txt = readText(f.path)
                        if type(txt) == "string" and txt ~= "" then
                            if writeText(pathFor(n), txt) then
                                existing[n] = true
                                migrated = migrated + 1
                            end
                        end
                    end
                end
            end
        end

        driftgod.S.r205LegacyMigrationDone = true
        if migrated > 0 then log("Migrated " .. tostring(migrated) .. " legacy custom presets into storage\\presets") end
    end

    function driftgod.R205_ScanCustomPresets()
        ensureDir()
        migrateLegacy()

        local names, seen = {}, {}
        for _, f in ipairs(listFilesInDir(PRESET_DIR)) do
            local n = safeName(f.name)
            if n ~= "" and n ~= "_preset_index" and not seen[n] then
                seen[n] = true
                names[#names + 1] = n
            end
        end

        for _, n in ipairs(driftgod.S.r203SavedPresetNames or {}) do
            n = safeName(n)
            if n ~= "" and not seen[n] then seen[n] = true; names[#names + 1] = n end
        end
        for _, n in ipairs(driftgod.S.r205SavedPresetNames or {}) do
            n = safeName(n)
            if n ~= "" and not seen[n] then seen[n] = true; names[#names + 1] = n end
        end

        table.sort(names, function(a, b)
            local aa, bb = savedAt(a), savedAt(b)
            if aa == bb then return tostring(a) < tostring(b) end
            return aa > bb
        end)

        driftgod.S.customPresetList = names

        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        if #names <= 0 then idx = 1
        elseif idx < 1 then idx = 1
        elseif idx > #names then idx = #names end
        driftgod.S.customPresetIndex = idx

        return names
    end

    function driftgod.R205_RecentCustomPresets(limit)
        local all = driftgod.R205_ScanCustomPresets()
        local out = {}
        limit = tonumber(limit or 3) or 3
        for i = 1, math.min(limit, #all) do out[#out + 1] = all[i] end
        return out
    end

    function driftgod.R205_LoadCustomPresetByName(name)
        name = safeName(name)
        local tbl = loadPresetTable(name)
        if type(tbl) ~= "table" then
            if driftgod.Toast then driftgod.Toast("Preset load failed", 2200) end
            return false
        end

        local base = tostring(tbl.base_preset or tbl.r195BaseTuningPreset or tbl.r198BaseTuningPreset or tbl.activeArcadeDriftPreset or "")
        driftgod.S.r202SuppressBasePrefill = true
        if base ~= "" and driftgod.ApplyArcadeDriftPreset then driftgod.Try(function() driftgod.ApplyArcadeDriftPreset(base, false) end) end
        driftgod.S.r202SuppressBasePrefill = false

        local keys = {
            "customPresetName",
            "base_preset", "source_preset",
            "r195BaseTuningPreset", "r198BaseTuningPreset", "activeArcadeDriftPreset",
            "arcadePresetRuntimeAssist", "arcadePresetRuntimeEnabled",
            "driftAssistEnabled", "driftTuningEnabled", "driftTuningDriftEnabled",
            "stabilityAssistEnabled", "autoCounterSteerEnabled",
            "momentumAssistEnabled", "accelAssistEnabled",
            "experimentalGravityEnabled", "experimentalAccelEnabled", "experimentalTractionEnabled", "experimentalGripEnabled",
            "driftGripLevel", "driftStabilityLevel", "stabilityLevel",
            "autoCounterSteerLevel", "counterSteerLevel",
            "momentumStrength", "momentumLevel",
            "accelStrength", "accelerationLevel",
            "experimentalGravityStrength", "experimentalAccelStrength",
            "experimentalTractionLevel", "experimentalGripLevel"
        }

        for _, k in ipairs(keys) do if tbl[k] ~= nil then driftgod.S[k] = tbl[k] end end
        driftgod.S.r195BaseTuningPreset = base ~= "" and base or driftgod.S.r195BaseTuningPreset
        driftgod.S.r198BaseTuningPreset = base ~= "" and base or driftgod.S.r198BaseTuningPreset
        driftgod.S.activeArcadeDriftPreset = base ~= "" and base or driftgod.S.activeArcadeDriftPreset
        driftgod.S.customPresetName = tostring(tbl.customPresetName or name)
        driftgod.S.r205ActiveCustomPreset = name

        if driftgod.R202_ApplyTuningFeatureState then driftgod.Try(function() driftgod.R202_ApplyTuningFeatureState(tbl) end) end

        local list = driftgod.R205_ScanCustomPresets()
        for i, n in ipairs(list) do if tostring(n) == tostring(name) then driftgod.S.customPresetIndex = i; break end end

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Applied custom preset: " .. tostring(name), 2200) end
        log("Loaded custom preset: " .. tostring(name) .. " | base=" .. tostring(base))
        return true
    end

    function driftgod.R205_LoadSelectedCustomPreset()
        local list = driftgod.R205_ScanCustomPresets()
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        local name = list[idx]
        if not name then
            if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end
            return false
        end
        return driftgod.R205_LoadCustomPresetByName(name)
    end

    driftgod.R109_ScanCustomPresets = driftgod.R205_ScanCustomPresets
    driftgod.R110_ScanCustomPresets = driftgod.R205_ScanCustomPresets
    driftgod.R129_ScanCustomPresets = driftgod.R205_ScanCustomPresets
    driftgod.R130_ScanCustomPresets = driftgod.R205_ScanCustomPresets
    driftgod.R132_ScanCustomPresets = driftgod.R205_ScanCustomPresets
    driftgod.R136_ScanCustomPresets = driftgod.R205_ScanCustomPresets
    driftgod.R197_ScanCustomPresets = driftgod.R205_ScanCustomPresets
    driftgod.R199_ScanCustomPresets = driftgod.R205_ScanCustomPresets
    driftgod.R202_ScanCustomPresets = driftgod.R205_ScanCustomPresets
    driftgod.R203_ScanCustomPresets = driftgod.R205_ScanCustomPresets

    driftgod.R109_LoadSelectedCustomPreset = driftgod.R205_LoadSelectedCustomPreset
    driftgod.R110_ApplyCustomPreset = driftgod.R205_LoadSelectedCustomPreset
    driftgod.R136_LoadSelectedCustomPreset = driftgod.R205_LoadSelectedCustomPreset
    driftgod.R197_LoadSelectedCustomPreset = driftgod.R205_LoadSelectedCustomPreset
    driftgod.R199_LoadSelectedCustomPreset = driftgod.R205_LoadSelectedCustomPreset
    driftgod.R202_LoadSelectedCustomPreset = driftgod.R205_LoadSelectedCustomPreset
    driftgod.R203_LoadSelectedCustomPreset = driftgod.R205_LoadSelectedCustomPreset

    local function txt(msg, color)
        if R110Text then R110Text(tostring(msg or ""), color or "white")
        elseif dgA38Text then dgA38Text(tostring(msg or ""), color or "white")
        elseif ImGui and ImGui.Text then ImGui.Text(tostring(msg or "")) end
    end

    local function button(label, cb)
        if R123PurpleButton then return R123PurpleButton(label, cb) end
        if driftgod.R101_ColorButton then return driftgod.R101_ColorButton(label, "purple", cb) end
        if ImGui and ImGui.Button and ImGui.Button(label) then if cb then cb() end; return true end
        return false
    end

    function driftgod.R205_RenderPresetCreation()
        if R110Child and R110Child("Preset Creation") then
            driftgod.S.customPresetName = tostring(driftgod.S.customPresetName or "CustomPreset")
            if ImGui and ImGui.InputText then
                local ok, value = driftgod.Try(function() return ImGui.InputText("Preset Name##R205", driftgod.S.customPresetName, 64) end)
                if ok then
                    if type(value) == "string" then driftgod.S.customPresetName = value
                    elseif type(value) == "table" and value[1] then driftgod.S.customPresetName = tostring(value[1]) end
                end
            else
                txt("Preset Name: " .. tostring(driftgod.S.customPresetName), "white")
            end

            button("Save Current Tuning##R205", driftgod.R203_SaveCustomPreset or driftgod.R202_SaveCustomPreset or driftgod.R110_SaveCustomPreset)
            if R110SameLine then R110SameLine() elseif ImGui and ImGui.SameLine then ImGui.SameLine() end
