    driftgod.Try(driftgod.R205_ScanCustomPresets)
    driftgod.S.r205AutoScanUntil = (driftgod.Now and driftgod.Now() or math.floor((os.clock() or 0) * 1000)) + 15000
    driftgod.S.r205NextAutoScan = 0

    if driftgod.AddTickHandler and not driftgod._R205_AutoScanTick then
        driftgod._R205_AutoScanTick = true
        driftgod.Try(function()
            driftgod.AddTickHandler(function()
                local now = driftgod.Now and driftgod.Now() or math.floor((os.clock() or 0) * 1000)
                if now <= tonumber(driftgod.S.r205AutoScanUntil or 0) and now >= tonumber(driftgod.S.r205NextAutoScan or 0) then
                    driftgod.S.r205NextAutoScan = now + 1500
                    driftgod.Try(driftgod.R205_ScanCustomPresets)
                end
            end)
        end)
