end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"

    local function log(msg)
        if driftgod.R196B_TuningDebug then driftgod.R196B_TuningDebug("[R206] " .. tostring(msg or ""))
        elseif driftgod.Log then driftgod.Log("[DriftGod][R206] " .. tostring(msg or "")) end
    end

    local function menuRoot()
        local r = "."
        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then r = FileMgr.GetMenuRootPath() or "." end
        end)
        if r == nil or r == "" then r = "." end
        return tostring(r)
    end

    local ROOT = menuRoot()
    local PRESET_DIR = ROOT .. "\\Lua\\DriftGod\\storage\\presets\\"

    driftgod.R206_CustomPresetDir = PRESET_DIR
    driftgod.R205_CustomPresetDir = PRESET_DIR
    driftgod.R203_CustomPresetDir = PRESET_DIR
    driftgod.R202_CustomPresetDir = PRESET_DIR
    driftgod.R199_CustomPresetDir = PRESET_DIR
    driftgod.R197_CustomPresetDir = PRESET_DIR
    driftgod.R136_CustomPresetDir = PRESET_DIR
    driftgod.R132_CustomPresetDir = PRESET_DIR
    driftgod.R130_CustomPresetDir = PRESET_DIR
    driftgod.R129_CustomPresetDir = PRESET_DIR
    driftgod.R110_CustomPresetDir = PRESET_DIR
    driftgod.R109_CustomPresetDir = PRESET_DIR

    local function ensureDir()
        driftgod.Try(function()
            if FileMgr and FileMgr.CreateDir then
                FileMgr.CreateDir(ROOT .. "\\Lua\\DriftGod")
                FileMgr.CreateDir(ROOT .. "\\Lua\\DriftGod\\storage")
                FileMgr.CreateDir(PRESET_DIR)
            end
        end)
    end

    local function safeName(name)
        name = tostring(name or "CustomPreset")
        name = name:gsub("[\\/:%*%?\"<>|]", "_")
        name = name:gsub("%s+", "_")
        name = name:gsub("_+", "_")
        name = name:gsub("^_+", ""):gsub("_+$", "")
        if name == "" then name = "CustomPreset" end
        return name
    end

    local function pathFor(name)
        return PRESET_DIR .. safeName(name) .. ".lua"
    end

    local function fileNameFromPath(p)
        local n = tostring(p or ""):match("([^\\/]+)%.lua$")
        if n then return safeName(n) end
        n = tostring(p or ""):gsub("%.lua$", "")
        if n ~= "" and not n:find("[\\/]", 1, false) then return safeName(n) end
        return nil
    end

    local function writeText(path, txt)
        local ok = false
        driftgod.Try(function()
            if FileMgr and FileMgr.WriteFileContent then ok = FileMgr.WriteFileContent(path, tostring(txt or ""), false) end
        end)
        if ok then return true end
        driftgod.Try(function()
            local f = io and io.open and io.open(path, "w")
            if f then f:write(tostring(txt or "")); f:close(); ok = true end
        end)
        return ok == true
    end

    local function readText(path)
        local ok, txt = driftgod.Try(function()
            if FileMgr and FileMgr.ReadFileContent then return FileMgr.ReadFileContent(path) end
            return nil
        end)
        if ok and type(txt) == "string" and txt ~= "" then return txt end
        ok, txt = driftgod.Try(function()
            local f = io and io.open and io.open(path, "r")
            if not f then return nil end
            local s = f:read("*a")
            f:close()
            return s
        end)
        if ok and type(txt) == "string" and txt ~= "" then return txt end
        return nil
    end

    local function loadPresetTable(name)
        local full = pathFor(name)
        local ok, tbl = driftgod.Try(function() return dofile(full) end)
        if ok and type(tbl) == "table" then return tbl end

        local txt = readText(full)
        if type(txt) == "string" and txt ~= "" then
            ok, tbl = driftgod.Try(function()
                local loader = load or loadstring
                if not loader then return nil end
                local chunk = loader(txt)
                if chunk then return chunk() end
                return nil
            end)
            if ok and type(tbl) == "table" then return tbl end
        end
        return nil
    end

    local function listPresetNames()
        ensureDir()
        local names, seen = {}, {}

        local function add(raw)
            local n = fileNameFromPath(raw)
            if n and n ~= "_preset_index" and not seen[n] then
                seen[n] = true
                names[#names + 1] = n
            end
        end

        driftgod.Try(function()
            if FileMgr and FileMgr.FindFiles then
                local tries = {
                    function() return FileMgr.FindFiles(PRESET_DIR, "lua", false) end,
                    function() return FileMgr.FindFiles(PRESET_DIR, ".lua", false) end,
                    function() return FileMgr.FindFiles(PRESET_DIR, "*.lua", false) end,
                    function() return FileMgr.FindFiles(PRESET_DIR, "lua") end,
                    function() return FileMgr.FindFiles(PRESET_DIR, ".lua") end,
                    function() return FileMgr.FindFiles(PRESET_DIR, "*.lua") end,
                }
                for _, fn in ipairs(tries) do
                    local ok, files = driftgod.Try(fn)
                    if ok and type(files) == "table" then
                        for _, f in ipairs(files) do add(f) end
                    end
                    if #names > 0 then break end
                end
            end
        end)

        if #names <= 0 then
            driftgod.Try(function()
                if io and io.popen then
                    local p = io.popen('dir /b /a-d "' .. tostring(PRESET_DIR) .. '*.lua" 2>nul')
                    if p then
                        for line in p:lines() do add(line) end
                        p:close()
                    end
                end
            end)
        end

        for _, n in ipairs(driftgod.S.r206SavedPresetNames or {}) do add(n) end
        for _, n in ipairs(driftgod.S.r205SavedPresetNames or {}) do add(n) end
        for _, n in ipairs(driftgod.S.r203SavedPresetNames or {}) do add(n) end

        table.sort(names, function(a, b)
            local ta, tb = loadPresetTable(a), loadPresetTable(b)
            local aa = tonumber(ta and ta.saved_at or 0) or 0
            local bb = tonumber(tb and tb.saved_at or 0) or 0
            if aa == bb then return tostring(a) < tostring(b) end
            return aa > bb
        end)

        driftgod.S.customPresetList = names
        if #names > 0 then
            driftgod.S.customPresetIndex = math.max(1, math.min(tonumber(driftgod.S.customPresetIndex or 1) or 1, #names))
        else
            driftgod.S.customPresetIndex = 1
        end
        return names
    end

    function driftgod.R206_ScanCustomPresets()
        return listPresetNames()
    end

    function driftgod.R206_RecentCustomPresets(limit)
        local all = driftgod.R206_ScanCustomPresets()
        local out = {}
        limit = tonumber(limit or 3) or 3
        for i = 1, math.min(limit, #all) do out[#out + 1] = all[i] end
        return out
    end

    local SaveKeys = {
        "customPresetName",
        "base_preset", "source_preset",
        "r195BaseTuningPreset", "r198BaseTuningPreset", "activeArcadeDriftPreset",
        "arcadePresetRuntimeAssist", "arcadePresetRuntimeEnabled",
        "driftAssistEnabled", "driftTuningEnabled", "driftTuningDriftEnabled",
        "stabilityAssistEnabled", "autoCounterSteerEnabled",
        "momentumAssistEnabled", "accelAssistEnabled",
        "experimentalGravityEnabled", "experimentalAccelEnabled", "experimentalTractionEnabled", "experimentalGripEnabled",
        "driftGripLevel", "driftStabilityLevel", "stabilityLevel",
        "autoCounterSteerLevel", "counterSteerLevel",
        "momentumStrength", "momentumLevel",
        "accelStrength", "accelerationLevel",
        "experimentalGravityStrength", "experimentalAccelStrength",
        "experimentalTractionLevel", "experimentalGripLevel"
    }

    local function serialize(tbl)
        local out = { "return {" }
        for _, k in ipairs(SaveKeys) do
            local v = tbl[k]
            if type(v) == "number" or type(v) == "boolean" then
                out[#out + 1] = "  " .. k .. " = " .. tostring(v) .. ","
            elseif type(v) == "string" then
                out[#out + 1] = "  " .. k .. " = " .. string.format("%q", v) .. ","
            end
        end
        out[#out + 1] = "  preset_schema = \"DriftGodCustomPreset_R206\","
        out[#out + 1] = "  saved_at = " .. tostring(tbl.saved_at or (os.time and os.time() or math.floor((os.clock() or 0) * 1000))) .. ","
        out[#out + 1] = "  is_custom_preset = true,"
        out[#out + 1] = "}"
        return table.concat(out, "\n")
    end

    local function builtinSet()
        local set = {}
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            set[safeName(p.id or "")] = true
            set[safeName(p.name or "")] = true
        end
        return set
    end

    local function uniqueName(requested)
        local base = safeName(requested or driftgod.S.customPresetName or "CustomPreset")
        local builtins = builtinSet()
        local existing = {}
        for _, n in ipairs(listPresetNames()) do existing[safeName(n)] = true end
        if not builtins[base] and not existing[base] then return base end
        local i = 2
        while true do
            local c = base .. "_" .. tostring(i)
            if not builtins[c] and not existing[c] then return c end
            i = i + 1
        end
    end

    function driftgod.R206_SaveCustomPreset()
        ensureDir()
        driftgod.S = driftgod.S or {}

        if driftgod.R202_CaptureTuningFeatureState then driftgod.Try(driftgod.R202_CaptureTuningFeatureState) end

        local base = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.r198BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or "")
        local name = uniqueName(driftgod.S.customPresetName or "CustomPreset")

        local tbl = {
            customPresetName = name,
            base_preset = base,
            source_preset = base,
            r195BaseTuningPreset = base,
            r198BaseTuningPreset = base,
            activeArcadeDriftPreset = base,
            saved_at = os.time and os.time() or math.floor((os.clock() or 0) * 1000)
        }

        for _, k in ipairs(SaveKeys) do
            if driftgod.S[k] ~= nil then tbl[k] = driftgod.S[k] end
        end

        tbl.customPresetName = name
        tbl.base_preset = base
        tbl.source_preset = base
        tbl.r195BaseTuningPreset = base
        tbl.r198BaseTuningPreset = base
        tbl.activeArcadeDriftPreset = base

        local ok = writeText(pathFor(name), serialize(tbl))

        local cache = { name }
        for _, n in ipairs(driftgod.S.r206SavedPresetNames or {}) do
            if tostring(n) ~= tostring(name) then cache[#cache + 1] = tostring(n) end
        end
        driftgod.S.r206SavedPresetNames = cache
        driftgod.S.r205SavedPresetNames = cache
        driftgod.S.r203SavedPresetNames = cache
        driftgod.S.customPresetList = cache
        driftgod.S.customPresetIndex = 1
        driftgod.S.customPresetName = name
        driftgod.S.r206ActiveCustomPreset = name

        listPresetNames()

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast(ok and ("Saved preset: " .. tostring(name)) or "Preset save failed", 2200) end
        log("Saved custom preset: " .. tostring(name) .. " -> storage\\presets")
        return ok
    end

    function driftgod.R206_LoadCustomPresetByName(name)
        name = safeName(name)
        local tbl = loadPresetTable(name)
        if type(tbl) ~= "table" then
            if driftgod.Toast then driftgod.Toast("Preset load failed", 2200) end
            return false
        end

        local base = tostring(tbl.base_preset or tbl.r195BaseTuningPreset or tbl.r198BaseTuningPreset or tbl.activeArcadeDriftPreset or "")
        driftgod.S.r202SuppressBasePrefill = true
        if base ~= "" and driftgod.ApplyArcadeDriftPreset then driftgod.Try(function() driftgod.ApplyArcadeDriftPreset(base, false) end) end
        driftgod.S.r202SuppressBasePrefill = false

        for _, k in ipairs(SaveKeys) do
            if tbl[k] ~= nil then driftgod.S[k] = tbl[k] end
        end

        driftgod.S.r195BaseTuningPreset = base ~= "" and base or driftgod.S.r195BaseTuningPreset
        driftgod.S.r198BaseTuningPreset = base ~= "" and base or driftgod.S.r198BaseTuningPreset
        driftgod.S.activeArcadeDriftPreset = base ~= "" and base or driftgod.S.activeArcadeDriftPreset
        driftgod.S.customPresetName = tostring(tbl.customPresetName or name)
        driftgod.S.r206ActiveCustomPreset = name

        if driftgod.R202_ApplyTuningFeatureState then driftgod.Try(function() driftgod.R202_ApplyTuningFeatureState(tbl) end) end

        local list = listPresetNames()
        for i, n in ipairs(list) do
            if tostring(n) == tostring(name) then driftgod.S.customPresetIndex = i; break end
        end

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Applied custom preset: " .. tostring(name), 2200) end
        log("Loaded custom preset: " .. tostring(name))
        return true
    end

    function driftgod.R206_LoadSelectedCustomPreset()
        local list = listPresetNames()
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        local name = list[idx]
        if not name then
            if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end
            return false
        end
        return driftgod.R206_LoadCustomPresetByName(name)
    end

    function driftgod.R206_DeleteSelectedCustomPreset()
        local list = listPresetNames()
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        local name = list[idx]
        if not name then
            if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end
            return false
        end
        driftgod.Try(function()
            if FileMgr and FileMgr.DeleteFile then FileMgr.DeleteFile(pathFor(name))
            elseif os and os.remove then os.remove(pathFor(name)) end
        end)
        driftgod.S.r206SavedPresetNames = {}
        driftgod.S.r205SavedPresetNames = {}
        driftgod.S.r203SavedPresetNames = {}
        listPresetNames()
        driftgod.S.customPresetIndex = 1
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Deleted preset: " .. tostring(name), 2200) end
        return true
    end

