    function driftgod.R210_RenderPresetCreation()
        if beginChild("Preset Creation") then
            text("Preset Creation", "header")
            text("Save the current base preset, toggles, and tuning values.", "dim")

            driftgod.S.customPresetName = tostring(driftgod.S.customPresetName or "CustomPreset")
            if ImGui and ImGui.InputText then
                local ok, value = driftgod.Try(function()
                    return ImGui.InputText("Preset Name##R210", driftgod.S.customPresetName, 64)
                end)
                if ok then
                    if type(value) == "string" then driftgod.S.customPresetName = value
                    elseif type(value) == "table" and value[1] then driftgod.S.customPresetName = tostring(value[1]) end
                end
            else
                text("Preset Name: " .. tostring(driftgod.S.customPresetName), "white")
            end

            colorButton("Save Current Tuning##R210", "green", driftgod.R210_SaveCustomPreset)
            sameLine()
            colorButton("Refresh##R210", "blue", driftgod.R210_ScanCustomPresets)

            local list = driftgod.R210_ScanCustomPresets()
            local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
            if #list > 0 then
                if idx < 1 then idx = 1 end
                if idx > #list then idx = #list end
                driftgod.S.customPresetIndex = idx
            end

            local preview = list[idx] or "No custom presets"
            if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
                local open = false
                driftgod.Try(function() open = ImGui.BeginCombo("Custom Preset##R210Combo", tostring(preview)) end)
                if open then
                    for i, name in ipairs(list) do
                        local clicked = false
                        driftgod.Try(function() clicked = ImGui.Selectable(tostring(name) .. "##R210Preset_" .. tostring(i), i == idx) end)
                        if clicked then
                            driftgod.S.customPresetIndex = i
                            driftgod.S.r210SelectedCustomPresetName = name
                        end
                    end
                    driftgod.Try(ImGui.EndCombo)
                end
            else
                text("Selected: " .. tostring(preview), "white")
            end

            colorButton("Apply##R210", "purple", driftgod.R210_LoadSelectedCustomPreset)
            sameLine()
            colorButton("Delete##R210", "red", driftgod.R210_DeleteSelectedCustomPreset)
            endChild()
        end
    end

    local function renderFamily(family)
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
