    function driftgod.R210_RenderPresetColumns(id)
        local groups = {
            {label="Default / Starter", families={"Default / Starter", "Open"}},
            {label="Wide Road", families={"Wide / Open Roads"}},
            {label="Technical", families={"Technical / Windy Roads"}},
            {label="Custom", custom=true},
        }

        if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex and ImGui.BeginTable(id or "DG_R210_PresetColumns", 4, dgSafeTableFlags and dgSafeTableFlags() or 0) then
            ImGui.TableNextRow()
            for i, g in ipairs(groups) do
                ImGui.TableSetColumnIndex(i - 1)
                text(g.label, "header")
            end
            ImGui.TableNextRow()
            for i, g in ipairs(groups) do
                ImGui.TableSetColumnIndex(i - 1)
                if g.custom then
                    renderCustomRecent()
                else
                    for _, fam in ipairs(g.families or {}) do renderFamily(fam) end
                end
