    local function ctext(msg, color)
        local s = tostring(msg or "")
        local c = tostring(color or "white")
        local map = {
            header={0.72,0.42,1.00,1.00}, purple={0.72,0.42,1.00,1.00}, active={0.72,0.42,1.00,1.00},
            green={0.30,1.00,0.45,1.00}, red={1.00,0.30,0.34,1.00}, yellow={1.00,0.86,0.25,1.00},
            gold={1.00,0.72,0.18,1.00}, cyan={0.35,0.86,1.00,1.00}, blue={0.45,0.65,1.00,1.00},
            dim={0.62,0.62,0.68,1.00}, white={1.00,1.00,1.00,1.00}
        }
        local rgba = map[c] or map.white
        if ImGui and ImGui.TextColored then driftgod.Try(function() ImGui.TextColored(rgba[1], rgba[2], rgba[3], rgba[4], s) end)
        elseif dgA38Text then dgA38Text(s, c)
        elseif ImGui and ImGui.Text then ImGui.Text(s) end
    end

    local function sameLine()
        if R110SameLine then R110SameLine()
        elseif ImGui and ImGui.SameLine then ImGui.SameLine() end
    end

    local function colorButton(label, color, cb)
        local pushed = 0
        if ImGui and ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Button then
            local r,g,b = 0.22,0.22,0.26
            local hr,hg,hb = 0.30,0.30,0.36
            local ar,ag,ab = 0.38,0.38,0.44
            if color == "purple" then r,g,b=0.45,0.18,0.85; hr,hg,hb=0.58,0.30,1.00; ar,ag,ab=0.35,0.12,0.70 end
            if color == "green" then r,g,b=0.06,0.35,0.14; hr,hg,hb=0.08,0.48,0.20; ar,ag,ab=0.10,0.62,0.26 end
            if color == "blue" then r,g,b=0.06,0.20,0.50; hr,hg,hb=0.09,0.30,0.68; ar,ag,ab=0.12,0.38,0.85 end
            if color == "red" then r,g,b=0.45,0.06,0.08; hr,hg,hb=0.62,0.10,0.12; ar,ag,ab=0.78,0.14,0.16 end
            driftgod.Try(function()
                ImGui.PushStyleColor(ImGuiCol.Button, r,g,b,0.94)
                ImGui.PushStyleColor(ImGuiCol.ButtonHovered, hr,hg,hb,0.98)
                ImGui.PushStyleColor(ImGuiCol.ButtonActive, ar,ag,ab,1.00)
            end)
            pushed = 3
        end
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) == true end) end
        if pushed > 0 and ImGui and ImGui.PopStyleColor then driftgod.Try(ImGui.PopStyleColor, pushed) end
        if clicked and cb then driftgod.Try(cb) end
        return clicked
    end

    function driftgod.R211_RenderPresetColumns(id)
        local groups = {
            {label="Default / Starter", families={"Default / Starter", "Open"}},
            {label="Wide Road", families={"Wide / Open Roads"}},
            {label="Technical", families={"Technical / Windy Roads"}},
            {label="Custom", custom=true},
        }

        local function renderFamily(fam)
            for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
                if tostring(p.family or "") == tostring(fam or "") then
                    ctext(tostring(p.name or p.id or "Preset"), "cyan")
                    colorButton("Apply##R211_Base_" .. tostring(p.id or p.name), "purple", function()
                        if driftgod.ApplyArcadeDriftPreset then driftgod.ApplyArcadeDriftPreset(p.id, true) end
                    end)
                end
            end
        end

        local function renderCustom()
            local list = driftgod.R211_RecentCustomPresets(3)
            if #list <= 0 then
                ctext("No custom presets yet.", "red")
                ctext("Debug: scanning DriftGod\\storage\\presets\\", "yellow")
                ctext("Root: " .. tostring(driftgod.S.r211PresetDebugRoot or ROOT), "dim")
                ctext("Active dir: " .. tostring(driftgod.S.r211LastPresetDir or primaryDir()), "dim")
                if type(driftgod.S.r211PresetDebugDirs) == "table" then
                    for i, line in ipairs(driftgod.S.r211PresetDebugDirs) do
                        if i <= 4 then ctext(tostring(line), "dim") end
                    end
                end
                return
            end
            for _, name in ipairs(list) do
                ctext(tostring(name), "purple")
                colorButton("Apply##R211_Custom_" .. tostring(name), "purple", function()
                    driftgod.R211_LoadCustomPresetByName(name)
                end)
            end
        end

        if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex and ImGui.BeginTable(id or "DG_R211_PresetColumns", 4, dgSafeTableFlags and dgSafeTableFlags() or 0) then
            ImGui.TableNextRow()
            for i, g in ipairs(groups) do ImGui.TableSetColumnIndex(i - 1); ctext(g.label, g.custom and "green" or "header") end
            ImGui.TableNextRow()
            for i, g in ipairs(groups) do
                ImGui.TableSetColumnIndex(i - 1)
                if g.custom then renderCustom()
                else for _, fam in ipairs(g.families or {}) do renderFamily(fam) end end
            end
            ImGui.EndTable()
        else
            for _, g in ipairs(groups) do
                ctext(g.label, g.custom and "green" or "header")
                if g.custom then renderCustom()
                else for _, fam in ipairs(g.families or {}) do renderFamily(fam) end end
            end
        end
    end

    function driftgod.R211_RenderPresetCreation()
        local beginOk = true
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, r = driftgod.Try(function() return ClickGUI.BeginCustomChildWindow("Preset Creation") end)
            beginOk = ok and r
        end
        if beginOk then
            ctext("Preset Creation", "header")
            ctext("Save current base preset, toggles, and tuning values.", "dim")

            driftgod.S.customPresetName = tostring(driftgod.S.customPresetName or "CustomPreset")
            if ImGui and ImGui.InputText then
                local ok, value = driftgod.Try(function() return ImGui.InputText("Preset Name##R211", driftgod.S.customPresetName, 64) end)
                if ok then
                    if type(value) == "string" then driftgod.S.customPresetName = value
                    elseif type(value) == "table" and value[1] then driftgod.S.customPresetName = tostring(value[1]) end
                end
            else
                ctext("Preset Name: " .. tostring(driftgod.S.customPresetName), "white")
            end

            colorButton("Save Current Tuning##R211", "green", driftgod.R211_SaveCustomPreset)
            sameLine()
            colorButton("Refresh / Debug Scan##R211", "blue", function() driftgod.R211_ScanCustomPresets(true) end)

            local list = driftgod.R211_ScanCustomPresets(false)
            local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
            if #list > 0 then
                if idx < 1 then idx = 1 end
                if idx > #list then idx = #list end
                driftgod.S.customPresetIndex = idx
            end

            local preview = list[idx] or "No custom presets"
            if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
                local open = false
                driftgod.Try(function() open = ImGui.BeginCombo("Custom Preset##R211Combo", tostring(preview)) end)
                if open then
                    for i, name in ipairs(list) do
                        local clicked = false
                        driftgod.Try(function() clicked = ImGui.Selectable(tostring(name) .. "##R211Preset_" .. tostring(i), i == idx) end)
                        if clicked then
                            driftgod.S.customPresetIndex = i
                            driftgod.S.r211SelectedCustomPresetName = name
                        end
                    end
                    driftgod.Try(ImGui.EndCombo)
                end
            else
                ctext("Selected: " .. tostring(preview), "white")
            end

            colorButton("Apply##R211", "purple", driftgod.R211_LoadSelectedCustomPreset)
            sameLine()
            colorButton("Delete##R211", "red", driftgod.R211_DeleteSelectedCustomPreset)

            ctext("Debug count: " .. tostring(driftgod.S.r211PresetDebugCount or 0), "yellow")
            ctext("Active dir: " .. tostring(driftgod.S.r211LastPresetDir or primaryDir()), "dim")

            if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
        end
    end

    driftgod.R109_RenderPresetCreation = driftgod.R211_RenderPresetCreation
    driftgod.R110_RenderPresetCreation = driftgod.R211_RenderPresetCreation
    driftgod.R205_RenderPresetCreation = driftgod.R211_RenderPresetCreation
