    driftgod.R206_RenderPresetColumns = driftgod.R211_RenderPresetColumns
    driftgod.R209_RenderPresetColumns = driftgod.R211_RenderPresetColumns
    driftgod.R210_RenderPresetColumns = driftgod.R211_RenderPresetColumns

    local previousDrift = renderDriftMinimal
    renderDriftMinimal = function()
        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Presets") then
            driftgod.R211_RenderPresetColumns("DG_R211_DriftPresetColumns")
            driftgod.Try(ClickGUI.EndCustomChildWindow)
        elseif previousDrift then
            previousDrift()
            return
        end

        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Drift Tuning") then
            if R123RenderTuningGrid then R123RenderTuningGrid() end
            driftgod.Try(ClickGUI.EndCustomChildWindow)
        end

        driftgod.R211_RenderPresetCreation()
    end

    driftgod.Try(function() driftgod.R211_ScanCustomPresets(true) end)
    dbg("R211 loaded. Custom preset debug enabled. If count is 0, send scan logs.", true)
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"
    driftgod.S.customPresetDebugEnabled = false

    local INDEX_FILE = "_presets_index.json"

    local function ms()
        return driftgod.Now and driftgod.Now() or math.floor((os.clock() or 0) * 1000)
    end

    local function stamp()
        return os.time and os.time() or ms()
    end

    local function dbg(msg, force)
        if not (driftgod.S and driftgod.S.customPresetDebugEnabled == true) then return end
        local n = ms()
        if not force and n < tonumber(driftgod.S.r212NextPresetDebugLog or 0) then return end
        driftgod.S.r212NextPresetDebugLog = n + 3000
        if driftgod.Log then driftgod.Log("[CustomPresetDebug] " .. tostring(msg or "")) end
    end

    local function root()
        local r = "."
        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then r = FileMgr.GetMenuRootPath() or "." end
        end)
        if r == nil or r == "" then r = "." end
        return tostring(r):gsub("/", "\\"):gsub("\\+$", "")
    end

    local ROOT = root()
    local PRESET_DIR = ROOT .. "\\Lua\\DriftGod\\storage\\presets\\"

    local function slash(dir)
        dir = tostring(dir or ""):gsub("/", "\\")
        if dir ~= "" and dir:sub(-1) ~= "\\" then dir = dir .. "\\" end
        return dir
    end

    PRESET_DIR = slash(PRESET_DIR)

    local function addDir(out, seen, dir)
        dir = slash(dir)
        if dir == "" then return end
        local k = dir:lower()
        if not seen[k] then
            seen[k] = true
            out[#out + 1] = dir
        end
    end

    local function candidateDirs()
        return { PRESET_DIR }
    end

    local function ensureDir(dir)
        dir = slash(dir or PRESET_DIR)
        driftgod.Try(function()
            if FileMgr and FileMgr.CreateDir then
                FileMgr.CreateDir(ROOT .. "\\Lua\\DriftGod")
                FileMgr.CreateDir(ROOT .. "\\Lua\\DriftGod\\storage")
                FileMgr.CreateDir(dir)
            end
        end)
    end

    local function safeName(name)
        name = tostring(name or "CustomPreset")
        name = name:gsub("[\\/:%*%?\"<>|]", "_")
        name = name:gsub("%s+", "_")
        name = name:gsub("_+", "_")
        name = name:gsub("^_+", ""):gsub("_+$", "")
        if name == "" then name = "CustomPreset" end
        return name
    end

    local function fileName(raw)
        local s = tostring(raw or ""):gsub("/", "\\")
        local n = s:match("([^\\]+)%.json$")
        if n then return safeName(n), "json" end
        n = s:match("([^\\]+)%.lua$")
        if n then return safeName(n), "lua" end
        n = s:gsub("%.json$", ""):gsub("%.lua$", "")
        if n ~= "" and not n:find("\\", 1, true) then return safeName(n), nil end
        return nil, nil
    end

    local function pathFor(dir, name, ext)
        return slash(dir or PRESET_DIR) .. safeName(name) .. "." .. tostring(ext or "json"):gsub("^%.", "")
    end

    local function indexPath(dir)
        return slash(dir or PRESET_DIR) .. INDEX_FILE
    end

    local function readText(path)
        local ok, txt = driftgod.Try(function()
            if FileMgr and FileMgr.ReadFileContent then return FileMgr.ReadFileContent(path) end
            return nil
        end)
        if ok and type(txt) == "string" and txt ~= "" then return txt end

        ok, txt = driftgod.Try(function()
            local f = io and io.open and io.open(path, "r")
            if not f then return nil end
            local s = f:read("*a")
            f:close()
            return s
        end)
        if ok and type(txt) == "string" and txt ~= "" then return txt end
        return nil
    end

    local function writeText(path, txt)
        local ok = false
        driftgod.Try(function()
            if FileMgr and FileMgr.WriteFileContent then
                ok = FileMgr.WriteFileContent(path, tostring(txt or ""), false)
            end
        end)
        if ok then return true end

        driftgod.Try(function()
            local f = io and io.open and io.open(path, "w")
            if f then f:write(tostring(txt or "")); f:close(); ok = true end
        end)
        return ok == true
    end

    local function esc(s)
        s = tostring(s or "")
        s = s:gsub("\\", "\\\\"):gsub('"', '\\"'):gsub("\r", "\\r"):gsub("\n", "\\n")
        return s
    end

    local function unesc(s)
        s = tostring(s or "")
        s = s:gsub('\\"', '"'):gsub("\\n", "\n"):gsub("\\r", "\r"):gsub("\\\\", "\\")
        return s
    end

    local function jsonValue(v)
        if type(v) == "boolean" then return v and "true" or "false" end
        if type(v) == "number" then return tostring(v) end
        if v == nil then return "null" end
        return '"' .. esc(v) .. '"'
    end

    local SaveKeys = {
        "customPresetName",
        "base_preset", "source_preset",
        "r195BaseTuningPreset", "r198BaseTuningPreset", "activeArcadeDriftPreset",
        "arcadePresetRuntimeAssist", "arcadePresetRuntimeEnabled",
        "driftAssistEnabled", "driftTuningEnabled", "driftTuningDriftEnabled",
        "stabilityAssistEnabled", "autoCounterSteerEnabled",
        "momentumAssistEnabled", "accelAssistEnabled",
        "experimentalGravityEnabled", "experimentalAccelEnabled", "experimentalTractionEnabled", "experimentalGripEnabled",
        "driftGripLevel", "driftStabilityLevel", "stabilityLevel",
        "autoCounterSteerLevel", "counterSteerLevel",
        "momentumStrength", "momentumLevel",
        "accelStrength", "accelerationLevel",
        "experimentalGravityStrength", "experimentalAccelStrength",
        "experimentalTractionLevel", "experimentalGripLevel"
    }

    local function encodePreset(tbl)
        local out = { "{", '  "preset_schema": "DriftGodCustomPreset_R212",' }
        for _, k in ipairs(SaveKeys) do
            local v = tbl[k]
            if v ~= nil then out[#out + 1] = '  "' .. tostring(k) .. '": ' .. jsonValue(v) .. "," end
        end
        out[#out + 1] = '  "saved_at": ' .. tostring(tonumber(tbl.saved_at or stamp()) or stamp()) .. ","
        out[#out + 1] = '  "is_custom_preset": true'
        out[#out + 1] = "}"
        return table.concat(out, "\n")
    end

    local function parseFlatJson(txt)
        txt = tostring(txt or "")
        local t = {}
        for key, raw in txt:gmatch('"%s*([^"]-)%s*"%s*:%s*([^,%}%]]+)') do
            raw = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
            local str = raw:match('^"(.-)"$')
            if str ~= nil then
                t[key] = unesc(str)
            elseif raw == "true" then
                t[key] = true
            elseif raw == "false" then
                t[key] = false
            elseif raw == "null" then
                t[key] = nil
            else
                local n = tonumber(raw)
                if n ~= nil then t[key] = n else t[key] = raw end
            end
        end
        return t
    end

    local function encodeIndex(entries)
        table.sort(entries, function(a, b)
            local aa = tonumber(a.saved_at or 0) or 0
            local bb = tonumber(b.saved_at or 0) or 0
            if aa == bb then return tostring(a.name or "") < tostring(b.name or "") end
            return aa > bb
        end)
        local out = {
            "{",
            '  "schema": "DriftGodPresetIndex_R212",',
            '  "updated_at": ' .. tostring(stamp()) .. ",",
            '  "presets": ['
        }
        for i, e in ipairs(entries or {}) do
            out[#out + 1] =
                '    {"name": "' .. esc(e.name or "") ..
                '", "file": "' .. esc(e.file or (safeName(e.name) .. ".json")) ..
                '", "base": "' .. esc(e.base or "") ..
                '", "saved_at": ' .. tostring(tonumber(e.saved_at or 0) or 0) .. "}" .. (i < #entries and "," or "")
        end
        out[#out + 1] = "  ]"
        out[#out + 1] = "}"
        return table.concat(out, "\n")
    end

    local function parseIndex(txt)
        txt = tostring(txt or "")
        local out, seen = {}, {}
        local arr = txt:match('%"presets%"%s*:%s*%[(.*)%]') or txt
        for block in arr:gmatch("%{(.-)%}") do
            local name = block:match('%"name%"%s*:%s*%"(.-)%"')
            if name and name ~= "" then
                local clean = safeName(unesc(name))
                if not seen[clean] then
                    seen[clean] = true
                    local file = unesc(block:match('%"file%"%s*:%s*%"(.-)%"') or (clean .. ".json"))
                    local base = unesc(block:match('%"base%"%s*:%s*%"(.-)%"') or "")
                    local saved = tonumber(block:match('%"saved_at%"%s*:%s*([%d%.%-]+)') or 0) or 0
                    out[#out + 1] = { name = clean, file = file, base = base, saved_at = saved }
                end
            end
        end
        table.sort(out, function(a, b)
            if tonumber(a.saved_at or 0) == tonumber(b.saved_at or 0) then return tostring(a.name) < tostring(b.name) end
            return tonumber(a.saved_at or 0) > tonumber(b.saved_at or 0)
        end)
        return out
    end

    local function writeIndex(dir, entries)
        ensureDir(dir)
        return writeText(indexPath(dir), encodeIndex(entries or {}))
    end

    local function readIndex(dir)
        local txt = readText(indexPath(dir))
        if not txt then return {} end
        return parseIndex(txt)
    end

    local function loadLegacyLua(full)
        local ok, tbl = driftgod.Try(function() return dofile(full) end)
        if ok and type(tbl) == "table" then return tbl end
        return nil
    end

    local function loadPresetFromDir(dir, name)
        local jsonPath = pathFor(dir, name, "json")
        local txt = readText(jsonPath)
        if txt then
            local t = parseFlatJson(txt)
            if next(t) then return t, jsonPath, "json" end
        end

        local luaPath = pathFor(dir, name, "lua")
        local tbl = loadLegacyLua(luaPath)
        if type(tbl) == "table" then return tbl, luaPath, "lua" end

        return nil, nil, nil
    end

    local function loadPreset(name)
        name = safeName(name)
        for _, dir in ipairs(candidateDirs()) do
            local tbl, path, ext = loadPresetFromDir(dir, name)
            if tbl then
                driftgod.S.r212LastPresetDir = dir
                return tbl, path, ext
            end
        end
        return nil, nil, nil
    end

    local function scannerFiles(dir)
        ensureDir(dir)
        local out, seen = {}, {}
        local function add(raw)
            local n, ext = fileName(raw)
            if n and n ~= "_presets_index" and n ~= "_preset_index" and not seen[n .. tostring(ext or "")] then
                seen[n .. tostring(ext or "")] = true
                out[#out + 1] = { name = n, ext = ext or "json", raw = tostring(raw or "") }
            end
        end

        if driftgod.VS_FindFiles then
            local ok, files = driftgod.Try(function() return driftgod.VS_FindFiles(dir, { "json", "lua" }) end)
            if ok and type(files) == "table" then
                for _, f in ipairs(files) do add(f) end
            end
        end

        if #out <= 0 and FileMgr and FileMgr.FindFiles then
            for _, ext in ipairs({ "json", ".json", "lua", ".lua" }) do
                for _, rec in ipairs({ true, false }) do
                    local ok, files = driftgod.Try(function() return FileMgr.FindFiles(dir, ext, rec) end)
                    if ok and type(files) == "table" then
                        for _, f in ipairs(files) do add(f) end
                    end
                    if #out > 0 then break end
                end
                if #out > 0 then break end
            end
        end

        return out
    end

    function driftgod.R212_RebuildPresetIndex(forceDebug)
        local total = 0
        local notes = {}

        for _, dir in ipairs(candidateDirs()) do
            local entries, seen = {}, {}
            local currentIndex = readIndex(dir)
            for _, e in ipairs(currentIndex) do
                if e.name and e.name ~= "" and not seen[e.name] then
                    seen[e.name] = true
                    entries[#entries + 1] = e
                end
            end

            local files = scannerFiles(dir)
            for _, f in ipairs(files) do
                local name = safeName(f.name)
                if name ~= "" and name ~= "_presets_index" and not seen[name] then
                    local tbl = nil
                    if f.ext == "json" then tbl = parseFlatJson(readText(pathFor(dir, name, "json")) or "") end
                    if not tbl or not next(tbl) then tbl = loadLegacyLua(pathFor(dir, name, "lua")) end
                    local saved = tonumber(tbl and tbl.saved_at or 0) or stamp()
                    local base = tostring(tbl and (tbl.base_preset or tbl.r195BaseTuningPreset or tbl.r198BaseTuningPreset or tbl.activeArcadeDriftPreset) or "")
                    entries[#entries + 1] = { name = name, file = name .. ".json", base = base, saved_at = saved }
                    seen[name] = true
                end
            end

            if #entries > 0 then
                writeIndex(dir, entries)
                total = total + #entries
            end
            notes[#notes + 1] = tostring(dir) .. " entries=" .. tostring(#entries) .. " files=" .. tostring(#files)
        end

        driftgod.S.r212IndexDebugNotes = notes
        if forceDebug == true then
            dbg("R212 rebuild index | totalEntries=" .. tostring(total), true)
            dbg(table.concat(notes, " || "), true)
        end
        return total
    end

    function driftgod.R212_ScanCustomPresets(forceDebug)
        local names, seen, sourceInfo = {}, {}, {}
        local function add(name, source)
            name = safeName(name)
            if name ~= "" and name ~= "_presets_index" and not seen[name] then
                seen[name] = true
                names[#names + 1] = name
                sourceInfo[#sourceInfo + 1] = name .. "@" .. tostring(source or "?")
            end
        end

        for _, dir in ipairs(candidateDirs()) do
            ensureDir(dir)
            local idx = readIndex(dir)
            if #idx > 0 then
                driftgod.S.r212LastPresetDir = dir
                for _, e in ipairs(idx) do add(e.name, "index") end
            end
        end

        if #names <= 0 then
            driftgod.R212_RebuildPresetIndex(forceDebug == true)
            for _, dir in ipairs(candidateDirs()) do
                local idx = readIndex(dir)
                if #idx > 0 then
                    driftgod.S.r212LastPresetDir = dir
                    for _, e in ipairs(idx) do add(e.name, "rebuilt-index") end
                end
            end
        end

        for _, n in ipairs(driftgod.S.r212SavedPresetNames or {}) do add(n, "cache") end
        for _, n in ipairs(driftgod.S.r210SavedPresetNames or {}) do add(n, "cache") end

        table.sort(names, function(a, b)
            local ta = loadPreset(a)
            local tb = loadPreset(b)
            local aa = tonumber(ta and ta.saved_at or 0) or 0
            local bb = tonumber(tb and tb.saved_at or 0) or 0
            if aa == bb then return tostring(a) < tostring(b) end
            return aa > bb
        end)

        driftgod.S.customPresetList = names
        driftgod.S.r212PresetDebugCount = #names
        driftgod.S.r212PresetDebugRoot = ROOT
        driftgod.S.r212PresetDebugSources = sourceInfo

        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        if #names <= 0 then idx = 1
        elseif idx < 1 then idx = 1
        elseif idx > #names then idx = #names end
        driftgod.S.customPresetIndex = idx

        if forceDebug == true or #names <= 0 then
            dbg("R212 scan | root=" .. tostring(ROOT) .. " | found=" .. tostring(#names) .. " | activeDir=" .. tostring(driftgod.S.r212LastPresetDir or PRESET_DIR), true)
            if #sourceInfo > 0 then dbg("R212 sources=" .. table.concat(sourceInfo, ", "), true) end
            if type(driftgod.S.r212IndexDebugNotes) == "table" then dbg("R212 notes=" .. table.concat(driftgod.S.r212IndexDebugNotes, " || "), true) end
        end

        return names
    end

    function driftgod.R212_RecentCustomPresets(limit)
        local all = driftgod.R212_ScanCustomPresets(false)
        local out = {}
        limit = tonumber(limit or 3) or 3
        for i = 1, math.min(limit, #all) do out[#out + 1] = all[i] end
        return out
    end

    local function builtinSet()
        local set = {}
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            set[safeName(p.id or "")] = true
            set[safeName(p.name or "")] = true
        end
        return set
    end

    local function uniqueName(requested)
        local base = safeName(requested or driftgod.S.customPresetName or "CustomPreset")
        local built = builtinSet()
        local existing = {}
        for _, n in ipairs(driftgod.R212_ScanCustomPresets(false)) do existing[safeName(n)] = true end
        if not built[base] and not existing[base] then return base end
        local i = 2
        while true do
            local c = base .. "_" .. tostring(i)
            if not built[c] and not existing[c] then return c end
            i = i + 1
        end
    end

    function driftgod.R212_SaveCustomPreset()
        driftgod.S = driftgod.S or {}
        ensureDir(PRESET_DIR)
        if driftgod.R202_CaptureTuningFeatureState then driftgod.Try(driftgod.R202_CaptureTuningFeatureState) end

        local base = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.r198BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or "")
        local name = uniqueName(driftgod.S.customPresetName or "CustomPreset")
        local saved = stamp()

        local tbl = {
            customPresetName = name,
            base_preset = base,
            source_preset = base,
            r195BaseTuningPreset = base,
            r198BaseTuningPreset = base,
            activeArcadeDriftPreset = base,
            saved_at = saved
        }
        for _, k in ipairs(SaveKeys) do if driftgod.S[k] ~= nil then tbl[k] = driftgod.S[k] end end
        tbl.customPresetName = name
        tbl.base_preset = base
        tbl.source_preset = base
        tbl.r195BaseTuningPreset = base
        tbl.r198BaseTuningPreset = base
        tbl.activeArcadeDriftPreset = base
        tbl.saved_at = saved

        local ok = writeText(pathFor(PRESET_DIR, name, "json"), encodePreset(tbl))

        local idx = readIndex(PRESET_DIR)
        local filtered = { { name = name, file = name .. ".json", base = base, saved_at = saved } }
        for _, e in ipairs(idx) do
            if safeName(e.name) ~= name then filtered[#filtered + 1] = e end
        end
        writeIndex(PRESET_DIR, filtered)

        driftgod.S.r212SavedPresetNames = driftgod.S.r212SavedPresetNames or {}
        table.insert(driftgod.S.r212SavedPresetNames, 1, name)
        driftgod.S.customPresetName = name
        driftgod.S.customPresetIndex = 1
        driftgod.S.r212LastPresetDir = PRESET_DIR
        driftgod.R212_ScanCustomPresets(true)

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast(ok and ("Saved preset: " .. tostring(name)) or "Preset save failed", 2200) end
        dbg("R212 saved json preset | name=" .. tostring(name) .. " | ok=" .. tostring(ok) .. " | path=" .. tostring(pathFor(PRESET_DIR, name, "json")), true)
        return ok
    end

    function driftgod.R212_LoadCustomPresetByName(name)
        name = safeName(name)
        local tbl = loadPreset(name)
        if type(tbl) ~= "table" then
            if driftgod.Toast then driftgod.Toast("Preset load failed", 2200) end
            dbg("R212 load failed | name=" .. tostring(name), true)
            return false
        end

        local base = tostring(tbl.base_preset or tbl.r195BaseTuningPreset or tbl.r198BaseTuningPreset or tbl.activeArcadeDriftPreset or "")
        driftgod.S.r202SuppressBasePrefill = true
        if base ~= "" and driftgod.ApplyArcadeDriftPreset then driftgod.Try(function() driftgod.ApplyArcadeDriftPreset(base, false) end) end
        driftgod.S.r202SuppressBasePrefill = false

        for _, k in ipairs(SaveKeys) do if tbl[k] ~= nil then driftgod.S[k] = tbl[k] end end
        driftgod.S.r195BaseTuningPreset = base ~= "" and base or driftgod.S.r195BaseTuningPreset
        driftgod.S.r198BaseTuningPreset = base ~= "" and base or driftgod.S.r198BaseTuningPreset
        driftgod.S.activeArcadeDriftPreset = base ~= "" and base or driftgod.S.activeArcadeDriftPreset
        driftgod.S.customPresetName = tostring(tbl.customPresetName or name)
        driftgod.S.r212ActiveCustomPreset = name

        if driftgod.R202_ApplyTuningFeatureState then driftgod.Try(function() driftgod.R202_ApplyTuningFeatureState(tbl) end) end

        local list = driftgod.R212_ScanCustomPresets(false)
        for i, n in ipairs(list) do if tostring(n) == tostring(name) then driftgod.S.customPresetIndex = i; break end end

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Applied custom preset: " .. tostring(name), 2200) end
        dbg("R212 loaded preset | name=" .. tostring(name) .. " | base=" .. tostring(base), true)
        return true
    end

    function driftgod.R212_LoadSelectedCustomPreset()
        local list = driftgod.R212_ScanCustomPresets(false)
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        local name = list[idx]
        if not name then
            if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end
            dbg("R212 apply selected failed; list empty", true)
            return false
        end
        return driftgod.R212_LoadCustomPresetByName(name)
    end

    function driftgod.R212_DeleteSelectedCustomPreset()
        local list = driftgod.R212_ScanCustomPresets(false)
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        local name = list[idx]
        if not name then
            if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end
            return false
        end

        for _, dir in ipairs(candidateDirs()) do
            driftgod.Try(function()
                if FileMgr and FileMgr.DeleteFile then
                    FileMgr.DeleteFile(pathFor(dir, name, "json"))
                    FileMgr.DeleteFile(pathFor(dir, name, "lua"))
                elseif os and os.remove then
                    os.remove(pathFor(dir, name, "json"))
                    os.remove(pathFor(dir, name, "lua"))
                end
            end)
            local idxList = readIndex(dir)
            local filtered = {}
            for _, e in ipairs(idxList) do if safeName(e.name) ~= name then filtered[#filtered + 1] = e end end
            writeIndex(dir, filtered)
        end

        driftgod.S.customPresetIndex = 1
        driftgod.R212_ScanCustomPresets(true)
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Deleted preset: " .. tostring(name), 2200) end
        return true
    end

