    local function ctext(msg, color)
        local s = tostring(msg or "")
        local c = tostring(color or "white")
        local map = {
            header={0.72,0.42,1.00,1.00}, purple={0.72,0.42,1.00,1.00}, active={0.72,0.42,1.00,1.00},
            green={0.30,1.00,0.45,1.00}, red={1.00,0.30,0.34,1.00}, yellow={1.00,0.86,0.25,1.00},
            gold={1.00,0.72,0.18,1.00}, cyan={0.35,0.86,1.00,1.00}, blue={0.45,0.65,1.00,1.00},
            dim={0.62,0.62,0.68,1.00}, white={1.00,1.00,1.00,1.00}
        }
        local rgba = map[c] or map.white
        if ImGui and ImGui.TextColored then driftgod.Try(function() ImGui.TextColored(rgba[1], rgba[2], rgba[3], rgba[4], s) end)
        elseif dgA38Text then dgA38Text(s, c)
        elseif ImGui and ImGui.Text then ImGui.Text(s) end
    end

    local function sameLine()
        if R110SameLine then R110SameLine()
        elseif ImGui and ImGui.SameLine then ImGui.SameLine() end
    end

    local function colorButton(label, color, cb)
        local pushed = 0
        if ImGui and ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Button then
            local r,g,b = 0.22,0.22,0.26
            local hr,hg,hb = 0.30,0.30,0.36
            local ar,ag,ab = 0.38,0.38,0.44
            if color == "purple" then r,g,b=0.45,0.18,0.85; hr,hg,hb=0.58,0.30,1.00; ar,ag,ab=0.35,0.12,0.70 end
            if color == "green" then r,g,b=0.06,0.35,0.14; hr,hg,hb=0.08,0.48,0.20; ar,ag,ab=0.10,0.62,0.26 end
            if color == "blue" then r,g,b=0.06,0.20,0.50; hr,hg,hb=0.09,0.30,0.68; ar,ag,ab=0.12,0.38,0.85 end
            if color == "red" then r,g,b=0.45,0.06,0.08; hr,hg,hb=0.62,0.10,0.12; ar,ag,ab=0.78,0.14,0.16 end
            driftgod.Try(function()
                ImGui.PushStyleColor(ImGuiCol.Button, r,g,b,0.94)
                ImGui.PushStyleColor(ImGuiCol.ButtonHovered, hr,hg,hb,0.98)
                ImGui.PushStyleColor(ImGuiCol.ButtonActive, ar,ag,ab,1.00)
            end)
            pushed = 3
        end
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) == true end) end
        if pushed > 0 and ImGui and ImGui.PopStyleColor then driftgod.Try(ImGui.PopStyleColor, pushed) end
        if clicked and cb then driftgod.Try(cb) end
        return clicked
    end

    function driftgod.R212_RenderPresetColumns(id)
        local groups = {
            {label="Default / Starter", families={"Default / Starter", "Open"}},
            {label="Wide Road", families={"Wide / Open Roads"}},
            {label="Technical", families={"Technical / Windy Roads"}},
            {label="Custom", custom=true},
        }

        local function renderFamily(fam)
            for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
                if tostring(p.family or "") == tostring(fam or "") then
                    ctext(tostring(p.name or p.id or "Preset"), "cyan")
                    colorButton("Apply##R212_Base_" .. tostring(p.id or p.name), "purple", function()
                        if driftgod.ApplyArcadeDriftPreset then driftgod.ApplyArcadeDriftPreset(p.id, true) end
                    end)
                end
            end
        end

        local function renderCustom()
            local list = driftgod.R212_RecentCustomPresets(3)
            if #list <= 0 then
                ctext("No custom presets yet.", "red")
                ctext("Index: _presets_index.json not populated yet.", "yellow")
                ctext("Press Rebuild Index / Debug Scan below.", "dim")
                ctext("Active dir: " .. tostring(driftgod.S.r212LastPresetDir or PRESET_DIR), "dim")
                return
            end
            for _, name in ipairs(list) do
                ctext(tostring(name), "purple")
                colorButton("Apply##R212_Custom_" .. tostring(name), "purple", function()
                    driftgod.R212_LoadCustomPresetByName(name)
                end)
            end
        end

        if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex and ImGui.BeginTable(id or "DG_R212_PresetColumns", 4, dgSafeTableFlags and dgSafeTableFlags() or 0) then
            ImGui.TableNextRow()
            for i, g in ipairs(groups) do ImGui.TableSetColumnIndex(i - 1); ctext(g.label, g.custom and "green" or "header") end
            ImGui.TableNextRow()
            for i, g in ipairs(groups) do
                ImGui.TableSetColumnIndex(i - 1)
                if g.custom then renderCustom()
                else for _, fam in ipairs(g.families or {}) do renderFamily(fam) end end
            end
            ImGui.EndTable()
        else
            for _, g in ipairs(groups) do
                ctext(g.label, g.custom and "green" or "header")
                if g.custom then renderCustom()
                else for _, fam in ipairs(g.families or {}) do renderFamily(fam) end end
            end
        end
    end

    function driftgod.R212_RenderPresetCreation()
        local okChild = true
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, r = driftgod.Try(function() return ClickGUI.BeginCustomChildWindow("Preset Creation") end)
            okChild = ok and r
        end
        if okChild then
            ctext("Preset Creation", "header")
            ctext("JSON presets + _presets_index.json", "dim")

            driftgod.S.customPresetName = tostring(driftgod.S.customPresetName or "CustomPreset")
            if ImGui and ImGui.InputText then
                local ok, value = driftgod.Try(function() return ImGui.InputText("Preset Name##R212", driftgod.S.customPresetName, 64) end)
                if ok then
                    if type(value) == "string" then driftgod.S.customPresetName = value
                    elseif type(value) == "table" and value[1] then driftgod.S.customPresetName = tostring(value[1]) end
                end
            else
                ctext("Preset Name: " .. tostring(driftgod.S.customPresetName), "white")
            end

            colorButton("Save Current Tuning##R212", "green", driftgod.R212_SaveCustomPreset)
            sameLine()
            colorButton("Rebuild Index / Debug Scan##R212", "blue", function()
                driftgod.R212_RebuildPresetIndex(true)
                driftgod.R212_ScanCustomPresets(true)
            end)

            local list = driftgod.R212_ScanCustomPresets(false)
            local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
            if #list > 0 then
                if idx < 1 then idx = 1 end
                if idx > #list then idx = #list end
                driftgod.S.customPresetIndex = idx
            end

            local preview = list[idx] or "No custom presets"
            if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
                local open = false
                driftgod.Try(function() open = ImGui.BeginCombo("Custom Preset##R212Combo", tostring(preview)) end)
                if open then
                    for i, name in ipairs(list) do
                        local clicked = false
                        driftgod.Try(function() clicked = ImGui.Selectable(tostring(name) .. "##R212Preset_" .. tostring(i), i == idx) end)
                        if clicked then
                            driftgod.S.customPresetIndex = i
                            driftgod.S.r212SelectedCustomPresetName = name
                        end
                    end
                    driftgod.Try(ImGui.EndCombo)
                end
            else
                ctext("Selected: " .. tostring(preview), "white")
            end

            colorButton("Apply##R212", "purple", driftgod.R212_LoadSelectedCustomPreset)
            sameLine()
            colorButton("Delete##R212", "red", driftgod.R212_DeleteSelectedCustomPreset)

            ctext("Debug count: " .. tostring(driftgod.S.r212PresetDebugCount or 0), "yellow")
            ctext("Active dir: " .. tostring(driftgod.S.r212LastPresetDir or PRESET_DIR), "dim")

            if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
        end
    end

    driftgod.R109_RenderPresetCreation = driftgod.R212_RenderPresetCreation
    driftgod.R110_RenderPresetCreation = driftgod.R212_RenderPresetCreation
    driftgod.R205_RenderPresetCreation = driftgod.R212_RenderPresetCreation
    driftgod.R206_RenderPresetCreation = driftgod.R212_RenderPresetCreation
    driftgod.R209_RenderPresetCreation = driftgod.R212_RenderPresetCreation
    driftgod.R210_RenderPresetCreation = driftgod.R212_RenderPresetCreation
    driftgod.R211_RenderPresetCreation = driftgod.R212_RenderPresetCreation

    driftgod.R110_RenderPresetColumns = driftgod.R212_RenderPresetColumns
    driftgod.R203_RenderPresetColumns = driftgod.R212_RenderPresetColumns
    driftgod.R205_RenderPresetColumns = driftgod.R212_RenderPresetColumns
    driftgod.R206_RenderPresetColumns = driftgod.R212_RenderPresetColumns
    driftgod.R209_RenderPresetColumns = driftgod.R212_RenderPresetColumns
    driftgod.R210_RenderPresetColumns = driftgod.R212_RenderPresetColumns
    driftgod.R211_RenderPresetColumns = driftgod.R212_RenderPresetColumns

    local previousDrift = renderDriftMinimal
    renderDriftMinimal = function()
        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Presets") then
            driftgod.R212_RenderPresetColumns("DG_R212_DriftPresetColumns")
            driftgod.Try(ClickGUI.EndCustomChildWindow)
        elseif previousDrift then
            previousDrift()
            return
        end

        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Drift Tuning") then
            if R123RenderTuningGrid then R123RenderTuningGrid() end
            driftgod.Try(ClickGUI.EndCustomChildWindow)
        end

        driftgod.R212_RenderPresetCreation()
    end

    dbg("R212 JSON index system installed; startup scan deferred to R213.", true)
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"

    local INDEX_FILE = "_presets_index.json"

    local function now()
        return os.time and os.time() or (driftgod.Now and driftgod.Now() or math.floor((os.clock() or 0) * 1000))
    end

    local function log(msg, force)
        if not (driftgod.S and driftgod.S.customPresetDebugEnabled == true) and not force then return end
        if driftgod.Log then driftgod.Log("[CustomPresetDebug] " .. tostring(msg or "")) end
    end

    local function root()
        local r = "."
        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then r = FileMgr.GetMenuRootPath() or "." end
        end)
        if r == nil or r == "" then r = "." end
        return tostring(r):gsub("/", "\\"):gsub("\\+$", "")
    end

    local ROOT = root()
    local PRESET_DIR = ROOT .. "\\Lua\\DriftGod\\storage\\presets\\"

    local function slash(dir)
        dir = tostring(dir or ""):gsub("/", "\\")
        if dir ~= "" and dir:sub(-1) ~= "\\" then dir = dir .. "\\" end
        return dir
    end

    PRESET_DIR = slash(PRESET_DIR)

    local function safeName(name)
        name = tostring(name or "CustomPreset")
        name = name:gsub("[\\/:%*%?\"<>|]", "_")
        name = name:gsub("%s+", "_")
        name = name:gsub("_+", "_")
        name = name:gsub("^_+", ""):gsub("_+$", "")
        if name == "" then name = "CustomPreset" end
        return name
    end

    local function addDir(out, seen, dir)
        dir = slash(dir)
        local k = dir:lower()
        if dir ~= "" and not seen[k] then
            seen[k] = true
            out[#out + 1] = dir
        end
    end

    local function candidateDirs()
        return { PRESET_DIR }
    end

    local function ensureDir(dir)
        dir = slash(dir or PRESET_DIR)
        driftgod.Try(function()
            if FileMgr and FileMgr.CreateDir then
                FileMgr.CreateDir(ROOT .. "\\Lua\\DriftGod")
                FileMgr.CreateDir(ROOT .. "\\Lua\\DriftGod\\storage")
                FileMgr.CreateDir(dir)
            end
        end)
    end

    local function pathFor(dir, name, ext)
        ext = tostring(ext or "json"):gsub("^%.", "")
        return slash(dir or PRESET_DIR) .. safeName(name) .. "." .. ext
    end

    local function indexPath(dir)
        return slash(dir or PRESET_DIR) .. INDEX_FILE
    end

    local function fileExists(path)
        path = tostring(path or "")
        if path == "" then return false end

        local ok, exists = driftgod.Try(function()
            if FileMgr and FileMgr.DoesFileExist then return FileMgr.DoesFileExist(path) end
            return nil
        end)
        if ok and exists ~= nil then return exists == true end

        ok, exists = driftgod.Try(function()
            local f = io and io.open and io.open(path, "r")
            if f then f:close(); return true end
            return false
        end)
        if ok then return exists == true end

        return false
    end

    local function readTextQuiet(path)
        path = tostring(path or "")
        if path == "" then return nil end
        if not fileExists(path) then return nil end

        local ok, txt = driftgod.Try(function()
            local f = io and io.open and io.open(path, "r")
            if f then
                local s = f:read("*a")
                f:close()
                return s
            end
            return nil
        end)
        if ok and type(txt) == "string" and txt ~= "" then return txt end

        ok, txt = driftgod.Try(function()
            if FileMgr and FileMgr.ReadFileContent then return FileMgr.ReadFileContent(path) end
            return nil
        end)
        if ok and type(txt) == "string" and txt ~= "" then return txt end
        return nil
    end

    local function writeText(path, txt)
        path = tostring(path or "")
        local ok = false
        driftgod.Try(function()
            local f = io and io.open and io.open(path, "w")
            if f then f:write(tostring(txt or "")); f:close(); ok = true end
        end)
        if ok then return true end

        driftgod.Try(function()
            if FileMgr and FileMgr.WriteFileContent then
                ok = FileMgr.WriteFileContent(path, tostring(txt or ""), false)
            end
        end)
        return ok == true
    end

    local function fileNameExt(raw)
        local s = tostring(raw or ""):gsub("/", "\\")
        local n = s:match("([^\\]+)%.json$")
        if n then return safeName(n), "json" end
        n = s:match("([^\\]+)%.lua$")
        if n then return safeName(n), "lua" end
        return nil, nil
    end

    local function esc(s)
        s = tostring(s or "")
        s = s:gsub("\\", "\\\\"):gsub('"', '\\"'):gsub("\r", "\\r"):gsub("\n", "\\n")
        return s
    end

    local function unesc(s)
        s = tostring(s or "")
        s = s:gsub("\\n", "\n"):gsub("\\r", "\r"):gsub('\\"', '"'):gsub("\\\\", "\\")
        return s
    end

    local function jsonVal(v)
        if type(v) == "boolean" then return v and "true" or "false" end
        if type(v) == "number" then return tostring(v) end
        if v == nil then return "null" end
        return '"' .. esc(v) .. '"'
    end

    local SaveKeys = {
        "customPresetName",
        "base_preset", "source_preset",
        "r195BaseTuningPreset", "r198BaseTuningPreset", "activeArcadeDriftPreset",
        "arcadePresetRuntimeAssist", "arcadePresetRuntimeEnabled",
        "driftAssistEnabled", "driftTuningEnabled", "driftTuningDriftEnabled",
        "stabilityAssistEnabled", "autoCounterSteerEnabled",
        "momentumAssistEnabled", "accelAssistEnabled",
        "experimentalGravityEnabled", "experimentalAccelEnabled", "experimentalTractionEnabled", "experimentalGripEnabled",
        "driftGripLevel", "driftStabilityLevel", "stabilityLevel",
        "autoCounterSteerLevel", "counterSteerLevel",
        "momentumStrength", "momentumLevel",
        "accelStrength", "accelerationLevel",
        "experimentalGravityStrength", "experimentalAccelStrength",
        "experimentalTractionLevel", "experimentalGripLevel"
    }

    local function encodePreset(tbl)
        local out = { "{", '  "preset_schema": "DriftGodCustomPreset_R213",' }
        for _, k in ipairs(SaveKeys) do
            if tbl[k] ~= nil then out[#out + 1] = '  "' .. k .. '": ' .. jsonVal(tbl[k]) .. "," end
        end
        out[#out + 1] = '  "saved_at": ' .. tostring(tonumber(tbl.saved_at or now()) or now()) .. ","
        out[#out + 1] = '  "is_custom_preset": true'
        out[#out + 1] = "}"
        return table.concat(out, "\n")
    end

    local function parseFlatJson(txt)
        txt = tostring(txt or "")
        local t = {}
        for key, raw in txt:gmatch('"%s*([^"]-)%s*"%s*:%s*([^,%}%]]+)') do
            raw = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
            local str = raw:match('^"(.-)"$')
            if str ~= nil then t[key] = unesc(str)
            elseif raw == "true" then t[key] = true
            elseif raw == "false" then t[key] = false
            elseif raw == "null" then t[key] = nil
            else
                local num = tonumber(raw)
                if num ~= nil then t[key] = num else t[key] = raw end
            end
        end
        return t
    end

    local function parseIndex(txt)
        txt = tostring(txt or "")
        local out, seen = {}, {}
        local arr = txt:match('%"presets%"%s*:%s*%[(.*)%]') or txt
        for block in arr:gmatch("%{(.-)%}") do
            local rawName = block:match('%"name%"%s*:%s*%"(.-)%"')
            if rawName and rawName ~= "" then
                local name = safeName(unesc(rawName))
                if not seen[name] then
                    seen[name] = true
                    local file = unesc(block:match('%"file%"%s*:%s*%"(.-)%"') or (name .. ".json"))
                    local base = unesc(block:match('%"base%"%s*:%s*%"(.-)%"') or "")
                    local saved = tonumber(block:match('%"saved_at%"%s*:%s*([%d%.%-]+)') or 0) or 0
                    local ext = tostring(file):match("%.([%w_]+)$") or "json"
                    out[#out + 1] = { name=name, file=file, ext=ext, base=base, saved_at=saved }
                end
            end
        end
        table.sort(out, function(a,b)
            local aa, bb = tonumber(a.saved_at or 0) or 0, tonumber(b.saved_at or 0) or 0
            if aa == bb then return tostring(a.name) < tostring(b.name) end
            return aa > bb
        end)
        return out
    end

    local function encodeIndex(entries)
        table.sort(entries, function(a,b)
            local aa, bb = tonumber(a.saved_at or 0) or 0, tonumber(b.saved_at or 0) or 0
            if aa == bb then return tostring(a.name) < tostring(b.name) end
            return aa > bb
        end)

        local out = {
            "{",
            '  "schema": "DriftGodPresetIndex_R213",',
            '  "updated_at": ' .. tostring(now()) .. ",",
            '  "presets": ['
        }
        for i, e in ipairs(entries or {}) do
            local file = tostring(e.file or (safeName(e.name) .. ".json"))
            out[#out + 1] =
                '    {"name": "' .. esc(e.name or "") ..
                '", "file": "' .. esc(file) ..
                '", "base": "' .. esc(e.base or "") ..
                '", "saved_at": ' .. tostring(tonumber(e.saved_at or 0) or 0) ..
                "}" .. (i < #entries and "," or "")
        end
        out[#out + 1] = "  ]"
        out[#out + 1] = "}"
        return table.concat(out, "\n")
    end

    local function readIndex(dir)
        local txt = readTextQuiet(indexPath(dir))
        if not txt then return {} end
        return parseIndex(txt)
    end

    local function writeIndex(dir, entries)
        ensureDir(dir)
        return writeText(indexPath(dir), encodeIndex(entries or {}))
    end

    local function loadLua(path)
        if not fileExists(path) then return nil end
        local ok, tbl = driftgod.Try(function() return dofile(path) end)
        if ok and type(tbl) == "table" then return tbl end
        return nil
    end

    local function loadJson(path)
        local txt = readTextQuiet(path)
        if not txt then return nil end
        local tbl = parseFlatJson(txt)
        if type(tbl) == "table" and next(tbl) then return tbl end
        return nil
    end

    local function scanFiles(dir)
        ensureDir(dir)
        local out, seen = {}, {}
        local function add(raw)
            local name, ext = fileNameExt(raw)
            if name and name ~= "_presets_index" and name ~= "_preset_index" then
                local k = (name .. "." .. tostring(ext)):lower()
                if not seen[k] then
                    seen[k] = true
                    out[#out + 1] = { name=name, ext=ext, file=name .. "." .. ext }
                end
            end
        end

        if driftgod.VS_FindFiles then
            local ok, files = driftgod.Try(function() return driftgod.VS_FindFiles(dir, { "json", "lua" }) end)
            if ok and type(files) == "table" then for _, f in ipairs(files) do add(f) end end
        end

        if #out <= 0 and FileMgr and FileMgr.FindFiles then
            for _, ext in ipairs({ "json", ".json", "lua", ".lua" }) do
                local ok, files = driftgod.Try(function() return FileMgr.FindFiles(dir, ext, true) end)
                if ok and type(files) == "table" then for _, f in ipairs(files) do add(f) end end
                if #out > 0 then break end
            end
        end
        return out
    end

    function driftgod.R213_RebuildPresetIndex(force)
        local total = 0
        local notes = {}
        for _, dir in ipairs(candidateDirs()) do
            local files = scanFiles(dir)
            local entries, seen = {}, {}
            for _, f in ipairs(files) do
                local tbl = nil
                if f.ext == "json" then tbl = loadJson(pathFor(dir, f.name, "json"))
                elseif f.ext == "lua" then tbl = loadLua(pathFor(dir, f.name, "lua")) end

                local saved = tonumber(tbl and tbl.saved_at or 0) or now()
                local base = tostring(tbl and (tbl.base_preset or tbl.r195BaseTuningPreset or tbl.r198BaseTuningPreset or tbl.activeArcadeDriftPreset) or "")
                if not seen[f.name] then
                    seen[f.name] = true
                    entries[#entries + 1] = { name=f.name, file=f.name .. "." .. f.ext, ext=f.ext, base=base, saved_at=saved }
                end
            end

            if #entries > 0 then
                writeIndex(dir, entries)
                total = total + #entries
            else
                local idx = readIndex(dir)
                total = total + #idx
            end

            notes[#notes + 1] = tostring(dir) .. " files=" .. tostring(#files) .. " entries=" .. tostring(#entries)
        end
        driftgod.S.r213IndexDebugNotes = notes
        if force then
            log("R213 rebuilt index | total=" .. tostring(total), true)
            log(table.concat(notes, " || "), true)
        end
        return total
    end

    local function indexEntryFor(name)
        name = safeName(name)
        for _, dir in ipairs(candidateDirs()) do
            local idx = readIndex(dir)
            for _, e in ipairs(idx) do
                if safeName(e.name) == name then
                    local ext = tostring(e.ext or tostring(e.file or ""):match("%.([%w_]+)$") or "json")
                    local file = tostring(e.file or (name .. "." .. ext))
                    driftgod.S.r213LastPresetDir = dir
                    return e, dir, ext, file
                end
            end
        end
        return nil, nil, nil, nil
    end

    local function loadPreset(name)
        name = safeName(name)

        local e, dir, ext, file = indexEntryFor(name)
        if e and dir then
            local full = slash(dir) .. tostring(file or (name .. "." .. tostring(ext or "json")))
            local tbl = nil
            if tostring(ext) == "lua" or tostring(file):lower():match("%.lua$") then tbl = loadLua(full)
            else tbl = loadJson(full) end

            if not tbl then
                local fallbackLua = pathFor(dir, name, "lua")
                tbl = loadLua(fallbackLua)
                if tbl then
                    e.file = name .. ".lua"
                    e.ext = "lua"
                    local idx = readIndex(dir)
                    for _, item in ipairs(idx) do
                        if safeName(item.name) == name then item.file = name .. ".lua"; item.ext = "lua" end
                    end
                    writeIndex(dir, idx)
                end
            end
            if tbl then return tbl, dir end
        end

        for _, d in ipairs(candidateDirs()) do
            local tbl = loadJson(pathFor(d, name, "json"))
            if tbl then driftgod.S.r213LastPresetDir = d; return tbl, d end
            tbl = loadLua(pathFor(d, name, "lua"))
            if tbl then driftgod.S.r213LastPresetDir = d; return tbl, d end
        end

        return nil, nil
    end

    function driftgod.R213_ScanCustomPresets(force)
        local names, seen = {}, {}
        local function add(name)
            name = safeName(name)
            if name ~= "" and not seen[name] then
                seen[name] = true
                names[#names + 1] = name
            end
        end

        for _, dir in ipairs(candidateDirs()) do
            for _, e in ipairs(readIndex(dir)) do add(e.name) end
        end

        if #names <= 0 then
            driftgod.R213_RebuildPresetIndex(force == true)
            for _, dir in ipairs(candidateDirs()) do
                for _, e in ipairs(readIndex(dir)) do add(e.name) end
            end
        end

        for _, n in ipairs(driftgod.S.r213SavedPresetNames or {}) do add(n) end
        for _, n in ipairs(driftgod.S.r212SavedPresetNames or {}) do add(n) end

        table.sort(names, function(a,b)
            local ea = select(1, indexEntryFor(a))
            local eb = select(1, indexEntryFor(b))
            local aa = tonumber(ea and ea.saved_at or 0) or 0
            local bb = tonumber(eb and eb.saved_at or 0) or 0
            if aa == bb then return tostring(a) < tostring(b) end
            return aa > bb
        end)

        driftgod.S.customPresetList = names
        driftgod.S.r213PresetDebugCount = #names
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        if #names <= 0 then idx = 1
        elseif idx < 1 then idx = 1
        elseif idx > #names then idx = #names end
        driftgod.S.customPresetIndex = idx

        if force then
            log("R213 scan | found=" .. tostring(#names) .. " | dir=" .. tostring(driftgod.S.r213LastPresetDir or PRESET_DIR), true)
            log("R213 names=" .. table.concat(names, ", "), true)
        end
        return names
    end

    function driftgod.R213_RecentCustomPresets(limit)
        local all = driftgod.R213_ScanCustomPresets(false)
        local out = {}
        limit = tonumber(limit or 3) or 3
        for i = 1, math.min(limit, #all) do out[#out + 1] = all[i] end
        return out
    end

    local function uniqueName(requested)
        local base = safeName(requested or driftgod.S.customPresetName or "CustomPreset")
        local existing, built = {}, {}
        for _, n in ipairs(driftgod.R213_ScanCustomPresets(false)) do existing[safeName(n)] = true end
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            built[safeName(p.id or "")] = true
            built[safeName(p.name or "")] = true
        end
        if not existing[base] and not built[base] then return base end
        local i = 2
        while true do
            local c = base .. "_" .. tostring(i)
            if not existing[c] and not built[c] then return c end
            i = i + 1
        end
    end

    function driftgod.R213_SaveCustomPreset()
        ensureDir(PRESET_DIR)
        driftgod.S = driftgod.S or {}
        if driftgod.R202_CaptureTuningFeatureState then driftgod.Try(driftgod.R202_CaptureTuningFeatureState) end

        local base = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.r198BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or "")
        local name = uniqueName(driftgod.S.customPresetName or "CustomPreset")
        local saved = now()
        local tbl = {
            customPresetName=name, base_preset=base, source_preset=base,
            r195BaseTuningPreset=base, r198BaseTuningPreset=base, activeArcadeDriftPreset=base,
            saved_at=saved
        }
        for _, k in ipairs(SaveKeys) do if driftgod.S[k] ~= nil then tbl[k] = driftgod.S[k] end end
        tbl.customPresetName = name
        tbl.base_preset = base
        tbl.source_preset = base
        tbl.r195BaseTuningPreset = base
        tbl.r198BaseTuningPreset = base
        tbl.activeArcadeDriftPreset = base
        tbl.saved_at = saved

        local ok = writeText(pathFor(PRESET_DIR, name, "json"), encodePreset(tbl))

        local idx = readIndex(PRESET_DIR)
        local newIdx = { { name=name, file=name .. ".json", ext="json", base=base, saved_at=saved } }
        for _, e in ipairs(idx) do if safeName(e.name) ~= name then newIdx[#newIdx + 1] = e end end
        writeIndex(PRESET_DIR, newIdx)

        driftgod.S.r213SavedPresetNames = driftgod.S.r213SavedPresetNames or {}
        table.insert(driftgod.S.r213SavedPresetNames, 1, name)
        driftgod.S.customPresetName = name
        driftgod.S.customPresetIndex = 1
        driftgod.S.r213LastPresetDir = PRESET_DIR
        driftgod.R213_ScanCustomPresets(true)

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast(ok and ("Saved preset: " .. tostring(name)) or "Preset save failed", 2200) end
        log("R213 saved json preset | " .. tostring(name) .. " | ok=" .. tostring(ok), true)
        return ok
    end

    function driftgod.R213_LoadCustomPresetByName(name)
        name = safeName(name)
        local tbl = loadPreset(name)
        if type(tbl) ~= "table" then
            if driftgod.Toast then driftgod.Toast("Preset load failed", 2200) end
            log("R213 load failed | " .. tostring(name), true)
            return false
        end

        local base = tostring(tbl.base_preset or tbl.r195BaseTuningPreset or tbl.r198BaseTuningPreset or tbl.activeArcadeDriftPreset or "")
        driftgod.S.r202SuppressBasePrefill = true
        if base ~= "" and driftgod.ApplyArcadeDriftPreset then driftgod.Try(function() driftgod.ApplyArcadeDriftPreset(base, false) end) end
        driftgod.S.r202SuppressBasePrefill = false

        for _, k in ipairs(SaveKeys) do if tbl[k] ~= nil then driftgod.S[k] = tbl[k] end end
        driftgod.S.r195BaseTuningPreset = base ~= "" and base or driftgod.S.r195BaseTuningPreset
        driftgod.S.r198BaseTuningPreset = base ~= "" and base or driftgod.S.r198BaseTuningPreset
        driftgod.S.activeArcadeDriftPreset = base ~= "" and base or driftgod.S.activeArcadeDriftPreset
        driftgod.S.customPresetName = tostring(tbl.customPresetName or name)
        driftgod.S.r213ActiveCustomPreset = name

        if driftgod.R202_ApplyTuningFeatureState then driftgod.Try(function() driftgod.R202_ApplyTuningFeatureState(tbl) end) end

        local list = driftgod.R213_ScanCustomPresets(false)
        for i, n in ipairs(list) do if tostring(n) == tostring(name) then driftgod.S.customPresetIndex = i; break end end

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Applied custom preset: " .. tostring(name), 2200) end
        log("R213 loaded preset | " .. tostring(name) .. " | base=" .. tostring(base), true)
        return true
    end

    function driftgod.R213_LoadSelectedCustomPreset()
        local list = driftgod.R213_ScanCustomPresets(false)
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        local name = list[idx]
        if not name then
            if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end
            return false
        end
        return driftgod.R213_LoadCustomPresetByName(name)
    end

    function driftgod.R213_DeleteSelectedCustomPreset()
        local list = driftgod.R213_ScanCustomPresets(false)
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        local name = list[idx]
        if not name then
            if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end
            return false
        end

        for _, dir in ipairs(candidateDirs()) do
            driftgod.Try(function()
                if FileMgr and FileMgr.DeleteFile then
                    FileMgr.DeleteFile(pathFor(dir, name, "json"))
                    FileMgr.DeleteFile(pathFor(dir, name, "lua"))
                elseif os and os.remove then
                    os.remove(pathFor(dir, name, "json"))
                    os.remove(pathFor(dir, name, "lua"))
                end
            end)

            local idxList, filtered = readIndex(dir), {}
            for _, e in ipairs(idxList) do if safeName(e.name) ~= name then filtered[#filtered + 1] = e end end
            writeIndex(dir, filtered)
        end

        driftgod.S.customPresetIndex = 1
        driftgod.R213_ScanCustomPresets(true)
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Deleted preset: " .. tostring(name), 2200) end
        return true
    end

