driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"
    driftgod.S.customPresetDebugEnabled = false

    local INDEX_FILE = "_presets_index.json"

    local function timeNow()
        return os.time and os.time() or (driftgod.Now and driftgod.Now() or math.floor((os.clock() or 0) * 1000))
    end

    local function root()
        local r = "."
        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then r = FileMgr.GetMenuRootPath() or "." end
        end)
        if r == nil or r == "" then r = "." end
        return tostring(r):gsub("/", "\\"):gsub("\\+$", "")
    end

    local ROOT = root()
    local PRESET_DIR = ROOT .. "\\Lua\\DriftGod\\storage\\presets\\"

    local function slash(dir)
        dir = tostring(dir or ""):gsub("/", "\\")
        if dir ~= "" and dir:sub(-1) ~= "\\" then dir = dir .. "\\" end
        return dir
    end

    PRESET_DIR = slash(PRESET_DIR)

    local function safeName(name)
        name = tostring(name or "CustomPreset")
        name = name:gsub("[\\/:%*%?\"<>|]", "_")
        name = name:gsub("%s+", "_")
        name = name:gsub("_+", "_")
        name = name:gsub("^_+", ""):gsub("_+$", "")
        if name == "" then name = "CustomPreset" end
        return name
    end

    local function isHelperBase(base)
        local b = tostring(base or ""):lower():gsub("^_+", ""):gsub("_+$", "")
        return b == "presets_index" or b == "preset_index" or b == "index" or b == "last_saved"
    end

    local function rawFileInfo(raw)
        local s = tostring(raw or ""):gsub("/", "\\")
        local full = s:match("([^\\]+)$") or s
        local base, ext = full:match("^(.-)%.([%w_]+)$")
        if not base or not ext then return nil, nil end
        ext = ext:lower()
        if ext ~= "json" and ext ~= "lua" then return nil, nil end
        if isHelperBase(base) then return nil, nil end
        return safeName(base), ext
    end

    local function addDir(out, seen, dir)
        dir = slash(dir)
        local k = dir:lower()
        if dir ~= "" and not seen[k] then
            seen[k] = true
            out[#out + 1] = dir
        end
    end

    local function candidateDirs()
        return { PRESET_DIR }
    end

    local function ensureDir(dir)
        dir = slash(dir or PRESET_DIR)
        driftgod.Try(function()
            if FileMgr and FileMgr.CreateDir then
                FileMgr.CreateDir(ROOT .. "\\Lua\\DriftGod")
                FileMgr.CreateDir(ROOT .. "\\Lua\\DriftGod\\storage")
                FileMgr.CreateDir(dir)
            end
        end)
    end

    local function pathFor(dir, name, ext)
        return slash(dir or PRESET_DIR) .. safeName(name) .. "." .. tostring(ext or "json"):gsub("^%.", "")
    end

    local function indexPath(dir)
        return slash(dir or PRESET_DIR) .. INDEX_FILE
    end

    local function fileExists(path)
        local ok, exists = driftgod.Try(function()
            if FileMgr and FileMgr.DoesFileExist then return FileMgr.DoesFileExist(path) end
            return nil
        end)
        if ok and exists ~= nil then return exists == true end

        ok, exists = driftgod.Try(function()
            local f = io and io.open and io.open(path, "r")
            if f then f:close(); return true end
            return false
        end)
        return ok and exists == true
    end

    local function readText(path)
        if not fileExists(path) then return nil end

        local ok, txt = driftgod.Try(function()
            local f = io and io.open and io.open(path, "r")
            if f then
                local s = f:read("*a")
                f:close()
                return s
            end
            return nil
        end)
        if ok and type(txt) == "string" and txt ~= "" then return txt end

        ok, txt = driftgod.Try(function()
            if FileMgr and FileMgr.ReadFileContent then return FileMgr.ReadFileContent(path) end
            return nil
        end)
        if ok and type(txt) == "string" and txt ~= "" then return txt end
        return nil
    end

    local function writeText(path, txt)
        local ok = false
        driftgod.Try(function()
            local f = io and io.open and io.open(path, "w")
            if f then f:write(tostring(txt or "")); f:close(); ok = true end
        end)
        if ok then return true end

        driftgod.Try(function()
            if FileMgr and FileMgr.WriteFileContent then ok = FileMgr.WriteFileContent(path, tostring(txt or ""), false) end
        end)
        return ok == true
    end

    local function esc(s)
        s = tostring(s or "")
        return s:gsub("\\", "\\\\"):gsub('"', '\\"'):gsub("\r", "\\r"):gsub("\n", "\\n")
    end

    local function unesc(s)
        s = tostring(s or "")
        return s:gsub("\\n", "\n"):gsub("\\r", "\r"):gsub('\\"', '"'):gsub("\\\\", "\\")
    end

    local function jsonVal(v)
        if type(v) == "boolean" then return v and "true" or "false" end
        if type(v) == "number" then return tostring(v) end
        if v == nil then return "null" end
        return '"' .. esc(v) .. '"'
    end

    local SaveKeys = {
        "customPresetName",
        "base_preset", "source_preset",
        "r195BaseTuningPreset", "r198BaseTuningPreset", "activeArcadeDriftPreset",
        "arcadePresetRuntimeAssist", "arcadePresetRuntimeEnabled",
        "driftAssistEnabled", "driftTuningEnabled", "driftTuningDriftEnabled",
        "stabilityAssistEnabled", "autoCounterSteerEnabled",
        "momentumAssistEnabled", "accelAssistEnabled",
        "experimentalGravityEnabled", "experimentalAccelEnabled", "experimentalTractionEnabled", "experimentalGripEnabled",
        "driftGripLevel", "driftStabilityLevel", "stabilityLevel",
        "autoCounterSteerLevel", "counterSteerLevel",
        "momentumStrength", "momentumLevel",
        "accelStrength", "accelerationLevel",
        "experimentalGravityStrength", "experimentalAccelStrength",
        "experimentalTractionLevel", "experimentalGripLevel"
    }

    local function parseFlatJson(txt)
        local t = {}
        for key, raw in tostring(txt or ""):gmatch('"%s*([^"]-)%s*"%s*:%s*([^,%}%]]+)') do
            raw = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
            local str = raw:match('^"(.-)"$')
            if str ~= nil then t[key] = unesc(str)
            elseif raw == "true" then t[key] = true
            elseif raw == "false" then t[key] = false
            elseif raw == "null" then t[key] = nil
            else
                local num = tonumber(raw)
                if num ~= nil then t[key] = num else t[key] = raw end
            end
        end
        return t
    end

    local function encodePreset(tbl)
        local out = { "{", '  "preset_schema": "DriftGodCustomPreset_R214",' }
        for _, k in ipairs(SaveKeys) do
            if tbl[k] ~= nil then out[#out + 1] = '  "' .. k .. '": ' .. jsonVal(tbl[k]) .. "," end
        end
        out[#out + 1] = '  "saved_at": ' .. tostring(tonumber(tbl.saved_at or timeNow()) or timeNow()) .. ","
        out[#out + 1] = '  "is_custom_preset": true'
        out[#out + 1] = "}"
        return table.concat(out, "\n")
    end

    local function parseIndex(txt)
        local out, seen = {}, {}
        local arr = tostring(txt or ""):match('%"presets%"%s*:%s*%[(.*)%]') or tostring(txt or "")
        for block in arr:gmatch("%{(.-)%}") do
            local rawName = block:match('%"name%"%s*:%s*%"(.-)%"')
            if rawName and rawName ~= "" then
                local name = safeName(unesc(rawName))
                if not isHelperBase(name) and not seen[name] then
                    local file = unesc(block:match('%"file%"%s*:%s*%"(.-)%"') or (name .. ".json"))
                    local fileBase, ext = rawFileInfo(file)
                    ext = ext or tostring(file):match("%.([%w_]+)$") or "json"
                    if fileBase and not isHelperBase(fileBase) then name = fileBase end
                    local base = unesc(block:match('%"base%"%s*:%s*%"(.-)%"') or "")
                    local saved = tonumber(block:match('%"saved_at%"%s*:%s*([%d%.%-]+)') or 0) or 0
                    seen[name] = true
                    out[#out + 1] = { name=name, file=name .. "." .. ext, ext=ext, base=base, saved_at=saved }
                end
            end
        end
        table.sort(out, function(a,b)
            local aa, bb = tonumber(a.saved_at or 0) or 0, tonumber(b.saved_at or 0) or 0
            if aa == bb then return tostring(a.name) < tostring(b.name) end
            return aa > bb
        end)
        return out
    end

    local function encodeIndex(entries)
        table.sort(entries, function(a,b)
            local aa, bb = tonumber(a.saved_at or 0) or 0, tonumber(b.saved_at or 0) or 0
            if aa == bb then return tostring(a.name) < tostring(b.name) end
            return aa > bb
        end)

        local out = {
            "{",
            '  "schema": "DriftGodPresetIndex_R214",',
            '  "updated_at": ' .. tostring(timeNow()) .. ",",
            '  "presets": ['
        }

        local clean = {}
        local seen = {}
        for _, e in ipairs(entries or {}) do
            local name = safeName(e.name)
            if name ~= "" and not isHelperBase(name) and not seen[name] then
                seen[name] = true
                local ext = tostring(e.ext or tostring(e.file or ""):match("%.([%w_]+)$") or "json")
                clean[#clean + 1] = {
                    name = name,
                    file = name .. "." .. ext,
                    ext = ext,
                    base = tostring(e.base or ""),
                    saved_at = tonumber(e.saved_at or 0) or 0
                }
            end
        end

        for i, e in ipairs(clean) do
            out[#out + 1] =
                '    {"name": "' .. esc(e.name or "") ..
                '", "file": "' .. esc(e.file or "") ..
                '", "base": "' .. esc(e.base or "") ..
                '", "saved_at": ' .. tostring(e.saved_at or 0) ..
                "}" .. (i < #clean and "," or "")
        end

        out[#out + 1] = "  ]"
        out[#out + 1] = "}"
        return table.concat(out, "\n")
    end

    local function readIndex(dir)
        local txt = readText(indexPath(dir))
        if not txt then return {} end
        return parseIndex(txt)
    end

    local function writeIndex(dir, entries)
        ensureDir(dir)
        return writeText(indexPath(dir), encodeIndex(entries or {}))
    end

    local function loadLua(path)
        if not fileExists(path) then return nil end
        local ok, tbl = driftgod.Try(function() return dofile(path) end)
        if ok and type(tbl) == "table" then return tbl end
        return nil
    end

    local function loadJson(path)
        local txt = readText(path)
        if not txt then return nil end
        local tbl = parseFlatJson(txt)
        if type(tbl) == "table" and next(tbl) then return tbl end
        return nil
    end

    local function scanFiles(dir)
        local out, seen = {}, {}
        local function add(raw)
            local name, ext = rawFileInfo(raw)
            if name and ext then
                local k = (name .. "." .. ext):lower()
                if not seen[k] then
                    seen[k] = true
                    out[#out + 1] = { name=name, ext=ext, file=name .. "." .. ext }
                end
            end
        end

        if driftgod.VS_FindFiles then
            local ok, files = driftgod.Try(function() return driftgod.VS_FindFiles(dir, { "json", "lua" }) end)
            if ok and type(files) == "table" then for _, f in ipairs(files) do add(f) end end
        end

        if #out <= 0 and FileMgr and FileMgr.FindFiles then
            for _, ext in ipairs({ "json", ".json", "lua", ".lua" }) do
                local ok, files = driftgod.Try(function() return FileMgr.FindFiles(dir, ext, true) end)
                if ok and type(files) == "table" then for _, f in ipairs(files) do add(f) end end
                if #out > 0 then break end
            end
        end

        return out
    end

    function driftgod.R214_RebuildPresetIndex(force)
        local total = 0
        for _, dir in ipairs(candidateDirs()) do
            ensureDir(dir)
            local entries, seen = {}, {}
            for _, f in ipairs(scanFiles(dir)) do
                local tbl = nil
                if f.ext == "json" then tbl = loadJson(pathFor(dir, f.name, "json"))
                elseif f.ext == "lua" then tbl = loadLua(pathFor(dir, f.name, "lua")) end

                local saved = tonumber(tbl and tbl.saved_at or 0) or timeNow()
                local base = tostring(tbl and (tbl.base_preset or tbl.r195BaseTuningPreset or tbl.r198BaseTuningPreset or tbl.activeArcadeDriftPreset) or "")
                if not seen[f.name] then
                    seen[f.name] = true
                    entries[#entries + 1] = { name=f.name, file=f.name .. "." .. f.ext, ext=f.ext, base=base, saved_at=saved }
                end
            end

            if #entries > 0 then writeIndex(dir, entries); total = total + #entries
            else
                local idx = readIndex(dir)
                writeIndex(dir, idx)
                total = total + #idx
            end
        end

        if force and driftgod.Log then driftgod.Log("[CustomPresetDebug] R214 rebuilt index | total=" .. tostring(total)) end
        return total
    end

    local function indexEntryFor(name)
        name = safeName(name)
        if isHelperBase(name) then return nil end
        for _, dir in ipairs(candidateDirs()) do
            for _, e in ipairs(readIndex(dir)) do
                if safeName(e.name) == name and not isHelperBase(e.name) then
                    local ext = tostring(e.ext or tostring(e.file or ""):match("%.([%w_]+)$") or "json")
                    return e, dir, ext
                end
            end
        end
        return nil
    end

    local function loadPreset(name)
        name = safeName(name)
        if isHelperBase(name) then return nil end

        local e, dir, ext = indexEntryFor(name)
        if e and dir then
            local tbl = nil
            if ext == "lua" then tbl = loadLua(pathFor(dir, name, "lua"))
            else tbl = loadJson(pathFor(dir, name, "json")) end
            if tbl then return tbl, dir end
            tbl = loadLua(pathFor(dir, name, "lua")) or loadJson(pathFor(dir, name, "json"))
            if tbl then return tbl, dir end
        end

        for _, dir in ipairs(candidateDirs()) do
            local tbl = loadLua(pathFor(dir, name, "lua")) or loadJson(pathFor(dir, name, "json"))
            if tbl then return tbl, dir end
        end

        return nil
    end

    function driftgod.R214_ScanCustomPresets(force)
        local names, seen = {}, {}
        local function add(n)
            n = safeName(n)
            if n ~= "" and not isHelperBase(n) and not seen[n] then
                seen[n] = true
                names[#names + 1] = n
            end
        end

        for _, dir in ipairs(candidateDirs()) do
            for _, e in ipairs(readIndex(dir)) do add(e.name) end
        end

        if #names <= 0 then
            driftgod.R214_RebuildPresetIndex(force == true)
            for _, dir in ipairs(candidateDirs()) do
                for _, e in ipairs(readIndex(dir)) do add(e.name) end
            end
        end

        for _, n in ipairs(driftgod.S.r214SavedPresetNames or {}) do add(n) end
        for _, n in ipairs(driftgod.S.r213SavedPresetNames or {}) do add(n) end

        table.sort(names, function(a,b)
            local ea = indexEntryFor(a)
            local eb = indexEntryFor(b)
            local aa = tonumber(ea and ea.saved_at or 0) or 0
            local bb = tonumber(eb and eb.saved_at or 0) or 0
            if aa == bb then return tostring(a) < tostring(b) end
            return aa > bb
        end)

        driftgod.S.customPresetList = names
        driftgod.S.r214PresetCount = #names
        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        if #names <= 0 then idx = 1
        elseif idx < 1 then idx = 1
        elseif idx > #names then idx = #names end
        driftgod.S.customPresetIndex = idx

        if force and driftgod.Log then driftgod.Log("[CustomPresetDebug] R214 scan | found=" .. tostring(#names) .. " | names=" .. table.concat(names, ", ")) end
        return names
    end

    function driftgod.R214_RecentCustomPresets(limit)
        local all = driftgod.R214_ScanCustomPresets(false)
        local out = {}
        limit = tonumber(limit or 3) or 3
        for i = 1, math.min(limit, #all) do out[#out + 1] = all[i] end
        return out
    end

    local function uniqueName(requested)
        local base = safeName(requested or driftgod.S.customPresetName or "CustomPreset")
        local existing, built = {}, {}
        for _, n in ipairs(driftgod.R214_ScanCustomPresets(false)) do existing[safeName(n)] = true end
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            built[safeName(p.id or "")] = true
            built[safeName(p.name or "")] = true
        end
        if not existing[base] and not built[base] and not isHelperBase(base) then return base end
        local i = 2
        while true do
            local c = base .. "_" .. tostring(i)
            if not existing[c] and not built[c] and not isHelperBase(c) then return c end
            i = i + 1
        end
    end

    function driftgod.R214_SaveCustomPreset()
        driftgod.S = driftgod.S or {}
        ensureDir(PRESET_DIR)
        if driftgod.R202_CaptureTuningFeatureState then driftgod.Try(driftgod.R202_CaptureTuningFeatureState) end

        local base = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.r198BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or "")
        local name = uniqueName(driftgod.S.customPresetName or "CustomPreset")
        local saved = timeNow()
        local tbl = {
            customPresetName=name, base_preset=base, source_preset=base,
            r195BaseTuningPreset=base, r198BaseTuningPreset=base, activeArcadeDriftPreset=base,
            saved_at=saved
        }
        for _, k in ipairs(SaveKeys) do if driftgod.S[k] ~= nil then tbl[k] = driftgod.S[k] end end
        tbl.customPresetName = name
        tbl.base_preset = base
        tbl.source_preset = base
        tbl.r195BaseTuningPreset = base
        tbl.r198BaseTuningPreset = base
        tbl.activeArcadeDriftPreset = base
        tbl.saved_at = saved

        local ok = writeText(pathFor(PRESET_DIR, name, "json"), encodePreset(tbl))

        local idx, newIdx = readIndex(PRESET_DIR), { { name=name, file=name .. ".json", ext="json", base=base, saved_at=saved } }
        for _, e in ipairs(idx) do if safeName(e.name) ~= name and not isHelperBase(e.name) then newIdx[#newIdx + 1] = e end end
        writeIndex(PRESET_DIR, newIdx)

        driftgod.S.r214SavedPresetNames = driftgod.S.r214SavedPresetNames or {}
        table.insert(driftgod.S.r214SavedPresetNames, 1, name)
        driftgod.S.customPresetName = name
        driftgod.S.customPresetIndex = 1
        driftgod.R214_ScanCustomPresets(false)

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast(ok and ("Saved preset: " .. tostring(name)) or "Preset save failed", 2200) end
        return ok
    end

    function driftgod.R214_LoadCustomPresetByName(name)
        name = safeName(name)
        local tbl = loadPreset(name)
        if type(tbl) ~= "table" then
            if driftgod.Toast then driftgod.Toast("Preset load failed", 2200) end
            return false
        end

        local base = tostring(tbl.base_preset or tbl.r195BaseTuningPreset or tbl.r198BaseTuningPreset or tbl.activeArcadeDriftPreset or "")
        driftgod.S.r202SuppressBasePrefill = true
        if base ~= "" and driftgod.ApplyArcadeDriftPreset then driftgod.Try(function() driftgod.ApplyArcadeDriftPreset(base, false) end) end
        driftgod.S.r202SuppressBasePrefill = false

        for _, k in ipairs(SaveKeys) do if tbl[k] ~= nil then driftgod.S[k] = tbl[k] end end
        driftgod.S.r195BaseTuningPreset = base ~= "" and base or driftgod.S.r195BaseTuningPreset
        driftgod.S.r198BaseTuningPreset = base ~= "" and base or driftgod.S.r198BaseTuningPreset
        driftgod.S.activeArcadeDriftPreset = base ~= "" and base or driftgod.S.activeArcadeDriftPreset
        driftgod.S.customPresetName = tostring(tbl.customPresetName or name)
        driftgod.S.r214ActiveCustomPreset = name

        if driftgod.R202_ApplyTuningFeatureState then driftgod.Try(function() driftgod.R202_ApplyTuningFeatureState(tbl) end) end
        local list = driftgod.R214_ScanCustomPresets(false)
        for i, n in ipairs(list) do if tostring(n) == tostring(name) then driftgod.S.customPresetIndex = i; break end end

        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Applied custom preset: " .. tostring(name), 2200) end
        return true
    end

    function driftgod.R214_LoadSelectedCustomPreset()
        local list = driftgod.R214_ScanCustomPresets(false)
        local name = list[tonumber(driftgod.S.customPresetIndex or 1) or 1]
        if not name then
            if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end
            return false
        end
        return driftgod.R214_LoadCustomPresetByName(name)
    end

    function driftgod.R214_DeleteSelectedCustomPreset()
        local list = driftgod.R214_ScanCustomPresets(false)
        local name = list[tonumber(driftgod.S.customPresetIndex or 1) or 1]
        if not name then
            if driftgod.Toast then driftgod.Toast("No custom preset selected", 1800) end
            return false
        end

        for _, dir in ipairs(candidateDirs()) do
            driftgod.Try(function()
                if FileMgr and FileMgr.DeleteFile then
                    FileMgr.DeleteFile(pathFor(dir, name, "json"))
                    FileMgr.DeleteFile(pathFor(dir, name, "lua"))
                elseif os and os.remove then
                    os.remove(pathFor(dir, name, "json"))
                    os.remove(pathFor(dir, name, "lua"))
                end
            end)
            local filtered = {}
            for _, e in ipairs(readIndex(dir)) do if safeName(e.name) ~= name and not isHelperBase(e.name) then filtered[#filtered + 1] = e end end
            writeIndex(dir, filtered)
        end

        driftgod.S.customPresetIndex = 1
        driftgod.R214_ScanCustomPresets(false)
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        if driftgod.Toast then driftgod.Toast("Deleted preset: " .. tostring(name), 2200) end
        return true
    end

