        { name="Pop Shuv-It",     type="forward_jump", category="Street / Reliable",  yaw=360, pitch=0,    roll=0,   duration=900,  jump=7.0,  forwardNudge=1.8, unlock=1500 },
        { name="Varial Kickflip", type="forward_jump", category="Street / Reliable",  yaw=360, pitch=0,    roll=360, duration=1250, jump=8.5,  forwardNudge=2.0, unlock=4500 },
        { name="Side Flip",       type="forward_jump", category="Street / Reliable",  yaw=0,   pitch=0,    roll=360, duration=1150, jump=8.5,  forwardNudge=2.0, unlock=6500 },
        { name="540",             type="forward_jump", category="Advanced / Reliable", yaw=540, pitch=0,   roll=0,   duration=1300, jump=8.5,  forwardNudge=2.0, unlock=9000 },
        { name="Gainer",          type="forward_jump", category="Advanced / Air",      yaw=0,   pitch=360,  roll=0,   duration=1350, jump=9.5,  forwardNudge=2.6, unlock=12000 },
        { name="Arabian",         type="forward_jump", category="Advanced / Air",      yaw=360, pitch=-360, roll=0,   duration=1500, jump=10.0, forwardNudge=2.4, unlock=16000 },
    }

    local function r216Clamp(n, lo, hi)
        n = tonumber(n or lo) or lo
        if n < lo then return lo end
        if n > hi then return hi end
        return n
    end

    local function r216Now()
        if driftgod.GetMs then return tonumber(driftgod.GetMs() or 0) or 0 end
        if Time and Time.GetEpocheMs then return tonumber(Time.GetEpocheMs() or 0) or 0 end
        if driftgod.Now then return tonumber(driftgod.Now() or 0) or 0 end
        return 0
    end

    local function r216HasTrick(name)
        local key = tostring(name or ""):lower()
        for _, trick in ipairs(driftgod.Tricks or {}) do
            if tostring(trick and trick.name or ""):lower() == key then return true end
        end
        return false
    end

    local function r216AppendNewStunts()
        driftgod.Tricks = driftgod.Tricks or {}
        for _, stunt in ipairs(R216_NEW_STUNTS) do
            if not r216HasTrick(stunt.name) then
                table.insert(driftgod.Tricks, stunt)
            end
        end
    end

    local function r216InstallUnlocksAndOrder()
        driftgod.StuntUnlocks = driftgod.StuntUnlocks or {}
        for _, stunt in ipairs(R216_NEW_STUNTS) do
            if driftgod.StuntUnlocks[stunt.name] == nil then
                driftgod.StuntUnlocks[stunt.name] = tonumber(stunt.unlock or 0) or 0
            end
        end

        local desiredOrder = {
            "Donut", "Ollie", "720 Spin", "Back Flip", "Front Flip", "Forward Flip", "Kickflip",
            "Pop Shuv-It", "Varial Kickflip", "Side Flip", "540", "Gainer", "Arabian"
        }

        local existingOrder = driftgod.StuntUnlockOrder or {}
        local seen = {}
        local newOrder = {}

        for _, name in ipairs(desiredOrder) do
            if not seen[name] then
                table.insert(newOrder, name)
                seen[name] = true
            end
        end

        for _, name in ipairs(existingOrder) do
            if not seen[name] then
                table.insert(newOrder, name)
                seen[name] = true
            end
        end

        driftgod.StuntUnlockOrder = newOrder
    end

    local oldNormalize = driftgod.NormalizeStuntName
    driftgod.NormalizeStuntName = function(name)
        local s = tostring(name or "")
        local lower = s:lower()

        if lower:find("ollie", 1, true) then return "Ollie" end
        if lower:find("pop", 1, true) and (lower:find("shuv", 1, true) or lower:find("shove", 1, true)) then return "Pop Shuv-It" end
        if lower:find("shuv", 1, true) or lower:find("shove", 1, true) then return "Pop Shuv-It" end
        if lower:find("varial", 1, true) and lower:find("kick", 1, true) then return "Varial Kickflip" end
        if lower:find("side flip", 1, true) or lower:find("sideflip", 1, true) then return "Side Flip" end
        if lower == "540" or lower:find("540", 1, true) then return "540" end
        if lower:find("gainer", 1, true) then return "Gainer" end
        if lower:find("arabian", 1, true) then return "Arabian" end

        if oldNormalize then return oldNormalize(name) end
        return s
    end

    function driftgod.PerformForwardLandingJumpTrick(name, yaw, pitch, roll, duration, jumpForce, forwardNudge)
        if driftgod.S then
            local now = r216Now()
            driftgod.S.stuntCooldownUntil = math.max(tonumber(driftgod.S.stuntCooldownUntil or 0) or 0, now + tonumber(driftgod.S.stuntTierUseCooldownMs or 900))
        end

        if driftgod.ApplyStuntTierDuration then duration = driftgod.ApplyStuntTierDuration(name, duration) end

        driftgod.QueueStunt(name, function(veh)
            local initialVelocity = ENTITY.GET_ENTITY_VELOCITY(veh)
            local initialRotation = ENTITY.GET_ENTITY_ROTATION(veh, 2)
            local initialHeading = ENTITY.GET_ENTITY_HEADING(veh)

            duration = r216Clamp(duration, 450, 2600)
            jumpForce = r216Clamp(jumpForce, 3.0, 14.0)
            forwardNudge = r216Clamp(forwardNudge, 0.0, 4.0)

            local stepMs = 10
            local steps = math.max(1, math.floor(duration / stepMs))
            local rad = math.rad(initialHeading or 0.0)
            local forwardX = math.sin(-rad)
            local forwardY = math.cos(-rad)
            local baseVX = tonumber(initialVelocity.x or 0.0) or 0.0
            local baseVY = tonumber(initialVelocity.y or 0.0) or 0.0
            local baseVZ = tonumber(initialVelocity.z or 0.0) or 0.0

            ENTITY.APPLY_FORCE_TO_ENTITY(veh, 1, 0.0, 0.0, jumpForce * 0.62, 0.0, 0.0, 0.0, 0, false, true, true, false, true)

            for i = 1, steps do
                local progress = i / steps
                local input = driftgod.GetInput and driftgod.GetInput() or { x = 0.0, y = 0.0 }
                local easeOut = 1.0 - progress
                local ix = tonumber(input.x or 0.0) or 0.0
                local iy = tonumber(input.y or 0.0) or 0.0

                ENTITY.SET_ENTITY_VELOCITY(
                    veh,
                    baseVX + forwardX * forwardNudge + ix * 3.0,
                    baseVY + forwardY * forwardNudge + iy * 3.0,
                    baseVZ + (jumpForce * 0.42 * easeOut)
                )

                ENTITY.SET_ENTITY_ROTATION(
                    veh,
                    (tonumber(initialRotation.x or 0.0) or 0.0) + pitch * progress + iy * 5.0,
                    (tonumber(initialRotation.y or 0.0) or 0.0) + roll * progress,
                    initialHeading + yaw * progress + ix * 5.0,
                    2,
                    true
                )

                driftgod.Yield(stepMs)
            end

            for i = 1, 24 do
                local t = i / 24
                ENTITY.SET_ENTITY_ROTATION(veh, 0.0, 0.0, initialHeading, 2, true)
                ENTITY.SET_ENTITY_VELOCITY(
                    veh,
                    baseVX + forwardX * forwardNudge * (1.0 - t * 0.35),
                    baseVY + forwardY * forwardNudge * (1.0 - t * 0.35),
                    math.max(-0.25, baseVZ - 0.02 * i)
                )
                driftgod.Yield(10)
            end

            ENTITY.SET_ENTITY_ROTATION(veh, 0.0, 0.0, initialHeading, 2, true)
        end)
    end

    local oldRunTrickMeta = driftgod.RunTrickMeta
    driftgod.RunTrickMeta = function(trick)
        if trick and tostring(trick.type or "") == "forward_jump" then
            return driftgod.PerformForwardLandingJumpTrick(
                trick.name,
                tonumber(trick.yaw or 0) or 0,
                tonumber(trick.pitch or 0) or 0,
                tonumber(trick.roll or 0) or 0,
                tonumber(trick.duration or 1000) or 1000,
                tonumber(trick.jump or 8) or 8,
                tonumber(trick.forwardNudge or 2) or 2
            )
        end
        if oldRunTrickMeta then return oldRunTrickMeta(trick) end
    end

    local oldRegisterDefaultTricks = driftgod.RegisterDefaultTricks
    if type(oldRegisterDefaultTricks) == "function" and driftgod.R216_RegisterDefaultTricksWrapped ~= true then
        driftgod.RegisterDefaultTricks = function(...)
            local result = oldRegisterDefaultTricks(...)
            r216AppendNewStunts()
            r216InstallUnlocksAndOrder()
            return result
        end
        driftgod.R216_RegisterDefaultTricksWrapped = true
    end

    r216AppendNewStunts()
    r216InstallUnlocksAndOrder()

    driftgod.R216_NewReliableStunts = R216_NEW_STUNTS

end)

