        end
        if oldNormalizeR221 then return oldNormalizeR221(name) end
        return s
    end

    function driftgod.PerformR221ContinuousForwardStunt(name, yaw, pitch, roll, duration, jumpForce, forwardNudge)
        if not r221CanRun() then
            if driftgod.Toast then driftgod.Toast("Stunt engine not ready.", 1800) end
            return
        end

        if driftgod.S then
            local now = r221Now()
            driftgod.S.stuntCooldownUntil = math.max(tonumber(driftgod.S.stuntCooldownUntil or 0) or 0, now + tonumber(driftgod.S.stuntTierUseCooldownMs or 0))
        end

        driftgod.QueueStunt(name, function(veh)
            local initialVelocity = ENTITY.GET_ENTITY_VELOCITY(veh)
            local initialRotation = ENTITY.GET_ENTITY_ROTATION(veh, 2)
            local initialHeading = ENTITY.GET_ENTITY_HEADING(veh)

            local baseVX, baseVY, baseVZ = r221V3(initialVelocity)
            local startPitch = tonumber(initialRotation and initialRotation.x or 0.0) or 0.0
            local startRoll = tonumber(initialRotation and initialRotation.y or 0.0) or 0.0
            local heading = tonumber(initialHeading or 0.0) or 0.0
            local fwdX, fwdY = r221ForwardFromHeading(heading)

            duration = r221Clamp(duration, 750, 3000)
            jumpForce = r221Clamp(jumpForce, 2.0, 9.0)
            forwardNudge = r221Clamp(forwardNudge, 0.0, 0.75)

            local stepMs = 10
            local steps = math.max(1, math.floor(duration / stepMs))
            local settleStart = 0.88

            ENTITY.APPLY_FORCE_TO_ENTITY(veh, 1, 0.0, 0.0, jumpForce * 0.52, 0.0, 0.0, 0.0, 0, false, true, true, false, true)

            for i = 1, steps do
                local progress = i / steps
                local stuntProgress = r221Smooth(progress)
                local input = driftgod.GetInput and driftgod.GetInput() or { x = 0.0, y = 0.0 }
                local ix = tonumber(input.x or 0.0) or 0.0
                local iy = tonumber(input.y or 0.0) or 0.0

                local curPitch = startPitch + (pitch or 0) * stuntProgress + iy * 2.0
                local curRoll = startRoll + (roll or 0) * stuntProgress
                local curYaw = heading + (yaw or 0) * stuntProgress + ix * 1.5

                if progress >= settleStart then
                    local t = r221Smooth((progress - settleStart) / (1.0 - settleStart))
                    local targetPitch = r221NearestEquivalent(curPitch, 0.0)
                    local targetRoll = r221NearestEquivalent(curRoll, 0.0)
                    local targetYaw = r221NearestEquivalent(curYaw, heading)
                    curPitch = curPitch + (targetPitch - curPitch) * t
                    curRoll = curRoll + (targetRoll - curRoll) * t
                    curYaw = curYaw + (targetYaw - curYaw) * t
                end

                local fallAssist = 0.62 * progress
                local remainingLift = jumpForce * 0.30 * (1.0 - progress)
                local zVel = baseVZ + remainingLift - fallAssist

                ENTITY.SET_ENTITY_ROTATION(veh, curPitch, curRoll, curYaw, 2, true)
                ENTITY.SET_ENTITY_VELOCITY(
                    veh,
                    baseVX + fwdX * forwardNudge + ix * 0.35,
                    baseVY + fwdY * forwardNudge + iy * 0.35,
                    zVel
                )

                driftgod.Yield(stepMs)
            end

            local finalPitch = r221NearestEquivalent(startPitch + (pitch or 0), 0.0)
            local finalRoll = r221NearestEquivalent(startRoll + (roll or 0), 0.0)
            local finalYaw = r221NearestEquivalent(heading + (yaw or 0), heading)
            ENTITY.SET_ENTITY_ROTATION(veh, finalPitch, finalRoll, finalYaw, 2, true)
            ENTITY.SET_ENTITY_VELOCITY(veh, baseVX, baseVY, math.min(baseVZ, -0.35))
        end)
    end

    function driftgod.PerformR219SmoothForwardLandingJump(name, yaw, pitch, roll, duration, jumpForce, forwardNudge)
        local raw = tostring(name or "")
        local norm = driftgod.NormalizeStuntName and driftgod.NormalizeStuntName(raw) or raw
        local key = r221Key(norm)
        local cfg = R221_ANIM[key]
        if cfg then
            return driftgod.PerformR221ContinuousForwardStunt(norm, cfg.yaw, cfg.pitch, cfg.roll, cfg.duration, cfg.jump, cfg.nudge)
        end
        return driftgod.PerformR221ContinuousForwardStunt(norm, yaw, pitch, roll, duration, jumpForce, forwardNudge)
    end

