    function driftgod.R224_RenderPresetColumns(id)
        local groups = {
            {label="Default", color="default", default=true},
            {label="Starter", color="starter", sections={{family="Default / Starter"}, {label="Very Open", color="green", family="Open"}}},
            {label="Wide Road", color="wide", sections={{family="Wide / Open Roads"}}},
            {label="Technical", color="technical", sections={{family="Technical / Windy Roads"}}},
            {label="Custom", color="custom", custom=true},
        }

        local function renderFamily(family, textColor)
            local any = false
            for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
                if tostring(p.family or "") == tostring(family or "") then
                    any = true
                    ctext(tostring(p.name or p.id or "Preset"), textColor or "white")
                    plainButton("Apply##R224_Base_" .. tostring(p.id or p.name), function()
                        if driftgod.ApplyArcadeDriftPreset then driftgod.ApplyArcadeDriftPreset(p.id, true) end
                    end)
                end
            end
            if not any then ctext("No presets", "dim") end
        end

        local function renderCustomRecent()
            local list = scanRecent(3)
            if #list <= 0 then
                ctext("No custom presets yet.", "dim")
                return
            end
            for _, name in ipairs(list) do
                ctext(tostring(name), "custom")
                plainButton("Apply##R224_Custom_" .. tostring(name), function() loadCustomByName(name) end)
            end
        end

        local function renderGroup(g)
            if g.default then
                ctext("Built-in baseline", "default")
                renderFeature(driftgod.H.PresetDefault, "PresetDefault")
                renderFeature(driftgod.H.PresetKrieger, "PresetKrieger")
            elseif g.custom then
                renderCustomRecent()
            else
                for si, section in ipairs(g.sections or {}) do
                    if si > 1 and ImGui and ImGui.Spacing then driftgod.Try(ImGui.Spacing) end
                    if section.label and section.label ~= "" then ctext(section.label, section.color or g.color) end
                    renderFamily(section.family, section.color or g.color)
                end
            end
        end

        if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex and ImGui.BeginTable(id or "DG_R224_PresetColumns", 5, dgSafeTableFlags and dgSafeTableFlags() or 0) then
            ImGui.TableNextRow()
            for i, g in ipairs(groups) do ImGui.TableSetColumnIndex(i - 1); ctext(g.label, g.color) end
            ImGui.TableNextRow()
            for i, g in ipairs(groups) do ImGui.TableSetColumnIndex(i - 1); renderGroup(g) end
            ImGui.EndTable()
        else
            for _, g in ipairs(groups) do ctext(g.label, g.color); renderGroup(g) end
        end
    end

