            elseif driftgod.R212_ScanCustomPresets then list = driftgod.R212_ScanCustomPresets(false) or {}
            elseif driftgod.R211_ScanCustomPresets then list = driftgod.R211_ScanCustomPresets(false) or {} end

            local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
            if #list > 0 then if idx < 1 then idx = 1 end; if idx > #list then idx = #list end; driftgod.S.customPresetIndex = idx end
            local preview = list[idx] or "No custom presets"

