                elseif driftgod.R212_DeleteSelectedCustomPreset then driftgod.R212_DeleteSelectedCustomPreset()
                elseif driftgod.R211_DeleteSelectedCustomPreset then driftgod.R211_DeleteSelectedCustomPreset() end
            end)

            if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
        end
