    local previousR224Drift = renderDriftMinimal
    renderDriftMinimal = function()
        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Presets") then
            driftgod.R224_RenderPresetColumns("DG_R224_DriftPresetColumns")
            driftgod.Try(ClickGUI.EndCustomChildWindow)
        elseif previousR224Drift then
            previousR224Drift()
