    local function getFeature(handle)
        if not handle then return nil end
        if type(handle) == "table" or type(handle) == "userdata" then return handle end
        if FeatureMgr and FeatureMgr.GetFeature then
            local ok, feat = driftgod.Try(FeatureMgr.GetFeature, handle)
            if ok then return feat end
        end
        return nil
    end

    local function setToggle(handle, desired)
        local feat = getFeature(handle)
        if not feat then return false end
        desired = desired == true
        local current = nil
        driftgod.Try(function() if feat.IsToggled then current = feat:IsToggled() end end)
        if current ~= nil and current == desired then return true end
        local ok = driftgod.Try(function()
            if feat.SetBoolValue then feat:SetBoolValue(desired)
            elseif feat.SetToggled then feat:SetToggled(desired)
            elseif feat.Toggle then feat:Toggle() end
        end)
        driftgod.Try(function() if feat.TriggerCallback then feat:TriggerCallback() elseif feat.Trigger then feat:Trigger() end end)
        return ok
    end

    local function setInt(handle, value)
        local feat = getFeature(handle)
        if not feat then return false end
        value = math.floor(tonumber(value or 0) or 0)
        local ok = driftgod.Try(function()
            if feat.SetIntValue then feat:SetIntValue(value)
            elseif feat.SetValue then feat:SetValue(value)
            elseif feat.SetFloatValue then feat:SetFloatValue(value + 0.0) end
        end)
        driftgod.Try(function() if feat.TriggerCallback then feat:TriggerCallback() elseif feat.Trigger then feat:Trigger() end end)
        return ok
    end

    local function applyTuningDefaults(force)
        driftgod.S = driftgod.S or {}
        if force ~= true and driftgod.S.r224TuningDefaultsApplied == true then return end

        driftgod.S.driftTuningDriftEnabled = false
        driftgod.S.stabilityAssistEnabled = false

        driftgod.S.autoCounterSteerLevel = 1
        driftgod.S.counterSteerLevel = 1
        driftgod.S.autoCounterSteer = 1
        driftgod.S.driftCounterSteer = 1

        driftgod.S.accelStrength = 1
        driftgod.S.accelerationLevel = 1
        driftgod.S.acceleration = 1
        driftgod.S.driftAcceleration = 1

        driftgod.S.experimentalAccelStrength = 1
        driftgod.S.experimentalGripLevel = 0

        setToggle(driftgod.H.R179_DriftToggle, false)
        setToggle(driftgod.H.StabilityAssist, false)
        setInt(driftgod.H.R123_CounterSlider, 1)
        setInt(driftgod.H.R123_AccelSlider, 1)
        setInt(driftgod.H.R123_ExpAccelSlider, 1)
        setInt(driftgod.H.R123_GripSlider, 0)

        driftgod.S.r224TuningDefaultsApplied = true
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
    end

    driftgod.R224_ApplyRequestedTuningDefaults = applyTuningDefaults
    applyTuningDefaults(false)

    if Script and Script.QueueJob then
        Script.QueueJob(function()
            if Script and Script.Yield then Script.Yield(900) end
            if driftgod.R224_ApplyRequestedTuningDefaults then driftgod.Try(driftgod.R224_ApplyRequestedTuningDefaults, false) end
        end)
    end

end)

driftgod.Try(function()
    DG = DG or {}
    driftgod.S = driftgod.S or {}
    driftgod.H = driftgod.H or {}

    local function toast(msg, ms)
        if driftgod.Toast then
            driftgod.Try(driftgod.Toast, tostring(msg or ""), tonumber(ms or 2200) or 2200)
        elseif GUI and GUI.AddToast then
            driftgod.Try(GUI.AddToast, "DriftGod", tostring(msg or ""), tonumber(ms or 2200) or 2200, eToastPos and (eToastPos.TOP_RIGHT or eToastPos.TopRight) or nil)
        end
    end

    local function renameWideAngle()
        if type(driftgod.ArcadeDriftPresets) == "table" then
            for _, p in ipairs(driftgod.ArcadeDriftPresets) do
                if tostring(p.id or "") == "driftgod_wide_angle" or tostring(p.name or "") == "DriftGod Wide Angle" then
                    p.name = "Wide Angle"
                    if type(p.desc) == "string" then
                        p.desc = p.desc:gsub("DriftGod Wide Angle", "Wide Angle")
                        p.desc = p.desc:gsub("Open / airport / giant roads", "airport / giant roads")
                        p.desc = p.desc:gsub("Open / ", "")
                    end
                    if type(p.ud_source) == "string" then
                        p.ud_source = p.ud_source:gsub("DriftGod Wide Angle", "Wide Angle")
                        p.ud_source = p.ud_source:gsub("Open %- ", "")
                    end
                end
            end
        end
    end

    renameWideAngle()
    local oldR116RefreshUniversalPresetValues = driftgod.R116RefreshUniversalPresetValues
    driftgod.R116RefreshUniversalPresetValues = function(...)
        local ret
        if oldR116RefreshUniversalPresetValues then ret = oldR116RefreshUniversalPresetValues(...) end
        renameWideAngle()
        return ret
    end

    local function getFeature(handle)
        if not handle then return nil end
        if type(handle) == "table" or type(handle) == "userdata" then return handle end
        if FeatureMgr and FeatureMgr.GetFeature then
            local ok, feat = driftgod.Try(FeatureMgr.GetFeature, handle)
            if ok then return feat end
        end
        return nil
    end

    local function triggerFeature(feat)
        if not feat then return end
        driftgod.Try(function()
            if feat.TriggerCallback then feat:TriggerCallback()
            elseif feat.Trigger then feat:Trigger() end
        end)
    end

    local function setToggle(handle, desired)
        local feat = getFeature(handle)
        if not feat then return false end
        desired = desired == true
        local current = nil
        driftgod.Try(function() if feat.IsToggled then current = feat:IsToggled() end end)
        if current ~= nil and current ~= desired and feat.Toggle then
            driftgod.Try(function() feat:Toggle() end)
        else
            driftgod.Try(function()
                if feat.SetBoolValue then feat:SetBoolValue(desired)
                elseif feat.SetToggled then feat:SetToggled(desired)
                elseif feat.SetValue then feat:SetValue(desired) end
            end)
        end
        triggerFeature(feat)
        return true
    end

    local function setInt(handle, value)
        local feat = getFeature(handle)
        if not feat then return false end
        value = math.floor(tonumber(value or 0) or 0)
        driftgod.Try(function()
            if feat.SetIntValue then feat:SetIntValue(value)
            elseif feat.SetValue then feat:SetValue(value)
            elseif feat.SetFloatValue then feat:SetFloatValue(value + 0.0) end
        end)
        triggerFeature(feat)
        return true
    end

    local function setAliases(kind, value)
        driftgod.S = driftgod.S or {}
        value = tonumber(value or 0) or 0
        if kind == "drift" then
            driftgod.S.driftGripLevel = value; driftgod.S.driftLevel = value; driftgod.S.drift = value
        elseif kind == "stability" then
            driftgod.S.driftStabilityLevel = value; driftgod.S.stabilityLevel = value; driftgod.S.stability = value; driftgod.S.driftStability = value
        elseif kind == "counter" then
            driftgod.S.autoCounterSteerLevel = value; driftgod.S.counterSteerLevel = value; driftgod.S.autoCounterSteer = value; driftgod.S.driftCounterSteer = value
        elseif kind == "momentum" then
            driftgod.S.momentumStrength = value; driftgod.S.momentumLevel = value; driftgod.S.momentum = value; driftgod.S.driftMomentum = value
        elseif kind == "accel" then
            driftgod.S.accelStrength = value; driftgod.S.accelerationLevel = value; driftgod.S.acceleration = value; driftgod.S.driftAcceleration = value
        elseif kind == "gravity" then
            driftgod.S.experimentalGravityStrength = value
        elseif kind == "expaccel" then
            driftgod.S.experimentalAccelStrength = value; driftgod.S.experimentalAccelLevel = value
        elseif kind == "traction" then
            driftgod.S.experimentalTractionLevel = value; driftgod.S.tractionLevel = value
        elseif kind == "grip" then
            driftgod.S.experimentalGripLevel = value; driftgod.S.gripLevel = value
        end
    end

    local function pushTuningState(tbl)
        driftgod.S = driftgod.S or {}
        tbl = tbl or {}
        for k, v in pairs(tbl) do driftgod.S[k] = v end

        if driftgod.R202_ApplyTuningFeatureState then driftgod.Try(driftgod.R202_ApplyTuningFeatureState, tbl) end

        if tbl.driftAssistEnabled ~= nil then setToggle(driftgod.H.DriftAssist, tbl.driftAssistEnabled == true) end
        if tbl.driftTuningEnabled ~= nil then setToggle(driftgod.H.DriftTuningMaster, tbl.driftTuningEnabled == true) end
        if tbl.driftTuningDriftEnabled ~= nil then setToggle(driftgod.H.R179_DriftToggle, tbl.driftTuningDriftEnabled == true) end
        if tbl.stabilityAssistEnabled ~= nil then setToggle(driftgod.H.StabilityAssist, tbl.stabilityAssistEnabled == true) end
        if tbl.autoCounterSteerEnabled ~= nil then setToggle(driftgod.H.AutoCounterSteer, tbl.autoCounterSteerEnabled == true) end
        if tbl.momentumAssistEnabled ~= nil then setToggle(driftgod.H.MomentumAssist, tbl.momentumAssistEnabled == true) end
        if tbl.accelAssistEnabled ~= nil then setToggle(driftgod.H.AccelAssist, tbl.accelAssistEnabled == true) end
        if tbl.experimentalAccelEnabled ~= nil then setToggle(driftgod.H.ExperimentalAcceleration or driftgod.H.ExperimentalAccel, tbl.experimentalAccelEnabled == true) end
        if tbl.experimentalGripEnabled ~= nil then setToggle(driftgod.H.ExperimentalGrip, tbl.experimentalGripEnabled == true) end
        if tbl.experimentalTractionEnabled ~= nil then setToggle(driftgod.H.ExperimentalTraction, tbl.experimentalTractionEnabled == true) end

        if tbl.driftGripLevel ~= nil then setAliases("drift", tbl.driftGripLevel); setInt(driftgod.H.R123_DriftSlider, tbl.driftGripLevel) end
        if tbl.driftStabilityLevel ~= nil then setAliases("stability", tbl.driftStabilityLevel); setInt(driftgod.H.R123_StabilitySlider, tbl.driftStabilityLevel) end
        if tbl.autoCounterSteerLevel ~= nil then setAliases("counter", tbl.autoCounterSteerLevel); setInt(driftgod.H.R123_CounterSlider, tbl.autoCounterSteerLevel) end
        if tbl.momentumStrength ~= nil then setAliases("momentum", tbl.momentumStrength); setInt(driftgod.H.R123_MomentumSlider, tbl.momentumStrength) end
        if tbl.accelStrength ~= nil then setAliases("accel", tbl.accelStrength); setInt(driftgod.H.R123_AccelSlider, tbl.accelStrength) end
        if tbl.experimentalAccelStrength ~= nil then setAliases("expaccel", tbl.experimentalAccelStrength); setInt(driftgod.H.R123_ExpAccelSlider, tbl.experimentalAccelStrength) end
        if tbl.experimentalGripLevel ~= nil then setAliases("grip", tbl.experimentalGripLevel); setInt(driftgod.H.R123_GripSlider, tbl.experimentalGripLevel) end
        if tbl.experimentalTractionLevel ~= nil then setAliases("traction", tbl.experimentalTractionLevel); setInt(driftgod.H.R123_TractionSlider, tbl.experimentalTractionLevel) end

        if driftgod.ClampAssistToUnlocks then driftgod.Try(driftgod.ClampAssistToUnlocks, false) end
        if driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
    end

    function driftgod.ApplyDefaultDriftingPreset(showToast)
        if driftgod.ClearLockedArcadePresetBlocker then driftgod.Try(driftgod.ClearLockedArcadePresetBlocker, "Reset Preset applied") end
        driftgod.S.activeStartupPreset = "Default"
        driftgod.S.r198ActiveCustomPreset = nil
        driftgod.S.r195BaseTuningPreset = nil
        driftgod.S.r198BaseTuningPreset = nil
        driftgod.S.activeArcadeDriftPreset = nil
        driftgod.S.arcadePresetRuntimeEnabled = false

        pushTuningState({
            driftAssistEnabled = true,
            driftTuningEnabled = true,
            driftTuningDriftEnabled = false,
            stabilityAssistEnabled = false,
            autoCounterSteerEnabled = true,
            momentumAssistEnabled = false,
            accelAssistEnabled = false,
            experimentalAccelEnabled = true,
            experimentalGripEnabled = true,
            driftGripLevel = 1,
            driftStabilityLevel = 1,
            autoCounterSteerLevel = 1,
            momentumStrength = 1,
            accelStrength = 1,
            experimentalAccelStrength = 1,
            experimentalGripLevel = 0,
        })

        if showToast ~= false then toast("Preset applied: Reset Preset", 2400) end
        return true
    end

    local oldApplyKriegerPreset = driftgod.ApplyKriegerPreset
    function driftgod.ApplyKriegerPreset(showToast)
        if driftgod.ClearLockedArcadePresetBlocker then driftgod.Try(driftgod.ClearLockedArcadePresetBlocker, "Krieger preset applied") end
        driftgod.S.activeStartupPreset = "Krieger"
        driftgod.S.r198ActiveCustomPreset = nil
