        if dgColorText then return dgColorText(txt, color) end
        if dgMiniText then return dgMiniText(txt, color) end
        if dgA38Text then return dgA38Text(txt, color) end
        if ImGui and ImGui.Text then return ImGui.Text(txt) end
    end

    local function R226Button(label, cb)
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) == true end) end
        if clicked and type(cb) == "function" then driftgod.Try(cb) end
        return clicked
    end

    local function R226PresetScore()
        driftgod.S = driftgod.S or {}
        if driftgod.GetArcadeDriftPresetScore then
            local ok, v = driftgod.Try(driftgod.GetArcadeDriftPresetScore)
            if ok then return math.floor(tonumber(v or 0) or 0) end
        end
        local best = tonumber(driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore or 0) or 0
        local current = tonumber(driftgod.S.currentScore or 0) or 0
        if current > best then best = current end
        if best < 0 then best = 0 end
        return math.floor(best)
    end

    local function R226IsTrialAvailable(p, score)
        if not p then return false end
        score = tonumber(score or R226PresetScore()) or 0
        local trialUntil = tonumber(p.trial_until or 0) or 0
        local need = tonumber(p.unlock or 0) or 0
        return trialUntil > 0 and score < trialUntil and score < need
    end

    local function R226IsUnlocked(p, score)
        if not p then return false end
        score = tonumber(score or R226PresetScore()) or 0
        return score >= (tonumber(p.unlock or 0) or 0)
    end

    function driftgod.IsArcadeDriftPresetTrialAvailable(id)
        local p = driftgod.GetArcadeDriftPresetById and driftgod.GetArcadeDriftPresetById(id) or nil
        return R226IsTrialAvailable(p, R226PresetScore())
    end

    function driftgod.IsArcadeDriftPresetPermanentlyUnlocked(id)
        local p = driftgod.GetArcadeDriftPresetById and driftgod.GetArcadeDriftPresetById(id) or nil
        return R226IsUnlocked(p, R226PresetScore())
    end

    function driftgod.IsArcadeDriftPresetUnlocked(id)
        local p = driftgod.GetArcadeDriftPresetById and driftgod.GetArcadeDriftPresetById(id) or nil
        if not p then return false end
        local score = R226PresetScore()
        return R226IsUnlocked(p, score) or R226IsTrialAvailable(p, score)
    end

    function driftgod.GetArcadeDriftPresetLabel(p)
        if not p then return "Unknown Preset" end
        local score = R226PresetScore()
        local need = tonumber(p.unlock or 0) or 0
        local trialUntil = tonumber(p.trial_until or 0) or 0
        local active = (driftgod.S and driftgod.S.activeArcadeDriftPreset == p.id) and "  [ACTIVE]" or ""
        local name = tostring(p.name or "Preset"):gsub("DriftGod Wide Angle", "Wide Angle")
        if R226IsUnlocked(p, score) then return name .. " — UNLOCKED" .. active end
        if trialUntil > 0 and R226IsTrialAvailable(p, score) then
            return "TRIAL: " .. name .. " — Starter Preview until " .. tostring(trialUntil) .. " Best Run" .. active
        end
        return "LOCKED: " .. name .. " | Unlock at " .. tostring(need) .. " | Current " .. tostring(score)
    end

    dgArcadePresetStatus = function(p, score)
        driftgod.S = driftgod.S or {}
        if not p then return "LOCKED", "locked", 0 end
        score = tonumber(score or R226PresetScore()) or 0
        local need = tonumber(p.unlock or 0) or 0
        local active = driftgod.S.activeArcadeDriftPreset == p.id
        local unlocked = R226IsUnlocked(p, score)
        local trial = R226IsTrialAvailable(p, score)

        if active then
            if unlocked then return "ACTIVE", "active", 0 end
            if trial then return "TRIAL ACTIVE", "active", math.max(0, need - score) end
            return "LOCKED", "locked", math.max(0, need - score)
        end
        if unlocked then return "UNLOCKED", "unlocked", 0 end
        if trial then return "TRIAL", "next", math.max(0, need - score) end
        return "LOCKED", "locked", math.max(0, need - score)
    end

