    local DRIFTGOD_UNLOCK = 100000

    local function fmt(n)
        n = math.floor(tonumber(n or 0) or 0)
        local s = tostring(n)
        local left, num, right = string.match(s, '^([^%d]*%d)(%d*)(.-)$')
        if not left then return s end
        return left .. (num:reverse():gsub('(%d%d%d)', '%1,'):reverse()) .. right
    end

    local function toast(msg, ms)
        if driftgod.Toast then
            driftgod.Try(driftgod.Toast, tostring(msg or ""), tonumber(ms or 3000) or 3000)
        elseif GUI and GUI.AddToast then
            driftgod.Try(GUI.AddToast, "DriftGod", tostring(msg or ""), tonumber(ms or 3000) or 3000, eToastPos and (eToastPos.TOP_RIGHT or eToastPos.TopRight) or nil)
        end
    end

    local function score()
        if driftgod.GetArcadeDriftPresetScore then
            local ok, v = driftgod.Try(driftgod.GetArcadeDriftPresetScore)
            if ok then return math.floor(tonumber(v or 0) or 0) end
        end
        local best = tonumber(driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore or 0) or 0
        local cur = tonumber(driftgod.S.currentScore or 0) or 0
        if cur > best then best = cur end
        if best < 0 then best = 0 end
        return math.floor(best)
    end

    local function isDriftGodId(id)
        id = tostring(id or "")
        return id == DRIFTGOD_PRESET_ID or id == "driftgod" or id == "DriftGod"
    end

