        if type(driftgod.ArcadeDriftPresets) ~= "table" then return nil end
        for _, p in ipairs(driftgod.ArcadeDriftPresets) do
            if tostring(p.id or "") == DRIFTGOD_PRESET_ID or tostring(p.name or "") == "DriftGod" then
                return p
            end
        end
        return nil
    end

    local function applyDriftGodPresetGate()
        local p = findDriftGodPreset()
        if not p then return nil end
        p.id = DRIFTGOD_PRESET_ID
        p.name = "DriftGod"
        p.unlock = DRIFTGOD_UNLOCK
        p.trial_until = DRIFTGOD_TRIAL_UNTIL
        p.desc = "DriftGod preset trial is available until 5,000 Best Run. After the trial, unlock it permanently at 100,000 Best Run."
        return p
    end

