        end
        if oldTrial then return oldTrial(id) end
        return false
    end

    local oldPermanent = driftgod.IsArcadeDriftPresetPermanentlyUnlocked
    driftgod.IsArcadeDriftPresetPermanentlyUnlocked = function(id)
        applyDriftGodPresetGate()
        if isDriftGodId(id) then return score() >= DRIFTGOD_UNLOCK end
        if oldPermanent then return oldPermanent(id) end
        local p = driftgod.GetArcadeDriftPresetById and driftgod.GetArcadeDriftPresetById(id) or nil
        return p ~= nil and score() >= (tonumber(p.unlock or 0) or 0)
    end

    local oldUnlocked = driftgod.IsArcadeDriftPresetUnlocked
    driftgod.IsArcadeDriftPresetUnlocked = function(id)
        applyDriftGodPresetGate()
        if isDriftGodId(id) then
            local s = score()
            return s < DRIFTGOD_TRIAL_UNTIL or s >= DRIFTGOD_UNLOCK
        end
        if oldUnlocked then return oldUnlocked(id) end
        local p = driftgod.GetArcadeDriftPresetById and driftgod.GetArcadeDriftPresetById(id) or nil
        return p ~= nil and score() >= (tonumber(p.unlock or 0) or 0)
    end

    local oldLabel = driftgod.GetArcadeDriftPresetLabel
    driftgod.GetArcadeDriftPresetLabel = function(p)
        applyDriftGodPresetGate()
        p = p or {}
        if tostring(p.id or "") == DRIFTGOD_PRESET_ID or tostring(p.name or "") == "DriftGod" then
            local s = score()
            local active = (driftgod.S and driftgod.S.activeArcadeDriftPreset == DRIFTGOD_PRESET_ID) and "  [ACTIVE]" or ""
            if s >= DRIFTGOD_UNLOCK then return "DriftGod — UNLOCKED" .. active end
            if s < DRIFTGOD_TRIAL_UNTIL then return "TRIAL: DriftGod — Starter Preview until " .. fmt(DRIFTGOD_TRIAL_UNTIL) .. " Best Run" .. active end
            return "LOCKED: DriftGod | Unlock at " .. fmt(DRIFTGOD_UNLOCK) .. " | Current " .. fmt(s)
        end
        if oldLabel then return oldLabel(p) end
        return tostring(p.name or p.id or "Preset")
    end

    if dgArcadePresetStatus then
        local oldStatus = dgArcadePresetStatus
        dgArcadePresetStatus = function(p, currentScore)
            applyDriftGodPresetGate()
            if p and (tostring(p.id or "") == DRIFTGOD_PRESET_ID or tostring(p.name or "") == "DriftGod") then
                local s = math.floor(tonumber(currentScore or score()) or 0)
                local active = driftgod.S and driftgod.S.activeArcadeDriftPreset == DRIFTGOD_PRESET_ID
                if s >= DRIFTGOD_UNLOCK then return active and "ACTIVE" or "UNLOCKED", active and "active" or "unlocked", 0 end
                if s < DRIFTGOD_TRIAL_UNTIL then return active and "TRIAL ACTIVE" or "TRIAL", active and "active" or "next", math.max(0, DRIFTGOD_UNLOCK - s) end
                return "LOCKED", "locked", math.max(0, DRIFTGOD_UNLOCK - s)
            end
            return oldStatus(p, currentScore)
        end
    end

    local function notifyDriftGodLocked()
        toast("You need to get " .. fmt(DRIFTGOD_UNLOCK) .. " to unlock DriftGod preset.", 4200)
    end

    local oldApply = driftgod.ApplyArcadeDriftPreset
    driftgod.ApplyArcadeDriftPreset = function(id, showToast)
        applyDriftGodPresetGate()
        if isDriftGodId(id) then
            local p = findDriftGodPreset()
            local s = score()
            if s >= DRIFTGOD_TRIAL_UNTIL and s < DRIFTGOD_UNLOCK then
                if driftgod.ArmLockedArcadePresetBlocker and p then driftgod.Try(driftgod.ArmLockedArcadePresetBlocker, p, s, DRIFTGOD_UNLOCK) end
                if showToast ~= false then notifyDriftGodLocked() end
                return false
            end
            if oldApply then return oldApply(DRIFTGOD_PRESET_ID, showToast) end
            return false
        end
        if oldApply then return oldApply(id, showToast) end
        return false
    end

    local oldShiftNotice = driftgod.ShowLockedArcadePresetShiftNotice
    driftgod.ShowLockedArcadePresetShiftNotice = function(...)
        if driftgod.S and tostring(driftgod.S.lockedArcadeDriftPresetId or "") == DRIFTGOD_PRESET_ID then
            local now = driftgod.Now and driftgod.Now() or math.floor(os.clock() * 1000)
            if now - (tonumber(driftgod.S.lockedArcadeDriftPresetLastNoticeMs or 0) or 0) < 850 then return end
            driftgod.S.lockedArcadeDriftPresetLastNoticeMs = now
