            driftgod.S.lockedArcadeDriftPresetBannerText = "You need to get " .. fmt(DRIFTGOD_UNLOCK) .. " to unlock DriftGod preset."
            notifyDriftGodLocked()
            return
        end
        if oldShiftNotice then return oldShiftNotice(...) end
    end
end)

