        local changed = false
        for _, row in ipairs(tuningRows) do
            local cap = driftgod.R245GetTuningCap(row.kind, row.fallback)
            local mn = tonumber(row.mn or 1) or 1
            if cap < mn then cap = mn == 0 and 0 or mn end
            local old = tonumber(driftgod.S[row.key] or mn) or mn
            local v = clampInt(old, mn, cap)
            if v ~= old then changed = true end
            driftgod.S[row.key] = v
            setAlias(row.kind, v)
            setSliderLimitAndValue(row.hash and row.hash() or nil, mn, cap, v)
        end
        if (driftgod.R245GetTuningCap("traction", 5) or 0) <= 0 then driftgod.S.experimentalTractionEnabled = false; setToggle(driftgod.H.ExperimentalTraction, false) end
        if (driftgod.R245GetTuningCap("grip", 5) or 0) <= 0 then driftgod.S.experimentalGripEnabled = false; setToggle(driftgod.H.ExperimentalGrip, false) end
        if changed and showToast == true then
            if driftgod.Toast then driftgod.Toast("Tuning sliders capped to unlocked levels.", 2200) end
        end
        return changed
    end

    local oldClamp = driftgod.ClampAssistToUnlocks
    driftgod.ClampAssistToUnlocks = function(showToast)
        if oldClamp then driftgod.Try(oldClamp, false) end
        local changed = driftgod.R245RefreshTuningSliderCaps(showToast == true)
        return changed
    end

