    if oldApplyArcadePreset and not driftgod.__R245ApplyArcadeWrapped then
        driftgod.__R245ApplyArcadeWrapped = true
        driftgod.ApplyArcadeDriftPreset = function(...)
            local r = oldApplyArcadePreset(...)
