            return r
        end
    end

    local oldDefaultPreset = driftgod.ApplyDefaultDriftingPreset
    if oldDefaultPreset and not driftgod.__R245DefaultWrapped then
        driftgod.__R245DefaultWrapped = true
        driftgod.ApplyDefaultDriftingPreset = function(showToast, syncFeatures)
            local r = oldDefaultPreset(showToast, syncFeatures)

            driftgod.S.activeStartupPreset = "Default Drifting"
            driftgod.S.activeArcadeDriftPreset = "default_drifting"
            driftgod.S.r195BaseTuningPreset = driftgod.S.r195BaseTuningPreset or "default_drifting"
            driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false)
            return r
        end
    end

    local oldCheckUnlocks = driftgod.CheckUnlocks
    if oldCheckUnlocks and not driftgod.__R245CheckUnlocksWrapped then
        driftgod.__R245CheckUnlocksWrapped = true
        driftgod.CheckUnlocks = function(...)
            local r = oldCheckUnlocks(...)
            driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false)
            return r
        end
    end

    if renderDriftMinimal and not driftgod.__R245RenderDriftWrapped then
        driftgod.__R245RenderDriftWrapped = true
        local oldRenderDrift = renderDriftMinimal
        renderDriftMinimal = function(...)
