        end
    end

    local oldReset = driftgod.R204_ResetTuningDefaults
    if oldReset and not driftgod.__R245R204ResetWrapped then
        driftgod.__R245R204ResetWrapped = true
        driftgod.R204_ResetTuningDefaults = function(...)
            local r = oldReset(...)
            driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false)
            return r
        end
    end

    driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false)
end)

