    local function colorButton(label, color, cb)
        local pushed = pushButtonColor(color)
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) == true end) end
        if pushed > 0 and ImGui and ImGui.PopStyleColor then driftgod.Try(ImGui.PopStyleColor, pushed) end
        if clicked and type(cb) == "function" then driftgod.Try(cb) end
        return clicked
    end

    local oldSaveStartupChoice = driftgod.R246_SaveStartupPresetChoice
    if oldSaveStartupChoice and not driftgod.__R247SaveChoiceWrapped then
        driftgod.__R247SaveChoiceWrapped = true
        driftgod.R246_SaveStartupPresetChoice = function(mode, idOrName, name, saveNow)
            if tostring(mode or "") == "builtin" and isResetId(idOrName) then name = "Reset" end
            return oldSaveStartupChoice(mode, idOrName, name, saveNow)
        end
    end

    if driftgod.ApplyDefaultDriftingPreset and not driftgod.__R247ResetWrapped then
        driftgod.__R247ResetWrapped = true
        local oldDefault = driftgod.ApplyDefaultDriftingPreset
        driftgod.ApplyDefaultDriftingPreset = function(showToast, save, ...)
            local result = oldDefault(false, save, ...)
            if result ~= false and not driftgod.__R246ApplyingStartupPreset and driftgod.R246_SaveStartupPresetChoice then
                driftgod.R246_SaveStartupPresetChoice("builtin", RESET_ID, "Reset", true)
            end
            driftgod.S.activeStartupPreset = "Reset"
            if driftgod.S.activeArcadeDriftPreset == RESET_ID or driftgod.S.activeArcadeDriftPreset == "Default Drifting" then driftgod.S.activeArcadeDriftPreset = RESET_ID end
            return result
        end
    end

    function driftgod.ApplyResetPreset(showToast)
        if driftgod.ApplyDefaultDriftingPreset then return driftgod.ApplyDefaultDriftingPreset(false, true) end
        return false
    end

    if driftgod.ApplyArcadeDriftPreset and not driftgod.__R247ApplyArcadeWrapped then
        driftgod.__R247ApplyArcadeWrapped = true
        local oldApply = driftgod.ApplyArcadeDriftPreset
        driftgod.ApplyArcadeDriftPreset = function(id, showToast, ...)
            if isResetId(id) then return driftgod.ApplyResetPreset(false) end
            local p = presetById(id)
            if not presetUnlocked(id, p) then return false end
            local result = oldApply(id, false, ...)
            if result ~= false and not driftgod.__R246ApplyingStartupPreset and not driftgod.__R246ApplyingCustomPreset and driftgod.R246_SaveStartupPresetChoice then
                local finalId = isDriftGodId(id) and DRIFTGOD_ID or tostring(id or "")
                driftgod.R246_SaveStartupPresetChoice("builtin", finalId, displayName(finalId, p), true)
            end
