    local function renderPresetButton(p)
        if not p then return end
        local id = tostring(p.id or "")
        if id == "" then return end
        local unlocked = presetUnlocked(id, p)
        local color = unlocked and familyColor(p.family) or "grey"
        local name = displayName(id, p)
        textColor(name, unlocked and color or "locked")
        if not unlocked then
            local need = tonumber(p.unlock or 0) or 0
            if need > 0 then textColor("Unlock: " .. comma(need), "dim") end
        end
        colorButton("Apply##R247Preset_" .. id, color, function()
            if unlocked and driftgod.ApplyArcadeDriftPreset then driftgod.ApplyArcadeDriftPreset(id, false) end
        end)
    end

