            {label="Open", color="green", family="Open"},
            {label="Wide Road", color="cyan", family="Wide / Open Roads"},
            {label="Technical", color="lightblue", family="Technical / Windy Roads"},
            {label="Custom", color="custom", custom=true},
        }
        local function renderGroup(g)
            if g.reset then
                textColor("Reset Preset", "dim")
                colorButton("Reset##R247ResetPreset", "blue", function() driftgod.ApplyResetPreset(false) end)
            elseif g.custom then
                renderCustom()
            else
                renderFamily(g.family)
            end
        end
        local flags = dgSafeTableFlags and dgSafeTableFlags() or 0
        if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex and ImGui.BeginTable(id or "DG_R247_PresetColumns", #groups, flags) then
            ImGui.TableNextRow()
            for i,g in ipairs(groups) do ImGui.TableSetColumnIndex(i-1); textColor(g.label, g.color) end
            ImGui.TableNextRow()
            for i,g in ipairs(groups) do ImGui.TableSetColumnIndex(i-1); renderGroup(g) end
            ImGui.EndTable()
        else
            for _, g in ipairs(groups) do textColor(g.label, g.color); renderGroup(g); if ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end end
        end
