    local function renderFeature(hash, label)
        if hash and ClickGUI and ClickGUI.RenderFeature then
            local ok = driftgod.Try(ClickGUI.RenderFeature, hash)
            if ok then return true end
        end
        if hash and dgRenderFeatureSafe then local ok=driftgod.Try(dgRenderFeatureSafe, hash); if ok then return true end end
        if label then textColor("Missing: " .. tostring(label), "dim") end
        return false
    end

    local function setBasePreset(id)
        id = tostring(id or "")
        if isResetId(id) then
            driftgod.S.r195BaseTuningPreset = RESET_ID
            driftgod.S.r198BaseTuningPreset = RESET_ID
            driftgod.S.activeArcadeDriftPreset = RESET_ID
            driftgod.ApplyResetPreset(false)
            return true
        end
        local p = presetById(id)
        if not presetUnlocked(id, p) then return false end
        driftgod.S.r195BaseTuningPreset = id
        driftgod.S.r198BaseTuningPreset = id
        driftgod.S.activeArcadeDriftPreset = id
        if driftgod.ApplyArcadeDriftPreset then driftgod.ApplyArcadeDriftPreset(id, false) end
        if driftgod.R245RefreshTuningSliderCaps then driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false) end
        return true
    end

