            if type(cached) == "table" then return cached end
        end
        local list = {{id=RESET_ID, name="Reset", color="blue"}}
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            local id = tostring(p.id or "")
            if id ~= "" and presetUnlocked(id, p) then
                list[#list+1] = {id=id, name=displayName(id,p), color=familyColor(p.family), p=p}
            end
        end
        return list
    end

