            {name="Acceleration", toggle=driftgod.H.AccelAssist, slider=driftgod.H.R123_AccelSlider, sliderLabel="Acceleration", cap="accel"},
            {name="Gravity", toggle=driftgod.H.ExperimentalGravity, slider=driftgod.H.R123_GravitySlider, sliderLabel="Gravity", cap="gravity"},
            {name="Exp Accel", toggle=driftgod.H.ExperimentalAcceleration or driftgod.H.ExperimentalAccel, slider=driftgod.H.R123_ExpAccelSlider, sliderLabel="Exp Accel", cap="expaccel"},
            {name="Traction", toggle=driftgod.H.ExperimentalTraction, slider=driftgod.H.R123_TractionSlider, sliderLabel="Traction", cap="traction"},
