            ImGui.TableSetColumnIndex(1)
            if ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
                local opened=false; driftgod.Try(function() opened = ImGui.BeginCombo("Base Preset##R247BasePreset", tostring(preview)) end)
                if opened then
                    for _, item in ipairs(basePresetList()) do
                        local clicked=false
                        driftgod.Try(function() clicked = ImGui.Selectable(tostring(item.name) .. "##R247Base_" .. tostring(item.id), tostring(item.id) == tostring(current)) end)
                        if clicked then setBasePreset(item.id); current = item.id; preview = item.name end
