driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"
    driftgod.__ProductionPatch = "R309_ProductBuild_1_0_0"

    local RESET_ID = "default_drifting"
    local DRIFTGOD_ID = "corner_magnet"
    local DRIFTGOD_TRIAL_UNTIL = 5000
    local DRIFTGOD_UNLOCK = 100000

    local function score()
        if driftgod.GetArcadeDriftPresetScore then
            local ok, v = driftgod.Try(driftgod.GetArcadeDriftPresetScore)
            if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
        end
        if driftgod.ScoreForUnlock then
            local ok, v = driftgod.Try(driftgod.ScoreForUnlock)
            if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
        end
        local best = tonumber(driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore or 0) or 0
        local cur = tonumber(driftgod.S.currentScore or 0) or 0
        return math.floor(math.max(best, cur, 0))
    end

    local function isReset(id)
        id = tostring(id or "")
        return id == RESET_ID or id == "reset" or id == "Default Drifting" or id == "Reset"
    end

    local function isDriftGod(id)
        id = tostring(id or "")
        return id == DRIFTGOD_ID or id == "driftgod" or id == "DriftGod"
    end

    local function presetById(id)
        id = tostring(id or "")
        if id == "" then return nil end
        if driftgod.GetArcadeDriftPresetById then
            local ok, p = driftgod.Try(driftgod.GetArcadeDriftPresetById, id)
            if ok and type(p) == "table" then return p end
        end
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            if tostring(p.id or "") == id then return p end
        end
        return nil
    end

    function driftgod.R248BasePresetAllowed(id, p)
        id = tostring(id or (p and p.id) or "")
        if id == "" then return false end
        if isReset(id) then return true end
        p = p or presetById(id)
        if not p then return false end
        if isDriftGod(id) then
            local s = score()
            return s < DRIFTGOD_TRIAL_UNTIL or s >= DRIFTGOD_UNLOCK
        end
        if driftgod.IsArcadeDriftPresetUnlocked then
            local ok, unlocked = driftgod.Try(driftgod.IsArcadeDriftPresetUnlocked, id)
            if ok then return unlocked == true end
        end
        return score() >= (tonumber(p.unlock or 0) or 0)
    end

    function driftgod.R248SanitizeBasePreset()
        driftgod.S = driftgod.S or {}
        local id = tostring(driftgod.S.r195BaseTuningPreset or driftgod.S.r198BaseTuningPreset or driftgod.S.activeArcadeDriftPreset or "")
        if id == "" or isReset(id) then
            driftgod.S.r195BaseTuningPreset = RESET_ID
            driftgod.S.r198BaseTuningPreset = RESET_ID
            return RESET_ID
        end
        if driftgod.R248BasePresetAllowed(id, presetById(id)) ~= true then
            driftgod.S.r195BaseTuningPreset = RESET_ID
            driftgod.S.r198BaseTuningPreset = RESET_ID
            return RESET_ID
        end
        return id
    end

    if driftgod.R247IsPresetUnlocked and not driftgod.__R248WrappedR247Unlock then
        driftgod.__R248WrappedR247Unlock = true
        driftgod.R247IsPresetUnlocked = function(id)
            return driftgod.R248BasePresetAllowed(id, nil) == true
        end
    end

    driftgod.Try(driftgod.R248SanitizeBasePreset)
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.__ProductionPatch = "R309_ProductBuild_1_0_0"

    local RESET_ID = "default_drifting"
    local DRIFTGOD_ID = "driftgod"
    local DRIFTGOD_TRIAL_UNTIL = 5000
    local DRIFTGOD_UNLOCK = 100000

    local function score()
        driftgod.S = driftgod.S or {}
        if driftgod.GetArcadeDriftPresetScore then
            local ok, v = driftgod.Try(driftgod.GetArcadeDriftPresetScore)
            if ok then return math.floor(tonumber(v or 0) or 0) end
        end
        local best = tonumber(driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore or driftgod.S.bestRun or 0) or 0
        local current = tonumber(driftgod.S.currentScore or driftgod.S.arcadeRunScore or 0) or 0
        if current > best then best = current end
        if best < 0 then best = 0 end
        return math.floor(best)
    end

    local function isDriftGod(id, name)
        id = tostring(id or ""):lower()
        name = tostring(name or ""):lower()
        return id == DRIFTGOD_ID or name == DRIFTGOD_ID
    end

    local function displayName(id, p)
        id = tostring(id or (p and p.id) or "")
        local name = tostring((p and (p.name or p.id)) or id or "")
        if id == RESET_ID or id == "reset" or name == "Default Drifting" then return "Reset" end
        return name:gsub("Default Drifting", "Reset"):gsub("DriftGod Wide Angle", "Wide Angle")
    end

    local function familyColor(family)
        family = tostring(family or "")
        if family == "Default / Starter" then return "orange" end
        if family == "Open" or family == "Open" or family == "Open" then return "green" end
        if family == "Wide / Open Roads" then return "cyan" end
        if family == "Technical / Windy Roads" then return "lightblue" end
        return "purple"
    end

    local function presetAllowedFast(p, s)
        if type(p) ~= "table" then return false end
        local id = tostring(p.id or "")
        if id == "" then return false end
        if id == RESET_ID or id == "reset" then return true end
        if isDriftGod(id, p.name) then
            return s < DRIFTGOD_TRIAL_UNTIL or s >= DRIFTGOD_UNLOCK
        end
        return s >= (tonumber(p.unlock or 0) or 0)
    end

    function driftgod.R249InvalidateBasePresetDropdownCache(reason)
        driftgod.__R249BasePresetDropdownCache = nil
        driftgod.__R249BasePresetDropdownKey = nil
        driftgod.__R249BasePresetDropdownReason = tostring(reason or "manual")
    end

    function driftgod.R249GetBasePresetDropdownList(includeReset)
        driftgod.S = driftgod.S or {}
        local s = score()
        local presetCount = type(driftgod.ArcadeDriftPresets) == "table" and #driftgod.ArcadeDriftPresets or 0
        local key = tostring(s) .. "|" .. tostring(presetCount) .. "|" .. tostring(includeReset == true)
