            return true
        end
        return false
    end

    function driftgod.R254_EnsureSpawnerHudToggle()
        driftgod.H = driftgod.H or {}
        driftgod.H.R254SpawnerHudToggle = driftgod.H.R254SpawnerHudToggle or (driftgod.Hash and driftgod.Hash('R254SpawnerHudToggle') or Utils.Joaat('DG_R254SpawnerHudToggle'))
        if driftgod.R254SpawnerHudToggleFeature then return driftgod.R254SpawnerHudToggleFeature end
        if driftgod.SafeAddFeature and eFeatureType and eFeatureType.Toggle then
            local ok, feat = driftgod.Try(function()
                return driftgod.SafeAddFeature(driftgod.H.R254SpawnerHudToggle, 'Garage HUD', eFeatureType.Toggle, 'Show or hide the DriftGod Garage HUD / quick menu.', function(f)
                    if driftgod.__R254SyncingSpawnerHudToggle == true then return end
                    local on = false
                    driftgod.Try(function() on = f and f.IsToggled and f:IsToggled() == true or false end)
                    setSpawnerOpen(on)

                    syncBoolFeature(driftgod.H and driftgod.H.VehicleSpawnerOpen, on)
                    if driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
                end)
            end)
            if ok and feat then
                driftgod.R254SpawnerHudToggleFeature = feat
                driftgod.Try(function() if feat.SetDefaultValue then feat:SetDefaultValue(isSpawnerOpen() == true):Reset() end end)
                driftgod.Try(function() if feat.SetName then feat:SetName('Garage HUD') end end)
                driftgod.Try(function() if feat.SetDesc then feat:SetDesc('Show or hide the DriftGod Garage HUD / quick menu.') end end)
            end
        end
        return driftgod.R254SpawnerHudToggleFeature
    end

    local function renderFeature(hash)
        if not hash then return false end
        if ClickGUI and ClickGUI.RenderFeature then
            local ok = driftgod.Try(function() ClickGUI.RenderFeature(hash) end)
            if ok then return true end
        end
        local f = getFeature(hash)
        if f and f.Render then
            local ok = driftgod.Try(function() f:Render() end)
            if ok then return true end
        end
        if dgMiniFeature then
            local ok = driftgod.Try(dgMiniFeature, hash, 'Garage HUD')
            if ok then return true end
        end
        return false
    end

    local function renderCheckboxFallback()
        local open = isSpawnerOpen()
        if ImGui and ImGui.Checkbox then
            local ok, a, b = driftgod.Try(ImGui.Checkbox, 'Garage HUD##R254SpawnerHudCheckbox', open)
            if ok then
                local newVal = open
                local changed = false
                if type(b) == 'boolean' then
                    newVal = a == true
                    changed = b == true
                elseif type(a) == 'boolean' then

                    changed = a == true
                    newVal = not open
                end
                if changed then
                    setSpawnerOpen(newVal)
                    syncBoolFeature(driftgod.H and driftgod.H.VehicleSpawnerOpen, newVal)
                    syncBoolFeature(driftgod.H and driftgod.H.R254SpawnerHudToggle, newVal)
                    if driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
                end
                return true
            end
        end

        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button('Garage HUD##R254SpawnerHudButtonFallback') == true end) end
        if clicked then
            setSpawnerOpen(not open)
            if driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
        end
        if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end
        if dgMiniText then driftgod.Try(dgMiniText, isSpawnerOpen() and 'ON' or 'OFF', isSpawnerOpen() and 'green' or 'dim')
        elseif ImGui and ImGui.Text then driftgod.Try(ImGui.Text, isSpawnerOpen() and 'ON' or 'OFF') end
        return true
    end

    function driftgod.R254_RenderSpawnerHudToggle()
        if driftgod.VS_RegisterFeatures then driftgod.Try(driftgod.VS_RegisterFeatures) end
        driftgod.R254_EnsureSpawnerHudToggle()
        local open = isSpawnerOpen()
        syncBoolFeature(driftgod.H and driftgod.H.R254SpawnerHudToggle, open)
        syncBoolFeature(driftgod.H and driftgod.H.VehicleSpawnerOpen, open)
        if renderFeature(driftgod.H and driftgod.H.R254SpawnerHudToggle) then return true end
        return renderCheckboxFallback()
    end

    driftgod.R252_RenderSpawnerHudToggle = driftgod.R254_RenderSpawnerHudToggle

    if type(driftgod.VS_RenderGaragePanel) == 'function' then
        local function t(txt, color)
            if dgMiniText then local ok = driftgod.Try(dgMiniText, tostring(txt or ''), color or 'white'); if ok then return end end
            if R164_text then local ok = driftgod.Try(R164_text, tostring(txt or ''), color or 'white'); if ok then return end end
            if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, tostring(txt or '')) end
        end
        local function same() if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end end
        local function child(name)
            if ClickGUI and ClickGUI.BeginCustomChildWindow then
                local ok, open = driftgod.Try(ClickGUI.BeginCustomChildWindow, tostring(name or 'Section'))
                return ok and open == true
            end
            return false
        end
        local function endChild() if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end end
        local function feature(hash, label)
            if hash and dgMiniFeature then local ok = driftgod.Try(dgMiniFeature, hash, label); if ok then return true end end
            if hash and ClickGUI and ClickGUI.RenderFeature then local ok = driftgod.Try(function() ClickGUI.RenderFeature(hash) end); if ok then return true end end
            if hash and renderFeatureSafe then local ok = driftgod.Try(renderFeatureSafe, hash, label); if ok then return true end end
            return false
        end
        local function btn(label, cb)
            local clicked = false
            if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or 'Button')) == true end) end
            if clicked and type(cb) == 'function' then driftgod.Try(cb) end
            return clicked
        end

        local oldStuntHud = driftgod.R253_RenderGarageStuntHudToggle
        driftgod.VS_RenderGaragePanel = function()
            if driftgod.VS_RegisterFeatures then driftgod.Try(driftgod.VS_RegisterFeatures) end
            if R169_ensureSpawnerTopLeftDefault then driftgod.Try(R169_ensureSpawnerTopLeftDefault) end
            if child('DriftGod Garage') then
                t('Saved Vehicles Browser', 'header')
                driftgod.R254_RenderSpawnerHudToggle()
                same(); btn('Scan##R254Garage', driftgod.R154_RefreshSpawner or driftgod.R153_ScanVehicleSpawner or driftgod.R115_ScanSpawnerVehicles)
                same(); btn('Random##R254Garage', driftgod.R154_RandomSpawner or driftgod.R153_RandomVehicleSpawner or driftgod.R115_RandomSpawnerVehicle)
                feature(driftgod.H and driftgod.H.VehicleSpawnerCategory, 'Category')
                feature(driftgod.H and driftgod.H.VehicleSpawnerVehicle, 'Saved Vehicle')
                feature(driftgod.H and driftgod.H.VehicleSpawnerHotkeyInsert, 'Insert Hotkey')
                feature(driftgod.H and driftgod.H.VehicleSpawnerHudPreset, 'HUD Position')
                t('Spawn from the HUD with Enter / Right. Delete backs out or closes.', 'dim')
                if R154_statusRows then driftgod.Try(R154_statusRows) else
                    local count, selected = 0, 'None'
                    driftgod.Try(function()
                        count = #(driftgod.VS.runtime.items or {})
                        local item = (driftgod.VS.runtime.filtered or {})[(tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0) + 1]
                        if item then selected = tostring(item.displayLabel or item.name or selected) end
                    end)
                    t('Scanned: ' .. tostring(count) .. ' | Selected: ' .. tostring(selected), 'dim')
                end
                endChild()
            end
            if oldStuntHud then oldStuntHud() end
        end
    end
end)

