driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"
    driftgod.__ProductionPatch = "R309_ProductBuild_1_0_0"

    local sin, cos, sqrt, abs, pi = math.sin, math.cos, math.sqrt, math.abs, math.pi
    local function pow(a, b) return (tonumber(a or 0) or 0) ^ (tonumber(b or 1) or 1) end
    local function clamp(v, a, b)
        v = tonumber(v or 0) or 0
        if v < a then return a end
        if v > b then return b end
        return v
    end
    local function nowMs()
        if driftgod.Now then return tonumber(driftgod.Now() or 0) or 0 end
        return math.floor((os.clock() or 0) * 1000)
    end

    driftgod.Easing = driftgod.Easing or {}
    driftgod.EasingCredits = "Easing implementation credit: ihateraven. Equations: Robert Penner / Tweener family."

    driftgod.Easing.linear = function(t,b,c,d) return c * t / d + b end
    driftgod.Easing.quad_in = function(t,b,c,d) t=t/d; return c*t*t+b end
    driftgod.Easing.quad_out = function(t,b,c,d) t=t/d; return -c*t*(t-2)+b end
    driftgod.Easing.quad_in_out = function(t,b,c,d) t=t/d*2; if t<1 then return c/2*t*t+b end; t=t-1; return -c/2*(t*(t-2)-1)+b end
    driftgod.Easing.cubic_in = function(t,b,c,d) t=t/d; return c*t*t*t+b end
    driftgod.Easing.cubic_out = function(t,b,c,d) t=t/d-1; return c*(t*t*t+1)+b end
    driftgod.Easing.cubic_in_out = function(t,b,c,d) t=t/d*2; if t<1 then return c/2*t*t*t+b end; t=t-2; return c/2*(t*t*t+2)+b end
    driftgod.Easing.sine_in = function(t,b,c,d) return -c*cos(t/d*(pi/2))+c+b end
    driftgod.Easing.sine_out = function(t,b,c,d) return c*sin(t/d*(pi/2))+b end
    driftgod.Easing.sine_in_out = function(t,b,c,d) return -c/2*(cos(pi*t/d)-1)+b end
    driftgod.Easing.expo_out = function(t,b,c,d) if t>=d then return b+c end; return c*1.001*(-pow(2,-10*t/d)+1)+b end
    driftgod.Easing.expo_in = function(t,b,c,d) if t<=0 then return b end; return c*pow(2,10*(t/d-1))+b-c*0.001 end
    driftgod.Easing.circ_out = function(t,b,c,d) t=t/d-1; return c*sqrt(math.max(0,1-t*t))+b end
    driftgod.Easing.back_out = function(t,b,c,d,s) s=tonumber(s or 1.70158) or 1.70158; t=t/d-1; return c*(t*t*((s+1)*t+s)+1)+b end

    local function bounceOut(t,b,c,d)
        t=t/d
        if t < (1/2.75) then return c*(7.5625*t*t)+b end
        if t < (2/2.75) then t=t-(1.5/2.75); return c*(7.5625*t*t+0.75)+b end
        if t < (2.5/2.75) then t=t-(2.25/2.75); return c*(7.5625*t*t+0.9375)+b end
        t=t-(2.625/2.75); return c*(7.5625*t*t+0.984375)+b
    end
    driftgod.Easing.bounce_out = bounceOut
    driftgod.Easing.bounce_in = function(t,b,c,d) return c - bounceOut(d-t,0,c,d) + b end

    driftgod.EasingNames = {
        "linear", "quad_out", "quad_in", "quad_in_out",
        "sine_out", "sine_in", "sine_in_out",
        "cubic_out", "cubic_in", "cubic_in_out",
        "expo_out", "expo_in", "circ_out", "back_out", "bounce_out", "bounce_in"
    }

    function driftgod.Ease(name, t, b, c, d)
        d = tonumber(d or 1) or 1
        if d <= 0 then return (tonumber(b or 0) or 0) + (tonumber(c or 0) or 0) end
        t = clamp(t, 0, d)
        b = tonumber(b or 0) or 0
        c = tonumber(c or 0) or 0
        local fn = driftgod.Easing and driftgod.Easing[tostring(name or "")] or nil
        if type(fn) ~= "function" then fn = driftgod.Easing.linear end
        local ok, v = driftgod.Try(fn, t, b, c, d)
        if ok and tonumber(v) then return tonumber(v) end
        return driftgod.Easing.linear(t,b,c,d)
    end

    local function ensureDefaults()
        driftgod.S.easingLabEnabled = driftgod.S.easingLabEnabled ~= false
        driftgod.S.easingLabStyleIndex = tonumber(driftgod.S.easingLabStyleIndex or 2) or 2
        if driftgod.S.easingLabStyleIndex < 1 then driftgod.S.easingLabStyleIndex = 1 end
        if driftgod.S.easingLabStyleIndex > #driftgod.EasingNames then driftgod.S.easingLabStyleIndex = #driftgod.EasingNames end
        driftgod.S.easingLoadingEnabled = driftgod.S.easingLoadingEnabled ~= false
        driftgod.S.easingTabsEnabled = driftgod.S.easingTabsEnabled ~= false
        driftgod.S.easingGhostRaceEnabled = driftgod.S.easingGhostRaceEnabled ~= false
        driftgod.S.easingComboHudEnabled = driftgod.S.easingComboHudEnabled ~= false
        driftgod.S.easingResultCardEnabled = driftgod.S.easingResultCardEnabled ~= false
        driftgod.S.easingStuntAnimationEnabled = driftgod.S.easingStuntAnimationEnabled == true
        driftgod.S.easingPreviewStartMs = tonumber(driftgod.S.easingPreviewStartMs or 0) or 0
        driftgod.S.easingPreviewDurationMs = tonumber(driftgod.S.easingPreviewDurationMs or 1400) or 1400
        driftgod.S.easingPreviewLoop = driftgod.S.easingPreviewLoop ~= false
    end

    local function saveQuiet()
        if driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
    end

    local function text(txt)
        if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, tostring(txt or "")) end
    end
    local function sep() if ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end end
    local function same() if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end end
    local function colorText(txt, kind)
        if dgMiniText then local ok=driftgod.Try(dgMiniText, tostring(txt or ""), kind); if ok then return end end
        if dgColorText then local ok=driftgod.Try(dgColorText, tostring(txt or ""), kind); if ok then return end end
        text(txt)
    end
    local function header(txt) colorText(txt, "header") end
    local function dim(txt) colorText(txt, "dim") end

    local function child(title, fn)
        local opened = false
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, ret = driftgod.Try(ClickGUI.BeginCustomChildWindow, tostring(title or "Section"))
            opened = ok and ret == true
        end
        if opened then
            driftgod.Try(fn)
            if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
        else
            header(title); sep(); driftgod.Try(fn); sep()
        end
    end

    local function button(label, cb)
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) end) end
        if clicked and type(cb) == "function" then driftgod.Try(cb) end
        return clicked
    end

    local function toggle(label, key)
        ensureDefaults()
        local on = driftgod.S[key] == true
        local tag = on and "ON" or "OFF"
        if button(tostring(label) .. ": " .. tag, function()
            driftgod.S[key] = not (driftgod.S[key] == true)
            saveQuiet()
        end) then return end
    end

    local function styleName()
        ensureDefaults()
        return driftgod.EasingNames[tonumber(driftgod.S.easingLabStyleIndex or 1) or 1] or "linear"
    end

    local function selectStyle(i)
        ensureDefaults()
        i = tonumber(i or 1) or 1
        if i < 1 then i = #driftgod.EasingNames end
        if i > #driftgod.EasingNames then i = 1 end
        driftgod.S.easingLabStyleIndex = i
        driftgod.S.easingPreviewStartMs = nowMs()
        saveQuiet()
    end

    local function renderStylePicker()
        ensureDefaults()
        local selected = styleName()
        text("Selected: " .. tostring(selected))
        if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
            local opened = false
            driftgod.Try(function() opened = ImGui.BeginCombo("Easing Style##R260EasingStyle", selected) end)
            if opened then
                for i, name in ipairs(driftgod.EasingNames) do
                    local clicked = false
                    driftgod.Try(function() clicked = ImGui.Selectable(tostring(name), i == driftgod.S.easingLabStyleIndex) end)
                    if clicked then selectStyle(i) end
                end
                driftgod.Try(ImGui.EndCombo)
            end
        else
            button("Previous Style", function() selectStyle((tonumber(driftgod.S.easingLabStyleIndex or 1) or 1) - 1) end)
            same()
            button("Next Style", function() selectStyle((tonumber(driftgod.S.easingLabStyleIndex or 1) or 1) + 1) end)
        end
        button("Replay Preview", function() driftgod.S.easingPreviewStartMs = nowMs() end)
        same()
        toggle("Loop Preview", "easingPreviewLoop")
    end

    local function progressBar(frac, label)
        frac = clamp(frac, 0, 1)
        if ImGui and ImGui.ProgressBar then
            local ok = driftgod.Try(ImGui.ProgressBar, frac, 0, 0, tostring(label or ""))
            if ok then return end
        end
        local filled = math.floor(frac * 20 + 0.5)
        if filled < 0 then filled = 0 end
        if filled > 20 then filled = 20 end
        text("[" .. string.rep("#", filled) .. string.rep("-", 20-filled) .. "] " .. tostring(label or ""))
    end

    local function renderPreview()
        ensureDefaults()
        local duration = tonumber(driftgod.S.easingPreviewDurationMs or 1400) or 1400
        local start = tonumber(driftgod.S.easingPreviewStartMs or 0) or 0
        local now = nowMs()
        if start <= 0 then start = now; driftgod.S.easingPreviewStartMs = start end
        local elapsed = now - start
        if driftgod.S.easingPreviewLoop == true and elapsed > duration then
            start = now
            driftgod.S.easingPreviewStartMs = start
            elapsed = 0
        end
        if elapsed > duration then elapsed = duration end
        local name = styleName()
        local v = driftgod.Ease(name, elapsed, 0, 1, duration)
        local pct = math.floor(v * 100 + 0.5)
        local raw = math.floor((elapsed / duration) * 100 + 0.5)

        text("Raw time: " .. tostring(raw) .. "%  |  Eased value: " .. tostring(pct) .. "%")
        progressBar(v, tostring(name) .. " preview")
        sep()
        text("Loading UI:   DRIFTGOD READY  " .. tostring(pct) .. "%")
        text("Tab/Page UI:  Section fade/slide value " .. tostring(pct) .. "%")
        text("Ghost Race:   " .. (v < 0.25 and "3..." or (v < 0.50 and "2..." or (v < 0.75 and "1..." or "GO!"))))
        text("Combo HUD:    " .. tostring(math.max(1, math.floor(1 + v * 4 + 0.5))) .. "x COMBO pop")
        text("Result Card:  " .. (v >= 1 and "YOU WON / DID NOT FINISH ready" or "Result card animating in"))
    end

    function driftgod.R260_RenderEasingLab()
        ensureDefaults()
        child("Easing Lab", function()
            header("Easing Lab / Visual Motion Preview")
            dim("Preview easing styles before wiring them into loading, tab UI, Ghosts & Race, combo HUD, or optional stunt animations.")
            dim("Credits: ihateraven. Original equations: Robert Penner / Tweener family.")
            sep()
            toggle("Visual Easing Master", "easingLabEnabled")
            sep()
            renderStylePicker()
            sep()
            renderPreview()
        end)

        child("Where To Use It", function()
            toggle("Loading UI Easing", "easingLoadingEnabled")
            toggle("Tab/Page Easing", "easingTabsEnabled")
            toggle("Ghost Race Countdown / Results", "easingGhostRaceEnabled")
            toggle("Combo HUD / Score Popups", "easingComboHudEnabled")
            toggle("Result Card Easing", "easingResultCardEnabled")
            toggle("Stunt Animation Easing", "easingStuntAnimationEnabled")
            dim("Stunt Animation Easing is OFF by default. This lab does not change stunt physics yet.")
        end)
    end

    driftgod.R260_EasingCreditLine = driftgod.EasingCredits

    if type(renderSettingsMinimal) == "function" and driftgod.R260_SettingsWrapped ~= true then
        driftgod.R260_SettingsWrapped = true
        driftgod.R260_OldRenderSettingsMinimal = renderSettingsMinimal
        renderSettingsMinimal = function(...)
            if driftgod.R260_OldRenderSettingsMinimal then driftgod.Try(driftgod.R260_OldRenderSettingsMinimal, ...) end
            if driftgod.S and driftgod.S.easingLabEnabled ~= false then
                driftgod.R260_RenderEasingLab()
            else
                child("Easing Lab", function()
                    header("Easing Lab")
                    toggle("Visual Easing Master", "easingLabEnabled")
