        driftgod.S.easingLabStyleIndex = clamp(driftgod.S.easingLabStyleIndex or 2, 1, #driftgod.EasingNames)
        driftgod.S.easingPreviewStartMs = tonumber(driftgod.S.easingPreviewStartMs or 0) or 0
        driftgod.S.easingPreviewDurationMs = tonumber(driftgod.S.easingPreviewDurationMs or 1800) or 1800
        driftgod.S.easingPreviewLoop = driftgod.S.easingPreviewLoop ~= false
