    local function ease(style, elapsed, start, change, duration)
        if driftgod.Ease then return driftgod.Ease(style, elapsed, start, change, duration) end
        duration = tonumber(duration or 1) or 1
        if duration <= 0 then return start + change end
        return start + change * clamp(elapsed / duration, 0, 1)
    end

    local function previewProgress()
        ensure()
        local now = nowMs()
        if driftgod.S.easingPreviewStartMs <= 0 then driftgod.S.easingPreviewStartMs = now end
        local dur = tonumber(driftgod.S.easingPreviewDurationMs or 1800) or 1800
        local elapsed = now - (driftgod.S.easingPreviewStartMs or now)
        if elapsed > dur then
            if driftgod.S.easingPreviewLoop == true then
                driftgod.S.easingPreviewStartMs = now
                elapsed = 0
            else
                elapsed = dur
            end
        end
        local style = currentStyle()
        local p = clamp(ease(style, elapsed, 0, 1, dur), 0, 1)
        return p, elapsed, dur, style
    end

    local function bar(p, width)
