            t(string.rep(" ", slide) .. "DriftGod - Drift Like a God")
            t("Opacity: " .. tostring(alpha) .. "%   Scale feel: " .. string.format("%.2f", 0.90 + 0.10*p))
            t("Loading " .. bar(p, 34) .. " " .. tostring(math.floor(p * 100)) .. "%")
