    function driftgod.R262_GetVehicleForEasingPreview()
        if driftgod.GetPlayerVehicleForGhostRecording then
            local ok, veh = driftgod.Try(driftgod.GetPlayerVehicleForGhostRecording)
            if ok and tonumber(veh or 0) and tonumber(veh or 0) ~= 0 then return tonumber(veh) end
        end
        local veh = 0
        driftgod.Try(function()
            if PLAYER and PLAYER.PLAYER_PED_ID and PED and PED.GET_VEHICLE_PED_IS_IN then
                veh = PED.GET_VEHICLE_PED_IS_IN(PLAYER.PLAYER_PED_ID(), false) or 0
            end
        end)
        return tonumber(veh or 0) or 0
    end

    function driftgod.R262_StartVehicleEasingPreview()
        ensure()
        if driftgod.S.easingVehiclePreviewRunning == true then
            driftgod.S.easingVehiclePreviewStatus = "Already running"
            return false
        end
        local veh = driftgod.R262_GetVehicleForEasingPreview and driftgod.R262_GetVehicleForEasingPreview() or 0
        if tonumber(veh or 0) == 0 then
            driftgod.S.easingVehiclePreviewStatus = "Enter a vehicle first"
            return false
        end
        if not (Script and Script.QueueJob and Script.Yield) then
            driftgod.S.easingVehiclePreviewStatus = "Script.QueueJob unavailable"
            return false
        end

        local style = currentStyle()
        driftgod.S.easingVehiclePreviewRunning = true
        driftgod.S.easingVehiclePreviewStatus = "Running " .. style .. " vehicle stunt preview"

        Script.QueueJob(function()
            local startPitch, startRoll, startYaw = 0.0, 0.0, 0.0
            driftgod.Try(function()
                if driftgod.GetEntityRotationForRecording then
                    startPitch, startRoll, startYaw = driftgod.GetEntityRotationForRecording(veh)
                elseif ENTITY and ENTITY.GET_ENTITY_ROTATION then
                    local rr = ENTITY.GET_ENTITY_ROTATION(veh, 2)
                    if type(rr) == "table" then
                        startPitch = tonumber(rr.x or rr.X or rr[1] or 0.0) or 0.0
                        startRoll  = tonumber(rr.y or rr.Y or rr[2] or 0.0) or 0.0
                        startYaw   = tonumber(rr.z or rr.Z or rr[3] or 0.0) or 0.0
                    end
                end
            end)

            driftgod.Try(function()
                if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
            end)

            local dur = 1250
            local start = nowMs()
            while nowMs() - start <= dur do
                local elapsed = nowMs() - start
                local p = ease(style, elapsed, 0, 1, dur)
                local pitch = startPitch + (0.0 * p)
                local roll = startRoll + (360.0 * p)
                local yaw = startYaw + (45.0 * p)
                driftgod.Try(function()
                    if ENTITY and ENTITY.SET_ENTITY_ROTATION then
                        ENTITY.SET_ENTITY_ROTATION(veh, pitch, roll, yaw, 2, true)
                    end
                end)
                Script.Yield(0)
            end

            driftgod.Try(function()
                if ENTITY and ENTITY.SET_ENTITY_ROTATION then ENTITY.SET_ENTITY_ROTATION(veh, startPitch, startRoll, startYaw, 2, true) end
                if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, false) end
            end)

            driftgod.S.easingVehiclePreviewRunning = false
            driftgod.S.easingVehiclePreviewStatus = "Finished " .. style .. " vehicle preview"
        end)

        return true
    end

    local function renderVehiclePreview(p, style)
        child("Vehicle Stunt Preview", function()
            header("Safe Vehicle Easing Preview")
            dim("This does not change the real stunt system. It rotates your current vehicle once, then restores it.")
            t("Preview rotation: roll " .. tostring(math.floor(360 * p)) .. "° / yaw " .. tostring(math.floor(45 * p)) .. "°")
            t("Status: " .. tostring(driftgod.S.easingVehiclePreviewStatus or "Idle"))
            if button("Run Vehicle Easing Preview") then
                driftgod.R262_StartVehicleEasingPreview()
            end
            same()
            if button("Reset Preview Status") then
                driftgod.S.easingVehiclePreviewStatus = "Idle"
            end
        end)
    end

    function driftgod.R262_RenderEasingPlayground()
        ensure()
        local p, elapsed, dur, style = previewProgress()

        child("Easing Lab — R262 Preview Playground", function()
            header("Easing Lab — Visual Playground")
            dim("Pick an easing style and preview it as DriftGod UI, full page loading, or a mini vehicle stunt.")
            dim("Credits: ihateraven. Original equations: Robert Penner / Tweener family.")
            sep()
            renderStylePicker()
            sep()
            renderModePicker()
            sep()
            t("Preview Progress: " .. bar(p, 28) .. " " .. tostring(math.floor(p*100)) .. "%")
            t("Elapsed: " .. tostring(math.floor(elapsed)) .. " / " .. tostring(math.floor(dur)) .. " ms")
        end)

        local mode = tonumber(driftgod.S.easingPreviewModeIndex or 4) or 4
        if mode == 1 then
            renderUiMock(p, style)
        elseif mode == 2 then
            renderFullPage(p, style)
        elseif mode == 3 then
            renderVehiclePreview(p, style)
        else
            renderUiMock(p, style)
            renderFullPage(p, style)
            renderVehiclePreview(p, style)
        end

        child("Future Wiring Targets", function()
            t("Loading UI: use easing for image fade, bar fill, percent text, ready fade.")
            t("Tab/Page UI: use easing for page/section fade-in.")
            t("Ghosts & Race: use easing for 3...2...1...GO, DNF, result stats.")
            t("Combo HUD: use easing for combo pop and score pulse.")
            t("Stunts: optional easing style only after visual tests feel good.")
        end)
    end

    driftgod.R260_RenderEasingLab = driftgod.R262_RenderEasingPlayground
    driftgod.R261_RenderEasingLab = driftgod.R262_RenderEasingPlayground
end)

