    local function bar(p, width)
        width = math.floor(tonumber(width or 24) or 24)
        local fill = math.floor(width * clamp(p or 0, 0, 1) + 0.5)
        return "[" .. string.rep("█", fill) .. string.rep("░", math.max(0, width - fill)) .. "]"
    end

    local function getScore()
        local score = 0
        driftgod.Try(function()
            if driftgod.GetArcadeDriftPresetScore then score = tonumber(driftgod.GetArcadeDriftPresetScore() or 0) or 0 end
        end)
        if score <= 0 then
            score = tonumber(driftgod.S.bestScore or driftgod.S.highestScore or driftgod.S.todayBestScore or driftgod.S.arcadeBestScore or 0) or 0
        end
        return math.max(0, score)
    end

    driftgod.R269AnimationUnlocks = {
        { name = "linear",      unlock = 0,     label = "None / Linear" },
        { name = "quad_out",    unlock = 1000,  label = "Quad Out" },
