    driftgod.R269PreviewStunts = {
        { name = "Donut", yaw = 360, roll = 0, pitch = 0 },
        { name = "Ollie", yaw = 0, roll = 0, pitch = -18, z = 0.30 },
        { name = "Kickflip", yaw = 0, roll = 360, pitch = 0 },
        { name = "Heelflip", yaw = 0, roll = -360, pitch = 0 },
        { name = "Back Flip", yaw = 0, roll = 0, pitch = 360 },
        { name = "Front Flip", yaw = 0, roll = 0, pitch = -360 },
        { name = "Gainer", yaw = 90, roll = 0, pitch = 360 },
        { name = "720 Spin", yaw = 720, roll = 0, pitch = 0 },
        { name = "Side Flip", yaw = 0, roll = 360, pitch = 0 },
        { name = "Varial Kickflip", yaw = 180, roll = 360, pitch = 0 },
        { name = "Laser Flip", yaw = -360, roll = -360, pitch = 0 },
        { name = "Backside Flip", yaw = 180, roll = 0, pitch = 360 },
    }

    local function animationCount() return #(driftgod.R269AnimationUnlocks or {}) end
    local function stuntCount() return #(driftgod.R269PreviewStunts or {}) end

    local function ensure()
        driftgod.EasingNames = driftgod.EasingNames or {"linear", "quad_out", "quad_in", "quad_in_out", "sine_out", "sine_in", "sine_in_out", "cubic_out", "cubic_in", "cubic_in_out", "expo_out", "expo_in", "circ_out", "back_out", "bounce_out", "bounce_in"}
        driftgod.S.stuntAnimationUnlocksEnabled = driftgod.S.stuntAnimationUnlocksEnabled ~= false
        driftgod.S.stuntAnimationPreviewLocked = driftgod.S.stuntAnimationPreviewLocked ~= false
        driftgod.S.stuntEasingTestEnabled = driftgod.S.stuntEasingTestEnabled ~= false
        driftgod.S.stuntEasingAllowOvershoot = driftgod.S.stuntEasingAllowOvershoot ~= false
        driftgod.S.stuntAnimationSelectedIndex = clamp(driftgod.S.stuntAnimationSelectedIndex or driftgod.S.stuntEasingStyleIndex or 14, 1, animationCount())
        driftgod.S.stuntAnimationPreviewIndex = clamp(driftgod.S.stuntAnimationPreviewIndex or 1, 1, stuntCount())
        driftgod.S.stuntAnimationPreviewDurationMs = clamp(driftgod.S.stuntAnimationPreviewDurationMs or 1250, 500, 3500)
        driftgod.S.r269PreviewStartMs = tonumber(driftgod.S.r269PreviewStartMs or 0) or 0
        driftgod.S.r269PreviewLoop = driftgod.S.r269PreviewLoop == true
    end

    local function unlockEntry(index)
        ensure()
        return driftgod.R269AnimationUnlocks[clamp(index or driftgod.S.stuntAnimationSelectedIndex or 1, 1, animationCount())] or driftgod.R269AnimationUnlocks[1]
    end

    local function styleIndexByName(name)
        name = tostring(name or "")
        for i, n in ipairs(driftgod.EasingNames or {}) do
            if tostring(n) == name then return i end
        end
        return 1
    end

    local function selectedAnimation()
        local e = unlockEntry(driftgod.S.stuntAnimationSelectedIndex)
        return e.name or "linear", e
    end

    local function isUnlocked(e)
        if driftgod.S.stuntAnimationUnlocksEnabled ~= true then return true end
        if driftgod.S.stuntAnimationPreviewLocked == true then return true end
        return getScore() >= tonumber((e and e.unlock) or 0)
    end

    local function highestUnlockedIndex()
        local score = getScore()
        local idx = 1
        for i, e in ipairs(driftgod.R269AnimationUnlocks or {}) do
            if score >= tonumber(e.unlock or 0) then idx = i end
        end
        return idx
    end

    local function activeAnimationName()
        ensure()
        local e = unlockEntry(driftgod.S.stuntAnimationSelectedIndex)
        if not isUnlocked(e) then
            e = unlockEntry(highestUnlockedIndex())
        end
        return tostring(e.name or "linear"), e
    end

    function driftgod.R269_CurrentStuntAnimationName()
        return activeAnimationName()
    end

    local function syncStuntStyleToSelection()
        local name = activeAnimationName()
        local idx = styleIndexByName(name)
        driftgod.S.stuntEasingStyleIndex = idx
        driftgod.S.easingLabStyleIndex = idx
        return name
    end

    local function ease(style, elapsed, start, change, duration)
        if driftgod.Ease then return driftgod.Ease(style, elapsed, start, change, duration) end
        duration = tonumber(duration or 1) or 1
        if duration <= 0 then return start + change end
        return start + change * clamp(elapsed / duration, 0, 1)
    end

    function driftgod.R269_StuntEaseProgress(progress)
        ensure()
        progress = clamp(progress, 0.0, 1.0)
        if driftgod.S.stuntEasingTestEnabled ~= true then return progress end
        local style = syncStuntStyleToSelection()
        local ok, v = driftgod.Try(ease, style, progress * 1000.0, 0.0, 1.0, 1000.0)
        if not (ok and tonumber(v)) then return progress end
        v = tonumber(v)
        if driftgod.S.stuntEasingAllowOvershoot == true then return clamp(v, -0.20, 1.25) end
        return clamp(v, 0.0, 1.0)
    end

    driftgod.R263_StuntEaseProgress = driftgod.R269_StuntEaseProgress
    driftgod.R264_StuntEaseProgress = driftgod.R269_StuntEaseProgress

    driftgod.S.spawnerPreviewEnabled = true
    driftgod.S.spawnerPreviewRotateEnabled = true
    driftgod.S.spawnerPreviewOnlyJson = true
    driftgod.S.spawnerPreviewStatus = driftgod.S.spawnerPreviewStatus or "Original R264 preview + rotation restored"

    local function renderToggle(label, key)
        ensure()
        local on = driftgod.S[key] == true
        if button(tostring(label) .. ": " .. (on and "ON" or "OFF")) then
            driftgod.S[key] = not on
            saveQuiet()
        end
        same(); mini((driftgod.S[key] == true) and "ON" or "OFF", (driftgod.S[key] == true) and "green" or "dim")
    end

    local function animationStatusLine(e)
        local score = getScore()
        local req = tonumber(e.unlock or 0) or 0
        local unlocked = score >= req
        local label = tostring(e.label or e.name or "Animation")
        local status = unlocked and "UNLOCKED" or (tostring(math.max(0, req - score)) .. " pts left")
        return label .. " — " .. status
    end

    local function nextUnlock()
        local score = getScore()
        for _, e in ipairs(driftgod.R269AnimationUnlocks or {}) do
            if score < tonumber(e.unlock or 0) then return e end
        end
        return nil
    end

    local function renderUnlockBar()
        local score = getScore()
        local nxt = nextUnlock()
        if nxt then
            local prevReq = 0
            for _, e in ipairs(driftgod.R269AnimationUnlocks or {}) do
                local req = tonumber(e.unlock or 0) or 0
                if req < tonumber(nxt.unlock or 0) and req <= score then prevReq = req end
            end
            local span = math.max(1, tonumber(nxt.unlock or 0) - prevReq)
            local pct = clamp((score - prevReq) / span, 0, 1)
            t("Next Animation: " .. tostring(nxt.label or nxt.name) .. " at " .. tostring(nxt.unlock) .. " pts")
            t("Progress: " .. bar(pct, 30) .. " " .. tostring(math.floor(pct * 100)) .. "%")
        else
            t("All animations unlocked")
            t("Progress: " .. bar(1, 30) .. " 100%")
        end
    end

    local function renderAnimationPicker()
        ensure()
        local name, e = selectedAnimation()
        t("Selected Animation: " .. animationStatusLine(e))
        if button("< Animation##R269") then
            driftgod.S.stuntAnimationSelectedIndex = driftgod.S.stuntAnimationSelectedIndex - 1
            if driftgod.S.stuntAnimationSelectedIndex < 1 then driftgod.S.stuntAnimationSelectedIndex = animationCount() end
            syncStuntStyleToSelection(); saveQuiet()
        end
        same()
        if button("Animation >##R269") then
            driftgod.S.stuntAnimationSelectedIndex = driftgod.S.stuntAnimationSelectedIndex + 1
            if driftgod.S.stuntAnimationSelectedIndex > animationCount() then driftgod.S.stuntAnimationSelectedIndex = 1 end
            syncStuntStyleToSelection(); saveQuiet()
        end
        same()
        if button("Apply Animation##R269") then
            local applied = syncStuntStyleToSelection()
            driftgod.S.r264LastStuntEasingName = "Applied animation / " .. tostring(applied)
            saveQuiet()
        end

        if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
            local comboLabel = tostring(e.label or e.name or name)
            local opened = false
            driftgod.Try(function() opened = ImGui.BeginCombo("Animation Unlock##R269", comboLabel) end)
            if opened then
                for i, entry in ipairs(driftgod.R269AnimationUnlocks or {}) do
                    local display = tostring(entry.label or entry.name) .. "  [" .. tostring(entry.unlock or 0) .. "]"
                    if getScore() >= tonumber(entry.unlock or 0) then display = display .. " UNLOCKED" else display = display .. " LOCKED" end
                    local clicked = false
                    driftgod.Try(function() clicked = ImGui.Selectable(display, i == driftgod.S.stuntAnimationSelectedIndex) end)
                    if clicked then
                        driftgod.S.stuntAnimationSelectedIndex = i
                        syncStuntStyleToSelection(); saveQuiet()
                    end
                end
                ImGui.EndCombo()
            end
        end
    end

    local function renderStuntPicker()
        ensure()
        local st = driftgod.R269PreviewStunts[driftgod.S.stuntAnimationPreviewIndex] or driftgod.R269PreviewStunts[1]
        t("Preview Stunt: " .. tostring(st.name or "Stunt"))
        if button("< Stunt##R269") then
            driftgod.S.stuntAnimationPreviewIndex = driftgod.S.stuntAnimationPreviewIndex - 1
            if driftgod.S.stuntAnimationPreviewIndex < 1 then driftgod.S.stuntAnimationPreviewIndex = stuntCount() end
            saveQuiet()
        end
        same()
        if button("Stunt >##R269") then
            driftgod.S.stuntAnimationPreviewIndex = driftgod.S.stuntAnimationPreviewIndex + 1
            if driftgod.S.stuntAnimationPreviewIndex > stuntCount() then driftgod.S.stuntAnimationPreviewIndex = 1 end
            saveQuiet()
        end

        if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
            local opened = false
            driftgod.Try(function() opened = ImGui.BeginCombo("Stunt Preview##R269", tostring(st.name or "Stunt")) end)
            if opened then
                for i, entry in ipairs(driftgod.R269PreviewStunts or {}) do
                    local clicked = false
                    driftgod.Try(function() clicked = ImGui.Selectable(tostring(entry.name or i), i == driftgod.S.stuntAnimationPreviewIndex) end)
                    if clicked then driftgod.S.stuntAnimationPreviewIndex = i; saveQuiet() end
                end
                ImGui.EndCombo()
            end
        end
    end

    local function getCurrentVehicle()
        local veh = 0
        driftgod.Try(function()
            if driftgod.R262_GetVehicleForEasingPreview then veh = driftgod.R262_GetVehicleForEasingPreview() or 0 end
        end)
        if tonumber(veh or 0) ~= 0 then return tonumber(veh) end
        driftgod.Try(function()
            if PLAYER and PLAYER.PLAYER_PED_ID and PED and PED.GET_VEHICLE_PED_IS_IN then
                veh = PED.GET_VEHICLE_PED_IS_IN(PLAYER.PLAYER_PED_ID(), false) or 0
            end
        end)
        return tonumber(veh or 0) or 0
    end

    function driftgod.R269_StartStuntAnimationPreview()
        ensure()
        if driftgod.S.r269VehiclePreviewRunning == true then
            driftgod.S.r269VehiclePreviewStatus = "Already running"
            return false
        end
        local veh = getCurrentVehicle()
        if veh == 0 then
            driftgod.S.r269VehiclePreviewStatus = "Enter a vehicle first"
            return false
        end
        if not (Script and Script.QueueJob and Script.Yield) then
            driftgod.S.r269VehiclePreviewStatus = "Script.QueueJob unavailable"
            return false
        end

        local style = syncStuntStyleToSelection()
        local stunt = driftgod.R269PreviewStunts[driftgod.S.stuntAnimationPreviewIndex] or driftgod.R269PreviewStunts[1]
        local dur = tonumber(driftgod.S.stuntAnimationPreviewDurationMs or 1250) or 1250
        driftgod.S.r269VehiclePreviewRunning = true
        driftgod.S.r269VehiclePreviewStatus = "Running " .. tostring(stunt.name or "Stunt") .. " / " .. tostring(style)

        Script.QueueJob(function()
            local startPitch, startRoll, startYaw = 0.0, 0.0, 0.0
            driftgod.Try(function()
                if driftgod.GetEntityRotationForRecording then
                    startPitch, startRoll, startYaw = driftgod.GetEntityRotationForRecording(veh)
                elseif ENTITY and ENTITY.GET_ENTITY_ROTATION then
                    local rr = ENTITY.GET_ENTITY_ROTATION(veh, 2)
                    if type(rr) == "table" then
                        startPitch = tonumber(rr.x or rr.X or rr[1] or 0.0) or 0.0
                        startRoll  = tonumber(rr.y or rr.Y or rr[2] or 0.0) or 0.0
                        startYaw   = tonumber(rr.z or rr.Z or rr[3] or 0.0) or 0.0
                    end
                end
            end)
            driftgod.Try(function() if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end end)

            local start = nowMs()
            while nowMs() - start <= dur do
                local elapsed = nowMs() - start
                local p = ease(style, elapsed, 0.0, 1.0, dur)
                if driftgod.S.stuntEasingAllowOvershoot == true then p = clamp(p, -0.20, 1.25) else p = clamp(p, 0.0, 1.0) end
                local pitch = startPitch + (tonumber(stunt.pitch or 0.0) or 0.0) * p
                local roll  = startRoll  + (tonumber(stunt.roll  or 0.0) or 0.0) * p
                local yaw   = startYaw   + (tonumber(stunt.yaw   or 0.0) or 0.0) * p
                driftgod.Try(function()
                    if ENTITY and ENTITY.SET_ENTITY_ROTATION then ENTITY.SET_ENTITY_ROTATION(veh, pitch, roll, yaw, 2, true) end
                end)
                Script.Yield(0)
            end

            driftgod.Try(function()
                if ENTITY and ENTITY.SET_ENTITY_ROTATION then ENTITY.SET_ENTITY_ROTATION(veh, startPitch, startRoll, startYaw, 2, true) end
                if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, false) end
            end)
            driftgod.S.r269VehiclePreviewRunning = false
            driftgod.S.r269VehiclePreviewStatus = "Finished " .. tostring(stunt.name or "Stunt") .. " / " .. tostring(style)
        end)
        return true
    end

    local function previewProgressBar()
        ensure()
        if driftgod.S.r269PreviewStartMs <= 0 then driftgod.S.r269PreviewStartMs = nowMs() end
        local dur = tonumber(driftgod.S.stuntAnimationPreviewDurationMs or 1250) or 1250
        local elapsed = nowMs() - driftgod.S.r269PreviewStartMs
        if elapsed > dur then
            if driftgod.S.r269PreviewLoop == true then driftgod.S.r269PreviewStartMs = nowMs(); elapsed = 0 else elapsed = dur end
        end
        local style = activeAnimationName()
        local p = ease(style, elapsed, 0.0, 1.0, dur)
        if driftgod.S.stuntEasingAllowOvershoot == true then p = clamp(p, -0.20, 1.25) else p = clamp(p, 0.0, 1.0) end
