        end
        driftgod.R261_RenderEasingLab = driftgod.R260_RenderEasingLab
        driftgod.R262_RenderEasingPlayground = driftgod.R260_RenderEasingLab
    end

    if type(driftgod.R263_RenderSpawnerPreviewControls) == "function" and driftgod.R269_SpawnerPreviewNoteWrapped ~= true then
        driftgod.R269_SpawnerPreviewNoteWrapped = true
        local oldSpawnerPreviewControls = driftgod.R263_RenderSpawnerPreviewControls
        driftgod.R263_RenderSpawnerPreviewControls = function(...)
            local ok, ret = driftgod.Try(oldSpawnerPreviewControls, ...)
            child("Vehicle Preview Note", function()
                header("Vehicle Preview")
                dim("Restored to the original R264 ghost preview + rotation behavior.")
                dim("R265-R268 mod-apply preview experiments are not included in this build.")
                t("Preview: " .. tostring(driftgod.S.spawnerPreviewEnabled == true and "ON" or "OFF") .. " | Rotate: " .. tostring(driftgod.S.spawnerPreviewRotateEnabled == true and "ON" or "OFF"))
            end)
            if ok then return ret end
        end
    end
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}; driftgod.VS = driftgod.VS or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"
    driftgod.__ProductionPatch = "R309_ProductBuild_1_0_0"

    local function nowMs()
        if driftgod.Now then return tonumber(driftgod.Now() or 0) or 0 end
        if driftgod.VS_Now then return tonumber(driftgod.VS_Now() or 0) or 0 end
        return math.floor((os.clock() or 0) * 1000)
    end

    local function clamp(v, a, b)
        v = tonumber(v or 0) or 0
        if v < a then return a end
        if v > b then return b end
        return v
    end

    local function t(txt)
        if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, tostring(txt or "")) end
    end
    local function sep() if ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end end
    local function same() if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end end
    local function mini(txt, kind)
        if dgMiniText then local ok = driftgod.Try(dgMiniText, tostring(txt or ""), kind); if ok then return end end
        if dgColorText then local ok = driftgod.Try(dgColorText, tostring(txt or ""), kind); if ok then return end end
        if r223Text then local ok = driftgod.Try(r223Text, tostring(txt or ""), kind); if ok then return end end
        t(txt)
    end
    local function header(txt) mini(txt, "header") end
    local function dim(txt) mini(txt, "dim") end
    local function button(label)
        local clicked = false
        driftgod.Try(function() if ImGui and ImGui.Button then clicked = ImGui.Button(tostring(label or "Button")) end end)
        return clicked == true
    end
    local function child(title, fn)
        local opened = false
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, ret = driftgod.Try(ClickGUI.BeginCustomChildWindow, tostring(title or "Section"))
            opened = ok and ret == true
        end
        if opened then
            local ok, err = driftgod.Try(fn)
            if not ok then t("Section error: " .. tostring(err)) end
            if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
        else
            header(title); sep()
            local ok, err = driftgod.Try(fn)
            if not ok then t("Section error: " .. tostring(err)) end
            sep()
        end
    end
    local function saveQuiet()
        if driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
    end

    driftgod.R271AnimationUnlocks = driftgod.R271AnimationUnlocks or driftgod.R269AnimationUnlocks or {
        { name="linear", label="Linear / None", unlock=0 },
        { name="quad_out", label="Quad Out", unlock=1000 },
        { name="quad_in", label="Quad In", unlock=2000 },
        { name="quad_in_out", label="Quad In-Out", unlock=3000 },
        { name="sine_out", label="Sine Out", unlock=4000 },
        { name="sine_in", label="Sine In", unlock=5000 },
        { name="sine_in_out", label="Sine In-Out", unlock=6000 },
        { name="cubic_out", label="Cubic Out", unlock=7000 },
        { name="cubic_in", label="Cubic In", unlock=8000 },
        { name="cubic_in_out", label="Cubic In-Out", unlock=9000 },
        { name="expo_out", label="Expo Out", unlock=10000 },
        { name="expo_in", label="Expo In", unlock=11000 },
        { name="circ_out", label="Circ Out", unlock=12000 },
        { name="back_out", label="Back Out", unlock=13000 },
        { name="bounce_out", label="Bounce Out", unlock=14000 },
        { name="bounce_in", label="Bounce In", unlock=15000 },
    }
    driftgod.R271PreviewStunts = driftgod.R271PreviewStunts or driftgod.R269PreviewStunts or {
        { name="Donut", roll=0, pitch=0, yaw=360 },
        { name="Ollie", roll=0, pitch=-22, yaw=0 },
        { name="Kickflip", roll=360, pitch=0, yaw=0 },
        { name="Heelflip", roll=-360, pitch=0, yaw=0 },
        { name="Back Flip", roll=0, pitch=360, yaw=0 },
        { name="Front Flip", roll=0, pitch=-360, yaw=0 },
        { name="Gainer", roll=0, pitch=360, yaw=40 },
        { name="720 Spin", roll=0, pitch=0, yaw=720 },
        { name="Side Flip", roll=360, pitch=0, yaw=45 },
        { name="Varial Kickflip", roll=360, pitch=0, yaw=180 },
        { name="Laser Flip", roll=-360, pitch=0, yaw=360 },
        { name="Backside Flip", roll=360, pitch=0, yaw=-180 },
    }

    local function getScore()
        if driftgod.GetArcadeDriftPresetScore then local ok, v = driftgod.Try(driftgod.GetArcadeDriftPresetScore); if ok and tonumber(v) then return tonumber(v) end end
        return tonumber(driftgod.S.bestRunScore or driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore or 0) or 0
    end
    local function animCount() return #(driftgod.R271AnimationUnlocks or {}) end
    local function stuntCount() return #(driftgod.R271PreviewStunts or {}) end
    local function ensureAnim()
        driftgod.EasingNames = driftgod.EasingNames or {"linear", "quad_out", "quad_in", "quad_in_out", "sine_out", "sine_in", "sine_in_out", "cubic_out", "cubic_in", "cubic_in_out", "expo_out", "expo_in", "circ_out", "back_out", "bounce_out", "bounce_in"}
        driftgod.S.stuntAnimationSelectedIndex = clamp(driftgod.S.stuntAnimationSelectedIndex or driftgod.S.easingLabStyleIndex or 2, 1, math.max(1, animCount()))
        driftgod.S.stuntAnimationPreviewIndex = clamp(driftgod.S.stuntAnimationPreviewIndex or 1, 1, math.max(1, stuntCount()))
        driftgod.S.stuntAnimationPreviewLocked = driftgod.S.stuntAnimationPreviewLocked ~= false
        driftgod.S.stuntAnimationUnlocksEnabled = driftgod.S.stuntAnimationUnlocksEnabled ~= false
        driftgod.S.stuntAnimationPreviewDurationMs = tonumber(driftgod.S.stuntAnimationPreviewDurationMs or 1250) or 1250
        driftgod.S.r271PreviewStartMs = tonumber(driftgod.S.r271PreviewStartMs or 0) or 0
        driftgod.S.r271PreviewLoop = driftgod.S.r271PreviewLoop ~= false
        driftgod.S.r271EasingSubtab = clamp(driftgod.S.r271EasingSubtab or 1, 1, 5)
    end
    local function styleIndexByName(name)
        name = tostring(name or "")
        for i,n in ipairs(driftgod.EasingNames or {}) do if tostring(n) == name then return i end end
        return 1
    end
    local function currentAnimEntry()
        ensureAnim()
        return (driftgod.R271AnimationUnlocks or {})[driftgod.S.stuntAnimationSelectedIndex] or (driftgod.R271AnimationUnlocks or {})[1] or {name="linear", label="Linear / None", unlock=0}
    end
    local function currentAnimName()
        return tostring((currentAnimEntry()).name or "linear")
    end
    local function currentStuntEntry()
        ensureAnim()
        return (driftgod.R271PreviewStunts or {})[driftgod.S.stuntAnimationPreviewIndex] or (driftgod.R271PreviewStunts or {})[1] or {name="Donut", roll=0, pitch=0, yaw=360}
    end
    local function syncAnimToStunts()
        local name = currentAnimName()
        local idx = styleIndexByName(name)
        driftgod.S.easingLabStyleIndex = idx
        driftgod.S.stuntEasingStyleIndex = idx
        driftgod.S.stuntEasingTestEnabled = true
        driftgod.S.r264LastStuntEasingName = "Applied animation / " .. tostring(name)
        return name
    end
    local function ease(style, elapsed, start, change, dur)
        if driftgod.Ease then
            local ok, v = driftgod.Try(driftgod.Ease, style, elapsed, start, change, dur)
            if ok and tonumber(v) then return tonumber(v) end
        end
        return (start or 0) + (change or 1) * clamp((elapsed or 0) / math.max(1, dur or 1), 0, 1)
    end
    local function bar(p, width)
        width = math.floor(tonumber(width or 30) or 30)
        local fill = math.floor(width * clamp(p, 0, 1) + 0.5)
        return "[" .. string.rep("█", fill) .. string.rep("░", math.max(0, width-fill)) .. "]"
    end
    local function previewProgress()
        ensureAnim()
        if driftgod.S.r271PreviewStartMs <= 0 then driftgod.S.r271PreviewStartMs = nowMs() end
        local dur = tonumber(driftgod.S.stuntAnimationPreviewDurationMs or 1250) or 1250
        local elapsed = nowMs() - driftgod.S.r271PreviewStartMs
        if elapsed > dur then
            if driftgod.S.r271PreviewLoop == true then driftgod.S.r271PreviewStartMs = nowMs(); elapsed = 0 else elapsed = dur end
        end
        local p = ease(currentAnimName(), elapsed, 0.0, 1.0, dur)
        if driftgod.S.stuntEasingAllowOvershoot == true then p = clamp(p, -0.20, 1.25) else p = clamp(p, 0.0, 1.0) end
        return clamp(p, 0.0, 1.0), elapsed, dur
    end

    function driftgod.R271_RenderAlwaysVisibleAnimationBar()
        ensureAnim()
        local p, elapsed, dur = previewProgress()
        local e = currentAnimEntry()
        child("Animation Preview Bar", function()
            header("Animation Preview Bar")
            t("Animation: " .. tostring(e.label or e.name) .. " | Unlock: " .. tostring(e.unlock or 0) .. " pts")
            t("Loading / Motion: " .. bar(p, 34) .. " " .. tostring(math.floor(p * 100)) .. "%")
            t("Elapsed: " .. tostring(math.floor(elapsed)) .. " / " .. tostring(math.floor(dur)) .. " ms")
            dim("This is the visual guide from the first animation test, now kept at the top of Easing.")
        end)
    end

    local function renderAnimPicker()
        ensureAnim()
        local e = currentAnimEntry()
        local unlocked = getScore() >= tonumber(e.unlock or 0)
        t("Animation: " .. tostring(e.label or e.name) .. "  [" .. tostring(e.unlock or 0) .. " pts] " .. (unlocked and "UNLOCKED" or "LOCKED"))
        if button("< Animation##R271") then
            driftgod.S.stuntAnimationSelectedIndex = driftgod.S.stuntAnimationSelectedIndex - 1
            if driftgod.S.stuntAnimationSelectedIndex < 1 then driftgod.S.stuntAnimationSelectedIndex = animCount() end
            syncAnimToStunts(); driftgod.S.r271PreviewStartMs = nowMs(); saveQuiet()
        end
        same()
        if button("Animation >##R271") then
            driftgod.S.stuntAnimationSelectedIndex = driftgod.S.stuntAnimationSelectedIndex + 1
            if driftgod.S.stuntAnimationSelectedIndex > animCount() then driftgod.S.stuntAnimationSelectedIndex = 1 end
            syncAnimToStunts(); driftgod.S.r271PreviewStartMs = nowMs(); saveQuiet()
        end
        if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
            local opened = false
            driftgod.Try(function() opened = ImGui.BeginCombo("Animation##R271", tostring(e.label or e.name)) end)
            if opened then
                for i, entry in ipairs(driftgod.R271AnimationUnlocks or {}) do
                    local isUnlocked = getScore() >= tonumber(entry.unlock or 0)
                    local display = tostring(entry.label or entry.name) .. "  [" .. tostring(entry.unlock or 0) .. "] " .. (isUnlocked and "UNLOCKED" or "LOCKED")
                    local clicked = false
                    driftgod.Try(function() clicked = ImGui.Selectable(display, i == driftgod.S.stuntAnimationSelectedIndex) end)
                    if clicked then driftgod.S.stuntAnimationSelectedIndex = i; syncAnimToStunts(); driftgod.S.r271PreviewStartMs = nowMs(); saveQuiet() end
                end
                ImGui.EndCombo()
            end
        end
    end
    local function renderStuntPicker()
        ensureAnim()
        local st = currentStuntEntry()
        t("Preview Stunt: " .. tostring(st.name or "Stunt"))
        if button("< Stunt##R271") then driftgod.S.stuntAnimationPreviewIndex = driftgod.S.stuntAnimationPreviewIndex - 1; if driftgod.S.stuntAnimationPreviewIndex < 1 then driftgod.S.stuntAnimationPreviewIndex = stuntCount() end; saveQuiet() end
        same()
        if button("Stunt >##R271") then driftgod.S.stuntAnimationPreviewIndex = driftgod.S.stuntAnimationPreviewIndex + 1; if driftgod.S.stuntAnimationPreviewIndex > stuntCount() then driftgod.S.stuntAnimationPreviewIndex = 1 end; saveQuiet() end
        if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
            local opened = false
            driftgod.Try(function() opened = ImGui.BeginCombo("Stunt##R271", tostring(st.name or "Stunt")) end)
            if opened then
                for i, entry in ipairs(driftgod.R271PreviewStunts or {}) do
