                    if clicked then driftgod.S.stuntAnimationPreviewIndex = i; saveQuiet() end
                end
                ImGui.EndCombo()
            end
        end
    end

    function driftgod.R271_StartStuntAnimationPreview()
        ensureAnim()
        if driftgod.R269_StartStuntAnimationPreview then
            driftgod.S.r269VehiclePreviewStatus = "Running " .. tostring(currentStuntEntry().name or "Stunt") .. " / " .. tostring(currentAnimName())
