                local c = ENTITY.GET_ENTITY_COORDS(ent, true)
                if type(c) == "table" then
                    x = tonumber(c.x or c.X or c[1] or 0.0) or 0.0; y = tonumber(c.y or c.Y or c[2] or 0.0) or 0.0; z = tonumber(c.z or c.Z or c[3] or 72.0) or 72.0
                elseif c then
                    x = tonumber(c.x or c.X or 0.0) or 0.0; y = tonumber(c.y or c.Y or 0.0) or 0.0; z = tonumber(c.z or c.Z or 72.0) or 72.0
                end
            end
        end)
        return x,y,z
    end
    local function getHeading(ent)
        local h=0.0; driftgod.Try(function() if ENTITY and ENTITY.GET_ENTITY_HEADING then h=tonumber(ENTITY.GET_ENTITY_HEADING(ent) or 0.0) or 0.0 end end); return h
    end
    local function offsetFromHeading(x,y,z,h,forward,right,up)
        local rad=math.rad(tonumber(h or 0.0) or 0.0); local sx=math.sin(rad); local cy=math.cos(rad)
        return x + (-sx)*forward + cy*right, y + cy*forward + sx*right, z + (up or 0.0)
    end

    function driftgod.R271_ClearSpawnerGhost(reason)
        local veh = tonumber(driftgod.S.r263SpawnerPreviewVehicle or driftgod.S.r271SpawnerPreviewVehicle or 0) or 0
        if veh ~= 0 then
            driftgod.Try(function() if ENTITY and ENTITY.SET_ENTITY_VISIBLE then ENTITY.SET_ENTITY_VISIBLE(veh, false, false) end end)
            driftgod.Try(function() if ENTITY and ENTITY.SET_ENTITY_COLLISION then ENTITY.SET_ENTITY_COLLISION(veh, false, false) end end)
            driftgod.Try(function() if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end end)
            driftgod.Try(function() if ENTITY and ENTITY.SET_ENTITY_AS_MISSION_ENTITY then ENTITY.SET_ENTITY_AS_MISSION_ENTITY(veh, true, true) end end)
            driftgod.Try(function()
                if ENTITY and ENTITY.DELETE_ENTITY then ENTITY.DELETE_ENTITY(veh)
                elseif entities and entities.delete_by_handle then entities.delete_by_handle(veh) end
            end)
        end
        if tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) == veh then
            driftgod.S.ghostReplayPreviewVehicle = 0
            driftgod.S.ghostReplayPreviewVehicleModel = 0
            driftgod.S.ghostReplayPreviewLabel = ""
        end
        driftgod.S.r263SpawnerPreviewVehicle = 0
        driftgod.S.r271SpawnerPreviewVehicle = 0
        driftgod.S.r263SpawnerPreviewModel = 0
        driftgod.S.r263SpawnerPreviewSpawnedKey = ""
        driftgod.S.r271SpawnerPreviewKey = ""
        driftgod.S.spawnerPreviewStatus = reason and ("Preview cleared: " .. tostring(reason)) or "Preview cleared"
        return true
    end
    driftgod.R263_HideSpawnerPreviewVehicle = driftgod.R271_ClearSpawnerGhost

    function driftgod.R271_PositionSpawnerGhost()
        ensureSpawnerPreview()
        local veh = tonumber(driftgod.S.r263SpawnerPreviewVehicle or driftgod.S.r271SpawnerPreviewVehicle or 0) or 0
        if veh == 0 then return false end
        local ped = getPed(); if ped == 0 then return false end
        local x,y,z = getCoords(ped); local h = getHeading(ped)
        local px,py,pz = offsetFromHeading(x,y,z,h,driftgod.S.spawnerPreviewForwardOffset,driftgod.S.spawnerPreviewRightOffset,driftgod.S.spawnerPreviewZOffset)
        local spin = ((nowMs()/25.0)%360.0)
        driftgod.Try(function()
            if ENTITY and ENTITY.SET_ENTITY_COORDS_NO_OFFSET then ENTITY.SET_ENTITY_COORDS_NO_OFFSET(veh, px, py, pz, false, false, false)
            elseif ENTITY and ENTITY.SET_ENTITY_COORDS then ENTITY.SET_ENTITY_COORDS(veh, px, py, pz, false, false, false, false) end
        end)
        driftgod.Try(function()
            if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh, true) end
            if ENTITY and ENTITY.SET_ENTITY_COLLISION then ENTITY.SET_ENTITY_COLLISION(veh, false, false) end
            if ENTITY and ENTITY.SET_ENTITY_VISIBLE then ENTITY.SET_ENTITY_VISIBLE(veh, true, false) end
            if ENTITY and ENTITY.SET_ENTITY_ALPHA then ENTITY.SET_ENTITY_ALPHA(veh, 145, false) end
        end)
        if driftgod.S.spawnerPreviewRotateEnabled == true then
            driftgod.Try(function() if ENTITY and ENTITY.SET_ENTITY_ROTATION then ENTITY.SET_ENTITY_ROTATION(veh, 0.0, 0.0, spin, 2, true) elseif ENTITY and ENTITY.SET_ENTITY_HEADING then ENTITY.SET_ENTITY_HEADING(veh, spin) end end)
        end
        return true
    end

    function driftgod.R271_SpawnSpawnerPreviewForItem(item)
        ensureSpawnerPreview()
        if not (driftgod.R263_IsSpawnerPreviewable and driftgod.R263_IsSpawnerPreviewable(item)) then return false end
        local key = tostring(item.path or item.displayLabel or item.name or "")
        local existingKey = tostring(driftgod.S.r271SpawnerPreviewKey or driftgod.S.r263SpawnerPreviewSpawnedKey or "")
        local veh = tonumber(driftgod.S.r263SpawnerPreviewVehicle or driftgod.S.r271SpawnerPreviewVehicle or 0) or 0
        if existingKey == key and veh ~= 0 then driftgod.R271_PositionSpawnerGhost(); driftgod.S.spawnerPreviewStatus = "Previewing " .. tostring(item.displayLabel or item.name or "vehicle"); return true end
        if veh ~= 0 then driftgod.R271_ClearSpawnerGhost("selection changed") end
        local model = 0
        if driftgod.R263_ExtractVehicleModelFromJson then model = tonumber((driftgod.R263_ExtractVehicleModelFromJson(item.path)) or 0) or 0 end
        if model == 0 then driftgod.S.spawnerPreviewStatus = "No preview model in JSON: " .. tostring(item.displayLabel or item.name or "vehicle"); return false end
        local ok = false
        driftgod.Try(function() if driftgod.SpawnGhostPreviewVehicleWithModel then ok = driftgod.SpawnGhostPreviewVehicleWithModel(model, "Spawner Preview: " .. tostring(item.displayLabel or item.name or "vehicle")) == true end end)
        veh = tonumber(driftgod.S.ghostReplayPreviewVehicle or 0) or 0
        if ok and veh ~= 0 then
            driftgod.S.r263SpawnerPreviewVehicle = veh
            driftgod.S.r271SpawnerPreviewVehicle = veh
            driftgod.S.r263SpawnerPreviewModel = model
            driftgod.S.r263SpawnerPreviewSpawnedKey = key
            driftgod.S.r271SpawnerPreviewKey = key
            driftgod.S.spawnerPreviewStatus = "Previewing " .. tostring(item.displayLabel or item.name or "vehicle")
            driftgod.R271_PositionSpawnerGhost()
            return true
        end
        driftgod.S.spawnerPreviewStatus = "Preview spawn failed: " .. tostring(item.displayLabel or item.name or "vehicle")
        return false
    end
    driftgod.R263_SpawnSpawnerPreviewForItem = driftgod.R271_SpawnSpawnerPreviewForItem

    function driftgod.R271_TickSpawnerPreview()
        ensureSpawnerPreview()
        if driftgod.S.spawnerPreviewEnabled ~= true then return end
        if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.open == true) then
            if tonumber(driftgod.S.r263SpawnerPreviewVehicle or driftgod.S.r271SpawnerPreviewVehicle or 0) ~= 0 then driftgod.R271_ClearSpawnerGhost("spawner closed") end
            return
        end
        local item = driftgod.R263_SelectedSpawnerPreviewItem and driftgod.R263_SelectedSpawnerPreviewItem() or nil
        if not (driftgod.R263_IsSpawnerPreviewable and driftgod.R263_IsSpawnerPreviewable(item)) then
            if tonumber(driftgod.S.r263SpawnerPreviewVehicle or driftgod.S.r271SpawnerPreviewVehicle or 0) ~= 0 then driftgod.R271_ClearSpawnerGhost("not a json vehicle") end
            driftgod.S.r263SpawnerPreviewSelectedKey = ""
            return
        end
        local key = tostring(item.path or item.displayLabel or item.name or "")
        local now = nowMs()
        if key ~= tostring(driftgod.S.r263SpawnerPreviewSelectedKey or "") then
            if tonumber(driftgod.S.r263SpawnerPreviewVehicle or driftgod.S.r271SpawnerPreviewVehicle or 0) ~= 0 then driftgod.R271_ClearSpawnerGhost("selection changed") end
            driftgod.S.r263SpawnerPreviewSelectedKey = key
            driftgod.S.r263SpawnerPreviewSelectedAt = now
            driftgod.S.spawnerPreviewStatus = "Preview pending: " .. tostring(item.displayLabel or item.name or "vehicle")
            return
        end
        local stableMs = now - (tonumber(driftgod.S.r263SpawnerPreviewSelectedAt or now) or now)
        if stableMs >= tonumber(driftgod.S.spawnerPreviewDelayMs or 550) then driftgod.R271_SpawnSpawnerPreviewForItem(item) end
        if driftgod.S.spawnerPreviewFollowPlayer == true then driftgod.R271_PositionSpawnerGhost() end
    end
    driftgod.R263_TickSpawnerPreview = driftgod.R271_TickSpawnerPreview

    if type(driftgod.VS_SetOpen) == "function" and driftgod.R271_VSSetOpenWrapped ~= true then
        driftgod.R271_VSSetOpenWrapped = true
        local oldSetOpen = driftgod.VS_SetOpen
        driftgod.VS_SetOpen = function(state, ...)
