            if button("Clear Preview##R271") then driftgod.R271_ClearSpawnerGhost("manual clear") end
            t("Status: " .. tostring(driftgod.S.spawnerPreviewStatus or "Ready"))
        end)
    end
    driftgod.R263_RenderSpawnerPreviewControls = driftgod.R271_RenderSpawnerPreviewControls
end)

driftgod.Try(function()
