    function driftgod.R272_StartVehicleAnimationPreview()
        local veh = getCurrentVehicle()
        if veh == 0 then driftgod.S.r272VehiclePreviewStatus = "Enter a vehicle first"; return false end
        if not (Script and Script.QueueJob and Script.Yield) then driftgod.S.r272VehiclePreviewStatus = "Script.QueueJob unavailable"; return false end
        local a = anim(); local st = stunt(); local style = tostring(a.name or "linear")
        driftgod.S.r272VehiclePreviewStatus = "Running " .. tostring(st.name) .. " / " .. style
        Script.QueueJob(function()
            local startPitch,startRoll,startYaw = 0.0,0.0,0.0
            driftgod.Try(function()
                if ENTITY and ENTITY.GET_ENTITY_ROTATION then
                    local rr=ENTITY.GET_ENTITY_ROTATION(veh,2)
                    if type(rr)=="table" then startPitch=tonumber(rr.x or rr.X or rr[1] or 0) or 0; startRoll=tonumber(rr.y or rr.Y or rr[2] or 0) or 0; startYaw=tonumber(rr.z or rr.Z or rr[3] or 0) or 0 end
                end
            end)
            driftgod.Try(function() if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh,true) end end)
            local dur=tonumber(driftgod.S.stuntAnimationPreviewDurationMs or 1400) or 1400; local start=nowMs()
            while nowMs()-start <= dur do
                local elapsed=nowMs()-start; local p=ease(style, elapsed, 0, 1, dur); p=clamp(p,0,1)
                driftgod.Try(function() if ENTITY and ENTITY.SET_ENTITY_ROTATION then ENTITY.SET_ENTITY_ROTATION(veh, startPitch+(tonumber(st.pitch or 0)*p), startRoll+(tonumber(st.roll or 0)*p), startYaw+(tonumber(st.yaw or 0)*p), 2, true) end end)
                Script.Yield(0)
            end
            driftgod.Try(function() if ENTITY and ENTITY.SET_ENTITY_ROTATION then ENTITY.SET_ENTITY_ROTATION(veh,startPitch,startRoll,startYaw,2,true) end; if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(veh,false) end end)
            driftgod.S.r272VehiclePreviewStatus = "Finished " .. tostring(st.name) .. " / " .. style
        end)
        return true
    end

    function driftgod.R272_RenderEasingSubtabs()
        ensure()

        driftgod.R272_RenderPlainAnimationBar()
        renderSubtabButtons()
        local sub = tonumber(driftgod.S.r272EasingSubtab or 1) or 1
        if sub == 1 then
            text("Preview Bar")
            renderAnimPicker()
            driftgod.R272_RenderPlainAnimationBar()
        elseif sub == 2 then
            renderUnlocks()
        elseif sub == 3 then
            text("Stunt Preview")
            renderStuntPicker()
            renderAnimPicker()
            if button("Apply Animation To Real Stunts##R272Apply") then syncToRealStunts() end
            text("Current Real-Stunt Animation: " .. tostring(anim().label or anim().name))
        elseif sub == 4 then
            text("Vehicle Preview")
            text("This uses your current vehicle and previews the selected stunt animation.")
            renderStuntPicker()
            renderAnimPicker()
            if button("Run Vehicle Preview##R272Run") then driftgod.R272_StartVehicleAnimationPreview() end
            text("Preview Status: " .. tostring(driftgod.S.r272VehiclePreviewStatus or driftgod.S.r269VehiclePreviewStatus or "Idle"))
        else
            text("Original Lab")
            if type(previousEasingRenderer) == "function" and previousEasingRenderer ~= driftgod.R272_RenderEasingSubtabs then
                driftgod.Try(previousEasingRenderer)
            else
                text("Original Easing Lab unavailable.")
            end
        end
    end

    driftgod.R260_RenderEasingLab = driftgod.R272_RenderEasingSubtabs
    driftgod.R261_RenderEasingLab = driftgod.R272_RenderEasingSubtabs
    driftgod.R262_RenderEasingPlayground = driftgod.R272_RenderEasingSubtabs
    driftgod.R271_RenderEasingSubtabs = driftgod.R272_RenderEasingSubtabs

    function driftgod.R272_RenderStuntEasingControls()
        text("Stunt Animation")
        text("Current Real-Stunt Animation: " .. tostring(anim().label or anim().name))
        local p = progress()
        text("Animation Preview Bar: " .. makeBar(p, 30) .. " " .. tostring(math.floor(p * 100)) .. "%")
        if button("Apply Current Animation##R272SmallApply") then syncToRealStunts() end
    end
    driftgod.R264_RenderStuntEasingControls = driftgod.R272_RenderStuntEasingControls
    driftgod.R263_RenderStuntEasingControls = driftgod.R272_RenderStuntEasingControls
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"
    driftgod.__ProductionPatch = "R309_ProductBuild_1_0_0"

    local function clamp(v, a, b)
        v = tonumber(v or 0) or 0
        if v < a then return a end
        if v > b then return b end
        return v
    end

    local function nowMs()
        if driftgod.Now then return tonumber(driftgod.Now() or 0) or 0 end
        return math.floor((os.clock() or 0) * 1000)
    end

    local function text(txt)
        if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, tostring(txt or "")) end
    end
    local function sep() if ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end end
    local function same() if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end end
    local function mini(txt, kind)
        if dgMiniText then local ok = driftgod.Try(dgMiniText, tostring(txt or ""), kind); if ok then return end end
        if dgColorText then local ok = driftgod.Try(dgColorText, tostring(txt or ""), kind); if ok then return end end
        text(txt)
    end
    local function header(txt) mini(txt, "header") end
    local function dim(txt) mini(txt, "dim") end
    local function button(label)
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) end) end
        return clicked == true
    end
    local function child(title, fn)
        local opened = false
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, ret = driftgod.Try(ClickGUI.BeginCustomChildWindow, tostring(title or "Section"))
            opened = ok and ret == true
        end
        if opened then
            local ok, err = driftgod.Try(fn)
            if not ok then text("Section error: " .. tostring(err)) end
            if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
        else
            header(title); sep()
            local ok, err = driftgod.Try(fn)
            if not ok then text("Section error: " .. tostring(err)) end
            sep()
        end
    end

    local function saveQuiet()
        if driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
    end

    local function ensureEasing()
        driftgod.EasingNames = driftgod.EasingNames or {
            "linear", "quad_out", "quad_in", "quad_in_out",
            "sine_out", "sine_in", "sine_in_out",
            "cubic_out", "cubic_in", "cubic_in_out",
            "expo_out", "expo_in", "circ_out", "back_out", "bounce_out", "bounce_in"
        }
        driftgod.S.easingLabEnabled = driftgod.S.easingLabEnabled ~= false
        driftgod.S.easingLabStyleIndex = clamp(driftgod.S.easingLabStyleIndex or driftgod.S.stuntEasingStyleIndex or 2, 1, #driftgod.EasingNames)
        driftgod.S.easingPreviewStartMs = tonumber(driftgod.S.easingPreviewStartMs or 0) or 0
        driftgod.S.easingPreviewDurationMs = clamp(driftgod.S.easingPreviewDurationMs or 1400, 500, 3500)
        driftgod.S.easingPreviewLoop = driftgod.S.easingPreviewLoop ~= false
        driftgod.S.r273EasingSubtab = clamp(driftgod.S.r273EasingSubtab or 1, 1, 4)
    end

    local function easingName()
        ensureEasing()
        return tostring((driftgod.EasingNames or {})[driftgod.S.easingLabStyleIndex] or "linear")
    end

    local function setEasingIndex(i)
        ensureEasing()
        i = tonumber(i or 1) or 1
        if i < 1 then i = #driftgod.EasingNames end
        if i > #driftgod.EasingNames then i = 1 end
        driftgod.S.easingLabStyleIndex = i
        driftgod.S.stuntEasingStyleIndex = i
        driftgod.S.stuntAnimationSelectedIndex = i
        driftgod.S.easingPreviewStartMs = nowMs()
        driftgod.S.stuntEasingTestEnabled = true
        saveQuiet()
    end

    function driftgod.R273_RenderOriginalEasingStylePicker()
        ensureEasing()
        local selected = easingName()
        text("Selected: " .. tostring(selected))
        if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
            local opened = false
            driftgod.Try(function() opened = ImGui.BeginCombo("Easing Style##R273OriginalEasingStyle", selected) end)
            if opened then
                for i, name in ipairs(driftgod.EasingNames) do
                    local clicked = false
                    driftgod.Try(function() clicked = ImGui.Selectable(tostring(name), i == driftgod.S.easingLabStyleIndex) end)
                    if clicked then setEasingIndex(i) end
                end
                driftgod.Try(ImGui.EndCombo)
            end
        else
            if button("Previous Style##R273") then setEasingIndex((tonumber(driftgod.S.easingLabStyleIndex or 1) or 1) - 1) end
            same()
            if button("Next Style##R273") then setEasingIndex((tonumber(driftgod.S.easingLabStyleIndex or 1) or 1) + 1) end
        end
        if button("Replay Preview##R273") then driftgod.S.easingPreviewStartMs = nowMs(); saveQuiet() end
        same()
        if button("Loop Preview: " .. ((driftgod.S.easingPreviewLoop ~= false) and "ON" or "OFF") .. "##R273") then
            driftgod.S.easingPreviewLoop = not (driftgod.S.easingPreviewLoop ~= false)
            saveQuiet()
        end
    end

    function driftgod.R273_RenderOriginalAnimatedLoadingBarOnly()
        ensureEasing()
        local duration = tonumber(driftgod.S.easingPreviewDurationMs or 1400) or 1400
        local start = tonumber(driftgod.S.easingPreviewStartMs or 0) or 0
        local now = nowMs()
        if start <= 0 then start = now; driftgod.S.easingPreviewStartMs = start end
        local elapsed = now - start
        if driftgod.S.easingPreviewLoop == true and elapsed > duration then
            start = now
            driftgod.S.easingPreviewStartMs = start
            elapsed = 0
        end
        if elapsed > duration then elapsed = duration end

        local name = easingName()
        local v = 0
        if driftgod.Ease then
            local ok, vv = driftgod.Try(driftgod.Ease, name, elapsed, 0, 1, duration)
            if ok and tonumber(vv) then v = tonumber(vv) end
        else
            v = elapsed / math.max(1, duration)
        end
        v = clamp(v, 0, 1)
        local pct = math.floor(v * 100 + 0.5)
        local raw = math.floor((elapsed / duration) * 100 + 0.5)

        text("Raw time: " .. tostring(raw) .. "%  |  Eased value: " .. tostring(pct) .. "%")
        if ImGui and ImGui.ProgressBar then
            local ok = driftgod.Try(ImGui.ProgressBar, v, 0, 0, tostring(name) .. " preview")
            if not ok then
                local filled = math.floor(v * 20 + 0.5)
                if filled < 0 then filled = 0 end
                if filled > 20 then filled = 20 end
                text("[" .. string.rep("#", filled) .. string.rep("-", 20-filled) .. "] " .. tostring(name) .. " preview")
            end
        else
            local filled = math.floor(v * 20 + 0.5)
            if filled < 0 then filled = 0 end
            if filled > 20 then filled = 20 end
            text("[" .. string.rep("#", filled) .. string.rep("-", 20-filled) .. "] " .. tostring(name) .. " preview")
        end
        sep()
        text("Loading UI:   DRIFTGOD READY  " .. tostring(pct) .. "%")
        text("Tab/Page UI:  Section fade/slide value " .. tostring(pct) .. "%")
        text("Ghost Race:   " .. (v < 0.25 and "3..." or (v < 0.50 and "2..." or (v < 0.75 and "1..." or "GO!"))))
        text("Combo HUD:    " .. tostring(math.max(1, math.floor(1 + v * 4 + 0.5))) .. "x COMBO pop")
        text("Result Card:  " .. (v >= 1 and "YOU WON / DID NOT FINISH ready" or "Result card animating in"))
    end

    local function getScore()
        local score = 0
        driftgod.Try(function() if driftgod.GetArcadeDriftPresetScore then score = tonumber(driftgod.GetArcadeDriftPresetScore() or 0) or 0 end end)
        if score <= 0 then score = tonumber(driftgod.S.bestScore or driftgod.S.highestScore or driftgod.S.todayBestScore or driftgod.S.arcadeBestScore or 0) or 0 end
        return math.max(0, score)
    end

    local function ensureUnlockTables()
        driftgod.R271AnimationUnlocks = driftgod.R271AnimationUnlocks or driftgod.R269AnimationUnlocks or {
            { name = "linear",      unlock = 0,     label = "None / Linear" },
            { name = "quad_out",    unlock = 1000,  label = "Quad Out" },
