    local function renderSubtabButtons()
        ensureEasing()
        local names = { "Preview", "Unlocks", "Stunts", "Vehicle" }
        for i, label in ipairs(names) do
            if i > 1 then same() end
            local on = driftgod.S.r273EasingSubtab == i
            if button((on and "[" .. label .. "]" or label) .. "##R273Sub" .. tostring(i)) then
                driftgod.S.r273EasingSubtab = i
                saveQuiet()
            end
        end
        sep()
    end

    function driftgod.R273_RenderUnlocksNoExtraBar()
        ensureUnlockTables()
        child("Animation Unlocks", function()
            header("Animation Unlocks")
            dim("Every animation is a side-grade. The original Easing bar above is the only preview bar used here.")
            local score = getScore()
            text("Best / Unlock Score: " .. tostring(math.floor(score)))
            sep()
            for _, e in ipairs(driftgod.R271AnimationUnlocks or {}) do
                local unlock = tonumber(e.unlock or 0) or 0
                local unlocked = score >= unlock
                text(tostring(e.label or e.name) .. "  -  " .. tostring(unlock) .. " pts  -  " .. (unlocked and "UNLOCKED" or "LOCKED"))
            end
        end)
    end

    function driftgod.R273_RenderStuntControlsNoExtraBar()
        ensureEasing(); ensureUnlockTables()
        child("Stunt Animation", function()
            header("Stunt Animation")
            dim("Pick the animation above. The original Easing bar above is the only visual timing bar.")
            if button("< Animation##R273Stunt") then setEasingIndex((tonumber(driftgod.S.easingLabStyleIndex or 1) or 1) - 1) end
            same()
            if button("Animation >##R273Stunt") then setEasingIndex((tonumber(driftgod.S.easingLabStyleIndex or 1) or 1) + 1) end
            text("Active Real-Stunt Animation: " .. easingName())
            text("Real stunts: " .. ((driftgod.S.stuntEasingTestEnabled ~= false) and "ON" or "OFF"))
            if button("Apply Current Animation To Real Stunts##R273") then
                driftgod.S.stuntEasingStyleIndex = driftgod.S.easingLabStyleIndex
                driftgod.S.stuntAnimationSelectedIndex = driftgod.S.easingLabStyleIndex
