    function driftgod.R273_RenderVehiclePreviewNoExtraBar()
        ensureUnlockTables()
        child("Vehicle Preview", function()
            header("Vehicle Stunt Preview")
            dim("Uses the selected animation. The original Easing bar above is the only progress guide.")
            local stunts = driftgod.R271PreviewStunts or {}
            driftgod.S.stuntAnimationPreviewIndex = clamp(driftgod.S.stuntAnimationPreviewIndex or 1, 1, math.max(1, #stunts))
            local stunt = stunts[driftgod.S.stuntAnimationPreviewIndex] or { name = "Donut" }
            if button("< Stunt##R273Vehicle") then
                driftgod.S.stuntAnimationPreviewIndex = driftgod.S.stuntAnimationPreviewIndex - 1
                if driftgod.S.stuntAnimationPreviewIndex < 1 then driftgod.S.stuntAnimationPreviewIndex = #stunts end
                saveQuiet()
            end
            same()
            if button("Stunt >##R273Vehicle") then
                driftgod.S.stuntAnimationPreviewIndex = driftgod.S.stuntAnimationPreviewIndex + 1
                if driftgod.S.stuntAnimationPreviewIndex > #stunts then driftgod.S.stuntAnimationPreviewIndex = 1 end
                saveQuiet()
            end
            text("Selected Stunt: " .. tostring(stunt.name or "Donut"))
            text("Selected Animation: " .. easingName())
            if button("Run Vehicle Preview##R273") then
                if driftgod.R271_StartStuntAnimationPreview then driftgod.Try(driftgod.R271_StartStuntAnimationPreview)
                elseif driftgod.R269_StartStuntAnimationPreview then driftgod.Try(driftgod.R269_StartStuntAnimationPreview)
                elseif driftgod.R262_StartVehicleEasingPreview then driftgod.Try(driftgod.R262_StartVehicleEasingPreview) end
            end
            text("Preview Status: " .. tostring(driftgod.S.r269VehiclePreviewStatus or driftgod.S.r262VehiclePreviewStatus or "Idle"))
        end)
    end

    function driftgod.R273_RenderEasingOriginalBarOnly()
        ensureEasing()
        child("Easing Lab", function()
            header("Easing Lab / Visual Motion Preview")
            dim("Using only the original animated loading/progress bar from the first Easing Lab.")
