    function driftgod.R275_ClearPreviewTracking(reason)
        driftgod.S = driftgod.S or {}
        local veh = tonumber(driftgod.S.r263SpawnerPreviewVehicle or driftgod.S.r265SpawnerPreviewVehicle or driftgod.S.r266SpawnerPreviewVehicle or driftgod.S.r267SpawnerPreviewVehicle or driftgod.S.r270SpawnerPreviewVehicle or driftgod.S.r271SpawnerPreviewVehicle or 0) or 0

