    end
    local function sep() if ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end end
    local function color(txt, kind)
        if dgMiniText then local ok = driftgod.Try(dgMiniText, tostring(txt or ""), kind or "white"); if ok then return end end
        if dgColorText then local ok = driftgod.Try(dgColorText, tostring(txt or ""), kind or "white"); if ok then return end end
        if dgA24ColorText then local ok = driftgod.Try(dgA24ColorText, tostring(txt or ""), kind or "white"); if ok then return end end
        t(txt)
    end
    local function fmt(n)
        n = math.floor(tonumber(n or 0) or 0)
        local s = tostring(n)
        while true do
            local ns, k = s:gsub("^(-?%d+)(%d%d%d)", "%1,%2")
            s = ns
            if k == 0 then break end
        end
        return s
    end
    local function score()
        local v = nil
        if driftgod.GetArcadeDriftPresetScore then local ok, r = driftgod.Try(driftgod.GetArcadeDriftPresetScore); if ok and tonumber(r) then v = tonumber(r) end end
        if v == nil and driftgod.GetLifetimeScore then local ok, r = driftgod.Try(driftgod.GetLifetimeScore); if ok and tonumber(r) then v = tonumber(r) end end
        if v == nil then v = tonumber(driftgod.S.bestRunScore or driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore or driftgod.S.arcadeBestScore or 0) or 0 end
        return math.max(0, math.floor(v))
    end

    driftgod.R278_PTFXEffectUnlocks = driftgod.R278_PTFXEffectUnlocks or {
        ["Flame"] = 3000,
        ["Flare Trail"] = 3000,
        ["Flare Fuse FP"] = 8000,
        ["Torch Fire"] = 8000,
        ["Bomb Gas"] = 15000,
        ["Stunts Shotburst Spawn"] = 25000,
        ["Peeing"] = 40000,
        ["Foundry Molten Pour"] = 40000,
        ["Powerplay Beast Appear Trails"] = 60000,
        ["Clown Death"] = 80000,
        ["Clown Trails"] = 100000,
    }

    driftgod.R278_PTFXLocationUnlocks = driftgod.R278_PTFXLocationUnlocks or {
        exhaust = 3000,
        wheels = 15000,
        taillights = 25000,
    }

    function driftgod.R278_GetPTFXEffectRequirement(fx)
        local label = tostring((fx and fx.label) or "")
        return tonumber((driftgod.R278_PTFXEffectUnlocks or {})[label] or 100000) or 100000
    end

    function driftgod.R278_GetUnlockedPTFXEffects()
        local out = {}
        local s = score()
        local effects = driftgod.PTFX and driftgod.PTFX.effects or {}
        for i, fx in ipairs(effects) do
            local req = driftgod.R278_GetPTFXEffectRequirement(fx)
            if s >= req then
                table.insert(out, {
                    label = tostring(fx.label or ("Effect " .. tostring(i))),
                    req = req,
                    originalIndex = i,
                    fx = fx
                })
            end
        end
        return out, s
    end

    function driftgod.R278_IsPTFXEffectUnlocked(indexOrFx)
        local s = score()
        local fx = nil
        if type(indexOrFx) == "number" then
            fx = driftgod.PTFX and driftgod.PTFX.effects and driftgod.PTFX.effects[indexOrFx] or nil
        else
            fx = indexOrFx
        end
        return fx ~= nil and s >= driftgod.R278_GetPTFXEffectRequirement(fx), driftgod.R278_GetPTFXEffectRequirement(fx), s
    end

    function driftgod.R278_EnsurePTFXSelection()
        driftgod.S = driftgod.S or {}
        local unlocked = driftgod.R278_GetUnlockedPTFXEffects()
        if #unlocked <= 0 then
            driftgod.S.ptfxSelectedIndex = 1
            if driftgod.S.ptfxRunning == true and driftgod.StopPTFX then driftgod.Try(driftgod.StopPTFX) end
            driftgod.S.ptfxRunning = false
            return false
        end

        local idx = tonumber(driftgod.S.ptfxSelectedIndex or 1) or 1
        local ok = driftgod.R278_IsPTFXEffectUnlocked(idx)
        if ok then return true end

        driftgod.S.ptfxSelectedIndex = tonumber(unlocked[1].originalIndex or 1) or 1
        driftgod.S._r143PtfxSelectionDirty = true
        return true
    end

    local function currentVisibleEffectIndex(unlocked)
        local selected = tonumber(driftgod.S.ptfxSelectedIndex or 1) or 1
        for i, item in ipairs(unlocked or {}) do
            if tonumber(item.originalIndex or 0) == selected then return i end
        end
        return 1
    end

    local function locationLabel(loc)
        loc = tostring(loc or "exhaust")
        if loc == "wheels" then return "Wheels" end
        if loc == "taillights" then return "Rear Taillights" end
        return "Exhaust"
    end

    local function unlockedLocations()
        local s = score()
        local all = {
            { label = "Exhaust", value = "exhaust", req = 3000 },
            { label = "Wheels", value = "wheels", req = 15000 },
            { label = "Rear Taillights", value = "taillights", req = 25000 },
        }
