        local opened = false
        if ImGui and ImGui.BeginCombo then driftgod.Try(function() opened = ImGui.BeginCombo(label, tostring(preview or "Select")) end) end
        if opened then
            for i, item in ipairs(items or {}) do
                local clicked = false
                local itemLabel = tostring(item.label or item.name or item[1] or item)
                local selected = item.selected == true
                driftgod.Try(function() clicked = ImGui.Selectable(itemLabel, selected) end)
                if clicked and onSelect then onSelect(i, item) end
            end
            driftgod.Try(function() ImGui.EndCombo() end)
        else
            t(tostring(label) .. ": " .. tostring(preview or "None"))
        end
    end

