            local ok = driftgod.Try(dgMiniFeature, hash, label)
            if ok then return end
        end
        if label then t(tostring(label)) end
    end

    function driftgod.R278_RenderPTFXBeta()
        if driftgod.R140_RegisterBetaFeatures then driftgod.Try(driftgod.R140_RegisterBetaFeatures) end
        driftgod.S = driftgod.S or {}
        driftgod.S.ptfxSelectedIndex = tonumber(driftgod.S.ptfxSelectedIndex or 1) or 1

        local unlocked, s = driftgod.R278_GetUnlockedPTFXEffects()
        local locs = unlockedLocations()

        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("PTFX") then
            color("PTFX", "header")
