            if #unlocked <= 0 then
                color("No PTFX effects unlocked yet.", "warning")
                color("First PTFX unlock: 3,000 points.", "dim")
                if driftgod.S.ptfxRunning == true and driftgod.R140_SetPTFXEnabled then driftgod.Try(driftgod.R140_SetPTFXEnabled, false) end
                if ClickGUI.EndCustomChildWindow then ClickGUI.EndCustomChildWindow() end
                return
            end

            driftgod.R278_EnsurePTFXSelection()
            ensureLocation()

            renderFeature(driftgod.H and driftgod.H.R140_PTFXEnabled, "Enable PTFX")

            local visibleIndex = currentVisibleEffectIndex(unlocked)
            local current = unlocked[visibleIndex] or unlocked[1]
            combo("PTFX Effect", current and current.label or "None", unlocked, function(_, item)
                driftgod.S.ptfxSelectedIndex = tonumber(item.originalIndex or 1) or 1
                driftgod.S._r143PtfxSelectionDirty = true
            end)

            if current then
                color("Unlocked: " .. tostring(current.label) .. " at " .. fmt(current.req) .. " points.", "dim")
            end

            local curLoc = tostring(driftgod.S.ptfxLocation or (locs[1] and locs[1].value or "exhaust"))
            local curLocLabel = locationLabel(curLoc)
            combo("PTFX Location", curLocLabel, locs, function(_, item)
                driftgod.S.ptfxLocation = tostring(item.value or "exhaust")
                driftgod.S._r143PtfxSelectionDirty = true
            end)

            if #locs > 0 then
                local nextReq = nil
                local locationRows = {
                    { label = "Wheels", req = 15000 },
                    { label = "Rear Taillights", req = 25000 },
                }
                for _, row in ipairs(locationRows) do
                    if s < row.req then nextReq = row; break end
                end
                if nextReq then color("Next PTFX location: " .. nextReq.label .. " at " .. fmt(nextReq.req) .. " points.", "dim") end
            end

            if driftgod.S._r143PtfxSelectionDirty == true and driftgod.S.ptfxRunning == true then
                color("Selection changed. Toggle Enable PTFX OFF/ON to apply.", "warning")
            end

            if ClickGUI.EndCustomChildWindow then ClickGUI.EndCustomChildWindow() end
        end
    end

    driftgod.R140_RenderPTFXBeta = driftgod.R278_RenderPTFXBeta

    local oldR140SetPTFXEnabled = driftgod.R140_SetPTFXEnabled
    if type(oldR140SetPTFXEnabled) == "function" and driftgod.R278_PTFXToggleWrapped ~= true then
        driftgod.R278_PTFXToggleWrapped = true
        driftgod.R140_SetPTFXEnabled = function(enabled, ...)
