        end
    end

    local oldStart = driftgod.StartPTFX
    if type(oldStart) == "function" and driftgod.R278_StartPTFXWrapped ~= true then
        driftgod.R278_StartPTFXWrapped = true
        driftgod.StartPTFX = function(...)
            if not driftgod.R278_EnsurePTFXSelection() then
                if driftgod.Toast then driftgod.Toast("No PTFX effects unlocked yet.", 2000) end
                driftgod.S.ptfxRunning = false
                return false
            end
            ensureLocation()
            return oldStart(...)
        end
    end

    local function cycleUnlocked(delta)
        local unlocked = driftgod.R278_GetUnlockedPTFXEffects()
        if #unlocked <= 0 then
            if driftgod.Toast then driftgod.Toast("No PTFX effects unlocked yet.", 2000) end
            return false
        end
        local vi = currentVisibleEffectIndex(unlocked)
        vi = vi + delta
        if vi < 1 then vi = #unlocked end
        if vi > #unlocked then vi = 1 end
        driftgod.S.ptfxSelectedIndex = tonumber(unlocked[vi].originalIndex or 1) or 1
        if driftgod.S.ptfxRunning == true and driftgod.StartPTFX then driftgod.Try(driftgod.StartPTFX) end
        return true
    end

    driftgod.NextPTFX = function() return cycleUnlocked(1) end
    driftgod.PreviousPTFX = function() return cycleUnlocked(-1) end
