            local ok = driftgod.Try(ClickGUI.RenderFeature, hash)
            if ok then return end
        end
        if hash and dgMiniFeature then
            local ok = driftgod.Try(dgMiniFeature, hash, label)
            if ok then return end
        end
        if label then txt(tostring(label)) end
    end

    local function combo(label, preview, items, onSelect)
        if not (ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo) then
            txt(tostring(label) .. ": " .. tostring(preview or "None"))
            return
        end

        local opened = false
        driftgod.Try(function() opened = ImGui.BeginCombo(tostring(label), tostring(preview or "Select")) end)
        if opened then
            for i, item in ipairs(items or {}) do
                local clicked = false
                local selected = tostring(item.value) == tostring(driftgod.S.superDriveDirection or "vehicle")
                driftgod.Try(function() clicked = ImGui.Selectable(tostring(item.label or item.value or item), selected) end)
                if clicked and onSelect then onSelect(i, item) end
            end
            driftgod.Try(function() ImGui.EndCombo() end)
        end
    end

    function driftgod.R279_RenderSuperDriveBeta()
        if driftgod.R140_RegisterBetaFeatures then driftgod.Try(driftgod.R140_RegisterBetaFeatures) end
        driftgod.S = driftgod.S or {}
        local s = score()

        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("SuperDrive (BETA)") then
            color("SuperDrive (BETA)", "header")
            red("WARNING: Recommended NOT to use. This is unstable and can crash your game.")
            red("Use only for testing, and avoid switching modes quickly.")
            sep()

            txt(tostring(driftgod.SuperDriveStatus and driftgod.SuperDriveStatus() or "SuperDrive: loading"))
            txt("Unlock Score: " .. fmt(s))

            if s < 50000 then
                driftgod.S.superDriveEnabled = false
                color("Locked: SuperDrive unlocks at 50,000 points.", "warning")
                color("Mode unlocks: Vehicle 50,000 | WASD 60,000 | Cam 70,000.", "dim")
                if ClickGUI.EndCustomChildWindow then ClickGUI.EndCustomChildWindow() end
                return
            end

            driftgod.R279_EnsureAllowedSuperDriveMode()

            renderFeature(driftgod.H.SuperDriveOptionToggle, "SuperDrive")
            renderFeature(driftgod.H.SuperDriveToggle, "Toggle SuperDrive")

            local modes = modeList()
            local curMode = tostring(driftgod.S.superDriveDirection or "vehicle")
            combo("SuperDrive Mode", modeLabel(curMode), modes, function(_, item)
                local value = tostring(item.value or "vehicle")
                if value == "vehicle" and driftgod.SetSuperDriveDirectionVehicle then driftgod.SetSuperDriveDirectionVehicle()
                elseif value == "wasd" and driftgod.SetSuperDriveDirectionWASD then driftgod.SetSuperDriveDirectionWASD()
                elseif value == "camera" and driftgod.SetSuperDriveDirectionCamera then driftgod.SetSuperDriveDirectionCamera()
                end
            end)

            local nextMode = nil
            if s < 60000 then nextMode = "WASD unlocks at 60,000 points."
            elseif s < 70000 then nextMode = "Cam unlocks at 70,000 points." end
            if nextMode then color(nextMode, "dim") end

            sep()
            txt("Speed / Acceleration")
            renderFeature(driftgod.H.R140_SuperDriveSpeed, "Speed")
            renderFeature(driftgod.H.R140_SuperDriveAccel, "Acceleration")
            color("Mode unlocks: Vehicle 50,000 | WASD 60,000 | Cam 70,000.", "dim")
            if ClickGUI.EndCustomChildWindow then ClickGUI.EndCustomChildWindow() end
        end
    end

    function driftgod.R279_RenderRoadSurfaceBeta()
        if driftgod.R140_RegisterBetaFeatures then driftgod.Try(driftgod.R140_RegisterBetaFeatures) end

        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Road Surface / Grip (BETA)") then
            color("Road Surface / Grip (BETA)", "header")
            red("WARNING: Recommended NOT to use. Grip/Road Surface is experimental and can crash your game.")
            red("Use only for testing. Turn it OFF if the session starts acting unstable.")
            sep()
            renderFeature(driftgod.H.R187_RoadSurfaceToggle, "Road Surface / Grip")

            if driftgod.S.roadSurfaceEnabled == true then
                txt("Grip: " .. tostring(driftgod.R140_SurfaceGripLabel and driftgod.R140_SurfaceGripLabel() or "Unknown"))
                renderFeature(driftgod.H.R140_SurfaceGrip, "Grip")
                color("100 = Normal | 50 = Low Grip | 25 = Ice | 0 = Zero Traction", "dim")
            else
                txt("Grip changes are off.")
            end

            if ClickGUI.EndCustomChildWindow then ClickGUI.EndCustomChildWindow() end
        end
    end

    driftgod.R140_RenderSuperDriveBeta = driftgod.R279_RenderSuperDriveBeta
    driftgod.R140_RenderRoadSurfaceBeta = driftgod.R279_RenderRoadSurfaceBeta

    driftgod.R102_RenderBeta = function()
        if driftgod.R140_RenderPTFXBeta then driftgod.R140_RenderPTFXBeta() end
        driftgod.R279_RenderSuperDriveBeta()
        driftgod.R279_RenderRoadSurfaceBeta()
    end
    renderBeta = driftgod.R102_RenderBeta
end)

