driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"
    driftgod.__ProductionPatch = "R309_ProductBuild_1_0_0"

    local RESET_ID = "default_drifting"
    local DRIFTGOD_ID = "corner_magnet"

    driftgod.S.r282AutoRestoreMostRecentPreset = driftgod.S.r282AutoRestoreMostRecentPreset ~= false
    driftgod.S.r282AutoApplyNewPresetUnlocks = driftgod.S.r282AutoApplyNewPresetUnlocks ~= false

    local function nowStamp()
        if os and os.time then return os.time() end
        if driftgod.Now then local ok, v = driftgod.Try(driftgod.Now); if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end end
        return 0
    end

    local function lower(s) return tostring(s or ""):lower() end

    local function isResetId(id)
        id = tostring(id or "")
        return id == RESET_ID or id == "reset" or id == "Default Drifting" or id == "Reset"
    end

    local function isDriftGodId(id, name)
        local lid = lower(id)
        local lname = lower(name)
        return lid == "corner_magnet" or lid == "driftgod" or lname == "driftgod"
    end

    local function score()
        driftgod.S = driftgod.S or {}
        if driftgod.GetArcadeDriftPresetScore then
            local ok, v = driftgod.Try(driftgod.GetArcadeDriftPresetScore)
            if ok and tonumber(v) then return math.floor(math.max(0, tonumber(v) or 0)) end
        end
        local best = tonumber(driftgod.S.bestRunScore or driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore or 0) or 0
        local cur = tonumber(driftgod.S.currentScore or driftgod.S.arcadeRunScore or 0) or 0
        if cur > best then best = cur end
        if best < 0 then best = 0 end
        return math.floor(best)
    end

    local function presetById(id)
        id = tostring(id or "")
        if id == "" then return nil end
        if driftgod.GetArcadeDriftPresetById then
            local ok, p = driftgod.Try(driftgod.GetArcadeDriftPresetById, id)
            if ok and type(p) == "table" then return p end
        end
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            if tostring(p.id or "") == id then return p end
        end
        return nil
    end

    local function displayNameForPreset(id, p)
        id = tostring(id or "")
        if isResetId(id) then return "Reset" end
        p = p or presetById(id)
        local name = tostring((p and (p.name or p.id)) or id or "Preset")
        if isDriftGodId(id, name) then return "DriftGod" end
        if name == "Default Drifting" then return "Reset" end
        return name:gsub("DriftGod Wide Angle", "Wide Angle")
    end

    local function isPresetUsable(id, p)
        id = tostring(id or "")
        if id == "" then return false end
        if isResetId(id) then return true end
        p = p or presetById(id)
        if not p then return false end

        if driftgod.IsArcadeDriftPresetUnlocked then
            local ok, unlocked = driftgod.Try(driftgod.IsArcadeDriftPresetUnlocked, id)
            if ok then return unlocked == true end
        end

        if driftgod.IsArcadeDriftPresetTrialAvailable then
            local ok, trial = driftgod.Try(driftgod.IsArcadeDriftPresetTrialAvailable, id)
            if ok and trial == true then return true end
        end

        local s = score()
        if isDriftGodId(id, p.name) then
            local trialUntil = tonumber(p.trial_until or 0) or 0
            local need = tonumber(p.unlock or 100000) or 100000
            return (trialUntil > 0 and s < trialUntil and s < need) or s >= need
        end
        return s >= (tonumber(p.unlock or 0) or 0)
    end

    function driftgod.R282_SaveMostRecentPresetChoice(mode, idOrName, name, saveNow)
        driftgod.S = driftgod.S or {}
        mode = tostring(mode or "builtin")
        idOrName = tostring(idOrName or "")
        name = tostring(name or idOrName)
        if idOrName == "" then return false end

        driftgod.S.r282MostRecentPresetMode = mode
        driftgod.S.r282MostRecentPresetId = mode == "builtin" and idOrName or ""
        driftgod.S.r282MostRecentCustomPresetName = mode == "custom" and idOrName or ""
        driftgod.S.r282MostRecentPresetName = name
        driftgod.S.r282MostRecentPresetSavedAt = nowStamp()

        driftgod.S.savedStartupPresetMode = mode
        driftgod.S.savedStartupPresetDisplayName = name
        driftgod.S.savedStartupPresetUserSelected = true
        driftgod.S.savedStartupPresetSavedAt = driftgod.S.r282MostRecentPresetSavedAt
        if mode == "custom" then
            driftgod.S.savedStartupCustomPresetName = idOrName
            driftgod.S.savedStartupPresetId = ""
            driftgod.S.r246SavedCustomPresetName = idOrName
            driftgod.S.activeStartupPreset = name
        else
            local id = isDriftGodId(idOrName, name) and DRIFTGOD_ID or idOrName
            driftgod.S.savedStartupPresetId = id
            driftgod.S.savedStartupCustomPresetName = ""
            driftgod.S.r246SavedBuiltinPresetId = id
            driftgod.S.activeStartupPreset = name
            if not isResetId(id) then driftgod.S.activeArcadeDriftPreset = id end
        end

        if saveNow == true and not driftgod.__R282ApplyingQuietNoSave and not driftgod.__R246ApplyingStartupPreset then
            if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
        end
        return true
    end

    local oldApplyArcade = driftgod.ApplyArcadeDriftPreset
    if type(oldApplyArcade) == "function" and driftgod.__R282ApplyArcadeWrapped ~= true then
        driftgod.__R282ApplyArcadeWrapped = true
        driftgod.ApplyArcadeDriftPreset = function(id, showToast, ...)
            if isResetId(id) then
                if driftgod.ApplyResetPreset then return driftgod.ApplyResetPreset(false) end
            end
            local result = oldApplyArcade(id, showToast, ...)
            if result ~= false and not driftgod.__R282ApplyingQuietNoSave and not driftgod.__R246ApplyingStartupPreset and not driftgod.__R246ApplyingCustomPreset then
                local p = presetById(id)
                local finalId = isDriftGodId(id, p and p.name) and DRIFTGOD_ID or tostring(id or "")
                if finalId ~= "" then
                    driftgod.R282_SaveMostRecentPresetChoice("builtin", finalId, displayNameForPreset(finalId, p), true)
                end
            end
            return result
        end
    end

    local oldApplyReset = driftgod.ApplyResetPreset
    if type(oldApplyReset) == "function" and driftgod.__R282ApplyResetWrapped ~= true then
        driftgod.__R282ApplyResetWrapped = true
        driftgod.ApplyResetPreset = function(showToast, ...)
            local result = oldApplyReset(false, ...)
            if result ~= false and not driftgod.__R282ApplyingQuietNoSave and not driftgod.__R246ApplyingStartupPreset then
                driftgod.R282_SaveMostRecentPresetChoice("builtin", RESET_ID, "Reset", true)
            end
            return result
        end
    end

    function driftgod.R282_ApplyBuiltinPresetQuiet(id, reason, saveRecent)
        id = tostring(id or "")
        if id == "" then return false end
        local p = presetById(id)
        if not isResetId(id) and not isPresetUsable(id, p) then return false end

        driftgod.__R282ApplyingQuietNoSave = true
        local ok, result = false, false
        if isResetId(id) then
            if driftgod.ApplyResetPreset then ok, result = driftgod.Try(driftgod.ApplyResetPreset, false) end
        elseif driftgod.ApplyArcadeDriftPreset then
            ok, result = driftgod.Try(driftgod.ApplyArcadeDriftPreset, id, false)
        end
        driftgod.__R282ApplyingQuietNoSave = false

        if ok and result ~= false then
            local name = displayNameForPreset(id, p)
            if isResetId(id) then
                driftgod.S.activeArcadeDriftPreset = RESET_ID
                driftgod.S.r198BaseTuningPreset = RESET_ID
                name = "Reset"
            else
                driftgod.S.activeArcadeDriftPreset = id
                driftgod.S.r198BaseTuningPreset = id
            end
            driftgod.S.activeStartupPreset = name
            driftgod.S.arcadePresetRuntimeEnabled = true
            if saveRecent == true then driftgod.R282_SaveMostRecentPresetChoice("builtin", id, name, true) end
            if driftgod.R245RefreshTuningSliderCaps then driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false) end
            return true
        end
        return false
    end

    function driftgod.R282_RestoreMostRecentPreset(reason)
        if driftgod.S.r282AutoRestoreMostRecentPreset == false then return false end

        local mode = tostring(driftgod.S.r282MostRecentPresetMode or driftgod.S.savedStartupPresetMode or "")
        if mode == "custom" and driftgod.R246_ApplySavedStartupPreset then
            local oldFlag = driftgod.__R282ApplyingQuietNoSave
            driftgod.__R282ApplyingQuietNoSave = true
            local ok, ret = driftgod.Try(driftgod.R246_ApplySavedStartupPreset, "R282 custom restore")
            driftgod.__R282ApplyingQuietNoSave = oldFlag
            return ok and ret == true
        end

        local candidates = {
            driftgod.S.r282MostRecentPresetId,
            driftgod.S.savedStartupPresetId,
            driftgod.S.r246SavedBuiltinPresetId,
            driftgod.S.activeArcadeDriftPreset,
            driftgod.S.r198BaseTuningPreset,
        }

        for _, id in ipairs(candidates) do
            id = tostring(id or "")
            if id ~= "" and driftgod.R282_ApplyBuiltinPresetQuiet(id, tostring(reason or "restore"), false) then
                return true
            end
        end

        if driftgod.R246_ApplySavedStartupPreset then
            local oldFlag = driftgod.__R282ApplyingQuietNoSave
            driftgod.__R282ApplyingQuietNoSave = true
            local ok, ret = driftgod.Try(driftgod.R246_ApplySavedStartupPreset, "R282 fallback restore")
            driftgod.__R282ApplyingQuietNoSave = oldFlag
            return ok and ret == true
        end

        return false
    end

    local function highestUnlockedPreset()
        local s = score()
        local best, bestNeed = nil, -1
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            local id = tostring(p.id or "")
            local need = tonumber(p.unlock or 0) or 0
            if id ~= "" and need > 0 and s >= need and not isResetId(id) then

                if need > bestNeed then
                    best = p
                    bestNeed = need
                end
            end
        end
        return best, bestNeed, s
    end

    function driftgod.R282_CheckNewPresetUnlocks(reason)
        if driftgod.S.r282AutoApplyNewPresetUnlocks == false then return false end

        local p, need, s = highestUnlockedPreset()
        if not p then
            if driftgod.S.r282PresetUnlockBaselineReady ~= true then
                driftgod.S.r282PresetUnlockBaselineReady = true
                driftgod.S.r282HighestSeenPresetUnlockScore = tonumber(driftgod.S.r282HighestSeenPresetUnlockScore or 0) or 0
            end
            return false
        end

        need = tonumber(need or 0) or 0
        local seen = tonumber(driftgod.S.r282HighestSeenPresetUnlockScore or 0) or 0

        if driftgod.S.r282PresetUnlockBaselineReady ~= true then
            driftgod.S.r282PresetUnlockBaselineReady = true
            driftgod.S.r282HighestSeenPresetUnlockScore = math.max(seen, need)
            driftgod.S.r282HighestSeenPresetUnlockId = tostring(p.id or "")
            return false
        end

        if need > seen then
            local id = tostring(p.id or "")
            if id ~= "" and driftgod.R282_ApplyBuiltinPresetQuiet(id, "new unlock", true) then
                driftgod.S.r282HighestSeenPresetUnlockScore = need
                driftgod.S.r282HighestSeenPresetUnlockId = id
                driftgod.S.r282LastAutoAppliedPresetId = id
                driftgod.S.r282LastAutoAppliedPresetName = displayNameForPreset(id, p)
                driftgod.S.r282LastAutoAppliedPresetScore = s
                driftgod.S.r282LastAutoAppliedPresetAt = nowStamp()
                if driftgod.SaveProgress then driftgod.Try(function() driftgod.SaveProgress(false) end) end
                return true
            end
        elseif need > 0 and seen < need then
            driftgod.S.r282HighestSeenPresetUnlockScore = need
            driftgod.S.r282HighestSeenPresetUnlockId = tostring(p.id or "")
        end

        return false
    end

    driftgod.ApplyAutoArcadeDriftPresetStage = function(...)
        return driftgod.R282_CheckNewPresetUnlocks("legacy auto-stage")
    end

    driftgod.Try(function() driftgod.R282_RestoreMostRecentPreset("post-load") end)

    if false and not driftgod.__R282AutoPresetLoopInstalled and Script and Script.RegisterLooped then
        driftgod.__R282AutoPresetLoopInstalled = true
        Script.RegisterLooped(function()
            if Script and Script.Yield then Script.Yield(3000) end
            driftgod.Try(function()
                if ShouldUnload and ShouldUnload() then return false end
                if driftgod.R282_RestoreMostRecentPreset and driftgod.S.r282RestoreChecked ~= true then
                    driftgod.S.r282RestoreChecked = true
                    driftgod.R282_RestoreMostRecentPreset("loop first restore")
                end
                if driftgod.R282_CheckNewPresetUnlocks then driftgod.R282_CheckNewPresetUnlocks("loop") end
            end)
        end)
    end
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"
    driftgod.__ProductionPatch = "R309_ProductBuild_1_0_0"

    local function text(msg, color)
        msg = tostring(msg or "")
        if dgMiniText then local ok = driftgod.Try(dgMiniText, msg, color or "white"); if ok then return end end
        if dgColorText then local ok = driftgod.Try(dgColorText, msg, color or "white"); if ok then return end end
        if dgA38Text then local ok = driftgod.Try(dgA38Text, msg, color or "white"); if ok then return end end
        if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, msg) end
    end

    local function sep()
        if dgMiniSep then local ok = driftgod.Try(dgMiniSep); if ok then return end end
        if ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end
    end

    local function same()
        if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end
    end

    local function feature(hash, label)
        if hash and dgMiniFeature then local ok = driftgod.Try(dgMiniFeature, hash, label); if ok then return true end end
        if hash and renderFeatureSafe then local ok = driftgod.Try(renderFeatureSafe, hash, label); if ok then return true end end
        if hash and ClickGUI and ClickGUI.RenderFeature then local ok = driftgod.Try(ClickGUI.RenderFeature, hash); if ok then return true end end
        if label and label ~= "" then text(tostring(label), "dim") end
        return false
    end

    local function row(a, alabel, b, blabel)
        feature(a, alabel)
        if b then same(); feature(b, blabel) end
    end

    local function panel(title, sub, body)
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local okBegin = false
            driftgod.Try(function() okBegin = ClickGUI.BeginCustomChildWindow(tostring(title or "Section")) == true end)
            if okBegin then
                if sub and tostring(sub) ~= "" then text(sub, "dim"); sep() end
                local ok, err = driftgod.Try(body)
                if ok ~= true then text("Ghost/Race section failed: " .. tostring(err), "red") end
                driftgod.Try(ClickGUI.EndCustomChildWindow)
            end
        else
            text(title, "header")
            if sub and tostring(sub) ~= "" then text(sub, "dim") end
            sep()
            local ok, err = driftgod.Try(body)
            if ok ~= true then text("Ghost/Race section failed: " .. tostring(err), "red") end
            sep()
        end
    end

    local function num(v)
        v = tonumber(v or 0) or 0
        if dgA38Num then local ok, n = driftgod.Try(dgA38Num, v); if ok then return tostring(n) end end
