driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}; driftgod.VS = driftgod.VS or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"
    driftgod.__ProductionPatch = "R309_ProductBuild_1_0_0"

    local function text(msg, color)
        msg = tostring(msg or "")
        color = tostring(color or "white")
        if dgMiniText then local ok = driftgod.Try(dgMiniText, msg, color); if ok then return end end
        if dgColorText then local ok = driftgod.Try(dgColorText, msg, color); if ok then return end end
        if dgA38Text then local ok = driftgod.Try(dgA38Text, msg, color); if ok then return end end
        if ImGui and ImGui.TextColored and color == "orange" then
            local ok = driftgod.Try(ImGui.TextColored, 1.00, 0.58, 0.12, 1.00, msg)
            if ok then return end
        end
        if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, msg) end
    end

    local function orangeHotkeyHint() return false end

    local function sep()
        if dgMiniSep then local ok = driftgod.Try(dgMiniSep); if ok then return end end
        if ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end
    end

    local function same()
        if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end
    end

    local function child(name)
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, open = driftgod.Try(ClickGUI.BeginCustomChildWindow, tostring(name or "Section"))
            return ok and open == true
        end
        text(name, "header")
        return true
    end

    local function endChild()
        if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
    end

    local function feature(hash, label)
        if hash and dgMiniFeature then local ok = driftgod.Try(dgMiniFeature, hash, label); if ok then return true end end
        if hash and renderFeatureSafe then local ok = driftgod.Try(renderFeatureSafe, hash, label); if ok then return true end end
        if hash and ClickGUI and ClickGUI.RenderFeature then local ok = driftgod.Try(ClickGUI.RenderFeature, hash); if ok then return true end end
        if label then text(label, "dim") end
        return false
    end

    local function button(label, cb)
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) == true end) end
        if clicked and type(cb) == "function" then driftgod.Try(cb) end
        return clicked
    end

    local function fmt(n)
        n = tonumber(n or 0) or 0
        if dgA38Num then local ok, v = driftgod.Try(dgA38Num, n); if ok then return tostring(v) end end
        if n >= 1000000 then return string.format("%.1fm", n / 1000000) end
        if n >= 1000 then return string.format("%.1fk", n / 1000) end
        return tostring(math.floor(n))
    end

    local function shortText(value, maxLen)
        local s = tostring(value or "")
        maxLen = tonumber(maxLen or 24) or 24
        s = s:gsub("DriftGod Wide Angle", "Wide Angle")
             :gsub("Speed %+ Control", "Speed+Control")
             :gsub("High Speed Sweep", "Speed Sweep")
             :gsub("Touge Rebuild", "Touge")
             :gsub("Runway King", "Runway")
             :gsub("Velocity Arc", "Velocity")
             :gsub("Apex Runner", "Apex")
             :gsub("Corner Magnet", "DriftGod")
             :gsub("Unlock more in Arcade > Drift Presets%.%s*", "")
             :gsub(" Best Run score", " BR")
             :gsub(" Best Run", " BR")
             :gsub("Only ", "")
             :gsub(" needed for ", " → ")
             :gsub("Current Preset:%s*", "")
             :gsub("Preset:%s*", "")
        if #s > maxLen then return string.sub(s, 1, math.max(1, maxLen - 1)) .. "…" end
        return s
    end

    local function bestRunScore()
        if driftgod.GetArcadeDriftPresetScore then
            local ok, v = driftgod.Try(driftgod.GetArcadeDriftPresetScore)
            if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
        end
        driftgod.S = driftgod.S or {}
        return math.floor(math.max(
            tonumber(driftgod.S.bestRunScore or 0) or 0,
            tonumber(driftgod.S.bestScore or 0) or 0,
            tonumber(driftgod.S.highScore or 0) or 0,
            tonumber(driftgod.S.highestScore or 0) or 0,
            tonumber(driftgod.S.currentScore or 0) or 0,
            0
        ))
    end

    local function nextUnlockCompact()
        local candidates = {}
        local score = bestRunScore()
        local function add(category, name, req)
            req = tonumber(req or 0) or 0
            if req > score then table.insert(candidates, { category=category, name=name, req=req }) end
        end
        if driftgod.GetNextLockedArcadeDriftPreset then
            local ok, p, need = driftgod.Try(driftgod.GetNextLockedArcadeDriftPreset)
            if ok and p then add("Preset", p.name or p.id or "Preset", need or p.unlock or p.score) end
        end
        add("Utility", "DriftGod Plate", 100)
        add("PTFX", "PTFX Starter", 3000)
        add("Utility", "Traffic Reduce", 15000)
        add("Utility", "Clear Traffic", 50000)
        table.sort(candidates, function(a, b) return (a.req or 0) < (b.req or 0) end)
        local n = candidates[1]
        if not n then return "All Unlocked" end
        return shortText(tostring(n.category or "Unlock") .. ": " .. tostring(n.name or "Reward"), 24)
    end

    local function tableRows(id, rows)
        if dgMiniTable then local ok = driftgod.Try(dgMiniTable, tostring(id or "Table"), rows); if ok then return end end
        if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex and ImGui.EndTable and ImGui.BeginTable(tostring(id or "Table"), 2, 0) then
            for _, row in ipairs(rows or {}) do
                ImGui.TableNextRow()
                ImGui.TableSetColumnIndex(0); if ImGui.Text then ImGui.Text(tostring(row[1] or "")) end
                ImGui.TableSetColumnIndex(1); text(row[2], row[4] or row[3] or "white")
            end
            ImGui.EndTable()
            return
        end
        for _, row in ipairs(rows or {}) do text(tostring(row[1] or "") .. ": " .. tostring(row[2] or ""), row[4] or row[3] or "white") end
    end

    local function ensureGarageToggle()
        if driftgod.VS_RegisterFeatures then driftgod.Try(driftgod.VS_RegisterFeatures) end
        if driftgod.R254_EnsureSpawnerHudToggle then driftgod.Try(driftgod.R254_EnsureSpawnerHudToggle) end
    end

    local function renderGarageHudToggle()
        ensureGarageToggle()
        if driftgod.R254_RenderSpawnerHudToggle then
            local ok = driftgod.Try(driftgod.R254_RenderSpawnerHudToggle)
            if ok then return true end
        end
        return feature(driftgod.H and (driftgod.H.R254SpawnerHudToggle or driftgod.H.VehicleSpawnerOpen), "Garage HUD")
    end

    local function ensureStuntHudToggle()
        driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
        if driftgod.R193_RegisterStuntHudControls then driftgod.Try(driftgod.R193_RegisterStuntHudControls) end
        if not driftgod.H.StuntHudToggle and driftgod.Hash then driftgod.H.StuntHudToggle = driftgod.Hash("StuntHudToggle") end
        if driftgod.H.StuntHudToggle and not driftgod.R284StuntHudToggleFeature and not driftgod.R253StuntHudToggleFeature and not driftgod.R193StuntHudToggleFeature and driftgod.AddToggle then
            local ok, feat = driftgod.Try(function()
                return driftgod.AddToggle("StuntHudToggle", "Stunt HUD", "Show or hide the DriftGod Stunts quick menu.", function(f)
                    local on = false
                    driftgod.Try(function() on = f and f.IsToggled and f:IsToggled() == true or false end)
                    driftgod.S.stuntQuickMenuEnabled = on
                    if on then
                        if driftgod.OpenStuntQuickMenu then driftgod.Try(driftgod.OpenStuntQuickMenu) end
                    else
                        if driftgod.CloseStuntQuickMenu then driftgod.Try(driftgod.CloseStuntQuickMenu) end
