        if driftgod.ScoreForUnlock then
            local ok, v = driftgod.Try(driftgod.ScoreForUnlock)
            if ok and tonumber(v) then return math.floor(math.max(0, tonumber(v) or 0)) end
        end
        return math.floor(math.max(
            tonumber(driftgod.S.bestRunScore or 0) or 0,
            tonumber(driftgod.S.bestScore or 0) or 0,
            tonumber(driftgod.S.highScore or 0) or 0,
            tonumber(driftgod.S.highestScore or 0) or 0,
            tonumber(driftgod.S.arcadeBestScore or 0) or 0,
            tonumber(driftgod.S.currentScore or 0) or 0,
            tonumber(driftgod.S.arcadeRunScore or 0) or 0,
            0
        ))
    end

    local function presetById(id)
        id = tostring(id or "")
        if id == "" then return nil end
        if driftgod.GetArcadeDriftPresetById then
            local ok, p = driftgod.Try(driftgod.GetArcadeDriftPresetById, id)
            if ok and type(p) == "table" then return p end
        end
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            if tostring(p.id or "") == id then return p end
        end
        return nil
    end

    local function presetName(id, p)
        id = tostring(id or "")
        if isResetId(id) then return "Reset" end
        p = p or presetById(id)
        local name = tostring((p and (p.name or p.id)) or id or "Preset")
        if isDriftGodId(id, name) then return "DriftGod" end
        if name == "Default Drifting" then return "Reset" end
        return name:gsub("DriftGod Wide Angle", "Wide Angle")
    end

    local function presetUnlockNeed(id, p)
        p = p or presetById(id)
        if not p then return 0 end
        return tonumber(p.unlock or p.score or p.threshold or 0) or 0
    end

    local function presetUsable(id, p)
        id = tostring(id or "")
        if id == "" then return false end
        if isResetId(id) then return true end
        p = p or presetById(id)
        if not p then return false end

        if driftgod.IsArcadeDriftPresetUnlocked then
            local ok, unlocked = driftgod.Try(driftgod.IsArcadeDriftPresetUnlocked, id)
            if ok then return unlocked == true end
        end
        if driftgod.IsArcadeDriftPresetTrialAvailable then
            local ok, trial = driftgod.Try(driftgod.IsArcadeDriftPresetTrialAvailable, id)
            if ok and trial == true then return true end
        end

        local s = score()
        if isDriftGodId(id, p.name) then
            local trialUntil = tonumber(p.trial_until or 0) or 0
            local need = tonumber(p.unlock or 100000) or 100000
            return (trialUntil > 0 and s < trialUntil and s < need) or s >= need
        end

        return s >= presetUnlockNeed(id, p)
    end

    local function activeCustomName()
        driftgod.S = driftgod.S or {}
        local name = tostring(
            driftgod.S.r288DefaultCustomPresetName
            or driftgod.S.r214ActiveCustomPreset
            or driftgod.S.r203ActiveCustomPreset
            or driftgod.S.r202ActiveCustomPreset
            or driftgod.S.r198ActiveCustomPreset
            or driftgod.S.customPresetLastSavedName
            or driftgod.S.customPresetName
            or ""
        )
        if name ~= "" then return name end

        local idx = tonumber(driftgod.S.customPresetIndex or 1) or 1
        local scans = {
            "R214_ScanCustomPresets", "R213_ScanCustomPresets", "R212_ScanCustomPresets",
            "R211_ScanCustomPresets", "R210_ScanCustomPresets", "R206_ScanCustomPresets",
            "R205_ScanCustomPresets", "R203_ScanCustomPresets", "R202_ScanCustomPresets",
            "R199_ScanCustomPresets", "R197_ScanCustomPresets"
        }
        for _, fnName in ipairs(scans) do
            local fn = DG[fnName]
            if type(fn) == "function" then
                local ok, list = driftgod.Try(fn, false)
                if ok and type(list) == "table" and list[idx] then return tostring(list[idx]) end
                ok, list = driftgod.Try(fn)
                if ok and type(list) == "table" and list[idx] then return tostring(list[idx]) end
            end
        end
        return ""
    end

    local function saveSettingsQuiet()
        if driftgod.__R288RestoringDefaultPreset == true then return false end
        if driftgod.SaveSettings then
            local ok = driftgod.Try(function() driftgod.SaveSettings(false) end)
            return ok == true
        end
        return false
    end

    function driftgod.R288_SaveDefaultBuiltin(id, reason, saveNow)
        driftgod.S = driftgod.S or {}
        id = tostring(id or "")
        if id == "" then return false end
        local p = presetById(id)
        if not isResetId(id) and not presetUsable(id, p) then return false end
        if isDriftGodId(id, p and p.name) then id = DRIFTGOD_ID end

        local name = presetName(id, p)
        driftgod.S.r288DefaultPresetMode = "builtin"
        driftgod.S.r288DefaultPresetId = id
        driftgod.S.r288DefaultCustomPresetName = ""
        driftgod.S.r288DefaultPresetName = name
        driftgod.S.r288DefaultPresetReason = tostring(reason or "builtin")
        driftgod.S.r288DefaultPresetSavedAt = nowStamp()
        driftgod.S.r288DefaultPresetUnlockScore = presetUnlockNeed(id, p)

        driftgod.S.savedStartupPresetMode = "builtin"
        driftgod.S.savedStartupPresetId = id
        driftgod.S.savedStartupCustomPresetName = ""
        driftgod.S.savedStartupPresetDisplayName = name
        driftgod.S.savedStartupPresetUserSelected = true
        driftgod.S.r246SavedBuiltinPresetId = id
        driftgod.S.activeStartupPreset = name
        if not isResetId(id) then
            driftgod.S.activeArcadeDriftPreset = id
            driftgod.S.r198BaseTuningPreset = id
            driftgod.S.r195BaseTuningPreset = id
        end
        driftgod.S.arcadePresetRuntimeEnabled = true
        driftgod.S.driftAssistEnabled = true

        if driftgod.R246_SaveStartupPresetChoice and not driftgod.__R288SavingStartupChoice then
            driftgod.__R288SavingStartupChoice = true
            driftgod.Try(driftgod.R246_SaveStartupPresetChoice, "builtin", id, name, false)
            driftgod.__R288SavingStartupChoice = false
        end

        if saveNow == true then saveSettingsQuiet() end
        return true
    end

    function driftgod.R288_SaveDefaultCustom(name, reason, saveNow)
        driftgod.S = driftgod.S or {}
        name = tostring(name or activeCustomName() or "")
        if name == "" then return false end

        driftgod.S.r288DefaultPresetMode = "custom"
        driftgod.S.r288DefaultPresetId = ""
        driftgod.S.r288DefaultCustomPresetName = name
        driftgod.S.r288DefaultPresetName = name
        driftgod.S.r288DefaultPresetReason = tostring(reason or "custom")
        driftgod.S.r288DefaultPresetSavedAt = nowStamp()

        driftgod.S.savedStartupPresetMode = "custom"
        driftgod.S.savedStartupCustomPresetName = name
        driftgod.S.savedStartupPresetId = ""
        driftgod.S.savedStartupPresetDisplayName = name
        driftgod.S.savedStartupPresetUserSelected = true
        driftgod.S.r246SavedCustomPresetName = name
        driftgod.S.activeStartupPreset = name
        driftgod.S.arcadePresetRuntimeEnabled = true
        driftgod.S.driftAssistEnabled = true

        if driftgod.R246_SaveStartupPresetChoice and not driftgod.__R288SavingStartupChoice then
            driftgod.__R288SavingStartupChoice = true
            driftgod.Try(driftgod.R246_SaveStartupPresetChoice, "custom", name, name, false)
            driftgod.__R288SavingStartupChoice = false
        end

        if saveNow == true then saveSettingsQuiet() end
        return true
    end

    local function quietCall(fn, ...)
        if type(fn) ~= "function" then return false end
        local oldToast, oldSave = driftgod.Toast, driftgod.SaveSettings
        driftgod.__R288RestoringDefaultPreset = true
        driftgod.Toast = function(...) return true end
        driftgod.SaveSettings = function(...) return true end
        local ok, result = driftgod.Try(fn, ...)
        driftgod.Toast = oldToast
        driftgod.SaveSettings = oldSave
        driftgod.__R288RestoringDefaultPreset = false
        if ok then return result end
        return false
    end

    function driftgod.R288_ApplyBuiltinDefault(id, reason)
        id = tostring(id or "")
        if id == "" then return false end
        local p = presetById(id)
        if not isResetId(id) and not presetUsable(id, p) then return false end

        local ok = false
        if isResetId(id) then
            if driftgod.ApplyResetPreset then ok = quietCall(driftgod.ApplyResetPreset, false) ~= false
            elseif driftgod.ApplyDefaultDriftingPreset then ok = quietCall(driftgod.ApplyDefaultDriftingPreset, false, false) ~= false end
        elseif driftgod.ApplyArcadeDriftPreset then
            ok = quietCall(driftgod.ApplyArcadeDriftPreset, id, false) ~= false
        end

        if ok then
            driftgod.S.activeStartupPreset = presetName(id, p)
            if not isResetId(id) then
                driftgod.S.activeArcadeDriftPreset = id
                driftgod.S.r198BaseTuningPreset = id
                driftgod.S.r195BaseTuningPreset = id
            end
            driftgod.S.arcadePresetRuntimeEnabled = true
            driftgod.S.driftAssistEnabled = true
            if driftgod.ClampAssistToUnlocks then driftgod.Try(driftgod.ClampAssistToUnlocks, false) end
            if driftgod.R245RefreshTuningSliderCaps then driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false) end
            return true
        end
        return false
    end

    function driftgod.R288_ApplyCustomDefault(name, reason)
        name = tostring(name or "")
        if name == "" then return false end

        local loaders = {
            "R214_LoadCustomPresetByName", "R213_LoadCustomPresetByName", "R212_LoadCustomPresetByName",
            "R211_LoadCustomPresetByName", "R210_LoadCustomPresetByName", "R206_LoadCustomPresetByName",
            "R205_LoadCustomPresetByName", "R203_LoadCustomPresetByName", "R202_LoadCustomPresetByName",
            "R199_LoadCustomPresetByName", "R197_LoadCustomPresetByName"
        }

        for _, fnName in ipairs(loaders) do
            local fn = DG[fnName]
            if type(fn) == "function" then
                local result = quietCall(fn, name)
                if result ~= false and result ~= nil then
                    driftgod.S.r288DefaultPresetMode = "custom"
                    driftgod.S.r288DefaultCustomPresetName = name
                    driftgod.S.activeStartupPreset = name
                    driftgod.S.arcadePresetRuntimeEnabled = true
                    driftgod.S.driftAssistEnabled = true
                    return true
                end
            end
        end

        if driftgod.R246_ApplySavedStartupPreset then
            local oldMode, oldName = driftgod.S.savedStartupPresetMode, driftgod.S.savedStartupCustomPresetName
            driftgod.S.savedStartupPresetMode = "custom"
            driftgod.S.savedStartupCustomPresetName = name
            local result = quietCall(driftgod.R246_ApplySavedStartupPreset, "R288 custom fallback")
            driftgod.S.savedStartupPresetMode, driftgod.S.savedStartupCustomPresetName = oldMode, oldName
            if result == true then
                driftgod.S.activeStartupPreset = name
                driftgod.S.arcadePresetRuntimeEnabled = true
                driftgod.S.driftAssistEnabled = true
                return true
            end
        end

        return false
    end

    local function highestUnlockedPreset()
        local s = score()
        local best, bestNeed = nil, -1
        for _, p in ipairs(driftgod.ArcadeDriftPresets or {}) do
            local id = tostring(p.id or "")
            local need = presetUnlockNeed(id, p)
            if id ~= "" and need > 0 and s >= need and not isResetId(id) then

                if need > bestNeed then
                    best = p
                    bestNeed = need
                end
            end
        end
        return best, bestNeed, s
    end

    function driftgod.R288_RestoreDefaultPreset(reason)
        driftgod.S = driftgod.S or {}

        local mode = tostring(driftgod.S.r288DefaultPresetMode or driftgod.S.savedStartupPresetMode or "")
        if mode == "custom" then
            local name = tostring(driftgod.S.r288DefaultCustomPresetName or driftgod.S.savedStartupCustomPresetName or driftgod.S.r246SavedCustomPresetName or "")
            if name ~= "" and driftgod.R288_ApplyCustomDefault(name, reason or "restore custom") then return true end
        end

        local ids = {
            driftgod.S.r288DefaultPresetId,
            driftgod.S.savedStartupPresetId,
            driftgod.S.r246SavedBuiltinPresetId,
            driftgod.S.activeArcadeDriftPreset,
            driftgod.S.r198BaseTuningPreset,
            driftgod.S.r195BaseTuningPreset,
        }

        for _, id in ipairs(ids) do
            id = tostring(id or "")
            if id ~= "" and driftgod.R288_ApplyBuiltinDefault(id, reason or "restore builtin") then return true end
        end

        if mode ~= "custom" then
            local p = highestUnlockedPreset()
            if p and p.id and driftgod.R288_ApplyBuiltinDefault(p.id, "highest unlocked fallback") then
                driftgod.R288_SaveDefaultBuiltin(p.id, "highest unlocked fallback", true)
                return true
            end
        end

        return false
    end

    function driftgod.R288_CheckPresetUnlockDefault(reason)
        driftgod.S = driftgod.S or {}
        if tostring(driftgod.S.r288DefaultPresetMode or driftgod.S.savedStartupPresetMode or "") == "custom" then

            local p, need = highestUnlockedPreset()
            if p and need and need > (tonumber(driftgod.S.r288HighestSeenPresetUnlockScore or 0) or 0) then
                driftgod.S.r288HighestSeenPresetUnlockScore = tonumber(need or 0) or 0
                driftgod.S.r288HighestSeenPresetUnlockId = tostring(p.id or "")
                saveSettingsQuiet()
            end
            return false
        end

        local p, need, s = highestUnlockedPreset()
        if not p then return false end
        need = tonumber(need or 0) or 0

        local seen = tonumber(driftgod.S.r288HighestSeenPresetUnlockScore or driftgod.S.r282HighestSeenPresetUnlockScore or 0) or 0
        local currentDefaultNeed = presetUnlockNeed(driftgod.S.r288DefaultPresetId or driftgod.S.savedStartupPresetId or driftgod.S.activeArcadeDriftPreset or "", nil)

        if need > seen or need > currentDefaultNeed then
            local id = tostring(p.id or "")
            if id ~= "" and driftgod.R288_ApplyBuiltinDefault(id, "new unlock default") then
                driftgod.R288_SaveDefaultBuiltin(id, "new unlock default", true)
                driftgod.S.r288HighestSeenPresetUnlockScore = need
                driftgod.S.r288HighestSeenPresetUnlockId = id
                driftgod.S.r282HighestSeenPresetUnlockScore = need
                driftgod.S.r282HighestSeenPresetUnlockId = id
                driftgod.S.r288LastAutoDefaultPresetName = presetName(id, p)
                driftgod.S.r288LastAutoDefaultPresetScore = s
                driftgod.S.r288LastAutoDefaultPresetAt = nowStamp()
                saveSettingsQuiet()
                return true
            end
        else
            driftgod.S.r288HighestSeenPresetUnlockScore = math.max(seen, need)
            driftgod.S.r288HighestSeenPresetUnlockId = tostring(p.id or "")
        end

        return false
    end

    if type(driftgod.ApplyArcadeDriftPreset) == "function" and driftgod.__R288ApplyArcadeWrapped ~= true then
        driftgod.__R288ApplyArcadeWrapped = true
        local oldApplyArcade = driftgod.ApplyArcadeDriftPreset
        driftgod.ApplyArcadeDriftPreset = function(id, showToast, ...)
            local result = oldApplyArcade(id, showToast, ...)
            if result ~= false
                and driftgod.__R288RestoringDefaultPreset ~= true
                and driftgod.__R288ApplyingCustomPreset ~= true
                and driftgod.__R288SavingStartupChoice ~= true
                and tostring(id or "") ~= "" then
                driftgod.R288_SaveDefaultBuiltin(id, "manual builtin apply", true)
            end
            return result
        end
    end

    local function wrapCustomByName(fnName)
        local fn = DG[fnName]
        if type(fn) ~= "function" or DG["__R288Wrapped_" .. fnName] then return end
        DG["__R288Wrapped_" .. fnName] = true
        DG[fnName] = function(name, ...)
            driftgod.__R288ApplyingCustomPreset = true
            local result = fn(name, ...)
            driftgod.__R288ApplyingCustomPreset = false
            if result ~= false and driftgod.__R288RestoringDefaultPreset ~= true then
                driftgod.R288_SaveDefaultCustom(tostring(name or activeCustomName() or ""), "manual custom apply", true)
            end
            return result
        end
    end

    local function wrapCustomSelected(fnName)
        local fn = DG[fnName]
        if type(fn) ~= "function" or DG["__R288Wrapped_" .. fnName] then return end
        DG["__R288Wrapped_" .. fnName] = true
        DG[fnName] = function(...)
            driftgod.__R288ApplyingCustomPreset = true
            local result = fn(...)
            driftgod.__R288ApplyingCustomPreset = false
            if result ~= false and driftgod.__R288RestoringDefaultPreset ~= true then
                driftgod.R288_SaveDefaultCustom(activeCustomName(), "manual custom apply", true)
            end
            return result
        end
    end

    for _, fnName in ipairs({
        "R214_LoadCustomPresetByName", "R213_LoadCustomPresetByName", "R212_LoadCustomPresetByName",
        "R211_LoadCustomPresetByName", "R210_LoadCustomPresetByName", "R206_LoadCustomPresetByName",
        "R205_LoadCustomPresetByName", "R203_LoadCustomPresetByName", "R202_LoadCustomPresetByName",
        "R199_LoadCustomPresetByName", "R197_LoadCustomPresetByName"
    }) do wrapCustomByName(fnName) end

    for _, fnName in ipairs({
        "R214_LoadSelectedCustomPreset", "R213_LoadSelectedCustomPreset", "R212_LoadSelectedCustomPreset",
        "R211_LoadSelectedCustomPreset", "R210_LoadSelectedCustomPreset", "R206_LoadSelectedCustomPreset",
        "R205_LoadSelectedCustomPreset", "R203_LoadSelectedCustomPreset", "R202_LoadSelectedCustomPreset",
        "R199_LoadSelectedCustomPreset", "R197_LoadSelectedCustomPreset",
        "R110_ApplyCustomPreset", "R109_LoadSelectedCustomPreset", "R136_ApplyCustomPreset",
        "R132_ApplyCustomPreset", "R130_ApplyCustomPreset", "R129_ApplyCustomPreset"
    }) do wrapCustomSelected(fnName) end

    driftgod.R282_RestoreMostRecentPreset = driftgod.R288_RestoreDefaultPreset
    driftgod.R282_CheckNewPresetUnlocks = driftgod.R288_CheckPresetUnlockDefault
    driftgod.ApplyAutoArcadeDriftPresetStage = function(...) return driftgod.R288_CheckPresetUnlockDefault("legacy auto-stage") end

    driftgod.Try(function() driftgod.R288_RestoreDefaultPreset("post-load immediate") end)
    driftgod.Try(function() driftgod.R288_CheckPresetUnlockDefault("post-load unlock check") end)

    if not driftgod.__R288PresetRestoreLoopInstalled and Script and Script.RegisterLooped then
        driftgod.__R288PresetRestoreLoopInstalled = true
        driftgod.S.r288RestoreLoopTicks = 0
        Script.RegisterLooped(function()
            if Script and Script.Yield then Script.Yield(700) end
            driftgod.Try(function()
                if ShouldUnload and ShouldUnload() then return false end
                driftgod.S.r288RestoreLoopTicks = (tonumber(driftgod.S.r288RestoreLoopTicks or 0) or 0) + 1
                if driftgod.S.r288RestoreLoopTicks <= 8 then
                    driftgod.R288_RestoreDefaultPreset("startup guard")
                end
                driftgod.R288_CheckPresetUnlockDefault("loop unlock check")
            end)
        end)
    end
end)

