    local function optionByIndex(index)
        index = math.floor(tonumber(index or 0) or 0)
        if index < 0 then index = 0 end
        if index > (#driftgod.R289_HotkeyOptions - 1) then index = #driftgod.R289_HotkeyOptions - 1 end
        return driftgod.R289_HotkeyOptions[index + 1] or driftgod.R289_HotkeyOptions[1], index
    end

    local function optionNameByCode(code)
        local opt = optionByIndex(idxForCode(code))
        return tostring(opt and opt.name or "None")
    end

    local function saveSettings()
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
    end

    function driftgod.R289_EnsureSavedHotkeyDefaults()
        driftgod.S = driftgod.S or {}
        local changed = false

        if driftgod.S.stuntHudHotkeyKeyCode == nil then
            driftgod.S.stuntHudHotkeyKeyCode = driftgod.R289_KEY_HOME
            driftgod.S.stuntHudHotkeyIndex = idxForCode(driftgod.R289_KEY_HOME)
            changed = true
        else
            driftgod.S.stuntHudHotkeyIndex = idxForCode(driftgod.S.stuntHudHotkeyKeyCode)
        end

        if driftgod.S.garageHudHotkeyKeyCode == nil then
            driftgod.S.garageHudHotkeyKeyCode = driftgod.R289_KEY_INSERT
            driftgod.S.garageHudHotkeyIndex = idxForCode(driftgod.R289_KEY_INSERT)
            changed = true
        else
            driftgod.S.garageHudHotkeyIndex = idxForCode(driftgod.S.garageHudHotkeyKeyCode)
        end

        driftgod.S.stuntHudHotkeyDefaultName = "Home"
        driftgod.S.garageHudHotkeyDefaultName = "Insert"

        if changed and driftgod.S.r289HotkeyDefaultsSaved ~= true then
            driftgod.S.r289HotkeyDefaultsSaved = true
            saveSettings()
        end
    end

    local function featureByHash(hash)
        if not hash then return nil end
        local feat = nil
        if FeatureMgr and FeatureMgr.GetFeature then driftgod.Try(function() feat = FeatureMgr.GetFeature(hash) end) end
        return feat
    end

    local function removeKnownHotkeysFromFeature(feat)
        if not feat then return false end
        driftgod.Try(function()
            if feat.GetHotkeys and feat.RemoveHotkey then
                local keys = feat:GetHotkeys()
                if type(keys) == "table" then
                    for _, key in pairs(keys) do
                        driftgod.Try(function() feat:RemoveHotkey(key, true) end)
                    end
                end
            end
        end)
        driftgod.Try(function() if feat.ClearHotkeys then feat:ClearHotkeys() end end)
        return true
    end

    function driftgod.R289_ApplyFeatureHotkey(feat, hash, keyCode, label)
        keyCode = tonumber(keyCode or 0) or 0
        if not feat and hash then feat = featureByHash(hash) end
        if not feat then return false end

        removeKnownHotkeysFromFeature(feat)

        if keyCode <= 0 then return true end

        local added = false
        if feat.AddHotKey then
            local ok = driftgod.Try(function() feat:AddHotKey(keyCode) end)
            if ok then added = true end
        end

        if not added and HotKeyMgr and HotKeyMgr.AddHotkey and hash then
            local ok = driftgod.Try(function() HotKeyMgr.AddHotkey(hash, keyCode) end)
            if ok then added = true end
        end

        return added == true
    end

    local function ensureGarageFeature()
        if driftgod.VS_RegisterFeatures then driftgod.Try(driftgod.VS_RegisterFeatures) end
        if driftgod.R254_EnsureSpawnerHudToggle then driftgod.Try(driftgod.R254_EnsureSpawnerHudToggle) end
        return driftgod.R254SpawnerHudToggleFeature
            or featureByHash(driftgod.H and driftgod.H.R254SpawnerHudToggle)
            or featureByHash(driftgod.H and driftgod.H.VehicleSpawnerOpen)
    end

    local function ensureStuntFeature()
        if driftgod.R193_RegisterStuntHudControls then driftgod.Try(driftgod.R193_RegisterStuntHudControls) end
        if not driftgod.H.StuntHudToggle and driftgod.Hash then driftgod.H.StuntHudToggle = driftgod.Hash("StuntHudToggle") end
        if driftgod.H.StuntHudToggle and not driftgod.R289StuntHudToggleFeature and not driftgod.R287StuntHudToggleFeature and not driftgod.R285StuntHudToggleFeature and not driftgod.R284StuntHudToggleFeature and not driftgod.R253StuntHudToggleFeature and not driftgod.R193StuntHudToggleFeature and driftgod.AddToggle then
            local ok, feat = driftgod.Try(function()
                return driftgod.AddToggle("StuntHudToggle", "Stunt HUD", "Show or hide the DriftGod Stunts quick menu.", function(f)
                    local on = false
                    driftgod.Try(function() on = f and f.IsToggled and f:IsToggled() == true or false end)
                    driftgod.S.stuntQuickMenuEnabled = on
                    if on then
                        if driftgod.OpenStuntQuickMenu then driftgod.Try(driftgod.OpenStuntQuickMenu) end
                    else
                        if driftgod.CloseStuntQuickMenu then driftgod.Try(driftgod.CloseStuntQuickMenu) end
                    end
                    saveSettings()
                end, driftgod.S.stuntQuickMenuEnabled ~= false)
            end)
            if ok and feat then driftgod.R289StuntHudToggleFeature = feat end
        end
        return driftgod.R193StuntHudToggleFeature
            or driftgod.R253StuntHudToggleFeature
            or driftgod.R284StuntHudToggleFeature
            or driftgod.R285StuntHudToggleFeature
            or driftgod.R287StuntHudToggleFeature
            or driftgod.R289StuntHudToggleFeature
            or featureByHash(driftgod.H and driftgod.H.StuntHudToggle)
    end

    function driftgod.R289_ApplySavedHudHotkeys()
        driftgod.R289_EnsureSavedHotkeyDefaults()

        local stuntKey = tonumber(driftgod.S.stuntHudHotkeyKeyCode or driftgod.R289_KEY_HOME) or driftgod.R289_KEY_HOME
        local garageKey = tonumber(driftgod.S.garageHudHotkeyKeyCode or driftgod.R289_KEY_INSERT) or driftgod.R289_KEY_INSERT

        local stuntFeat = ensureStuntFeature()
        local garageFeat = ensureGarageFeature()

        driftgod.S.r289StuntHotkeyApplied = driftgod.R289_ApplyFeatureHotkey(stuntFeat, driftgod.H and driftgod.H.StuntHudToggle, stuntKey, "Stunt HUD")
        local garageHash = driftgod.H and (driftgod.H.R254SpawnerHudToggle or driftgod.H.VehicleSpawnerOpen)
        driftgod.S.r289GarageHotkeyApplied = driftgod.R289_ApplyFeatureHotkey(garageFeat, garageHash, garageKey, "Garage HUD")

        if driftgod.R289StuntHudHotkeyFeature and driftgod.R289StuntHudHotkeyFeature.SetListIndex then
            driftgod.Try(function() driftgod.R289StuntHudHotkeyFeature:SetListIndex(idxForCode(stuntKey)) end)
        end
        if driftgod.R289GarageHudHotkeyFeature and driftgod.R289GarageHudHotkeyFeature.SetListIndex then
            driftgod.Try(function() driftgod.R289GarageHudHotkeyFeature:SetListIndex(idxForCode(garageKey)) end)
        end

        return driftgod.S.r289StuntHotkeyApplied == true or driftgod.S.r289GarageHotkeyApplied == true
    end

    function driftgod.R289_SetHudHotkey(kind, index, saveNow)
        driftgod.R289_EnsureSavedHotkeyDefaults()
        local opt, fixedIndex = optionByIndex(index)
        local code = tonumber(opt.code or 0) or 0

        if kind == "stunt" then
            driftgod.S.stuntHudHotkeyIndex = fixedIndex
            driftgod.S.stuntHudHotkeyKeyCode = code
            driftgod.S.stuntHudHotkeyName = opt.name
        elseif kind == "garage" then
            driftgod.S.garageHudHotkeyIndex = fixedIndex
            driftgod.S.garageHudHotkeyKeyCode = code
            driftgod.S.garageHudHotkeyName = opt.name
        end

        driftgod.R289_ApplySavedHudHotkeys()
        if saveNow ~= false then saveSettings() end
        return true
    end

    function driftgod.R289_RegisterHotkeyDropdownFeatures()
        driftgod.R289_EnsureSavedHotkeyDefaults()
        driftgod.H = driftgod.H or {}

        if not driftgod.H.StuntHudHotkeyCombo and driftgod.Hash then driftgod.H.StuntHudHotkeyCombo = driftgod.Hash("StuntHudHotkeyCombo") end
        if not driftgod.H.GarageHudHotkeyCombo and driftgod.Hash then driftgod.H.GarageHudHotkeyCombo = driftgod.Hash("GarageHudHotkeyCombo") end

        if driftgod.SafeAddFeature and eFeatureType and eFeatureType.Combo then
            if driftgod.H.StuntHudHotkeyCombo and not driftgod.R289StuntHudHotkeyFeature then
                local ok, feat = driftgod.Try(function()
                    return driftgod.SafeAddFeature(driftgod.H.StuntHudHotkeyCombo, "Stunt HUD Hotkey", eFeatureType.Combo, "Default: Home. Select a saved built-in Cherax hotkey for the Stunt HUD.", function(f)
                        local idx = 0
                        driftgod.Try(function() idx = f:GetListIndex() end)
                        driftgod.R289_SetHudHotkey("stunt", idx, true)
                    end)
                end)
                if ok and feat then
                    driftgod.R289StuntHudHotkeyFeature = feat
                    driftgod.Try(function() feat:SetList(driftgod.R289_HotkeyNames) end)
                    driftgod.Try(function() feat:SetListIndex(driftgod.S.stuntHudHotkeyIndex or idxForCode(driftgod.R289_KEY_HOME)) end)
                end
            end

            if driftgod.H.GarageHudHotkeyCombo and not driftgod.R289GarageHudHotkeyFeature then
                local ok, feat = driftgod.Try(function()
                    return driftgod.SafeAddFeature(driftgod.H.GarageHudHotkeyCombo, "Garage HUD Hotkey", eFeatureType.Combo, "Default: Insert. Select a saved built-in Cherax hotkey for the Garage HUD.", function(f)
                        local idx = 0
                        driftgod.Try(function() idx = f:GetListIndex() end)
                        driftgod.R289_SetHudHotkey("garage", idx, true)
                    end)
                end)
                if ok and feat then
                    driftgod.R289GarageHudHotkeyFeature = feat
                    driftgod.Try(function() feat:SetList(driftgod.R289_HotkeyNames) end)
                    driftgod.Try(function() feat:SetListIndex(driftgod.S.garageHudHotkeyIndex or idxForCode(driftgod.R289_KEY_INSERT)) end)
                end
            end
        end
    end

    local function textLine(msg, color)
        if dgMiniText then local ok = driftgod.Try(dgMiniText, tostring(msg or ""), color or "white"); if ok then return end end
