    local function btn(label, cb)
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) == true end) end
        if clicked and type(cb) == "function" then driftgod.Try(cb) end
        return clicked
    end

    local function renderHotkeyCombo(kind)
        driftgod.R289_RegisterHotkeyDropdownFeatures()
        driftgod.R289_EnsureSavedHotkeyDefaults()

        local isStunt = kind == "stunt"
        local keyCode = tonumber(isStunt and driftgod.S.stuntHudHotkeyKeyCode or driftgod.S.garageHudHotkeyKeyCode or 0) or 0
        local defaultName = isStunt and "Home" or "Insert"
        local label = isStunt and "Stunt HUD Hotkey" or "Garage HUD Hotkey"
        local hash = isStunt and driftgod.H.StuntHudHotkeyCombo or driftgod.H.GarageHudHotkeyCombo

        textLine("Default: " .. defaultName, "dim")

        local rendered = false
        if hash then
            rendered = feature(hash, label) == true
        end

        if not rendered and ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
            local preview = optionNameByCode(keyCode)
            local opened = false
            driftgod.Try(function() opened = ImGui.BeginCombo(label .. "##R289" .. tostring(kind), preview) == true end)
            if opened then
                for i, item in ipairs(driftgod.R289_HotkeyOptions) do
                    local idx = i - 1
                    local selected = tonumber(item.code or 0) == keyCode
                    local clicked = false
                    driftgod.Try(function() clicked = ImGui.Selectable(tostring(item.name), selected) == true end)
                    if clicked then driftgod.R289_SetHudHotkey(kind, idx, true) end
                end
                driftgod.Try(ImGui.EndCombo)
            end
        end

        local current = optionNameByCode(keyCode)
        textLine("Saved hotkey: " .. tostring(current), keyCode > 0 and "green" or "dim")
    end

