    local function textLine(msg, color)
        if dgMiniText then local ok = driftgod.Try(dgMiniText, tostring(msg or ""), color or "white"); if ok then return end end
        if R164_text then local ok = driftgod.Try(R164_text, tostring(msg or ""), color or "white"); if ok then return end end
        if dgColorText then local ok = driftgod.Try(dgColorText, tostring(msg or ""), color or "white"); if ok then return end end
        if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, tostring(msg or "")) end
    end

    local function sameLine()
        if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end
    end

    local function sep()
        if dgMiniSep then driftgod.Try(dgMiniSep) elseif ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end
    end

    local function child(name)
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, open = driftgod.Try(ClickGUI.BeginCustomChildWindow, tostring(name or "Section"))
            return ok and open == true
        end
        textLine(name, "header")
        return true
    end

    local function endChild()
        if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
    end

    local function feature(hash, label)
        if hash and dgMiniFeature then local ok = driftgod.Try(dgMiniFeature, hash, label); if ok then return true end end
        if hash and renderFeatureSafe then local ok = driftgod.Try(renderFeatureSafe, hash, label); if ok then return true end end
        if hash and ClickGUI and ClickGUI.RenderFeature then local ok = driftgod.Try(ClickGUI.RenderFeature, hash); if ok then return true end end
        return false
    end

    local function btn(label, cb)
        local clicked = false
        if ImGui and ImGui.Button then driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) == true end) end
        if clicked and type(cb) == "function" then driftgod.Try(cb) end
        return clicked
    end

    function driftgod.R290_HotkeyDisplayName(kind, optionOrCode)
        local code = optionOrCode
        local baseName = nil
        if type(optionOrCode) == "table" then
            code = optionOrCode.code
            baseName = optionOrCode.name
        end
        code = tonumber(code or 0) or 0
        if not baseName then
            baseName = "None"
            for _, item in ipairs(driftgod.R289_HotkeyOptions or {}) do
                if tonumber(item.code or 0) == code then
                    baseName = tostring(item.name or "None")
                    break
                end
            end
        end

        if tostring(kind or "") == "stunt" and code == KEY_HOME then
            return "Home (Default)"
        end
        if tostring(kind or "") == "garage" and code == KEY_INSERT then
            return "Insert (Default)"
        end
        return tostring(baseName or "None")
    end

    function driftgod.R290_BuildHotkeyNames(kind)
        local out = {}
        for i, item in ipairs(driftgod.R289_HotkeyOptions or {}) do
            out[i] = driftgod.R290_HotkeyDisplayName(kind, item)
        end
        return out
    end

    function driftgod.R290_ApplyHotkeyDropdownLabels()
        driftgod.R290_StuntHotkeyNames = driftgod.R290_BuildHotkeyNames("stunt")
        driftgod.R290_GarageHotkeyNames = driftgod.R290_BuildHotkeyNames("garage")

        if driftgod.R289StuntHudHotkeyFeature then
            driftgod.Try(function() driftgod.R289StuntHudHotkeyFeature:SetList(driftgod.R290_StuntHotkeyNames) end)
            driftgod.Try(function() driftgod.R289StuntHudHotkeyFeature:SetListIndex(driftgod.S.stuntHudHotkeyIndex or 0) end)
        end
        if driftgod.R289GarageHudHotkeyFeature then
            driftgod.Try(function() driftgod.R289GarageHudHotkeyFeature:SetList(driftgod.R290_GarageHotkeyNames) end)
            driftgod.Try(function() driftgod.R289GarageHudHotkeyFeature:SetListIndex(driftgod.S.garageHudHotkeyIndex or 0) end)
        end
    end

    if type(driftgod.R289_RegisterHotkeyDropdownFeatures) == "function" and driftgod.__R290RegisterHotkeyDropdownFeaturesWrapped ~= true then
        driftgod.__R290RegisterHotkeyDropdownFeaturesWrapped = true
        local oldRegister = driftgod.R289_RegisterHotkeyDropdownFeatures
        driftgod.R289_RegisterHotkeyDropdownFeatures = function(...)
            local ok, ret = driftgod.Try(oldRegister, ...)
            driftgod.Try(driftgod.R290_ApplyHotkeyDropdownLabels)
            if ok then return ret end
        end
    end

    local function idxForCode(code)
        code = tonumber(code or 0) or 0
        for i, item in ipairs(driftgod.R289_HotkeyOptions or {}) do
            if tonumber(item.code or 0) == code then return i - 1 end
        end
        return 0
    end

    local function optionByIndex(index)
        index = math.floor(tonumber(index or 0) or 0)
        local opts = driftgod.R289_HotkeyOptions or {}
        if index < 0 then index = 0 end
        if #opts <= 0 then return { name = "None", code = 0 }, 0 end
        if index > (#opts - 1) then index = #opts - 1 end
        return opts[index + 1] or opts[1], index
    end

    local function currentHotkeyDisplay(kind)
        driftgod.S = driftgod.S or {}
        local code = 0
        if kind == "stunt" then code = tonumber(driftgod.S.stuntHudHotkeyKeyCode or KEY_HOME) or KEY_HOME
        else code = tonumber(driftgod.S.garageHudHotkeyKeyCode or KEY_INSERT) or KEY_INSERT end
        return driftgod.R290_HotkeyDisplayName(kind, code), code
    end

    local function renderHotkeyCombo(kind)
        if driftgod.R289_EnsureSavedHotkeyDefaults then driftgod.Try(driftgod.R289_EnsureSavedHotkeyDefaults) end
        if driftgod.R289_RegisterHotkeyDropdownFeatures then driftgod.Try(driftgod.R289_RegisterHotkeyDropdownFeatures) end
        driftgod.Try(driftgod.R290_ApplyHotkeyDropdownLabels)

        local isStunt = kind == "stunt"
        local label = isStunt and "Stunt HUD Hotkey" or "Garage HUD Hotkey"
        local hash = isStunt and (driftgod.H and driftgod.H.StuntHudHotkeyCombo) or (driftgod.H and driftgod.H.GarageHudHotkeyCombo)
        local defaultText = isStunt and "Default: Home" or "Default: Insert"
        local rendered = false

        textLine(defaultText, "dim")

        if hash then rendered = feature(hash, label) == true end

        if not rendered and ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
            local preview = currentHotkeyDisplay(kind)
            local opened = false
            driftgod.Try(function() opened = ImGui.BeginCombo(label .. "##R290" .. tostring(kind), tostring(preview)) == true end)
            if opened then
                for i, item in ipairs(driftgod.R289_HotkeyOptions or {}) do
                    local idx = i - 1
                    local selectedCode = isStunt and (tonumber(driftgod.S.stuntHudHotkeyKeyCode or KEY_HOME) or KEY_HOME)
                        or (tonumber(driftgod.S.garageHudHotkeyKeyCode or KEY_INSERT) or KEY_INSERT)
                    local selected = tonumber(item.code or 0) == selectedCode
                    local clicked = false
                    local itemLabel = driftgod.R290_HotkeyDisplayName(kind, item)
                    driftgod.Try(function() clicked = ImGui.Selectable(tostring(itemLabel), selected) == true end)
                    if clicked and driftgod.R289_SetHudHotkey then
                        driftgod.R289_SetHudHotkey(kind, idx, true)
                        driftgod.Try(driftgod.R290_ApplyHotkeyDropdownLabels)
                    end
                end
                driftgod.Try(ImGui.EndCombo)
            end
        end

        local current = currentHotkeyDisplay(kind)
        textLine("Saved hotkey: " .. tostring(current), "green")
    end

    local function ensureStuntToggle()
        if driftgod.R193_RegisterStuntHudControls then driftgod.Try(driftgod.R193_RegisterStuntHudControls) end
        if not driftgod.H.StuntHudToggle and driftgod.Hash then driftgod.H.StuntHudToggle = driftgod.Hash("StuntHudToggle") end
    end

    local function ensureGarageToggle()
        if driftgod.VS_RegisterFeatures then driftgod.Try(driftgod.VS_RegisterFeatures) end
        if driftgod.R254_EnsureSpawnerHudToggle then driftgod.Try(driftgod.R254_EnsureSpawnerHudToggle) end
    end

    function driftgod.R290_RenderStuntHudSettings()
        if driftgod.R289_RegisterHotkeyDropdownFeatures then driftgod.Try(driftgod.R289_RegisterHotkeyDropdownFeatures) end
        ensureStuntToggle()

        local opened = true
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, o = driftgod.Try(ClickGUI.BeginCustomChildWindow, "Stunt HUD")
            opened = ok and o == true
        else
            textLine("Stunt HUD", "header")
        end

        if opened then
            textLine("Stunt HUD / Quick Menu", "header")
            feature(driftgod.H and driftgod.H.StuntHudToggle, "Stunt HUD")
            feature(driftgod.H and driftgod.H.StuntHudMoveToggle, "Stunt Menu Movement")

            renderHotkeyCombo("stunt")

            if driftgod.R193_RenderStuntHudPositionDropdown then
                driftgod.Try(driftgod.R193_RenderStuntHudPositionDropdown)
            elseif driftgod.H and driftgod.H.StuntHudPreset then
                feature(driftgod.H.StuntHudPreset, "Stunt HUD Position")
            end

            local sx, sy = 0.085, 0.560
            if dgGetStuntMenuXY then
                local ok, x, y = driftgod.Try(dgGetStuntMenuXY)
                if ok then sx, sy = tonumber(x) or sx, tonumber(y) or sy end
            else
                sx = tonumber(driftgod.S.stuntQuickMenuX or driftgod.S.stuntHudX or sx) or sx
                sy = tonumber(driftgod.S.stuntQuickMenuY or driftgod.S.stuntHudY or sy) or sy
            end
            if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, "Current X/Y: " .. string.format("%.3f", sx) .. " / " .. string.format("%.3f", sy)) end

            sep()
            textLine("Move", "white")
            feature(driftgod.H and driftgod.H.StuntHudXMinus, "X-"); sameLine(); feature(driftgod.H and driftgod.H.StuntHudXPlus, "X+")
            feature(driftgod.H and driftgod.H.StuntHudYMinus, "Y-"); sameLine(); feature(driftgod.H and driftgod.H.StuntHudYPlus, "Y+")
            feature(driftgod.H and driftgod.H.StuntHudReset, "Reset Position")
            textLine("Fine Move", "white")
            btn("X-##R290StuntFineXMinus", function() if dgMoveStuntMenu then dgMoveStuntMenu(-0.005, 0.000, "Stunt HUD X") end end)
            sameLine(); btn("X+##R290StuntFineXPlus", function() if dgMoveStuntMenu then dgMoveStuntMenu(0.005, 0.000, "Stunt HUD X") end end)
            btn("Y-##R290StuntFineYMinus", function() if dgMoveStuntMenu then dgMoveStuntMenu(0.000, -0.005, "Stunt HUD Y") end end)
            sameLine(); btn("Y+##R290StuntFineYPlus", function() if dgMoveStuntMenu then dgMoveStuntMenu(0.000, 0.005, "Stunt HUD Y") end end)
            textLine("Position and hotkey save immediately.", "dim")

            if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
        end
    end

    local function moveSpawnerHud(dx, dy, label)
        if driftgod.R162_MoveSpawnerHud then return driftgod.R162_MoveSpawnerHud(dx or 0, dy or 0, label or "Garage HUD") end
        driftgod.S = driftgod.S or {}
        driftgod.S.vehicleSpawnerHudX = (tonumber(driftgod.S.vehicleSpawnerHudX or 0.085) or 0.085) + (tonumber(dx or 0) or 0)
        driftgod.S.vehicleSpawnerHudY = (tonumber(driftgod.S.vehicleSpawnerHudY or 0.080) or 0.080) + (tonumber(dy or 0) or 0)
        saveSettings()
    end

    function driftgod.R290_RenderSpawnerHudControls()
        if driftgod.R289_RegisterHotkeyDropdownFeatures then driftgod.Try(driftgod.R289_RegisterHotkeyDropdownFeatures) end
        if driftgod.R162_EnsureSpawnerHudDefaults then driftgod.Try(driftgod.R162_EnsureSpawnerHudDefaults) end
        if driftgod.R162_RegisterSpawnerHudMovementFeature then driftgod.Try(driftgod.R162_RegisterSpawnerHudMovementFeature) end
        ensureGarageToggle()

        textLine("Garage HUD / Quick Menu", "header")

        if driftgod.R254_RenderSpawnerHudToggle then
            local ok = driftgod.Try(driftgod.R254_RenderSpawnerHudToggle)
            if not ok then feature(driftgod.H and (driftgod.H.R254SpawnerHudToggle or driftgod.H.VehicleSpawnerOpen), "Garage HUD") end
        else
            feature(driftgod.H and (driftgod.H.R254SpawnerHudToggle or driftgod.H.VehicleSpawnerOpen), "Garage HUD")
        end

        renderHotkeyCombo("garage")

        btn("Open HUD##R290SpawnerHud", driftgod.R154_OpenSpawnerHud or driftgod.R115_OpenSpawnerHud or driftgod.R114_OpenSpawnerHud)
        sameLine(); btn("Close HUD##R290SpawnerHud", driftgod.R154_CloseSpawnerHud or driftgod.R115_CloseSpawnerHud or driftgod.R114_CloseSpawnerHud)
        sameLine(); btn("Scan##R290SpawnerHud", driftgod.R154_RefreshSpawner or driftgod.R115_ScanSpawnerVehicles or driftgod.R114_ScanSpawnerVehicles)
        sameLine(); btn("Random##R290SpawnerHud", driftgod.R154_RandomSpawner or driftgod.R115_RandomSpawnerVehicle or driftgod.R114_RandomSpawnerVehicle)

        feature(driftgod.H and driftgod.H.VehicleSpawnerHudMoveToggle, "Spawner Menu Movement")
        if driftgod.R171_renderSpawnerHudPositionDropdown then driftgod.Try(driftgod.R171_renderSpawnerHudPositionDropdown)
        elseif driftgod.R168_renderSpawnerHudPositionDropdown then driftgod.Try(driftgod.R168_renderSpawnerHudPositionDropdown)
        else feature(driftgod.H and driftgod.H.VehicleSpawnerHudPreset, "Garage HUD Position") end

        local x = tonumber(driftgod.S.vehicleSpawnerHudX or 0.085) or 0.085
        local y = tonumber(driftgod.S.vehicleSpawnerHudY or 0.080) or 0.080
        textLine("Current X/Y: " .. string.format("%.3f", x) .. " / " .. string.format("%.3f", y), "white")

        textLine("Move", "white")
        btn("X-##R290SpawnerHudMoveXMinus", function() moveSpawnerHud(-0.025, 0.000, "Spawner X") end)
        sameLine(); btn("X+##R290SpawnerHudMoveXPlus", function() moveSpawnerHud(0.025, 0.000, "Spawner X") end)
        btn("Y-##R290SpawnerHudMoveYMinus", function() moveSpawnerHud(0.000, -0.025, "Spawner Y") end)
        sameLine(); btn("Y+##R290SpawnerHudMoveYPlus", function() moveSpawnerHud(0.000, 0.025, "Spawner Y") end)
        btn("Spawner Menu Reset Position##R290SpawnerHud", function()
            if driftgod.VS_ApplyHudPreset then driftgod.VS_ApplyHudPreset(driftgod.S.vehicleSpawnerHudPresetIndex or 1, true) end
            if driftgod.Toast then driftgod.Try(driftgod.Toast, "Garage HUD position reset", 1000) end
        end)

        textLine("Fine Move", "white")
        btn("X-##R290SpawnerHudFineXMinus", function() moveSpawnerHud(-0.005, 0.000, "Spawner Fine X") end)
        sameLine(); btn("X+##R290SpawnerHudFineXPlus", function() moveSpawnerHud(0.005, 0.000, "Spawner Fine X") end)
        btn("Y-##R290SpawnerHudFineYMinus", function() moveSpawnerHud(0.000, -0.005, "Spawner Fine Y") end)
        sameLine(); btn("Y+##R290SpawnerHudFineYPlus", function() moveSpawnerHud(0.000, 0.005, "Spawner Fine Y") end)

        textLine("Position and hotkey save immediately.", "dim")
        if driftgod.VS and driftgod.VS.runtime then
            textLine("Status: " .. (driftgod.VS.runtime.open and "Open" or "Closed"), driftgod.VS.runtime.open and "green" or "dim")
        end
    end

    function driftgod.R290_RenderSpawnerHudSettings()
        local opened = true
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, o = driftgod.Try(ClickGUI.BeginCustomChildWindow, "Garage HUD")
            opened = ok and o == true
        else
            textLine("Garage HUD", "header")
        end
        if opened then
            driftgod.R290_RenderSpawnerHudControls()
            if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
        end
    end

    function driftgod.R290_RenderStuntHudToggle()
        ensureStuntToggle()
        if feature(driftgod.H and driftgod.H.StuntHudToggle, "Stunt HUD") then return true end
        local open = driftgod.S and driftgod.S.stuntQuickMenuEnabled ~= false
        btn("Stunt HUD##R290GarageStuntToggle", function()
            driftgod.S = driftgod.S or {}
            driftgod.S.stuntQuickMenuEnabled = not (driftgod.S.stuntQuickMenuEnabled ~= false)
            if driftgod.S.stuntQuickMenuEnabled then
                if driftgod.OpenStuntQuickMenu then driftgod.Try(driftgod.OpenStuntQuickMenu) end
            else
                if driftgod.CloseStuntQuickMenu then driftgod.Try(driftgod.CloseStuntQuickMenu) end
            end
            saveSettings()
        end)
        sameLine(); textLine(open and "ON" or "OFF", open and "green" or "dim")
        return true
    end

    function driftgod.R290_RenderGarageHudToggle()
        ensureGarageToggle()
        if driftgod.R254_RenderSpawnerHudToggle then
            local ok = driftgod.Try(driftgod.R254_RenderSpawnerHudToggle)
            if ok then return true end
        end
        return feature(driftgod.H and (driftgod.H.R254SpawnerHudToggle or driftgod.H.VehicleSpawnerOpen), "Garage HUD")
    end

