    renderStuntHudSettings = driftgod.R290_RenderStuntHudSettings
    driftgod.R193_RenderStuntHudSettings = driftgod.R290_RenderStuntHudSettings
    driftgod.R189_RenderStuntHudSettings = driftgod.R290_RenderStuntHudSettings

    driftgod.R290_RenderSpawnerHudControls = driftgod.R290_RenderSpawnerHudControls
    driftgod.R289_RenderSpawnerHudControls = driftgod.R290_RenderSpawnerHudControls
    driftgod.R252_RenderSpawnerHudControls = driftgod.R290_RenderSpawnerHudControls
    driftgod.R171_RenderSpawnerHudControls = driftgod.R290_RenderSpawnerHudControls
    driftgod.R170_RenderSpawnerHudControls = driftgod.R290_RenderSpawnerHudControls
    driftgod.R169_RenderSpawnerHudControls = driftgod.R290_RenderSpawnerHudControls
    driftgod.R167_RenderSpawnerHudControls = driftgod.R290_RenderSpawnerHudControls
    driftgod.R165_RenderSpawnerHudControls = driftgod.R290_RenderSpawnerHudControls
    driftgod.R164_RenderSpawnerHudControls = driftgod.R290_RenderSpawnerHudControls

    driftgod.R290_RenderSpawnerHudSettings = driftgod.R290_RenderSpawnerHudSettings
    driftgod.R289_RenderSpawnerHudSettings = driftgod.R290_RenderSpawnerHudSettings
    driftgod.R189_RenderSpawnerHudSettings = driftgod.R290_RenderSpawnerHudSettings
    driftgod.R101_RenderSpawnerHudSettings = driftgod.R290_RenderSpawnerHudSettings

    if driftgod.R289_EnsureSavedHotkeyDefaults then driftgod.Try(driftgod.R289_EnsureSavedHotkeyDefaults) end
    if driftgod.R289_RegisterHotkeyDropdownFeatures then driftgod.Try(driftgod.R289_RegisterHotkeyDropdownFeatures) end
    if driftgod.R289_ApplySavedHudHotkeys then driftgod.Try(driftgod.R289_ApplySavedHudHotkeys) end
    driftgod.Try(driftgod.R290_ApplyHotkeyDropdownLabels)
end)

driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}; driftgod.H = driftgod.H or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"
    driftgod.__ProductionPatch = "R309_ProductBuild_1_0_0"

    driftgod.S.stuntCooldownsEnabled = driftgod.S.stuntCooldownsEnabled ~= false
    driftgod.S.cooldownsEnabled = true

    driftgod.R291_StuntCooldownTiers = {
        { score = 0,      ms = 3000, label = "Starter" },
        { score = 5000,   ms = 2500, label = "Warm-Up" },
        { score = 15000,  ms = 2000, label = "Flow" },
        { score = 30000,  ms = 1500, label = "Quick" },
        { score = 60000,  ms = 1000, label = "Rapid" },
        { score = 100000, ms = 750,  label = "Elite" },
    }

    local function nowMs()
        if driftgod.Now then
            local ok, v = driftgod.Try(driftgod.Now)
            if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
        end
        if driftgod.GetMs then
            local ok, v = driftgod.Try(driftgod.GetMs)
            if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
        end
        return math.floor((os.clock() or 0) * 1000)
    end

    local function score()
        driftgod.S = driftgod.S or {}
        if driftgod.GetArcadeDriftPresetScore then
            local ok, v = driftgod.Try(driftgod.GetArcadeDriftPresetScore)
            if ok and tonumber(v) then return math.floor(math.max(0, tonumber(v) or 0)) end
        end
        if driftgod.ScoreForUnlock then
            local ok, v = driftgod.Try(driftgod.ScoreForUnlock)
            if ok and tonumber(v) then return math.floor(math.max(0, tonumber(v) or 0)) end
        end
        if driftgod.GetStuntUnlockScore then
            local ok, v = driftgod.Try(driftgod.GetStuntUnlockScore)
            if ok and tonumber(v) then return math.floor(math.max(0, tonumber(v) or 0)) end
        end
        return math.floor(math.max(
            tonumber(driftgod.S.bestRunScore or 0) or 0,
            tonumber(driftgod.S.bestScore or 0) or 0,
            tonumber(driftgod.S.highScore or 0) or 0,
            tonumber(driftgod.S.highestScore or 0) or 0,
            tonumber(driftgod.S.arcadeBestScore or 0) or 0,
            tonumber(driftgod.S.currentScore or 0) or 0,
            tonumber(driftgod.S.arcadeRunScore or 0) or 0,
            0
        ))
    end

    function driftgod.R291_GetStuntCooldownTier()
        local s = score()
        local tier = driftgod.R291_StuntCooldownTiers[1]
        local nextTier = nil
        for i, t in ipairs(driftgod.R291_StuntCooldownTiers or {}) do
            if s >= (tonumber(t.score or 0) or 0) then
                tier = t
                nextTier = driftgod.R291_StuntCooldownTiers[i + 1]
            end
        end
        driftgod.S.r291StuntCooldownScore = s
        driftgod.S.r291StuntCooldownMs = tonumber(tier.ms or 3000) or 3000
