        driftgod.S.stuntCooldownMs = cd
        driftgod.S.sameStuntCooldownMs = cd
        driftgod.S.stuntTierUseCooldownMs = cd

        if last > 0 and (now - last) < cd then
            local left = math.max(0, cd - (now - last))
            driftgod.S.r291LastCooldownBlockMs = left
            driftgod.S.r291LastCooldownBlockName = tostring(name or "")
            if driftgod.Toast then driftgod.Try(driftgod.Toast, "Stunt cooldown: " .. formatSec(left), 1100) end
            return false
