        local sameLast = tonumber(driftgod.S.lastSameStuntTime or 0) or 0
        if tostring(name or "") == tostring(driftgod.S.lastStuntNameUsed or "") and sameLast > 0 and (now - sameLast) < cd then
            local left = math.max(0, cd - (now - sameLast))
            driftgod.S.r291LastCooldownBlockMs = left
            driftgod.S.r291LastCooldownBlockName = tostring(name or "")
