    local function hash32(s)
        s = tostring(s or "")
        local h = 2166136261
        for i = 1, #s do
            h = (h * 16777619 + string.byte(s, i)) % 4294967296
        end
        return string.format("%08x", h)
    end

    local function bxor(a, b)
        a = tonumber(a or 0) or 0
        b = tonumber(b or 0) or 0
        local res, p = 0, 1
        while a > 0 or b > 0 do
            local aa = a % 2
            local bb = b % 2
            if aa ~= bb then res = res + p end
            a = (a - aa) / 2
            b = (b - bb) / 2
            p = p * 2
        end
        return res
    end

    local function hexByte(n)
        return string.format("%02x", tonumber(n or 0) or 0)
    end

    local function fromHexByte(h)
