    local function xorHex(data, key)
        data = tostring(data or "")
        key = tostring(key or "DriftGod")
        if key == "" then key = "DriftGod" end
        local out = {}
        local klen = #key
        for i = 1, #data do
            local db = string.byte(data, i)
            local kb = string.byte(key, ((i - 1) % klen) + 1)
            out[#out + 1] = hexByte(bxor(db, kb))
        end
        return table.concat(out)
    end

    local function unxorHex(hex, key)
        hex = tostring(hex or "")
        key = tostring(key or "DriftGod")
        if key == "" then key = "DriftGod" end
        local out = {}
        local klen = #key
        local j = 1
        for i = 1, #hex, 2 do
            local hb = fromHexByte(hex:sub(i, i + 1))
            local kb = string.byte(key, ((j - 1) % klen) + 1)
            out[#out + 1] = string.char(bxor(hb, kb))
            j = j + 1
        end
        return table.concat(out)
    end

    local function serializeTable(tbl)
