    function driftgod.R295_GetRockstarUsername()
        local name = ""
        driftgod.Try(function()
            local pid = nil
            if GTA and GTA.GetLocalPlayerId then pid = tonumber(GTA.GetLocalPlayerId()) end
            if (pid == nil or pid < 0) and PLAYER and PLAYER.PLAYER_ID then pid = tonumber(PLAYER.PLAYER_ID()) end
            if pid == nil then pid = 0 end
            if PLAYER and PLAYER.GET_PLAYER_NAME then
                local v = PLAYER.GET_PLAYER_NAME(pid)
                if v and tostring(v) ~= "" and tostring(v) ~= "nil" then name = tostring(v) end
            end
        end)
        if name == "" then
            driftgod.Try(function()
                if NETWORK and NETWORK.NETWORK_PLAYER_GET_NAME and PLAYER and PLAYER.PLAYER_ID then
                    local v = NETWORK.NETWORK_PLAYER_GET_NAME(PLAYER.PLAYER_ID())
                    if v and tostring(v) ~= "" and tostring(v) ~= "nil" then name = tostring(v) end
                end
            end)
        end
        if name == "" then
            name = tostring(driftgod.S.r295RockstarUsername or driftgod.S.r295ProfileLabel or "")
        end
        if name == "" then
            local ok, env = driftgod.Try(function() return os.getenv and (os.getenv("USERNAME") or os.getenv("USER")) end)
            if ok and env and tostring(env) ~= "" then name = "local_" .. tostring(env) end
        end
        if name == "" then name = "local" end
        return driftgod.R295_SafeProfileLabel(name)
    end

    local function loadVaultKey()
        ensureProtectedDirs()
        local keyFile = driftgod.LoadTable and driftgod.LoadTable(driftgod.Paths.protectedVaultKey) or nil
        if type(keyFile) == "table" and type(keyFile.local_secret) == "string" and keyFile.local_secret ~= "" then
            return keyFile.local_secret
        end

        local seed = tostring(os.time and os.time() or 0) .. "|" .. tostring(os.clock and os.clock() or 0) .. "|" .. tostring(math.random and math.random(1000000, 9999999) or 0) .. "|" .. rootDir()
        local secret = "DG-" .. hash32(seed .. "|a") .. hash32(seed .. "|b") .. hash32(seed .. "|c")
        local data = {
            magic = "DGVAULTKEY1",
            created_at = os.time and os.time() or 0,
            build = tostring(driftgod.BuildNumber or ""),
            profile_label = driftgod.R295_GetRockstarUsername(),
            local_secret = secret,
        }
        if driftgod.SaveTable then driftgod.Try(driftgod.SaveTable, driftgod.Paths.protectedVaultKey, data) end
        return secret
    end

    function driftgod.R295_GetProtectionKey(kind)
        local secret = loadVaultKey()
        local profile = tostring(driftgod.S.r295ProfileLabel or driftgod.R295_GetRockstarUsername() or "local")

        if tostring(kind or "") == "progress" then
            return SCRIPT_SALT .. "|" .. secret .. "|progress|" .. profile
        end
        return SCRIPT_SALT .. "|" .. secret .. "|local-vault"
    end

    function driftgod.R295_SaveProtectedTable(path, kind, tbl, meta)
        ensureProtectedDirs()
        if type(tbl) ~= "table" then return false end
        local plain = serializeTable(tbl)
        local key = driftgod.R295_GetProtectionKey(kind)
        local payload = xorHex(plain, key)
        local checksum = hash32(plain .. "|" .. key .. "|" .. tostring(kind or "data"))
        local container = {
            magic = PROTECTED_MAGIC,
            version = 1,
            kind = tostring(kind or "data"),
            build = tostring(driftgod.BuildNumber or ""),
            date = tostring(driftgod.LastUpdateDate or driftgod.LastUpdated or ""),
            profile_label = tostring(driftgod.S.r295ProfileLabel or driftgod.R295_GetRockstarUsername()),
            checksum = checksum,
            payload = payload,
            meta = meta or {},
        }
        if driftgod.SaveTable then return driftgod.SaveTable(path, container) == true end
        return writeText(path, serializeTable(container))
    end

    function driftgod.R295_LoadProtectedTable(path, expectedKind)
        local container = driftgod.LoadTable and driftgod.LoadTable(path) or nil
        if type(container) ~= "table" then return nil, "missing" end
        if tostring(container.magic or "") ~= PROTECTED_MAGIC then return nil, "bad magic" end
        local kind = tostring(container.kind or "")
        if expectedKind and tostring(expectedKind) ~= "" and kind ~= tostring(expectedKind) then return nil, "wrong kind" end
        local key = driftgod.R295_GetProtectionKey(kind)
        local plain = unxorHex(container.payload or "", key)
        local checksum = hash32(plain .. "|" .. key .. "|" .. kind)
        if checksum ~= tostring(container.checksum or "") then return nil, "checksum" end
        local tbl, err = loadTableFromString(plain)
        if type(tbl) ~= "table" then return nil, err or "decode failed" end
        return tbl, path
    end

    function driftgod.R295_SaveProfileMeta()
        driftgod.S = driftgod.S or {}
        local username = driftgod.R295_GetRockstarUsername()
        driftgod.S.r295RockstarUsername = username
        driftgod.S.r295ProfileLabel = username
        ensureProtectedDirs()
        local meta = {
            rockstar_username = username,
            profile_label = username,
            first_seen = driftgod.S.r295ProfileFirstSeen or (os.time and os.time() or 0),
            last_seen = os.time and os.time() or 0,
            build = tostring(driftgod.BuildNumber or ""),
            version = tostring(driftgod.Version or ""),
            hard_lock_enabled = false,
        }
        driftgod.S.r295ProfileFirstSeen = meta.first_seen
        driftgod.S.r295ProfileLastSeen = meta.last_seen
        driftgod.R295_SaveProtectedTable(driftgod.Paths.protectedProfileMeta, "profile", meta, { label = username })
        return username
    end

    function driftgod.R295_SaveProtectedProgress(data)
        data = data or {}
        if type(data) ~= "table" then return false end
        driftgod.R295_SaveProfileMeta()
        local meta = {
            profile_label = tostring(driftgod.S.r295ProfileLabel or "local"),
            score = tonumber(data.bestScore or data.highScore or data.highestScore or data.currentScore or 0) or 0,
            saved_at = os.time and os.time() or 0,
        }
        local ok1 = driftgod.R295_SaveProtectedTable(driftgod.Paths.protectedProgress, "progress", data, meta)
        ensureProtectedDirs()
        local ok2 = false
        if driftgod.Paths.protectedProfileProgress then
            ok2 = driftgod.R295_SaveProtectedTable(driftgod.Paths.protectedProfileProgress, "progress", data, meta)
        end
        driftgod.S.r295ProtectedProgressLastSaved = ok1 or ok2
        return ok1 or ok2
    end

    function driftgod.R295_LoadProtectedProgress()
        local data, path = nil, nil
        if driftgod.Paths.protectedProfileProgress and fileExists(driftgod.Paths.protectedProfileProgress) then
            data, path = driftgod.R295_LoadProtectedTable(driftgod.Paths.protectedProfileProgress, "progress")
            if type(data) == "table" then return data, path end
        end
        if fileExists(driftgod.Paths.protectedProgress) then
            data, path = driftgod.R295_LoadProtectedTable(driftgod.Paths.protectedProgress, "progress")
            if type(data) == "table" then return data, path end
        end
        return nil, nil
    end

    local function safePresetName(name)
        name = tostring(name or "CustomPreset")
        name = name:gsub("[\\/:%*%?\"<>|]", "_")
        name = name:gsub("%s+", "_")
        name = name:gsub("[^%w_%-%._]", "_")
        name = name:gsub("_+", "_"):gsub("^_+", ""):gsub("_+$", "")
        if name == "" then name = "CustomPreset" end
        if #name > 64 then name = name:sub(1, 64) end
        return name
    end

    local function presetSearchDirs()
        local dirs, seen = {}, {}
        local function add(d)
            d = slash(d or "")
            if d ~= "\\" and d ~= "" and not seen[d:lower()] then seen[d:lower()] = true; dirs[#dirs + 1] = d end
        end
        if driftgod.Paths and driftgod.Paths.storage then add(join(driftgod.Paths.storage, "presets")) end
        if driftgod.StorageDir then add(join(driftgod.StorageDir, "presets")) end
        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then add(tostring(FileMgr.GetMenuRootPath() or "") .. "\\Lua\\DriftGod\\storage\\presets") end
        end)
        return dirs
    end

    local function findPresetFile(name)
        name = safePresetName(name)
        for _, dir in ipairs(presetSearchDirs()) do
            for _, ext in ipairs({ "json", "lua" }) do
                local path = slash(dir) .. name .. "." .. ext
                if fileExists(path) then return path, ext end
            end
        end
        return nil, nil
    end

    function driftgod.R295_MirrorCustomPresetByName(name)
        name = safePresetName(name or driftgod.S.customPresetName or driftgod.S.r214ActiveCustomPreset or driftgod.S.r203ActiveCustomPreset or "CustomPreset")
        local path, ext = findPresetFile(name)
        if not path then return false end
        local raw = readText(path)
        if type(raw) ~= "string" or raw == "" then return false end
        ensureProtectedDirs()
        local tbl = {
            customPresetName = name,
            source_file = tostring(path),
            source_ext = tostring(ext or ""),
            raw = raw,
            mirrored_at = os.time and os.time() or 0,
            build = tostring(driftgod.BuildNumber or ""),
            hard_lock_enabled = false,
        }
        local outPath = join(driftgod.Paths.protectedPresets, name .. ".dgpreset")
        local ok = driftgod.R295_SaveProtectedTable(outPath, "preset", tbl, { name = name, ext = ext })
        driftgod.S.r295LastProtectedPresetName = name
        driftgod.S.r295LastProtectedPresetSaved = ok == true
        return ok == true
    end

    local function wrapSavePreset(fnName)
        local fn = DG[fnName]
        if type(fn) ~= "function" or DG["__R295Wrapped_" .. fnName] then return end
        DG["__R295Wrapped_" .. fnName] = true
        DG[fnName] = function(...)
            local result = fn(...)
            if result ~= false then
                driftgod.Try(driftgod.R295_MirrorCustomPresetByName, driftgod.S and driftgod.S.customPresetName or nil)
            end
            return result
        end
    end

    local function wrapLoadSelected(fnName)

        if type(DG[fnName]) == "function" then DG["__R295ProtectedAware_" .. fnName] = true end
    end

    if type(driftgod.SaveProgressToVault) == "function" and driftgod.__R295SaveProgressToVaultWrapped ~= true then
        driftgod.__R295SaveProgressToVaultWrapped = true
        local oldSaveProgressToVault = driftgod.SaveProgressToVault
        driftgod.SaveProgressToVault = function(data, ...)
            local ok = oldSaveProgressToVault(data, ...)
            if ok == true and type(data) == "table" then driftgod.Try(driftgod.R295_SaveProtectedProgress, data) end
            return ok
        end
    end

    if type(driftgod.LoadBestProgressFromVault) == "function" and driftgod.__R295LoadBestProgressWrapped ~= true then
        driftgod.__R295LoadBestProgressWrapped = true
        local oldLoadBestProgress = driftgod.LoadBestProgressFromVault
        driftgod.LoadBestProgressFromVault = function(...)
            local data, path = oldLoadBestProgress(...)
            if type(data) == "table" then return data, path end
            local pData, pPath = driftgod.R295_LoadProtectedProgress()
            if type(pData) == "table" then
                driftgod.S.r295LoadedProtectedProgressPath = tostring(pPath or "")
                return pData, pPath
            end
            return data, path
        end
    end

    for _, fnName in ipairs({
        "R214_SaveCustomPreset", "R213_SaveCustomPreset", "R212_SaveCustomPreset",
        "R211_SaveCustomPreset", "R210_SaveCustomPreset", "R206_SaveCustomPreset",
        "R205_SaveCustomPreset", "R203_SaveCustomPreset", "R202_SaveCustomPreset",
        "R199_SaveCustomPreset", "R197_SaveCustomPreset",
        "R110_SaveCustomPreset", "R109_SaveCustomPreset"
    }) do wrapSavePreset(fnName) end

    for _, fnName in ipairs({
        "R214_LoadSelectedCustomPreset", "R203_LoadSelectedCustomPreset",
        "R110_ApplyCustomPreset", "R109_LoadSelectedCustomPreset"
    }) do wrapLoadSelected(fnName) end

    ensureProtectedDirs()
    driftgod.Try(driftgod.R295_SaveProfileMeta)

    if not driftgod.__R295ProfileRefreshLoopInstalled and Script and Script.RegisterLooped then
        driftgod.__R295ProfileRefreshLoopInstalled = true
        driftgod.S.r295ProfileRefreshTicks = 0
        Script.RegisterLooped(function()
            if Script and Script.Yield then Script.Yield(2500) end
            if ShouldUnload and ShouldUnload() then return false end
            driftgod.S.r295ProfileRefreshTicks = (tonumber(driftgod.S.r295ProfileRefreshTicks or 0) or 0) + 1
            if driftgod.S.r295ProfileRefreshTicks > 10 then return false end
            driftgod.Try(function()
                local before = tostring(driftgod.S.r295RockstarUsername or "")
                local now = driftgod.R295_GetRockstarUsername()
                if now ~= "" and now ~= before then driftgod.R295_SaveProfileMeta() end
            end)
        end)
    end
end)

