driftgod.Try(function()
    DG = DG or {}; driftgod.S = driftgod.S or {}
    driftgod.Version = "v1.0.1"
    driftgod.BuildNumber = "2026.06.26.309"
    driftgod.BuildDate = "2026-06-26"
    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"
    driftgod.__ProductionPatch = "R309_ProductBuild_1_0_0"

    driftgod.S.stuntComboMinMph = tonumber(driftgod.S.stuntComboMinMph or 20) or 20
    if driftgod.S.stuntComboMinMph < 20 then driftgod.S.stuntComboMinMph = 20 end

    driftgod.S.stuntTierMinMphForUse = 20

    local function getMph()
        if driftgod.GetCurrentVehicleMph then
            local ok, v = driftgod.Try(driftgod.GetCurrentVehicleMph)
            if ok and tonumber(v) then return tonumber(v) or 0 end
        end
        if driftgod.GetCurrentMphForStuntTier then
            local ok, v = driftgod.Try(driftgod.GetCurrentMphForStuntTier)
            if ok and tonumber(v) then return tonumber(v) or 0 end
        end
        if driftgod.GetSpeedMph then
            local ok, v = driftgod.Try(driftgod.GetSpeedMph)
            if ok and tonumber(v) then return tonumber(v) or 0 end
        end
        if driftgod.S and tonumber(driftgod.S.currentMph or 0) then
            return tonumber(driftgod.S.currentMph or 0) or 0
        end
        if driftgod.HasNatives and driftgod.HasNatives() and driftgod.GetVehicle and ENTITY and ENTITY.GET_ENTITY_SPEED then
            local veh = driftgod.GetVehicle()
            if veh and veh ~= 0 then
                local ok, mps = driftgod.Try(ENTITY.GET_ENTITY_SPEED, veh)
                if ok and tonumber(mps) then return (tonumber(mps) or 0) * 2.236936 end
            end
        end
        return 0
    end

    function driftgod.R297_GetCurrentStuntMph()
        return getMph()
    end

    function driftgod.R297_CanCountStuntCombo(name)
        driftgod.S = driftgod.S or {}
        local minMph = tonumber(driftgod.S.stuntComboMinMph or 20) or 20
        if minMph < 20 then minMph = 20 end

        local mph = tonumber(driftgod.S.r297ActiveStuntStartMph or driftgod.S.r297LastStuntStartMph or -1) or -1
        if mph < 0 then mph = getMph() end

        driftgod.S.r297LastComboCheckName = tostring(name or "")
        driftgod.S.r297LastComboCheckMph = mph
        driftgod.S.r297LastComboCheckMinMph = minMph

        return mph >= minMph
    end

    if type(driftgod.QueueStunt) == "function" and driftgod.__R297QueueStuntWrapped ~= true then
        driftgod.__R297QueueStuntWrapped = true
        local oldQueueStunt = driftgod.QueueStunt
        driftgod.QueueStunt = function(name, callback, ...)
            driftgod.S = driftgod.S or {}
            local startMph = getMph()
            driftgod.S.r297LastStuntStartMph = startMph
            driftgod.S.r297ActiveStuntStartMph = startMph
            driftgod.S.r297ActiveStuntName = tostring(name or "")
            return oldQueueStunt(name, callback, ...)
        end
    end

    if type(driftgod.AwardStuntLanding) == "function" and driftgod.__R297AwardStuntLandingWrapped ~= true then
        driftgod.__R297AwardStuntLandingWrapped = true
        local oldAwardStuntLanding = driftgod.AwardStuntLanding
        driftgod.AwardStuntLanding = function(name, ...)
            driftgod.S = driftgod.S or {}

            if not driftgod.R297_CanCountStuntCombo(name) then

                driftgod.S.r297LastNoCountStuntName = tostring(name or "")
                driftgod.S.r297LastNoCountStuntMph = tonumber(driftgod.S.r297LastComboCheckMph or 0) or 0
                driftgod.S.r297LastNoCountReason = "under_mph"
                driftgod.S.lastStuntName = tostring(name or driftgod.S.lastStuntName or "None")
                driftgod.S.lastStuntLanded = false
                driftgod.S.r297ActiveStuntStartMph = nil
                driftgod.S.r297ActiveStuntName = nil
                return false
            end

            driftgod.S.r297ActiveStuntStartMph = nil
            driftgod.S.r297ActiveStuntName = nil
            return oldAwardStuntLanding(name, ...)
        end
    end

    if type(driftgod.CanCountStuntTierUse) == "function" and driftgod.__R297CanCountStuntTierUseWrapped ~= true then
        driftgod.__R297CanCountStuntTierUseWrapped = true
        local oldCanCountStuntTierUse = driftgod.CanCountStuntTierUse
        driftgod.CanCountStuntTierUse = function(stuntName, targetTier, ...)
            local mph = getMph()
            local minMph = tonumber(driftgod.S and driftgod.S.stuntComboMinMph or 20) or 20
            if minMph < 20 then minMph = 20 end
            if mph < minMph then
                if driftgod.S then
                    driftgod.S.r297LastTierNoCountName = tostring(stuntName or "")
                    driftgod.S.r297LastTierNoCountMph = mph
                    driftgod.S.r297LastTierNoCountReason = "under_mph"
                end
                return false, "silent"
            end
            return oldCanCountStuntTierUse(stuntName, targetTier, ...)
        end
    end
end)

driftgod.Try(function()
