    local function bestScore()
        if driftgod.GetArcadeDriftPresetScore then
            local ok, v = driftgod.Try(driftgod.GetArcadeDriftPresetScore)
            if ok and tonumber(v) then return math.floor(math.max(0, tonumber(v) or 0)) end
        end
        driftgod.S = driftgod.S or {}
        local best = tonumber(driftgod.S.bestRunScore or driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore or 0) or 0
        local cur = tonumber(driftgod.S.currentScore or driftgod.S.arcadeRunScore or 0) or 0
        return math.floor(math.max(0, best, cur))
    end

