    function driftgod.R298_GetTransitionEntries()
        driftgod.R271AnimationUnlocks = driftgod.R271AnimationUnlocks or driftgod.R269AnimationUnlocks or driftgod.R272Animations or defaultTransitions
        return driftgod.R271AnimationUnlocks
    end

    function driftgod.R298_EnsureTransitionDefaults()
        driftgod.S = driftgod.S or {}
        local entries = driftgod.R298_GetTransitionEntries()
        local count = #(entries or {})
        if count < 1 then count = 1 end
        driftgod.EasingNames = driftgod.EasingNames or {"linear", "quad_out", "quad_in", "quad_in_out", "sine_out", "sine_in", "sine_in_out", "cubic_out", "cubic_in", "cubic_in_out", "expo_out", "expo_in", "circ_out", "back_out", "bounce_out", "bounce_in"}
        driftgod.S.stuntAnimationSelectedIndex = math.floor(clamp(driftgod.S.stuntAnimationSelectedIndex or driftgod.S.easingLabStyleIndex or driftgod.S.stuntEasingStyleIndex or 1, 1, count))
        driftgod.S.easingLabStyleIndex = math.floor(clamp(driftgod.S.easingLabStyleIndex or driftgod.S.stuntAnimationSelectedIndex or 1, 1, math.max(1, #(driftgod.EasingNames or {}))))
        driftgod.S.stuntEasingStyleIndex = math.floor(clamp(driftgod.S.stuntEasingStyleIndex or driftgod.S.easingLabStyleIndex or 1, 1, math.max(1, #(driftgod.EasingNames or {}))))
        driftgod.S.stuntEasingTestEnabled = driftgod.S.stuntEasingTestEnabled ~= false
        driftgod.S.r298TransitionPreviewStartMs = tonumber(driftgod.S.r298TransitionPreviewStartMs or 0) or 0
        driftgod.S.r298TransitionPreviewDurationMs = tonumber(driftgod.S.r298TransitionPreviewDurationMs or 1250) or 1250
        if driftgod.S.r298TransitionPreviewStartMs <= 0 then driftgod.S.r298TransitionPreviewStartMs = nowMs() end
    end

    local function currentEntry()
        driftgod.R298_EnsureTransitionDefaults()
        local entries = driftgod.R298_GetTransitionEntries()
        return entries[driftgod.S.stuntAnimationSelectedIndex] or entries[1] or defaultTransitions[1]
    end

    local function styleIndexByName(name)
        name = tostring(name or "")
        for i, n in ipairs(driftgod.EasingNames or {}) do
            if tostring(n) == name then return i end
        end
        return 1
    end

    local function applyTransitionIndex(idx)
        driftgod.R298_EnsureTransitionDefaults()
        local entries = driftgod.R298_GetTransitionEntries()
        local count = #(entries or {})
        if count < 1 then return false end
        idx = math.floor(clamp(idx or 1, 1, count))
        local e = entries[idx] or entries[1]
        local need = tonumber(e and e.unlock or 0) or 0
        if bestScore() < need then return false end
        local style = tostring(e.name or "linear")
        local styleIdx = styleIndexByName(style)
        driftgod.S.stuntAnimationSelectedIndex = idx
        driftgod.S.easingLabStyleIndex = styleIdx
        driftgod.S.stuntEasingStyleIndex = styleIdx
        driftgod.S.stuntEasingTestEnabled = true
        driftgod.S.r264LastStuntEasingName = "Selected transition / " .. style
        driftgod.S.r298TransitionPreviewStartMs = nowMs()
        saveQuiet()
        return true
    end

    local function ease(style, elapsed, start, change, dur)
        if driftgod.Ease then
            local ok, v = driftgod.Try(driftgod.Ease, tostring(style or "linear"), elapsed, start, change, dur)
            if ok and tonumber(v) then return tonumber(v) or 0 end
        end
        return (tonumber(start or 0) or 0) + (tonumber(change or 1) or 1) * clamp((tonumber(elapsed or 0) or 0) / math.max(1, tonumber(dur or 1) or 1), 0, 1)
    end

    local function asciiBar(p, width)
        width = math.floor(tonumber(width or 30) or 30)
        local fill = math.floor(width * clamp(p, 0, 1) + 0.5)
        return "[" .. string.rep("█", fill) .. string.rep("░", math.max(0, width - fill)) .. "]"
    end

    function driftgod.R298_RenderTransitionBar()
        driftgod.R298_EnsureTransitionDefaults()
        local e = currentEntry()
        local dur = tonumber(driftgod.S.r298TransitionPreviewDurationMs or 1250) or 1250
        local elapsed = nowMs() - (tonumber(driftgod.S.r298TransitionPreviewStartMs or 0) or 0)
        if elapsed > dur then driftgod.S.r298TransitionPreviewStartMs = nowMs(); elapsed = 0 end
        local p = clamp(ease(tostring(e.name or "linear"), elapsed, 0.0, 1.0, dur), 0, 1)
        if ImGui and ImGui.ProgressBar then
            local ok = driftgod.Try(ImGui.ProgressBar, p, 0, 0, "Transition " .. tostring(math.floor(p * 100)) .. "%")
            if ok then return end
        end
        text("Transition Bar: " .. asciiBar(p, 34) .. " " .. tostring(math.floor(p * 100)) .. "%")
    end

    function driftgod.R298_RenderTransitionDropdown()
        driftgod.R298_EnsureTransitionDefaults()
        local entries = driftgod.R298_GetTransitionEntries()
        local e = currentEntry()
        local score = bestScore()
        text("Selected: " .. tostring(e.label or e.name or "Linear / None"))
        if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
            local opened = false
            driftgod.Try(function() opened = ImGui.BeginCombo("Easing Style##R298StuntTransitionStyle", tostring(e.label or e.name or "Transition")) end)
            if opened then
                for i, entry in ipairs(entries or {}) do
                    local need = tonumber(entry.unlock or 0) or 0
                    local unlocked = score >= need
                    local label = tostring(entry.label or entry.name or "Transition") .. " — " .. tostring(need) .. " pts " .. (unlocked and "[UNLOCKED]" or "[LOCKED]")
                    local clicked = false
                    driftgod.Try(function() clicked = ImGui.Selectable(label, i == driftgod.S.stuntAnimationSelectedIndex) end)
                    if clicked and unlocked then applyTransitionIndex(i) end
                end
                ImGui.EndCombo()
            end
        else
            if ImGui and ImGui.Button and ImGui.Button("< Transition##R298") then
                local nextIdx = (tonumber(driftgod.S.stuntAnimationSelectedIndex or 1) or 1) - 1
                if nextIdx < 1 then nextIdx = #(entries or {}) end
                applyTransitionIndex(nextIdx)
            end
            same()
            if ImGui and ImGui.Button and ImGui.Button("Transition >##R298") then
                local nextIdx = (tonumber(driftgod.S.stuntAnimationSelectedIndex or 1) or 1) + 1
                if nextIdx > #(entries or {}) then nextIdx = 1 end
                applyTransitionIndex(nextIdx)
            end
        end
    end

    function driftgod.R298_RenderTransitionUnlocks()
        driftgod.R298_EnsureTransitionDefaults()
        local score = bestScore()
        text("Unlocks — Best Run: " .. tostring(math.floor(score)))
        for i, entry in ipairs(driftgod.R298_GetTransitionEntries() or {}) do
            local need = tonumber(entry.unlock or 0) or 0
            local unlocked = score >= need
            local selected = i == driftgod.S.stuntAnimationSelectedIndex
            local prefix = selected and "> " or "  "
            text(prefix .. (unlocked and "[UNLOCKED] " or "[LOCKED] ") .. tostring(entry.label or entry.name or "Transition") .. " — " .. tostring(need) .. " pts")
        end
    end

