    driftgod.LastUpdated = "2026-06-26"
    driftgod.LastUpdateDate = "2026-06-26"
    driftgod.__ProductionPatch = "R309_ProductBuild_1_0_0"

    local fallbackTransitions = {
        { name="linear", label="Linear / None", unlock=0 },
        { name="quad_out", label="Quad Out", unlock=1000 },
        { name="quad_in", label="Quad In", unlock=2000 },
        { name="quad_in_out", label="Quad In-Out", unlock=3000 },
        { name="sine_out", label="Sine Out", unlock=4000 },
        { name="sine_in", label="Sine In", unlock=5000 },
        { name="sine_in_out", label="Sine In-Out", unlock=6000 },
        { name="cubic_out", label="Cubic Out", unlock=7000 },
        { name="cubic_in", label="Cubic In", unlock=8000 },
        { name="cubic_in_out", label="Cubic In-Out", unlock=9000 },
        { name="expo_out", label="Expo Out", unlock=10000 },
        { name="expo_in", label="Expo In", unlock=11000 },
        { name="circ_out", label="Circ Out", unlock=12000 },
        { name="back_out", label="Back Out", unlock=13000 },
        { name="bounce_out", label="Bounce Out", unlock=14000 },
        { name="bounce_in", label="Bounce In", unlock=15000 },
    }

    local function score()
        if driftgod.GetArcadeDriftPresetScore then
            local ok, v = driftgod.Try(driftgod.GetArcadeDriftPresetScore)
            if ok and tonumber(v) then return math.floor(math.max(0, tonumber(v) or 0)) end
        end
        local best = tonumber(driftgod.S.bestRunScore or driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore or 0) or 0
        local cur = tonumber(driftgod.S.currentScore or driftgod.S.arcadeRunScore or 0) or 0
        return math.floor(math.max(0, best, cur))
    end

    local function entries()
        if driftgod.R298_GetTransitionEntries then
            local ok, v = driftgod.Try(driftgod.R298_GetTransitionEntries)
            if ok and type(v) == "table" and #v > 0 then return v end
        end
        return fallbackTransitions
    end

    local function fmt(n)
        n = tonumber(n or 0) or 0
        if dgFmtNum then local ok, v = driftgod.Try(dgFmtNum, n); if ok and v then return tostring(v) end end
        if n >= 1000000 then return string.format("%.1fm", n / 1000000) end
        if n >= 1000 then return string.format("%.1fk", n / 1000) end
        return tostring(math.floor(n))
    end

    local function txt(s, color)
        s = tostring(s or "")
        if dgColorText then local ok = driftgod.Try(dgColorText, s, color or "white"); if ok then return end end
        if dgMiniText then local ok = driftgod.Try(dgMiniText, s, color or "white"); if ok then return end end
        if r223Text then local ok = driftgod.Try(r223Text, s, color or "white"); if ok then return end end
        if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, s) end
    end

