        if ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end
    end

    local function flags()
        if dgSafeTableFlags then
            local ok, f = driftgod.Try(dgSafeTableFlags)
            if ok and f then return f end
        end
        return 0
    end

    local function cell(s, color)
        if dgTableCell then local ok = driftgod.Try(dgTableCell, tostring(s or ""), color); if ok then return end end
        txt(s, color)
    end

    local function selectedIndex()
        local list = entries()
        local count = #(list or {})
        if count < 1 then count = 1 end
        local idx = tonumber(driftgod.S.stuntAnimationSelectedIndex or driftgod.S.easingLabStyleIndex or driftgod.S.stuntEasingStyleIndex or 1) or 1
        idx = math.floor(idx)
        if idx < 1 then idx = 1 end
        if idx > count then idx = count end
        return idx
    end

    local function currentLabel()
        local list = entries()
        local e = list[selectedIndex()] or list[1] or {}
        return tostring(e.label or e.name or "Linear / None")
    end

    local function nextUnlock()
        local best = score()
        local bestIdx, bestNeed = nil, nil
        for i, e in ipairs(entries() or {}) do
            local need = tonumber(e.unlock or 0) or 0
            if need > best and (bestNeed == nil or need < bestNeed) then
                bestIdx, bestNeed = i, need
            end
        end
        return bestIdx, bestNeed
    end

    function driftgod.R300_RenderTransitionNextUnlockText()
        local idx, need = nextUnlock()
        if idx and need then
            local e = (entries() or {})[idx] or {}
            txt("Next unlock: " .. tostring(e.label or e.name or "Transition") .. " at " .. fmt(need) .. " pts", "next")
        else
            txt("Next unlock: All transition unlocks earned", "green")
        end
        txt("To view more transition unlocks, go to Arcade > Rewards > Tuning > Transitions.", "dim")
    end

    function driftgod.R300_RenderTransitionRewardsTable()
        local list = entries()
        local best = score()
        local selected = selectedIndex()
        local nextIdx = nextUnlock()

        if ImGui and ImGui.BeginTable and ImGui.BeginTable("DG_R300TransitionRewardsGrid", 6, flags()) then
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0); txt("Status", "header")
            ImGui.TableSetColumnIndex(1); txt("Transition", "header")
            ImGui.TableSetColumnIndex(2); txt("Score", "header")
            ImGui.TableSetColumnIndex(3); txt("Selected", "header")
            ImGui.TableSetColumnIndex(4); txt("Style", "header")
            ImGui.TableSetColumnIndex(5); txt("Next", "header")

            for i, e in ipairs(list or {}) do
                local need = tonumber(e.unlock or 0) or 0
                local unlocked = best >= need
                local isSelected = i == selected
                local status = isSelected and "ACTIVE" or (unlocked and "UNLOCKED" or (i == nextIdx and "NEXT" or "LOCKED"))
                local color = isSelected and "active" or (unlocked and "unlocked" or (i == nextIdx and "next" or "locked"))
                local remaining = math.max(0, need - best)
                ImGui.TableNextRow()
                ImGui.TableSetColumnIndex(0); cell(status, color)
                ImGui.TableSetColumnIndex(1); cell(tostring(e.label or e.name or "Transition"), color)
                ImGui.TableSetColumnIndex(2); cell(need <= 0 and "Starter" or fmt(need), unlocked and "white" or "locked")
                ImGui.TableSetColumnIndex(3); cell(isSelected and "YES" or "--", isSelected and "active" or "dim")
                ImGui.TableSetColumnIndex(4); cell(tostring(e.name or "linear"), color)
                ImGui.TableSetColumnIndex(5); cell(unlocked and "--" or fmt(remaining), i == nextIdx and "next" or "dim")
            end
            ImGui.EndTable()
        else
            for i, e in ipairs(list or {}) do
                local need = tonumber(e.unlock or 0) or 0
                local unlocked = best >= need
                local isSelected = i == selected
                local prefix = isSelected and "ACTIVE" or (unlocked and "UNLOCKED" or "LOCKED")
                txt(prefix .. " | " .. tostring(e.label or e.name or "Transition") .. " | " .. (need <= 0 and "Starter" or fmt(need) .. " pts"), isSelected and "active" or (unlocked and "green" or "dim"))
            end
        end
    end

