    function driftgod.R301_RenderTransitionRewardsTable()
        local list = entries()
        local best = score()
        local selected = selectedIndex()
        local nextEntry = driftgod.R301_GetNextTransitionUnlock()
        local nextNeed = nextEntry and tonumber(nextEntry.unlock or -1) or -1

        if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex and ImGui.EndTable then
            local ok = false
            if dgSafeTableFlags then ok = ImGui.BeginTable("DG_R301_TransitionRewardsTable", 6, dgSafeTableFlags())
            elseif ImGuiTableFlags and ImGuiTableFlags.SizingStretchSame then ok = ImGui.BeginTable("DG_R301_TransitionRewardsTable", 6, ImGuiTableFlags.SizingStretchSame)
            else ok = ImGui.BeginTable("DG_R301_TransitionRewardsTable", 6) end

            if ok then
                ImGui.TableNextRow()
                ImGui.TableSetColumnIndex(0); cell("Status", "header")
                ImGui.TableSetColumnIndex(1); cell("Transition", "header")
                ImGui.TableSetColumnIndex(2); cell("Unlock", "header")
                ImGui.TableSetColumnIndex(3); cell("Selected", "header")
                ImGui.TableSetColumnIndex(4); cell("Style", "header")
                ImGui.TableSetColumnIndex(5); cell("Needed", "header")

                for i, e in ipairs(list) do
                    local need = tonumber(e.unlock or 0) or 0
                    local unlocked = best >= need
                    local active = i == selected
                    local nextOne = (not unlocked) and need == nextNeed
                    local status = active and "ACTIVE" or (unlocked and "UNLOCKED" or (nextOne and "NEXT" or "LOCKED"))
                    local color = active and "active" or (unlocked and "green" or (nextOne and "next" or "dim"))
                    local remaining = math.max(0, need - best)

                    ImGui.TableNextRow()
                    ImGui.TableSetColumnIndex(0); cell(status, color)
                    ImGui.TableSetColumnIndex(1); cell(tostring(e.label or e.name or "Transition"), color)
                    ImGui.TableSetColumnIndex(2); cell(need <= 0 and "Starter" or fmt(need) .. " pts", unlocked and "white" or "dim")
                    ImGui.TableSetColumnIndex(3); cell(active and "YES" or "--", active and "active" or "dim")
                    ImGui.TableSetColumnIndex(4); cell(tostring(e.name or "linear"), color)
                    ImGui.TableSetColumnIndex(5); cell(unlocked and "--" or fmt(remaining), nextOne and "next" or "dim")
                end

                ImGui.EndTable()
                return
            end
        end

        for i, e in ipairs(list) do
            local need = tonumber(e.unlock or 0) or 0
            local unlocked = best >= need
            local active = i == selected
            local status = active and "ACTIVE" or (unlocked and "UNLOCKED" or "LOCKED")
            txt(status .. " | " .. tostring(e.label or e.name or "Transition") .. " | " .. (need <= 0 and "Starter" or fmt(need) .. " pts"), active and "active" or (unlocked and "green" or "dim"))
        end
    end

