            if ok then return end
        end
        if ImGui and ImGui.TextColored then
            local palette = {
                unlocked={0.30,0.95,0.40,1.00}, locked={0.62,0.62,0.62,1.00},
                next={1.00,0.82,0.18,1.00}, active={0.72,0.42,1.00,1.00},
                purple={0.72,0.42,1.00,1.00}, warning={1.00,0.42,0.28,1.00},
