            if ok then return end
        end
        if colorKey then colorText(textValue, colorKey)
        elseif ImGui and ImGui.Text then ImGui.Text(tostring(textValue or "")) end
    end

    local function sep()
        if ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end
    end

    local function fmt(n)
        n = tonumber(n or 0) or 0
        if dgFmtNum then local ok, v = driftgod.Try(dgFmtNum, n); if ok and v then return tostring(v) end end
        local s = tostring(math.floor(n))
        while true do
            local ns, k = s:gsub("^(-?%d+)(%d%d%d)", "%1,%2")
            s = ns
            if k == 0 then break end
        end
        return s
    end

    local function score()
        if driftgod.GetArcadeDriftPresetScore then
            local ok, v = driftgod.Try(driftgod.GetArcadeDriftPresetScore)
            if ok and tonumber(v) then return math.floor(math.max(0, tonumber(v) or 0)) end
        end
        if driftgod.ScoreForUnlock then
            local ok, v = driftgod.Try(driftgod.ScoreForUnlock)
            if ok and tonumber(v) then return math.floor(math.max(0, tonumber(v) or 0)) end
        end
        local best = tonumber(driftgod.S.bestRunScore or driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore or 0) or 0
        local cur = tonumber(driftgod.S.currentScore or driftgod.S.arcadeRunScore or 0) or 0
        return math.floor(math.max(0, best, cur))
    end

    local function entries()
        if driftgod.R298_GetTransitionEntries then
            local ok, v = driftgod.Try(driftgod.R298_GetTransitionEntries)
            if ok and type(v) == "table" and #v > 0 then return v end
        end
