    end

    local function reqFor(e)
        return tonumber((e or {}).unlock or (e or {}).req or (e or {}).score or (e or {}).points or (e or {}).threshold or 0) or 0
    end

    local function labelFor(e)
        return tostring((e or {}).label or (e or {}).short or (e or {}).title or (e or {}).name or "Transition")
    end

    local function styleFor(e)
        return tostring((e or {}).name or (e or {}).style or (e or {}).easing or "linear")
    end

