        local list = entries()
        local idx = tonumber(driftgod.S.stuntAnimationSelectedIndex or driftgod.S.stuntEasingSelectedIndex or driftgod.S.stuntTransitionSelectedIndex or driftgod.S.easingLabStyleIndex or 1) or 1
        idx = math.floor(idx)
        if idx < 1 then idx = 1 end
        if idx > #list then idx = #list end
        return idx
    end

    local function nextIndex(best)
        local idx, need = nil, nil
        for i, e in ipairs(entries()) do
            local req = reqFor(e)
            if req > best and (need == nil or req < need) then
                idx, need = i, req
            end
        end
        return idx, need
    end

    local function statusFor(best, req, isNext, isActive)
        req = tonumber(req or 0) or 0
        if isActive then return "ACTIVE", "active", 0 end
        if req <= 0 or best >= req then return "UNLOCKED", "unlocked", 0 end
        if isNext then return "NEXT", "next", math.max(0, req - best) end
        return "LOCKED", "locked", math.max(0, req - best)
    end

    function driftgod.R303_RenderTransitionRewardsTable()
        local list = entries()
        local best = score()
        local selected = selectedIndex()
        local nextIdx = nextIndex(best)

        if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex and ImGui.EndTable then
            local flags = 0
            if dgSafeTableFlags then local ok, v = driftgod.Try(dgSafeTableFlags); if ok and v then flags = v end end
            if flags == 0 and ImGuiTableFlags and ImGuiTableFlags.SizingStretchSame then flags = ImGuiTableFlags.SizingStretchSame end

            if ImGui.BeginTable("ProgressionTransitionsGrid_R303", 6, flags) then
                ImGui.TableNextRow()
                ImGui.TableSetColumnIndex(0); colorText("Status", "header")
                ImGui.TableSetColumnIndex(1); colorText("Transition", "header")
                ImGui.TableSetColumnIndex(2); colorText("Score", "header")
                ImGui.TableSetColumnIndex(3); colorText("Selected", "header")
                ImGui.TableSetColumnIndex(4); colorText("Style", "header")
                ImGui.TableSetColumnIndex(5); colorText("Next", "header")

                for i, e in ipairs(list) do
                    local req = reqFor(e)
                    local isActive = i == selected
                    local status, color, remaining = statusFor(best, req, i == nextIdx, isActive)
                    local reqText = req <= 0 and "Starter" or fmt(req)
                    local nextText = remaining > 0 and ("Left " .. fmt(remaining)) or "--"

                    ImGui.TableNextRow()
                    ImGui.TableSetColumnIndex(0); tableCell(status, color)
                    ImGui.TableSetColumnIndex(1); tableCell(labelFor(e), color == "locked" and "locked" or nil)
