                    ImGui.TableSetColumnIndex(4); tableCell(styleFor(e), color == "locked" and "locked" or (isActive and "active" or nil))
                    ImGui.TableSetColumnIndex(5); tableCell(nextText, status == "NEXT" and "next" or nil)
                end

