                colorText("Change the transition, then test a stunt to feel the difference.", "warning")
                return
            end
        end

        for i, e in ipairs(list) do
            local bestNow = best
            local req = reqFor(e)
            local status, color, remaining = statusFor(bestNow, req, i == nextIdx, i == selected)
            colorText(status .. " | " .. labelFor(e) .. " | " .. (req <= 0 and "Starter" or fmt(req)) .. " | " .. (remaining > 0 and ("Left " .. fmt(remaining)) or "--"), color)
        end
