function driftgod.R310_GetUtilityScore()
    if driftgod.R102_GetUnlockScore then return tonumber(driftgod.R102_GetUnlockScore() or 0) or 0 end
    if driftgod.GetVehicleSectorProgressScore then return tonumber(driftgod.GetVehicleSectorProgressScore() or 0) or 0 end
    driftgod.S = driftgod.S or {}
    return math.max(
        tonumber(driftgod.S.bestScore or 0) or 0,
        tonumber(driftgod.S.highestScore or 0) or 0,
        tonumber(driftgod.S.previousScore or 0) or 0,
        tonumber(driftgod.S.totalScore or 0) or 0,
        tonumber(driftgod.S.lifetimeScore or 0) or 0
    )
end

function driftgod.IsMakeWayUnlocked()
    return (driftgod.R310_GetUtilityScore() or 0) >= 20000
end

function driftgod.R310_ClearTrafficUnlockScore()
    return 50000
end

function driftgod.R310_IsClearTrafficUnlocked()
    return (driftgod.R310_GetUtilityScore() or 0) >= 50000
end

driftgod.R310_PreUtilityClearTrafficTick = driftgod.R310_PreUtilityClearTrafficTick or driftgod.ClearTrafficTick
function driftgod.ClearTrafficTick()
    driftgod.S = driftgod.S or {}

    if driftgod.R310_IsClearTrafficUnlocked and driftgod.R310_IsClearTrafficUnlocked() ~= true then
        if driftgod.S.clearTrafficEnabled == true then
            driftgod.S.clearTrafficEnabled = false
            driftgod.Try(function()
                if FeatureMgr and FeatureMgr.GetFeature and driftgod.H and driftgod.H.ClearTraffic then
                    local f = FeatureMgr.GetFeature(driftgod.H.ClearTraffic)
                    if f and f.SetValue then f:SetValue(false) end
                end
            end)
        end
        driftgod.S._clearTrafficWasOn = false
        return
    end

    if driftgod.R310_PreUtilityClearTrafficTick then
        return driftgod.R310_PreUtilityClearTrafficTick()
    end
end

driftgod.R310_PreUtilityMakeWayTick = driftgod.R310_PreUtilityMakeWayTick or driftgod.MakeWayTick
function driftgod.MakeWayTick()
    driftgod.S = driftgod.S or {}

    if driftgod.IsMakeWayUnlocked and driftgod.IsMakeWayUnlocked() ~= true then
        if driftgod.S.makeWayLastApplied == true and driftgod.SetCheraxMakeWay then
            driftgod.Try(driftgod.SetCheraxMakeWay, false, "locked")
        end
        return
    end

    if driftgod.R310_PreUtilityMakeWayTick then
        return driftgod.R310_PreUtilityMakeWayTick()
    end
end

driftgod.R310_PreUtilityPlateTick = driftgod.R310_PreUtilityPlateTick or driftgod.DriftGodPlateTick
function driftgod.DriftGodPlateTick()
    driftgod.S = driftgod.S or {}

    if driftgod.R158_IsPlateUnlocked and driftgod.R158_IsPlateUnlocked() ~= true then
        if driftgod.S.driftGodPlateEnabled == true or driftgod.S.autoPlateEnabled == true or driftgod.S.plateEnabled == true or driftgod.S.customPlateEnabled == true then
            driftgod.S.driftGodPlateEnabled = false
            driftgod.S.autoPlateEnabled = false
            driftgod.S.plateEnabled = false
            driftgod.S.customPlateEnabled = false
            if driftgod.RestoreDriftGodPlate then driftgod.Try(driftgod.RestoreDriftGodPlate) end
            driftgod.Try(function()
                if FeatureMgr and FeatureMgr.GetFeature and driftgod.H and driftgod.H.DriftGodPlateToggle then
                    local f = FeatureMgr.GetFeature(driftgod.H.DriftGodPlateToggle)
                    if f and f.SetValue then f:SetValue(false) end
                end
            end)
        end
        return
    end

    if driftgod.R310_PreUtilityPlateTick then
        return driftgod.R310_PreUtilityPlateTick()
    end
end

function driftgod.R310_UtilityFormatNumber(value)
    value = tonumber(value or 0) or 0
    local whole = math.floor(value)
    local text = tostring(whole)

    while true do
        local formatted, count = text:gsub("^(-?%d+)(%d%d%d)", "%1,%2")
        text = formatted
        if count == 0 then break end
    end

    return text
end

function driftgod.R310_UtilityLockedLeftText(required, score)
    required = tonumber(required or 0) or 0
    score = tonumber(score or 0) or 0
    return driftgod.R310_UtilityFormatNumber(math.max(0, required - score)) .. " left"
end

function driftgod.R310_UtilityText(msg, color)
    msg = tostring(msg or "")
    color = tostring(color or "white")

    if type(dgMiniText) == "function" then
        local ok = driftgod.Try(dgMiniText, msg, color)
        if ok then return end
    end

    if type(dgColorText) == "function" then
        local ok = driftgod.Try(dgColorText, msg, color)
        if ok then return end
    end

    if ImGui and ImGui.Text then
        driftgod.Try(ImGui.Text, msg)
    end
end

function driftgod.R310_UtilitySeparator()
    if type(dgMiniSep) == "function" then
        local ok = driftgod.Try(dgMiniSep)
        if ok then return end
    end

    if ImGui and ImGui.Separator then
        driftgod.Try(ImGui.Separator)
    elseif ImGui and ImGui.Spacing then
        driftgod.Try(ImGui.Spacing)
    end
end

function driftgod.R310_UtilityFeature(handle, label)
    if handle ~= nil then
        if type(dgMiniFeature) == "function" then
            local ok = driftgod.Try(dgMiniFeature, handle, label)
            if ok then return true end
        end

        if ClickGUI and ClickGUI.RenderFeature then
            local ok = driftgod.Try(ClickGUI.RenderFeature, handle)
            if ok then return true end
        end
    end

    if label ~= nil then
        driftgod.R310_UtilityText(tostring(label), "dim")
    end

    return false
end

function driftgod.R310_UtilityTable(id, rows)
    rows = rows or {}

    if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex and ImGui.EndTable then
        local ok, opened = driftgod.Try(ImGui.BeginTable, tostring(id or "DG_UtilityTable"), 2, 0)
        if ok and opened then
            for _, row in ipairs(rows) do
                ImGui.TableNextRow()
                ImGui.TableSetColumnIndex(0)
                driftgod.R310_UtilityText(tostring(row[1] or ""), row[3] or "white")
                ImGui.TableSetColumnIndex(1)
                driftgod.R310_UtilityText(tostring(row[2] or ""), row[4] or row[3] or "white")
            end
            ImGui.EndTable()
            return true
        end
    end

    for _, row in ipairs(rows) do
        driftgod.R310_UtilityText(tostring(row[1] or "") .. ": " .. tostring(row[2] or ""), row[4] or row[3] or "white")
    end

    return false
end

function driftgod.R102_RenderUtilitiesMain()
    local utilityScore = driftgod.R310_GetUtilityScore and driftgod.R310_GetUtilityScore() or 0
    local plateReq = driftgod.R158_PlateUnlockScore and driftgod.R158_PlateUnlockScore() or 100
    local plateUnlocked = driftgod.R158_IsPlateUnlocked and driftgod.R158_IsPlateUnlocked() == true
    local makeWayUnlocked = driftgod.IsMakeWayUnlocked and driftgod.IsMakeWayUnlocked() == true
    local headlightsReq = driftgod.R102_HeadlightsUnlockScore and driftgod.R102_HeadlightsUnlockScore() or 7500
    local headlightsUnlocked = driftgod.R102_IsHeadlightsUnlocked and driftgod.R102_IsHeadlightsUnlocked() == true
    local clearTrafficUnlocked = driftgod.R310_IsClearTrafficUnlocked and driftgod.R310_IsClearTrafficUnlocked() == true

    if ClickGUI.BeginCustomChildWindow("Utility Unlocks") then
        driftgod.R310_UtilityText("Utilities", "header")
        driftgod.R310_UtilityTable("DG_R102_UtilityStatus", {
            {"Score", driftgod.R310_UtilityFormatNumber(utilityScore), "white", "gold"},
            {"DriftGod Plate", plateUnlocked and "Unlocked" or driftgod.R310_UtilityLockedLeftText(plateReq, utilityScore), "white", plateUnlocked and "green" or "cyan"},
            {"Headlights", headlightsUnlocked and "Unlocked" or driftgod.R310_UtilityLockedLeftText(headlightsReq, utilityScore), "white", headlightsUnlocked and "green" or "cyan"},
            {"Make Way", makeWayUnlocked and "Unlocked" or driftgod.R310_UtilityLockedLeftText(20000, utilityScore), "white", makeWayUnlocked and "green" or "cyan"},
            {"Clear Traffic", clearTrafficUnlocked and "Unlocked" or driftgod.R310_UtilityLockedLeftText(50000, utilityScore), "white", clearTrafficUnlocked and "green" or "cyan"},
        })
        driftgod.R310_UtilitySeparator()

        if plateUnlocked then
            driftgod.R310_UtilityFeature(driftgod.H.DriftGodPlateToggle, "DriftGod Plate")
        end

        if headlightsUnlocked then
            driftgod.R310_UtilityFeature(driftgod.H.HeadlightsAlwaysToggle, "Headlights")
        end

        if makeWayUnlocked then
            driftgod.R310_UtilityFeature(driftgod.H.MakeWayAutoToggle, "Make Way")
        end

        ClickGUI.EndCustomChildWindow()
    end

    if clearTrafficUnlocked and ClickGUI.BeginCustomChildWindow("Traffic") then
        driftgod.R310_UtilityFeature(driftgod.H.ClearTraffic, "Clear Traffic")
        driftgod.R310_UtilityFeature(driftgod.H.ClearTrafficRadius, "Radius")
        driftgod.R310_UtilityFeature(driftgod.H.ClearTrafficRadiusReset, "Reset Radius")
        ClickGUI.EndCustomChildWindow()
    end
end



