-- ═══════════════════════════════════════════════════════════════════════════════════
-- secure score seal
-- note: score files keep compatibility fields, but trusted score values are sealed.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    _G.driftgod = driftgod
    _G.DG = driftgod
    driftgod.S = driftgod.S or {}

    if driftgod.__ScoreSealInstalled == true then return end
    driftgod.__ScoreSealInstalled = true

    local magic = "DG_SCORE_SEAL_1"
    local legacyImportMaxScore = 250000

    local scoreFields = {
        "bestScore",
        "highScore",
        "highestScore",
        "bestDriftScore",
        "topScore",
        "progressScore",
        "lifetimeScore",
        "totalScore",
        "totalDriftScore",
        "previousScore",
        "lastRunScore",
        "challengeBestScore",
        "todayBestScore",
        "overallScore",
        "bestCombo",
    }

    local function nnum(v)
        local n = tonumber(v or 0) or 0
        if n ~= n or n < 0 then n = 0 end
        if n > 999999999 then n = 999999999 end
        return math.floor(n)
    end

    local function hash32(text)
        text = tostring(text or "")
        local h = 2166136261
        for i = 1, #text do
            h = (h * 16777619 + string.byte(text, i)) % 4294967296
        end
        return string.format("%08x", h)
    end

    local function hashnum(text)
        return tonumber(hash32(text):sub(1, 7), 16) or 0
    end

    local function key()
        local out = ""
        driftgod.Try(function()
            if driftgod.R295_GetProtectionKey then
                out = tostring(driftgod.R295_GetProtectionKey("score") or "")
            end
        end)
        if out == "" then
            local root = ""
            driftgod.Try(function()
                root = tostring((driftgod.Paths and driftgod.Paths.root) or driftgod.RootDir or "")
            end)
            local profile = tostring((driftgod.S and (driftgod.S.r295ProfileLabel or driftgod.S.r295RockstarUsername)) or "local")
            out = "DriftGodScoreSeal|" .. tostring(driftgod.BuildNumber or "") .. "|" .. root .. "|" .. profile
        end
        return out
    end

    local function encodeScore(name, value, serial)
        name = tostring(name or "score")
        serial = nnum(serial)
        local n = nnum(value)
        local k = key()
        local offset = (hashnum(k .. "|" .. name .. "|" .. tostring(serial) .. "|offset") % 7000000) + 331337
        local mul = 37 + (hashnum(k .. "|" .. name .. "|mul") % 19)
        local tail = (hashnum(k .. "|" .. tostring(serial) .. "|" .. name .. "|tail") % 90000) + 10000
        local encoded = (n + offset) * mul + tail
        local sig = hash32(k .. "|" .. name .. "|" .. tostring(n) .. "|" .. tostring(encoded) .. "|" .. tostring(serial) .. "|" .. tostring(mul) .. "|" .. tostring(tail))
        return "dg1." .. tostring(serial) .. "." .. tostring(encoded) .. "." .. sig
    end

    local function decodeScore(name, packed)
        name = tostring(name or "score")
        packed = tostring(packed or "")
        local serialText, encodedText, sig = packed:match("^dg1%.(%d+)%.(%d+)%.([%da-fA-F]+)$")
        if not serialText or not encodedText or not sig then return nil, false end

        local serial = nnum(serialText)
        local encoded = tonumber(encodedText or 0) or 0
        local k = key()
        local offset = (hashnum(k .. "|" .. name .. "|" .. tostring(serial) .. "|offset") % 7000000) + 331337
        local mul = 37 + (hashnum(k .. "|" .. name .. "|mul") % 19)
        local tail = (hashnum(k .. "|" .. tostring(serial) .. "|" .. name .. "|tail") % 90000) + 10000
        local raw = (encoded - tail) / mul - offset
        local n = nnum(math.floor(raw + 0.5))
        local check = hash32(k .. "|" .. name .. "|" .. tostring(n) .. "|" .. tostring(encoded) .. "|" .. tostring(serial) .. "|" .. tostring(mul) .. "|" .. tostring(tail))

        if tostring(check):lower() ~= tostring(sig):lower() then return nil, false end
        return n, true
    end

    local function deepCopy(v, depth)
        depth = tonumber(depth or 0) or 0
        if type(v) ~= "table" then return v end
        if depth > 12 then return {} end
        local out = {}
        for k, val in pairs(v) do
            out[deepCopy(k, depth + 1)] = deepCopy(val, depth + 1)
        end
        return out
    end

    local function highestPlain(t)
        if type(t) ~= "table" then return 0 end
        local best = 0

        for _, field in ipairs(scoreFields) do
            local n = nnum(t[field])
            if n > best then best = n end
        end

        if type(t.highScores) == "table" then
            for _, entry in pairs(t.highScores) do
                local n = nnum(type(entry) == "table" and entry.score or entry)
                if n > best then best = n end
            end
        end

        if type(t.vehicleHighScores) == "table" then
            for _, entry in pairs(t.vehicleHighScores) do
                local n = nnum(type(entry) == "table" and entry.score or entry)
                if n > best then best = n end
            end
        end

        return best
    end

    local function sealChecksum(seal)
        if type(seal) ~= "table" then return "" end
        local parts = { tostring(seal.magic or ""), tostring(seal.version or 0), tostring(seal.serial or 0) }

        if type(seal.fields) == "table" then
            for _, field in ipairs(scoreFields) do
                parts[#parts + 1] = field .. "=" .. tostring(seal.fields[field] or "")
            end
        end

        local function appendRows(label, rows)
            if type(rows) ~= "table" then return end
            for k, row in pairs(rows) do
                if type(row) == "table" then
                    parts[#parts + 1] = label .. ":" .. tostring(k)
                        .. ":" .. tostring(row.score or "")
                        .. ":" .. tostring(row.combo or "")
                        .. ":" .. tostring(row.longest or "")
                end
            end
        end

        appendRows("high", seal.highScores)
        appendRows("veh", seal.vehicleHighScores)

        return hash32(table.concat(parts, "|") .. "|" .. key())
    end

    function driftgod.R311_SealProgressScores(data, sanitizePlain)
        if type(data) ~= "table" then return data end

        local serial = nnum(data.progressSaveSerial or (driftgod.S and driftgod.S.progressSaveSerial) or os.time and os.time() or 1)
        if serial <= 0 then serial = 1 end

        local seal = {
            magic = magic,
            version = 1,
            serial = serial,
            fields = {},
            highScores = {},
            vehicleHighScores = {},
        }

        for _, field in ipairs(scoreFields) do
            seal.fields[field] = encodeScore(field, data[field], serial)
            if sanitizePlain == true then data[field] = 0 end
        end

        if type(data.highScores) == "table" then
            for k, entry in pairs(data.highScores) do
                if type(entry) == "table" then
                    seal.highScores[k] = {
                        score = encodeScore("highScores." .. tostring(k) .. ".score", entry.score, serial),
                        combo = encodeScore("highScores." .. tostring(k) .. ".combo", entry.combo, serial),
                        longest = encodeScore("highScores." .. tostring(k) .. ".longest", entry.longest, serial),
                    }
                    if sanitizePlain == true then
                        entry.score = 0
                        entry.combo = 0
                        entry.longest = 0
                    end
                elseif tonumber(entry) then
                    seal.highScores[k] = {
                        score = encodeScore("highScores." .. tostring(k) .. ".score", entry, serial),
                    }
                    if sanitizePlain == true then data.highScores[k] = 0 end
                end
            end
        end

        if type(data.vehicleHighScores) == "table" then
            for k, entry in pairs(data.vehicleHighScores) do
                if type(entry) == "table" then
                    seal.vehicleHighScores[k] = {
                        score = encodeScore("vehicleHighScores." .. tostring(k) .. ".score", entry.score, serial),
                        combo = encodeScore("vehicleHighScores." .. tostring(k) .. ".combo", entry.combo, serial),
                        longest = encodeScore("vehicleHighScores." .. tostring(k) .. ".longest", entry.longest, serial),
                    }
                    if sanitizePlain == true then
                        entry.score = 0
                        entry.combo = 0
                        entry.longest = 0
                    end
                elseif tonumber(entry) then
                    seal.vehicleHighScores[k] = {
                        score = encodeScore("vehicleHighScores." .. tostring(k) .. ".score", entry, serial),
                    }
                    if sanitizePlain == true then data.vehicleHighScores[k] = 0 end
                end
            end
        end

        seal.checksum = sealChecksum(seal)
        data.secureScoreSeal = seal
        data.scoreStorageMode = "sealed"
        data.scorePlaintextTrusted = false
        return data
    end

    function driftgod.R311_UnsealProgressScores(data)
        if type(data) ~= "table" then return data, false, "not table" end

        local seal = data.secureScoreSeal
        if type(seal) ~= "table" or tostring(seal.magic or "") ~= magic then
            return data, false, "missing"
        end

        local expected = sealChecksum(seal)
        if tostring(expected):lower() ~= tostring(seal.checksum or ""):lower() then
            return data, false, "checksum"
        end

        local decoded = 0

        if type(seal.fields) == "table" then
            for _, field in ipairs(scoreFields) do
                local n, ok = decodeScore(field, seal.fields[field])
                if ok then
                    data[field] = n
                    decoded = decoded + 1
                end
            end
        end

        local function decodeRows(label, rows, target)
            if type(rows) ~= "table" or type(target) ~= "table" then return end
            for k, row in pairs(rows) do
                if type(row) == "table" then
                    if type(target[k]) ~= "table" then target[k] = {} end

                    local n, ok = decodeScore(label .. "." .. tostring(k) .. ".score", row.score)
                    if ok then target[k].score = n; decoded = decoded + 1 end

                    n, ok = decodeScore(label .. "." .. tostring(k) .. ".combo", row.combo)
                    if ok then target[k].combo = n; decoded = decoded + 1 end

                    n, ok = decodeScore(label .. "." .. tostring(k) .. ".longest", row.longest)
                    if ok then target[k].longest = n; decoded = decoded + 1 end
                end
            end
        end

        decodeRows("highScores", seal.highScores, data.highScores)
        decodeRows("vehicleHighScores", seal.vehicleHighScores, data.vehicleHighScores)

        if decoded <= 0 then return data, false, "empty" end

        data.scorePlaintextTrusted = false
        data.scoreStorageMode = "sealed"
        return data, true, "ok"
    end

    local oldExportProgress = driftgod.ExportProgress
    if type(oldExportProgress) == "function" then
        driftgod.ExportProgress = function(...)
            local data = oldExportProgress(...)
            if type(data) == "table" then
                driftgod.R311_SealProgressScores(data, false)
            end
            return data
        end
    end

    local oldApplyProgress = driftgod.ApplyProgress
    if type(oldApplyProgress) == "function" then
        driftgod.ApplyProgress = function(data, ...)
            if type(data) == "table" then
                driftgod.R311_UnsealProgressScores(data)
            end
            return oldApplyProgress(data, ...)
        end
    end

    local oldSaveProgressToVault = driftgod.SaveProgressToVault
    if type(oldSaveProgressToVault) == "function" then
        driftgod.SaveProgressToVault = function(data, ...)
            local full = data
            if type(full) ~= "table" and driftgod.ExportProgress then full = driftgod.ExportProgress() end
            if type(full) ~= "table" then return oldSaveProgressToVault(data, ...) end

            driftgod.R311_SealProgressScores(full, false)

            local public = deepCopy(full)
            driftgod.R311_SealProgressScores(public, true)

            local ok = oldSaveProgressToVault(public, ...)
            if ok == true and driftgod.R295_SaveProtectedProgress then
                driftgod.Try(driftgod.R295_SaveProtectedProgress, full)
            end
            return ok
        end
    end

    local oldLoadBestProgressFromVault = driftgod.LoadBestProgressFromVault
    if type(oldLoadBestProgressFromVault) == "function" then
        driftgod.LoadBestProgressFromVault = function(...)
            local secureBest, securePath, secureScore, secureSerial = nil, nil, -1, -1
            local protectedBest, protectedPath, protectedScore = nil, nil, -1
            local legacyBest, legacyPath, legacyScore = nil, nil, -1

            local function consider(data, path, protected)
                if type(data) ~= "table" then return end
                local copy = deepCopy(data)
                local _, sealed = driftgod.R311_UnsealProgressScores(copy)
                local score = highestPlain(copy)

                if sealed == true then
                    local serial = nnum(copy.progressSaveSerial or (copy.secureScoreSeal and copy.secureScoreSeal.serial) or 0)
                    if score > secureScore or (score == secureScore and serial > secureSerial) then
                        secureBest, securePath, secureScore, secureSerial = copy, path, score, serial
                    end
                    return
                end

                if protected == true then
                    if score > protectedScore then
                        protectedBest, protectedPath, protectedScore = copy, path, score
                    end
                    return
                end

                if score <= legacyImportMaxScore and score > legacyScore then
                    legacyBest, legacyPath, legacyScore = copy, path, score
                end
            end

            if driftgod.GetProgressVaultPaths and driftgod.LoadTable then
                for _, path in ipairs(driftgod.GetProgressVaultPaths() or {}) do
                    consider(driftgod.LoadTable(path), tostring(path or ""), false)
                end
            end

            if driftgod.R295_LoadProtectedProgress then
                local pData, pPath = driftgod.R295_LoadProtectedProgress()
                consider(pData, tostring(pPath or "protected progress"), true)
            end

            if secureBest then
                driftgod.S.r311LoadedScoreSeal = true
                driftgod.S.r311LoadedScoreSealPath = tostring(securePath or "")
                driftgod.S.r311LoadedScoreSealScore = secureScore
                return secureBest, securePath
            end

            if protectedBest then
                driftgod.R311_SealProgressScores(protectedBest, false)
                driftgod.S.r311LoadedProtectedLegacy = true
                driftgod.S.r311LoadedScoreSealPath = tostring(protectedPath or "")
                driftgod.S.r311LoadedScoreSealScore = protectedScore
                return protectedBest, protectedPath
            end

            if legacyBest then
                driftgod.R311_SealProgressScores(legacyBest, false)
                driftgod.S.r311LoadedLegacyProgress = true
                driftgod.S.r311LoadedScoreSealPath = tostring(legacyPath or "")
                driftgod.S.r311LoadedScoreSealScore = legacyScore
                return legacyBest, legacyPath
            end

            return oldLoadBestProgressFromVault(...)
        end
    end

    driftgod.Try(function()
        if driftgod.LoadProgress then driftgod.LoadProgress(false) end
    end)
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- secure score vault
-- note: local scores use per-install sealing, scattered shards, and a trust ledger.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    _G.driftgod = driftgod
    _G.DG = driftgod
    driftgod.S = driftgod.S or {}

    if driftgod.__ScoreVaultV2Installed == true then return end
    driftgod.__ScoreVaultV2Installed = true

    local oldSealProgressScores = driftgod.R311_SealProgressScores
    local oldUnsealProgressScores = driftgod.R311_UnsealProgressScores

    local magic = "DG_SCORE_VAULT_2"
    local keyFileName = "score_vault.dgkey"
    local ledgerFileName = "score_ledger.dgledger"
    local legacyImportMaxScore = 250000
    local oldSealMaxScore = 750000
    local ledgerJumpAllowance = 275000

    local scoreFields = {
        "bestScore",
        "highScore",
        "highestScore",
        "bestDriftScore",
        "topScore",
        "progressScore",
        "lifetimeScore",
        "totalScore",
        "totalDriftScore",
        "previousScore",
        "lastRunScore",
        "challengeBestScore",
        "todayBestScore",
        "overallScore",
        "bestCombo",
    }

    local function nnum(v)
        local n = tonumber(v or 0) or 0
        if n ~= n or n < 0 then n = 0 end
        if n > 999999999 then n = 999999999 end
        return math.floor(n)
    end

    local function hash32(text)
        text = tostring(text or "")
        local h = 2166136261
        for i = 1, #text do
            h = (h ~ string.byte(text, i)) & 0xffffffff
            h = (h * 16777619) & 0xffffffff
        end
        return string.format("%08x", h)
    end

    local function hashnum(text)
        return tonumber(hash32(text):sub(1, 7), 16) or 0
    end

    local function joinPath(a, b)
        a = tostring(a or "")
        b = tostring(b or "")
        if a == "" then return b end
        local last = a:sub(-1)
        if last == "\\" or last == "/" then return a .. b end
        return a .. "\\" .. b
    end

    local function scoreDir()
        local dir = nil
        driftgod.Try(function()
            if driftgod.Paths then
                dir = driftgod.Paths.protected or driftgod.Paths.storage or driftgod.Paths.root
            end
        end)
        if not dir or dir == "" then
            driftgod.Try(function()
                if driftgod.Paths and driftgod.Paths.luaRoot then
                    dir = joinPath(driftgod.Paths.luaRoot, "DriftGod\\protected")
                end
            end)
        end
        if not dir or dir == "" then dir = "DriftGod\\protected" end

        driftgod.Try(function()
            if driftgod.EnsureDir then driftgod.EnsureDir(dir) end
        end)
        driftgod.Try(function()
            if FileMgr and FileMgr.CreateDir then FileMgr.CreateDir(dir) end
        end)

        return dir
    end

    local function readFile(path)
        local out = nil
        driftgod.Try(function()
            local f = io.open(path, "rb")
            if f then out = f:read("*a"); f:close() end
        end)
        return out
    end

    local function writeFile(path, text)
        local ok = false
        driftgod.Try(function()
            local f = io.open(path, "wb")
            if f then f:write(tostring(text or "")); f:close(); ok = true end
        end)
        return ok
    end

    local function profileLabel()
        local out = "local"
        driftgod.Try(function()
            out = tostring((driftgod.S and (driftgod.S.r295ProfileLabel or driftgod.S.r295RockstarUsername or driftgod.S.rockstarUsername)) or "local")
        end)
        if out == "" then out = "local" end
        return out
    end

    local function rootLabel()
        local out = ""
        driftgod.Try(function()
            out = tostring((driftgod.Paths and (driftgod.Paths.root or driftgod.Paths.luaRoot or driftgod.Paths.storage)) or "")
        end)
        return out
    end

    local function makeLocalKey()
        local seed = table.concat({
            tostring(os.time and os.time() or 0),
            tostring(os.clock and os.clock() or 0),
            tostring(math.random and math.random(100000, 999999) or 0),
            tostring({}),
            rootLabel(),
            profileLabel(),
            tostring(driftgod.BuildNumber or ""),
        }, "|")

        local a = hash32(seed .. "|a")
        local b = hash32(seed .. "|" .. a .. "|b")
        local c = hash32(seed .. "|" .. b .. "|c")
        local d = hash32(seed .. "|" .. c .. "|d")
        return "dgsv2." .. a .. b .. c .. d
    end

    local cachedKey = nil

    local function localKey()
        if cachedKey and cachedKey ~= "" then return cachedKey end

        local path = joinPath(scoreDir(), keyFileName)
        local existing = readFile(path)
        if existing and existing:match("^dgsv2%.") then
            cachedKey = existing:gsub("%s+", "")
            return cachedKey
        end

        cachedKey = makeLocalKey()
        writeFile(path, cachedKey)
        return cachedKey
    end

    local function ledgerPath()
        return joinPath(scoreDir(), ledgerFileName)
    end

    local function ledgerSig(serial, score)
        return hash32(localKey() .. "|ledger|" .. tostring(serial or 0) .. "|" .. tostring(score or 0) .. "|" .. profileLabel() .. "|" .. rootLabel())
    end

    local function readLedger()
        local text = readFile(ledgerPath()) or ""
        local serial, score, sig = text:match("^dgsv2ledger|(%d+)|(%d+)|([%da-fA-F]+)$")
        serial = nnum(serial)
        score = nnum(score)
        if serial <= 0 then return 0, 0, false end
        if tostring(sig or ""):lower() ~= ledgerSig(serial, score):lower() then return 0, 0, false end
        return serial, score, true
    end

    local function writeLedger(serial, score)
        serial = nnum(serial)
        score = nnum(score)
        if serial <= 0 then serial = 1 end
        local text = "dgsv2ledger|" .. tostring(serial) .. "|" .. tostring(score) .. "|" .. ledgerSig(serial, score)
        return writeFile(ledgerPath(), text)
    end

    local function highestPlain(t)
        if type(t) ~= "table" then return 0 end
        local best = 0

        for _, field in ipairs(scoreFields) do
            local n = nnum(t[field])
            if n > best then best = n end
        end

        if type(t.highScores) == "table" then
            for _, entry in pairs(t.highScores) do
                local n = nnum(type(entry) == "table" and entry.score or entry)
                if n > best then best = n end
            end
        end

        if type(t.vehicleHighScores) == "table" then
            for _, entry in pairs(t.vehicleHighScores) do
                local n = nnum(type(entry) == "table" and entry.score or entry)
                if n > best then best = n end
            end
        end

        return best
    end

    local function deepCopy(v, depth)
        depth = tonumber(depth or 0) or 0
        if type(v) ~= "table" then return v end
        if depth > 12 then return {} end

        local out = {}
        for k, val in pairs(v) do
            out[deepCopy(k, depth + 1)] = deepCopy(val, depth + 1)
        end
        return out
    end

    local function lane(name, serial, tag)
        return hashnum(localKey() .. "|" .. tostring(name or "") .. "|" .. tostring(serial or 0) .. "|" .. tostring(tag or "") .. "|" .. profileLabel())
    end

    local function fieldId(name, serial)
        return "k" .. hash32(localKey() .. "|id|" .. tostring(name or "") .. "|" .. tostring(serial or 0)):sub(1, 12)
    end

    local function encodeScore(name, value, serial)
        name = tostring(name or "score")
        serial = nnum(serial)
        local score = nnum(value)

        local a = (lane(name, serial, "a") % 9000000) + 700001
        local b = ((lane(name, serial, "b") % 31) * 2) + 37
        local c = (lane(name, serial, "c") % 800000) + 11111
        local d = (lane(name, serial, "d") % 700000) + 33333
        local e = (lane(name, serial, "e") % 600000) + 55555
        local f = (lane(name, serial, "f") % 500000) + 77777

        local packed = (score + a) * b + c
        local shard1 = packed + d
        local shard2 = e
        local shard3 = d + e
        local shard4 = (packed % 9973) + f
        local sig = hash32(localKey() .. "|v2|" .. name .. "|" .. tostring(score) .. "|" .. tostring(serial) .. "|" .. tostring(shard1) .. "|" .. tostring(shard2) .. "|" .. tostring(shard3) .. "|" .. tostring(shard4))

        return {
            q = tostring(shard1),
            r = tostring(shard2),
            s = tostring(shard3),
            t = tostring(shard4),
            u = sig,
        }
    end

    local function decodeScore(name, row, serial)
        if type(row) ~= "table" then return nil, false end
        name = tostring(name or "score")
        serial = nnum(serial)

        local shard1 = tonumber(row.q or 0) or 0
        local shard2 = tonumber(row.r or 0) or 0
        local shard3 = tonumber(row.s or 0) or 0
        local shard4 = tonumber(row.t or 0) or 0
        local sig = tostring(row.u or "")

        local a = (lane(name, serial, "a") % 9000000) + 700001
        local b = ((lane(name, serial, "b") % 31) * 2) + 37
        local c = (lane(name, serial, "c") % 800000) + 11111
        local e = (lane(name, serial, "e") % 500000) + 77777

        local packed = shard1 - (shard3 - shard2)
        local score = nnum(math.floor(((packed - c) / b) - a + 0.5))
        local checkShard4 = (packed % 9973) + e

        if nnum(checkShard4) ~= nnum(shard4) then return nil, false end

        local check = hash32(localKey() .. "|v2|" .. name .. "|" .. tostring(score) .. "|" .. tostring(serial) .. "|" .. tostring(shard1) .. "|" .. tostring(shard2) .. "|" .. tostring(shard3) .. "|" .. tostring(shard4))
        if check:lower() ~= sig:lower() then return nil, false end

        return score, true
    end

    local function sealChecksum(seal)
        if type(seal) ~= "table" then return "" end

        local parts = {
            tostring(seal.magic or ""),
            tostring(seal.version or 0),
            tostring(seal.serial or 0),
            tostring(seal.profile or ""),
            tostring(seal.root or ""),
        }

        local serial = nnum(seal.serial)
        if type(seal.bucket) == "table" then
            for _, field in ipairs(scoreFields) do
                local id = fieldId(field, serial)
                local row = seal.bucket[id]
                if type(row) == "table" then
                    parts[#parts + 1] = id .. ":" .. tostring(row.q) .. ":" .. tostring(row.r) .. ":" .. tostring(row.s) .. ":" .. tostring(row.t) .. ":" .. tostring(row.u)
                end
            end
        end

        local function appendRows(kind, rows)
            if type(rows) ~= "table" then return end
            for k, _ in pairs(rows) do
                local labels = { "score", "combo", "longest" }
                table.sort(labels)
                for _, label in ipairs(labels) do
                    local id = fieldId(kind .. "." .. tostring(k) .. "." .. label, serial)
                    local row = rows[id]
                    if type(row) == "table" then
                        parts[#parts + 1] = kind .. ":" .. id .. ":" .. tostring(row.q) .. ":" .. tostring(row.r) .. ":" .. tostring(row.s) .. ":" .. tostring(row.t) .. ":" .. tostring(row.u)
                    end
                end
            end
        end

        appendRows("highScores", seal.highScores)
        appendRows("vehicleHighScores", seal.vehicleHighScores)

        if type(seal.decoys) == "table" then
            for i = 1, math.min(#seal.decoys, 8) do
                local row = seal.decoys[i]
                if type(row) == "table" then
                    parts[#parts + 1] = "d:" .. tostring(row.q) .. ":" .. tostring(row.r) .. ":" .. tostring(row.s) .. ":" .. tostring(row.t) .. ":" .. tostring(row.u)
                end
            end
        end

        return hash32(table.concat(parts, "|") .. "|" .. localKey())
    end

    local function addDecoys(seal, serial)
        seal.decoys = seal.decoys or {}
        for i = 1, 8 do
            local fakeName = "decoy." .. tostring(i) .. "." .. hash32(localKey() .. "|decoy|" .. tostring(serial) .. "|" .. tostring(i))
            seal.decoys[i] = encodeScore(fakeName, (lane(fakeName, serial, "fake") % 3200000), serial)
        end
    end

    function driftgod.R312_SealProgressScores(data, sanitizePlain)
        if type(data) ~= "table" then return data end

        local serial = nnum(data.progressSaveSerial or (driftgod.S and driftgod.S.progressSaveSerial) or (os.time and os.time() or 1))
        if serial <= 0 then serial = 1 end

        local seal = {
            magic = magic,
            version = 2,
            serial = serial,
            profile = hash32(profileLabel()),
            root = hash32(rootLabel()),
            bucket = {},
            highScores = {},
            vehicleHighScores = {},
        }

        for _, field in ipairs(scoreFields) do
            seal.bucket[fieldId(field, serial)] = encodeScore(field, data[field], serial)
            if sanitizePlain == true then data[field] = 0 end
        end

        if type(data.highScores) == "table" then
            for k, entry in pairs(data.highScores) do
                if type(entry) == "table" then
                    seal.highScores[fieldId("highScores." .. tostring(k) .. ".score", serial)] = encodeScore("highScores." .. tostring(k) .. ".score", entry.score, serial)
                    seal.highScores[fieldId("highScores." .. tostring(k) .. ".combo", serial)] = encodeScore("highScores." .. tostring(k) .. ".combo", entry.combo, serial)
                    seal.highScores[fieldId("highScores." .. tostring(k) .. ".longest", serial)] = encodeScore("highScores." .. tostring(k) .. ".longest", entry.longest, serial)
                    if sanitizePlain == true then
                        entry.score = 0
                        entry.combo = 0
                        entry.longest = 0
                    end
                elseif tonumber(entry) then
                    seal.highScores[fieldId("highScores." .. tostring(k) .. ".score", serial)] = encodeScore("highScores." .. tostring(k) .. ".score", entry, serial)
                    if sanitizePlain == true then data.highScores[k] = 0 end
                end
            end
        end

        if type(data.vehicleHighScores) == "table" then
            for k, entry in pairs(data.vehicleHighScores) do
                if type(entry) == "table" then
                    seal.vehicleHighScores[fieldId("vehicleHighScores." .. tostring(k) .. ".score", serial)] = encodeScore("vehicleHighScores." .. tostring(k) .. ".score", entry.score, serial)
                    seal.vehicleHighScores[fieldId("vehicleHighScores." .. tostring(k) .. ".combo", serial)] = encodeScore("vehicleHighScores." .. tostring(k) .. ".combo", entry.combo, serial)
                    seal.vehicleHighScores[fieldId("vehicleHighScores." .. tostring(k) .. ".longest", serial)] = encodeScore("vehicleHighScores." .. tostring(k) .. ".longest", entry.longest, serial)
                    if sanitizePlain == true then
                        entry.score = 0
                        entry.combo = 0
                        entry.longest = 0
                    end
                elseif tonumber(entry) then
                    seal.vehicleHighScores[fieldId("vehicleHighScores." .. tostring(k) .. ".score", serial)] = encodeScore("vehicleHighScores." .. tostring(k) .. ".score", entry, serial)
                    if sanitizePlain == true then data.vehicleHighScores[k] = 0 end
                end
            end
        end

        addDecoys(seal, serial)
        seal.checksum = sealChecksum(seal)

        data.secureScoreSeal = seal
        data.scoreStorageMode = "sealed-v2"
        data.scorePlaintextTrusted = false

        local best = highestPlain(data)
        if best > 0 then writeLedger(serial, best) end

        return data
    end

    function driftgod.R312_UnsealProgressScores(data)
        if type(data) ~= "table" then return data, false, "not table" end

        local seal = data.secureScoreSeal
        if type(seal) ~= "table" or tostring(seal.magic or "") ~= magic then
            if type(oldUnsealProgressScores) == "function" then
                local copy = deepCopy(data)
                local out, ok, reason = oldUnsealProgressScores(copy)
                local score = highestPlain(copy)

                if ok == true and score <= oldSealMaxScore then
                    driftgod.R312_SealProgressScores(copy, false)
                    return copy, true, "old-seal"
                end

                return data, false, reason or "missing"
            end
            return data, false, "missing"
        end

        local serial = nnum(seal.serial)
        if serial <= 0 then return data, false, "serial" end

        if tostring(seal.checksum or ""):lower() ~= sealChecksum(seal):lower() then
            return data, false, "checksum"
        end

        local decoded = 0

        if type(seal.bucket) == "table" then
            for _, field in ipairs(scoreFields) do
                local n, ok = decodeScore(field, seal.bucket[fieldId(field, serial)], serial)
                if ok == true then
                    data[field] = n
                    decoded = decoded + 1
                end
            end
        end

        local function decodeRows(kind, rows, target)
            if type(rows) ~= "table" or type(target) ~= "table" then return end
            for k, entry in pairs(target) do
                if type(entry) == "table" then
                    local n, ok = decodeScore(kind .. "." .. tostring(k) .. ".score", rows[fieldId(kind .. "." .. tostring(k) .. ".score", serial)], serial)
                    if ok then entry.score = n; decoded = decoded + 1 end

                    n, ok = decodeScore(kind .. "." .. tostring(k) .. ".combo", rows[fieldId(kind .. "." .. tostring(k) .. ".combo", serial)], serial)
                    if ok then entry.combo = n; decoded = decoded + 1 end

                    n, ok = decodeScore(kind .. "." .. tostring(k) .. ".longest", rows[fieldId(kind .. "." .. tostring(k) .. ".longest", serial)], serial)
                    if ok then entry.longest = n; decoded = decoded + 1 end
                else
                    local n, ok = decodeScore(kind .. "." .. tostring(k) .. ".score", rows[fieldId(kind .. "." .. tostring(k) .. ".score", serial)], serial)
                    if ok then target[k] = n; decoded = decoded + 1 end
                end
            end
        end

        decodeRows("highScores", seal.highScores, data.highScores)
        decodeRows("vehicleHighScores", seal.vehicleHighScores, data.vehicleHighScores)

        if decoded <= 0 then return data, false, "empty" end

        local best = highestPlain(data)
        local ledgerSerial, ledgerScore, ledgerOk = readLedger()

        if ledgerOk == true and ledgerScore > 0 and best > (ledgerScore + ledgerJumpAllowance) then
            return data, false, "ledger-jump"
        end

        if best > 0 and (ledgerOk ~= true or best >= ledgerScore or serial >= ledgerSerial) then
            writeLedger(serial, best)
        end

        data.scorePlaintextTrusted = false
        data.scoreStorageMode = "sealed-v2"
        driftgod.S.r312LoadedScoreVault = true
        driftgod.S.r312LoadedScoreVaultScore = best
        return data, true, "ok"
    end

    driftgod.R311_SealProgressScores = driftgod.R312_SealProgressScores
    driftgod.R311_UnsealProgressScores = driftgod.R312_UnsealProgressScores

    local oldLoadBestProgressFromVault = driftgod.LoadBestProgressFromVault
    if type(oldLoadBestProgressFromVault) == "function" then
        driftgod.LoadBestProgressFromVault = function(...)
            local secureBest, securePath, secureScore, secureSerial = nil, nil, -1, -1
            local legacyBest, legacyPath, legacyScore = nil, nil, -1

            local function consider(data, path, protected)
                if type(data) ~= "table" then return end
                local copy = deepCopy(data)
                local _, sealed = driftgod.R312_UnsealProgressScores(copy)
                local score = highestPlain(copy)

                if sealed == true then
                    local serial = nnum(copy.progressSaveSerial or (copy.secureScoreSeal and copy.secureScoreSeal.serial) or 0)
                    if score > secureScore or (score == secureScore and serial > secureSerial) then
                        secureBest, securePath, secureScore, secureSerial = copy, path, score, serial
                    end
                    return
                end

                if protected == true and score <= oldSealMaxScore and score > secureScore then
                    driftgod.R312_SealProgressScores(copy, false)
                    secureBest, securePath, secureScore, secureSerial = copy, path, score, nnum(copy.progressSaveSerial or 1)
                    return
                end

                if score <= legacyImportMaxScore and score > legacyScore then
                    legacyBest, legacyPath, legacyScore = copy, path, score
                end
            end

            if driftgod.GetProgressVaultPaths and driftgod.LoadTable then
                for _, path in ipairs(driftgod.GetProgressVaultPaths() or {}) do
                    consider(driftgod.LoadTable(path), tostring(path or ""), false)
                end
            end

            if driftgod.R295_LoadProtectedProgress then
                local pData, pPath = driftgod.R295_LoadProtectedProgress()
                consider(pData, tostring(pPath or "protected progress"), true)
            end

            if secureBest then
                driftgod.S.r312LoadedScoreVaultPath = tostring(securePath or "")
                driftgod.S.r312LoadedScoreVaultScore = secureScore
                return secureBest, securePath
            end

            if legacyBest then
                driftgod.R312_SealProgressScores(legacyBest, false)
                driftgod.S.r312LoadedLegacyProgress = true
                driftgod.S.r312LoadedScoreVaultPath = tostring(legacyPath or "")
                driftgod.S.r312LoadedScoreVaultScore = legacyScore
                return legacyBest, legacyPath
            end

            return oldLoadBestProgressFromVault(...)
        end
    end

    driftgod.Try(function()
        if driftgod.LoadProgress then driftgod.LoadProgress(false) end
    end)
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime performance compatibility patch
-- note: keeps the original cherax build untouched while reducing repeated hud work.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}

    driftgod.__PrimeBuild = true
    driftgod.__PrimePerformancePatch = "P1_Garage_Stunt_Runtime_Cache"
    driftgod.PrimePerformanceStats = driftgod.PrimePerformanceStats or {
        garageRenderCalls = 0,
        garageRenderSkipped = 0,
        garageRebuildCalls = 0,
        garageRebuildSkipped = 0,
        stuntListBuilds = 0,
        stuntListCacheHits = 0,
        pedCacheHits = 0,
        vehicleCacheHits = 0,
    }

    local primeState = driftgod.__PrimePerformanceState or {
        garageFrame = nil,
        garageLastRenderMs = -1000,
        garageRebuildSignature = nil,
        garageRefreshGeneration = 0,
        stuntList = nil,
        stuntListAt = -1000,
        ped = 0,
        pedAt = -1000,
        vehicle = 0,
        vehicleAt = -1000,
    }
    driftgod.__PrimePerformanceState = primeState

    local function primeNowMs()
        local ms = 0
        driftgod.Try(function()
            if Time and Time.GetEpocheMs then
                ms = tonumber(Time.GetEpocheMs() or 0) or 0
            end
        end)
        if ms <= 0 then
            driftgod.Try(function()
                if os and os.clock then
                    ms = math.floor((tonumber(os.clock() or 0) or 0) * 1000)
                end
            end)
        end
        return ms
    end

    local function primeFrameId()
        local frame = nil

        driftgod.Try(function()
            if MISC and MISC.GET_FRAME_COUNT then
                frame = tonumber(MISC.GET_FRAME_COUNT())
            end
        end)

        if frame == nil then
            driftgod.Try(function()
                if Natives and Natives.InvokeInt then
                    frame = tonumber(Natives.InvokeInt(0xFC8202EFC642E6F2))
                end
            end)
        end

        return frame
    end

    -- Cache the local ped and vehicle for a few milliseconds. DriftGod asks for these
    -- repeatedly inside the same runtime/render pass, and each original lookup invokes
    -- several GTA natives.
    if type(driftgod.GetPed) == "function" and driftgod.__PrimeGetPedWrapped ~= true then
        local originalGetPed = driftgod.GetPed
        driftgod.GetPed = function(...)
            local now = primeNowMs()
            if (now - (primeState.pedAt or -1000)) <= 4 then
                driftgod.PrimePerformanceStats.pedCacheHits = (driftgod.PrimePerformanceStats.pedCacheHits or 0) + 1
                return primeState.ped or 0
            end

            local ped = originalGetPed(...)
            primeState.ped = tonumber(ped or 0) or 0
            primeState.pedAt = now
            return primeState.ped
        end
        driftgod.__PrimeGetPedWrapped = true
    end

    if type(driftgod.GetVehicle) == "function" and driftgod.__PrimeGetVehicleWrapped ~= true then
        local originalGetVehicle = driftgod.GetVehicle
        driftgod.GetVehicle = function(...)
            local now = primeNowMs()
            if (now - (primeState.vehicleAt or -1000)) <= 4 then
                driftgod.PrimePerformanceStats.vehicleCacheHits = (driftgod.PrimePerformanceStats.vehicleCacheHits or 0) + 1
                return primeState.vehicle or 0
            end

            local vehicle = originalGetVehicle(...)
            primeState.vehicle = tonumber(vehicle or 0) or 0
            primeState.vehicleAt = now
            return primeState.vehicle
        end
        driftgod.IsInVehicle = function()
            return (driftgod.GetVehicle and driftgod.GetVehicle() or 0) ~= 0
        end
        driftgod.__PrimeGetVehicleWrapped = true
    end

    -- Cache stunt availability briefly. The Stunt HUD asks for the same list many times
    -- in a single frame and the original function rebuilds multiple tables on every call.
    local function invalidatePrimeStuntCache()
        primeState.stuntList = nil
        primeState.stuntListAt = -1000
    end
    driftgod.InvalidatePrimeStuntCache = invalidatePrimeStuntCache

    if type(driftgod.GetUnlockedTricks) == "function" and driftgod.__PrimeUnlockedTricksWrapped ~= true then
        local originalGetUnlockedTricks = driftgod.GetUnlockedTricks
        driftgod.GetUnlockedTricks = function(...)
            local now = primeNowMs()
            if type(primeState.stuntList) == "table" and (now - (primeState.stuntListAt or -1000)) <= 75 then
                driftgod.PrimePerformanceStats.stuntListCacheHits = (driftgod.PrimePerformanceStats.stuntListCacheHits or 0) + 1
                return primeState.stuntList
            end

            local list = originalGetUnlockedTricks(...)
            if type(list) ~= "table" then list = {} end
            primeState.stuntList = list
            primeState.stuntListAt = now
            driftgod.PrimePerformanceStats.stuntListBuilds = (driftgod.PrimePerformanceStats.stuntListBuilds or 0) + 1
            return list
        end
        driftgod.__PrimeUnlockedTricksWrapped = true
    end

    if type(driftgod.SetStuntHudStuntVisible) == "function" and driftgod.__PrimeStuntVisibilityWrapped ~= true then
        local originalSetStuntHudStuntVisible = driftgod.SetStuntHudStuntVisible
        driftgod.SetStuntHudStuntVisible = function(...)
            local result = originalSetStuntHudStuntVisible(...)
            invalidatePrimeStuntCache()
            return result
        end
        driftgod.__PrimeStuntVisibilityWrapped = true
    end

    if type(driftgod.ApplySettings) == "function" and driftgod.__PrimeApplySettingsWrapped ~= true then
        local originalApplySettings = driftgod.ApplySettings
        driftgod.ApplySettings = function(...)
            local result = originalApplySettings(...)
            invalidatePrimeStuntCache()
            primeState.garageRebuildSignature = nil
            return result
        end
        driftgod.__PrimeApplySettingsWrapped = true
    end

    -- Garage refreshes genuinely change the source list, so mark the filtered cache dirty.
    if type(driftgod.VS_Refresh) == "function" and driftgod.__PrimeVSRefreshWrapped ~= true then
        local originalVSRefresh = driftgod.VS_Refresh
        driftgod.VS_Refresh = function(...)
            primeState.garageRefreshGeneration = (primeState.garageRefreshGeneration or 0) + 1
            primeState.garageRebuildSignature = nil
            return originalVSRefresh(...)
        end
        driftgod.__PrimeVSRefreshWrapped = true
    end

    -- Rebuild the Garage list only when its source, folder, category, or open state changes.
    -- The original renderer calls VS_Rebuild every rendered frame.
    if type(driftgod.VS_Rebuild) == "function" and driftgod.__PrimeVSRebuildWrapped ~= true then
        local originalVSRebuild = driftgod.VS_Rebuild

        local function garageSignature()
            local runtime = driftgod.VS and driftgod.VS.runtime or {}
            local settings = driftgod.S or {}
            local items = runtime.items or {}
            local first = items[1]
            local last = items[#items]

            return table.concat({
                tostring(runtime.open == true),
                tostring(runtime.currentFolder or ""),
                tostring(settings.vehicleSpawnerCategoryIndex or 0),
                tostring(#items),
                tostring(items),
                tostring(first and (first.path or first.name or first.displayLabel) or ""),
                tostring(last and (last.path or last.name or last.displayLabel) or ""),
                tostring(primeState.garageRefreshGeneration or 0),
            }, "|")
        end

        driftgod.VS_Rebuild = function(force, ...)
            local signature = garageSignature()
            local filtered = driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.filtered
            local hasCache = type(filtered) == "table"

            if force ~= true and hasCache and primeState.garageRebuildSignature == signature then
                driftgod.PrimePerformanceStats.garageRebuildSkipped = (driftgod.PrimePerformanceStats.garageRebuildSkipped or 0) + 1
                if driftgod.VS_NormalizeSelection then driftgod.VS_NormalizeSelection() end
                return filtered
            end

            driftgod.PrimePerformanceStats.garageRebuildCalls = (driftgod.PrimePerformanceStats.garageRebuildCalls or 0) + 1
            local result = originalVSRebuild(...)
            primeState.garageRebuildSignature = garageSignature()
            return result
        end
        driftgod.__PrimeVSRebuildWrapped = true
    end

    -- Several bundled compatibility patches can call VS_RenderHud in the same game frame.
    -- Draw it once per frame while leaving all existing controls and visuals intact.
    if type(driftgod.VS_RenderHud) == "function" and driftgod.__PrimeVSRenderWrapped ~= true then
        local originalVSRenderHud = driftgod.VS_RenderHud
        driftgod.VS_RenderHud = function(...)
            if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.open == true) then return end

            driftgod.PrimePerformanceStats.garageRenderCalls = (driftgod.PrimePerformanceStats.garageRenderCalls or 0) + 1

            local frame = primeFrameId()
            local now = primeNowMs()
            if frame ~= nil then
                if primeState.garageFrame == frame then
                    driftgod.PrimePerformanceStats.garageRenderSkipped = (driftgod.PrimePerformanceStats.garageRenderSkipped or 0) + 1
                    return
                end
                primeState.garageFrame = frame
            elseif (now - (primeState.garageLastRenderMs or -1000)) < 5 then
                driftgod.PrimePerformanceStats.garageRenderSkipped = (driftgod.PrimePerformanceStats.garageRenderSkipped or 0) + 1
                return
            end

            primeState.garageLastRenderMs = now
            return originalVSRenderHud(...)
        end
        driftgod.__PrimeVSRenderWrapped = true
    end

    -- The Score HUD checks these visibility functions more than once in the same frame.
    local function wrapShortBooleanCache(name)
        local original = driftgod[name]
        if type(original) ~= "function" or driftgod["__Prime" .. name .. "Wrapped"] == true then return end

        local lastAt = -1000
        local lastValue = false
        driftgod[name] = function(...)
            local now = primeNowMs()
            if (now - lastAt) <= 4 then return lastValue end
            lastValue = original(...) == true
            lastAt = now
            return lastValue
        end
        driftgod["__Prime" .. name .. "Wrapped"] = true
    end

    wrapShortBooleanCache("CanShowScoreHud")
    wrapShortBooleanCache("IsScoreHudVisible")

    local message = "[DriftGod Prime] Performance patch installed: " .. tostring(driftgod.__PrimePerformancePatch)
    if Logger and Logger.LogInfo then
        Logger.LogInfo(message)
    elseif log then
        log(message)
    end
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime compatibility patch p2
-- note: isolates the garage hard-crash path without changing the stable cherax file.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.__PrimePerformancePatch = "P2_Garage_Crash_Isolation"
    driftgod.__PrimeGarageP2 = driftgod.__PrimeGarageP2 or {}

    local P2 = driftgod.__PrimeGarageP2
    P2.lastRenderMs = tonumber(P2.lastRenderMs or -1000) or -1000
    P2.firstRenderLogged = P2.firstRenderLogged == true
    P2.lastError = tostring(P2.lastError or "")

    local function p2Log(message, isError)
        message = "[DriftGod Prime] [Garage P2] " .. tostring(message or "")
        if isError == true and Logger and Logger.LogError then
            Logger.LogError(message)
        elseif Logger and Logger.LogInfo then
            Logger.LogInfo(message)
        elseif log then
            log(message)
        end
    end

    local function p2NowMs()
        local ms = 0
        driftgod.Try(function()
            if Time and Time.GetEpocheMs then
                ms = tonumber(Time.GetEpocheMs() or 0) or 0
            end
        end)
        if ms <= 0 then
            driftgod.Try(function()
                if os and os.clock then ms = math.floor((tonumber(os.clock() or 0) or 0) * 1000) end
            end)
        end
        return ms
    end

    -- Prime can hard-crash when the Garage rebuild changes large FeatureMgr list values
    -- from inside a hotkey/runtime callback. The HUD does not need these dropdown lists,
    -- so P2 keeps them detached while the Garage compatibility path is being tested.
    if driftgod.__PrimeGarageOriginalSyncFeatures == nil then
        driftgod.__PrimeGarageOriginalSyncFeatures = driftgod.VS_SyncFeatures
    end
    driftgod.VS_SyncFeatures = function()
        P2.syncSkipped = (tonumber(P2.syncSkipped or 0) or 0) + 1
        return true
    end

    if type(driftgod.VS_Refresh) == "function" and driftgod.__PrimeGarageP2RefreshWrapped ~= true then
        local previousRefresh = driftgod.VS_Refresh
        driftgod.VS_Refresh = function(...)
            p2Log("vehicle scan begin")
            local ok, result = driftgod.Try(previousRefresh, ...)
            if not ok then
                P2.lastError = tostring(result)
                p2Log("vehicle scan Lua error: " .. tostring(result), true)
                return 0
            end
            p2Log("vehicle scan complete | items=" .. tostring(#((driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.items) or {})))
            return result
        end
        driftgod.__PrimeGarageP2RefreshWrapped = true
    end

    -- Safe open/close path: no FeatureMgr SetList calls, no sound native, and no native
    -- frame-count probe. Data work completes before the first render is allowed.
    function driftgod.VS_SetOpen(openState)
        if driftgod.VS_EnsureDefaults then driftgod.Try(driftgod.VS_EnsureDefaults) end
        if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.hud) then
            p2Log("open failed: Garage runtime unavailable", true)
            return false
        end

        openState = openState == true
        p2Log("set open begin | state=" .. tostring(openState))

        driftgod.VS.runtime.open = openState
        driftgod.VS.hud.lastKeys = {}
        driftgod.VS.runtime.currentFolder = nil
        driftgod.S.vehicleSpawnerIndex = tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0

        if openState then
            driftgod.VS.hud.scroll = 0
            driftgod.VS.hud.inputLockUntil = p2NowMs() + 250

            if #((driftgod.VS.runtime.items) or {}) == 0 and driftgod.VS_Refresh then
                local ok, result = driftgod.Try(driftgod.VS_Refresh)
                if not ok then
                    P2.lastError = tostring(result)
                    driftgod.VS.runtime.open = false
                    p2Log("open refresh error: " .. tostring(result), true)
                    return false
                end
            end

            if driftgod.VS_Rebuild then
                local ok, result = driftgod.Try(driftgod.VS_Rebuild, true)
                if not ok then
                    P2.lastError = tostring(result)
                    driftgod.VS.runtime.open = false
                    p2Log("open rebuild error: " .. tostring(result), true)
                    return false
                end
            end

            P2.firstRenderLogged = false
            P2.lastRenderMs = -1000
            p2Log("garage data ready | items=" .. tostring(#(driftgod.VS.runtime.items or {}))
                .. " | filtered=" .. tostring(#(driftgod.VS.runtime.filtered or {})))
        else
            p2Log("garage closed")
        end

        return true
    end

    function driftgod.VS_ToggleOpen()
        local isOpen = driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.open == true
        return driftgod.VS_SetOpen(not isOpen)
    end

    local function p2DrawRect(x, y, w, h, r, g, b, a)
        if driftgod.DrawRect then
            driftgod.Try(driftgod.DrawRect, x, y, w, h, r, g, b, a)
            return
        end
        driftgod.Try(function()
            if GRAPHICS and GRAPHICS.DRAW_RECT then
                GRAPHICS.DRAW_RECT(x, y, w, h, r, g, b, a, false)
            end
        end)
    end

    local function p2DrawText(text, x, y, scale, r, g, b, a, justify, wrapLeft, wrapRight, maxChars)
        text = tostring(text or "")
        maxChars = tonumber(maxChars or 42) or 42
        if maxChars > 0 and #text > maxChars then text = text:sub(1, math.max(1, maxChars - 3)) .. "..." end

        driftgod.Try(function()
            if not HUD then return end
            if HUD.SET_TEXT_FONT then HUD.SET_TEXT_FONT(4) end
            if HUD.SET_TEXT_SCALE then HUD.SET_TEXT_SCALE(0.0, tonumber(scale or 0.22) or 0.22) end
            if HUD.SET_TEXT_COLOUR then HUD.SET_TEXT_COLOUR(r or 255, g or 255, b or 255, a or 255) end
            if HUD.SET_TEXT_WRAP then HUD.SET_TEXT_WRAP(wrapLeft or 0.0, wrapRight or 1.0) end
            if HUD.SET_TEXT_CENTRE then HUD.SET_TEXT_CENTRE(justify == 0) end
            if HUD.SET_TEXT_RIGHT_JUSTIFY then HUD.SET_TEXT_RIGHT_JUSTIFY(justify == 2) end
            if HUD.SET_TEXT_JUSTIFICATION then HUD.SET_TEXT_JUSTIFICATION(justify or 1) end
            if HUD.SET_TEXT_OUTLINE then HUD.SET_TEXT_OUTLINE() end
            if HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT then HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT("STRING") end
            if HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME then HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME(text) end
            if HUD.END_TEXT_COMMAND_DISPLAY_TEXT then HUD.END_TEXT_COMMAND_DISPLAY_TEXT(x, y, 0) end
        end)
    end

    local PRIME_GARAGE_CONTROLS = { 172, 173, 174, 175, 176, 177, 24, 25, 199, 200, 201, 202 }
    local function p2BlockControls()
        driftgod.Try(function()
            if not (PAD and PAD.DISABLE_CONTROL_ACTION) then return end
            for _, control in ipairs(PRIME_GARAGE_CONTROLS) do
                PAD.DISABLE_CONTROL_ACTION(0, control, true)
            end
        end)
    end

    local function p2RenderGarage()
        if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.open == true) then return end

        local now = p2NowMs()
        -- Multiple legacy workers may call this function. Time-only dedupe avoids the
        -- GET_FRAME_COUNT native that was used by P1 and may be unsafe in Prime.
        if (now - (P2.lastRenderMs or -1000)) < 8 then return end
        P2.lastRenderMs = now

        local firstFrame = P2.firstRenderLogged ~= true
        if firstFrame then p2Log("first render begin") end

        p2BlockControls()
        if firstFrame then p2Log("first render controls complete") end

        if driftgod.VS_HandleInput then
            local ok, err = driftgod.Try(driftgod.VS_HandleInput)
            if not ok then
                P2.lastError = tostring(err)
                p2Log("input Lua error: " .. tostring(err), true)
            end
        end
        if firstFrame then p2Log("first render input complete") end

        local S = driftgod.S or {}
        local runtime = driftgod.VS.runtime
        local hud = driftgod.VS.hud or {}
        local x = tonumber(S.vehicleSpawnerHudX or 0.085) or 0.085
        local y = tonumber(S.vehicleSpawnerHudY or 0.560) or 0.560
        local width = tonumber(S.vehicleSpawnerHudWidth or 0.128) or 0.128
        local opacity = tonumber(S.vehicleSpawnerHudOpacity or 0.50) or 0.50
        if opacity < 0.10 then opacity = 0.10 elseif opacity > 1.0 then opacity = 1.0 end

        local rows, rowH, headerH, subH, footerH = 6, 0.026, 0.040, 0.024, 0.024
        local height = headerH + subH + (rows * rowH) + footerH
        local left, right = x - width / 2, x + width / 2

        p2DrawRect(x, y + height / 2, width + 0.006, height + 0.006, 150, 45, 255, math.floor(85 * opacity))
        p2DrawRect(x, y + height / 2, width, height, 5, 5, 11, math.floor(220 * opacity))
        p2DrawRect(x, y + headerH / 2, width, headerH, 80, 0, 125, math.floor(240 * opacity))
        p2DrawRect(x, y + headerH + subH / 2, width, subH, 0, 0, 0, math.floor(220 * opacity))
        if firstFrame then p2Log("first render background complete") end

        p2DrawText("DRIFTGOD GARAGE", x, y + 0.006, 0.245, 255, 255, 255, 255, 0)
        local folderLabel = runtime.currentFolder and ("/" .. tostring(runtime.currentFolder)) or "Root"
        p2DrawText("[ " .. folderLabel .. " ]", left + 0.009, y + headerH + 0.003, 0.210,
            runtime.currentFolder and 90 or 255, runtime.currentFolder and 255 or 255,
            runtime.currentFolder and 120 or 255, 255, 1, left + 0.006, right - 0.010, 38)

        local filtered = runtime.filtered or {}
        if #filtered <= 0 then
            p2DrawText("No vehicles loaded", left + 0.010, y + headerH + subH + 0.010,
                0.225, 255, 120, 120, 240, 1, left + 0.006, right - 0.010, 38)
        else
            for i = 1, rows do
                local itemIndex = (tonumber(hud.scroll or 0) or 0) + i
                local item = filtered[itemIndex]
                local rowY = y + headerH + subH + ((i - 0.5) * rowH)
                if item then
                    local selected = (itemIndex - 1) == (tonumber(S.vehicleSpawnerIndex or 0) or 0)
                    if selected then
                        p2DrawRect(x, rowY, width - 0.010, rowH - 0.002, 115, 45, 255, math.floor(220 * opacity))
                    else
                        p2DrawRect(x, rowY, width - 0.010, rowH - 0.002, 9, 7, 16, math.floor(205 * opacity))
                    end

                    local label = tostring(item.displayLabel or item.name or "Vehicle")
                    local cr, cg, cb = 245, 245, 255
                    if item.isRandom then cr, cg, cb = 255, 70, 130
                    elseif item.isFolder then cr, cg, cb = 90, 255, 120 end
                    p2DrawText(label, left + 0.009, rowY - 0.010, 0.218, cr, cg, cb, 245, 1,
                        left + 0.006, right - 0.022, 42)
                    if selected then
                        p2DrawText(">", right - 0.010, rowY - 0.010, 0.230, 255, 255, 255, 245, 2,
                            left + 0.006, right - 0.006, 2)
                    end
                end
            end
        end

        local footerY = y + height - footerH / 2
        p2DrawRect(x, footerY, width, footerH, 35, 0, 55, math.floor(235 * opacity))
        p2DrawText(runtime.currentFolder and "ENTER | DEL BACK" or "ENTER | DEL CLOSE",
            x, footerY - 0.009, 0.176, 220, 220, 235, 235, 0)

        if firstFrame then
            P2.firstRenderLogged = true
            p2Log("first render complete")
        end
    end

    driftgod.VS_RenderHud = p2RenderGarage

    p2Log("P2 patch installed | FeatureMgr Garage list sync disabled | native frame probe removed")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime compatibility patch p3
-- note: opens the garage without invoking the legacy vehicle scanner.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.__PrimePerformancePatch = "P3_Garage_Open_Without_Scan"
    driftgod.__PrimeGarageP3 = driftgod.__PrimeGarageP3 or {}

    local P3 = driftgod.__PrimeGarageP3

    local function p3Log(message, isError)
        message = "[DriftGod Prime] [Garage P3] " .. tostring(message or "")
        if isError == true and Logger and Logger.LogError then
            Logger.LogError(message)
        elseif Logger and Logger.LogInfo then
            Logger.LogInfo(message)
        elseif log then
            log(message)
        end
    end

    local function p3NowMs()
        local ms = 0
        driftgod.Try(function()
            if Time and Time.GetEpocheMs then
                ms = tonumber(Time.GetEpocheMs() or 0) or 0
            end
        end)
        if ms <= 0 then
            driftgod.Try(function()
                if os and os.clock then
                    ms = math.floor((tonumber(os.clock() or 0) or 0) * 1000)
                end
            end)
        end
        return ms
    end

    -- Preserve the legacy scanner for a later isolated diagnostic build, but never call
    -- it from the Garage hotkey or F5 in P3. Prime hard-crashed inside that scan path.
    if driftgod.__PrimeUnsafeGarageRefresh == nil then
        driftgod.__PrimeUnsafeGarageRefresh = driftgod.VS_Refresh
    end

    driftgod.VS_Refresh = function()
        P3.blockedScanCount = (tonumber(P3.blockedScanCount or 0) or 0) + 1
        if driftgod.VS and driftgod.VS.runtime then
            driftgod.VS.runtime.lastStatus = "Prime P3: vehicle scan disabled for crash isolation"
        end
        p3Log("vehicle scan blocked safely | count=" .. tostring(P3.blockedScanCount))
        return #(driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.items or {})
    end

    function driftgod.VS_SetOpen(openState)
        if driftgod.VS_EnsureDefaults then driftgod.Try(driftgod.VS_EnsureDefaults) end
        if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.hud) then
            p3Log("open failed: Garage runtime unavailable", true)
            return false
        end

        openState = openState == true
        p3Log("set open begin | state=" .. tostring(openState))

        driftgod.VS.runtime.items = driftgod.VS.runtime.items or {}
        driftgod.VS.runtime.categories = driftgod.VS.runtime.categories or { "All" }
        if #driftgod.VS.runtime.categories == 0 then
            driftgod.VS.runtime.categories[1] = "All"
        end

        driftgod.VS.runtime.open = openState
        driftgod.VS.hud.lastKeys = {}
        driftgod.VS.runtime.currentFolder = nil
        driftgod.S.vehicleSpawnerIndex = tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0

        if openState then
            driftgod.VS.hud.scroll = 0
            driftgod.VS.hud.inputLockUntil = p3NowMs() + 250

            local ok, result = driftgod.Try(function()
                if driftgod.VS_Rebuild then
                    return driftgod.VS_Rebuild(true)
                end
                return true
            end)

            if not ok then
                driftgod.VS.runtime.open = false
                p3Log("cached rebuild Lua error: " .. tostring(result), true)
                return false
            end

            if driftgod.__PrimeGarageP2 then
                driftgod.__PrimeGarageP2.firstRenderLogged = false
                driftgod.__PrimeGarageP2.lastRenderMs = -1000
            end

            p3Log("garage opened without scan | items=" .. tostring(#(driftgod.VS.runtime.items or {}))
                .. " | filtered=" .. tostring(#(driftgod.VS.runtime.filtered or {})))
        else
            p3Log("garage closed")
        end

        return true
    end

    function driftgod.VS_ToggleOpen()
        local isOpen = driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.open == true
        return driftgod.VS_SetOpen(not isOpen)
    end

    p3Log("patch installed | automatic and F5 vehicle scans disabled")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime compatibility patch p6
-- note: restores the confirmed-safe p3 garage open path, keeps none / linear as the
--       default transition, and scans vehicle files only through a manual safe path.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.H = driftgod.H or {}
    driftgod.DefaultSettings = driftgod.DefaultSettings or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or { lastKeys = {}, scroll = 0, inputLockUntil = 0 }

    driftgod.__PrimePerformancePatch = "P6_Safe_Disk_Garage_Linear_Default"
    driftgod.__PrimeGarageP6 = driftgod.__PrimeGarageP6 or {}

    local P6 = driftgod.__PrimeGarageP6
    local PRIME_SCAN_KEY = 0x75 -- F6; F5 conflicts with Damage and Add Checkpoint.

    local function p6Log(message, isError)
        message = "[DriftGod Prime] [Garage P6] " .. tostring(message or "")
        if isError == true and Logger and Logger.LogError then
            Logger.LogError(message)
        elseif Logger and Logger.LogInfo then
            Logger.LogInfo(message)
        elseif log then
            log(message)
        end
    end

    local function nowMs()
        local value = 0
        driftgod.Try(function()
            if Time and Time.GetEpocheMs then
                value = tonumber(Time.GetEpocheMs() or 0) or 0
            end
        end)
        if value <= 0 then
            driftgod.Try(function()
                if os and os.clock then value = math.floor((tonumber(os.clock() or 0) or 0) * 1000) end
            end)
        end
        return value
    end

    local function normalize(path)
        return tostring(path or ""):gsub("/", "\\"):gsub("\\+$", "")
    end

    local function trim(value)
        return tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    end

    local function addUnique(list, seen, value)
        value = normalize(value)
        if value == "" then return end
        local key = value:lower()
        if seen[key] then return end
        seen[key] = true
        list[#list + 1] = value
    end

    local function safeVehicleRoots()
        local roots, seen = {}, {}
        local profile = ""
        driftgod.Try(function() profile = tostring(os.getenv("USERPROFILE") or "") end)
        if profile ~= "" then
            addUnique(roots, seen, profile .. "\\Documents\\Cherax\\Vehicles")
        end

        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then
                local root = normalize(FileMgr.GetMenuRootPath() or "")
                if root ~= "" then
                    addUnique(roots, seen, root .. "\\Vehicles")
                    addUnique(roots, seen, root:gsub("\\Lua$", "") .. "\\Vehicles")
                end
            end
        end)

        return roots
    end

    local allowedExtensions = {
        json = true,
        ini = true,
        xml = true,
        txt = true,
        cfg = true,
        vehicle = true,
        veh = true,
    }

    local function listFilesWithWindowsDir(root)
        local files = {}
        if not (io and io.popen) then
            return files, "io.popen unavailable"
        end

        root = normalize(root)
        if root == "" then return files, "empty root" end
        if root:find('"', 1, true) then return files, "invalid quote in root" end

        local command = 'cmd /d /c dir /b /s /a-d "' .. root .. '\\*" 2>nul'
        local okOpen, pipe = driftgod.Try(io.popen, command, "r")
        if not okOpen or not pipe then
            return files, "io.popen failed: " .. tostring(pipe)
        end

        local okRead, readError = driftgod.Try(function()
            for line in pipe:lines() do
                line = trim(line)
                local ext = line:lower():match("%.([%w_]+)$")
                if line ~= "" and ext and allowedExtensions[ext] then
                    files[#files + 1] = normalize(line)
                end
            end
        end)
        driftgod.Try(function() pipe:close() end)

        if not okRead then return files, tostring(readError) end
        return files, nil
    end

    local function buildDiskItem(root, path)
        local category, relative = "Root", path
        if driftgod.VS_CategoryFromPath then
            local ok, resultCategory, resultRelative = driftgod.Try(driftgod.VS_CategoryFromPath, root, path)
            if ok then
                category = tostring(resultCategory or "Root")
                relative = tostring(resultRelative or path)
            end
        end

        local filename = path:match("([^\\/]+)$") or path
        local name = filename:gsub("%.[%w_]+$", "")
        local ext = filename:lower():match("%.([%w_]+)$") or ""
        local label = name
        if category ~= "" and category ~= "Root" and category ~= "All" then
            label = category .. " / " .. name
        end

        return {
            name = name,
            path = path,
            rel = relative,
            category = category ~= "" and category or "Root",
            displayLabel = label,
            ext = ext,
            root = root,
            primeDiskItem = true,
        }
    end

    function driftgod.VS_PrimeSafeDiskRefresh()
        if P6.scanInProgress == true then
            p6Log("manual scan skipped: scan already running")
            return #(driftgod.VS.runtime.items or {})
        end

        P6.scanInProgress = true
        P6.scanCount = (tonumber(P6.scanCount or 0) or 0) + 1
        p6Log("manual safe disk scan begin | attempt=" .. tostring(P6.scanCount))

        local roots = safeVehicleRoots()
        local items, seenFiles = {}, {}
        local categories, categorySeen = { "All" }, { All = true }

        for _, root in ipairs(roots) do
            p6Log("root scan begin | root=" .. tostring(root))
            local files, err = listFilesWithWindowsDir(root)
            p6Log("root scan complete | root=" .. tostring(root)
                .. " | files=" .. tostring(#files)
                .. (err and (" | note=" .. tostring(err)) or ""))

            for _, path in ipairs(files) do
                local key = normalize(path):lower()
                if not seenFiles[key] then
                    seenFiles[key] = true
                    local item = buildDiskItem(root, path)
                    items[#items + 1] = item
                    if not categorySeen[item.category] then
                        categorySeen[item.category] = true
                        categories[#categories + 1] = item.category
                    end
                end
            end
        end

        table.sort(categories, function(a, b)
            if a == "All" then return true end
            if b == "All" then return false end
            return tostring(a):lower() < tostring(b):lower()
        end)
        table.sort(items, function(a, b)
            local ac, bc = tostring(a.category or ""), tostring(b.category or "")
            if ac:lower() == bc:lower() then
                return tostring(a.name or ""):lower() < tostring(b.name or ""):lower()
            end
            return ac:lower() < bc:lower()
        end)

        driftgod.VS.runtime.items = items
        driftgod.VS.runtime.categories = categories
        driftgod.VS.runtime.currentFolder = nil
        driftgod.VS.runtime.root = roots[1] or ""
        driftgod.VS.runtime.lastScanMs = nowMs()
        driftgod.VS.runtime.lastStatus = "Prime safe disk vehicles: " .. tostring(#items)
        driftgod.S.vehicleSpawnerIndex = 0
        driftgod.S.vehicleSpawnerCategoryIndex = 0
        driftgod.VS.hud.scroll = 0

        local okRebuild, rebuildError = driftgod.Try(function()
            if driftgod.VS_Rebuild then driftgod.VS_Rebuild(true) end
        end)

        P6.scanInProgress = false
        if not okRebuild then
            p6Log("manual safe disk rebuild error: " .. tostring(rebuildError), true)
            return 0
        end

        p6Log("manual safe disk scan complete | roots=" .. tostring(#roots)
            .. " | vehicles=" .. tostring(#items)
            .. " | categories=" .. tostring(#categories))
        return #items
    end

    -- Keep the proven P3 behavior: opening Garage never scans. F5 remains blocked.
    driftgod.VS_Refresh = function()
        P6.blockedLegacyScanCount = (tonumber(P6.blockedLegacyScanCount or 0) or 0) + 1
        driftgod.VS.runtime.lastStatus = "Prime: use F6 for safe vehicle scan"
        p6Log("legacy/F5 scan blocked safely | count=" .. tostring(P6.blockedLegacyScanCount))
        return #(driftgod.VS.runtime.items or {})
    end
    driftgod.R153_ScanVehicleSpawner = driftgod.VS_Refresh
    driftgod.R154_RefreshSpawner = driftgod.VS_Refresh

    -- Debounce the duplicate Garage hotkey callbacks observed on Prime.
    local safeP3SetOpen = driftgod.VS_SetOpen
    driftgod.VS_SetOpen = function(state, ...)
        state = state == true
        local now = nowMs()
        if P6.lastOpenState == state and (now - (tonumber(P6.lastOpenMs or -1000) or -1000)) < 175 then
            p6Log("duplicate open callback suppressed | state=" .. tostring(state))
            return true
        end
        P6.lastOpenState = state
        P6.lastOpenMs = now
        return safeP3SetOpen(state, ...)
    end

    function driftgod.VS_ToggleOpen()
        local open = driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.open == true
        return driftgod.VS_SetOpen(not open)
    end

    local function readTextFile(path)
        local file = nil
        local okOpen = driftgod.Try(function() file = io.open(path, "rb") end)
        if not okOpen or not file then return nil end
        local body = nil
        local okRead = driftgod.Try(function() body = file:read("*a") end)
        driftgod.Try(function() file:close() end)
        if not okRead or type(body) ~= "string" then return nil end
        return body
    end

    local function extractJsonModel(path)
        local text = readTextFile(path)
        if not text or text == "" then return 0, "file unreadable" end

        local numericKeys = { "model", "Model", "modelHash", "ModelHash", "hash", "Hash", "vehicleModel", "VehicleModel" }
        for _, key in ipairs(numericKeys) do
            local value = tonumber(text:match('"' .. key .. '"%s*:%s*([%-]?%d+)') or "")
            if value and value ~= 0 then return value, key end
        end

        local stringKeys = { "modelName", "ModelName", "model", "Model", "vehicle", "Vehicle", "spawnName", "SpawnName" }
        for _, key in ipairs(stringKeys) do
            local value = text:match('"' .. key .. '"%s*:%s*"([^"]+)"')
            if value and value ~= "" and Utils and Utils.Joaat then
                local okHash, hash = driftgod.Try(Utils.Joaat, value)
                hash = okHash and tonumber(hash or 0) or 0
                if hash ~= 0 then return hash, key .. "=" .. value end
            end
        end

        return 0, "no supported model field"
    end

    local function selectRandomDiskItem(targetCategory)
        local pool = {}
        for _, candidate in ipairs(driftgod.VS.runtime.items or {}) do
            if targetCategory == "All" or tostring(candidate.category or "Root"):lower() == tostring(targetCategory or ""):lower() then
                pool[#pool + 1] = candidate
            end
        end
        if #pool == 0 then return nil end
        return pool[math.random(1, #pool)]
    end

    -- P6 deliberately avoids Cherax's Load Vehicle FeatureMgr bridge. For JSON files it
    -- spawns the saved model only; complete saved modifications will be restored later.
    function driftgod.VS_LoadItem(item)
        if not item then
            p6Log("spawn blocked: no item selected", true)
            return false
        end

        if item.isFolder then
            driftgod.VS.runtime.currentFolder = item.folderTarget or item.category
            driftgod.S.vehicleSpawnerIndex = 0
            driftgod.VS.hud.scroll = 0
            if driftgod.VS_Rebuild then driftgod.VS_Rebuild(true) end
            return true
        end

        if item.isRandom then
            item = selectRandomDiskItem(item.randomTargetCategory or "All")
            if not item then
                p6Log("random spawn blocked: no vehicles available", true)
                return false
            end
        end

        local path = tostring(item.path or "")
        if not path:lower():match("%.json$") then
            p6Log("spawn blocked for this diagnostic: only JSON model spawn is supported | file=" .. tostring(path), true)
            return false
        end

        local model, source = extractJsonModel(path)
        if model == 0 then
            p6Log("JSON model extraction failed | file=" .. tostring(path) .. " | reason=" .. tostring(source), true)
            return false
        end

        if type(driftgod.SpawnConfiguredVehicle) ~= "function" then
            p6Log("basic JSON model spawn unavailable: SpawnConfiguredVehicle missing", true)
            return false
        end

        local okSpawn, vehicle = driftgod.Try(function()
            return driftgod.SpawnConfiguredVehicle({ model = model }, tostring(item.name or "Saved Vehicle"))
        end)
        vehicle = tonumber(vehicle or 0) or 0

        if not okSpawn or vehicle == 0 then
            p6Log("basic JSON model spawn failed | model=" .. tostring(model)
                .. " | source=" .. tostring(source)
                .. " | result=" .. tostring(vehicle), true)
            return false
        end

        driftgod.VS.runtime.lastSpawnedName = tostring(item.displayLabel or item.name or "Saved Vehicle")
        driftgod.VS.runtime.lastSpawnedModel = tostring(model)
        driftgod.VS.runtime.lastSpawnedHandle = vehicle
        driftgod.VS.runtime.spawnCount = (tonumber(driftgod.VS.runtime.spawnCount or 0) or 0) + 1
        p6Log("basic JSON model spawned | name=" .. tostring(driftgod.VS.runtime.lastSpawnedName)
            .. " | model=" .. tostring(model)
            .. " | handle=" .. tostring(vehicle)
            .. " | source=" .. tostring(source))
        return true
    end

    function driftgod.VS_HandleInput()
        if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.hud) then return end
        if driftgod.VS_Now and driftgod.VS_Now() < (driftgod.VS.hud.inputLockUntil or 0) then return end

        if driftgod.VS_KeyPressed and driftgod.VS_KeyPressed(PRIME_SCAN_KEY) then
            driftgod.VS_PrimeSafeDiskRefresh()
        end

        local count = #(driftgod.VS.runtime.filtered or {})
        if count <= 0 then
            if driftgod.VS_KeyPressed and driftgod.VS.Keys
                and (driftgod.VS_KeyPressed(driftgod.VS.Keys.DELETE)
                    or driftgod.VS_KeyPressed(driftgod.VS.Keys.LEFT)) then
                driftgod.VS_SetOpen(false)
            end
            return
        end

        if driftgod.VS_KeyPressed and driftgod.VS.Keys and driftgod.VS_KeyPressed(driftgod.VS.Keys.UP) then
            driftgod.S.vehicleSpawnerIndex = (tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0) - 1
            if driftgod.S.vehicleSpawnerIndex < 0 then driftgod.S.vehicleSpawnerIndex = count - 1 end
            if driftgod.VS_NormalizeSelection then driftgod.VS_NormalizeSelection() end
        elseif driftgod.VS_KeyPressed and driftgod.VS.Keys and driftgod.VS_KeyPressed(driftgod.VS.Keys.DOWN) then
            driftgod.S.vehicleSpawnerIndex = (tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0) + 1
            if driftgod.S.vehicleSpawnerIndex >= count then driftgod.S.vehicleSpawnerIndex = 0 end
            if driftgod.VS_NormalizeSelection then driftgod.VS_NormalizeSelection() end
        elseif driftgod.VS_KeyPressed and driftgod.VS.Keys
            and (driftgod.VS_KeyPressed(driftgod.VS.Keys.ENTER)
                or driftgod.VS_KeyPressed(driftgod.VS.Keys.RIGHT)) then
            local item = (driftgod.VS.runtime.filtered or {})[(tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0) + 1]
            if item then
                if item.isFolder then
                    driftgod.VS.runtime.currentFolder = item.folderTarget or item.category
                    driftgod.S.vehicleSpawnerIndex = 0
                    driftgod.VS.hud.scroll = 0
                    if driftgod.VS_Rebuild then driftgod.VS_Rebuild(true) end
                elseif driftgod.VS_QueueSelected then
                    driftgod.VS_QueueSelected()
                end
            end
        elseif driftgod.VS_KeyPressed and driftgod.VS.Keys
            and (driftgod.VS_KeyPressed(driftgod.VS.Keys.DELETE)
                or driftgod.VS_KeyPressed(driftgod.VS.Keys.LEFT)) then
            if driftgod.VS.runtime.currentFolder then
                driftgod.VS.runtime.currentFolder = nil
                driftgod.S.vehicleSpawnerIndex = 0
                driftgod.VS.hud.scroll = 0
                if driftgod.VS_Rebuild then driftgod.VS_Rebuild(true) end
            else
                driftgod.VS_SetOpen(false)
            end
        end
    end

    -- None / Linear is index 1 in DriftGod's production transition tables.
    driftgod.DefaultSettings.stuntAnimationSelectedIndex = 1
    driftgod.DefaultSettings.easingLabStyleIndex = 1
    driftgod.DefaultSettings.stuntEasingStyleIndex = 1
    driftgod.DefaultSettings.stuntEasingSelectedIndex = 1
    driftgod.DefaultSettings.stuntTransitionSelectedIndex = 1

    for _, entries in ipairs({ driftgod.R269AnimationUnlocks, driftgod.R271AnimationUnlocks, driftgod.R272Animations }) do
        if type(entries) == "table" then
            for _, entry in ipairs(entries) do
                if type(entry) == "table" and tostring(entry.name or "") == "linear" then
                    entry.label = "None / Linear"
                    entry.unlock = 0
                end
            end
        end
    end

    if driftgod.S.primeP6LinearTransitionDefaultApplied ~= true then
        driftgod.S.stuntAnimationSelectedIndex = 1
        driftgod.S.easingLabStyleIndex = 1
        driftgod.S.stuntEasingStyleIndex = 1
        driftgod.S.stuntEasingSelectedIndex = 1
        driftgod.S.stuntTransitionSelectedIndex = 1
        driftgod.S.r264LastStuntEasingName = "Selected transition / linear"
        driftgod.S.primeP6LinearTransitionDefaultApplied = true
        if driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
        p6Log("stunt transition default migrated to None / Linear")
    end

    p6Log("patch installed | P3 safe open restored | F6 safe disk scan | no FeatureMgr vehicle-list probes")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime compatibility patch p7
-- note: enumerates the existing cherax vehicles folder through cmd redirection because
--       prime disables io.popen. the scan starts only after the safe garage is open.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or { lastKeys = {}, scroll = 0, inputLockUntil = 0 }

    driftgod.__PrimePerformancePatch = "P7_Command_File_Garage_Scan"
    driftgod.__PrimeGarageP7 = driftgod.__PrimeGarageP7 or {}

    local P7 = driftgod.__PrimeGarageP7
    local allowedExtensions = {
        json = true,
        ini = true,
        xml = true,
        txt = true,
        cfg = true,
        vehicle = true,
        veh = true,
    }

    local function p7Log(message, isError)
        message = "[DriftGod Prime] [Garage P7] " .. tostring(message or "")
        if isError == true and Logger and Logger.LogError then
            Logger.LogError(message)
        elseif Logger and Logger.LogInfo then
            Logger.LogInfo(message)
        elseif log then
            log(message)
        end
    end

    local function normalize(path)
        return tostring(path or ""):gsub("/", "\\"):gsub("\\+$", "")
    end

    local function trim(value)
        return tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    end

    local function getVehicleRoot()
        local profile = ""
        driftgod.Try(function() profile = tostring(os.getenv("USERPROFILE") or "") end)
        if profile ~= "" then
            return normalize(profile .. "\\Documents\\Cherax\\Vehicles")
        end
        return "C:\\Users\\TheValuableAsset\\Documents\\Cherax\\Vehicles"
    end

    local function getTempPath()
        local tempRoot = ""
        driftgod.Try(function() tempRoot = tostring(os.getenv("TEMP") or "") end)
        if tempRoot == "" then
            driftgod.Try(function() tempRoot = tostring(os.getenv("TMP") or "") end)
        end
        if tempRoot == "" then
            tempRoot = getVehicleRoot()
        end
        return normalize(tempRoot) .. "\\DriftGod_Prime_VehicleScan.txt"
    end

    local function enumerateWithCommand(root)
        local files = {}
        root = normalize(root)
        local tempPath = getTempPath()

        driftgod.Try(function()
            if os and os.remove then os.remove(tempPath) end
        end)

        if not (os and os.execute) then
            return files, "os.execute unavailable", tempPath
        end
        if not (io and io.open) then
            return files, "io.open unavailable", tempPath
        end

        -- os.execute already routes through cmd.exe on Windows. Quoted paths preserve spaces.
        local command = 'dir /b /s /a-d "' .. root .. '\\*.*" > "' .. tempPath .. '" 2>nul'
        p7Log("command scan launch | root=" .. tostring(root) .. " | temp=" .. tostring(tempPath))

        local okExecute, resultA, resultB, resultC = driftgod.Try(os.execute, command)
        p7Log("command scan returned | pcall=" .. tostring(okExecute)
            .. " | resultA=" .. tostring(resultA)
            .. " | resultB=" .. tostring(resultB)
            .. " | resultC=" .. tostring(resultC))

        local handle = nil
        local okOpen, openError = driftgod.Try(function()
            handle = io.open(tempPath, "rb")
        end)
        if not okOpen or not handle then
            return files, "temporary scan file unavailable: " .. tostring(openError), tempPath
        end

        local lineCount = 0
        local okRead, readError = driftgod.Try(function()
            for line in handle:lines() do
                lineCount = lineCount + 1
                line = normalize(trim(line))
                local ext = line:lower():match("%.([%w_]+)$")
                if line ~= "" and ext and allowedExtensions[ext] then
                    files[#files + 1] = line
                end
            end
        end)
        driftgod.Try(function() handle:close() end)
        driftgod.Try(function() if os and os.remove then os.remove(tempPath) end end)

        if not okRead then
            return files, "temporary scan read failed: " .. tostring(readError), tempPath
        end

        return files, nil, tempPath, lineCount
    end

    local function buildItem(root, path)
        root = normalize(root)
        path = normalize(path)

        local relative = path
        local rootLower = root:lower()
        local pathLower = path:lower()
        if pathLower:sub(1, #rootLower) == rootLower then
            relative = path:sub(#root + 1):gsub("^\\+", "")
        end

        local filename = path:match("([^\\]+)$") or path
        local name = filename:gsub("%.[%w_]+$", "")
        local category = relative:match("^([^\\]+)\\") or "Root"
        local ext = filename:lower():match("%.([%w_]+)$") or ""
        local label = name
        if category ~= "Root" and category ~= "All" and category ~= "" then
            label = category .. " / " .. name
        end

        return {
            name = name,
            path = path,
            rel = relative,
            category = category,
            displayLabel = label,
            ext = ext,
            root = root,
            primeDiskItem = true,
            primeCommandScanItem = true,
        }
    end

    function driftgod.VS_PrimeSafeDiskRefresh()
        if P7.scanInProgress == true then
            p7Log("scan skipped: already running")
            return #(driftgod.VS.runtime.items or {})
        end

        P7.scanInProgress = true
        P7.scanAttempts = (tonumber(P7.scanAttempts or 0) or 0) + 1

        local root = getVehicleRoot()
        p7Log("command-file scan begin | attempt=" .. tostring(P7.scanAttempts)
            .. " | root=" .. tostring(root))

        local files, scanError, tempPath, rawLineCount = enumerateWithCommand(root)
        p7Log("command-file enumeration complete | rawLines=" .. tostring(rawLineCount or 0)
            .. " | supportedFiles=" .. tostring(#files)
            .. (scanError and (" | note=" .. tostring(scanError)) or ""))

        local items = {}
        local seen = {}
        local categories = { "All" }
        local categorySeen = { All = true }

        for _, path in ipairs(files) do
            local key = normalize(path):lower()
            if not seen[key] then
                seen[key] = true
                local item = buildItem(root, path)
                items[#items + 1] = item
                if not categorySeen[item.category] then
                    categorySeen[item.category] = true
                    categories[#categories + 1] = item.category
                end
            end
        end

        table.sort(categories, function(a, b)
            if a == "All" then return true end
            if b == "All" then return false end
            return tostring(a):lower() < tostring(b):lower()
        end)
        table.sort(items, function(a, b)
            local ac = tostring(a.category or "")
            local bc = tostring(b.category or "")
            if ac:lower() == bc:lower() then
                return tostring(a.name or ""):lower() < tostring(b.name or ""):lower()
            end
            return ac:lower() < bc:lower()
        end)

        driftgod.VS.runtime.items = items
        driftgod.VS.runtime.categories = categories
        driftgod.VS.runtime.currentFolder = nil
        driftgod.VS.runtime.root = root
        driftgod.VS.runtime.lastStatus = "Prime vehicle files: " .. tostring(#items)
        driftgod.S.vehicleSpawnerIndex = 0
        driftgod.S.vehicleSpawnerCategoryIndex = 0
        driftgod.VS.hud.scroll = 0

        local okRebuild, rebuildError = driftgod.Try(function()
            if driftgod.VS_Rebuild then driftgod.VS_Rebuild(true) end
        end)

        P7.scanInProgress = false
        P7.lastScanCount = #items
        P7.lastScanError = tostring(scanError or "")
        P7.lastTempPath = tostring(tempPath or "")

        if not okRebuild then
            p7Log("garage rebuild error: " .. tostring(rebuildError), true)
            return 0
        end

        p7Log("command-file scan complete | vehicles=" .. tostring(#items)
            .. " | categories=" .. tostring(#categories)
            .. " | first=" .. tostring(items[1] and items[1].path or "none")
            .. " | last=" .. tostring(items[#items] and items[#items].path or "none"))

        return #items
    end

    -- Open through the confirmed-safe P6/P3 path first. Scan in a queued job only after
    -- the first Garage frame has had time to render, avoiding work inside the hotkey callback.
    local previousSetOpen = driftgod.VS_SetOpen
    driftgod.VS_SetOpen = function(state, ...)
        state = state == true
        local result = previousSetOpen(state, ...)

        if state == true and result ~= false and P7.autoScanQueued ~= true
            and #(driftgod.VS.runtime.items or {}) == 0 then
            P7.autoScanQueued = true

            local function runAutoScan()
                driftgod.Try(function()
                    if Script and Script.Yield then Script.Yield(180) end
                end)

                if driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.open == true then
                    p7Log("delayed automatic scan starting")
                    driftgod.VS_PrimeSafeDiskRefresh()
                else
                    p7Log("delayed automatic scan skipped: Garage closed")
                end

                P7.autoScanQueued = false
            end

            if Script and Script.QueueJob then
                Script.QueueJob(runAutoScan)
            else
                runAutoScan()
            end
        end

        return result
    end

    function driftgod.VS_ToggleOpen()
        local open = driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.open == true
        return driftgod.VS_SetOpen(not open)
    end

    p7Log("patch installed | exact Cherax Vehicles path | automatic command-file scan after safe open")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime compatibility patch p8
-- note: disables p7 automatic command scanning and uses one documented non-recursive
--       FileMgr.FindFiles call from a manual FeatureMgr button.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or { lastKeys = {}, scroll = 0, inputLockUntil = 0 }

    driftgod.__PrimePerformancePatch = "P8_Manual_FileMgr_Root_JSON"
    driftgod.__PrimeGarageP8 = driftgod.__PrimeGarageP8 or {}
    local P8 = driftgod.__PrimeGarageP8

    -- Prevent the P7 wrapper from launching os.execute automatically when Garage opens.
    if driftgod.__PrimeGarageP7 then
        driftgod.__PrimeGarageP7.autoScanQueued = true
    end

    local VEHICLE_ROOT = "C:\\Users\\TheValuableAsset\\Documents\\Cherax\\Vehicles"

    local function p8Log(message, isError)
        message = "[DriftGod Prime] [Garage P8] " .. tostring(message or "")
        if isError == true and Logger and Logger.LogError then
            Logger.LogError(message)
        elseif Logger and Logger.LogInfo then
            Logger.LogInfo(message)
        elseif log then
            log(message)
        end
    end

    local function normalize(path)
        return tostring(path or ""):gsub("/", "\\"):gsub("\\+$", "")
    end

    local function buildItem(path)
        path = normalize(path)
        if path ~= "" and not path:match("^[A-Za-z]:\\") then
            path = VEHICLE_ROOT .. "\\" .. path:gsub("^\\+", "")
        end

        local filename = path:match("([^\\]+)$") or path
        local name = filename:gsub("%.[Jj][Ss][Oo][Nn]$", "")
        return {
            name = name,
            path = path,
            rel = filename,
            category = "Root",
            displayLabel = name,
            ext = "json",
            root = VEHICLE_ROOT,
            primeDiskItem = true,
            primeFileMgrItem = true,
        }
    end

    function driftgod.VS_PrimeRootJsonRefresh()
        if P8.scanInProgress == true then
            p8Log("scan skipped: already running")
            return #(driftgod.VS.runtime.items or {})
        end

        P8.scanInProgress = true
        P8.scanAttempts = (tonumber(P8.scanAttempts or 0) or 0) + 1
        p8Log("manual root JSON scan begin | attempt=" .. tostring(P8.scanAttempts)
            .. " | root=" .. VEHICLE_ROOT
            .. " | extension=.json | recursive=false")

        if not (FileMgr and FileMgr.FindFiles) then
            P8.scanInProgress = false
            p8Log("scan unavailable: FileMgr.FindFiles missing", true)
            return 0
        end

        -- Keep this as one isolated documented call. Do not add FeatureMgr probes,
        -- recursive traversal, or additional extensions until Prime confirms it is safe.
        p8Log("FileMgr.FindFiles call entering")
        local okFind, found = driftgod.Try(function()
            return FileMgr.FindFiles(VEHICLE_ROOT, ".json", false)
        end)
        p8Log("FileMgr.FindFiles call returned | pcall=" .. tostring(okFind)
            .. " | type=" .. tostring(type(found)))

        if not okFind then
            P8.scanInProgress = false
            p8Log("FileMgr.FindFiles Lua error: " .. tostring(found), true)
            return 0
        end

        if type(found) ~= "table" then found = {} end

        local items = {}
        local seen = {}
        for _, path in pairs(found) do
            path = normalize(path)
            local key = path:lower()
            if path ~= "" and not seen[key] then
                seen[key] = true
                items[#items + 1] = buildItem(path)
            end
        end

        table.sort(items, function(a, b)
            return tostring(a.name or ""):lower() < tostring(b.name or ""):lower()
        end)

        driftgod.VS.runtime.items = items
        driftgod.VS.runtime.categories = { "All", "Root" }
        driftgod.VS.runtime.currentFolder = nil
        driftgod.VS.runtime.root = VEHICLE_ROOT
        driftgod.VS.runtime.lastStatus = "Prime root JSON vehicles: " .. tostring(#items)
        driftgod.S.vehicleSpawnerIndex = 0
        driftgod.S.vehicleSpawnerCategoryIndex = 0
        driftgod.VS.hud.scroll = 0

        local okRebuild, rebuildError = driftgod.Try(function()
            if driftgod.VS_Rebuild then driftgod.VS_Rebuild(true) end
        end)

        P8.scanInProgress = false
        P8.lastScanCount = #items

        if not okRebuild then
            p8Log("garage rebuild error: " .. tostring(rebuildError), true)
            return 0
        end

        p8Log("manual root JSON scan complete | vehicles=" .. tostring(#items)
            .. " | first=" .. tostring(items[1] and items[1].path or "none")
            .. " | last=" .. tostring(items[#items] and items[#items].path or "none"))
        return #items
    end

    -- Route the existing DriftGod "Scan Cherax Vehicles" feature to the isolated P8 scan.
    driftgod.VS_PrimeSafeDiskRefresh = driftgod.VS_PrimeRootJsonRefresh
    driftgod.VS_Refresh = driftgod.VS_PrimeRootJsonRefresh
    driftgod.R153_ScanVehicleSpawner = driftgod.VS_PrimeRootJsonRefresh
    driftgod.R154_RefreshSpawner = driftgod.VS_PrimeRootJsonRefresh

    -- Add an unmistakable manual button. It runs only after the user activates it.
    if driftgod.SafeAddFeature and Utils and Utils.Joaat and eFeatureType and eFeatureType.Button then
        local hash = Utils.Joaat("DG_PRIME_GARAGE_SCAN_ROOT_JSON_P8")
        driftgod.SafeAddFeature(
            hash,
            "Prime Garage: Scan Root JSON",
            eFeatureType.Button,
            "Prime diagnostic: scans C:\\Users\\TheValuableAsset\\Documents\\Cherax\\Vehicles for root-level .json files only.",
            function()
                driftgod.VS_PrimeRootJsonRefresh()
            end
        )
        P8.featureHash = hash
    end

    -- Keep Garage opening on the confirmed-safe P3/P6 path with no automatic scan.
    p8Log("patch installed | Garage opens without scan | use FeatureMgr button 'Prime Garage: Scan Root JSON'")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime compatibility patch p9
-- note: decodes Prime's userdata result returned by FileMgr.FindFiles instead of
--       discarding it as an empty Lua table.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or { lastKeys = {}, scroll = 0, inputLockUntil = 0 }

    driftgod.__PrimePerformancePatch = "P9_FileMgr_Userdata_Adapter"
    driftgod.__PrimeGarageP9 = driftgod.__PrimeGarageP9 or {}
    local P9 = driftgod.__PrimeGarageP9
    local VEHICLE_ROOT = "C:\\Users\\TheValuableAsset\\Documents\\Cherax\\Vehicles"

    local function p9Log(message, isError)
        message = "[DriftGod Prime] [Garage P9] " .. tostring(message or "")
        if isError == true and Logger and Logger.LogError then
            Logger.LogError(message)
        elseif Logger and Logger.LogInfo then
            Logger.LogInfo(message)
        elseif log then
            log(message)
        end
    end

    local function normalize(path)
        return tostring(path or ""):gsub("/", "\\"):gsub("\\+$", "")
    end

    local function valueToPath(value)
        if value == nil then return nil end
        if type(value) == "string" then return normalize(value) end

        local candidates = {}
        local function addCandidate(v)
            if type(v) == "string" and v ~= "" then candidates[#candidates + 1] = v end
        end

        driftgod.Try(function() addCandidate(value.path) end)
        driftgod.Try(function() addCandidate(value.Path) end)
        driftgod.Try(function() addCandidate(value.filename) end)
        driftgod.Try(function() addCandidate(value.FileName) end)

        for _, methodName in ipairs({ "string", "String", "ToString", "GetPath", "GetString" }) do
            driftgod.Try(function()
                local fn = value[methodName]
                if type(fn) == "function" then addCandidate(fn(value)) end
            end)
        end

        local rendered = tostring(value or "")
        if rendered ~= "" and not rendered:match("^userdata:") then
            addCandidate(rendered)
        end

        for _, candidate in ipairs(candidates) do
            candidate = normalize(candidate)
            if candidate ~= "" then return candidate end
        end
        return nil
    end

    local function decodeCollection(collection, sourceLabel)
        local output, seen = {}, {}

        local function add(value)
            local path = valueToPath(value)
            if not path or path == "" then return false end
            local key = path:lower()
            if seen[key] then return false end
            seen[key] = true
            output[#output + 1] = path
            return true
        end

        if type(collection) == "table" then
            for _, value in pairs(collection) do add(value) end
            p9Log("collection decoded | source=" .. tostring(sourceLabel)
                .. " | type=table | extracted=" .. tostring(#output))
            return output
        end

        if type(collection) ~= "userdata" then
            p9Log("collection decode unsupported | source=" .. tostring(sourceLabel)
                .. " | type=" .. tostring(type(collection)))
            return output
        end

        local reportedLength = -1
        local lengthOk, lengthValue = driftgod.Try(function() return #collection end)
        if lengthOk then reportedLength = tonumber(lengthValue or -1) or -1 end

        local methodCount = -1
        local methodUsed = "none"
        for _, name in ipairs({ "size", "Size", "GetSize", "count", "Count", "GetCount" }) do
            local ok, result = driftgod.Try(function()
                local fn = collection[name]
                if type(fn) == "function" then return fn(collection) end
                return nil
            end)
            result = ok and tonumber(result) or nil
            if result and result >= 0 then
                methodCount = result
                methodUsed = name
                break
            end
        end

        local count = math.max(reportedLength, methodCount)
        if count > 10000 then count = 10000 end

        local indexMode = "none"
        if count >= 0 then
            local before = #output
            for i = 1, count do
                local ok, value = driftgod.Try(function() return collection[i] end)
                if ok and value ~= nil then add(value) end
            end
            if #output > before then indexMode = "one-based" end

            if #output == before then
                for i = 0, math.max(0, count - 1) do
                    local ok, value = driftgod.Try(function() return collection[i] end)
                    if ok and value ~= nil then add(value) end
                end
                if #output > before then indexMode = "zero-based" end
            end
        end

        if #output == 0 then
            local okIpairs = driftgod.Try(function()
                for _, value in ipairs(collection) do add(value) end
            end)
            if okIpairs and #output > 0 then indexMode = "ipairs" end
        end

        if #output == 0 then
            local okPairs = driftgod.Try(function()
                for _, value in pairs(collection) do add(value) end
            end)
            if okPairs and #output > 0 then indexMode = "pairs" end
        end

        if #output == 0 and count < 0 then
            -- Last-resort bounded probes for userdata containers without __len.
            local consecutiveNil = 0
            for i = 1, 4096 do
                local ok, value = driftgod.Try(function() return collection[i] end)
                if ok and value ~= nil then
                    add(value)
                    consecutiveNil = 0
                else
                    consecutiveNil = consecutiveNil + 1
                    if consecutiveNil >= 8 then break end
                end
            end
            if #output > 0 then indexMode = "bounded-one-based" end
        end

        local mtType = "nil"
        driftgod.Try(function() mtType = tostring(type(getmetatable(collection))) end)
        p9Log("collection decoded | source=" .. tostring(sourceLabel)
            .. " | type=userdata"
            .. " | lenOk=" .. tostring(lengthOk)
            .. " | len=" .. tostring(reportedLength)
            .. " | method=" .. tostring(methodUsed)
            .. " | methodCount=" .. tostring(methodCount)
            .. " | indexMode=" .. tostring(indexMode)
            .. " | metatableType=" .. tostring(mtType)
            .. " | extracted=" .. tostring(#output))

        if #output > 0 then
            p9Log("collection sample | first=" .. tostring(output[1])
                .. " | last=" .. tostring(output[#output]))
        end

        return output
    end

    local function buildItem(path)
        path = normalize(path)
        if path ~= "" and not path:match("^[A-Za-z]:\\") then
            path = VEHICLE_ROOT .. "\\" .. path:gsub("^\\+", "")
        end

        local relative = path
        local rootLower = VEHICLE_ROOT:lower()
        if path:lower():sub(1, #rootLower) == rootLower then
            relative = path:sub(#VEHICLE_ROOT + 1):gsub("^\\+", "")
        end

        local filename = path:match("([^\\]+)$") or path
        local name = filename:gsub("%.[Jj][Ss][Oo][Nn]$", "")
        local category = relative:match("^([^\\]+)\\") or "Root"
        local label = category ~= "Root" and (category .. " / " .. name) or name

        return {
            name = name,
            path = path,
            rel = relative,
            category = category,
            displayLabel = label,
            ext = "json",
            root = VEHICLE_ROOT,
            primeDiskItem = true,
            primeFileMgrItem = true,
            primeP9Item = true,
        }
    end

    local function runFind(extension, recursive, label)
        p9Log("FindFiles entering | label=" .. tostring(label)
            .. " | extension=" .. tostring(extension)
            .. " | recursive=" .. tostring(recursive))

        local ok, result = driftgod.Try(function()
            return FileMgr.FindFiles(VEHICLE_ROOT, extension, recursive)
        end)

        p9Log("FindFiles returned | label=" .. tostring(label)
            .. " | pcall=" .. tostring(ok)
            .. " | type=" .. tostring(type(result)))

        if not ok then
            p9Log("FindFiles Lua error | label=" .. tostring(label)
                .. " | error=" .. tostring(result), true)
            return {}
        end

        return decodeCollection(result, label)
    end

    function driftgod.VS_PrimeRootJsonRefresh()
        if P9.scanInProgress == true then
            p9Log("scan skipped: already running")
            return #(driftgod.VS.runtime.items or {})
        end

        if not (FileMgr and FileMgr.FindFiles) then
            p9Log("scan unavailable: FileMgr.FindFiles missing", true)
            return 0
        end

        P9.scanInProgress = true
        P9.scanAttempts = (tonumber(P9.scanAttempts or 0) or 0) + 1
        p9Log("userdata-aware JSON scan begin | attempt=" .. tostring(P9.scanAttempts)
            .. " | root=" .. VEHICLE_ROOT)

        local files = runFind(".json", false, "dot-json-root")
        if #files == 0 then
            files = runFind("json", false, "json-root")
        end
        if #files == 0 then
            files = runFind(".json", true, "dot-json-recursive")
        end
        if #files == 0 then
            files = runFind("json", true, "json-recursive")
        end

        local items, seen = {}, {}
        local categories, categorySeen = { "All" }, { All = true }

        for _, path in ipairs(files) do
            path = normalize(path)
            local key = path:lower()
            if path ~= "" and not seen[key] then
                seen[key] = true
                local item = buildItem(path)
                items[#items + 1] = item
                if not categorySeen[item.category] then
                    categorySeen[item.category] = true
                    categories[#categories + 1] = item.category
                end
            end
        end

        table.sort(categories, function(a, b)
            if a == "All" then return true end
            if b == "All" then return false end
            return tostring(a):lower() < tostring(b):lower()
        end)
        table.sort(items, function(a, b)
            local ac, bc = tostring(a.category or ""), tostring(b.category or "")
            if ac:lower() == bc:lower() then
                return tostring(a.name or ""):lower() < tostring(b.name or ""):lower()
            end
            return ac:lower() < bc:lower()
        end)

        driftgod.VS.runtime.items = items
        driftgod.VS.runtime.categories = categories
        driftgod.VS.runtime.currentFolder = nil
        driftgod.VS.runtime.root = VEHICLE_ROOT
        driftgod.VS.runtime.lastStatus = "Prime JSON vehicles: " .. tostring(#items)
        driftgod.S.vehicleSpawnerIndex = 0
        driftgod.S.vehicleSpawnerCategoryIndex = 0
        driftgod.VS.hud.scroll = 0

        local okRebuild, rebuildError = driftgod.Try(function()
            if driftgod.VS_Rebuild then driftgod.VS_Rebuild(true) end
        end)

        P9.scanInProgress = false
        P9.lastScanCount = #items

        if not okRebuild then
            p9Log("garage rebuild error: " .. tostring(rebuildError), true)
            return 0
        end

        p9Log("userdata-aware JSON scan complete | vehicles=" .. tostring(#items)
            .. " | categories=" .. tostring(#categories)
            .. " | first=" .. tostring(items[1] and items[1].path or "none")
            .. " | last=" .. tostring(items[#items] and items[#items].path or "none"))
        return #items
    end

    driftgod.VS_PrimeSafeDiskRefresh = driftgod.VS_PrimeRootJsonRefresh
    driftgod.VS_Refresh = driftgod.VS_PrimeRootJsonRefresh
    driftgod.R153_ScanVehicleSpawner = driftgod.VS_PrimeRootJsonRefresh
    driftgod.R154_RefreshSpawner = driftgod.VS_PrimeRootJsonRefresh

    -- Remove the old P8 diagnostic button and replace it with the userdata-aware scan.
    driftgod.Try(function()
        if driftgod.__PrimeGarageP8 and driftgod.__PrimeGarageP8.featureHash
            and FeatureMgr and FeatureMgr.RemoveFeature then
            FeatureMgr.RemoveFeature(driftgod.__PrimeGarageP8.featureHash)
        end
    end)

    if driftgod.SafeAddFeature and Utils and Utils.Joaat and eFeatureType and eFeatureType.Button then
        local hash = Utils.Joaat("DG_PRIME_GARAGE_SCAN_USERDATA_P9")
        driftgod.SafeAddFeature(
            hash,
            "Prime Garage: Decode Vehicle Files",
            eFeatureType.Button,
            "Reads Prime's userdata result from FileMgr.FindFiles and populates the DriftGod Garage.",
            function()
                driftgod.VS_PrimeRootJsonRefresh()
            end
        )
        P9.featureHash = hash
    end

    p9Log("patch installed | FileMgr userdata adapter | manual scan only")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime garage p10 - full cherax json vehicle restore
-- note: replaces the model-only diagnostic spawn with saved vehicle data application.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or { runtime = {}, hud = {} }
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or {}

    driftgod.__PrimeGarageP10 = driftgod.__PrimeGarageP10 or {
        patch = "P10_Full_Cherax_JSON_Restore",
        applies = 0,
        failures = 0,
    }
    local P10 = driftgod.__PrimeGarageP10

    local function p10Log(message, important)
        message = "[DriftGod Prime] [Garage P10] " .. tostring(message or "")
        if Logger and Logger.LogInfo then
            if important == true and Logger.LogError then Logger.LogError(message)
            else Logger.LogInfo(message) end
        elseif driftgod.Log then
            driftgod.Log(message)
        end
    end

    local function readVehicleFile(path)
        path = tostring(path or "")
        if path == "" then return nil, "empty path" end

        if FileMgr and FileMgr.ReadFileContent then
            local ok, body = driftgod.Try(function() return FileMgr.ReadFileContent(path) end)
            if ok and type(body) == "string" and body ~= "" then
                return body, "FileMgr.ReadFileContent"
            end
        end

        local file = nil
        local okOpen = driftgod.Try(function() file = io.open(path, "rb") end)
        if okOpen and file then
            local body = nil
            local okRead = driftgod.Try(function() body = file:read("*a") end)
            driftgod.Try(function() file:close() end)
            if okRead and type(body) == "string" and body ~= "" then
                return body, "io.open"
            end
        end

        return nil, "file unreadable"
    end

    local function numberField(text, ...)
        local keys = { ... }
        for _, key in ipairs(keys) do
            local value = text:match('"' .. key .. '"%s*:%s*([%-]?[%d%.]+)')
            if value ~= nil then return tonumber(value) end
        end
        return nil
    end

    local function stringField(text, ...)
        local keys = { ... }
        for _, key in ipairs(keys) do
            local value = text:match('"' .. key .. '"%s*:%s*"(.-)"')
            if value ~= nil then
                value = value:gsub('\\"', '"'):gsub('\\\\', '\\')
                return value
            end
        end
        return nil
    end

    local function boolField(text, ...)
        local keys = { ... }
        for _, key in ipairs(keys) do
            local raw = text:match('"' .. key .. '"%s*:%s*([%a%d]+)')
            if raw ~= nil then
                raw = tostring(raw):lower()
                if raw == "true" or raw == "1" then return true end
                if raw == "false" or raw == "0" then return false end
            end
        end
        return nil
    end

    local function objectSection(text, key, maxLength)
        local startPos = text:find('"' .. tostring(key) .. '"', 1, true)
        if not startPos then return "" end
        return text:sub(startPos, math.min(#text, startPos + (tonumber(maxLength or 1200) or 1200)))
    end

    local function colorObject(text, ...)
        local keys = { ... }
        for _, key in ipairs(keys) do
            local section = objectSection(text, key, 500)
            if section ~= "" then
                local r = numberField(section, "r", "R", "red", "Red")
                local g = numberField(section, "g", "G", "green", "Green")
                local b = numberField(section, "b", "B", "blue", "Blue")
                if r ~= nil and g ~= nil and b ~= nil then
                    return { r = r, g = g, b = b }
                end

                local ar, ag, ab = section:match('%[%s*(%d+)%s*,%s*(%d+)%s*,%s*(%d+)')
                if ar then return { r = tonumber(ar), g = tonumber(ag), b = tonumber(ab) } end
            end
        end
        return nil
    end

    local KRZ_MOD_INDEX = {
        MOD_SPOILERS=0, MOD_FRONTBUMPER=1, MOD_REARBUMPER=2, MOD_SIDESKIRT=3,
        MOD_EXHAUST=4, MOD_FRAME=5, MOD_GRILLE=6, MOD_HOOD=7, MOD_FENDER=8,
        MOD_RIGHTFENDER=9, MOD_ROOF=10, MOD_ENGINE=11, MOD_BRAKES=12,
        MOD_TRANSMISSION=13, MOD_HORNS=14, MOD_SUSPENSION=15, MOD_ARMOR=16,
        MOD_TURBO=18, MOD_TIRESMOKE=20, MOD_XENONHEADLIGHTS=22,
        MOD_FRONTWHEEL=23, MOD_REARWHEEL=24, MOD_PLATEHOLDER=25,
        MOD_VANITYPLATES=26, MOD_TRIM=27, MOD_TRIMDESIGN=27, MOD_ORNAMENTS=28,
        MOD_DASHBOARD=29, MOD_DIALDESIGN=30, MOD_DOORSPEAKERS=31, MOD_SEATS=32,
        MOD_STEERINGWHEELS=33, MOD_COLUMNSHIFTERLEVERS=34, MOD_PLAQUES=35,
        MOD_SPEAKERS=36, MOD_TRUNK=37, MOD_HYDRAULICS=38, MOD_ENGINEBLOCK=39,
        MOD_AIRFILTER=40, MOD_STRUTS=41, MOD_ARCHCOVER=42, MOD_AERIALS=43,
        MOD_TANK=44, MOD_WINDOWS=45, MOD_LIVERY=48,
    }

    local function resolveModel(text)
        local model = numberField(text,
            "vehicle_model_hash", "vehicleModel", "VehicleModel",
            "modelHash", "ModelHash", "model", "Model", "hash", "Hash")
        if model and model ~= 0 then return model, "numeric" end

        local modelName = stringField(text, "model", "Model", "modelName", "ModelName", "vehicle", "Vehicle", "spawnName", "SpawnName")
        if modelName and modelName ~= "" then
            local hash = 0
            driftgod.Try(function()
                if Utils and Utils.Joaat then hash = tonumber(Utils.Joaat(modelName) or 0) or 0
                elseif Utils and Utils.sJoaat then hash = tonumber(Utils.sJoaat(modelName) or 0) or 0 end
            end)
            if hash ~= 0 then return hash, "name=" .. modelName end
        end

        return 0, "missing model"
    end

    local function parseCheraxVehicleJson(text)
        text = tostring(text or "")
        if text == "" then return nil, "empty JSON" end

        local model, modelSource = resolveModel(text)
        if model == 0 then return nil, modelSource end

        local snap = {
            model = model,
            modelSource = modelSource,
            mods = {},
            wheelType = numberField(text, "wheelType", "wheel_type", "WheelType") or 0,
            primaryColor = numberField(text, "primaryColor", "primary_color", "PrimaryColor") or 0,
            secondaryColor = numberField(text, "secondaryColor", "secondary_color", "SecondaryColor") or 0,
            pearlescentColor = numberField(text, "pearlescentColor", "pearlescent_color", "PearlescentColor") or 0,
            wheelColor = numberField(text, "wheelColor", "wheel_color", "WheelColor") or 0,
            windowTint = numberField(text, "windowTint", "vehicle_window_tint", "WindowTint") or 0,
            interiorColor = numberField(text, "interiorColor", "interior_color", "InteriorColor") or 0,
            dashBoardColor = numberField(text, "dashBoardColor", "dashboardColor", "dashboard_color", "DashboardColor") or 0,
            plateText = stringField(text, "plateText", "plate_text", "PlateText") or "",
            plateTextIndex = numberField(text, "plateTextIndex", "plate_text_index", "PlateTextIndex") or 0,
            liveryID = numberField(text, "liveryID", "liveryId", "livery", "Livery") or -1,
            livery2ID = numberField(text, "livery2ID", "livery2Id", "Livery2") or -1,
            isPrimaryColorCustom = boolField(text, "isPrimaryColorCustom", "hasCustomPrimary", "customPrimaryColorEnabled"),
            isSecondaryColorCustom = boolField(text, "isSecondaryColorCustom", "hasCustomSecondary", "customSecondaryColorEnabled"),
            customPrimaryColor = colorObject(text, "customPrimaryColor", "custom_primary_color"),
            customSecondaryColor = colorObject(text, "customSecondaryColor", "custom_secondary_color"),
            tyreSmokeColor = colorObject(text, "tyreSmokeColor", "tireSmokeColor", "tyre_smoke_color"),
            bulletproofTyres = boolField(text, "bulletproofTyres", "bulletproofTires"),
            driftTyres = boolField(text, "driftTyres", "driftTires"),
            dirtLevel = numberField(text, "dirtLevel", "DirtLevel") or 0.0,
            disableExtras = numberField(text, "disableExtras", "DisableExtras"),
            extras = {},
            toggleMods = {},
        }

        if snap.isPrimaryColorCustom == nil then snap.isPrimaryColorCustom = snap.customPrimaryColor ~= nil end
        if snap.isSecondaryColorCustom == nil then snap.isSecondaryColorCustom = snap.customSecondaryColor ~= nil end

        -- Standard Cherax JSON mod objects: "mod23": { "index": 17, "variation": false }
        for modType = 0, 49 do
            local section = objectSection(text, "mod" .. tostring(modType), 260)
            if section ~= "" then
                local index = numberField(section, "index", "Index")
                local variation = boolField(section, "variation", "Variation") == true
                if index ~= nil then
                    snap.mods["mod" .. tostring(modType)] = { index = index, variation = variation }
                end
            end
        end

        -- KRZ / alternate JSON mod arrays.
        for modName, modType in pairs(KRZ_MOD_INDEX) do
            local idx, variation = text:match('"' .. modName .. '"%s*:%s*%[%s*(-?%d+)%s*,%s*(%d+)%s*%]')
            if idx then
                snap.mods["mod" .. tostring(modType)] = {
                    index = tonumber(idx) or -1,
                    variation = tostring(variation) == "1",
                }
            elseif text:match('"' .. modName .. '"%s*:%s*"TOGGLE"') then
                snap.mods["mod" .. tostring(modType)] = { index = 1, variation = false }
                snap.toggleMods[modType] = true
            end
        end

        for _, modType in ipairs({ 18, 20, 22 }) do
            local mod = snap.mods["mod" .. tostring(modType)]
            if mod then snap.toggleMods[modType] = tonumber(mod.index or 0) == 1 end
        end

        local neonSection = objectSection(text, "neonKits", 1000)
        snap.neon = {
            left = boolField(neonSection, "left", "neonLOn") == true or boolField(text, "neonLOn") == true,
            right = boolField(neonSection, "right", "neonROn") == true or boolField(text, "neonROn") == true,
            front = boolField(neonSection, "front", "neonFOn") == true or boolField(text, "neonFOn") == true,
            back = boolField(neonSection, "back", "neonBOn") == true or boolField(text, "neonBOn") == true,
        }
        snap.neonColor = colorObject(neonSection, "color") or colorObject(text, "neonColor", "neon_color") or {
            r = numberField(text, "neonColorR") or 255,
            g = numberField(text, "neonColorG") or 0,
            b = numberField(text, "neonColorB") or 255,
        }

        for extra = 1, 20 do
            local enabled = boolField(text, "extra" .. tostring(extra), "Extra" .. tostring(extra))
            if enabled ~= nil then snap.extras[extra] = enabled end
        end

        -- Normalize into the config shape used by SpawnConfiguredVehicle.
        local cfg = {
            model = snap.model,
            wheelType = snap.wheelType,
            primaryColor = snap.primaryColor,
            secondaryColor = snap.secondaryColor,
            pearlescentColor = snap.pearlescentColor,
            wheelColor = snap.wheelColor,
            customPrimaryColor = snap.customPrimaryColor or { r = 0, g = 0, b = 0 },
            customSecondaryColor = snap.customSecondaryColor or { r = 0, g = 0, b = 0 },
            tyreSmokeColor = snap.tyreSmokeColor or { r = 255, g = 255, b = 255 },
            windowTint = snap.windowTint,
            interiorColor = snap.interiorColor,
            dashBoardColor = snap.dashBoardColor,
            plateText = snap.plateText,
            plateTextIndex = snap.plateTextIndex,
            neon = snap.neon,
            neonColor = snap.neonColor,
            mods = {},
        }
        for modType = 0, 49 do
            local mod = snap.mods["mod" .. tostring(modType)]
            if mod then cfg.mods[modType] = { index = mod.index, variation = mod.variation == true } end
        end

        return { snap = snap, cfg = cfg }, nil
    end

    local function invokeVoid(hash, ...)
        local args = { ... }
        return driftgod.Try(function()
            if Natives and Natives.InvokeVoid then
                local unpackFn = (table and table.unpack) or unpack
                Natives.InvokeVoid(hash, unpackFn(args))
            end
        end)
    end

    local function applyPrimeSavedVehicleData(vehicle, parsed, sourceLabel)
        vehicle = tonumber(vehicle or 0) or 0
        if vehicle == 0 or type(parsed) ~= "table" or type(parsed.snap) ~= "table" then
            return false, "invalid apply arguments"
        end

        local snap = parsed.snap
        local applied = {}

        local okSnapshot, snapshotResult = driftgod.Try(function()
            if driftgod.ApplyCheraxVehicleSnapshotToVehicle then
                return driftgod.ApplyCheraxVehicleSnapshotToVehicle(vehicle, snap)
            end
            return false
        end)
        if okSnapshot and snapshotResult ~= false then applied[#applied + 1] = "cheraxSnapshot" end

        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then VEHICLE.SET_VEHICLE_MOD_KIT(vehicle, 0)
            else invokeVoid(0x1F2AA07F00B3217A, vehicle, 0) end
        end)

        for modType, enabled in pairs(snap.toggleMods or {}) do
            driftgod.Try(function()
                if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then VEHICLE.TOGGLE_VEHICLE_MOD(vehicle, modType, enabled == true)
                else invokeVoid(0x2A1F4F37F95BAD08, vehicle, modType, enabled == true) end
            end)
        end
        applied[#applied + 1] = "toggleMods"

        -- Clear the temporary custom paint applied by SpawnConfiguredVehicle when the save uses indexed paint.
        if snap.isPrimaryColorCustom ~= true then
            driftgod.Try(function()
                if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle)
                else invokeVoid(0x55E1D2758F34E437, vehicle) end
            end)
        end
        if snap.isSecondaryColorCustom ~= true then
            driftgod.Try(function()
                if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle)
                else invokeVoid(0x5FFBDEEC3E8E2009, vehicle) end
            end)
        end

        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then VEHICLE.SET_VEHICLE_COLOURS(vehicle, snap.primaryColor, snap.secondaryColor)
            else invokeVoid(0x4F1D4BE3A7F24601, vehicle, snap.primaryColor, snap.secondaryColor) end
            if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicle, snap.pearlescentColor, snap.wheelColor)
            else invokeVoid(0x2036F561ADD12E33, vehicle, snap.pearlescentColor, snap.wheelColor) end

            if snap.isPrimaryColorCustom == true and type(snap.customPrimaryColor) == "table" then
                local c = snap.customPrimaryColor
                if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle, c.r or 0, c.g or 0, c.b or 0)
                else invokeVoid(0x7141766F91D15BEA, vehicle, c.r or 0, c.g or 0, c.b or 0) end
            end
            if snap.isSecondaryColorCustom == true and type(snap.customSecondaryColor) == "table" then
                local c = snap.customSecondaryColor
                if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle, c.r or 0, c.g or 0, c.b or 0)
                else invokeVoid(0x36CED73BFED89754, vehicle, c.r or 0, c.g or 0, c.b or 0) end
            end
        end)

        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_INTERIOR_COLOUR then VEHICLE.SET_VEHICLE_INTERIOR_COLOUR(vehicle, snap.interiorColor)
            else invokeVoid(0xF40DD601A65F7F19, vehicle, snap.interiorColor) end
            if VEHICLE and VEHICLE.SET_VEHICLE_DASHBOARD_COLOUR then VEHICLE.SET_VEHICLE_DASHBOARD_COLOUR(vehicle, snap.dashBoardColor)
            else invokeVoid(0x6089CDF6A57F326C, vehicle, snap.dashBoardColor) end
        end)
        applied[#applied + 1] = "interiorDashboard"

        for index, enabled in pairs(snap.neon or {}) do
            local neonIndex = ({ left = 0, right = 1, front = 2, back = 3 })[index]
            if neonIndex ~= nil then
                driftgod.Try(function()
                    if VEHICLE and VEHICLE.SET_VEHICLE_NEON_LIGHT_ENABLED then VEHICLE.SET_VEHICLE_NEON_LIGHT_ENABLED(vehicle, neonIndex, enabled == true)
                    else invokeVoid(0x2AA720E4287BF269, vehicle, neonIndex, enabled == true) end
                end)
            end
        end
        local nc = snap.neonColor or { r = 255, g = 0, b = 255 }
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_NEON_COLOUR then VEHICLE.SET_VEHICLE_NEON_COLOUR(vehicle, nc.r, nc.g, nc.b)
            else invokeVoid(0x8E0A582209A62695, vehicle, nc.r, nc.g, nc.b) end
        end)
        applied[#applied + 1] = "neon"

        for extra = 1, 20 do
            local enabled = snap.extras and snap.extras[extra]
            if enabled == nil and snap.disableExtras ~= nil then
                local bit = 2 ^ (extra - 1)
                enabled = (math.floor(snap.disableExtras / bit) % 2) == 0
            end
            if enabled ~= nil then
                driftgod.Try(function()
                    if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA then VEHICLE.SET_VEHICLE_EXTRA(vehicle, extra, enabled ~= true)
                    else invokeVoid(0x7EE3A3C5E4A40CC9, vehicle, extra, enabled ~= true) end
                end)
            end
        end
        applied[#applied + 1] = "extras"

        if snap.liveryID and snap.liveryID >= 0 then
            driftgod.Try(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_LIVERY then VEHICLE.SET_VEHICLE_LIVERY(vehicle, snap.liveryID)
                else invokeVoid(0x60BF608F1B8CD1B6, vehicle, snap.liveryID) end
            end)
        end
        if snap.livery2ID and snap.livery2ID >= 0 then
            driftgod.Try(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_MOD then VEHICLE.SET_VEHICLE_MOD(vehicle, 48, snap.livery2ID, false)
                else invokeVoid(0x6AF0636DDEDCB6DD, vehicle, 48, snap.livery2ID, false) end
            end)
        end

        if snap.bulletproofTyres == true then
            driftgod.Try(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_TYRES_CAN_BURST then VEHICLE.SET_VEHICLE_TYRES_CAN_BURST(vehicle, false)
                else invokeVoid(0xEB9DC3C7D8596C46, vehicle, false) end
            end)
        end
        if snap.driftTyres == true then
            driftgod.Try(function()
                if VEHICLE and VEHICLE.SET_DRIFT_TYRES_ENABLED then VEHICLE.SET_DRIFT_TYRES_ENABLED(vehicle, true)
                else invokeVoid(0x5AC79C98C5C17F05, vehicle, true) end
            end)
        end

        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_DIRT_LEVEL then VEHICLE.SET_VEHICLE_DIRT_LEVEL(vehicle, snap.dirtLevel or 0.0)
            else invokeVoid(0x79D3B596FE44EE8B, vehicle, snap.dirtLevel or 0.0) end
            if VEHICLE and VEHICLE.SET_VEHICLE_FIXED then VEHICLE.SET_VEHICLE_FIXED(vehicle)
            else invokeVoid(0x115722B1B9C14C1C, vehicle) end
            if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then VEHICLE.SET_VEHICLE_ENGINE_ON(vehicle, true, true, false)
            else invokeVoid(0x2497C4717C8B881E, vehicle, true, true, false) end
            if VEHICLE and VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY then VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY(vehicle)
            else invokeVoid(0x49733E92263139D1, vehicle, 5.0) end
        end)
        applied[#applied + 1] = "finalize"

        P10.applies = (tonumber(P10.applies or 0) or 0) + 1
        p10Log("saved data applied | pass=" .. tostring(sourceLabel or "now")
            .. " | handle=" .. tostring(vehicle)
            .. " | model=" .. tostring(snap.model)
            .. " | mods=" .. tostring((function() local n=0 for _ in pairs(snap.mods or {}) do n=n+1 end return n end)())
            .. " | indexedPaint=" .. tostring(snap.primaryColor) .. "/" .. tostring(snap.secondaryColor)
            .. " | custom=" .. tostring(snap.isPrimaryColorCustom == true) .. "/" .. tostring(snap.isSecondaryColorCustom == true)
            .. " | wheelType=" .. tostring(snap.wheelType)
            .. " | applied=" .. table.concat(applied, ","))
        return true, table.concat(applied, ",")
    end

    local function selectRandomItem(targetCategory)
        local pool = {}
        for _, candidate in ipairs(driftgod.VS.runtime.items or {}) do
            if not candidate.isFolder and not candidate.isRandom
                and (targetCategory == "All" or tostring(candidate.category or "Root"):lower() == tostring(targetCategory or ""):lower()) then
                pool[#pool + 1] = candidate
            end
        end
        if #pool == 0 then return nil end
        return pool[math.random(1, #pool)]
    end

    function driftgod.VS_LoadItem(item)
        if not item then
            p10Log("load blocked: no item selected", true)
            return false
        end

        if item.isFolder then
            driftgod.VS.runtime.currentFolder = item.folderTarget or item.category
            driftgod.S.vehicleSpawnerIndex = 0
            driftgod.VS.hud.scroll = 0
            if driftgod.VS_Rebuild then driftgod.VS_Rebuild(true) end
            return true
        end

        if item.isRandom then
            item = selectRandomItem(item.randomTargetCategory or "All")
            if not item then
                p10Log("random load blocked: no vehicles available", true)
                return false
            end
        end

        local path = tostring(item.path or "")
        if not path:lower():match("%.json$") then
            p10Log("load blocked: P10 currently supports Cherax JSON vehicle files only | file=" .. path, true)
            return false
        end

        local text, readMethod = readVehicleFile(path)
        if not text then
            P10.failures = (tonumber(P10.failures or 0) or 0) + 1
            p10Log("vehicle JSON read failed | file=" .. path .. " | reason=" .. tostring(readMethod), true)
            return false
        end

        local parsed, parseError = parseCheraxVehicleJson(text)
        if not parsed then
            P10.failures = (tonumber(P10.failures or 0) or 0) + 1
            p10Log("vehicle JSON parse failed | file=" .. path .. " | reason=" .. tostring(parseError), true)
            return false
        end

        local label = tostring(item.displayLabel or item.name or "Saved Vehicle")
        p10Log("full saved vehicle spawn begin | name=" .. label
            .. " | model=" .. tostring(parsed.snap.model)
            .. " | source=" .. tostring(parsed.snap.modelSource)
            .. " | reader=" .. tostring(readMethod))

        if type(driftgod.SpawnConfiguredVehicle) ~= "function" then
            p10Log("spawn unavailable: SpawnConfiguredVehicle missing", true)
            return false
        end

        local okSpawn, vehicle = driftgod.Try(function()
            return driftgod.SpawnConfiguredVehicle(parsed.cfg, label)
        end)
        vehicle = tonumber(vehicle or 0) or 0

        if not okSpawn or vehicle == 0 then
            P10.failures = (tonumber(P10.failures or 0) or 0) + 1
            p10Log("full saved vehicle spawn failed | name=" .. label
                .. " | model=" .. tostring(parsed.snap.model)
                .. " | result=" .. tostring(vehicle), true)
            return false
        end

        applyPrimeSavedVehicleData(vehicle, parsed, "now")

        if Script and Script.QueueJob then
            Script.QueueJob(function()
                if Script and Script.Yield then Script.Yield(250) end
                applyPrimeSavedVehicleData(vehicle, parsed, "250ms")
                if Script and Script.Yield then Script.Yield(750) end
                applyPrimeSavedVehicleData(vehicle, parsed, "1000ms")
                if Script and Script.Yield then Script.Yield(1250) end
                applyPrimeSavedVehicleData(vehicle, parsed, "2250ms-final")
            end)
        end

        driftgod.VS.runtime.lastSpawnedName = label
        driftgod.VS.runtime.lastSpawnedModel = tostring(parsed.snap.model)
        driftgod.VS.runtime.lastSpawnedHandle = vehicle
        driftgod.VS.runtime.spawnCount = (tonumber(driftgod.VS.runtime.spawnCount or 0) or 0) + 1
        driftgod.VS.runtime.lastStatus = "Loaded full saved data: " .. label

        p10Log("full saved vehicle spawned | name=" .. label
            .. " | model=" .. tostring(parsed.snap.model)
            .. " | handle=" .. tostring(vehicle)
            .. " | file=" .. path)
        return true
    end

    p10Log("patch installed | model-only diagnostic loader replaced with full Cherax JSON restore")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime garage p11 - direct cherax mod restore
-- note: directly applies mod0-mod49 because the older snapshot helper is unreliable on prime.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or { runtime = {}, hud = {} }
    driftgod.VS.runtime = driftgod.VS.runtime or {}

    driftgod.__PrimeGarageP11 = driftgod.__PrimeGarageP11 or {
        patch = "P11_Direct_Cherax_Mod_Restore",
        applyCount = 0,
        verifyFailures = 0,
    }
    local P11 = driftgod.__PrimeGarageP11

    local function p11Log(message, important)
        message = "[DriftGod Prime] [Garage P11] " .. tostring(message or "")
        if Logger and Logger.LogInfo then
            if important == true and Logger.LogError then
                Logger.LogError(message)
            else
                Logger.LogInfo(message)
            end
        elseif driftgod.Log then
            driftgod.Log(message)
        end
    end

    local function readTextFile(path)
        path = tostring(path or "")
        if path == "" then return nil, "empty path" end

        if FileMgr and FileMgr.ReadFileContent then
            local ok, body = driftgod.Try(function()
                return FileMgr.ReadFileContent(path)
            end)
            if ok and type(body) == "string" and body ~= "" then
                return body, "FileMgr.ReadFileContent"
            end
        end

        local file = nil
        local okOpen = driftgod.Try(function()
            file = io.open(path, "rb")
        end)
        if okOpen and file then
            local body = nil
            local okRead = driftgod.Try(function()
                body = file:read("*a")
            end)
            driftgod.Try(function() file:close() end)
            if okRead and type(body) == "string" and body ~= "" then
                return body, "io.open"
            end
        end

        return nil, "file unreadable"
    end

    local function parseDirectModData(text)
        text = tostring(text or "")
        if text == "" then return nil, "empty JSON" end

        local data = {
            wheelType = tonumber(text:match('"wheelType"%s*:%s*(-?%d+)')) or 0,
            mods = {},
            parsedCount = 0,
        }

        for modType = 0, 49 do
            local key = "mod" .. tostring(modType)
            local body = text:match('"' .. key .. '"%s*:%s*%{(.-)%}')
            if body then
                local index = tonumber(body:match('"index"%s*:%s*(-?%d+)'))
                local variationRaw = body:match('"variation"%s*:%s*([%a%d]+)')
                local variation = tostring(variationRaw or "false"):lower()
                variation = variation == "true" or variation == "1"

                if index ~= nil then
                    data.mods[modType] = {
                        index = index,
                        variation = variation,
                    }
                    data.parsedCount = data.parsedCount + 1
                end
            end
        end

        if data.parsedCount <= 0 then
            return nil, "no mod0-mod49 objects parsed"
        end

        return data, nil
    end

    local function invokeVoid(hash, ...)
        local args = { ... }
        return driftgod.Try(function()
            if Natives and Natives.InvokeVoid then
                local unpackFn = (table and table.unpack) or unpack
                Natives.InvokeVoid(hash, unpackFn(args))
            end
        end)
    end

    local function setModKit(vehicle)
        local ok = false
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then
                VEHICLE.SET_VEHICLE_MOD_KIT(vehicle, 0)
                ok = true
            else
                invokeVoid(0x1F2AA07F00B3217A, vehicle, 0)
                ok = true
            end
        end)
        return ok
    end

    local function setWheelType(vehicle, wheelType)
        local ok = false
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then
                VEHICLE.SET_VEHICLE_WHEEL_TYPE(vehicle, wheelType)
                ok = true
            else
                invokeVoid(0x487EB21CC7295BA1, vehicle, wheelType)
                ok = true
            end
        end)
        return ok
    end

    local function setRegularMod(vehicle, modType, modIndex, variation)
        local ok = false
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_MOD then
                VEHICLE.SET_VEHICLE_MOD(vehicle, modType, modIndex, variation == true)
                ok = true
            else
                invokeVoid(0x6AF0636DDEDCB6DD, vehicle, modType, modIndex, variation == true)
                ok = true
            end
        end)
        return ok
    end

    local function setToggleMod(vehicle, modType, enabled)
        local ok = false
        driftgod.Try(function()
            if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then
                VEHICLE.TOGGLE_VEHICLE_MOD(vehicle, modType, enabled == true)
                ok = true
            else
                invokeVoid(0x2A1F4F37F95BAD08, vehicle, modType, enabled == true)
                ok = true
            end
        end)
        return ok
    end

    local function getAppliedMod(vehicle, modType)
        local value = nil
        driftgod.Try(function()
            if VEHICLE and VEHICLE.GET_VEHICLE_MOD then
                value = tonumber(VEHICLE.GET_VEHICLE_MOD(vehicle, modType))
            elseif Natives and Natives.InvokeInt then
                value = tonumber(Natives.InvokeInt(0x772960298DA26FDB, vehicle, modType))
            end
        end)
        return value
    end

    local function getNumMods(vehicle, modType)
        local value = nil
        driftgod.Try(function()
            if VEHICLE and VEHICLE.GET_NUM_VEHICLE_MODS then
                value = tonumber(VEHICLE.GET_NUM_VEHICLE_MODS(vehicle, modType))
            elseif Natives and Natives.InvokeInt then
                value = tonumber(Natives.InvokeInt(0xE38E9162A2500646, vehicle, modType))
            end
        end)
        return value
    end

    local TOGGLE_TYPES = {
        [17] = true,
        [18] = true,
        [19] = true,
        [20] = true,
        [21] = true,
        [22] = true,
    }

    local function applyDirectMods(vehicle, data, passLabel)
        vehicle = tonumber(vehicle or 0) or 0
        if vehicle == 0 or type(data) ~= "table" or type(data.mods) ~= "table" then
            return false, "invalid arguments"
        end

        setModKit(vehicle)
        setWheelType(vehicle, tonumber(data.wheelType or 0) or 0)

        local regularApplied = 0
        local toggleApplied = 0
        local failedCalls = 0

        -- Apply body, performance, interior, livery, and other non-wheel mods first.
        for modType = 0, 49 do
            local mod = data.mods[modType]
            if mod and modType ~= 23 and modType ~= 24 then
                if TOGGLE_TYPES[modType] then
                    local enabled = tonumber(mod.index or 0) == 1
                    if setToggleMod(vehicle, modType, enabled) then
                        toggleApplied = toggleApplied + 1
                    else
                        failedCalls = failedCalls + 1
                    end
                else
                    if setRegularMod(vehicle, modType, tonumber(mod.index or -1) or -1, mod.variation == true) then
                        regularApplied = regularApplied + 1
                    else
                        failedCalls = failedCalls + 1
                    end
                end
            end
        end

        -- Wheels depend on wheel type, so set them last and reassert wheel type first.
        setWheelType(vehicle, tonumber(data.wheelType or 0) or 0)
        for _, modType in ipairs({ 23, 24 }) do
            local mod = data.mods[modType]
            if mod then
                if setRegularMod(vehicle, modType, tonumber(mod.index or -1) or -1, mod.variation == true) then
                    regularApplied = regularApplied + 1
                else
                    failedCalls = failedCalls + 1
                end
            end
        end

        -- Reassert kit and wheel choices because Prime/GTA can reset them immediately after spawn.
        setModKit(vehicle)
        setWheelType(vehicle, tonumber(data.wheelType or 0) or 0)
        for _, modType in ipairs({ 23, 24 }) do
            local mod = data.mods[modType]
            if mod then
                setRegularMod(vehicle, modType, tonumber(mod.index or -1) or -1, mod.variation == true)
            end
        end

        local verified = 0
        local mismatches = {}
        for modType = 0, 49 do
            local mod = data.mods[modType]
            if mod and not TOGGLE_TYPES[modType] then
                local available = getNumMods(vehicle, modType)
                local requested = tonumber(mod.index or -1) or -1

                -- Only compare slots that the model reports as supported.
                if available == nil or available > 0 or requested == -1 then
                    local actual = getAppliedMod(vehicle, modType)
                    if actual ~= nil then
                        if actual == requested then
                            verified = verified + 1
                        elseif #mismatches < 8 then
                            mismatches[#mismatches + 1] = tostring(modType) .. ":" .. tostring(requested) .. "->" .. tostring(actual)
                        end
                    end
                end
            end
        end

        P11.applyCount = (tonumber(P11.applyCount or 0) or 0) + 1
        P11.verifyFailures = (tonumber(P11.verifyFailures or 0) or 0) + #mismatches

        p11Log("direct mods applied | pass=" .. tostring(passLabel or "now")
            .. " | handle=" .. tostring(vehicle)
            .. " | parsed=" .. tostring(data.parsedCount or 0)
            .. " | wheelType=" .. tostring(data.wheelType)
            .. " | regular=" .. tostring(regularApplied)
            .. " | toggles=" .. tostring(toggleApplied)
            .. " | failedCalls=" .. tostring(failedCalls)
            .. " | verified=" .. tostring(verified)
            .. " | mismatches=" .. tostring(#mismatches)
            .. (#mismatches > 0 and (" [" .. table.concat(mismatches, ",") .. "]") or ""),
            failedCalls > 0)

        return failedCalls == 0, table.concat(mismatches, ",")
    end

    local PreviousPrimeGarageLoadItem = driftgod.VS_LoadItem

    function driftgod.VS_LoadItem(item)
        local path = item and tostring(item.path or "") or ""
        local jsonText = nil
        local jsonReadMethod = nil
        local directData = nil
        local directError = nil

        if path:lower():match("%.json$") then
            jsonText, jsonReadMethod = readTextFile(path)
            if jsonText then
                directData, directError = parseDirectModData(jsonText)
            else
                directError = jsonReadMethod
            end
        end

        local ok = false
        local result = nil
        if type(PreviousPrimeGarageLoadItem) == "function" then
            ok, result = driftgod.Try(PreviousPrimeGarageLoadItem, item)
            if not ok then
                p11Log("previous full vehicle loader errored | file=" .. path .. " | error=" .. tostring(result), true)
                return false
            end
        else
            p11Log("previous full vehicle loader missing", true)
            return false
        end

        if result ~= true then
            return result
        end

        if not directData then
            if path:lower():match("%.json$") then
                p11Log("direct mod parse skipped | file=" .. path
                    .. " | reader=" .. tostring(jsonReadMethod)
                    .. " | reason=" .. tostring(directError), true)
            end
            return result
        end

        local vehicle = tonumber(driftgod.VS.runtime.lastSpawnedHandle or 0) or 0
        if vehicle == 0 then
            p11Log("direct mod apply skipped: no last spawned handle | file=" .. path, true)
            return result
        end

        p11Log("direct mod restore begin | file=" .. path
            .. " | reader=" .. tostring(jsonReadMethod)
            .. " | handle=" .. tostring(vehicle)
            .. " | parsed=" .. tostring(directData.parsedCount)
            .. " | wheelType=" .. tostring(directData.wheelType)
            .. " | mod0=" .. tostring(directData.mods[0] and directData.mods[0].index or "nil")
            .. " | mod14=" .. tostring(directData.mods[14] and directData.mods[14].index or "nil")
            .. " | mod23=" .. tostring(directData.mods[23] and directData.mods[23].index or "nil"))

        applyDirectMods(vehicle, directData, "now")

        if Script and Script.QueueJob then
            Script.QueueJob(function()
                if Script and Script.Yield then Script.Yield(100) end
                applyDirectMods(vehicle, directData, "100ms")
                if Script and Script.Yield then Script.Yield(400) end
                applyDirectMods(vehicle, directData, "500ms")
                if Script and Script.Yield then Script.Yield(1000) end
                applyDirectMods(vehicle, directData, "1500ms-final")
            end)
        end

        return result
    end

    p11Log("patch installed | direct mod0-mod49 restore and verification enabled")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime garage p12 - exact pre-prime cherax vehicle loader bridge
-- note: uses DriftGod's original working method. the safe Prime file scanner supplies
--       the file list, while Cherax's built-in Load Vehicle feature restores all data.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or { runtime = {}, hud = {} }
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or {}

    driftgod.__PrimeGarageP12 = driftgod.__PrimeGarageP12 or {
        patch = "P12_Exact_PrePrime_LoadVehicle_Bridge",
        loads = 0,
        failures = 0,
    }
    local P12 = driftgod.__PrimeGarageP12
    local SAVED_VEHICLE_LIST_HASH = 514776905
    local LOAD_VEHICLE_FEATURE_NAME = "Load Vehicle"

    local function p12Log(message, important)
        message = "[DriftGod Prime] [Garage P12] " .. tostring(message or "")
        if important == true and Logger and Logger.LogError then
            Logger.LogError(message)
        elseif Logger and Logger.LogInfo then
            Logger.LogInfo(message)
        elseif log then
            log(message)
        end
    end

    local function normalize(path)
        return tostring(path or ""):gsub("/", "\\"):gsub("\\+$", "")
    end

    local function jsonIndexForItem(item)
        if type(item) ~= "table" then return nil, 0 end

        local wanted = normalize(item.path):lower()
        if wanted == "" then return nil, 0 end

        local paths = {}
        local seen = {}
        for _, candidate in ipairs(driftgod.VS.runtime.items or {}) do
            local path = normalize(candidate and candidate.path or "")
            if path ~= "" and path:lower():match("%.json$") then
                local key = path:lower()
                if not seen[key] then
                    seen[key] = true
                    paths[#paths + 1] = path
                end
            end
        end

        -- This is the exact fallback ordering used by the working pre-Prime DriftGod.
        table.sort(paths, function(a, b)
            return tostring(a):lower() < tostring(b):lower()
        end)

        for index, path in ipairs(paths) do
            if normalize(path):lower() == wanted then
                return index - 1, #paths
            end
        end

        return nil, #paths
    end

    local function selectRandomItem(targetCategory)
        local pool = {}
        for _, candidate in ipairs(driftgod.VS.runtime.items or {}) do
            if targetCategory == "All"
                or tostring(candidate.category or "Root"):lower() == tostring(targetCategory or ""):lower() then
                pool[#pool + 1] = candidate
            end
        end
        if #pool <= 0 then return nil end
        return pool[math.random(1, #pool)]
    end

    local function setRuntimeLoaded(item)
        driftgod.VS.runtime.lastSpawnedName = tostring(item.displayLabel or item.name or "Saved Vehicle")
        driftgod.VS.runtime.lastSpawnedModel = "Cherax Saved Vehicle"
        driftgod.VS.runtime.lastSpawnedHandle = 0
        driftgod.VS.runtime.spawnCount = (tonumber(driftgod.VS.runtime.spawnCount or 0) or 0) + 1
    end

    -- Replaces P10/P11's manual native reconstruction with the original production loader.
    function driftgod.VS_LoadItem(item)
        if not item then
            p12Log("load blocked: no saved vehicle selected", true)
            return false
        end

        if item.isRandom then
            item = selectRandomItem(item.randomTargetCategory or "All")
            if not item then
                p12Log("random load blocked: no vehicles available", true)
                return false
            end
        end

        if item.isFolder then
            driftgod.VS.runtime.currentFolder = item.folderTarget or item.category
            driftgod.S.vehicleSpawnerIndex = 0
            driftgod.VS.hud.scroll = 0
            if driftgod.VS_Rebuild then driftgod.Try(driftgod.VS_Rebuild, true) end
            return true
        end

        local path = normalize(item.path)
        if not path:lower():match("%.json$") then
            p12Log("load blocked: exact Cherax loader currently supports JSON entries | file=" .. path, true)
            return false
        end

        local listIndex = tonumber(item.cheraxListIndex)
        local pathCount = 0
        if listIndex == nil then
            listIndex, pathCount = jsonIndexForItem(item)
        end

        if listIndex == nil then
            P12.failures = (tonumber(P12.failures or 0) or 0) + 1
            p12Log("could not map file to Cherax Saved Vehicles index | file=" .. path
                .. " | scannedJson=" .. tostring(pathCount), true)
            return false
        end

        local listHash = tonumber(item.cheraxListHash or SAVED_VEHICLE_LIST_HASH) or SAVED_VEHICLE_LIST_HASH

        p12Log("exact pre-prime load begin | file=" .. path
            .. " | listHash=" .. tostring(listHash)
            .. " | listIndex=" .. tostring(listIndex)
            .. " | scannedJson=" .. tostring(pathCount))

        local setOk, setError = driftgod.Try(function()
            FeatureMgr.SetFeatureListIndex(listHash, listIndex)
        end)
        if not setOk then
            P12.failures = (tonumber(P12.failures or 0) or 0) + 1
            p12Log("SetFeatureListIndex failed | hash=" .. tostring(listHash)
                .. " | index=" .. tostring(listIndex)
                .. " | error=" .. tostring(setError), true)
            return false
        end
        p12Log("saved vehicle list index selected | hash=" .. tostring(listHash)
            .. " | index=" .. tostring(listIndex))

        local loadFeature = nil
        local resolveOk, resolveError = driftgod.Try(function()
            loadFeature = FeatureMgr.GetFeatureByName(LOAD_VEHICLE_FEATURE_NAME)
        end)
        if not resolveOk or loadFeature == nil then
            P12.failures = (tonumber(P12.failures or 0) or 0) + 1
            p12Log("Load Vehicle feature resolution failed | pcall=" .. tostring(resolveOk)
                .. " | type=" .. tostring(type(loadFeature))
                .. " | error=" .. tostring(resolveError), true)
            return false
        end
        p12Log("Load Vehicle feature resolved | type=" .. tostring(type(loadFeature)))

        local triggerOk, triggerError = driftgod.Try(function()
            loadFeature:TriggerCallback()
        end)
        if not triggerOk then
            P12.failures = (tonumber(P12.failures or 0) or 0) + 1
            p12Log("Load Vehicle callback failed | error=" .. tostring(triggerError), true)
            return false
        end

        setRuntimeLoaded(item)
        P12.loads = (tonumber(P12.loads or 0) or 0) + 1
        p12Log("loaded through Cherax built-in vehicle loader | name="
            .. tostring(driftgod.VS.runtime.lastSpawnedName)
            .. " | loadCount=" .. tostring(P12.loads))

        if driftgod.VS_Toast then
            driftgod.Try(driftgod.VS_Toast, "Loaded " .. tostring(driftgod.VS.runtime.lastSpawnedName), 2500)
        end
        return true
    end

    -- Assign the exact sorted JSON index after every successful Prime scan.
    local PreviousPrimeRootJsonRefresh = driftgod.VS_PrimeRootJsonRefresh
    if type(PreviousPrimeRootJsonRefresh) == "function" then
        function driftgod.VS_PrimeRootJsonRefresh(...)
            local count = PreviousPrimeRootJsonRefresh(...)
            local paths = {}
            for _, item in ipairs(driftgod.VS.runtime.items or {}) do
                if normalize(item.path):lower():match("%.json$") then
                    paths[#paths + 1] = item
                end
            end
            table.sort(paths, function(a, b)
                return normalize(a.path):lower() < normalize(b.path):lower()
            end)
            for index, item in ipairs(paths) do
                item.cheraxListHash = SAVED_VEHICLE_LIST_HASH
                item.cheraxListIndex = index - 1
            end
            p12Log("scan index bridge prepared | json=" .. tostring(#paths)
                .. " | firstIndex=" .. tostring(paths[1] and paths[1].cheraxListIndex or "none")
                .. " | lastIndex=" .. tostring(paths[#paths] and paths[#paths].cheraxListIndex or "none"))
            return count
        end

        driftgod.VS_PrimeSafeDiskRefresh = driftgod.VS_PrimeRootJsonRefresh
        driftgod.VS_Refresh = driftgod.VS_PrimeRootJsonRefresh
        driftgod.R153_ScanVehicleSpawner = driftgod.VS_PrimeRootJsonRefresh
        driftgod.R154_RefreshSpawner = driftgod.VS_PrimeRootJsonRefresh
    end

    p12Log("patch installed | exact working pre-Prime Load Vehicle bridge restored")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime drift tuning p13 - base preset dropdown performance
-- note: replaces the per-item BeginCombo renderer with Prime's native Combo widget
--       and caches by unlock state instead of the constantly-changing live drift score.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}

    driftgod.__PrimeBasePresetP13 = driftgod.__PrimeBasePresetP13 or {
        patch = "P13_Native_Combo_Unlock_Tier_Cache",
        rebuilds = 0,
        selections = 0,
    }
    local P13 = driftgod.__PrimeBasePresetP13
    local RESET_ID = "default_drifting"
    local SCORE_CHECK_MS = 250

    local function p13Log(message, important)
        message = "[DriftGod Prime] [Base Preset P13] " .. tostring(message or "")
        if important == true and Logger and Logger.LogError then
            Logger.LogError(message)
        elseif Logger and Logger.LogInfo then
            Logger.LogInfo(message)
        elseif log then
            log(message)
        end
    end

    local function nowMs()
        if Time and Time.GetEpocheMs then
            local ok, value = driftgod.Try(Time.GetEpocheMs)
            if ok and tonumber(value) then return tonumber(value) end
        end
        if driftgod.DriftChallengeNowMs then
            local ok, value = driftgod.Try(driftgod.DriftChallengeNowMs)
            if ok and tonumber(value) then return tonumber(value) end
        end
        if os and os.clock then return math.floor((os.clock() or 0) * 1000) end
        return 0
    end

    local function currentScore()
        if driftgod.GetArcadeDriftPresetScore then
            local ok, value = driftgod.Try(driftgod.GetArcadeDriftPresetScore)
            if ok and tonumber(value) then return math.floor(tonumber(value) or 0) end
        end
        local best = tonumber(driftgod.S.bestScore or driftgod.S.highScore or driftgod.S.highestScore or driftgod.S.bestRun or 0) or 0
        local current = tonumber(driftgod.S.currentScore or driftgod.S.arcadeRunScore or 0) or 0
        if current > best then best = current end
        if best < 0 then best = 0 end
        return math.floor(best)
    end

    local function isReset(id, name)
        id = tostring(id or "")
        name = tostring(name or "")
        return id == RESET_ID or id == "reset" or name == "Default Drifting" or name == "Reset"
    end

    local function isDriftGod(id, name)
        id = tostring(id or ""):lower()
        name = tostring(name or ""):lower()
        return id == "corner_magnet" or id == "driftgod" or name == "driftgod"
    end

    local function displayName(id, preset)
        local name = tostring((preset and (preset.name or preset.id)) or id or "")
        if isReset(id, name) then return "Reset" end
        return name:gsub("Default Drifting", "Reset"):gsub("DriftGod Wide Angle", "Wide Angle")
    end

    local function presetAllowed(preset, score)
        if type(preset) ~= "table" then return false end
        local id = tostring(preset.id or "")
        local name = tostring(preset.name or "")
        if id == "" then return false end
        if isReset(id, name) then return true end
        if isDriftGod(id, name) then
            return score < 5000 or score >= 100000
        end
        return score >= (tonumber(preset.unlock or 0) or 0)
    end

    local function buildStableList(force)
        local now = nowMs()
        if force ~= true
            and type(P13.items) == "table"
            and (now - (tonumber(P13.lastScoreCheckMs or 0) or 0)) < SCORE_CHECK_MS then
            return P13.items, P13.names
        end

        P13.lastScoreCheckMs = now
        local score = currentScore()
        local items = {{ id = RESET_ID, name = "Reset" }}
        local signature = { RESET_ID }

        for _, preset in ipairs(driftgod.ArcadeDriftPresets or {}) do
            local id = tostring(preset.id or "")
            local name = tostring(preset.name or "")
            if id ~= "" and not isReset(id, name) and presetAllowed(preset, score) then
                items[#items + 1] = {
                    id = id,
                    name = displayName(id, preset),
                    p = preset,
                }
                signature[#signature + 1] = id
            end
        end

        local key = table.concat(signature, "|")
        if force == true or P13.key ~= key or type(P13.items) ~= "table" or type(P13.names) ~= "table" then
            local names = {}
            for i, item in ipairs(items) do names[i] = tostring(item.name or item.id or i) end
            P13.items = items
            P13.names = names
            P13.key = key
            P13.rebuilds = (tonumber(P13.rebuilds or 0) or 0) + 1
        end

        return P13.items, P13.names
    end

    local function applyPreset(id)
        id = tostring(id or RESET_ID)
        driftgod.__R250BasePresetDropdownBusy = true

        local ok, result = driftgod.Try(function()
            if isReset(id, id) then
                driftgod.S.r195BaseTuningPreset = RESET_ID
                driftgod.S.r198BaseTuningPreset = RESET_ID
                driftgod.S.activeArcadeDriftPreset = RESET_ID
                if driftgod.ApplyResetPreset then
                    return driftgod.ApplyResetPreset(false)
                elseif driftgod.ApplyDefaultDriftingPreset then
                    return driftgod.ApplyDefaultDriftingPreset(false, true)
                end
                return true
            end

            driftgod.S.r195BaseTuningPreset = id
            driftgod.S.r198BaseTuningPreset = id
            driftgod.S.activeArcadeDriftPreset = id
            if driftgod.ApplyArcadeDriftPreset then
                return driftgod.ApplyArcadeDriftPreset(id, false)
            end
            return true
        end)

        driftgod.__R250BasePresetDropdownBusy = false

        if driftgod.R245RefreshTuningSliderCaps then
            driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false)
        end
        if driftgod.R250InvalidateBasePresetCache then
            driftgod.Try(driftgod.R250InvalidateBasePresetCache, "P13 base preset selected")
        end

        if ok then
            P13.selections = (tonumber(P13.selections or 0) or 0) + 1
            p13Log("selected | id=" .. id .. " | count=" .. tostring(P13.selections))
            return result ~= false
        end

        p13Log("selection failed | id=" .. id .. " | error=" .. tostring(result), true)
        return false
    end

    -- Stable list API for any older renderer that still references R249/R250 directly.
    driftgod.R250GetBasePresetList = function()
        local items = buildStableList(false)
        return items
    end

    driftgod.R249GetBasePresetDropdownList = function(includeReset)
        local items = buildStableList(false)
        if includeReset == true then return items end
        P13.withoutReset = P13.withoutReset or {}
        P13.withoutResetKey = P13.withoutResetKey or ""
        if P13.withoutResetKey ~= tostring(P13.key) then
            local out = {}
            for _, item in ipairs(items or {}) do
                if tostring(item.id or "") ~= RESET_ID then out[#out + 1] = item end
            end
            P13.withoutReset = out
            P13.withoutResetKey = tostring(P13.key)
        end
        return P13.withoutReset
    end

    -- This assignment intentionally occurs after R251's wrapper, bypassing its per-frame
    -- mute/busy churn and the BeginCombo + Selectable loop that tanks Prime FPS.
    driftgod.R250RenderBasePresetCombo = function(current, preview)
        local items, names = buildStableList(false)
        if type(items) ~= "table" or type(names) ~= "table" or #items <= 0 then
            return current, preview
        end

        local currentIndex = 0
        for i, item in ipairs(items) do
            if tostring(item.id or "") == tostring(current or "") then
                currentIndex = i - 1
                break
            end
        end

        if ImGui and ImGui.Combo then
            local callOk, newIndex, changed = driftgod.Try(
                ImGui.Combo,
                "Base Preset##PrimeP13BasePreset",
                currentIndex,
                names,
                #names,
                math.min(#names, 10)
            )

            if callOk then
                newIndex = tonumber(newIndex)
                if newIndex == nil then newIndex = currentIndex end
                if newIndex < 0 then newIndex = 0 end
                if newIndex > (#items - 1) then newIndex = #items - 1 end

                local didChange = changed == true or newIndex ~= currentIndex
                if didChange then
                    local selected = items[newIndex + 1]
                    if selected and applyPreset(selected.id) then
                        current = tostring(selected.id or current)
                        preview = tostring(selected.name or preview)
                    end
                end
                return current, preview
            end

            p13Log("ImGui.Combo call failed; using lightweight fallback | error=" .. tostring(newIndex), true)
        end

        -- Fallback keeps the UI usable without reopening the expensive BeginCombo path.
        if ImGui and ImGui.Button and ImGui.SameLine then
            local previousClicked = false
            local nextClicked = false
            driftgod.Try(function() previousClicked = ImGui.Button("<##PrimeP13BasePrevious") == true end)
            driftgod.Try(ImGui.SameLine)
            if ImGui.Text then driftgod.Try(ImGui.Text, tostring(preview or "Reset")) end
            driftgod.Try(ImGui.SameLine)
            driftgod.Try(function() nextClicked = ImGui.Button(">##PrimeP13BaseNext") == true end)

            if previousClicked or nextClicked then
                local newIndex = currentIndex + (nextClicked and 1 or -1)
                if newIndex < 0 then newIndex = #items - 1 end
                if newIndex >= #items then newIndex = 0 end
                local selected = items[newIndex + 1]
                if selected and applyPreset(selected.id) then
                    current = tostring(selected.id or current)
                    preview = tostring(selected.name or preview)
                end
            end
        end

        return current, preview
    end

    buildStableList(true)
    p13Log("patch installed | native Combo enabled | unlock-tier cache enabled | presets="
        .. tostring(P13.items and #P13.items or 0))
end)


-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime drift tuning p14 - popup-free base preset selector
-- note: Prime's ImGui combo popup causes a severe frame-rate drop while open.
-- this replaces only that popup with a lightweight inline arrow selector.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}

    driftgod.__PrimeBasePresetP14 = driftgod.__PrimeBasePresetP14 or {
        patch = "P14_Popup_Free_Base_Preset_Selector",
        selections = 0,
    }

    local P14 = driftgod.__PrimeBasePresetP14
    local RESET_ID = "default_drifting"

    local function p14Log(message, important)
        message = "[DriftGod Prime] [Base Preset P14] " .. tostring(message or "")
        if important == true and Logger and Logger.LogError then
            Logger.LogError(message)
        elseif Logger and Logger.LogInfo then
            Logger.LogInfo(message)
        elseif log then
            log(message)
        end
    end

    local function isReset(id)
        id = tostring(id or "")
        return id == "" or id == RESET_ID or id == "reset" or id == "Reset" or id == "Default Drifting"
    end

    local function applyPreset(id)
        id = tostring(id or RESET_ID)
        driftgod.__R250BasePresetDropdownBusy = true

        local ok, result = driftgod.Try(function()
            if isReset(id) then
                driftgod.S.r195BaseTuningPreset = RESET_ID
                driftgod.S.r198BaseTuningPreset = RESET_ID
                driftgod.S.activeArcadeDriftPreset = RESET_ID

                if driftgod.ApplyResetPreset then
                    return driftgod.ApplyResetPreset(false)
                elseif driftgod.ApplyDefaultDriftingPreset then
                    return driftgod.ApplyDefaultDriftingPreset(false, true)
                end
                return true
            end

            driftgod.S.r195BaseTuningPreset = id
            driftgod.S.r198BaseTuningPreset = id
            driftgod.S.activeArcadeDriftPreset = id

            if driftgod.ApplyArcadeDriftPreset then
                return driftgod.ApplyArcadeDriftPreset(id, false)
            end
            return true
        end)

        driftgod.__R250BasePresetDropdownBusy = false

        if driftgod.R245RefreshTuningSliderCaps then
            driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false)
        end

        if ok then
            P14.selections = (tonumber(P14.selections or 0) or 0) + 1
            p14Log("selected | id=" .. tostring(id) .. " | count=" .. tostring(P14.selections))
            return result ~= false
        end

        p14Log("selection failed | id=" .. tostring(id) .. " | error=" .. tostring(result), true)
        return false
    end

    local function renderButton(label)
        if not (ImGui and ImGui.Button) then return false end
        local clicked = false
        local ok = driftgod.Try(function()
            clicked = ImGui.Button(label) == true
        end)
        return ok == true and clicked == true
    end

    -- Overrides P13 after all legacy R250/R251 wrappers. No BeginCombo, Combo,
    -- Selectable, popup, or per-option renderer remains on this control path.
    driftgod.R250RenderBasePresetCombo = function(current, preview)
        local list = nil
        if driftgod.R250GetBasePresetList then
            local ok, value = driftgod.Try(driftgod.R250GetBasePresetList)
            if ok and type(value) == "table" then list = value end
        end

        if type(list) ~= "table" or #list <= 0 then
            if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, tostring(preview or "Reset")) end
            return current, preview
        end

        local currentIndex = 1
        local currentId = tostring(current or RESET_ID)
        for i = 1, #list do
            if tostring(list[i] and list[i].id or "") == currentId then
                currentIndex = i
                break
            end
        end

        local previousClicked = renderButton("<##PrimeP14BasePrevious")
        if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end

        local selectedName = tostring((list[currentIndex] and list[currentIndex].name) or preview or "Reset")
        if ImGui and ImGui.Text then
            driftgod.Try(ImGui.Text, selectedName)
        end

        if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end
        local nextClicked = renderButton(">##PrimeP14BaseNext")

        if previousClicked or nextClicked then
            local nextIndex = currentIndex + (nextClicked and 1 or -1)
            if nextIndex < 1 then nextIndex = #list end
            if nextIndex > #list then nextIndex = 1 end

            local selected = list[nextIndex]
            if selected and applyPreset(selected.id) then
                current = tostring(selected.id or current)
                preview = tostring(selected.name or preview)
            end
        end

        return current, preview
    end

    p14Log("patch installed | popup removed | inline arrow selector enabled")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime drift tuning p15 - staged base preset selection
-- note: browsing only changes a pending selection. the preset is applied once,
--       after the user presses Apply. only one preset name is rendered at a time.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}

    driftgod.__PrimeBasePresetP15 = driftgod.__PrimeBasePresetP15 or {
        patch = "P15_Staged_Base_Preset_Apply",
        browses = 0,
        applies = 0,
        dirty = false,
        pendingIndex = 1,
        pendingId = nil,
        pendingName = nil,
        cachedItems = nil,
        lastListRefreshMs = 0,
    }

    local P15 = driftgod.__PrimeBasePresetP15
    local RESET_ID = "default_drifting"
    local LIST_REFRESH_MS = 2000

    local function p15Log(message, important)
        message = "[DriftGod Prime] [Base Preset P15] " .. tostring(message or "")
        if important == true and Logger and Logger.LogError then
            Logger.LogError(message)
        elseif Logger and Logger.LogInfo then
            Logger.LogInfo(message)
        elseif log then
            log(message)
        end
    end

    local function nowMs()
        if Time and Time.GetEpocheMs then
            local ok, value = driftgod.Try(Time.GetEpocheMs)
            if ok and tonumber(value) then return tonumber(value) end
        end
        if os and os.clock then return math.floor((os.clock() or 0) * 1000) end
        return 0
    end

    local function isReset(id)
        id = tostring(id or "")
        return id == "" or id == RESET_ID or id == "reset" or id == "Reset" or id == "Default Drifting"
    end

    local function getItems(force)
        local now = nowMs()
        if force ~= true and type(P15.cachedItems) == "table" and #P15.cachedItems > 0
            and (now - (tonumber(P15.lastListRefreshMs or 0) or 0)) < LIST_REFRESH_MS then
            return P15.cachedItems
        end

        local list = nil
        if driftgod.R250GetBasePresetList then
            local ok, value = driftgod.Try(driftgod.R250GetBasePresetList)
            if ok and type(value) == "table" and #value > 0 then list = value end
        end

        if type(list) ~= "table" or #list <= 0 then
            list = {{ id = RESET_ID, name = "Reset" }}
        end

        P15.cachedItems = list
        P15.lastListRefreshMs = now
        return list
    end

    local function findIndex(list, id)
        id = tostring(id or RESET_ID)
        for i = 1, #list do
            if tostring(list[i] and list[i].id or "") == id then return i end
        end
        return 1
    end

    local function syncPending(list, activeId, force)
        activeId = tostring(activeId or RESET_ID)
        if force == true or P15.dirty ~= true or tostring(P15.lastActiveId or "") ~= activeId then
            local index = findIndex(list, activeId)
            local item = list[index] or list[1]
            P15.pendingIndex = index
            P15.pendingId = tostring(item and item.id or activeId)
            P15.pendingName = tostring(item and item.name or "Reset")
            P15.lastActiveId = activeId
            P15.dirty = false
        end
    end

    local function applyPreset(id)
        id = tostring(id or RESET_ID)
        driftgod.__R250BasePresetDropdownBusy = true

        local ok, result = driftgod.Try(function()
            if isReset(id) then
                driftgod.S.r195BaseTuningPreset = RESET_ID
                driftgod.S.r198BaseTuningPreset = RESET_ID
                driftgod.S.activeArcadeDriftPreset = RESET_ID

                if driftgod.ApplyResetPreset then
                    return driftgod.ApplyResetPreset(false)
                elseif driftgod.ApplyDefaultDriftingPreset then
                    return driftgod.ApplyDefaultDriftingPreset(false, true)
                end
                return true
            end

            driftgod.S.r195BaseTuningPreset = id
            driftgod.S.r198BaseTuningPreset = id
            driftgod.S.activeArcadeDriftPreset = id

            if driftgod.ApplyArcadeDriftPreset then
                return driftgod.ApplyArcadeDriftPreset(id, false)
            end
            return true
        end)

        driftgod.__R250BasePresetDropdownBusy = false

        if ok and result ~= false then
            if driftgod.R245RefreshTuningSliderCaps then
                driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false)
            end
            P15.applies = (tonumber(P15.applies or 0) or 0) + 1
            p15Log("applied once | id=" .. tostring(id) .. " | count=" .. tostring(P15.applies))
            return true
        end

        p15Log("apply failed | id=" .. tostring(id) .. " | error=" .. tostring(result), true)
        return false
    end

    local function button(label)
        if not (ImGui and ImGui.Button) then return false end
        local clicked = false
        local ok = driftgod.Try(function() clicked = ImGui.Button(tostring(label)) == true end)
        return ok == true and clicked == true
    end

    local function sameLine()
        if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end
    end

    local function text(value)
        if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, tostring(value or "")) end
    end

    -- Final override: no popup and no apply during browsing. The only expensive
    -- preset operation occurs when Apply is explicitly pressed.
    driftgod.R250RenderBasePresetCombo = function(current, preview)
        local list = getItems(false)
        local activeId = tostring(current or RESET_ID)
        syncPending(list, activeId, false)

        local previousClicked = button("<##PrimeP15BasePrevious")
        sameLine()
        text(tostring(P15.pendingName or preview or "Reset"))
        sameLine()
        local nextClicked = button(">##PrimeP15BaseNext")

        if previousClicked or nextClicked then
            local index = tonumber(P15.pendingIndex or findIndex(list, activeId)) or 1
            index = index + (nextClicked and 1 or -1)
            if index < 1 then index = #list end
            if index > #list then index = 1 end

            local item = list[index] or list[1]
            P15.pendingIndex = index
            P15.pendingId = tostring(item and item.id or RESET_ID)
            P15.pendingName = tostring(item and item.name or "Reset")
            P15.dirty = tostring(P15.pendingId) ~= activeId
            P15.browses = (tonumber(P15.browses or 0) or 0) + 1
        end

        sameLine()
        local applyClicked = button("Apply##PrimeP15BaseApply")

        if P15.dirty == true then
            sameLine()
            local cancelClicked = button("Cancel##PrimeP15BaseCancel")
            if cancelClicked then
                syncPending(list, activeId, true)
            elseif applyClicked then
                local pendingId = tostring(P15.pendingId or activeId)
                local pendingName = tostring(P15.pendingName or preview or "Reset")
                if applyPreset(pendingId) then
                    current = pendingId
                    preview = pendingName
                    P15.lastActiveId = pendingId
                    P15.dirty = false
                end
            end
        elseif applyClicked then
            -- Nothing changed, so do not reapply the active preset.
            p15Log("apply skipped | selection unchanged | id=" .. tostring(activeId))
        end

        return current, preview
    end

    p15Log("patch installed | staged selector enabled | apply-on-confirm only | one name rendered")
end)


-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime drift tuning p16 - exact drift tuning base preset control
-- note: replaces the legacy R196B dropdown inside Drift > Drift Tuning.
--       browsing renders one pending name and applies only after confirmation.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}

    driftgod.__PrimeBasePresetP16 = driftgod.__PrimeBasePresetP16 or {
        patch = "P16_Exact_R196B_Drift_Tuning_Selector",
        slotsSeen = {},
        pendingId = nil,
        pendingName = nil,
        pendingIndex = 1,
        activeId = nil,
        dirty = false,
        list = nil,
        listAtMs = 0,
        applies = 0,
    }

    local P16 = driftgod.__PrimeBasePresetP16
    local RESET_ID = "default_drifting"
    local LIST_CACHE_MS = 2000

    local function p16Log(message, important)
        message = "[DriftGod Prime] [Base Preset P16] " .. tostring(message or "")
        if important == true and Logger and Logger.LogError then
            Logger.LogError(message)
        elseif Logger and Logger.LogInfo then
            Logger.LogInfo(message)
        elseif log then
            log(message)
        end
    end

    local function nowMs()
        if Time and Time.GetEpocheMs then
            local ok, value = driftgod.Try(Time.GetEpocheMs)
            if ok and tonumber(value) then return tonumber(value) end
        end
        if driftgod.DriftChallengeNowMs then
            local ok, value = driftgod.Try(driftgod.DriftChallengeNowMs)
            if ok and tonumber(value) then return tonumber(value) end
        end
        if os and os.clock then return math.floor((os.clock() or 0) * 1000) end
        return 0
    end

    local function isReset(id)
        id = tostring(id or "")
        return id == "" or id == RESET_ID or id == "reset" or id == "Reset" or id == "Default Drifting"
    end

    local function normalizeCurrent(id)
        id = tostring(id or "")
        if isReset(id) then return RESET_ID end
        return id
    end

    local function displayName(item)
        if type(item) ~= "table" then return "Reset" end
        local id = tostring(item.id or "")
        local name = tostring(item.name or item.label or id)
        if isReset(id) or name == "Default Drifting" then return "Reset" end
        return name:gsub("Default Drifting", "Reset"):gsub("DriftGod Wide Angle", "Wide Angle")
    end

    local function getList(force)
        local now = nowMs()
        if force ~= true and type(P16.list) == "table" and #P16.list > 0
            and (now - (tonumber(P16.listAtMs or 0) or 0)) < LIST_CACHE_MS then
            return P16.list
        end

        local out = {{ id = RESET_ID, name = "Reset" }}
        local seen = { [RESET_ID] = true }
        local source = nil

        if driftgod.R249GetBasePresetDropdownList then
            local ok, value = driftgod.Try(driftgod.R249GetBasePresetDropdownList, false)
            if ok and type(value) == "table" then source = value end
        end
        if type(source) ~= "table" and driftgod.R250GetBasePresetList then
            local ok, value = driftgod.Try(driftgod.R250GetBasePresetList)
            if ok and type(value) == "table" then source = value end
        end
        if type(source) ~= "table" then source = driftgod.ArcadeDriftPresets or {} end

        for _, item in ipairs(source) do
            local id = tostring(type(item) == "table" and item.id or "")
            if id ~= "" and not isReset(id) and not seen[id] then
                seen[id] = true
                out[#out + 1] = {
                    id = id,
                    name = displayName(item),
                    p = item,
                }
            end
        end

        P16.list = out
        P16.listAtMs = now
        return out
    end

    local function findIndex(list, id)
        id = normalizeCurrent(id)
        for i = 1, #list do
            if normalizeCurrent(list[i] and list[i].id) == id then return i end
        end
        return 1
    end

    local function syncPending(list, activeId, force)
        activeId = normalizeCurrent(activeId)
        if force == true or P16.dirty ~= true or normalizeCurrent(P16.activeId) ~= activeId then
            local index = findIndex(list, activeId)
            local item = list[index] or list[1]
            P16.pendingIndex = index
            P16.pendingId = normalizeCurrent(item and item.id)
            P16.pendingName = tostring(item and item.name or "Reset")
            P16.activeId = activeId
            P16.dirty = false
        end
    end

    local function button(label)
        if not (ImGui and ImGui.Button) then return false end
        local clicked = false
        local ok = driftgod.Try(function() clicked = ImGui.Button(tostring(label)) == true end)
        return ok == true and clicked == true
    end

    local function sameLine()
        if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end
    end

    local function text(value)
        if ImGui and ImGui.Text then
            driftgod.Try(ImGui.Text, tostring(value or ""))
        elseif dgMiniText then
            driftgod.Try(dgMiniText, tostring(value or ""), "purple")
        end
    end

    local function applyOnce(id)
        id = normalizeCurrent(id)
        driftgod.__R250BasePresetDropdownBusy = true

        local ok, result = driftgod.Try(function()
            driftgod.S.r195BaseTuningPreset = id
            driftgod.S.r198BaseTuningPreset = id
            driftgod.S.activeArcadeDriftPreset = id

            if isReset(id) then
                if driftgod.ApplyResetPreset then return driftgod.ApplyResetPreset(false) end
                if driftgod.ApplyDefaultDriftingPreset then return driftgod.ApplyDefaultDriftingPreset(false, true) end
                return true
            end

            if driftgod.ApplyArcadeDriftPreset then
                return driftgod.ApplyArcadeDriftPreset(id, false)
            end
            return true
        end)

        driftgod.__R250BasePresetDropdownBusy = false

        if ok and result ~= false then
            if driftgod.R245RefreshTuningSliderCaps then
                driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false)
            end
            P16.applies = (tonumber(P16.applies or 0) or 0) + 1
            p16Log("applied once | id=" .. tostring(id) .. " | count=" .. tostring(P16.applies))
            return true
        end

        p16Log("apply failed | id=" .. tostring(id) .. " | error=" .. tostring(result), true)
        return false
    end

    function driftgod.PrimeRenderDriftTuningBasePresetSelector(current, preview, slot)
        slot = tostring(slot or "R196B")
        if P16.slotsSeen[slot] ~= true then
            P16.slotsSeen[slot] = true
            p16Log("exact Drift Tuning control active | slot=" .. slot .. " | legacy dropdown bypassed")
        end

        local list = getList(false)
        local activeId = normalizeCurrent(current)
        syncPending(list, activeId, false)

        local previousClicked = button("<##PrimeP16Previous_" .. slot)
        sameLine()
        text(tostring(P16.pendingName or preview or "Reset"))
        sameLine()
        local nextClicked = button(">##PrimeP16Next_" .. slot)

        if previousClicked or nextClicked then
            local index = tonumber(P16.pendingIndex or findIndex(list, activeId)) or 1
            index = index + (nextClicked and 1 or -1)
            if index < 1 then index = #list end
            if index > #list then index = 1 end

            local item = list[index] or list[1]
            P16.pendingIndex = index
            P16.pendingId = normalizeCurrent(item and item.id)
            P16.pendingName = tostring(item and item.name or "Reset")
            P16.dirty = normalizeCurrent(P16.pendingId) ~= activeId
        end

        sameLine()
        local applyClicked = button("Apply##PrimeP16Apply_" .. slot)

        if P16.dirty == true then
            sameLine()
            local cancelClicked = button("Cancel##PrimeP16Cancel_" .. slot)
            if cancelClicked then
                syncPending(list, activeId, true)
            elseif applyClicked then
                local pendingId = normalizeCurrent(P16.pendingId)
                if applyOnce(pendingId) then
                    P16.activeId = pendingId
                    P16.dirty = false
                    activeId = pendingId
                    preview = tostring(P16.pendingName or preview or "Reset")
                end
            end
        end

        return activeId, preview
    end

    -- Cover the newer R250 Drift Tuning renderer too. The two legacy R196B
    -- closures were patched directly above, so every known Drift Tuning path
    -- now uses this single-name, apply-on-confirm selector.
    driftgod.R250RenderBasePresetCombo = function(current, preview)
        return driftgod.PrimeRenderDriftTuningBasePresetSelector(current, preview, "R250")
    end

    p16Log("patch installed | exact Drift > Drift Tuning dropdown replaced | Preset Creation untouched")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime drift tuning p17 - virtualized dropdown-style base preset selector
