    local function nowMs()
        if Time and Time.GetEpocheMs then
            local ok, value = driftgod.Try(Time.GetEpocheMs)
            if ok and tonumber(value) then return tonumber(value) end
        end
        if driftgod.DriftChallengeNowMs then
            local ok, value = driftgod.Try(driftgod.DriftChallengeNowMs)
            if ok and tonumber(value) then return tonumber(value) end
        end
        if os and os.clock then return math.floor((os.clock() or 0) * 1000) end
        return 0
    end

    local function isReset(id)
        id = tostring(id or "")
        return id == "" or id == RESET_ID or id == "reset" or id == "Reset" or id == "Default Drifting"
    end

    local function normalizeId(id)
        if isReset(id) then return RESET_ID end
        return tostring(id or RESET_ID)
    end

    local function displayName(item)
        if type(item) ~= "table" then return "Reset" end
        local id = tostring(item.id or "")
        local name = tostring(item.name or item.label or id)
        if isReset(id) or name == "Default Drifting" then return "Reset" end
        return name:gsub("Default Drifting", "Reset"):gsub("DriftGod Wide Angle", "Wide Angle")
    end

    local function listSignature(source)
        if type(source) ~= "table" then return "none" end
        local parts = { tostring(#source) }
        for i = 1, #source do
            local item = source[i]
            parts[#parts + 1] = tostring(type(item) == "table" and item.id or "")
        end
        return table.concat(parts, "|")
    end

    local function buildList(force)
        local now = nowMs()
        if force ~= true and type(P17.list) == "table" and #P17.list > 0
            and (now - (tonumber(P17.listAtMs or 0) or 0)) < LIST_CACHE_MS then
            return P17.list
        end

        local source = nil
        if driftgod.R249GetBasePresetDropdownList then
            local ok, value = driftgod.Try(driftgod.R249GetBasePresetDropdownList, false)
            if ok and type(value) == "table" then source = value end
        end
        if type(source) ~= "table" and driftgod.R250GetBasePresetList then
            local ok, value = driftgod.Try(driftgod.R250GetBasePresetList)
            if ok and type(value) == "table" then source = value end
        end
        if type(source) ~= "table" then source = driftgod.ArcadeDriftPresets or {} end

        local out = {{ id = RESET_ID, name = "Reset" }}
        local seen = { [RESET_ID] = true }
        for _, item in ipairs(source) do
            local id = normalizeId(type(item) == "table" and item.id or "")
            if id ~= RESET_ID and not seen[id] then
                seen[id] = true
                out[#out + 1] = {
                    id = id,
                    name = displayName(item),
                    preset = item,
                }
            end
        end

        local sig = listSignature(out)
        if sig ~= P17.listSignature then
            P17.listSignature = sig
            for _, slotState in pairs(P17.slots) do
                slotState.open = false
                slotState.pageStart = 1
            end
        end

        P17.list = out
        P17.listAtMs = now
        return out
    end

    local function findIndex(list, id)
        id = normalizeId(id)
        for i = 1, #list do
            if normalizeId(list[i] and list[i].id) == id then return i end
        end
        return 1
    end

    local function clampPageStart(startIndex, count)
        local maxStart = math.max(1, count - VISIBLE_ROWS + 1)
        startIndex = tonumber(startIndex or 1) or 1
        if startIndex < 1 then startIndex = 1 end
        if startIndex > maxStart then startIndex = maxStart end
        return startIndex
    end

    local function centeredPageStart(selectedIndex, count)
        return clampPageStart((tonumber(selectedIndex or 1) or 1) - math.floor(VISIBLE_ROWS / 2), count)
    end

    local function button(label)
        if not (ImGui and ImGui.Button) then return false end
        local clicked = false
        local ok = driftgod.Try(function() clicked = ImGui.Button(tostring(label)) == true end)
        return ok == true and clicked == true
    end

    local function sameLine()
        if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end
    end

    local function text(value)
        if ImGui and ImGui.Text then
            driftgod.Try(ImGui.Text, tostring(value or ""))
        elseif dgMiniText then
            driftgod.Try(dgMiniText, tostring(value or ""), "purple")
        end
    end

    local function separator()
        if ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end
    end

    local function applyOnce(id)
        id = normalizeId(id)
        driftgod.__R250BasePresetDropdownBusy = true

        local ok, result = driftgod.Try(function()
            driftgod.S.r195BaseTuningPreset = id
            driftgod.S.r198BaseTuningPreset = id
            driftgod.S.activeArcadeDriftPreset = id

            if isReset(id) then
                if driftgod.ApplyResetPreset then return driftgod.ApplyResetPreset(false) end
                if driftgod.ApplyDefaultDriftingPreset then return driftgod.ApplyDefaultDriftingPreset(false, true) end
                return true
            end

            if driftgod.ApplyArcadeDriftPreset then
                return driftgod.ApplyArcadeDriftPreset(id, false)
            end
            return true
        end)

        driftgod.__R250BasePresetDropdownBusy = false

        if ok and result ~= false then
            if driftgod.R245RefreshTuningSliderCaps then
                driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false)
            end
            P17.applies = (tonumber(P17.applies or 0) or 0) + 1
            p17Log("applied once | id=" .. tostring(id) .. " | count=" .. tostring(P17.applies))
            return true
        end

        p17Log("apply failed | id=" .. tostring(id) .. " | error=" .. tostring(result), true)
        return false
    end

    local function slotState(slot, current, preview)
        slot = tostring(slot or "R196B")
        local state = P17.slots[slot]
        if type(state) ~= "table" then
            state = {
                open = false,
                pendingId = normalizeId(current),
                pendingName = tostring(preview or "Reset"),
                dirty = false,
                activeId = normalizeId(current),
                pageStart = 1,
                announced = false,
            }
            P17.slots[slot] = state
        end

        local activeId = normalizeId(current)
        if state.open ~= true and state.dirty ~= true and normalizeId(state.activeId) ~= activeId then
            state.activeId = activeId
            state.pendingId = activeId
            state.pendingName = tostring(preview or state.pendingName or "Reset")
        end
        return state
    end

    function driftgod.PrimeRenderDriftTuningBasePresetSelector(current, preview, slot)
        slot = tostring(slot or "R196B")
        current = normalizeId(current)
        local state = slotState(slot, current, preview)

        if state.announced ~= true then
            state.announced = true
            p17Log("virtualized Drift Tuning dropdown active | slot=" .. slot .. " | maxVisibleRows=" .. tostring(VISIBLE_ROWS))
        end

        local display = state.dirty == true and state.pendingName or tostring(preview or state.pendingName or "Reset")
        local arrow = state.open == true and " ^" or " v"
        if button("Base Preset: " .. tostring(display) .. arrow .. "##PrimeP17Open_" .. slot) then
            state.open = not (state.open == true)
            if state.open == true then
                local list = buildList(true)
                local selectedIndex = findIndex(list, state.pendingId or current)
                state.pageStart = centeredPageStart(selectedIndex, #list)
            end
        end

        if state.open == true then
            local list = buildList(false)
            local count = #list
            state.pageStart = clampPageStart(state.pageStart, count)
            local first = state.pageStart
            local last = math.min(count, first + VISIBLE_ROWS - 1)

            separator()

            if first > 1 then
                if button("^ More##PrimeP17PrevPage_" .. slot) then
                    state.pageStart = clampPageStart(first - VISIBLE_ROWS, count)
                end
            end

            for i = first, last do
                local item = list[i]
                local id = normalizeId(item and item.id)
                local name = tostring(item and item.name or "Reset")
                local marker = "  "
                if id == normalizeId(state.pendingId) then marker = "> "
                elseif id == current then marker = "* " end

                if button(marker .. name .. "##PrimeP17Row_" .. slot .. "_" .. tostring(i)) then
                    state.pendingId = id
                    state.pendingName = name
                    state.dirty = id ~= current
                    state.open = false
                end
            end

            if last < count then
                if button("v More##PrimeP17NextPage_" .. slot) then
                    state.pageStart = clampPageStart(first + VISIBLE_ROWS, count)
                end
            end

            separator()
        end

        if state.dirty == true then
            if button("Apply##PrimeP17Apply_" .. slot) then
                local pendingId = normalizeId(state.pendingId)
                if applyOnce(pendingId) then
                    current = pendingId
                    preview = tostring(state.pendingName or preview or "Reset")
                    state.activeId = pendingId
                    state.dirty = false
                    state.open = false
                end
            end
            sameLine()
            if button("Cancel##PrimeP17Cancel_" .. slot) then
                state.pendingId = current
                state.pendingName = tostring(preview or "Reset")
                state.activeId = current
                state.dirty = false
                state.open = false
            end
        end

        return current, preview
    end

    driftgod.R250RenderBasePresetCombo = function(current, preview)
        return driftgod.PrimeRenderDriftTuningBasePresetSelector(current, preview, "R250")
    end

    p17Log("patch installed | dropdown-style selector restored | virtualized rows=" .. tostring(VISIBLE_ROWS) .. " | apply-on-confirm")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime ptfx callback safety
-- note: defers asset loading and particle natives out of feature callbacks.
-- ═══════════════════════════════════════════════════════════════════════════════════

do
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.H = driftgod.H or {}

    driftgod.__PrimeBuild = true
    driftgod.__PrimePTFXPatch = "P18_Deferred_Local_Worker"

    local p18ImmediateStart = driftgod.StartPTFX
    local p18ImmediateStop = driftgod.StopPTFX
    local p18OriginalNext = driftgod.NextPTFX
    local p18OriginalPrevious = driftgod.PreviousPTFX

    local function p18Log(msg)
        msg = "[DriftGod Prime] [PTFX P18] " .. tostring(msg or "")
        if Logger and Logger.LogInfo then
            driftgod.Try(Logger.LogInfo, msg)
        elseif driftgod.Log then
            driftgod.Try(driftgod.Log, msg)
        end
    end

    local function p18Toast(msg, ms)
        if driftgod.Toast then
            driftgod.Try(driftgod.Toast, tostring(msg or ""), ms or 1800)
        elseif GUI and GUI.AddToast then
            driftgod.Try(GUI.AddToast, "DriftGod", tostring(msg or ""), ms or 1800)
        end
    end

    local function p18NowMs()
        if Time and Time.GetEpocheMs then
            local ok, value = driftgod.Try(Time.GetEpocheMs)
            if ok and tonumber(value) then return tonumber(value) end
        end
        return math.floor((os.clock and os.clock() or 0) * 1000)
    end

    local function p18SetLocalMode()
        -- Prime stability: do not enter freemode script context or networked PTFX natives.
        driftgod.S.ptfxUseFreemodeScript = false
        driftgod.S.ptfxFreemode = false
        driftgod.S.ptfxUseFreemode = false
        driftgod.S.ptfxFreemodeMode = false
    end

    local function p18Queue(action, reason)
        action = tostring(action or "")
        if action ~= "start" and action ~= "stop" and action ~= "restart" then return false end

        p18SetLocalMode()
        driftgod.S._primeP18PtfxPending = action
        driftgod.S._primeP18PtfxPendingReason = tostring(reason or "unspecified")
        driftgod.S._primeP18PtfxPendingAt = p18NowMs()
        p18Log("queued | action=" .. action .. " | reason=" .. tostring(reason or "unspecified"))
        return true
    end

    -- Public Start/Stop calls are converted to requests so buttons and feature callbacks
    -- never load assets, yield, or invoke particle natives directly.
    function driftgod.StartPTFX()
        return p18Queue("start", "StartPTFX")
    end

    function driftgod.StopPTFX()
        return p18Queue("stop", "StopPTFX")
    end

    function driftgod.R140_SetPTFXEnabled(enabled)
        driftgod.S = driftgod.S or {}
        local on = enabled == true

        -- This function runs inside the Enable PTFX feature callback. Keep it Lua-only.
        driftgod.S._r143PtfxBusy = false
        driftgod.S._r143PtfxSelectionDirty = false
        driftgod.S.ptfxRequestedEnabled = on
        p18SetLocalMode()

        if on then
            p18Queue("start", "Enable PTFX toggle on")
        else
            p18Queue("stop", "Enable PTFX toggle off")
        end
    end

    function driftgod.ToggleFreemodePTFXMode()
        p18SetLocalMode()
        p18Toast("Freemode PTFX is disabled on Prime for stability.", 2200)
        p18Log("freemode request blocked safely")
        return false
    end

    function driftgod.NextPTFX()
        driftgod.S = driftgod.S or {}
        local effects = driftgod.PTFX and driftgod.PTFX.effects or {}
        local total = #effects
        if total <= 0 then return false end

        local wasRequested = driftgod.S.ptfxRequestedEnabled == true or driftgod.S.ptfxRunning == true
        driftgod.S.ptfxSelectedIndex = (tonumber(driftgod.S.ptfxSelectedIndex or 1) or 1) + 1
        if driftgod.S.ptfxSelectedIndex > total then driftgod.S.ptfxSelectedIndex = 1 end
        driftgod.S._r143PtfxSelectionDirty = false

        if wasRequested then p18Queue("restart", "Next PTFX") end
        p18Log("next selected | index=" .. tostring(driftgod.S.ptfxSelectedIndex) .. " | restart=" .. tostring(wasRequested))
        return true
    end

    function driftgod.PreviousPTFX()
        driftgod.S = driftgod.S or {}
        local effects = driftgod.PTFX and driftgod.PTFX.effects or {}
        local total = #effects
        if total <= 0 then return false end

        local wasRequested = driftgod.S.ptfxRequestedEnabled == true or driftgod.S.ptfxRunning == true
        driftgod.S.ptfxSelectedIndex = (tonumber(driftgod.S.ptfxSelectedIndex or 1) or 1) - 1
        if driftgod.S.ptfxSelectedIndex < 1 then driftgod.S.ptfxSelectedIndex = total end
        driftgod.S._r143PtfxSelectionDirty = false

        if wasRequested then p18Queue("restart", "Previous PTFX") end
        p18Log("previous selected | index=" .. tostring(driftgod.S.ptfxSelectedIndex) .. " | restart=" .. tostring(wasRequested))
        return true
    end

    -- The original tick restarts particle assets from a normal feature OnTick callback.
    -- A dedicated RegisterLooped worker below owns refreshes instead.
    function driftgod.LightTrailsTick()
        return true
    end

    if Script and Script.RegisterLooped and driftgod.__PrimeP18PTFXWorkerInstalled ~= true then
        driftgod.__PrimeP18PTFXWorkerInstalled = true

        Script.RegisterLooped(function()
            if ShouldUnload and ShouldUnload() then
                -- Prime reload safety: do not call native/UI cleanup from a loop worker while
                -- Cherax is destroying Lua features on the render thread. Existing handles are
                -- owned by the unloading script and are discarded with its runtime state.
                driftgod.S = driftgod.S or {}
                driftgod.S._primeP18PtfxPending = nil
                driftgod.S._primeP18PtfxPendingReason = nil
                driftgod.S.ptfxRequestedEnabled = false
                driftgod.S.ptfxRunning = false
                return false
            end

            driftgod.S = driftgod.S or {}
            local action = driftgod.S._primeP18PtfxPending

            if action then
                local reason = tostring(driftgod.S._primeP18PtfxPendingReason or "unspecified")
                driftgod.S._primeP18PtfxPending = nil
                driftgod.S._primeP18PtfxPendingReason = nil
                p18SetLocalMode()

                p18Log("worker begin | action=" .. tostring(action) .. " | reason=" .. reason)

                local ok, result = true, nil
                if action == "stop" then
                    if type(p18ImmediateStop) == "function" then
                        ok, result = driftgod.Try(p18ImmediateStop)
                    end
                    driftgod.S.ptfxRequestedEnabled = false
                    driftgod.S.ptfxRunning = false
                elseif action == "restart" then
                    if type(p18ImmediateStop) == "function" then driftgod.Try(p18ImmediateStop) end
                    if Script and Script.Yield then Script.Yield(30) end
                    if type(p18ImmediateStart) == "function" then
                        ok, result = driftgod.Try(p18ImmediateStart)
                    end
                    driftgod.S.ptfxRequestedEnabled = ok == true and driftgod.S.ptfxRunning == true
                else
                    if type(p18ImmediateStart) == "function" then
                        ok, result = driftgod.Try(p18ImmediateStart)
                    end
                    driftgod.S.ptfxRequestedEnabled = ok == true and driftgod.S.ptfxRunning == true
                end

                p18Log("worker complete | action=" .. tostring(action)
                    .. " | ok=" .. tostring(ok)
                    .. " | running=" .. tostring(driftgod.S.ptfxRunning == true)
                    .. " | result=" .. tostring(result))

                if not ok then
                    driftgod.S.ptfxRunning = false
                    driftgod.S.ptfxRequestedEnabled = false
                    p18Toast("PTFX failed safely. Check the P18 log.", 2200)

                    driftgod.Try(function()
                        if driftgod.H.R140_PTFXEnabled and FeatureMgr and FeatureMgr.GetFeature then
                            local feature = FeatureMgr.GetFeature(driftgod.H.R140_PTFXEnabled)
                            if feature and feature.SetBoolValue then feature:SetBoolValue(false) end
                        end
                    end)
                end
            end

            -- Optional loop refresh is also performed here, where yielding is safe.
            if driftgod.S.ptfxRunning == true and driftgod.S.ptfxLoopKeeperEnabled ~= false then
                local intervalMs = tonumber(driftgod.S.ptfxLoopRefreshMs or 1500) or 1500
                if intervalMs < 1000 then intervalMs = 1000 end
                local lastMs = tonumber(driftgod.S._primeP18LastRefreshMs or p18NowMs()) or p18NowMs()
                local nowMs = p18NowMs()
                driftgod.S._primeP18LastRefreshMs = lastMs

                if nowMs - lastMs >= intervalMs then
                    driftgod.S._primeP18LastRefreshMs = nowMs
                    p18SetLocalMode()
                    if type(p18ImmediateStop) == "function" then driftgod.Try(p18ImmediateStop) end
                    if Script and Script.Yield then Script.Yield(20) end
                    local okRefresh, errRefresh = true, nil
                    if type(p18ImmediateStart) == "function" then
                        okRefresh, errRefresh = driftgod.Try(p18ImmediateStart)
                    end
                    p18Log("worker refresh | ok=" .. tostring(okRefresh)
                        .. " | running=" .. tostring(driftgod.S.ptfxRunning == true)
                        .. " | error=" .. tostring(errRefresh))
                end
            else
                driftgod.S._primeP18LastRefreshMs = p18NowMs()
            end

            if Script and Script.Yield then
                local busy = driftgod.S and (driftgod.S._primeP18PtfxPending ~= nil or driftgod.S.ptfxRunning == true)
                Script.Yield(busy and 50 or 250)
            end
        end)
    else
        p18Log("worker unavailable | Script.RegisterLooped=" .. tostring(Script and Script.RegisterLooped ~= nil))
    end

    p18SetLocalMode()
    if driftgod.S.ptfxLoopRefreshMs == nil or tonumber(driftgod.S.ptfxLoopRefreshMs) < 1000 then
        driftgod.S.ptfxLoopRefreshMs = 1500
    end

    p18Log("patch installed | feature callback deferred | local PTFX only | worker refresh enabled")
end

-- prime ptfx loop keeper safety
-- note: looped effects remain active without forced stop/start cycling on Prime.
do
    driftgod = driftgod or DG or {}
    driftgod.S = driftgod.S or {}
    driftgod.S.ptfxLoopKeeperEnabled = false

    function driftgod.TogglePTFXLoopKeeper()
        driftgod.S.ptfxLoopKeeperEnabled = false
        if driftgod.Toast then
            driftgod.Try(driftgod.Toast, "PTFX Loop Keeper is disabled on Prime for stability.", 2200)
        elseif GUI and GUI.AddToast then
            driftgod.Try(GUI.AddToast, "DriftGod", "PTFX Loop Keeper is disabled on Prime for stability.", 2200)
        end
        if Logger and Logger.LogInfo then
            driftgod.Try(Logger.LogInfo, "[DriftGod Prime] [PTFX P18] loop keeper request blocked safely")
        end
        return false
    end
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime production alpha
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.__GoldenBaseline = "v1.0.1 Production Alpha"
driftgod.__ProductionBundleBase = "v1.0.2-production-alpha"
driftgod.__ProductionPatch = "P20_Prime_Performance_Audit"
driftgod.Version = "v1.0.1"

do
    driftgod.__PrimeP20 = driftgod.__PrimeP20 or { frames = {}, times = {} }
    local state = driftgod.__PrimeP20

    local function nowMs()
        local value = 0
        driftgod.Try(function()
            if Time and Time.GetEpocheMs then value = tonumber(Time.GetEpocheMs() or 0) or 0 end
        end)
        if value <= 0 then value = math.floor((os.clock() or 0) * 1000) end
        return value
    end

    local function frameId()
        local value = nil
        driftgod.Try(function()
            if MISC and MISC.GET_FRAME_COUNT then value = tonumber(MISC.GET_FRAME_COUNT()) end
        end)
        if value == nil then
            driftgod.Try(function()
                if Natives and Natives.InvokeInt then value = tonumber(Natives.InvokeInt(0xFC8202EFC642E6F2)) end
            end)
        end
        return value
    end

    local function wrapOncePerFrame(name, key)
        local original = driftgod[name]
        if type(original) ~= "function" or state["wrapped_" .. key] == true then return end
        driftgod[name] = function(...)
            local frame = frameId()
            if frame ~= nil then
                if state.frames[key] == frame then return end
                state.frames[key] = frame
            else
                local now = nowMs()
                if now - (state.times[key] or -1000) < 5 then return end
                state.times[key] = now
            end
            return original(...)
        end
        state["wrapped_" .. key] = true
    end

    wrapOncePerFrame("TickDriftChallengeRace", "challenge_tick")
    wrapOncePerFrame("DrawDriftChallengeHud", "challenge_hud")
    wrapOncePerFrame("RenderLockedArcadePresetBanner", "locked_banner")
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime garage first-open scan, recursive folders, random hotkey, and reload safety
-- note: scans once when the garage is first opened, keeps the session cache afterward,
--       includes nested vehicle folders, and adds a saved F9 random-vehicle hotkey.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.H = driftgod.H or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or { lastKeys = {}, scroll = 0, inputLockUntil = 0 }
    driftgod.DefaultSettings = driftgod.DefaultSettings or {}

    driftgod.__PrimeGarageP21 = driftgod.__PrimeGarageP21 or {
        patch = "P23_Exact_Subfolder_Index_And_Random_Hotkey_Combo",
        autoScanQueued = false,
        autoScanAttempted = false,
        autoScanComplete = false,
        scanInProgress = false,
        pendingRandom = false,
        workerInstalled = false,
        lastScanCount = 0,
        unloading = false,
        unloadHandlerInstalled = false,
    }
    local P21 = driftgod.__PrimeGarageP21

    driftgod.__GoldenBaseline = "v1.0.1 Production Alpha"
    driftgod.__ProductionBundleBase = "v1.0.5-production-alpha"
    driftgod.__ProductionPatch = "P23_Exact_Subfolder_Index_And_Random_Hotkey_Combo"
    driftgod.Version = "v1.0.1"

    local RANDOM_DEFAULT_KEY = 0x78 -- F9
    local SAVED_VEHICLE_LIST_HASH = 514776905

    local function isUnloading()
        if P21.unloading == true then return true end
        local unloading = false
        driftgod.Try(function()
            if ShouldUnload and ShouldUnload() then unloading = true end
        end)
        return unloading == true
    end

    local function logMessage(message, important)
        message = "[DriftGod Prime] [Garage] " .. tostring(message or "")
        if important == true and Logger and Logger.LogError then
            Logger.LogError(message)
        elseif Logger and Logger.LogInfo then
            Logger.LogInfo(message)
        elseif log then
            log(message)
        end
    end

    local function toast(message, duration)
        if driftgod.VS_Toast then
            driftgod.Try(driftgod.VS_Toast, tostring(message or ""), duration or 2500)
        elseif driftgod.Toast then
            driftgod.Try(driftgod.Toast, tostring(message or ""), duration or 2500)
        end
    end

    local function nowMs()
        local value = 0
        driftgod.Try(function()
            if Time and Time.GetEpocheMs then value = tonumber(Time.GetEpocheMs() or 0) or 0 end
        end)
        if value <= 0 then
            driftgod.Try(function()
                if os and os.clock then value = math.floor((tonumber(os.clock() or 0) or 0) * 1000) end
            end)
        end
        return value
    end

    local function normalize(path)
        path = tostring(path or ""):gsub("/", "\\")
        while #path > 3 and path:sub(-1) == "\\" do path = path:sub(1, -2) end
        return path
    end

    local function addUnique(list, seen, value)
        value = normalize(value)
        if value == "" then return end
        local key = value:lower()
        if seen[key] then return end
        seen[key] = true
        list[#list + 1] = value
    end

    local function vehicleRoots()
        local roots, seen = {}, {}

        if type(driftgod.VS_Roots) == "function" then
            local ok, values = driftgod.Try(driftgod.VS_Roots)
            if ok and type(values) == "table" then
                for _, root in ipairs(values) do addUnique(roots, seen, root) end
            end
        end

        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then
                local root = normalize(FileMgr.GetMenuRootPath() or "")
                if root ~= "" then
                    addUnique(roots, seen, root .. "\\Vehicles")
                    addUnique(roots, seen, root:gsub("\\Lua$", "") .. "\\Vehicles")
                end
            end
        end)

        driftgod.Try(function()
            if os and os.getenv then
                local profile = tostring(os.getenv("USERPROFILE") or "")
                if profile ~= "" then addUnique(roots, seen, profile .. "\\Documents\\Cherax\\Vehicles") end
            end
        end)

        return roots
    end

    local function valueToPath(value)
        if value == nil then return nil end
        if type(value) == "string" then return normalize(value) end

        local candidates = {}
        local function add(valueText)
            if type(valueText) == "string" and valueText ~= "" then candidates[#candidates + 1] = valueText end
        end

        driftgod.Try(function() add(value.path) end)
        driftgod.Try(function() add(value.Path) end)
        driftgod.Try(function() add(value.filename) end)
        driftgod.Try(function() add(value.FileName) end)

        for _, methodName in ipairs({ "string", "String", "ToString", "GetPath", "GetString" }) do
            driftgod.Try(function()
                local fn = value[methodName]
                if type(fn) == "function" then add(fn(value)) end
            end)
        end

        local rendered = tostring(value or "")
        if rendered ~= "" and not rendered:match("^userdata:") then add(rendered) end

        for _, candidate in ipairs(candidates) do
            candidate = normalize(candidate)
            if candidate ~= "" then return candidate end
        end
        return nil
    end

    local function decodeCollection(collection)
        local output, seen = {}, {}

        local function add(value)
            local path = valueToPath(value)
            if not path or path == "" then return false end
            local key = path:lower()
            if seen[key] then return false end
            seen[key] = true
            output[#output + 1] = path
            return true
        end

        if type(collection) == "table" then
            for _, value in pairs(collection) do add(value) end
            return output
        end

        if type(collection) ~= "userdata" then return output end

        local reportedLength = -1
        local okLength, lengthValue = driftgod.Try(function() return #collection end)
        if okLength then reportedLength = tonumber(lengthValue or -1) or -1 end

        local methodCount = -1
        for _, methodName in ipairs({ "size", "Size", "GetSize", "count", "Count", "GetCount" }) do
            local ok, result = driftgod.Try(function()
                local fn = collection[methodName]
                if type(fn) == "function" then return fn(collection) end
                return nil
            end)
            result = ok and tonumber(result) or nil
            if result and result >= 0 then methodCount = result; break end
        end

        local count = math.max(reportedLength, methodCount)
        if count > 10000 then count = 10000 end

        if count >= 0 then
            for index = 1, count do
                local ok, value = driftgod.Try(function() return collection[index] end)
                if ok and value ~= nil then add(value) end
            end
            if #output == 0 then
                for index = 0, math.max(0, count - 1) do
                    local ok, value = driftgod.Try(function() return collection[index] end)
                    if ok and value ~= nil then add(value) end
                end
            end
        end

        if #output == 0 then
            driftgod.Try(function()
                for _, value in ipairs(collection) do add(value) end
            end)
        end

        if #output == 0 then
            driftgod.Try(function()
                for _, value in pairs(collection) do add(value) end
            end)
        end

        if #output == 0 and count < 0 then
            local consecutiveNil = 0
            for index = 1, 4096 do
                local ok, value = driftgod.Try(function() return collection[index] end)
                if ok and value ~= nil then
                    add(value)
                    consecutiveNil = 0
                else
                    consecutiveNil = consecutiveNil + 1
                    if consecutiveNil >= 8 then break end
                end
            end
        end

        return output
    end

    local function makeAbsolute(root, path)
        root = normalize(root)
        path = normalize(path)
        if path == "" then return "" end
        if path:match("^[A-Za-z]:\\") or path:sub(1, 2) == "\\\\" then return path end
        return normalize(root .. "\\" .. path:gsub("^\\+", ""))
    end

    local function relativeToRoot(root, path)
        root = normalize(root)
        path = normalize(path)
        if root ~= "" and path:lower():sub(1, #root) == root:lower() then
            return path:sub(#root + 1):gsub("^\\+", "")
        end
        return path:gsub("^\\+", "")
    end

    local function categoryForRelative(relative)
        relative = normalize(relative):gsub("^\\+", "")
        local directory = relative:match("^(.*)\\[^\\]+$")
        if directory and directory ~= "" then return directory end
        return "Root"
    end

    local function runFind(root, extension, recursive)
        local ok, result = driftgod.Try(function()
            return FileMgr.FindFiles(root, extension, recursive == true)
        end)
        if not ok then return {} end
        return decodeCollection(result)
    end

    local function canonicalVehicleRoot()
        local root = ""
        driftgod.Try(function()
            if FileMgr and FileMgr.GetMenuRootPath then root = normalize(FileMgr.GetMenuRootPath() or "") end
        end)
        root = root:gsub("\\[Ll][Uu][Aa]$", "")
        if root == "" then
            local roots = vehicleRoots()
            return normalize(roots[1] or "")
        end
        return normalize(root .. "\\Vehicles")
    end

    local function buildCheraxOrderedIndex()
        local roots, rootSeen = {}, {}
        local function addRoot(root)
            root = normalize(root)
            if root == "" then return end
            local key = root:lower()
            if rootSeen[key] then return end
            rootSeen[key] = true
            roots[#roots + 1] = root
        end

        addRoot(canonicalVehicleRoot())
        for _, root in ipairs(vehicleRoots()) do addRoot(root) end

        for _, root in ipairs(roots) do
            local ordered, seen = {}, {}
            -- Use one successful recursive query, exactly like the known-working Cherax
            -- saved-vehicle loaders. Do not merge root-only results into list ordering.
            for _, extension in ipairs({ ".json", "json", "*.json" }) do
                local batch = runFind(root, extension, true)
                for _, path in ipairs(batch) do
                    path = makeAbsolute(root, path)
                    if path ~= "" and path:lower():match("%.json$") then
                        local key = path:lower()
                        if not seen[key] then
                            seen[key] = true
                            ordered[#ordered + 1] = path
                        end
                    end
                end
                if #ordered > 0 then break end
            end

            if #ordered > 0 then
                table.sort(ordered, function(a, b) return tostring(a):lower() < tostring(b):lower() end)
                local indexByPath = {}
                for index, path in ipairs(ordered) do indexByPath[normalize(path):lower()] = index - 1 end
                return indexByPath, ordered, root
            end
        end

        return {}, {}, canonicalVehicleRoot()
    end

    function driftgod.P21_RecursiveGarageScan(reason)
        if isUnloading() then return #(driftgod.VS.runtime.items or {}) end
        if P21.scanInProgress == true then return #(driftgod.VS.runtime.items or {}) end
        if not (FileMgr and FileMgr.FindFiles) then
            logMessage("vehicle scan unavailable: FileMgr.FindFiles missing", true)
            return 0
        end

        P21.scanInProgress = true
        local roots = vehicleRoots()
        local found, seen, sourceRoot = {}, {}, {}

        local function addPath(root, path)
            path = makeAbsolute(root, path)
            if path == "" or not path:lower():match("%.json$") then return end
            local key = path:lower()
            if seen[key] then return end
            seen[key] = true
            found[#found + 1] = path
            sourceRoot[key] = normalize(root)
        end

        for _, root in ipairs(roots) do
            driftgod.Try(function() if FileMgr.CreateDir then FileMgr.CreateDir(root) end end)

            -- Always merge recursive results. The former scanner stopped after finding any
            -- root-level file, which prevented Prime from ever requesting subfolder files.
            for _, extension in ipairs({ ".json", "json", "*.json" }) do
                for _, recursive in ipairs({ true, false }) do
                    for _, path in ipairs(runFind(root, extension, recursive)) do addPath(root, path) end
                end
            end
        end

        table.sort(found, function(a, b) return tostring(a):lower() < tostring(b):lower() end)

        -- Cherax's Load Vehicle index must come from its canonical recursive Vehicles list,
        -- not from the merged UI discovery list. Mixing roots shifts subfolder indices and
        -- makes a displayed name load a different saved vehicle.
        local cheraxIndexByPath, cheraxOrderedPaths, cheraxIndexRoot = buildCheraxOrderedIndex()
        P21.cheraxIndexByPath = cheraxIndexByPath
        P21.cheraxOrderedPaths = cheraxOrderedPaths
        P21.cheraxIndexRoot = cheraxIndexRoot

        local items = {}
        local categories, categorySeen = { "All" }, { All = true }
        local exactMapped = 0

        for _, path in ipairs(found) do
            local root = sourceRoot[path:lower()] or roots[1] or ""
            local relative = relativeToRoot(root, path)
            local filename = path:match("([^\\]+)$") or path
            local name = filename:gsub("%.[Jj][Ss][Oo][Nn]$", "")
            local category = categoryForRelative(relative)
            local label = category ~= "Root" and (category .. " / " .. name) or name

            if not categorySeen[category] then
                categorySeen[category] = true
                categories[#categories + 1] = category
            end

            local exactIndex = cheraxIndexByPath[normalize(path):lower()]
            if exactIndex ~= nil then exactMapped = exactMapped + 1 end

            items[#items + 1] = {
                name = name,
                path = path,
                rel = relative,
                category = category,
                displayLabel = label,
                ext = "json",
                root = root,
                primeDiskItem = true,
                primeFileMgrItem = true,
                primeRecursiveItem = true,
                cheraxListHash = SAVED_VEHICLE_LIST_HASH,
                cheraxListIndex = exactIndex,
                cheraxIndexRoot = cheraxIndexRoot,
            }
        end

        table.sort(categories, function(a, b)
            if a == "All" then return true end
            if b == "All" then return false end
            return tostring(a):lower() < tostring(b):lower()
        end)

        driftgod.VS.runtime.items = items
        driftgod.VS.runtime.categories = categories
        driftgod.VS.runtime.currentFolder = nil
        driftgod.VS.runtime.root = roots[1] or ""
        driftgod.VS.runtime.lastScanMs = nowMs()
        driftgod.VS.runtime.lastStatus = "Saved vehicles: " .. tostring(#items)
        driftgod.S.vehicleSpawnerIndex = 0
        driftgod.S.vehicleSpawnerCategoryIndex = 0
        driftgod.VS.hud.scroll = 0

        if isUnloading() then
            P21.scanInProgress = false
            return #items
        end

        local rebuildOk, rebuildError = driftgod.Try(function()
            if driftgod.VS_Rebuild then driftgod.VS_Rebuild(true) end
            if driftgod.VS_SyncFeatures then driftgod.VS_SyncFeatures() end
        end)

        P21.scanInProgress = false
        P21.autoScanAttempted = true
        P21.autoScanComplete = true
        P21.autoScanQueued = false
        P21.lastScanCount = #items

        if not rebuildOk then
            logMessage("garage rebuild failed after scan: " .. tostring(rebuildError), true)
            return 0
        end

        logMessage("vehicle scan complete | reason=" .. tostring(reason or "manual")
            .. " | vehicles=" .. tostring(#items)
            .. " | folders=" .. tostring(math.max(0, #categories - 1))
            .. " | exactMappings=" .. tostring(exactMapped) .. "/" .. tostring(#items)
            .. " | cheraxOrder=" .. tostring(#cheraxOrderedPaths)
            .. " | indexRoot=" .. tostring(cheraxIndexRoot))
        return #items
    end

    -- Keep every existing manual Scan button and HUD scan key pointed at the new Prime-safe scanner.
    driftgod.VS_PrimeRootJsonRefresh = driftgod.P21_RecursiveGarageScan
    driftgod.VS_PrimeSafeDiskRefresh = driftgod.P21_RecursiveGarageScan
    driftgod.VS_Refresh = driftgod.P21_RecursiveGarageScan
    driftgod.R153_ScanVehicleSpawner = driftgod.P21_RecursiveGarageScan
    driftgod.R154_RefreshSpawner = driftgod.P21_RecursiveGarageScan
    driftgod.R115_ScanSpawnerVehicles = driftgod.P21_RecursiveGarageScan
    driftgod.R114_ScanSpawnerVehicles = driftgod.P21_RecursiveGarageScan

    -- Resolve Random before entering P12, then require the exact canonical path mapping.
    -- A missing mapping is blocked instead of allowing Cherax to load the wrong vehicle.
    if type(driftgod.VS_LoadItem) == "function" and P21.exactLoadWrapped ~= true then
        P21.exactLoadWrapped = true
        local PreviousExactLoadItem = driftgod.VS_LoadItem
        driftgod.VS_LoadItem = function(item, ...)
            if not item then return false end

            if item.isRandom then
                local pool = {}
                local target = tostring(item.randomTargetCategory or "All")
                for _, candidate in ipairs(driftgod.VS.runtime.items or {}) do
                    if target == "All" or tostring(candidate.category or "Root"):lower() == target:lower() then
                        pool[#pool + 1] = candidate
                    end
                end
                if #pool <= 0 then
                    logMessage("random vehicle blocked: no mapped vehicles available", true)
                    return false
                end
                return driftgod.VS_LoadItem(pool[math.random(1, #pool)], ...)
            end

            if not item.isFolder and tostring(item.path or ""):lower():match("%.json$") then
                local key = normalize(item.path):lower()
                local exactIndex = P21.cheraxIndexByPath and P21.cheraxIndexByPath[key] or nil
                if exactIndex == nil then
                    logMessage("load blocked: saved vehicle is not present in Cherax's canonical recursive index | file="
                        .. tostring(item.path or ""), true)
                    toast("Vehicle mapping changed. Press Scan and try again.", 3000)
                    return false
                end
                item.cheraxListHash = SAVED_VEHICLE_LIST_HASH
                item.cheraxListIndex = exactIndex
            end

            return PreviousExactLoadItem(item, ...)
        end
    end

    local PreviousSetOpen = driftgod.VS_SetOpen
    if type(PreviousSetOpen) == "function" and P21.openWrapped ~= true then
        P21.openWrapped = true
        driftgod.VS_SetOpen = function(openState, ...)
            local result = PreviousSetOpen(openState, ...)
            if not isUnloading() and openState == true and P21.autoScanAttempted ~= true and P21.autoScanQueued ~= true then
                P21.autoScanQueued = true
                P21.autoScanAt = nowMs() + 180
                driftgod.VS.runtime.lastStatus = "Preparing first Garage scan..."
            end
            return result
        end
    end

    function driftgod.P21_QueueRandomVehicle(reason)
        if isUnloading() then return false end
        P21.pendingRandom = true
        P21.pendingRandomReason = tostring(reason or "Random hotkey")
        P21.pendingRandomAt = nowMs()

        if P21.autoScanAttempted ~= true and P21.autoScanQueued ~= true then
            P21.autoScanQueued = true
            P21.autoScanAt = nowMs() + 80
        end
        return true
    end

    local function spawnRandomNow(reason)
        if isUnloading() then return false end
        local count = #(driftgod.VS.runtime.items or {})
        if count <= 0 then
            toast("No saved vehicles were found.", 2500)
            logMessage("random vehicle blocked: scan contains no vehicles", true)
            return false
        end

        if driftgod.VS_LoadItem and driftgod.VS_RandomRow then
            local ok, result = driftgod.Try(driftgod.VS_LoadItem, driftgod.VS_RandomRow("All"))
            if ok and result == true then
                logMessage("random vehicle loaded | reason=" .. tostring(reason or "Random"))
                return true
            end
        end

        local pool = driftgod.VS.runtime.items or {}
        local item = pool[math.random(1, #pool)]
        if item and driftgod.VS_LoadItem then
            local ok, result = driftgod.Try(driftgod.VS_LoadItem, item)
            return ok and result == true
        end
        return false
    end

    local function hotkeyIndexForCode(code)
        code = tonumber(code or 0) or 0
        for index, option in ipairs(driftgod.R289_HotkeyOptions or {}) do
            if tonumber(option.code or 0) == code then return index - 1 end
        end
        return 0
    end

    local function hotkeyOption(index)
        local options = driftgod.R289_HotkeyOptions or {}
        index = math.floor(tonumber(index or 0) or 0)
        if index < 0 then index = 0 end
        if index > #options - 1 then index = math.max(0, #options - 1) end
        return options[index + 1] or { name = "None", code = 0 }, index
    end

    driftgod.DefaultSettings.randomVehicleHotkeyKeyCode = RANDOM_DEFAULT_KEY
    driftgod.DefaultSettings.randomVehicleHotkeyIndex = hotkeyIndexForCode(RANDOM_DEFAULT_KEY)
    driftgod.DefaultSettings.randomVehicleHotkeyName = "F9"

    local function loadSavedRandomHotkey()
        local loaded = nil
        if driftgod.LoadTable and driftgod.SettingsFile then
            local ok, result = driftgod.Try(driftgod.LoadTable, driftgod.SettingsFile)
            if ok and type(result) == "table" then loaded = result end
        end

        if loaded and loaded.randomVehicleHotkeyKeyCode ~= nil then
            driftgod.S.randomVehicleHotkeyKeyCode = tonumber(loaded.randomVehicleHotkeyKeyCode or RANDOM_DEFAULT_KEY) or RANDOM_DEFAULT_KEY
        elseif driftgod.S.randomVehicleHotkeyKeyCode == nil then
            driftgod.S.randomVehicleHotkeyKeyCode = RANDOM_DEFAULT_KEY
        end

        driftgod.S.randomVehicleHotkeyIndex = hotkeyIndexForCode(driftgod.S.randomVehicleHotkeyKeyCode)
        local option = hotkeyOption(driftgod.S.randomVehicleHotkeyIndex)
        driftgod.S.randomVehicleHotkeyName = tostring(option.name or "F9")
    end

    loadSavedRandomHotkey()

    local function randomFeature()
        if isUnloading() then return nil end
        local feature = nil
        if driftgod.H.VehicleSpawnerRandom and FeatureMgr and FeatureMgr.GetFeature then
            driftgod.Try(function() feature = FeatureMgr.GetFeature(driftgod.H.VehicleSpawnerRandom) end)
        end
        if feature then
            driftgod.VS.features = driftgod.VS.features or {}
            driftgod.VS.features.random = feature
        end
        return feature
    end

    local function applyRandomHotkey()
        local feature = randomFeature()
        if not feature then return false end
        local code = tonumber(driftgod.S.randomVehicleHotkeyKeyCode or RANDOM_DEFAULT_KEY) or RANDOM_DEFAULT_KEY

        if driftgod.R289_ApplyFeatureHotkey then
            return driftgod.R289_ApplyFeatureHotkey(feature, driftgod.H.VehicleSpawnerRandom, code, "Random Vehicle") == true
        end

        driftgod.Try(function() if feature.ClearHotkeys then feature:ClearHotkeys() end end)
        if code <= 0 then return true end
        local ok = false
        if feature.AddHotKey then ok = driftgod.Try(function() feature:AddHotKey(code) end) end
        return ok == true
    end

    local function ensureRandomFeature()
        if isUnloading() then return nil end
        if not driftgod.H.VehicleSpawnerRandom then
            driftgod.H.VehicleSpawnerRandom = driftgod.Hash and driftgod.Hash("VehicleSpawnerRandom") or Utils.Joaat("VehicleSpawnerRandom")
        end

        -- Reload safety: the Random button already exists. Reuse it instead of calling
        -- SafeAddFeature, because SafeAddFeature removes the live feature first and can
        -- invalidate Cherax's render pointer while the menu is open.
        local feature = randomFeature()
        if feature then
            P21.randomFeatureInstalled = true
            return feature
        end

        P21.randomFeatureInstalled = false
        logMessage("existing Random feature unavailable; hotkey attachment skipped safely")
        return nil
    end

    driftgod.H.RandomVehicleHotkeyCombo = driftgod.H.RandomVehicleHotkeyCombo
        or (driftgod.Hash and driftgod.Hash("RandomVehicleHotkeyCombo") or Utils.Joaat("RandomVehicleHotkeyCombo"))

    local function setRandomHotkey(index, saveNow)
        local option, fixedIndex = hotkeyOption(index)
        driftgod.S.randomVehicleHotkeyIndex = fixedIndex
        driftgod.S.randomVehicleHotkeyKeyCode = tonumber(option.code or 0) or 0
        driftgod.S.randomVehicleHotkeyName = tostring(option.name or "None")
        applyRandomHotkey()
        if saveNow ~= false and driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
        return true
    end

    local function registerRandomHotkeyCombo()
        if isUnloading() then return nil end
        local hash = driftgod.H.RandomVehicleHotkeyCombo
        local feature = P21.randomHotkeyComboFeature

        if not feature and hash and FeatureMgr and FeatureMgr.GetFeature then
            driftgod.Try(function() feature = FeatureMgr.GetFeature(hash) end)
        end

        if not feature and hash and FeatureMgr and FeatureMgr.AddFeature and eFeatureType and eFeatureType.Combo then
            local ok, created = driftgod.Try(function()
                return FeatureMgr.AddFeature(
                    hash,
                    "Default Random Hotkey",
                    eFeatureType.Combo,
                    "Default: F9. Select the saved built-in Cherax hotkey used by the Garage Random button.",
                    function(f)
                        if P21.syncingRandomHotkeyCombo == true then return end
                        local index = 0
                        driftgod.Try(function() index = f:GetListIndex() end)
                        setRandomHotkey(index, true)
                    end,
                    true
                )
            end)
            if ok then feature = created end
        end

        if feature then
            P21.randomHotkeyComboFeature = feature
            if P21.randomHotkeyComboConfigured ~= true then
                P21.syncingRandomHotkeyCombo = true
                driftgod.Try(function() feature:SetList(driftgod.R289_HotkeyNames or {}) end)
                driftgod.Try(function() feature:SetListIndex(driftgod.S.randomVehicleHotkeyIndex or hotkeyIndexForCode(RANDOM_DEFAULT_KEY)) end)
                P21.syncingRandomHotkeyCombo = false
                P21.randomHotkeyComboConfigured = true
            end
        end
        return feature
    end

    -- Route every existing Random button path through the same deferred Prime-safe request.
    driftgod.R109_SpawnRandomSavedVehicle = function() return driftgod.P21_QueueRandomVehicle("Random button") end
    driftgod.R110_SpawnerRandomVehicle = function() return driftgod.P21_QueueRandomVehicle("Random button") end
    driftgod.R114_RandomSpawnerVehicle = function() return driftgod.P21_QueueRandomVehicle("Random button") end
    driftgod.R115_RandomSpawnerVehicle = function() return driftgod.P21_QueueRandomVehicle("Random button") end
    driftgod.R153_RandomVehicleSpawner = function() return driftgod.P21_QueueRandomVehicle("Random button") end
    driftgod.R154_RandomSpawner = function() return driftgod.P21_QueueRandomVehicle("Random button") end

    ensureRandomFeature()
    registerRandomHotkeyCombo()
    applyRandomHotkey()

    -- Reapply the random hotkey after manual settings reloads.
    if type(driftgod.LoadSettings) == "function" and P21.loadSettingsWrapped ~= true then
        P21.loadSettingsWrapped = true
        local PreviousLoadSettings = driftgod.LoadSettings
        driftgod.LoadSettings = function(...)
            local result = PreviousLoadSettings(...)
            loadSavedRandomHotkey()
            applyRandomHotkey()
            P21.randomHotkeyComboConfigured = false
            registerRandomHotkeyCombo()
            return result
        end
    end

    -- Add the saved Random hotkey dropdown to the same Garage HUD settings area.
    -- It uses the same Cherax Combo feature style and option list as Garage HUD Hotkey.
    if type(driftgod.R290_RenderSpawnerHudControls) == "function" and P21.settingsWrapped ~= true then
        P21.settingsWrapped = true
        local PreviousRenderSpawnerHudControls = driftgod.R290_RenderSpawnerHudControls

        local function uiText(text)
            if dgMiniText then
                local ok = driftgod.Try(dgMiniText, tostring(text or ""), "dim")
                if ok then return end
            end
            if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, tostring(text or "")) end
        end

        local function renderRandomHotkeyFeature()
            local feature = registerRandomHotkeyCombo()
            local hash = driftgod.H.RandomVehicleHotkeyCombo
            if not feature or not hash then return false end

            if dgMiniFeature then
                local ok = driftgod.Try(dgMiniFeature, hash, "Default Random Hotkey")
                if ok then return true end
            end
            if renderFeatureSafe then
                local ok = driftgod.Try(renderFeatureSafe, hash, "Default Random Hotkey")
                if ok then return true end
            end
            if ClickGUI and ClickGUI.RenderFeature then
                local ok = driftgod.Try(ClickGUI.RenderFeature, hash)
                if ok then return true end
            end
            return false
        end

        local function renderWithRandomHotkey(...)
            local result = PreviousRenderSpawnerHudControls(...)
            if isUnloading() then return result end

            uiText("Default: F9")
            if not renderRandomHotkeyFeature() then
                uiText("Default Random Hotkey dropdown unavailable")
            end
            uiText("Saved hotkey: " .. tostring(driftgod.S.randomVehicleHotkeyName or "F9"))
            return result
        end

        driftgod.R290_RenderSpawnerHudControls = renderWithRandomHotkey
        driftgod.R289_RenderSpawnerHudControls = renderWithRandomHotkey
        driftgod.R252_RenderSpawnerHudControls = renderWithRandomHotkey
        driftgod.R171_RenderSpawnerHudControls = renderWithRandomHotkey
        driftgod.R170_RenderSpawnerHudControls = renderWithRandomHotkey
        driftgod.R169_RenderSpawnerHudControls = renderWithRandomHotkey
        driftgod.R167_RenderSpawnerHudControls = renderWithRandomHotkey
        driftgod.R165_RenderSpawnerHudControls = renderWithRandomHotkey
        driftgod.R164_RenderSpawnerHudControls = renderWithRandomHotkey
    end

    if Script and Script.RegisterLooped and P21.workerInstalled ~= true then
        P21.workerInstalled = true
        Script.RegisterLooped(function()
            if isUnloading() then return false end

            local active = false
            local currentTime = nowMs()

            if P21.autoScanQueued == true and P21.scanInProgress ~= true and currentTime >= (tonumber(P21.autoScanAt or 0) or 0) then
                active = true
                driftgod.P21_RecursiveGarageScan(P21.pendingRandom and "random hotkey first-use" or "first Garage open")
            end

            if P21.pendingRandom == true and P21.scanInProgress ~= true then
                active = true
                if P21.autoScanAttempted ~= true then
                    if P21.autoScanQueued ~= true then
                        P21.autoScanQueued = true
                        P21.autoScanAt = currentTime + 80
                    end
                else
                    local reason = P21.pendingRandomReason
                    P21.pendingRandom = false
                    P21.pendingRandomReason = nil
                    spawnRandomNow(reason)
                end
            end

            if Script and Script.Yield then Script.Yield(active and 50 or 250) end
        end)
    end

    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_UNLOAD and P21.unloadHandlerInstalled ~= true then
        P21.unloadHandlerInstalled = true
        driftgod.Try(function()
            EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
                -- Do not call FeatureMgr, ClickGUI, ImGui, PTFX, or file APIs here.
                P21.unloading = true
                P21.autoScanQueued = false
                P21.pendingRandom = false
                P21.pendingRandomReason = nil
                P21.scanInProgress = false
                driftgod.S = driftgod.S or {}
                driftgod.S._primeP18PtfxPending = nil
                driftgod.S._primeP18PtfxPendingReason = nil
            end)
        end)
    end

    logMessage("first-open recursive Garage scan enabled | exact subfolder index mapping enabled | Random hotkey dropdown="
        .. tostring(driftgod.S.randomVehicleHotkeyName or "F9"))
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime drift tuning lab
-- note: session-only score simulation and five isolated runtime math methods.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}

    local LAB = driftgod.PrimeDriftTuningLab or {}
    driftgod.PrimeDriftTuningLab = LAB
    LAB.patch = "P22_Five_Method_Drift_Tuning_Lab"
    LAB.scoreOverrideEnabled = false
    LAB.scoreOverride = 0
    LAB.activeMethod = math.floor(tonumber(LAB.activeMethod or 0) or 0)
    LAB.editingMethod = math.floor(tonumber(LAB.editingMethod or 1) or 1)
    LAB.runtimeSnapshot = LAB.runtimeSnapshot or nil
    LAB.methods = LAB.methods or {}

    local METHOD_INFO = {
        {
            name = "Method 1 - Linear Additive",
            short = "Linear",
            desc = "Direct fixed increments. This is the clearest baseline for comparing each option."
        },
        {
            name = "Method 2 - Percentage Scaling",
            short = "Percent",
            desc = "Scales each selected base preset proportionally instead of adding fixed amounts."
        },
        {
            name = "Method 3 - Quadratic Curve",
            short = "Quadratic",
            desc = "Level 4 is gentler while level 5 becomes much stronger. Useful for testing progressive response."
        },
        {
            name = "Method 4 - Smooth Blend",
            short = "Smooth",
            desc = "Blends partway toward a linear target for softer, less abrupt tuning changes."
        },
        {
            name = "Method 5 - Hybrid Balanced",
            short = "Hybrid",
            desc = "Combines additive and percentage results for a balanced middle ground."
        },
    }

    local VALUE_ROWS = {
        { key = "drift", label = "Drift" },
        { key = "stability", label = "Stability" },
        { key = "counter", label = "Counter-Steering" },
        { key = "momentum", label = "Momentum" },
        { key = "acceleration", label = "Acceleration" },
        { key = "gravity", label = "Experimental Gravity" },
        { key = "experimentalAcceleration", label = "Experimental Acceleration" },
        { key = "traction", label = "Experimental Traction" },
        { key = "experimentalGrip", label = "Experimental Grip" },
    }

    local function clamp(value, minimum, maximum)
        value = tonumber(value or minimum) or minimum
        if value < minimum then return minimum end
        if value > maximum then return maximum end
        return value
    end

    local function copyTable(source)
        local out = {}
        for key, value in pairs(source or {}) do out[key] = value end
        return out
    end

    local function defaultMethodValues()
        return {
            drift = 3,
            stability = 3,
            counter = 3,
            momentum = 3,
            acceleration = 3,
            gravity = 3,
            experimentalAcceleration = 3,
            traction = 3,
            experimentalGrip = 3,
        }
    end

    local function normalizeMethodValues(index)
        index = math.floor(clamp(index, 1, 5))
        local values = LAB.methods[index]
        if type(values) ~= "table" then
            values = defaultMethodValues()
            LAB.methods[index] = values
        end
        for _, row in ipairs(VALUE_ROWS) do
            values[row.key] = math.floor(clamp(values[row.key] or 3, 1, 5))
        end
        return values
    end

    for index = 1, 5 do normalizeMethodValues(index) end

    local ISOLATED_STATE_KEYS = {
        "driftAssistEnabled",
        "driftTuningEnabled",
        "arcadePresetRuntimeEnabled",
        "stabilityAssistEnabled",
        "autoCounterSteerEnabled",
        "momentumAssistEnabled",
        "accelAssistEnabled",
        "experimentalGravityEnabled",
        "experimentalAccelEnabled",
        "experimentalTractionEnabled",
        "experimentalGripEnabled",
        "driftAssistPlusEnabled",
    }

    local function captureRuntimeState()
        if type(LAB.runtimeSnapshot) == "table" then return end
        LAB.runtimeSnapshot = {}
        for _, key in ipairs(ISOLATED_STATE_KEYS) do LAB.runtimeSnapshot[key] = driftgod.S[key] end
    end

    local function isolateNormalTuningWorkers()
        captureRuntimeState()
        driftgod.S.driftAssistEnabled = true
        driftgod.S.driftTuningEnabled = true
        driftgod.S.arcadePresetRuntimeEnabled = true
        driftgod.S.stabilityAssistEnabled = false
        driftgod.S.autoCounterSteerEnabled = false
        driftgod.S.momentumAssistEnabled = false
        driftgod.S.accelAssistEnabled = false
        driftgod.S.experimentalGravityEnabled = false
        driftgod.S.experimentalAccelEnabled = false
        driftgod.S.experimentalTractionEnabled = false
        driftgod.S.experimentalGripEnabled = false
        driftgod.S.driftAssistPlusEnabled = false
    end

    local function restoreRuntimeState()
        if type(LAB.runtimeSnapshot) ~= "table" then return end
        for _, key in ipairs(ISOLATED_STATE_KEYS) do driftgod.S[key] = LAB.runtimeSnapshot[key] end
        LAB.runtimeSnapshot = nil
    end

    function driftgod.P22_ActivateTuningLabMethod(index)
        index = math.floor(clamp(index, 1, 5))
        normalizeMethodValues(index)
        LAB.activeMethod = index
        LAB.editingMethod = index
        isolateNormalTuningWorkers()
        if driftgod.Toast then
            driftgod.Toast("Base Tuning active: " .. tostring(METHOD_INFO[index].short), 2000)
        end
        if driftgod.Log then
            driftgod.Log("[Base Tuning] active method=" .. tostring(index) .. " | " .. tostring(METHOD_INFO[index].name))
        end
        return true
    end

    function driftgod.P22_DisableTuningLab()
        LAB.activeMethod = 0
        restoreRuntimeState()
        if driftgod.Toast then driftgod.Toast("Base Tuning disabled. Standard tuning restored.", 2000) end
        return true
    end

    function driftgod.P22_ResetTuningLabMethod(index)
        index = math.floor(clamp(index, 1, 5))
        LAB.methods[index] = defaultMethodValues()
        if driftgod.Toast then driftgod.Toast("Base Tuning method " .. tostring(index) .. " reset to neutral 3.", 1600) end
        return true
    end

    local previousGetArcadeScore = driftgod.GetArcadeDriftPresetScore
    driftgod.GetArcadeDriftPresetScore = function(...)
        local realScore = 0
        if type(previousGetArcadeScore) == "function" then
            local ok, value = driftgod.Try(previousGetArcadeScore, ...)
            if ok and tonumber(value) then realScore = math.floor(tonumber(value) or 0) end
        end
        if LAB.scoreOverrideEnabled == true then return math.max(realScore, LAB.scoreOverride) end
        return realScore
    end

    local previousScoreForUnlock = driftgod.ScoreForUnlock
    if type(previousScoreForUnlock) == "function" then
        driftgod.ScoreForUnlock = function(...)
            local realScore = 0
            local ok, value = driftgod.Try(previousScoreForUnlock, ...)
            if ok and tonumber(value) then realScore = math.floor(tonumber(value) or 0) end
            if LAB.scoreOverrideEnabled == true then return math.max(realScore, LAB.scoreOverride) end
            return realScore
        end
    end

    local function signedPower(delta)
        delta = tonumber(delta or 0) or 0
        if delta == 0 then return 0 end
        local sign = delta < 0 and -1 or 1
        return sign * ((math.abs(delta) * math.abs(delta)) / 2.0)
    end

    local function deltas(values, transform)
        transform = transform or function(value) return value end
        local function one(key)
            local raw = (tonumber(values[key] or 3) or 3) - 3
            return transform(raw)
        end
        return {
            drift = one("drift"),
            stability = one("stability"),
            counter = one("counter"),
            momentum = one("momentum"),
            acceleration = one("acceleration"),
            gravity = one("gravity"),
            experimentalAcceleration = one("experimentalAcceleration"),
            traction = one("traction"),
            experimentalGrip = one("experimentalGrip"),
        }
    end

    local function applyLinear(base, values, transform)
        local d = deltas(values, transform)
        local q = copyTable(base)
        q.angle = clamp((tonumber(base.angle or 50.0) or 50.0)
            + d.drift * 4.0
            + d.experimentalGrip * 0.70
            - d.traction * 2.0,
            25.0, 92.0)
        q.grip_pad = clamp((tonumber(base.grip_pad or 8.0) or 8.0)
            + d.drift * 1.25
            + d.experimentalGrip * 2.0
            + d.traction * 1.25
            + d.gravity * 0.75
            - d.stability * 0.30,
            0.0, 30.0)
        q.assist = clamp((tonumber(base.assist or 80.0) or 80.0)
            + d.stability * 4.0
            + d.counter * 5.0,
            35.0, 100.0)
        q.intensity = clamp((tonumber(base.intensity or 30.0) or 30.0)
            + d.momentum * 3.0
            + d.experimentalAcceleration * 2.0
            - d.stability * 1.0,
            10.0, 72.0)
        q.base_force = clamp((tonumber(base.base_force or 0.015) or 0.015)
            * (1.0 + d.acceleration * 0.080 + d.experimentalAcceleration * 0.060 + d.momentum * 0.035),
            0.004, 0.050)
        q.min_speed = clamp((tonumber(base.min_speed or 12.0) or 12.0)
            - d.experimentalGrip * 0.75
            - d.gravity * 0.50
            + d.traction * 0.40,
            5.0, 38.0)
        q._r198ExtraVelocity = clamp(
            d.momentum * 0.0018 + d.experimentalAcceleration * 0.0018 + d.acceleration * 0.0012,
            -0.0040, 0.0080)
        q._r198Downforce = clamp(d.gravity * 0.010, -0.010, 0.030)
        return q
    end

    local function applyPercentage(base, values)
        local d = deltas(values)
        local q = copyTable(base)
        q.angle = clamp((tonumber(base.angle or 50.0) or 50.0)
            * (1.0 + d.drift * 0.055 + d.experimentalGrip * 0.010 - d.traction * 0.025),
            25.0, 92.0)
        q.grip_pad = clamp((tonumber(base.grip_pad or 8.0) or 8.0)
            * (1.0 + d.drift * 0.12 + d.experimentalGrip * 0.18 + d.traction * 0.10 + d.gravity * 0.06 - d.stability * 0.03),
            0.0, 30.0)
        q.assist = clamp((tonumber(base.assist or 80.0) or 80.0)
            * (1.0 + d.stability * 0.040 + d.counter * 0.050),
            35.0, 100.0)
        q.intensity = clamp((tonumber(base.intensity or 30.0) or 30.0)
            * (1.0 + d.momentum * 0.080 + d.experimentalAcceleration * 0.060 - d.stability * 0.025),
            10.0, 72.0)
        q.base_force = clamp((tonumber(base.base_force or 0.015) or 0.015)
            * (1.0 + d.acceleration * 0.100 + d.experimentalAcceleration * 0.075 + d.momentum * 0.045),
            0.004, 0.050)
        q.min_speed = clamp((tonumber(base.min_speed or 12.0) or 12.0)
            * (1.0 - d.experimentalGrip * 0.055 - d.gravity * 0.035 + d.traction * 0.030),
            5.0, 38.0)
        q._r198ExtraVelocity = clamp(
            d.momentum * 0.0020 + d.experimentalAcceleration * 0.0022 + d.acceleration * 0.0015,
            -0.0040, 0.0080)
        q._r198Downforce = clamp(d.gravity * 0.012, -0.010, 0.030)
        return q
    end

    local function blendPreset(base, target, amount)
        local q = copyTable(base)
        amount = clamp(amount, 0.0, 1.0)
        for _, key in ipairs({"angle", "grip_pad", "assist", "intensity", "base_force", "min_speed", "_r198ExtraVelocity", "_r198Downforce"}) do
            local a = tonumber(base[key] or 0.0) or 0.0
            local b = tonumber(target[key] or a) or a
            q[key] = a + ((b - a) * amount)
        end
        return q
    end

    local function hybridPreset(base, first, second)
        local q = copyTable(base)
        for _, key in ipairs({"angle", "grip_pad", "assist", "intensity", "base_force", "min_speed", "_r198ExtraVelocity", "_r198Downforce"}) do
            local a = tonumber(first[key] or base[key] or 0.0) or 0.0
            local b = tonumber(second[key] or base[key] or 0.0) or 0.0
            q[key] = (a * 0.55) + (b * 0.45)
        end
        return q
    end

    function driftgod.P22_GetLabTunedRuntimePreset(base)
        if type(base) ~= "table" then return base end
        local method = math.floor(tonumber(LAB.activeMethod or 0) or 0)
        if method < 1 or method > 5 then return nil end
        local values = normalizeMethodValues(method)
        local q
        if method == 1 then
            q = applyLinear(base, values)
        elseif method == 2 then
            q = applyPercentage(base, values)
        elseif method == 3 then
            q = applyLinear(base, values, signedPower)
        elseif method == 4 then
            q = blendPreset(base, applyLinear(base, values), 0.55)
        else
            q = hybridPreset(base, applyLinear(base, values), applyPercentage(base, values))
        end
        q._primeTuningLabMethod = method
        q._primeTuningLabName = METHOD_INFO[method].name
        return q
    end

    local previousRuntimeTuner = driftgod.R197_GetTunedRuntimePreset
    driftgod.R197_GetTunedRuntimePreset = function(base)
        local method = math.floor(tonumber(LAB.activeMethod or 0) or 0)
        if method >= 1 and method <= 5 then
            isolateNormalTuningWorkers()
            local tuned = driftgod.P22_GetLabTunedRuntimePreset(base)
            if tuned then return tuned end
        end
        if type(previousRuntimeTuner) == "function" then return previousRuntimeTuner(base) end
        return base
    end

    local function uiText(message, color)
        message = tostring(message or "")
        color = tostring(color or "white")
        if dgMiniText then
            local ok = driftgod.Try(dgMiniText, message, color)
            if ok then return end
        end
        if dgColorText then
            local ok = driftgod.Try(dgColorText, message, color)
            if ok then return end
        end
        if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, message) end
    end

    local function uiSameLine()
        if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end
    end

    local function uiButton(label, callback)
        local clicked = false
        if ImGui and ImGui.Button then
            driftgod.Try(function() clicked = ImGui.Button(tostring(label or "Button")) == true end)
        end
        if clicked and type(callback) == "function" then driftgod.Try(callback) end
        return clicked
    end

    local function beginChild(name)
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, opened = driftgod.Try(ClickGUI.BeginCustomChildWindow, tostring(name or "Drift Tuning Lab"))
            return ok and opened == true
        end
        uiText(name, "header")
        return true
    end

    local function endChild()
        if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
    end

    local function methodSummary(values)
        return "D" .. tostring(values.drift)
            .. "  S" .. tostring(values.stability)
            .. "  C" .. tostring(values.counter)
            .. "  M" .. tostring(values.momentum)
            .. "  A" .. tostring(values.acceleration)
            .. "  G" .. tostring(values.gravity)
            .. "  EA" .. tostring(values.experimentalAcceleration)
            .. "  T" .. tostring(values.traction)
            .. "  EG" .. tostring(values.experimentalGrip)
    end

    local function renderValueControls(methodIndex, values)
        local tableId = "DG_P22_MethodValues_" .. tostring(methodIndex)
        if ImGui and ImGui.BeginTable and ImGui.TableNextRow and ImGui.TableSetColumnIndex and ImGui.EndTable then
            local opened = false
            driftgod.Try(function() opened = ImGui.BeginTable(tableId, 4, 0) == true end)
            if opened then
                for _, row in ipairs(VALUE_ROWS) do
                    ImGui.TableNextRow()
                    ImGui.TableSetColumnIndex(0)
                    uiText(row.label, "white")
                    ImGui.TableSetColumnIndex(1)
                    uiButton("-##P22_" .. tostring(methodIndex) .. "_" .. row.key, function()
                        values[row.key] = math.floor(clamp((values[row.key] or 3) - 1, 1, 5))
                    end)
                    ImGui.TableSetColumnIndex(2)
                    local value = math.floor(clamp(values[row.key] or 3, 1, 5))
                    uiText(tostring(value) .. " / 5" .. (value == 3 and "  NEUTRAL" or ""), value == 3 and "dim" or "green")
                    ImGui.TableSetColumnIndex(3)
                    uiButton("+##P22_" .. tostring(methodIndex) .. "_" .. row.key, function()
                        values[row.key] = math.floor(clamp((values[row.key] or 3) + 1, 1, 5))
                    end)
                end
                ImGui.EndTable()
                return
            end
        end

        for _, row in ipairs(VALUE_ROWS) do
            uiText(row.label .. ": " .. tostring(values[row.key] or 3) .. " / 5", "white")
            uiSameLine()
            uiButton("-##P22_Fallback_" .. tostring(methodIndex) .. "_" .. row.key, function()
                values[row.key] = math.floor(clamp((values[row.key] or 3) - 1, 1, 5))
            end)
            uiSameLine()
            uiButton("+##P22_Fallback_" .. tostring(methodIndex) .. "_" .. row.key, function()
                values[row.key] = math.floor(clamp((values[row.key] or 3) + 1, 1, 5))
            end)
        end
    end

    function driftgod.P22_RenderTuningLab()
        if beginChild("Drift Tuning Lab - Test Unlock") then
            uiText("Session-only Best Run simulation", "header")
            uiText("Simulated Best Run: " .. tostring(LAB.scoreOverride) .. "+", "gold")
            uiText("This unlocks testing without modifying or resealing saved progress.", "dim")
            uiButton((LAB.scoreOverrideEnabled and "250K Test Unlock: ON" or "250K Test Unlock: OFF") .. "##P22ScoreOverride", function()
                LAB.scoreOverrideEnabled = not (LAB.scoreOverrideEnabled == true)
            end)
            if LAB.activeMethod > 0 then
                uiSameLine()
                uiButton("Disable Active Lab Method##P22DisableLab", driftgod.P22_DisableTuningLab)
                uiText("Active: " .. tostring(METHOD_INFO[LAB.activeMethod].name), "green")
                uiText("Normal tuning workers are isolated while this method is active.", "dim")
            else
                uiText("Active method: None. Normal Drift Tuning is controlling the vehicle.", "dim")
            end
            uiText("Testing rule: leave every option at 3, then change one option at a time.", "orange")
            endChild()
        end

        for methodIndex = 1, 5 do
            local info = METHOD_INFO[methodIndex]
            local values = normalizeMethodValues(methodIndex)
            if beginChild("Drift Tuning Lab " .. tostring(methodIndex) .. " - " .. tostring(info.short)) then
                local active = LAB.activeMethod == methodIndex
                uiText(info.name, active and "green" or "header")
                uiText(info.desc, "dim")
                uiText("Independent values: " .. methodSummary(values), "white")

                uiButton((active and "ACTIVE" or "Activate Method " .. tostring(methodIndex)) .. "##P22Activate_" .. tostring(methodIndex), function()
                    driftgod.P22_ActivateTuningLabMethod(methodIndex)
                end)
                uiSameLine()
                uiButton((LAB.editingMethod == methodIndex and "Hide Controls" or "Edit Controls") .. "##P22Edit_" .. tostring(methodIndex), function()
                    LAB.editingMethod = (LAB.editingMethod == methodIndex) and 0 or methodIndex
                end)
                uiSameLine()
                uiButton("Reset Method##P22Reset_" .. tostring(methodIndex), function()
                    driftgod.P22_ResetTuningLabMethod(methodIndex)
                end)

                if LAB.editingMethod == methodIndex then
                    uiText("1-2 decrease | 3 neutral | 4-5 increase", "orange")
                    renderValueControls(methodIndex, values)
                else
                    uiText("Controls hidden to keep the Drift tab lightweight.", "dim")
                end
                endChild()
            end
        end
    end

    local previousRenderDriftMinimal = renderDriftMinimal
    renderDriftMinimal = function(...)
        -- Preserve the established production order, but place the five lab sections
        -- immediately after Drift Tuning and before Preset Creation.
        if driftgod.R245RefreshTuningSliderCaps then driftgod.Try(driftgod.R245RefreshTuningSliderCaps, false) end

        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Drift Presets") then
            if driftgod.R247_RenderPresetColumns then driftgod.R247_RenderPresetColumns("DG_R247_DriftPresetColumns") end
            if ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
        elseif driftgod.R247_RenderPresetColumns then
            driftgod.R247_RenderPresetColumns("DG_R247_DriftPresetColumns")
        end

        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Drift Tuning") then
            if driftgod.R247_RenderTuningGrid then driftgod.R247_RenderTuningGrid() end
            if ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
        elseif driftgod.R247_RenderTuningGrid then
            driftgod.R247_RenderTuningGrid()
        end

        driftgod.P22_RenderTuningLab()

        if driftgod.R224_RenderPresetCreation then driftgod.R224_RenderPresetCreation()
        elseif driftgod.R214_RenderPresetCreation then driftgod.R214_RenderPresetCreation()
        elseif type(previousRenderDriftMinimal) == "function" then previousRenderDriftMinimal(...) end
    end

    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_UNLOAD and LAB.unloadHandlerInstalled ~= true then
        LAB.unloadHandlerInstalled = true
        driftgod.Try(function()
            EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
                LAB.activeMethod = 0
                LAB.runtimeSnapshot = nil
            end)
        end)
    end

    if driftgod.Log then
        driftgod.Log("[Base Tuning] loaded | methods=5 | saved per Base Preset | real progression required")
    end
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime drift tuning lab visibility hook
-- note: inserts the lab through the confirmed Preset Creation render path.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod

    local LAB = driftgod.PrimeDriftTuningLab
    local rawLabRenderer = driftgod.P22_RenderTuningLab
    local oldPresetCreation = driftgod.R224_RenderPresetCreation or driftgod.R214_RenderPresetCreation

    if type(LAB) ~= "table" or type(rawLabRenderer) ~= "function" then
        if driftgod.Log then
            driftgod.Log("[Base Tuning] visibility hook unavailable | lab renderer missing")
        end
        return
    end

    if LAB.p23VisibilityHookInstalled == true then return end
    LAB.p23VisibilityHookInstalled = true
    LAB._p23RenderedInCurrentDriftPass = false

    -- The earlier Drift renderer may already call the lab. This gate prevents duplicate
    -- rendering when the confirmed Preset Creation path also inserts it.
    driftgod.P22_RenderTuningLab = function(...)
        if LAB._p23RenderedInCurrentDriftPass == true then return true end
        LAB._p23RenderedInCurrentDriftPass = true
        return rawLabRenderer(...)
    end

    local function renderPresetCreationAfterLab(...)
        -- This is the exact path already visible directly beneath Drift Tuning.
        -- Rendering the lab here guarantees it appears immediately before Preset Creation.
        driftgod.P22_RenderTuningLab()

        local ok, a, b, c, d
        if type(oldPresetCreation) == "function" then
            ok, a, b, c, d = driftgod.Try(oldPresetCreation, ...)
        else
            ok = true
        end

        LAB._p23RenderedInCurrentDriftPass = false

        if not ok then
            if driftgod.Log then
                driftgod.Log("[Base Tuning] Preset Creation renderer failed after lab insertion | " .. tostring(a))
            end
            return false
        end
        return a, b, c, d
    end

    driftgod.R224_RenderPresetCreation = renderPresetCreationAfterLab
    driftgod.R214_RenderPresetCreation = renderPresetCreationAfterLab
    driftgod.R213_RenderPresetCreation = renderPresetCreationAfterLab
    driftgod.R212_RenderPresetCreation = renderPresetCreationAfterLab
    driftgod.R211_RenderPresetCreation = renderPresetCreationAfterLab
    driftgod.R210_RenderPresetCreation = renderPresetCreationAfterLab
    driftgod.R209_RenderPresetCreation = renderPresetCreationAfterLab
    driftgod.R206_RenderPresetCreation = renderPresetCreationAfterLab
    driftgod.R205_RenderPresetCreation = renderPresetCreationAfterLab
    driftgod.R110_RenderPresetCreation = renderPresetCreationAfterLab
    driftgod.R109_RenderPresetCreation = renderPresetCreationAfterLab

    if driftgod.Log then
        driftgod.Log("[Base Tuning] visibility hook installed | position=before Preset Creation | methods=5")
    end
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime drift tuning lab runtime bridge
-- note: feeds the active lab method into the final UniversalDrifting runtime.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}

    local LAB = driftgod.PrimeDriftTuningLab
    if type(LAB) ~= "table"
        or type(driftgod.P22_GetLabTunedRuntimePreset) ~= "function"
        or type(driftgod.ApplyArcadeDriftPresetRuntime) ~= "function"
        or type(driftgod.GetArcadeDriftPresetById) ~= "function" then
        if driftgod.Log then
            driftgod.Log("[Base Tuning] runtime bridge unavailable | required runtime functions missing")
        end
        return
    end

    if LAB.p24RuntimeBridgeInstalled == true then return end
    LAB.p24RuntimeBridgeInstalled = true
    LAB.runtimeBridgeActive = true
    LAB.lastAppliedPreset = LAB.lastAppliedPreset or nil
    LAB.lastAppliedMs = tonumber(LAB.lastAppliedMs or 0) or 0
    LAB.lastAppliedLogMs = tonumber(LAB.lastAppliedLogMs or 0) or 0

    local finalUniversalRuntime = driftgod.ApplyArcadeDriftPresetRuntime
    local canonicalPresetGetter = driftgod.GetArcadeDriftPresetById

    local function nowMs()
        if driftgod.Now then
            local ok, value = driftgod.Try(driftgod.Now)
            if ok and tonumber(value) then return tonumber(value) end
        end
        return math.floor((os.clock() or 0) * 1000)
    end

    local function clonePreset(source)
        local out = {}
        for key, value in pairs(source or {}) do out[key] = value end
        return out
    end

    local function formatApplied(preset)
        if type(preset) ~= "table" then return "No tuned runtime values applied yet." end
        return string.format(
            "angle=%.1f | pad=%.1f | assist=%.1f | intensity=%.1f | force=%.4f | minSpeed=%.1f",
            tonumber(preset.angle or 0.0) or 0.0,
            tonumber(preset.grip_pad or 0.0) or 0.0,
            tonumber(preset.assist or 0.0) or 0.0,
            tonumber(preset.intensity or 0.0) or 0.0,
            tonumber(preset.base_force or 0.0) or 0.0,
            tonumber(preset.min_speed or 0.0) or 0.0
        )
    end

    driftgod.ApplyArcadeDriftPresetRuntime = function(veh, kmh, driftAngle, held)
        local method = math.floor(tonumber(LAB.activeMethod or 0) or 0)
        if method < 1 or method > 5 then
            return finalUniversalRuntime(veh, kmh, driftAngle, held)
        end

        local activePresetId = tostring(driftgod.S.activeArcadeDriftPreset or "")
        local originalGetter = driftgod.GetArcadeDriftPresetById
        local previousCounterState = driftgod.S.autoCounterSteerEnabled
        local appliedPreset = nil

        -- Separate counter-steer workers remain disabled by the lab, but the final
        -- UniversalDrifting runtime needs this gate enabled while it consumes the
        -- lab-computed assist value.
        driftgod.S.autoCounterSteerEnabled = true

        driftgod.GetArcadeDriftPresetById = function(id)
            local base = canonicalPresetGetter(id)
            if type(base) ~= "table" then return base end
            if activePresetId ~= "" and tostring(id or "") ~= activePresetId then return base end

            local tuned = driftgod.P22_GetLabTunedRuntimePreset(base)
            if type(tuned) == "table" then
                appliedPreset = clonePreset(tuned)
                return tuned
            end
            return base
        end

        local ok, a, b, c, d = driftgod.Try(finalUniversalRuntime, veh, kmh, driftAngle, held)

        driftgod.GetArcadeDriftPresetById = originalGetter
        driftgod.S.autoCounterSteerEnabled = previousCounterState

        if type(appliedPreset) == "table" then
            LAB.lastAppliedPreset = appliedPreset
            LAB.lastAppliedMethod = method
            LAB.lastAppliedMs = nowMs()

            if LAB.lastAppliedMs - (LAB.lastAppliedLogMs or 0) >= 1500 then
                LAB.lastAppliedLogMs = LAB.lastAppliedMs
                if driftgod.Log then
                    driftgod.Log("[Base Tuning] APPLIED method=" .. tostring(method)
                        .. " | " .. formatApplied(appliedPreset))
                end
            end
        end

        if not ok then
            if driftgod.Log then
                driftgod.Log("[Base Tuning] UniversalDrifting runtime bridge failed safely | " .. tostring(a))
            end
            return nil
        end
        return a, b, c, d
    end

    local previousLabRenderer = driftgod.P22_RenderTuningLab
    if type(previousLabRenderer) == "function" then
        driftgod.P22_RenderTuningLab = function(...)
            local shouldRenderStatus = LAB._p23RenderedInCurrentDriftPass ~= true
            local a, b, c, d = previousLabRenderer(...)

            if shouldRenderStatus and ClickGUI and ClickGUI.BeginCustomChildWindow then
                local opened = false
                driftgod.Try(function()
                    opened = ClickGUI.BeginCustomChildWindow("Drift Tuning Lab - Runtime Verification") == true
                end)
                if opened then
                    local activeMethod = math.floor(tonumber(LAB.activeMethod or 0) or 0)
                    local age = nowMs() - (tonumber(LAB.lastAppliedMs or 0) or 0)
                    local activeText = activeMethod > 0
                        and ("Runtime bridge: ACTIVE | Method " .. tostring(activeMethod))
                        or "Runtime bridge: READY | No method active"

                    if dgMiniText then
                        driftgod.Try(dgMiniText, activeText, activeMethod > 0 and "green" or "dim")
                        if activeMethod > 0 and type(LAB.lastAppliedPreset) == "table" and age < 4000 then
                            driftgod.Try(dgMiniText, "Applied to UniversalDrifting: " .. formatApplied(LAB.lastAppliedPreset), "gold")
                        elseif activeMethod > 0 then
                            driftgod.Try(dgMiniText, "Waiting for the vehicle drift runtime to tick...", "orange")
                        end
                    elseif ImGui and ImGui.Text then
                        driftgod.Try(ImGui.Text, activeText)
                        if activeMethod > 0 and type(LAB.lastAppliedPreset) == "table" and age < 4000 then
                            driftgod.Try(ImGui.Text, "Applied: " .. formatApplied(LAB.lastAppliedPreset))
                        elseif activeMethod > 0 then
                            driftgod.Try(ImGui.Text, "Waiting for the vehicle drift runtime to tick...")
                        end
                    end

                    if ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
                end
            end

            return a, b, c, d
        end
    end

    if driftgod.Log then
        driftgod.Log("[Base Tuning] runtime bridge installed | target=final UniversalDrifting runtime | live verification enabled")
    end
end)


-- ═══════════════════════════════════════════════════════════════════════════════════
-- prime base tuning profiles
-- note: binds one selected math method and its values to each base preset.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.DefaultSettings = driftgod.DefaultSettings or {}

    local LAB = driftgod.PrimeDriftTuningLab or {}
    driftgod.PrimeDriftTuningLab = LAB
    local P25 = driftgod.PrimeBaseTuning or {}
    driftgod.PrimeBaseTuning = P25

    P25.patch = "P27_Base_Tuning_Direct_Combo"
    P25.methodNames = { "Standard", "Linear", "Percent", "Quadratic", "Smooth", "Hybrid" }
    driftgod.H.BaseTuningCombo = driftgod.H.BaseTuningCombo
        or (driftgod.Hash and driftgod.Hash("BaseTuningCombo") or Utils.Joaat("BaseTuningCombo"))
    P25.syncingCombo = false
    P25.currentBase = tostring(P25.currentBase or "")
    P25.applying = false
    P25.dirty = false
    P25.saveAt = tonumber(P25.saveAt or 0) or 0
    P25.lastSignature = tostring(P25.lastSignature or "")
    P25.lastValues = type(P25.lastValues) == "table" and P25.lastValues or nil

    local function clamp(value, minimum, maximum)
        value = tonumber(value or minimum) or minimum
        if value < minimum then return minimum end
        if value > maximum then return maximum end
        return value
    end

    local function copyTable(source)
        local out = {}
        for key, value in pairs(source or {}) do out[key] = value end
        return out
    end

    local function nowMs()
        if driftgod.Now then
            local ok, value = driftgod.Try(driftgod.Now)
            if ok and tonumber(value) then return tonumber(value) end
        end
        if Time and Time.GetEpocheMs then
            local ok, value = driftgod.Try(Time.GetEpocheMs)
            if ok and tonumber(value) then return tonumber(value) end
        end
        return math.floor((os.clock() or 0) * 1000)
    end

    local function currentBaseId()
        local id = tostring(driftgod.S.r195BaseTuningPreset
            or driftgod.S.r198BaseTuningPreset
            or driftgod.S.activeArcadeDriftPreset
            or "")
        if id == "" or id == "Default Drifting" then return "__RESET__" end
        return id
    end

    local function neutralValues()
        return {
            drift = 3,
            stability = 3,
            counter = 3,
            momentum = 3,
            acceleration = 3,
            gravity = 3,
            experimentalAcceleration = 3,
            traction = 3,
            experimentalGrip = 3,
        }
    end

    local function captureValues()
        return {
            drift = math.floor(clamp(driftgod.S.driftGripLevel or 3, 1, 5)),
            stability = math.floor(clamp(driftgod.S.driftStabilityLevel or driftgod.S.stabilityLevel or 3, 1, 5)),
            counter = math.floor(clamp(driftgod.S.autoCounterSteerLevel or driftgod.S.counterSteerLevel or 3, 1, 5)),
            momentum = math.floor(clamp(driftgod.S.momentumStrength or driftgod.S.momentumLevel or 3, 1, 5)),
            acceleration = math.floor(clamp(driftgod.S.accelStrength or driftgod.S.accelerationLevel or 3, 1, 5)),
            gravity = math.floor(clamp(driftgod.S.experimentalGravityStrength or driftgod.S.gravityLevel or 3, 1, 5)),
            experimentalAcceleration = math.floor(clamp(driftgod.S.experimentalAccelStrength or driftgod.S.experimentalAccelLevel or 3, 1, 5)),
            traction = math.floor(clamp(driftgod.S.experimentalTractionLevel or driftgod.S.tractionLevel or 3, 1, 5)),
            experimentalGrip = math.floor(clamp(driftgod.S.experimentalGripLevel or driftgod.S.gripLevel or 3, 1, 5)),
        }
    end

    local function valuesSignature(values)
        values = values or captureValues()
        return table.concat({
            tostring(values.drift or 3),
            tostring(values.stability or 3),
            tostring(values.counter or 3),
            tostring(values.momentum or 3),
            tostring(values.acceleration or 3),
            tostring(values.gravity or 3),
            tostring(values.experimentalAcceleration or 3),
            tostring(values.traction or 3),
            tostring(values.experimentalGrip or 3),
        }, ":")
    end

    local function setFeatureInt(hash, value)
        if not hash or not FeatureMgr or not FeatureMgr.GetFeature then return end
        driftgod.Try(function()
            local feature = FeatureMgr.GetFeature(hash)
            if feature and feature.SetIntValue then feature:SetIntValue(value) end
        end)
    end

    local function applyValues(values)
        values = type(values) == "table" and values or neutralValues()
        P25.applying = true

        local drift = math.floor(clamp(values.drift or 3, 1, 5))
        local stability = math.floor(clamp(values.stability or 3, 1, 5))
        local counter = math.floor(clamp(values.counter or 3, 1, 5))
        local momentum = math.floor(clamp(values.momentum or 3, 1, 5))
        local acceleration = math.floor(clamp(values.acceleration or 3, 1, 5))
        local gravity = math.floor(clamp(values.gravity or 3, 1, 5))
        local experimentalAcceleration = math.floor(clamp(values.experimentalAcceleration or 3, 1, 5))
        local traction = math.floor(clamp(values.traction or 3, 1, 5))
        local experimentalGrip = math.floor(clamp(values.experimentalGrip or 3, 1, 5))

        driftgod.S.driftGripLevel = drift
        driftgod.S.driftStabilityLevel = stability
        driftgod.S.stabilityLevel = stability
        driftgod.S.stability = stability
        driftgod.S.driftStability = stability
        driftgod.S.autoCounterSteerLevel = counter
        driftgod.S.counterSteerLevel = counter
        driftgod.S.autoCounterSteer = counter
        driftgod.S.driftCounterSteer = counter
        driftgod.S.momentumStrength = momentum
        driftgod.S.momentumLevel = momentum
        driftgod.S.momentum = momentum
        driftgod.S.driftMomentum = momentum
        driftgod.S.accelStrength = acceleration
        driftgod.S.accelerationLevel = acceleration
        driftgod.S.acceleration = acceleration
        driftgod.S.driftAcceleration = acceleration
        driftgod.S.experimentalGravityStrength = gravity
        driftgod.S.gravityLevel = gravity
        driftgod.S.experimentalAccelStrength = experimentalAcceleration
        driftgod.S.experimentalAccelLevel = experimentalAcceleration
        driftgod.S.experimentalTractionLevel = traction
        driftgod.S.tractionLevel = traction
        driftgod.S.experimentalGripLevel = experimentalGrip
        driftgod.S.gripLevel = experimentalGrip

        if driftgod.H then
            setFeatureInt(driftgod.H.R123_DriftSlider, drift)
            setFeatureInt(driftgod.H.R123_StabilitySlider, stability)
            setFeatureInt(driftgod.H.R123_CounterSlider, counter)
            setFeatureInt(driftgod.H.R123_MomentumSlider, momentum)
            setFeatureInt(driftgod.H.R123_AccelSlider, acceleration)
            setFeatureInt(driftgod.H.R123_GravitySlider, gravity)
            setFeatureInt(driftgod.H.R123_ExpAccelSlider, experimentalAcceleration)
            setFeatureInt(driftgod.H.R123_TractionSlider, traction)
            setFeatureInt(driftgod.H.R123_GripSlider, experimentalGrip)
        end

        P25.lastValues = captureValues()
        P25.lastSignature = valuesSignature(P25.lastValues)
        P25.applying = false
    end

    local function profiles()
        if type(driftgod.S.baseTuningProfiles) ~= "table" then driftgod.S.baseTuningProfiles = {} end
        return driftgod.S.baseTuningProfiles
    end

    local function ensureProfile(baseId, seedFromCurrent)
        baseId = tostring(baseId or currentBaseId())
        local all = profiles()
        local profile = all[baseId]
        if type(profile) ~= "table" then
            profile = {
                selectedMethod = 0,
                standardValues = seedFromCurrent == false and neutralValues() or captureValues(),
                methods = {},
            }
            all[baseId] = profile
        end
        if type(profile.methods) ~= "table" then profile.methods = {} end
        profile.selectedMethod = math.floor(clamp(profile.selectedMethod or 0, 0, 5))
        if type(profile.standardValues) ~= "table" then profile.standardValues = captureValues() end
        return profile
    end

    local function selectedSlot(profile, method, create)
        method = math.floor(clamp(method or 0, 0, 5))
        if method == 0 then
            if type(profile.standardValues) ~= "table" and create ~= false then profile.standardValues = captureValues() end
            return profile.standardValues
        end
        local key = tostring(method)
        if type(profile.methods[key]) ~= "table" and create ~= false then profile.methods[key] = neutralValues() end
        return profile.methods[key]
    end

    local function markDirty()
        P25.dirty = true
        P25.saveAt = nowMs() + 650
        driftgod.S.productionDirtySettings = true
    end

    local function saveCurrentSlot(baseId, valuesOverride)
        local profile = ensureProfile(baseId, true)
        local method = math.floor(clamp(profile.selectedMethod or driftgod.S.baseTuningSelectedMethod or 0, 0, 5))
        local values = type(valuesOverride) == "table" and copyTable(valuesOverride) or captureValues()
        if method == 0 then profile.standardValues = copyTable(values)
        else profile.methods[tostring(method)] = copyTable(values) end
        if method >= 1 and method <= 5 then LAB.methods[method] = copyTable(values) end
        markDirty()
        return profile
    end

    local function applyMethod(method, values)
        method = math.floor(clamp(method or 0, 0, 5))
        driftgod.S.baseTuningSelectedMethod = method
        if method == 0 then
            if driftgod.P22_DisableTuningLab then driftgod.Try(driftgod.P22_DisableTuningLab) else LAB.activeMethod = 0 end
            applyValues(values)
            return
        end
        applyValues(values)
        LAB.methods[method] = copyTable(values)
        if driftgod.P22_ActivateTuningLabMethod then
            driftgod.Try(driftgod.P22_ActivateTuningLabMethod, method)
        else
            LAB.activeMethod = method
        end
    end

    local syncBaseTuningComboIndex
    local registerBaseTuningCombo

    local function loadProfile(baseId)
        local profile = ensureProfile(baseId, true)
        local method = math.floor(clamp(profile.selectedMethod or 0, 0, 5))
        local values = selectedSlot(profile, method, true)
        applyMethod(method, values)
        P25.currentBase = tostring(baseId)
        P25.lastValues = captureValues()
        P25.lastSignature = valuesSignature(P25.lastValues)
        syncBaseTuningComboIndex(method)
        return profile
    end

    function driftgod.P25_SelectBaseTuningMethod(method)
        method = math.floor(clamp(method or 0, 0, 5))
        local baseId = currentBaseId()
        local profile = saveCurrentSlot(baseId)
        profile.selectedMethod = method
        local values = selectedSlot(profile, method, true)
        applyMethod(method, values)
        syncBaseTuningComboIndex(method)
        markDirty()
        return true
    end

    syncBaseTuningComboIndex = function(index)
        local feature = P25.baseTuningComboFeature
        if not feature then return end
        index = math.floor(clamp(index or 0, 0, 5))
        P25.syncingCombo = true
        if P25.comboConfigured ~= true then
            driftgod.Try(function() feature:SetList(P25.methodNames) end)
            P25.comboConfigured = true
        end
        if tonumber(P25.comboIndex) ~= index then
            driftgod.Try(function() feature:SetListIndex(index) end)
            P25.comboIndex = index
        end
        P25.syncingCombo = false
    end

    registerBaseTuningCombo = function()
        local hash = driftgod.H.BaseTuningCombo
        local feature = P25.baseTuningComboFeature

        if not feature and hash and FeatureMgr and FeatureMgr.GetFeature then
            driftgod.Try(function() feature = FeatureMgr.GetFeature(hash) end)
        end

        if not feature and hash and FeatureMgr and FeatureMgr.AddFeature and eFeatureType and eFeatureType.Combo then
            local ok, created = driftgod.Try(function()
                return FeatureMgr.AddFeature(
                    hash,
                    "Base Tuning",
                    eFeatureType.Combo,
                    "Saved per Base Preset.",
                    function(f)
                        if P25.syncingCombo == true then return end
                        local index = 0
                        driftgod.Try(function() index = f:GetListIndex() end)
                        driftgod.P25_SelectBaseTuningMethod(index)
                    end,
                    true
                )
            end)
            if ok then feature = created end
        end

        if feature then
            P25.baseTuningComboFeature = feature
            local baseId = currentBaseId()
            local profile = ensureProfile(baseId, true)
            local selected = math.floor(clamp(profile.selectedMethod or driftgod.S.baseTuningSelectedMethod or 0, 0, 5))
            syncBaseTuningComboIndex(selected)
        end

        return feature
    end

    function driftgod.P25_RenderBaseTuningCombo()
        local baseId = currentBaseId()
        local profile = ensureProfile(baseId, true)
        local selected = math.floor(clamp(profile.selectedMethod or driftgod.S.baseTuningSelectedMethod or 0, 0, 5))
        local preview = tostring(P25.methodNames[selected + 1] or "Standard")
        local feature = registerBaseTuningCombo()
        local hash = driftgod.H.BaseTuningCombo

        -- Prime-safe primary path: render a real Cherax Combo feature, exactly like
        -- Garage HUD Hotkey. This avoids depending on raw ImGui BeginCombo support.
        if feature and hash and ClickGUI and ClickGUI.RenderFeature then
            local ok = driftgod.Try(ClickGUI.RenderFeature, hash)
            if ok then return true end
        end
        if feature and hash and renderFeatureSafe then
            local ok = driftgod.Try(renderFeatureSafe, hash, "Base Tuning")
            if ok then return true end
        end
        if feature and hash and dgMiniFeature then
            local ok = driftgod.Try(dgMiniFeature, hash, "Base Tuning")
            if ok then return true end
        end

        -- Last-resort visual fallback for unusual builds.
        if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
            local opened = false
            driftgod.Try(function() opened = ImGui.BeginCombo("Base Tuning##P27BaseTuning", preview) == true end)
            if opened then
                for index = 0, 5 do
                    local clicked = false
                    local name = tostring(P25.methodNames[index + 1] or index)
                    driftgod.Try(function()
                        clicked = ImGui.Selectable(name .. "##P27BaseTuning_" .. tostring(index), index == selected) == true
                    end)
                    if clicked then
                        driftgod.P25_SelectBaseTuningMethod(index)
                        selected = index
                    end
                end
                driftgod.Try(ImGui.EndCombo)
            end
            return true
        end

        if dgMiniText then driftgod.Try(dgMiniText, "Base Tuning: " .. preview, "purple")
        elseif ImGui and ImGui.Text then driftgod.Try(ImGui.Text, "Base Tuning: " .. preview) end
        return false
    end

    -- Persist nested profiles even though this patch loads after the original settings pass.
    local stored = nil
    if driftgod.LoadTable and driftgod.SettingsFile then
        local ok, value = driftgod.Try(driftgod.LoadTable, driftgod.SettingsFile)
        if ok and type(value) == "table" then stored = value end
    end
    if type(stored) == "table" then
        if type(stored.baseTuningProfiles) == "table" then driftgod.S.baseTuningProfiles = stored.baseTuningProfiles end
        if stored.baseTuningSelectedMethod ~= nil then
            driftgod.S.baseTuningSelectedMethod = math.floor(clamp(stored.baseTuningSelectedMethod, 0, 5))
        end
    end

    driftgod.DefaultSettings.baseTuningProfiles = driftgod.DefaultSettings.baseTuningProfiles or {}
    driftgod.DefaultSettings.baseTuningSelectedMethod = driftgod.DefaultSettings.baseTuningSelectedMethod or 0

    if type(driftgod.ExportSettings) == "function" and P25.exportWrapped ~= true then
        P25.exportWrapped = true
        local oldExport = driftgod.ExportSettings
        driftgod.ExportSettings = function(...)
            local data = oldExport(...) or {}
            data.baseTuningProfiles = driftgod.S.baseTuningProfiles or {}
            data.baseTuningSelectedMethod = math.floor(clamp(driftgod.S.baseTuningSelectedMethod or 0, 0, 5))
            return data
        end
    end

    if type(driftgod.ApplySettings) == "function" and P25.applyWrapped ~= true then
        P25.applyWrapped = true
        local oldApply = driftgod.ApplySettings
        driftgod.ApplySettings = function(data, ...)
            local result = oldApply(data, ...)
            if type(data) == "table" then
                if type(data.baseTuningProfiles) == "table" then driftgod.S.baseTuningProfiles = data.baseTuningProfiles end
                if data.baseTuningSelectedMethod ~= nil then
                    driftgod.S.baseTuningSelectedMethod = math.floor(clamp(data.baseTuningSelectedMethod, 0, 5))
                end
            end
            return result
        end
    end

    -- Replace the five large lab panels with the compact Base Tuning dropdown.
    P25.previousLabRenderer = P25.previousLabRenderer or driftgod.P22_RenderTuningLab
    driftgod.P22_RenderTuningLab = function() return true end

    registerBaseTuningCombo()
    P25.currentBase = currentBaseId()
    loadProfile(P25.currentBase)

    if Script and Script.RegisterLooped and P25.workerInstalled ~= true then
        P25.workerInstalled = true
        Script.RegisterLooped(function()
            if ShouldUnload and ShouldUnload() then return false end

            local baseId = currentBaseId()
            if baseId ~= tostring(P25.currentBase or "") then
                if tostring(P25.currentBase or "") ~= "" then saveCurrentSlot(P25.currentBase, P25.lastValues) end
                loadProfile(baseId)
            elseif P25.applying ~= true then
                local profile = ensureProfile(baseId, true)
                local method = math.floor(clamp(profile.selectedMethod or 0, 0, 5))
                local values = captureValues()
                local signature = valuesSignature(values)
                if signature ~= tostring(P25.lastSignature or "") then
                    P25.lastValues = copyTable(values)
                    P25.lastSignature = signature
                    if method == 0 then profile.standardValues = copyTable(values)
                    else
                        profile.methods[tostring(method)] = copyTable(values)
                        LAB.methods[method] = copyTable(values)
                    end
                    markDirty()
                end

                if method >= 1 and method <= 5 then
                    LAB.activeMethod = method
                    LAB.methods[method] = copyTable(selectedSlot(profile, method, true))
                elseif LAB.activeMethod ~= 0 and driftgod.P22_DisableTuningLab then
                    driftgod.Try(driftgod.P22_DisableTuningLab)
                end
            end

            if P25.dirty == true and nowMs() >= (tonumber(P25.saveAt or 0) or 0) then
                P25.dirty = false
                if driftgod.SaveSettings then driftgod.Try(driftgod.SaveSettings, false) end
            end

            if Script and Script.Yield then Script.Yield(150) end
        end)
    end

    if driftgod.Log then
        driftgod.Log("[Base Tuning] dropdown loaded | profiles saved per Base Preset | methods=Standard,Linear,Percent,Quadratic,Smooth,Hybrid")
    end
end)

