-- prime garage phone suppression
-- note: blocks and closes the GTA phone while the Garage HUD is active.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.VS = driftgod.VS or {}

    if type(driftgod.VS_BlockControls) ~= "function" or driftgod.VS._p25PhoneBlockInstalled == true then return end
    driftgod.VS._p25PhoneBlockInstalled = true

    local previousBlockControls = driftgod.VS_BlockControls
    local phoneControls = {
        27,
        172, 173, 174, 175, 176, 177, 178, 179,
        180, 181, 182, 183, 184, 185, 186,
        199, 200, 201, 202,
    }

    driftgod.VS_BlockControls = function(...)
        local ok, result = driftgod.Try(previousBlockControls, ...)
        if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.open == true) then
            if ok then return result end
            return nil
        end

        for padIndex = 0, 2 do
            for _, control in ipairs(phoneControls) do
                driftgod.Try(function()
                    Natives.InvokeVoid(0xFE99B66D079CF6BC, padIndex, control, true)
                end)
            end
            for control = 172, 177 do
                driftgod.Try(function()
                    Natives.InvokeVoid(0xEDE476E5EE29EDB1, padIndex, control)
                end)
            end
        end

        -- If the phone was already beginning to open, close it immediately.
        if MOBILE and MOBILE.DESTROY_MOBILE_PHONE then
            driftgod.Try(MOBILE.DESTROY_MOBILE_PHONE)
        else
            driftgod.Try(function() Natives.InvokeVoid(0x3BC861DF703E5097) end)
        end

        if ok then return result end
        return nil
    end

    if driftgod.Log then driftgod.Log("[Garage HUD] phone input suppression enabled") end
end)

