-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.2 acceleration and tuning activation
-- note: strengthens slower-car drift acceleration and enables tuning on profile selection.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.H = driftgod.H or {}

    local P28 = driftgod.PrimeAccelerationUpdate or {}
    driftgod.PrimeAccelerationUpdate = P28
    if P28.installed == true then return end
    P28.installed = true

    local function clamp(value, minimum, maximum)
        value = tonumber(value or minimum) or minimum
        if value < minimum then return minimum end
        if value > maximum then return maximum end
        return value
    end

    local function nowMs()
        if driftgod.Now then
            local ok, value = driftgod.Try(driftgod.Now)
            if ok and tonumber(value) then return tonumber(value) end
        end
        return math.floor((os.clock() or 0) * 1000)
    end

    local function getFeature(hash)
        if not hash or not FeatureMgr or not FeatureMgr.GetFeature then return nil end
        local feature = nil
        driftgod.Try(function() feature = FeatureMgr.GetFeature(hash) end)
        return feature
    end

    function driftgod.P28_EnableTuningForBaseSelection(reason)
        driftgod.S.driftTuningEnabled = true
        local feature = getFeature(driftgod.H.DriftTuningMaster)
        if feature then
            local isOn = false
            driftgod.Try(function()
                if feature.IsToggled then isOn = feature:IsToggled() == true
                elseif feature.GetBoolValue then isOn = feature:GetBoolValue() == true end
            end)
            if not isOn then
                driftgod.Try(function()
                    if feature.SetBoolValue then feature:SetBoolValue(true)
                    elseif feature.Toggle then feature:Toggle(true) end
                end)
                driftgod.Try(function()
                    if feature.TriggerCallback then feature:TriggerCallback() end
                end)
            end
        end
        P28.lastEnableReason = tostring(reason or "Base Tuning selection")
        return true
    end

    -- Selecting Standard, Linear, Percent, Quadratic, Smooth, or Hybrid enables Tuning.
    if type(driftgod.P25_SelectBaseTuningMethod) == "function" and P28.selectWrapped ~= true then
        P28.selectWrapped = true
        local previousSelect = driftgod.P25_SelectBaseTuningMethod
        driftgod.P25_SelectBaseTuningMethod = function(method, ...)
            driftgod.P28_EnableTuningForBaseSelection("Base Tuning method " .. tostring(method))
            return previousSelect(method, ...)
        end
    end

    -- Strengthen Standard tuning values before UniversalDrifting consumes the preset.
    if type(driftgod.R197_GetTunedRuntimePreset) == "function" and P28.standardTunerWrapped ~= true then
        P28.standardTunerWrapped = true
        local previousStandardTuner = driftgod.R197_GetTunedRuntimePreset
        driftgod.R197_GetTunedRuntimePreset = function(base, ...)
            local tuned = previousStandardTuner(base, ...)
            if type(tuned) ~= "table" or tuned == base then return tuned end

            local acceleration = driftgod.S.accelAssistEnabled == true
                and math.max(0, (tonumber(driftgod.S.accelStrength or 3) or 3) - 3) or 0
            local experimental = driftgod.S.experimentalAccelEnabled == true
                and math.max(0, (tonumber(driftgod.S.experimentalAccelStrength or 3) or 3) - 3) or 0

            if acceleration > 0 or experimental > 0 then
                tuned.base_force = clamp((tonumber(tuned.base_force or 0.015) or 0.015)
                    * (1.0 + acceleration * 0.045 + experimental * 0.060), 0.004, 0.055)
                tuned.min_speed = clamp((tonumber(tuned.min_speed or 12.0) or 12.0)
                    - acceleration * 0.55 - experimental * 0.75, 4.0, 38.0)
                tuned._r198ExtraVelocity = clamp((tonumber(tuned._r198ExtraVelocity or 0.0) or 0.0)
                    + acceleration * 0.0017 + experimental * 0.0023, -0.0040, 0.0120)
            end
            return tuned
        end
    end

    -- Strengthen all five Base Tuning math methods without changing their saved values.
    if type(driftgod.P22_GetLabTunedRuntimePreset) == "function" and P28.baseTunerWrapped ~= true then
        P28.baseTunerWrapped = true
        local previousBaseTuner = driftgod.P22_GetLabTunedRuntimePreset
        driftgod.P22_GetLabTunedRuntimePreset = function(base, ...)
            local tuned = previousBaseTuner(base, ...)
            if type(tuned) ~= "table" then return tuned end

            local lab = driftgod.PrimeDriftTuningLab
            local method = lab and math.floor(tonumber(lab.activeMethod or 0) or 0) or 0
            local values = lab and lab.methods and lab.methods[method] or nil
            if type(values) ~= "table" then return tuned end

            local acceleration = math.max(0, (tonumber(values.acceleration or 3) or 3) - 3)
            local experimental = math.max(0, (tonumber(values.experimentalAcceleration or 3) or 3) - 3)
            if acceleration > 0 or experimental > 0 then
                tuned.base_force = clamp((tonumber(tuned.base_force or 0.015) or 0.015)
                    * (1.0 + acceleration * 0.070 + experimental * 0.095), 0.004, 0.060)
                tuned.min_speed = clamp((tonumber(tuned.min_speed or 12.0) or 12.0)
                    - acceleration * 0.85 - experimental * 1.10, 3.5, 38.0)
                tuned._r198ExtraVelocity = clamp((tonumber(tuned._r198ExtraVelocity or 0.0) or 0.0)
                    + acceleration * 0.0025 + experimental * 0.0033, -0.0040, 0.0160)
                tuned._p28LowSpeedAcceleration = clamp((acceleration * 0.55) + (experimental * 0.75), 0.0, 2.6)
            end
            return tuned
        end
    end

    -- Base Tuning methods isolate the normal acceleration workers. Add one controlled,
    -- forward low-speed push after UniversalDrifting runs, strongest on slower vehicles.
    if type(driftgod.ApplyArcadeDriftPresetRuntime) == "function" and P28.runtimeWrapped ~= true then
        P28.runtimeWrapped = true
        local previousRuntime = driftgod.ApplyArcadeDriftPresetRuntime
        driftgod.ApplyArcadeDriftPresetRuntime = function(veh, kmh, driftAngle, held, ...)
            local a, b, c, d = previousRuntime(veh, kmh, driftAngle, held, ...)

            local lab = driftgod.PrimeDriftTuningLab
            local method = lab and math.floor(tonumber(lab.activeMethod or 0) or 0) or 0
            if method < 1 or method > 5 or held ~= true or not veh or veh == 0 then return a, b, c, d end
            if driftgod.S.stuntBusy == true then return a, b, c, d end

            kmh = tonumber(kmh or 0.0) or 0.0
            local angle = math.abs(tonumber(driftAngle or 0.0) or 0.0)
            if kmh < 3.0 or kmh > 88.0 or angle < 4.0 or angle > 125.0 then return a, b, c, d end

            local values = lab.methods and lab.methods[method] or nil
            if type(values) ~= "table" then return a, b, c, d end
            local acceleration = math.max(0.0, ((tonumber(values.acceleration or 3) or 3) - 3.0) / 2.0)
            local experimental = math.max(0.0, ((tonumber(values.experimentalAcceleration or 3) or 3) - 3.0) / 2.0)
            local strength = clamp((acceleration * 0.65) + (experimental * 0.90), 0.0, 1.55)
            if strength <= 0.0 then return a, b, c, d end

            local now = nowMs()
            if now - (tonumber(P28.lastMethodBoostMs or 0) or 0) < 110 then return a, b, c, d end
            P28.lastMethodBoostMs = now

            local inAir = false
            if ENTITY and ENTITY.IS_ENTITY_IN_AIR then driftgod.Try(function() inAir = ENTITY.IS_ENTITY_IN_AIR(veh) == true end) end
            if inAir then return a, b, c, d end

            local lowSpeed = clamp((64.0 - kmh) / 59.0, 0.0, 1.0)
            local highFade = clamp((88.0 - kmh) / 24.0, 0.0, 1.0)
            local gain = strength * highFade
            if gain <= 0.0 then return a, b, c, d end

            if ENTITY and ENTITY.GET_ENTITY_VELOCITY and ENTITY.SET_ENTITY_VELOCITY then
                driftgod.Try(function()
                    local velocity = ENTITY.GET_ENTITY_VELOCITY(veh)
                    if velocity then
                        local multiplier = 1.0 + gain * (0.0028 + lowSpeed * 0.0068)
                        ENTITY.SET_ENTITY_VELOCITY(veh,
                            (velocity.x or 0.0) * multiplier,
                            (velocity.y or 0.0) * multiplier,
                            velocity.z or 0.0)
                    end
                end)
            end

            if ENTITY and ENTITY.GET_ENTITY_HEADING and ENTITY.APPLY_FORCE_TO_ENTITY then
                driftgod.Try(function()
                    local heading = tonumber(ENTITY.GET_ENTITY_HEADING(veh) or 0.0) or 0.0
                    local radians = math.rad(heading)
                    local amount = gain * (0.0035 + lowSpeed * 0.0105)
                    ENTITY.APPLY_FORCE_TO_ENTITY(
                        veh, 1,
                        -math.sin(radians) * amount,
                        math.cos(radians) * amount,
                        0.0, 0.0, 0.0, 0.0,
                        0, false, true, true, false, true
                    )
                end)
            end

            return a, b, c, d
        end
    end

    -- Enable Tuning once for the restored profile, then only when preset/method changes.
    if Script and Script.RegisterLooped and P28.selectionWorkerInstalled ~= true then
        P28.selectionWorkerInstalled = true
        Script.RegisterLooped(function()
            if ShouldUnload and ShouldUnload() then return false end

            local base = tostring(driftgod.S.r195BaseTuningPreset
                or driftgod.S.r198BaseTuningPreset
                or driftgod.S.activeArcadeDriftPreset
                or "default_drifting")
            local method = math.floor(clamp(driftgod.S.baseTuningSelectedMethod or 0, 0, 5))
            local key = base .. ":" .. tostring(method)
            if key ~= tostring(P28.lastSelectionKey or "") then
                P28.lastSelectionKey = key
                driftgod.P28_EnableTuningForBaseSelection("restored profile " .. key)
            end

            if Script and Script.Yield then Script.Yield(200) end
        end)
    else
        driftgod.P28_EnableTuningForBaseSelection("startup profile")
    end

    if driftgod.Log then
        driftgod.Log("[Drift Tuning] v1.0.2 acceleration update loaded | low-speed assist adaptive | Base Tuning auto-enables Tuning")
    end
end)

