    local function dg103_combo(label, index, names, popupRows)
        index = tonumber(index or 0) or 0
        if type(names) ~= "table" or #names <= 0 then return index, false end
        if index < 0 then index = 0 end
        if index > #names - 1 then index = #names - 1 end

        if ImGui and ImGui.Combo then
            local ok, newIndex, changed = driftgod.Try(ImGui.Combo, label, index, names, #names, popupRows or math.min(#names, 8))
            if ok and type(newIndex) == "number" then
                if newIndex < 0 then newIndex = 0 end
                if newIndex > #names - 1 then newIndex = #names - 1 end
                return newIndex, (changed == true or newIndex ~= index)
            end
        end

        local prev = dg103_button("<##" .. tostring(label))
        dg103_same_line()
        dg103_text(names[index + 1] or names[1] or "Topic", "purple")
        dg103_same_line()
        local next = dg103_button(">##" .. tostring(label))
        if prev or next then
            local n = index + (next and 1 or -1)
            if n < 0 then n = #names - 1 end
            if n > #names - 1 then n = 0 end
            return n, true
        end
        return index, false
    end

