            local selected = GUIDE_TIPS[idx + 1] or GUIDE_TIPS[1]
            dg103_text(selected.name, "purple")
            dg103_render_lines(selected.lines)
            dg103_end_child()
        end

        if dg103_child("Guide - How To", "How To", "Step-by-step mini guides for common actions.") then
