    function driftgod.R103_RequestSettingsReset()
        driftgod.show_reset_popup = true
        driftgod.reset_popup_opened_at = dg103_now_ms()
    end

    function driftgod.R103_PerformDeferredSettingsReset()
        driftgod.pending_settings_reset = false
        local ok, err = driftgod.Try(function()
            if driftgod.RestoreDefaultSettings then
                driftgod.RestoreDefaultSettings()
            else
                for k, v in pairs(driftgod.DefaultSettings or {}) do driftgod.S[k] = v end
                if driftgod.SaveSettings then driftgod.SaveSettings(false) end
            end
        end)

        if ok then
            driftgod.needs_settings_feature_sync = true
            if driftgod.Toast then driftgod.Toast("Settings reset complete. Progress and saved content were not erased.", 3500) end
        else
            if Logger and Logger.LogError then Logger.LogError("[DriftGod] Deferred settings reset failed: " .. tostring(err)) end
            if driftgod.Toast then driftgod.Toast("Settings reset failed. Check logs.", 3500) end
        end
    end

    if Script and Script.RegisterLooped and driftgod.R103ResetWorkerInstalled ~= true then
        driftgod.R103ResetWorkerInstalled = true
        Script.RegisterLooped(function()
            if ShouldUnload and ShouldUnload() then return false end

            if driftgod.pending_settings_reset == true then
                driftgod.R103_PerformDeferredSettingsReset()
            end

            if driftgod.needs_settings_feature_sync == true then
                driftgod.needs_settings_feature_sync = false
                driftgod.Try(function() if driftgod.SyncScoreHudVisibilityFromFlags then driftgod.SyncScoreHudVisibilityFromFlags() end end)
                driftgod.Try(function() if driftgod.VS_SyncFeatures then driftgod.VS_SyncFeatures() end end)
            end

            if Script and Script.Yield then Script.Yield(200) end
        end)
    end

    function driftgod.R103_RenderResetPopup()
        if not (ImGui and ImGui.OpenPopup and ImGui.BeginPopupModal and ImGui.EndPopup) then return end

        if driftgod.show_reset_popup == true then
            driftgod.Try(ImGui.OpenPopup, "Reset DriftGod Settings##DG103ResetPopup")
        end

        local flags = nil
        if ImGuiWindowFlags and ImGuiWindowFlags.AlwaysAutoResize then flags = ImGuiWindowFlags.AlwaysAutoResize end
        local ok, visible = driftgod.Try(ImGui.BeginPopupModal, "Reset DriftGod Settings##DG103ResetPopup", true, flags)
        if ok and visible then
            dg103_text("Reset Settings?", "header")
            dg103_text("This only resets DriftGod configuration/preferences.", "yellow")
            dg103_sep()
            dg103_text("Will reset:", "purple")
            dg103_text("HUD positions, HUD visibility, UI preferences, tuning defaults, hotkey/layout preferences.", "white")
            dg103_text("Will NOT reset:", "green")
            dg103_text("Progress, Best Run, scores, unlocks, custom presets, saved vehicles, garage files, ghosts, recordings, or race data.", "white")
            dg103_sep()
            dg103_text("The actual reset is deferred to DriftGod's worker loop so ClickGUI rendering stays safe.", "dim")
            dg103_sep()

            local pushed = dg103_push_button_color("safe")
            if dg103_button("NO, GO BACK##DG103NoReset") then
                driftgod.show_reset_popup = false
                if ImGui.CloseCurrentPopup then driftgod.Try(ImGui.CloseCurrentPopup) end
            end
            dg103_pop_button_color(pushed)

            dg103_same_line()
            pushed = dg103_push_button_color("danger")
            if dg103_button("YES, RESET SETTINGS##DG103YesReset") then
                driftgod.pending_settings_reset = true
                driftgod.show_reset_popup = false
                if ImGui.CloseCurrentPopup then driftgod.Try(ImGui.CloseCurrentPopup) end
            end
            dg103_pop_button_color(pushed)

            driftgod.Try(ImGui.EndPopup)
        end
    end

