                dg103_same_line()
                if dg103_button("Load Settings##DG103LoadSettings") and driftgod.LoadSettings then driftgod.LoadSettings(true) end
                if dg103_button("Save Progress##DG103SaveProgress") and driftgod.SaveProgress then driftgod.SaveProgress(true) end
                dg103_same_line()
                if dg103_button("Load Progress##DG103LoadProgress") and driftgod.LoadProgress then driftgod.LoadProgress(true) end
            end
            dg103_end_child()
        end
