    function driftgod.R103_RenderSettings()
        if ImGui and ImGui.BeginTabBar and ImGui.BeginTabBar("DriftGodSettingsTabs_v103") then
            if ImGui.BeginTabItem("HUD") then
                if driftgod.SyncScoreHudVisibilityFromFlags then driftgod.Try(driftgod.SyncScoreHudVisibilityFromFlags) end
                if driftgod.R172_RenderSelectedHudSettings then driftgod.R172_RenderSelectedHudSettings()
                elseif driftgod.R102_RenderSelectedHudSettings then driftgod.R102_RenderSelectedHudSettings()
                elseif driftgod.R101_RenderSelectedHudSettings then driftgod.R101_RenderSelectedHudSettings()
                else dg103_text("HUD controls are unavailable in this build.", "yellow") end
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Stunts") then
                if renderStunts then renderStunts() else dg103_text("Stunt settings are unavailable in this build.", "yellow") end
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Config") then
                driftgod.R103_RenderSaveAndLoad()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Advanced") then
                if renderBeta then renderBeta() else dg103_text("Advanced tools are unavailable in this build.", "yellow") end
                ImGui.EndTabItem()
            end
            ImGui.EndTabBar()
        else
            driftgod.R103_RenderSaveAndLoad()
        end

        -- Always last, outside nested controls, matching Startup/HustleMeter recovery style.
        driftgod.R103_RenderResetRecoverySection()
    end

    renderSettingsMinimal = driftgod.R103_RenderSettings
    renderConfig = renderConfig or driftgod.R103_RenderSettings

    local MORE_SCRIPTS = {
        {"Startup", "Auto startup helpers, sessions, themes, and quality-of-life boot flow."},
        {"Essentials", "Small always-useful utility controls for everyday Cherax sessions."},
