    -- Final Garage debounce: suppress the Prime flash where duplicate hotkey callbacks
    -- open then immediately close the HUD inside the same short input burst.
    if type(driftgod.VS_SetOpen) == "function" and driftgod.R103GarageDebounceWrapped ~= true then
        driftgod.R103GarageDebounceWrapped = true
        local previousSetOpen = driftgod.VS_SetOpen
        driftgod.VS_SetOpen = function(openState, ...)
            openState = openState == true
            local now = dg103_now_ms()
            driftgod.__R103GarageLastSetOpenMs = tonumber(driftgod.__R103GarageLastSetOpenMs or 0) or 0
            driftgod.__R103GarageLastTrueOpenMs = tonumber(driftgod.__R103GarageLastTrueOpenMs or 0) or 0

            local currentlyOpen = driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.open == true
            if openState == false and currentlyOpen == true and (now - driftgod.__R103GarageLastTrueOpenMs) < 350 then
                if driftgod.VS and driftgod.VS.runtime then driftgod.VS.runtime.lastStatus = "Duplicate close suppressed" end
                return true
            end

            if openState == true then driftgod.__R103GarageLastTrueOpenMs = now end
            driftgod.__R103GarageLastSetOpenMs = now
            return previousSetOpen(openState, ...)
        end
    end

    if type(driftgod.VS_ToggleOpen) == "function" and driftgod.R103GarageToggleDebounceWrapped ~= true then
        driftgod.R103GarageToggleDebounceWrapped = true
        local previousToggleOpen = driftgod.VS_ToggleOpen
        driftgod.VS_ToggleOpen = function(...)
            local now = dg103_now_ms()
            local last = tonumber(driftgod.__R103GarageLastToggleMs or 0) or 0
            if now - last < 350 then
                if driftgod.VS and driftgod.VS.runtime then driftgod.VS.runtime.lastStatus = "Duplicate toggle suppressed" end
                return true
            end
            driftgod.__R103GarageLastToggleMs = now
            return previousToggleOpen(...)
        end
    end

    -- The established DriftGod tab callback was patched above to route How To -> Guide,
    -- Settings -> deferred reset UI, and Credits -> refreshed Credits. No late tab re-register is needed.


    if driftgod.Log then
        driftgod.Log("[UI] v1.0.3 Guide / Settings / Credits polish loaded. Deferred reset worker active.")
    end
end)
-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.4 config reset recovery safety patch
-- note: keeps guide/credits polish, moves reset controls into settings > config only,
--       separates settings reset from progress reset, and avoids unsafe FeatureMgr value writes.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or driftgod or {}
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.H = driftgod.H or {}

    driftgod.__ProductionPatch = "Config_Reset_Recovery_Safe"
    driftgod.__UIConfigResetRecoveryPatch = "v1.0.4"
    driftgod.Version = "v1.0.4"
    driftgod.BuildNumber = "2026.07.26.104"
    driftgod.LastUpdated = "2026-07-26"
    driftgod.LastUpdateDate = "2026-07-26"

    local function dg104_copy(value, seen)
        if type(value) ~= "table" then return value end
        seen = seen or {}
        if seen[value] then return seen[value] end
        local out = {}
        seen[value] = out
        for k, v in pairs(value) do out[dg104_copy(k, seen)] = dg104_copy(v, seen) end
        return out
    end

    local function dg104_text(text, tone)
        text = tostring(text or "")
        tone = tostring(tone or "white")
        if dgMiniText then
            local ok = driftgod.Try(dgMiniText, text, tone)
            if ok then return end
        end
        if dgA38Text then
            local ok = driftgod.Try(dgA38Text, text, tone)
            if ok then return end
        end
        if ImGui and ImGui.TextColored then
            if tone == "header" or tone == "purple" then driftgod.Try(ImGui.TextColored, 0.72, 0.42, 1.00, 1.00, text); return end
            if tone == "gold" then driftgod.Try(ImGui.TextColored, 1.00, 0.78, 0.18, 1.00, text); return end
            if tone == "green" then driftgod.Try(ImGui.TextColored, 0.36, 1.00, 0.55, 1.00, text); return end
            if tone == "red" then driftgod.Try(ImGui.TextColored, 1.00, 0.28, 0.34, 1.00, text); return end
            if tone == "yellow" then driftgod.Try(ImGui.TextColored, 1.00, 0.86, 0.28, 1.00, text); return end
            if tone == "cyan" then driftgod.Try(ImGui.TextColored, 0.42, 0.82, 1.00, 1.00, text); return end
            if tone == "dim" then driftgod.Try(ImGui.TextColored, 0.58, 0.58, 0.66, 1.00, text); return end
        end
        if ImGui and ImGui.Text then driftgod.Try(ImGui.Text, text) end
    end

    local function dg104_sep()
        if dgMiniSep then local ok = driftgod.Try(dgMiniSep); if ok then return end end
        if ImGui and ImGui.Separator then driftgod.Try(ImGui.Separator) end
    end

    local function dg104_same_line()
        if dgMiniSameLine then local ok = driftgod.Try(dgMiniSameLine); if ok then return end end
        if ImGui and ImGui.SameLine then driftgod.Try(ImGui.SameLine) end
    end

    local function dg104_child(name, title, subtitle)
        local opened = true
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, res = driftgod.Try(ClickGUI.BeginCustomChildWindow, tostring(name or "Section"))
            opened = ok and res ~= false
        end
        if opened then
            if title and title ~= "" then dg104_text(title, "header") end
            if subtitle and subtitle ~= "" then dg104_text(subtitle, "dim") end
            if title and title ~= "" then dg104_sep() end
        end
        return opened
    end

    local function dg104_end_child()
        if ClickGUI and ClickGUI.EndCustomChildWindow then driftgod.Try(ClickGUI.EndCustomChildWindow) end
    end

    local function dg104_button(label)
        if not (ImGui and ImGui.Button) then return false end
        local ok, clicked = driftgod.Try(ImGui.Button, tostring(label or "Button"))
        return ok and clicked == true
    end

    local function dg104_push_button_color(kind)
        if not (ImGui and ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Button and ImGuiCol.ButtonHovered and ImGuiCol.ButtonActive) then return 0 end
        if kind == "safe" then
            driftgod.Try(ImGui.PushStyleColor, ImGuiCol.Button, 0.18, 0.36, 0.24, 1.00)
            driftgod.Try(ImGui.PushStyleColor, ImGuiCol.ButtonHovered, 0.24, 0.50, 0.32, 1.00)
            driftgod.Try(ImGui.PushStyleColor, ImGuiCol.ButtonActive, 0.12, 0.28, 0.18, 1.00)
            return 3
        elseif kind == "danger" then
            driftgod.Try(ImGui.PushStyleColor, ImGuiCol.Button, 0.55, 0.12, 0.18, 1.00)
            driftgod.Try(ImGui.PushStyleColor, ImGuiCol.ButtonHovered, 0.76, 0.18, 0.25, 1.00)
            driftgod.Try(ImGui.PushStyleColor, ImGuiCol.ButtonActive, 0.40, 0.08, 0.12, 1.00)
            return 3
        elseif kind == "warning" then
            driftgod.Try(ImGui.PushStyleColor, ImGuiCol.Button, 0.58, 0.32, 0.08, 1.00)
            driftgod.Try(ImGui.PushStyleColor, ImGuiCol.ButtonHovered, 0.78, 0.44, 0.12, 1.00)
            driftgod.Try(ImGui.PushStyleColor, ImGuiCol.ButtonActive, 0.44, 0.24, 0.06, 1.00)
            return 3
        end
        return 0
    end

    local function dg104_pop_button_color(count)
        count = tonumber(count or 0) or 0
        if count > 0 and ImGui and ImGui.PopStyleColor then driftgod.Try(ImGui.PopStyleColor, count) end
    end

    local function dg104_toast(msg, ms)
        if driftgod.Toast then driftgod.Toast(tostring(msg or ""), tonumber(ms or 3000) or 3000)
        elseif GUI and GUI.AddToast then driftgod.Try(function() GUI.AddToast("DriftGod", tostring(msg or ""), tonumber(ms or 3000) or 3000, eToastPos and (eToastPos.TOP_RIGHT or eToastPos.TopRight) or 2) end)
        elseif Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] " .. tostring(msg or "")) end
    end

    -- Safe replacement: never call RestoreDefaultSettings here, because older builds attempt
    -- Feature:SetIntValue() on button features such as "Momentum +", which can throw a C++ exception.
    function driftgod.R104_ResetSettingsConfigOnly()
        driftgod.S = driftgod.S or {}
        for k, v in pairs(driftgod.DefaultSettings or {}) do
            driftgod.S[k] = dg104_copy(v)
        end

        -- Keep publisher-safe defaults aligned with the current public build.
        driftgod.S.inputHudEnabled = false
        driftgod.S.inputHudX = 0.190
        driftgod.S.inputHudY = 0.805
        driftgod.S.inputHudScale = 0.50
        driftgod.S.inputHudBackground = false

        driftgod.S.mphHudEnabled = true
        driftgod.S.mphHudX = 0.175
        driftgod.S.mphHudY = 0.977
        driftgod.S.mphHudScale = 0.65
        driftgod.S.mphHudBackground = false

        driftgod.S.noScoreZonesEnabled = true
        driftgod.S.bannedAreasEnabled = true
        driftgod.S.blockDriveOnWaterScore = true
        driftgod.S.noScoreZones = driftgod.S.noScoreZones or {}
        driftgod.S.noScoreZoneRadius = tonumber(driftgod.S.noScoreZoneRadius or driftgod.S.bannedAreaRadius or 55.0) or 55.0
        driftgod.S.bannedAreaRadius = tonumber(driftgod.S.bannedAreaRadius or driftgod.S.noScoreZoneRadius or 55.0) or 55.0

        driftgod.S.autoPlateEnabled = false
        driftgod.S.driftGodPlateEnabled = false
        driftgod.S.plateEnabled = false
        driftgod.S.customPlateEnabled = false
        driftgod.S.disableScrollWheel = false
        driftgod.S.accelAssistEnabled = true
        driftgod.S.momentumAssistEnabled = true
        driftgod.S.progressUnlocksEnabled = true

        if driftgod.ApplyPublisherDefaultsOnce then driftgod.Try(function() driftgod.ApplyPublisherDefaultsOnce() end) end
        if driftgod.ApplyStartupPreset then driftgod.Try(function() driftgod.ApplyStartupPreset(false) end) end
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end

        -- Intentionally no FeatureMgr value writes and no FeatureMgr row rebuilds here.
        driftgod.needs_settings_feature_sync = false
        return true
    end

    function driftgod.R104_ResetProgressOnly()
        driftgod.S = driftgod.S or {}

        local zeroKeys = {
            "bestScore", "bestDriftScore", "highScore", "highestScore", "topScore", "topDriftScore",
            "previousScore", "lastScore", "lastRunScore", "lifetimeScore", "totalScore", "totalDriftScore",
            "progressScore", "score", "currentScore", "sessionScore", "driftScore", "points", "totalPoints",
            "overallScore", "overallScoreBankedRuns", "overallScoreLastBankedRun", "challengeBestScore",
            "sessionChallengePoints", "sessionChallengeTotalPool", "progressMilestonePoints",
            "totalStuntsLanded", "landedStuntsThisRun", "cleanStuntChain", "longestDriftMs"
        }
        for _, k in ipairs(zeroKeys) do driftgod.S[k] = 0 end

        driftgod.S.bestRun = 0
        driftgod.S.bestCombo = 1
        driftgod.S.currentRunBestCombo = 1
        driftgod.S.comboMultiplier = 1
        driftgod.S.runActive = false
        driftgod.S.isDrifting = false
        driftgod.S.activeDriftMs = 0
        driftgod.S.validDriftWatchMs = 0

        driftgod.S.highScores = {}
        driftgod.S.vehicleHighScores = {}
        driftgod.S.unlockedRewards = {}
        driftgod.S.notifiedUnlocks = {}
        driftgod.S.beatenRivals = {}
        driftgod.S.bonusPopups = {}

        driftgod.S.stuntProgressionResetActive = false
        driftgod.S.stuntProgressionResetBaseline = 0
        driftgod.S.stuntUnlockLastHighest = ""
        driftgod.S.stuntUnlockBannerStart = 0
        driftgod.S.stuntUnlockBannerTitle = ""
        driftgod.S.stuntUnlockBannerName = ""
        driftgod.S.stuntUnlockNeedPopupStart = 0
        driftgod.S.stuntUnlockNeedPopupText = ""
        driftgod.S.stuntUpgradeEarnedTiers = {}
        driftgod.S.stuntUpgradeAnnouncedTiers = {}
        driftgod.S.stuntUpgradeLastHighestTierKey = ""
        driftgod.S.stuntUpgradeTierPopupStart = 0
        driftgod.S.stuntUpgradeTierPopupText = ""
        driftgod.S.stuntUseRunCounts = {}
        driftgod.S.stuntTierFreshUseCounts = {}
        driftgod.S.stuntUseRunId = (tonumber(driftgod.S.stuntUseRunId or 0) or 0) + 1
        driftgod.S.stuntUseLastScoreActive = false

        driftgod.S.dailyChallengeDateKey = nil
        driftgod.S.dailyChallengeActiveIds = {}
        driftgod.S.dailyChallengeCompleted = {}
        driftgod.S.dailyChallengeForceNonce = 0
        driftgod.S.sessionChallengesCompleted = {}
        driftgod.S.sessionChallengeLastCompleted = ""
        driftgod.S.progressMilestoneTitle = ""
        driftgod.S.progressMilestoneLastCompleted = ""
        driftgod.S.progressMilestonesCompleted = {}
        driftgod.S.vehicleMastery = {}
        driftgod.S.vehicleMasteryRewards = {}
        driftgod.S.vehicleMasteryLastVehicleModel = 0
        driftgod.S.vehicleMasteryLastVehicleName = ""

        if driftgod.ResetRunStats then driftgod.Try(function() driftgod.ResetRunStats() end) end
        if driftgod.ResetStuntUseRun then driftgod.Try(function() driftgod.ResetStuntUseRun("progress reset") end) end
        if driftgod.ForceAllStuntsTierOne then driftgod.Try(function() driftgod.ForceAllStuntsTierOne("progress reset") end) end
        if driftgod.UpdateActiveRival then driftgod.Try(function() driftgod.UpdateActiveRival(false) end) end

        local data = nil
        if driftgod.ExportProgress then
            local ok, result = driftgod.Try(function() return driftgod.ExportProgress() end)
            if ok and type(result) == "table" then data = result end
        end
        data = data or {
            progressSaveVersion = "A40",
            progressSaveSerial = (tonumber(driftgod.S.progressSaveSerial or 0) or 0) + 1,
            bestScore = 0,
            highScore = 0,
            highestScore = 0,
            previousScore = 0,
            lastRunScore = 0,
            bestCombo = 1,
            totalStuntsLanded = 0,
            highScores = {},
            vehicleHighScores = {},
            unlockedRewards = {},
            notifiedUnlocks = {},
            beatenRivals = {},
            challengeBestScore = 0,
            progressScore = 0,
            lifetimeScore = 0,
            totalScore = 0,
            totalDriftScore = 0,
            overallScore = 0,
            stuntUpgradeEarnedTiers = {},
            stuntUpgradeAnnouncedTiers = {},
            stuntTierFreshUseCounts = {},
            stuntUseRunCounts = {},
            dailyChallengeCompleted = {},
            sessionChallengesCompleted = {},
            progressMilestonesCompleted = {},
            vehicleMastery = {},
            vehicleMasteryRewards = {},
        }

        -- Overwrite every path the loader may consider, including legacy paths, so old backups do not rehydrate progress.
        local paths = {}
        if driftgod.GetProgressVaultPaths then
            local ok, result = driftgod.Try(function() return driftgod.GetProgressVaultPaths() end)
            if ok and type(result) == "table" then paths = result end
        elseif driftgod.ProgressFile then
            paths = { driftgod.ProgressFile }
        end
        if #paths <= 0 and driftgod.ProgressFile then paths = { driftgod.ProgressFile } end

        for _, path in ipairs(paths) do
            if type(path) == "string" and path ~= "" and driftgod.SaveTable then
                driftgod.Try(function() driftgod.SaveTable(path, data) end)
            end
        end

        return true
    end

    function driftgod.R103_PerformDeferredSettingsReset()
        driftgod.pending_settings_reset = false
        local ok, err = driftgod.Try(function() return driftgod.R104_ResetSettingsConfigOnly() end)
        if ok then
            dg104_toast("Settings reset complete. Progress and saved content were not erased.", 3500)
        else
            if Logger and Logger.LogError then Logger.LogError("[DriftGod] Deferred settings reset failed: " .. tostring(err)) end
            dg104_toast("Settings reset failed. Check logs.", 3500)
        end
    end

    function driftgod.R104_PerformDeferredProgressReset()
        driftgod.pending_progress_reset = false
        local ok, err = driftgod.Try(function() return driftgod.R104_ResetProgressOnly() end)
        if ok then
            dg104_toast("Progress reset complete. Settings/config and saved content were not erased.", 4000)
        else
            if Logger and Logger.LogError then Logger.LogError("[DriftGod] Deferred progress reset failed: " .. tostring(err)) end
            dg104_toast("Progress reset failed. Check logs.", 4000)
        end
    end

