            dg104_sep()
            dg104_text("Will reset", "purple")
            dg104_popup_text("HUD positions, HUD visibility, UI preferences, tuning defaults, intro/config preferences, and layout-style settings.", "white")
            dg104_text("Will NOT reset", "green")
            dg104_popup_text("Progress, Best Run, scores, unlocks, rivals, stunt tiers, custom presets, saved vehicles, garage files, ghosts, recordings, or race data.", "white")
            dg104_sep()
            dg104_popup_text("The actual reset is deferred to DriftGod's worker loop and does not write FeatureMgr values from the render callback.", "dim")
            dg104_sep()

            local pushed = dg104_push_button_color("safe")
            if dg104_button("NO, GO BACK##DG104NoSettingsReset") then
                driftgod.show_reset_popup = false
                if ImGui.CloseCurrentPopup then driftgod.Try(ImGui.CloseCurrentPopup) end
            end
            dg104_pop_button_color(pushed)
            dg104_same_line()
            pushed = dg104_push_button_color("danger")
            if dg104_button("YES, RESET SETTINGS##DG104YesSettingsReset") then
                driftgod.pending_settings_reset = true
                driftgod.show_reset_popup = false
                if ImGui.CloseCurrentPopup then driftgod.Try(ImGui.CloseCurrentPopup) end
            end
            dg104_pop_button_color(pushed)
            driftgod.Try(ImGui.EndPopup)
