    function driftgod.R104_RenderResetRecoverySection()
        if dg104_child("Settings - Reset & Recovery", "Reset & Recovery", "Configuration reset and progress reset are separated for safety.") then
            dg104_text("Reset Settings", "yellow")
            dg104_text("Resets configs/preferences only. Progress and saved content are preserved.", "dim")
            local pushed = dg104_push_button_color("warning")
            if dg104_button("RESET SETTINGS##DG104RequestSettingsReset") then driftgod.R103_RequestSettingsReset() end
            dg104_pop_button_color(pushed)
