    function driftgod.R103_RenderResetRecoverySection()
        -- Keep old callers safe, but this section is only invoked from Settings > Config in v1.0.4.
        driftgod.R104_RenderResetRecoverySection()
    end

    function driftgod.R104_RenderConfigTab()
        if driftgod.R103_RenderSaveAndLoad then
            driftgod.R103_RenderSaveAndLoad()
        else
            if dg104_child("Settings - Save / Load", "Save / Load", "Manual persistence controls.") then
                if dg104_button("Save Settings##DG104SaveSettings") and driftgod.SaveSettings then driftgod.SaveSettings(true) end
                dg104_same_line()
                if dg104_button("Load Settings##DG104LoadSettings") and driftgod.LoadSettings then driftgod.LoadSettings(true) end
                if dg104_button("Save Progress##DG104SaveProgress") and driftgod.SaveProgress then driftgod.SaveProgress(true) end
                dg104_same_line()
                if dg104_button("Load Progress##DG104LoadProgress") and driftgod.LoadProgress then driftgod.LoadProgress(true) end
                dg104_end_child()
            end
        end

        -- Requested placement: Settings > Config, bottom of the Config tab.
        driftgod.R104_RenderResetRecoverySection()
    end

    function driftgod.R103_RenderSettings()
        if ImGui and ImGui.BeginTabBar and ImGui.BeginTabBar("DriftGodSettingsTabs_v104") then
            if ImGui.BeginTabItem("HUD") then
                if driftgod.SyncScoreHudVisibilityFromFlags then driftgod.Try(driftgod.SyncScoreHudVisibilityFromFlags) end
                if driftgod.R172_RenderSelectedHudSettings then driftgod.R172_RenderSelectedHudSettings()
                elseif driftgod.R102_RenderSelectedHudSettings then driftgod.R102_RenderSelectedHudSettings()
                elseif driftgod.R101_RenderSelectedHudSettings then driftgod.R101_RenderSelectedHudSettings()
                else dg104_text("HUD controls are unavailable in this build.", "yellow") end
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Stunts") then
                if renderStunts then renderStunts() else dg104_text("Stunt settings are unavailable in this build.", "yellow") end
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Config") then
                driftgod.R104_RenderConfigTab()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Advanced") then
                if renderBeta then renderBeta() else dg104_text("Advanced tools are unavailable in this build.", "yellow") end
                ImGui.EndTabItem()
            end
            ImGui.EndTabBar()
        else
            driftgod.R104_RenderConfigTab()
        end
    end

    renderSettingsMinimal = driftgod.R103_RenderSettings

    if Script and Script.RegisterLooped and driftgod.R104ProgressResetWorkerInstalled ~= true then
        driftgod.R104ProgressResetWorkerInstalled = true
        Script.RegisterLooped(function()
            if ShouldUnload and ShouldUnload() then return false end
            if driftgod.pending_progress_reset == true then
                driftgod.R104_PerformDeferredProgressReset()
            end
            if Script and Script.Yield then Script.Yield(200) end
        end)
    end

    if driftgod.Log then
        driftgod.Log("[UI] v1.0.4 Reset & Recovery loaded. Reset controls now live only in Settings > Config and avoid unsafe FeatureMgr value writes.")
    end
end)


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.5 ui + reset safety patch
-- note: guide text is shortened/wrapped; reset controls render only in Settings > Config.
-- note: reset workers never call tuning preset appliers or FeatureMgr value setters.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or driftgod or {}
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.H = driftgod.H or {}

    driftgod.Version = "v1.0.5"
    driftgod.BuildNumber = "2026.07.26.105"
    driftgod.LastUpdated = "2026-07-26"
    driftgod.LastUpdateDate = "2026-07-26"
    driftgod.__ProductionPatch = "v1_0_5_Guide_Config_Reset_Crash_Fix"

    local function DG105Copy(value, seen)
        if type(value) ~= "table" then return value end
        seen = seen or {}
        if seen[value] then return seen[value] end
        local out = {}
        seen[value] = out
        for k, v in pairs(value) do out[DG105Copy(k, seen)] = DG105Copy(v, seen) end
        return out
    end

    local function DG105Try(fn, ...)
        if driftgod.Try then return driftgod.Try(fn, ...) end
        return pcall(fn, ...)
    end

    local function DG105TextRaw(text, tone)
        text = tostring(text or "")
        tone = tostring(tone or "white")
        if dgMiniText then
            local ok = DG105Try(dgMiniText, text, tone)
            if ok then return end
        end
        if dgA38Text then
            local ok = DG105Try(dgA38Text, text, tone)
            if ok then return end
        end
        if not ImGui then return end
        if ImGui.TextColored then
            if tone == "header" or tone == "purple" then DG105Try(ImGui.TextColored, 0.72, 0.42, 1.00, 1.00, text); return end
            if tone == "gold" or tone == "yellow" then DG105Try(ImGui.TextColored, 1.00, 0.82, 0.22, 1.00, text); return end
            if tone == "green" then DG105Try(ImGui.TextColored, 0.36, 1.00, 0.55, 1.00, text); return end
            if tone == "red" then DG105Try(ImGui.TextColored, 1.00, 0.28, 0.34, 1.00, text); return end
            if tone == "cyan" then DG105Try(ImGui.TextColored, 0.42, 0.82, 1.00, 1.00, text); return end
            if tone == "dim" then DG105Try(ImGui.TextColored, 0.58, 0.58, 0.66, 1.00, text); return end
        end
        if ImGui.TextWrapped then DG105Try(ImGui.TextWrapped, text)
        elseif ImGui.Text then DG105Try(ImGui.Text, text) end
    end

    local function DG105Wrap(text, limit)
        text = tostring(text or "")
        limit = tonumber(limit or 62) or 62
        if #text <= limit then return {text} end
        local out, line = {}, ""
        for word in text:gmatch("%S+") do
            if line == "" then
                line = word
            elseif #(line .. " " .. word) <= limit then
                line = line .. " " .. word
            else
                out[#out + 1] = line
                line = word
            end
        end
        if line ~= "" then out[#out + 1] = line end
        if #out <= 0 then out[1] = text end
        return out
    end

    local function DG105Text(text, tone)
        for _, part in ipairs(DG105Wrap(text, 64)) do
            DG105TextRaw(part, tone)
        end
    end

    local function DG105Sep()
        if dgMiniSep then local ok = DG105Try(dgMiniSep); if ok then return end end
        if ImGui and ImGui.Separator then DG105Try(ImGui.Separator) end
    end

    local function DG105SameLine()
        if dgMiniSameLine then local ok = DG105Try(dgMiniSameLine); if ok then return end end
        if ImGui and ImGui.SameLine then DG105Try(ImGui.SameLine) end
    end

    local function DG105Child(name, title, subtitle)
        local opened = true
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, res = DG105Try(ClickGUI.BeginCustomChildWindow, tostring(name or "Section"))
            opened = ok and res ~= false
        end
        if opened then
            if title and title ~= "" then DG105TextRaw(title, "header") end
            if subtitle and subtitle ~= "" then DG105Text(subtitle, "dim") end
            if title and title ~= "" then DG105Sep() end
        end
        return opened
    end

    local function DG105EndChild()
        if ClickGUI and ClickGUI.EndCustomChildWindow then DG105Try(ClickGUI.EndCustomChildWindow) end
    end

    local function DG105Button(label)
        if not (ImGui and ImGui.Button) then return false end
        local ok, clicked = DG105Try(ImGui.Button, tostring(label or "Button"))
        return ok and clicked == true
    end

    local function DG105Combo(label, index, names, rows)
        names = names or {"None"}
        index = math.floor(tonumber(index or 0) or 0)
        if index < 0 then index = 0 end
        if index > #names - 1 then index = #names - 1 end
        if ImGui and ImGui.Combo then
            local ok, newIndex, changed = DG105Try(ImGui.Combo, label, index, names, #names, rows or math.min(#names, 8))
            if ok and type(newIndex) == "number" then
                newIndex = math.max(0, math.min(#names - 1, math.floor(newIndex)))
                return newIndex, changed == true or newIndex ~= index
            end
        end
        local prev = DG105Button("<##" .. tostring(label))
        DG105SameLine(); DG105TextRaw(names[index + 1] or names[1] or "Topic", "purple"); DG105SameLine()
        local next = DG105Button(">##" .. tostring(label))
        if prev or next then
            local n = index + (next and 1 or -1)
            if n < 0 then n = #names - 1 end
            if n > #names - 1 then n = 0 end
            return n, true
        end
        return index, false
    end

    local function DG105PushButtonColor(kind)
        if not (ImGui and ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Button and ImGuiCol.ButtonHovered and ImGuiCol.ButtonActive) then return 0 end
        if kind == "safe" then
            DG105Try(ImGui.PushStyleColor, ImGuiCol.Button, 0.18, 0.36, 0.24, 1.00)
            DG105Try(ImGui.PushStyleColor, ImGuiCol.ButtonHovered, 0.24, 0.50, 0.32, 1.00)
            DG105Try(ImGui.PushStyleColor, ImGuiCol.ButtonActive, 0.12, 0.28, 0.18, 1.00)
            return 3
        elseif kind == "warning" then
            DG105Try(ImGui.PushStyleColor, ImGuiCol.Button, 0.58, 0.32, 0.08, 1.00)
            DG105Try(ImGui.PushStyleColor, ImGuiCol.ButtonHovered, 0.78, 0.44, 0.12, 1.00)
            DG105Try(ImGui.PushStyleColor, ImGuiCol.ButtonActive, 0.44, 0.24, 0.06, 1.00)
            return 3
        elseif kind == "danger" then
            DG105Try(ImGui.PushStyleColor, ImGuiCol.Button, 0.55, 0.12, 0.18, 1.00)
            DG105Try(ImGui.PushStyleColor, ImGuiCol.ButtonHovered, 0.76, 0.18, 0.25, 1.00)
            DG105Try(ImGui.PushStyleColor, ImGuiCol.ButtonActive, 0.40, 0.08, 0.12, 1.00)
            return 3
        end
        return 0
    end

    local function DG105PopButtonColor(count)
        count = tonumber(count or 0) or 0
        if count > 0 and ImGui and ImGui.PopStyleColor then DG105Try(ImGui.PopStyleColor, count) end
    end

    local function DG105Toast(msg, ms)
        if driftgod.Toast then driftgod.Toast(tostring(msg or ""), tonumber(ms or 3000) or 3000)
        elseif GUI and GUI.AddToast then DG105Try(function() GUI.AddToast("DriftGod", tostring(msg or ""), tonumber(ms or 3000) or 3000, eToastPos and (eToastPos.TOP_RIGHT or eToastPos.TopRight) or 2) end)
