-- v1.0.7 ui patch: separator cleanup after reset
-- note: UI-only cleanup for Guide / Settings / Credits. Removes the extra horizontal
--       separator lines that became visually loud after reset while preserving the
--       working deferred-reset system and Discover More Scripts behavior.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or driftgod or {}
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.H = driftgod.H or {}

    driftgod.Version = "v1.0.7"
    driftgod.BuildNumber = "2026.07.27.107"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_7_Separator_Cleanup"

    local function DG107Try(fn, ...)
        if driftgod.Try then return driftgod.Try(fn, ...) end
        return pcall(fn, ...)
    end

    local function DG107Wrap(text, limit)
        text = tostring(text or "")
        limit = tonumber(limit or 64) or 64
        if #text <= limit then return { text } end
        local out, line = {}, ""
        for word in text:gmatch("%S+") do
            if line == "" then
                line = word
            elseif #(line .. " " .. word) <= limit then
                line = line .. " " .. word
            else
                out[#out + 1] = line
                line = word
            end
        end
        if line ~= "" then out[#out + 1] = line end
        if #out == 0 then out[1] = text end
        return out
    end

    local function DG107TextRaw(text, tone)
        text = tostring(text or "")
        tone = tostring(tone or "white")
        if dgMiniText then
            local ok = DG107Try(dgMiniText, text, tone)
            if ok then return end
        end
        if dgA38Text then
            local ok = DG107Try(dgA38Text, text, tone)
            if ok then return end
        end
        if not ImGui then return end
        if ImGui.TextColored then
            if tone == "header" or tone == "purple" then DG107Try(ImGui.TextColored, 0.72, 0.42, 1.00, 1.00, text); return end
            if tone == "gold" or tone == "yellow" then DG107Try(ImGui.TextColored, 1.00, 0.82, 0.22, 1.00, text); return end
            if tone == "green" then DG107Try(ImGui.TextColored, 0.36, 1.00, 0.55, 1.00, text); return end
            if tone == "red" then DG107Try(ImGui.TextColored, 1.00, 0.28, 0.34, 1.00, text); return end
            if tone == "cyan" then DG107Try(ImGui.TextColored, 0.42, 0.82, 1.00, 1.00, text); return end
            if tone == "dim" then DG107Try(ImGui.TextColored, 0.58, 0.58, 0.66, 1.00, text); return end
        end
        if ImGui.TextWrapped then DG107Try(ImGui.TextWrapped, text)
        elseif ImGui.Text then DG107Try(ImGui.Text, text) end
    end

    local function DG107Text(text, tone)
        for _, part in ipairs(DG107Wrap(text, 64)) do DG107TextRaw(part, tone) end
    end

    local function DG107Space(amount)
        amount = tonumber(amount or 1) or 1
        if not ImGui then return end
        if ImGui.Dummy then
            for _ = 1, amount do DG107Try(ImGui.Dummy, 0.0, 4.0) end
        elseif ImGui.Spacing then
            for _ = 1, amount do DG107Try(ImGui.Spacing) end
        end
    end

    local function DG107SameLine()
        if dgMiniSameLine then local ok = DG107Try(dgMiniSameLine); if ok then return end end
        if ImGui and ImGui.SameLine then DG107Try(ImGui.SameLine) end
    end

    local function DG107Child(name, title, subtitle)
        local opened = true
        if ClickGUI and ClickGUI.BeginCustomChildWindow then
            local ok, res = DG107Try(ClickGUI.BeginCustomChildWindow, tostring(name or "Section"))
            opened = ok and res ~= false
        end
        if opened then
            if title and title ~= "" then DG107TextRaw(title, "header") end
            if subtitle and subtitle ~= "" then DG107Text(subtitle, "dim") end
            DG107Space(1)
        end
        return opened
    end

    local function DG107EndChild()
        if ClickGUI and ClickGUI.EndCustomChildWindow then DG107Try(ClickGUI.EndCustomChildWindow) end
    end

    local function DG107Button(label)
        if not (ImGui and ImGui.Button) then return false end
        local ok, clicked = DG107Try(ImGui.Button, tostring(label or "Button"))
        return ok and clicked == true
    end

    local function DG107Combo(label, index, names, rows)
        names = names or { "None" }
        index = math.floor(tonumber(index or 0) or 0)
        if index < 0 then index = 0 end
        if index > #names - 1 then index = #names - 1 end
        if ImGui and ImGui.Combo then
            local ok, newIndex, changed = DG107Try(ImGui.Combo, label, index, names, #names, rows or math.min(#names, 8))
            if ok and type(newIndex) == "number" then
                newIndex = math.max(0, math.min(#names - 1, math.floor(newIndex)))
                return newIndex, changed == true or newIndex ~= index
            end
        end
        local prev = DG107Button("<##" .. tostring(label))
        DG107SameLine(); DG107TextRaw(names[index + 1] or names[1] or "Topic", "purple"); DG107SameLine()
        local next = DG107Button(">##" .. tostring(label))
        if prev or next then
            local n = index + (next and 1 or -1)
            if n < 0 then n = #names - 1 end
            if n > #names - 1 then n = 0 end
            return n, true
        end
        return index, false
    end

    local function DG107PushButtonColor(kind)
        if not (ImGui and ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Button and ImGuiCol.ButtonHovered and ImGuiCol.ButtonActive) then return 0 end
