-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.9 garage patch: exact selected vehicle loader
-- note: fixes Garage loading the wrong selected vehicle by resolving the selected
--       row against Cherax's current Saved Vehicles combo list at load time. This
--       avoids stale saved indices, sorted-disk order drift, and selection changes
--       between the HUD/UI click and the deferred worker load.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or driftgod or {}
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or {}

    driftgod.Version = "v1.0.9"
    driftgod.BuildNumber = "2026.07.27.109"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_9_Garage_Exact_Selected_Vehicle_Load"

    driftgod.__GarageExactSelection = driftgod.__GarageExactSelection or {
        patch = "v1.0.9",
        loads = 0,
        blocked = 0,
        lastResolved = "None",
        lastBlocked = "None"
    }
    local G109 = driftgod.__GarageExactSelection
    local SAVED_VEHICLE_LIST_HASH = 514776905
    local DEFAULT_SAVED_HASHES = { 514776905, 2597793574, 2620226128 }
    local LOAD_VEHICLE_FEATURE_NAME = "Load Vehicle"

    local function g109_try(fn, ...)
        if type(fn) ~= "function" then return false, "missing function" end
        if driftgod.Try then return driftgod.Try(fn, ...) end
        return pcall(fn, ...)
    end

    local function log(message, important)
        message = "[DriftGod Prime] [Garage v1.0.9] " .. tostring(message or "")
        if important == true and Logger and Logger.LogError then Logger.LogError(message)
        elseif Logger and Logger.LogInfo then Logger.LogInfo(message)
        elseif driftgod.Log then driftgod.Log(message) end
    end

    local function toast(message, ms)
        if driftgod.VS_Toast then g109_try(driftgod.VS_Toast, tostring(message or ""), tonumber(ms or 2500) or 2500)
        elseif driftgod.Toast then g109_try(driftgod.Toast, tostring(message or ""), tonumber(ms or 2500) or 2500)
        elseif GUI and GUI.AddToast then g109_try(function() GUI.AddToast("DriftGod", tostring(message or ""), tonumber(ms or 2500) or 2500, eToastPos and (eToastPos.TOP_RIGHT or eToastPos.TopRight) or 2) end) end
    end

    local function now_ms()
        if driftgod.VS_Now then
            local ok, value = g109_try(driftgod.VS_Now)
            if ok and tonumber(value) then return tonumber(value) end
        end
        if Time and Time.GetEpocheMs then
            local ok, value = g109_try(Time.GetEpocheMs)
            if ok and tonumber(value) then return tonumber(value) end
        end
        return math.floor((os.clock() or 0) * 1000)
    end

    local function normalize_path(path)
        path = tostring(path or ""):gsub("/", "\\")
        path = path:gsub("\\+", "\\")
        while #path > 3 and path:sub(-1) == "\\" do path = path:sub(1, -2) end
        return path
    end

    local function trim(text)
        return tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
    end

    local function filename(path)
        return normalize_path(path):match("([^\\]+)$") or tostring(path or "")
    end

    local function strip_json_ext(text)
        return tostring(text or ""):gsub("%.[Jj][Ss][Oo][Nn]$", "")
    end

    local function normalize_label(text)
        text = trim(text)
        text = text:gsub("/", "\\"):gsub(">", "\\")
        text = text:gsub("%s*\\%s*", "\\")
        text = text:gsub("\\+", "\\")
        text = strip_json_ext(text)
        text = trim(text)
        return text:lower()
    end

    local function decode_collection(collection)
        local output, seen = {}, {}
        local function add(value)
            if value == nil then return end
            local text = trim(value)
            if text == "" then return end
            if not seen[text] then
                seen[text] = true
                output[#output + 1] = text
            end
        end
        if type(collection) == "table" then
            for _, value in ipairs(collection) do add(value) end
            if #output == 0 then
                for _, value in pairs(collection) do add(value) end
            end
        end
        return output
    end

    local function get_saved_hashes()
        local hashes, seen = {}, {}
        local source = (driftgod.VS and driftgod.VS.CheraxSavedVehicleHashes) or DEFAULT_SAVED_HASHES
        for _, hash in ipairs(source) do
            hash = tonumber(hash)
            if hash and not seen[hash] then seen[hash] = true; hashes[#hashes + 1] = hash end
        end
        if not seen[SAVED_VEHICLE_LIST_HASH] then hashes[#hashes + 1] = SAVED_VEHICLE_LIST_HASH end
        return hashes
    end

    local function get_feature_list(hash)
        if not (FeatureMgr and FeatureMgr.GetFeatureList) then return {} end
        local ok, list = g109_try(function() return FeatureMgr.GetFeatureList(hash) end)
        if not ok then return {} end
        return decode_collection(list)
    end

    local function shallow_copy(item)
        if type(item) ~= "table" then return item end
        local copy = {}
        for k, v in pairs(item) do copy[k] = v end
        return copy
    end

    local function add_candidate(list, seen, value, source)
        value = trim(value)
        if value == "" then return end
        local key = normalize_label(value)
        if key == "" then return end
        if not seen[key] then
            seen[key] = true
            list[#list + 1] = { raw = value, key = key, source = source or "candidate" }
        end
    end

    local function selected_item_candidates(item)
        local candidates, seen = {}, {}
        if type(item) ~= "table" then return candidates end

        local path = normalize_path(item.path or "")
        local rel = normalize_path(item.rel or "")
        local name = strip_json_ext(tostring(item.name or ""))
        local fileName = strip_json_ext(filename(path))
        local category = trim(item.category or "")
        if name == "" then name = fileName end

        -- Highest confidence: label captured from Cherax's own saved-vehicle combo.
        add_candidate(candidates, seen, item.cheraxListLabel, "cherax-label")

        -- Strong candidates: exact UI/path-style labels.
        add_candidate(candidates, seen, item.displayLabel, "display-label")
        add_candidate(candidates, seen, rel, "relative-path")
        add_candidate(candidates, seen, rel:gsub("\\", " / "), "relative-display")
        if category ~= "" and category ~= "Root" and category ~= "All" then
            add_candidate(candidates, seen, category .. "\\" .. name, "category-name")
            add_candidate(candidates, seen, category .. " / " .. name, "category-display")
        end

        -- Lowest confidence: bare file/name. This is accepted only when unique.
        add_candidate(candidates, seen, name, "name")
        add_candidate(candidates, seen, fileName, "filename")
        return candidates
    end

    local function resolve_against_current_cherax_list(item)
        if type(item) ~= "table" then return nil, "missing item" end
        local candidates = selected_item_candidates(item)
        if #candidates <= 0 then return nil, "no candidates" end

        local allMatchesByKey = {}
        local anyListCount = 0

        for _, hash in ipairs(get_saved_hashes()) do
            local list = get_feature_list(hash)
            if #list > 0 then anyListCount = anyListCount + 1 end
            for index, label in ipairs(list) do
                local labelKey = normalize_label(label)
                if labelKey ~= "" then
                    allMatchesByKey[labelKey] = allMatchesByKey[labelKey] or {}
                    allMatchesByKey[labelKey][#allMatchesByKey[labelKey] + 1] = {
                        hash = hash,
                        index = index - 1,
                        label = label,
                    }
                end
            end
        end

        -- If the item already stores a captured Cherax label/index, trust it only if
        -- the current list entry still matches one of the selected item's exact labels.
        local storedHash = tonumber(item.cheraxListHash)
        local storedIndex = tonumber(item.cheraxListIndex)
        if storedHash and storedIndex and storedIndex >= 0 then
            local list = get_feature_list(storedHash)
            local storedLabel = list[storedIndex + 1]
            if storedLabel then
                local storedKey = normalize_label(storedLabel)
                for _, candidate in ipairs(candidates) do
                    if storedKey == candidate.key then
                        return { hash = storedHash, index = storedIndex, label = storedLabel, source = "stored-verified:" .. tostring(candidate.source) }
                    end
                end
            end
        end

        -- High-confidence exact labels first. A unique match is required.
        for _, candidate in ipairs(candidates) do
            local matches = allMatchesByKey[candidate.key] or {}
            if #matches == 1 then
                local m = matches[1]
                return { hash = m.hash, index = m.index, label = m.label, source = candidate.source }
            elseif #matches > 1 then
                -- Bare-name duplicates are common. Do not guess; loading a wrong car is worse.
                G109.lastBlocked = "Ambiguous vehicle label: " .. tostring(candidate.raw)
                return nil, "ambiguous: " .. tostring(candidate.raw)
            end
        end

        if anyListCount <= 0 then
            return nil, "Cherax saved vehicle list unavailable"
        end
        return nil, "not found in current Cherax saved vehicle list"
    end

    local function set_saved_vehicle_index(hash, index)
        if not (FeatureMgr and FeatureMgr.SetFeatureListIndex) then return false, "FeatureMgr.SetFeatureListIndex missing" end
        hash = tonumber(hash)
        index = tonumber(index)
        if not hash or not index or index < 0 then return false, "invalid hash/index" end

        local okSet, errSet = g109_try(function() FeatureMgr.SetFeatureListIndex(hash, index) end)
        if not okSet then return false, tostring(errSet) end

        -- Some Cherax builds apply combo changes more reliably through the feature
        -- object as well. Use hash only; never pass a Feature object into GetFeature.
        if FeatureMgr.GetFeature then
            g109_try(function()
                local feature = FeatureMgr.GetFeature(hash)
                if feature and feature.SetListIndex then feature:SetListIndex(index) end
            end)
        end
        return true
    end

    local function trigger_load_vehicle()
        if not (FeatureMgr and FeatureMgr.GetFeatureByName) then return false, "FeatureMgr.GetFeatureByName missing" end
        local loadFeature = nil
        local okResolve, errResolve = g109_try(function()
            loadFeature = FeatureMgr.GetFeatureByName((driftgod.VS and driftgod.VS.LoadVehicleFeatureName) or LOAD_VEHICLE_FEATURE_NAME)
        end)
        if not okResolve or not loadFeature then return false, "Load Vehicle feature not found: " .. tostring(errResolve) end
        if not loadFeature.TriggerCallback then return false, "Load Vehicle feature has no TriggerCallback" end
        local okTrigger, errTrigger = g109_try(function() loadFeature:TriggerCallback() end)
        if not okTrigger then return false, tostring(errTrigger) end
        return true
    end

    local function choose_random_item(targetCategory)
        local pool = {}
        targetCategory = tostring(targetCategory or "All")
        for _, candidate in ipairs((driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.items) or {}) do
            if targetCategory == "All" or tostring(candidate.category or "Root"):lower() == targetCategory:lower() then
                pool[#pool + 1] = candidate
            end
        end
        if #pool <= 0 then return nil end
        return shallow_copy(pool[math.random(1, #pool)])
    end

    local function set_runtime_loaded(item, resolved)
        if not (driftgod.VS and driftgod.VS.runtime) then return end
        driftgod.VS.runtime.lastSpawnedName = tostring(item.displayLabel or item.name or resolved.label or "Saved Vehicle")
        driftgod.VS.runtime.lastSpawnedModel = "Cherax Saved Vehicle"
        driftgod.VS.runtime.lastSpawnedHandle = 0
        driftgod.VS.runtime.spawnCount = (tonumber(driftgod.VS.runtime.spawnCount or 0) or 0) + 1
        driftgod.VS.runtime.lastStatus = "Loaded " .. tostring(driftgod.VS.runtime.lastSpawnedName)
    end

    function driftgod.DG109_CurrentGarageSelectionNoRebuild()
        driftgod.VS = driftgod.VS or {}
        driftgod.VS.runtime = driftgod.VS.runtime or {}
        local filtered = driftgod.VS.runtime.filtered or {}
        if #filtered <= 0 and driftgod.VS_Rebuild then g109_try(function() driftgod.VS_Rebuild(true) end); filtered = driftgod.VS.runtime.filtered or {} end
        local count = #filtered
        if count <= 0 then return nil end
        local index = math.floor(tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0)
        if index < 0 then index = 0 end
        if index > count - 1 then index = count - 1 end
        driftgod.S.vehicleSpawnerIndex = index
        return shallow_copy(filtered[index + 1])
    end

    function driftgod.VS_Selected()
        return driftgod.DG109_CurrentGarageSelectionNoRebuild()
    end

    function driftgod.VS_LoadItem(item, ...)
        if not item then
            G109.blocked = (tonumber(G109.blocked or 0) or 0) + 1
            G109.lastBlocked = "No saved vehicle selected."
            log("load blocked: no selected item", true)
            return false
        end

        item = shallow_copy(item)

        if item.isRandom then
            item = choose_random_item(item.randomTargetCategory or "All")
            if not item then
                G109.blocked = (tonumber(G109.blocked or 0) or 0) + 1
                G109.lastBlocked = "Random blocked: no vehicles available."
                log("random blocked: no vehicles available", true)
                return false
            end
        end

        if item.isFolder then
            driftgod.VS.runtime.currentFolder = item.folderTarget or item.category
            driftgod.S.vehicleSpawnerIndex = 0
            driftgod.VS.hud.scroll = 0
            if driftgod.VS_Rebuild then g109_try(function() driftgod.VS_Rebuild(true) end) end
            return true
        end

        if not tostring(item.path or ""):lower():match("%.json$") and tostring(item.ext or ""):lower() ~= "cherax" then
            G109.blocked = (tonumber(G109.blocked or 0) or 0) + 1
            G109.lastBlocked = "Only JSON/Cherax saved vehicle entries can be loaded safely."
            log("load blocked: unsupported saved vehicle entry | file=" .. tostring(item.path or ""), true)
            toast("This Garage entry cannot be mapped safely.", 3000)
            return false
        end

        local resolved, reason = resolve_against_current_cherax_list(item)
        if not resolved then
            G109.blocked = (tonumber(G109.blocked or 0) or 0) + 1
            G109.lastBlocked = tostring(reason or "mapping failed")
            log("load blocked: exact selected mapping failed | reason=" .. tostring(reason)
                .. " | selected=" .. tostring(item.displayLabel or item.name or item.path or "unknown"), true)
            toast("Garage mapping changed. Press Scan, then try again.", 3500)
            return false
        end

        local setOk, setErr = set_saved_vehicle_index(resolved.hash, resolved.index)
        if not setOk then
            G109.blocked = (tonumber(G109.blocked or 0) or 0) + 1
            G109.lastBlocked = "Set selected index failed: " .. tostring(setErr)
            log("SetFeatureListIndex failed | hash=" .. tostring(resolved.hash)
                .. " | index=" .. tostring(resolved.index)
                .. " | error=" .. tostring(setErr), true)
            toast("Could not select the saved vehicle in Cherax.", 3500)
            return false
        end

        local triggerOk, triggerErr = trigger_load_vehicle()
        if not triggerOk then
            G109.blocked = (tonumber(G109.blocked or 0) or 0) + 1
            G109.lastBlocked = "Load Vehicle trigger failed: " .. tostring(triggerErr)
            log("Load Vehicle trigger failed | error=" .. tostring(triggerErr), true)
            toast("Cherax Load Vehicle failed.", 3500)
            return false
        end

        item.cheraxListHash = resolved.hash
        item.cheraxListIndex = resolved.index
        item.cheraxListLabel = resolved.label
        set_runtime_loaded(item, resolved)
        G109.loads = (tonumber(G109.loads or 0) or 0) + 1
        G109.lastResolved = "hash=" .. tostring(resolved.hash) .. " index=" .. tostring(resolved.index) .. " label=" .. tostring(resolved.label) .. " source=" .. tostring(resolved.source)
        log("loaded exact selected vehicle | selected=" .. tostring(item.displayLabel or item.name or item.path)
            .. " | label=" .. tostring(resolved.label)
            .. " | index=" .. tostring(resolved.index)
            .. " | source=" .. tostring(resolved.source))
        toast("Loaded " .. tostring(item.displayLabel or item.name or resolved.label or "Saved Vehicle"), 2500)
        return true
    end

    function driftgod.R154_QueueItem(item)
        if not item then return false end
        item = shallow_copy(item)
        if item.isFolder then
            return driftgod.VS_LoadItem(item)
        end
        driftgod.VS.runtime.pending = { item = item, at = now_ms() + 80, exactSnapshot = true }
        driftgod.VS.runtime.lastStatus = "Queued " .. tostring(item.displayLabel or item.name or "vehicle")
        if driftgod.R154_InstallVehicleSpawnerWorker then g109_try(driftgod.R154_InstallVehicleSpawnerWorker) end
        return true
    end

    function driftgod.R154_QueueSelected()
        local item = driftgod.DG109_CurrentGarageSelectionNoRebuild()
        if not item then
            log("queue selected blocked: no selected item", true)
            toast("No Garage vehicle selected.", 2500)
            return false
        end
        return driftgod.R154_QueueItem(item)
    end

    function driftgod.VS_QueueSelected()
        return driftgod.R154_QueueSelected()
    end

    function driftgod.VS_ProcessPending()
        if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.pending) then return end
        local pending = driftgod.VS.runtime.pending
        local at = tonumber(pending.at or 0) or 0
        if now_ms() < at then return end
        driftgod.VS.runtime.pending = nil
        return driftgod.VS_LoadItem(pending.item)
    end

    function driftgod.R154_ProcessVehicleSpawnerPending()
        return driftgod.VS_ProcessPending()
    end

    if driftgod.VS_PrintStatus then
        local previousPrintStatus = driftgod.VS_PrintStatus
        driftgod.VS_PrintStatus = function(...)
            local result = previousPrintStatus(...)
            log("exact selection status | loads=" .. tostring(G109.loads)
                .. " | blocked=" .. tostring(G109.blocked)
                .. " | lastResolved=" .. tostring(G109.lastResolved)
                .. " | lastBlocked=" .. tostring(G109.lastBlocked))
            return result
        end
    end

    log("patch installed | selected Garage row now resolves against Cherax's current Saved Vehicles list before loading")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.10 prime garage patch: safe rollback from v1.0.9 exact-list resolver
-- note: v1.0.9 used Cherax Saved Vehicles list inspection at load time. On Prime that
--       can hard-crash. This patch disables that unsafe resolver and returns to the
--       known-good P12/P21 hash+index bridge, using only the scan-time exact index.
--       Loading is staged across worker ticks: resolve -> SetFeatureListIndex ->
--       Trigger Load Vehicle. No FeatureMgr.GetFeatureList calls are made here.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or driftgod or {}
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or {}

    driftgod.Version = "v1.0.10"
    driftgod.BuildNumber = "2026.07.27.110"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_10_Prime_Garage_Safe_Rollback"

    driftgod.__GaragePrimeSafeRollback = driftgod.__GaragePrimeSafeRollback or {
        patch = "v1.0.10",
        loads = 0,
        blocked = 0,
        failures = 0,
        lastResolved = "None",
        lastBlocked = "None",
        busy = false,
    }
    local G110 = driftgod.__GaragePrimeSafeRollback
    local SAVED_VEHICLE_LIST_HASH = 514776905
    local LOAD_VEHICLE_FEATURE_NAME = "Load Vehicle"

    -- Tell status tools that v1.0.9 should no longer be trusted for loading.
    if driftgod.__GarageExactSelection then
        driftgod.__GarageExactSelection.disabledBy = "v1.0.10_Prime_Garage_Safe_Rollback"
    end

    local function g110_try(fn, ...)
        if type(fn) ~= "function" then return false, "missing function" end
        if driftgod.Try then return driftgod.Try(fn, ...) end
        return pcall(fn, ...)
    end

    local function log(message, important)
        message = "[DriftGod Prime] [Garage v1.0.10] " .. tostring(message or "")
        if important == true and Logger and Logger.LogError then Logger.LogError(message)
        elseif Logger and Logger.LogInfo then Logger.LogInfo(message)
        elseif driftgod.Log then driftgod.Log(message) end
    end

    local function toast(message, ms)
        if driftgod.VS_Toast then g110_try(driftgod.VS_Toast, tostring(message or ""), tonumber(ms or 2500) or 2500)
        elseif driftgod.Toast then g110_try(driftgod.Toast, tostring(message or ""), tonumber(ms or 2500) or 2500)
        elseif GUI and GUI.AddToast then
            g110_try(function()
                GUI.AddToast("DriftGod", tostring(message or ""), tonumber(ms or 2500) or 2500, eToastPos and (eToastPos.TOP_RIGHT or eToastPos.TopRight) or 2)
            end)
        end
    end

    local function now_ms()
        if driftgod.VS_Now then
            local ok, value = g110_try(driftgod.VS_Now)
            if ok and tonumber(value) then return tonumber(value) end
        end
        if Time and Time.GetEpocheMs then
            local ok, value = g110_try(Time.GetEpocheMs)
            if ok and tonumber(value) then return tonumber(value) end
        end
        return math.floor((os.clock() or 0) * 1000)
    end

    local function normalize(path)
        path = tostring(path or ""):gsub("/", "\\")
        path = path:gsub("\\+", "\\")
        while #path > 3 and path:sub(-1) == "\\" do path = path:sub(1, -2) end
        return path
    end

    local function copy_item(item)
        if type(item) ~= "table" then return item end
        local copy = {}
        for k, v in pairs(item) do copy[k] = v end
        return copy
    end

    local function selected_no_rebuild()
        driftgod.VS = driftgod.VS or {}
        driftgod.VS.runtime = driftgod.VS.runtime or {}
        local filtered = driftgod.VS.runtime.filtered or {}
        if #filtered <= 0 and driftgod.VS_Rebuild then
            g110_try(function() driftgod.VS_Rebuild(true) end)
            filtered = driftgod.VS.runtime.filtered or {}
        end
        local count = #filtered
        if count <= 0 then return nil end
        local index = math.floor(tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0)
        if index < 0 then index = 0 end
        if index > count - 1 then index = count - 1 end
        driftgod.S.vehicleSpawnerIndex = index
        return copy_item(filtered[index + 1])
    end

    local function choose_random_item(targetCategory)
        local pool = {}
        targetCategory = tostring(targetCategory or "All")
        for _, candidate in ipairs((driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.items) or {}) do
            if targetCategory == "All" or tostring(candidate.category or "Root"):lower() == targetCategory:lower() then
                -- Only include vehicles with exact scan-time index mappings.
                if candidate and not candidate.isFolder and tonumber(candidate.cheraxListIndex) ~= nil then
                    pool[#pool + 1] = candidate
                end
            end
        end
        if #pool <= 0 then return nil end
        return copy_item(pool[math.random(1, #pool)])
    end

    local function resolve_scan_time_index(item)
        if type(item) ~= "table" then return nil, "missing item" end
        if item.isFolder then return nil, "folder" end

        local path = normalize(item.path or "")
        if path == "" or not path:lower():match("%.json$") then
            return nil, "only JSON saved vehicles can use the Prime-safe bridge"
        end

        local index = tonumber(item.cheraxListIndex)
        local hash = tonumber(item.cheraxListHash or SAVED_VEHICLE_LIST_HASH) or SAVED_VEHICLE_LIST_HASH

        -- P21's recursive scanner builds this exact map from Cherax's canonical
        -- Vehicles folder order. Trust scan-time data only; never inspect Cherax's
        -- FeatureMgr combo list from Prime during load.
        if index == nil and driftgod.__PrimeGarageP21 and type(driftgod.__PrimeGarageP21.cheraxIndexByPath) == "table" then
            index = tonumber(driftgod.__PrimeGarageP21.cheraxIndexByPath[path:lower()])
        end

        if index == nil then
            return nil, "no exact scan-time Cherax index; press Scan first"
        end
        if index < 0 then
            return nil, "invalid Cherax index"
        end

        return { hash = hash, index = math.floor(index), path = path, label = tostring(item.displayLabel or item.name or path) }, nil
    end

    local function set_runtime_loaded(item, resolved)
        if not (driftgod.VS and driftgod.VS.runtime) then return end
        driftgod.VS.runtime.lastSpawnedName = tostring(item.displayLabel or item.name or resolved.label or "Saved Vehicle")
        driftgod.VS.runtime.lastSpawnedModel = "Cherax Saved Vehicle"
        driftgod.VS.runtime.lastSpawnedHandle = 0
        driftgod.VS.runtime.spawnCount = (tonumber(driftgod.VS.runtime.spawnCount or 0) or 0) + 1
        driftgod.VS.runtime.lastStatus = "Loaded " .. tostring(driftgod.VS.runtime.lastSpawnedName)
    end

    local function queue_block(reason, ms)
        G110.blocked = (tonumber(G110.blocked or 0) or 0) + 1
        G110.lastBlocked = tostring(reason or "blocked")
        log("load blocked: " .. tostring(reason or "unknown"), true)
        toast(tostring(reason or "Garage load blocked."), ms or 3500)
        return false
    end

    function driftgod.DG110_CurrentGarageSelectionNoRebuild()
        return selected_no_rebuild()
    end

    function driftgod.VS_Selected()
        return selected_no_rebuild()
    end

    function driftgod.VS_LoadItem(item, ...)
        -- For compatibility, VS_LoadItem now queues a staged Prime-safe load instead
        -- of doing FeatureMgr operations immediately. Folder rows still open directly.
        if not item then return queue_block("No Garage vehicle selected.", 2500) end
        return driftgod.R154_QueueItem(item)
    end

    function driftgod.R154_QueueItem(item)
        if not item then return queue_block("No Garage vehicle selected.", 2500) end
        item = copy_item(item)

        if item.isRandom then
            item = choose_random_item(item.randomTargetCategory or "All")
            if not item then return queue_block("No mapped saved vehicles are available for Random.", 3000) end
        end

        if item.isFolder then
            driftgod.VS.runtime.currentFolder = item.folderTarget or item.category
            driftgod.S.vehicleSpawnerIndex = 0
            driftgod.VS.hud.scroll = 0
            if driftgod.VS_Rebuild then g110_try(function() driftgod.VS_Rebuild(true) end) end
            return true
        end

        if G110.busy == true or (driftgod.VS.runtime.pending and driftgod.VS.runtime.pending.primeSafe110 == true) then
            return queue_block("Garage load is already queued. Wait a moment.", 2500)
        end

        local resolved, reason = resolve_scan_time_index(item)
        if not resolved then
            return queue_block("Garage mapping is not ready. Press Scan, then try again.", 3500)
        end

        G110.busy = true
        driftgod.VS.runtime.pending = {
            primeSafe110 = true,
            stage = "set-index",
            item = item,
            resolved = resolved,
            at = now_ms() + 250,
        }
        driftgod.VS.runtime.lastStatus = "Queued " .. tostring(item.displayLabel or item.name or "vehicle")
        G110.lastResolved = "queued hash=" .. tostring(resolved.hash) .. " index=" .. tostring(resolved.index) .. " path=" .. tostring(resolved.path)
        if driftgod.R154_InstallVehicleSpawnerWorker then g110_try(driftgod.R154_InstallVehicleSpawnerWorker) end
        log("queued Prime-safe staged load | label=" .. tostring(item.displayLabel or item.name or "vehicle")
            .. " | hash=" .. tostring(resolved.hash) .. " | index=" .. tostring(resolved.index))
        return true
    end

    function driftgod.R154_QueueSelected()
        local item = selected_no_rebuild()
        if not item then return queue_block("No Garage vehicle selected.", 2500) end
        return driftgod.R154_QueueItem(item)
    end

    function driftgod.VS_QueueSelected()
        return driftgod.R154_QueueSelected()
    end

    local function fail_pending(reason)
        G110.failures = (tonumber(G110.failures or 0) or 0) + 1
        G110.lastBlocked = tostring(reason or "failed")
        if driftgod.VS and driftgod.VS.runtime then
            driftgod.VS.runtime.pending = nil
            driftgod.VS.runtime.lastStatus = "Garage load failed: " .. tostring(reason or "unknown")
        end
        G110.busy = false
        log("load failed: " .. tostring(reason or "unknown"), true)
        toast("Garage load failed safely. No vehicle was spawned.", 3500)
        return false
    end

    function driftgod.VS_ProcessPending()
        if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.pending) then return end
        local pending = driftgod.VS.runtime.pending
        if pending.primeSafe110 ~= true then
            -- Legacy pending entry: convert to the safe staged queue when possible.
            local legacyItem = pending.item
            driftgod.VS.runtime.pending = nil
            G110.busy = false
            if legacyItem then return driftgod.R154_QueueItem(legacyItem) end
            return
        end

        if now_ms() < (tonumber(pending.at or 0) or 0) then return end
        local item = pending.item
        local resolved = pending.resolved

        if pending.stage == "set-index" then
            if not (FeatureMgr and FeatureMgr.SetFeatureListIndex) then return fail_pending("FeatureMgr.SetFeatureListIndex missing") end
            local okSet, errSet = g110_try(function()
                FeatureMgr.SetFeatureListIndex(resolved.hash, resolved.index)
            end)
            if not okSet then return fail_pending("SetFeatureListIndex failed: " .. tostring(errSet)) end

            pending.stage = "trigger-load"
            pending.at = now_ms() + 350
            driftgod.VS.runtime.lastStatus = "Selected Cherax saved vehicle index. Loading next..."
            log("saved vehicle index set | hash=" .. tostring(resolved.hash) .. " | index=" .. tostring(resolved.index))
            return true
        end

        if pending.stage == "trigger-load" then
            if not (FeatureMgr and FeatureMgr.GetFeatureByName) then return fail_pending("FeatureMgr.GetFeatureByName missing") end
            local loadFeature = nil
            local okResolve, errResolve = g110_try(function()
                loadFeature = FeatureMgr.GetFeatureByName((driftgod.VS and driftgod.VS.LoadVehicleFeatureName) or LOAD_VEHICLE_FEATURE_NAME)
            end)
            if not okResolve or loadFeature == nil then return fail_pending("Load Vehicle feature not found: " .. tostring(errResolve)) end
            if not loadFeature.TriggerCallback then return fail_pending("Load Vehicle feature has no TriggerCallback") end

            local okTrigger, errTrigger = g110_try(function() loadFeature:TriggerCallback() end)
            if not okTrigger then return fail_pending("Load Vehicle callback failed: " .. tostring(errTrigger)) end

            driftgod.VS.runtime.pending = nil
            G110.busy = false
            set_runtime_loaded(item, resolved)
            G110.loads = (tonumber(G110.loads or 0) or 0) + 1
            G110.lastResolved = "loaded hash=" .. tostring(resolved.hash) .. " index=" .. tostring(resolved.index) .. " label=" .. tostring(item.displayLabel or item.name or "vehicle")
            log("loaded through staged Prime-safe bridge | label=" .. tostring(driftgod.VS.runtime.lastSpawnedName)
                .. " | hash=" .. tostring(resolved.hash) .. " | index=" .. tostring(resolved.index))
            toast("Loaded " .. tostring(driftgod.VS.runtime.lastSpawnedName), 2500)
            return true
        end

        return fail_pending("unknown pending stage: " .. tostring(pending.stage))
    end

    function driftgod.R154_ProcessVehicleSpawnerPending()
        return driftgod.VS_ProcessPending()
    end

    if driftgod.VS_PrintStatus then
        local previousPrintStatus = driftgod.VS_PrintStatus
        driftgod.VS_PrintStatus = function(...)
            local result = previousPrintStatus(...)
            log("Prime-safe rollback status | loads=" .. tostring(G110.loads)
                .. " | blocked=" .. tostring(G110.blocked)
                .. " | failures=" .. tostring(G110.failures)
                .. " | lastResolved=" .. tostring(G110.lastResolved)
                .. " | lastBlocked=" .. tostring(G110.lastBlocked))
            return result
        end
    end

    log("patch installed | v1.0.9 FeatureMgr list inspection disabled | staged P12/P21 Prime-safe bridge active")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.11 garage diagnostics patch: Prime-safe deep logging
-- note: logging-only garage patch. It does not inspect Cherax saved-vehicle lists at
--       spawn time, does not change the load strategy, and keeps the v1.0.10 Prime
--       safe rollback behavior. Use this to capture the exact selected row, mapped
--       Cherax list hash/index, scan order, filtered order, queue timing, and post-load
--       local vehicle model/handle so wrong-spawn bugs can be fixed precisely.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or driftgod or {}
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}

    driftgod.Version = "v1.0.11"
    driftgod.BuildNumber = "2026.07.27.111"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_11_Garage_Deep_Logs"

    local function DG111Try(fn, ...)
        if driftgod.Try then return driftgod.Try(fn, ...) end
        return pcall(fn, ...)
    end

    local function DG111NowMs()
        if Time and Time.GetEpocheMs then
            local ok, ms = DG111Try(Time.GetEpocheMs)
            if ok and ms then return tonumber(ms) or math.floor(os.clock() * 1000) end
        end
        return math.floor(os.clock() * 1000)
    end

    local function DG111SafeText(v)
        local s = tostring(v == nil and "nil" or v)
        s = s:gsub("[\r\n]+", " ")
        if #s > 700 then s = s:sub(1, 700) .. "..." end
        return s
    end

    local function DG111EnsureLogDir()
        if driftgod.VS.DebugDir and driftgod.VS.DebugLogFile then return end
        local root = ""
        DG111Try(function() root = tostring(FileMgr.GetMenuRootPath() or "") end)
        if root == "" then root = "." end
        driftgod.VS.DebugDir = root .. "\\Lua\\DriftGod\\debug"
        driftgod.VS.DebugLogFile = driftgod.VS.DebugDir .. "\\garage_debug.log"
        driftgod.VS.DebugLastLoadFile = driftgod.VS.DebugDir .. "\\garage_last_load.lua"
        DG111Try(function() if FileMgr and FileMgr.CreateDir then FileMgr.CreateDir(root .. "\\Lua") end end)
        DG111Try(function() if FileMgr and FileMgr.CreateDir then FileMgr.CreateDir(root .. "\\Lua\\DriftGod") end end)
        DG111Try(function() if FileMgr and FileMgr.CreateDir then FileMgr.CreateDir(driftgod.VS.DebugDir) end end)
    end

    local function DG111AppendLine(line)
        DG111EnsureLogDir()
        local path = driftgod.VS.DebugLogFile or "garage_debug.log"
        DG111Try(function()
            local f = io.open(path, "a")
            if f then
                f:write(tostring(line or ""), "\n")
                f:close()
            end
        end)
    end

    function driftgod.VS_DebugLog(stage, detail)
        stage = DG111SafeText(stage or "GARAGE")
        detail = DG111SafeText(detail or "")
        local line = string.format("%s | ms=%s | %s | %s",
            os.date("%Y-%m-%d %H:%M:%S"), tostring(DG111NowMs()), stage, detail)
        DG111AppendLine(line)
        if Logger and Logger.LogInfo then
            Logger.LogInfo("[DriftGod Prime] [GarageDbg] " .. stage .. " | " .. detail)
        elseif driftgod.Log then
            driftgod.Log("[GarageDbg] " .. stage .. " | " .. detail)
        end
        driftgod.VS.runtime.lastGarageDebug = line
    end

    local function DG111ItemLine(item)
        if type(item) ~= "table" then return "item=nil" end
        return table.concat({
            "display=" .. DG111SafeText(item.displayLabel or item.name),
            "name=" .. DG111SafeText(item.name),
            "category=" .. DG111SafeText(item.category),
            "rel=" .. DG111SafeText(item.rel),
            "path=" .. DG111SafeText(item.path),
            "ext=" .. DG111SafeText(item.ext),
            "root=" .. DG111SafeText(item.root),
            "isFolder=" .. tostring(item.isFolder == true),
            "isRandom=" .. tostring(item.isRandom == true),
            "cheraxHash=" .. DG111SafeText(item.cheraxListHash),
            "cheraxIndex=" .. DG111SafeText(item.cheraxListIndex),
            "cheraxLabel=" .. DG111SafeText(item.cheraxListLabel),
            "randomTarget=" .. DG111SafeText(item.randomTargetCategory),
            "folderTarget=" .. DG111SafeText(item.folderTarget)
        }, " | ")
    end

    function driftgod.VS_DebugItem(tag, item)
        driftgod.VS_DebugLog(tag or "ITEM", DG111ItemLine(item))
    end

    function driftgod.VS_DebugDumpFiltered(reason, limit)
        limit = tonumber(limit or 80) or 80
        local filtered = driftgod.VS.runtime and driftgod.VS.runtime.filtered or {}
        local names = driftgod.VS.runtime and driftgod.VS.runtime.names or {}
        driftgod.VS_DebugLog("FILTERED_DUMP_BEGIN", "reason=" .. DG111SafeText(reason) .. " | selectedIndex=" .. tostring(driftgod.S.vehicleSpawnerIndex or 0) .. " | filteredCount=" .. tostring(#filtered) .. " | namesCount=" .. tostring(#names) .. " | open=" .. tostring(driftgod.VS.runtime.open == true) .. " | folder=" .. DG111SafeText(driftgod.VS.runtime.currentFolder))
        for i = 1, math.min(#filtered, limit) do
            driftgod.VS_DebugLog("FILTERED_ROW", "row1=" .. tostring(i) .. " | row0=" .. tostring(i - 1) .. " | menuName=" .. DG111SafeText(names[i]) .. " | " .. DG111ItemLine(filtered[i]))
        end
        if #filtered > limit then driftgod.VS_DebugLog("FILTERED_DUMP_TRUNCATED", "remaining=" .. tostring(#filtered - limit)) end
        driftgod.VS_DebugLog("FILTERED_DUMP_END", "reason=" .. DG111SafeText(reason))
    end

    function driftgod.VS_DebugDumpItems(reason, limit)
        limit = tonumber(limit or 200) or 200
        local items = driftgod.VS.runtime and driftgod.VS.runtime.items or {}
        local cats = driftgod.VS.runtime and driftgod.VS.runtime.categories or {}
        driftgod.VS_DebugLog("ITEM_DUMP_BEGIN", "reason=" .. DG111SafeText(reason) .. " | items=" .. tostring(#items) .. " | categories=" .. table.concat(cats, ", "))
        for i = 1, math.min(#items, limit) do
            driftgod.VS_DebugLog("ITEM_ROW", "item1=" .. tostring(i) .. " | item0=" .. tostring(i - 1) .. " | " .. DG111ItemLine(items[i]))
        end
        if #items > limit then driftgod.VS_DebugLog("ITEM_DUMP_TRUNCATED", "remaining=" .. tostring(#items - limit)) end
        driftgod.VS_DebugLog("ITEM_DUMP_END", "reason=" .. DG111SafeText(reason))
    end

    function driftgod.VS_DebugDumpCheraxFeatureLists(reason)
        -- Scan-time only helper. Do not call this during actual load/spawn.
        driftgod.VS_DebugLog("CHERAX_LISTS_BEGIN", "reason=" .. DG111SafeText(reason))
        for _, hash in ipairs(driftgod.VS.CheraxSavedVehicleHashes or {}) do
            local ok, list = DG111Try(function() return FeatureMgr.GetFeatureList(hash) end)
            local count = (ok and type(list) == "table") and #list or 0
            driftgod.VS_DebugLog("CHERAX_LIST", "hash=" .. tostring(hash) .. " | ok=" .. tostring(ok) .. " | count=" .. tostring(count))
            if ok and type(list) == "table" then
                for i, label in ipairs(list) do
                    if i <= 250 then
                        driftgod.VS_DebugLog("CHERAX_LIST_ROW", "hash=" .. tostring(hash) .. " | row1=" .. tostring(i) .. " | row0=" .. tostring(i - 1) .. " | label=" .. DG111SafeText(label))
                    end
                end
                if #list > 250 then driftgod.VS_DebugLog("CHERAX_LIST_TRUNCATED", "hash=" .. tostring(hash) .. " | remaining=" .. tostring(#list - 250)) end
            end
        end
        driftgod.VS_DebugLog("CHERAX_LISTS_END", "reason=" .. DG111SafeText(reason))
    end

    function driftgod.VS_DebugLocalVehicleInfo()
        local info = { ped = 0, vehicle = 0, model = 0, inVehicle = false }
        DG111Try(function()
            info.ped = Natives.InvokeInt(0xD80958FC74E988A6) or 0
            info.vehicle = Natives.InvokeInt(0x9A9112A0FE9A4713, info.ped, false) or 0
            info.inVehicle = info.vehicle ~= 0
            if info.vehicle ~= 0 then info.model = Natives.InvokeInt(0x9F47B058362C84B5, info.vehicle) or 0 end
        end)
        return info
    end

    local function DG111WriteLastLoad(item, extra)
        DG111EnsureLogDir()
        local function q(s) return string.format("%q", tostring(s == nil and "" or s)) end
        local info = driftgod.VS_DebugLocalVehicleInfo()
        local lines = {
            "return {",
            "    savedAt = " .. q(os.date("%Y-%m-%d %H:%M:%S")) .. ",",
            "    ms = " .. tostring(DG111NowMs()) .. ",",
            "    selectedIndex = " .. tostring(tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0) .. ",",
            "    open = " .. tostring(driftgod.VS.runtime.open == true) .. ",",
            "    folder = " .. q(driftgod.VS.runtime.currentFolder) .. ",",
            "    status = " .. q(driftgod.VS.runtime.lastStatus) .. ",",
            "    extra = " .. q(extra) .. ",",
            "    localVehicle = { ped = " .. tostring(info.ped or 0) .. ", vehicle = " .. tostring(info.vehicle or 0) .. ", model = " .. tostring(info.model or 0) .. ", inVehicle = " .. tostring(info.inVehicle == true) .. " },",
            "    item = {",
            "        display = " .. q(type(item) == "table" and (item.displayLabel or item.name) or "") .. ",",
            "        name = " .. q(type(item) == "table" and item.name or "") .. ",",
            "        category = " .. q(type(item) == "table" and item.category or "") .. ",",
            "        rel = " .. q(type(item) == "table" and item.rel or "") .. ",",
            "        path = " .. q(type(item) == "table" and item.path or "") .. ",",
            "        ext = " .. q(type(item) == "table" and item.ext or "") .. ",",
            "        root = " .. q(type(item) == "table" and item.root or "") .. ",",
            "        cheraxListHash = " .. q(type(item) == "table" and item.cheraxListHash or "") .. ",",
            "        cheraxListIndex = " .. q(type(item) == "table" and item.cheraxListIndex or "") .. ",",
            "        cheraxListLabel = " .. q(type(item) == "table" and item.cheraxListLabel or "") .. ",",
            "    },",
            "}"
        }
        DG111Try(function()
            local f = io.open(driftgod.VS.DebugLastLoadFile, "w")
            if f then f:write(table.concat(lines, "\n"), "\n"); f:close() end
        end)
    end

    -- Wrap scan/refresh to record scan roots, Cherax list snapshots, and final map.
    if type(driftgod.VS_Refresh) == "function" and driftgod.R111_VSRefreshWrapped ~= true then
        driftgod.R111_VSRefreshWrapped = true
        local oldRefresh = driftgod.VS_Refresh
        driftgod.VS_Refresh = function(...)
            driftgod.VS_DebugLog("SCAN_BEGIN", "Garage scan requested | currentIndex=" .. tostring(driftgod.S.vehicleSpawnerIndex or 0))
            if driftgod.VS_Roots then
                local okRoots, roots = DG111Try(function() return driftgod.VS_Roots() end)
                if okRoots and type(roots) == "table" then
                    for i, root in ipairs(roots) do driftgod.VS_DebugLog("SCAN_ROOT", "root" .. tostring(i) .. "=" .. DG111SafeText(root)) end
                end
            end
            driftgod.VS_DebugDumpCheraxFeatureLists("before-refresh")
            local ok, result = DG111Try(oldRefresh, ...)
            driftgod.VS_DebugLog("SCAN_RESULT", "ok=" .. tostring(ok) .. " | result=" .. DG111SafeText(result) .. " | items=" .. tostring(#(driftgod.VS.runtime.items or {})) .. " | filtered=" .. tostring(#(driftgod.VS.runtime.filtered or {})) .. " | categories=" .. table.concat(driftgod.VS.runtime.categories or {}, ", "))
            driftgod.VS_DebugDumpItems("after-refresh", 200)
            driftgod.VS_DebugDumpFiltered("after-refresh", 120)
            if not ok then return false end
            return result
        end
    end

    if type(driftgod.VS_Rebuild) == "function" and driftgod.R111_VSRebuildWrapped ~= true then
        driftgod.R111_VSRebuildWrapped = true
        local oldRebuild = driftgod.VS_Rebuild
        driftgod.VS_Rebuild = function(...)
            local before = tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0
            local ok, result = DG111Try(oldRebuild, ...)
            local after = tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0
            if before ~= after or driftgod.VS.runtime.lastRebuildDebugMs == nil or (DG111NowMs() - (tonumber(driftgod.VS.runtime.lastRebuildDebugMs or 0) or 0)) > 2500 then
                driftgod.VS.runtime.lastRebuildDebugMs = DG111NowMs()
                driftgod.VS_DebugLog("REBUILD", "ok=" .. tostring(ok) .. " | beforeIndex=" .. tostring(before) .. " | afterIndex=" .. tostring(after) .. " | open=" .. tostring(driftgod.VS.runtime.open == true) .. " | folder=" .. DG111SafeText(driftgod.VS.runtime.currentFolder) .. " | filtered=" .. tostring(#(driftgod.VS.runtime.filtered or {})) .. " | names=" .. tostring(#(driftgod.VS.runtime.names or {})))
            end
            if not ok then return false end
            return result
        end
    end

    if type(driftgod.VS_Selected) == "function" and driftgod.R111_VSSelectedWrapped ~= true then
        driftgod.R111_VSSelectedWrapped = true
        local oldSelected = driftgod.VS_Selected
        driftgod.VS_Selected = function(...)
            local indexBefore = tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0
            local ok, item = DG111Try(oldSelected, ...)
            driftgod.VS_DebugLog("SELECTED", "ok=" .. tostring(ok) .. " | indexBefore=" .. tostring(indexBefore) .. " | indexAfter=" .. tostring(driftgod.S.vehicleSpawnerIndex or 0) .. " | " .. DG111ItemLine(item))
            if not ok then return nil end
            return item
        end
    end

    if type(driftgod.VS_QueueSelected) == "function" and driftgod.R111_VSQueueWrapped ~= true then
        driftgod.R111_VSQueueWrapped = true
        local oldQueue = driftgod.VS_QueueSelected
        driftgod.VS_QueueSelected = function(...)
            driftgod.VS_DebugLog("QUEUE_REQUEST", "selectedIndex=" .. tostring(driftgod.S.vehicleSpawnerIndex or 0) .. " | open=" .. tostring(driftgod.VS.runtime.open == true) .. " | folder=" .. DG111SafeText(driftgod.VS.runtime.currentFolder))
            local selected = nil
            DG111Try(function() selected = (driftgod.VS.runtime.filtered or {})[(tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0) + 1] end)
            driftgod.VS_DebugItem("QUEUE_ROW_BEFORE_CALL", selected)
            local ok, result = DG111Try(oldQueue, ...)
            local pending = driftgod.VS.runtime and driftgod.VS.runtime.pending and driftgod.VS.runtime.pending.item or nil
            driftgod.VS_DebugLog("QUEUE_RESULT", "ok=" .. tostring(ok) .. " | result=" .. DG111SafeText(result) .. " | pendingAt=" .. DG111SafeText(driftgod.VS.runtime and driftgod.VS.runtime.pending and driftgod.VS.runtime.pending.at) .. " | " .. DG111ItemLine(pending))
            DG111WriteLastLoad(pending or selected, "queued")
            if not ok then return false end
            return result
        end
    end

    if type(driftgod.VS_ProcessPending) == "function" and driftgod.R111_VSProcessWrapped ~= true then
        driftgod.R111_VSProcessWrapped = true
        local oldProcess = driftgod.VS_ProcessPending
        driftgod.VS_ProcessPending = function(...)
            local pending = driftgod.VS.runtime and driftgod.VS.runtime.pending and driftgod.VS.runtime.pending.item or nil
            if pending then driftgod.VS_DebugLog("PROCESS_PENDING_BEGIN", "ageMs=" .. tostring(DG111NowMs() - (tonumber(driftgod.VS.runtime.pending.at or 0) or 0)) .. " | " .. DG111ItemLine(pending)) end
            local ok, result = DG111Try(oldProcess, ...)
            driftgod.VS_DebugLog("PROCESS_PENDING_END", "ok=" .. tostring(ok) .. " | result=" .. DG111SafeText(result) .. " | hasPending=" .. tostring(driftgod.VS.runtime.pending ~= nil))
            if not ok then return false end
            return result
        end
    end

    if type(driftgod.VS_LoadItem) == "function" and driftgod.R111_VSLoadItemWrapped ~= true then
        driftgod.R111_VSLoadItemWrapped = true
        local oldLoadItem = driftgod.VS_LoadItem
        driftgod.VS_LoadItem = function(item, ...)
            driftgod.VS_DebugLog("LOAD_BEGIN", "selectedIndex=" .. tostring(driftgod.S.vehicleSpawnerIndex or 0) .. " | listHash=" .. DG111SafeText(type(item) == "table" and item.cheraxListHash or nil) .. " | listIndex=" .. DG111SafeText(type(item) == "table" and item.cheraxListIndex or nil) .. " | " .. DG111ItemLine(item))
            driftgod.VS_DebugDumpFiltered("before-load", 120)
            DG111WriteLastLoad(item, "before-load")

            local beforeInfo = driftgod.VS_DebugLocalVehicleInfo()
            driftgod.VS_DebugLog("LOAD_BEFORE_LOCAL_VEH", "ped=" .. tostring(beforeInfo.ped) .. " | vehicle=" .. tostring(beforeInfo.vehicle) .. " | model=" .. tostring(beforeInfo.model) .. " | inVehicle=" .. tostring(beforeInfo.inVehicle))

            local ok, result = DG111Try(oldLoadItem, item, ...)
            driftgod.VS_DebugLog("LOAD_CALLBACK_RESULT", "ok=" .. tostring(ok) .. " | result=" .. DG111SafeText(result) .. " | status=" .. DG111SafeText(driftgod.VS.runtime.lastStatus) .. " | lastSpawned=" .. DG111SafeText(driftgod.VS.runtime.lastSpawnedName) .. " | " .. DG111ItemLine(item))

            local afterInfo = driftgod.VS_DebugLocalVehicleInfo()
            driftgod.VS_DebugLog("LOAD_AFTER_LOCAL_VEH", "ped=" .. tostring(afterInfo.ped) .. " | vehicle=" .. tostring(afterInfo.vehicle) .. " | model=" .. tostring(afterInfo.model) .. " | inVehicle=" .. tostring(afterInfo.inVehicle))
            DG111WriteLastLoad(item, "after-load result=" .. tostring(result))

            -- A delayed sample helps if Cherax spawns/puts player into the vehicle one or two frames later.
            if Script and Script.QueueJob then
                Script.QueueJob(function()
                    if Script and Script.Yield then Script.Yield(1000) end
                    local delayed = driftgod.VS_DebugLocalVehicleInfo()
                    driftgod.VS_DebugLog("LOAD_DELAYED_LOCAL_VEH", "ped=" .. tostring(delayed.ped) .. " | vehicle=" .. tostring(delayed.vehicle) .. " | model=" .. tostring(delayed.model) .. " | inVehicle=" .. tostring(delayed.inVehicle) .. " | selected=" .. DG111SafeText(type(item) == "table" and (item.displayLabel or item.name) or "nil"))
                    DG111WriteLastLoad(item, "delayed-check")
                end)
            end

            if not ok then return false end
            return result
        end
    end

    if type(driftgod.VS_PrintStatus) == "function" and driftgod.R111_VSPrintStatusWrapped ~= true then
        driftgod.R111_VSPrintStatusWrapped = true
        local oldPrint = driftgod.VS_PrintStatus
        driftgod.VS_PrintStatus = function(...)
            driftgod.VS_DebugLog("PRINT_STATUS", "manual status requested")
            driftgod.VS_DebugDumpFiltered("manual-status", 120)
            driftgod.VS_DebugDumpItems("manual-status", 200)
            local ok, result = DG111Try(oldPrint, ...)
            if not ok then return false end
            return result
        end
    end

    driftgod.VS_DebugLog("PATCH_LOADED", "v1.0.11 garage deep logs installed | log=" .. DG111SafeText(driftgod.VS.DebugLogFile))
    if driftgod.VS_Toast then driftgod.VS_Toast("Garage debug logging enabled. Reproduce one wrong spawn, then send garage_debug.log.", 4500) end
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.14 garage patch: safe rollback after v1.0.13 Prime crash
-- note: v1.0.12's alternate Saved Vehicles hash crashed Prime, and v1.0.13's raw
--       FileMgr-order loader also crashed in live testing. This build intentionally
--       returns Garage loading to the non-crashing v1.0.10/v1.0.11 Prime-safe staged
--       bridge and keeps the deep diagnostics active. It does not use hash 2597793574
--       and does not calculate raw FileMgr order at load time.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or driftgod or {}
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}

    driftgod.Version = "v1.0.14"
    driftgod.BuildNumber = "2026.07.27.114"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_14_Safe_Garage_Rollback"
    driftgod.__GarageRawOrderDisabled = true
    driftgod.__GarageUnsafePrimeHashDisabled = true

    local function g114_try(fn, ...)
        if type(fn) ~= "function" then return false, "missing function" end
        if driftgod.Try then return driftgod.Try(fn, ...) end
        return pcall(fn, ...)
    end

    local function log(message, important)
        message = "[DriftGod Prime] [Garage v1.0.14] " .. tostring(message or "")
        if important == true and Logger and Logger.LogError then Logger.LogError(message)
        elseif Logger and Logger.LogInfo then Logger.LogInfo(message)
        elseif driftgod.Log then driftgod.Log(message) end
    end

    local function debug(event, detail)
        local line = "V114_" .. tostring(event or "EVENT") .. " | " .. tostring(detail or "")
        if driftgod.VS_DebugLog then g114_try(function() driftgod.VS_DebugLog(line) end) end
        log(line, false)
    end

    -- Clear any stale queue from a previous live reload. Fresh script loads should not
    -- inherit a raw-order or alternate-hash pending record.
    if driftgod.VS and driftgod.VS.runtime then
        if driftgod.VS.runtime.pending and (driftgod.VS.runtime.pending.primeRaw113 == true or driftgod.VS.runtime.pending.primeHash112 == true) then
            driftgod.VS.runtime.pending = nil
        end
        driftgod.VS.runtime.lastStatus = "Garage safe rollback active. Press Scan before loading vehicles."
    end

    if driftgod.__GaragePrimeRawOrder113 then
        driftgod.__GaragePrimeRawOrder113.disabledBy = "v1.0.14_Safe_Garage_Rollback"
        driftgod.__GaragePrimeRawOrder113.busy = false
    end
    if driftgod.__GaragePrimeHashFix then
        driftgod.__GaragePrimeHashFix.disabledBy = "v1.0.14_Safe_Garage_Rollback"
        driftgod.__GaragePrimeHashFix.busy = false
    end
    if driftgod.__GaragePrimeSafeRollback then
        driftgod.__GaragePrimeSafeRollback.patch = "v1.0.14-safe-rollback-via-v1.0.10-v1.0.11"
        driftgod.__GaragePrimeSafeRollback.busy = false
    end

    debug("PATCH_LOADED", "v1.0.12 alternate hash disabled | v1.0.13 raw order disabled | reverted to non-crashing staged Prime bridge with deep logs")
    log("safe rollback installed. Do not use v1.0.12/v1.0.13 for Prime Garage testing.")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.15 garage patch: Production-style Prime Garage bridge
-- note: DriftGod_Production loads the correct saved vehicle by setting the saved
--       vehicle combo index and triggering Cherax Load Vehicle in the same worker
--       pass. v1.0.10/v1.0.11 split those into staged frames, which stayed safe
--       but could let Prime load the wrong saved vehicle. This patch keeps the
--       safe hash 514776905, avoids the crashing 2597793574 hash, avoids raw
--       FileMgr scanning at load time, and ports the Production immediate load
--       flow into Prime with detailed diagnostics.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or driftgod or {}
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or { lastKeys = {}, scroll = 0, inputLockUntil = 0 }

    driftgod.Version = "v1.0.15"
    driftgod.BuildNumber = "2026.07.27.115"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_15_Production_Garage_Bridge"
    driftgod.__GarageProductionBridge115 = driftgod.__GarageProductionBridge115 or {}

    local G115 = driftgod.__GarageProductionBridge115
    G115.loads = tonumber(G115.loads or 0) or 0
    G115.blocked = tonumber(G115.blocked or 0) or 0
    G115.failures = tonumber(G115.failures or 0) or 0
    G115.busy = false

    local SAFE_SAVED_VEHICLE_HASH = 514776905
    local UNSAFE_PRIME_HASH = 2597793574
    local LOAD_VEHICLE_FEATURE_NAME = "Load Vehicle"

    local function g115_try(fn, ...)
        if type(fn) ~= "function" then return false, "missing function" end
        if driftgod.Try then return driftgod.Try(fn, ...) end
        return pcall(fn, ...)
    end

    local function now_ms()
        if driftgod.VS_Now then
            local ok, ms = g115_try(driftgod.VS_Now)
            if ok and ms then return tonumber(ms) or math.floor((os.clock and os.clock() or 0) * 1000) end
        end
        if Time and Time.GetEpocheMs then
            local ok, ms = g115_try(Time.GetEpocheMs)
            if ok and ms then return tonumber(ms) or math.floor((os.clock and os.clock() or 0) * 1000) end
        end
        return math.floor((os.clock and os.clock() or 0) * 1000)
    end

    local function safe_text(v)
        local s = tostring(v == nil and "nil" or v)
        s = s:gsub("[\r\n]+", " ")
        if #s > 700 then s = s:sub(1, 700) .. "..." end
        return s
    end

    local function log(message, important)
        message = "[DriftGod Prime] [Garage v1.0.15] " .. tostring(message or "")
        if important == true and Logger and Logger.LogError then Logger.LogError(message)
        elseif Logger and Logger.LogInfo then Logger.LogInfo(message)
        elseif driftgod.Log then driftgod.Log(message) end
    end

    local function debug(event, detail)
        local line = "V115_" .. tostring(event or "EVENT") .. " | " .. tostring(detail or "")
        if driftgod.VS_DebugLog then g115_try(function() driftgod.VS_DebugLog(line) end) end
        log(line, false)
    end

    local function toast(message, ms)
        if driftgod.VS_Toast then g115_try(driftgod.VS_Toast, tostring(message or ""), tonumber(ms or 2500) or 2500)
        elseif driftgod.Toast then g115_try(driftgod.Toast, tostring(message or ""), tonumber(ms or 2500) or 2500)
        elseif GUI and GUI.AddToast then g115_try(function() GUI.AddToast("DriftGod", tostring(message or ""), tonumber(ms or 2500) or 2500) end) end
    end

    local function normalize(path)
        return tostring(path or ""):gsub("/", "\\")
    end

    local function item_line(item)
        if type(item) ~= "table" then return "item=nil" end
        return table.concat({
            "display=" .. safe_text(item.displayLabel or item.name),
            "name=" .. safe_text(item.name),
            "category=" .. safe_text(item.category),
            "rel=" .. safe_text(item.rel),
            "path=" .. safe_text(item.path),
            "hash=" .. safe_text(item.cheraxListHash),
            "cheraxIndex=" .. safe_text(item.cheraxListIndex),
            "prodIndex=" .. safe_text(item.productionSortedIndex),
            "p21Root=" .. safe_text(item.cheraxIndexRoot),
            "folder=" .. tostring(item.isFolder == true),
            "random=" .. tostring(item.isRandom == true)
        }, " | ")
    end

    local function copy_item(item)
        if type(item) ~= "table" then return item end
        local out = {}
        for k, v in pairs(item) do out[k] = v end
        return out
    end

    local function selected_no_rebuild()
        if not (driftgod.VS and driftgod.VS.runtime) then return nil end
        local filtered = driftgod.VS.runtime.filtered or {}
        local idx = math.floor(tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0)
        if idx < 0 then idx = 0 end
        if idx > #filtered - 1 then idx = #filtered - 1 end
        driftgod.S.vehicleSpawnerIndex = idx
        return filtered[idx + 1]
    end

    local function choose_random_item(category)
        if not (driftgod.VS and driftgod.VS.runtime) then return nil end
        local target = tostring(category or "All")
        local pool = {}
        for _, candidate in ipairs(driftgod.VS.runtime.items or {}) do
            if type(candidate) == "table" and not candidate.isFolder and not candidate.isRandom then
                if target == "All" or tostring(candidate.category or "Root"):lower() == target:lower() then
                    pool[#pool + 1] = candidate
                end
            end
        end
        if #pool <= 0 then return nil end
        return pool[math.random(1, #pool)]
    end

    local function attach_production_sorted_indices(reason)
        if not (driftgod.VS and driftgod.VS.runtime and type(driftgod.VS.runtime.items) == "table") then return 0 end
        if not (driftgod.VS_Roots and driftgod.VS_FindFiles and driftgod.VS_Normalize) then return 0 end

        local jsons, seen = {}, {}
        for _, root in ipairs(driftgod.VS_Roots() or {}) do
            for _, f in ipairs(driftgod.VS_FindFiles(root, { "json" }) or {}) do
                local path = normalize(f)
                if path ~= "" and path:lower():match("%.json$") then
                    local key = path:lower()
                    if not seen[key] then
                        seen[key] = true
                        jsons[#jsons + 1] = path
                    end
                end
            end
        end
        table.sort(jsons, function(a, b) return tostring(a):lower() < tostring(b):lower() end)

        local indexByPath = {}
        for i, path in ipairs(jsons) do
            indexByPath[normalize(path):lower()] = i - 1
        end

        local mapped = 0
        for _, item in ipairs(driftgod.VS.runtime.items or {}) do
            if type(item) == "table" and tostring(item.path or ""):lower():match("%.json$") then
                local idx = indexByPath[normalize(item.path):lower()]
                if idx ~= nil then
                    item.productionSortedIndex = idx
                    mapped = mapped + 1
                end
            end
        end

        G115.productionOrderCount = #jsons
        G115.productionMapped = mapped
        debug("ATTACH_PRODUCTION_INDICES", "reason=" .. tostring(reason or "manual")
            .. " | mapped=" .. tostring(mapped)
            .. "/" .. tostring(#(driftgod.VS.runtime.items or {}))
            .. " | productionOrder=" .. tostring(#jsons))
        return mapped
    end

    if type(driftgod.VS_Refresh) == "function" and G115.refreshWrapped ~= true then
        G115.refreshWrapped = true
        local previousRefresh = driftgod.VS_Refresh
        driftgod.VS_Refresh = function(...)
            local result = previousRefresh(...)
            g115_try(function() attach_production_sorted_indices("after-refresh") end)
            return result
        end
        driftgod.R153_ScanVehicleSpawner = driftgod.VS_Refresh
        driftgod.R154_RefreshSpawner = driftgod.VS_Refresh
        driftgod.R115_ScanSpawnerVehicles = driftgod.VS_Refresh
        driftgod.R114_ScanSpawnerVehicles = driftgod.VS_Refresh
    end

    -- Production fallback indices are attached after manual Scan/Refresh only.
    -- Do not run FileMgr discovery during script load on Prime.

    local function resolve_index(item)
        if type(item) ~= "table" then return nil, "No Garage vehicle selected." end
        if item.isRandom then
            local picked = choose_random_item(item.randomTargetCategory or "All")
            if not picked then return nil, "No mapped saved vehicles are available for Random." end
            item = copy_item(picked)
        else
            item = copy_item(item)
        end

        if item.isFolder then
            return { item = item, folder = true }, nil
        end

        local path = normalize(item.path or "")
        if path == "" or not path:lower():match("%.json$") then
            return nil, "Only JSON Cherax saved vehicles are supported by Prime Garage loading."
        end

        -- Match DriftGod_Production's primary behavior: trust the scan-time Cherax
        -- saved vehicle index first, then use its sorted-JSON fallback only if the
        -- primary index is absent. Do not query FeatureMgr lists or FileMgr raw order
        -- during load.
        local index = tonumber(item.cheraxListIndex)
        local source = "cheraxListIndex"

        if index == nil then
            index = tonumber(item.productionSortedIndex)
            source = "productionSortedIndex"
        end

        if index == nil and driftgod.__PrimeGarageP21 and type(driftgod.__PrimeGarageP21.cheraxIndexByPath) == "table" then
            index = tonumber(driftgod.__PrimeGarageP21.cheraxIndexByPath[path:lower()])
            source = "P21CheraxIndexByPath"
        end

        if index == nil then
            return nil, "No saved-vehicle index is ready. Press Scan, then try again."
        end
        index = math.floor(index)
        if index < 0 then return nil, "Invalid saved-vehicle index." end

        local itemHash = tonumber(item.cheraxListHash)
        local hash = SAFE_SAVED_VEHICLE_HASH
        if itemHash and itemHash ~= SAFE_SAVED_VEHICLE_HASH then
            debug("UNSAFE_HASH_IGNORED", "itemHash=" .. tostring(itemHash) .. " | forcedHash=" .. tostring(SAFE_SAVED_VEHICLE_HASH))
        end
        if itemHash == SAFE_SAVED_VEHICLE_HASH then hash = itemHash end

        return {
            item = item,
            hash = hash,
            unsafeHash = UNSAFE_PRIME_HASH,
            index = index,
            indexSource = source,
            path = path,
            label = tostring(item.displayLabel or item.name or path),
            cheraxIndex = tonumber(item.cheraxListIndex),
            productionSortedIndex = tonumber(item.productionSortedIndex),
        }, nil
    end

    local function block(reason, ms)
        G115.blocked = (tonumber(G115.blocked or 0) or 0) + 1
        G115.lastBlocked = tostring(reason or "blocked")
        if driftgod.VS and driftgod.VS.runtime then
            driftgod.VS.runtime.lastStatus = "Garage blocked: " .. tostring(reason or "unknown")
        end
        debug("BLOCKED", tostring(reason or "unknown"))
        log("load blocked: " .. tostring(reason or "unknown"), true)
        toast(tostring(reason or "Garage load blocked."), tonumber(ms or 3000) or 3000)
        return false
    end

    local function set_runtime_loaded(item, resolved)
        if not (driftgod.VS and driftgod.VS.runtime) then return end
        driftgod.VS.runtime.pending = nil
        driftgod.VS.runtime.lastSpawnedName = tostring(item.displayLabel or item.name or resolved.label or "Saved Vehicle")
        driftgod.VS.runtime.lastSpawnedModel = "Cherax Saved Vehicle"
        driftgod.VS.runtime.lastSpawnedHandle = 0
        driftgod.VS.runtime.spawnCount = (tonumber(driftgod.VS.runtime.spawnCount or 0) or 0) + 1
        driftgod.VS.runtime.lastStatus = "Loaded " .. tostring(driftgod.VS.runtime.lastSpawnedName)
    end

    local function load_now(item, queuedAt)
        local resolved, reason = resolve_index(item)
        if not resolved then return block(reason or "Garage mapping failed.", 3500) end
        if resolved.folder == true then
            local folderItem = resolved.item
            driftgod.VS.runtime.currentFolder = folderItem.folderTarget or folderItem.category
            driftgod.S.vehicleSpawnerIndex = 0
            driftgod.VS.hud.scroll = 0
            if driftgod.VS_Rebuild then g115_try(function() driftgod.VS_Rebuild(true) end) end
            return true
        end

        item = resolved.item or item
        debug("PRODUCTION_LOAD_BEGIN", "queuedAgeMs=" .. tostring(now_ms() - (tonumber(queuedAt or now_ms()) or now_ms()))
            .. " | hash=" .. tostring(resolved.hash)
            .. " | index=" .. tostring(resolved.index)
            .. " | source=" .. tostring(resolved.indexSource)
            .. " | selected=" .. safe_text(resolved.label)
            .. " | path=" .. safe_text(resolved.path)
            .. " | cheraxIndex=" .. safe_text(resolved.cheraxIndex)
            .. " | prodIndex=" .. safe_text(resolved.productionSortedIndex))

        if not (FeatureMgr and FeatureMgr.SetFeatureListIndex) then return block("FeatureMgr.SetFeatureListIndex missing", 3500) end
        if not (FeatureMgr and FeatureMgr.GetFeatureByName) then return block("FeatureMgr.GetFeatureByName missing", 3500) end

        -- Production-critical behavior: set selected index and trigger Load Vehicle
        -- immediately in the same worker pass. Do not split this across staged frames.
        local okSet, errSet = g115_try(function()
            FeatureMgr.SetFeatureListIndex(resolved.hash, resolved.index)
        end)
        if not okSet then
            G115.failures = G115.failures + 1
            return block("SetFeatureListIndex failed: " .. tostring(errSet), 3500)
        end

        local loadFeature = nil
        local okResolve, errResolve = g115_try(function()
            loadFeature = FeatureMgr.GetFeatureByName((driftgod.VS and driftgod.VS.LoadVehicleFeatureName) or LOAD_VEHICLE_FEATURE_NAME)
        end)
        if not okResolve or not loadFeature then
            G115.failures = G115.failures + 1
            return block("Load Vehicle feature not found: " .. tostring(errResolve), 3500)
        end
        if not loadFeature.TriggerCallback then
            G115.failures = G115.failures + 1
            return block("Load Vehicle feature has no TriggerCallback", 3500)
        end

        local okTrigger, errTrigger = g115_try(function() loadFeature:TriggerCallback() end)
        if not okTrigger then
            G115.failures = G115.failures + 1
            return block("Load Vehicle callback failed: " .. tostring(errTrigger), 3500)
        end

        G115.loads = G115.loads + 1
        G115.busy = false
        set_runtime_loaded(item, resolved)
        G115.lastResolved = "loaded hash=" .. tostring(resolved.hash)
            .. " index=" .. tostring(resolved.index)
            .. " source=" .. tostring(resolved.indexSource)
            .. " label=" .. tostring(resolved.label)
        debug("PRODUCTION_LOAD_TRIGGERED", G115.lastResolved)
        log("loaded through Production-style immediate bridge | label=" .. tostring(driftgod.VS.runtime.lastSpawnedName)
            .. " | hash=" .. tostring(resolved.hash)
            .. " | index=" .. tostring(resolved.index)
            .. " | source=" .. tostring(resolved.indexSource))
        toast("Loaded " .. tostring(driftgod.VS.runtime.lastSpawnedName), 2500)
        return true
    end

    function driftgod.DG115_CurrentGarageSelectionNoRebuild()
        return selected_no_rebuild()
    end

    function driftgod.VS_Selected()
        return selected_no_rebuild()
    end

    function driftgod.VS_LoadItem(item, ...)
        -- Direct internal load path. Public UI buttons should still queue first.
        return load_now(item, now_ms())
    end

    function driftgod.R154_QueueItem(item)
        if not item then return block("No Garage vehicle selected.", 2500) end
        item = copy_item(item)

        if item.isFolder then
            return load_now(item, now_ms())
        end

        if G115.busy == true or (driftgod.VS.runtime and driftgod.VS.runtime.pending and driftgod.VS.runtime.pending.productionBridge115 == true) then
            return block("Garage load is already queued. Wait a moment.", 2500)
        end

        local resolved, reason = resolve_index(item)
        if not resolved then return block(reason or "Garage mapping failed.", 3500) end
        if resolved.folder == true then return load_now(item, now_ms()) end

        G115.busy = true
        driftgod.VS.runtime.pending = {
            productionBridge115 = true,
            item = item,
            at = now_ms() + 50,
            queuedAt = now_ms(),
        }
        driftgod.VS.runtime.lastStatus = "Queued " .. tostring(item.displayLabel or item.name or "vehicle")
        debug("QUEUE", "selectedIndex=" .. tostring(driftgod.S.vehicleSpawnerIndex or 0)
            .. " | hash=" .. tostring(resolved.hash)
            .. " | index=" .. tostring(resolved.index)
            .. " | source=" .. tostring(resolved.indexSource)
            .. " | " .. item_line(item))
        if driftgod.R154_InstallVehicleSpawnerWorker then g115_try(driftgod.R154_InstallVehicleSpawnerWorker) end
        return true
    end

    function driftgod.R154_QueueSelected()
        local item = selected_no_rebuild()
        if not item then return block("No Garage vehicle selected.", 2500) end
        return driftgod.R154_QueueItem(item)
    end

    function driftgod.VS_QueueSelected()
        return driftgod.R154_QueueSelected()
    end

    function driftgod.VS_LoadSelected()
        return driftgod.R154_QueueSelected()
    end

    function driftgod.VS_ProcessPending()
        if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.pending) then return end
        local pending = driftgod.VS.runtime.pending

        if pending.productionBridge115 ~= true then
            local legacyItem = pending.item
            driftgod.VS.runtime.pending = nil
            G115.busy = false
            if legacyItem then return driftgod.R154_QueueItem(legacyItem) end
            return
        end

        if now_ms() < (tonumber(pending.at or 0) or 0) then return end
        local item = pending.item
        local queuedAt = pending.queuedAt or pending.at or now_ms()
        driftgod.VS.runtime.pending = nil
        local result = load_now(item, queuedAt)
        G115.busy = false
        return result
    end

    function driftgod.R154_ProcessVehicleSpawnerPending()
        return driftgod.VS_ProcessPending()
    end

    -- Clear stale staged/raw/alternate pending records from earlier crash-test builds.
    if driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.pending then
        local p = driftgod.VS.runtime.pending
        if p.primeSafe110 == true or p.primeHash112 == true or p.primeRaw113 == true then
            driftgod.VS.runtime.pending = nil
        end
    end
    if driftgod.__GaragePrimeSafeRollback then driftgod.__GaragePrimeSafeRollback.busy = false end
    if driftgod.__GaragePrimeHashFix then driftgod.__GaragePrimeHashFix.busy = false end
    if driftgod.__GaragePrimeRawOrder113 then driftgod.__GaragePrimeRawOrder113.busy = false end

    if type(driftgod.VS_PrintStatus) == "function" and G115.printWrapped ~= true then
        G115.printWrapped = true
        local previousPrintStatus = driftgod.VS_PrintStatus
        driftgod.VS_PrintStatus = function(...)
            local result = previousPrintStatus(...)
            log("Production bridge status | loads=" .. tostring(G115.loads)
                .. " | blocked=" .. tostring(G115.blocked)
                .. " | failures=" .. tostring(G115.failures)
                .. " | productionMapped=" .. tostring(G115.productionMapped)
                .. " | productionOrder=" .. tostring(G115.productionOrderCount)
                .. " | lastResolved=" .. tostring(G115.lastResolved)
                .. " | lastBlocked=" .. tostring(G115.lastBlocked))
            return result
        end
    end

    debug("PATCH_LOADED", "Production-style immediate Garage bridge installed | safeHash=" .. tostring(SAFE_SAVED_VEHICLE_HASH) .. " | unsafeHashBlocked=" .. tostring(UNSAFE_PRIME_HASH))
    log("patch installed | Garage now mirrors DriftGod_Production set-index + immediate Load Vehicle trigger")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.16 garage patch: Prime safe-list label resolver
-- note: v1.0.15 proved the selected DriftGod row was correct, but the stored
--       P21/Cherax index was shifted. This patch stops trusting scan/raw indices
--       for loading and resolves the selected file name against the live safe
--       Saved Vehicles list hash only: 514776905. It avoids the Prime-crashing
--       alternate hash and avoids raw FileMgr load-time order probing.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or driftgod or {}
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or {}

    driftgod.Version = "v1.0.16"
    driftgod.BuildNumber = "2026.07.27.116"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_16_Prime_Garage_Safe_List_Match"

    driftgod.__GarageSafeListMatch116 = driftgod.__GarageSafeListMatch116 or {
        patch = "v1.0.16",
        loads = 0,
        blocked = 0,
        failures = 0,
        exactMapped = 0,
        safeListCount = 0,
        lastResolved = "None",
        lastBlocked = "None",
        busy = false,
    }
    local G116 = driftgod.__GarageSafeListMatch116

    local SAFE_HASH = 514776905
    local BLOCKED_HASH = 2597793574
    local LOAD_FEATURE = "Load Vehicle"

    local function tcall(fn, ...)
        if type(fn) ~= "function" then return false, "missing function" end
        if driftgod.Try then return driftgod.Try(fn, ...) end
        return pcall(fn, ...)
    end

    local function now_ms()
        local ok, v = tcall(function()
            if Time and Time.GetEpocheMs then return Time.GetEpocheMs() end
            return nil
        end)
        if ok and tonumber(v) then return tonumber(v) end
        return math.floor((tonumber(os.clock and os.clock() or 0) or 0) * 1000)
    end

    local function log_line(tag, msg, important)
        local full = "[DriftGod Prime] [Garage v1.0.16] " .. tostring(tag or "LOG") .. " | " .. tostring(msg or "")
        if important == true and Logger and Logger.LogError then Logger.LogError(full)
        elseif Logger and Logger.LogInfo then Logger.LogInfo(full)
        elseif driftgod.Log then driftgod.Log(full) end
        if driftgod.VS_DebugLog then tcall(function() driftgod.VS_DebugLog("V116_" .. tostring(tag or "LOG"), tostring(msg or "")) end) end
    end

    local function toast(msg, ms)
        if driftgod.VS_Toast then tcall(driftgod.VS_Toast, tostring(msg or ""), tonumber(ms or 2500) or 2500)
        elseif driftgod.Toast then tcall(driftgod.Toast, tostring(msg or ""), tonumber(ms or 2500) or 2500)
        elseif GUI and GUI.AddToast then tcall(function() GUI.AddToast("DriftGod", tostring(msg or ""), tonumber(ms or 2500) or 2500, eToastPos and (eToastPos.TOP_RIGHT or eToastPos.TopRight) or 2) end) end
    end

    local function trim(s)
        return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "")
    end

    local function normalize_path(path)
        path = tostring(path or ""):gsub("/", "\\")
        path = path:gsub("\\+", "\\")
        while #path > 3 and path:sub(-1) == "\\" do path = path:sub(1, -2) end
        return path
    end

    local function strip_json(text)
        return tostring(text or ""):gsub("%.[Jj][Ss][Oo][Nn]$", "")
    end

    local function file_leaf(path)
        local p = normalize_path(path)
        return p:match("([^\\]+)$") or p
    end

    local function key_text(text)
        text = trim(text)
        text = text:gsub("/", "\\"):gsub(">", "\\")
        text = text:gsub("%s*\\%s*", "\\")
        text = text:gsub("\\+", "\\")
        text = strip_json(text)
        text = trim(text)
        return text:lower()
    end

    local function decode_feature_list(list)
        local out = {}
        local seen = {}
        local function add(v)
            local s = trim(v)
            if s == "" then return end
            local k = s .. "##" .. tostring(#out + 1)
            if not seen[k] then
                seen[k] = true
                out[#out + 1] = s
            end
        end
        if type(list) == "table" then
            for _, v in ipairs(list) do add(v) end
            if #out == 0 then for _, v in pairs(list) do add(v) end end
        end
        return out
    end

    local function add_match(map, rawKey, entry)
        local k = key_text(rawKey)
        if k == "" then return end
        map[k] = map[k] or {}
        -- Avoid duplicate entries for labels where the full label, filename,
        -- and leaf normalize to the same key. Duplicate self-matches would
        -- incorrectly look ambiguous.
        for _, existing in ipairs(map[k]) do
            if tonumber(existing.hash) == tonumber(entry.hash) and tonumber(existing.index) == tonumber(entry.index) then
                return
            end
        end
        map[k][#map[k] + 1] = entry
    end

    local function split_label(label)
        local n = normalize_path(label)
        local leaf = n:match("([^\\]+)$") or n
        local cat = n:match("^(.*)\\[^\\]+$") or ""
        return strip_json(trim(cat)), strip_json(trim(leaf))
    end

    local function read_safe_saved_vehicle_list()
        if not (FeatureMgr and FeatureMgr.GetFeatureList) then return {}, "FeatureMgr.GetFeatureList missing" end
        local ok, list = tcall(function() return FeatureMgr.GetFeatureList(SAFE_HASH) end)
        if not ok then return {}, tostring(list) end
        return decode_feature_list(list), nil
    end

    local function build_safe_map(reason)
        local list, err = read_safe_saved_vehicle_list()
        local map = {}
        for i, label in ipairs(list or {}) do
            local entry = { hash = SAFE_HASH, index = i - 1, label = tostring(label or "") }
            local cat, leaf = split_label(label)
            add_match(map, label, entry)
            add_match(map, leaf, entry)
            add_match(map, file_leaf(label), entry)
            if cat ~= "" then
                add_match(map, cat .. "\\" .. leaf, entry)
                add_match(map, cat .. " / " .. leaf, entry)
            end
        end
        G116.safeList = list or {}
        G116.safeMap = map
        G116.safeListCount = #(list or {})
        G116.lastMapError = err
        log_line("SAFE_LIST_MAP", "reason=" .. tostring(reason or "manual")
            .. " | safeHash=" .. tostring(SAFE_HASH)
            .. " | labels=" .. tostring(G116.safeListCount)
            .. " | err=" .. tostring(err or "nil"))
        return map, list
    end

    local function add_candidate(out, seen, raw, source)
        raw = trim(raw)
        if raw == "" then return end
        local k = key_text(raw)
        if k == "" or seen[k] then return end
        seen[k] = true
        out[#out + 1] = { raw = raw, key = k, source = source or "candidate" }
    end

    local function candidates_for_item(item)
        local out, seen = {}, {}
        if type(item) ~= "table" then return out end
        local path = normalize_path(item.path or "")
        local rel = normalize_path(item.rel or "")
        local name = strip_json(trim(item.name or ""))
        local file = strip_json(file_leaf(path))
        if name == "" then name = file end
        local category = trim(item.category or "")

        add_candidate(out, seen, item.cheraxListLabel, "stored-label")
        add_candidate(out, seen, item.displayLabel, "display-label")
        add_candidate(out, seen, rel, "relative-path")
        add_candidate(out, seen, rel:gsub("\\", " / "), "relative-display")
        if category ~= "" and category ~= "Root" and category ~= "All" then
            add_candidate(out, seen, category .. "\\" .. name, "category-name")
            add_candidate(out, seen, category .. " / " .. name, "category-display")
        end
        add_candidate(out, seen, name, "name")
        add_candidate(out, seen, file, "filename")
        return out
    end

    local function around_list(index)
        local list = G116.safeList or {}
        index = tonumber(index or 0) or 0
        local parts = {}
        for i = math.max(0, index - 2), math.min(#list - 1, index + 2) do
            parts[#parts + 1] = tostring(i) .. "=" .. tostring(list[i + 1] or "")
        end
        return table.concat(parts, " || ")
    end

    local function resolve_safe_item(item, reason)
        if type(item) ~= "table" then return nil, "No Garage vehicle selected." end
        if item.isFolder then return { item = item, folder = true }, nil end

        local map = G116.safeMap
        if type(map) ~= "table" or G116.safeListCount <= 0 then
            map = build_safe_map(reason or "resolve")
        end

        local candidates = candidates_for_item(item)
        local tried = {}
        for _, c in ipairs(candidates) do
            tried[#tried + 1] = tostring(c.source) .. "=" .. tostring(c.raw)
            local matches = map[c.key] or {}
            if #matches == 1 then
                local m = matches[1]
                if tostring(reason or "") ~= "annotate" then
                    log_line("SAFE_LIST_MATCH", "reason=" .. tostring(reason or "load")
                        .. " | selected=" .. tostring(item.displayLabel or item.name or item.path)
                        .. " | candidateSource=" .. tostring(c.source)
                        .. " | candidate=" .. tostring(c.raw)
                        .. " | safeHash=" .. tostring(SAFE_HASH)
                        .. " | safeIndex=" .. tostring(m.index)
                        .. " | safeLabel=" .. tostring(m.label)
                        .. " | oldP21Index=" .. tostring(item.cheraxListIndex)
                        .. " | nearby=" .. around_list(m.index))
                end
                return {
                    item = item,
                    hash = SAFE_HASH,
                    index = tonumber(m.index),
                    label = tostring(m.label or ""),
                    source = "safe-list:" .. tostring(c.source),
                    oldIndex = tonumber(item.cheraxListIndex),
                    oldHash = tonumber(item.cheraxListHash),
                }, nil
            elseif #matches > 1 then
                return nil, "Ambiguous safe-list match for " .. tostring(c.raw) .. " (" .. tostring(#matches) .. " matches)."
            end
        end

        return nil, "No safe-list match in hash " .. tostring(SAFE_HASH) .. ". Tried: " .. table.concat(tried, " ; ")
    end

    local function annotate_items(reason)
        local map = build_safe_map(reason or "annotate")
        local mapped = 0
        for _, item in ipairs((driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.items) or {}) do
            if type(item) == "table" and not item.isFolder and not item.isRandom then
                local resolved = resolve_safe_item(item, "annotate")
                if resolved and resolved.index ~= nil then
                    item.primeSafeListHash = SAFE_HASH
                    item.primeSafeListIndex = resolved.index
                    item.primeSafeListLabel = resolved.label
                    item.cheraxListHash = SAFE_HASH
                    item.cheraxListIndex = resolved.index
                    item.cheraxListLabel = resolved.label
                    mapped = mapped + 1
                end
            end
        end
        G116.exactMapped = mapped
        log_line("ANNOTATE_DONE", "reason=" .. tostring(reason or "manual")
            .. " | mapped=" .. tostring(mapped)
            .. "/" .. tostring(#((driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.items) or {}))
            .. " | safeList=" .. tostring(G116.safeListCount))
        return mapped
    end

    local function block(reason, ms)
        G116.blocked = (tonumber(G116.blocked or 0) or 0) + 1
        G116.lastBlocked = tostring(reason or "blocked")
        if driftgod.VS and driftgod.VS.runtime then driftgod.VS.runtime.lastStatus = "Garage blocked: " .. tostring(reason or "unknown") end
        log_line("BLOCKED", tostring(reason or "unknown"), true)
        toast(tostring(reason or "Garage load blocked."), tonumber(ms or 3000) or 3000)
        return false
    end

    local function selected_no_rebuild()
        if not (driftgod.VS and driftgod.VS.runtime) then return nil end
        local filtered = driftgod.VS.runtime.filtered or {}
        local idx = math.floor(tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0)
        if idx < 0 then idx = 0 end
        if idx > #filtered - 1 then idx = #filtered - 1 end
        driftgod.S.vehicleSpawnerIndex = idx
        return filtered[idx + 1]
    end

    local function copy_item(item)
        if type(item) ~= "table" then return item end
        local out = {}
        for k, v in pairs(item) do out[k] = v end
        return out
    end

    local function choose_random_item(category)
        local pool = {}
        local target = tostring(category or "All")
        for _, candidate in ipairs((driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.items) or {}) do
            if type(candidate) == "table" and not candidate.isFolder and not candidate.isRandom then
                if target == "All" or tostring(candidate.category or "Root"):lower() == target:lower() then pool[#pool + 1] = candidate end
            end
        end
        if #pool <= 0 then return nil end
        return pool[math.random(1, #pool)]
    end

    local function load_now(item, queuedAt)
        if type(item) ~= "table" then return block("No Garage vehicle selected.", 2500) end
        item = copy_item(item)

        if item.isRandom then
            item = choose_random_item(item.randomTargetCategory or "All")
            if not item then return block("No vehicles available for Random.", 2500) end
            item = copy_item(item)
        end

        if item.isFolder then
            driftgod.VS.runtime.currentFolder = item.folderTarget or item.category
            driftgod.S.vehicleSpawnerIndex = 0
            driftgod.VS.hud.scroll = 0
            if driftgod.VS_Rebuild then tcall(function() driftgod.VS_Rebuild(true) end) end
            return true
        end

        local resolved, reason = resolve_safe_item(item, "load")
        if not resolved then return block(reason or "Could not resolve selected vehicle in safe list.", 4500) end
        if resolved.hash == BLOCKED_HASH then return block("Blocked unsafe Prime Garage hash " .. tostring(BLOCKED_HASH), 4500) end

        log_line("LOAD_BEGIN", "queuedAgeMs=" .. tostring(now_ms() - (tonumber(queuedAt or now_ms()) or now_ms()))
            .. " | selected=" .. tostring(item.displayLabel or item.name or item.path)
            .. " | safeHash=" .. tostring(resolved.hash)
            .. " | safeIndex=" .. tostring(resolved.index)
            .. " | safeLabel=" .. tostring(resolved.label)
            .. " | source=" .. tostring(resolved.source)
            .. " | oldIndex=" .. tostring(resolved.oldIndex)
            .. " | oldHash=" .. tostring(resolved.oldHash))

        if not (FeatureMgr and FeatureMgr.SetFeatureListIndex) then return block("FeatureMgr.SetFeatureListIndex missing", 3500) end
        if not (FeatureMgr and FeatureMgr.GetFeatureByName) then return block("FeatureMgr.GetFeatureByName missing", 3500) end

        local okSet, errSet = tcall(function() FeatureMgr.SetFeatureListIndex(SAFE_HASH, resolved.index) end)
        if not okSet then
            G116.failures = (tonumber(G116.failures or 0) or 0) + 1
            return block("SetFeatureListIndex failed on safe hash: " .. tostring(errSet), 4500)
        end

        local loadFeature = nil
        local okFeature, errFeature = tcall(function()
            loadFeature = FeatureMgr.GetFeatureByName((driftgod.VS and driftgod.VS.LoadVehicleFeatureName) or LOAD_FEATURE)
        end)
        if not okFeature or not loadFeature then
            G116.failures = (tonumber(G116.failures or 0) or 0) + 1
            return block("Load Vehicle feature not found: " .. tostring(errFeature), 3500)
        end
        if not loadFeature.TriggerCallback then return block("Load Vehicle feature has no TriggerCallback", 3500) end

        local okTrigger, errTrigger = tcall(function() loadFeature:TriggerCallback() end)
        if not okTrigger then
            G116.failures = (tonumber(G116.failures or 0) or 0) + 1
            return block("Load Vehicle callback failed: " .. tostring(errTrigger), 4500)
        end

        G116.loads = (tonumber(G116.loads or 0) or 0) + 1
        G116.busy = false
        G116.lastResolved = "safeHash=" .. tostring(SAFE_HASH)
            .. " safeIndex=" .. tostring(resolved.index)
            .. " safeLabel=" .. tostring(resolved.label)
            .. " source=" .. tostring(resolved.source)
        if driftgod.VS and driftgod.VS.runtime then
            driftgod.VS.runtime.pending = nil
            driftgod.VS.runtime.lastSpawnedName = tostring(item.displayLabel or item.name or resolved.label or "Saved Vehicle")
            driftgod.VS.runtime.lastSpawnedModel = "Cherax Saved Vehicle"
            driftgod.VS.runtime.lastSpawnedHandle = 0
            driftgod.VS.runtime.spawnCount = (tonumber(driftgod.VS.runtime.spawnCount or 0) or 0) + 1
            driftgod.VS.runtime.lastStatus = "Loaded " .. tostring(driftgod.VS.runtime.lastSpawnedName)
        end
        log_line("LOAD_TRIGGERED", G116.lastResolved)
        toast("Loaded " .. tostring(item.displayLabel or item.name or resolved.label or "Saved Vehicle"), 2500)
        return true
    end

    if type(driftgod.VS_Refresh) == "function" and G116.refreshWrapped ~= true then
        G116.refreshWrapped = true
        local previousRefresh = driftgod.VS_Refresh
        driftgod.VS_Refresh = function(...)
            local result = previousRefresh(...)
            tcall(function() annotate_items("after-scan") end)
            if driftgod.VS_SyncFeatures then tcall(function() driftgod.VS_SyncFeatures() end) end
            return result
        end
        driftgod.VS_PrimeRootJsonRefresh = driftgod.VS_Refresh
        driftgod.VS_PrimeSafeDiskRefresh = driftgod.VS_Refresh
        driftgod.R153_ScanVehicleSpawner = driftgod.VS_Refresh
        driftgod.R154_RefreshSpawner = driftgod.VS_Refresh
        driftgod.R115_ScanSpawnerVehicles = driftgod.VS_Refresh
        driftgod.R114_ScanSpawnerVehicles = driftgod.VS_Refresh
    end

    function driftgod.DG116_CurrentGarageSelectionNoRebuild()
        return selected_no_rebuild()
    end

    function driftgod.VS_Selected()
        return selected_no_rebuild()
    end

    function driftgod.VS_LoadItem(item, ...)
        return load_now(item, now_ms())
    end

    function driftgod.R154_QueueItem(item)
        if not item then return block("No Garage vehicle selected.", 2500) end
        item = copy_item(item)
        if item.isFolder then return load_now(item, now_ms()) end
        if G116.busy == true or (driftgod.VS.runtime and driftgod.VS.runtime.pending and driftgod.VS.runtime.pending.safeList116 == true) then
            return block("Garage load is already queued. Wait a moment.", 2500)
        end
        local resolved, reason = resolve_safe_item(item, "queue")
        if not resolved then return block(reason or "Could not resolve selected vehicle in safe list.", 4500) end
        G116.busy = true
        driftgod.VS.runtime.pending = {
            safeList116 = true,
            item = item,
            at = now_ms() + 50,
            queuedAt = now_ms(),
        }
        driftgod.VS.runtime.lastStatus = "Queued " .. tostring(item.displayLabel or item.name or "vehicle")
        log_line("QUEUE", "selectedIndex=" .. tostring(driftgod.S.vehicleSpawnerIndex or 0)
            .. " | safeHash=" .. tostring(resolved.hash)
            .. " | safeIndex=" .. tostring(resolved.index)
            .. " | safeLabel=" .. tostring(resolved.label)
            .. " | oldIndex=" .. tostring(item.cheraxListIndex)
            .. " | selected=" .. tostring(item.displayLabel or item.name or item.path))
        if driftgod.R154_InstallVehicleSpawnerWorker then tcall(driftgod.R154_InstallVehicleSpawnerWorker) end
        return true
    end

    function driftgod.R154_QueueSelected()
        local item = selected_no_rebuild()
        if not item then return block("No Garage vehicle selected.", 2500) end
        return driftgod.R154_QueueItem(item)
    end

    function driftgod.VS_QueueSelected()
        return driftgod.R154_QueueSelected()
    end

    function driftgod.VS_LoadSelected()
        return driftgod.R154_QueueSelected()
    end

    function driftgod.VS_ProcessPending()
        if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.pending) then return end
        local pending = driftgod.VS.runtime.pending
        if pending.safeList116 ~= true then
            local legacyItem = pending.item
            driftgod.VS.runtime.pending = nil
            G116.busy = false
            if legacyItem then return driftgod.R154_QueueItem(legacyItem) end
            return
        end
        if now_ms() < (tonumber(pending.at or 0) or 0) then return end
        local item = pending.item
        local queuedAt = pending.queuedAt or pending.at or now_ms()
        driftgod.VS.runtime.pending = nil
        local result = load_now(item, queuedAt)
        G116.busy = false
        return result
    end

    function driftgod.R154_ProcessVehicleSpawnerPending()
        return driftgod.VS_ProcessPending()
    end

    if driftgod.__GarageProductionBridge115 then driftgod.__GarageProductionBridge115.busy = false end
    if driftgod.__GaragePrimeSafeRollback then driftgod.__GaragePrimeSafeRollback.busy = false end
    if driftgod.__GaragePrimeHashFix then driftgod.__GaragePrimeHashFix.busy = false end
    if driftgod.__GaragePrimeRawOrder113 then driftgod.__GaragePrimeRawOrder113.busy = false end

    -- Run a light safe-list annotation only after this patch loads. It does not use
    -- FileMgr or the unsafe hash, and only reads the stable Saved Vehicles list.
    tcall(function() annotate_items("patch-load") end)

    if type(driftgod.VS_PrintStatus) == "function" and G116.printWrapped ~= true then
        G116.printWrapped = true
        local previousPrint = driftgod.VS_PrintStatus
        driftgod.VS_PrintStatus = function(...)
            local result = previousPrint(...)
            log_line("STATUS", "loads=" .. tostring(G116.loads)
                .. " | blocked=" .. tostring(G116.blocked)
                .. " | failures=" .. tostring(G116.failures)
                .. " | mapped=" .. tostring(G116.exactMapped)
                .. " | safeList=" .. tostring(G116.safeListCount)
                .. " | lastResolved=" .. tostring(G116.lastResolved)
                .. " | lastBlocked=" .. tostring(G116.lastBlocked))
            return result
        end
    end

    log_line("PATCH_LOADED", "safe-list label resolver active | safeHash=" .. tostring(SAFE_HASH)
        .. " | blockedHash=" .. tostring(BLOCKED_HASH)
        .. " | previous P21 indices are ignored for loading")
end)


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.18 prime garage - direct JSON restore fallback
-- note: replaces the model-only diagnostic spawn with saved vehicle data application.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or { runtime = {}, hud = {} }
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or {}

    driftgod.__PrimeGarageP10 = driftgod.__PrimeGarageP10 or {
        patch = "v1.0.18_Direct_JSON_Restore",
        applies = 0,
        failures = 0,
    }
    local P10 = driftgod.__PrimeGarageP10

    local function p10Log(message, important)
        message = "[DriftGod Prime] [Garage v1.0.18 DirectJSON] " .. tostring(message or "")
        if Logger and Logger.LogInfo then
            if important == true and Logger.LogError then Logger.LogError(message)
            else Logger.LogInfo(message) end
        elseif driftgod.Log then
            driftgod.Log(message)
        end
    end

    local function readVehicleFile(path)
        path = tostring(path or "")
        if path == "" then return nil, "empty path" end

        if FileMgr and FileMgr.ReadFileContent then
            local ok, body = driftgod.Try(function() return FileMgr.ReadFileContent(path) end)
            if ok and type(body) == "string" and body ~= "" then
                return body, "FileMgr.ReadFileContent"
            end
        end

        local file = nil
        local okOpen = driftgod.Try(function() file = io.open(path, "rb") end)
        if okOpen and file then
            local body = nil
            local okRead = driftgod.Try(function() body = file:read("*a") end)
            driftgod.Try(function() file:close() end)
            if okRead and type(body) == "string" and body ~= "" then
                return body, "io.open"
            end
        end

        return nil, "file unreadable"
    end

    local function numberField(text, ...)
        local keys = { ... }
        for _, key in ipairs(keys) do
            local value = text:match('"' .. key .. '"%s*:%s*([%-]?[%d%.]+)')
            if value ~= nil then return tonumber(value) end
        end
        return nil
    end

    local function stringField(text, ...)
        local keys = { ... }
        for _, key in ipairs(keys) do
            local value = text:match('"' .. key .. '"%s*:%s*"(.-)"')
            if value ~= nil then
                value = value:gsub('\\"', '"'):gsub('\\\\', '\\')
                return value
            end
        end
        return nil
    end

    local function boolField(text, ...)
        local keys = { ... }
        for _, key in ipairs(keys) do
            local raw = text:match('"' .. key .. '"%s*:%s*([%a%d]+)')
            if raw ~= nil then
                raw = tostring(raw):lower()
                if raw == "true" or raw == "1" then return true end
                if raw == "false" or raw == "0" then return false end
            end
        end
        return nil
    end

    local function objectSection(text, key, maxLength)
        local startPos = text:find('"' .. tostring(key) .. '"', 1, true)
        if not startPos then return "" end
        return text:sub(startPos, math.min(#text, startPos + (tonumber(maxLength or 1200) or 1200)))
    end

    local function colorObject(text, ...)
        local keys = { ... }
        for _, key in ipairs(keys) do
            local section = objectSection(text, key, 500)
            if section ~= "" then
                local r = numberField(section, "r", "R", "red", "Red")
                local g = numberField(section, "g", "G", "green", "Green")
                local b = numberField(section, "b", "B", "blue", "Blue")
                if r ~= nil and g ~= nil and b ~= nil then
                    return { r = r, g = g, b = b }
                end

                local ar, ag, ab = section:match('%[%s*(%d+)%s*,%s*(%d+)%s*,%s*(%d+)')
                if ar then return { r = tonumber(ar), g = tonumber(ag), b = tonumber(ab) } end
            end
        end
        return nil
    end

    local KRZ_MOD_INDEX = {
        MOD_SPOILERS=0, MOD_FRONTBUMPER=1, MOD_REARBUMPER=2, MOD_SIDESKIRT=3,
        MOD_EXHAUST=4, MOD_FRAME=5, MOD_GRILLE=6, MOD_HOOD=7, MOD_FENDER=8,
        MOD_RIGHTFENDER=9, MOD_ROOF=10, MOD_ENGINE=11, MOD_BRAKES=12,
        MOD_TRANSMISSION=13, MOD_HORNS=14, MOD_SUSPENSION=15, MOD_ARMOR=16,
        MOD_TURBO=18, MOD_TIRESMOKE=20, MOD_XENONHEADLIGHTS=22,
        MOD_FRONTWHEEL=23, MOD_REARWHEEL=24, MOD_PLATEHOLDER=25,
        MOD_VANITYPLATES=26, MOD_TRIM=27, MOD_TRIMDESIGN=27, MOD_ORNAMENTS=28,
        MOD_DASHBOARD=29, MOD_DIALDESIGN=30, MOD_DOORSPEAKERS=31, MOD_SEATS=32,
        MOD_STEERINGWHEELS=33, MOD_COLUMNSHIFTERLEVERS=34, MOD_PLAQUES=35,
        MOD_SPEAKERS=36, MOD_TRUNK=37, MOD_HYDRAULICS=38, MOD_ENGINEBLOCK=39,
        MOD_AIRFILTER=40, MOD_STRUTS=41, MOD_ARCHCOVER=42, MOD_AERIALS=43,
        MOD_TANK=44, MOD_WINDOWS=45, MOD_LIVERY=48,
    }

    local function resolveModel(text)
        local model = numberField(text,
            "vehicle_model_hash", "vehicleModel", "VehicleModel",
            "modelHash", "ModelHash", "model", "Model", "hash", "Hash")
        if model and model ~= 0 then return model, "numeric" end

        local modelName = stringField(text, "model", "Model", "modelName", "ModelName", "vehicle", "Vehicle", "spawnName", "SpawnName")
        if modelName and modelName ~= "" then
            local hash = 0
            driftgod.Try(function()
                if Utils and Utils.Joaat then hash = tonumber(Utils.Joaat(modelName) or 0) or 0
                elseif Utils and Utils.sJoaat then hash = tonumber(Utils.sJoaat(modelName) or 0) or 0 end
            end)
            if hash ~= 0 then return hash, "name=" .. modelName end
        end

        return 0, "missing model"
    end

    local function parseCheraxVehicleJson(text)
        text = tostring(text or "")
        if text == "" then return nil, "empty JSON" end

        local model, modelSource = resolveModel(text)
        if model == 0 then return nil, modelSource end

        local snap = {
            model = model,
            modelSource = modelSource,
            mods = {},
            wheelType = numberField(text, "wheelType", "wheel_type", "WheelType") or 0,
            primaryColor = numberField(text, "primaryColor", "primary_color", "PrimaryColor") or 0,
            secondaryColor = numberField(text, "secondaryColor", "secondary_color", "SecondaryColor") or 0,
            pearlescentColor = numberField(text, "pearlescentColor", "pearlescent_color", "PearlescentColor") or 0,
            wheelColor = numberField(text, "wheelColor", "wheel_color", "WheelColor") or 0,
            windowTint = numberField(text, "windowTint", "vehicle_window_tint", "WindowTint") or 0,
            interiorColor = numberField(text, "interiorColor", "interior_color", "InteriorColor") or 0,
            dashBoardColor = numberField(text, "dashBoardColor", "dashboardColor", "dashboard_color", "DashboardColor") or 0,
            plateText = stringField(text, "plateText", "plate_text", "PlateText") or "",
            plateTextIndex = numberField(text, "plateTextIndex", "plate_text_index", "PlateTextIndex") or 0,
            liveryID = numberField(text, "liveryID", "liveryId", "livery", "Livery") or -1,
            livery2ID = numberField(text, "livery2ID", "livery2Id", "Livery2") or -1,
            isPrimaryColorCustom = boolField(text, "isPrimaryColorCustom", "hasCustomPrimary", "customPrimaryColorEnabled"),
            isSecondaryColorCustom = boolField(text, "isSecondaryColorCustom", "hasCustomSecondary", "customSecondaryColorEnabled"),
            customPrimaryColor = colorObject(text, "customPrimaryColor", "custom_primary_color"),
            customSecondaryColor = colorObject(text, "customSecondaryColor", "custom_secondary_color"),
            tyreSmokeColor = colorObject(text, "tyreSmokeColor", "tireSmokeColor", "tyre_smoke_color"),
            bulletproofTyres = boolField(text, "bulletproofTyres", "bulletproofTires"),
            driftTyres = boolField(text, "driftTyres", "driftTires"),
            dirtLevel = numberField(text, "dirtLevel", "DirtLevel") or 0.0,
            disableExtras = numberField(text, "disableExtras", "DisableExtras"),
            extras = {},
            toggleMods = {},
        }

        if snap.isPrimaryColorCustom == nil then snap.isPrimaryColorCustom = snap.customPrimaryColor ~= nil end
        if snap.isSecondaryColorCustom == nil then snap.isSecondaryColorCustom = snap.customSecondaryColor ~= nil end

        -- Standard Cherax JSON mod objects: "mod23": { "index": 17, "variation": false }
        for modType = 0, 49 do
            local section = objectSection(text, "mod" .. tostring(modType), 260)
            if section ~= "" then
                local index = numberField(section, "index", "Index")
                local variation = boolField(section, "variation", "Variation") == true
                if index ~= nil then
                    snap.mods["mod" .. tostring(modType)] = { index = index, variation = variation }
                end
            end
        end

        -- KRZ / alternate JSON mod arrays.
        for modName, modType in pairs(KRZ_MOD_INDEX) do
            local idx, variation = text:match('"' .. modName .. '"%s*:%s*%[%s*(-?%d+)%s*,%s*(%d+)%s*%]')
            if idx then
                snap.mods["mod" .. tostring(modType)] = {
                    index = tonumber(idx) or -1,
                    variation = tostring(variation) == "1",
                }
            elseif text:match('"' .. modName .. '"%s*:%s*"TOGGLE"') then
                snap.mods["mod" .. tostring(modType)] = { index = 1, variation = false }
                snap.toggleMods[modType] = true
            end
        end

        for _, modType in ipairs({ 18, 20, 22 }) do
            local mod = snap.mods["mod" .. tostring(modType)]
            if mod then snap.toggleMods[modType] = tonumber(mod.index or 0) == 1 end
        end

        local neonSection = objectSection(text, "neonKits", 1000)
        snap.neon = {
            left = boolField(neonSection, "left", "neonLOn") == true or boolField(text, "neonLOn") == true,
            right = boolField(neonSection, "right", "neonROn") == true or boolField(text, "neonROn") == true,
            front = boolField(neonSection, "front", "neonFOn") == true or boolField(text, "neonFOn") == true,
            back = boolField(neonSection, "back", "neonBOn") == true or boolField(text, "neonBOn") == true,
        }
        snap.neonColor = colorObject(neonSection, "color") or colorObject(text, "neonColor", "neon_color") or {
            r = numberField(text, "neonColorR") or 255,
            g = numberField(text, "neonColorG") or 0,
            b = numberField(text, "neonColorB") or 255,
        }

        for extra = 1, 20 do
            local enabled = boolField(text, "extra" .. tostring(extra), "Extra" .. tostring(extra))
            if enabled ~= nil then snap.extras[extra] = enabled end
        end

        -- Normalize into the config shape used by SpawnConfiguredVehicle.
        local cfg = {
            model = snap.model,
            wheelType = snap.wheelType,
            primaryColor = snap.primaryColor,
            secondaryColor = snap.secondaryColor,
            pearlescentColor = snap.pearlescentColor,
            wheelColor = snap.wheelColor,
            customPrimaryColor = snap.customPrimaryColor or { r = 0, g = 0, b = 0 },
            customSecondaryColor = snap.customSecondaryColor or { r = 0, g = 0, b = 0 },
            tyreSmokeColor = snap.tyreSmokeColor or { r = 255, g = 255, b = 255 },
            windowTint = snap.windowTint,
            interiorColor = snap.interiorColor,
            dashBoardColor = snap.dashBoardColor,
            plateText = snap.plateText,
            plateTextIndex = snap.plateTextIndex,
            neon = snap.neon,
            neonColor = snap.neonColor,
            mods = {},
        }
        for modType = 0, 49 do
            local mod = snap.mods["mod" .. tostring(modType)]
            if mod then cfg.mods[modType] = { index = mod.index, variation = mod.variation == true } end
        end

        return { snap = snap, cfg = cfg }, nil
    end

    local function invokeVoid(hash, ...)
        local args = { ... }
        return driftgod.Try(function()
            if Natives and Natives.InvokeVoid then
                local unpackFn = (table and table.unpack) or unpack
                Natives.InvokeVoid(hash, unpackFn(args))
            end
        end)
    end

    local function applyPrimeSavedVehicleData(vehicle, parsed, sourceLabel)
        vehicle = tonumber(vehicle or 0) or 0
        if vehicle == 0 or type(parsed) ~= "table" or type(parsed.snap) ~= "table" then
            return false, "invalid apply arguments"
        end

        local snap = parsed.snap
        local applied = {}

        local okSnapshot, snapshotResult = driftgod.Try(function()
            if driftgod.ApplyCheraxVehicleSnapshotToVehicle then
                return driftgod.ApplyCheraxVehicleSnapshotToVehicle(vehicle, snap)
            end
            return false
        end)
        if okSnapshot and snapshotResult ~= false then applied[#applied + 1] = "cheraxSnapshot" end

        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then VEHICLE.SET_VEHICLE_MOD_KIT(vehicle, 0)
            else invokeVoid(0x1F2AA07F00B3217A, vehicle, 0) end
        end)

        for modType, enabled in pairs(snap.toggleMods or {}) do
            driftgod.Try(function()
                if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then VEHICLE.TOGGLE_VEHICLE_MOD(vehicle, modType, enabled == true)
                else invokeVoid(0x2A1F4F37F95BAD08, vehicle, modType, enabled == true) end
            end)
        end
        applied[#applied + 1] = "toggleMods"

        -- Clear the temporary custom paint applied by SpawnConfiguredVehicle when the save uses indexed paint.
        if snap.isPrimaryColorCustom ~= true then
            driftgod.Try(function()
                if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle)
                else invokeVoid(0x55E1D2758F34E437, vehicle) end
            end)
        end
        if snap.isSecondaryColorCustom ~= true then
            driftgod.Try(function()
                if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle)
                else invokeVoid(0x5FFBDEEC3E8E2009, vehicle) end
            end)
        end

        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then VEHICLE.SET_VEHICLE_COLOURS(vehicle, snap.primaryColor, snap.secondaryColor)
            else invokeVoid(0x4F1D4BE3A7F24601, vehicle, snap.primaryColor, snap.secondaryColor) end
            if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicle, snap.pearlescentColor, snap.wheelColor)
            else invokeVoid(0x2036F561ADD12E33, vehicle, snap.pearlescentColor, snap.wheelColor) end

            if snap.isPrimaryColorCustom == true and type(snap.customPrimaryColor) == "table" then
                local c = snap.customPrimaryColor
                if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle, c.r or 0, c.g or 0, c.b or 0)
                else invokeVoid(0x7141766F91D15BEA, vehicle, c.r or 0, c.g or 0, c.b or 0) end
            end
            if snap.isSecondaryColorCustom == true and type(snap.customSecondaryColor) == "table" then
                local c = snap.customSecondaryColor
                if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle, c.r or 0, c.g or 0, c.b or 0)
                else invokeVoid(0x36CED73BFED89754, vehicle, c.r or 0, c.g or 0, c.b or 0) end
            end
        end)

        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_INTERIOR_COLOUR then VEHICLE.SET_VEHICLE_INTERIOR_COLOUR(vehicle, snap.interiorColor)
            else invokeVoid(0xF40DD601A65F7F19, vehicle, snap.interiorColor) end
            if VEHICLE and VEHICLE.SET_VEHICLE_DASHBOARD_COLOUR then VEHICLE.SET_VEHICLE_DASHBOARD_COLOUR(vehicle, snap.dashBoardColor)
            else invokeVoid(0x6089CDF6A57F326C, vehicle, snap.dashBoardColor) end
        end)
        applied[#applied + 1] = "interiorDashboard"

        for index, enabled in pairs(snap.neon or {}) do
            local neonIndex = ({ left = 0, right = 1, front = 2, back = 3 })[index]
            if neonIndex ~= nil then
                driftgod.Try(function()
                    if VEHICLE and VEHICLE.SET_VEHICLE_NEON_LIGHT_ENABLED then VEHICLE.SET_VEHICLE_NEON_LIGHT_ENABLED(vehicle, neonIndex, enabled == true)
                    else invokeVoid(0x2AA720E4287BF269, vehicle, neonIndex, enabled == true) end
                end)
            end
        end
        local nc = snap.neonColor or { r = 255, g = 0, b = 255 }
        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_NEON_COLOUR then VEHICLE.SET_VEHICLE_NEON_COLOUR(vehicle, nc.r, nc.g, nc.b)
            else invokeVoid(0x8E0A582209A62695, vehicle, nc.r, nc.g, nc.b) end
        end)
        applied[#applied + 1] = "neon"

        for extra = 1, 20 do
            local enabled = snap.extras and snap.extras[extra]
            if enabled == nil and snap.disableExtras ~= nil then
                local bit = 2 ^ (extra - 1)
                enabled = (math.floor(snap.disableExtras / bit) % 2) == 0
            end
            if enabled ~= nil then
                driftgod.Try(function()
                    if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA then VEHICLE.SET_VEHICLE_EXTRA(vehicle, extra, enabled ~= true)
                    else invokeVoid(0x7EE3A3C5E4A40CC9, vehicle, extra, enabled ~= true) end
                end)
            end
        end
        applied[#applied + 1] = "extras"

        if snap.liveryID and snap.liveryID >= 0 then
            driftgod.Try(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_LIVERY then VEHICLE.SET_VEHICLE_LIVERY(vehicle, snap.liveryID)
                else invokeVoid(0x60BF608F1B8CD1B6, vehicle, snap.liveryID) end
            end)
        end
        if snap.livery2ID and snap.livery2ID >= 0 then
            driftgod.Try(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_MOD then VEHICLE.SET_VEHICLE_MOD(vehicle, 48, snap.livery2ID, false)
                else invokeVoid(0x6AF0636DDEDCB6DD, vehicle, 48, snap.livery2ID, false) end
            end)
        end

        if snap.bulletproofTyres == true then
            driftgod.Try(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_TYRES_CAN_BURST then VEHICLE.SET_VEHICLE_TYRES_CAN_BURST(vehicle, false)
                else invokeVoid(0xEB9DC3C7D8596C46, vehicle, false) end
            end)
        end
        if snap.driftTyres == true then
            driftgod.Try(function()
                if VEHICLE and VEHICLE.SET_DRIFT_TYRES_ENABLED then VEHICLE.SET_DRIFT_TYRES_ENABLED(vehicle, true)
                else invokeVoid(0x5AC79C98C5C17F05, vehicle, true) end
            end)
        end

        driftgod.Try(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_DIRT_LEVEL then VEHICLE.SET_VEHICLE_DIRT_LEVEL(vehicle, snap.dirtLevel or 0.0)
            else invokeVoid(0x79D3B596FE44EE8B, vehicle, snap.dirtLevel or 0.0) end
            if VEHICLE and VEHICLE.SET_VEHICLE_FIXED then VEHICLE.SET_VEHICLE_FIXED(vehicle)
            else invokeVoid(0x115722B1B9C14C1C, vehicle) end
            if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then VEHICLE.SET_VEHICLE_ENGINE_ON(vehicle, true, true, false)
            else invokeVoid(0x2497C4717C8B881E, vehicle, true, true, false) end
            if VEHICLE and VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY then VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY(vehicle)
            else invokeVoid(0x49733E92263139D1, vehicle, 5.0) end
        end)
        applied[#applied + 1] = "finalize"

        P10.applies = (tonumber(P10.applies or 0) or 0) + 1
        p10Log("saved data applied | pass=" .. tostring(sourceLabel or "now")
            .. " | handle=" .. tostring(vehicle)
            .. " | model=" .. tostring(snap.model)
            .. " | mods=" .. tostring((function() local n=0 for _ in pairs(snap.mods or {}) do n=n+1 end return n end)())
            .. " | indexedPaint=" .. tostring(snap.primaryColor) .. "/" .. tostring(snap.secondaryColor)
            .. " | custom=" .. tostring(snap.isPrimaryColorCustom == true) .. "/" .. tostring(snap.isSecondaryColorCustom == true)
            .. " | wheelType=" .. tostring(snap.wheelType)
            .. " | applied=" .. table.concat(applied, ","))
        return true, table.concat(applied, ",")
    end

    local function selectRandomItem(targetCategory)
        local pool = {}
        for _, candidate in ipairs(driftgod.VS.runtime.items or {}) do
            if not candidate.isFolder and not candidate.isRandom
                and (targetCategory == "All" or tostring(candidate.category or "Root"):lower() == tostring(targetCategory or ""):lower()) then
                pool[#pool + 1] = candidate
            end
        end
        if #pool == 0 then return nil end
        return pool[math.random(1, #pool)]
    end

    function driftgod.VS_LoadItem(item)
        if not item then
            p10Log("load blocked: no item selected", true)
            return false
        end

        if item.isFolder then
            driftgod.VS.runtime.currentFolder = item.folderTarget or item.category
            driftgod.S.vehicleSpawnerIndex = 0
            driftgod.VS.hud.scroll = 0
            if driftgod.VS_Rebuild then driftgod.VS_Rebuild(true) end
            return true
        end

        if item.isRandom then
            item = selectRandomItem(item.randomTargetCategory or "All")
            if not item then
                p10Log("random load blocked: no vehicles available", true)
                return false
            end
        end

        local path = tostring(item.path or "")
        if not path:lower():match("%.json$") then
            p10Log("load blocked: P10 currently supports Cherax JSON vehicle files only | file=" .. path, true)
            return false
        end

        local text, readMethod = readVehicleFile(path)
        if not text then
            P10.failures = (tonumber(P10.failures or 0) or 0) + 1
            p10Log("vehicle JSON read failed | file=" .. path .. " | reason=" .. tostring(readMethod), true)
            return false
        end

        local parsed, parseError = parseCheraxVehicleJson(text)
        if not parsed then
            P10.failures = (tonumber(P10.failures or 0) or 0) + 1
            p10Log("vehicle JSON parse failed | file=" .. path .. " | reason=" .. tostring(parseError), true)
            return false
        end

        local label = tostring(item.displayLabel or item.name or "Saved Vehicle")
        p10Log("full saved vehicle spawn begin | name=" .. label
            .. " | model=" .. tostring(parsed.snap.model)
            .. " | source=" .. tostring(parsed.snap.modelSource)
            .. " | reader=" .. tostring(readMethod))

        if type(driftgod.SpawnConfiguredVehicle) ~= "function" then
            p10Log("spawn unavailable: SpawnConfiguredVehicle missing", true)
            return false
        end

        local okSpawn, vehicle = driftgod.Try(function()
            return driftgod.SpawnConfiguredVehicle(parsed.cfg, label)
        end)
        vehicle = tonumber(vehicle or 0) or 0

        if not okSpawn or vehicle == 0 then
            P10.failures = (tonumber(P10.failures or 0) or 0) + 1
            p10Log("full saved vehicle spawn failed | name=" .. label
                .. " | model=" .. tostring(parsed.snap.model)
                .. " | result=" .. tostring(vehicle), true)
            return false
        end

        applyPrimeSavedVehicleData(vehicle, parsed, "now")

        if Script and Script.QueueJob then
            Script.QueueJob(function()
                if Script and Script.Yield then Script.Yield(250) end
                applyPrimeSavedVehicleData(vehicle, parsed, "250ms")
                if Script and Script.Yield then Script.Yield(750) end
                applyPrimeSavedVehicleData(vehicle, parsed, "1000ms")
                if Script and Script.Yield then Script.Yield(1250) end
                applyPrimeSavedVehicleData(vehicle, parsed, "2250ms-final")
            end)
        end

        driftgod.VS.runtime.lastSpawnedName = label
        driftgod.VS.runtime.lastSpawnedModel = tostring(parsed.snap.model)
        driftgod.VS.runtime.lastSpawnedHandle = vehicle
        driftgod.VS.runtime.spawnCount = (tonumber(driftgod.VS.runtime.spawnCount or 0) or 0) + 1
        driftgod.VS.runtime.lastStatus = "Loaded full saved data: " .. label

        p10Log("full saved vehicle spawned | name=" .. label
            .. " | model=" .. tostring(parsed.snap.model)
            .. " | handle=" .. tostring(vehicle)
            .. " | file=" .. path)
        return true
    end

    p10Log("patch installed | direct selected JSON loader restored after Prime index mismatch")
end)



-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.18 garage patch: Prime direct JSON selected-file loader
-- note: v1.0.17 crashed on Prime while probing multiple FeatureMgr list hashes.
--       This build is based on the non-crashing v1.0.16 base, then restores the
--       earlier direct JSON loader at the very end so Garage loads the selected
--       file path itself instead of trusting any Cherax saved-vehicle index.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or { lastKeys = {}, scroll = 0, inputLockUntil = 0 }

    driftgod.Version = "v1.0.18"
    driftgod.BuildNumber = "2026.07.27.118"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_18_Prime_Direct_JSON_Garage"
    driftgod.__GarageDirectJson118 = driftgod.__GarageDirectJson118 or {}

    local G118 = driftgod.__GarageDirectJson118
    G118.patch = "v1.0.18_Direct_JSON_Selected_File"
    G118.loads = tonumber(G118.loads or 0) or 0
    G118.blocked = tonumber(G118.blocked or 0) or 0
    G118.failures = tonumber(G118.failures or 0) or 0
    G118.busy = false

    local function tcall(fn, ...)
        if type(fn) ~= "function" then return false, "missing function" end
        if driftgod.Try then return driftgod.Try(fn, ...) end
        return pcall(fn, ...)
    end

    local function now_ms()
        local ok, v = tcall(function()
            if Time and Time.GetEpocheMs then return Time.GetEpocheMs() end
            return nil
        end)
        if ok and tonumber(v) then return tonumber(v) end
        return math.floor((tonumber(os.clock and os.clock() or 0) or 0) * 1000)
    end

    local function log_line(tag, msg, important)
        local full = "[DriftGod Prime] [Garage v1.0.18] " .. tostring(tag or "LOG") .. " | " .. tostring(msg or "")
        if important == true and Logger and Logger.LogError then Logger.LogError(full)
        elseif Logger and Logger.LogInfo then Logger.LogInfo(full)
        elseif driftgod.Log then driftgod.Log(full) end
        if driftgod.VS_DebugLog then tcall(function() driftgod.VS_DebugLog("V118_" .. tostring(tag or "LOG"), tostring(msg or "")) end) end
    end

    local function toast(msg, ms)
        if driftgod.VS_Toast then tcall(driftgod.VS_Toast, tostring(msg or ""), tonumber(ms or 2500) or 2500)
        elseif driftgod.Toast then tcall(driftgod.Toast, tostring(msg or ""), tonumber(ms or 2500) or 2500)
        elseif GUI and GUI.AddToast then tcall(function() GUI.AddToast("DriftGod", tostring(msg or ""), tonumber(ms or 2500) or 2500) end) end
    end

    local function copy_item(item)
        if type(item) ~= "table" then return item end
        local out = {}
        for k, v in pairs(item) do out[k] = v end
        return out
    end

    local function selected_no_rebuild()
        if not (driftgod.VS and driftgod.VS.runtime) then return nil end
        local filtered = driftgod.VS.runtime.filtered or {}
        local idx = math.floor(tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0)
        if idx < 0 then idx = 0 end
        if idx > #filtered - 1 then idx = #filtered - 1 end
        driftgod.S.vehicleSpawnerIndex = idx
        return filtered[idx + 1]
    end

    local function block(reason, ms)
        G118.blocked = (tonumber(G118.blocked or 0) or 0) + 1
        G118.lastBlocked = tostring(reason or "blocked")
        if driftgod.VS and driftgod.VS.runtime then driftgod.VS.runtime.lastStatus = "Garage blocked: " .. tostring(reason or "unknown") end
        log_line("BLOCKED", tostring(reason or "unknown"), true)
        toast(tostring(reason or "Garage load blocked."), tonumber(ms or 3500) or 3500)
        return false
    end

    local function item_label(item)
        if type(item) ~= "table" then return "nil" end
        return tostring(item.displayLabel or item.name or item.path or "Saved Vehicle")
    end

    local function direct_load_now(item, queuedAt)
        if type(item) ~= "table" then return block("No Garage vehicle selected.", 2500) end
        item = copy_item(item)

        log_line("LOAD_BEGIN", "queuedAgeMs=" .. tostring(now_ms() - (tonumber(queuedAt or now_ms()) or now_ms()))
            .. " | selected=" .. item_label(item)
            .. " | path=" .. tostring(item.path or "")
            .. " | category=" .. tostring(item.category or "")
            .. " | oldHash=" .. tostring(item.cheraxListHash)
            .. " | oldIndex=" .. tostring(item.cheraxListIndex)
            .. " | mode=direct-json")

        local ok, result = tcall(function()
            -- This calls the v1.0.18 DirectJSON copy of the old P10 loader that was
            -- appended immediately above this patch. It reads item.path and spawns
            -- that exact saved JSON; it does not call SetFeatureListIndex or Load Vehicle.
            return driftgod.VS_LoadItem(item)
        end)

        if ok and result ~= false then
            G118.loads = (tonumber(G118.loads or 0) or 0) + 1
            G118.lastLoaded = item_label(item)
            if driftgod.VS and driftgod.VS.runtime then
                driftgod.VS.runtime.pending = nil
                driftgod.VS.runtime.lastStatus = "Loaded direct JSON: " .. item_label(item)
            end
            log_line("LOAD_DONE", "selected=" .. item_label(item)
                .. " | result=" .. tostring(result)
                .. " | totalLoads=" .. tostring(G118.loads))
            return true
        end

        G118.failures = (tonumber(G118.failures or 0) or 0) + 1
        return block("Direct JSON load failed for " .. item_label(item) .. " | ok=" .. tostring(ok) .. " | result=" .. tostring(result), 4500)
    end

    function driftgod.DG118_CurrentGarageSelectionNoRebuild()
        return selected_no_rebuild()
    end

    function driftgod.VS_Selected()
        return selected_no_rebuild()
    end

    function driftgod.R154_QueueItem(item)
        if not item then return block("No Garage vehicle selected.", 2500) end
        item = copy_item(item)

        if item.isFolder then
            return direct_load_now(item, now_ms())
        end

        if G118.busy == true or (driftgod.VS.runtime and driftgod.VS.runtime.pending and driftgod.VS.runtime.pending.directJson118 == true) then
            return block("Garage load is already queued. Wait a moment.", 2500)
        end

        G118.busy = true
        driftgod.VS.runtime.pending = {
            directJson118 = true,
            item = item,
            at = now_ms() + 80,
            queuedAt = now_ms(),
        }
        driftgod.VS.runtime.lastStatus = "Queued direct JSON " .. item_label(item)
        log_line("QUEUE", "selectedIndex=" .. tostring(driftgod.S.vehicleSpawnerIndex or 0)
            .. " | selected=" .. item_label(item)
            .. " | path=" .. tostring(item.path or "")
            .. " | oldHash=" .. tostring(item.cheraxListHash)
            .. " | oldIndex=" .. tostring(item.cheraxListIndex)
            .. " | mode=direct-json")
        if driftgod.R154_InstallVehicleSpawnerWorker then tcall(driftgod.R154_InstallVehicleSpawnerWorker) end
        return true
    end

    function driftgod.R154_QueueSelected()
        local item = selected_no_rebuild()
        if not item then return block("No Garage vehicle selected.", 2500) end
        return driftgod.R154_QueueItem(item)
    end

    function driftgod.VS_QueueSelected()
        return driftgod.R154_QueueSelected()
    end

    function driftgod.VS_LoadSelected()
        return driftgod.R154_QueueSelected()
    end

    local directJsonLoadItem = driftgod.VS_LoadItem
    -- Keep direct immediate calls safe too. This wrapper is intentionally tiny and
    -- only blocks old v1.0.16/v1.0.17 index resolvers from coming back on reload.
    driftgod.DG118_DirectJsonLoadItem = directJsonLoadItem
    driftgod.VS_LoadItem = function(item, ...)
        return directJsonLoadItem(item, ...)
    end

    function driftgod.VS_ProcessPending()
        if not (driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.pending) then return end
        local pending = driftgod.VS.runtime.pending
        if pending.directJson118 ~= true then
            local legacyItem = pending.item
            driftgod.VS.runtime.pending = nil
            G118.busy = false
            if legacyItem then return driftgod.R154_QueueItem(legacyItem) end
            return
        end
        if now_ms() < (tonumber(pending.at or 0) or 0) then return end
        local item = pending.item
        local queuedAt = pending.queuedAt or pending.at or now_ms()
        driftgod.VS.runtime.pending = nil
        local result = direct_load_now(item, queuedAt)
        G118.busy = false
        return result
    end

    function driftgod.R154_ProcessVehicleSpawnerPending()
        return driftgod.VS_ProcessPending()
    end

    if Script and Script.RegisterLooped and G118.workerInstalled ~= true then
        G118.workerInstalled = true
        Script.RegisterLooped(function()
            if ShouldUnload and ShouldUnload() then return false end
            if driftgod and driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.pending then
                driftgod.VS_ProcessPending()
                if Script and Script.Yield then Script.Yield(0) end
            else
                if Script and Script.Yield then Script.Yield(120) end
            end
        end)
    end

    if driftgod.__GarageMultiHash117 then driftgod.__GarageMultiHash117.busy = false; driftgod.__GarageMultiHash117.disabledBy = "v1.0.18_Direct_JSON" end
    if driftgod.__GarageSafeListMatch116 then driftgod.__GarageSafeListMatch116.busy = false; driftgod.__GarageSafeListMatch116.disabledBy = "v1.0.18_Direct_JSON" end
    if driftgod.__GarageProductionBridge115 then driftgod.__GarageProductionBridge115.busy = false; driftgod.__GarageProductionBridge115.disabledBy = "v1.0.18_Direct_JSON" end
    if driftgod.__GaragePrimeHashFix then driftgod.__GaragePrimeHashFix.disabledBy = "v1.0.18_Direct_JSON" end
    if driftgod.__GaragePrimeRawOrder113 then driftgod.__GaragePrimeRawOrder113.disabledBy = "v1.0.18_Direct_JSON" end

    if driftgod.VS and driftgod.VS.runtime then
        driftgod.VS.runtime.pending = nil
        driftgod.VS.runtime.lastStatus = "Prime Garage direct JSON loader active. Press Scan before loading vehicles."
    end

    if type(driftgod.VS_PrintStatus) == "function" and G118.printWrapped ~= true then
        G118.printWrapped = true
        local previousPrint = driftgod.VS_PrintStatus
        driftgod.VS_PrintStatus = function(...)
            local result = previousPrint(...)
            log_line("STATUS", "loads=" .. tostring(G118.loads)
                .. " | blocked=" .. tostring(G118.blocked)
                .. " | failures=" .. tostring(G118.failures)
                .. " | lastLoaded=" .. tostring(G118.lastLoaded)
                .. " | lastBlocked=" .. tostring(G118.lastBlocked))
            return result
        end
    end

    log_line("PATCH_LOADED", "Direct JSON selected-file Garage loader active | FeatureMgr saved-vehicle index loading bypassed")
end)


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.19 garage patch: direct JSON mod restore
-- note: v1.0.18 proved the selected JSON file path is correct on Prime, but the
--       direct spawn path did not reliably restore vehicle mods. This wraps the
--       v1.0.18 direct loader and reapplies mod0-mod49, wheel type, livery, and
--       toggle mods directly from the selected JSON after the vehicle exists.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}

    driftgod.Version = "v1.0.19"
    driftgod.BuildNumber = "2026.07.27.119"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_19_Prime_Direct_JSON_Mod_Restore"
    driftgod.__GarageDirectJson119 = driftgod.__GarageDirectJson119 or {}

    local G119 = driftgod.__GarageDirectJson119
    G119.patch = "v1.0.19_Direct_JSON_Mod_Restore"
    G119.loads = tonumber(G119.loads or 0) or 0
    G119.applies = tonumber(G119.applies or 0) or 0
    G119.failures = tonumber(G119.failures or 0) or 0

    local function tcall(fn, ...)
        if type(fn) ~= "function" then return false, "missing function" end
        if driftgod.Try then return driftgod.Try(fn, ...) end
        return pcall(fn, ...)
    end

    local function log_line(tag, msg, important)
        local full = "[DriftGod Prime] [Garage v1.0.19] " .. tostring(tag or "LOG") .. " | " .. tostring(msg or "")
        if important == true and Logger and Logger.LogError then Logger.LogError(full)
        elseif Logger and Logger.LogInfo then Logger.LogInfo(full)
        elseif driftgod.Log then driftgod.Log(full) end
        if driftgod.VS_DebugLog then tcall(function() driftgod.VS_DebugLog("V119_" .. tostring(tag or "LOG"), tostring(msg or "")) end) end
    end

    local function read_text_file(path)
        path = tostring(path or "")
        if path == "" then return nil, "empty path" end

        if FileMgr and FileMgr.ReadFileContent then
            local ok, body = tcall(function() return FileMgr.ReadFileContent(path) end)
            if ok and type(body) == "string" and body ~= "" then return body, "FileMgr.ReadFileContent" end
        end

        local file = nil
        local okOpen = tcall(function() file = io.open(path, "rb") end)
        if okOpen and file then
            local body = nil
            local okRead = tcall(function() body = file:read("*a") end)
            tcall(function() file:close() end)
            if okRead and type(body) == "string" and body ~= "" then return body, "io.open" end
        end

        return nil, "file unreadable"
    end

    local function section_for_key(text, key, max_len)
        text = tostring(text or "")
        key = tostring(key or "")
        if text == "" or key == "" then return "" end

        local keyPos = text:find('"' .. key .. '"', 1, true)
        if not keyPos then return "" end

        local brace = text:find("{", keyPos, true)
        if not brace then
            return text:sub(keyPos, math.min(#text, keyPos + (tonumber(max_len or 420) or 420)))
        end

        local depth = 0
        for i = brace, #text do
            local c = text:sub(i, i)
            if c == "{" then depth = depth + 1 end
            if c == "}" then
                depth = depth - 1
                if depth <= 0 then return text:sub(brace, i) end
            end
            if i - brace > (tonumber(max_len or 2600) or 2600) then break end
        end

        return text:sub(keyPos, math.min(#text, keyPos + (tonumber(max_len or 2600) or 2600)))
    end

    local function number_field(text, ...)
        local keys = { ... }
        text = tostring(text or "")
        for _, key in ipairs(keys) do
            key = tostring(key or "")
            local raw = text:match('"' .. key .. '"%s*:%s*(-?%d+%.?%d*)')
            if raw ~= nil then return tonumber(raw) end
        end
        return nil
    end

    local function bool_field(text, ...)
        local keys = { ... }
        text = tostring(text or "")
        for _, key in ipairs(keys) do
            key = tostring(key or "")
            local raw = text:match('"' .. key .. '"%s*:%s*([%a%d]+)')
            if raw ~= nil then
                raw = tostring(raw):lower()
                if raw == "true" or raw == "1" then return true end
                if raw == "false" or raw == "0" then return false end
            end
        end
        return nil
    end

    local function color_object(text, ...)
        local keys = { ... }
        text = tostring(text or "")
        for _, key in ipairs(keys) do
            local section = section_for_key(text, key, 700)
            if section ~= "" then
                local r = number_field(section, "r", "R", "red", "Red")
                local g = number_field(section, "g", "G", "green", "Green")
                local b = number_field(section, "b", "B", "blue", "Blue")
                if r ~= nil and g ~= nil and b ~= nil then return { r = r, g = g, b = b } end
                local ar, ag, ab = section:match('%[%s*(%d+)%s*,%s*(%d+)%s*,%s*(%d+)')
                if ar then return { r = tonumber(ar), g = tonumber(ag), b = tonumber(ab) } end
            end
        end
        return nil
    end

    local KRZ_MOD_INDEX = {
        MOD_SPOILERS=0, MOD_FRONTBUMPER=1, MOD_REARBUMPER=2, MOD_SIDESKIRT=3,
        MOD_EXHAUST=4, MOD_FRAME=5, MOD_GRILLE=6, MOD_HOOD=7, MOD_FENDER=8,
        MOD_RIGHTFENDER=9, MOD_ROOF=10, MOD_ENGINE=11, MOD_BRAKES=12,
        MOD_TRANSMISSION=13, MOD_HORNS=14, MOD_SUSPENSION=15, MOD_ARMOR=16,
        MOD_TURBO=18, MOD_TIRESMOKE=20, MOD_XENONHEADLIGHTS=22,
        MOD_FRONTWHEEL=23, MOD_REARWHEEL=24, MOD_PLATEHOLDER=25,
        MOD_VANITYPLATES=26, MOD_TRIM=27, MOD_TRIMDESIGN=27, MOD_ORNAMENTS=28,
        MOD_DASHBOARD=29, MOD_DIALDESIGN=30, MOD_DOORSPEAKERS=31, MOD_SEATS=32,
        MOD_STEERINGWHEELS=33, MOD_COLUMNSHIFTERLEVERS=34, MOD_PLAQUES=35,
        MOD_SPEAKERS=36, MOD_TRUNK=37, MOD_HYDRAULICS=38, MOD_ENGINEBLOCK=39,
        MOD_AIRFILTER=40, MOD_STRUTS=41, MOD_ARCHCOVER=42, MOD_AERIALS=43,
        MOD_TANK=44, MOD_WINDOWS=45, MOD_LIVERY=48,
    }

    local function parse_mod_restore_data(text)
        text = tostring(text or "")
        if text == "" then return nil, "empty JSON" end

        local data = {
            mods = {},
            toggleMods = {},
            parsedCount = 0,
            wheelType = number_field(text, "wheelType", "wheel_type", "WheelType"),
            pearlescentColor = number_field(text, "pearlescentColor", "pearlescent_color", "PearlescentColor"),
            wheelColor = number_field(text, "wheelColor", "wheel_color", "WheelColor"),
            primaryColor = number_field(text, "primaryColor", "primary_color", "PrimaryColor"),
            secondaryColor = number_field(text, "secondaryColor", "secondary_color", "SecondaryColor"),
            windowTint = number_field(text, "windowTint", "vehicle_window_tint", "WindowTint"),
            plateTextIndex = number_field(text, "plateTextIndex", "plate_text_index", "PlateTextIndex"),
            liveryID = number_field(text, "liveryID", "liveryId", "livery", "Livery"),
            livery2ID = number_field(text, "livery2ID", "livery2Id", "Livery2"),
            isPrimaryColorCustom = bool_field(text, "isPrimaryColorCustom", "hasCustomPrimary", "customPrimaryColorEnabled"),
            isSecondaryColorCustom = bool_field(text, "isSecondaryColorCustom", "hasCustomSecondary", "customSecondaryColorEnabled"),
            customPrimaryColor = color_object(text, "customPrimaryColor", "custom_primary_color"),
            customSecondaryColor = color_object(text, "customSecondaryColor", "custom_secondary_color"),
            tyreSmokeColor = color_object(text, "tyreSmokeColor", "tireSmokeColor", "tyre_smoke_color"),
            xenonColor = number_field(text, "xenonColor", "headlightColor", "xenonLightColor"),
        }

        for modType = 0, 49 do
            local section = section_for_key(text, "mod" .. tostring(modType), 450)
            if section ~= "" then
                local index = number_field(section, "index", "Index", "modIndex", "ModIndex")
                local variation = bool_field(section, "variation", "Variation", "customTires", "CustomTires") == true
                if index ~= nil then
                    data.mods[modType] = { index = index, variation = variation }
                    data.parsedCount = data.parsedCount + 1
                end
            else
                local flat = number_field(text, "mod" .. tostring(modType), "Mod" .. tostring(modType))
                if flat ~= nil then
                    data.mods[modType] = { index = flat, variation = false }
                    data.parsedCount = data.parsedCount + 1
                end
            end
        end

        for modName, modType in pairs(KRZ_MOD_INDEX) do
            local idx, variation = text:match('"' .. modName .. '"%s*:%s*%[%s*(-?%d+)%s*,%s*(%d+)%s*%]')
            if idx then
                if data.mods[modType] == nil then data.parsedCount = data.parsedCount + 1 end
                data.mods[modType] = { index = tonumber(idx) or -1, variation = tostring(variation) == "1" }
            elseif text:match('"' .. modName .. '"%s*:%s*"TOGGLE"') then
                if data.mods[modType] == nil then data.parsedCount = data.parsedCount + 1 end
                data.mods[modType] = { index = 1, variation = false }
                data.toggleMods[modType] = true
            end
        end

        for _, modType in ipairs({ 18, 20, 22 }) do
            local mod = data.mods[modType]
            if mod then data.toggleMods[modType] = tonumber(mod.index or 0) >= 1 end
        end

        if data.parsedCount <= 0 then return nil, "no mod data parsed" end
        return data, nil
    end

    local function invoke_void(hash, ...)
        local args = { ... }
        return tcall(function()
            if Natives and Natives.InvokeVoid then
                local unpackFn = (table and table.unpack) or unpack
                Natives.InvokeVoid(hash, unpackFn(args))
            end
        end)
    end

    local function set_mod_kit(vehicle)
        return tcall(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then VEHICLE.SET_VEHICLE_MOD_KIT(vehicle, 0)
            else invoke_void(0x1F2AA07F00B3217A, vehicle, 0) end
        end)
    end

    local function set_wheel_type(vehicle, wheelType)
        wheelType = tonumber(wheelType or 0) or 0
        return tcall(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then VEHICLE.SET_VEHICLE_WHEEL_TYPE(vehicle, wheelType)
            else invoke_void(0x487EB21CC7295BA1, vehicle, wheelType) end
        end)
    end

    local function set_vehicle_mod(vehicle, modType, index, variation)
        modType = tonumber(modType or -1) or -1
        index = tonumber(index or -1) or -1
        if modType < 0 then return false end
        return tcall(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_MOD then VEHICLE.SET_VEHICLE_MOD(vehicle, modType, index, variation == true)
            else invoke_void(0x6AF0636DDEDCB6DD, vehicle, modType, index, variation == true) end
        end)
    end

    local function toggle_vehicle_mod(vehicle, modType, enabled)
        modType = tonumber(modType or -1) or -1
        if modType < 0 then return false end
        return tcall(function()
            if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then VEHICLE.TOGGLE_VEHICLE_MOD(vehicle, modType, enabled == true)
            else invoke_void(0x2A1F4F37F95BAD08, vehicle, modType, enabled == true) end
        end)
    end

    local function apply_colors_again(vehicle, data)
        if type(data) ~= "table" then return false end

        tcall(function()
            if data.isPrimaryColorCustom ~= true then
                if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle)
                else invoke_void(0x55E1D2758F34E437, vehicle) end
            end
            if data.isSecondaryColorCustom ~= true then
                if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle)
                else invoke_void(0x5FFBDEEC3E8E2009, vehicle) end
            end
        end)

        tcall(function()
            if data.primaryColor ~= nil and data.secondaryColor ~= nil then
                if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then VEHICLE.SET_VEHICLE_COLOURS(vehicle, data.primaryColor, data.secondaryColor)
                else invoke_void(0x4F1D4BE3A7F24601, vehicle, data.primaryColor, data.secondaryColor) end
            end
            if data.pearlescentColor ~= nil or data.wheelColor ~= nil then
                if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicle, tonumber(data.pearlescentColor or 0) or 0, tonumber(data.wheelColor or 0) or 0)
                else invoke_void(0x2036F561ADD12E33, vehicle, tonumber(data.pearlescentColor or 0) or 0, tonumber(data.wheelColor or 0) or 0) end
            end
        end)

        if data.isPrimaryColorCustom == true and type(data.customPrimaryColor) == "table" then
            local c = data.customPrimaryColor
            tcall(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle, c.r or 0, c.g or 0, c.b or 0)
                else invoke_void(0x7141766F91D15BEA, vehicle, c.r or 0, c.g or 0, c.b or 0) end
            end)
        end
        if data.isSecondaryColorCustom == true and type(data.customSecondaryColor) == "table" then
            local c = data.customSecondaryColor
            tcall(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle, c.r or 0, c.g or 0, c.b or 0)
                else invoke_void(0x36CED73BFED89754, vehicle, c.r or 0, c.g or 0, c.b or 0) end
            end)
        end

        if type(data.tyreSmokeColor) == "table" then
            local c = data.tyreSmokeColor
            tcall(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR then VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR(vehicle, c.r or 255, c.g or 255, c.b or 255) end
            end)
        end

        return true
    end

    local function apply_direct_mods(vehicle, data, pass)
        vehicle = tonumber(vehicle or 0) or 0
        if vehicle == 0 or type(data) ~= "table" then return false end

        local applied = 0
        local failed = 0
        local mod23 = data.mods and data.mods[23]
        local mod24 = data.mods and data.mods[24]

        set_mod_kit(vehicle)

        if data.wheelType ~= nil then set_wheel_type(vehicle, data.wheelType) end

        -- Apply body/performance mods first, but keep wheel slots until after wheelType.
        for modType = 0, 49 do
            if modType ~= 18 and modType ~= 20 and modType ~= 22 and modType ~= 23 and modType ~= 24 then
                local mod = data.mods and data.mods[modType]
                if mod and mod.index ~= nil then
                    local ok = set_vehicle_mod(vehicle, modType, mod.index, mod.variation == true)
                    if ok then applied = applied + 1 else failed = failed + 1 end
                end
            end
        end

        -- Toggle-only vehicle mods.
        for _, modType in ipairs({ 18, 20, 22 }) do
            local mod = data.mods and data.mods[modType]
            if mod then
                local enabled = data.toggleMods and data.toggleMods[modType]
                if enabled == nil then enabled = tonumber(mod.index or 0) >= 1 end
                local ok = toggle_vehicle_mod(vehicle, modType, enabled == true)
                if ok then applied = applied + 1 else failed = failed + 1 end
            end
        end

        -- Wheels must be applied after wheelType. Some vehicles ignore rear wheels, but this is safe.
        if mod23 and mod23.index ~= nil then
            local ok = set_vehicle_mod(vehicle, 23, mod23.index, mod23.variation == true)
            if ok then applied = applied + 1 else failed = failed + 1 end
        end
        if mod24 and mod24.index ~= nil then
            local ok = set_vehicle_mod(vehicle, 24, mod24.index, mod24.variation == true)
            if ok then applied = applied + 1 else failed = failed + 1 end
        end

        if data.liveryID ~= nil and tonumber(data.liveryID or -1) and tonumber(data.liveryID or -1) >= 0 then
            tcall(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_LIVERY then VEHICLE.SET_VEHICLE_LIVERY(vehicle, data.liveryID)
                else invoke_void(0x60BF608F1B8CD1B6, vehicle, data.liveryID) end
            end)
        end
        if data.livery2ID ~= nil and tonumber(data.livery2ID or -1) and tonumber(data.livery2ID or -1) >= 0 then
            set_vehicle_mod(vehicle, 48, data.livery2ID, false)
        end
        if data.windowTint ~= nil then
            tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_WINDOW_TINT then VEHICLE.SET_VEHICLE_WINDOW_TINT(vehicle, data.windowTint) end end)
        end
        if data.plateTextIndex ~= nil then
            tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX(vehicle, data.plateTextIndex) end end)
        end
        if data.xenonColor ~= nil then
            tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_XENON_LIGHT_COLOR then VEHICLE.SET_VEHICLE_XENON_LIGHT_COLOR(vehicle, data.xenonColor) end end)
        end

        -- Some mod changes reset paint/wheel colour, so repeat visual colours after mods.
        apply_colors_again(vehicle, data)

        tcall(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_FIXED then VEHICLE.SET_VEHICLE_FIXED(vehicle) end
            if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then VEHICLE.SET_VEHICLE_ENGINE_ON(vehicle, true, true, false) end
        end)

        G119.applies = (tonumber(G119.applies or 0) or 0) + 1
        log_line("MOD_RESTORE", "pass=" .. tostring(pass or "now")
            .. " | handle=" .. tostring(vehicle)
            .. " | parsed=" .. tostring(data.parsedCount or 0)
            .. " | applied=" .. tostring(applied)
            .. " | failed=" .. tostring(failed)
            .. " | wheelType=" .. tostring(data.wheelType)
            .. " | mod0=" .. tostring(data.mods and data.mods[0] and data.mods[0].index or "nil")
            .. " | mod14=" .. tostring(data.mods and data.mods[14] and data.mods[14].index or "nil")
            .. " | mod23=" .. tostring(data.mods and data.mods[23] and data.mods[23].index or "nil")
            .. " | mod24=" .. tostring(data.mods and data.mods[24] and data.mods[24].index or "nil"))
        return true
    end

    local previous_direct_load = driftgod.DG118_DirectJsonLoadItem or driftgod.DG119_PreviousDirectLoadItem or driftgod.VS_LoadItem
    driftgod.DG119_PreviousDirectLoadItem = previous_direct_load

    function driftgod.DG119_ApplyDirectModsToLastVehicle(path, pass)
        path = tostring(path or (driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.lastLoadedPath) or "")
        local vehicle = tonumber(driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.lastSpawnedHandle or 0) or 0
        if path == "" or vehicle == 0 then
            log_line("MOD_RESTORE_SKIPPED", "path=" .. tostring(path) .. " | handle=" .. tostring(vehicle), true)
            return false
        end
        local text, reader = read_text_file(path)
        if not text then
            log_line("MOD_PARSE_FAILED", "file=" .. tostring(path) .. " | reader=" .. tostring(reader), true)
            return false
        end
        local data, err = parse_mod_restore_data(text)
        if not data then
            log_line("MOD_PARSE_FAILED", "file=" .. tostring(path) .. " | reason=" .. tostring(err), true)
            return false
        end
        log_line("MOD_PARSE_OK", "file=" .. tostring(path) .. " | reader=" .. tostring(reader) .. " | parsed=" .. tostring(data.parsedCount))
        return apply_direct_mods(vehicle, data, pass or "manual")
    end

    function driftgod.DG119_DirectJsonLoadItemWithMods(item, ...)
        local path = ""
        if type(item) == "table" and not item.isFolder and not item.isRandom then path = tostring(item.path or "") end

        local text, reader = nil, "not read"
        local data, parseErr = nil, nil
        if path:lower():match("%.json$") then
            text, reader = read_text_file(path)
            if text then data, parseErr = parse_mod_restore_data(text) end
        end

        local ok, result = tcall(previous_direct_load, item, ...)
        if not ok then
            G119.failures = (tonumber(G119.failures or 0) or 0) + 1
            log_line("LOAD_ERROR", "previous direct loader errored | path=" .. tostring(path) .. " | error=" .. tostring(result), true)
            return false
        end
        if result == false then return false end

        G119.loads = (tonumber(G119.loads or 0) or 0) + 1
        local vehicle = tonumber(driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.lastSpawnedHandle or 0) or 0
        if driftgod.VS and driftgod.VS.runtime then driftgod.VS.runtime.lastLoadedPath = path end

        if vehicle == 0 then
            log_line("MOD_RESTORE_SKIPPED", "no spawned handle | path=" .. tostring(path), true)
            return result
        end
        if not data then
            log_line("MOD_PARSE_SKIPPED", "path=" .. tostring(path) .. " | reader=" .. tostring(reader) .. " | reason=" .. tostring(parseErr or "no data"), true)
            return result
        end

        log_line("MOD_RESTORE_BEGIN", "path=" .. tostring(path)
            .. " | reader=" .. tostring(reader)
            .. " | handle=" .. tostring(vehicle)
            .. " | parsed=" .. tostring(data.parsedCount)
            .. " | wheelType=" .. tostring(data.wheelType))

        apply_direct_mods(vehicle, data, "now")

        if Script and Script.QueueJob then
            Script.QueueJob(function()
                if Script and Script.Yield then Script.Yield(150) end
                apply_direct_mods(vehicle, data, "150ms")
                if Script and Script.Yield then Script.Yield(450) end
                apply_direct_mods(vehicle, data, "600ms")
                if Script and Script.Yield then Script.Yield(900) end
                apply_direct_mods(vehicle, data, "1500ms")
                if Script and Script.Yield then Script.Yield(1000) end
                apply_direct_mods(vehicle, data, "2500ms-final")
            end)
        end

        return result
    end

    driftgod.VS_LoadItem = function(item, ...)
        return driftgod.DG119_DirectJsonLoadItemWithMods(item, ...)
    end
    driftgod.DG118_DirectJsonLoadItem = driftgod.VS_LoadItem

    if driftgod.VS and driftgod.VS.runtime then
        driftgod.VS.runtime.lastStatus = "Prime Garage direct JSON + mod restore active. Press Scan before loading vehicles."
    end

    log_line("PATCH_LOADED", "Direct JSON selected-file Garage loader active with mod0-mod49 restore")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.20 garage patch: deep mod diagnostics
-- note: v1.0.18 fixed selected vehicle spawning on Prime, while v1.0.19 still
--       showed incorrect saved mods. This build keeps direct JSON Garage loading
--       and adds full parse/apply/read-back diagnostics so mismatches are visible.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}

    driftgod.Version = "v1.0.20"
    driftgod.BuildNumber = "2026.07.27.120"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_20_Prime_Deep_Mod_Diagnostics"
    driftgod.__GarageModDiagnostics120 = driftgod.__GarageModDiagnostics120 or {}

    local G120 = driftgod.__GarageModDiagnostics120
    G120.patch = "v1.0.20_Deep_Mod_Diagnostics"
    G120.loads = tonumber(G120.loads or 0) or 0
    G120.applies = tonumber(G120.applies or 0) or 0
    G120.failures = tonumber(G120.failures or 0) or 0
    G120.token = tonumber(G120.token or 0) or 0

    local function tcall(fn, ...)
        if type(fn) ~= "function" then return false, "missing function" end
        if driftgod.Try then return driftgod.Try(fn, ...) end
        return pcall(fn, ...)
    end

    local function log_line(tag, msg, important)
        local full = "[DriftGod Prime] [Garage v1.0.20] " .. tostring(tag or "LOG") .. " | " .. tostring(msg or "")
        if important == true and Logger and Logger.LogError then Logger.LogError(full)
        elseif Logger and Logger.LogInfo then Logger.LogInfo(full)
        elseif driftgod.Log then driftgod.Log(full) end
        if driftgod.VS_DebugLog then tcall(function() driftgod.VS_DebugLog("V120_" .. tostring(tag or "LOG"), tostring(msg or "")) end) end
    end

    local function clean_text(s, max_len)
        s = tostring(s or "")
        s = s:gsub("\r", " "):gsub("\n", " "):gsub("\t", " ")
        s = s:gsub("%s+", " ")
        max_len = tonumber(max_len or 240) or 240
        if #s > max_len then s = s:sub(1, max_len) .. "..." end
        return s
    end

    local function bool_text(v)
        if v == nil then return "nil" end
        return tostring(v == true)
    end

    local function read_text_file(path)
        path = tostring(path or "")
        if path == "" then return nil, "empty path" end

        if FileMgr and FileMgr.ReadFileContent then
            local ok, body = tcall(function() return FileMgr.ReadFileContent(path) end)
            if ok and type(body) == "string" and body ~= "" then return body, "FileMgr.ReadFileContent" end
        end

        local file = nil
        local okOpen = tcall(function() file = io.open(path, "rb") end)
        if okOpen and file then
            local body = nil
            local okRead = tcall(function() body = file:read("*a") end)
            tcall(function() file:close() end)
            if okRead and type(body) == "string" and body ~= "" then return body, "io.open" end
        end

        return nil, "file unreadable"
    end

    local function section_for_key(text, key, max_len)
        text = tostring(text or "")
        key = tostring(key or "")
        if text == "" or key == "" then return "" end

        local keyPos = text:find('"' .. key .. '"', 1, true)
        if not keyPos then return "" end

        local brace = text:find("{", keyPos, true)
        local bracket = text:find("[", keyPos, true)
        local startAt = brace
        local closeOpen = "{"
        local closeClose = "}"
        if bracket and (not brace or bracket < brace) then
            startAt = bracket
            closeOpen = "["
            closeClose = "]"
        end

        if not startAt then
            return text:sub(keyPos, math.min(#text, keyPos + (tonumber(max_len or 420) or 420)))
        end

        local depth = 0
        local inString = false
        local escaped = false
        for i = startAt, #text do
            local c = text:sub(i, i)
            if inString then
                if escaped then escaped = false
                elseif c == "\\" then escaped = true
                elseif c == '"' then inString = false end
            else
                if c == '"' then inString = true
                elseif c == closeOpen then depth = depth + 1
                elseif c == closeClose then
                    depth = depth - 1
                    if depth <= 0 then return text:sub(startAt, i) end
                end
            end
            if i - startAt > (tonumber(max_len or 2600) or 2600) then break end
        end

        return text:sub(keyPos, math.min(#text, keyPos + (tonumber(max_len or 2600) or 2600)))
    end

    local function number_field(text, ...)
        local keys = { ... }
        text = tostring(text or "")
        for _, key in ipairs(keys) do
            key = tostring(key or "")
            local raw = text:match('"' .. key .. '"%s*:%s*(-?%d+%.?%d*)')
            if raw ~= nil then return tonumber(raw) end
        end
        return nil
    end

    local function string_field(text, ...)
        local keys = { ... }
        text = tostring(text or "")
        for _, key in ipairs(keys) do
            key = tostring(key or "")
            local raw = text:match('"' .. key .. '"%s*:%s*"([^"]*)"')
            if raw ~= nil then return raw end
        end
        return nil
    end

    local function bool_field(text, ...)
        local keys = { ... }
        text = tostring(text or "")
        for _, key in ipairs(keys) do
            key = tostring(key or "")
            local raw = text:match('"' .. key .. '"%s*:%s*([%a%d]+)')
            if raw ~= nil then
                raw = tostring(raw):lower()
                if raw == "true" or raw == "1" then return true end
                if raw == "false" or raw == "0" then return false end
            end
        end
        return nil
    end

    local function color_object(text, ...)
        local keys = { ... }
        text = tostring(text or "")
        for _, key in ipairs(keys) do
            local section = section_for_key(text, key, 700)
            if section ~= "" then
                local r = number_field(section, "r", "R", "red", "Red")
                local g = number_field(section, "g", "G", "green", "Green")
                local b = number_field(section, "b", "B", "blue", "Blue")
                if r ~= nil and g ~= nil and b ~= nil then return { r = r, g = g, b = b } end
                local ar, ag, ab = section:match('%[%s*(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)')
                if ar then return { r = tonumber(ar), g = tonumber(ag), b = tonumber(ab) } end
            end
        end
        return nil
    end

    local KRZ_MOD_INDEX = {
        MOD_SPOILERS=0, MOD_FRONTBUMPER=1, MOD_REARBUMPER=2, MOD_SIDESKIRT=3,
        MOD_EXHAUST=4, MOD_FRAME=5, MOD_GRILLE=6, MOD_HOOD=7, MOD_FENDER=8,
        MOD_RIGHTFENDER=9, MOD_ROOF=10, MOD_ENGINE=11, MOD_BRAKES=12,
        MOD_TRANSMISSION=13, MOD_HORNS=14, MOD_SUSPENSION=15, MOD_ARMOR=16,
        MOD_TURBO=18, MOD_TIRESMOKE=20, MOD_XENONHEADLIGHTS=22,
        MOD_FRONTWHEEL=23, MOD_REARWHEEL=24, MOD_PLATEHOLDER=25,
        MOD_VANITYPLATES=26, MOD_TRIM=27, MOD_TRIMDESIGN=27, MOD_ORNAMENTS=28,
        MOD_DASHBOARD=29, MOD_DIALDESIGN=30, MOD_DOORSPEAKERS=31, MOD_SEATS=32,
        MOD_STEERINGWHEELS=33, MOD_COLUMNSHIFTERLEVERS=34, MOD_PLAQUES=35,
        MOD_SPEAKERS=36, MOD_TRUNK=37, MOD_HYDRAULICS=38, MOD_ENGINEBLOCK=39,
        MOD_AIRFILTER=40, MOD_STRUTS=41, MOD_ARCHCOVER=42, MOD_AERIALS=43,
        MOD_TANK=44, MOD_WINDOWS=45, MOD_LIVERY=48,
    }

    local function parse_diagnostics_data(text)
        text = tostring(text or "")
        if text == "" then return nil, "empty JSON" end

        local data = {
            mods = {},
            toggleMods = {},
            rawMod = {},
            parsedCount = 0,
            textBytes = #text,
            model = number_field(text, "vehicle_model_hash", "vehicleModel", "VehicleModel", "modelHash", "ModelHash", "model", "Model", "hash", "Hash"),
            wheelType = number_field(text, "wheelType", "wheel_type", "WheelType"),
            pearlescentColor = number_field(text, "pearlescentColor", "pearlescent_color", "PearlescentColor"),
            wheelColor = number_field(text, "wheelColor", "wheel_color", "WheelColor"),
            primaryColor = number_field(text, "primaryColor", "primary_color", "PrimaryColor"),
            secondaryColor = number_field(text, "secondaryColor", "secondary_color", "SecondaryColor"),
            windowTint = number_field(text, "windowTint", "vehicle_window_tint", "WindowTint"),
            interiorColor = number_field(text, "interiorColor", "interior_color", "InteriorColor"),
            dashBoardColor = number_field(text, "dashBoardColor", "dashboardColor", "dashboard_color", "DashboardColor"),
            plateText = string_field(text, "plateText", "plate_text", "PlateText"),
            plateTextIndex = number_field(text, "plateTextIndex", "plate_text_index", "PlateTextIndex"),
            liveryID = number_field(text, "liveryID", "liveryId", "livery", "Livery"),
            livery2ID = number_field(text, "livery2ID", "livery2Id", "Livery2"),
            isPrimaryColorCustom = bool_field(text, "isPrimaryColorCustom", "hasCustomPrimary", "customPrimaryColorEnabled"),
            isSecondaryColorCustom = bool_field(text, "isSecondaryColorCustom", "hasCustomSecondary", "customSecondaryColorEnabled"),
            customPrimaryColor = color_object(text, "customPrimaryColor", "custom_primary_color"),
            customSecondaryColor = color_object(text, "customSecondaryColor", "custom_secondary_color"),
            tyreSmokeColor = color_object(text, "tyreSmokeColor", "tireSmokeColor", "tyre_smoke_color"),
            xenonColor = number_field(text, "xenonColor", "headlightColor", "xenonLightColor"),
            hasModsObject = text:find('"mods"', 1, true) ~= nil,
            hasMod0Object = text:find('"mod0"', 1, true) ~= nil,
            hasKRZ = text:find('"MOD_', 1, true) ~= nil,
            preview = clean_text(text, 300),
        }

        if data.isPrimaryColorCustom == nil then data.isPrimaryColorCustom = data.customPrimaryColor ~= nil end
        if data.isSecondaryColorCustom == nil then data.isSecondaryColorCustom = data.customSecondaryColor ~= nil end

        for modType = 0, 49 do
            local key = "mod" .. tostring(modType)
            local section = section_for_key(text, key, 900)
            if section ~= "" then
                local index = number_field(section, "index", "Index", "modIndex", "ModIndex")
                local variation = bool_field(section, "variation", "Variation", "customTires", "CustomTires") == true
                if index ~= nil then
                    data.mods[modType] = { index = index, variation = variation, source = key }
                    data.rawMod[modType] = clean_text(section, 260)
                    data.parsedCount = data.parsedCount + 1
                end
            else
                local flat = number_field(text, key, "Mod" .. tostring(modType))
                if flat ~= nil then
                    data.mods[modType] = { index = flat, variation = false, source = "flat_" .. key }
                    data.rawMod[modType] = "flat=" .. tostring(flat)
                    data.parsedCount = data.parsedCount + 1
                end
            end
        end

        for modName, modType in pairs(KRZ_MOD_INDEX) do
            local idx, variation = text:match('"' .. modName .. '"%s*:%s*%[%s*(-?%d+)%s*,%s*(%d+)%s*%]')
            if idx then
                if data.mods[modType] == nil then data.parsedCount = data.parsedCount + 1 end
                data.mods[modType] = { index = tonumber(idx) or -1, variation = tostring(variation) == "1", source = modName }
                data.rawMod[modType] = modName .. "=[" .. tostring(idx) .. "," .. tostring(variation) .. "]"
            elseif text:match('"' .. modName .. '"%s*:%s*"TOGGLE"') then
                if data.mods[modType] == nil then data.parsedCount = data.parsedCount + 1 end
                data.mods[modType] = { index = 1, variation = false, source = modName .. "_TOGGLE" }
                data.toggleMods[modType] = true
                data.rawMod[modType] = modName .. "=TOGGLE"
            end
        end

        for _, modType in ipairs({ 18, 20, 22 }) do
            local m = data.mods[modType]
            if m then
                local explicit = bool_field(text, "toggleMod" .. tostring(modType), "mod" .. tostring(modType) .. "Enabled")
                if explicit ~= nil then data.toggleMods[modType] = explicit
                elseif data.toggleMods[modType] == nil then data.toggleMods[modType] = tonumber(m.index or 0) >= 1 end
            end
        end

        return data, nil
    end

    local function fmt_color(c)
        if type(c) ~= "table" then return "nil" end
        return tostring(c.r or "nil") .. "," .. tostring(c.g or "nil") .. "," .. tostring(c.b or "nil")
    end

    local function get_vehicle_state(vehicle)
        local st = { mods = {}, vars = {}, counts = {}, toggles = {} }
        vehicle = tonumber(vehicle or 0) or 0
        if vehicle == 0 then return st end

        tcall(function() if ENTITY and ENTITY.GET_ENTITY_MODEL then st.model = ENTITY.GET_ENTITY_MODEL(vehicle) end end)
        tcall(function()
            if VEHICLE and VEHICLE.GET_VEHICLE_COLOURS then
                local p, s = VEHICLE.GET_VEHICLE_COLOURS(vehicle)
                st.primaryColor = p
                st.secondaryColor = s
            end
        end)
        tcall(function()
            if VEHICLE and VEHICLE.GET_VEHICLE_EXTRA_COLOURS then
                local pearl, wheel = VEHICLE.GET_VEHICLE_EXTRA_COLOURS(vehicle)
                st.pearlescentColor = pearl
                st.wheelColor = wheel
            end
        end)
        tcall(function() if VEHICLE and VEHICLE.GET_VEHICLE_WHEEL_TYPE then st.wheelType = VEHICLE.GET_VEHICLE_WHEEL_TYPE(vehicle) end end)
        tcall(function() if VEHICLE and VEHICLE.GET_VEHICLE_WINDOW_TINT then st.windowTint = VEHICLE.GET_VEHICLE_WINDOW_TINT(vehicle) end end)
        tcall(function() if VEHICLE and VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT_INDEX then st.plateTextIndex = VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT_INDEX(vehicle) end end)
        tcall(function() if VEHICLE and VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT then st.plateText = VEHICLE.GET_VEHICLE_NUMBER_PLATE_TEXT(vehicle) end end)
        tcall(function() if VEHICLE and VEHICLE.GET_VEHICLE_LIVERY then st.liveryID = VEHICLE.GET_VEHICLE_LIVERY(vehicle) end end)
        tcall(function() if VEHICLE and VEHICLE.GET_IS_VEHICLE_PRIMARY_COLOUR_CUSTOM then st.isPrimaryColorCustom = VEHICLE.GET_IS_VEHICLE_PRIMARY_COLOUR_CUSTOM(vehicle) end end)
        tcall(function() if VEHICLE and VEHICLE.GET_IS_VEHICLE_SECONDARY_COLOUR_CUSTOM then st.isSecondaryColorCustom = VEHICLE.GET_IS_VEHICLE_SECONDARY_COLOUR_CUSTOM(vehicle) end end)
        tcall(function()
            if VEHICLE and VEHICLE.GET_VEHICLE_CUSTOM_PRIMARY_COLOUR then
                local r, g, b = VEHICLE.GET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle)
                st.customPrimaryColor = { r = r, g = g, b = b }
            end
        end)
        tcall(function()
            if VEHICLE and VEHICLE.GET_VEHICLE_CUSTOM_SECONDARY_COLOUR then
                local r, g, b = VEHICLE.GET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle)
                st.customSecondaryColor = { r = r, g = g, b = b }
            end
        end)

        for modType = 0, 49 do
            tcall(function() if VEHICLE and VEHICLE.GET_NUM_VEHICLE_MODS then st.counts[modType] = VEHICLE.GET_NUM_VEHICLE_MODS(vehicle, modType) end end)
            tcall(function() if VEHICLE and VEHICLE.GET_VEHICLE_MOD then st.mods[modType] = VEHICLE.GET_VEHICLE_MOD(vehicle, modType) end end)
            tcall(function() if VEHICLE and VEHICLE.GET_VEHICLE_MOD_VARIATION then st.vars[modType] = VEHICLE.GET_VEHICLE_MOD_VARIATION(vehicle, modType) end end)
            if modType == 18 or modType == 20 or modType == 22 then
                tcall(function() if VEHICLE and VEHICLE.IS_TOGGLE_MOD_ON then st.toggles[modType] = VEHICLE.IS_TOGGLE_MOD_ON(vehicle, modType) end end)
            end
        end

        return st
    end

    local function set_mod_kit(vehicle)
        return tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then VEHICLE.SET_VEHICLE_MOD_KIT(vehicle, 0) end end)
    end

    local function set_wheel_type(vehicle, value)
        value = tonumber(value or 0) or 0
        return tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then VEHICLE.SET_VEHICLE_WHEEL_TYPE(vehicle, value) end end)
    end

    local function set_vehicle_mod(vehicle, modType, index, variation)
        modType = tonumber(modType or 0) or 0
        index = tonumber(index or -1) or -1
        return tcall(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_MOD then VEHICLE.SET_VEHICLE_MOD(vehicle, modType, index, variation == true) end
        end)
    end

    local function toggle_vehicle_mod(vehicle, modType, enabled)
        modType = tonumber(modType or 0) or 0
        return tcall(function()
            if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then VEHICLE.TOGGLE_VEHICLE_MOD(vehicle, modType, enabled == true) end
        end)
    end

    local function apply_colors(vehicle, data)
        if type(data) ~= "table" then return end
        tcall(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS and data.primaryColor ~= nil and data.secondaryColor ~= nil then
                VEHICLE.SET_VEHICLE_COLOURS(vehicle, data.primaryColor, data.secondaryColor)
            end
        end)
        tcall(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then
                if data.pearlescentColor ~= nil or data.wheelColor ~= nil then
                    VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicle, data.pearlescentColor or 0, data.wheelColor or 0)
                end
            end
        end)
        if data.isPrimaryColorCustom == true and type(data.customPrimaryColor) == "table" then
            local c = data.customPrimaryColor
            tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle, c.r or 0, c.g or 0, c.b or 0) end end)
        end
        if data.isSecondaryColorCustom == true and type(data.customSecondaryColor) == "table" then
            local c = data.customSecondaryColor
            tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle, c.r or 0, c.g or 0, c.b or 0) end end)
        end
        if type(data.tyreSmokeColor) == "table" then
            local c = data.tyreSmokeColor
            tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR then VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR(vehicle, c.r or 255, c.g or 255, c.b or 255) end end)
        end
    end

    local function log_parse_summary(path, reader, data)
        if type(data) ~= "table" then return end
        log_line("PARSE_SUMMARY", "path=" .. tostring(path)
            .. " | reader=" .. tostring(reader)
            .. " | bytes=" .. tostring(data.textBytes)
            .. " | parsedMods=" .. tostring(data.parsedCount)
            .. " | model=" .. tostring(data.model)
            .. " | wheelType=" .. tostring(data.wheelType)
            .. " | colors=" .. tostring(data.primaryColor) .. "/" .. tostring(data.secondaryColor)
            .. " | pearlWheel=" .. tostring(data.pearlescentColor) .. "/" .. tostring(data.wheelColor)
            .. " | customFlags=" .. bool_text(data.isPrimaryColorCustom) .. "/" .. bool_text(data.isSecondaryColorCustom)
            .. " | customRGB=" .. fmt_color(data.customPrimaryColor) .. "/" .. fmt_color(data.customSecondaryColor)
            .. " | livery=" .. tostring(data.liveryID) .. "/" .. tostring(data.livery2ID)
            .. " | hasModsObject=" .. tostring(data.hasModsObject)
            .. " | hasMod0Object=" .. tostring(data.hasMod0Object)
            .. " | hasKRZ=" .. tostring(data.hasKRZ))
        log_line("JSON_PREVIEW", data.preview)
    end

    local function log_expected_mod_chunks(data)
        if type(data) ~= "table" then return end
        for startMod = 0, 49, 10 do
            local parts = {}
            for modType = startMod, math.min(49, startMod + 9) do
                local m = data.mods and data.mods[modType]
                if m then
                    parts[#parts + 1] = tostring(modType) .. "=" .. tostring(m.index) .. "/" .. tostring(m.variation == true and 1 or 0) .. "/" .. tostring(m.source or "?")
                else
                    parts[#parts + 1] = tostring(modType) .. "=nil"
                end
            end
            log_line("EXPECT_MODS_" .. tostring(startMod) .. "_" .. tostring(math.min(49, startMod + 9)), table.concat(parts, " | "))
        end
    end

    local function log_raw_mods(data)
        if type(data) ~= "table" then return end
        for modType = 0, 49 do
            if data.rawMod and data.rawMod[modType] then
                log_line("RAW_MOD_" .. tostring(modType), data.rawMod[modType])
            end
        end
    end

    local function log_state_chunks(prefix, state)
        state = state or {}
        for startMod = 0, 49, 10 do
            local parts = {}
            for modType = startMod, math.min(49, startMod + 9) do
                parts[#parts + 1] = tostring(modType)
                    .. "=idx:" .. tostring(state.mods and state.mods[modType] or "na")
                    .. ",var:" .. tostring(state.vars and state.vars[modType] or "na")
                    .. ",max:" .. tostring(state.counts and state.counts[modType] or "na")
                    .. ",tog:" .. tostring(state.toggles and state.toggles[modType] or "na")
            end
            log_line(prefix .. "_" .. tostring(startMod) .. "_" .. tostring(math.min(49, startMod + 9)), table.concat(parts, " | "))
        end
    end

    local function log_visual_state(prefix, state)
        state = state or {}
        log_line(prefix .. "_VISUAL", "model=" .. tostring(state.model)
            .. " | wheelType=" .. tostring(state.wheelType)
            .. " | colors=" .. tostring(state.primaryColor) .. "/" .. tostring(state.secondaryColor)
            .. " | pearlWheel=" .. tostring(state.pearlescentColor) .. "/" .. tostring(state.wheelColor)
            .. " | customFlags=" .. bool_text(state.isPrimaryColorCustom) .. "/" .. bool_text(state.isSecondaryColorCustom)
            .. " | customRGB=" .. fmt_color(state.customPrimaryColor) .. "/" .. fmt_color(state.customSecondaryColor)
            .. " | windowTint=" .. tostring(state.windowTint)
            .. " | plate=" .. tostring(state.plateTextIndex) .. "/" .. tostring(state.plateText)
            .. " | livery=" .. tostring(state.liveryID))
    end

    local function log_mismatches(pass, data, state)
        if type(data) ~= "table" or type(state) ~= "table" then return 0 end
        local mismatches = {}
        local invalid = {}

        if data.wheelType ~= nil and state.wheelType ~= nil and tonumber(state.wheelType) ~= tonumber(data.wheelType) then
            mismatches[#mismatches + 1] = "wheelType exp=" .. tostring(data.wheelType) .. " got=" .. tostring(state.wheelType)
        end
        if data.primaryColor ~= nil and state.primaryColor ~= nil and tonumber(state.primaryColor) ~= tonumber(data.primaryColor) then
            mismatches[#mismatches + 1] = "primary exp=" .. tostring(data.primaryColor) .. " got=" .. tostring(state.primaryColor)
        end
        if data.secondaryColor ~= nil and state.secondaryColor ~= nil and tonumber(state.secondaryColor) ~= tonumber(data.secondaryColor) then
            mismatches[#mismatches + 1] = "secondary exp=" .. tostring(data.secondaryColor) .. " got=" .. tostring(state.secondaryColor)
        end

        for modType = 0, 49 do
            local m = data.mods and data.mods[modType]
            if m and m.index ~= nil then
                local exp = tonumber(m.index or -1) or -1
                local got = state.mods and state.mods[modType]
                local max = state.counts and state.counts[modType]
                if max ~= nil and tonumber(max) and exp >= tonumber(max) and exp >= 0 then
                    invalid[#invalid + 1] = tostring(modType) .. " exp=" .. tostring(exp) .. " max=" .. tostring(max)
                end
                if got ~= nil and tonumber(got) ~= exp and not (modType == 18 or modType == 20 or modType == 22) then
                    mismatches[#mismatches + 1] = tostring(modType) .. " exp=" .. tostring(exp) .. " got=" .. tostring(got) .. " max=" .. tostring(max or "na") .. " src=" .. tostring(m.source or "?")
                end
            end
        end

        if #invalid > 0 then
            for i = 1, #invalid, 12 do
                local chunk = {}
                for j = i, math.min(#invalid, i + 11) do chunk[#chunk + 1] = invalid[j] end
                log_line("INVALID_EXPECTED_INDEX_" .. tostring(pass), table.concat(chunk, " | "), true)
            end
        end
        if #mismatches > 0 then
            for i = 1, #mismatches, 8 do
                local chunk = {}
                for j = i, math.min(#mismatches, i + 7) do chunk[#chunk + 1] = mismatches[j] end
                log_line("MISMATCH_" .. tostring(pass), table.concat(chunk, " | "), true)
            end
        else
            log_line("MISMATCH_" .. tostring(pass), "none detected by native read-back")
        end
        return #mismatches
    end

    local function apply_mods_verbose(vehicle, data, pass, token)
        vehicle = tonumber(vehicle or 0) or 0
        if vehicle == 0 or type(data) ~= "table" then return false end
        if token ~= nil and tonumber(token) ~= tonumber(G120.token) then
            log_line("STALE_APPLY_SKIPPED", "pass=" .. tostring(pass) .. " | token=" .. tostring(token) .. " | current=" .. tostring(G120.token) .. " | handle=" .. tostring(vehicle))
            return false
        end

        G120.applies = (tonumber(G120.applies or 0) or 0) + 1
        local before = get_vehicle_state(vehicle)
        log_visual_state("BEFORE_" .. tostring(pass), before)
        if tostring(pass) == "now" then log_state_chunks("BEFORE_MODS", before) end

        local okKit = set_mod_kit(vehicle)
        log_line("SET_MOD_KIT", "pass=" .. tostring(pass) .. " | ok=" .. tostring(okKit))

        if data.wheelType ~= nil then
            local okWheel = set_wheel_type(vehicle, data.wheelType)
            log_line("SET_WHEEL_TYPE", "pass=" .. tostring(pass) .. " | exp=" .. tostring(data.wheelType) .. " | ok=" .. tostring(okWheel))
        end

        apply_colors(vehicle, data)

        for modType = 0, 49 do
            local m = data.mods and data.mods[modType]
            if m and m.index ~= nil then
                local exp = tonumber(m.index or -1) or -1
                local var = m.variation == true
                local max = before.counts and before.counts[modType]
                local okSet, setResult = true, nil
                if modType == 18 or modType == 20 or modType == 22 then
                    local enabled = data.toggleMods and data.toggleMods[modType]
                    if enabled == nil then enabled = exp >= 1 end
                    okSet, setResult = toggle_vehicle_mod(vehicle, modType, enabled == true)
                else
                    okSet, setResult = set_vehicle_mod(vehicle, modType, exp, var)
                end
                local check = get_vehicle_state(vehicle)
                local got = check.mods and check.mods[modType]
                local gotVar = check.vars and check.vars[modType]
                local gotToggle = check.toggles and check.toggles[modType]
                local mismatch = false
                if not (modType == 18 or modType == 20 or modType == 22) and got ~= nil and tonumber(got) ~= exp then mismatch = true end
                log_line("SET_MOD", "pass=" .. tostring(pass)
                    .. " | mod=" .. tostring(modType)
                    .. " | exp=" .. tostring(exp)
                    .. " | var=" .. tostring(var)
                    .. " | max=" .. tostring(max or "na")
                    .. " | source=" .. tostring(m.source or "?")
                    .. " | ok=" .. tostring(okSet)
                    .. " | result=" .. tostring(setResult)
                    .. " | after=" .. tostring(got)
                    .. " | afterVar=" .. tostring(gotVar)
                    .. " | toggle=" .. tostring(gotToggle)
                    .. " | mismatch=" .. tostring(mismatch), mismatch)
            end
        end

        -- Repeat wheels and visuals after the full mod pass, because many GTA vehicles reset colours/wheels during mod application.
        if data.wheelType ~= nil then set_wheel_type(vehicle, data.wheelType) end
        if data.mods and data.mods[23] then set_vehicle_mod(vehicle, 23, data.mods[23].index, data.mods[23].variation == true) end
        if data.mods and data.mods[24] then set_vehicle_mod(vehicle, 24, data.mods[24].index, data.mods[24].variation == true) end
        apply_colors(vehicle, data)

        if data.liveryID ~= nil and tonumber(data.liveryID or -1) and tonumber(data.liveryID or -1) >= 0 then
            tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_LIVERY then VEHICLE.SET_VEHICLE_LIVERY(vehicle, data.liveryID) end end)
        end
        if data.livery2ID ~= nil and tonumber(data.livery2ID or -1) and tonumber(data.livery2ID or -1) >= 0 then
            set_vehicle_mod(vehicle, 48, data.livery2ID, false)
        end
        if data.windowTint ~= nil then tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_WINDOW_TINT then VEHICLE.SET_VEHICLE_WINDOW_TINT(vehicle, data.windowTint) end end) end
        if data.plateTextIndex ~= nil then tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX(vehicle, data.plateTextIndex) end end) end
        if data.plateText and data.plateText ~= "" then tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT(vehicle, data.plateText) end end) end
        if data.xenonColor ~= nil then tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_XENON_LIGHT_COLOR then VEHICLE.SET_VEHICLE_XENON_LIGHT_COLOR(vehicle, data.xenonColor) end end) end
        tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_FIXED then VEHICLE.SET_VEHICLE_FIXED(vehicle) end end)
        tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then VEHICLE.SET_VEHICLE_ENGINE_ON(vehicle, true, true, false) end end)

        local after = get_vehicle_state(vehicle)
        log_visual_state("AFTER_" .. tostring(pass), after)
        log_state_chunks("AFTER_MODS_" .. tostring(pass), after)
        local mismatchCount = log_mismatches(pass, data, after)
        log_line("APPLY_COMPLETE", "pass=" .. tostring(pass)
            .. " | handle=" .. tostring(vehicle)
            .. " | expectedMods=" .. tostring(data.parsedCount)
            .. " | mismatches=" .. tostring(mismatchCount)
            .. " | token=" .. tostring(token)
            .. " | currentToken=" .. tostring(G120.token))
        return true
    end

    local base_direct_load = driftgod.DG119_PreviousDirectLoadItem
        or driftgod.DG118_BaseDirectJsonLoadItem
        or driftgod.DG118_DirectJsonLoadItem
        or driftgod.VS_LoadItem

    G120.baseLoaderType = tostring(type(base_direct_load))

    function driftgod.DG120_ApplyModDiagnosticsToLastVehicle(path, pass)
        path = tostring(path or (driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.lastLoadedPath) or "")
        local vehicle = tonumber(driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.lastSpawnedHandle or 0) or 0
        if path == "" or vehicle == 0 then
            log_line("MANUAL_SKIPPED", "path=" .. tostring(path) .. " | handle=" .. tostring(vehicle), true)
            return false
        end
        local text, reader = read_text_file(path)
        if not text then
            log_line("MANUAL_READ_FAILED", "path=" .. tostring(path) .. " | reader=" .. tostring(reader), true)
            return false
        end
        local data, err = parse_diagnostics_data(text)
        if not data then
            log_line("MANUAL_PARSE_FAILED", "path=" .. tostring(path) .. " | err=" .. tostring(err), true)
            return false
        end
        log_parse_summary(path, reader, data)
        log_expected_mod_chunks(data)
        log_raw_mods(data)
        return apply_mods_verbose(vehicle, data, pass or "manual", G120.token)
    end

    function driftgod.DG120_LoadItemWithDeepModDiagnostics(item, ...)
        if type(item) == "table" and item.isFolder then
            return base_direct_load(item, ...)
        end
        if type(item) == "table" and item.isRandom then
            return base_direct_load(item, ...)
        end

        local path = ""
        local label = "unknown"
        if type(item) == "table" then
            path = tostring(item.path or "")
            label = tostring(item.displayLabel or item.name or "Saved Vehicle")
        end

        G120.token = (tonumber(G120.token or 0) or 0) + 1
        local token = G120.token
        G120.loads = (tonumber(G120.loads or 0) or 0) + 1

        log_line("QUEUE", "token=" .. tostring(token)
            .. " | label=" .. tostring(label)
            .. " | path=" .. tostring(path)
            .. " | baseLoader=" .. tostring(G120.baseLoaderType)
            .. " | selectedIndex=" .. tostring(driftgod.S and driftgod.S.vehicleSpawnerIndex or "nil"))

        local text, reader = nil, "not read"
        local data, parseErr = nil, nil
        if path:lower():match("%.json$") then
            text, reader = read_text_file(path)
            if text then data, parseErr = parse_diagnostics_data(text) end
        end

        if data then
            log_parse_summary(path, reader, data)
            log_expected_mod_chunks(data)
            log_raw_mods(data)
        else
            log_line("PARSE_BLOCKED", "path=" .. tostring(path) .. " | reader=" .. tostring(reader) .. " | reason=" .. tostring(parseErr or "not json/no data"), true)
        end

        local ok, result = tcall(base_direct_load, item, ...)
        if not ok then
            G120.failures = (tonumber(G120.failures or 0) or 0) + 1
            log_line("BASE_LOAD_ERROR", "token=" .. tostring(token) .. " | label=" .. tostring(label) .. " | path=" .. tostring(path) .. " | error=" .. tostring(result), true)
            return false
        end
        if result == false then
            log_line("BASE_LOAD_FALSE", "token=" .. tostring(token) .. " | label=" .. tostring(label) .. " | path=" .. tostring(path), true)
            return false
        end

        local vehicle = tonumber(driftgod.VS and driftgod.VS.runtime and driftgod.VS.runtime.lastSpawnedHandle or 0) or 0
        if driftgod.VS and driftgod.VS.runtime then driftgod.VS.runtime.lastLoadedPath = path end
        log_line("BASE_LOAD_DONE", "token=" .. tostring(token)
            .. " | result=" .. tostring(result)
            .. " | handle=" .. tostring(vehicle)
            .. " | label=" .. tostring(label)
            .. " | path=" .. tostring(path))

        if vehicle == 0 then
            log_line("NO_HANDLE", "token=" .. tostring(token) .. " | path=" .. tostring(path), true)
            return result
        end
        if not data then
            log_line("NO_DATA_AFTER_LOAD", "token=" .. tostring(token) .. " | path=" .. tostring(path) .. " | reason=" .. tostring(parseErr), true)
            return result
        end

        apply_mods_verbose(vehicle, data, "now", token)

        if Script and Script.QueueJob then
            Script.QueueJob(function()
                if Script and Script.Yield then Script.Yield(300) end
                apply_mods_verbose(vehicle, data, "300ms", token)
                if Script and Script.Yield then Script.Yield(900) end
                apply_mods_verbose(vehicle, data, "1200ms", token)
                if Script and Script.Yield then Script.Yield(1900) end
                apply_mods_verbose(vehicle, data, "3100ms-final", token)
            end)
        end

        return result
    end

    driftgod.VS_LoadItem = function(item, ...)
        return driftgod.DG120_LoadItemWithDeepModDiagnostics(item, ...)
    end
    driftgod.DG120_BaseDirectLoadItem = base_direct_load
    driftgod.DG118_DirectJsonLoadItem = driftgod.VS_LoadItem
    driftgod.DG119_DirectJsonLoadItemWithMods = driftgod.VS_LoadItem

    if driftgod.VS and driftgod.VS.runtime then
        driftgod.VS.runtime.lastStatus = "Prime Garage deep mod diagnostics active. Spawn one vehicle, wait 4 seconds, then send logs."
    end

    log_line("PATCH_LOADED", "Deep mod diagnostics installed | baseLoaderType=" .. tostring(G120.baseLoaderType) .. " | avoids FeatureMgr list probing")
end)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.22 garage patch: flashless Garage reveal
-- note: keeps v1.0.21's confirmed Cherax saved-index normalization, but prevents
--       the model-only spawner's default delayed style passes from repainting the
--       vehicle over saved colors. The vehicle is briefly hidden while the first
--       restoration passes finish, then revealed after the saved color/mod state is stable.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    driftgod = driftgod or DG or {}
    DG = driftgod
    driftgod.S = driftgod.S or {}
    driftgod.VS = driftgod.VS or {}
    driftgod.VS.runtime = driftgod.VS.runtime or {}
    driftgod.VS.hud = driftgod.VS.hud or { lastKeys = {}, scroll = 0, inputLockUntil = 0 }

    driftgod.Version = "v1.0.22"
    driftgod.BuildNumber = "2026.07.27.122"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_22_Prime_Flashless_Garage_Reveal"
    driftgod.__GarageCheraxIndex122 = driftgod.__GarageCheraxIndex122 or {}

    local G122 = driftgod.__GarageCheraxIndex122
    G122.patch = "v1.0.22_Flashless_Garage_Reveal"
    G122.loads = tonumber(G122.loads or 0) or 0
    G122.failures = tonumber(G122.failures or 0) or 0
    G122.token = tonumber(G122.token or 0) or 0

    local function tcall(fn, ...)
        if type(fn) ~= "function" then return false, "missing function" end
        if driftgod.Try then return driftgod.Try(fn, ...) end
        return pcall(fn, ...)
    end

    local function log122(tag, msg, important)
        local debugEnabled = driftgod.S and driftgod.S.garageDebugLogsEnabled == true
        if important ~= true and not debugEnabled then return end
        local full = "[DriftGod Prime] [Garage] " .. tostring(tag or "LOG") .. " | " .. tostring(msg or "")
        if important == true and Logger and Logger.LogError then Logger.LogError(full)
        elseif Logger and Logger.LogInfo then Logger.LogInfo(full)
        elseif driftgod.Log then driftgod.Log(full) end
        if debugEnabled and driftgod.VS_DebugLog then
            tcall(function() driftgod.VS_DebugLog("GARAGE_" .. tostring(tag or "LOG"), tostring(msg or "")) end)
        end
    end

    local function toast122(msg, ms)
        msg = tostring(msg or "")
        ms = tonumber(ms or 2400) or 2400
        if driftgod.VS_Toast then tcall(driftgod.VS_Toast, msg, ms)
        elseif driftgod.Toast then tcall(driftgod.Toast, msg, ms)
        elseif GUI and GUI.AddToast then tcall(function() GUI.AddToast("DriftGod", msg, ms) end) end
    end

    local function read_file122(path)
        path = tostring(path or "")
        if path == "" then return nil, "empty path" end
        if FileMgr and FileMgr.ReadFileContent then
            local ok, body = tcall(function() return FileMgr.ReadFileContent(path) end)
            if ok and type(body) == "string" and body ~= "" then return body, "FileMgr.ReadFileContent" end
        end
        local file = nil
        local okOpen = tcall(function() file = io.open(path, "rb") end)
        if okOpen and file then
            local body = nil
            local okRead = tcall(function() body = file:read("*a") end)
            tcall(function() file:close() end)
            if okRead and type(body) == "string" and body ~= "" then return body, "io.open" end
        end
        return nil, "file unreadable"
    end

    local function compact122(s, limit)
        s = tostring(s or "")
        s = s:gsub("\r", " "):gsub("\n", " "):gsub("\t", " "):gsub("%s+", " ")
        limit = tonumber(limit or 240) or 240
        if #s > limit then return s:sub(1, limit) .. "..." end
        return s
    end

    local function section122(text, key, max_len)
        text = tostring(text or "")
        key = tostring(key or "")
        if text == "" or key == "" then return "" end
        local keyPos = text:find('"' .. key .. '"', 1, true)
        if not keyPos then return "" end
        local brace = text:find("{", keyPos, true)
        local bracket = text:find("[", keyPos, true)
        local startAt = brace
        local openChar = "{"
        local closeChar = "}"
        if bracket and (not brace or bracket < brace) then
            startAt = bracket
            openChar = "["
            closeChar = "]"
        end
        max_len = tonumber(max_len or 1400) or 1400
        if not startAt then return text:sub(keyPos, math.min(#text, keyPos + max_len)) end
        local depth = 0
        local inString = false
        local escaped = false
        for i = startAt, #text do
            local c = text:sub(i, i)
            if inString then
                if escaped then escaped = false
                elseif c == "\\" then escaped = true
                elseif c == '"' then inString = false end
            else
                if c == '"' then inString = true
                elseif c == openChar then depth = depth + 1
                elseif c == closeChar then
                    depth = depth - 1
                    if depth <= 0 then return text:sub(startAt, i) end
                end
            end
            if i - startAt > max_len then break end
        end
        return text:sub(keyPos, math.min(#text, keyPos + max_len))
    end

    local function number122(text, ...)
        text = tostring(text or "")
        local keys = { ... }
        for _, key in ipairs(keys) do
            key = tostring(key or "")
            local raw = text:match('"' .. key .. '"%s*:%s*(-?%d+%.?%d*)')
            if raw ~= nil then return tonumber(raw) end
        end
        return nil
    end

    local function string122(text, ...)
        text = tostring(text or "")
        local keys = { ... }
        for _, key in ipairs(keys) do
            key = tostring(key or "")
            local raw = text:match('"' .. key .. '"%s*:%s*"([^\"]*)"')
            if raw ~= nil then return raw:gsub('\\"', '"'):gsub('\\\\', '\\') end
        end
        return nil
    end

    local function bool122(text, ...)
        text = tostring(text or "")
        local keys = { ... }
        for _, key in ipairs(keys) do
            key = tostring(key or "")
            local raw = text:match('"' .. key .. '"%s*:%s*([%a%d]+)')
            if raw ~= nil then
                raw = tostring(raw):lower()
                if raw == "true" or raw == "1" then return true end
                if raw == "false" or raw == "0" then return false end
            end
        end
        return nil
    end

    local function color122(text, ...)
        local keys = { ... }
        for _, key in ipairs(keys) do
            local sec = section122(text, key, 700)
            if sec ~= "" then
                local r = number122(sec, "r", "R", "red", "Red")
                local g = number122(sec, "g", "G", "green", "Green")
                local b = number122(sec, "b", "B", "blue", "Blue")
                if r ~= nil and g ~= nil and b ~= nil then return { r = r, g = g, b = b } end
                local ar, ag, ab = sec:match('%[%s*(-?%d+)%s*,%s*(-?%d+)%s*,%s*(-?%d+)')
                if ar then return { r = tonumber(ar), g = tonumber(ag), b = tonumber(ab) } end
            end
        end
        return nil
    end

    local function invoke_void122(hash, ...)
        local args = { ... }
        return tcall(function()
            local unpackFn = (table and table.unpack) or unpack
            if Natives and Natives.InvokeVoid then return Natives.InvokeVoid(hash, unpackFn(args)) end
            if driftgod.Inv and driftgod.Inv.Void then return driftgod.Inv.Void(hash, unpackFn(args)) end
            return nil
        end)
    end

    local function invoke_int122(hash, ...)
        local args = { ... }
        local ok, result = tcall(function()
            local unpackFn = (table and table.unpack) or unpack
            if Natives and Natives.InvokeInt then return Natives.InvokeInt(hash, unpackFn(args)) end
            if driftgod.Inv and driftgod.Inv.Int then return driftgod.Inv.Int(hash, unpackFn(args)) end
            return nil
        end)
        if ok then return tonumber(result) end
        return nil
    end

    local function invoke_bool122(hash, ...)
        local args = { ... }
        local ok, result = tcall(function()
            local unpackFn = (table and table.unpack) or unpack
            if Natives and Natives.InvokeBool then return Natives.InvokeBool(hash, unpackFn(args)) end
            if driftgod.Inv and driftgod.Inv.Bool then return driftgod.Inv.Bool(hash, unpackFn(args)) end
            return nil
        end)
        if ok and result ~= nil then return result == true end
        return nil
    end

    local function set_mod_kit122(vehicle)
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then return tcall(function() return VEHICLE.SET_VEHICLE_MOD_KIT(vehicle, 0) end) end
        return invoke_void122(0x1F2AA07F00B3217A, vehicle, 0)
    end

    local function set_wheel_type122(vehicle, wheelType)
        wheelType = tonumber(wheelType or 0) or 0
        if VEHICLE and VEHICLE.SET_VEHICLE_WHEEL_TYPE then return tcall(function() return VEHICLE.SET_VEHICLE_WHEEL_TYPE(vehicle, wheelType) end) end
        return invoke_void122(0x487EB21CC7295BA1, vehicle, wheelType)
    end

    local function set_vehicle_mod122(vehicle, modType, nativeIndex, variation)
        modType = tonumber(modType or 0) or 0
        nativeIndex = tonumber(nativeIndex or -1) or -1
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD then return tcall(function() return VEHICLE.SET_VEHICLE_MOD(vehicle, modType, nativeIndex, variation == true) end) end
        return invoke_void122(0x6AF0636DDEDCB6DD, vehicle, modType, nativeIndex, variation == true)
    end

    local function toggle_mod122(vehicle, modType, enabled)
        modType = tonumber(modType or 0) or 0
        if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then return tcall(function() return VEHICLE.TOGGLE_VEHICLE_MOD(vehicle, modType, enabled == true) end) end
        return invoke_void122(0x2A1F4F37F95BAD08, vehicle, modType, enabled == true)
    end

    local function get_mod122(vehicle, modType)
        if VEHICLE and VEHICLE.GET_VEHICLE_MOD then
            local ok, result = tcall(function() return VEHICLE.GET_VEHICLE_MOD(vehicle, modType) end)
            if ok and result ~= nil then return tonumber(result) end
        end
        return invoke_int122(0x772960298DA26FDB, vehicle, modType)
    end

    local function get_mod_count122(vehicle, modType)
        if VEHICLE and VEHICLE.GET_NUM_VEHICLE_MODS then
            local ok, result = tcall(function() return VEHICLE.GET_NUM_VEHICLE_MODS(vehicle, modType) end)
            if ok and result ~= nil then return tonumber(result) end
        end
        return invoke_int122(0xE38E9162A2500646, vehicle, modType)
    end

    local function get_toggle122(vehicle, modType)
        if VEHICLE and VEHICLE.IS_TOGGLE_MOD_ON then
            local ok, result = tcall(function() return VEHICLE.IS_TOGGLE_MOD_ON(vehicle, modType) end)
            if ok and result ~= nil then return result == true end
        end
        return invoke_bool122(0x84B233A8C8FC8AE7, vehicle, modType)
    end

    local function set_colors122(vehicle, snap)
        snap = snap or {}
        tcall(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then VEHICLE.SET_VEHICLE_COLOURS(vehicle, snap.primaryColor or 0, snap.secondaryColor or 0)
            else invoke_void122(0x4F1D4BE3A7F24601, vehicle, snap.primaryColor or 0, snap.secondaryColor or 0) end
        end)
        tcall(function()
            if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicle, snap.pearlescentColor or 0, snap.wheelColor or 0)
            else invoke_void122(0x2036F561ADD12E33, vehicle, snap.pearlescentColor or 0, snap.wheelColor or 0) end
        end)
        if snap.isPrimaryColorCustom == true and type(snap.customPrimaryColor) == "table" then
            local c = snap.customPrimaryColor
            tcall(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle, c.r or 0, c.g or 0, c.b or 0)
                else invoke_void122(0x7141766F91D15BEA, vehicle, c.r or 0, c.g or 0, c.b or 0) end
            end)
        else
            tcall(function()
                if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicle)
                else invoke_void122(0x55E1D2758F34E437, vehicle) end
            end)
        end
        if snap.isSecondaryColorCustom == true and type(snap.customSecondaryColor) == "table" then
            local c = snap.customSecondaryColor
            tcall(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle, c.r or 0, c.g or 0, c.b or 0)
                else invoke_void122(0x36CED73BFED89754, vehicle, c.r or 0, c.g or 0, c.b or 0) end
            end)
        else
            tcall(function()
                if VEHICLE and VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicle)
                else invoke_void122(0x5FFBDEEC3E8E2009, vehicle) end
            end)
        end
        if type(snap.tyreSmokeColor) == "table" then
            local c = snap.tyreSmokeColor
            tcall(function()
                if VEHICLE and VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR then VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR(vehicle, c.r or 255, c.g or 255, c.b or 255)
                else invoke_void122(0xB5BA80F839791C0F, vehicle, c.r or 255, c.g or 255, c.b or 255) end
            end)
        end
    end


    local function cloak_vehicle122(vehicle, token, reason)
        vehicle = tonumber(vehicle or 0) or 0
        if vehicle == 0 then return false end
        if token ~= nil and tonumber(token) ~= tonumber(G122.token) then return false end
        reason = tostring(reason or "cloak")
        tcall(function()
            if ENTITY and ENTITY.SET_ENTITY_VISIBLE then ENTITY.SET_ENTITY_VISIBLE(vehicle, false, false)
            else invoke_void122(0xEA1C610A04DB6BBB, vehicle, false, false) end
        end)
        tcall(function()
            if ENTITY and ENTITY.SET_ENTITY_ALPHA then ENTITY.SET_ENTITY_ALPHA(vehicle, 0, false)
            else invoke_void122(0x44A0870B7E92D7C0, vehicle, 0, false) end
        end)
        tcall(function()
            if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(vehicle, true)
            else invoke_void122(0x428CA6DBD1094446, vehicle, true) end
        end)
        log122("CLOAK", "reason=" .. reason .. " | handle=" .. tostring(vehicle) .. " | token=" .. tostring(token))
        return true
    end

    local function reveal_vehicle122(vehicle, token, reason)
        vehicle = tonumber(vehicle or 0) or 0
        if vehicle == 0 then return false end
        local staleReveal = false
        if token ~= nil and tonumber(token) ~= tonumber(G122.token) then
            staleReveal = true
            log122("STALE_REVEAL_FORCED", "reason=" .. tostring(reason or "reveal") .. " | token=" .. tostring(token) .. " | current=" .. tostring(G122.token) .. " | handle=" .. tostring(vehicle))
        end
        reason = tostring(reason or "reveal")
        tcall(function()
            if ENTITY and ENTITY.RESET_ENTITY_ALPHA then ENTITY.RESET_ENTITY_ALPHA(vehicle)
            else invoke_void122(0x9B1E824FFBB7027A, vehicle) end
        end)
        tcall(function()
            if ENTITY and ENTITY.SET_ENTITY_VISIBLE then ENTITY.SET_ENTITY_VISIBLE(vehicle, true, false)
            else invoke_void122(0xEA1C610A04DB6BBB, vehicle, true, false) end
        end)
        tcall(function()
            if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then ENTITY.FREEZE_ENTITY_POSITION(vehicle, false)
            else invoke_void122(0x428CA6DBD1094446, vehicle, false) end
        end)
        log122("REVEAL", "reason=" .. reason .. " | handle=" .. tostring(vehicle) .. " | token=" .. tostring(token) .. " | stale=" .. tostring(staleReveal == true))
        return true
    end

    local function saved_to_native122(savedIndex, cheraxFormat)
        savedIndex = tonumber(savedIndex or -1) or -1
        if cheraxFormat == true then
            if savedIndex <= 0 then return -1 end
            return savedIndex - 1
        end
        return savedIndex
    end

    local function parse_saved_vehicle122(text)
        text = tostring(text or "")
        if text == "" then return nil, "empty JSON" end
        local format = string122(text, "format", "Format") or ""
        local cheraxFormat = tostring(format):lower():find("cherax", 1, true) ~= nil or text:find('"mods"', 1, true) ~= nil
        local model = number122(text, "vehicle_model_hash", "vehicleModel", "VehicleModel", "modelHash", "ModelHash", "model", "Model", "hash", "Hash") or 0
        if model == 0 then return nil, "missing model" end

        local snap = {
            model = model,
            format = format,
            cheraxFormat = cheraxFormat,
            mods = {},
            toggleMods = {},
            parsedCount = 0,
            bytes = #text,
            wheelType = number122(text, "wheelType", "wheel_type", "WheelType") or 0,
            primaryColor = number122(text, "primaryColor", "primary_color", "PrimaryColor") or 0,
            secondaryColor = number122(text, "secondaryColor", "secondary_color", "SecondaryColor") or 0,
            pearlescentColor = number122(text, "pearlescentColor", "pearlescent_color", "PearlescentColor") or 0,
            wheelColor = number122(text, "wheelColor", "wheel_color", "WheelColor") or 0,
            windowTint = number122(text, "windowTint", "vehicle_window_tint", "WindowTint") or 0,
            interiorColor = number122(text, "interiorColor", "interior_color", "InteriorColor") or 0,
            dashBoardColor = number122(text, "dashBoardColor", "dashboardColor", "dashboard_color", "DashboardColor") or 0,
            plateText = string122(text, "plateText", "plate_text", "PlateText") or "",
            plateTextIndex = number122(text, "plateTextIndex", "plate_text_index", "PlateTextIndex") or 0,
            liveryID = number122(text, "liveryID", "liveryId", "livery", "Livery") or -1,
            livery2ID = number122(text, "livery2ID", "livery2Id", "Livery2") or -1,
            isPrimaryColorCustom = bool122(text, "isPrimaryColorCustom", "hasCustomPrimary", "customPrimaryColorEnabled"),
            isSecondaryColorCustom = bool122(text, "isSecondaryColorCustom", "hasCustomSecondary", "customSecondaryColorEnabled"),
            customPrimaryColor = color122(text, "customPrimaryColor", "custom_primary_color"),
            customSecondaryColor = color122(text, "customSecondaryColor", "custom_secondary_color"),
            tyreSmokeColor = color122(text, "tyreSmokeColor", "tireSmokeColor", "tyre_smoke_color"),
            disableExtras = number122(text, "disableExtras", "DisableExtras"),
            bulletproofTyres = bool122(text, "bulletproofTyres", "bulletproofTires"),
            driftTyres = bool122(text, "driftTyres", "driftTires"),
            dirtLevel = number122(text, "dirtLevel", "DirtLevel") or 0.0,
            preview = compact122(text, 260),
        }
        if snap.isPrimaryColorCustom == nil then snap.isPrimaryColorCustom = snap.customPrimaryColor ~= nil end
        if snap.isSecondaryColorCustom == nil then snap.isSecondaryColorCustom = snap.customSecondaryColor ~= nil end

        for modType = 0, 49 do
            local key = "mod" .. tostring(modType)
            local sec = section122(text, key, 850)
            if sec ~= "" then
                local saved = number122(sec, "index", "Index", "modIndex", "ModIndex")
                local variation = bool122(sec, "variation", "Variation", "customTires", "CustomTires") == true
                if saved ~= nil then
                    local native = saved_to_native122(saved, cheraxFormat)
                    snap.mods[modType] = { savedIndex = saved, nativeIndex = native, variation = variation, source = key }
                    snap.parsedCount = snap.parsedCount + 1
                end
            end
        end

        for _, modType in ipairs({18, 20, 22}) do
            local m = snap.mods[modType]
            if m then snap.toggleMods[modType] = (tonumber(m.savedIndex or 0) or 0) > 0 end
        end

        local neonSection = section122(text, "neonKits", 1000)
        snap.neon = {
            left = bool122(neonSection, "left", "neonLOn") == true or bool122(text, "neonLOn") == true,
            right = bool122(neonSection, "right", "neonROn") == true or bool122(text, "neonROn") == true,
            front = bool122(neonSection, "front", "neonFOn") == true or bool122(text, "neonFOn") == true,
            back = bool122(neonSection, "back", "neonBOn") == true or bool122(text, "neonBOn") == true,
        }
        snap.neonColor = color122(neonSection, "color") or color122(text, "neonColor", "neon_color") or { r = 255, g = 0, b = 255 }

        snap.extras = {}
        for extra = 1, 20 do
            local enabled = bool122(text, "extra" .. tostring(extra), "Extra" .. tostring(extra))
            if enabled ~= nil then snap.extras[extra] = enabled end
        end

        return snap, nil
    end

    local function log_expected122(snap)
        for startMod = 0, 49, 10 do
            local parts = {}
            for modType = startMod, math.min(49, startMod + 9) do
                local m = snap.mods and snap.mods[modType]
                if m then
                    parts[#parts + 1] = tostring(modType) .. "=" .. tostring(m.savedIndex) .. "->" .. tostring(m.nativeIndex) .. "/" .. tostring(m.variation == true and 1 or 0)
                else
                    parts[#parts + 1] = tostring(modType) .. "=nil"
                end
            end
            log122("EXPECT_NATIVE_" .. tostring(startMod) .. "_" .. tostring(math.min(49, startMod + 9)), table.concat(parts, " | "))
        end
    end

    local function apply_saved_data122(vehicle, snap, pass, token)
        vehicle = tonumber(vehicle or 0) or 0
        if vehicle == 0 or type(snap) ~= "table" then return false end
        if token ~= nil and tonumber(token) ~= tonumber(G122.token) then
            log122("STALE_APPLY_SKIPPED", "pass=" .. tostring(pass) .. " | token=" .. tostring(token) .. " | current=" .. tostring(G122.token) .. " | handle=" .. tostring(vehicle))
            return false
        end

        set_mod_kit122(vehicle)
        set_wheel_type122(vehicle, snap.wheelType or 0)
        set_colors122(vehicle, snap)

        local applied = 0
        local mismatches = {}
        for modType = 0, 49 do
            local m = snap.mods and snap.mods[modType]
            if m then
                if modType == 18 or modType == 20 or modType == 22 then
                    toggle_mod122(vehicle, modType, snap.toggleMods and snap.toggleMods[modType] == true)
                else
                    set_vehicle_mod122(vehicle, modType, m.nativeIndex, m.variation == true)
                end
                applied = applied + 1
            end
        end

        -- Wheels and colours are intentionally repeated last. Some vehicles reset wheel
        -- mods when wheel type or body mods change.
        set_wheel_type122(vehicle, snap.wheelType or 0)
        if snap.mods and snap.mods[23] then set_vehicle_mod122(vehicle, 23, snap.mods[23].nativeIndex, snap.mods[23].variation == true) end
        if snap.mods and snap.mods[24] then set_vehicle_mod122(vehicle, 24, snap.mods[24].nativeIndex, snap.mods[24].variation == true) end
        set_colors122(vehicle, snap)

        if snap.liveryID and tonumber(snap.liveryID) and tonumber(snap.liveryID) >= 0 then
            tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_LIVERY then VEHICLE.SET_VEHICLE_LIVERY(vehicle, snap.liveryID) else invoke_void122(0x60BF608F1B8CD1B6, vehicle, snap.liveryID) end end)
        end
        if snap.livery2ID and tonumber(snap.livery2ID) and tonumber(snap.livery2ID) >= 0 then
            set_vehicle_mod122(vehicle, 48, saved_to_native122(snap.livery2ID, snap.cheraxFormat == true), false)
        end
        if snap.windowTint ~= nil then tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_WINDOW_TINT then VEHICLE.SET_VEHICLE_WINDOW_TINT(vehicle, snap.windowTint) else invoke_void122(0x57C51E6BAD752696, vehicle, snap.windowTint) end end) end
        if snap.plateTextIndex ~= nil then tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT_INDEX(vehicle, snap.plateTextIndex) else invoke_void122(0x9088EB5A43FFB0A1, vehicle, snap.plateTextIndex) end end) end
        if snap.plateText and snap.plateText ~= "" then tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT then VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT(vehicle, snap.plateText) else invoke_void122(0x95A88F0B409CDA47, vehicle, tostring(snap.plateText)) end end) end

        for extra = 1, 20 do
            local enabled = snap.extras and snap.extras[extra]
            if enabled == nil and snap.disableExtras ~= nil then
                local bit = 2 ^ (extra - 1)
                enabled = (math.floor((tonumber(snap.disableExtras or 0) or 0) / bit) % 2) == 0
            end
            if enabled ~= nil then
                tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA then VEHICLE.SET_VEHICLE_EXTRA(vehicle, extra, enabled ~= true) else invoke_void122(0x7EE3A3C5E4A40CC9, vehicle, extra, enabled ~= true) end end)
            end
        end

        if type(snap.neon) == "table" then
            local map = { left = 0, right = 1, front = 2, back = 3 }
            for key, idx in pairs(map) do
                tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_NEON_LIGHT_ENABLED then VEHICLE.SET_VEHICLE_NEON_LIGHT_ENABLED(vehicle, idx, snap.neon[key] == true) else invoke_void122(0x2AA720E4287BF269, vehicle, idx, snap.neon[key] == true) end end)
            end
        end
        if type(snap.neonColor) == "table" then
            local c = snap.neonColor
            tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_NEON_COLOUR then VEHICLE.SET_VEHICLE_NEON_COLOUR(vehicle, c.r or 255, c.g or 0, c.b or 255) else invoke_void122(0x8E0A582209A62695, vehicle, c.r or 255, c.g or 0, c.b or 255) end end)
        end

        if snap.bulletproofTyres == true then tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_TYRES_CAN_BURST then VEHICLE.SET_VEHICLE_TYRES_CAN_BURST(vehicle, false) else invoke_void122(0xEB9DC3C7D8596C46, vehicle, false) end end) end
        if snap.driftTyres == true then tcall(function() if VEHICLE and VEHICLE.SET_DRIFT_TYRES_ENABLED then VEHICLE.SET_DRIFT_TYRES_ENABLED(vehicle, true) else invoke_void122(0x5AC79C98C5C17F05, vehicle, true) end end) end
        tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_DIRT_LEVEL then VEHICLE.SET_VEHICLE_DIRT_LEVEL(vehicle, snap.dirtLevel or 0.0) else invoke_void122(0x79D3B596FE44EE8B, vehicle, snap.dirtLevel or 0.0) end end)
        tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_FIXED then VEHICLE.SET_VEHICLE_FIXED(vehicle) else invoke_void122(0x115722B1B9C14C1C, vehicle) end end)
        tcall(function() if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then VEHICLE.SET_VEHICLE_ENGINE_ON(vehicle, true, true, false) else invoke_void122(0x2497C4717C8B881E, vehicle, true, true, false) end end)

        local checked = 0
        for modType = 0, 49 do
            local m = snap.mods and snap.mods[modType]
            if m and not (modType == 18 or modType == 20 or modType == 22) then
                local got = get_mod122(vehicle, modType)
                local max = get_mod_count122(vehicle, modType)
                if got ~= nil and tonumber(got) ~= tonumber(m.nativeIndex) then
                    -- If the vehicle reports no available mods for a slot, GTA may keep -1.
                    -- Still log it, but cap the spam to the important signal.
                    mismatches[#mismatches + 1] = tostring(modType) .. " saved=" .. tostring(m.savedIndex) .. " native=" .. tostring(m.nativeIndex) .. " got=" .. tostring(got) .. " max=" .. tostring(max or "na")
                end
                checked = checked + 1
            end
        end
        for _, modType in ipairs({18, 20, 22}) do
            local m = snap.mods and snap.mods[modType]
            if m then
                log122("VERIFY_TOGGLE", "pass=" .. tostring(pass) .. " | mod=" .. tostring(modType) .. " | saved=" .. tostring(m.savedIndex) .. " | enabled=" .. tostring(snap.toggleMods[modType] == true) .. " | got=" .. tostring(get_toggle122(vehicle, modType)))
            end
        end

        if #mismatches > 0 then
            for i = 1, #mismatches, 8 do
                local chunk = {}
                for j = i, math.min(#mismatches, i + 7) do chunk[#chunk + 1] = mismatches[j] end
                log122("MISMATCH_" .. tostring(pass), table.concat(chunk, " | "), true)
            end
        else
            log122("MISMATCH_" .. tostring(pass), "none after normalized native apply")
        end

        log122("APPLY_COMPLETE", "pass=" .. tostring(pass)
            .. " | handle=" .. tostring(vehicle)
            .. " | applied=" .. tostring(applied)
            .. " | checked=" .. tostring(checked)
            .. " | mismatches=" .. tostring(#mismatches)
            .. " | wheelType=" .. tostring(snap.wheelType)
            .. " | colors=" .. tostring(snap.primaryColor) .. "/" .. tostring(snap.secondaryColor)
            .. " | token=" .. tostring(token)
            .. " | currentToken=" .. tostring(G122.token))
        return true
    end

    local function select_random122(targetCategory)
        local pool = {}
        for _, candidate in ipairs(driftgod.VS.runtime.items or {}) do
            if not candidate.isFolder and not candidate.isRandom
                and (tostring(targetCategory or "All") == "All" or tostring(candidate.category or "Root"):lower() == tostring(targetCategory or ""):lower()) then
                pool[#pool + 1] = candidate
            end
        end
        if #pool == 0 then return nil end
        return pool[math.random(1, #pool)]
    end

    local function copy_item122(item)
        if type(item) ~= "table" then return item end
        local out = {}
        for k, v in pairs(item) do out[k] = v end
        return out
    end

    function driftgod.DG122_LoadItem(item)
        if not item then
            toast122("No Garage vehicle selected.", 2400)
            log122("BLOCKED", "no item selected", true)
            return false
        end
        if item.isFolder then
            driftgod.VS.runtime.currentFolder = item.folderTarget or item.category
            driftgod.S.vehicleSpawnerIndex = 0
            driftgod.VS.hud.scroll = 0
            if driftgod.VS_Rebuild then tcall(function() driftgod.VS_Rebuild(true) end) end
            return true
        end
        if item.isRandom then
            item = select_random122(item.randomTargetCategory or "All")
            if not item then
                toast122("No saved vehicles available for Random.", 2500)
                log122("BLOCKED", "random had no available vehicle", true)
                return false
            end
        end

        item = copy_item122(item)
        local path = tostring(item.path or "")
        if not path:lower():match("%.json$") then
            toast122("Garage DirectJSON only supports JSON saved vehicles.", 3000)
            log122("BLOCKED", "non-json path=" .. path, true)
            return false
        end

        G122.token = (tonumber(G122.token or 0) or 0) + 1
        local token = G122.token
        local label = tostring(item.displayLabel or item.name or "Saved Vehicle")
        log122("QUEUE", "token=" .. tostring(token) .. " | selected=" .. label .. " | path=" .. path .. " | selectedIndex=" .. tostring(driftgod.S.vehicleSpawnerIndex or 0))

        local text, reader = read_file122(path)
        if not text then
            G122.failures = (tonumber(G122.failures or 0) or 0) + 1
            toast122("Vehicle JSON read failed.", 3000)
            log122("READ_FAILED", "path=" .. path .. " | reader=" .. tostring(reader), true)
            return false
        end

        local snap, parseErr = parse_saved_vehicle122(text)
        if not snap then
            G122.failures = (tonumber(G122.failures or 0) or 0) + 1
            toast122("Vehicle JSON parse failed.", 3000)
            log122("PARSE_FAILED", "path=" .. path .. " | err=" .. tostring(parseErr), true)
            return false
        end

        log122("PARSE_SUMMARY", "token=" .. tostring(token)
            .. " | reader=" .. tostring(reader)
            .. " | bytes=" .. tostring(snap.bytes)
            .. " | format=" .. tostring(snap.format)
            .. " | cheraxFormat=" .. tostring(snap.cheraxFormat == true)
            .. " | model=" .. tostring(snap.model)
            .. " | parsedMods=" .. tostring(snap.parsedCount)
            .. " | wheelType=" .. tostring(snap.wheelType)
            .. " | colors=" .. tostring(snap.primaryColor) .. "/" .. tostring(snap.secondaryColor)
            .. " | pearlWheel=" .. tostring(snap.pearlescentColor) .. "/" .. tostring(snap.wheelColor)
            .. " | custom=" .. tostring(snap.isPrimaryColorCustom == true) .. "/" .. tostring(snap.isSecondaryColorCustom == true))
        log_expected122(snap)

        if type(driftgod.SpawnConfiguredVehicle) ~= "function" then
            G122.failures = (tonumber(G122.failures or 0) or 0) + 1
            toast122("Spawn unavailable: SpawnConfiguredVehicle missing.", 3000)
            log122("SPAWN_FAILED", "SpawnConfiguredVehicle missing", true)
            return false
        end

        local originalFullStyle = driftgod.ApplyConfiguredVehicleFullStyle
        driftgod.ApplyConfiguredVehicleFullStyle = function(_, _, _) return true end
        log122("STYLE_QUEUE_BYPASS", "enabled for model-only spawn | token=" .. tostring(token) .. " | label=" .. label)
        local okSpawn, vehicle = tcall(function()
            -- Model-only spawn prevents raw Cherax saved indexes, while the temporary
            -- style bypass prevents default delayed style passes from repainting over
            -- the saved colour during the first few seconds.
            return driftgod.SpawnConfiguredVehicle({ model = snap.model }, label)
        end)
        driftgod.ApplyConfiguredVehicleFullStyle = originalFullStyle
        log122("STYLE_QUEUE_BYPASS", "restored after model-only spawn | token=" .. tostring(token) .. " | ok=" .. tostring(okSpawn) .. " | handle=" .. tostring(vehicle))
        vehicle = tonumber(vehicle or 0) or 0
        if not okSpawn or vehicle == 0 then
            G122.failures = (tonumber(G122.failures or 0) or 0) + 1
            toast122("Saved vehicle spawn failed.", 3000)
            log122("SPAWN_FAILED", "label=" .. label .. " | model=" .. tostring(snap.model) .. " | result=" .. tostring(vehicle), true)
            return false
        end

        driftgod.VS.runtime.lastSpawnedName = label
        driftgod.VS.runtime.lastSpawnedModel = tostring(snap.model)
        driftgod.VS.runtime.lastSpawnedHandle = vehicle
        driftgod.VS.runtime.lastLoadedPath = path
        driftgod.VS.runtime.spawnCount = (tonumber(driftgod.VS.runtime.spawnCount or 0) or 0) + 1
        driftgod.VS.runtime.lastStatus = "Loaded flashless Cherax JSON: " .. label
        G122.loads = (tonumber(G122.loads or 0) or 0) + 1

        log122("SPAWNED", "token=" .. tostring(token) .. " | label=" .. label .. " | model=" .. tostring(snap.model) .. " | handle=" .. tostring(vehicle) .. " | path=" .. path)
        cloak_vehicle122(vehicle, token, "post-spawn-pre-style")
        apply_saved_data122(vehicle, snap, "hidden-now", token)

        if Script and Script.QueueJob then
            Script.QueueJob(function()
                if Script and Script.Yield then Script.Yield(90) end
                apply_saved_data122(vehicle, snap, "hidden-90ms", token)
                if Script and Script.Yield then Script.Yield(160) end
                apply_saved_data122(vehicle, snap, "hidden-250ms", token)
                reveal_vehicle122(vehicle, token, "saved-style-stabilized")
                if Script and Script.Yield then Script.Yield(650) end
                apply_saved_data122(vehicle, snap, "post-reveal-900ms", token)
                if Script and Script.Yield then Script.Yield(1300) end
                apply_saved_data122(vehicle, snap, "post-reveal-2200ms-final", token)
            end)
        else
            reveal_vehicle122(vehicle, token, "no-queuejob")
        end

        toast122("Spawned " .. label, 1800)
        return true
    end

    function driftgod.VS_LoadItem(item, ...)
        return driftgod.DG122_LoadItem(item, ...)
    end
    driftgod.DG118_DirectJsonLoadItem = driftgod.VS_LoadItem
    function driftgod.VS_LoadSelected()
        local filtered = driftgod.VS.runtime.filtered or {}
        local idx = math.floor(tonumber(driftgod.S.vehicleSpawnerIndex or 0) or 0)
        if idx < 0 then idx = 0 end
        if idx > #filtered - 1 then idx = #filtered - 1 end
        driftgod.S.vehicleSpawnerIndex = idx
        return driftgod.DG122_LoadItem(filtered[idx + 1])
    end
    function driftgod.VS_QueueSelected() return driftgod.VS_LoadSelected() end
    function driftgod.R154_QueueSelected() return driftgod.VS_LoadSelected() end
    function driftgod.R154_QueueItem(item) return driftgod.DG122_LoadItem(item) end

    log122("PATCH_LOADED", "Flashless Garage reveal active: bypasses model-only default style queue, cloaks first saved-data passes")
end)


