-- ═══════════════════════════════════════════════════════════════════════════════════
-- DriftGod integration UI
-- note: renders Flying Cars SA inside Arcade > Utilities > Beta, under SuperDrive.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.FlyingCarsSA = driftgod.FlyingCarsSA or {}
driftgod.FlyingCarsSA.version = script_version
driftgod.FlyingCarsSA.state = state
driftgod.FlyingCarsSA.config = config
driftgod.FlyingCarsSA.feature_hash = feature_hash

driftgod.FlyingCarsSA.SetEnabled = function(enabled)
    enabled = enabled == true
    if enabled_feature and enabled_feature.IsToggled and enabled_feature.SetBoolValue then
        if enabled_feature:IsToggled() ~= enabled then
            enabled_feature:SetBoolValue(enabled)
        end
    end
    state.enabled = enabled
end

driftgod.FlyingCarsSA.Toggle = function()
    if enabled_feature and enabled_feature.Toggle then
        enabled_feature:Toggle()
        return true
    end
    state.enabled = not (state.enabled == true)
    return state.enabled
end

local function dg_fc_feature(hash, label, color)
    if hash ~= nil then
        local ok, err = driftgod.Try(function()
            if ui_render_feature then ui_render_feature(hash, color or ui_color.white)
            elseif ClickGUI and ClickGUI.RenderFeature then ClickGUI.RenderFeature(hash) end
        end)
        if ok ~= true and driftgod.Log then
            driftgod.Log("[FlyingCarsSA] RenderFeature failed for " .. tostring(label or hash) .. " | " .. tostring(err))
        end
    else
        ui_text("Missing feature: " .. tostring(label or "unknown"), ui_color.red, true)
    end
end

local function dg_fc_row(label, value, color)
    if ui_label_value then
        ui_label_value(tostring(label or ""), tostring(value or ""), ui_color.soft, color or ui_color.white)
    else
        ImGui.Text(tostring(label or "") .. " " .. tostring(value or ""))
    end
end

local function dg_fc_render_live_status()
    dg_fc_row("Status:", state.enabled and "ENABLED" or "DISABLED", state.enabled and ui_color.green or ui_color.red)
    dg_fc_row("Direction:", direction_mode_name(state.directionMode), state.directionMode == "camera" and ui_color.blue or ui_color.gold)
    dg_fc_row("Phase:", tostring(state.phase or "ROAD"), ui_color.white)
    dg_fc_row("Current Flight:", format_distance(state.runDistance or 0.0), ui_color.cyan)
    dg_fc_row("All-time Best:", format_distance(state.bestDistance or 0.0), ui_color.gold)
    dg_fc_row("Speed:", format_speed(state.speed or 0.0), ui_color.white)
end

local function dg_fc_render_quick_controls()
    ui_text(key_name(config.activation) .. "  Enable Flying Cars / nose up while active", ui_color.gold, true)
    ui_text(key_name(config.pitchDown) .. "  Nose down", ui_color.cyan, true)
    ui_text(key_name(config.turnLeft) .. " / " .. key_name(config.turnRight) .. "  Bank and turn", ui_color.purple, true)
    ui_text(key_name(config.modeToggle) .. "  Vehicle Nose / Gameplay Camera", ui_color.blue, true)
    ui_text("Accelerate = thrust  |  Brake = air drag", ui_color.green, true)
end

local function dg_fc_render_high_scores_inline()
    load_high_scores()
    if not high_scores.records or #high_scores.records == 0 then
        ui_text("No clean landings recorded yet.", ui_color.muted, true)
    else
        for rank = 1, math.min(5, #high_scores.records) do
            local score = high_scores.records[rank]
            ui_text("#" .. tostring(rank) .. "  " .. format_feet(score.distance)
                .. "  |  height " .. format_feet(score.height)
                .. "  |  flips " .. tostring(math.floor(tonumber(score.flips) or 0)),
                high_score_rank_color(rank), true)
        end
    end
    ui_spacing()
    dg_fc_feature(feature_hash.resetBest, "Reload High Scores", ui_color.blue)
end

function driftgod.R123_RenderFlyingCarsSA()
    process_key_capture()
    if not (ClickGUI and ClickGUI.BeginCustomChildWindow) then return end

    if ClickGUI.BeginCustomChildWindow("Flying Cars SA (BETA)") then
        ui_text("Flying Cars SA (BETA)", ui_color.purple)
        ui_text("San Andreas-style vehicle flight ported directly into DriftGod.", ui_color.soft, true)
        ui_text("Road cars become speed-based aircraft; no money, RP, transactions, or online rewards.", ui_color.muted, true)
        ui_separator()

        dg_fc_render_live_status()
        ui_spacing()
        dg_fc_feature(feature_hash.enabled, "DG Flying Cars SA", state.enabled and ui_color.red or ui_color.green)
        dg_fc_feature(feature_hash.directionMode, "DG Flight Direction", ui_color.blue)

        if ImGui.BeginTabBar and ImGui.BeginTabBar("DG_FlyingCarsSA_BetaTabs") then
            if ImGui.BeginTabItem("Flight") then
                ui_text("Presentation", ui_color.cyan)
                dg_fc_feature(feature_hash.hud, "Flight HUD", ui_color.soft_green)
                dg_fc_feature(feature_hash.stuntStats, "SA Stunt Stats", ui_color.gold)
                dg_fc_feature(feature_hash.speedBob, "High-Speed Screen Bobbing", ui_color.blue)
                dg_fc_feature(feature_hash.telemetry, "Physics Telemetry", ui_color.orange)
                ui_separator()
                ui_text("Quick Controls", ui_color.gold)
                dg_fc_render_quick_controls()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Keybinds") then
                ui_text("Click a binding, then press a key. Escape cancels.", ui_color.soft, true)
                for _, row in ipairs(keybind_rows or {}) do
                    render_keybind_button(row)
                end
                ui_spacing()
                if ui_button("Restore Flying Cars Defaults", button_red, -1, 0) then reset_keybinds() end
                ui_text("Saved to: " .. tostring(config_file), ui_color.muted, true)
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Scores") then
                ui_text("Top clean landings", ui_color.gold)
                dg_fc_render_high_scores_inline()
                ui_text("Bad landings are disqualified and not saved.", ui_color.red, true)
                ImGui.EndTabItem()
            end
            ImGui.EndTabBar()
        else
            dg_fc_feature(feature_hash.hud, "Flight HUD", ui_color.soft_green)
            dg_fc_feature(feature_hash.stuntStats, "SA Stunt Stats", ui_color.gold)
            dg_fc_feature(feature_hash.speedBob, "High-Speed Screen Bobbing", ui_color.blue)
            dg_fc_feature(feature_hash.telemetry, "Physics Telemetry", ui_color.orange)
            dg_fc_render_quick_controls()
        end

        ui_separator()
        ui_text("Standalone Flying Cars SA logic is embedded here, but the separate Flying Cars SA tab is not created.", ui_color.muted, true)
        ClickGUI.EndCustomChildWindow()
    end
end

