    stop_speed_bobbing()
    restore_vehicle(state.vehicle)
    if overlay_handler then EventMgr.RemoveHandler(overlay_handler) end
end)

log(
    script_name .. " " .. script_version
        .. " integrated into DriftGod Arcade > Utilities > Beta."
)

end)

driftgod.Try(function()
    local previousBeta = driftgod.R102_RenderBeta
    driftgod.R123_PreFlyingCarsBetaRenderer = previousBeta

    driftgod.R102_RenderBeta = function()
        -- user requested Flying Cars SA underneath SuperDrive (BETA).
        if driftgod.R279_RenderSuperDriveBeta then
            driftgod.R279_RenderSuperDriveBeta()
        elseif driftgod.R140_RenderSuperDriveBeta then
            driftgod.R140_RenderSuperDriveBeta()
        elseif previousBeta then
            previousBeta()
            if driftgod.R123_RenderFlyingCarsSA then driftgod.R123_RenderFlyingCarsSA() end
            return
        end

        if driftgod.R123_RenderFlyingCarsSA then driftgod.R123_RenderFlyingCarsSA() end

        if driftgod.R279_RenderRoadSurfaceBeta then driftgod.R279_RenderRoadSurfaceBeta() end
        if driftgod.R140_RenderPTFXBeta then driftgod.R140_RenderPTFXBeta() end
    end
    renderBeta = driftgod.R102_RenderBeta

    if driftgod.Log then driftgod.Log("[FlyingCarsSA] v1.0.23 Beta integration loaded under Arcade > Utilities > Beta") end
end)


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.24 patch: Power Glider beta replacement path
-- note: v1.0.23 embedded Flying Cars SA under Arcade > Utilities > Beta. This patch
--       keeps that source available but hides the flight UI and replaces it with a
--       speed-gated forward-momentum assist intended to supersede SuperDrive testing.
--       It does not add lift, does not disable gravity, and does not use camera/WASD
--       direction forcing; momentum is applied in the vehicle's current forward path.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or {}
    driftgod.S = driftgod.S or {}

    driftgod.Version = "v1.0.24"
    driftgod.BuildNumber = "2026.07.27.124"
    driftgod.BuildDate = "2026-07-27"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_24_Momentum_Drive_SA_Beta"

    local patch_name = "Power Glider"
    local mph_per_mps = 2.2369362920544
    local mps_per_mph = 0.44704

    local nh = {
        PLAYER_PED_ID = 0xD80958FC74E988A6,
        IS_PED_IN_ANY_VEHICLE = 0x997ABD671D25CA0B,
        GET_VEHICLE_PED_IS_IN = 0x9A9112A0FE9A4713,
        GET_PED_IN_VEHICLE_SEAT = 0xBB40DD2270B65366,
        DOES_ENTITY_EXIST = 0x7239B21A38F536BA,
        GET_ENTITY_SPEED = 0xD5037BA82E12416F,
        GET_ENTITY_SPEED_VECTOR = 0x9A8D700A51CB7B0D,
        GET_ENTITY_VELOCITY = 0x4805D2B1D8CF94A9,
        GET_ENTITY_FORWARD_VECTOR = 0x0A794A5A57F8DF91,
        SET_ENTITY_VELOCITY = 0x1C99BB7B6E96D16F,
        APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS = 0x18FF00FC7EFF559E,
        SET_VEHICLE_GRAVITY = 0x89F149B6131E57DA,
        GET_FRAME_TIME = 0x15C40837039FFAF7,
        GET_CONTROL_NORMAL = 0xEC3C9B8D5327B563,
        IS_CONTROL_PRESSED = 0xF3A21BCD95725A4A,
        GET_VEHICLE_CLASS = 0x29439776AAA00A62,
        IS_ENTITY_IN_AIR = 0x886E37EC497200B6,
    }

    local control = {
        ACCELERATE = 71,
        BRAKE = 72,
        HANDBRAKE = 76,
    }

    local runtime = driftgod.MomentumDriveSA or {
        active = false,
        lastVehicle = 0,
        peakSpeed = 0.0,
        activeSince = 0,
        lastLog = 0,
        tickCount = 0,
        lastStatus = "Ready",
        lastMph = 0.0,
        lastForce = 0.0,
        lastBlend = 0.0,
    }
    driftgod.MomentumDriveSA = runtime

    local function clamp(v, lo, hi)
        v = tonumber(v or lo) or lo
        if v < lo then return lo end
        if v > hi then return hi end
        return v
    end

    local function now_ms()
        if driftgod.GetMs then
            local ok, v = driftgod.Try(driftgod.GetMs)
            if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
        end
        if Natives and Natives.InvokeInt then
            local ok, v = driftgod.Try(function() return Natives.InvokeInt(0x9CD27B0045628463) end)
            if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
        end
        if os and os.clock then return math.floor(os.clock() * 1000) end
        return 0
    end

    local function log(msg)
        msg = "[MomentumDriveSA] " .. tostring(msg or "")
        if driftgod.Log then driftgod.Log(msg)
        elseif Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] " .. msg) end
    end

    local function toast(msg, ms)
        if driftgod.Toast then driftgod.Toast(tostring(msg or ""), ms or 1600)
        elseif GUI and GUI.AddToast then GUI.AddToast("DriftGod", tostring(msg or ""), ms or 1600) end
    end

    local function save_settings_quiet()
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
    end

    local function invoke_bool(hash, ...)
        if not (Natives and Natives.InvokeBool) then return false end
        local ok, v = driftgod.Try(function(...) return Natives.InvokeBool(hash, ...) end, ...)
        return ok == true and v == true
    end

    local function invoke_int(hash, ...)
        if not (Natives and Natives.InvokeInt) then return 0 end
        local ok, v = driftgod.Try(function(...) return Natives.InvokeInt(hash, ...) end, ...)
        return ok == true and (tonumber(v) or 0) or 0
    end

    local function invoke_float(hash, ...)
        if not (Natives and Natives.InvokeFloat) then return 0.0 end
        local ok, v = driftgod.Try(function(...) return Natives.InvokeFloat(hash, ...) end, ...)
        return ok == true and (tonumber(v) or 0.0) or 0.0
    end

    local function invoke_void(hash, ...)
        if not (Natives and Natives.InvokeVoid) then return false end
        local ok = driftgod.Try(function(...) Natives.InvokeVoid(hash, ...) end, ...)
        return ok == true
    end

    local function unpack_v3(a, b, c, dx, dy, dz)
        if type(a) == "table" then
            return tonumber(a.x or a.X or a[1]) or dx,
                   tonumber(a.y or a.Y or a[2]) or dy,
                   tonumber(a.z or a.Z or a[3]) or dz
        end
        if type(a) == "userdata" then
            local okx, x = driftgod.Try(function() return a.x or a.X end)
            local oky, y = driftgod.Try(function() return a.y or a.Y end)
            local okz, z = driftgod.Try(function() return a.z or a.Z end)
            if okx or oky or okz then
                return tonumber(x) or dx, tonumber(y) or dy, tonumber(z) or dz
            end
        end
        return tonumber(a) or dx, tonumber(b) or dy, tonumber(c) or dz
    end

    local function invoke_v3(hash, dx, dy, dz, ...)
        if not (Natives and Natives.InvokeV3) then return dx, dy, dz end
        local ok, a, b, c = driftgod.Try(function(...) return Natives.InvokeV3(hash, ...) end, ...)
        if ok then return unpack_v3(a, b, c, dx, dy, dz) end
        return dx, dy, dz
    end

    local function exists(entity)
        return entity and entity ~= 0 and invoke_bool(nh.DOES_ENTITY_EXIST, entity)
    end

    local function get_local_vehicle()
        local ped = invoke_int(nh.PLAYER_PED_ID)
        if ped == 0 or not invoke_bool(nh.IS_PED_IN_ANY_VEHICLE, ped, false) then return 0 end
        local veh = invoke_int(nh.GET_VEHICLE_PED_IS_IN, ped, false)
        if veh == 0 or not exists(veh) then return 0 end
        if invoke_int(nh.GET_PED_IN_VEHICLE_SEAT, veh, -1, false) ~= ped then return 0 end
        local class = invoke_int(nh.GET_VEHICLE_CLASS, veh)
        if class == 8 or class == 13 or class == 14 or class == 15 or class == 16 or class == 21 then return 0 end
        return veh
    end

    local function control_normal(id)
        return clamp(invoke_float(nh.GET_CONTROL_NORMAL, 0, id), 0.0, 1.0)
    end

    local function format_mph(v)
        return string.format("%.0f mph", tonumber(v or 0.0) or 0.0)
    end

    local function apply_relative_forward_force(vehicle, force)
        if math.abs(force) <= 0.0001 then return false end
        return invoke_void(nh.APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS, vehicle, 1, 0.0, force, 0.0, false, true, true, false)
    end

    local function set_velocity(vehicle, x, y, z)
        return invoke_void(nh.SET_ENTITY_VELOCITY, vehicle, x, y, z)
    end

    local function reset_runtime(reason)
        if runtime.active == true and reason and reason ~= "" then log("inactive | " .. tostring(reason)) end
        runtime.active = false
        runtime.lastVehicle = 0
        runtime.peakSpeed = 0.0
        runtime.activeSince = 0
        runtime.lastForce = 0.0
        runtime.lastBlend = 0.0
        runtime.lastStatus = tostring(reason or "Waiting")
    end

    local function ensure_defaults()
        driftgod.S = driftgod.S or {}
        if driftgod.S.momentumDriveSAEnabled == nil then driftgod.S.momentumDriveSAEnabled = false end
        if driftgod.S.momentumDriveSAThresholdMph == nil then driftgod.S.momentumDriveSAThresholdMph = 85.0 end
        if driftgod.S.momentumDriveSAStrength == nil then driftgod.S.momentumDriveSAStrength = 0.42 end
        if driftgod.S.momentumDriveSAMaxAssistMph == nil then driftgod.S.momentumDriveSAMaxAssistMph = 165.0 end
        if driftgod.S.momentumDriveSAHoldRatio == nil then driftgod.S.momentumDriveSAHoldRatio = 0.985 end
        if driftgod.S.momentumDriveSAHud == nil then driftgod.S.momentumDriveSAHud = true end
        if driftgod.S.momentumDriveSATelemetry == nil then driftgod.S.momentumDriveSATelemetry = false end
        if driftgod.S.momentumDriveSAAutoDisableSuperDrive == nil then driftgod.S.momentumDriveSAAutoDisableSuperDrive = true end
    end

    ensure_defaults()

    local function disable_old_flight_mode()
        if driftgod.FlyingCarsSA and driftgod.FlyingCarsSA.SetEnabled then
            driftgod.Try(function() driftgod.FlyingCarsSA.SetEnabled(false) end)
        end
        if driftgod.FlyingCarsSA and driftgod.FlyingCarsSA.state then
            driftgod.FlyingCarsSA.state.enabled = false
        end
    end

    function driftgod.ToggleMomentumDriveSA()
        ensure_defaults()
        driftgod.S.momentumDriveSAEnabled = not (driftgod.S.momentumDriveSAEnabled == true)
        disable_old_flight_mode()
        if driftgod.S.momentumDriveSAEnabled == true then
            if driftgod.S.momentumDriveSAAutoDisableSuperDrive ~= false then
                driftgod.S.superDriveEnabled = false
            end
            toast("Power Glider armed at " .. format_mph(driftgod.S.momentumDriveSAThresholdMph), 2400)
            log("armed | threshold=" .. tostring(driftgod.S.momentumDriveSAThresholdMph) .. "mph strength=" .. tostring(driftgod.S.momentumDriveSAStrength))
        else
            reset_runtime("disabled")
            toast("Power Glider disabled.", 1800)
        end
        save_settings_quiet()
    end

    function driftgod.SetMomentumDriveSAEnabled(enabled)
        ensure_defaults()
        driftgod.S.momentumDriveSAEnabled = enabled == true
        disable_old_flight_mode()
        if driftgod.S.momentumDriveSAEnabled and driftgod.S.momentumDriveSAAutoDisableSuperDrive ~= false then
            driftgod.S.superDriveEnabled = false
        end
        if not driftgod.S.momentumDriveSAEnabled then reset_runtime("disabled") end
        save_settings_quiet()
    end

    function driftgod.MomentumDriveSAThresholdDelta(delta)
        ensure_defaults()
        driftgod.S.momentumDriveSAThresholdMph = clamp((tonumber(driftgod.S.momentumDriveSAThresholdMph) or 85.0) + (tonumber(delta) or 0.0), 25.0, 180.0)
        toast("Momentum threshold: " .. format_mph(driftgod.S.momentumDriveSAThresholdMph), 1500)
        save_settings_quiet()
    end

    function driftgod.MomentumDriveSAStrengthDelta(delta)
        ensure_defaults()
        driftgod.S.momentumDriveSAStrength = clamp((tonumber(driftgod.S.momentumDriveSAStrength) or 0.42) + (tonumber(delta) or 0.0), 0.05, 1.50)
        toast("Momentum strength: " .. string.format("%.2f", driftgod.S.momentumDriveSAStrength), 1500)
        save_settings_quiet()
    end

    function driftgod.MomentumDriveSAMaxAssistDelta(delta)
        ensure_defaults()
        driftgod.S.momentumDriveSAMaxAssistMph = clamp((tonumber(driftgod.S.momentumDriveSAMaxAssistMph) or 165.0) + (tonumber(delta) or 0.0), 60.0, 260.0)
        toast("Momentum cap: " .. format_mph(driftgod.S.momentumDriveSAMaxAssistMph), 1500)
        save_settings_quiet()
    end

    function driftgod.ResetMomentumDriveSA()
        driftgod.S.momentumDriveSAThresholdMph = 85.0
        driftgod.S.momentumDriveSAStrength = 0.42
        driftgod.S.momentumDriveSAMaxAssistMph = 165.0
        driftgod.S.momentumDriveSAHoldRatio = 0.985
        reset_runtime("reset")
        toast("Power Glider settings reset.", 1800)
        save_settings_quiet()
    end

    function driftgod.MomentumDriveSAStatus()
        ensure_defaults()
        local stateLabel = runtime.active and "ACTIVE" or "ARMED"
        if driftgod.S.momentumDriveSAEnabled ~= true then stateLabel = "OFF" end
        return "Power Glider: " .. stateLabel
            .. " | Speed: " .. format_mph(runtime.lastMph or 0.0)
            .. " | Arms at: " .. format_mph(driftgod.S.momentumDriveSAThresholdMph)
            .. " | Strength: " .. string.format("%.2f", tonumber(driftgod.S.momentumDriveSAStrength or 0.42) or 0.42)
            .. " | Cap: " .. format_mph(driftgod.S.momentumDriveSAMaxAssistMph)
            .. " | Direction: Vehicle momentum"
    end

    local function tick_momentum_drive()
        ensure_defaults()
        disable_old_flight_mode()

        if driftgod.S.momentumDriveSAEnabled ~= true then
            if runtime.active == true then reset_runtime("disabled") end
            return false
        end

        if driftgod.S.momentumDriveSAAutoDisableSuperDrive ~= false and driftgod.S.superDriveEnabled == true then
            driftgod.S.superDriveEnabled = false
        end

        local veh = get_local_vehicle()
        if veh == 0 then
            if runtime.active == true then reset_runtime("no supported driver vehicle") end
            runtime.lastStatus = "Enter a supported driver's seat."
            return true
        end

        invoke_void(nh.SET_VEHICLE_GRAVITY, veh, true)

        local speed = invoke_float(nh.GET_ENTITY_SPEED, veh)
        local mph = speed * mph_per_mps
        runtime.lastMph = mph

        local threshold_mph = clamp(driftgod.S.momentumDriveSAThresholdMph, 25.0, 180.0)
        local max_mph = clamp(driftgod.S.momentumDriveSAMaxAssistMph, threshold_mph + 5.0, 260.0)
        local strength = clamp(driftgod.S.momentumDriveSAStrength, 0.05, 1.50)
        local threshold_mps = threshold_mph * mps_per_mph
        local max_mps = max_mph * mps_per_mph
        local side_local, forward_local, vertical_local = invoke_v3(nh.GET_ENTITY_SPEED_VECTOR, 0.0, 0.0, 0.0, veh, true)
        local throttle = control_normal(control.ACCELERATE)
        local brake = math.max(control_normal(control.BRAKE), invoke_bool(nh.IS_CONTROL_PRESSED, 0, control.HANDBRAKE) and 1.0 or 0.0)
        local airborne = invoke_bool(nh.IS_ENTITY_IN_AIR, veh)

        if forward_local < threshold_mps or mph < threshold_mph or brake > 0.35 then
            if runtime.active == true and brake > 0.35 then reset_runtime("brake cancelled")
            elseif runtime.active == true and mph < threshold_mph - 5.0 then reset_runtime("below threshold") end
            runtime.peakSpeed = math.max(0.0, runtime.peakSpeed * 0.965)
            runtime.lastForce = 0.0
            runtime.lastBlend = 0.0
            runtime.lastStatus = "Waiting for " .. format_mph(threshold_mph)
            return true
        end

        local now = now_ms()
        if runtime.lastVehicle ~= veh then
            runtime.lastVehicle = veh
            runtime.peakSpeed = speed
            runtime.activeSince = now
        end

        if runtime.active ~= true then
            runtime.active = true
            runtime.activeSince = now
            log("active | speed=" .. format_mph(mph) .. " threshold=" .. format_mph(threshold_mph))
        end

        local dt = clamp(invoke_float(nh.GET_FRAME_TIME), 1.0 / 240.0, 0.05)
        local hold_ratio = clamp(tonumber(driftgod.S.momentumDriveSAHoldRatio or 0.985) or 0.985, 0.940, 0.998)
        local decay = brake > 0.05 and 0.940 or (throttle > 0.05 and hold_ratio or 0.972)
        runtime.peakSpeed = math.max(speed, math.min(max_mps, runtime.peakSpeed * decay))

        local over_threshold = clamp((speed - threshold_mps) / math.max(1.0, max_mps - threshold_mps), 0.0, 1.0)
        local assist_scale = (0.35 + over_threshold * 0.65) * (0.35 + throttle * 0.65)
        if airborne then assist_scale = assist_scale * 0.50 end
        if brake > 0.05 then assist_scale = assist_scale * clamp(1.0 - brake * 1.35, 0.0, 1.0) end

        local force = clamp(strength * assist_scale, 0.0, 1.35)
        apply_relative_forward_force(veh, force)

        local target_speed = math.max(threshold_mps, runtime.peakSpeed * hold_ratio)
        target_speed = math.min(target_speed, max_mps)
        local missing = math.max(0.0, target_speed - speed)
        local blend = 0.0
        if missing > 0.10 and brake < 0.05 then
            local fx, fy, fz = invoke_v3(nh.GET_ENTITY_FORWARD_VECTOR, 0.0, 1.0, 0.0, veh)
            local vx, vy, vz = invoke_v3(nh.GET_ENTITY_VELOCITY, 0.0, 0.0, 0.0, veh)
            blend = clamp(missing * (0.0065 + strength * 0.0045) * (0.35 + throttle * 0.65), 0.0, 0.115)
            if airborne then blend = blend * 0.45 end
            set_velocity(veh, vx + fx * blend, vy + fy * blend, vz)
        end

        runtime.lastForce = force
        runtime.lastBlend = blend
        runtime.tickCount = (runtime.tickCount or 0) + 1
        runtime.lastStatus = "Active"

        if driftgod.S.momentumDriveSATelemetry == true and now - (runtime.lastLog or 0) > 850 then
            runtime.lastLog = now
            log("tick | mph=" .. string.format("%.1f", mph)
                .. " forward=" .. string.format("%.2f", forward_local)
                .. " peak=" .. string.format("%.2f", runtime.peakSpeed)
                .. " force=" .. string.format("%.3f", force)
                .. " blend=" .. string.format("%.4f", blend)
                .. " throttle=" .. string.format("%.2f", throttle)
                .. " brake=" .. string.format("%.2f", brake))
        end

        return true
    end

    driftgod.MomentumDriveSATick = tick_momentum_drive

    if not driftgod.__MomentumDriveSALoop124Installed then
        driftgod.__MomentumDriveSALoop124Installed = true
        if Script and Script.RegisterLooped then
            Script.RegisterLooped(function()
                if ShouldUnload and ShouldUnload() then return false end
                local active = false
                if driftgod.MomentumDriveSATick then active = driftgod.MomentumDriveSATick() == true end
                if Script and Script.Yield then Script.Yield(active and 0 or 140) end
            end)
        elseif FeatureMgr and FeatureMgr.AddFeature and Utils and Utils.Joaat and eFeatureType then
            driftgod.SafeAddFeature(Utils.Joaat("DG_MOMENTUM_DRIVE_SA_TICK_124"), "DG Power Glider Runtime", eFeatureType.Script, "Hidden runtime for Power Glider.", function()
                if driftgod.MomentumDriveSATick then driftgod.MomentumDriveSATick() end
            end)
        end
    end

    local function ui_text_line(text)
        if ImGui and ImGui.TextWrapped then ImGui.TextWrapped(tostring(text or ""))
        elseif ImGui and ImGui.Text then ImGui.Text(tostring(text or "")) end
    end

    local function ui_text_color(text, r, g, b, a)
        if ImGui and ImGui.TextColored then ImGui.TextColored(r or 1.0, g or 1.0, b or 1.0, a or 1.0, tostring(text or ""))
        else ui_text_line(text) end
    end

    local function ui_sep()
        if ImGui and ImGui.Separator then ImGui.Separator() end
    end

    local function ui_same()
        if ImGui and ImGui.SameLine then ImGui.SameLine() end
    end

    local function ui_button(label, w)
        if ImGui and ImGui.Button then return ImGui.Button(tostring(label or "Button"), w or -1, 0) == true end
        return false
    end

    local function render_pair(label, value)
        ui_text_color(tostring(label or ""), 0.72, 0.78, 0.88, 1.0)
        ui_same()
        ui_text_color(tostring(value or ""), 0.96, 0.97, 1.00, 1.0)
    end

    function driftgod.R124_RenderMomentumDriveSA()
        ensure_defaults()
        if not (ClickGUI and ClickGUI.BeginCustomChildWindow) then return end

        if ClickGUI.BeginCustomChildWindow("Power Glider (BETA)") then
            ui_text_color("Power Glider (BETA)", 0.72, 0.42, 1.00, 1.00)
            ui_text_line("SuperDrive replacement test: speed-gated forward momentum, no flying, no lift, no camera steering.")
            ui_text_color("Arms after your chosen speed, then carries momentum in the vehicle's current direction.", 0.70, 0.92, 0.76, 1.00)
            ui_sep()

            render_pair("Status:", driftgod.MomentumDriveSAStatus and driftgod.MomentumDriveSAStatus() or "Power Glider")
            render_pair("Runtime:", tostring(runtime.lastStatus or "Ready"))

            if ui_button((driftgod.S.momentumDriveSAEnabled == true and "Disable" or "Enable") .. " Power Glider", -1) then
                if driftgod.ToggleMomentumDriveSA then driftgod.ToggleMomentumDriveSA() end
            end

            ui_sep()
            ui_text_color("Speed Gate", 0.35, 0.86, 1.00, 1.00)
            render_pair("Activation Speed:", format_mph(driftgod.S.momentumDriveSAThresholdMph))
            if ui_button("Threshold -5 mph", 170) then driftgod.MomentumDriveSAThresholdDelta(-5.0) end
            ui_same()
            if ui_button("Threshold +5 mph", 170) then driftgod.MomentumDriveSAThresholdDelta(5.0) end

            ui_text_color("Momentum Tuning", 1.00, 0.78, 0.18, 1.00)
            render_pair("Strength:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSAStrength or 0.42) or 0.42))
            if ui_button("Strength -", 170) then driftgod.MomentumDriveSAStrengthDelta(-0.05) end
            ui_same()
            if ui_button("Strength +", 170) then driftgod.MomentumDriveSAStrengthDelta(0.05) end

            render_pair("Assist Cap:", format_mph(driftgod.S.momentumDriveSAMaxAssistMph))
            if ui_button("Cap -10 mph", 170) then driftgod.MomentumDriveSAMaxAssistDelta(-10.0) end
            ui_same()
            if ui_button("Cap +10 mph", 170) then driftgod.MomentumDriveSAMaxAssistDelta(10.0) end

            ui_sep()
            if ui_button("Reset Momentum Drive Settings", -1) then driftgod.ResetMomentumDriveSA() end

            ui_sep()
            if ui_button((driftgod.S.momentumDriveSAHud == true and "HUD: ON" or "HUD: OFF"), 170) then
                driftgod.S.momentumDriveSAHud = not (driftgod.S.momentumDriveSAHud == true)
                save_settings_quiet()
            end
            ui_same()
            if ui_button((driftgod.S.momentumDriveSATelemetry == true and "Telemetry: ON" or "Telemetry: OFF"), 170) then
                driftgod.S.momentumDriveSATelemetry = not (driftgod.S.momentumDriveSATelemetry == true)
                save_settings_quiet()
            end

            ui_text_color("Notes", 0.54, 0.60, 0.70, 1.00)
            ui_text_line("This intentionally bypasses the old Flying Cars lift model and auto-disables SuperDrive while armed.")
            ui_text_line("Use this as the new low-risk SuperDrive replacement candidate.")
            ClickGUI.EndCustomChildWindow()
        end
    end

    -- Replace the v1.0.23 Flying Cars beta panel with the speed-gated Momentum Drive panel.
    driftgod.R123_RenderFlyingCarsSA = driftgod.R124_RenderMomentumDriveSA

    local oldBeta = driftgod.R102_RenderBeta
    driftgod.R124_PreMomentumDriveBetaRenderer = oldBeta
    driftgod.R102_RenderBeta = function()
        if driftgod.R279_RenderSuperDriveBeta then
            driftgod.R279_RenderSuperDriveBeta()
        elseif driftgod.R140_RenderSuperDriveBeta then
            driftgod.R140_RenderSuperDriveBeta()
        end

        if driftgod.R124_RenderMomentumDriveSA then driftgod.R124_RenderMomentumDriveSA() end

        if driftgod.R279_RenderRoadSurfaceBeta then driftgod.R279_RenderRoadSurfaceBeta() end
        if driftgod.R140_RenderPTFXBeta then driftgod.R140_RenderPTFXBeta() end
    end
    renderBeta = driftgod.R102_RenderBeta

    if EventMgr and eLuaEvent and eLuaEvent.ON_PRESENT and not driftgod.__MomentumDriveSAHud124Installed then
        driftgod.__MomentumDriveSAHud124Installed = true
        EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
            if not (driftgod.S and driftgod.S.momentumDriveSAEnabled == true and driftgod.S.momentumDriveSAHud == true) then return end
            if not (ImGui and ImGui.GetDisplaySize and ImGui.BgAddText) then return end
            local w, h = ImGui.GetDisplaySize()
            w, h = tonumber(w) or 0.0, tonumber(h) or 0.0
            if w <= 0 or h <= 0 then return end
            local text = (runtime.active and "MOMENTUM DRIVE ACTIVE" or "MOMENTUM DRIVE ARMED")
                .. "  |  " .. format_mph(runtime.lastMph or 0.0)
                .. " / " .. format_mph(driftgod.S.momentumDriveSAThresholdMph or 85.0)
            local x = w * 0.5 - (#text * 3.4)
            local y = h - 104
            ImGui.BgAddText(x + 1, y + 1, text, 0, 0, 0, 210)
            ImGui.BgAddText(x, y, text, runtime.active and 90 or 210, runtime.active and 255 or 220, runtime.active and 135 or 255, 245)
        end)
    end

    disable_old_flight_mode()
    log("v1.0.24 loaded | Flying Cars beta UI replaced by speed-gated same-direction Power Glider")
end)


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.25 patch: Grounded Camera Power Glider
-- note: v1.0.24 proved the speed-gated momentum concept. This patch moves the
--       feature closer to Flying Cars SA's control feel while keeping it grounded:
--       camera/vehicle guidance modes, throttle-controlled speed build, brake drag,
--       speed gate activation, gravity locked on, zero lift, and no airborne assist.
--       It is intended to replace the old SuperDrive beta panel.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or {}
    driftgod.S = driftgod.S or {}

    driftgod.Version = "v1.0.25"
    driftgod.BuildNumber = "2026.07.27.125"
    driftgod.BuildDate = "2026-07-27"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_25_Grounded_Camera_Momentum"

    local mph_per_mps = 2.2369362920544
    local mps_per_mph = 0.44704

    local nh = {
        PLAYER_PED_ID = 0xD80958FC74E988A6,
        IS_PED_IN_ANY_VEHICLE = 0x997ABD671D25CA0B,
        GET_VEHICLE_PED_IS_IN = 0x9A9112A0FE9A4713,
        GET_PED_IN_VEHICLE_SEAT = 0xBB40DD2270B65366,
        DOES_ENTITY_EXIST = 0x7239B21A38F536BA,
        GET_ENTITY_SPEED = 0xD5037BA82E12416F,
        GET_ENTITY_SPEED_VECTOR = 0x9A8D700A51CB7B0D,
        GET_ENTITY_VELOCITY = 0x4805D2B1D8CF94A9,
        GET_ENTITY_FORWARD_VECTOR = 0x0A794A5A57F8DF91,
        SET_ENTITY_VELOCITY = 0x1C99BB7B6E96D16F,
        APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS = 0x18FF00FC7EFF559E,
        SET_VEHICLE_GRAVITY = 0x89F149B6131E57DA,
        GET_FRAME_TIME = 0x15C40837039FFAF7,
        GET_CONTROL_NORMAL = 0xEC3C9B8D5327B563,
        IS_CONTROL_PRESSED = 0xF3A21BCD95725A4A,
        GET_VEHICLE_CLASS = 0x29439776AAA00A62,
        IS_ENTITY_IN_AIR = 0x886E37EC497200B6,
        IS_VEHICLE_ON_ALL_WHEELS = 0xB104CD1BABF302E2,
        GET_GAMEPLAY_CAM_ROT = 0x837765A25378F0BB,
        GET_FINAL_RENDERED_CAM_ROT = 0x5B4E4C817FCC2DFB,
    }

    local control = {
        ACCELERATE = 71,
        BRAKE = 72,
        HANDBRAKE = 76,
        VEH_FLY_THROTTLE_UP = 87,
        VEH_FLY_THROTTLE_DN = 88,
    }

    local runtime = driftgod.MomentumDriveSA or {}
    driftgod.MomentumDriveSA = runtime
    runtime.active = false
    runtime.commandSpeed = runtime.commandSpeed or 0.0
    runtime.lastMode = runtime.lastMode or "camera"
    runtime.lastStatus = runtime.lastStatus or "Ready"
    runtime.lastMph = runtime.lastMph or 0.0
    runtime.lastTargetMph = runtime.lastTargetMph or 0.0
    runtime.lastForce = runtime.lastForce or 0.0
    runtime.lastBlend = runtime.lastBlend or 0.0
    runtime.lastLog = runtime.lastLog or 0
    runtime.modeKeyDown = false

    local function clamp(v, lo, hi)
        v = tonumber(v or lo) or lo
        if v < lo then return lo end
        if v > hi then return hi end
        return v
    end

    local function lerp(a, b, t)
        return (tonumber(a) or 0.0) + ((tonumber(b) or 0.0) - (tonumber(a) or 0.0)) * clamp(t, 0.0, 1.0)
    end

    local function magnitude2(x, y)
        x, y = tonumber(x) or 0.0, tonumber(y) or 0.0
        return math.sqrt(x * x + y * y)
    end

    local function normalize2(x, y, fx, fy)
        x, y = tonumber(x) or 0.0, tonumber(y) or 0.0
        local m = math.sqrt(x * x + y * y)
        if m < 0.0001 then return tonumber(fx) or 0.0, tonumber(fy) or 1.0, false end
        return x / m, y / m, true
    end

    local function now_ms()
        if driftgod.GetMs then
            local ok, v = driftgod.Try(driftgod.GetMs)
            if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
        end
        if Natives and Natives.InvokeInt then
            local ok, v = driftgod.Try(function() return Natives.InvokeInt(0x9CD27B0045628463) end)
            if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
        end
        if os and os.clock then return math.floor(os.clock() * 1000) end
        return 0
    end

    local function log(msg)
        msg = "[MomentumDriveSA] " .. tostring(msg or "")
        if driftgod.Log then driftgod.Log(msg)
        elseif Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] " .. msg) end
    end

    local function toast(msg, ms)
        if driftgod.Toast then driftgod.Toast(tostring(msg or ""), ms or 1600)
        elseif GUI and GUI.AddToast then GUI.AddToast("DriftGod", tostring(msg or ""), ms or 1600) end
    end

    local function save_settings_quiet()
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
    end

    local function invoke_bool(hash, ...)
        if not (Natives and Natives.InvokeBool) then return false end
        local ok, v = driftgod.Try(function(...) return Natives.InvokeBool(hash, ...) end, ...)
        return ok == true and v == true
    end

    local function invoke_int(hash, ...)
        if not (Natives and Natives.InvokeInt) then return 0 end
        local ok, v = driftgod.Try(function(...) return Natives.InvokeInt(hash, ...) end, ...)
        return ok == true and (tonumber(v) or 0) or 0
    end

    local function invoke_float(hash, ...)
        if not (Natives and Natives.InvokeFloat) then return 0.0 end
        local ok, v = driftgod.Try(function(...) return Natives.InvokeFloat(hash, ...) end, ...)
        return ok == true and (tonumber(v) or 0.0) or 0.0
    end

    local function invoke_void(hash, ...)
        if not (Natives and Natives.InvokeVoid) then return false end
        local ok = driftgod.Try(function(...) Natives.InvokeVoid(hash, ...) end, ...)
        return ok == true
    end

    local function unpack_v3(a, b, c, dx, dy, dz)
        if type(a) == "table" then
            return tonumber(a.x or a.X or a[1]) or dx,
                   tonumber(a.y or a.Y or a[2]) or dy,
                   tonumber(a.z or a.Z or a[3]) or dz
        end
        if type(a) == "userdata" then
            local okx, x = driftgod.Try(function() return a.x or a.X end)
            local oky, y = driftgod.Try(function() return a.y or a.Y end)
            local okz, z = driftgod.Try(function() return a.z or a.Z end)
            if okx or oky or okz then
                return tonumber(x) or dx, tonumber(y) or dy, tonumber(z) or dz
            end
        end
        return tonumber(a) or dx, tonumber(b) or dy, tonumber(c) or dz
    end

    local function invoke_v3(hash, dx, dy, dz, ...)
        if not (Natives and Natives.InvokeV3) then return dx, dy, dz end
        local ok, a, b, c = driftgod.Try(function(...) return Natives.InvokeV3(hash, ...) end, ...)
        if ok then return unpack_v3(a, b, c, dx, dy, dz) end
        return dx, dy, dz
    end

    local function exists(entity)
        return entity and entity ~= 0 and invoke_bool(nh.DOES_ENTITY_EXIST, entity)
    end

    local function get_local_vehicle()
        local ped = invoke_int(nh.PLAYER_PED_ID)
        if ped == 0 or not invoke_bool(nh.IS_PED_IN_ANY_VEHICLE, ped, false) then return 0 end
        local veh = invoke_int(nh.GET_VEHICLE_PED_IS_IN, ped, false)
        if veh == 0 or not exists(veh) then return 0 end
        if invoke_int(nh.GET_PED_IN_VEHICLE_SEAT, veh, -1, false) ~= ped then return 0 end
        local class = invoke_int(nh.GET_VEHICLE_CLASS, veh)
        if class == 8 or class == 13 or class == 14 or class == 15 or class == 16 or class == 21 then return 0 end
        return veh
    end

    local function control_normal(id)
        return clamp(invoke_float(nh.GET_CONTROL_NORMAL, 0, id), 0.0, 1.0)
    end

    local function key_down(vk)
        local down = false
        driftgod.Try(function()
            if Utils and Utils.IsKeyDown and Utils.IsKeyDown(vk) then down = true end
        end)
        return down
    end

    local function gui_open()
        local open = false
        driftgod.Try(function()
            if GUI and GUI.IsOpen and GUI.IsOpen() == true then open = true end
        end)
        return open
    end

    local function rotation_to_direction(rx, rz)
        local rad_x = math.rad(tonumber(rx) or 0.0)
        local rad_z = math.rad(tonumber(rz) or 0.0)
        local horizontal = math.abs(math.cos(rad_x))
        return -math.sin(rad_z) * horizontal, math.cos(rad_z) * horizontal
    end

    local function get_camera_direction_horizontal()
        local rx, _, rz = invoke_v3(nh.GET_GAMEPLAY_CAM_ROT, 0.0, 0.0, 0.0, 2)
        if math.abs(rx or 0.0) < 0.001 and math.abs(rz or 0.0) < 0.001 then
            rx, _, rz = invoke_v3(nh.GET_FINAL_RENDERED_CAM_ROT, 0.0, 0.0, 0.0, 2)
        end
        local x, y = rotation_to_direction(rx, rz)
        return normalize2(x, y, 0.0, 1.0)
    end

    local function get_vehicle_direction_horizontal(veh)
        local x, y, _ = invoke_v3(nh.GET_ENTITY_FORWARD_VECTOR, 0.0, 1.0, 0.0, veh)
        return normalize2(x, y, 0.0, 1.0)
    end

    local function get_drive_direction(veh)
        local mode = tostring(driftgod.S.momentumDriveSADirectionMode or "camera")
        if mode == "vehicle" then
            return get_vehicle_direction_horizontal(veh)
        end
        local x, y, ok = get_camera_direction_horizontal()
        if ok then return x, y, true end
        return get_vehicle_direction_horizontal(veh)
    end

    local function apply_world_force(veh, x, y, z)
        if math.abs(x or 0.0) + math.abs(y or 0.0) + math.abs(z or 0.0) <= 0.0001 then return false end
        return invoke_void(nh.APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS, veh, 1, x, y, z, true, false, true, true)
    end

    local function set_velocity(veh, x, y, z)
        return invoke_void(nh.SET_ENTITY_VELOCITY, veh, x, y, z)
    end

    local function format_mph(v)
        return string.format("%.0f mph", tonumber(v or 0.0) or 0.0)
    end

    local function direction_label()
        return tostring(driftgod.S.momentumDriveSADirectionMode or "camera") == "vehicle" and "Vehicle Nose" or "Gameplay Camera"
    end

    local function ensure_defaults()
        driftgod.S = driftgod.S or {}
        if driftgod.S.momentumDriveSAEnabled == nil then driftgod.S.momentumDriveSAEnabled = false end
        if driftgod.S.momentumDriveSAThresholdMph == nil then driftgod.S.momentumDriveSAThresholdMph = 85.0 end
        if driftgod.S.momentumDriveSAStrength == nil then driftgod.S.momentumDriveSAStrength = 0.55 end
        if driftgod.S.momentumDriveSAMaxAssistMph == nil then driftgod.S.momentumDriveSAMaxAssistMph = 165.0 end
        if driftgod.S.momentumDriveSAHoldRatio == nil then driftgod.S.momentumDriveSAHoldRatio = 0.988 end
        if driftgod.S.momentumDriveSAHud == nil then driftgod.S.momentumDriveSAHud = true end
        if driftgod.S.momentumDriveSATelemetry == nil then driftgod.S.momentumDriveSATelemetry = false end
        if driftgod.S.momentumDriveSAAutoDisableSuperDrive == nil then driftgod.S.momentumDriveSAAutoDisableSuperDrive = true end
        if driftgod.S.momentumDriveSADirectionMode ~= "vehicle" then driftgod.S.momentumDriveSADirectionMode = "camera" end
        if driftgod.S.momentumDriveSAModeToggleKey == nil then driftgod.S.momentumDriveSAModeToggleKey = 0xA0 end
        if driftgod.S.momentumDriveSACameraSteer == nil then driftgod.S.momentumDriveSACameraSteer = 0.72 end
        if driftgod.S.momentumDriveSABrakeDrag == nil then driftgod.S.momentumDriveSABrakeDrag = 0.44 end
        if driftgod.S.momentumDriveSAGroundOnly == nil then driftgod.S.momentumDriveSAGroundOnly = true end
    end

    local function disable_old_modes()
        if driftgod.FlyingCarsSA and driftgod.FlyingCarsSA.SetEnabled then
            driftgod.Try(function() driftgod.FlyingCarsSA.SetEnabled(false) end)
        end
        if driftgod.FlyingCarsSA and driftgod.FlyingCarsSA.state then
            driftgod.FlyingCarsSA.state.enabled = false
        end
        if driftgod.S then
            driftgod.S.superDriveEnabled = false
            driftgod.S._superDriveLastState = false
        end
    end

    local function reset_runtime(reason)
        if runtime.active == true and reason and reason ~= "" then log("inactive | " .. tostring(reason)) end
        runtime.active = false
        runtime.lastVehicle = 0
        runtime.commandSpeed = 0.0
        runtime.lastForce = 0.0
        runtime.lastBlend = 0.0
        runtime.lastTargetMph = 0.0
        runtime.lastStatus = tostring(reason or "Waiting")
    end

    function driftgod.SetMomentumDriveSADirectionMode(mode)
        ensure_defaults()
        mode = mode == "vehicle" and "vehicle" or "camera"
        driftgod.S.momentumDriveSADirectionMode = mode
        runtime.lastMode = mode
        toast("Momentum Drive mode: " .. direction_label(), 1600)
        log("mode=" .. tostring(mode))
        save_settings_quiet()
    end

    function driftgod.ToggleMomentumDriveSADirectionMode()
        ensure_defaults()
        local next_mode = tostring(driftgod.S.momentumDriveSADirectionMode or "camera") == "camera" and "vehicle" or "camera"
        driftgod.SetMomentumDriveSADirectionMode(next_mode)
    end

    local oldToggle = driftgod.ToggleMomentumDriveSA
    function driftgod.ToggleMomentumDriveSA()
        ensure_defaults()
        driftgod.S.momentumDriveSAEnabled = not (driftgod.S.momentumDriveSAEnabled == true)
        disable_old_modes()
        if driftgod.S.momentumDriveSAEnabled == true then
            runtime.commandSpeed = 0.0
            runtime.active = false
            toast("Power Glider armed | " .. direction_label(), 2400)
            log("armed | threshold=" .. tostring(driftgod.S.momentumDriveSAThresholdMph) .. "mph mode=" .. tostring(driftgod.S.momentumDriveSADirectionMode))
        else
            reset_runtime("disabled")
            toast("Power Glider disabled.", 1800)
        end
        save_settings_quiet()
    end

    function driftgod.SetMomentumDriveSAEnabled(enabled)
        ensure_defaults()
        driftgod.S.momentumDriveSAEnabled = enabled == true
        disable_old_modes()
        if not driftgod.S.momentumDriveSAEnabled then reset_runtime("disabled") end
        save_settings_quiet()
    end

    function driftgod.MomentumDriveSASteerDelta(delta)
        ensure_defaults()
        driftgod.S.momentumDriveSACameraSteer = clamp((tonumber(driftgod.S.momentumDriveSACameraSteer) or 0.72) + (tonumber(delta) or 0.0), 0.10, 1.50)
        toast("Camera guide: " .. string.format("%.2f", driftgod.S.momentumDriveSACameraSteer), 1500)
        save_settings_quiet()
    end

    function driftgod.MomentumDriveSABrakeDelta(delta)
        ensure_defaults()
        driftgod.S.momentumDriveSABrakeDrag = clamp((tonumber(driftgod.S.momentumDriveSABrakeDrag) or 0.44) + (tonumber(delta) or 0.0), 0.10, 1.20)
        toast("Brake drag: " .. string.format("%.2f", driftgod.S.momentumDriveSABrakeDrag), 1500)
        save_settings_quiet()
    end

    local oldReset = driftgod.ResetMomentumDriveSA
    function driftgod.ResetMomentumDriveSA()
        driftgod.S.momentumDriveSAThresholdMph = 85.0
        driftgod.S.momentumDriveSAStrength = 0.55
        driftgod.S.momentumDriveSAMaxAssistMph = 165.0
        driftgod.S.momentumDriveSAHoldRatio = 0.988
        driftgod.S.momentumDriveSADirectionMode = "camera"
        driftgod.S.momentumDriveSACameraSteer = 0.72
        driftgod.S.momentumDriveSABrakeDrag = 0.44
        driftgod.S.momentumDriveSAGroundOnly = true
        reset_runtime("reset")
        toast("Power Glider settings reset.", 1800)
        save_settings_quiet()
    end

    function driftgod.MomentumDriveSAStatus()
        ensure_defaults()
        local state_label = runtime.active and "ACTIVE" or "ARMED"
        if driftgod.S.momentumDriveSAEnabled ~= true then state_label = "OFF" end
        return "Power Glider: " .. state_label
            .. " | Mode: " .. direction_label()
            .. " | Speed: " .. format_mph(runtime.lastMph or 0.0)
            .. " | Target: " .. format_mph(runtime.lastTargetMph or 0.0)
            .. " | Arms: " .. format_mph(driftgod.S.momentumDriveSAThresholdMph)
            .. " | Cap: " .. format_mph(driftgod.S.momentumDriveSAMaxAssistMph)
    end

    local function update_mode_hotkey()
        ensure_defaults()
        local key = tonumber(driftgod.S.momentumDriveSAModeToggleKey or 0xA0) or 0xA0
        local down = false
        if not gui_open() then down = key_down(key) end
        if down and runtime.modeKeyDown ~= true then
            driftgod.ToggleMomentumDriveSADirectionMode()
        end
        runtime.modeKeyDown = down
    end

    local function tick_grounded_camera_momentum()
        ensure_defaults()
        disable_old_modes()
        update_mode_hotkey()

        if driftgod.S.momentumDriveSAEnabled ~= true then
            if runtime.active == true then reset_runtime("disabled") end
            return false
        end

        local veh = get_local_vehicle()
        if veh == 0 then
            if runtime.active == true then reset_runtime("no supported driver vehicle") end
            runtime.lastStatus = "Enter a supported driver's seat."
            return true
        end

        invoke_void(nh.SET_VEHICLE_GRAVITY, veh, true)

        local vx, vy, vz = invoke_v3(nh.GET_ENTITY_VELOCITY, 0.0, 0.0, 0.0, veh)
        local hspeed = magnitude2(vx, vy)
        local mph = hspeed * mph_per_mps
        runtime.lastMph = mph

        local threshold_mph = clamp(driftgod.S.momentumDriveSAThresholdMph, 25.0, 180.0)
        local max_mph = clamp(driftgod.S.momentumDriveSAMaxAssistMph, threshold_mph + 5.0, 260.0)
        local strength = clamp(driftgod.S.momentumDriveSAStrength, 0.05, 1.50)
        local threshold_mps = threshold_mph * mps_per_mph
        local max_mps = max_mph * mps_per_mph
        local dt = clamp(invoke_float(nh.GET_FRAME_TIME), 1.0 / 240.0, 0.05)
        local throttle = math.max(control_normal(control.ACCELERATE), control_normal(control.VEH_FLY_THROTTLE_UP))
        local brake = math.max(control_normal(control.BRAKE), control_normal(control.VEH_FLY_THROTTLE_DN))
        if invoke_bool(nh.IS_CONTROL_PRESSED, 0, control.HANDBRAKE) then brake = 1.0 end

        local airborne = invoke_bool(nh.IS_ENTITY_IN_AIR, veh)
        if driftgod.S.momentumDriveSAGroundOnly ~= false and airborne then
            if runtime.active == true then reset_runtime("airborne pause") end
            runtime.lastStatus = "Ground contact required."
            runtime.lastForce = 0.0
            runtime.lastBlend = 0.0
            return true
        end

        if mph < threshold_mph then
            if runtime.active == true and mph < threshold_mph - 4.0 then reset_runtime("below speed gate") end
            runtime.commandSpeed = math.max(0.0, math.min(runtime.commandSpeed or 0.0, max_mps) * 0.985)
            runtime.lastStatus = "Waiting for " .. format_mph(threshold_mph)
            runtime.lastTargetMph = (runtime.commandSpeed or 0.0) * mph_per_mps
            runtime.lastForce = 0.0
            runtime.lastBlend = 0.0
            return true
        end

        local now = now_ms()
        if runtime.lastVehicle ~= veh then
            runtime.lastVehicle = veh
            runtime.commandSpeed = clamp(math.max(hspeed, threshold_mps), threshold_mps, max_mps)
            runtime.active = false
        end

        if runtime.active ~= true then
            runtime.active = true
            runtime.activeSince = now
            runtime.commandSpeed = clamp(math.max(runtime.commandSpeed or 0.0, hspeed, threshold_mps), threshold_mps, max_mps)
            log("active | speed=" .. format_mph(mph) .. " mode=" .. direction_label() .. " threshold=" .. format_mph(threshold_mph))
        end

        local hold_ratio = clamp(tonumber(driftgod.S.momentumDriveSAHoldRatio or 0.988) or 0.988, 0.940, 0.998)
        local command = clamp(tonumber(runtime.commandSpeed or hspeed) or hspeed, threshold_mps, max_mps)
        if throttle > 0.05 then
            local build_rate = (7.0 + strength * 21.0) * throttle
            command = command + build_rate * dt
            command = math.max(command, hspeed * 0.996)
        elseif brake > 0.05 then
            local brake_drag = clamp(tonumber(driftgod.S.momentumDriveSABrakeDrag or 0.44) or 0.44, 0.10, 1.20)
            command = command - (8.0 + brake_drag * 34.0) * brake * dt
        else
            command = command * (1.0 - ((1.0 - hold_ratio) * dt * 60.0))
            command = math.max(command, threshold_mps)
            if hspeed > command then command = math.max(command, hspeed * 0.992) end
        end
        command = clamp(command, threshold_mps, max_mps)
        runtime.commandSpeed = command
        runtime.lastTargetMph = command * mph_per_mps

        local dx, dy, has_direction = get_drive_direction(veh)
        if not has_direction then
            runtime.lastStatus = "No drive direction."
            return true
        end

        local along = vx * dx + vy * dy
        local missing = math.max(0.0, command - along)
        local input_power = 0.35 + throttle * 0.65
        local force = clamp(missing * (0.055 + strength * 0.105) * input_power, 0.0, 2.25)
        apply_world_force(veh, dx * force, dy * force, 0.0)

        local mode = tostring(driftgod.S.momentumDriveSADirectionMode or "camera")
        local steer_setting = clamp(tonumber(driftgod.S.momentumDriveSACameraSteer or 0.72) or 0.72, 0.10, 1.50)
        local blend = clamp((0.010 + strength * 0.040) * steer_setting * input_power, 0.003, 0.135)
        if mode == "vehicle" then blend = blend * 0.65 end
        if brake > 0.05 then blend = blend * clamp(1.0 - brake * 0.78, 0.12, 1.0) end

        local target_x = dx * command
        local target_y = dy * command
        local new_x = lerp(vx, target_x, blend)
        local new_y = lerp(vy, target_y, blend)

        if brake > 0.05 then
            local brake_drag = clamp(tonumber(driftgod.S.momentumDriveSABrakeDrag or 0.44) or 0.44, 0.10, 1.20)
            local drag = clamp(brake * (0.010 + brake_drag * 0.050), 0.0, 0.085)
            new_x = new_x * (1.0 - drag)
            new_y = new_y * (1.0 - drag)
        end

        local new_speed = magnitude2(new_x, new_y)
        if new_speed > max_mps then
            local sx, sy = normalize2(new_x, new_y, dx, dy)
            new_x, new_y = sx * max_mps, sy * max_mps
        end

        set_velocity(veh, new_x, new_y, vz)

        runtime.lastForce = force
        runtime.lastBlend = blend
        runtime.lastMode = mode
        runtime.lastStatus = "Active | " .. direction_label()

        if driftgod.S.momentumDriveSATelemetry == true and now - (runtime.lastLog or 0) > 700 then
            runtime.lastLog = now
            log("tick | mph=" .. string.format("%.1f", mph)
                .. " target=" .. string.format("%.1f", runtime.lastTargetMph or 0.0)
                .. " mode=" .. tostring(mode)
                .. " force=" .. string.format("%.3f", force)
                .. " blend=" .. string.format("%.4f", blend)
                .. " throttle=" .. string.format("%.2f", throttle)
                .. " brake=" .. string.format("%.2f", brake)
                .. " dx=" .. string.format("%.2f", dx)
                .. " dy=" .. string.format("%.2f", dy))
        end

        return true
    end

    driftgod.MomentumDriveSATick = tick_grounded_camera_momentum

    local function ui_text_line(text)
        if ImGui and ImGui.TextWrapped then ImGui.TextWrapped(tostring(text or ""))
        elseif ImGui and ImGui.Text then ImGui.Text(tostring(text or "")) end
    end

    local function ui_text_color(text, r, g, b, a)
        if ImGui and ImGui.TextColored then ImGui.TextColored(r or 1.0, g or 1.0, b or 1.0, a or 1.0, tostring(text or ""))
        else ui_text_line(text) end
    end

    local function ui_sep()
        if ImGui and ImGui.Separator then ImGui.Separator() end
    end

    local function ui_same()
        if ImGui and ImGui.SameLine then ImGui.SameLine() end
    end

    local function ui_button(label, w)
        if ImGui and ImGui.Button then return ImGui.Button(tostring(label or "Button"), w or -1, 0) == true end
        return false
    end

    local function render_pair(label, value)
        ui_text_color(tostring(label or ""), 0.72, 0.78, 0.88, 1.0)
        ui_same()
        ui_text_color(tostring(value or ""), 0.96, 0.97, 1.00, 1.0)
    end

    function driftgod.R125_RenderMomentumDriveSA()
        ensure_defaults()
        if not (ClickGUI and ClickGUI.BeginCustomChildWindow) then return end

        if ClickGUI.BeginCustomChildWindow("Power Glider (BETA)") then
            ui_text_color("Power Glider (BETA)", 0.72, 0.42, 1.00, 1.00)
            ui_text_line("Grounded SuperDrive replacement using Flying Cars SA-style camera guidance and speed control.")
            ui_text_color("No lift. Gravity stays on. Activates after the speed gate, then throttle builds speed and brake bleeds it off.", 0.70, 0.92, 0.76, 1.00)
            ui_sep()

            render_pair("Status:", driftgod.MomentumDriveSAStatus and driftgod.MomentumDriveSAStatus() or "Power Glider")
            render_pair("Runtime:", tostring(runtime.lastStatus or "Ready"))

            if ui_button((driftgod.S.momentumDriveSAEnabled == true and "Disable" or "Enable") .. " Power Glider", -1) then
                if driftgod.ToggleMomentumDriveSA then driftgod.ToggleMomentumDriveSA() end
            end

            ui_sep()
            ui_text_color("Direction", 0.35, 0.86, 1.00, 1.00)
            render_pair("Mode:", direction_label() .. "  |  Left Shift toggles")
            if ui_button("Mode: Gameplay Camera", 170) then driftgod.SetMomentumDriveSADirectionMode("camera") end
            ui_same()
            if ui_button("Mode: Vehicle Nose", 170) then driftgod.SetMomentumDriveSADirectionMode("vehicle") end

            ui_text_color("Speed Gate", 0.35, 0.86, 1.00, 1.00)
            render_pair("Activation Speed:", format_mph(driftgod.S.momentumDriveSAThresholdMph))
            if ui_button("Threshold -5 mph", 170) then driftgod.MomentumDriveSAThresholdDelta(-5.0) end
            ui_same()
            if ui_button("Threshold +5 mph", 170) then driftgod.MomentumDriveSAThresholdDelta(5.0) end

            ui_text_color("Speed Control", 1.00, 0.78, 0.18, 1.00)
            render_pair("Target:", format_mph(runtime.lastTargetMph or 0.0))
            render_pair("Assist Cap:", format_mph(driftgod.S.momentumDriveSAMaxAssistMph))
            if ui_button("Cap -10 mph", 170) then driftgod.MomentumDriveSAMaxAssistDelta(-10.0) end
            ui_same()
            if ui_button("Cap +10 mph", 170) then driftgod.MomentumDriveSAMaxAssistDelta(10.0) end

            render_pair("Strength:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSAStrength or 0.55) or 0.55))
