            if ui_button("Strength +", 170) then driftgod.MomentumDriveSAStrengthDelta(0.05) end

            render_pair("Camera Guide:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSACameraSteer or 0.72) or 0.72))
            if ui_button("Guide -", 170) then driftgod.MomentumDriveSASteerDelta(-0.05) end
            ui_same()
            if ui_button("Guide +", 170) then driftgod.MomentumDriveSASteerDelta(0.05) end

            render_pair("Brake Drag:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSABrakeDrag or 0.44) or 0.44))
            if ui_button("Brake Drag -", 170) then driftgod.MomentumDriveSABrakeDelta(-0.05) end
            ui_same()
            if ui_button("Brake Drag +", 170) then driftgod.MomentumDriveSABrakeDelta(0.05) end

            ui_sep()
            if ui_button((driftgod.S.momentumDriveSAHud == true and "HUD: ON" or "HUD: OFF"), 170) then
                driftgod.S.momentumDriveSAHud = not (driftgod.S.momentumDriveSAHud == true)
                save_settings_quiet()
            end
            ui_same()
            if ui_button((driftgod.S.momentumDriveSATelemetry == true and "Telemetry: ON" or "Telemetry: OFF"), 170) then
                driftgod.S.momentumDriveSATelemetry = not (driftgod.S.momentumDriveSATelemetry == true)
                save_settings_quiet()
            end

            if ui_button("Reset Momentum Drive Settings", -1) then driftgod.ResetMomentumDriveSA() end

            ui_sep()
            ui_text_color("Control feel", 0.54, 0.60, 0.70, 1.00)
            ui_text_line("Gameplay Camera mode pulls horizontal momentum toward your camera aim, similar to Flying Cars SA, but locked to ground speed.")
            ui_text_line("Accelerate builds the target speed toward the cap. Brake adds drag and lowers the target speed.")
            ui_text_line("Old SuperDrive is hidden from this Beta page and forced off while this is active.")
            ClickGUI.EndCustomChildWindow()
        end
    end

    driftgod.R124_RenderMomentumDriveSA = driftgod.R125_RenderMomentumDriveSA
    driftgod.R123_RenderFlyingCarsSA = driftgod.R125_RenderMomentumDriveSA

    driftgod.R102_RenderBeta = function()
        -- SuperDrive is intentionally replaced by Power Glider in this branch.
        if driftgod.R125_RenderMomentumDriveSA then driftgod.R125_RenderMomentumDriveSA() end
        if driftgod.R279_RenderRoadSurfaceBeta then driftgod.R279_RenderRoadSurfaceBeta() end
        if driftgod.R140_RenderPTFXBeta then driftgod.R140_RenderPTFXBeta() end
    end
    renderBeta = driftgod.R102_RenderBeta

    disable_old_modes()
    log("v1.0.25 loaded | grounded camera/vehicle momentum guidance active; SuperDrive beta panel replaced")
end)


