    local function clamp(v, lo, hi)
        v = tonumber(v or lo) or lo
        if v < lo then return lo end
        if v > hi then return hi end
        return v
    end

    local function lerp(a, b, t)
        return (tonumber(a) or 0.0) + ((tonumber(b) or 0.0) - (tonumber(a) or 0.0)) * clamp(t, 0.0, 1.0)
    end

    local function magnitude2(x, y)
        x, y = tonumber(x) or 0.0, tonumber(y) or 0.0
        return math.sqrt(x * x + y * y)
    end

    local function normalize2(x, y, fx, fy)
        x, y = tonumber(x) or 0.0, tonumber(y) or 0.0
        local mag = math.sqrt(x * x + y * y)
        if mag < 0.0001 then return tonumber(fx) or 0.0, tonumber(fy) or 1.0, false end
        return x / mag, y / mag, true
    end

    local function now_ms()
        if driftgod.GetMs then
