    local function unpack_v3(a, b, c, dx, dy, dz)
        if type(a) == "table" then
            return tonumber(a.x or a.X or a[1]) or dx,
                   tonumber(a.y or a.Y or a[2]) or dy,
                   tonumber(a.z or a.Z or a[3]) or dz
        end
        if type(a) == "userdata" then
            local okx, x = driftgod.Try(function() return a.x or a.X end)
            local oky, y = driftgod.Try(function() return a.y or a.Y end)
            local okz, z = driftgod.Try(function() return a.z or a.Z end)
            if okx or oky or okz then
                return tonumber(x) or dx, tonumber(y) or dy, tonumber(z) or dz
            end
        end
        return tonumber(a) or dx, tonumber(b) or dy, tonumber(c) or dz
    end

    local function invoke_v3(hash, dx, dy, dz, ...)
        if not (Natives and Natives.InvokeV3) then return dx, dy, dz end
        local ok, a, b, c = driftgod.Try(function(...) return Natives.InvokeV3(hash, ...) end, ...)
        if ok then return unpack_v3(a, b, c, dx, dy, dz) end
        return dx, dy, dz
    end

