            local ok = driftgod.Try(function() VEHICLE.SET_VEHICLE_REDUCE_GRIP(veh, enabled == true) end)
            return ok == true
        end
        return invoke_void(nh.SET_VEHICLE_REDUCE_GRIP, veh, enabled == true)
    end

