    function driftgod.MomentumDriveSASteerDelta(delta)
        ensure_defaults()
        driftgod.S.momentumDriveSACameraSteer = clamp((tonumber(driftgod.S.momentumDriveSACameraSteer) or 0.80) + (tonumber(delta) or 0.0), 0.10, 1.50)
