            if runtime.active == true or (runtime.lowGripVehicle and runtime.lowGripVehicle ~= 0) then reset_runtime("disabled") end
            return false
        end

        local veh = get_local_vehicle()
        if veh == 0 then
            if runtime.active == true then reset_runtime("no supported driver vehicle") end
            runtime.lastStatus = "Enter a supported driver's seat."
            return true
        end

        invoke_void(nh.SET_VEHICLE_GRAVITY, veh, true)
        apply_low_grip(veh)

        local vx, vy, vz = invoke_v3(nh.GET_ENTITY_VELOCITY, 0.0, 0.0, 0.0, veh)
        local hspeed = magnitude2(vx, vy)
        local mph = hspeed * mph_per_mps
        runtime.lastMph = mph

        local max_mph = clamp(driftgod.S.momentumDriveSAMaxAssistMph, 20.0, 260.0)
        local strength = clamp(driftgod.S.momentumDriveSAStrength, 0.05, 1.50)
        local max_mps = max_mph * mps_per_mph
        local min_roll_mps = clamp(driftgod.S.momentumDriveSAMinRollMph, 0.0, 35.0) * mps_per_mph
        local dt = clamp(invoke_float(nh.GET_FRAME_TIME), 1.0 / 240.0, 0.05)
        local throttle = math.max(control_normal(control.ACCELERATE), control_normal(control.VEH_FLY_THROTTLE_UP))
        local brake = math.max(control_normal(control.BRAKE), control_normal(control.VEH_FLY_THROTTLE_DN))
        if invoke_bool(nh.IS_CONTROL_PRESSED, 0, control.HANDBRAKE) then brake = 1.0 end

        local airborne = invoke_bool(nh.IS_ENTITY_IN_AIR, veh)
        if driftgod.S.momentumDriveSAGroundOnly ~= false and airborne then
            runtime.lastStatus = "Airborne pause | Low Grip kept"
            runtime.lastForce = 0.0
            runtime.lastBlend = 0.0
            runtime.lastTargetMph = (runtime.commandSpeed or 0.0) * mph_per_mps
            return true
        end

        local now = now_ms()
        if runtime.lastVehicle ~= veh then
            if runtime.lastVehicle and runtime.lastVehicle ~= 0 then clear_low_grip(runtime.lastVehicle) end
            runtime.lastVehicle = veh
            runtime.commandSpeed = clamp(math.max(hspeed, min_roll_mps), 0.0, max_mps)
            runtime.active = false
            apply_low_grip(veh)
        end

        if runtime.active ~= true then
            runtime.active = true
            runtime.activeSince = now
            runtime.commandSpeed = clamp(math.max(runtime.commandSpeed or 0.0, hspeed, min_roll_mps), 0.0, max_mps)
            log("active | immediate=true speed=" .. format_mph(mph) .. " mode=" .. direction_label() .. " lowGrip=" .. tostring(driftgod.S.momentumDriveSALowGrip == true))
        end

        local hold_ratio = clamp(tonumber(driftgod.S.momentumDriveSAHoldRatio or 0.992) or 0.992, 0.940, 0.998)
        local command = clamp(tonumber(runtime.commandSpeed or hspeed) or hspeed, 0.0, max_mps)

        if throttle > 0.05 then
            local build_rate = (8.5 + strength * 24.0) * throttle
            command = command + build_rate * dt
            command = math.max(command, hspeed * 0.998, min_roll_mps * throttle)
        elseif brake > 0.05 then
            local brake_drag = clamp(tonumber(driftgod.S.momentumDriveSABrakeDrag or 0.48) or 0.48, 0.10, 1.20)
            command = command - (9.0 + brake_drag * 36.0) * brake * dt
        else
            command = command * (1.0 - ((1.0 - hold_ratio) * dt * 60.0))
            if hspeed > command then command = math.max(command, hspeed * 0.992) end
        end
        command = clamp(command, 0.0, max_mps)
        runtime.commandSpeed = command
        runtime.lastTargetMph = command * mph_per_mps

        local dx, dy, has_direction = get_drive_direction(veh)
        if not has_direction then
            runtime.lastStatus = "No drive direction."
            return true
        end

        local along = vx * dx + vy * dy
        local missing = math.max(0.0, command - along)
        local input_power = throttle > 0.05 and (0.28 + throttle * 0.72) or 0.18
        local force = clamp(missing * (0.050 + strength * 0.110) * input_power, 0.0, 2.35)
        if throttle > 0.05 or missing > 0.35 then apply_world_force(veh, dx * force, dy * force, 0.0) end

        local mode = tostring(driftgod.S.momentumDriveSADirectionMode or "camera")
        local steer_setting = clamp(tonumber(driftgod.S.momentumDriveSACameraSteer or 0.80) or 0.80, 0.10, 1.50)
        local blend = clamp((0.011 + strength * 0.043) * steer_setting * input_power, 0.002, 0.140)
        if mode == "vehicle" then blend = blend * 0.65 end
        if brake > 0.05 then blend = blend * clamp(1.0 - brake * 0.82, 0.10, 1.0) end

        local target_x = dx * command
        local target_y = dy * command
        local new_x = lerp(vx, target_x, blend)
        local new_y = lerp(vy, target_y, blend)

        if brake > 0.05 then
            local brake_drag = clamp(tonumber(driftgod.S.momentumDriveSABrakeDrag or 0.48) or 0.48, 0.10, 1.20)
            local drag = clamp(brake * (0.012 + brake_drag * 0.055), 0.0, 0.095)
            new_x = new_x * (1.0 - drag)
            new_y = new_y * (1.0 - drag)
        end

        local new_speed = magnitude2(new_x, new_y)
        if new_speed > max_mps then
            local sx, sy = normalize2(new_x, new_y, dx, dy)
            new_x, new_y = sx * max_mps, sy * max_mps
        end

        set_velocity(veh, new_x, new_y, vz)

        runtime.lastForce = force
        runtime.lastBlend = blend
        runtime.lastMode = mode
        runtime.lastStatus = "Active Now | " .. direction_label() .. " | Low Grip " .. (driftgod.S.momentumDriveSALowGrip == true and "ON" or "OFF")

        if driftgod.S.momentumDriveSATelemetry == true and now - (runtime.lastLog or 0) > 700 then
            runtime.lastLog = now
            log("tick126 | mph=" .. string.format("%.1f", mph)
                .. " target=" .. string.format("%.1f", runtime.lastTargetMph or 0.0)
                .. " mode=" .. tostring(mode)
                .. " lowGrip=" .. tostring(driftgod.S.momentumDriveSALowGrip == true)
                .. " force=" .. string.format("%.3f", force)
                .. " blend=" .. string.format("%.4f", blend)
                .. " throttle=" .. string.format("%.2f", throttle)
                .. " brake=" .. string.format("%.2f", brake)
                .. " dx=" .. string.format("%.2f", dx)
                .. " dy=" .. string.format("%.2f", dy))
        end

        return true
    end

    driftgod.MomentumDriveSATick = tick_always_active_low_grip

    local function ui_text_line(text)
        if ImGui and ImGui.TextWrapped then ImGui.TextWrapped(tostring(text or ""))
        elseif ImGui and ImGui.Text then ImGui.Text(tostring(text or "")) end
    end

    local function ui_text_color(text, r, g, b, a)
        if ImGui and ImGui.TextColored then ImGui.TextColored(r or 1.0, g or 1.0, b or 1.0, a or 1.0, tostring(text or ""))
        else ui_text_line(text) end
    end

    local function ui_sep()
        if ImGui and ImGui.Separator then ImGui.Separator() end
    end

    local function ui_same()
        if ImGui and ImGui.SameLine then ImGui.SameLine() end
    end

    local function ui_button(label, w)
        if ImGui and ImGui.Button then return ImGui.Button(tostring(label or "Button"), w or -1, 0) == true end
        return false
    end

    local function render_pair(label, value)
        ui_text_color(tostring(label or ""), 0.72, 0.78, 0.88, 1.0)
        ui_same()
        ui_text_color(tostring(value or ""), 0.96, 0.97, 1.00, 1.0)
    end

    function driftgod.R126_RenderMomentumDriveSA()
        ensure_defaults()
        if not (ClickGUI and ClickGUI.BeginCustomChildWindow) then return end

        if ClickGUI.BeginCustomChildWindow("Power Glider (BETA)") then
            ui_text_color("Power Glider (BETA)", 0.72, 0.42, 1.00, 1.00)
            ui_text_line("SuperDrive replacement: active immediately when enabled, with low grip and grounded camera/vehicle momentum.")
            ui_text_color("No speed gate. No lift. Gravity stays on. Accelerate builds speed; brake bleeds speed.", 0.70, 0.92, 0.76, 1.00)
            ui_sep()

            render_pair("Status:", driftgod.MomentumDriveSAStatus and driftgod.MomentumDriveSAStatus() or "Power Glider")
            render_pair("Runtime:", tostring(runtime.lastStatus or "Ready"))

            if ui_button((driftgod.S.momentumDriveSAEnabled == true and "Disable" or "Enable") .. " Power Glider", -1) then
                if driftgod.ToggleMomentumDriveSA then driftgod.ToggleMomentumDriveSA() end
            end

            ui_sep()
            ui_text_color("Direction", 0.35, 0.86, 1.00, 1.00)
            render_pair("Mode:", direction_label() .. "  |  Left Shift toggles")
            if ui_button("Mode: Gameplay Camera", 170) then driftgod.SetMomentumDriveSADirectionMode("camera") end
            ui_same()
            if ui_button("Mode: Vehicle Nose", 170) then driftgod.SetMomentumDriveSADirectionMode("vehicle") end

            ui_text_color("Grip", 1.00, 0.78, 0.18, 1.00)
            render_pair("Low Grip:", driftgod.S.momentumDriveSALowGrip == true and "ON" or "OFF")
            if ui_button((driftgod.S.momentumDriveSALowGrip == true and "Low Grip: ON" or "Low Grip: OFF"), 170) then
                driftgod.ToggleMomentumDriveSALowGrip()
            end
            ui_same()
            render_pair("Type:", "Reduced Grip native")

            ui_text_color("Speed Control", 1.00, 0.78, 0.18, 1.00)
            render_pair("Current:", format_mph(runtime.lastMph or 0.0))
            render_pair("Target:", format_mph(runtime.lastTargetMph or 0.0))
            render_pair("Assist Cap:", format_mph(driftgod.S.momentumDriveSAMaxAssistMph))
            if ui_button("Cap -10 mph", 170) then driftgod.MomentumDriveSAMaxAssistDelta(-10.0) end
            ui_same()
            if ui_button("Cap +10 mph", 170) then driftgod.MomentumDriveSAMaxAssistDelta(10.0) end

            render_pair("Roll Start:", format_mph(driftgod.S.momentumDriveSAMinRollMph))
            if ui_button("Roll -2 mph", 170) then driftgod.MomentumDriveSAMinRollDelta(-2.0) end
            ui_same()
            if ui_button("Roll +2 mph", 170) then driftgod.MomentumDriveSAMinRollDelta(2.0) end

            render_pair("Strength:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSAStrength or 0.62) or 0.62))
            if ui_button("Strength -", 170) then driftgod.MomentumDriveSAStrengthDelta(-0.05) end
            ui_same()
            if ui_button("Strength +", 170) then driftgod.MomentumDriveSAStrengthDelta(0.05) end

            render_pair("Camera Guide:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSACameraSteer or 0.80) or 0.80))
            if ui_button("Guide -", 170) then driftgod.MomentumDriveSASteerDelta(-0.05) end
            ui_same()
            if ui_button("Guide +", 170) then driftgod.MomentumDriveSASteerDelta(0.05) end

            render_pair("Brake Drag:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSABrakeDrag or 0.48) or 0.48))
            if ui_button("Brake Drag -", 170) then driftgod.MomentumDriveSABrakeDelta(-0.05) end
            ui_same()
            if ui_button("Brake Drag +", 170) then driftgod.MomentumDriveSABrakeDelta(0.05) end

            ui_sep()
            if ui_button((driftgod.S.momentumDriveSAHud == true and "HUD: ON" or "HUD: OFF"), 170) then
                driftgod.S.momentumDriveSAHud = not (driftgod.S.momentumDriveSAHud == true)
                save_settings_quiet()
            end
            ui_same()
            if ui_button((driftgod.S.momentumDriveSATelemetry == true and "Telemetry: ON" or "Telemetry: OFF"), 170) then
                driftgod.S.momentumDriveSATelemetry = not (driftgod.S.momentumDriveSATelemetry == true)
                save_settings_quiet()
            end

            if ui_button("Reset Momentum Drive Settings", -1) then driftgod.ResetMomentumDriveSA() end

            ui_sep()
            ui_text_color("Control feel", 0.54, 0.60, 0.70, 1.00)
            ui_text_line("Enable it and it is active right away. Low Grip is applied like SuperDrive's reduced-grip mode.")
            ui_text_line("Gameplay Camera mode pulls horizontal momentum toward your camera aim. Vehicle Nose mode carries the car forward.")
            ui_text_line("Accelerate builds the target speed toward the cap. Brake adds drag and lowers the target speed.")
            ClickGUI.EndCustomChildWindow()
        end
    end

    driftgod.R125_RenderMomentumDriveSA = driftgod.R126_RenderMomentumDriveSA
    driftgod.R124_RenderMomentumDriveSA = driftgod.R126_RenderMomentumDriveSA
    driftgod.R123_RenderFlyingCarsSA = driftgod.R126_RenderMomentumDriveSA

    driftgod.R102_RenderBeta = function()
        if driftgod.R126_RenderMomentumDriveSA then driftgod.R126_RenderMomentumDriveSA() end
        if driftgod.R279_RenderRoadSurfaceBeta then driftgod.R279_RenderRoadSurfaceBeta() end
        if driftgod.R140_RenderPTFXBeta then driftgod.R140_RenderPTFXBeta() end
    end
    renderBeta = driftgod.R102_RenderBeta

    disable_old_modes()
    log("v1.0.26 loaded | always-active low-grip grounded Power Glider active")
end)


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.27 patch: Grounded SuperDrive SA camera-slide controller
-- note: v1.0.26 made Power Glider active immediately with low grip, but the
--       desired target is closer to the older SuperDrive feel plus Flying Cars SA's
--       camera/vehicle guidance and throttle/brake speed control. This patch keeps
--       the car grounded, applies reduced grip plus safe friction override, and uses
--       a stronger horizontal velocity/force blend so the vehicle carries momentum
--       in the camera or vehicle-nose direction without lift or flight.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or {}
    driftgod.S = driftgod.S or {}

    driftgod.Version = "v1.0.27"
    driftgod.BuildNumber = "2026.07.27.127"
    driftgod.BuildDate = "2026-07-27"
    driftgod.LastUpdated = "2026-07-27"
    driftgod.LastUpdateDate = "2026-07-27"
    driftgod.__ProductionPatch = "v1_0_27_Grounded_SuperDrive_SA_Camera_Slide"

    local mph_per_mps = 2.2369362920544
    local mps_per_mph = 0.44704

    local nh = {
        PLAYER_PED_ID = 0xD80958FC74E988A6,
        IS_PED_IN_ANY_VEHICLE = 0x997ABD671D25CA0B,
        GET_VEHICLE_PED_IS_IN = 0x9A9112A0FE9A4713,
        GET_PED_IN_VEHICLE_SEAT = 0xBB40DD2270B65366,
        DOES_ENTITY_EXIST = 0x7239B21A38F536BA,
        GET_ENTITY_SPEED = 0xD5037BA82E12416F,
        GET_ENTITY_VELOCITY = 0x4805D2B1D8CF94A9,
        GET_ENTITY_FORWARD_VECTOR = 0x0A794A5A57F8DF91,
        SET_ENTITY_VELOCITY = 0x1C99BB7B6E96D16F,
        APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS = 0x18FF00FC7EFF559E,
        SET_VEHICLE_GRAVITY = 0x89F149B6131E57DA,
        SET_VEHICLE_REDUCE_GRIP = 0x222FF6A823D122E2,
        GET_FRAME_TIME = 0x15C40837039FFAF7,
        GET_CONTROL_NORMAL = 0xEC3C9B8D5327B563,
        IS_CONTROL_PRESSED = 0xF3A21BCD95725A4A,
        GET_VEHICLE_CLASS = 0x29439776AAA00A62,
        IS_ENTITY_IN_AIR = 0x886E37EC497200B6,
        IS_VEHICLE_ON_ALL_WHEELS = 0xB104CD1BABF302E2,
        GET_ENTITY_HEIGHT_ABOVE_GROUND = 0x1DD55701034110E5,
        GET_GAMEPLAY_CAM_ROT = 0x837765A25378F0BB,
        GET_FINAL_RENDERED_CAM_ROT = 0x5B4E4C817FCC2DFB,
    }

    local control = {
        ACCELERATE = 71,
        BRAKE = 72,
        HANDBRAKE = 76,
        VEH_FLY_THROTTLE_UP = 87,
        VEH_FLY_THROTTLE_DN = 88,
    }

    local runtime = driftgod.MomentumDriveSA or {}
    driftgod.MomentumDriveSA = runtime
    runtime.patch = "v1.0.27"
    runtime.lastStatus = runtime.lastStatus or "Ready"
    runtime.commandSpeed = tonumber(runtime.commandSpeed or 0.0) or 0.0
    runtime.lastMph = tonumber(runtime.lastMph or 0.0) or 0.0
    runtime.lastTargetMph = tonumber(runtime.lastTargetMph or 0.0) or 0.0
    runtime.lastForce = tonumber(runtime.lastForce or 0.0) or 0.0
    runtime.lastBlend = tonumber(runtime.lastBlend or 0.0) or 0.0
    runtime.lastGrip = runtime.lastGrip or "off"
    runtime.modeKeyDown = runtime.modeKeyDown == true
    runtime.lowGripVehicle = runtime.lowGripVehicle or 0
    runtime.lastVehicle = runtime.lastVehicle or 0
    runtime.active = runtime.active == true
    runtime.lastLog = runtime.lastLog or 0

    local function clamp(v, lo, hi)
        v = tonumber(v or lo) or lo
        if v < lo then return lo end
        if v > hi then return hi end
        return v
    end

    local function lerp(a, b, t)
        return (tonumber(a) or 0.0) + ((tonumber(b) or 0.0) - (tonumber(a) or 0.0)) * clamp(t, 0.0, 1.0)
    end

    local function magnitude2(x, y)
        x, y = tonumber(x) or 0.0, tonumber(y) or 0.0
        return math.sqrt(x * x + y * y)
    end

    local function normalize2(x, y, fx, fy)
        x, y = tonumber(x) or 0.0, tonumber(y) or 0.0
        local mag = math.sqrt(x * x + y * y)
        if mag < 0.0001 then return tonumber(fx) or 0.0, tonumber(fy) or 1.0, false end
        return x / mag, y / mag, true
    end

    local function now_ms()
        if driftgod.GetMs then
            local ok, v = driftgod.Try(driftgod.GetMs)
            if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
        end
        if Natives and Natives.InvokeInt then
            local ok, v = driftgod.Try(function() return Natives.InvokeInt(0x9CD27B0045628463) end)
            if ok and tonumber(v) then return math.floor(tonumber(v) or 0) end
        end
        if os and os.clock then return math.floor(os.clock() * 1000) end
        return 0
    end

    local function log(msg)
        msg = "[GroundedSuperDriveSA] " .. tostring(msg or "")
        if driftgod.Log then driftgod.Log(msg)
        elseif Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] " .. msg) end
    end

    local function toast(msg, ms)
        if driftgod.Toast then driftgod.Toast(tostring(msg or ""), ms or 1600)
        elseif GUI and GUI.AddToast then GUI.AddToast("DriftGod", tostring(msg or ""), ms or 1600) end
    end

    local function save_settings_quiet()
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
    end

    local function invoke_bool(hash, ...)
        if not (Natives and Natives.InvokeBool) then return false end
        local ok, v = driftgod.Try(function(...) return Natives.InvokeBool(hash, ...) end, ...)
        return ok == true and v == true
    end

    local function invoke_int(hash, ...)
        if not (Natives and Natives.InvokeInt) then return 0 end
        local ok, v = driftgod.Try(function(...) return Natives.InvokeInt(hash, ...) end, ...)
        return ok == true and (tonumber(v) or 0) or 0
    end

    local function invoke_float(hash, ...)
        if not (Natives and Natives.InvokeFloat) then return 0.0 end
        local ok, v = driftgod.Try(function(...) return Natives.InvokeFloat(hash, ...) end, ...)
        return ok == true and (tonumber(v) or 0.0) or 0.0
    end

    local function invoke_void(hash, ...)
        if not (Natives and Natives.InvokeVoid) then return false end
        local ok = driftgod.Try(function(...) Natives.InvokeVoid(hash, ...) end, ...)
        return ok == true
    end

    local function unpack_v3(a, b, c, dx, dy, dz)
        if type(a) == "table" then
            return tonumber(a.x or a.X or a[1]) or dx,
                   tonumber(a.y or a.Y or a[2]) or dy,
                   tonumber(a.z or a.Z or a[3]) or dz
        end
        if type(a) == "userdata" then
            local okx, x = driftgod.Try(function() return a.x or a.X end)
            local oky, y = driftgod.Try(function() return a.y or a.Y end)
            local okz, z = driftgod.Try(function() return a.z or a.Z end)
            if okx or oky or okz then return tonumber(x) or dx, tonumber(y) or dy, tonumber(z) or dz end
        end
        return tonumber(a) or dx, tonumber(b) or dy, tonumber(c) or dz
    end

    local function invoke_v3(hash, dx, dy, dz, ...)
        if not (Natives and Natives.InvokeV3) then return dx, dy, dz end
        local ok, a, b, c = driftgod.Try(function(...) return Natives.InvokeV3(hash, ...) end, ...)
        if ok then return unpack_v3(a, b, c, dx, dy, dz) end
        return dx, dy, dz
    end

    local function exists(ent)
        return ent and ent ~= 0 and invoke_bool(nh.DOES_ENTITY_EXIST, ent)
    end

    local function get_local_vehicle()
        local ped = invoke_int(nh.PLAYER_PED_ID)
        if ped == 0 or not invoke_bool(nh.IS_PED_IN_ANY_VEHICLE, ped, false) then return 0 end
        local veh = invoke_int(nh.GET_VEHICLE_PED_IS_IN, ped, false)
        if veh == 0 or not exists(veh) then return 0 end
        if invoke_int(nh.GET_PED_IN_VEHICLE_SEAT, veh, -1, false) ~= ped then return 0 end
        local class = invoke_int(nh.GET_VEHICLE_CLASS, veh)
        if class == 8 or class == 13 or class == 14 or class == 15 or class == 16 or class == 21 then return 0 end
        return veh
    end

    local function control_normal(id)
        return clamp(invoke_float(nh.GET_CONTROL_NORMAL, 0, id), 0.0, 1.0)
    end

    local function key_down(vk)
        local down = false
        driftgod.Try(function() if Utils and Utils.IsKeyDown and Utils.IsKeyDown(vk) then down = true end end)
        return down
    end

    local function gui_open()
        local open = false
        driftgod.Try(function() if GUI and GUI.IsOpen and GUI.IsOpen() == true then open = true end end)
        return open
    end

    local function rotation_to_direction(rx, rz)
        local rad_x = math.rad(tonumber(rx) or 0.0)
        local rad_z = math.rad(tonumber(rz) or 0.0)
        local horizontal = math.abs(math.cos(rad_x))
        return -math.sin(rad_z) * horizontal, math.cos(rad_z) * horizontal
    end

    local function get_camera_direction_horizontal()
        local rx, _, rz = invoke_v3(nh.GET_GAMEPLAY_CAM_ROT, 0.0, 0.0, 0.0, 2)
        if math.abs(rx or 0.0) < 0.001 and math.abs(rz or 0.0) < 0.001 then
            rx, _, rz = invoke_v3(nh.GET_FINAL_RENDERED_CAM_ROT, 0.0, 0.0, 0.0, 2)
        end
        local x, y = rotation_to_direction(rx, rz)
        return normalize2(x, y, 0.0, 1.0)
    end

    local function get_vehicle_direction_horizontal(veh)
        local x, y, _ = invoke_v3(nh.GET_ENTITY_FORWARD_VECTOR, 0.0, 1.0, 0.0, veh)
        return normalize2(x, y, 0.0, 1.0)
    end

    local function get_drive_direction(veh)
        local mode = tostring(driftgod.S.momentumDriveSADirectionMode or "camera")
        if mode == "vehicle" then return get_vehicle_direction_horizontal(veh) end
        local x, y, ok = get_camera_direction_horizontal()
        if ok then return x, y, true end
        return get_vehicle_direction_horizontal(veh)
    end

    local function apply_world_force(veh, x, y, z)
        if math.abs(x or 0.0) + math.abs(y or 0.0) + math.abs(z or 0.0) <= 0.0001 then return false end
        return invoke_void(nh.APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS, veh, 1, x, y, z, true, false, true, true)
    end

    local function set_velocity(veh, x, y, z)
        return invoke_void(nh.SET_ENTITY_VELOCITY, veh, x, y, z)
    end

    local function set_reduced_grip(veh, enabled)
        if not veh or veh == 0 then return false end
        if driftgod.SafeSetVehicleReduceGrip then
            local ok, result = driftgod.Try(function() return driftgod.SafeSetVehicleReduceGrip(veh, enabled == true) end)
            return ok == true and result ~= false
        end
        if VEHICLE and VEHICLE.SET_VEHICLE_REDUCE_GRIP then
            local ok = driftgod.Try(function() VEHICLE.SET_VEHICLE_REDUCE_GRIP(veh, enabled == true) end)
            return ok == true
        end
        return invoke_void(nh.SET_VEHICLE_REDUCE_GRIP, veh, enabled == true)
    end

    local function set_friction(veh, value)
        if not veh or veh == 0 then return false end
        value = clamp(value, 0.0, 2.0)
        if driftgod.SafeSetVehicleFrictionOverride then
            local ok, result = driftgod.Try(function() return driftgod.SafeSetVehicleFrictionOverride(veh, value) end)
            return ok == true and result ~= false
        end
        return false
    end

    local function clear_ground_grip(veh)
        if veh and veh ~= 0 then
            set_reduced_grip(veh, false)
            set_friction(veh, 1.0)
        end
        if runtime.lowGripVehicle == veh then runtime.lowGripVehicle = 0 end
        runtime.lastGrip = "off"
    end

    local function apply_ground_grip(veh)
        if driftgod.S.momentumDriveSALowGrip ~= false then
            if runtime.lowGripVehicle ~= 0 and runtime.lowGripVehicle ~= veh then clear_ground_grip(runtime.lowGripVehicle) end
            set_reduced_grip(veh, true)
            local friction = clamp(tonumber(driftgod.S.momentumDriveSAFriction or 0.22) or 0.22, 0.02, 0.60)
            set_friction(veh, friction)
            runtime.lowGripVehicle = veh
            runtime.lastGrip = string.format("low+friction %.2f", friction)
        else
            clear_ground_grip(veh)
        end
    end

    local function format_mph(v)
        return string.format("%.0f mph", tonumber(v or 0.0) or 0.0)
    end

    local function direction_label()
        return tostring(driftgod.S.momentumDriveSADirectionMode or "camera") == "vehicle" and "Vehicle Nose" or "Gameplay Camera"
    end

    local function ensure_defaults()
        driftgod.S = driftgod.S or {}
        if driftgod.S.momentumDriveSAEnabled == nil then driftgod.S.momentumDriveSAEnabled = false end
        driftgod.S.momentumDriveSAThresholdMph = 0.0
        if driftgod.S.momentumDriveSAStrength == nil then driftgod.S.momentumDriveSAStrength = 0.88 end
        if driftgod.S.momentumDriveSABaseMph == nil then driftgod.S.momentumDriveSABaseMph = 42.0 end
        if driftgod.S.momentumDriveSAMaxAssistMph == nil then driftgod.S.momentumDriveSAMaxAssistMph = 175.0 end
        if driftgod.S.momentumDriveSAHoldRatio == nil then driftgod.S.momentumDriveSAHoldRatio = 0.996 end
        if driftgod.S.momentumDriveSAHud == nil then driftgod.S.momentumDriveSAHud = true end
        if driftgod.S.momentumDriveSATelemetry == nil then driftgod.S.momentumDriveSATelemetry = false end
        if driftgod.S.momentumDriveSAAutoDisableSuperDrive == nil then driftgod.S.momentumDriveSAAutoDisableSuperDrive = true end
        if driftgod.S.momentumDriveSADirectionMode ~= "vehicle" then driftgod.S.momentumDriveSADirectionMode = "camera" end
        if driftgod.S.momentumDriveSAModeToggleKey == nil then driftgod.S.momentumDriveSAModeToggleKey = 0xA0 end
        if driftgod.S.momentumDriveSACameraSteer == nil then driftgod.S.momentumDriveSACameraSteer = 1.05 end
        if driftgod.S.momentumDriveSABrakeDrag == nil then driftgod.S.momentumDriveSABrakeDrag = 0.62 end
        if driftgod.S.momentumDriveSAGroundOnly == nil then driftgod.S.momentumDriveSAGroundOnly = true end
        if driftgod.S.momentumDriveSALowGrip == nil then driftgod.S.momentumDriveSALowGrip = true end
        if driftgod.S.momentumDriveSAFriction == nil then driftgod.S.momentumDriveSAFriction = 0.22 end
        if driftgod.S.momentumDriveSADownforce == nil then driftgod.S.momentumDriveSADownforce = 0.18 end

        -- one-time profile migration from the weaker v1.0.24-v1.0.26 beta defaults
        -- into the stronger grounded SuperDrive SA feel. Only values that still look
        -- like old defaults are lifted; user-tuned higher values are preserved.
        if driftgod.S.momentumDriveSAProfileVersion ~= "v1.0.27" then
            if (tonumber(driftgod.S.momentumDriveSAStrength or 0.0) or 0.0) <= 0.65 then driftgod.S.momentumDriveSAStrength = 0.88 end
            if (tonumber(driftgod.S.momentumDriveSACameraSteer or 0.0) or 0.0) <= 0.85 then driftgod.S.momentumDriveSACameraSteer = 1.05 end
            if (tonumber(driftgod.S.momentumDriveSABrakeDrag or 0.0) or 0.0) <= 0.50 then driftgod.S.momentumDriveSABrakeDrag = 0.62 end
            if (tonumber(driftgod.S.momentumDriveSAHoldRatio or 0.0) or 0.0) <= 0.993 then driftgod.S.momentumDriveSAHoldRatio = 0.996 end
            if (tonumber(driftgod.S.momentumDriveSAMaxAssistMph or 0.0) or 0.0) <= 165.0 then driftgod.S.momentumDriveSAMaxAssistMph = 175.0 end
            driftgod.S.momentumDriveSABaseMph = tonumber(driftgod.S.momentumDriveSABaseMph or 42.0) or 42.0
            driftgod.S.momentumDriveSAFriction = tonumber(driftgod.S.momentumDriveSAFriction or 0.22) or 0.22
            driftgod.S.momentumDriveSADownforce = tonumber(driftgod.S.momentumDriveSADownforce or 0.18) or 0.18
            driftgod.S.momentumDriveSALowGrip = true
            driftgod.S.momentumDriveSAProfileVersion = "v1.0.27"
        end
    end

    local function disable_old_modes()
        if driftgod.FlyingCarsSA and driftgod.FlyingCarsSA.SetEnabled then driftgod.Try(function() driftgod.FlyingCarsSA.SetEnabled(false) end) end
        if driftgod.FlyingCarsSA and driftgod.FlyingCarsSA.state then driftgod.FlyingCarsSA.state.enabled = false end
        if driftgod.S then
            driftgod.S.superDriveEnabled = false
            driftgod.S._superDriveLastState = false
        end
    end

    local function reset_runtime(reason)
        if runtime.active == true and reason and reason ~= "" then log("inactive | " .. tostring(reason)) end
        if runtime.lowGripVehicle and runtime.lowGripVehicle ~= 0 then clear_ground_grip(runtime.lowGripVehicle) end
        runtime.active = false
        runtime.lastVehicle = 0
        runtime.commandSpeed = 0.0
        runtime.lastForce = 0.0
        runtime.lastBlend = 0.0
        runtime.lastTargetMph = 0.0
        runtime.lastStatus = tostring(reason or "Waiting")
    end

    function driftgod.SetMomentumDriveSADirectionMode(mode)
        ensure_defaults()
        mode = mode == "vehicle" and "vehicle" or "camera"
        driftgod.S.momentumDriveSADirectionMode = mode
        runtime.lastMode = mode
        toast("Momentum Drive mode: " .. direction_label(), 1500)
        log("mode=" .. tostring(mode))
        save_settings_quiet()
    end

    function driftgod.ToggleMomentumDriveSADirectionMode()
        ensure_defaults()
        local next_mode = tostring(driftgod.S.momentumDriveSADirectionMode or "camera") == "camera" and "vehicle" or "camera"
        driftgod.SetMomentumDriveSADirectionMode(next_mode)
    end

    function driftgod.ToggleMomentumDriveSALowGrip()
        ensure_defaults()
        driftgod.S.momentumDriveSALowGrip = not (driftgod.S.momentumDriveSALowGrip == true)
        if not driftgod.S.momentumDriveSALowGrip then clear_ground_grip(runtime.lowGripVehicle or get_local_vehicle()) end
        toast("Momentum Drive Low Grip: " .. (driftgod.S.momentumDriveSALowGrip and "ON" or "OFF"), 1500)
        log("lowGrip=" .. tostring(driftgod.S.momentumDriveSALowGrip))
        save_settings_quiet()
    end

    function driftgod.ToggleMomentumDriveSA()
        ensure_defaults()
        driftgod.S.momentumDriveSAEnabled = not (driftgod.S.momentumDriveSAEnabled == true)
        disable_old_modes()
        if driftgod.S.momentumDriveSAEnabled == true then
            local veh = get_local_vehicle()
            local base = clamp(driftgod.S.momentumDriveSABaseMph, 0.0, 120.0) * mps_per_mph
            runtime.commandSpeed = base
            runtime.active = false
            if veh ~= 0 then apply_ground_grip(veh) end
            toast("Power Glider ON | " .. direction_label() .. " | SuperDrive grip", 2400)
            log("enabled | immediate=true base=" .. format_mph(driftgod.S.momentumDriveSABaseMph) .. " mode=" .. tostring(driftgod.S.momentumDriveSADirectionMode) .. " friction=" .. tostring(driftgod.S.momentumDriveSAFriction))
        else
            reset_runtime("disabled")
            toast("Power Glider OFF", 1800)
        end
        save_settings_quiet()
    end

    function driftgod.SetMomentumDriveSAEnabled(enabled)
        ensure_defaults()
        driftgod.S.momentumDriveSAEnabled = enabled == true
        disable_old_modes()
        if driftgod.S.momentumDriveSAEnabled then
            runtime.commandSpeed = clamp(driftgod.S.momentumDriveSABaseMph, 0.0, 120.0) * mps_per_mph
            local veh = get_local_vehicle()
            if veh ~= 0 then apply_ground_grip(veh) end
        else
            reset_runtime("disabled")
        end
        save_settings_quiet()
    end

    function driftgod.MomentumDriveSABaseDelta(delta)
        ensure_defaults()
        driftgod.S.momentumDriveSABaseMph = clamp((tonumber(driftgod.S.momentumDriveSABaseMph) or 42.0) + (tonumber(delta) or 0.0), 0.0, 120.0)
        toast("Base speed: " .. format_mph(driftgod.S.momentumDriveSABaseMph), 1500)
        save_settings_quiet()
    end

    function driftgod.MomentumDriveSAFrictionDelta(delta)
        ensure_defaults()
        driftgod.S.momentumDriveSAFriction = clamp((tonumber(driftgod.S.momentumDriveSAFriction) or 0.22) + (tonumber(delta) or 0.0), 0.02, 0.60)
        toast("Grip friction: " .. string.format("%.2f", driftgod.S.momentumDriveSAFriction), 1500)
        save_settings_quiet()
    end

    function driftgod.MomentumDriveSADownforceDelta(delta)
        ensure_defaults()
        driftgod.S.momentumDriveSADownforce = clamp((tonumber(driftgod.S.momentumDriveSADownforce) or 0.18) + (tonumber(delta) or 0.0), 0.00, 0.80)
        toast("Ground stick: " .. string.format("%.2f", driftgod.S.momentumDriveSADownforce), 1500)
        save_settings_quiet()
    end

    function driftgod.ResetMomentumDriveSA()
        driftgod.S.momentumDriveSAThresholdMph = 0.0
        driftgod.S.momentumDriveSAStrength = 0.88
        driftgod.S.momentumDriveSABaseMph = 42.0
        driftgod.S.momentumDriveSAMaxAssistMph = 175.0
        driftgod.S.momentumDriveSAHoldRatio = 0.996
        driftgod.S.momentumDriveSADirectionMode = "camera"
        driftgod.S.momentumDriveSACameraSteer = 1.05
        driftgod.S.momentumDriveSABrakeDrag = 0.62
        driftgod.S.momentumDriveSAGroundOnly = true
        driftgod.S.momentumDriveSALowGrip = true
        driftgod.S.momentumDriveSAFriction = 0.22
        driftgod.S.momentumDriveSADownforce = 0.18
        reset_runtime("reset")
        toast("Power Glider settings reset.", 1800)
        save_settings_quiet()
    end

    function driftgod.MomentumDriveSAStatus()
        ensure_defaults()
        local state_label = runtime.active and "ACTIVE" or "READY"
        if driftgod.S.momentumDriveSAEnabled ~= true then state_label = "OFF" end
        return "Power Glider: " .. state_label
            .. " | Mode: " .. direction_label()
            .. " | Speed: " .. format_mph(runtime.lastMph or 0.0)
            .. " | Target: " .. format_mph(runtime.lastTargetMph or 0.0)
            .. " | Base: " .. format_mph(driftgod.S.momentumDriveSABaseMph)
            .. " | Cap: " .. format_mph(driftgod.S.momentumDriveSAMaxAssistMph)
            .. " | Grip: " .. tostring(runtime.lastGrip or "off")
    end

    local function update_mode_hotkey()
        ensure_defaults()
        local key = tonumber(driftgod.S.momentumDriveSAModeToggleKey or 0xA0) or 0xA0
        local down = false
        if not gui_open() then down = key_down(key) end
        if down and runtime.modeKeyDown ~= true then driftgod.ToggleMomentumDriveSADirectionMode() end
        runtime.modeKeyDown = down
    end

    local function tick_grounded_superdrive_sa()
        ensure_defaults()
        disable_old_modes()
        update_mode_hotkey()

        if driftgod.S.momentumDriveSAEnabled ~= true then
            if runtime.active == true or (runtime.lowGripVehicle and runtime.lowGripVehicle ~= 0) then reset_runtime("disabled") end
            return false
        end

        local veh = get_local_vehicle()
        if veh == 0 then
            if runtime.active == true then reset_runtime("no supported driver vehicle") end
            runtime.lastStatus = "Enter a supported driver's seat."
            return true
        end

        invoke_void(nh.SET_VEHICLE_GRAVITY, veh, true)
        apply_ground_grip(veh)

        local vx, vy, vz = invoke_v3(nh.GET_ENTITY_VELOCITY, 0.0, 0.0, 0.0, veh)
        local hspeed = magnitude2(vx, vy)
        local mph = hspeed * mph_per_mps
        runtime.lastMph = mph

        local max_mph = clamp(driftgod.S.momentumDriveSAMaxAssistMph, 30.0, 260.0)
        local base_mph = clamp(driftgod.S.momentumDriveSABaseMph, 0.0, math.min(120.0, max_mph))
        local strength = clamp(driftgod.S.momentumDriveSAStrength, 0.05, 1.50)
        local max_mps = max_mph * mps_per_mph
        local base_mps = base_mph * mps_per_mph
        local dt = clamp(invoke_float(nh.GET_FRAME_TIME), 1.0 / 240.0, 0.05)
        local throttle = math.max(control_normal(control.ACCELERATE), control_normal(control.VEH_FLY_THROTTLE_UP))
        local brake = math.max(control_normal(control.BRAKE), control_normal(control.VEH_FLY_THROTTLE_DN))
        if invoke_bool(nh.IS_CONTROL_PRESSED, 0, control.HANDBRAKE) then brake = math.max(brake, 0.72) end

        local airborne = invoke_bool(nh.IS_ENTITY_IN_AIR, veh)
        local on_wheels = invoke_bool(nh.IS_VEHICLE_ON_ALL_WHEELS, veh)
        local height = invoke_float(nh.GET_ENTITY_HEIGHT_ABOVE_GROUND, veh)
        if driftgod.S.momentumDriveSAGroundOnly ~= false and airborne and height > 1.20 then
            runtime.lastStatus = "Airborne pause | no lift"
            runtime.lastForce = 0.0
            runtime.lastBlend = 0.0
            runtime.lastTargetMph = (runtime.commandSpeed or 0.0) * mph_per_mps
            return true
        end

        local now = now_ms()
        if runtime.lastVehicle ~= veh then
            if runtime.lastVehicle and runtime.lastVehicle ~= 0 then clear_ground_grip(runtime.lastVehicle) end
            runtime.lastVehicle = veh
            runtime.commandSpeed = clamp(math.max(hspeed, base_mps), 0.0, max_mps)
            runtime.active = false
            apply_ground_grip(veh)
        end

        if runtime.active ~= true then
            runtime.active = true
            runtime.activeSince = now
            runtime.commandSpeed = clamp(math.max(runtime.commandSpeed or 0.0, hspeed, base_mps), 0.0, max_mps)
            log("active | groundSuperDrive=true speed=" .. format_mph(mph) .. " target=" .. format_mph(runtime.commandSpeed * mph_per_mps) .. " mode=" .. direction_label() .. " grip=" .. tostring(runtime.lastGrip))
        end

        local command = clamp(tonumber(runtime.commandSpeed or base_mps) or base_mps, 0.0, max_mps)
        local brake_drag = clamp(tonumber(driftgod.S.momentumDriveSABrakeDrag or 0.62) or 0.62, 0.10, 1.35)

        if throttle > 0.05 then
            local build_rate = (16.0 + strength * 44.0) * throttle
            command = command + build_rate * dt
            command = math.max(command, hspeed * 0.998, base_mps)
        elseif brake > 0.05 then
            command = command - (16.0 + brake_drag * 58.0) * brake * dt
        else
            if command < base_mps then
                command = lerp(command, base_mps, clamp(dt * (0.80 + strength), 0.0, 0.10))
            else
                local hold_ratio = clamp(tonumber(driftgod.S.momentumDriveSAHoldRatio or 0.996) or 0.996, 0.960, 0.999)
                command = command * (1.0 - ((1.0 - hold_ratio) * dt * 60.0))
                if command < base_mps then command = base_mps end
            end
        end
        command = clamp(command, 0.0, max_mps)
        runtime.commandSpeed = command
        runtime.lastTargetMph = command * mph_per_mps

        local dx, dy, has_direction = get_drive_direction(veh)
        if not has_direction then
            runtime.lastStatus = "No drive direction."
            return true
        end

        local along = vx * dx + vy * dy
        local missing = command - along
        local input_power = throttle > 0.05 and (0.55 + throttle * 0.55) or 0.70
        if brake > 0.05 then input_power = input_power * clamp(1.0 - brake * 0.55, 0.25, 1.0) end

        local force = clamp(math.max(0.0, missing) * (0.115 + strength * 0.185) * input_power, 0.0, 5.25)
        if force > 0.002 then apply_world_force(veh, dx * force, dy * force, 0.0) end

        local mode = tostring(driftgod.S.momentumDriveSADirectionMode or "camera")
        local steer_setting = clamp(tonumber(driftgod.S.momentumDriveSACameraSteer or 1.05) or 1.05, 0.10, 1.75)
        local blend = clamp((0.040 + strength * 0.105) * steer_setting * input_power, 0.006, 0.285)
        if mode == "vehicle" then blend = blend * 0.74 end
        if brake > 0.05 then blend = blend * clamp(1.0 - brake * 0.72, 0.12, 1.0) end

        local target_x = dx * command
        local target_y = dy * command
        local new_x = lerp(vx, target_x, blend)
        local new_y = lerp(vy, target_y, blend)

        if brake > 0.05 then
            local drag = clamp(brake * (0.020 + brake_drag * 0.065), 0.0, 0.135)
            new_x = new_x * (1.0 - drag)
            new_y = new_y * (1.0 - drag)
        end

        local new_speed = magnitude2(new_x, new_y)
        if new_speed > max_mps then
            local sx, sy = normalize2(new_x, new_y, dx, dy)
            new_x, new_y = sx * max_mps, sy * max_mps
        end

        local downforce = clamp(tonumber(driftgod.S.momentumDriveSADownforce or 0.18) or 0.18, 0.0, 0.80)
        if downforce > 0.001 and (on_wheels or height < 0.85) then
            apply_world_force(veh, 0.0, 0.0, -downforce * (0.45 + clamp(mph / 120.0, 0.0, 1.35)))
        end

        set_velocity(veh, new_x, new_y, vz)

        runtime.lastForce = force
        runtime.lastBlend = blend
        runtime.lastMode = mode
        runtime.lastStatus = "Ground SuperDrive | " .. direction_label() .. " | " .. tostring(runtime.lastGrip or "low grip")

        if driftgod.S.momentumDriveSATelemetry == true and now - (runtime.lastLog or 0) > 650 then
            runtime.lastLog = now
            log("tick127 | mph=" .. string.format("%.1f", mph)
                .. " target=" .. string.format("%.1f", runtime.lastTargetMph or 0.0)
                .. " base=" .. string.format("%.1f", base_mph)
                .. " mode=" .. tostring(mode)
                .. " grip=" .. tostring(runtime.lastGrip)
                .. " force=" .. string.format("%.3f", force)
                .. " blend=" .. string.format("%.4f", blend)
                .. " throttle=" .. string.format("%.2f", throttle)
                .. " brake=" .. string.format("%.2f", brake)
                .. " dir=" .. string.format("%.2f", dx) .. "," .. string.format("%.2f", dy)
                .. " height=" .. string.format("%.2f", height))
        end

        return true
    end

    driftgod.MomentumDriveSATick = tick_grounded_superdrive_sa

    local function ui_text_line(text)
        if ImGui and ImGui.TextWrapped then ImGui.TextWrapped(tostring(text or ""))
        elseif ImGui and ImGui.Text then ImGui.Text(tostring(text or "")) end
    end

    local function ui_text_color(text, r, g, b, a)
        if ImGui and ImGui.TextColored then ImGui.TextColored(r or 1.0, g or 1.0, b or 1.0, a or 1.0, tostring(text or ""))
        else ui_text_line(text) end
    end

    local function ui_sep()
        if ImGui and ImGui.Separator then ImGui.Separator() end
    end

    local function ui_same()
        if ImGui and ImGui.SameLine then ImGui.SameLine() end
    end

    local function ui_button(label, w)
        if ImGui and ImGui.Button then return ImGui.Button(tostring(label or "Button"), w or -1, 0) == true end
        return false
    end

    local function render_pair(label, value)
        ui_text_color(tostring(label or ""), 0.72, 0.78, 0.88, 1.0)
        ui_same()
        ui_text_color(tostring(value or ""), 0.96, 0.97, 1.00, 1.0)
    end

    function driftgod.R127_RenderMomentumDriveSA()
        ensure_defaults()
        if not (ClickGUI and ClickGUI.BeginCustomChildWindow) then return end

        if ClickGUI.BeginCustomChildWindow("Power Glider (BETA)") then
            ui_text_color("Power Glider (BETA)", 0.72, 0.42, 1.00, 1.00)
            ui_text_line("Grounded SuperDrive replacement: low-grip camera-slide momentum with Flying Cars SA-style speed control.")
            ui_text_color("Active immediately when enabled. No lift. Gravity stays on. Left Shift toggles camera / vehicle nose.", 0.70, 0.92, 0.76, 1.00)
            ui_sep()

            render_pair("Status:", driftgod.MomentumDriveSAStatus and driftgod.MomentumDriveSAStatus() or "Power Glider")
            render_pair("Runtime:", tostring(runtime.lastStatus or "Ready"))

            if ui_button((driftgod.S.momentumDriveSAEnabled == true and "Disable" or "Enable") .. " Power Glider", -1) then
                if driftgod.ToggleMomentumDriveSA then driftgod.ToggleMomentumDriveSA() end
            end

            ui_sep()
            ui_text_color("Direction", 0.35, 0.86, 1.00, 1.00)
            render_pair("Mode:", direction_label() .. "  |  Left Shift toggles")
            if ui_button("Mode: Gameplay Camera", 170) then driftgod.SetMomentumDriveSADirectionMode("camera") end
            ui_same()
            if ui_button("Mode: Vehicle Nose", 170) then driftgod.SetMomentumDriveSADirectionMode("vehicle") end

            ui_text_color("SuperDrive Grip", 1.00, 0.78, 0.18, 1.00)
            render_pair("Low Grip:", driftgod.S.momentumDriveSALowGrip == true and "ON" or "OFF")
            render_pair("Friction:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSAFriction or 0.22) or 0.22))
            if ui_button((driftgod.S.momentumDriveSALowGrip == true and "Low Grip: ON" or "Low Grip: OFF"), 170) then driftgod.ToggleMomentumDriveSALowGrip() end
            ui_same()
            if ui_button("Friction -", 170) then driftgod.MomentumDriveSAFrictionDelta(-0.03) end
            ui_same()
            if ui_button("Friction +", 170) then driftgod.MomentumDriveSAFrictionDelta(0.03) end

            ui_text_color("Speed Control", 1.00, 0.78, 0.18, 1.00)
            render_pair("Current:", format_mph(runtime.lastMph or 0.0))
            render_pair("Target:", format_mph(runtime.lastTargetMph or 0.0))
            render_pair("Base:", format_mph(driftgod.S.momentumDriveSABaseMph))
            if ui_button("Base -5 mph", 170) then driftgod.MomentumDriveSABaseDelta(-5.0) end
            ui_same()
            if ui_button("Base +5 mph", 170) then driftgod.MomentumDriveSABaseDelta(5.0) end

            render_pair("Assist Cap:", format_mph(driftgod.S.momentumDriveSAMaxAssistMph))
            if ui_button("Cap -10 mph", 170) then driftgod.MomentumDriveSAMaxAssistDelta(-10.0) end
            ui_same()
            if ui_button("Cap +10 mph", 170) then driftgod.MomentumDriveSAMaxAssistDelta(10.0) end

            render_pair("Strength:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSAStrength or 0.88) or 0.88))
            if ui_button("Strength -", 170) then driftgod.MomentumDriveSAStrengthDelta(-0.05) end
            ui_same()
            if ui_button("Strength +", 170) then driftgod.MomentumDriveSAStrengthDelta(0.05) end

            render_pair("Camera Pull:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSACameraSteer or 1.05) or 1.05))
            if ui_button("Camera Pull -", 170) then driftgod.MomentumDriveSASteerDelta(-0.05) end
            ui_same()
            if ui_button("Camera Pull +", 170) then driftgod.MomentumDriveSASteerDelta(0.05) end

            render_pair("Brake Drag:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSABrakeDrag or 0.62) or 0.62))
            if ui_button("Brake Drag -", 170) then driftgod.MomentumDriveSABrakeDelta(-0.05) end
            ui_same()
            if ui_button("Brake Drag +", 170) then driftgod.MomentumDriveSABrakeDelta(0.05) end

            render_pair("Ground Stick:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSADownforce or 0.18) or 0.18))
            if ui_button("Ground Stick -", 170) then driftgod.MomentumDriveSADownforceDelta(-0.05) end
            ui_same()
            if ui_button("Ground Stick +", 170) then driftgod.MomentumDriveSADownforceDelta(0.05) end

            ui_sep()
            if ui_button((driftgod.S.momentumDriveSAHud == true and "HUD: ON" or "HUD: OFF"), 170) then
                driftgod.S.momentumDriveSAHud = not (driftgod.S.momentumDriveSAHud == true)
                save_settings_quiet()
            end
            ui_same()
            if ui_button((driftgod.S.momentumDriveSATelemetry == true and "Telemetry: ON" or "Telemetry: OFF"), 170) then
                driftgod.S.momentumDriveSATelemetry = not (driftgod.S.momentumDriveSATelemetry == true)
                save_settings_quiet()
            end

            if ui_button("Reset Momentum Drive Settings", -1) then driftgod.ResetMomentumDriveSA() end

            ui_sep()
            ui_text_color("Control feel", 0.54, 0.60, 0.70, 1.00)
