            ui_text_line("Accelerate raises the target speed toward the cap. Brake drops target speed and adds drag. No input carries the base/held speed.")
            ClickGUI.EndCustomChildWindow()
        end
    end

    driftgod.R127_RenderMomentumDriveSA = driftgod.R127_RenderMomentumDriveSA
    driftgod.R126_RenderMomentumDriveSA = driftgod.R127_RenderMomentumDriveSA
    driftgod.R125_RenderMomentumDriveSA = driftgod.R127_RenderMomentumDriveSA
    driftgod.R124_RenderMomentumDriveSA = driftgod.R127_RenderMomentumDriveSA
    driftgod.R123_RenderFlyingCarsSA = driftgod.R127_RenderMomentumDriveSA

