        if driftgod.R279_RenderRoadSurfaceBeta then driftgod.R279_RenderRoadSurfaceBeta() end
        if driftgod.R140_RenderPTFXBeta then driftgod.R140_RenderPTFXBeta() end
    end
    renderBeta = driftgod.R102_RenderBeta

    disable_old_modes()
    log("v1.0.27 loaded | Grounded SuperDrive SA camera-slide controller active")
end)


