        if invoke_int(NH.GET_PED_IN_VEHICLE_SEAT, veh, -1, false) ~= ped then return 0 end
        local class = invoke_int(NH.GET_VEHICLE_CLASS, veh)
        if class == 8 or class == 13 or class == 14 or class == 15 or class == 16 or class == 21 then return 0 end
        return veh
    end

    local function control_normal(id)
        return clamp(invoke_float(NH.GET_CONTROL_NORMAL, 0, id), 0.0, 1.0)
    end

    local function rotation_to_horizontal(rx, rz)
        local pitch = math.rad(tonumber(rx) or 0.0)
        local yaw = math.rad(tonumber(rz) or 0.0)
        local horizontal = math.abs(math.cos(pitch))
        local x = -math.sin(yaw) * horizontal
        local y = math.cos(yaw) * horizontal
        return normalize2(x, y, 0.0, 1.0)
    end

    local function camera_direction()
        local rx, _, rz = invoke_v3(NH.GET_GAMEPLAY_CAM_ROT, 0.0, 0.0, 0.0, 2)
        if math.abs(rx or 0.0) < 0.001 and math.abs(rz or 0.0) < 0.001 then
            rx, _, rz = invoke_v3(NH.GET_FINAL_RENDERED_CAM_ROT, 0.0, 0.0, 0.0, 2)
