        if driftgod.S.momentumDriveSAStrength == nil then driftgod.S.momentumDriveSAStrength = 0.18 end
        if driftgod.S.momentumDriveSAFriction == nil then driftgod.S.momentumDriveSAFriction = 0.21 end
