                if math.abs((tonumber(driftgod.S.momentumDriveSAMaxAssistMph) or 180.0) - 180.0) < 0.01 then driftgod.S.momentumDriveSAMaxAssistMph = 175.0 end
                if math.abs((tonumber(driftgod.S.momentumDriveSAStrength) or 0.90) - 0.90) < 0.005 then driftgod.S.momentumDriveSAStrength = 0.18 end
                if math.abs((tonumber(driftgod.S.momentumDriveSAFriction) or 0.12) - 0.12) < 0.005 then driftgod.S.momentumDriveSAFriction = 0.21 end
                if math.abs((tonumber(driftgod.S.momentumDriveSASlideTurnRate) or 6.25) - 6.25) < 0.005 then driftgod.S.momentumDriveSASlideTurnRate = 3.25 end
                if math.abs((tonumber(driftgod.S.momentumDriveSASpeedResponse) or 5.25) - 5.25) < 0.005 then driftgod.S.momentumDriveSASpeedResponse = 0.75 end
