        toast("Camera slide response: " .. string.format("%.2f", driftgod.S.momentumDriveSASlideTurnRate), 1400)
        save_settings_quiet()
    end

    function driftgod.MomentumDriveSASpeedResponseDelta(delta)
        ensure_defaults()
        driftgod.S.momentumDriveSASpeedResponse = clamp((tonumber(driftgod.S.momentumDriveSASpeedResponse) or 0.75) + (tonumber(delta) or 0.0), 0.75, 12.0)
        toast("Speed response: " .. string.format("%.2f", driftgod.S.momentumDriveSASpeedResponse), 1400)
        save_settings_quiet()
    end

    function driftgod.ToggleMomentumDriveSA()
        ensure_defaults()
        driftgod.S.momentumDriveSAEnabled = not (driftgod.S.momentumDriveSAEnabled == true)
        disable_replaced_modes()
        if driftgod.S.momentumDriveSAEnabled then
            local veh = get_local_vehicle()
            local current = 0.0
            if veh ~= 0 then
                local vx, vy = invoke_v3(NH.GET_ENTITY_VELOCITY, 0.0, 0.0, 0.0, veh)
                current = magnitude2(vx, vy)
                apply_grip(veh)
            end
            local base = clamp(driftgod.S.momentumDriveSABaseMph, 0.0, 120.0) * MPS_PER_MPH
            runtime.commandSpeed = math.max(current, base)
            toast("Power Glider ON | Gameplay Camera", 2200)
        else
            if runtime.lowGripVehicle ~= 0 then clear_grip(runtime.lowGripVehicle) end
            runtime.active = false
            runtime.commandSpeed = 0.0
            runtime.lastStatus = "Disabled"
            toast("Power Glider OFF", 1700)
        end
