        driftgod.S.momentumDriveSAMaxAssistMph = 175.0
        driftgod.S.momentumDriveSAStrength = 0.18
        driftgod.S.momentumDriveSAFriction = 0.21
        driftgod.S.momentumDriveSABrakeDrag = 0.72
        driftgod.S.momentumDriveSADownforce = 0.14
        driftgod.S.momentumDriveSASlideTurnRate = 3.25
        driftgod.S.momentumDriveSASpeedResponse = 0.75
        driftgod.S.momentumDriveSADirectionMode = "camera"
        driftgod.S.momentumDriveSALowGrip = true
        driftgod.S.momentumDriveSAGroundOnly = true
        driftgod.S.momentumDriveSAProfileVersion = "v1.0.29"
