        return "Power Glider: " .. state
            .. " | " .. direction_label()
            .. " | " .. format_mph(runtime.lastMph or 0.0)
            .. " -> " .. format_mph(runtime.lastTargetMph or 0.0)
            .. " | Grip " .. tostring(runtime.lastGrip or "off")
    end

    local function super_slide_tick()
        ensure_defaults()
        disable_replaced_modes()

        if driftgod.S.momentumDriveSAEnabled ~= true then
            if runtime.lowGripVehicle ~= 0 then clear_grip(runtime.lowGripVehicle) end
            runtime.active = false
            runtime.lastStatus = "Disabled"
            return false
        end

        local veh = get_local_vehicle()
        if veh == 0 then
            if runtime.lowGripVehicle ~= 0 then clear_grip(runtime.lowGripVehicle) end
            runtime.active = false
            runtime.lastVehicle = 0
            runtime.lastStatus = "Enter a supported driver's seat."
            return true
        end

        invoke_void(NH.SET_VEHICLE_GRAVITY, veh, true)
        apply_grip(veh)

        local vx, vy, vz = invoke_v3(NH.GET_ENTITY_VELOCITY, 0.0, 0.0, 0.0, veh)
        local speed = magnitude2(vx, vy)
        runtime.lastMph = speed * MPH_PER_MPS

        local airborne = invoke_bool(NH.IS_ENTITY_IN_AIR, veh)
        local on_wheels = invoke_bool(NH.IS_VEHICLE_ON_ALL_WHEELS, veh)
        local height = invoke_float(NH.GET_ENTITY_HEIGHT_ABOVE_GROUND, veh)
        if airborne and height > 1.20 then
            runtime.active = true
            runtime.lastStatus = "Airborne pause | horizontal slide resumes on ground"
            runtime.lastTargetMph = (runtime.commandSpeed or speed) * MPH_PER_MPS
            return true
        end

        if runtime.lastVehicle ~= veh then
            if runtime.lastVehicle ~= 0 and runtime.lastVehicle ~= veh then clear_grip(runtime.lastVehicle) end
            runtime.lastVehicle = veh
            local base = clamp(driftgod.S.momentumDriveSABaseMph, 0.0, 120.0) * MPS_PER_MPH
            runtime.commandSpeed = math.max(speed, base)
        end

        runtime.active = true

        local dt = clamp(invoke_float(NH.GET_FRAME_TIME), 1.0 / 240.0, 0.05)
        local throttle = math.max(control_normal(CONTROL.ACCELERATE), control_normal(CONTROL.FLY_THROTTLE_UP))
        local brake = math.max(control_normal(CONTROL.BRAKE), control_normal(CONTROL.FLY_THROTTLE_DN))
        if invoke_bool(NH.IS_CONTROL_PRESSED, 0, CONTROL.HANDBRAKE) then brake = math.max(brake, 0.80) end

        local cap_mph = clamp(driftgod.S.momentumDriveSAMaxAssistMph, 30.0, 260.0)
        local base_mph = clamp(driftgod.S.momentumDriveSABaseMph, 0.0, math.min(120.0, cap_mph))
        local cap = cap_mph * MPS_PER_MPH
        local base = base_mph * MPS_PER_MPH
        local strength = clamp(driftgod.S.momentumDriveSAStrength, 0.10, 1.50)
        local brake_drag = clamp(driftgod.S.momentumDriveSABrakeDrag, 0.10, 1.50)
        local command = clamp(tonumber(runtime.commandSpeed or math.max(speed, base)) or base, 0.0, cap)

        -- Flying Cars SA-style speed control, but on the ground: throttle builds the
        -- carried speed, brake bleeds it, and coasting preserves most momentum.
        if throttle > 0.04 then
            command = command + (22.0 + strength * 48.0) * MPS_PER_MPH * throttle * dt
            if command < base then command = base end
        elseif brake > 0.04 then
            command = command - (28.0 + brake_drag * 64.0) * MPS_PER_MPH * brake * dt
            if command < 0.0 then command = 0.0 end
        else
            local coast_loss_mph = 0.90
            command = math.max(base, command - coast_loss_mph * MPS_PER_MPH * dt)
        end
        command = clamp(command, 0.0, cap)
        runtime.commandSpeed = command
        runtime.lastTargetMph = command * MPH_PER_MPS

        local dx, dy, okdir = drive_direction(veh)
        if not okdir then
            runtime.lastStatus = "No camera direction."
            return true
        end

        -- THIS is the Power Glider behavior: steer the velocity vector, not the chassis.
        -- The vehicle body remains free to yaw / drift / face sideways under low grip.
        local curx, cury, cur_ok = normalize2(vx, vy, dx, dy)
        if not cur_ok and speed < 0.50 then curx, cury = dx, dy end

        local turn_rate = clamp(driftgod.S.momentumDriveSASlideTurnRate, 0.75, 14.0)
        if tostring(driftgod.S.momentumDriveSADirectionMode or "camera") == "vehicle" then
            turn_rate = turn_rate * 0.72
        end
        if brake > 0.04 then turn_rate = turn_rate * clamp(1.0 - brake * 0.55, 0.35, 1.0) end
        local turn_blend = approach_blend(turn_rate, dt)

        local mix_x = lerp(curx, dx, turn_blend)
        local mix_y = lerp(cury, dy, turn_blend)
        local travel_x, travel_y = normalize2(mix_x, mix_y, dx, dy)

        local speed_response = clamp(driftgod.S.momentumDriveSASpeedResponse, 0.75, 12.0)
        local speed_blend = approach_blend(speed_response * (0.55 + strength * 0.65), dt)
        if brake > 0.04 then speed_blend = clamp(speed_blend + brake * 0.10, 0.0, 0.42) end
        local new_speed = lerp(speed, command, speed_blend)

        if brake > 0.04 then
            local extra_drag = clamp(brake * (0.006 + brake_drag * 0.024), 0.0, 0.055)
            new_speed = new_speed * (1.0 - extra_drag)
        end
        new_speed = clamp(new_speed, 0.0, cap)

        local new_x = travel_x * new_speed
        local new_y = travel_y * new_speed

        local downforce = clamp(driftgod.S.momentumDriveSADownforce, 0.0, 0.80)
        if downforce > 0.001 and (on_wheels or height < 0.85) then
            invoke_void(NH.APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS, veh, 1, 0.0, 0.0,
                -downforce * (0.35 + clamp(runtime.lastMph / 120.0, 0.0, 1.50)), true, false, true, true)
        end

        invoke_void(NH.SET_ENTITY_VELOCITY, veh, new_x, new_y, vz)

        runtime.lastBlend = turn_blend
        runtime.lastSpeedBlend = speed_blend
        runtime.lastStatus = "SUPER SLIDING | camera aims travel | chassis free"

        local now = 0
        if os and os.clock then now = math.floor(os.clock() * 1000) end
        if driftgod.S.momentumDriveSATelemetry == true and now - (runtime.lastLog or 0) > 650 then
            runtime.lastLog = now
            log("tick128 | mph=" .. string.format("%.1f", runtime.lastMph)
                .. " target=" .. string.format("%.1f", runtime.lastTargetMph)
                .. " mode=" .. tostring(driftgod.S.momentumDriveSADirectionMode)
                .. " cameraDir=" .. string.format("%.2f,%.2f", dx, dy)
                .. " travelDir=" .. string.format("%.2f,%.2f", travel_x, travel_y)
                .. " turnBlend=" .. string.format("%.4f", turn_blend)
                .. " speedBlend=" .. string.format("%.4f", speed_blend)
                .. " throttle=" .. string.format("%.2f", throttle)
                .. " brake=" .. string.format("%.2f", brake)
                .. " friction=" .. string.format("%.2f", tonumber(driftgod.S.momentumDriveSAFriction or 0.21) or 0.21))
        end

        return true
    end

    driftgod.MomentumDriveSATick = super_slide_tick

