-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.3 production patch: Power Glider presets + Shift drift counter-steer
-- note: keeps the proven v1.0.29 Power Glider movement core intact. This pass
--       changes the approved default brake response to 1.20, adds five A/B-style
--       built-in Power Glider presets plus Custom, and reserves LEFT SHIFT as a hold-to-
--       drift input. Presets may intentionally use no counter-steer or progressively
--       stronger counter-steer. Counter-steer affects the steering bias only; camera
--       guidance continues to steer the horizontal velocity vector, not the chassis.
-- ═══════════════════════════════════════════════════════════════════════════════════

driftgod.Try(function()
    DG = DG or {}
    driftgod.S = driftgod.S or {}

    driftgod.Version = "v1.0.3"
    driftgod.BuildNumber = "2026.07.28.003"
    driftgod.BuildDate = "2026-07-27"
    driftgod.LastUpdated = "2026-07-28"
    driftgod.LastUpdateDate = "2026-07-28"
    driftgod.__ProductionPatch = "v1_0_3_Product_Build"

    local previous_tick = driftgod.MomentumDriveSATick
    local previous_render = driftgod.R128_RenderMomentumDriveSA

    local NH130 = {
        PLAYER_PED_ID = 0xD80958FC74E988A6,
        IS_PED_IN_ANY_VEHICLE = 0x997ABD671D25CA0B,
        GET_VEHICLE_PED_IS_IN = 0x9A9112A0FE9A4713,
        GET_PED_IN_VEHICLE_SEAT = 0xBB40DD2270B65366,
        DOES_ENTITY_EXIST = 0x7239B21A38F536BA,
        GET_VEHICLE_CLASS = 0x29439776AAA00A62,
        GET_ENTITY_VELOCITY = 0x4805D2B1D8CF94A9,
        GET_ENTITY_HEADING = 0xE83D4F9BA2A38914,
        SET_VEHICLE_STEER_BIAS = 0x42A8EC77D5150CBE,
    }

    local runtime130 = driftgod.MomentumDriveSA or {}
    driftgod.MomentumDriveSA = runtime130
    runtime130.counterSteerVehicle = tonumber(runtime130.counterSteerVehicle or 0) or 0
    runtime130.lastCounterBiasDeg = tonumber(runtime130.lastCounterBiasDeg or 0.0) or 0.0
    runtime130.lastSlipAngle = tonumber(runtime130.lastSlipAngle or 0.0) or 0.0
    runtime130.shiftHeld = runtime130.shiftHeld == true

    local function clamp(v, lo, hi)
        v = tonumber(v or lo) or lo
        if v < lo then return lo end
        if v > hi then return hi end
        return v
    end

    local function try_bool(hash, ...)
        if not (Natives and Natives.InvokeBool) then return false end
        local ok, value = driftgod.Try(function(...) return Natives.InvokeBool(hash, ...) end, ...)
        return ok == true and value == true
    end

    local function try_int(hash, ...)
        if not (Natives and Natives.InvokeInt) then return 0 end
        local ok, value = driftgod.Try(function(...) return Natives.InvokeInt(hash, ...) end, ...)
        return ok == true and (tonumber(value) or 0) or 0
    end

    local function try_float(hash, ...)
        if not (Natives and Natives.InvokeFloat) then return 0.0 end
        local ok, value = driftgod.Try(function(...) return Natives.InvokeFloat(hash, ...) end, ...)
        return ok == true and (tonumber(value) or 0.0) or 0.0
    end

    local function unpack_v3(a, b, c)
        if type(a) == "table" then
            return tonumber(a.x or a.X or a[1]) or 0.0,
                   tonumber(a.y or a.Y or a[2]) or 0.0,
                   tonumber(a.z or a.Z or a[3]) or 0.0
        end
        if type(a) == "userdata" then
            local okx, x = driftgod.Try(function() return a.x or a.X end)
            local oky, y = driftgod.Try(function() return a.y or a.Y end)
            local okz, z = driftgod.Try(function() return a.z or a.Z end)
            if okx or oky or okz then return tonumber(x) or 0.0, tonumber(y) or 0.0, tonumber(z) or 0.0 end
        end
        return tonumber(a) or 0.0, tonumber(b) or 0.0, tonumber(c) or 0.0
    end

    local function try_v3(hash, ...)
        if not (Natives and Natives.InvokeV3) then return 0.0, 0.0, 0.0 end
        local ok, a, b, c = driftgod.Try(function(...) return Natives.InvokeV3(hash, ...) end, ...)
        if ok then return unpack_v3(a, b, c) end
        return 0.0, 0.0, 0.0
    end

    local function log130(msg)
        msg = "[PowerGlider130] " .. tostring(msg or "")
        if driftgod.Log then driftgod.Log(msg)
        elseif Logger and Logger.LogInfo then Logger.LogInfo("[DriftGod] " .. msg) end
    end

    local function toast130(msg, ms)
        if driftgod.Toast then driftgod.Toast(tostring(msg or ""), ms or 1700)
        elseif GUI and GUI.AddToast then GUI.AddToast("DriftGod", tostring(msg or ""), ms or 1700) end
    end

    local function save130()
        if driftgod.SaveSettings then driftgod.Try(function() driftgod.SaveSettings(false) end) end
    end

    local function get_vehicle()
        local ped = try_int(NH130.PLAYER_PED_ID)
        if ped == 0 or not try_bool(NH130.IS_PED_IN_ANY_VEHICLE, ped, false) then return 0 end
        local veh = try_int(NH130.GET_VEHICLE_PED_IS_IN, ped, false)
        if veh == 0 or not try_bool(NH130.DOES_ENTITY_EXIST, veh) then return 0 end
        if try_int(NH130.GET_PED_IN_VEHICLE_SEAT, veh, -1, false) ~= ped then return 0 end
        local class = try_int(NH130.GET_VEHICLE_CLASS, veh)
        if class == 8 or class == 13 or class == 14 or class == 15 or class == 16 or class == 21 then return 0 end
        return veh
    end

    local function gui_open()
        if GUI and GUI.IsOpen then
            local ok, value = driftgod.Try(function() return GUI.IsOpen() end)
            if ok then return value == true end
        end
        return false
    end

    local function shift_held()
        if gui_open() then return false end
        if Utils and Utils.IsKeyDown then
            local ok, value = driftgod.Try(function() return Utils.IsKeyDown(0xA0) end)
            return ok == true and value == true
        end
        return false
    end

    local presets = {
        ["Pure Camera"] = {
            description = "Approved v1.0.29 feel with the stronger 1.20 brake response. Raw camera-guided slide; no counter-steer.",
            base = 22.0, cap = 175.0, strength = 0.18, friction = 0.21,
            slide = 3.25, speed = 0.75, brake = 1.20, ground = 0.14,
            counter = 0.00,
        },
        ["Balanced Counter"] = {
            description = "The approved profile with moderate Shift counter-steer for easier drift recovery while keeping the same slide feel.",
            base = 22.0, cap = 175.0, strength = 0.18, friction = 0.21,
            slide = 3.25, speed = 0.75, brake = 1.20, ground = 0.14,
            counter = 0.55,
        },
        ["Loose Counter"] = {
            description = "Looser tires and a quicker camera arc. Shift adds stronger counter-steer so the chassis can hang sideways without feeling abandoned.",
            base = 22.0, cap = 180.0, strength = 0.18, friction = 0.17,
            slide = 3.75, speed = 0.85, brake = 1.20, ground = 0.12,
            counter = 0.78,
        },
        ["Long Sweep"] = {
            description = "Long, floaty camera sweeps with extra carried speed. No counter-steer: this is the raw high-momentum comparison preset.",
            base = 28.0, cap = 195.0, strength = 0.16, friction = 0.19,
            slide = 2.40, speed = 0.75, brake = 1.05, ground = 0.10,
            counter = 0.00,
        },
        ["Tight Technical"] = {
            description = "More grip, faster camera response and strong Shift counter-steer for tighter streets and quick direction changes.",
            base = 18.0, cap = 160.0, strength = 0.22, friction = 0.24,
            slide = 4.50, speed = 1.05, brake = 1.35, ground = 0.18,
            counter = 0.95,
        },
    }

    local preset_order = {
        "Pure Camera",
        "Balanced Counter",
        "Loose Counter",
        "Long Sweep",
        "Tight Technical",
        "Custom",
    }

    local function mark_custom()
        driftgod.S.momentumDriveSAPreset = "Custom"
        driftgod.S.momentumDriveSAPresetVersion = "v1.0.30"
    end

    local function ensure130()
        driftgod.S = driftgod.S or {}
        if driftgod.S.momentumDriveSABrakeDrag == nil then driftgod.S.momentumDriveSABrakeDrag = 1.20 end
        if driftgod.S.momentumDriveSACounterSteerStrength == nil then driftgod.S.momentumDriveSACounterSteerStrength = 0.0 end

        if driftgod.S.momentumDriveSAPreset == nil then
            -- Treat the exact approved v1.0.29 profile as Pure Camera; preserve any
            -- existing hand-tuned profile as Custom rather than relabeling it.
            local approved =
                math.abs((tonumber(driftgod.S.momentumDriveSABaseMph) or 22.0) - 22.0) < 0.01 and
                math.abs((tonumber(driftgod.S.momentumDriveSAMaxAssistMph) or 175.0) - 175.0) < 0.01 and
                math.abs((tonumber(driftgod.S.momentumDriveSAStrength) or 0.18) - 0.18) < 0.005 and
                math.abs((tonumber(driftgod.S.momentumDriveSAFriction) or 0.21) - 0.21) < 0.005 and
                math.abs((tonumber(driftgod.S.momentumDriveSASlideTurnRate) or 3.25) - 3.25) < 0.005 and
                math.abs((tonumber(driftgod.S.momentumDriveSASpeedResponse) or 0.75) - 0.75) < 0.005 and
                math.abs((tonumber(driftgod.S.momentumDriveSADownforce) or 0.14) - 0.14) < 0.005 and
                (math.abs((tonumber(driftgod.S.momentumDriveSABrakeDrag) or 0.72) - 0.72) < 0.005 or
                 math.abs((tonumber(driftgod.S.momentumDriveSABrakeDrag) or 1.20) - 1.20) < 0.005)
            driftgod.S.momentumDriveSAPreset = approved and "Pure Camera" or "Custom"
        end

        if driftgod.S.momentumDriveSAPresetVersion ~= "v1.0.30" then
            -- Only migrate the exact old approved brake value. Any hand-tuned brake value is preserved.
            if math.abs((tonumber(driftgod.S.momentumDriveSABrakeDrag) or 0.72) - 0.72) < 0.005 then
                driftgod.S.momentumDriveSABrakeDrag = 1.20
            end
            if driftgod.S.momentumDriveSAPreset ~= "Custom" and not presets[driftgod.S.momentumDriveSAPreset] then
                driftgod.S.momentumDriveSAPreset = "Pure Camera"
            end
            driftgod.S.momentumDriveSAPresetVersion = "v1.0.30"
        end
        driftgod.S.momentumDriveSACounterSteerStrength = clamp(driftgod.S.momentumDriveSACounterSteerStrength, 0.0, 1.25)
    end

    local function apply_preset_values(name, announce)
        ensure130()
        local p = presets[name]
        if not p then
            if name == "Custom" then
                driftgod.S.momentumDriveSAPreset = "Custom"
                save130()
                return true
            end
            return false
        end
        driftgod.S.momentumDriveSABaseMph = p.base
        driftgod.S.momentumDriveSAMaxAssistMph = p.cap
        driftgod.S.momentumDriveSAStrength = p.strength
        driftgod.S.momentumDriveSAFriction = p.friction
        driftgod.S.momentumDriveSASlideTurnRate = p.slide
        driftgod.S.momentumDriveSASpeedResponse = p.speed
        driftgod.S.momentumDriveSABrakeDrag = p.brake
        driftgod.S.momentumDriveSADownforce = p.ground
        driftgod.S.momentumDriveSACounterSteerStrength = p.counter
        driftgod.S.momentumDriveSADirectionMode = "camera"
        driftgod.S.momentumDriveSALowGrip = true
        driftgod.S.momentumDriveSAGroundOnly = true
        driftgod.S.momentumDriveSAPreset = name
        driftgod.S.momentumDriveSAPresetVersion = "v1.0.30"
        if runtime130.commandSpeed and runtime130.commandSpeed > (p.cap * 0.44704) then
            runtime130.commandSpeed = p.cap * 0.44704
        end
        if announce then
            toast130("Power Glider preset: " .. name, 1900)
        end
        save130()
        return true
    end

    function driftgod.ApplyMomentumDriveSAPreset(name)
        return apply_preset_values(tostring(name or "Pure Camera"), true)
    end

    function driftgod.GetMomentumDriveSAPresetNames()
        return preset_order
    end

    function driftgod.GetMomentumDriveSAPresetDescription(name)
        local p = presets[tostring(name or "")]
        if p then return p.description end
        return "Custom keeps your current Power Glider tuning. Any manual adjustment automatically switches the preset label to Custom."
    end

    -- Override tuning helpers so touching any knob intentionally becomes Custom.
    function driftgod.MomentumDriveSABaseDelta(delta)
        ensure130(); mark_custom()
        local cap = clamp(driftgod.S.momentumDriveSAMaxAssistMph, 30.0, 260.0)
        driftgod.S.momentumDriveSABaseMph = clamp((tonumber(driftgod.S.momentumDriveSABaseMph) or 22.0) + (tonumber(delta) or 0.0), 0.0, math.min(120.0, cap))
        toast130("Base speed: " .. string.format("%.0f mph", driftgod.S.momentumDriveSABaseMph), 1300); save130()
    end

    function driftgod.MomentumDriveSAMaxAssistDelta(delta)
        ensure130(); mark_custom()
        driftgod.S.momentumDriveSAMaxAssistMph = clamp((tonumber(driftgod.S.momentumDriveSAMaxAssistMph) or 175.0) + (tonumber(delta) or 0.0), 30.0, 260.0)
        if (tonumber(driftgod.S.momentumDriveSABaseMph) or 0.0) > driftgod.S.momentumDriveSAMaxAssistMph then
            driftgod.S.momentumDriveSABaseMph = driftgod.S.momentumDriveSAMaxAssistMph
        end
        toast130("Assist cap: " .. string.format("%.0f mph", driftgod.S.momentumDriveSAMaxAssistMph), 1300); save130()
    end

