    function driftgod.ResetMomentumDriveSA()
        apply_preset_values("Pure Camera", false)
        runtime130.commandSpeed = 0.0
        runtime130.active = false
        toast130("Power Glider reset to Pure Camera preset.", 1700)
    end

    local function set_steer_bias(veh, bias)
        bias = tonumber(bias or 0.0) or 0.0
        if VEHICLE and VEHICLE.SET_VEHICLE_STEER_BIAS then
            local ok = driftgod.Try(function() VEHICLE.SET_VEHICLE_STEER_BIAS(veh, bias) end)
            return ok == true
        end
        if Natives and Natives.InvokeVoid then
            local ok = driftgod.Try(function() Natives.InvokeVoid(NH130.SET_VEHICLE_STEER_BIAS, veh, bias) end)
            return ok == true
        end
        return false
    end

    local function clear_countersteer(veh)
        veh = tonumber(veh or runtime130.counterSteerVehicle or 0) or 0
        if veh ~= 0 then set_steer_bias(veh, 0.0) end
        runtime130.counterSteerVehicle = 0
        runtime130.lastCounterBiasDeg = 0.0
        runtime130.lastSlipAngle = 0.0
    end

    local function signed_slip_angle(veh, vx, vy)
        local speed = math.sqrt((tonumber(vx) or 0.0)^2 + (tonumber(vy) or 0.0)^2)
        if speed < 0.35 then return 0.0 end
        local heading = try_float(NH130.GET_ENTITY_HEADING, veh)
        local travel = math.fmod(270.0 + math.deg(math.atan(tonumber(vy) or 0.0, tonumber(vx) or 0.0)), 360.0)
        local delta = (heading - travel) % 360.0
        if delta > 180.0 then delta = delta - 360.0 end
        return clamp(delta, -120.0, 120.0)
    end

    local function apply_shift_countersteer(veh)
        ensure130()
        local held = shift_held()
        runtime130.shiftHeld = held

        if not held or driftgod.S.momentumDriveSAEnabled ~= true then
            if runtime130.counterSteerVehicle ~= 0 then clear_countersteer(runtime130.counterSteerVehicle) end
            return false
        end

        local strength = clamp(driftgod.S.momentumDriveSACounterSteerStrength, 0.0, 1.25)
        if strength <= 0.001 then
            if runtime130.counterSteerVehicle ~= 0 then clear_countersteer(runtime130.counterSteerVehicle) end
            return true
        end

        local vx, vy = try_v3(NH130.GET_ENTITY_VELOCITY, veh)
        local mph = math.sqrt(vx * vx + vy * vy) * 2.2369362920544
        if mph < 8.0 then
            clear_countersteer(veh)
            return true
        end

        local slip = signed_slip_angle(veh, vx, vy)
        local abs_slip = math.abs(slip)
        runtime130.lastSlipAngle = slip
        if abs_slip < 7.0 then
            set_steer_bias(veh, 0.0)
            runtime130.counterSteerVehicle = veh
            runtime130.lastCounterBiasDeg = 0.0
            return true
        end

        -- Similar in spirit to DriftGod's existing auto-counter-steer: the farther
        -- sideways the chassis gets, the more steering bias is introduced, but it is
        -- capped so Shift assists a drift instead of forcibly straightening the car.
        local over = math.max(0.0, abs_slip - 7.0)
        local gain = 0.34 * strength
        local max_deg = 15.0 * strength
        local bias_deg = math.min(over * gain, max_deg)
        local sign = slip >= 0.0 and 1.0 or -1.0
        local bias = math.rad(sign * bias_deg)
        set_steer_bias(veh, bias)
        runtime130.counterSteerVehicle = veh
        runtime130.lastCounterBiasDeg = sign * bias_deg
        return true
    end

    driftgod.MomentumDriveSATick = function()
        ensure130()
        local active = false
        if previous_tick then
            local ok, result = driftgod.Try(function() return previous_tick() end)
            active = ok == true and result == true
        end

        if driftgod.S.momentumDriveSAEnabled ~= true then
            if runtime130.counterSteerVehicle ~= 0 then clear_countersteer(runtime130.counterSteerVehicle) end
            runtime130.shiftHeld = false
            return active
        end

        local veh = get_vehicle()
        if veh == 0 then
            if runtime130.counterSteerVehicle ~= 0 then clear_countersteer(runtime130.counterSteerVehicle) end
            runtime130.shiftHeld = false
            return active
        end

        apply_shift_countersteer(veh)
        local preset = tostring(driftgod.S.momentumDriveSAPreset or "Custom")
        local counter = clamp(driftgod.S.momentumDriveSACounterSteerStrength, 0.0, 1.25)
        if runtime130.shiftHeld then
            if counter > 0.001 then
                runtime130.lastStatus = "SHIFT DRIFT | " .. preset
                    .. " | slip " .. string.format("%.1f°", runtime130.lastSlipAngle or 0.0)
                    .. " | counter " .. string.format("%.1f°", runtime130.lastCounterBiasDeg or 0.0)
            else
                runtime130.lastStatus = "SHIFT DRIFT | " .. preset .. " | raw slide / no counter-steer"
            end
        end
        return active
    end

    local function ui_text(text)
        if ImGui and ImGui.TextWrapped then ImGui.TextWrapped(tostring(text or ""))
        elseif ImGui and ImGui.Text then ImGui.Text(tostring(text or "")) end
    end

    local function ui_color(text, r, g, b, a)
        if ImGui and ImGui.TextColored then ImGui.TextColored(r or 1.0, g or 1.0, b or 1.0, a or 1.0, tostring(text or ""))
        else ui_text(text) end
    end

    local function ui_sep()
        if ImGui and ImGui.Separator then ImGui.Separator() end
    end

    local function ui_same()
        if ImGui and ImGui.SameLine then ImGui.SameLine() end
    end

    local function ui_button(label, width)
        if ImGui and ImGui.Button then return ImGui.Button(tostring(label or "Button"), width or -1, 0) == true end
        return false
    end

    local function pair(label, value)
        ui_color(label, 0.72, 0.78, 0.88, 1.0)
        ui_same()
        ui_color(value, 0.96, 0.97, 1.00, 1.0)
    end

    local function render_preset_combo()
        ensure130()
        local current = tostring(driftgod.S.momentumDriveSAPreset or "Pure Camera")
        if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
            local opened = false
            driftgod.Try(function() opened = ImGui.BeginCombo("Power Glider Preset##DG130", current) end)
            if opened then
                for _, name in ipairs(preset_order) do
                    local selected = name == current
                    local clicked = false
                    driftgod.Try(function() clicked = ImGui.Selectable(name, selected) end)
                    if clicked then
                        if name == "Custom" then
                            mark_custom(); save130()
                        else
                            apply_preset_values(name, true)
                        end
                    end
                end
                ImGui.EndCombo()
            end
        else
            pair("Preset:", current)
            for i = 1, 5 do
                local name = preset_order[i]
                if ui_button(name, -1) then apply_preset_values(name, true) end
            end
        end
    end

    function driftgod.R130_RenderMomentumDriveSA()
        ensure130()
        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Power Glider Presets") then
            ui_color("Power Glider Presets", 1.00, 0.78, 0.18, 1.00)
            ui_text("Five built-in profiles are included. They deliberately vary grip, camera response, speed behavior and Shift counter-steer so you can compare the feel directly.")
            ui_sep()
            render_preset_combo()
            local current = tostring(driftgod.S.momentumDriveSAPreset or "Custom")
            ui_text(driftgod.GetMomentumDriveSAPresetDescription(current))
            ui_sep()
            pair("Brake Response:", string.format("%.2f", tonumber(driftgod.S.momentumDriveSABrakeDrag or 1.20) or 1.20))
            pair("Shift Drift:", runtime130.shiftHeld and "HELD" or "Release")
            local cs = clamp(driftgod.S.momentumDriveSACounterSteerStrength, 0.0, 1.25)
            pair("Counter-Steer:", cs <= 0.001 and "OFF for this preset" or (string.format("%.2f", cs) .. " while Left Shift is held"))
            if ui_button("Counter-Steer -", 170) then driftgod.MomentumDriveSACounterSteerDelta(-0.10) end
            ui_same()
            if ui_button("Counter-Steer +", 170) then driftgod.MomentumDriveSACounterSteerDelta(0.10) end
            ui_text("Left Shift is now HOLD TO DRIFT. It no longer toggles Camera / Vehicle Nose. Presets with counter-steer add steering bias only while Shift is held; zero-counter presets leave the chassis completely raw.")
            ClickGUI.EndCustomChildWindow()
        end

        if previous_render then previous_render() end
    end

    driftgod.R128_RenderMomentumDriveSA = driftgod.R130_RenderMomentumDriveSA
    driftgod.R127_RenderMomentumDriveSA = driftgod.R130_RenderMomentumDriveSA
    driftgod.R126_RenderMomentumDriveSA = driftgod.R130_RenderMomentumDriveSA
    driftgod.R125_RenderMomentumDriveSA = driftgod.R130_RenderMomentumDriveSA
    driftgod.R124_RenderMomentumDriveSA = driftgod.R130_RenderMomentumDriveSA
    driftgod.R123_RenderFlyingCarsSA = driftgod.R130_RenderMomentumDriveSA

    driftgod.R102_RenderBeta = function()
        if driftgod.R130_RenderMomentumDriveSA then driftgod.R130_RenderMomentumDriveSA() end
        if driftgod.R279_RenderRoadSurfaceBeta then driftgod.R279_RenderRoadSurfaceBeta() end
        if driftgod.R140_RenderPTFXBeta then driftgod.R140_RenderPTFXBeta() end
    end
    renderBeta = driftgod.R102_RenderBeta

    ensure130()
    -- Make the user-requested 1.20 brake response the approved default immediately.
    if driftgod.S.momentumDriveSAPresetVersion ~= "v1.0.30" then
        driftgod.S.momentumDriveSAPresetVersion = "v1.0.30"
    end
    save130()
    -- production build: normal startup logging intentionally muted
end)

